Object.assign(window.__TXT,{"12500": "痰血未清，右胁痛止，左胁依然，脉之数象稍平。原方兼和肝胃。", "12501": "（案35）年甫二旬，季春突然失血盈碗，血色鲜红，脉见芤象，火犯阳经，血络受伤，阳旺阴亏，阴不和谐。", "12502": "（案38）《经》以大怒则形气绝而血菀于上，客秋气郁，失血两口。冬月操劳过极，又复失红三次，每吐盈碗，俱属紫血。腊月下旬出疹，胸臆两胁兼痛。现在饮食难下，心中懊𢙐，难以名状。脉象细涩，推之不甚宁静。诵读吟咏，多主伤阴。七情不适，水不养肝，肝不藏血，气失摄纳，载血上行，所嫌先天既亏，脾胃不振，最怕土弱，不能生金，咳嗽失血多紫，不能见血报凉。", "12503": "（案39）脉象滑数而软，左部微弦。恙因肝阴不敛，火燥气冲，血不归经，逆而上犯，初起为火，久则成怯。", "12504": "（案2）素有遗精，入房易泄，火升耳鸣，痰湿闭塞，补药不效。至三十六载，吟诵劳碌，疫病转染，形体消瘦，服人乳蕴热于中，胸次按之汩汩有声，气息咽喉不利，饮食不思，脉象沉弦，且数且滑。沉者，郁也，气也。数者，火也，热也。滑者，痰也，湿也，水也。肾阴亏则精不藏，肝阳强则精不固。香燥难投，腻补不宜，从心肝肾进步，兼调脾胃。多访名哲斟酌。", "12505": "（案4）脉来弦滑无力，肾虚真阳不旺，脾虚健运失常，虚寒积饮，清浊混淆，贲音腹胀，懊𢙐嘈杂，口流清涎，臂肋疼痛，横逆左乳下，胸次寒凝。肾肝不纳，虚寒郁气。", "12506": "（案5）脉来沉弦而滑，肝郁中伤，积饮吐酸，痰如蛋清，已延两月。肺肾俱伤，食不能入，入则痛甚，两胁作胀，肝气犯胃。又值春令，非所宜也。", "12507": "（案8）右脉沉弦，左脉沉滑。肝气内郁，内有痰饮。痛吐清水，手足发冷。肝肾虽虚，从乎中治。", "12508": "（案9）右脉滑疾，左脉细涩，肝肾内亏，酒湿伤中。积饮酿热，食后饱胀。气结嘈杂，呕恶清水，久非所宜。", "12509": "（案10）脉见弦滑，肝脾气胀，胃气积饮，湿热为患，病延已久。脾肾亦虚，防其气逆上冲。", "12510": "（案11）脉弦兼滑，中阳不健，胃寒停饮，嗳气吐酸，食后尤甚，胸闷，膈上停痰，积饮为患。苓桂术甘不应，姜术亦不应。年在冲龄，病延已久。补命肾以建中阳，拟以肾气法调之。", "12511": "（案12）左脉沉弦，右脉沉滑。嗳逆吐酸，胸闷呕食。肾虚胃关不建，脾虚健运失常，积痰积饮，作酸作呕。外饮治脾，内饮治肾。", "12512": "（案13）脉来细涩，肝气逆来，犯胃中伤。胃不下降，不饥不纳，积饮吐酸，厥逆之气，自下而上，中宫之气惫矣。", "12513": "（案14）两脉俱弦，且滑且疾。思虑伤脾，积劳伤中，中伤停饮，呕吐清水，气不开畅，发甚胀痛，不耐操劳，已历十余载。病起于肝，损及于中。吐水多甜，脾湿生热。肾为水之本，膀胱为水之标，土乃水之堤防。崇土渗湿，肝病实脾。", "12514": "六进前方，气渐平顺，呕吐未发，亦未痛胀，脉之弦滑稍平。仍崇土渗湿，佐以和肝。", "12515": "（案15）脉来弦滑，中阳不健，肝胃不和，积寒积饮，吐食吐酸，间有苦水，木郁中伤。曲直作酸，木郁达之。本以苓桂术甘，现舌苔焦黄，胸中有热，先拟左金合二陈加味。", "12516": "（案16）恙因肝邪横逆，木来侮土，土受木克，以致饮食入胃，虽然运化，生津生液者少，为火为痰者多。细思病情，似乎诸饮成痰之状。所服六君、金匮、资生，皆肝肾脾之要药，理宜渐减方佳。服此药之后，反觉有横逆痰饮之象，又兼肢冷脉伏，呕吐痰涎，非高年久病所宜。若论痰饮，服六君理应见功。若论肾虚肝气，服桂附亦未有效。此棘手之症也。暂拟人参代赭石汤加减用之，服四帖后再为酌方可也。所云脉闭肢冷，皆痰饮阻塞胸中。故尔阳气宣通，脉闭肢寒自愈。", "12517": "（案2）气痰呃逆，脉象弦滑而数，按之无力，中虚胃不和，肺气不降，痰郁作呃，丁香、柿蒂、人参，甘温之品皆是。呃由暴起，所谓肺胃不和是也。拟二陈汤合杏仁、枇杷叶。一治肺，一治胃，明日再进三剂可也。", "12518": "（案1）右脉弦大，左象涩小。中宫失运，胃不冲和，气痰阻食。年近七旬，肺胃液枯，八仙长寿是理。现气痛阻逆，腻滞难投，暂宜宣剂。", "12519": "生脉散、二陈汤加枇杷叶、红糖，雪羹汤煎。", "12520": "（案2）气郁动肝，中伤气逆，食入作痛，嗳气不止，脉象沉弦，中州失运，非佳候也，拟补中益气加味。", "12521": "（案4）脉来沉小，心肝肾三阴不足。左脉犯弦，木制中胃，清气不展，浊阴上潜，清浊混淆，天地不泰，变生否象，不可轻视。", "12522": "脉来沉小而涩，肝肾阴亏，左脉仍弦，木制中胃，气失冲和，天地不泰，否象生矣。不独香燥难投，破气更属不利。养肝肾以纳气机，养肺胃以舒气化。是否候酌。", "12523": "（案5）先天薄弱，水不养肝，肝虚犯胃，胃不冲和，气不下逮，反逆于上，所以食不能下，脉象虚弦，不宜香燥，当以乙癸同源为是。", "12524": "（案6）肾虚胃关不健，气逆中宫，食入作阻，水不养肝，肝气中胃，两脉俱弦，舌绛苔燥，痰多汗多，阴阳不化，香燥殊属不宜。拟十味温胆加味。", "12525": "纳食主胃，运化主脾，脾升则降，胃降则和，中宫失运，气痰作阻，胃失冲和，饮食难下。年逾六旬，大便结燥。肺胃干槁，脉见双弦。木制中胃，病势深沉，虑难奏捷。", "12526": "右脉弦大不平，胃失冲和，木犯中宫。肝为刚脏，非柔不和，纳食主胃，胃降则和。肾不吸胃，胃关不健。金匮肾气，养肝补肾，纳气归窟，上病治下。十味温胆，奠安中州，未获效机。鄙见浅陋，拟补中益气加减，多酌。", "12527": "（案8）肾虚胃关不健，饮食迟于运化，中虚健运失常，痰起中焦。脉来弦大而数，按之无力。肾之阴亏，肝之阳强，犯中扰胃，清浊混淆，天地不泰，致生否象。胸满头眩，夜来阳强，梦多内热，四肢无力。胸下脐上，左右痞块，横硬延年十载。操劳烦心太甚，心肝肾三阴皆亏。香燥难投，谨防气痰作阻，法宜乙癸同源。", "12528": "（案9）左脉沉弦，肝郁中伤，右脉沉滑，气逆痰阻。中宫失运，胃不冲和。年逾六旬，五液先亏，防成关格。", "12529": "（案10）思虑伤脾，郁怒伤肝，肝胃不和，饮食减少，中宫不畅，懊𢙐作痛，病已多年，脉象双弦，弦者为减，殊属不宜。肝郁达之，火郁发之。拟东垣补中益气法，调中养胃，不致三阳结病为吉。", "12530": "（案11）脉来沉滑，气痰作阻，胸次不开，噫逆不爽，慎防堵塞。舒肺胃以展气化，不致病结则吉。", "12531": "生脉散加半夏、诃子肉、阿胶、荸荠、白蜜、姜汁", "12532": "左脉弦，右脉结，情怀抑郁，气勃于中，五志过极，皆从火化。木郁达之，必得抑郁开怀，心肝得太和之气，自臻安吉，否则防其结痹。", "12533": "开上实下，轻舒肺气，胸次渐开，天地交泰，否象自除。从心脾进步，候脉无结象，再为易方。", "12534": "脉来沉小，气胀拱痛，汩汩有声，二便皆不通畅。前哲以溲便不利，谓之关，饮食不下，谓之格。阴阳偏胜，病之逆从也。", "12535": "（案15）年逾六旬，操劳烦心，中胃不和，食入痛阻，机关不利，两脉俱弦。木犯中胃，殊属不宜。所服之方甚好，仿以为治。", "12536": "生脉散、二陈汤加竹二青、枇杷叶", "12537": "生脉散、二陈汤加枳实炭、杏仁、枇杷叶", "12538": "（案4）六脉往来调达，气分虚而肝脾不足。恙因思虑伤神，中焦失运，肝气横逆，木来侮土。《经》云：胃主纳，脾主运，一纳一运，化生津液。又兼胃中无火，不能消谷。命门火虚，釜底无薪。早进金匮肾气，晚服十九味资生。此二方最稳。然久患肝脾，汤药不宜多服。况年高气弱，津液内耗，温燥之品，亦不可多投。宜滋肝调气，静养怡情，庶乎相合。", "12539": "或加乌犀角（五分），脉数大加大古勇（五分）", "12540": "服药虽愈，不能霍然，脉来沉数，肾不交心，心阳上亢，子午不交，寤不成寐。拟六味地黄丸加味。", "12541": "（案2）脉来动滑，按之则弦，不知喜怒，多疑多虑，心胆自怯，郁损心阴，胆虚不寐。惊则气乱伤心，恐则精怯伤肾。胆为中正之官，心为主宰，肾为根本。胆附肝之短叶下，肝虚胆虚，胆冷无眠，胆虚亦无眠。", "12542": "（案4）倾接手书，敬念尊夫人。服药后心内转觉烦扰不宁。廿三日又服一帖，精神略减，饮食未进，日日如是。《经》所谓胃不和则卧不安。《难经》云：经有十二，络有十五，余三络者，阳𫏋、阴、脾之大络也。凡经络二十七气相随上下。其𫏋络不拘于十二经络，阳𫏋统诸阳络，阴𫏋统诸阴络。越人云：络脉满溢，不能拘通。譬之沟渠溢满，流注湖泽而不环周。故十二经不能拘其𫏋络，𫏋络亦不拘于十二经。是以古无治奇经八脉之法，亦未立方，只有针刺八脉之法。今厥气客于脏腑，卫气独留于阳。行于阳则阳𫏋盛，不能入于阴则阴𫏋虚，故目不冥。法用半夏秫米汤者，以药力不能直入阳𫏋，故治胃以泄胃气也。半夏辛温，入胃经气分。秫米甘酸，入胃经血分。乃北地之膏粱、芦栗是也。用千里长流水扬之万遍，与甘澜水同样，取其轻扬不助阴邪。炊以苇薪武火也，火沸入药。仍徐炊令减，寓升降之法。升以半夏，入阳分，通卫泄邪。降以秫米，入阴分，通营补虚。阴阳通，卧立至，汗自出。故曰汗出则已矣。", "12543": "大渴引饮，舌裂唇焦，火灼金伤，津液枯涸，能食脉软，此属上消，亦曰膈消，谨防发背。", "12544": "消渴已止，眠食俱安，痰嗽未平，胸腹仍胀，乃木火余威，木指金鸣，火灼金伤故也。曾经大产后，经前作痛，于兹七载，八脉有亏，现经闭二月有余，脉象细数无力，非胎候也。有虚劳之虑，宜静补真阴。", "12545": "（案7）脉来软数无力，证本阴液有亏。五志过极，俱从火化。万物遇火则消，故饥嘈善食。食不能多者，三消未著也。前哲治消症，必先荡涤积热，然后补阴。否则火得补而愈炽。服泻心五帖，火势已杀，宜补真阴。", "12546": "（案3）阳明胃火上炎，头中震痛如动脉之状，时作时止。脉洪而数，寒以取之。", "12547": "（案4）素本阳虚，不时巅痛，脉来细数，容色萧然。阴翳上滞精明之府。法当益火之源。", "12548": "（案5）宿疾阴亏，巅顶时痛，面色戴阳，脉来软数，浮阳上扰清空。暂以壮水之主。", "12549": "（案6）脉来沉滑，头痛如破，痛甚作呕，食入则吐，胸满胁胀。湿痰盘踞中州，清气无由上达清虚之所，名曰痰厥头痛。主以温中消饮，佐以风药取之。", "12550": "怒损肝阴，木郁化火，下耗肾水，上熏巅顶。值有妊三月，奇脉亦受其戕。少阴虚不能引巨阳腑气则巅痛，阳维为病苦寒热。拟逍遥散加味，以条达肝邪，治其寒热巅痛之本。", "12551": "（案1）胃脘当心而痛，痛则水泻。脉滑而弦，舌有黄苔，不思谷食，胸闷不宽，积湿化热，兼之停食，食聚中胃作楚。", "12552": "（案3）年甫念三，胃病九载，痛则呕吐酸水，脉象沉弦而滑。中阳不建，胃寒积饮。拟苓桂术甘加味。", "12553": "（案6）旧恙肝虚，气郁作痛，调治虽痊，去冬因风袭肺络，痰嗽延今不已。形神日羸，饮食日增，腹中汩汩有声，脉来细数无力。中虚积饮伏于肺经，乃虚劳之渐，殊堪虑也。", "12554": "痰嗽稍平，脘痛复作，按之则痛缓。可按为虚也。经以脾络布于胸中，肺脉还循胃口。证本木旺中虚，土不生金，风邪伏肺，气机不展。痛则不通，不可拘痛无补法之说。通则不痛。通者，宣和也，非必通利也，补亦可通也。益水生木，培土生金，展气化、宣伏风主治。", "12555": "服丸徐治，入冬以来，脘痛时作时止，痰嗽或减或增，饮食较进，细数之脉未起。脾肾双亏，伏风未尽。肾病当愈于冬，自得其位而起。不愈者，以水旺于冬，而冬水反涸，其体因少生生之气故也。水冷金寒，肺有伏风，外风易感，同气相求也，必使里气融合，方可有济，暂从温散。", "12556": "温散伏风，痰嗽竞止。脉仍细数，脘痛依然。暂以二陈加味，以搜肺络之余风。服三帖，仍以甲子所拟丸方调治（方未见）。", "12557": "乙丑五月诊脉仍细数。素本阴亏，木不条达，克制中胃。中伤络损，气失冲和。肝郁则痛，胃伤则呕。阳明之气下行则顺，太阴之气上升则和。《经》以六经为川，肠胃为海，以通为主。五六日更衣一次，阴液不濡，肠胃燥涩可知。香燥开胃非所宜也。拟以润燥生阴，佐和中胃。", "12558": "丙寅二月诊脉之细数如初。饮食较前略进，形神渐振。痛吐之并作，举发渐稀。证本肝阴不敛，克制中胃，胃不冲和，传化失职，津凝为饮，液结成痰，中虚清气不展，阴霾上翳否象。呈与七方甘缓，最为妥协。服四五帖后，仍服甲子拟丸方调治。", "12559": "肝阴不敛，肾阴不滋，健运失常，中伤饮聚，痛呕并见。屡发不瘳，肾损伤于肺，肝病传于脾。肾气通于胃，脾络布于胸。络脉通调则不痛，胃健气强则无痰。治病必求其本，滋苗必灌其根。若不培养真元，徒以痛无补法，印定呆法，安望成功。数载以来，病势退而复进，脉体和而又否者，病势苦深而少静定之力也。盖阴无骤补之法，草木功能难与性情争胜。金为水母，水出高原。谨拟补肾生阴为主，清金益肺辅之。俾金水相生，从虚则补母之法，乃经旨化裁之妙，非杜撰也。", "12560": "生脉散加白蜂蜜", "12561": "昨进生脉散，夜得少寐。今仍痛呕，虽体气素壮，然病将三月之久，脾胃已困，肝木独旺。肝在声为呼，胃气逾逆，不能饮食，转输愈钝，大便不行。肝为刚脏，非柔不和。胃为仓廪，非谷不养。肝气郁极化火，火灼阴液为痰，痰凝气结，幻生实象，非食积壅滞可下也。公议生脉散加金匮大半夏汤。", "12562": "生脉散加金匮大半夏汤", "12563": "痛呕不止，饮食不进，大便不解，夜来少寐，总由水不涵木，火灼液耗，两阳合明之气，未能合洽，故上不入下不出，中脘痛呕不舒也。此时惟宜壮水清金，两和肝胃。木欲实金以平之，肝欲急甘以缓之。水能生木，土能安木。肝和则胃开纳谷，胃开则安寐便解。此不治痛、不通便，而通便止痛之法在其中矣。仍以生脉散金匮参蜜半夏汤合甘麦大枣汤。", "12564": "生脉散、参蜜半夏汤、甘麦大枣汤加黄粟米甘澜水煎。", "12565": "生脉散合六味地黄丸", "12566": "（案12）木乘土位，转化失常，清阳不升，浊阴不降，升降失司，否而不泰。脘痛如刺，呕吐痰涎，不思饮食，脉来软数已历多年。正气已亏，殊难奏捷。拟调气法，中加以辅正之品。", "12567": "（案13）阴虚于下，肾不养肝，木乘土位，健运失常，不能化运精微二气，源流不畅。痛则不通，是以痛呕，不能纳谷，延今四载有余。春末夏初举发，今年发在冬时。脘痛如刺，呕吐不食，呻吟不绝，几致汗脱，延绵四十余日。服药呕虽平，饮食难进，脉尚未起，虑其来复，以丸代煎，徐徐培养。", "12568": "（案14）病原前方申说，第脘痛甚则怯寒，肢尖面目不可以当风，此属气闭不能敷荣四末、上走清空，非真寒也。服理气之剂，佐以山栀清气郁之火，痛势虽愈，呕平食纳，数脉亦缓。证本木乘土位，中伤气郁，化火伤阴，不宜烦劳动怒。肝病治脾，前贤良法。拟归芍六君加减，运中枢以畅清阳为主。", "12569": "（案15）肝郁乘脾，中伤气痛，食饮少，食入时吐，脉来细数无神。久延有虚劳之虑。《经》以怒为肝志，木郁达之。然草木功能难与情志争胜，使非戒怒，终无济也。", "12570": "（案1）胁痛本属肝胆。二经之脉皆循胁肋。素本忧劳，忧伤肺志，劳动心阳，心肺伤而肝胆郁。法当宣补，未可作东方气实宜疏论治。", "12571": "（案4）暴怒伤肝，木火载血，妄行清窍，胁肋胀痛，烦热脉洪。宜先泻东方之实，兼助中央之土，以杜传脾之患。", "12572": "（案8）肝胆之脉，循于胁肋。忧思过度，致损心脾。气血不能流贯，致令厥少二经不利。心脉亦循胸出胁，脾伤故木不安，是以胁肋隐痛。培补心脾，治病之本。", "12573": "（案1）腰者，肾之府。腰间空痛，按之稍缓，能直不能曲，病在督脉也。", "12574": "（案2）腰为肾府，痛属肾虚。肾与膀胱相表里。太阳之脉，夹脊抵腰，督带冲任，要会于此。素耽酒色，肾阴本亏，恬不知养，潜伤四脉，时有痛作，屡发不瘳。展转沉涸，岁月弥深。行立不支，卧息稍缓。暴痛为实，久痛为虚。在经属府，在脏属肾。拟方缓治。", "12575": "（案3）脉象沉弦，气郁动肝，肝冲气胀，已历多年。不耐烦劳，大腹小腹胀痛。形容憔悴，血不荣色，心脾营损，肝气横逆。养心脾以合肝胃。", "12576": "腹痛已痊，饮食已香，夜来寐安，脉神形色俱起。不宜烦劳动怒，原方损益。", "12577": "据来恙源，细参一切始原，遍身发冷，出汗不止，服真武加减未效。后便血，脐左右有硬积二块，头晕夜烦。两胁心腹作胀，筋骨疼痛不舒。肝主筋，脾主四肢。阴液本亏，阳明郁痰闷结，气积凝而成块，连服温胆小效。后服下剂，更兼礞石丸，据云症势已减六七，惟硬积跳动不消。此症虽在肝脾，总由肾之水亏，肝之阳强，阴液不充，是以气积不化。《素问》云：阳在外为阴之使，阴在内为阳之守。气行血流如风行水动也。仲景谓养正而积自除，正充而块自解，攻乏之剂不过一时，恐未能豁然。拟养正消积，固气和阴，久服可效，但不知脉象何如耳。", "12578": "（案2）脏气实者，虫无以生。虫生，必脏气虚也。证本肾虚于下，木失敷荣，木乘土位，脾困于中，蕴生湿热，化生蛔虫。虫蚀脂膏，痛如锥刺，时作时止，脉反浮洪。痛甚颊青唇赤，是虫之验也。治宜固肾扶脾为主，追虫渗湿助之。", "12579": "适接来札。服药后，腹内平静无声，此虫蛊何疑，后忽呕吐泄泻，并有青黑砖瓦色，茶杯口大数块，虫蛊化而未尽，更恐夹以暑湿积食，亦未可定，未见症不能悬揣，且实系虫化，亦当下行者顺，上行者逆。逆则脾阴大伤，正虚积不能化，甚为险要。但不知脉象如何耳，姑拟固正下积，静以待动。", "12580": "（案1）脉来沉滑而疾，湿痰内郁，化热生风，先是脚面麻木，引延两手，右手食指跳动，井肩环跳俱痒，入暮潮热。当理太阴阳明，化湿热，以杜风患。", "12581": "脉来滑疾，风湿郁于阳明，肝肾不足，两腿两手脊筋作痛，寐来更甚，两耳作响。湿热郁结，气化为火。", "12582": "接来恙原，服药已效，将木通减去三分，加车前子二钱、党参三钱。服数帖便中，来商再为诊脉。拟方顺候近安。知名恐呼，奉返谦简，每早服二妙丸。", "12583": "（案1）脉来虚数而弦，三阴内亏，湿热郁而不化。肾气不衡，肝不荣筋，精血大亏，腿瘦，胫弯，痛无宁息，病势不一，股内热痛，大腿如针刺痛。膝盖胫弯俱酸冷胀痛，魄门坠胀疼痛，左腿形如鹤膝，坐卧不宁，饮食不甘，病延已久，下痿已成，虑难奏捷，多酌。", "12584": "（案2）脉来虚数，肝肾两亏，酒色内伤，腰痛肋胀。延今两腿麻木，步履无力，口干便结。少腹作坠，谨防下痿。", "12585": "（案1）《经》以任脉为病，男子内结七疝。冲任同源，为十二经脉之海，起于肾下，出于气街，并走阳明经，夹脐上行至胸中而散。症因思虑烦劳，损伤中气，亏及冲任。任虚则失其担任之职。冲虚则血少不能荣筋。肝主一身之筋，与肾同归一体。前阴为宗筋之会，会与气街。以故睪丸下坠，不知痛痒，名曰𤻊疝。前哲治法颇多，效者甚鲜，暂从中治。", "12586": "（案3）二天不振，八脉有亏，任脉不足，睪丸下坠。偏于左者，肝也。肾气通于耳，水不济火则耳鸣，火炽阴消则精滞。脉来虚数少神，脾肾双补为主。", "12587": "（案3）思为脾志，心主藏神，神思过用，病所由生。心为君主之官。端拱无为，相火代心司职。曲运神机，摇动相火，载血上行，下为遗泻。因循怠治，病势转深，更增虚阳上越眩晕等症。诸风掉眩，皆属于肝。面色戴阳，肾虚故也。不能久立久坐者，肝主筋肾主骨，肝肾不足以滋荣筋骨也。眼花耳啸者，肾气通于耳。肝开窍于目，水弱不能上升，血少不能归明于目也。胸背之间隐痛如裂者，二气无能流贯，脉络不通也。呕吐黄绿水者，肝色青，脾色黄，青黄合色则绿，乃木乘土位之征也。前阴为宗筋之会，会于气街，而阳明为之长。心脾不足，冲脉不充，宗筋不振，阴缩不兴。滋阴降火，苦坚之法，最是良谋。惜少通以清寒之品，以故无效。不受温补热塞之剂者，盖壮年非相火真衰，乃抑郁致火不宣扬，膻中阴瞑，离光不振也。相火不足，宜益火之源以消阴翳。相火不宣，则宜斡旋中气，以畅诸经。譬如肾火蔽障则微，透风则翕然而起矣。", "12588": "（案2）脉左弦右软，气虚阴亏，肝之阳强，必由郁怒所伤。气失调达，心火湿热下注，火掩精关，疼痛淋浊，乃湿伤气，热伤阴。补阴益气，棋之先著，拟方候酌。", "12589": "湿热伤阴，溺管疼痛，血淋之后，阴阳未复，脉来数象，水部有火，湿热有余，热沥不尽。", "12590": "进补养肝肾与化湿热，溺管痛舒，血淋亦止。四五日间有疼痛，脉来虚小。肝肾精血未复，余气未尽，以丸缓图，清养为妙。", "12591": "五进补阴益气，淋浊已止，阳举不痛，皮外不痒，脉来左大，晨舌作干，阴虚不能上潮，以乙癸同源。", "12592": "（案6）脉来弦大，两尺不静，湿热伤阴，心相不静，欲火凝结，湿郁不化。考五淋治法，不越虚火、实火，必得清心绝欲，方能有济。", "12593": "（案1）膀胱为州都之官，津液藏焉，气化则能出。小便淋漓不畅，少腹、大腹微胀，舌绛口干，固由湿热伤阴，亦由精不化气，气化无权，服药或效，或不效者，里气空虚也。肝主疏泄，肾主闭藏。州都无约，水泉无束。考古名家虚火虚气，湿热不化，补中兼开，隆冬闭藏。年逾六旬，脉不应指，似无通利之法，恐伤生发之气。", "12594": "（案2）脾司清阳，胃司浊气。肾司二便，肺主治节。年逾花甲，二气渐衰，湿热内伤，脏不行腑，气化无权。但两脉俱弦，按之无力。真阳虚衰，真阴亦伤，脾胃困顿，小溲不通，气化不及州都。", "12595": "补命肾以建中阳，健脾胃以化湿热，补阴益气，升清降浊，腑气已调，小溲畅行。脏已安适，脉之双弦已和，面色已开，精神渐起，以丸徐徐调养，自臻安吉。", "12596": "（案1）《经》以肾开窍于二阴，主五液而司开合。饮食入于胃，津液输于脾，归于肺，注于膀胱，是为糟粕转入小肠，传送大肠，出于广肠，是为大便。其中酝酿氤氲之气，化生精血，滋润五脏，营养百骸。盖大肠传送，相傅为之斡旋，故肺与大肠相表里。肺为传送之官，治节出焉。肾之液涸，赖州都为之藏蓄。故肾与膀胱相表里。膀胱为州都之官，津液藏焉，小溲多而大便结，正与小溲秘而大便泄同归一体。便泻、便秘乃清浊相混，溲多便结乃清浊太分，过犹不及。脉来软数无神，尺部尤甚，证本阴亏水不制火，火灼金伤，寒热如疟，注泄之后，五液耗干。肺不清肃，无由下降，致令开合失司，传送失职。州都津液少藏，故大便秘而小便数。拟清上实下主治。清上则肺无畏火之炎，实下则肾有生水之渐。冀其金水相生，肺肾相资。清归于肺，润归于肾，则大肠无燥闭之患。愚见未识，高明以为然否。", "12597": "（案2）六脉细软，按之少神。恙由肝肾不充，气虚不健，以致小溲勤而短，大便反结。《经》云肾开窍于二阴，阴不足则气反虚而不运，法宜益气以清阴。", "12598": "（案3）脉数且滑，湿热伤阴，肠风便血。", "12599": "（案4）便血多年，先后不一，先紫后红，并有血块，腹中隐痛，脉来滑数，按之无力。三阴内亏，湿热不化，阴络受伤。肝不藏血，脾不统血，气不摄血，渗入大肠而下。", "12600": "（案2）脉左紧右缓紧，是腹痛之征，缓是脾玩之候。暴起寒湿，水气作泻，温熨是理。已延月余，绕脐作痛，气虚作坠，痛则作泻，湿郁化热之象。精通之岁，阴未和谐，久泻又伤，以香连归芍汤加减，是否候酌。", "12601": "（案3）面浮肢肿，入谷则出，腹胀胸闷，大便溏泄，小水不畅。六脉沉紧而涩，舌根白色不起。风湿抑郁，食填太阴，脏寒生满，浊气逆上，则生䐜胀，清气反下，则生泄泻。总由出纳之官应运不灵，是以二阴开窍不爽。拟温里以开通上下。延久脾阴大伤，牵及肾气，更为棘手。", "12602": "（案4）鼻涕稠浓，且有腥味。年甫十九，鼻息不利，有息肉脑空之患，脉来滑疾，已延七载，难于奏捷。拟清上实下主治。", "12603": "（案10）目为肝窍。《经》以五脏六腑之精气皆上注于目而为之睛，睛之窠为眼，骨之精为瞳子，筋之精为黑眼，血之精为络，气之精为白眼，肌肉之精为约束。曾经目赤，因循未愈。近乃白睛赤缕参差，浮红成片，时多泪出，内眦凝眵而瞳子黑睛无恙。此肾水下亏，不能生木。木燥生火，火甚生风，风火相搏，肺金受制。白睛属肺，肺热故白睛发赤。时多泪出，譬如热生风乃能雨，热耗津液，故多眵。脉来软数而空，有赤脉贯瞳子之虑。治宜壮水生木，升阳散火，不可泛服涤热之剂。《经》有上病下取之旨，拟明目养肝丸加减。", "12604": "（案12）水亏于下，火升于上，水不制火，阴不胜阳。缘少年嗜欲太过，水失所养，木燥生风，风火交并于上，阴液潜消于下，致令黑睛暗淡，瞳子无光，色兼蓝碧，此为内障。《经》以五脏六腑之精气皆禀受于脾，脾明于目，脾为诸阴之长，目为血脉之宗，肾为先天之源，脾为后天之本。脾土之强健赖肾气之充盈，肾气虚脾亦虚，脾虚则脏腑之精气皆失所司，不能归明于目。肝虚则血不归原，肾虚则水不济火，以故暗淡无光。治宜壮水济火，补阴潜阳，冀其水升火降。", "12605": "（案15）《经》以十二经脉、三百六十五络，其血气皆上注于目而走空窍，其别气走于耳而为听。心开窍于耳，肾之所司也。肾为藏水之脏，肾虚则水不能升，心火无由下降，壮火食气，气虚不能上走清空。阴液下亏，脉络为之干涸。气血源流不畅，是以耳内常鸣。素多抑郁，五志不伸，水虚不能生木，肝燥传脾，土虚不能生金。肺病及肾，肾气不平，五内互克，展转沉疴，岁月弥深。壮岁固不足虑，恐衰年百病相侵，故不仅耳闭已矣。是宜沉志静养，遣抱舒怀，补以药饵，方可有济。拟局方平补正心丹，去上病下取之意。", "12606": "（案16）齿痛上引太阳，因眩晕左肢麻痹而起。金水二脏素虚，眩晕乃肝邪所致。金虚不能平木，水虚不能制火。故肝阳内扰，阴火上升，肝位于左，气虚则麻，兼以酒酪肥甘过当，湿热蓄于肠胃，上壅于经，故见手足阳明、手太阴、足少阴四经之症。夫齿痛属阳明之有余。眩晕、麻痹属太少之不足。按《灵枢·经脉》篇，手阳明之脉，其支者从缺盆上头贯颊入下齿中；足阳明之脉下循鼻外，入上齿中。齿痛之由本此。第久于岁月，病势已深，调治非易。爰以清胃玉女加味，从阳明有余、少阴不足论治。", "12607": "（案18）肾水不足，心火有余。舌为心苗，火性炎上，水不济火，舌为之糜。脉来软数无神，缘五志乖违所致。上病下取，滋苗灌根，法当壮水之主，以制阳光。", "12608": "（案20）肾水不足，肝木失荣，木燥生火，火甚生风，风火交并，上冒清空，声哑舌强，视听不聪，脉来软数无力。治宜益气壮水调中，冀其水火既济，天地交通。", "12609": "（案21）音声本于脏气，气盛则声扬，气虚则声怯。肾为音声之本，舌为发声之机，气为声音之户。肾主藏精，精化为气，肺司气化，气主发音。证由诵读太过，损于脏气。河间以五志过极，俱从火化。火盛刑金，金溶不鸣。舌为心窍，肾为水脏。火性炎上，火旺水亏伤其本而失其机，是以声哑语言难出。脉来滑数而空，爰以铁笛加减。", "12610": "（案1）《经》以任脉为病，女子带下，客秋小便有血，秋后带见五色，每逢小便作痛，夜寐不安，饮食不甘，心移热于小肠，湿热、肝火内郁。病延半载，极难奏效。", "12611": "（案2）日来带下，频频不止，大便艰痛，小水色黄不畅，腹内有硬块，腰膝酸痛。《经》云肾气开窍于二阴。阴亏阳不敛，虚寒之质，液络精气枯涸，大为可虑。东垣谓连桂同功，能交心肾于顷刻，纳气下降，导火归原，亦前贤之良法也。立方呈政，须与贵处诸同道切脉验证，服三四帖仍祈赐酌。", "12612": "（案3）《经》以女子二七天癸至，任脉通，太冲脉盛，月事以时下。又二阳之病发心脾，有不得隐曲，女子不月，其传为风消，其传为息贲者危。汛闭年余，饮食日少，形体日羸，脉来弦动，乃郁损心脾，木乘土位所致。心为生血之源，肝为藏血之脏，脾为统血之经。心境不畅，肝不条达，脾失斡旋，气阻血滞，痞满生焉。五志不和，俱从火化。火灼真阴，血海渐涸，故月汛不以时下，必致血枯经闭而后已。将治心乎，有形之血难培；将治脾乎，守补中州易钝；抑治肝乎，条达滋柔均皆不受。当以干运中枢为主，俟脾胃渐开，以四物、逍遥养肝舒郁，再以归芍地黄补阴养血，和调冲任，冀其经通，方为佳兆。", "12613": "（案4）左脉弦出寸口，志意隐曲不伸，抑郁损心阴。阴虚血少，血不荣脾，脾伤不能为胃行其津液，胃病不能容受水谷而化精微。精血日以益衰，脉络为之枯涩。经闭半载有余，腹中虚胀作痛，荣色憔悴，饮食减少，拟归脾法。", "12614": "（案5）经血乃水谷之精气，调和于五脏，洒陈于六腑，源源而来，生化于心，统摄于脾，藏受于肝，宣布于肺，施泄于肾，上为乳汁，下为月水。经秘五载有余，饮食起居如故，无骨蒸痰嗽等症，乃任脉经坠滞塞，非血枯可比。手指肿，肿色紫，不时鼻衄，经血错行可知，营气不从，逆于肉里，遍体疮痒，脉来滑数而长，有痈疽肿满之患。拟子和玉烛散。多酌。", "12615": "（案6）汛愆，胸腹相引而痛，痛时手足逆冷，食生冷寒凉即发，腹中雷鸣，脉来沉细，显是命火中阳不足以煦和五内而敷荣四末，由产后气血双亏、虚寒为祟。治宜益火之源，以消阴翳。", "12616": "（案7）素本月事不调，今正晡热，巅疼胫肿，经居三月，脉来滑数。年甫廿四，肝脾不和，胃不开畅，湿郁不行，理脾胃以观动静。", "12617": "（案13）素有痛经症。阴液本虚，今春腹痛作泻，寒热呕吐胀闷频频不止，感邪夹湿，胃脘久伤，六脉沉涩，左部尤甚。胃为水谷之海，阳明阻塞，清不能升，浊不能降，脾湿生痰，肝木侮土，最为险要。况当经期犹须防内因、外感二者交病，恐生厥搐、呃逆、肢冷之险。", "12618": "左脉尚缓，右脉尚大。气郁填胸，气血俱病，五损之病，宜从中治。调其饮食，适其寒温，心畅肝和，脾胃健运，方能有济。", "12619": "（案21）女子首重调经，经调方能有孕。经先期，少腹胀痛，不时呕哕，脉见双弦无力。少腹主于肝。肝病善痛，肝传脾，脾病善胀，脾传胃，胃病善呕。饮食不甘，肝脾胃俱病，以丸缓治。", "12620": "（案26）《经》以齿乃骨之所终，手足阳明之脉上循于齿，地癸主于冲脉。冲为血海，并足阳明经而行。阴虚无以配阳，水弱不能济火。经事先期，不时齿痛。当以阳明有余、少阴不足论治。", "12621": "（案27）气不卫外则寒，血失中营则热，经无约束则愆期。二气素虚，奇经复损，督行一身之阳，任行一身之阴。任督犹天之子午，冲脉从中直上，若地之云升。法当静补真阴，以充八脉。", "12622": "生脉散加熟地黄、鱼鳔、山芋肉、山药、归身、左牡蛎、白莲花熬膏。", "12623": "（案28）经以应月，月以三旬而一盈，经以三旬而一至，象月满则亏也。亏极则病，阴亏则火盛，火盛则逼血妄行。《经》以阴虚阳搏谓之崩也。服药以来，崩漏虽止，巅顶犹痛，腹中䐃䐜胀。厥阴之脉上出额，与督脉会于巅顶，下络少腹。水不涵木，阴不敛阳，巅痛腹胀，脉尚软数无神。仍以壮水潜阳为主，冀其血气各守其乡，方无来复之患。", "12624": "乌贼骨丸、生脉散加生地、知母、玉竹、枣仁、牡蛎、归身、白芍蜜丸。", "12625": "（案29）冲为血海，下司肝肾，上隶阳明。经行饮冷，瘕聚胞中，延今十余年。经来脐下硬痛，连及两腰，任脉亦病，病深难于痊愈。", "12626": "（案30）腹中素有血症，大如复杯，脉络阻碍。经血循环失其常度。经不及期，经前作痛。气郁伤肝，木乘土位，饮食减少，悲哀伤肺，治节不行，胸次不畅，腰如束带，带脉亦伤。年逾三旬，尚未妊子，必得经候平调，方能孕育。", "12627": "左脉涩，右脉弦。肝郁中伤，气血凝结，经不通行，气胀腹痛，饮食不思。二阳之病发心脾，有不得隐曲，女子不月，其传为风消，其传为息贲者不治。", "12628": "（案34）脉来滑数而空，似有胎而不果腹，无坚硬之处，非停瘀可比。素本经事不调，日晡热，头痛时作时止，阴亏血少，病在肝脾，木不调达，土运郁壅。崇土培木，宣补中州，观其动静。", "12629": "（案35）脉左涩右弦，肝虚气血凝结，经居四月，似有胎而不固，心悸脘痛，漏淋不已，气聚为瘕。肝为起病之原，胃为传病之所。养心脾兼和肝胃。", "12630": "（案36）诊得六脉细数而弦，每胎堕总在二三月，腹内积有硬块。《经》谓妊娠，司胎一月在肝，二月在胆，三月在心，四月三焦，五月在脾，六月在胃，七月在肺，八月在大肠，九月在肾，十月膀胱。此症总在二三月胎漏，只缘肝胆，血热伤及心脾，太少二阴受恙，是以气不充血，积块频频，不化遵程。法养正消积合养阴滋降，以补天一之水，和阴清热，以泻地二之火，拟益母胜金丹加减。", "12631": "脉不应指，胎元不长，服回春丹安住亦必胎长为妙，仍防流滑。", "12632": "（案1）霍乱转筋，阴阳乖隔，寒暑交争，肢冷烦躁，苔黄脉闭，内陷之症。姑六和加减，恐难挽回。", "12633": "（案2）饮食自倍，肠胃两伤，经脉横解，肠澼为痔。素本善饮，湿甚中虚，肠澼延绵不已，虚气下坠，升降失常，滞下甚多，胀而不痛。此属虚也，气血交亏，湿郁化热。", "12634": "（案4）呕吐清水，痛则欲绝，脉象细软而涩，大非所宜。", "12635": "（案5）恙因肝郁夹湿，木旺土亏，胸闷作呕，气逆痰不升，间有寒热，此肝虚湿患，非客感也。脉来细软而滑，速宜固正和中，调脾渗湿。煎丸并进，尚可收功。", "12636": "（案11）酒湿伤阴，心脾肾三阴不足。手足振掉，莫能自主。巅眩目中生花，脉细数无力。非少壮所宜，有阴痱之患。宜壮水生阴，助土渗湿。", "12637": "（案12）湿热伤阴，中虚湿胜，脾主四肢，战栗动摇，火之象也。湿热化火，蕴于中州，以致两手动无宁息。诊脉软数无神，治宜培补心脾，参入甘温壮水之品。", "12638": "（案17）服调气畅中，木荣土渐旺，六脉稍觉和缓。缘阳在外为阴之使，阴在内为阳之守。扶阳即所以固气，气和而胃自调，照前煎方主治。", "12639": "生脉散：人参麦冬五味", "12640": "复脉汤（一名炙甘草汤）：炙甘草桂枝人参麻仁生地阿胶麦冬姜枣", "12641": "中脘痛连少腹，气滞寒停，寒热时作，感冒温邪，左脉弦数，右脉迟细，宜疏散畅中。", "12642": "温邪三日，头重骨疼，舌苔厚腻尖红，脉来弦大，按之微数，少阴阳明合病，柴葛解肌加白虎汤。", "12643": "时感九朝，胸闷寒热，口渴腹痛，舌白脉伏，有内陷之虑。", "12644": "斑疹隐隐，发而未透，喉疼，手足麻，头身皆痛而喘，脉伏邪闭，肺胃皆病，防其呃喘之患。服方是理，仍依法治。", "12645": "时邪八日，身发白㾦，舌苔厚黄而润，口干不渴，脉息沉数，有化热之势。热在血分，所以不渴。拟方候诸高明酌之。", "12646": "昨已更衣，通身有汗，热未退尽，舌强，舌心渐干，脉数少力。饮茶较多，邪势难解，仍防陷变。", "12647": "时疫四朝，壮热无汗，胸闷舌白，身痛腹泻，呕恶，神烦口渴，脉来浮数，妊娠两月，斑尚未透。", "12648": "妊娠足月，感冒时邪，身疼烦躁，壮热口渴，脉数舌绛，邪郁阳明，谨防热甚伤胎，气急谵语之变。", "12649": "复诊昨用苦降合清营之法，内热稍缓，苔亦较化，脉亦较和，惟脘痞格拒，腑气不通，日晡热甚，阳明之滞未下，火邪劫烁阴津，虑阴津消亡，发为陷症。议甘寒泄热，佐和中润下治之。", "12650": "四诊恙势较退，滞气已出胃腑，是属佳兆。惟脉来细数，脏阴、营液俱亏。若得腑气宣通，阴气来复，方保无虞。", "12651": "吴神迷不能语，牙关紧闭，发热面红，口甜，痰沫黏腻，小溲自遗，四肢不举，脉浮洪，舌苔滑腻。据述在军前甫回，旋即寒热，复食生冷，窃思病情，始因惊恐，复感秋邪，痰热蒙闭，先用至宝丹、石菖蒲、竹油汁汤下，一时许，神即清爽，再用煎方。", "12652": "病后复劳感邪，虚邪袭入，始发寒热，今则寒去而热蒸蒸，蕴于脾肺两经，舌苔白厚，有汗而热不清，溺赤似痛，脉数而濡，腠理空疏，是以多汗，阴虚夹痰，蕴恋于络，议景岳服蛮煎加竹叶石膏汤主之。", "12653": "疫邪两候，阴分已虚，热糊不清。口渴多饮，舌黑底绛，谵语不宁，痰咯不爽，脉象弦滑，伏邪化热，热郁不达，伤阴损精，正虚邪实，暂拟养阴化痰，兼开太阴。", "12654": "时感十朝，日前寒热如疟，目今已止，惟胸胃不开，精神萎顿，五更作呕，溲黄内热，脉来弦滑，且不宁静，伏邪未化，少阳阳明皆不清楚，未可言愈，不生风波即吉。", "12655": "脉来沉弦而数。沉者，郁也。肝郁不畅，气化为火，少阳不宁，右脉滑疾，湿热生痰，心肾两亏，厥阴之气鼓动火炎于上，上盛则下耗，养心肾以和厥阴。", "12656": "少壮年华，湿热久郁，今夏大腿曾患湿痰溃脓之症，虽已愈合，而湿热伤阴，脉尚未静，以补其不足，泻其有余。", "12657": "精不化气，气不生阴，脉不安静，阴中之阳不运。阳腑之气不调，舌有裂纹，气分有热，阴中有湿，所服之方，俱在理路，轻可去实，每朝服猪胆丸三钱。", "12658": "脉沉而滑，湿热郁肺，肺气受伤，肾气不纳，湿热上冲，喘咳不止，清火化痰，防其气冲厥逆之患。", "12659": "黄为土色，脾为土脏。脾为湿热薰蒸，则中央正色发越于外。脾虚不能统血，肺与大肠相为表里，火盛灼金，迫血妄行、血去阴伤，宗气上浮，虚里穴动。疾因酒后湿热内生，血在便后，腹中䐜胀，是血离营位，脾失统摄之司。黄如草木将凋，非黄之正气，乃中土久亏，无以奉秋收之令，脉来滑数无神，当从蓄血发黄论治。", "12660": "肾为水之下源，肺为水之上源，膀胱为水之导引，脾土为水之堤防。胎前水肿，气化无权，治水之法，禹功疏凿虽善，然非羸弱所宜。虚则崇土，一定成法。如甘遂、大戟、芫花、商陆等，行水虽速，堤防不固，正气不支，终属不济。现在腹大如箕，腰围倍昔，脉渺如丝，喘鸣肩息，生气残矣。", "12661": "肾统诸经之水，肺司百脉之气，脾为中土之脏。脾虚不能制水，肾虚不能纳水，肺虚不能行水，泛滥皮肤则肿，流注脏腑则胀，脉来沉数无神，症势危如朝露，勉拟金匮肾气丸法，宗《经》旨「塞因塞用」之例。", "12662": "始因疟邪留肝，致成痞块，延今多载，加之气郁伤中，肝脾两伤，胸腹痞胀，两腿浮肿，二便不畅，饮食日减，精神日羸，脉见两弦，木来乘土，清浊混淆，势成中满，不可轻视。每服小温中丸钱半，拟东垣先生升清降浊法，不致中满则吉。", "12663": "木乘土位，健运失常，清阳无展舒，阴霾上翳，以故食入反吐，肿胀频仍，脉来弦数无神，久延有三阳结病之虑。治病必求其本，《金匮要略》曰：见肝脉之病，当先实脾。爰以归脾、六君加减，资坤顺之德，助干健之功，仍宣抑郁以舒神志，否则徒恃药饵之能，一曝十寒无益。", "12664": "脾为生痰之源，肺为贮痰之器。年逾七一，阴阳就衰，肺脾肾三经皆病，肿自下起，蔓延于上，腰大如围，下体重著，二便不利，湿不运行，少食则胀，清浊混淆，气化无权，势入老境。金匮肾气固是正理，脉见滑数，脾虚生湿，渍之于肺，有喘满之虑，暂以苏杏轻通，化湿化热，再进肾气可也。", "12665": "一剂觉烦扰不安，食入于胃，带饮呕吐，吐尽方安，改用大半夏汤早服，烦少定，呕仍未止，原方加当归、茯苓。又一剂，仍复烦躁气逆不纳，或寒或热、脉躁指黑，鼻生烟煤，改用四君子加附子粳米汤。一剂，呕未尽止，稍能纳谷，脉静肢和，黑气已退，似觉胸膺痹窒。此虚气上逆，浊饮上升，原方加芍药、桂枝以敛虚气，以开脾郁。", "12666": "外强中干，气火并于上。病因前年受寒咳嗽，曾服麻黄数剂，未经得汗。又服杷叶、款冬，似觉稍轻。素来善茶，故成茶饮，发则咳嗽痰多，呕吐清水，背脊发寒，手足发烧，服金匮肾气，口鼻出血无休时。服半夏饮，两耳鸣不寐。继又考试，操劳郁闷，且相火素旺，木火易兴，大便燥结，右手伸而难屈。相火内寄于肝，听命于心。心为一身之主宰，肾为十二脉之根本。操劳不寐，心肾不交，阴不敛阳，不能和气，气有升无降，所以耳闭不聪也。肺为相傅之官，秉清肃之令。六叶两耳，二十四节，按二十四气。风寒内伏，清肃不行，上输之津不能敷于五脏，而痰饮生焉。且茶饮苦寒，最能伤胃。脾虚生湿，水积不行。辗转相因，遂成痼癖。化热伤阴，苦寒败胃，外强中干，恐伤生发之气。拟归脾、二地、二术，以养心脾，兼和肝调中，化痰治饮。", "12667": "脉弦兼滑，偶感暴寒，咳嗽。手足发烧，服神曲汤已解。咳嗽未已，痰饮举发，水停心下为饮。风寒伤于外，七情伤于内，茶饮伤气耗阴，思虑伤其肝脾，惊恐伤其心肾，治饮兼解七情。现在感冒未清，治宜先标后本。", "12668": "左脉弦涩，右来濡滑，按不应指。寒能生湿，湿能生饮。内饮治肾，外饮治脾。腹为太阴，太阴者脾也。脐属少阴，少阴者肾也。少腹属厥阴，厥阴者肝也。肾病带动肝胃，胸乡气满胀痛，扬扬有声。上焦如雾，中焦如沤，下焦如渎。清浊混淆，脏病带动六腑。所服之方，井井有条，无庸他歧，仍请一手调治。", "12669": "肺为娇脏，内配胸中，为五脏之华盖。清虚之所，不耐邪侵，外司皮毛，下荫于肾。哮喘十载，脉来滑疾，两尺不静，郁湿、郁热、郁痰、伏风为患，极难脱体。", "12670": "前因咳甚，哮症复萌，痰多气阻，额上有汗。肾司五脏之精，肺司百脉之气。肺气不降，肾气不纳，中气不能树定中枢，肺虚不能主扬诸气。调中养肾，纳气归窟，子母相生。", "12671": "髫年宿哮，秋冬举发。发则不能安卧，豁痰乃平，于兹廿余载。现在举发，气促痰鸣不得卧，痰未豁，食不甘，脉弦兼滑。肺有伏风，为外风所引，液败为痰，痰成窠臼，虑难脱体，先小青龙加减。", "12672": "髫年哮喘，起自风寒，风入于肺，液变为痰，风痰蟠踞清空，每遇秋冬即发，喘兼咳嗽，痰带涎沫红丝，竟夕无寐，齁䶎声闻四近，形丰脉软，外强中干，补则风痰愈结，散则正气不支，邪正既不两立，攻补又属两难，少壮若此，年衰何堪，暂以崇土生金，是否观其进退。", "12673": "脉滑而数，肺蕴风痰郁热，清肃不行，哮喘痰鸣，舌燥唇干溲混，巅疼食减，宜先清燥救肺。所服之方，井井有条，仍请原手调治，何必远涉就诊。第肺为娇脏，恶寒恶热，苦寒虽效，未宜常服，恐戕生发之气。", "12674": "肺司百脉之气，为至娇之脏，不耐邪侵。邪侵毫毛必咳，庚辰寒客肺俞，宜服小青龙化邪外达。因循怠治，致令邪郁肺络，变生哮喘，发则不能安卧，延今四载，终身之累也。", "12675": "脉来沉滑而疾，童年哮喘，风伏肺络，延今廿余载，正气肾气俱亏，不能化邪外达。前进补土生金法，久病宜和养肺胃。至于三子养亲、苏子降气、小青龙等，取效一时，非常服之品。太阴湿土司令，湿侵渍肺，又当一论。现在大气发泄，用药尤难，多酌高明。", "12676": "脉沉喘咳浮肿，鼻窍黑，唇舌赤，渴饮，少腹胀急，大便解而不爽，此秋风化燥，上伤肺气，气壅不降，水谷汤饮之湿，痹阻经隧，化为痰涎，最多坐不得卧之虑。法宜开太阳之里，用仲景越婢、小青龙合方。若畏产后久虚，补以温燥，客气散漫，三焦闭塞则危矣。", "12677": "肾纳五内之精，肺司百脉之气。症本肾水下亏，子窃母气，致令肺虚于下。《经》以邪之所凑，其气必虚。肺合毛皮，风邪易袭，皮毛先受风邪，邪气以从其合。肺中津液，不归正化，凝结为痰。屡有伤风咳嗽气促之患，喉间作痒，金水枯燥，可以知而无疑。发时宜宣风豁痰，暂治肺咳之标，平复后宜温养真阴，常服补肾精之本。", "12678": "肺为气之主，肾乃气之根。肾虚则气不归根，肺损则气无所附。致使孤阳浮泛，无所依从，喘鸣肩息，动劳益甚，脉来细数兼弦，诚为剥极之候。", "12679": "痰火内郁，脏腑受伤，喘促，脉洪而滑，法当清肃上焦。", "12680": "水不配火，肾不纳气，气不归原。气有余便是火。右肾热气上漫，常多走泄，精神不振。肾属水，虚则热，补阴不易，补阳尤难。脉象六阴按之虚数不静，两尺尤甚，心肾两亏。今拟斑龙、归脾、起元、两仪合为偶方，培补命肾之阴阳，冀其水火既济，自然纳气归窟。", "12681": "实火宜泻，虚火宜补。风火宜清宜散，郁火宜开宜发。格阳之火，宜衰之以属，所谓同气相求也。水亏于下，火越于上，厥阴绕咽，少阴循喉，久咳音哑喉痛，口干不欲饮冷，脉洪豁，按之不鼓，格阳形证已著。清火清热取一时之快，药入则减，药过依然，所谓扬汤止沸，终归不济，导龙入海，引火归原，前哲良谋无效者，鄙识浅陋也。小陡暂清肺热之法，尚属平稳可服，再拟金匮肾气，竭其所思，未知当否？多酌明哲。", "12682": "久咳音哑，每咳痰涎盈碗，食减神羸，苔白厚，脉双弦，中虚积饮，土败金伤，水湿浸淫，渍之于肺，传之于脾，注之于肾，三焦不治，殊属非宜。", "12683": "脉来细数兼弦，症本脏阴营液俱亏。木击金鸣，下损于上，精血膏脂不归正化，悉变为痰，咳嗽痰多，喉痛音哑，乍寒乍热，自汗盗汗，气促似喘，腹鸣便泄，二气不相接续，藩篱不固，转瞬春动阳升，有痰涌喘汗暴脱之虑。姑以从阴引阳，从阳引阴，质之明哲。", "12684": "症缘秋燥伤肺，痰嗽不舒，继又失血。入春以来，痰嗽益甚，气促似喘，内热便泻，形神日羸，饮食日少。肾损于下，肺损于上，上损从阳，下损从阴，上下交损，从乎中治。脉来细数无神，虚损之势已著。谨防喉痛音哑，吐食大汗。", "12685": "鸡鸣咳嗽，痰多食少，病历多年，五日前吐血，动作气促。肺肾两亏，三焦俱伤，脉数形羸，虚劳已著。", "12686": "清金保肾，乙癸同源，已服六剂，结喉肿痛全消，弦数之脉已缓，每朝咳嗽痰多，声音不振，午后心烦，总属阴亏水不济火，原方加减。", "12687": "清上则肺不畏火之炎，实下则肾有生水之渐。肾水承制五火，肺金运行诸气，金水相生，喉之肿痛全消，胸中逆气已平，饮食亦进，夜来安寐。惟平明痰嗽犹存，脉仍微数，肺胃伤而未复，仍顾其本。", "12688": "脉滑而数，风伤肺。痰郁肺胃，夏令脉洪数。前月初诊，脉沉滑而数。沉者，阴也，郁也。滑者，阳也，痰也。数者，火也。邪伏化热生痰，所以用苏、杏、甘、桔开提，蒌、夏理肺胃，不治咳嗽而咳嗽自解，不治痰而痰自出。用梨汁、莱卜汁以调肺胃，展其气化，清肃渐行，咳少缓矣。", "12689": "脉细如丝，按之如无，中伤肺损。不能言语，语则喘咳不宁，足肿身热。谨防大汗阴阳脱离之变。", "12690": "脉来沉滑而疾，湿痰蕴结肺胃之间。痰嗽气促，胸次不爽，面色戴阳，肾亏子盗母气。暂以《外台》茯苓饮加减。", "12691": "脉来沉涩，推之则移，痰郁阴亏。肺气不展，久嗽不已，三焦俱伤，慎勿轻视。舒肺胃以展气机，现在火令司权，慎防音哑。", "12692": "脉来滑数，肺有郁痰。喘咳不安，口干神倦食减，恙久体虚不受补，极难奏效。", "12693": "咳嗽痰多，脉象濡弱，气虚痰郁，脾受湿侵，渍之于肺。", "12694": "久咳痰多，喉肿且痛而痒，耳鸣头眩，寤而不寐，饮食少进，脉来弦数，阴亏已极，水不上升，心火刑金，清肃不降，虑难奏捷。", "12695": "服地黄汤加味六剂，诸恙亦安，头目尚觉不清，夜来寐则易醒，喉间痛止痒存，微咳，饮食尚少，脉沉弦数。", "12696": "脉沉而小，按之颇不流利。外寒内热，久嗽不已，喉间淫淫作痒即咳，夜来少寐，胸满食减。", "12697": "肺合皮毛，主咳。《经》言皮毛受邪，邪气以从其合也。其饮食入胃，从脾脉上至于肺，则肺寒。肺寒则内外合，邪因而客之，则为肺咳。乘春则肝先受之。盖肺咳不已，传于他脏，际此发陈之令，则必先传于肝，当以和解法中佐以肃降之品。", "12698": "肝藏诸经之血，肺司百脉之气。水弱肝虚，火载血上。肺虚不能下荫于肾，肾虚子窃母气，下损于上，痰嗽带血。相火内寄于肝，君火动则相火随之，心有所思，神有所归，则梦遗之病见矣。有情精血易损，接以草木，声势必难相应，宜速屏除尘绊，恬淡虚无，水升火降，方克有济。", "12699": "金水亏残，龙雷震荡，载血妄行，上溢清窍。木扣金鸣为咳，肾虚水泛为痰。营卫乖违，往来寒热，脉来细数无神。数载屡发不已，虚劳之势已著。勉拟甘温壮水，以制阳光，不可过服沉寒，致戕生气。蓄瘀虽为阴类，运之者，其惟阳乎！", "12700": "年近四旬，幼年失血。今春举发，血虽止，痰嗽不已，平明尤甚，脉来滑数，痰多食少，阴伤子盗母气。现在溽暑流行，谨防狂吐。", "12701": "失血多年，早暮咳呛，交节尤甚。现在三四日一发，血发甚涌，胸次作胀，食少运迟。巅疼身热，脉来弦数，阴虚火载血上，木击金鸣为咳，不宜思虑劳心，当思静则生阴之理。", "12702": "《经》以大怒则形气绝，而血菀于上。郁结化火，火载血上，狂吐之后，咳嗽延今不已。十余日必遗泄，脉来弦数，水不养肝，木击金鸣，肝虚侮胃，久延非宜。", "12703": "年逾六旬，二气就衰，冬客风冷，咳嗽绵延不已。今春痰带红紫，夜不能寐，身痛气急，动劳尤甚，饮食少思，足跗浮肿，蔓延于上，阴分大亏，兼有湿热，脉来停止，土败金残，生气大损，虑难奏捷。拟补肾开胃法，胃开则吉。", "12704": "失血之脉，缓静为顺，洪大为逆。半产之后，二气素乱，血随气上，痰嗽带血，痰少血多，脉来弦洪，且大且数，血不养肝，肝不藏血，气冲血逆，致有妄行之患。所服之方甚可，奈时令肝木用事，气火上腾，慎防喘汗血脱，金残肺痿。", "12705": "素有失血之患，心营肺卫俱伤，近乃复感寒邪，已经表散未解，身热憎寒，短气自汗，痰嗽带血，声嘶脉软，正虚邪实，殊为棘手。", "12706": "昨服小柴胡汤加减，表邪已解。本症阴虚，曾经咳血，龙雷内炽，五液交枯，虚热往来，渴不欲饮，自汗不收，痰嗽带血，面色戴阳，声嘶脉软。所幸胃气尚存，犹虑复感寒邪，变生难治。用药大旨，迎夏至一阴来复，以滋金水之源。", "12707": "肝藏诸经之血，肺司百脉之气，肾为藏水之脏，水亏不能生木，木燥生火，载血上行。木击金鸣为咳，肾水上泛为痰。阴偏不足，阳往乘之，舌绛咽干，蒸热夜甚，脉来细数无神，虚劳已著。勉以壮水之主，以镇阳光。现在木火上升之令，慎防狂吐。", "12708": "思为脾志，心主藏神，神思过用，病所由来。心为君主之官，脾为后天之本，二经受病，五内心虚。水虚不能生木，木火载血上行，木击金鸣为咳。木乘土位，津液凝滞成痰，阴液不足以滋脏腑，二阳之病发自心脾。心烦意乱，形容枯槁，病魔不去，精神不生。辗转沉痼，岁月弥深，所服之方，却是法程。胃者卫之源，脾乃营之本，卫外失司则寒，营内失守则热。失位之血，离经远来则紫，吐后色红者，近血也，渐淡为痰，合而为一者，血迫近而未及化也。痰血本为同类，脏气盛则痰即化红，脏气衰则血即化痰。前论痰为精血所化，譬如乱世之贼盗，即治世之良民。舌上白苔，丹田有热也。足得血而能步，血少故难行。中州不运，食欲少思，内宫运动，心有循持。未吐血前，脉强而硬，既吐血后，脉弦而软，显系血从肝来，营弱心虚则口难言。血化为痰，吐出方快，时或思卧，土困于中，心肾不交，竟夕不寐。脉来时弦细而急，或凝滞若不能自还，此三五不调，近乎涩革，两关尤甚，又似劲脉。总之脉缓则平，脉急则甚。左右者，阴阳之道路。阴阳互相克制，脉亦左右偏强。脾属坤土，主治中央，最宜服食，土不制水，水溢高源，涎吐不禁，清气在下，则生飧泄。昔黄帝问于歧伯曰：形弊血尽而功不立者，神不使也。精神不振，志意不治，精坏神去，营卫不可复收。何者？嗜欲无功，而忧患不止。诚能屏除尘绊，恬淡虚无，补以药饵，何忧不已。", "12709": "血富于冲，所在皆是。赖络脉之堤防，从隧道以流注。久咳肺络受伤，血随咳上，鲜瘀不一，脉来浮数兼弦，症本阴亏，水不济火，火灼金伤，木击金鸣，清气不降，络有停瘀，未宜骤补。昔肯堂治失血之症，必先荡尽停瘀，然后培养。余宗其法，多酌高明。", "12710": "伤风致损，必是肾虚，咳嗽痰多，微带鲜血，耳鸣盗汗，脱肛不收，脉来虚数，下损于上，肺肾两亏。速远房帏，独居静养，真阴来复，方能有济。", "12711": "肺无因而不咳，络不伤血不出，客秋感冒，痰嗽食减，甚则呕吐，至今吐血甚多，鲜红可畏。今春又吐，较前略少，痰嗽益甚，夜不能寐，身痛肢木，血不荣筋，面色带黄，阳盛水不济火，肾虚窃气于金，精损移枯于肺，脉带数象，尤非所宜。", "12712": "三阴不足，酒湿内伤，下有漏疡，火载血上，痰嗽食少，便溏，舌绛中有槽，左胁有动气，脉来虚弦。法宜清补，仍防狂吐。", "12713": "暴怒伤阴，肝阳化火，载血上行，咳喘带红，脉来弦劲，法当清以降之。", "12714": "肝藏诸经之血，肺司百脉之气。失血后咳不止，气微促，食减，脉细数，由盛怒伤肾，水不济火，火载血上，木击金鸣。肾不纳，肺不降，故气促。前贤以诸端皆为危证，殊属不宜。拟方多酌高明。", "12715": "右脉弦而洪，左脉弦大而芤。水不养肝，肝不藏血，气逆血上，血不归络，冲犯阳明，致有狂吐之患。天下无逆流之水，水由乎风；人身无逆行之血，血由乎气。脉不安静，波涛不定，防其壅逆，慎之。", "12716": "上年失血，得于醉饱之后，全属胃病。今次失血，因嗽而起。夫咳血与呕血不同，咳因嗽起，呕是逆来。脉象左关右尺洪而有力，余部细数。阴分素亏，交春生之气，龙雷鼓动，故不时头烘面热，耳鸣咳呛，误视头风，竟以辛温升散，致阳火独狂，冲破血脉，咳吐两昼夜未宁止。用犀角地黄，清心解热，未能制及龙雷。鄙意大剂育阴，兼以苦降之法，必得龙藏泽中，雷潜海底，方可向安。", "12717": "女子以肝为先天，盖肝藏血，且为血海，又当冲脉，此汪讱庵创论，实千古之确论也。肝藏血，情怀不遂，气动于中。人身气血，譬如权衡，一胜则一负，气旺则阴愈伤，阴伤而络血不注冲脉，此月事稀少所由来也。既肝无血养，而肝木愈燥，则化气化火。气火妄动，则血络不安，两胁或胀或痛。离经之血，必赖雷火以上升，由肺胃而出，咯呕夹红，止后觉头眩心悸，津津汗出。心主血，汗为心液，液耗阴伤，故精神萎顿，肢面虚浮，下体气坠，眼皮倦于开阖。木旺则土衰，脾失转输，清阳下陷，不能达于肢腠，故见症若此。刻当先养心脾，兼柔肝木，后议乙癸同源之法。鄙见如斯，敢质明眼。", "12718": "长夏失血，肺肾两伤，金水交亏，龙雷震荡，五液神魄之病生焉。神情恍惚，语言错乱，阴络内伤，云门卒痛，阳𫏋脉盛，竟夕无眠。脉象虚弦，殊难奏捷。壮水之主，以制阳光，是其大法。仍请原手调治，何必多歧。现在火令司权，远涉就诊，非其所宜。", "12719": "暮春风温上受，发热三日，吐血鲜红，四月中旬，血又涌来，至今不止，胸胁相引而痛，是系肝胃不和。胃为多血之腑，肝为藏血之赃，肝阴少藏，胃血上涌，脉来洪滑，非其所宜。", "12720": "三进真武汤，血上痛除，惟夹脊膂筋酸楚，左手大拇指乍寒乍热，督脉少运，仍防血逆上涌。", "12721": "足阳明脉，起于鼻，挟口环唇。盖鼻准属脾土，鼻孔属肺金，而胃统之。产后口鼻起黑色而衄，乃瘀血入肺，肺绝胃败之候也。急拟二味参苏加附子治之。", "12722": "操劳过度，真阴不足，水不制火，冲任血动，上溢于鼻，名曰外衄。脉来细弱无神，自述素耽酒色，法当培补真阴，未可作火热论治。", "12723": "素本阴精不足，疟后阴液大伤，阴亏阳亢，水不济火，逼血妄行，出于肺窍。肺主百脉之气，肝藏诸经之血。肾使一身之精。水虚无以制火，精虚不能化气，火性炎上，血随气行，是以血溢于肺窍，有喘促痉厥之虑。脉来软数无神，治宜壮水之主，与六淫在经邪热壅盛有间。", "12724": "阴虚火动，齿衄消渴，脉来浮滑，神倦气怯，大便坚，小便数。当从阳明有余，少阴不足论治。", "12725": "齿者骨之所络也，齿衄动摇，并无火证火脉可据。乃肾阴不固，虚火上升，宜壮水以制之。", "12726": "《经》曰中焦受气取汁，变化而赤，谓之血。出于中焦，而主于心，故五脏各有守经之血，而六腑则无矣。其散于脉内者，随冲任二经遍行经络，散在脉外者，充溢于肌腠皮肤之间。凡吐血衄血、牙龈齿缝出血，散在经络之血，涌而上决者也。近人谓巨口失红，及牙龈缝出血者为胃血，此说误人不浅。盖胃为外腑，职司出纳，为水谷蓄泄之区，其中并无一点一丝之血，夹杂内中，即牙宣出血一症，亦不过胃热炽甚，肉不附骨，故血热而上涌，其牙不宣而出血者，乃阴竭于下，阳亢于上，龙雷之火冲激胃络。钱氏所谓骨漏是也。恙起于一月之前，齿缝出血，牙并不宣，多则血流盈盏，昼夜十余作，发时面赤目赤，烦扰不安，近虽小愈，而漏不已。脉本六阳，刻下见症在胃，而所以致病，实由肝肾。急宜珍珠母丸合玉女煎加减，俾龙得下潜，然后阳明方有宁宇。", "12727": "饮食不入谓之格，二便不出谓之关。阴阳有所偏乘，尺寸为之复溢，气口脉浮大，上引结喉之人迎。吐逆不能食，大便兼旬不解，小便如癃闭，阳明胃液就枯。化火金伤，治节不行，阴阳不相营运，幽门失其启闭。气化不及州都，关津不利，乃三阳将结之危疴也。", "12728": "生脉散加生地山药萸肉牛乳", "12729": "气痰作阻，食不能下，关津不利，便不能解，中州失运，升降失司，乃高年之逆候也。生脉散加生地怀药制半夏广皮白蜜。", "12730": "酒入于胃，肝浮胆横。暴怒伤阴，暴喜伤阳。木乘土位，火灼金伤，金令不肃，州都气化失常，治节不行，传道之官失职，大便结如羊粪，小便不利如淋。诸逆冲上，皆属于火，体战心惊，火之象也。食不能下，人迎脉盛，病在阳明，阳明腑火上炎，少阴脏水耗竭，无以濡润诸经，一任三阳转结，《经》以一阳发病，其传为隔是也。虑难奏捷，勉拟清上实下法挽之。", "12731": "归脾六君，助坤顺，法干健，理阴神，益肾命，畅中阳。共服十有三剂，食入阻碍已平，呕吐痰涎亦止，胸次之痛大减，弦数之脉亦缓。症本火亏于下，土困于中，津液凝结成痰，蕴结不行，气为之阻，遂致三阳将结。前方既获效机，略为加减，为丸缓治。第胸次云门穴痛未除，乃营液欲竭，终属不宜。", "12732": "脉来洪数，气郁填胸，汨汨有声，隐隐作痛，食不能入，二便俱阻。长沙以小便不出谓之关，饮食不入谓之格，阴阳偏胜谓之逆。虑难奏捷。", "12733": "郁怒伤肝，忧思伤脾，肝脾荣损，气亘于中，贲门不利，食入作梗，痰多，干物难下，脉弦，左关沉涩，中枯症也。拟养胃和中，兼柔肝木。", "12734": "夫张机峰之论噎膈也，其言曰：此病是神思之病，法当内观静养，方为得旨。盖百病之因，多兼六淫而成，噎膈则以七情所致。由于饮食者，亦间有之。治症之法，无非开胃止吐，养阴润燥之方。然病在神思，所谓心病还须心药。内者，外之对。此症向来事外忘内，未尝收拾此心，或为利锁名缰，或为酒沉色困，以致五脏空虚，气无所主，食不能进，入亦反出。若不垂帘反照，及忙里偷闲，浓中著淡，何由屏绝诸魔？夫是之谓内观。静者，动之对。此症向来多动少静，未能恬逸此心，微是诱于大喜大怒，而致伤神伤肝，即被牵于劳思过扰，而致伤脾伤肾，致五火丛起，血无由生，胃脘干枯，大肠结燥。务须安养休息，即僻山深林，只称隐逸，宁静有志，虽车轰马骤，亦是心清。夫是之谓静。守此二者，则噎膈可通，即饮食可进，逆自平而呕吐可止，燥自润而血自可生，结自开而二便自利。左脉结涩，右脉弦小，中伤肺损，扰内无权，阴阳两败，药难为力。回府当以血肉有情之品，养生生之气，每日服人乳、牛乳皆可。", "12735": "怒则气上，思则气结，脉沉弦而滑，肝郁中伤，胃失冲和，气血作阻，机关不利之象。呃逆不容饮食，三阳结也。怡情开怀为妙。", "12736": "脉来两关弦细，肝气犯胃，胸咽梗痛，有如刀割，势成隔疾。", "12737": "清阳不升，浊阴不降，左胁盘踞，此肝积名曰肥气。肝属木，木克土，故肥气久而脾土必亏。脾为生化之源，源竭而肝木愈旺，上刑肺金，致有咳呛咯血之患。热移于脑，则鼻流浊涕。东垣云：痞满皆血症也，谓脾胃水谷之阴伤也。心主血，心虚则嘈杂似饥，故得食则安；肝藏血，肝虚则阴伏于阳，皆气血不运而成，即虚转实也。若用气药破之，虽取快一时，贻忧日后，痞气坚而阴愈伤矣。攻之愈急，必变中满，脉象虚数，而脾胃之阴宜养，营分宜调。参以乙癸同源，为法中之法。正气足，积自除；不治痞，而痞自消矣。", "12738": "肝积曰肥气，在左胁下，恙起前年，疟后肝邪未尽，口腹未谨，邪与痰滞，互结络中。春夏以来，渐觉硬大，客秋时感病后，脾胃虽强，而脾阳困顿，土衰木旺，肝邪愈强，积益散大，硬及腹右，食后觉饱，虑成蛊病。脉象左部细弦，右部兼滑，每遇烦劳，气逆耳鸣，心肾荣亏，肝阳上僭。法当扶土抑木，兼和荣泄浊之法。候裁。", "12739": "郁怒伤肝，肝营亏虚，气从中逆，阳之浊痰，借以上升，始则胸胁痛胀，走窜无定；继则脐下关元气海梗痛，二便不爽。此肝木横逆，始则上行，继则下克脾脏，于是清不能升，浊不能降，常似喘促，喉间有痰，或上或下。舌白中致滑腻，脉来沉涩软弱，正气已伤。拟养血柔肝，兼和中化浊之法。", "12740": "左脉沉弦不静，右脉滑数，肝郁不畅，气不条达，气聚为瘕，任脉为病，肝脉为患。肝脾皆伤，不宜忧虑郁结。月事不调，常多白带。议养心脾，和肝胃。归脾汤去耆，加金橘皮。", "12741": "胃阳衰微，阴寒凝结，嗳噫吞酸，胸痞不饥不食，脉来细数，非食停中脘，乃阳气不升作滞，是阴翳也。议理中主治。", "12742": "思虑伤脾，脾虚不运，痞塞不开，不饥不食，脉体弦多胃少，法当补肾温脾。《经》有塞因塞用之例。", "12743": "饮食有节，起居有常。饮食起居，均失其宜，脾胃伤而不运。一月以来，不饥不食，胸次痞满，脉形缓弱，升降失司，否而不泰。法当补脾肾，运中州，以展清阳为主。", "12744": "嗳腐吞酸，胸痞不食，寒滞中焦，脾阳不运，脉来小𫘝于迟，法当温暖中土。", "12745": "塞而不开谓之痞，胀而不行谓之满，有邪滞为实，无邪滞为虚。今胸脘无胀痛邪滞等证，但不饥不食，而自疑若满。脉来缓弱，容色萧然，气痞于中，中阳不健，非消导所宜。拟塞因塞用法。", "12746": "三经受感，病后绝不思食，时或知饥，食入则痞，调治半年方痊。近因忧劳太过，复不能食，脾胃为中土之脏，仓廪之官，赖肾火以生，火素不足，中州不振，胃虚卫不外护则寒，脾虚营失内守则热，非外感可比。脉来胃少弦多，原当益火生土，现在春木上升，宜先培土崇木。拟治中汤加附子。", "12747": "胸腹乃脏腑之部，膻中为阳气之海。胸次痞塞不开，按之有形，如心积伏梁之状。饮食减少，脉来细数，素来木不条达，中虚清气不展，离光不振，阴霾上翳，审以高年，非佳兆也。", "12748": "年甫十五，经水未通，小腹右角有形，大如复杯，痛如针刺，痛时其形反隐伏不见。盖积居膜原之间，如气血源流冲击，暂离窠臼，潜行于里。小便不利，且痛如淋证之状，积瘀壅塞膀胱。《经》以膀胱为州都之官，津液藏焉，气化则能出矣。州都气化失常，故小便如淋证之状，非淋证也。胸次气血，往来不畅，肺司百脉之气，为水之上源，下流不通，上流壅塞，气不化液，无水通调，水道郁而不伸，非喘促可比。扁鹊云：积者五脏所生，聚者六腑所成。脉来细数兼弦，证本先天元阴不足，水不涵木，木乘土位，健运失常，致令血液精华，不归正化，凝结于脏腑之外，隔膜之间，少腹厥阴肝木之部，症名肥气。当从养正除积论治，暂拟交加散加味，观其进退。", "12749": "复诊饮食较进，呕吐亦退，腹内知饥，饥不欲食，食入即胀，得后与气，则快然如衰。此胃阳未复，脾阴亦亏，脉来胃少弦多，爰以归脾汤加减。", "12750": "肾乃先天纳气藏精之穴，脾属后天资生化育之枢。先天精亏，频年产育过多，水枯木燥，肝木转取汲于胃，胃取汲于脾，脾胃输津液于肝，久则不能相继，而反为木克矣。滋水清肝，补精纳气，实为正治。故滋阴清降，似乎有效，后天薄弱者，滋降岂能久服。今拟欲求稳当，莫如滋水涵木，扶土柔肝，则先天后天，皆得其治，土气不为木制矣。据愚见，治病用药，须要中正和平，方能胃气无损，倘胃气一虚，则五脏无养，诸病蜂起。故曰：胃气治，则诸病不生，胃气弱，则诸邪辐凑是也。苦辛降逆，只可暂制肝气之怒盛，呕止痛平，即宜补肾和胃，方无掣肘之弊。脉来沉弦涩兼，由肝郁不舒，少腹痛，气逆直冲于胃，气不下趋，反胃之症，宜和中抑木法。", "12751": "抑郁不舒，土衰木团，食入即呕，脉左寸关数，肝木乘土，急宜清降。", "12752": "脉来六部弦劲，朝食暮吐，完谷不化。", "12753": "蛔厥作痛，呕泻俱出，皆缘平素劳郁，多怒伤肝，思虑伤脾，脾气日损，胃气日亏，饮食少进，遂致湿蒸热郁生虫。脉来弦数。乌梅汤加味。", "12754": "脉来弦细少神，气血已衰，食少胸腹作痛，有时呕涎，脾胃两败，和中合养营治法。", "12755": "脏气实者，虫无以生，虫之生者，脏气虚也。症本肾虚于下，木失敷荣，木乘土位，脾困于中，湿蕴生热，化生蛔虫，虫食脂膏，痛如锥刺，时作时止，脉反浮洪，痛甚颜青唇赤，是虫之明验也。治宜固肾扶土为主，追虫渗湿佐之。", "12756": "肝邪横逆，胸膺胀痛，呕吐苦酸，兼吐蛔虫。病缘胃虚趁嗜而出，理中安蛔，参入左金疏肝。前年经治以愈，今因半产早劳，兼之平素多郁，最伤脾胃，胃虚肝乘，纳食则呕，脘中板硬如拳，是中虚气滞凝结。诊脉沉细，形神皆衰，棘手重症，勉方候酌。", "12757": "脉象沉弦，气郁肝伤，土为木侮。肝病善痛，已历多年，不耐烦劳，形容憔悴，血不华色，心脾营损。养心脾以和肝胃。", "12758": "腹痛已平，饮食已进，夜来安寐，脉形神色俱起，不宜烦劳动怒，原方加减。", "12759": "肝郁乘脾，中伤气痛，饮食少进，食入则吐，脉来细数无神，久延有虚劳之虑。《经》以怒为肝志，木郁达之。然草木功能，难与性情争胜，使悲怒不戒，终无济也。", "12760": "病原已载前方。第脘痛甚则发寒，肢尖面目不可以当风，此属气闭不能营敷四末，上走清空，非真虚也。服理气之剂，佐以山栀清气郁之火，病势随愈，呕吐亦平，饮食亦进，脉数亦缓。症本木乘土位，中伤气郁，化火伤阴。不宜烦劳动怒。肝病治脾，前医良法。拟六君加减。运中枢以畅清阳为主。孩儿参茯苓白术炙草橘红青皮木香沉香佩兰当归白芍远志蜜水为丸", "12761": "痰嗽稍平，脘痛复作，按之则痛缓，可缓为虚也。《经》以脾络布于胸中，肺脉环循胃口。症本木旺中虚，土不生金，风伏于肺，气机不展，痛则不通，不可拘肝无补法之说。通则不痛，通者、宣和也，非必通利也，补亦可通也。益水生木，培土生金，展气化，宣伏风主治。", "12762": "服丸徐治，入冬以来，脘痛时作时止，痰嗽或减或增，饮食较进，细数之脉未起。肺胃双亏，伏风未尽，肾病当愈于冬，自得其位而起，不愈者，以水旺于冬，而冬水反涸，得润下之金体，而少升生之气故也。水冷金寒，肺有伏风，外风易感，同气相求也。必使里气融和，方克有济，暂从温散。", "12763": "乙丑五月，诊脉仍细数，素本阴亏，木不条达，克制中胃。中伤络损，气失冲和，肝郁则痛，胃伤则呕。阳明之气，下行为顺，太阴之气，上升则和。《经》以六经为川，肠胃为海，以通为主。五六日一更衣，阴液不濡，肠胃燥结可知。香燥开胃，非所宜也。当润燥生阴，佐和中胃。", "12764": "丙寅二月诊脉细数如初，饮食较前略进，形神渐振，痛呕并作，举发渐稀。症本阴亏不敛，克制中胃，胃不冲和，传化失职，津凝为饮，液结成痰。肝为起痛之源，胃为传病之所。脾络布于胸中，肺脉环循胃口。中虚清气不展，阴霾上翳，否象呈焉。七方中甘缓最为妥协，服三五剂后，仍以甲子所拟丸方调治。", "12765": "肝阴不敛，肾阴不滋，健运失常，中伤饮聚，痛呕并见，屡发不瘳。肾伤窃气于肺，肝病必传于脾，肾气通于胃脾，络布于胸，络脉通调则不痛，胃气强健则无痰。治病必求其本，滋苗必灌其根。如不培养真元，徒以痛无补法，执定呆理，安望成功？数载以来，病势退而复进，脉体和而又否者，病势深而少静定之力也。盖阴无骤补之法，且草木功能，难与性情争胜。金为水母，水出高源，谨拟补肾生阴为主，清金益肺辅之。俾金水相生，从虚则补母之法，乃经旨化裁之妙，非杜撰也。", "12766": "气虚不能传送，液耗不能濡润。气主煦之，血主濡之。肾司二阴，胃司九窃，肾水承制五火，肺金运行诸气。气液不足濡润。肝阳木旺，中伤转输失职，血燥液干，故大便不解，痛呕不舒，通夕不寐。拟生脉散，行肺金之治节，滋肾水之源流，冀其清肃令行，肝胃自治。症不拘方，因人而使，运用之妙，存乎一心。公议如是，敬呈钧鉴。", "12767": "生脉散加白蜜", "12768": "昨进生脉散，夜得少寐。今仍痛呕。虽体气素旺，然病将三月之久，脾胃已困，肝阳独旺。肝在声为呼，胃气愈逆，不能饮食，转输愈钝，大便不行。肝为刚脏，非柔不和，胃为仓廪，非谷不养。肝气郁极化火，火灼阴液为痰，痰凝气结，幻生实象，非食积壅滞可下也。公议仍以生脉散合大半夏汤。", "12769": "痛呕不止，饮食不进，大便不解，总由水不济火，火灼液耗，两阳合明之气，未能和洽，故上不入，下不出，中脘呕不舒也。此时惟宜壮水清金，两和肝胃。木欲实，金以平之，肝苦急，甘以缓之。水能生木，土能安木，肝和则胃开纳谷，胃开则安寐便解，此不治痛，不通便，而通便止痛之法在其中矣。仍以生脉散合《金匮》大半夏汤，加甘麦大枣法。", "12770": "六味合生脉散加黑枣黄粟米蜜甘澜水煎", "12771": "六味合生脉散加牛膝", "12772": "冲任并损，脾肾两亏，壮年产育过多，精血不足营养心脾，心脉循胸出胁，肝虚不能为胃行其津液，凝滞成痰，随气流行，乘虚而进，先犯心脾之络，是以胃脘当心而痛，横侵胁肋，攻冲背膂，膨胀有声，时作时止，乃痰饮之征。夫气血犹源泉也，盛则流畅，畅则流通，少则凝涩则不通，不通则痛。无急暴之势，惟连绵不已，虚病不卜可知。用药大旨，培补脾肾，以资冲任精血之本，宣通脉络，以治痰饮之标。拟丹溪白螺丸，合景岳大营煎加减。", "12773": "大营煎以养血，白螺丸之祛痰。营血渐生，宿痰渐化，脉络通调，病何由作？精血充满，痰无以生。痛止年余，近又复作，此精血未能充满，痰饮犹存，蔽障经中，气为之阻。自述痛时小溲如淋，乃痰隔中州，升降失司之据。养阴宣络，古之成法，药合机宜，原方增减。", "12774": "胃脘当心而痛，痛则水泻，脉滑而弦，舌有黄苔，胸次不舒，不思饮食，积食停饮阻隔，阴阳升降失司。和气平胃，以展清阳主治。", "12775": "客秋脘痛，心中愦愦莫能自主，服黄连二剂稍好。现在大痛不止，痛时胸次气郁如焚，贯膈冲咽，痰塞咽喉，咯咽不去，午后尤甚。头眩形神不振，饮食少进，脉来弦数，五志不伸，肝火犯中，土为木侮，以苦泄辛开法调之。左金戊己本好，先以泻心法，服后再议。", "12776": "年甫廿三，胃痛八载，呕吐吞酸，脉象沉潜无力。中阳不健，胃寒积饮，拟苓桂术甘汤加味。", "12777": "脉滑数，小腹痛如针刺，大便坚，溲混赤，火郁下焦，法宜清利。", "12778": "脉滑数，脘痛横连胁肋，昼轻夜重。此为痰郁，宜苦泄之。第经日不食，气馁于中，不胜涌吐，暂以失笑散加味。", "12779": "脉来洪数而弦，少腹痛连胸背，虚烦自汗，食入作吐，溲赤不利，便黄有沫。《内经》「痛论」十三条，寒居十一，惟二便不爽属热。今上则呕吐不安，下则二便不利，此二阳之火，蕴结不开，值经血适来，血为热所搏结，厥阴脉络愈壅，诸逆冲上，皆属于火，故食不得入。诸汗属阳明，心烦由血热。法当清理肠胃之火，直行下焦瘀血。", "12780": "昨投药后，诸症轻减。惟少腹胀痛不舒，夜来无寐，水不制火，阳跷脉盛，阴不上承，心阳独旺，血为热所搏结不行，经水适来，热入血室。议壮水补阴为急，行血逐瘀为缓。", "12781": "木乘土位，转化失常，清阳不升，浊阴不降，升降失司，否而不泰。脘痛如刺，呕吐痰涎，不思食物，脉来软数，已历多年，正气已亏，殊难奏效。拟补气法加补正品。", "12782": "阴虚于下，肾不养肝，木乘土位，健运失常，不能营运精微，二气源流不畅，痛则不通，是以痛呕不能纳谷。延今四载有余，春末夏初举发。今年发生在冬时，脘痛如刺，呕吐不食，呻吟不绝，几致汗脱，延绵四十余日，服药痛呕虽平，饮食难进，脉仍未起，虑其来复。以丸代煎，徐徐培养。", "12783": "胁痛本属肝胆，二经之脉，皆循胁肋。素本忧劳，忧伤肺志，劳动心阳，心肺伤而肝郁。法当宣补，未可以东方气实，宜疏散治。", "12784": "暴怒伤肝，木火载血妄行清窍，胁肋胀痛，烦热脉洪。宜先泻东方之实，兼助中央之土，以杜传脾之患。", "12785": "肝胆之脉，循乎胁肋。忧思过度，致伤心脾，气血不能流贯，致令厥、少二经不利，心脉亦循胸出胁。脾伤故木不安，是以胁肋隐痛。宜先培补心脾，治其致病之源", "12786": "腰为肾府，痛属肾虚，与膀胱相为表里。太阳挟脊抵腰，督、带、冲、任，皆会于此。素沉酒色，肾阴本亏，恬不知养，僭伤血脉。痛起于渐，屡发不瘳，辗转沉痼，岁月弥深，行立不支，卧息稍缓。暴病为实，久病为虚，在经属腑，在脏属肾。每晚服青娥丸三钱。", "12787": "《经》以任脉为病，男于内结七疝。冲任同源，为十二经脉之海，起于肾下，出于气街，并足阳明经，夹脐上行，至胸中而散。症因思虑烦劳，损伤中气，亏及奇经。任虚则失其担任之职，冲虚则血少不能营筋。肝主一身之筋，与肾同归一体，前阴为宗筋之会，会于气街，以故睪丸下坠，不知痛痒，名曰𤻊疝。前哲之法颇多，效者甚鲜。暂从中治。", "12788": "二天不振，八脉有亏，任脉不足，睪丸下坠。偏于左者，肝位也。肾气通于耳，水不济火则耳鸣，火炽阴削则精泄。脉来虚数少神，脾肾双培为主。", "12789": "疝气三载，脉弦兼滑。《经》以任脉为病，内结七疝，大如鸡卵，囊大如瓜，满腹攻痛，劳则胀大作坠，肝肾不足，中气亦虚。劳者温之，损者益之。", "12790": "久嗽不已，脉弱形癯，两足环跳穴按之则痛，不能步履。《经》曰：肺热叶焦，则生痿躄。肺为华盖，司气化而主皮毛，譬如天之雨露不施，则万物不生，树之剥肤亡液，则枝叶必槁也。若惟知壮筋骨而治腰膝，失其旨矣。下病治上，则宜滋养肺金。", "12791": "正在壮年，三阴不足，阴寒湿邪，乘虚陷入下焦，两足胫骨肿胀，腿膝酸疼，大肉渐瘦，脉象弦细微数，神疲食少，面目痿黄，气血俱亏，虑成残废。宜平补三阴，兼利湿舒络之品，缓缓调治。", "12792": "脉象比昨较静，惟是弦细，细为阴亏，弦为血少。肝肾血液不足，莫能流贯络中，腿足酸痛乏力，或轻或剧者，虚则善变也。拟以三阴进治。", "12793": "腿有六经，内前廉属肝脾之络。筋脉扎起，屈伸则痛，酸楚乏力，筋无血养，络湿不清，即系夏令，犹须棉护，显属虚寒。法当温养。", "12794": "大渴引饮，舌裂唇焦，火灼金伤，津液枯涸，能食脉软，此属上消，亦名膈消。谨防发背。白虎加人参汤。", "12795": "消渴已止，眠食俱安。痰嗽未平，胸腹仍胀，乃木火余威，木击金鸣，火灼金伤故也。曾经产后，经前作痛，于兹七载，尚未妊育，女子八脉有亏。现在经闭二月有余，脉象细数无力，非胎候也。有虚劳之虑。宜静补其阴。", "12796": "脉来软数无力，症本阴液有亏，五志过极，俱从火化，万物遇火则消，必先荡涤积热，然后补阴，否则得补而愈炽。服泻心汤五剂，火势已杀，宜补真阴。", "12797": "思为脾志，心主藏神，神思过用，病所由生。心为君主之官，端拱无为，相火代心司职，曲运神机，摇动相火，载血上行，下为遗泄。因循怠治，病势转深，更增虚阳上越，眩晕等症。诸风掉眩，皆属于肝，面色戴阳，肾虚故也。不能久立久坐者，肝主筋，肾主骨，不足以滋养筋骨也，眼花耳鸣者，肾气通于耳，肝开窍于目，水弱不能上升于耳，血少不能归明于目也。胸背间隐痛如裂者，二气无能流贯，脉络不通也。呕吐黄绿水者，肝色青，脾色黄，青黄合色则绿，乃木乘土位之征也。前阴为宗筋之会，会于气街，而阳明为之长，心脾不足，冲脉不充，宗筋不振，阴缩不兴。滋阴降火，苦坚之法，最是良谋。惜少以通济塞之品，以故无效。不受温补热塞之剂者，盖壮年非相火真衰，乃抑郁致火不宣扬。膻中阴瞑，离火不振也。相火不足，治宜益火之源，以消阴翳。相火不宣，则宜斡旋中气，以畅诸经。譬如盛火蔽障，微透风，则翕然而起矣。", "12798": "《经》云：肾主藏精，受五脏六腑之精而藏之，不独专主于肾也，当察四属，以求其旨。吟诵不倦，深霄不寐，寐则梦遗，形神日羸，饮食少思，脉来细数，此属血耗心虚，神不摄精，水不济火，肾不交心，非郁思不遂者可比。心不受病，当从厥阴胞络论治。", "12799": "年甫廿四，两天皆虚，纳谷不丰。去冬劳感咳嗽愈后，频频走泄，或有梦，或无梦，有梦治心，无梦治肾。有时心悸，体倦食少，劳心耗肾，心肾两亏，脉不宁静，心相火旺。阴虚精遗于下，阳虚热冒于上，心肾不交，水不济火。暂宜变化地黄汤。", "12800": "脉象虚数，两天不足，水亏于下，火炎于上，午后渴饮，肺胃阴伤，大便结，小便频，常多梦泄，能食不能充养形骸，壮其气血，水不济火，谨防消渴而变三阳结病。速当息虑宁神，撇去尘绊，静养调摄，水升火降，心得太和之气，服药方克有济。", "12801": "肺司百脉之气，肾纳五内之精。肺肾俱亏，精气不相营运，精不化气，气不归精，无故精滑，自不能禁。脉来软数无力，法当温固三阴，议丹溪九龙丸加参术。", "12802": "脉来软数无神，症本脏阴有亏。阴亏有二：有阴中之水亏，有阴中之火亏。少年真阴不固，真阳失守，肾兼水火之司。水不生木，肝病传脾，土不生金，脾伤及肺。《经》以中气不足，溲便为之变。肾开窍于二阴，肾虚则水反为湿，脾虚则土不制水，小水如膏如淋，非浊可比。宗气无根，虚里穴动。肾为先天，脾为后天，脾土之健运，赖肾水之充盈，肾中水火不能上蒸，中土何由健运，中虚不能交通心肾。", "12803": "劳心耗肾，肝不藏血，血不化精，精不化气，湿热伤阴，心火下注。溺血者，则血去不痛，有痛乃赤淋也。癃闭亦能溺血，三焦为决渎之官，水道出焉，气化则能出矣。脉来涩象，气化无权，火掩精窍，血阻溺窍。所用之方，尚在理路。", "12804": "水泉不止者，膀胱不藏也。小便频数，脉来虚数，心火下注，气结阑门，由癃而变淋，火掩精窍，已服多方，先效后不效。气虚阴亏，二便齐下，约束无权。宜清心保肾。", "12805": "血淋载余，溺管疼痛，始因苦寒伤胃，继又温补，咳嗽有痰，形神日羸，饮食日少，皮肤发热，下损于上，损及于中。脉来弦象，肾之阴亏，肝之阳强，三焦俱伤，殊属可虑。商政。", "12806": "阳明多气多血，大肠本无血，肝藏诸经之血，赖脾以统之，中气摄之。气不摄血，渗入大肠而下。血不养肝，肝不藏血，不能受孕者，血海空虚也。生产之后，血不归经，气不归窟，形丰脉虚，外强中干。养心脾，以和肝胃。", "12807": "络伤便血，历十余年。精神不振，肝气病痛，心虚气短，不相接续，阳事痿顿，年甫四二，未老先衰。脉来虚软，右关弦滑，中虚肾肝胃气皆虚，阴阳并损，从阳引阴，从阴引阳，大封大固，是其法程。第营出中焦，资生于胃，阳根于地，气根于肾，当从心脾进步。精血生于谷食，脾胃振作，为资生化源之本，不必寝事于阳，见血投凉。拟黑归脾汤加减。然否？明眼裁之。", "12808": "便后血，乃远血也。血色鲜红，肛脱半时乃上，已十余年。头眩神倦，脉来软数，肾水不足，肝阴少藏，脾少统司，气无摄纳，从乎中治。议归脾举元。", "12809": "脉滑数，酒湿伤阴，肠风便血。", "12810": "便血数年，先后不一，红紫相间，中带红块，腹中隐痛，脉来滑数，按之无力。三阴内亏，湿热不化，阴络受伤，脾不统血，气不摄血，渗入大肠而下。", "12811": "《经》以中焦取汁，变化而赤，是谓血。劳损中伤，化机衰惫，注泄下行，其色如赭。脉来细数，此阳败于阴，真元几脱之象。拟回阳之法。多酌明哲。", "12812": "便血已历多年，近乃肤胀腹大，脉沉潜无力，绝不思食，脾肾两亏，生阳不布，水溢则肿，气凝则胀。心开窍于耳，肾之所司，耳闭绝无闻者，肾气欲脱，不能上承心也。勉拟一方，以尽人力。", "12813": "脉来浮数而空，尺部独减，症本心脾气馁，脾肾阴虚，血失统司，水不制火，血注后阴，鲜瘀不定，便前便后俱有，远近之血交流，脉络不能摄固，血滑气脱，殊为棘手。", "12814": "《经》以肾开窍于二阴，主五液而司开阖。饮食于胃，津液输于脾，归于肺，注于膀胱，是为糟粕。转入小肠，传送大肠，出于广肠，是为大便。其中酝酿氤氲之气，化生精微，滋润五脏，营养百骸，盖大肠传送，赖相傅为之斡旋。故肺与大肠相为表里，肺为相傅之官，治节出焉。肾之津液，赖州都为之藏蓄，故肾与膀胱相为表里。膀胱为州都之官，津液藏焉。小溲多而大便结，正与大肠泄、小肠秘，同归一体。便泻溲秘，乃清浊相混，溲多便结，乃清浊不分，过犹不及。脉来软数无神，尺部尤甚，症本阴亏，水不制火，火灼阴伤，寒热如疟，注泄之后，五液干耗，肺不清肃，无由下降，致令开阖失司，传送失职，州都津液少藏，故大便秘而小便数。所服之方极是。拟清上实下主治。清上则肺无畏火之类，实下则肾有生水之渐，冀其金水相生，肺肾相资，清归于肺，润回于肾，则大肠无燥闭之患矣。愚见云然，未识高明以为是否。", "12815": "清气在下，则生飧泄，浊气在上，则生䐜胀，肝脉循于两胁，脾脉布于胸中，肝实胁胀，脾虚腹满，木乘土位，食少运迟，营卫不和，寒热往来，补中益气，是其法程。更兼以涩固胃关之品，冀效。", "12816": "阳气者，若天与日，失其所则折寿而不彰。故天运当以日光明。人与天地相参，与日月相应。膻中为阳气之海，生化著于神明，命门为阳气之根，长养由于中土，故曰君火以明，相火以位。明即位之光，位即明之质。症本相火之亏，不能生土，土虚无以生金。肺司百脉之气，脾乃生化之本，肾开窍于二阴，相火不振，膻中阴瞑，脾失斡旋，肺失治节，中土困于阴湿，乌能敷布诸经。湿甚则濡泄，注于二阴，是以大便溏薄，小水频数，虚症蜂起。譬如久雨淋漓，土为水浸，防堤溃决，庶物乖违。益火之本，以消阴翳，离照当空，化生万物，阴平阳秘，精神乃治。", "12817": "曾经洞泄，又值大产，脾肾双亏，《经》以肾乃胃之关，清气在下，则生飧泄。脾虚则清气不升，肾虚则胃关不固，是以洞泄日增，近复完谷不化。脾主远化属土，赖火以生，火虚不能生土，土虚不能运化精微，胃能容纳，脾不健运，肾火不足可知。脉来细弱无神，有血枯经闭之虑。治当益火之源，以消阴翳。", "12818": "脾统诸经之血，肾司五内之精。曾经三次血崩，七胎半产，脾肾双亏。脾与胃脂膜相连，为中土之藏，仓廪之官，容受水谷，有坤顺之德，化生气血，有干健之功。中土受亏，化机失职，清不能升，浊无由降，乃生呕吐吞酸，肠鸣飧泄等症。乘肾之虚，戊邪传癸，遂成肠澼，肾气不支，澼势危殆，昼夜无度，五色相兼，呕哕大汗，绝食神迷。自服热涩之剂，正合《局方》之理，是以获愈，未能如故。脾肾双亏，肾兼水火之司，火虚不能生土，水虚盗气于金，脾土乃肺金之母，大肠与肺相为表里，辛金上虚，庚金失摄，土虚不能胜湿，肾虚胃关不固，且南方卑湿，脾土常亏，既失所生，又素不足，土弱金残，湿胜泻泄，是以每至夏令，则必泄泻。《经》所谓长夏善病洞泄寒中是矣。经旨为常人立论，尚且洞泄，而况脾胃久亏者乎。是以泻后诸症蜂起，自与众殊。所幸年当少壮，能受峻补，病势一退，精神如故。然峻补之剂，仅可使愈，未能杜源。近复三月，或五志不和，饮食失宜，泄泻吞酸，不寐、怔忡、惊悸等症立起，即以峻补之剂，投之立愈，已而复发，反复相仍，于兹四载。今年六月间，因忧劳病发，仍以前法治之而已。第药入则减，药过依然，洞泄日加，虚症蜂起，怔忡惊悸，莫能自主，𪱥响腹胀，竟夜无眠，呕吐吞酸，时时欲便，非便即泻，泻则虚不能支，欲便能忍，忍则数日方解，精神日败。盖肾主藏精，开窍于二阴，泻则阴精不固，所以精不化气，气不归精，相火不振，君火失明，宗气上浮，心神昏愦，怔忡惊悸。阴阳不交则不寐，土不制水故肠鸣，吞酸乃西金化气太过，呕吐是东方犯土有余。此皆火不归窟，气不依精，不然何以卒然颓败，倏尔神清，使非气火为病，何能迅速如此。治病必求其本，病本火亏于下，气不归精，屡服益火之剂，病势未能尽却者，以火能生土，亦能伤金。肺司百脉之气，气与火不并立，壮火食气，热剂过当，肺金受伤，元气孤浮无主，以故卒然疲败，补火固是治本之法，所失在不兼济肺标之急。今拟晨服三才，养心清金育神，以济心肺之标。晚服八味，养脾益火生土，以治受病之本。申服归脾、六君，崇土生金，以杜致病之源。疗治标本虽殊，三法同归一体。冀具肾升肺降，中土畅和，二气两协其平，水火同归一窟，精神化气，气降归精，天地交通，何恙不已。", "12819": "《经》谓肾乃胃之关。清气在下，则生飧泄。宗气上浮，虚里穴动，胃关不固，泄泻数年不痊，气不归宗，怔忡屡发不已。脉来虚数无神，久延有二阳之病发心脾，传为风消息贲之虑。服煎剂以来，诸恙减七八，当以丸剂缓图可也。", "12820": "《经》以阳受风气，阴受湿气；伤于风者，上先受之，伤于湿者，下先受之。阴湿袭虚，病起于下，两足蒸蒸而热，肿痛至膝，蠕蠕而动，酸软无力，病名脚气。本为壅疾，然必少阴血虚，阳明气馁，湿邪得以乘之，脉来细数无神，有拘挛痿躄之虑。法当除湿通经为主，辅以宣补少阴阳明之品。昔永嘉南渡，人多此疾，湿郁明矣。", "12821": "怒损肝阴，木邪化火，下耗肾水，上蒸巅顶。值有妊三月，奇脉亦受其戕，少阴虚，不能引巨阳府气则巅疼，阳维为病，苦寒热。拟《医垒元戎》逍遥散加川芎、香附，以条达肝邪，治其寒热巅疼之本。", "12822": "阳明胃火上炎，头中震痛如动脉之状，时作时止，脉洪而数。寒以取之。", "12823": "素本阳虚，不时巅痛，脉来细数，容色萧然，阴翳上滞精明之府。法当益火之源。", "12824": "宿疾阴亏，巅顶时痛，面色戴阳，脉来软数，浮阳上扰清空。暂以壮水之主。", "12825": "脉象沉滑，头痛如破，痛甚作呕，胸满肋胀，湿痰盘踞中州，清气无由上达清灵之所，名曰痰厥头痛。主以温中，佐以风药取之。", "12826": "左脉虚弦，右脉滑疾，心、肝、肾之阴不足，中虚湿痰不运，两耳失聪，如风雨声，间或蝉鸣。肝虚生风，心阴、肾阴不足，脾虚生湿，肾虚不能纳气。", "12827": "去秋右耳或闭，或作蝉鸣，或如风雨声。冬月患痔，时痛时痒，水流不止，遂服补中益气。痔患虽愈，右耳仍闭，昼夜常鸣，二目迎亮处，无限小黑点闪烁不定。右脉滑疾无力，左脉虚弦，气虚有痰，肝虚生风，脾虚生湿。每日服天王补心丹一钱，以养其气，午后服资生丸以助坤顺。", "12828": "童年患耳，延今不已，现在耳轰不聪。湿热阻于气分，少阳不和。已近精通之岁，心火肝阳不宁。脉来滑数，厥、少不和，防其失聪。", "12829": "左脉虚数，右脉虚细，先天固属不足。气分有湿，阻蔽清窍，升降失常，湿蒸热腾，少阳不和，清窍不灵，致有耳蔽之患。", "12830": "脉弦右滑，按之大疾，气分有湿有痰，耳闭不聪，精通之时，清心相以化湿热，午后服资生丸。", "12831": "《经》以十二经脉，三百六十五络，其气血皆上注于目，而走空窍。其别气走于耳而为听，心开窃于耳，肾之所司也。肾为藏水之脏，肾虚则水不能上升，心火无由下降，壮火食气，二气不能别走清空。阴液下亏，脉络干涸，气血源流不畅，是以耳内常鸣。素多抑郁，五志不伸，水虚不能生木，肝燥生脾，土虚不能生金，肺病及肾，二气不平，五内互克，辗转沉痼，岁月弥深。壮年固不足虑，恐衰年百病相侵，未必不由乎此，岂仅耳闭而已哉！是以澄心静养，遣抱舒怀，辅以药饵，方克有济。拟《局方》平补镇心丹加减，以上病下取之意。", "12832": "心开窍于耳，肝开窍于目，赖肾水光明。耳内蝉鸣，睛红生眵，太阳胀痛，手足无汗。肾虚不能养肝，肝虚生风，肾虚生热，脾虚生湿。三阴内亏，脉来虚数而空。酒色宜戒，防上盛下虚之脱。自保生命为要。", "12833": "六脉俱沉，按之细数。沉者，郁也，气也。弦者，肝也。细者，肝阴不足。气火掩闭神光，左目失明。宜以明目地黄合扶桑法，以保右目。", "12834": "目疾六载，不时举发，迎风流泪，惧日羞明，交午尤甚，申刻方好。目内红丝，起自童年，肝开窍于目，肾之所司也。脉来弦数，肝肺伏热化风，清心凉肝，兼清肺热。", "12835": "目虽肝窍，《经》以五脏六腑之精气，皆上注于目，而为之精。精之窠为眼，骨之精为瞳子，筋之精为黑眼，血之精为络，气之精为白眼，肌肉之精为约束。曾经目赤，因循未愈，近乃白精赤缕参差，浮红成片，时多泪出，内眦凝眵，而瞳子黑精无恙。此肾水下亏，不能涵木，木燥生火，火甚生风，风火相搏，肺金受制。白睛属肺，肺热故白睛发赤，时多泪出，譬如热极生风乃能雨，热耗津液故多眵。脉来软数，而且有赤脉贯瞳之虑。治宜壮水生木，升阳散火，不可泛服去风涤热之剂。《经》有上病下取之旨，拟明目养肝丸加减。", "12836": "水亏于下，火升于上，水不制火，阴不胜阳。缘少年嗜欲太过，水失所养，不能生木，木燥生风，风火交并于上，阴液消耗于下，致令瞳睛暗淡，瞳子无光，色兼蓝碧，此为内障。《经》以五脏六腑之精气，皆交受于脾，上明于目。脾为诸经之长，目为血脉之宗。肾为先天之源，脾为后天之本。脾土之强健，赖肾水之充盈，肾水虚，脾亦虚。脾虚，则脏腑之精，皆失所司，不能归明于目。肝虚，则血不归原。肾虚，则水不济火，是故暗淡无光。治宜壮水济火，补阴潜阳，冀其水升火降。", "12837": "《经》以五脏六腑之精气，皆上注于目，不独专主乎肺气也。水之精为志，火之精为神，目者，神之使也。视物不甚分明，脉体虚弦无力，素多带下，奇经有亏，水火不济，神光不敛，宜纯补真阴。", "12838": "齿痛上引太阳，因眩晕、左肢麻痹而起。金水二脏素亏，眩晕乃肝邪所致，金虚不能平木，水虚不能制火，故肝阳内扰，阴水不升，肝位居左，气虚则麻。兼以酒体肥甘过度，湿热蓄于肠胃，上壅于经，故见手阳明、足阳明、手太阴、足少阴四经之症。夫齿痛，属阳明之有余，眩晕、麻痹、属太、少之不足。按《灵枢·经脉篇》：手阳明之脉，其支者从缺盆上颈贯颊，入下齿中；足阳明之脉，下循鼻外，入上齿中，齿痛之由本此。第久延岁月，病势已深，调治非易。爰以清胃、玉女煎加鹿衔草，从阳明有余，少阴不足论治。", "12839": "《经》以齿乃骨之所终。手足阳明之脉，上循于齿。天癸主于冲脉，冲为血海，并足阳明经而行。阴虚无以配阳，水虚不能济火，是以经事先期，不时齿痛。当从阳明有余，少阴不足论治。", "12840": "形丰脉软，外实内虚。舌为心苗，黑为肾色，舌边带黑，乃肾色见于心部，非其所宜。肾司五内之精，脾统诸经之血。脾肾强健，则精血各守其乡，肾色上僭，脾肾必虚。心属火，肾属水，肾水不能上升，心火无由下降，火炎物焦，理应如是。治病求本，滋苗灌根，培补其阳，徐徐调治。", "12841": "肾水不足，心火有余。舌为心苗，火性炎上，水不济火，舌为之糜。脉来软数无神，缘五志乖逆所致。上病下取，滋苗灌根，法当壮水之主，以制阳光。", "12842": "肾水不足，肝木失荣，木燥生火，火盛生风，风火相并，上冒清空，声哑舌强，视听不聪，脉来软数无力。治宜益气壮水，冀其水火既济，天地交通。", "12843": "音声本于脏气，气盛则声扬，气虚则声哑。肾为音声之根，肺为音声之本，舌乃发声之机，唇为声音之户。肾主藏精，精化为气，脉司气化，气主发音。证因诵读太过，损于脏气。河间云：五志过极，俱从火化，火盛刑金，金溶不鸣。舌为心苗，肾为水脏，火性炎上，火旺水亏，伤其本而失其机，是以声哑语难，脉来滑数而空。爰以铁笛丸加减。", "12844": "阴损于阳，液化为痰，精不化气，气不生阴，金水交伤，脉来细数，脏阴津液俱耗。无阳则阴不生，无阴则阳不化。阴耗阳竭，饮食入于阴，长气于阳，喉疼音哑，咳嗽痰多，肾水不升，肺阴不降，阳气不敛，阴气不收，生气伤残。", "12845": "三年前蒂丁下垂，愈后喉痛不能食盐，不耐烦劳，脉来虚数，心、肝、肾三阴皆亏。厥阴循咽，少阴浇喉，湿热痰火，郁而不达。拟清上实下，久防喉痛。", "12846": "类中于右，三阳发病，神烦言蹇，肢搐口歪，气冲呃逆。外风勾动内风，湿痰上攻清窍，脉来大小不均。年近古稀，风烛堪虑。", "12847": "曲运神机，劳伤乎心，心劳肾耗，水不涵木，肝阳内扰，奔走风尘，有劳无逸，内风化火，火动痰升，上冲多汗，精神昏愦，恍惚不宁，语言错乱，类中之象。今口角歪斜，精神清爽，脉象弦滑，惟宜静养为妙。", "12848": "心脉系舌本，脾脉络舌本，少阴循喉咙，挟舌本。心脾郁湿，生风生痰，舌破流涎，类中风也。", "12849": "卒然晕倒，手足厥逆，六脉皆伏，而气口犹是。此因饮食填塞胸中，胃气不行，阴阳阻隔，升降不通，类中风而非真中风也。先宜盐汤探吐，再服煎方。", "12850": "右半偏枯，已延二月，迩时虽可言语，吐字音未能清爽，手足未能运动，脉象左部细弦，右部气口脉虚濡，关部沉滑。《经》谓三阳之病发于右，右属痰与气虚。肝肾之阴亦损，而络中痰湿未能尽净，当从气血两培，兼化痰利节之法。", "12851": "一水以济五火，肾是也。肾水不足，不能养肝火，风阳鼓动，心火随之，以致心胸不安，头眩肢麻，肤腠刺痛，腹肋气喘作胀。脉来左部弦数，右部兼滑，风阳不降，夹有湿痰，延防类中。当滋水柔肝，兼养心脾，以化痰湿。", "12852": "水亏于下，火炎于上，壮火食气，上虚则眩，头眩足软，如立舟中，咽干口燥，梦泄频频。少阴肾脉上循喉，有梦而泄主于心。精不化气，水不上承，明验也。清上实下，是其大法。肾水亏，必盗气于金，金衰不能平木，水虚不能涵木，木燥生火，煎熬津液变痰。丹溪所谓无痰不作眩是也。脉来软数兼弦，值春令阳升，防其痉厥。乙癸同源，法宜壮水。地黄汤加半夏、沙苑。", "12853": "《经》以上气不足，脑为之不满，耳为之苦鸣，头为之旋，目为之眩。素本脾肾不足，抑郁不宜，气郁化火，土郁生痰，上扰精明之府，颠眩如驾风云，卒然愦乱，倏尔神清，非类中之比。脉来软数无神，原当壮水之主，上病下取，滋苗灌根。第痰伏中州，清气无由上达，下气无以上承。姑拟治痰为主，以半夏白术天麻丸加减。", "12854": "脉弦细，按之稍滑，营卫两亏，痰气结中，中脘板闷，嗳气不舒，内热食少，有时肢抽肉𥆧，所谓血虚肝风扰络，延久须防晕厥。拟进化痰镇逆法。", "12855": "忧思郁怒，最损肝脾，木性条达，不扬则抑，土德敦厚，不运则壅，二气无能流贯诸径，营卫循环道阻。肝乃肾之子，子伤则盗母气以自养，致令水亏于下，水不济火，灼阴耗血，筋失荣养，累累然结于项侧之右。脉来细数无神，溃久脓清不敛，法当壮水生木，益气养营。仍需恬淡无为，以舒神志，方克有济。", "12856": "忧思抑郁，最损心脾。神不安舍，惊悸多疑少寐，肢战食减，容色萧然，脉见双弦，殊为可虑。", "12857": "情怀屈抑不伸，肝木横乘脾胃，脾肺两伤，脾为生痰之源，肺为贮痰之器，脾虚不能运化水谷之精微，津液凝结成痰，上注于肺，喉为肺系，是以痰塞喉间，咯不能上，咽不能下，胸次不舒，饮食减少。痰随气以流行，痰自脾经入肺，经过胞络，神形外驰，莫能自主，悲不能止，涕泣沾襟，非癫狂可比。脉来弦数无神，有三阳结病之虑。法当宁中州为主。", "12858": "生地麦冬沙苑远志茯神玄武版菖蒲龙齿忧思抑郁，最伤心脾。心为君主之官，神明出焉，脾为谏议之官，智意出焉。二经受病，五内乖违，肾水下亏，不能上济，火盛灼金，肺金亏虚，不能平木，木复生火，二火交并，清肃不行，同气相求，必归于心。东垣以火盛必乘土位，煎熬津液成痰，痰随炎上之性，蔽障神明，心神外驰，莫能自主，故心烦意乱，不知所从，动作行为，倏然非昔。前议镇木清金，泻南补北，诸症悉退，脉亦调平。第火起于妄，变幻不定，宜济补真阴，济君相而行肺金清肃之令。清痰之本，调和智意，不容上扰心君，更益以镇重之品，定其气血，各守其乡，庶免来复之患。拟《惠民和剂局方》归神丹加味主之。", "12859": "思为脾志，肝主谋虑。曲运神思，谋虑不遂，思则气结，谋深木屈，木郁生火，土郁生痰。痰火扰乱神魂，故动作不经，语言无次，阴不胜阳，脉来搏疾。法当寻火寻痰，加以清镇之品。每朝服牛黄丸一钱。", "12860": "思则气结，忧则气耗，悲哀动中，形神错乱，肝胆自怯，心肾不交，多寤寡寐，神不安舍，舍空则痰火居之。多饮膏梁伏酒，兴而后寐，胆虚不寐，阳𫏋脉空，心神不敛，肝阳不宁，有狂乱之患。", "12861": "《经》以重阳为狂，重阴为癫。胎产之后，恶露不行。因于卧，卒败血上冲，扰乱心胞，瘀凝作胀，人事不省，如醉如疯。鼓动肝风，多笑多语，心神不安。胞络者，臣使之官，喜乐出焉。化郁是理。脉来沉，沉者郁也。气血不得和畅，气化风火，败血随之，癫狂见矣。仍宜化瘀。", "12862": "心火肝火上亢，神不安舍，舍空痰火居之。月事不调，而有带症，头常作痛，遍身骨节俱疼，近来肌肤作痒，两目呆瞪，项颈气胀，牙缝出血，右鼻作腥，语言错乱，脉来滑数，肝风痰火不宁，扰乱心胞为患。", "12863": "水亏于下，木失敷荣，土为木侮，中枢少运，致令水谷精微，不归正化，凝结成痰，蔽障中土，络脉为之间断。人之气血流贯，如环无端。痰伏于中，则周流气血失其常度，是以卒然仆地，神魂如醉，痰涎上溢，四肢瘛疭，良久方醒，间断来发，病名曰痫。补正则伏痰愈结，攻痰则正气益虚，偏补偏攻，均非所宜，症本虚中之实，法当补泻兼施。拟《集验》安神丸加减。", "12864": "卒然跌仆，流涎时醒者，号曰癫痫。忽然寒热，热甚昏冒者，名为尸厥。脉来弦大，心火肝阳上升化风，夹痰上达心胞，症延二载有余，积劳、积郁、积痰为患，治之甚难。", "12865": "《经》以诸风掉眩，皆属于肝，战栗震动，火之象也。身战、口噤、背张，至夏则发，逾时而已。脉来软数，水不济火，血热化风，病名曰风痉。法宜养肝息风，壮水制火。", "12866": "厥阴绕咽，少阴循喉咙，挟舌本，手足阳明之脉，入上下齿中。咽疼舌短，卒然口噤背张，手足掉摇，气从少腹冲逆于上，阴亏水不涵木，冲虚血不荣筋，中虚湿痰生热，血燥化风，风扰阳明，龙雷上僭，所服之方甚妥。拟归芍异功加减，从厥阴、阳明主治。", "12867": "瘛疭已缓，入夜虚烦，口干作渴，心悸如人将捕之之状。腹中似胀，时有气升，舌难伸，项背强，牙关紧，六日不更衣，脉虚弦而数，湿痰化热，血燥生风，风扰阳明，九窍不和，都从胃治。原方加减。", "12868": "因惊恐而致病者，主于肝胆；因病而致惊恐者，属乎心肾。心为君主之官，端拱无为，相火代君行事，相火藏于两肾之间。《经》言七节之旁，中有小心，即其处也。肾为作强之官，伎巧出焉，盖人之动作行为，皆赖肾中之火，此火一衰，则情志昏愦，形神颓残，而风痹痿厥等症，所由来也。今脐下卒然震动，惊惕莫能自主，旋竟上攻，两臂痿厥不收，逾时而已。脉数无力，面色戴阳，症势颇类无根之火。盖非相火衰微，乃忧思抑郁，致火不宣扬，不能生土，且南方卑湿，脾土常亏。既失所生，又素不足，脾湿郁而生痰，流注诸经，变幻不一。左关属肾，肾火不安，肾志为恐，而蔽障于痰则悸，譬如水滴火中，炎焰勃然而起，故气自脐下而上升于两臂，正合七节之旁之旨。两臂亦中土太阴、阳明之部，横走于肝则木不安，肝主谋虑，胆附于肝，胆主决断，为痰所扰则怯。诸恙虽见于目前，而致病之原已萌于曩昔。人年至半百而衰，必少壮有恃强之弊，非一朝一夕之故，其所由来者渐矣。公议补肝肾，运中枢，以杜痰源；省思虑，益精神，以舒志意，方克有济。张景岳云：此为不慎其初，所以致病于后，今病已及身，而又不知慎，则末有能善其后者矣。此言最切，故幸留意焉。", "12869": "《经》以喜怒伤气，寒暑伤形，冲脉起于肾下，出于气街，挟脐上行，至胸而散。冲脉动，则诸脉皆动。少腹属厥阴，厥阴肝也。气从少腹蠕动，逆冲于上。心慌意乱，虚里穴跳如跃梭。肾不养肝，气失摄纳，皆根蒂之亏。寡欲固是良谋，更宜恬淡虚无为妙，否则尽恃草木功能，一曝十寒，亦无益也。", "12870": "年甫廿三，脉来软数，二天不振，心肾交亏，瘰疬虽痊，二气伤而未复，虚里穴动，中虚作呕。先养心脾，兼滋肝肾。", "12871": "真阴不足，心肾不交，宗气上浮，虚里穴动，心烦意乱，莫能自主，脉数无神，当培其下。", "12872": "脉体渐平，症势渐减，水火渐有相济之机。第久恙阴亏阳亢，心肾不交，宜服养心之剂。", "12873": "心为君火之乡，肾为藏水之脏，火性炎上，水体润下，水欲上升，火欲下降，水虚无以上升，心火何由下降，水火不济，心肾不交，是以心烦意乱，不知所从，宗气上浮，虚里穴动。脉来软数无神，有惊悸健忘之虑。法宜壮水潜阳为主。", "12874": "真阴下亏，虚阳上越，水不济火，心肾乖违，五志过极，俱从火化。火愈炽，水愈亏。水不涵木，曲直作酸，阴不敛阳，竟夜无寐，甚至心烦虑乱，莫能自主，心气必困于精，脉来弦数而软。授以三才、六味，加以介类潜阳之品，专培五内之阴，冀其精化气、气归精，阴平阳秘，精神乃治。", "12875": "脉来动数，按之则弦。默默不知喜怒，时多疑虑，幻生惊恐，心胆自怯，怯则气乱，伤乎心也，恐则精怯，伤乎肾也。心为君主之官，胆司中正之职，附于肝之短叶下，胆汁不满，胆冷无眠。所服之方，理路甚是，仍清一手调治，暂与十味温胆汤。", "12876": "不寐怔忡之症，得于思虑惊恐。夫惊气伤胆，恐气伤肾。五志不伸，必生痰聚饮，聚饮气阻，则胆气不洁。胆寒肝热，热升于胃，则心胸懊𢙐，得汤饮稍安，不涌吐清涎。适阅前方，均调养心脾之法，未获效者，俱未论及胆胃二经，况悸在胃脘心下，脉来两关弦强搏指，岂非明证。书云：水停心下则悸。又曰：胃不和则卧不安。正合经旨。拟苓术半夏汤，和其阴阳。兼用猪胆汁为足少阳之先导，谅该有益。", "12877": "服药三剂，诸恙平平，脉来形色未起，殊非佳兆。现感风寒，暂以二陈汤加减。", "12878": "脉来细涩，脏阴营液俱耗。肾虚则胃关不健，肾不吸胃，食入即吐，小便红赤，夜不能寐，心神不交，酒色伤阴耗气，防其涣散。多酌明哲。", "12879": "左脉涩，右脉弦滑。肝肾两亏，肾虚则胃关不健，脾积则饮食作酸，胃不冲和，运纳失常。脉犯五行之克，少年更属不宜，延四月有余，正气肾气皆耗，虚不受补，症属棘手。补阴益气煎加沉香三分。服四剂，吞酸已减，脉象稍清，盗汗仍多，原方加神曲。以保固真元，诚有益耳。", "12880": "《经》以阳之汗，以天地之雨名之。汗即血也。素昔经来甚涌，近乃汗出不收，面色戴阳，虚里穴动，脉象软数无神。症属阴亏，水不济火，阴不敛阳，腠理疏开，心液外泄。前进壮水潜阳之剂，虽获效机，第汗血同归一体，使无崩漏之虑，宜加固血之品。", "12881": "经脉", "12882": "《经》以女子二七天癸至，任脉通，太冲脉盛，月事以时下。又二阳之病发心脾，有不得隐曲，女子不月，其传为风消，为息贲者危。经闭年余，饮食日少，形体日羸，脉来弦劲，乃郁损心脾，木乘土位所致。心为生血之源，肝为藏血之脏，脾为统血之经。心境不畅，肝不条达，脾失斡旋，气阻血滞，痞满生焉。五志不和，俱从火化，火烁真阴，血海渐涸，故月事不以时下，必至血枯经闭而后已。将治心乎？有形之血难培。苟治脾乎？守补中州易钝。抑治肝乎？条达滋柔均皆不受。当以斡运中枢为主，使脾胃渐开，将逍遥养肝郁，再以归芍地补阴养血，调和冲任，冀其经通为吉。", "12883": "左脉弦出寸口，志意隐曲不伸，郁损心阴，阴虚血少，血不养脾，脾伤不能为胃行其津液，胃病不能容受水谷而化精微，精血日以益衰，脉络为之枯涩，经闭半载有余，腹中虚胀作痛，容色憔憔，饮食减少。《经》言：二阳之病发心脾，有不得隐曲，女子不月是也。其传为风消，再传为息贲，则不治。", "12884": "腹中素有血症，大如复杯，脉络阻碍，经血循环，失其常度。经不及期，经前作痛，气郁伤肝，木乘土位，饮食减少，悲哀伤肺，治节不行，胸次不畅，腰如束带，带脉亦伤，年逾三旬，尚未妊子，必得经候平调，方能孕育。", "12885": "经乃水谷之精气，和调于五脏，洒陈于六腑，源源而来，生化于心，统摄于脾，藏受于肝，宣布于肺，施泄于肾，上为乳汁，下为月水。经闭五载有余，饮食起居如故，无骨蒸、痰嗽等症，乃任脉经隧滞塞，非血枯可比。手指肿胀色紫，不时鼻衄，经血错行可知。营气不从，逆于肉里，遍身疮疡，脉来滑数而长，有痈疽肿满之虑。拟子和玉烛散行之，冀其经通为吉。病势深远，药性暴悍，多酌明哲，再服可也。", "12886": "经以应月，月以三十日而一盈，经以三旬而一至，象月满则亏也。亏极则病，阴亏则火盛，火盛则逼血妄行。《经》以阴亏阳搏谓之崩是也。服药以来，崩漏虽止，巅顶犹疼，腹中䐜胀。厥阴之脉，上出于额，与督脉会于巅顶，下络少腹，水不涵木，阴不敛阳，巅疼腹胀，脉软数无神。仍以壮水潜阳为主，冀其气血各守其乡，方无来复之虑。", "12887": "气不外卫则寒，血失中营则热，经无约束则愆期，二气素虚，奇经复梗，督行一身之阳，任行一身之阴，任督犹天之子午，冲脉从中直上，合地之云升。法当静补真阴，以充八脉。", "12888": "脉来滑数，无神而空，似有胎而不果，腹无坚硬之处，非停瘀可比。素本月事不调，晡热巅疼，时作时止，阴亏血少，病在肝脾，木不条达，土运郁抑。崇土培木，宣补中州，观其动静。", "12889": "经候愆期，胸腹相引而痛，痛时手足厥冷，过食生冷、寒冻即发，腹中雷鸣，脉来沉细，显是命火中伤，不足以煦和五内而敷四未。皆由产后气血双亏，虚寒为崇。治宜益水之源，以消阴翳。", "12890": "坤道重在调经，经调方可受孕。经本失期，少腹胀痛，不时呕哕，脉象双弦无力，少腹主于肝，肝病善痛；肝传脾，脾病善胀；脾及胃，胃病善呕，饮食不甘。肝、脾、胃并病，有妨孕育。", "12891": "经闭半载，肝郁气滞，气滞血凝，血结成症，下离天枢寸许，正当冲脉之道，是以跳跃如梭，攻痛如咬，按有头足，疑生血鳖。肝乘土位食减，木击金鸣为咳。中虚营卫不和，寒热往来如疟，从日午至寅初，汗出而退。脾伤血不化赤，白带淋漓，脉象空弦，虚劳已著。第情志郁结之病，必得心境开舒，服药方克有济。", "12892": "年逾四旬，产育过多，气血双亏，形丰脉软，饮食不甘，精神慵倦，夜来少寐，清晨坐起必呕，胃有留饮，经失期色紫，腹右有症，由气郁伤肝，怒哀动中所致，有血崩之虑。先以解郁舒肝，以畅心脾主治。", "12893": "带下赤白如漏厄。脉虚弦，舌绛中有红巢，大便坚结难解，小腹左角作痛，遍体关节酸痛，咳嗽震动，按摩其痛不止，甚至呼吸往来俱觉牵引痛处，此皆血液脂膏耗损，不能荣养一身，经隧滞涩，络脉乖分，二气无能流贯连络交经之处。前哲谓久漏久崩，非堵塞可止，升提可愈。法当协和二气，调护双维，宣补中寓以收涩之意。", "12894": "宣补之中，寓以收涩之法，取通以济塞之意。盖带下日久，液道虚滑，卒然堵塞，陡障狂澜，其势必溃。故以宣通之品，为之向导，同气相求也。服后带下较减，痛楚渐舒，大便仍结，舌心无苔，一条红滑，乃真阴亏损之征也。脉来弦数无神。原方加减。", "12895": "连进通以济塞，带下十减二三，小腹关节酸痛俱缓，大便燥结未润，弦数之脉未静，舌心红滑如故。症本血液脂膏耗损，复延奇经，任行身前，督行身后，冲脉从中直上，带脉环周一身，如束带然，阴维阳维，阴阳相维，阴𫏋阳𫏋，阴阳相交，八脉俱亏，百骸俱损，岂铢两之丸散，所能窥其藩牖乎。爰以一通一塞，大封大固之品，共煎浓汁，如膏如饴，每以二两，开水和服，下咽之后，入胃输脾，融化营卫，濡枯泽槁，则欣欣向荣，营气充满一身，庶乎二气协和，奇经复振。", "12896": "带下不止，所有皆淡黄色，腹痛筋如抽掣，此精血内枯，脂液尽涸，冲任交病，非肝木乘脾也。从奇经八脉主治。", "12897": "经漏成带，医疗无功，乃冲、任、督、带交病，所与归脾等剂，未尝齿及奇经。议通阳补阴，从奇经八脉主治。", "12898": "奇经之脉，隶于肝肾。冲任不足，血复虚寒，经来色淡且少，带下腰痛，骨节酸痛，当乙癸同源主治。", "12899": "天地氤氲，万物化醇，男女媾精，万物化生，故受胎必得醇正之气。肝木乃东方生发之本，性喜条达，怒恶抑郁，则生发之气不振，脏腑皆失冲和。况坤道偏阴，阴性偏执，每不可解，皆缘木不条达，素来沉默寡言，脉象虚弦无力，肝木郁结可知。拟逍遥、归脾、八珍加减，冀其肝木畅和，方有兰征之庆。", "12900": "服壮水潜阳之剂，胎元竟过离宫，半载以来，阴平阳秘，脉象和调。曾经受孕，即觉体倦神疲，由渐而甚，至产育后方平。现在形神拘倦，甚于畴昔，皆缘火甚阴亏，仍以壮水潜阳为主。", "12901": "胎元本于气血，盛则胎旺，虚则胎怯。气主生胎，血主成胎，气血平调则胎固，气血偏盛则胎坠。曾经半产五次，俱在三月之间。三月手心主胞络司胎，心主一名膻中，为阳气之海。阳气者，若天与日，离照当空，化生万物，故生化著于神明，长养由于阳土，君火以明，相火以位，天非此火，不能生长万物，人非此火，不能生长胎元，人与天地同参，日月相应，天一生理也。但此火平则为恩，亢则为害。胎三月则坠，正属离火暴甚，阴液耗虚，木失滋营，势必憔悴，譬如久旱，赤日凭空，泉源干涸，林木枯槁，安能不坠。脉来滑数无神，证见咽干舌绛。法当壮水之主，以制阳光。", "12902": "产后百脉空虚，气血俱伤，冲任不振，半月血来甚涌，所谓冲伤血崩是也。斯时宜宗前哲暴崩暴漏，温之补之之法。蔓延不已，奇经大损，营卫乃伤，任虚不能外卫，冲虚无以内营，致寒热如感，冲脉并足阳明经而行，阳阴不和，乳房作痛，上气不足，头为之旋，水不济火，五心燔热，诸虚叠见，日以益甚。脉来弦数无神，先从太阴、阳明进步，冀其胃开进食，诸虚可复。", "12903": "大产后阴伤未复，内热目涩羞明，形神慵倦，脉象虚弦。水不涵木，火灼金伤，清肃不降，咳吐痰腥，有肺痈之虑。清上实下主之。", "12904": "有妊至七月则坠。七月手太阴肺脉司胎，肺司百脉之气，气与火不两立，壮火食气，肺藏乃伤，无以奉秋收之令。金水同源，肺与大肠相为表里，肾开窍于二阴，大便坚结难解，阴亏火盛可知。治宜壮水潜阳为主，辅以清肃上焦之意。", "12905": "半产后亡血过多，木失敷荣，素多抑郁，中枢少运。胃者卫之源，脾乃营之本。胃虚卫不外护则寒，脾虚营失中守则热。脾为统血之经，肝为藏血之脏，肝脾俱困，经候愆期，宗气上浮，虚里穴动，脉来弦数无神。治宜滋肾补肝为主，解郁崇土辅之。", "12906": "（案1）汪，唐家弄。喉痛，悬壅下垂，喉壁仍累累高起如疱丁，咯痰艰涩不利，交睫梦梦惚惚，至夜则足肢微浮，形瘦面黧，脉沉涩数。肾阴不上承，肺气不肃降，有水竭金枯之虞。", "12907": "（案2）王，十六浦。肝胆气横，阻遏胃降，饮食所入势必呕出，昨日呕甚吐苦，气仍逆而不已，呕剧将咽头胃络呕破，以致血与食物并出，咽中痛，脉弦。治以疏肝降胃，兼泄少阳，切莫见血投凉。", "12908": "又，二诊：肝阻胃降，呕逆过甚，将咽头震破，致血与食并出，咽中痛，投降胃血止呕，平。但头脑仍眩，体疲乏力，向有脑漏，偏著左边，脉弦。脑漏鼻渊亦胆热上移也。", "12909": "（案3）陈，澉浦。阳升太过，清窍空，脉络之血难以下趋，血走清道，鼻衄来如涌，涌日屡见不一见，络血由裂伤而出，如走熟径也。治当引阳入阴，安宁督脉，俾阳络之血不至妄行可耳。", "12910": "（案4）金，童，平湖。肺主气，心主血，心肺相依为用，所谓平人一呼脉行三寸，一吸脉行三寸，呼吸定息脉行六寸，一昼夜凡一万三千五百息，八十一丈周于身。肺气为病，心血不清，痧疹一发再发，留邪不达，气化有阻，面目肢体尽肿，颈项亦肿，呼吸深则胸胁中痛，小溲短少。水道不通，亦气化之不下输也。若蔓延深入，必至肺胀喘闭则恶矣。", "12911": "（案5）邵，右，武定路。产育多胞胎，脉内损，荣血有亏。头眩，目视少神，背膂胀痛，胸宇气闷不舒，入夜掌跖炎热，烦劳则下恶露，红黄杂见。脉弦涩，胞脉失固，殊防崩漏。腹中或痛而热，则肝气不舒，气有余便是火，故虽热而痛也。治以舒气调荣，兼固胞脉。", "12912": "又，二诊：肝气不舒，荣络失和，右腰肋内脉牵引而痛，咳嗽行动坐卧转侧或作拘急，脉弦涩。治以舒气机，调荣脉。", "12913": "（案6）李，右，唐家弄。经隧不通，胞络恒闭，少腹两旁有癖。近日咳呛见轻，偏左腿肢腰胯酸胀而痛，筋掣微麻，舌后半截难过弗爽，莫能名状。胞脉属心，心主一身之血脉，又络于舌，脉弦涩。仍以通络行血可也。", "12914": "（案7）潘，右，嘉善。右肩髃疼痛，筋骨拘急，机关不利，臂难上举。仲景云：但臂不遂者为痹。惟脉不浮数而弦滞，经事又复失调，当以行血舒筋，以利机关。", "12915": "（案8）忻，右，虹口。腹痛肠鸣，便泻，食难运化，形瘦色夭不泽，月事已两月不来，舌光绛如豚肝，日有寒热，间有咳嗽，脉濡弦。真元已伤，胞脉已闭，肠胃脂肪剥蚀殆尽，病势已深，生气索然，外将浮肿，难以疗治矣。", "12916": "（案9）陆，右。火为风搏，郁而不宣，喉痛咽肿，悬壅下垂，嗓音窒咽不扬，肢清形寒，脉浮数，稍有咳嗽。治以清宣利咽。", "12917": "（案10）汪，昆山。血瘀在络，左背胛酸楚，起及于肘腋胠胁，既则右背部胸膺亦然，内著于骨，故按之痛少止，然不能卧，卧则痛甚，胸臆气闷不舒，呼吸亦感不快，脉弦涩。心主一身之血脉，此亦脉痹之属，络病难治，渐痹渐痼，则尤难治矣。姑以宣通。", "12918": "（案11）胡，左，绩溪。脏脉精华皆上注于目，诸脉亦属于目，目得血而能视，肝肾精血内亏，精气无力上注，绿水泛入瞳人之内，瞳人散大，与黑珠风轮相浑，色如珠母，始初仅在右目，上年以来并及左目，但稍轻耳。脉濡弦而涩，尺部稍藏。瞽者善听，听觉又欠聪，肾脏精气之衰亦可见矣。药饵不外乎补精益气，但功效甚微耳。", "12919": "（案12）王，劳勃生路。饮食入胃，以传于肺。肺苦气逆，变动为咳，水谷精液酿痰而不生血，咳嗽痰沫多，咳剧震动肺络则痰红杂出。近日足肢浮肿，周行气化有阻，脉弦滑左搏，苔黄口苦，胆汁亦因震动而暗泄也。治以清络保肺，兼泄少阳。", "12920": "又，二诊：足肢浮肿见消，气逆咳呛仍剧未减，痰多不易咯出，日来仍带红少许，脉弦左搏，口苦苔黄，且增呕恶，饮食随痰涎呕出。盖肺气失宣，胃逆失降，胆汁亦逆流而上也。惟年老病久，未可泛泛视之。", "12921": "（案14）陈，吴江。呼出属肺，吸入属肾。肾气有伤，摄纳无力；肺苦气逆，咳嗽喘急不能安枕矣。腰酸形瘦，脉濡弦，寐觉汗泄。肺为气出入之道，其本在肾，其末在肺。纳下为主，复以宣上。但宜节欲，远房帷为要，否则难治。", "12922": "（案15）李，右，虹口。产后胞脉损伤，恶露缠绵，带下淋沥，腰酸胁痛，延日已久。近忽崩中，喷涌而至，有瘀块甚伙，头眩心悸，足膝酸软，脉弦涩而数。治以镇摄。", "12923": "（案16）米，昆山。咳嗽喘闭，气候寒暄失常必发且剧，喉间有声，卧难安枕，唾皆白沫，转黄浓则少瘥，脉滑。以温药和之。", "12924": "（案17）陈，西门。湿滞相搏肠府为病，腹痛下利红白，里急，肛胀痛则汗泄，脉弦，舌苔灰白而腻。治以导滞通腑。", "12925": "（案19）刘，左。胆附于肝，肝气盛强，少火变化壮火，胆应清静而不清静，胃当下降而不下降，以致胸脘痞塞，烦闷喜太息，时欲呕，甚则呕恶酸苦，苔黄，口苦而燥，夜不得寐，欲寐或作惊惕，即经旨「胃不和则卧不安」也，脉弦数。拟温胆汤，意泄木安胃为主。", "12926": "又，二诊：肾脏精气内夺，脑筋力量不赡，手麻足酸，起立举步殊难自立，耳失聪而胀，声音咽而涩，交睫汗泄见戢，张口言语唇向左喁，亦稍见瘥，鼻血已止，尿管乍痛，脉来弦涩。湿热不攘乃发病之诱因也，仍当强肾益脑。再俟机宜。", "12927": "（案22）姚，右。肝气亢害，肝血失荣，腹胀时胀时愈，十余日来气上冲胸，迫动神经，屡经发厥，厥时手举搐搦，心悸亢进，呃逆辄呵欠，脉弦滞。势恐成痫难愈。", "12928": "又，二诊：脑力安静，肝亢较和，厥搐获愈，心悸、呃逆，呵欠俱平，腹胀胸闷皆已舒适，脉濡缓。此时完好无恙，舒筋调荣可也。", "12929": "又，四诊：营谋不利，又遭大故，志意不乐，精神痛苦，心血脑力交瘁，阳动少藏，头眩畏烦，神思不定，夜眠不安，肉𥆧筋惕，头面及掌心炎热，腰背酸痛，不食不饥，食亦不厌，脉濡滑而弦。此为精神衰弱之证，然左肢及偏左头面自觉酸木，或稍有浮肿，是则厥中之萌，当怡悦静养为宜。", "12930": "（案24）卢，右，三马路。未二十日而经至，但涩少不多，往常愆期，或四五十日一转，头胀体酸精神疲，素喜提痧，右耳后及缺盆间有结肿，皆经隧血脉为病。痰多，咳不爽，恶风，则挟伤风也，脉濡弦。姑标本兼治。", "12931": "（案25）金，右。年老精气衰，肾脉不荣舌络，言语欲出忽蹇，呃逆，气舒稍瘥，头眩，脑后筋掣而痛，带下频，善恐，皆肾虚之象。脉弦涩，日来几经倾跌，乃厥中先兆，是不可以不慎也。", "12932": "（案27）夏，北京路。清阳失旋，阳难化气，腹胀，身尽肿，皮肤厚，面黄暗晦，头脑胀痛不清，大便溏，小溲赤，脉弦，此亦肤胀之属。治以温化，但不易治。", "12933": "（案29）胡，宁波路。肺络破裂，肺叶久坏，痰浊秽恶，屡经清涤，迄难廓清，近日来又喷涌，咯血盈碗盈盘。血出自喉，即属肺病，若以血多而称胃血，脏腑且不明，遑论疗治耶？幸脉静息平，不然殆已。", "12934": "（案30）周，大东门。三月间寒热之后，留邪不清，内居营卫，精气暗夺，偏身颤振，如战栗之状，张口语言，面部筋脉亦掣动可见，脉濡弦，神疲，舌后半截黄积，苔中露有绛点。当养心脾，调营卫，但恐不易有效。", "12935": "（案31）李，右。湿热内阻气分，并注血中，肌肤发瘰，搔痒流水，水出后则皮渐麸而蜕，发际内亦痒，头眩，腹胀闷，尿烫，大便泻利则适，脉弦而涩。利其气，清其血，渗泄其湿热。", "12936": "（案32）黄，右。面容肌肤痿黄，毫无津泽，小溲阴道胀痛，夜寐不安，腰酸，头眩耳鸣，带下频仍，乍寒乍热，脉弦涩，舌光无苔。奇脉既伤，血质贫乏，而肝气又盛，殊难调治，且恐有崩漏之患。", "12937": "（案33）李，右。血质淡薄，肌肤面色㿠白，旧岁产后又失调养，经来迟而白多，带下亦频，然血虚火又盛，偏头痛，左耳后筋掣不舒。近日口腔内有疮，稍有咳嗽，则气候上失和之过，脉弱弦微数。养荣补血，稍佐清宣。", "12938": "（案34）冯，右。冲为血海，女子系胞即系于此。流产胞脉暗伤，体质虚弱，以致虚不肯复，宗脉失养，累及脑海，头眩耳鸣腰疼，体疲，带下频仍，或胸背交痛，或胸膈气闷，呼吸亦感不舒，脉濡弦涩。见症似嫌复杂，奇恒为病则一，若求速效，亦不可能也。", "12939": "（案35）何，右。肠胃交通滞塞，食入翻出，呕恶酸苦痰涎，大便十余日不下，形瘦容悴，脉弦涩。肠枯胃逆，格症是虑。", "12940": "（案36）黄，姑。经停半载，大便溏泄，有时虽泻而不爽，形瘦纳减，晡热骨蒸，咳呛气急，左卧欠逸，面暗跗浮，脉细弦数。劳瘵血枯，难以图治。", "12941": "（案37）盛，右。冲脉起于关元。关元者，精神之所舍，元气之所系，女子系胞即为命门。六七而天癸就竭，不当竭而竭，是谓不及，不及则排泄亦不力，湿热得流布脉络中矣。足肢流火，肌肤风瘣，或发于耳后颈项间，面赤汗泄，莫不由此。然命门之精气日益不振，纳食寡味，胀而难化，近则且有五更晨泄之患，病机日长，元气日消矣，可忽耶！", "12942": "（案38）赵先生。肾脏有翕有辟，亦静亦动。精为肾之体，体主静主翕，故以蛰护封藏为本；尿为肾之用，用主动主辟，故又泻而不居。肾脏有伤，精气滑泄，有辟无翕，有动无静，精气虚乏，荣卫循行遂愆常度矣。肢清恶寒，然后身热而发无定时，脉濡弦，小溲昼少夜频。治宜固其精气，谐和荣卫。", "12943": "（案39）康，七浦路。脘痛，休止半晌又痛，鸣则少瘥，午后较剧，或彻于背，则如锥刺，脉弦涩。气滞血瘀，痛深及于络矣，以蠲痛通络。", "12944": "（案40）汪。阴伤液燥，太阴不收，肺气焦满，咳呛痰稠，右卧欠逸，行动即觉气急，形瘦皮毛焦，掌中热，鼻窍时见衄血，脉濡细弦数。诚恐肺痨叶焦，仍以清肃润降之剂。", "12945": "（案41）余太君。乘车倾跌，脑筋震动，有迸裂之势，心摇善恐，甚则四肢瘛，口向左㖞，头有微汗，如痉厥之状，虽较中为轻，然语言欲出忽蹇，与中相去仅一间耳。小溲数，带下频，皆年老精气衰之故，但胸中气闷，喜太息，咯痰灰黑，口苦，苔腻，脉濡弦，稍有郁闷，而厥即随之。盖气机失舒，痰阻于络，内风即乘隙而动，脑筋气就激烈而弗安也。兹拟荣络熄风豁痰，缓和神经。", "12946": "（案42）康，宝山路。肠胃幽门之间淤塞不通，食再则吐，咽入一瓯且呕，绵延甚多，便秘枯结，肌肉消瘦，肤起鳞屑，按少腹结肠如垒块，脉细弦涩，年逾六旬，胃脘枯槁。虽有智者能言之，未必能行耳。", "12947": "（案43）钱，右，常州。阳气者，若天与日，故阳者卫外而为固也，清静则肉腠闭拒，虽有大风苛毒，莫之能害。清阳不振，卫气空疏，头胀形寒畏风，鼻多清涕，动辄汗泄，耳轮畏风尤甚，感受清冷即欲作呕，饮食下咽即欲大便，皆阳之无力升举也，腹胀则阳微阴盛之过，脉细濡缓。治以固卫和阳。", "12948": "（案44）任，姑，高昌庙。生未足月婴时即泻，后天脾胃不振。现当任脉通、太冲脉盛之年，而干瘪不长，无发育气概，牙宣便溏，药饵难治。", "12949": "（案45）卢，右，三马路。外因伤风已解，咳痰霍然，头脑较清。经水适来，但涩少不畅，左胁间昨闪烁而痛，左手后及缺盆结核未消，脉弦。再以疏肝舒气。", "12950": "（案47）方，右，霞飞路。肝胆火热下移任脉，带频色黄，少腹胀，两旁作酸，脉弦涩。久恐聚而为瘕。《内经》云：「任脉为病，女子带下瘕聚。」宜先事消弭也。", "12951": "（案48）施，新开河。肺为娇嫩，水之上源。因𪱥郁而肺络迸裂，血乃外溢，血后肺燥，阴不上承，咳嗽不休，晶沫中带有血星、血筋。近复骨蒸盗汗，声音嘶败，脉细弦数，有水竭金枯之虑。惟肺系声音之路，苟阴精不复，液难荣溉，喉痛声嘶不瘥，即难疗治。", "12952": "（案49）陈，三马路。向嗜曲糵，内湿自盛，与外湿相感，未尝宣泄分消，寒热延缠已将四月，荣卫循行失常，头眩体酸，或有盗汗，咳嗽不甚，肌肉渐瘦，脉弦右搏，舌苔黄腻。荣卫皆水谷之气，水谷酿湿，湿盛荣卫自衰矣。先以和荣卫，止寒热，徐图理湿。", "12953": "（案50）姚。风邪由肺俞内舍于肺，失治，邪入益深，肺气益伤，咳嗽气逆喘急，左胠内痛，仅能右眠，身热痰腥，稍有浮肿，脉濡弦，肺叶行将败坏，亦颇难治。", "12954": "（案51）黄，右，吉祥街。形色稍起，略有生气，但损者非一日而损也，虚极岂能骤复？寒热，寝汗，咳嗽，不过较前稍减，脉濡弦。再以养荣固卫。", "12955": "（案53）赵先生。荣卫偕和，寒热自辍，惟肾脏精气之虚由来已久，摄纳不固，则小溲夜频，运化无力，则生痰酿湿，脉弦滑。拟强肾运脾。", "12956": "（案54）李，右。睫毛堕落，内眦多泪，睑皮发炎，舌苔薄，左边苔皮亦蜕如剥，头微眩，大便素溏，近年来已转实，但欲解不畅。年届六旬，脉来濡静柔和，见证属肝旺胃薄。纳食欲嗳，亦胃虚作嗳。愚见怡悦颐养为要，草木汤液不宜多服。", "12957": "（案55）马，后马路。性躁而量窄，有难言之隐，膈气不舒，清阳失旋，发为厥心痛，痛发倏忽面颊呈青色，肢清背胀，不痛则无恙，脉弦。从厥心痛治。", "12958": "（案58）杜，右，太平里。经事将至未至，以前少腹绷胀而痛，经净以后，带下有红黄恶物，腹中气忽上忽下不舒，夜卧足肢平放则难过，莫可鸣状，脉弦涩。隐疾之征兆已见，宜慎毋忽！", "12959": "（案59）顾，南海。湿蕴气中，清浊混乱，腹膨胀痛，肠中鸣，大便泻，小溲少，食难运化，面色苍黄，脉弦，苔黄腻，宿染雅癖，岂宜久泻？今延缠已两月久，则防脾败。", "12960": "（案60）荣，山海关路。思虑太过，志意不乐，脾元大伤，初起寒热多汗，延日既久，脾神益加委顿，气机不为灵转，腹膨胀，面浮跗肿，面容肌肤痿黄不泽，脉濡缓而弦。脾运困惫，胀势乃成，幸毋忽也！", "12961": "（案61）胡，法工部局。禀赋丰厚，色苍而肉腠致密的是强盛之体，但丰腴肠胃脂肪必厚，痰湿亦盛，痰浊盛，胃气苦浊，是以晨起口苦，腻而不清，乘热饮食，往往腹痛溏泄。然神劳事烦，脑力多动少静，清空之血下趋滞涩，脑常胀痛，亦晨起较甚者，因卧著血聚于上也。脉弦搏，形色脉候均无虚象。兹拟泄胃气之腻浊，清脑筋之血液。", "12962": "（案65）伍，宣城。两胁皆属于肝，气行于左，而脏实居右。胁内痛，牵及季胁以后，不惟转侧维艰，且又难卧下，右臂肩髃作酸，小溲赤，极艰涩难解，脉弦涩。肝脏气滞血瘀，防酿肝痈。", "12963": "（案67）余太君。风阳就和，脑力安静，瘛疭痉厥向瘳，胸宇已舒，面容清爽，舌苔亦薄，惟偏左头筋时仍扛起，木而不适，或作噫嗳，脉搏已调，大便颇逸。仍以清络柔肝安脑。", "12964": "（案68）余，右，源泰里。嗜饮成癖，曾患水肿，病根未除，癖又难去，心悸荡漾，脘中气结若痞，肢清足肿，脉沉细而弦。以温药和之。", "12965": "（案69）伍，宣城。肝著，气滞血瘀，右胁内痛，牵及季胁以后，淋溲便难，卧下转侧维艰，日昨食物有伤，痛则欲呕，脉弦。病势已深，治疗甚难，若不自慎，盖难图矣。", "12966": "（案70）崔，新开河。痰湿俱盛，元阳不振，腹胀尿急，宗筋不举，头眩，记忆善忘，交睫善寐，寐则多梦，脉濡滑，按之无力。宜扶元阳以祛痰湿。", "12967": "（案71）陈，右，南成都路。经事四月余不转，胞脉为闭，经隧之血将化为水，足肢浮肿，至晚而甚，当以通泄，延久输化不行，势必碍肺，又有喘闭之患矣。", "12968": "（案73）陈，国庆路。咳嗽起经八年，近日咳嗽痰多，左胸胁引痛，始觉左胸膛骨高肿，重吸及咳痛甚，按其热殊炽，仅能右眠，脉弦数，左搏于右，病在肺体著骨之处，防疽患。", "12969": "（案75）余，遂安。精败为浊，缠绵已久，小溲频数，注射无力，精耗于下，骨少髓养，阴中之火浮泛于上矣。左齿髓痛，牵及脑筋，目微赤，背胀，咳痰偶尔带红，左跗肿，右髀麻，脉弦而涩。病皆出于一源，从肝肾治。", "12970": "（案77）吴，福右路。外感秽湿，内伤食滞，内外相搏，胃气失降，胆汁壅遏，脘中痞闷而胀，头脑不清，面目肌肤发黄，小溲亦黄，但黄暗而不深，脉弦。以通降腑气可也。", "12971": "（案78）郑君，棋盘街。湿为重浊阴邪，湿踞于中，清阳不振，清气在下则泻，浊气在上则胀。清阳实四肢，浊阴归六府，阳不胜其阴，故肢清且麻，腹鸣濯濯矣。头眩亦清阳不升，少寐由胃气不和。脉弦，苔黄腻。升清阳以祛浊阴可也。", "12972": "（案79）胡，抛球场。前患黄疸，肝失疏泄，脾运不为灵转，胆汁瘀滞，结成窠囊，腹右膨胀，闷塞不舒，欲嗳弗畅，面目肌肤小溲俱黄，脉沉弦。病根深久，疏达肝脾，冀其少瘥而已。", "12973": "（案80）周，南市。腹胀痛绷急，食难运化，肌瘦，大便溏，脉弦而搏，咳嗽，少寐多汗，时有寒热，肺劳肠劳萃于一身，岂易治耶？非但女劳宜戒，饮食亦当有节也。", "12974": "（案81）吴，崇德。肾脏气力微弱，饮食入胃，以传于肺，水谷精微即酿为痰，痰壅于上，肺苦气逆而为咳嗽气急矣。气候寒冷较甚者，肺为呼吸器官，恶寒又肾命气怯无力御寒也。脉濡滑而弦。从肺肾一炁论治，但以纳肾为主，防喘促于未然。", "12975": "（案82）潘，爱多亚路。脉来弦搏刚劲，左寸滑而濡，右尤粗大，心悸不得卧，咳出之物非血非痰，有如肺体，心肺之伤久矣。惟近来益甚，气逆不舒，少腹作痛，面黄暗不泽，舌黄白而腻，肠胃又连带为病，难以图治。", "12976": "（案83）崔，右，小西门。产后失调，肝脾疏运委顿，面黄而浮，足跗浮肿，纳食胀闷难化，大便溏泄，神疲呵欠，肢酸乏力，脉濡弦，声音失扬。病势已成蓐痨。仍以疏肝运脾，未识能补救否。", "12977": "（案84）李，右。病经四十余日，初起发热，四肢关节肿痛，如痹症之状。近来足肢能举，右手肿痛较减，左手仍然肿痛，举动即见颤振，经隧筋骨间留邪未去，不言而喻。躯壳久病，由经隧牵动内脏，从前心悸亢进因于热度之高，今热度已平，而舒缩仍鼓搏有力，且乍疏乍数，或有歇止，心脏为病可见。心主血之循环，肺司气之出入，心肺相依为用，循环既乱，呼吸亦逆，是以吸入很觉吃力沉著。然天庭面部耳轮皆现黄暗之色，目珠微黄，小溲则赤，唇吻黝黑，舌灰口苦，以上见证，则肝胆为病，胆汁亦暗泄，气乱流也。脉沉弱无力，至数不调，有如虚里之动跳，此时以胆汁见证为剧，然安危之机，又在呼吸之逆，息促肺布叶举，变幻难测矣。", "12978": "又，二诊：平人一呼脉行三寸，一吸脉行三寸，呼吸定息脉行六寸，一昼夜凡一万三千五百息，八十一丈周于身。可知心脏血脉之循环，全赖肺之呼吸以逼行之。肺苦气逆，心脏舒缩太急，以致心悸亢进，其动振衣，乍疏乍数或动，而中心吸气仍觉吃力，面目肌肤皆黄暗不泽，爪甲枯淡，唇吻黝黑，舌苔灰而糙，心脏少血，胆汁又复暗泄，此因病累久致虚，与劳损之虚又自有别。再拟原意，参以镇摄，使肺气和平，心脏镇静，未识应否。", "12979": "（案85）李，九亩地。腹痛呕恶，已数月之久，肝脾积伤，蓄血暴动，忽然心嘈难过，倒仆不省人事，上呕积瘀如豚肝，下则黑衃如漆滓，面容肌肤萎黄，舌本白而灰糙厚腻，脉弦涩。速当推陈致新，此病非虚非火，若投凉与补，即有盅胀之累，但此时积衃未去，仍宜谨慎，以防晕厥。", "12980": "（案86）徐，常州。思虑忧郁，精神未能痛快，气机不获展舒，胸宇既闷，咽间如有物阻，咯不出，咽不下。当悗闷不适时，肢亦清厥。然志乐气爽，则又无恙，脉濡弦。当以愉快精神为主，参以宣气解郁可也。", "12981": "（案87）陈先生。清阳单薄，健运无力，四肢清厥，啜粥为安，啖饭欠适，脘中有时不舒，然难鸣状，久坐起立头脑旋运，闭目少选即瘥。头为诸阳之会，四肢为诸阳之末，脉濡缓而弦。仍以健脾和阳可也。", "12982": "（案88）胡，宁波路。肺叶久坏，裂痕已深，如烂疮，如漏管。痰浊秽恶虽弭，而咯血历久不瘥，或盈口而出，或与痰相杂而出，高卧较安，平卧较甚。脉尚平静，面亦清亮。不然，殆已久矣。", "12983": "又，二诊：胃脘枯槁至于结肠，势难挽救，昨日大便虽通，下燥粪甚伙，尚仍呕吐，形瘦见骨，色萎不泽，脉空弦而涩。膈症至此，徒唤奈何，勉方聊尽心力而已。", "12984": "（案90）霖公。心胸作嘈，腹中隐隐乍痛，大便稍带黏积，头脑昏蒙，巅顶尤欠清爽，口甘溺赤，脉缓微弦，面黄暗不泽。肝脾疏运失司，血质有衃败之渐，不可以寻常伤湿比拟也。", "12985": "（案92）郑，恒庆里。精神虚弱，愈虚弱而愈不宁，不宁则气机之运用、肠胃之传导变化均乖乱失常。脘腹否闷，嗳气频仍，便溏不爽，夜寐不安，咽间梗塞，脉濡弦，舌后光截花剥，既糙且腻。和调腑脏，安宁精神可也。", "12986": "（案93）周，南市。环脐少腹绷急而痛，酸坠不舒，便溏日有数起，未能爽适，形瘦，脉弦搏，食难运化，或欲作呕，咳嗽，少寐多汗，仍有寒热。肺劳肠劳并病，殊不易调，如不节饮食慎啖，更难疗治。", "12987": "又，二诊：热已减退，腰脊亦能直伸，左睪丸偏坠肿痛牵及鼠蹊，胯内色仍赤，惟焮热略减，皮已转皱，脉弦。精浊瘀滞未输，仍以通泄。此囊肿之属，为日已久，殊防外溃，溃则难敛。", "12988": "又，三诊：败精腐瘀已渐输出，左睪丸偏坠焮赤渐退，肿痛渐消，但未消尽，鼠蹊舒适，囊皮已蜕，脉来缓和。病机向瘳，仍守原意，小其制。", "12989": "（案95）郭，天津路。肝者，中之将也。病失疏泄，血亦瘀滞。肝脉贯鬲，上及颃颡，故肝气亢害，未有不侮胃累脑者。侮胃不过气逆，累脑则血不行矣，卒然发厥，如痧胀之状，愈发愈促，愈促愈剧，脉弦。治以疏达调通。", "12990": "（案96）郑，四马路。年届六旬，肝肾内亏，头眩耳鸣目花，举步浮荡，神疲，懒于言语，语言欲出忽蹇。此皆根蒂有亏之证，为厥中根萌，脉弦滑。议以河间法。", "12991": "（案99）胡，右，绩溪。年前产难，胞脉内伤。胞脉属心，心主血，汗即心之液。烦劳即背胀多汗，汗泄于夜寝既觉之后。心脏之虚，亦受胞脉之影响也。照述拟以养心调荣。", "12992": "（案100）李，右。心脏舒缩较前稍缓，亦不歇止，惟乍疏乍数之象未改，日前已觉安适。昨啖芋艿，滞气生痰，肝脾疏运失司，胃气翳滞不行，脘腹绷胀而痛，按之坚硬，盖胃体之绷胀也。足肢以上俱肿，环脐少腹按之𪔣𪔣然不坚。按「腹胀，身尽肿，皮肤厚，色苍黄，」经旨以为肤胀，此气分为病，与水分有别。经事之后，继以黄浊恶物。胞脉属心，与肤胀无甚关系，与心脏病有干也。先从肤胀治，法如木香流气饮。", "12993": "青浦陆君士谔，名医也。其治症，闻声望色察脉问证，洞见脏腑，烛照弥遗，就诊者无不叹为神技。而不知君固苦心得之也。余以善病，喜读医籍。去年冬，购得《医学南针》，读之大好，因想见陆君之为人。余左胁有块作痛，患已逾年，历经中西名医诊治，药日投而病日剧，乃搭车赴松江访陆君。君一诊，即曰：病虽在气，患已及血。余告以病起由乎积食。陆君曰：食入于胃，化行于脾。今饮啖如常，脾胃足征无病。凡气分之病，臌胀浮肿，皆不见痛。君病在血分也。立方当归、川芎、白芍、香附、柴胡、潞党、红枣。寥寥七味，一剂知，三剂病若失。因与君畅谈医药，并及近代名流。君于王孟英氏最为推服。余曰：孟英果然名家，可惜偏于寒凉。读潜斋书者，每每不敢用温药。君曰：孟英用药，何尝独遗温热？其寒凉方，救逆之案为多。检其全书，用附、桂、干姜之方，有一十九案。可知药贵对证，王氏亦绝无成见也。大抵当时医家，喜用温补。王氏所诊，病病者十之四，病药者十之六。读书者不知研求，自然有偏任寒凉之弊矣。因出其自编之《孟英医案》，分类排比，眉目朗然。余不禁狂喜，劝之发刊。君曰：孟英原案，犹《资治通鉴》，余此编犹纪事本末，不过自备检查尔，何足问世。余曰：初学得此，因证检方，得见孟英之手眼，未始非君之功也。陆君颇韪余言，余因草其缘起，即为之序。", "12994": "丙申春，蜀人石符生，将赴邓云崖司马之招，经杭抱病，侨于张柳吟之旧馆，亦为寓侧陈六顺治困。居停主人知之，即告以柳吟仆病之事，石闻之悚然，亟遣人延孟英诊焉。脉沉而涩滞，模糊不分至数，肢凉畏冷，涎沫上涌，二便涩少，神气不爽，曰：此途次感风湿之邪，失于解散，已从热化，加以温补，致气机愈形窒塞，邪热漫无出路，必致烁液成痰，逆行而上。但与舒展气机，则痰行热降，诸恙自瘳矣。以黄连、黄芩、枳实、橘皮、栀子、淡豉、桔梗、杏仁、贝母、郁金、通草、紫菀、竹茹、芦菔汁等药，三服而起，调理匝旬遂愈。", "12995": "夏间王某患感，越医谢树金治之，病虽退而能食矣，但不能起坐，类乎瘫痪。延已月余，人皆谓其成废。所亲钟某，浼孟英视之，曰：此多服表散，汗出过分，气血两伤，肢骸失其营养，脉微而细，舌亮无苔，与大剂参、耆、归、术、熟地、杜仲、菟丝、牛膝、枸杞、山药、木瓜、萸肉、葳蕤、续断、桑枝。（气血双补，而补血之药重于补气。以汗为血液，阴分偏伤也。）数十而起。", "12996": "毛允之戌冬患感，初治以温散，继即以滋阴，病日以剧。延至亥春，或疑为百日之痨，或谓是伤寒坏证。而凤山僧主升、柴、耆、术以补之，丁卯桥用轻粉、巴霜以下之。杂药遍投，形神日瘁。乃尊学周延孟英视之，脉来涩数上溢，呃忒，口腻，虽觉嗜饮，而水难下膈，频吐涎沫，便秘溺赤，潮热往来，少腹如烙，按之亦不坚满，曰：此病原属冬温，治以表散，则津液伤而热乃炽；继以滋填，热邪愈锢；再施温补，气机更窒；升、柴、耆、术，欲升其清，而反助其逆；巴霜、轻粉，欲降其浊，而尽劫其阴。病及三月，发热不是表邪；便秘旬余，结涩非关积滞。且脉涩为津液之已伤，数是热邪之留著，溢乃气机为热邪所壅而不得下行。岂非温邪未去，得补而胶固难除。徒使其内烁真阴，上薰清道，以致一身之气，尽失肃清之令，法当搜剔余邪，使热去津存，即是培元之道。伸其治节，俾浊气下趋，乃为宣达之机。何必执参、茸为补虚，指硝、黄为通降哉。以北沙参、紫菀、麦冬、知母、花粉、兰草、石斛、丹皮、黄芩、桑叶、栀子、黄连、木通、银花、橘皮、竹茹、芦根、橄榄、枇杷叶、地栗、海䖳等，出入为方。服之各恙递减，糜粥渐加。半月后始得大解，而腹热全消，谷食亦安。乃与滋阴善后而愈。（清热生津治法固善，然亦此人本元坚固，故屡误之后犹能挽回，否则亦难为力矣。）", "12997": "栖流所司药陈芝田，于仲夏患感，诸医投以温散，延至旬日，神昏谵妄，肢搐耳聋，舌黑唇焦，囊缩溺滴，胸口隐隐微斑，一望而知其危矣。转邀孟英诊之，脉细数而促，曰：阴亏热炽，液将涸矣。遂用西洋参、元参、生地、二冬、知、柏、楝实、石斛、白芍、甘草梢、银花、木通、犀角、石菖蒲，大剂投之。（孟英能善用大剂，故能起不治之证，亦古人所未有也。）次日复诊，其家人云：七八日来，小溲不过涓滴，昨药服六七个时辰后，解得小溲半杯。孟英曰：此即转机也。然阴气枯竭，甘凉濡润，不厌其多。于前方，再加龟板、鳖甲、百合、花粉，大锅煎之，频灌勿歇。如是者八日，神气始清，诸恙悉退。纯用滋阴之药，调治匝月而瘳。予谓孟英学识过人，热肠独具，凡遇危险之候，从不轻弃，最肯出心任怨以图之。如此案八日后神气始清，若经别手，纵使治法不错，而一二帖后不甚起色，必规避坚辞，致病家惑乱，谋及道旁。虽不死于病，亦必死于药矣。此在医者之识老心坚，又须病家之善于择而任之专也。谈何易耶？且闻孟英尝云：温热液涸神昏，有投犀角、地黄等药至十余剂，始得神清液复者。因温热案最伙，不暇详录，姑识此以告司人之命者。（一派甘寒之药，既可涤热，又以生津，真治温良法也。惟湿温证宜稍加斟酌耳。）", "12998": "江小香病势危笃，浼人迎孟英诊之，脉虚弦而小数，头痛偏于左后，子夜热躁，肢冷欲呕，口干不欲饮，不饥不欲食，舌蹇言涩，溺黄而频。曰：体属素虚，此由患感时，过投温散，阴津阳气皆伤。后来进补而势反日剧者，滋腻妨其中运，刚烈动其内风，（知此二语方可论药。）以致医者佥云表之不应，补亦无功，竟成无药可治之证。虽然，不过难治耳，未可遽弃也。与秋石水拌制高丽参、苁蓉、首乌、生白芍、牡蛎、楝实、盐水炒橘红、桑椹、石斛、蒺藜、茯苓煎，吞饭丸肉桂心五分。一剂躁平呕止，各恙皆减。连投数服，粥食渐安，乃去首乌、桂、楝，加砂仁末拌炒熟地、菊花、枸杞。半月而瘳。（从阴引阳，从阳引阴，绝妙机轴。）", "12999": "石诵义夏杪患感，多医广药，病势日增。延逾一月，始请孟英诊焉。脉至右寸关滑数上溢，左手弦数，耳聋口苦，热甚于夜，胸次迷闷，频吐黏沫，啜饮咽喉阻塞，便溏溺赤，间有谵语。曰：此暑热始终在肺，并不传经，一剂白虎汤可愈者，何以久延至此也？乃尊北涯，出前所服方见示。孟英一一阅之，惟初诊顾听泉用清解肺卫法为不谬耳。其余温散升提，滋阴凉血，各有来历，皆费心思，原是好方，惜未中病。而北涯因其溏泄，见孟英君石膏以为治，不敢与服。次日复诊，自陈昨药未投，惟求另施妥法。孟英曰：我法最妥，而君以为未妥者，为石膏之性寒耳。第药以对病为妥，此病舍此法，别无再妥之方。若必以模棱迎合为妥，恐贤郎之病不妥矣。北涯闻而感悟，颇有姑且服之之意。而病者偶索方一看，见首列石膏，即曰：我胸中但觉一团冷气，汤水皆须热呷，此药安可投乎？坚不肯服。然素仰孟英手眼，越日仍延过诊，且告之故。孟英曰：吾于是证，正欲发明。夫邪在肺经，清肃之令不行，津液凝滞，结成涎沫，盘踞胸中，升降之机亦窒，大气仅能旁趋而转旋，是一团涎沫之中，为气机所不能流行之地，其觉冷也，不亦宜乎？且予初诊时，即断为不传经之候，所以尚有今日，而能自觉胸中之冷。若传入心包，则舌黑神昏，才合吴古年之犀角地黄矣。然虽不传经，延之逾月，热愈久而液愈涸，药愈乱而病愈深，切勿以白虎为不妥，急急投之为妙。于是有敢服之心矣。而又有人云：曾目击所亲某，石膏甫下咽，而命亦随之。况月余之病，耳聋泄泻，正气已亏，究宜慎用。北涯闻之惶惑，仍不敢投。乃约翼日广征名士，会商可否。比孟英往诊，而群贤毕至。且见北涯求神拜佛，意乱心慌，殊可怜悯。欲与众商榷，恐转生掣肘，以误其病，遂不遑谦让，援笔立案云：病既久延，药无小效，主人之方寸乱矣。予三疏白虎而不用，今仍赴招诊视者，欲求其病之愈也。夫有是病则有是药，诸君不必各抒高见，希原自用之愚。古云鼻塞治心，耳聋治肺，肺移热于大肠，则为肠澼。是皆白虎之专司，何必拘少阳而疑虚寒哉！放胆服之，勿再因循，致贻伊戚也。坐中顾听泉见案，即谓北涯曰：孟英肠热胆坚，极堪倚赖。如犹不信，我辈别无善法也。顾友梅、许芷卿、赵笛楼亦皆谓是。疏方以白虎加西洋参、贝母、花粉、黄芩、紫菀、杏仁、冬瓜仁、枇杷叶、竹叶、竹茹、竹黄。而一剂甫投，咽喉即利。三服后各恙皆去，糜粥渐安。乃改甘润生津，调理而愈。予谓此案不仅治法可传，其阐发病情处，识见直超古人之上。（论亦根柢喻氏，而更加明透。）", "13000": "石芷卿患感，张某连投柴、葛药，热果渐退。而复热之后，势更孔甚，乃延孟英诊焉。先以栀、豉、芩、连等药，清解其升浮之热，俟邪归于府，脉来弦滑而实，径用承气汤下之。时其尊人北涯赴瓯，无人敢主其可服否也。另招他医决之，以为太峻，且腹不坚满，妄攻虑变。举家闻之摇惑，暮夜复恳再诊。孟英辨论洋洋，坚主前议。服后果下黑矢，次日大热大汗，大渴引饮。孟英曰：此府垢行而经热始显，与竹叶石膏汤，二剂而安。继以育阴充液，调理而康。", "13001": "周子朝患恶寒，头痛发热。酷似伤寒，而兼心下疼胀。孟英脉之，右部沉滑，苔黄不渴，溲如苏木汁。先以葱豉汤，（先解表。）加栀、连、杏、贝、蒌、橘为方。服后微汗，而不恶寒反恶热。虽汤饮略温，即气逆欲死。孟英曰：客邪解矣，清其痰热可也。与知母、花粉、杏、贝、旋、滑、斛、橘、杷、茹、茅根、芦根、地栗、海䖳等药。（后清里。）果吐胶痰甚多，而纳食渐复。惟动则欲喘，于肃上之中佐以滋下，为善其后而瘥。", "13002": "顾竹如孝廉令嫒，患感十余日，耳聋不语，昏不识人，而客未入室，彼反先知。（热极而神外越。〕医以为祟，凡犀角地黄、牛黄清心、复脉等汤，遍服无效，（药不误，特病重药轻耳。）已摒挡后事矣。所亲濮根厓嘱其延诊于孟英，脉至滑数，舌不能伸，苔色黄腻，遗溺便秘，目不交睫者已四昼夜，（下证已悉备。）胸腹按之不柔。与白虎汤去米、草，加石菖蒲、元参、犀角、鳖甲、花粉、杏仁、竹叶、竹黄、竹沥。投一剂即谵语滔滔，渠父母疑药不对病，孟英曰：不语者欲其语，是转机也。再投之，大渴而喜极热之饮。又疑凉药非宜，孟英姑应之曰：再服一剂，更方可也。三投之，痰果渐吐。四剂后，舌伸便下，神识渐清。乃去菖蒲、石膏、犀角、鳖甲，加生地、石斛、麦冬、贝母。数帖，（温病后阴必耗竭，宜急救其阴，转方甚合法。）热尽退而痰味甚咸。又去杏、贝、竹黄，加西洋参、牡蛎、龟板、苁蓉，服之全愈。逾年失怙，继遭祝融，郁损情怀，误投温补，至戊申年殒。（叶氏云：温邪中人，首先犯肺，其次则入心，正此病也。虽不用下剂，而通经透络之品大剂用之，亦足以荡涤邪秽。）", "13003": "姚小蘅太史令侄女，初秋患寒热而汛适至。医用正气散两帖，遂壮热狂烦，目赤谵语，甚至欲刎欲缢，势不可制。孟英按脉洪滑且数，苔色干黄尖绛，脘闷腹胀拒按，畏明口渴，气逆痰多。与桃仁承气汤加犀角、石膏、知母、花粉、竹沥、甘菊。人谓热虽炽而汛尚行，何必大破其血，而又加以极寒之药哉？孟英曰：叟勿过虑，恐一二剂尚不足以济事。果服两大剂，始得大便，而神清苔化，目赤亦退。改用甘寒以清之，继而又不更衣，即脉滑苔黄而腹胀，更与小承气汤二帖，便行而各恙遄已。数日后又如此，仍投小承气汤二帖。凡前后六投下剂，才得波浪不兴，渐以清养而瘳。季秋，适江右上高令孙明府之子沛堂为室。", "13004": "顾奏云季秋患感，医作虚治，补及旬日，舌卷痉厥，腰以下不能略动，危在须臾。所亲石诵羲延孟英设死里求生之策，察脉虚促欲绝。先灌紫雪一钱，随溉犀角地黄汤二大剂。服下，厥虽止而舌腭满黑，目赤如鸠，仍用前汤。三日间计服犀角两许，黑苔渐退，神识乃清，而呃忒频作。人犹疑其虚也，孟英曰：营热虽解，气道未肃耳。以犀角、元参、石花、连翘、银花、竹茹、知母、花粉、贝母、竹叶为方。服之，次日即下黑韧矢甚多，而呃忒止。又三剂，连解胶黑矢四次，舌色始润，略进米饮，腿能稍动，然臀已磨穿也。与甘润育阴药，续解黑矢又五次，便溺之色始正。投以滋养，日渐向安，己酉举于乡。其弟翰云，患左胯间肿硬而疼，暮热溺赤，舌绛而渴，孟英按脉细数，（阴虚血热。）径用西洋参、生地、麦冬、楝实、知母、花粉、银花、连翘、甘草、黄柏等药，服旬余而愈。", "13005": "许自堂令孙子社患感，延至秋杪，证交二十八日，诸医束手。渠伯母鲍玉士夫人，荐孟英诊之，左部数，右手俨若鱼翔，痰嗽气促，自汗瘛疭，苔色灰厚，渴无一息之停，垂危若是。而皓首之祖、孀母、少妻，相依为命，环乞拯救，甚可悯也。孟英曰：据脉莫能下手，吾且竭力勉图。第恐一齐众楚，信任不坚，则绝无可望之机矣。其母长跽而言曰：唯君所命，虽砒鸩勿疑也。于是先以竹叶石膏汤加减，至五剂，气平嗽减，汗亦渐收，苔色转黑，舌尖露绛。改投元参、生地、犀角、石膏、知母、花粉、竹叶、银花等药，又五剂，瘛疭渐减，舌绛渐退。彼妇翁召羽士为之拜斗，飞符噀水，鼓乐喧阗，病者即谵妄不安，神昏如醉，羽士反为吓退。夤夜速孟英视之，与紫雪钱余，神即清爽，仍用前方，重加竹沥。服八剂，始解黑如胶漆之大便，而黑苔渐退，右脉之至数始清。惟烦渴不减，令其恣啖北梨，舌才不燥，痰出亦多。又六剂，舌色乃淡，溲出管痛，热邪得从下行矣。凡十二日之间，共服大剂寒凉，已二十四帖。计用犀角三两有奇，而险浪始平。续以前法缓制，服六剂，又解黑矢五次，手足始为己有。又五剂，筋络之振惕始定，略能侧卧，呓语乃息，渐进稀糜。继灌甘润充其胃汁，七八剂后，渴止知饥，脉皆和缓。又浃旬，谷食乃复。又旬余，便溺之色始正。前后共下黑矢四十余次，苔色亦净，授滋填善后而康。是役也，凡同道暨许之族人戚友，莫不以为秋冬之交，用药偏寒。况病延已久，败象毕呈，苟不即投峻补，必致失手。既闻鲍夫人云：归许氏二十余年，目击多人，无不死于温补。此等病曾见之，此等药盖未尝闻也。孰知如此之证，有如此之治，求之古案亦未前闻，传诸后贤，亦难追步。盖学识可造，而肠热胆坚，非人力所能及。此孟英所以为不世出之良医也。", "13006": "段春木秋杪患发热，（外感温邪。）而腰腿痛如刀割。（真阴内损。）孟英视之，略不红肿，脉至细数，（热伤少阴。）苔色黑燥，溺赤便黑。与西洋参、麦冬、生地、犀角、银花、楝实、石斛、知母、甘草、竹沥、蔗汁，为大剂投之。热渐退，痛渐已，惟舌绛无津，（阴亏也）仍与甘凉濡润为方。数日后忽舌绛倍加，燥及咽膈，水饮不能下咽。孟英曰：真阴涸竭，药难奏绩矣。然窃疑其何以小愈之后，骤尔阴枯，或者背予而服别药乎？继其契友来询云：段死而舌出，此曷故与？孟英闻之，爽然大悟，因撷伤寒女劳复之文示之。其人顿足云：良然。彼于小愈后，曾宿于外，次日归即转剧。苟直陈不讳，或尚可治？孟英曰：未必然也。烧裈散、鼠矢汤，皆从足少阴以逐邪。不过热邪袭入此经，所谓阴阳易是也。今少腹无绞痛之苦，原非他人之病易于我。真是女劳之复，以致真阴枯涸，更将何药以骤复其真阴哉？然从此而女劳复与阴阳易，一虚一实有定论，不致混同而谈治矣。", "13007": "吴酝香孝廉三令嫒患感，诸医首以升散，继进温补。至三月下旬，证交三十五日，昏痉谵语，六昼夜不交睫，旬日不沾米饮。许芷卿视之，俨似养云室证，即拉孟英暨顾听泉、赵笛楼会诊。脉弦滑而微数，齿不能开，窥其舌缩苔垢。孟英曰：尖虽卷，色犹红润，且二便不秘，尚有一线生机未绝也。揆其受病原不甚重，只因谬治逾月，误药酿成大证。势虽危险，吾侪当竭力援之，第勿再犯一味悖药，事或有济。酝香颇极信从。孟英复询其服事婢媪曰：病已逾月，腰以下得毋有磨坏之虞乎？皆曰无之，惟数日前易其所遗，略有血渍，必月事之不愆也。孟英颇疑之，嘱其再易之时，留心细察。疏方以犀角四钱，石菖蒲二钱，贝母二两，整块朱砂两许，（朱砂不宜入煎剂。）竹沥碗许，佐以竹叶、竹黄、竹茹、知母、花粉、元参、旋覆、丝瓜络、苇茎、银花、鳖甲，调下紫雪丹。次日，诸君复会，渠母徐夫人即云：王君明视隔垣，小女腰下果已磨穿，糜溃如柈，婢媪辈粗忽，竟未之知也。昨药服后，证亦少减。孟英仍主原方。四服后夜始眠，痉才息，舌甫伸，苔仍黑。孟英于前方去鳖甲、朱砂、菖蒲，加生地、栀子。数服后，苔转黄，大便黑如胶漆，且有痰色。盖从前大解黄色，似乎无甚大热，不知热由补药所酿，滞于肠胃曲折之地，而不能下行，势必薰蒸于上，致有内陷入脏之逆也。黑矢下而神气渐清，余热复从气分而达，痰嗽不爽，右脉滑搏。孟英主用竹叶石膏汤加减，四剂渐安。而外患痛楚，彻夜呻吟，虽敷以珠黄，滋以甘润，未能向愈。孟英令以大蟾蜍治净煮汤，煎育阴充液之药服之，果痛止肌生，眠食渐进，汛事如期而瘳。冬间适张舟甫之子为室，或疑其病虽愈，而过饵凉药，恐难受孕，迨戊申夏，已得子矣。", "13008": "吴酝香之仆吴森，在越患感，旋杭日鼻衄数升，苔黄大渴，脉滑而洪，孟英投白虎汤二帖而安。遽食肥甘，复发壮热，脘闷昏倦，孟英以枳实栀豉汤而瘥。数日后，又昏沉欲寐，发热自汗，舌绛溺涩，仍求孟英诊之。左尺细数而芤，右尺洪大，是女劳复也，研诘之果然。与大剂滋阴清热药，吞豭鼠矢而愈。", "13009": "何新之亦儒医也。患感旬日，胡士扬诊，谓势欲内陷，举家皇皇。渠表弟沈悦亭茂才，亦工岐黄，而心折于孟英，因拉视之。呃忒，苔腻，便秘，痰多，心下拒按，持其脉右手洪大滑数。与小陷胸，加沙参、菖、贝、菀、薤、茹、杏、旋、杷之剂，数帖而安。继以甘凉，二旬后得大解而痊。何乃执柯，为王沈联姻娅焉。", "13010": "陈邠眉令郎，孟秋患感。医与表散温补，病随药剧。至八月初，渠叔祖陈霭山，延孟英视之。目瞪神呆，气喘时作，舌绛不语，便泻稀水，肢搐而厥，人皆以为必死矣。察其脉弦而软数，乃阴亏肝盛之质。提表助其升逆，温补滞其枢机，痰饮𫐖轕，风阳肆横。祷神驱祟，有何益哉。与鳖甲、龙、牡、旋、赭、芩、连、楝、贝、菖、茹、胆星、犀、羚等药，息风镇逆，清热蠲痰，数帖而平。", "13011": "龚念匏室，故舍人汪小米之女也。患秋感，服温散药而日重。渠叔母韩宜人，请援于孟英。脉见弦数软滑，苔黑肢瘛，疏方用沙参、元参、知母、花粉、犀、羚、茹、贝、栀、菖等药，曰：亟饵之，否将厥也。时念匏幕于江南，族人皆应试入场，侍疾者多母党。伊叔少洪疑药凉，不敢与服，迨暮果欲厥矣，众皆皇皇。幸彼女兄为故孝廉金访叔之室，颇具卓识，急煎孟英方灌之，遂得生机。次日复诊，脉较和，一路清凉，渐以向愈。", "13012": "张篪百之室患感，连服温散，继邀顾听泉诊之。云有骤变，须延孟英商治，渠不之信。旬日后，倏然昏厥，自寅正至辰初不苏。病者之兄吴次欧，速孟英视之，脉伏而弦滑。与大剂犀、羚、茹、贝、知母、花粉、元参、银花，调局方至宝丹，灌下即安。", "13013": "许少卿室，故医陈启东先生之从女也。夏初患感，何新之十进清解，病不略减，因邀诊于孟英。脉至弦洪豁大，右手为尤，大渴大汗，能食妄言，面赤足冷，彻夜不瞑。孟英曰：证虽属温，而真阴素亏。久伤思虑，心阳外越，内风鸱张。幸遇明手，未投温散，尚可无恐。与龙、牡、犀、珠、龟板、鳖甲、贝母、竹沥、竹叶、辰砂、小麦、元参、丹参、生地、麦冬，为大剂投之。外以烧铁淬醋，令吸其气。蛎粉扑止其汗，捣生附子帖于涌泉穴。甫服一剂，所亲荐胡某往视，大斥王议为非，而主透疹之法。（真盲人。）病家惑之，即煎胡药进焉。病者神气昏瞀，忽见世父启东扼其喉，使药不能下嗌，且嘱云：宜服王先生药。少卿闻之大骇，专服王药，渐以向愈。而阴不易复，频灌甘柔滋镇，月余始能起榻。季夏汛行，惟情志不怡，易生惊恐，与麦、参、熟地、石英、茯神、龙眼，甘、麦、大枣、三甲等药，（一定不易之法。）善其后。秋杪归宁，微吸客邪，寒热如疟，孟英投以清解，已得向安。胡某闻之，复于所亲处云：此证实由夏间治法不善，以致邪气留恋，再服清凉，必死无疑。汤某复从而和之，（总是病者该死，故一时有此二妖孽。）许氏即招汤某诊治，谓其阳气伤残，沉寒久伏，（既已沉寒，焉能作寒热。）以理中汤加威灵仙、桂枝、半夏、厚朴、姜、枣等药。（勿论其认证之误与不误，即理中汤，亦有此等加减法耶？）病者颇疑药太燥烈，汤复膏吞拭舌，说得天花乱坠。病家惑之，初服胃气倍加，继而痰嗽不饥，黄苔满布，肌消汛断，内热汗多，心悸不眠，卧榻不起。病者坚却其药，然已进二十剂矣。再邀何新之商之，亦难措手。仍嘱其求诊于孟英，按脉弦细软数，篡患悬痈，纵有神丹，不可救药矣。（服清解药，致邪气留恋，岂服滋补药，邪气反不留恋耶？此等人而亦自命为医，岂非怪物。）", "13014": "钱闻远仲郎患感，汤某进桂、朴、姜、柴等药，而痰血频咯，神瞀耳聋，谵语便溏，不饥大渴，苔黑溲少，彻夜无眠。范应枢、顾听泉迭进轻清，黑苔渐退，舌绛无津，外证依然，不能措手。孟英诊之，脉皆细数。乃真阴素亏，营液受烁，不必以便溏不食而畏滋腻也。授以西洋参、生地、二至、二冬、龟板、燕窝、茹、贝、银花、藕汁、梨汁、葳蕤、百合等药。二剂咯血渐止，痰出甚多，渐进稀糜，夜能稍寐。五剂热退，泻止，渴始减，脉渐和，旬日后解燥矢而痊。", "13015": "陈赤堂令正患感，面赤不眠，烦躁谵语，口甘渴腻，溲涩而疼，顾听泉多剂清解未应。孟英切其脉，左弦洪而数，右滑而溢，胸次痞结，大解未行。肝阳上浮，肺气不降，痰热阻痹，邪乃逗留。与小陷胸合温胆、雪羹，加旋、薤投之，胸结渐开。乃去半、薤，而送当归龙荟丸，谵语止，且能眠。参以通幽汤下其黑矢，三次后始进养阴和胃而痊。", "13016": "许芷卿亦精于医，偶患外感，即服清散之药，而证不减，或疑其非春温也。邀孟英质之，诊脉迟涩，二便皆行，筋掣不眠，畏寒能食，喉舌皆赤。（血热之征。）与大剂清营药，数服而瘥。迨夏两腿患疥，外科治之，久而不愈。孟英谓其平昔善饮，蕴热深沉，疡科药亟宜概屏。令以雪羹汤送当归龙荟丸，果得渐瘳。秋间其太夫人患感，连服温散，转为肢厥便秘，面赤冷汗，脉来一息一歇，（肢厥而便秘面赤，可决其非脱症矣。）举家惶惶，虑即脱变。孟英视其苔黄腻不渴，按其胸闷而不舒，且闻其嗅诸食物，无不极臭，断为暑湿内伏，挟痰阻肺。肺主一身之气，气壅不行，法宜开降，是虚脱之反面也。设投补药，则内闭而外脱。昧者犹以为投补迟疑而不及救。（世之愈补愈虚，以至于脱者，大半由此。）孰知真实类虚，不必以老年怀成见，总须以对证为良药。果一剂而脉至不歇，转为弦滑。再服汗止肢和，便行进粥。数帖而痊。方用紫菀、白前、竹茹、枳实、旋、贝、杏、蒌、兜铃、枇杷叶也。", "13017": "吴酝香大令宰金谿。自春仲感冒而起，迨夏徂秋。痰多气逆，肌肉消瘦。延至初冬，诸证蜂起，耳鸣腰痛，卧即火升，梦必干戈，凛寒善怒。多医咸主补虚，迄无小效，卧理南阳，已将半载。群公子计无所施，飞函至家，嘱大公子汾伯副车，叩求孟英来署，已冬仲之杪日矣。诊脉弦细，而左寸与右尺甚数，右寸关急搏不调。且病者颈垂不仰，气促难言，舌黯无苔，面黧不渴。孟英曰：病虽起于劳伤挟感，而延已经年。然溯其所自，平昔善饮，三十年来，期在必醉。非仅外来之客邪，失于清解，殆由内伏之积热，久锢深沉。温补杂投，互相煽动，营津受烁，内削痰多，升降愆常，火浮足冷，病机错杂，求愈殊难。既承千里相招，姑且按经设法。以石膏、知母、花粉、黄芩等，清肺涤痰；青蒿、鳖甲、栀子、金铃等，柔肝泄热；元参、女贞、天冬、黄柏等，壮水制火；竹茹、旋覆、杷叶、橘红等，宣中降气。出入为方，间佐龙荟丸，直泻胆经之酒毒；紫雪丹，搜逐隧络之留邪。服三剂，而舌布黄苔，蕴热渐泄。服六剂，而嗽减知饥，渴喜热饮，伏痰渐化。季冬八日，即能出堂讯案。十剂后，凛寒始罢，足亦渐温，肺气果得下降。望日出署行香，继而兵火之梦渐清，夜亦能眠。迎春东郊，审结积案，亦不觉其劳矣。方中参以西洋参、生地、麦冬，充其液；银花、绿豆、雪羹，化其积。至庚戌岁朝，各处贺年，午后护日，极其裕如，且肌肉渐丰，面黑亦退。药之对病，如是之神。调养至开篆时，起居如旧，各恙皆瘥。而孟英将赴宜黄杨明府之招，酝香为录其逐日方案，跋而记之。兹特采其大略如此。（酝香之证，予于五月间曾为一视，知其感受温邪，投以清解，三服后颇觉轻减。又以赴饮而病，复如故，然步履尚无恙也。后乃惑于温补之说，熟地、鹿胶等腻滞之药，恣服不辍。比孟英至而其势已棘，虽逐渐清解，大势向愈，然病久元虚，邪去而正亦随之。此所以终于不起也。）", "13018": "范廉居夫妇，与其令爱，一时患恙，旬日后咸剧，金粟香荐孟英视之。廉居则大解已行，热退未净，气逆不饥，呃忒自汗，脉形虚大，舌紫无苔。为上焦热恋，下部阴亏之象。予西洋参、旋覆、竹茹、枇杷叶、石斛、柿蒂、牡蛎、龟板、刀豆、牛膝之剂，两服即舌润知饥，呕汗皆罢。去刀豆、旋覆、柿蒂，加熟地、胡桃肉、当归，投之而愈。其室则苔腻口酸，耳鸣不寐，不饥神惫，脘痛头摇，脉至虚弦，按之涩弱。以当归、白芍、枸杞、木瓜、楝实、半夏、石斛、茯神、竹茹、兰叶、白豆蔻，为养营调气、和胃柔肝之法，数啜而瘳。渠女则壮热殿屎，二便皆闭，苔黄大渴，胀闷难堪，脉来弦滑数实，系府证也。投桃核承气，加海䖳、芦菔，二剂而痊。廉居尊人颖禾曰：甚矣！服药之不可不慎也。三人之证，医者皆谓可危，而治之日剧，君悉以一二剂起之，抑何神欤！因忆四十二岁时患痁，胡魁先用首乌太早，遂致客邪留恋，缠绵百日，大为所困。嗣后不敢服药，今四十年矣。昨闻韩组林年虽七十，饮啖兼人，而平时喜服药。医以为老，辄用附、桂、参、茸等药，以期可享遐龄。讵料初八日，晚膳尚健饭，三更睡醒，倐寒栗发颤，俄而四肢瘛疭，越日云亡。得非即世人所谓之子午证耶？孟英曰：此老系阳旺之体，肥甘过度，痰火日增，年至古稀，真阴日耗，而久服此等助火烁阴之药，以致风从火出，立拔根荄。与儿科所云急惊风证，殆无异焉。", "13019": "古云肥白之人多气虚，又云痰饮须以温药和之。儒医顾听泉，体丰色白，平昔多痰，晨起必喘逆，饱食稍安，颇有气虚之象。季冬感冒，自服疏解未效，迓孟英诊焉。左关弦寸滑如珠，尺细而干，舌尖甚绛。乃真阴素亏，水不涵木，风阳内炽，搏液成痰。谋虑操持，心阳太扰，肺金受烁，治节不伸。苔虽白而已干，热虽微而睛赤，忌投温燥，宜予轻清。用元参、石斛、栀子、竹茹、旋覆、蛤壳、贝母、枇杷叶、竹叶、兰叶、莲心为剂，三啜而安。自谓气虚，遽服党参、枸杞、当归等药，下咽之后，即觉火升气逆，渐至言语支离，溲频自汗。夤夜复迎孟英拯治，脉已虚促不调，即投牡蛎、龟板、鳖甲、女贞、旱莲、元参、甘草、小麦、竹叶、莲心，以和心肝之阳，而镇龙雷之奋。一剂而平。继又作劳复感，仍授轻清之法。两剂后，又因怫怒萦思，肝阳复僭，颧红目赤，左耳时聋，夜不成眠，神情烦躁。越日陡然大汗，湿透衣衾，再速孟英图之。脉极弦数而细，仍为阴虚阳越，不可误认阳虚，而妄施附、桂者。先令熏以炭醋，扑以蛎粉，随灌以大剂二至、二冬、三甲、元参、丹参、人参、黄连、童溲而瘳。继予多剂育阴清肝，始得全愈。又其媳新产之后，头痛甚剧。孟英按其脉右甚滑大，予清阳明法，得大解而瘥。", "13020": "施玉林患感，治经多手，延将匝月，热退未净，苔腻垢黄，脘闷便溏，腰疼溺短，不饥不眠，气短音低，医者技穷。李华甫荐孟英视之。脉弦软不调。而尺中虚细，是痰热尚结于上焦，房劳素伤于下部。初治即从清解，并无背谬之方，奈不足以开有形之结，而滋久耗之阴，以致旷日相持，神气日形消索也。以小陷胸汤加苇茎、竹茹、枇杷叶、兰叶、石斛、归身、枸杞为方，加野蔷薇露和服。一剂苔即化，三服而结粪下，胸乃舒。去蒌仁，加西洋参。服四帖，苔净能餐，诸恙冰释。续投峻补肝肾而康。", "13021": "翁笠渔素健啖，偶患发热。钱某谓劳倦内伤，进补中益气法，病日剧。张某诊为停食感冒，用承气法下之，连解黑矢，热如故。与养阴药多剂，热仍不退，且从此不食不便，不渴不眠。金云攻补难施，已成坏证。所亲孙诒堂迓孟英诊之，脉形涩数不调，神呆静卧，倦于语言，溺少苔黄，时时面赤，曰：无虑也。卫分之邪失于清解，补中益气，实卫锢邪，何异适燕而南其指乎？承气通腑，但能下其肠胃有形之物，不能散其卫分无形之邪。下后养阴，固是方法，然必表里皆和者，方可投之。卫气未清，徒增窒滞，枢机日钝，此神识之所以如呆也。升降失司，此出入之所以皆废也。延之虽久，病犹在卫，故可治也。予苇茎、葱豉，加芩、桔、栀子、栝蒌，服一剂而遍身赤疹，神气爽悟。乃去芩、桔、葱，加雪羹、芦菔、银花、兰叶。服数帖，解酱矢二十余次，苔退知饥，脉和而愈。", "13022": "一铁匠妇患感，杂治经旬，身热不退，不眠妄语，口渴耳聋，求治于余。脉来细数，唇红面白，肌瘦汗频。虽是贫家，却为娇质，神虚液夺，余暑未清。以西洋参、甘草、小麦、黄连、麦冬、石斛、丹参、莲心、竹叶为剂，服之神气遂安。自云心悸，因加红枣与紫石英服之，浃旬竟以告愈。", "13023": "七月初旬，余游鸳湖归，三侄寿和陡患凛寒，身热筋瘛，面红，谵妄汗频，四肢厥冷。年甫六岁，其母危之。余察其苔色黄腻，口渴唇红，乃停食感冒耳。以枳实栀豉汤加菖蒲及冬干之芦菔叶煎成，调入玉枢丹五分灌之。次日谵瘛皆减。而腹痛微有吐泻，寐醒则神犹瞀乱，知其邪有外泄之机，治当迎刃而导。于前方加苏叶一分、黄连二分，同炒煎服。连吐三五次，泻六七次，痛即减，第三日神清爽朗。余曰：去疾莫如尽。再服原方一帖遂愈。盖小儿之病，因于食滞者多。胃不和则卧不安，阳明实则谵妄，而世人辄作惊风治之，每致偾事。昧者更惑于巫瞽，而祭非其鬼，则尤可笑也。八月初余游虎林归，二女定宜患感旬余，热虽退而干咳无痰，不眠、不食、不便，胸腹无所苦，汤饮亦不思，五热形瘦，佥虑成劳。余按脉弦细，是痰阻而气不通也。以紫菀、白前、蒌仁、薤白、橘红、半夏、菖蒲、竹茹、枳壳、桔梗，服数帖渐愈。三女杏宜年十四，因侍姐病过劳，且浃旬风雨，寒气外侵，而自恐不支，勉强纳食，起病则凛寒微热，腿肿而酸，泛泛欲呕，兼以微嗽，适余归之次日也。视其苔微黄而腻，尖微绛，脉缓滑，以枳实栀豉汤加前、苏、杏、桔、芩、菔饮之。日晡余游南乡归，内子述服药后，神情昏瞀，呕出药食。恐夹痧邪，曾为刮背。余谓此食滞上焦，浊未下行耳。迨夜颇静，诘朝察之，胸仍拒按，原方加菖蒲、紫菀投之。余即游硖川，黄昏而归，内子云：午后神复瞀乱，恐有变证，明日君毋他往也。余颔之。夜间亦静，次早问答如常，胸犹拒按。因其吐既未畅，大便未行，以前方合小陷胸为剂，外用朴硝罨其胸次。至己刻又神昏如寐，引衣自覆，呼之不应，时或妄言，面色晦滞，四肢时冷，内子对之下泪。余按脉如故，确系浊气上熏，清阳失布。既非寒邪深入，亦非温热逆传。原方再服一帖，病如故。余再四思维，径以薤白、石菖蒲各一钱，蒌仁三钱，煎成，和入醇酒一杯灌之。外用葱白杵罨胸次，牙皂末吹鼻取嚏。时将薄暮，至初更始得微汗而肢和。寻即溏解一次而识人，夜分安眠。第四五日，胸次已舒，略无谵语，乃目有妄见，寐即恶梦，时有潮热。余以蒌、薤、菖、茹、翘、薇、菀、半、栀、豉、省头草等药，通府涤浊。连解三次，各恙皆平。改用清肝肃肺法，至七朝身凉全愈。继治蒋君寅昉五令郎全官，身热筋瘛，不啼不乳，神呆嗜卧。或疑惊风，夤夜延余往视，乃风热夹食也。与开泄清解法数帖，便行而痰渐嗽出，病即渐瘥。此等虽非大证，设稍误治，告危极速，故连类录之，以备大匠木屑竹头之需。", "13024": "马某年三十余，素用力，患发热恶寒，肢振自汗，少腹气上冲胸，头疼口渴。孟英诊曰：卫虚风袭，而络脉久伤，肝风内动，与建中去饴，加龙、牡、石英、苁蓉、楝实、桑枝，（建中之力在饴糖，今去饴，仍是桂枝法。）数帖而痊。（发热恶寒，头疼自汗，皆桂枝证。此人必津液素亏，因汗出而益耗其津，故肝失所养，而上冲肺胃，失所养而口渴也。）", "13025": "《寓意草》谓伤风亦有戴阳证，此为高年而言，然有似是而非者。黄鼎如令堂，年登大耋。季冬感冒，痰嗽气逆，额汗颧红，胸痞不饥，神情躁扰。孟英诊脉，左弦疾而促，右滑数而溢，苔色满布。系冬温挟痰阻肺，治节不伸，肝阳鼓舞直升。罗谦甫有治痰火类孤阳之案，颇相似也。以小陷胸汤加薤白、旋覆、赭石、花粉、海䖳、凫茈、竹沥为大剂投之，痰活便通，数日而瘥。继有陈舜廷之父，年逾花甲，患痰嗽气逆，惟饮姜汤则胸次舒畅。医者以为真属虚寒矣，连投温补之剂，驯致咽痛不食，苔色灰刺，便闭无溺，求孟英诊之。脉至双弦，按之索然，略无胃气。曰：渴喜姜汤者，不过为痰阻清阳之证据耳，岂可妄指为寒，迭投刚烈。胃阴已竭，药不能为矣。", "13026": "伤风虽小恙，过表伤阴，与邪未净而早投补剂，皆能延损。其高年下虚而误服升提者，往往阳浮上戴，须以温补救之。更有一种似伤风而实非伤风之证，乃根蒂空虚，肾水泛溢以成痰，浮阳冲逆而为嗽也。此自古未经道及者。今年四月十二日，孟英诣高石泉处谢吊。偶诊其脉，左关尺忽见浮弦而空。因私嘱其次郎隽生曰：尊翁之脉，颇有可虑，子其慎之！继无所苦，方疑其言之未当。虽有小恙，亦未邀诊。迨隽生登贤书，计偕有日。石泉忽患痰嗽，酷似伤风，冯某视之，与解散药一帖。次日便泻数行，黄某进分清药一剂，第三日痰升气逆，自觉唇肿不能啜饮。隽生始忆及孟英之言，速其拯治。脉如蛛丝过指，舌色晦黯无津，唇不略肿。其不能吸饮者，盖由气有出而无入耳。阴既脱于下，阳将脱于上，莫可救药。翌日云亡。此十二月春前事也。闻霜降后，许吉斋山长微患伤风，数日而逝。立春后，许砚邻亦然。皆同为似伤风证也。据孟英曰：儿子阿心，长成太速，心性太灵，余固知其不秀。秋分后，小患伤风，适余酬应纷繁，不遑顾视，且闻无甚大病，亦不延儿科诊视，不料三日倏然而殇。或云惜不早治，余谓襁褓而患根蒂之病，虽治愈亦何益哉。然则不必高年虑有此证，即小儿亦间有之矣。医者其可以伤风而概视为小恙哉。《不居集》专论伤风误补成劳，犹是一隅之见焉。", "13027": "翁嘉顺室，产后患风温，经孟英治愈。病染于姑，孟英诊曰：高年阴气太亏，邪气偏盛。《玉版论要》云：病温虚甚死。言人之真阴甚虚，曷足以御邪热而息燎原？可虞在两候之期乎。至十四天果殒。而嘉顺亦染焉，初发热即舌赤而渴，脉数且涩。孟英曰：非善证也。盖阴虚有素，值忧劳哀痛之余，五志内燔，温邪外迫。不必由卫及气，自气而营。急与清营，继投凉血，病不稍减。且家无主药之人，旁议哗然。幸其旧工人陈七，颇有胆识，力恳手援。孟英曰：我肠最热，奈病来颇恶，治虽合法，势必转重。若初起不先觑破，早已殆矣。吾若畏难推诿，恐他手虽识其证，亦无如此大剂，车薪杯水，何益于事。吾且肩劳任怨，殚心尽力以图之。病果日重，昏瞀耳聋，自利红水，目赤妄言。孟英惟以晋三犀角地黄汤，加银花、石膏、知、斛、栀、贝、花粉、兰草、菖蒲、元参、竹沥、竹茹、竹叶、凫茈、海䖳等，出入互用。至十余剂，舌上忽布秽浊垢苔，口气喷出，臭难向迩，手冷如冰，头面自汗，咸谓绝望矣。孟英曰：生机也。彼阴虚热邪深入，予一以清营凉血之法。服已逾旬，始得营阴渐振，推邪外出，乃现此苔。惟本元素弱，不能战解，故显肢冷，而汗仅出于头面，非阳虚欲脱也。复与甘寒频灌，越三日汗收热退，苔化肢温。自始迄终，犀角共服三两许，未犯一毫相悖之药。且赖陈七恪诚，始克起九死于一生。继以滋阴善后而康。（三江地气卑湿，天时温暖，伤寒之证绝少，最多湿温、风温之证。又人体质柔脆，不任荡涤之药，故惟以甘寒清解之剂，渐次搜剔，斯邪去而正不伤。若在北方，刚坚之体，此等药虽服百剂，亦若罔知。非加硝、黄荡涤，邪终不去。故叶氏之法，擅誉江浙。而吴氏之方，驰名幽冀。易地则皆然。亦智者之因地制宜也。）", "13028": "沈裕昆室，偶发脘痛，范某与逍遥法，痛颇止，而发热咽疼。邀顾听泉视之，知感温邪，与清散法，疼已而热不退。七日后，目闭鼻塞，耳聋肢搐，不言语，不饮食。顾疑证险，愿质之孟英。而沈之两郎，乃从王瘦石学，因请决于师。瘦石亦谓孟英识超，我当为汝致之。时已薄暮，乃飞刺追邀。比孟英往诊，见其外候如是，而左手诊毕即缩去，随以右手出之，遽曰：非神昏也。继挖牙关，察其苔色白滑，询知大解未行，曰：病是风温。然不逆传膻中，而顺传胃府，证可无恐。听泉学问胜我，知证有疑窦，而虚心下问，岂非胸襟过人处？但温邪传胃，世所常有。而此证如是骇人者，因素有痰饮，盘踞胃中。外邪入之，得以凭借。苔色之不形黄燥者，亦此故耳，不可误认为寒。夫温为热邪，脉象既形弦滑以数。但令痰饮一降，苔必转黄。此殆云遮雾隐之时，须具温太真燃犀之照，庶不为病所欺。且昔人于温证仅言逆传，不言顺传，后世遂执定伤寒在足经，温热在手经。不知经络贯串，岂容界限。喻氏谓伤寒亦传手经，但足经先受之耳。吾谓温热亦传足经，但手经先受之耳。一隅三反，既有其逆，岂无其顺？盖自肺之心包。病机渐进而内陷，故曰逆。自肺之胃府，病机欲出而下行，故曰顺。今邪虽顺传，欲出未能，所谓胃病则九窍不和，与逆传神昏之犀角地黄汤证大相径庭。郭云台云：胃实不和，投滚痰而非峻，可谓治斯病之真诠，遂疏小陷胸合蠲饮六神汤，加枳、朴，以芦菔煮水煎药，和入竹沥一杯，送下礞石滚痰丸四钱。沈嫌药峻，似有难色。孟英曰：既患骇人之病，必服骇人之药。药不瞑眩，厥疾勿疗，盍再质之瘦石、听泉乎？沈颔之。王、顾阅方，佥以为是，且云如畏剂重，陆续徐投可也。翌日，孟英与听泉会，诊脉证不甚减，询知昨药分数次而服，孟英曰：是势分力缓之故也。今可释疑急进，病必转机。听泉深然之，病家亦胆壮矣。如法服下，黎明果解胶韧痰秽数升，各恙即减，略吐语言，稍啜稀粥，苔转黄燥。药改轻清，渐以向安。嗣与育阴柔肝而愈。", "13029": "金禄卿室，沈裕昆之女也。患温，顾听泉连进轻清凉解而病不减，气逆无寐，咳吐黏痰，舌绛咽干，耳聋谵语，旬日外始延孟英诊焉。曰：体瘦，脉细数，尺中更乱，竟是阴气先伤，阳气独发，所谓伤寒偏死下虚人。譬之火患将临，既无池井，缸贮又空，纵竭心力，曷能有济？再四研诘，乃知发热前一日，陡然带下如崩，是真液早经漏泄矣。否则药治未讹，胡反燎原益炽，痉厥之变，不须旋踵。禄卿坚恳勉图，孟英以西洋参、生地、二冬、二至、元参、犀角、黄连、鸡子黄、知母为方。另用石斛、龟板、鳖甲各四两，左牡蛎一斤煮汤代水煎药。顾听泉又加阿胶，且云：我侪用此育阴镇阳，充液息风大剂，焉能津枯风动、痉厥陡生乎？服两剂果不能减。后惑旁言而祷签药，附、桂、干姜，罔知顾忌，径至四肢拘挛而逝。是误药速其毙而增其惨也。继而裕昆患湿温，亦犯重暍而亡。珠小辉太守令嫒，骤患颐肿，（此俗所谓蛤蟆瘟也。）连及唇鼻，乃至口不能开，舌不得出，孟英视之曰：温毒也。用射干、山豆根、马勃、羚羊、薄荷、银花、贝母、花粉、杏仁、竹黄为剂。（仿普济消毒饮意）并以紫雪搽于唇内，锡类散吹入咽喉，外将橄榄核磨涂肿处，果吐韧涎而肿渐消，诘朝即啜稀粥，数日而愈。", "13030": "许子双令堂梁宜人，仲春之杪，偶患微感，医与温散，热已渐退。孟英偶过诊，右寸脉促数不调，因谓子双曰：此风温证，其误表乎？恐有骤变。渠复质之前医，以为妄论，仍用温燥。越二日，即见鼾睡。再延孟英诊之，促数尤甚，曰：鼻息鼾矣，必至语言难出，仲圣岂欺我哉？风温误汗，往往皆然。况在高年，殊难救药，果浃旬而逝。（此证虽经仲景指出，而人多不识、往往杂药乱投，卒至鼾睡而死，医家、病家两俱茫然。孟英此案可为仲景之功臣矣。）", "13031": "姚某年未三旬，烟瘾甚大。适伊母病温而殁，劳瘁悲哀之际，吸受温邪，胁痛筋掣，气逆痰多，热壮神昏，茎缩自汗，医皆束手。所亲徐丽生嘱其速孟英诊之，脉见芤数，舌绛无津，有阴虚阳越、热炽液枯之险。况初发即尔，其根蒂之不坚可知。与犀、羚、元参、知母，壮水息风；苁蓉、楝实、鼠矢、石英，潜阳镇逆；沙参、麦冬、石斛、葳蕤，益气充津；花粉、栀子、银花、丝瓜络，蠲痰清热。一剂知，四剂安，随以大剂养阴而愈。（吸食鸦片之人，津液素亏，感受温邪较平人倍重。非此标本并治之剂，必不救矣。）", "13032": "姚令舆室，素患喘嗽而病春温。（新旧合邪。）医知其本元久亏，投以温补，痉厥神昏，耳聋谵语，面青舌绛，痰喘不眠，（肺原包心而生，故肺热必及于心。）皆束手矣。延孟英诊之，脉犹弦滑，曰：证虽危险，生机未绝，遽尔轻弃，毋乃太忍？与犀角、羚羊、元参、沙参、知母、花粉、石膏，以清热息风，救阴生液；佐苁蓉、石英、鳖甲、金铃、旋覆、贝母、竹沥，以潜阳镇逆，通络蠲痰。三剂而平，继去犀、羚、石膏，加生地黄，服旬日而愈。仲秋令舆病，竟误服温补，数日而殒，岂非命耶？", "13033": "韩组林年近古稀，孟冬患肢厥头肿，谵语遗溺。包某作虚风类，进以温补，势益剧。孟英脉之，脉弦数右滑溢，乃痰热内阻，风温外侵，与羚、贝、茹、栀、翘、薇、桑、菊、丹皮、花粉、旋覆，以芦菔汤煎服而瘳。", "13034": "余侄森伯，患发热面赤，渴而微汗，孟英视之，曰：春温也。乘其初犯，邪尚在肺，是以右寸之脉洪大，宜令其下行，由腑而出，则即可霍然。投知母、花粉、冬瓜子、桑叶、杷叶、黄芩、苇茎、栀子等药，果大便连泻极热之水二次，而脉静身凉，知饥啜粥，遂痊。设他人治之，初感总用汗药，势必酿成大证。", "13035": "陈建周令郎，患春温，初起即神气躁乱，惊惧不眠，两脉甚数。孟英谓温邪直入营分也。与神犀丹，佐紫雪，两剂而瘥。夏间，吴守旃暨高若舟令郎、胡秋纫四令爱患温，初起即肢瘛妄言，神情瞀乱，孟英皆用此法，寻即霍然。世人每执汗解之法，为初感之治。孰知病无定体，药贵得宜，无如具眼人稀，以致夭枉载道，归诸天数，岂尽然哉！", "13036": "王皱石广文令弟，患春温，始则谵语发狂，连服清解大剂，遂昏沉不语，肢冷如冰，目闭不开，遗溺不饮，医皆束手。孟英诊其脉弦大而缓滑，黄腻之苔满布，秽气直喷。投承气汤，加银花、石斛、黄芩、竹茹、元参、石菖蒲，下胶黑矢甚多，而神稍清，略进汤饮。次日，去硝、黄，加海䖳、芦菔、黄连、石膏。服二剂，而战解肢和，苔退进粥，不劳余力而愈。继有张镜江邀治叶某，又钱希敏之妹丈李某，孟英咸一下而瘳。惟吴守旃之室，暨郑又侨，皆下至十余次始痊。今年时疫盛行，医多失手，孟英随机应变，治法无穷，救活独多，不胜缕载。（此正吴氏所谓凉药无涤秽之功，而反冰伏其邪也。吴又可之法，切于疫而不甚切于温，观此可见。）", "13037": "又顾氏子患发热，独炽于头，医进发散，汗出不解，胸次痞闷，便滞溺艰，舌绛口干，饮不下膈，不眠头痛，脉数而弦。孟英曰：体质素虚，热薄于肺，痰结于胸，治宜轻解，羌、防、柴，葛，恶可妄投？膏粱与藜藿有殊，暑热与风寒迥异。治上焦如羽，展气化宜轻。以通草、苇茎、冬瓜子、丝瓜络、紫菀、枇杷叶、射干、兜铃、白前九味，天泉水急火煎服，复杯即已。盖席丰履厚之家，密室深居，风寒湿三气所不能侵，惟暑燥之邪易于吸受，误用温散，最易劫津。若田野农夫，栉风沐雨，肌坚气实，当用辛温。设进轻清，焉能济事？故医者须量体以裁衣，弗胶柱而鼓瑟也。（炳按：汪谢城云：复杯即已。下宜删去，以言过当也。若然则藜藿人温证暑证，亦可用辛温矣。此评甚是。）", "13038": "关寅伯赞府家某厨患春温，渠主人颖庵治之弗瘳，为速孟英诊焉。脉来弦软而寸数，舌绛苔黑而神昏，谵渴溺红，胸腹拒按，是双传证也。夫顺传者宜通其胃，逆传者宜清其营，治法不容紊也。然气血流通，经络贯串，邪之所凑，随处可传，其合其分，莫从界限。故临证者宜审病机而施活变，弗执死法以困生人。此证属双传即当双解，予凉膈散加犀角、菖蒲、元参下之，果愈。", "13039": "梅里任会嘉令正，年逾五旬，季春患证渐剧。访余视之，身热头疼，凛寒胸闷，气冲不寐，神惫音低，口渴嗽痰，干呕便闭，脉甚细软。延已旬余，咸以为虚，欲投补剂。余谓阴分虽亏，气郁痰滞，温邪留恋，胡可补邪？轻展清宣，庶乎合拍。以葱豉合小陷胸，加南沙参、射干、马兜铃、通草、竹茹，二剂，而热退呕止。去葱、豉、兜、射，加栀、贝、芩、菖，三帖而便行，胸适得寐知饥。改投柔木涵阴而愈。", "13040": "季秋，顾听泉邀孟英视康康侯副转之恙，切其脉滑数，而右歇左促，且肝部间有雀啄，气口又兼解索，望其面宛如熏黄，头汗自出，呼吸粗促，似不接续，坐卧无须臾之宁，便溺涩滞，浑赤极臭，心下坚硬拒按，形若覆碗，观其舌色，边紫苔黄，殊不甚干燥，问其所苦，曰：口渴甜腻，不欲饮食，苟一合眼，即气升欲喘，烦躁不能自持，胸中懊𢙐，莫可言状。孟英曰：此由湿热误补，漫无出路，充斥三焦，气机为其阻塞而不流行，蔓延日久，津液为之凝滞而成痰饮。不啻人禽杂处，苗莠同畴，邪正混为一家。医见肢冷自汗，不知病由壅闭而然。欲以培正，而邪气方张，得补反为树帜，岂非资寇兵而赍盗粮哉！非其类者锄而去之，乃为吃紧之治。听泉曰：良是也。夏间起病，闻自心悸少寐，杨某以为虚而补之。时尚出差办事，暑湿外侵，受而不觉，迨闱差未竣，其病斯发，而诸医之药，总不外乎温补一途，以致愈补愈剧。今拟温胆法待君可否？孟英曰：脉证多怪，皆属于痰。今胸痞如斯，略无痰吐，盖由痰能阻气，气不能运痰耳。宜于温胆中，加薤白、蒌仁，通其胸中之阳；又合小陷胸，为治饮痞之圣法；参以栀豉，泄其久郁之热，以除懊𢙐；佐以兰草，涤其陈腐之气而醒脾胃。听泉深然之，连投二剂，各恙皆减，脉亦略和。而病者以为既系实证，何妨一泻而去之，连服大黄丸二次，承气汤半帖。孟英急止之，曰：畏虚进补固非，欲速妄攻亦谬。盖湿蒸为热，灼液成痰，病非一朝一夕而成，治以上下分消为是。不比热邪传府，可一泻而愈也。越日，下部果渐肿。孟英曰：攻痞太速之戒，古人不我欺也。与听泉商，以前法加黄芩，合泻心意，再配雪羹投之，痰果渐吐，痞亦日消。而自腹至足，以及茎囊，肿势日加。孟英谓势已如此，难以遽消，但从三焦设法，则自上而下，病必无虞。与听泉商，用河间桂苓甘露饮意。而姚平泉孝廉，力主崇土胜湿之法，深以寒凉为不可用。众议仍投前日之药，孟英曰：前药原可服也，嫌力不足耳。次日，痰中带血甚多，孟英曰：湿热薰蒸不已，自气及营矣。与听泉暨王子能参军商，以知、柏、生地、犀角、鳖甲、白芍、苡仁、贝母、石斛、茅根、麦冬、滑石、栀子、藕汁、童溺，投之而止。逾数日又吐，且肢冷自汗，心馁畏脱。姚平泉谓气不摄血，当主归脾汤以统之。举家皇皇，连请诊脉者三次，孟英曰：脉来屡变，陈芝江所以不能指实其病，而杨阮诸人，皆疑为大虚之候也。然望闻问切，不可独凭于指下。今溲如赭石汤，浑赤有脚，其为湿热之病，昭昭若揭。初伤于气分，则津液受灼以为痰。渐及于营分，则阴血不安而妄溢。邪气内盛，岂非病实？而真实类虚，吾不受病之欺也。坚守前议，静镇不摇。服二剂果止。孟英曰：血之复吐也，由于气分之邪以扰及也。欲清气道之邪，必先去其邪所依附之痰。盖津液既为邪热灼烁以成痰，而痰反即为邪热之山险也。不妨峻攻其实，而缓行其势。初进滚痰丸三钱，得下泄气一次。副转云：四十日来未有之通畅也。连投数日，始解胶痰黑矢多遍，而小溲亦渐清长，苔色亦退，寝食遂安，惟下部之肿犹尔也。马香崖、陆虚舟皆主实脾行水之法，孟英曰：谛参脉证，病不在脾，况善饥便燥，口渴溺多，吾方虑转消证，亟投甘润之不遑，恶可渗利伤阴、补土劫液耶？且脾虚下陷之肿，与湿盛而肿之肿，其膝之上下、内外形势，必然相贯，今膝之上下、内外、凹凸迥判，毫不毗连。盖由湿热所酿之痰饮，既误补而痞塞中焦，复妄攻以流窜隧络，所谓不能一荡而蠲，势必旁趋四射，吾当以法取之。会又咳痰带血，而精神食饮如常，孟英曰：无恐也。此乃前次嚼三七太多。兜涩留瘀，最不宜用，吐而去之极妙。但须金水同治，冀咳止而血络不震动为要耳。与甘露饮，加藕汁、童溺服之，四剂而止，咳嗽亦宁。于是专治其下部之肿，以固本加知、柏、贝母、花粉、旋覆、橘络、丝瓜络、羚羊角、楝实、葱须、豆卷、薏苡、竹沥，出入为剂。二三帖间，其高突隆肿之处，即觉甚痒，搔之水出如汗，而作葱气。六七日后，两腿反觉干瘦燥痛，茎囊亦随之而消矣。孟英曰：用此润药消肿，尚且干痛咽燥，设从他议而投燥脾利水之法，更当何如哉？盖寒湿则伤阳，热湿则伤阴，血液皆阴也。善后之法，还宜滋养血液，稍佐竹沥以搜络中未净之痰，使愈后不为他日之患，更属法中之法。服之饮食中节，便溺有权，幸无消渴之虞，而竟愈焉。（前云不可妄攻，此又投峻下之剂，何也？盖前徒攻其热，故不中病，而致生他证。此则直攻其痰，始能与病相当也。）", "13041": "邵鱼竹给谏患感，杨某作疟治不应，始迓孟英诊之。脉软汗多，热不甚壮，（热为湿所持故脉软。）苔色厚腻，呕恶烦躁，痰多腿酸，显是湿温。因谓其令郎子旃曰：湿温者，湿蕴久而从时令之感以化热也，不可从表治，更勿畏虚率补，与宣解一剂，各恙颇减。奈众楚交咻，谓病由心力劳瘁而来，况汗多防脱，岂可不顾本原？群医附和，遂服参、归、熟地之药。（增湿益热，宜乎不救。）病日以剧。最后吴古年诊之云：此湿温也，何妄投补剂？然已末从挽救。交十四日而殒，始悔不从王议。", "13042": "仲秋久雨，吴汾伯于乡试后患恙，自言坐于水号，浸及于膝，人皆以为寒湿之病。孟英切脉甚数，溲赤苔黄，口干燥呛，因谓其尊人酝香曰：病由暑湿，而体极阴亏，已从热化，不可以便泄而稍犯温燥之药。先与轻清肃解，继用甘凉撤热，渐能安谷。半月后，热始退尽，而寝汗不眠，投以大剂滋填潜摄之药，兼吞五味子磁朱丸数十帖，乃得康复。此证误治即败，少谬亦必成损。苟非诚信于平日，焉能诚服于斯时？闻其寝汗不收，夜不成寐之间，旁言啧啧。孟英恐其摇动主意，必致全功尽弃，嘱其邀顾听泉、许芷卿质政，而顾、许咸是孟英议，于是主人之意甚坚，而大病乃痊，吁！谈何易耶！", "13043": "翁嘉顺之妇弟吴某，劳伤之后，发热身黄，自以为脱力也。孟英察脉软数，是湿温重证，故初起即黄。亟与清解，大便渐溏，小溲甚赤。湿热已得下行，其热即减。因家住茅家埠，吝惜舆金，遽尔辍药。七八日后复热，谵语昏聋，抽痉遗溺，再恳孟英视之。湿热之邪扰营矣。投元参、犀角、菖蒲、连翘、竹茹、竹叶、银花、石膏，泄卫清营之法，佐牛黄丸、紫雪丹而瘳。臀皮已塌，亟令贴羊皮金，不致成疮而愈。", "13044": "庆云圃观察令郎，恩荫堂司马，陡患偏坠，医与茴香、芦巴、乌药、荔核等剂，遂痛不可忍。浼赵棠村鹾尹邀孟英视之，按其脉肤甚热，曰：非疝也。睪丸肿痛，必偏于右，此湿热时邪也。设以疝治之必成痈。按法治之，果复杯而痛减，三服而便行热退。因食羊肉，肿痛复作，再与清解，谆嘱慎口腹而瘳。", "13045": "吴宪章年逾花甲，患感，医知其为湿温也，投药不应，而仍能起榻理事。石北涯拉孟英视之，冀其勿致加剧。及诊脉左寸数疾，余皆软大，谷食略减，便溏溲少，苔色腻黄，舌尖独黑，孟英不肯予方，人咸诧之，因曰：证原不重，吾以脉象舌色察之，是平昔曲运心机，离火内亢，坎水不制，势必自焚，况兼湿温之感乎？果数日而殒。", "13046": "黄纯光年七十八岁，患湿温，至旬余，脉形歇代，呃忒连朝，诸医望而畏之。孟英诊曰：脉虽歇，而弦搏有根，是得乎天者厚，虽属高年，犹为实象。参以病深声哕，原非小故，而二便窒涩，苔腻而灰，似府气未宣，痰湿热阻其气化流行之道也。清宣展布尚可图焉，何新之韪其议。因以旋、茹、栀、楝、杷、杏、萸、连、菀、蒌、雪羹为剂，片通草一两煎汤煮药，投匕即减。数服而大吐胶痰，连次更衣，遂安粥食。惟动则嗽逆，渐露下虚之象。予西洋参、龟板、牡蛎、苁蓉、石斛、牛膝、冬虫夏草、石英、茯苓、当归等药，而各恙递安，继加砂仁、熟地而起。", "13047": "沙沛生鹾尹，患身热头重，腹胀便溏，脘闷不饥，口流涎沫，腿酸溺少，脉软神疲。孟英诊曰：内湿素盛，兼吸客邪，不可谓值此亢旱之年，竟无泛滥之病也。予槟、朴、蔻、苓、猪、泽、橘、半、防己、秦艽之剂，小溲虽行，其口涎水流出尤多，病遂以愈。既而其子龙官初次患疟，耳聋舌绛，溺赤痰多，脉数而弦，寒微热甚。幼科云胎疟不能即愈，孟英曰：此齐东野语也。予滑石、竹茹、知母、花粉、苓、翘、橘、半、青蒿、鳖甲，八帖而痊。", "13048": "沈南台，年三十七岁，初冬在乡收租，将归饱啖羊肉面条，途次即发热头疼。到家招沈某视之，谓其体丰阳气不足。以致伤寒夹食。表散消导之中，佐以姜附。数帖后，热壮神昏，诸医束手。交八日，所亲许锡卿、吴久山交荐孟英图之。苔色黄腻，口不甚渴，粒米不沾，时时火升，汗躁谵语，溲赤便秘，面晦睛红，呼吸不调，胸前拒按，脉则虚软，微带弦滑，不甚鼓指，曰：体气素亏，然脉证太觉悬殊，必因痰阻清阳，故气壅塞而脉更无力也。剂以小陷胸合雪羹，加旋、菖、薤、枳、栀子、胆星，服后痰即吐，脉较起。再服谵语息，三服痰中带出紫血数块，四服热退而汗躁胥蠲。七服苔净胸舒，溲长口渴，改予甘凉濡润之法。服数帖痰已渐少，舌布新苔而仍不更衣，觉有秽气上冲，亦不知饥，仍予甘凉养胃，佐以兰叶、野蔷薇露，降其浊气。数帖后，秽气除，粥食进，但不大解，家人忧之，孟英曰：既无所苦，能食脉和，静俟水到渠成，不可妄行催动也。既而加谷起床，便犹不解。病者停药旬日，计起病已交一月矣。粥嫌不饱，意欲食饭，复请孟英商之，孟英曰：可食也。药则不当停，亟宜培养涵濡，俾其转运也。授参、术、归、苁、杞、麻、半、芍，少佐枳壳为方。服十二剂，始得畅解坚矢。嗣与峻补善后，寻即复元。续有宣氏妇脉体极虚，患温而胸次痞闷，苔黄垢腻，医皆畏难而退。孟英以轻清肃化之药数剂，苔退胸舒，即能进粥。随予生津养血，又旬日更衣而愈。观此则黄苔宜下之说，须合脉体以为可否也。", "13049": "癸卯春，邵秋子令堂，年近六旬，患寒热如疟者久矣。诸医杂治罔效，孟英视之曰：此湿邪久蕴，已从热化，误投提补，动其肝阳，痰饮因而上逆。与通降之法，寒热即减。而包某谓疟久阴虚，理宜滋养。病家闻之近是，遂进首乌、鳖甲等药，渐至脉伏胸痞，呃忒自汗，渴饮不食，颧赤便泄。包某束手，疏生脉散以塞责，举家彷徨。再求孟英诊之，曰：此滋腻阻塞气机，清阳不司旋运，（喜用熟地者鉴之。）痰饮闭滞隧络，非脱象也，补药不可进。以栝蒌、薤白，合小陷胸，加菖蒲、竹茹、旋覆、贝母、杏仁、紫菀、枇杷叶投之，呃止脉出，（清热涤饮，旋转气机，以救滋腻之失。）大有转机。而郑某谓病固属痰，须温热以宣通，勿寒凉而凝遏，病家又惑焉。姜桂频投，既而唇肿咽疼，不能进饮，舌干短硬，难出语言。复请孟英救疗，与犀角地黄汤，加元参、知母、银花、竹黄、花粉、胆星、石菖蒲、竹沥之类，（甘寒生津以救燥烈之失。）六七剂吐出极臭胶痰甚多，粥饮渐进，此第三次生机也。奈狂澜莫障，邪说横行，辄以凉药不宜擅服，久病必定元虚，甘言悦耳，遂至升散温补，各逞所能；符咒乩方，罔不偏试。延至仲夏，腭腐龈糜，唇高数寸，竟成燎原莫救。仍恳孟英设法，乃坚辞不能措手。付局医黄某敷治，肿烂日甚而终。", "13050": "戴氏妇，年五十六岁，仲冬患感。初服杨某归、柴、丹参药一剂，继服朱某干姜、苍术、厚朴药五剂，遂崩血一阵，谓其热入血室，不可治矣。始延孟英诊之，脉形空软促数，苔黑舌绛，足冷而强，息微善笑，询其汛断逾十载，曰：冬温失于清解，营血暴脱于下，岂可与热入血室同年而语耶？必由误服热药所致。因检所服各方而叹曰：小柴胡汤与冬温何涉？即以《伤寒论》亦不能初感即投。况以丹参代人参，尤为悖谬。夫人参补气，丹参行血，主治天渊。不论风寒暑湿各气初感，皆禁用血药，为其早用反致引邪深入也。既引而入，再误于辛热燥烈之数投，焉得不将其仅存无几之血，逼迫而使之尽脱于下乎。女人以血为主，天癸既绝，无病者尚不宜有所漏泄，况温邪方炽，而阴从下脱，可不畏哉。病家再四求治，孟英与西洋参、苁蓉、生地、犀角、石斛、生芍、银花、知母、麦冬、甘草、蔗浆、童溺，两剂足温，舌润，得解酱粪，脉数渐减而软益甚。乃去犀角，加高丽参，数帖，脉渐和，热退进粥。随以调补，幸得向安。（即热入血室，亦岂不可治之证。可见此人并不知热入血室为何病，第妄指其名耳。）", "13051": "王开荣素患痰嗽，兼有红证。今冬病头疼发热，渴饮不饥，便溏溺少，谵语神昏，自述胸中冷气上冲。医见其面赤痰喘，欲投附、桂、黑锡丹等药。所亲翁嘉顺嘱勿轻服，为延孟英诊之。脉滑且数，曰：温邪挟宿饮上逆，法当清解，与北沙参、冬瓜子、知母、滑石、花粉、石菖蒲、贝母、杏仁、芦根、葱白、淡豉、竹沥。两剂后面赤退，乃去葱豉，加麦冬、桑叶、枇杷叶。数帖热去泻减，谵语止，头痛息，喘定神清，乃裁菖、滑，加梨汁、地栗、海䖳。服数日，痰渐少，欲渐安，渴止溺行。始进养阴法，遂以霍然。（此人胃气素不清肃，又兼阴虚挟饮，故感受温邪，弥见𫐖轕。非此始终如法施治，殊难奏效也。）", "13052": "石子章患腹胀，朱某与大剂温补之药，殊若相安，孟英见而非之。彼云：服之略不助胀，正须多服图痊，君何疑焉。孟英曰：形瘦脉数，舌色乾红，此为阴虚热胀。昔年范次侯室暨杨改之如君之恙皆类此，医咸攻补偏施，病无小效。吾以极苦泄热微辛通络之法投之，应手而瘳。今子病初起时，胀不碍食，证非气分可知，而温补不助胀，遂服之不疑。不知阴愈耗，络愈痹，胀虽不加，而肌愈削，脉愈数，干呛气急，与女子之风消、息贲何以异耶？寻果不起。予按：喻氏始言男子亦有血蛊证，可见男女虽别，而异中有同，同中有异，临证者不可胶柱以鼓瑟也。", "13053": "沈春旸之母，偶患咽喉微痛，服轻清药一剂，即觉稍安，且起居作劳如常。第五日，犹操针黹至四鼓。第六日，忽云坐立不支，甫就榻即昏沉如寐。亟延王瘦石视之，用犀角地黄汤，化万氏牛黄丸灌之。继邀徐小坡，亦主是汤。云：恐无济。乃邀孟英决之。切其脉，左数右滑，皆极虚软，曰：王、徐所见极是。但虽感冬温，邪尚轻微。因积劳久虚之体，肝阳内动，烁液成痰，逆升而厥，俨似温邪内陷之候。方中犀角靖内风，牛黄化痰热，不妨借用，病可无虞，今日不必再投药饵矣。翼日复诊，神气虽清，苔色将黑，孟英与肃肺蠲痰、息风充液之剂，热退而苔色松浮。孟英曰：舌将蜕矣。仍与前药。越宿视之，苔果尽褪，宛如脱液之舌。且呕恶时作，大解未行。孟英于甘润生津药内，仍佐竹茹、竹沥、柿蒂、海䖳。数剂呕止便行，而舌上忽布白腐之苔，以及齿龈唇颊，满口遍生，揩拭不去。人皆异之，孟英坚守清肃肺胃，仍佐茹、沥，加橄榄、银花、建兰叶。数剂，白腐渐以脱下，舌色始露。惟啜粥则胸次梗梗不舒，夜不成寐。孟英曰：胃汁不充，热痰未净也，仍守前议。病家疑之，复商于瘦石，瘦石云：勿论其他，即如满口腐苔，酷似小儿鹅白，大方证甚属罕见，苟胸无学识者见之，必按剑而诧。今医者有不惑之智，而病家乃中道生疑，岂求愈之道耶。沈大愧服，一遵孟英设法。既而吐痰渐少，纳谷颇适，两胁又添辣痛。孟英诊脉，左关弦数，曰：必犯忿怒矣。诘之果然。加栀、楝、旱莲、女贞、生白芍、绿萼梅等，数服各恙皆安。肤蜕成片，而右腿肿痛不能屈伸。或疑风气，思用艾灸，孟英急止之曰：此阴亏耳，误灸必成废疾。吾以妙药奉赠，但不许速效也。疏方以西洋参、熟地黄、苁蓉、桑椹、石斛、木瓜、归、芍、二冬、杞、菊、楝实、牛膝，加无核白蒲桃干为剂，久服果得向愈。越三载以他疾终。", "13054": "吴馥斋室，春间娩子不育，汛事亦未一行。偶患呕吐发热。眩晕心嘈，大解溏泄，口渴溲痛。或疑其娠，或疑为损，孟英诊曰：产及一载，而经不至，腹不胀，脉弦缓，非娠非损，乃血虚痰滞，而感冬温也。以羚羊、淡豉、竹茹、白薇、栀子、杷叶、知母、葱白、花粉投之，三剂热退吐止。去葱、豉、羚羊，加生地、甘草、橘皮，调之而愈。", "13055": "张肖江妹，暮冬患感。朱某进温散药数服，病日剧。比孟英视之，目瞪不语，面赤气逆，昼夜需人抱坐，四日不著枕矣。乃冬温挟痰，误提而气不肃降也。以旋、赭、杏、贝、花粉、茅根、冬瓜子、紫菀、薤白、蒌仁、苏子、石菖蒲、竹沥为剂，芦菔汤煎。三帖大便行而能卧矣，自言胸中迷闷，改用小陷胸合三子养亲，加沙参、知母、旋、贝、竹茹、枇杷叶。数剂热退，知饥而愈。嗣有王炳华子患感，叶某用温散药而气逆碍卧。四明老医王秉衡，作肾虚不能纳气治，连服大剂温补，喘嗽益剧，面浮跗肿，抬肩自汗，大渴胁痛，乞治于孟英，已半月不交睫矣。诊其脉，右部弦大而强，舌根黑苔如煤者两条，面黧形瘦。幸而大解溏泄，得能消受许多误药。径与旋、赭、黄连、枳实、栝蒌、苏子、杏仁、紫菀、生石膏、芦菔汁，六大剂始能就枕，而大渴不止，脘腹反形痞胀，按之坚痛。乃去旋、赭，少加白芥子、半夏、薤白。兼令日啖北梨数十枚。服旬日，胸腹皆舒，苔色尽退。唯嗽未已，改用西洋参、杏、贝、芦根、知母、冬瓜子、花粉、柿霜、杷叶、竹沥，十许剂嗽止，而跗肿渴泻亦皆霍然矣。凡啖梨三百余斤，闻者莫不诧异。", "13056": "本朝乾纲丕振，雀顶尚红，冠饰朱缨，口燔烟草，皆为阳盛之象，是以火证偏多。夫药者补偏之物，医为救弊之人，岂可不识此大气运，而硁硁然泥夫司天在泉以论治，何异痴人说梦耶。安徽人程某，在余姑丈许辛泉典中司会计。仲冬患感，医者闻其病前一日，曾啖生芦菔一枚，而大便又溏，苔色又白。今年又为湿土在泉，遂指为中虚寒湿之病，参术附桂，多剂率投，驯致舌黑神昏，尚疑为大虚之候。禾中沈柳衣见之，知其药误，另招张镜江诊之，曰：冬温也。连与犀角地黄汤而无起色。二十日外，始乞孟英视焉。舌缩底绛，苔黑如漆，口开茎萎，脉细数而弦，右则按之如无。阴液尽烁，温毒深蟠，甘露琼浆，不能复其已竭之津矣。俄而果败。", "13057": "顾子襄体素丰，患颐肿，医投升散之药，神昏气逆，鼻衄大流。伊舅氏朱生甫明经为延孟英视之，面赤音低，不眠脘闷，大渴溺赤，脉滑数而洪，曰：冬温也。其苔色白而不燥者，内有伏痰耳；便泻如水者，肺热下迫大肠耳，岂可以为寒乎？予犀角，元参、旋覆、栀、芩、射干、竹茹、通、银花、石菖蒲服之，衄止神清，泻亦不作，去犀、射，加花粉、贝母。服二剂，解坚矢，吐胶痰，知饥热退而愈。继有朱氏子，右颈肿突，外科围药甚痛，身热不饥。孟英诊曰：冬温耳，非患痈也。敷药亟令洗净，另以芙蓉叶杵烂涂之。投以清解肺卫药，数日而痊。", "13058": "朱介眉，年逾花甲，患感于季冬。初服温散，苔色遂黑。即投白虎，胸胁大疼，面赤不眠，口干气逆，音低神惫，溺赤便溏，医者佥云不治。孟英切脉虚数而弦，是真阴素亏，痰多气郁。今年自夏徂冬，亢旱已极，所伏之邪，无非燥热。稍一温散，火即燎原。一见黑苔，即投白虎。而不知其枢机窒滞，气道未舒，且阴液耗伤，亦非白虎汤仅能涤热者之任也。予沙参、苇茎、竹茹、冬瓜子、丝瓜络，展气开痰；苁蓉、当归、紫石英、冬虫夏草，潜阳镇逆。复杯即减，旬日而瘥。", "13059": "三舍弟拜枫之室，汛后患感，孟英视曰：冬温也，而营分素亏，左腹聚气。肝阳烁液，痰阻枢机。脉数而虚，黄苔满布，腰疼碍于呼吸，口淡不饥不渴，嗽则欲呕，溲热便秘，当变法治之。初授葱、豉、连、楝、栀、薇、延胡、丝瓜络、竹茹，少加苏叶。服二剂，解溏矢，苔稍化而身热退。起榻梳发，复发热，脉尚数，改用南沙参、枇杷叶、橘、斛、栀、薇、芩、翘、芦菔。服二帖，脉数渐退，大解复行，心悸汗多，时或发热，闻有谵语，胁痛不饥，苔色根黄，即参养血。以北沙参、归身、石英、丹参、茯苓、黄连、萎蕤、甘草、小麦、红枣核为方。服三帖，虚热不作，谵语亦休，大解已坚，夜不成寐，不饥胸痞，痰滞未清也。为去后四味，加竹茹、半夏、盐橘红、姜汁炒栀子。二帖，痰果吐，胸渐舒，仍不知饥，神疲不语，脉甚细软。乃去芩、连、栀、半，加石斛、麦冬、冬瓜子、藕，而易沙参以西洋参，用陈仓米汤煎药，和入野蔷薇露。服五帖，脉渐起，神亦振。七帖后，知饥，而苔花少液。去竹茹、冬瓜子、蔷薇露，加甘草、生地、白蒲桃干。服二帖，粥食虽增，耳鸣神惫。复加枸杞，而地黄用熟者，易洋参以高丽参。服后苔净加餐，再加黄耆、杜仲而愈。惟素患带多，仿虎潜法善其后，汛至而康。", "13060": "蒋君寅昉太夫人患恙，适余在武林，专丁招往。病已七日，龈糜颐肿，寒热时形，脘闷头疼，不眠不食，苔黄便秘，脉数而弦。是冬令伏邪发为温病，血虚肝旺，禀赋使然。以枳、桔、羚、翘、栀、菖、葱头、兜铃、射干为前茅，三剂而肿消热退。以小陷胸合栀豉，加菖、苓、竹茹、雪羹开中坚，亦三剂而便畅胸舒，渐啜糜粥。以西洋参、肉苁蓉、麦冬、石斛、川贝母、竹茹、归身、知母、黄连为后劲，渐安眠食而痊。其庶祖母年八十六岁，患胸闷便秘，少腹瘕痛，夜分凛寒，两目更冷，不饮不食，口苦息粗，咸以高年为虑。按脉弦数而涩，此肝气素滞，食阻上焦，升降并愆，故脉涩而息不调也，岂可误以为正气之衰乎。进枳、桔、蒌、薤、菖、菀、苏、连、橘核、旋覆之方，投匕而瘥。次年春病复如是而较甚，余亦以此法瘳之。寅昉曾于去冬患血溢，与清舒肝胆而安。惟久患不眠，臂冷食少，自云服补心丹及知柏八味丸甚合。余曰：脉至弦细而缓，因赋质阴亏，心多思虑，五火内炽，烁液成痰，阻碍气机，故脉证如是。滋腻之药，不可再投。用沙参、丹参、丝瓜络、茅根、旋覆、橘、半、菖、苓，服十余剂而愈。", "13061": "张养之弱冠失怙后，即遘无妄之疾，缠绵七载，罄其赀财，经百十三医之手，而病莫能愈。因广购岐黄家言，静心参考，居然自疗而痊，然鼻已坏矣。抱此不白之冤，自惭形秽，乃闭户学书，专工作楷，其志良可悼也。孟英因与之交，见其体怯面青，易招外感，夏月亦著复衣，频吐白沫。询知阳痿多年，常服温辛之药，孟英屡谏之。而己亥九月间，患恶寒头痛，自饵温散不效，逆孟英诊之。脉极沉重，按至骨则弦滑隐然。卧曲房密帐之中，炉火重裘，尚觉不足以御寒。且涎沫仍吐，毫不作渴，胸腹无胀闷之苦，咳嗽无暂辍之时。惟大解坚燥，小溲不多，口气极重耳。乃谓曰：此积热深锢，气机郁而不达，非大苦寒以泻之不可也。养之初犹疑焉，及见方案，辨论滔滔，乃大呼曰：弟之死生，系乎一家之命，唯君怜而救之。孟英慰之曰：我不惑外显之假象，而直断为实热之内蕴者，非揣度之见，而确有脉证可凭。但请放心静养，不必稍存疑畏。及二三帖后，病不略减，诸友戚皆诋药偏于峻，究宜慎重服之。有于某者，扬言于其族党曰：养之之命，必送于孟英之手矣。众楚交咻，举家惶惑。次日另延陈启东暨俞某并诊，孟英闻之，急诣病榻前谓曰：兄非我之知己也，则任兄服谁之药，我不敢与闻也。兄苟裕如也，则任兄广征明哲，我不敢阻挠也。今兄贫士也，与我至交也。拮据资囊，延来妙手，果能洞识病情，投剂必效，则我亦当竭力怂恿也。第恐虽识是病，而用药断不能如我之力专而剂大也。苟未能确识是证，而以无毁无誉之方，应酬塞责，则因循养患，谁任其咎也。或竟不识是病，而开口言虚，动手即补，甘言悦耳，兄必信之。我不能坐观成败，如秦人视越人之肥瘠也。今俞某之方如是，陈医殊可却之，速著人赶去辞绝，留此一款，以作药资，不无小补。况连服苦寒，病无增减，是药已对证。不比平淡之剂，误投数帖，尚不见害也。实由热伏深锢，药未及病，今日再重用硝、黄、犀角，冀顽邪蕴毒，得以通泄下行，则周身之气机，自然流布矣。养之伏枕恭听，大为感悟。如法服之，越二日大便下如胶漆，秽恶之气，达于户外，而畏寒即以递减，糜粥日以加增。旬日后，粪色始正。百日后，康健胜常。嗣后，虽严冬亦不甚畏冷。偶有小恙，辄服清润之方，阳道复兴，近添一女。养之尝颂于人曰：孟英之手眼，或可得而学也。孟英之心地，不可得而及也。我之病，奇病也。孟英虽具明眼，而无此种热情，势必筑室道旁，乱尝药饵，不能有今日矣。况不但有今日，而十余年深藏久伏之疴，一旦扫除，自觉精神胜昔，可为后日之根基。再生之德，不亦大哉！", "13062": "胡蔚堂舅氏，年近古稀，患囊肿，小溲赤短，寒热如疟。孟英曰：非外感也，乃久蕴之湿热下流，气机尚未宣泄。与五苓合滋肾，加楝实、栀子、木通。两剂后，囊间出腥黏黄水甚多，小溲渐行，寒热亦去。继与知柏八味，去山药、萸肉，加栀子、楝实、芍药、苡仁等，久服而愈。壬寅夏，感受暑湿，误投温散，以致谵语神昏，势濒于危，而肛前囊后之间，溃出腥脓，疮口深大。疡科以为悬痈也，敷治罔效。时孟英患痁未痊，予固邀其扶病一诊。孟英曰：悬痈乃损怯证，成之以渐。今病来迅速，腥秽异常，是身中久蕴厚味湿热之毒，挟外受之暑邪，无所宣泄下注而为此证。切勿敷药，以遏其外走之势。但舌强而紫赤，脉细而滑数，客邪炽盛，伏热蕴隆，阴分甚亏，深虞津涸。先与清营之剂，三投而神气渐清。次以凉润阳明，便畅而热蠲脓净。改用甘柔滋养，月余溃处肌平。善后参入参、耆，竟得康强如昔。（用药次第可法）", "13063": "仲冬大雪连朝，积厚丈许，严寒久冻，西湖可行车马。斯时也，盛少云患痰嗽夜热，自汗不寐，左胁痛如针刺，肌削不肌，自问不起矣。请孟英托以后事，及诊其脉，许以可生。盖病来虽恶，未经误药也。与固本加龟板、鳖甲、苁蓉、知、柏、青黛、石斛、花粉、白芍、楝实、海石、旋覆、贝母、蛤壳、牛膝，出入为大剂，投之即效。连服四五十帖而痊。予谓斯证患于斯时，若经别手，未有不投温补者。而少云能与孟英游，其亦具眼之人乎。此真所谓患难交，不可不留心于平日也。然亦不能人人而遇之，殆佛氏所谓有缘存乎其间欤？", "13064": "胡振华以花甲之年，患溺后出血水甚痛。自云溲颇长激，似非火证。孟英察脉有滑数之象，与元参、生地、犀角、栀、楝、槐芯、侧柏、知母、花粉、石斛、银花、甘草梢、绿豆等药，旬日而痊。逾四载以他疾终。", "13065": "管氏妇自去秋患赤痢，多医罔效，延至暮春。孟英诊脉弦数，苔黄渴饮，腹胀而坠，五热夜甚，用白头翁汤合金铃子散，加芩、芍、栀、斛，吞驻车丸，浃旬而愈。", "13066": "濮树堂室病，孟英甫为参愈。而树堂继焉，起即四肢厥逆，脉伏恶寒，发热头痛，左为甚。惟口渴，因与葱豉二帖，（解表。）热虽退，脉仍伏，四肢冷过肘膝，大解频行，人皆疑为虚寒。孟英曰：此证俨似阴厥，然渴饮溲赤，真情已露，岂可泥于一起即厥，而必定其为寒乎？径投凉解，热果复发，而肢冷脉伏如故。幸病者坚信，服药不疑。至第七日，大便泻出红水，溺则管痛，呕恶烦躁，彻夜不瞑，人更危之。孟英曰：热邪既已下行，可望转机。以白头翁汤，加银花、通草、芩、芍、茹、滑、知、斛、栀、楝、羚角之类。投三日，红水始止，四肢渐和，颇有昏瞀谵语。用王氏犀角地黄汤一剂，四肢热而脉显滑数，苔转灰黄，大渴遗溺，病人自述如卧烘箱上。于昨方加入元参、银花、竹叶、生石膏、知、贝、栀、斛。服一剂，夜间即安寐，而苔转黑燥，于昨方复加花粉。服一剂，热退而头面汗多，（阳越于上。）懒言倦寐，小溲欲解不通。（阴虚于下。）诸戚友咸以为危，各举所知，（病已将愈，何危之有。）而群医佥云挽救不及，病家皇皇。孟英曰：此证幸初起即予诊视，得尽力以为死里求生之举。非比他人之病，皆因误治致危。然不明言其险者，恐病家惶惑，而筑室于道旁也。今生机已得，不过邪去真阴未复。但当恪守予法，自然水到渠成，切勿二三其德，以致为山亏篑。赖有一二知音，竟从孟英议。服西洋参、生地、苁蓉、麦冬、楝、芍、知、斛药，一剂溺行索粥，再服而黑苔退，三服而神清音朗，舌润津回。唯有韧痰不能吐，左偏头微痛，于原方加二至、桑、菊、贝母、牡蛎。又复五剂，得解硬矢一次，各患始安，眠食渐适而瘳。（凡厥逆脉伏之证，其热深藏，多不易解，非卓识定力，不惑于证，亦必摇于众议矣。）", "13067": "王开荣偶患腹中绞痛，（伏暑在内。）自服治痧诸药，（香燥可以益热。）而大便泻血如注。孟英诊之，左颇和，右关尺弦大而滑，（弦滑者痰也，大者热也。）面色油红，喘逆不寐，与苇茎汤合金铃子散，加银花、侧柏叶、栀、斛、芩、连。二帖后，面红退，血亦止，乃裁柏叶、银花，加雪羹、枯荷杆。又二帖，始发热，一夜得大汗周时，而腹之痛胀爽然若失，即能安寐进粥。改投沙参、知母、花粉、桑叶、杷叶、石斛、白芍、橘络、杏仁、冬瓜子、茅根、荷杆，三帖，大解行，而脉柔安谷。", "13068": "陈叟久患痰嗽气逆。（肺气不清。）夏初因恶寒，（热结在肺。）自服理中汤，遂痰中带血，气喘而厥，二便不通，冷汗腹胀。孟英察脉洪大，按腹如烙，与苇茎汤，加栀、楝、旋、贝、花粉、海䖳。外以田螺、大蒜、车前草，捣贴脐下，即溺行而平。", "13069": "高某，患两膝后筋络酸痛，（血不养筋。）略不红肿，卧则痛不可当，彻夜危坐。孟英切脉虚细，苔色黄腻，咽燥溺赤，与知、斛、栀、楝、牛膝、豆卷、桂枝、竹沥为方，送虎潜丸，（阴虚于下，火炎于上。煎剂以治其上，丸药以培其下，井井有法。）旬日而瘳。", "13070": "张某，患发热，医知其非寒邪也，用清解药数帖，腿肿异常，身面渐黄。孟英诊之，脉滑实，腹胀口干，与茵陈大黄汤，两剂便行而各恙霍然。", "13071": "冯媪患左目胞起瘰，继而痛及眉棱、额角、巅顶，脑后筋掣难忍。医投风剂，其势孔亟。孟英诊脉弦劲，舌绛不饥，与固本合二至、桑、菊、犀、羚、元参、牡蛎、鳖甲、白芍、知母、石斛、丹皮、细茶等，出入为用，匝月始愈。", "13072": "歙人吴永言，于十年前读《论语》「不撤姜食」之文，因日服之，虽盛夏不辍。至三年，患大溢血，虽以凉药治瘳，而时时火升迄今不愈。季冬就诊于孟英，身不衣绵，头面之汗蓬蓬也。且云服芩、连，则烦渴益甚，以苦能化燥也。用生地即闷滞不饥，以甘能缓中也。蔗梨入口亦然。按其脉，沉取滑数，是从前之积热，深伏于内。与白虎汤去草、米，加竹叶、竹茹、花粉、海䖳、荸荠、银花、绿豆恣服，渐吐胶痰而愈。继闻赵秋舲进士令郎子循，每啖蔗则鼻衄必至，或疑蔗为大热之性。孟英曰：蔗甘而凉，然甘味太重，生津之力有余；凉性甚微，荡热之功不足。津虚热不甚炽者，最属相宜。风温证中救液之良药，吾名之曰天生复脉汤。若湿热、痰火内盛者服之，则喻氏所谓翻受胃变从而化热矣。凡药皆当量人之体气而施，岂可拘乎一定之寒热耶？子循之体，水虚而火旺者也。蔗性不能敌，反从其气而化热，正如蔗经火炼则成糖，全失清凉之本气矣。枸杞子亦然。", "13073": "朱养之令弟媳，初患目赤，服药后，渐至满面红肿，壮热神昏，医者束手。孟英切脉，洪实滑数，舌绛大渴，腹微张。以酒洗大黄、犀角、元参、滑石、甘草、知母、花粉、银花、黄芩、连翘、薄荷、菊花、丹皮，两下之径愈。", "13074": "许培之令祖母，年逾七旬，久患淋漏，屡发风斑。孟英持其脉，弦而滑，舌绛口干，每以犀角、生地、二至、芩、蒿、白薇、元参、龟板、海螵之类，息其暴；甘露饮增损，调其常。人皆疑药过凉，孟英曰：量体裁衣。禀属阳旺，气血有余，察其脉色，治当如是。病者乃云：十余年前，偶患崩而广服温补，遂成此恙。始知先天阳气虽充，亦由药酿为病。秋杪患寒热如疟，喜怒不眠，苦渴易饥，不能纳食。孟英察脉，弦数倍常，与清肺蠲痰、柔肝充液之法，渐以向安。今冬有荐吴古年诊治者，询知病原，作高年脱营论，而以血脱益气裁方。初服三四剂，饮食骤增，举家忻幸。已而血漏甚多，眠食欲废，复延孟英视之，仍主前议，果得渐康。", "13075": "许芷卿患外寒，须覆重衾，内热，饮不解渴，仍能安谷，便溺皆行。或以为虚寒，或以为疡患，投以温散，即显咽痛。孟英脉之，沉弦而缓，作痰热内伏。投以犀、羚、元参、丹皮、白薇、黑栀、茹、贝、旋、蒡之剂，两帖而寒渴咽疼皆减。乃去犀、羚、牛蒡，加二至、知母、花粉、银花，解酱矢而瘳。", "13076": "褚芹香女校书，患汛愆寒热。医以为损，辄投温补，驯至腹胀不饥，带淋便闷，溲涩而痛。孟英诊脉，弦劲而数，乃热伏厥阴，误治而肺亦壅塞也。与清肃开上之剂，吞当归龙荟丸两服，寒热不作而知饥。旬日诸恙悉安。", "13077": "李德昌之母，仲夏患感，医诊为湿，辄与燥剂，大便反泻。遂疑高年气陷，改用补土，驯致气逆神昏，汗多舌缩。已办后事，始乞诊于孟英。脉洪数无伦，右尺更甚，与大剂犀角、石膏、黄芩、黄连、黄柏、知母、花粉、栀子、石斛、竹叶、莲心、元参、生地之药。另以冷雪水调紫雪，灌一昼夜。舌即出齿，而喉舌赤腐，咽水甚痛。乃去三黄，加银花、射干、豆根，并吹锡类散。三日后，脉证渐和，稀糜渐受。改授甘凉缓剂，旬日得坚黑矢而愈。", "13078": "幼科王蔚文之甥女，向依舅氏。于三年前患热病甚危，服多剂凉解始愈。第寝食虽如常人，而五心恒热，黑苔不退，口苦而渴，畏食荤膻。频饵甘凉之药，经来色黑不红。去年适吴氏，仍服凉药，迄不能痊。今夏伊舅氏浼孟英诊之，脉甚滑数，曰：此热毒逗留阳明之络，陷入冲脉，以冲隶阳明也。然久蕴深沉，尚不为大患者，以月事时下，犹有宣泄之路也。其频年药饵，寒之不寒者，以热藏隧络，汤剂不能搜剔也。令每日以豆腐皮包紫雪五分吞下。半月后，苔果退，渴渐减。改用元参、丹参、白薇、黄芩、青蒿煎汤，送服当归龙荟丸。又半月，经行色正，各恙皆蠲，寻即受孕焉。", "13079": "周光远令正，孀居十载，年已五十三岁，汛犹未绝，稍涉劳瘁，其至如崩。偶患少腹偏左掌大一块作疼，其疼似在皮里膜外，拊之痛甚。越日发热自汗，眩冒谵语，呕渴不饥，耳聋烦躁。孟英循其脉，虚软微数，左兼弦细，便溏溲热，舌本不赤，略布黄苔。营分素亏，而有伏热，阻于隧络。重药碍投，姑予芩、连、芍、楝、竹茹、桑叶、白薇、通草、橘核、丝瓜络、灯薪，少加朱砂和服。一剂势即减，二剂热退呕止，啜粥神清。第腹犹痛，去桑、芩、灯芯、朱砂，加苁、归、苡、藕，服数帖而起。迫季冬，其君姑七十八岁，患腹痛，痛亦仅在皮膜，仍能纳食，二便无疴。数日后痛及两腰，机关不利。碍于咳嗽，痰出甚艰，而有咸味，夜不能瞑，孟英视曰：肝肾大虚，脉络失养也。以沙参、熟地、归、杞、苁、膝、杜仲、石英、羊藿、络石、薏苡、胡桃等药进之，日以递愈。继用一味桑椹，善后而康。", "13080": "叶承恩，年五十岁，患发热暮甚，肢厥头疼，呕恶便溏，睡则呓语，不饥不渴，汗出上焦，自觉把握不住。延孟英诊之，脉软涩而不鼓指，右手尤甚，宛似虚寒之证。惟舌本紫，苔虽薄，而黄腻，口苦，眼鼻时觉出火。是真阴素亏，而热伏于内也。予栀、连、桑、菊、茹、翘、芩、斛、银花、丝瓜络、莲子心，出入数剂。热呓皆减，脉亦较和，溲赤而疼，大解色酱，知其伏热下行矣。又数剂，苔始退而知饥，参以养阴而愈。", "13081": "蔡湘帆，年二十岁，体素丰。偶发寒热，翼日尚吃饭出门，自不知为病也。第三日，寒热大作，茎缩不能小溲，气喘大汗，眩晕不支。乞孟英往诊，举家仓皇大哭。循其脉缓大而滑，苔色黄腻，脘下拒按，曰：无恐也。予菖、枳、旋、蒌、栀、豉、连、半、茹、䖳，以芦菔汤煎服。一剂，大吐痰涎而喘汗平；二剂，茎舒溲畅而大解行，越日寒热即减；又两剂，疟罢知饥而愈。然李东垣谆谆以内伤类外感为言，而温热暑湿之病，初起极类内伤，往往身未发热而手心先热，或兼眩晕自汗。设泥古法而不辨证，祸可言哉。", "13082": "徐仲荣四令弟德生，患感至旬余，忽然大战大汗，而大便兼下瘀血。朱茂才视之，不知战解之义，以为将脱也。率投大剂温补药一服，汗收壮热，杳不知饥，渴饮无眠，舌赤溲少，遂束手。更医谓汗下伤阴，滋填叠进，驯致身难转侧，懒语音低者，又旬余矣。所亲吴爱棠嘱延孟英图之。脉弦数而驶，按其胸下坚且痛，舌绛而根苔黄滞，曰：汗下伤阴固然，惟府犹实也，滋腻曷可投耶？然一病至此，又难攻夺，姑以善药通之。因予小陷胸汤合雪羹，加茹、杏、紫菀、白前、冬瓜子、芦菔，和梨汁。服二帖，坚黑之矢果下，仍夹瘀血，身热遂缓，稍进稀糜，改用清养肺胃以充津液。旬日后，热净溲澄，知饥安谷。惟舌不生苔。寐即汗出，授大剂滋阴而愈。德生有一婢，年十七矣，陡患腹痛，稍一言动，则痛不可支。举家疑为急痧中恶，多方以图，皆不应。飞速孟英往视，见其神色如常，并不吐泻，脉则牢涩，苔则腻黄，曰：此多食酸甘，而汛阻也。询之果然。以桃仁、红花、生蒲黄、灵脂、海䖳、香附、延胡、芍药，芦菔汤煎药，吞当归龙荟丸而愈。", "13083": "陈载陶令郎，夏间患嗽泻愈后，时发微热，寝汗如蒸。医治两月，迄不能退，时犹作嗽，咸以为劳。其世父喆堂逆孟英视之，热甚于颈面，形瘦口干，脉则右大，曰：肺热不清也。养阴之药久服，势必弄假成真，热锢深入而为损怯之证。亟宜淡泊滋味，屏绝补物。以芩、栀、地骨、桑叶、苡仁、枇杷叶、冬瓜皮、梨皮、苇茎为剂，服后热汗递减。至九帖，解酱矢赤溲，皆极热而臭，自此热尽退而汗不出矣。惟噫犹不畅，时欲太息，饱则胸下不舒，乃滋腻药所酿之痰未去也。改用沙参、枳实、旋覆、冬瓜子、竹茹、白前、栝蒌、海䖳、橘皮。数帖而胸舒嗽断，体健餐加。", "13084": "张某患四肢发热，久治不痊，食减便溏，汗多形瘦。张孝子谓此证非孟英不能愈，遂往就诊。曰：热厥也。前此必误服补药矣，故脉来甚涩。以芩、栀、连、柏、白薇、通草、地骨、青蒿、丝瓜络为方，十余剂而瘥。", "13085": "傅与三令正，年已花甲，患疟服药，浃旬而断，乃夜不能眠者数日。忽然吐泻交作，肢冷自汗，渴喜热汤，神气张皇而有谵语。张某谓元虚，而所用之药，乃桂、芍、萸、连、葛、霍、乌药、木香之类。病家欲投温补，迎孟英质之。脉来浮弦软数，尺中甚弱，舌绛无液，稍有黄苔。乃真阴素亏，久伤谋虑，吸受暑热，化疟未清，扰及中州，则为吐泻。询所吐，果有酸甘苦辣之味，泻亦色酱而热如火，岂非伏热之的据耶？然邪已自寻出路，故腹无痛苦。况汗出如淋，不独用香燥疏散之药为耗液，即温补如理中、四逆，亦无非助热而重劫其津也。乃定沙参、龙、牡、朱染茯神、黑豆皮、薏苡、木瓜、小麦、竹针、鲜莲子之方。一剂而吐泻皆止，得寐神清，且略知饥，稍能收谷。次日复诊，病者云侬舌上脱液者三十年矣，是以最怕热药。奈群医谓疟宜温化，以致愈服愈殆。设非先生眼光如炬，恐昨日已登鬼录矣。寻以充液柔肝而愈。", "13086": "李华甫，年六十三岁，仲夏患恶寒，气逆不饥，即请孟英视之。脉甚虚软，舌本紫而滑泽无苔，溲频数而浓赤不禁，阴茎已缩，两手紫黯。乃心阳过扰，热伏厥阴之象。不可谓无热恶寒发于阴，而认为真伤寒也。虽平昔耽饮嗜茶，设投燥剂，则液之涸也不须旋踵。爰以葱、豉、茹、芩、栀、薇、桑叶、通草，轻解其外，至夜始发热。再剂，微汗而解，独腹热如烙，舌渐干而口渴，改予西洋参、元参、生地、麦冬、甘草、花粉、栀、楝、苁、茹，和青蔗汁。服二帖，下坚矢，而舌愈干，且谵语不寐，于前方加竹叶、木通。服之舌根始见黄苔，知伏热渐化。再一剂，苔转黑，原方调以神犀丹一丸，即战解而舌始润，稍啜稀糜，犹妄言无寐。乃心阴久耗，阳不能收也。仍以前方加童溲和服，两帖。大解复行，神气渐谧，诸恙寻愈。此证设犯温升，即难救药。幸初发得遇名手，始克扶危持颠旬日而愈。故为相者治天下，当因民之所利而利之，不必务虚名而复井田、肉刑也。为医者治人，亦当因病之所利而利之，不可守成法而泥麻黄、桂枝也。", "13087": "丙辰春初，余游梅泾。曹霭山茂才拉视其令郎之证，云起于往夏疟后，暮热鼻衄，善欠羞明，頞颊时酸，溲浑有脚。先禀素弱，佥虑成劳。频服滋填，毫无寸效，久不起榻。及余诊之，脉软滑而微长，苔淡黄而不渴，仅能仰卧，反侧不能，曰：此非虚劳也。乃热伏阳明，是以机关不利，筋骨不束，而见以上诸证。幸衄血频流，小溲混浊，热气尚有宣泄，而人不甚枯削，以阳明为多气多血之经也。与生槐蕊、知、柏、芩、栀、白薇、花粉、茅根、茹、斛、丝瓜络等药。久服果渐愈。", "13088": "顾宗武偶患微寒发热，医进温散法，热虽退，而不饥不大便。复用平胃散数帖，腹渐胀而偏于右，尚疑其中气之虚寒也。遂与温运燥补诸药，胀乃日增，杳不进谷。或谓恐属痈疡，因招外科连某诊之，作胁疽治，病如故。黄某作肠痈论，以大黄泻之亦不应。严某谓胁疽部位不对，肠痈证据不符，作内疝治，仿子和、《活人》之法，及当归龙荟丸相间而投，亦无效。乃延孟英视之，脉极弦细而促，舌绛大渴，小溲赤少，饮而不食者月余矣。证实脉虚，坚辞不治。其家问曰：此证究是何病？乞为指示。孟英曰：据述病人素慎起居而薄滋味，显非停滞与痈疽之患。良由暑湿内蕴，势欲外泄，是以初起有微寒发热之候。误与风寒药，热虽暂退于表，邪仍伏处于中，不饥不便。肺胃失其下行，再加辛燥温补，气机更形窒滞，伏邪永无出路，津液潜消，䐜胀日甚。以气血流行之脏腑，为暑湿割据之窠巢，补之不可，攻之不能。痛虽不在膏肓，卢扁望而惊走。逾旬径殁。（杂药乱投，一何可笑。）", "13089": "黄莲泉家戚妪病痢，朱某以其年老，而为舍病顾虚之治。渐至少腹结块，攻痛异常，大渴无溺，杳不知饥，昼夜百余行，五色并见，呼号欲绝，始延孟英诊之。脉至沉滑而数，因谓曰：纵使暑热深受，见证奚至是耶？此必温补所酿耳。夫痢疾古称滞下，明指欲下而涩滞不通也。顾名思义，岂可以守补之品，更滞其气；燥烈之药，再助其虐乎？少腹聚气如瘕，痢证初起，因于停滞者有之。今见于七八日之后，时欲冲逆，按之不硬，则显非停滞之可拟。实为药剂之误投，以致邪浊蟠踞，滋蔓难图。及检所服诸方，果是参、术、姜、萸、附、桂、栗壳、故纸、川椒、乌梅等一派与病刺谬之药。孟英曰：彼岂雠于汝哉。畏老而补之，见痢而止之，亦未尝不煞费苦心，而欲汝病之即愈，惜徒有欲愈之心，未明致愈之道。但知年老元虚，不闻邪盛则实。彼亦年近古稀，悬壶多载，竟毕世沉迷于立斋、景岳诸书，良可叹也。岂造化果假权于若辈乎？不然，何彼书彼术之风行哉！戚云：壬寅之病，赖君再生，今乃一误至此，恐仙丹不能救矣。孟英曰：幸未呕哕，尚可希冀一二。遂与苁蓉、楝、芍、芩、连、橘、斛、楂曲、元胡、绿梅、鳖甲、鸡金、鼠矢、海䖳，出入互用。数帖渐安，继加驻车丸吞服，逾月始健。（痢疾初起即补，变成噤口者有之，延为休息者有之。邪因补而固结不解，虽有明手无如之何，良可叹恨。）", "13090": "上虞陈茂才患头痛，三日一发，发则恶寒。多药不效，饮食渐减。或拟大剂姜附，或议须投金石。葛仲信嘱其质于孟英，察脉甚弦，重按则滑，曰：热暑伏厥阴也，温补皆为戈戟。与左金，加楝、芍、栀、桑、羚、丹、菊、橘为剂，煎吞当归龙荟丸。三服而减，旬日即痊。", "13091": "钱氏妇，怀妊四月，而患寒热如疟。医与发散安胎，乃至舌黑神昏，大渴便泄，臭痰频吐，腰腹痛坠，人皆不能措手。孟英诊曰：伏暑失于清解，舌虽黑而脉形滑数，痰虽臭而气息调和，是胎尚未坏，犹可治也。重用气血两清之药，五剂而安。糜粥渐进，腰腹皆舒，胎亦跃跃。", "13092": "赵春山司马，向患痰嗽。自秋仲以来，屡发寒热。吴古年从伏暑化疟治，颇为应手。而一旬半月之后，病必复至，延至季冬。董兰痴鹾尹，嘱其质于孟英。按脉滑数，舌绛苔黄，渴饮溲赤，动则喘逆，夜不成眠，痰多畏冷，自问不能起矣。孟英曰：无恐也。不过膏粱酿痰，温补助热，是为病根。迨夏吸暑邪，互相𫐖轕，秋半而发，势颇类疟。古年虽识其证，惜手段小耳。因与羚羊、豆豉、连翘、薄荷、知母、花粉、竹茹、贝母、旋覆、海䖳、元参、栀子、醒头草、梨汁等药。服五剂，热退不畏冷。去前四味，加沙参、麦冬、葳蕤、枇杷叶。渐能安寐，各恙递减。再加生地，服匝月而体健胜昔，登高不喘。司马云：余昔曾服参、茸大补之药而阳痿，今服君方而沉疴顿起，乃知药贵对证，不贵补也。", "13093": "许芷卿痁起季秋，孟英尝清其伏暑而将愈。其从母亦知医，强投以小柴胡一剂，势复剧。孟英予温胆汤去甘草，加生石膏、黄芩、知母、花粉、芦菔而安。继因作劳太早而复发，适孟英丁忧，赵君笛楼仍用清解而瘥。迨季冬移居劳顿，疟复间作，且面浮跗肿，喘嗽易嗔，人皆以为大虚之候。孟英切脉左弦劲而数，右滑大不调，苔黄且腻，口渴溺多，乃胃肺之痰热有余，肝胆之风阳上僭。畏虚率补，必不能瘳。用西洋参、知母、花粉、竹茹、蛤壳、石斛、枇杷叶、青蒿、秦艽、白薇、银花、海䖳为方。连投四剂，大吐胶痰，而各恙悉除。", "13094": "沈氏子年甫髫，仲秋患感两旬，屡医弗愈，求孟英视之。神昏谵语，面惨无眠，舌绛耳聋，频吐白沫，脉数溺少，渴饮不饥，热已甚微，汗亦频出，牛黄、紫雪，数进无功。以元参、丹参、白薇、知母、苇茎、竹茹、旋覆、冬瓜子、蛤壳、石斛、枇杷叶、竹叶、花粉、莲子心、西瓜翠衣等出入为方，数服而愈。盖邪虽传营，气分未廓，故虽善饮水而敷布无权，不能下行为溺，但能旁溢为汗，上行为沫。良由初起不知为暑，治以表散风寒之药，及至传营，又不知营卫两解之法，徒以直走膻中之药，漫图侥幸，何异鹦鹉学人言，而不知所以言耶。", "13095": "邱小敏初发热，即肢瘛腹痛，卧则昏谵，坐起即清，膈间痞闷，饮亦碍下，舌色紫肿，苔厚腻黄，身面赤色，龈肿而疼。医见其病情错杂，初以为斑疹之候，进透发之剂。浑身冷汗，又虑内闭外脱，灌以紫雪，病如故。又疑热入血室，用桃仁、茺蔚、丹皮、藕汁、童溲等药。又恐其虚，用西洋参、龟板等味，遂言謇呃逆。正在彷徨，适病者登圊更衣，忽然昏晕，谓欲虚脱，欲进生脉饮以固元气。举家无措，所亲姜柳湖请孟英往诊之。脉洪弦而兼滑数，病属暑湿。惟肝气素郁，肺胃多痰，是以升降失常，邪气壅塞。卧即神昏者，乃湿热上熏也，故坐起则爽。彼热入血室，乃昼明了而夜谵语，非昼卧即昏，夜坐即明也。治宜清展气机，病必化疟而解。设以温散表其汗，则邪炽而津劫。若以滋补固其元，则邪闭而正脱。误用血分药，则引邪入营。徒用寒润法，则遏邪不化。先以雪羹、栀、楝、旋、枳、连、蒌、芩、半、菖、茹、元参、银花、丝瓜络等出入为方，吞当归龙荟丸。果转为疟，各恙递减。连下黑矢，半月后便色始正而疟亦止，胃醒安谷而瘳。停药数日，偶因嗔怒，其疟复作。寒少热多，睛赤龈疼，汗多足冷，孟英曰：余热逗留，风阳内煽也。视其苔灰黄夹黑，因谓其弟桂山曰：但看黑苔退净，则邪自清矣。仍予元参、白薇、知、芩、栀、茹、银花、木通、丝瓜络、菊叶等，送龙荟丸。疟即递减，逾旬苔净，眠食如常而起矣。", "13096": "高鲁川，家兄礼园之外舅也。年近古稀，新秋患感。顾某进清解药二剂，热即退。以其年高，遂用滋养。越日复热，谓欲转疟，改用厚朴、姜、枣等药，遂热壮神昏，速孟英视之。脉形滑数，舌心已黑，溲赤干呕，粥饮不入。亟予元参、知母、花粉、银花、竹茹、枇杷叶、莲子心、栀子、白薇、西瓜翠衣为剂，数帖霍然。", "13097": "许梅生仲郎恬甫，年未冠。仲秋患感，医知其阴虚伏暑也。叠进清卫凉营之法，旬余热退，以为无虑矣。惟六日不更衣，因用生地、麻仁、花粉等药。服后果欲大解，及登圊大泻一次，人即汗晕，急扶上榻。连泻二三十次，满床皆污，尽是黄水，身复发热，肢痉音低，唇焦齿槁，苔色干黄而渴，舌不能伸，目不欲张，速孟英勘之。脉微细欲绝，而呼吸甚促，按其心下坚而且痛，曰：疾不可为也。缘初治失于开泄，胸中痞结，而津液不能敷布，尽从下脱，攻补皆难措手矣。翼日果殒。", "13098": "四舍弟西甫，年二十四岁，秋杪患感，至六日神渐昏，延孟英诊之。脉形涩滞，苔垢头疼，气逆汗频，腰疼溲少，脘闷拒按，乃伏暑晚发而本元极亏也。亟与开中，俾有去路，小陷胸加栀、菖、豉、芩、白薇、翘、枳，芦菔汤煎服一剂。脘不拒按，苔亦稍退，汗不达于下部，脉来软而且涩，改授茹、半、芩、栀、橘、翘、知、蛤、花粉、莲子心之剂。三服，脉转弦数，大解未行，谵语不休，夜间热炽，肢凉头晕。浊热上熏也，以芩、蒌、栀、连、茹、翘、元参、白薇、丹皮、海䖳、竹叶投之。乃下坚黑大便，而圊后神晕，苔渐薄而转黑，为去芩、莲、蒌、䖳，加犀角、鲜生地、知母、花粉，两帖。更衣仍黑，气乃渐平，肢亦渐温，热渴均减，犹不知饥，脉软而虚，苔退未净，乃去犀、翘，加西洋参、麦冬、银花、菖蒲。服三剂，又解黑矢，舌色始津，而寐不安神，汗多心悸，因去知母、花粉、丹皮，加甘草、丹参、茯苓，而地黄用干者。两帖，大解甚畅，胃渐知饥，稍进稀糜，力不胜啜，脉亦虚大，寐即神驰，乃邪未清而虚毕露也，用西洋参、生地、龙齿、归、芍、芩、甘、连、柏、麦冬、小麦。服五剂，复下酱矢，而右脉尚虚大。又六帖，粪色始正，汗减神安，脉渐柔和，寝食乃适。嗣又食复数次，赖孟英活泼如龙，随机应变，竟以告愈，洵属再生。", "13099": "一劳力人发热，左胁疼，咳嗽碍眠，痰出甚臭，苔黄舌绛，渴饮谵语，便秘溲赤，脉形滑数，乃伏暑证。询其平昔嗜饮，醉后必向左卧，故湿热酿痰，久积于左，非内痈也。以苇茎汤去苡仁，加雪羹、芩、滑、茹、翘、栀、蒌、旋覆、木通等出入，三剂。大便行，谵语止，而痰出更多，其臭益甚，仍用前药。又四剂，痰始少而不臭，热净能眠，知饥苔退，改授甘凉养液而瘳。", "13100": "翁某年甫冠，仲冬患感，医与温散药数帖，神悗耳聋，苔黑便泻，胸痞腹胀，溲少妄言。孟英切脉细数而涩，乃暑湿内伏，气郁不宣也，投以犀角、银花、元参、连翘、菖蒲、郁金、黄连。药一剂，热退神清，脘不拒按，别恙未减，脉则弦细而数，口转发渴，改用芩、翘、朴、斛、连、楝、银花、通草、兰叶、冬瓜皮为剂。两啜化为间疟，其疟发一次，则苔化一层，胀减一分，粥加一盏。药不更张，凡四发而苔净胀消，脉和溲畅，嗣予调养而康。", "13101": "朱氏妇患赤痢匝月，多医杂治，痢止三日矣。而起病至今，胸头痞胀，米饮不沾，口渴苔黄，溲热而痛，凛寒身热，夜不成眠，神惫形消，诸医技窘。乞余往视，脉数而弦，伏暑未清，营津已劫，气机窒塞。首议清泄，南沙参、石菖蒲、蒌、薤、栀、芩、茹、连、橘、半、白薇、紫菀。四剂，而痰活胸舒，寒热大减，且能啜粥。改用北沙参、生首乌、柏子仁、冬瓜子、元参、蒌、薤、菖、栀。二剂，坚矢下，用清养法而痊。", "13102": "钱君友琴，年五十九岁。曾于七月间患滞下，自服大黄一剂而瘥。季秋患寒热时作，自服柴、桂等药，病益甚，狂躁欲啖西瓜，而服石膏。余诊之，脉滑右甚，苔色腻黄，便秘溲短，胸痞不沾粒米。乃暑湿夹痰阻于气分，治宜开泄，白虎不可投也。用蒌、薤、枳、朴、连、夏、茹、芩、菀、桔，服三剂。二便既畅，胸次豁然而愈矣。", "13103": "季夏，余游檇李，陆君又溪邀视其友王姓之病。寒热时作，汗多不解，便溏不畅，溲赤妄言，面黑如煤，苔黑大渴，烦躁气逆，脉滑而洪。按其心胸，坚硬而痛，乃暑湿夹痰食也。群医但知时感，辄进寒凉。闻说胸次不舒，遂疑为疹，羚、犀、膏、地，力竭计穷，已令病家备后事。余曰：此非重证，何必张皇。撤被启窗，胜于服药。病家唯唯，而不甚信。余即手为揭被开窗，病人即曰：舒畅多矣。药以小陷胸加芩、枳、翘、茹、薤、菖、海䖳，数服而愈。继有里中张姓者，证相类，面不黑而红，舌无苔而干。诸医亦不察其气分之尚结，痰食之未行，屡进生地，唇齿渐焦，遂束手。余以小陷胸加元参、海䖳、菖、枳、芩、翘，一饮而脘舒得卧，齿舌皆津。盖结散邪行，则气通液布也。", "13104": "戚媪者，年六十余矣。自幼佣食于黄莲泉家，忠勤敏干，老而弥甚。主仆之谊，胜于亲戚也。秋间患霍乱转筋，孟英视之，暑也。投自制蚕矢汤，两服而安。三日后，忽然倦卧不能反侧，气少不能语言，不饮不食。莲泉惶惧，不暇远致孟英，即邀济仁堂朱某诊之，以为霍乱皆属于寒，且昏沉欲脱，疏附子理中汤与焉。莲泉知药猛烈，不敢遽投，商之王安伯，安伯云：以予度之，且勿服也。若谓寒证，则前日之药，下咽即毙，吐泻安能渐止乎？莲泉闻之大悟，著人飞赶孟英至而切其脉曰：此高年之体，元气随泻而泄，固当补者。第余暑未清，热药在所禁耳。若在孟浪之家，必以前之凉药为未当，今日温补为极是。纵下咽不及救，亦惟归罪于前手寒凉之误也。设初起即误死于温补，而世人亦但知霍乱转筋是危险之证，从无一人，能知此证有阴阳之异，治法有寒热之殊，而一正其得失者。此病之所以不易治，而医之所以不可为也。今君见姜附而生疑，安伯察病机之已转。好问者心虚，识机者智赡，二美相济，遂使病者跳出鬼门关，医者卸脱无妄罪。幸矣！幸矣！乃以高丽参、麦冬、知母、萎蕤、木瓜、扁豆、石斛、白芍、苡仁、茯苓、蒺藜为方，服六剂始能言动，渐进饮食，调理月余而健。", "13105": "七月十八日夜，予患霍乱转筋甚剧，仓卒间，误服青麟丸钱许。比晓急邀孟英诊之，脉微弱如无，耳聋目陷，汗出肢冷。音哑肌削，危象毕呈。药恐迟滞，因嘱家慈先浓煎高丽参汤，亟为接续；随以参、术、白芍、茯苓、附、桂、干姜、木瓜、苡仁、扁豆、莲实为方，一剂而各证皆减。次日复诊，孟英曰：气分偏虚，那堪吐泻之泄夺。误服苦寒，微阳欲绝。昨与真武、理中合法，脾肾之阳复辟矣。刚猛之品，可以撤去。盖吐泻甚而津液伤，筋失其养则为之转，薛生白比之痉病，例可推也。凡治转筋，最要顾其津液。若阳既回，而再投刚烈，则津液不能复，而内风动矣。此治寒霍乱之用附、桂，亦贵有权衡，而不可漫无节制，致堕前功也。（此一段议论极精微。凡用寒用热，俱宜具此权衡，方无过当之弊。否则，药虽中病，而服之不止，及受其害矣。喻氏论中寒证，亦具此意。）即于前方裁去姜、附、肉桂，加黄耆、石斛，服至旬日而愈。予谓此番之病，危同朝露。若非孟英，恐不能救。常闻张柳吟云：但使病者听孟英论病之无微不入，用药之无处不到，源源本本，信笔成章，已觉疾瘳过半。古云「檄愈头风」，良有以也。（可见浙人禀赋之薄。若幽冀之人，即误服青麟丸数钱，亦不至如斯之甚也。）", "13106": "陈妪，年已七旬，患霍乱转筋甚危。亟拉孟英救之，已目陷神消，肢冷音飒，脉伏无溺，口渴汗多，腹痛苔黄，自欲投井。令取西瓜汁先与恣饮，方用白虎加芩、连、黄柏、木瓜、威灵仙，略佐细辛分许为剂。复杯即安。人皆疑用药太凉，何以径效？孟英曰：凡夏热亢旱之年，入秋多有此病，岂非伏暑使然？况见证如是之炽烈乎？今秋余已治愈多人，询其病前有无影响，或曰五心烦热者数日矣。或曰别无所苦，惟睹物皆红如火，已而病即陡发。夫端倪如此，更为伏暑之的据焉。", "13107": "李华甫继室，陡患霍乱而兼溺血如注，头疼如劈，自汗息微，势极危殆。迎孟英诊视，脉极弦驶，是肝阳内炽，暑热外侵。先用犀角、木通、滑石、栀子、竹茹、薏苡、银花、茅根、菊叶为大剂，和入藕汁，送当归龙荟丸，而霍乱即安。惟溺血虽减，而小溲时头犹大痛，必使人紧抱其头，重揿其巅，始可略耐。尚是风阳僭极，肺胃不清也。以苇茎汤去桃仁，加百合、白薇、元参、竹叶、西瓜翠衣、菊叶、莲子心为方，和入童溺，仍吞龙荟丸，服旬日而愈。继有祝氏妇，患溺血五六年矣，医皆作淋治。孟英诊视脉弦数，苔黄口苦，头疼溺热，曰：是溺血也，法宜清肝，与久淋当滋补者迥殊。病者极为首肯。盖其出路自知，而赧于细述，故医者但知其为淋也。", "13108": "陈楚珍仲媳，陡患霍乱，亟迓孟英治之。云昨晚曾食冷鱼，夜深病作，想由寒重致此。然脐间贴以回阳膏而不效奈何？及诊脉右甚滑数，口渴苔黄。今按胸下，果坚硬而痛。曰：吐泻虽多，宿食恋膈，非寒证也，回阳膏亟为揭去。以石菖蒲、枳实、苏叶、黄连、半夏、竹茹、海䖳、芦菔为方，服之，一剂霍然。", "13109": "刘廉方，常州名士也。在西湖受暑，移榻于崔仲迁别驾处，医治垂危。庄芝阶舍人，拉孟英往诊之。裸卧昏狂，舌黑大渴，溺赤便秘，脉数而芤，与犀角地黄汤加减服之。神识已清，略能进粥。次日复诊，颇知问答，大有生机，仍处甘凉法以赠之，并嘱伊格外谨慎。而越日，庄半霞诣孟英偕往诊视，见其目张睛瞪，齿露唇焦，气喘汗出，扬手掷足而不可救药也。众楚交咻，谓是寒凉药凝闭而然。孟英曰：病之宜凉宜热，汝辈不知也。脉乃皮里之事，汝等不见也。吾亦不屑为之争辨。惟目瞪唇焦，人所共睹，则其死于何药，自有定论。遂拂衣出，半霞再三请罪，孟英曰：俗人之见，何足介怀，是非日后自明，于我心无慊焉。第斯人斯病，皆可惜也。既而始知有人主热药以偾事，岂非命耶？仅二载而仲迁病，孟英闻之曰：殆矣。盖知其阴虚而受暑湿，恐主药者未必能悔悟于前车也。后果闻其广服温补之剂，以致真阴竭绝而死。覆辙相寻，迷而不醒，可哀也已。", "13110": "潘红茶方伯之孙翼廷，馆于许双南家。酷热之时，啜冷石花一碗，遂致心下痞闷，四肢渐冷，而上过肘膝，脉伏自汗。方某诊谓阳虚阴暑，脱陷在即，疏大剂姜、附、丁、桂，以回阳。双南在苏，其三郎杏书骇难主药，邀族人许芷卿诊而决之。芷卿云：此药断不可投。第证极危急，须逆孟英商之。时夜已半，孟英往视，曰：既受暑热，复为冷饮，冰伏胸中，大气不能转旋，是以肢冷脉伏，二便不行。速取六一散一两，以淡盐汤搅之，澄去滓，调下紫雪丹一钱。（藉辛香以通冰伏之气，用意精妙。）翼日再诊，脉见胸舒，溺行肢热，口干舌绛，暑象毕呈，化而为疟，与多剂白虎汤而愈。丙午举于乡。（认证既确，治法又极精妙，真可谓万世法程。）", "13111": "汪子与病革，始延孟英视之，曰：阴虚之质，暑热胶锢，殆误投补药矣。乃叔少洪云：侄素孱弱，医投熟地等药十余剂耳。孟英曰：暑热证，必看邪到血分，始可议用生地，何初病即进熟地？岂仅知禀赋之虚，未睹外来之疾耶？昔贤治暑，但申表散温补之戒，讵料今人于律外更犯滋腻之辜？而一误至此，略无悔悟，不啻如油入面，如胶投漆，将何法以挽回哉！越日果卒。夫小米舍人仅此一脉，完姻未久，遽尔珠沉，殊为惨然。冬间吴忻山亦惟一子，素禀虚怯，滋补颇投。医者不察其患温发热，佥谓阴虚，竞投滞腻培元之剂。乃至舌黑卷短，唇焦溺赤。孟英一诊即云不救。顾听泉竭力图维，终不能愈。按虚人受感，每蹈此辙，特录以为戒。", "13112": "金朗然之母，偶发脘疼呕吐。医与温补药，初若相安，渐至畏寒不寐，四肢不仁。更医云是风痹，仍投温补。因而不饥不食，二便不行，肌肉尽削，带下如溺，始延孟英诊之，曰：暑伏脾胃耳。其多投温补而不遽变者，以熟地等阴柔腻滞为之挟制也。然津气灼烁而殆尽，脂液奔迫以妄行，治节无权，阳明涸竭，焉能卫皮毛而畅四肢，利机关以和九窍哉。与白虎汤加西洋参、竹茹、橘皮、丝瓜络、石斛、花粉、竹沥、海䖳。连进二十剂，始解黑矢而各恙渐安。嗣与和肝胃、调八脉以善后，遂愈。李某向患脘痛，孟英频与建中法获瘳。今秋病偶发，他医诊之，闻其温补相投，径依样而画葫芦。服后耳闭腿疼，不饥便滞。仍就孟英视之，曰：暑邪内伏，误投补药使然，治宜清涤为先。彼不之信，反疑为风气，付外科灼灸，遂致筋不能伸而成锢疾。孟英曰：此证较金病轻逾十倍，惜其惑于浅见，致成终身之患。良可叹也！独怪谋利之徒，假河间太乙针之名，而妄施毒手。举国若狂，竟有不惜重价，求其一针，随以命殉之者，吾目击不少矣。夫《内经》治病，原有熨之一法，然但可以疗寒湿凝滞之证。河间原方，惟二活、黄连，加麝香、乳香耳，主治风痹。今乃托诸鬼神，矜夸秘授，云可治尽内伤、外感、四时、十二经一切之病，天下有是理乎？况其所用之药，群集辛热香窜之品，点之以火，显必伤阴，一熨而吐血者有之。其不可轻试于阴虚之体，与挟热之证也，概可见矣。吾友盛少云之尊人卧云先生，误于此而致周身溃烂，卧床数载以亡。仲圣焦骨伤筋之训，言犹在耳。操医术者，胡忍执炮烙之严刑，欺世俗而罔利哉。汪子与证，误服熟地而不救。此证误服温补地兼熟，而竟愈。盖体有虚实，治有迟早，邪有重轻，未可以一端拘也。", "13113": "乔有南之侄，甫五龄。发热数日，儿医与柴葛解肌汤一剂，肢搐而厥，目张不语。其母孀居，仅此一脉，遍求治疗，毫无寸效。所亲徐和甫，托王瘦石访一擅幼科之长者，瘦石谓宜求善于外感者。盖人有大小，病无二致，切勿舍大方而信专科，此喻嘉言活幼金针也。盍延孟英视之，徐从之。孟英曰：病是暑邪，治以风药。热得风而焰烈，津受烁以风腾。乃风药引起肝风，再投俗尚惊风之剂，稚子根本不牢，而狂风不息，折拔堪虞。与王氏犀角地黄汤，加羚羊角、生石膏、元参、桑叶、菊花、银花、牡蛎、知母、麦冬、竹叶诸药，数服而痊。（清暑热，息肝风，方极平允。）", "13114": "赵铁珊乃郎子善，康康侯之婿也。因事抑郁，凛寒发热。汤某作血虚治，进以归、芎、丹参之类，多剂不效。乃移榻康寓，延孟英诊之。脉涩而兼沉弦以数，然舌无苔，口不渴，便溺如常，纳谷稍减，惟左胁下及少腹自觉梗塞不舒，按之亦无形迹，时欲抚摩，似乎稍适。曰：阴虚挟郁，暑邪内伏。夫郁则气机不宣，伏邪无从走泄，遽投血药，引之深入。血为邪踞，更不流行，胁腹不舒乃其真谛。第病虽在血，而治宜清气为先。气得宣布，热象必露，瘀滞得行，厥疾始瘳。子善因目击去年妇翁之恙，颇极钦服。连投清气，热果渐壮，谵妄不眠，口干痰嗽。孟英曰：脉已转为弦滑，瘀血伏邪，皆有欲出之机，继此当用凉血清瘀为治。但恐旁观诧异，事反掣肘，嘱邀顾听泉质之，顾亦云然，遂同定犀角地黄汤加味。而所亲陈眉生、许小琴暨乃兄子勉，皆疑药凉剂重，纵是热证，岂无冰伏之虞？顾为之再四开导，总不领解。适病者鼻衄大流，孟英笑曰：真赃获矣。诸公之疑，可否冰释？渠舅氏陈谷人鹾尹云：证有疑似，原难主药。鼻血如是，病情已露，毋庸再议。径煎而饮之。次日衄复至，苔色转黑。孟英曰：三日不大便，瘀热未能下行也。于前方加滑石、桃仁、木通、海䖳、竹沥、石斛、银花、知母、花粉之类。又二剂，大解始行，黑如胶漆，三日间共下七十余次而止。乃去木通、桃仁辈，加西洋参、麦冬，以生液。病者疲惫已极，沉寐三昼夜，人皆危之，孟英曰：听之，使其阴气之来复，最是好机。醒后尚有微热谵语，药仍前法。又旬日，始解一次黑燥大便，而各恙悉退。惟口尚渴，与大剂甘凉以濡之。又旬日大解甫得复行，色始不黑，乃用滋阴填补而康。（此证不遇孟英必成虚损，讫无知其为伏暑者，虽死亦不知前药之误也。）", "13115": "仲夏淫雨匝月，泛滥为灾。季夏酷暑如焚，人多热病。有沈小园者，患病于越。医者但知湿甚，而不知化热。投以平胃散数帖，壮热昏狂，证极危殆。返杭日，渠居停吴仲庄浼孟英视之。脉滑实而数，大渴溲赤，稀水旁流，与石膏、大黄数下之而愈。仲庄欲施药济人，托孟英定一善法。孟英曰：余不敢师心自用，考古惟叶天士甘露消毒丹、神犀丹二方，为湿温、暑疫最妥之药。一治气分，一治营分，规模已具。即有兼证，尚可通融。司天在泉，不必拘泥。今岁奇荒，明年恐有奇疫。但甘露二字，人必疑为大寒之药；消毒二字，世人或误作外证之方，因易其名曰普济解疫丹。吴君与诸好善之家，依方合送，救活不知若干人也。", "13116": "陈蕴泉陡患昏谵，夤夜乞诊于孟英。脉甚滑数，苔色腻黄。乃平素多痰，兼吸暑热。与清解药一剂，化而为疟，脉亦较平。或谓其体弱不宜凉药，须用人参。渠家惶惑，孟英坚持以为不可。盖暑，脉颇类乎虚。而痰阻于肺，呼吸不调，又与气虚短促者相似。平昔虽虚，有病必先去病。况热能伤气，清暑热即所以顾元气也。何新之亦赞是议。遂连投白虎加减而愈。次年春，因丧妾悲悼，复感温邪，失于肃清，病日以甚。迨孟英自豫章归诊，已不可救药矣。（暑证，人多不识此二层。昔人虽曾论及，而无此明晰。）", "13117": "一人患晨泄有年，累治不效，而春间尤甚。孟英按其脉曰：汝虽苦泻，而泻后腹中反觉舒畅乎？曰：诚然。苟不泄泻，又胀闷减食矣。而服四神、附、桂之药，其泻必加，此曷故也？曰：此非温升补涩之证。乃肝强脾弱，木土相凌。处一方令其常服，数帖即安，后竟无此恙也。方用白术、苡仁、黄连、楝实、桂枝、茯苓、木瓜、芍药、蒺藜、橘皮而已。（扶脾抑肝，制方灵动。）", "13118": "方氏女，久患泄泻，脘痛，间兼齿痛，汛事不调，极其畏热，治不能愈。上年初夏。所亲崔映溪为延孟英诊之。体丰脉不甚显，而隐隐然弦且滑焉。曰：此肝强痰盛耳。然病根深锢，不可再行妄补。渠母云：溏泄十余年，本元虚极，广服培补，尚无寸效。再攻其病，岂不可虞？孟英曰：非然也。今之医者，每以漫无著落之虚字，括尽天下一切之病，动手辄补。举国如狂，目击心伤，可胜浩叹！且所谓虚者，不外乎阴与阳也。今肌肉不瘦，冬不知寒，是阴虚乎？抑阳虚乎？只因久泻，遂不察其脉证，而佥疑为虚寒之病矣。须知痰之为病，最顽且幻，益以风阳，性尤善变。治必先去其病，而后补其虚，不为晚也。否则，养痈为患，不但徒费参药耳。母不之信，遍访医疗，千方一律，无非补药。至今秋颈下起一痰核，黄某敷之使平，更以大剂温补。连投百日，忽吐泻胶痰斗余而亡。予按：此痰饮滋蔓，木土相雠，久则我不敌彼，而溃败决裂。设早从孟英之言，断不遽死于今日也。（凡病皆宜如此，不独痰饮为然。）", "13119": "叶杏江仲郎，患发热泄泻，医治十七日不效，骨瘦如柴，音嘶气逆。所亲许芷卿荐孟英诊之，脉数大渴，汗多苔黄，以竹叶石膏汤加减。十余剂渐以向愈，大解反极坚燥，（肺移热于大肠，）继与滋养而康。", "13120": "陈某偶患溏泄，所亲鲍继仲云：余往岁患泻，治不中肯，延逾半载，几为所困。今秋患此，服孟英方，数剂霍然，故服药不可不慎也。盍延孟英治之？陈因中表二人皆知医，招而视之，以为省便。辄投以温补健脾之药，数日后泻果减，热得补而不行。而发热昏痉，咽喉黑腐。其居停瞿颖山，疑病变太速，嘱其请援于孟英。孟英诊曰：迟也。病起泄泻，何必为寒？正是伏邪自寻出路。而温补以固留之，自然内陷厥阴，不可救药。果即殒焉。继有高小垞孝廉令弟雨生，因食蟹患泻。黄某用大剂温补药，泻果止，而颈筋酸痛，舌绛呕渴，口气甚臭。孟英持脉沉数，曰：食蟹而后泻，会逢其适耳。脉证如斯，理应清润。奈病人自畏凉药，复质于吴某，亦主温补。服及旬日，昏痉舌黑而毙。", "13121": "杨某患感旬日，初则便溏，医与温散，泻止热不退，昼夜静卧，饮食不进。孟英诊脉迟缓，浮取甚微，目眵，舌色光红，口不渴，溲亦行，胸腹无所苦，语懒音低，寻即睡去。是暑湿内伏，而有燥矢在胃，机关为之不利也。先与清营通胃药二剂，热退舌淡，而脉证依然。加以酒洗大黄、省头草，即下坚黑燥矢甚多，而睡减啜粥。继以凉润，旬日而痊。此湿胜于热之暑证也。以其湿胜，故不甚现热证，最足眩人。断为暑湿，足征卓识。", "13122": "何搢阶令正，素患肝厥。仲夏患感，沈越亭按温证法治之，内风不至陡动，而大便泄泻，脉细而弦，（泄泻乃湿温应有之证，不足为异。）渴饮痰多，不饥不寐。因邀孟英商之，投白头翁汤，加三甲、石斛、茯苓、竹茹而安。随以峻补善后而痊。", "13123": "家慈年七十四岁，陡患泄泻，腹微痛，身发热，神思不清，自汗呕恶，不进饮食。亟延医视，云虑其脱，拟进参药。迨孟英来诊，曰：暑脉微弱，不可谓之虚也。且兼数象，参不可投。高年固属阴亏，然去其所本无，即所以全其所本有也。爰定芩、连、滑、斛、茹、柏、竹叶、银花、橘皮、枇杷叶之方，冬瓜汤煎药。一剂而热退神清，二剂霍然矣。既而五弟妇偶患微寒发热，医与柴、芎等药一剂，遂昏狂悲哭，见人辄怒詈欲搏。屈孟英过诊，脉弦滑而数，面赤不瞑，苔色黄腻，胸下拒按。曰：痰热肝火为患耳。以菖蒲、胆星、旋、赭、连、蒌、枳、半，合雪羹投之。一剂而安，翼日寒热复作。孟英曰：幸其体实，药不可缓，庶免化疟也。照方服五剂，果寒热三作而遂痊。", "13124": "沈妪素患肝气，初冬便泻，医药勿瘥。所亲吴馥斋迓孟英诊之，脉至弦硬，舌赤无津，杳不知饥，胁腹时胀。乃风阳内炽，津液耗伤，香燥忌投，法宜濡润，否将阴涸，毋畏甘凉。予甘草、地黄、麦冬、阿胶、枸杞、薏苡、楝实、葳蕤、乌梅为剂，牡蛎一斤，甘澜水煮浓汤煎药，和入蔗浆服之。数日而瘳，已能安谷，忽然舌不能伸，心摇语蹇，不眠头晕，面赤火升。仍速孟英视之，脉硬虽和，极其弦细，是阴液未复，木火失涵。以前方去薏、楝、乌梅，加人参、龙眼肉，少佐黄连。授之而愈。", "13125": "沈友闻令郎厚栽，久患羸弱，驯致腹痛便泻，恶谷形消。诸医束手，求孟英图之。脉虚弦而空软，曰：不可为矣。虽然，治之得法，尚可起榻。可虞者，其明年春令乎。爰以潞参、鳖甲、耆、芍、甘、柏、薏、斛、木瓜、橘皮为方，吞仲景乌梅丸。不旬日而便坚食进，又旬日即下楼而肌充矣。又其大令郎子槎之室，体素怯，夏间曾患久泻，多剂温补始瘳。忽发寒热，肢麻头痛，彻夜不眠，嘈杂如饥，咽喉似阻，食饮难下，汗仅出于上焦。佥以为虚损将成。孟英持其脉，弦弱而数；视苔，微黄满腻，曰：暑湿时疟也，补药乌可投耶？以茹、滑、苓、连、桑叶、紫菀、银花、橘皮、冬瓜子、枇杷叶、丝瓜络等药，芦根汤煎。服数剂而痊，嗣与滋养善其后。既而子槎自上海归，亦患疟。孟英视之，暑湿挟痰也。予温胆汤数服而愈。次年春杪，厚栽竟逝。", "13126": "施瀛洲，体丰色白，夏月在绍患泻。医进参、术、桂、附、熟地、四神之类，略无寸效。季冬来杭就诊于孟英。其脉微弱，左手及右尺沉取有弦数之象，眩晕形消，舌色深紫，无苔不渴，纳食腹胀，溲少而赤，泻必肠鸣。中气固虚，理应投补，但不可佐滋腻以滞中枢，而助其溜下之势；又不宜杂燥热以煽风阳，而壮其食气之火。予参、耆、术、苡、升、柴、芩、泽、香连为剂，吞通关丸，乃宣清升降、补运兼施之法也。服之良效。浃旬舌淡溲行，胀消晕止，惟大便未实耳。去芩、泽、升、柴、香连、通关丸，加菟丝、木瓜、橘皮、黄柏、石脂、白芍，善后而瘳。", "13127": "鸳湖吴君小渔令宠，数年前因娩后，啖生菜而患便泻，久治不愈。仲秋余视之，脉弦数，曰：此非菜之罪也。乃土受木乘，而频年温补，益广病机。头痛带多，脘疼食少，吐酸痰嗽，五热不眠，无非八脉无权，风阳偏盛。授宣养清潜之法而愈。继其令妹适岳氏者，久患带下，去冬崩血，赤白并行，延今不已，卧榻数月，佥云无生理矣。余诊脉甚滑数，面赤口干，因问足冷乎？溲热乎？耳鸣无寐乎？向来辄服温补乎？皆曰然。幸能安谷，是药病也。幸涩之不止，药力尚有分势也。授以大剂清热坚阴之法，服数十剂。仲冬余复游禾，已能踵寓就诊参。", "13128": "秀水吴君小渔，年近七旬。平昔善饮，久患便泻带血，日夜十余次，溺不单行，广治罔效。聘余往视，脉软而弦。用补中益气汤，去归、柴，加乌梅、黄柏、白芍、茯苓，不十帖而痊。其季郎雅轩，素有失血之患。近由穹窿山归，途次发热，兼以咳逆见血。医治两旬，不应。余诊之，脉弦数，而上溢气冲，则自觉血腥，喘汗睛红，面黧足冷，饥不能食，胁痛耳鸣，苔腻口干，小溲短赤，寤不成寐，痰色甚浓。乃禀赋阴亏，水不涵木，心火内炽，肺金受戕。兼感客邪，胃浊不降，甚难措手，即欲辞归。而虞君梅亭、胡君春田，力乞疏方，勉图一二。爰以沙参五钱，蛤粉四钱，冬瓜子六钱，浮石、茯苓、石斛各三钱，桑皮二钱，竹茹、枇杷叶各一钱五分，丝瓜络、桃仁各一钱，芦根汤煎服。是清心肝，以靖浮越之阳；肃肺胃，而廓逗留之热也。一帖脉色转和，气冲亦减。余留七日返棹，已热退便行，能安眠食。惟不能慎口腹，戒忿怒，故痰嗽胁痛，未能尽蠲。逾二月，余游闻川过禾，因喉痛复邀过诊。仍是心肝之火上炎。为留三日，与龚萍、江茂才内外协治而瘥。但病源匪浅，情性不柔，春令深时，恐兴险浪。临别与其友人余姚岑君九鼎言之，以为左券。", "13129": "沈君雪江令嫒，黎里徐少岩刑部之媳也。胎前患泻，娩后不瘳。半载以来，诸药莫效。余按脉弦数而尺滑，询知带盛口干，腰酸咽痛，溲热善噫，肢冷畏烦，乃肝热而风行于胃，液走则阴血日亏。与白头翁汤，加余粮、石脂、熟地、龟板、竹茹、青蒿、砂仁，频服而痊。", "13130": "七月中旬，余游檇李归，道出梅注，吕君慎庵拉视沈则甫令正之恙。两年前，曾患带下，嗣后便泻不已。今夏更剧，每晨尤甚，后又肠鸣，不饥不渴，畏热无汗，胸闷时呕，夜下成眠，形消色瘁，小溲通畅，脉软微弦，经事渐稀。乃中虚木侮，生化无权，气久虚而血将涸矣。若刚燥则助风阳，滋腻更增滑溜、议砥柱中流，回狂澜而镇风轮。以潞党参、山药、石脂、余粮各三钱，茯苓、白芍各一钱五分，煨诃子、橘皮各一钱，牡蛎八钱，乌梅肉炭八分，酒炒黄柏六分，熟附子、炙甘草各五分，甘澜水煎陈米汤，煮药使浓厚。徐徐细呷，俾留恋中宫，不致直下为法。迨八月下旬，在曹蔼山茂才处，晤则甫云：前方服至四帖，病即愈，今已色华能食矣。因以诗什芽茶为赠。次年冬，闻患寒热亡。", "13131": "桐乡，冯诒斋广文，年二十七岁。自上年患疬，至今已十余枚，皆破而不敛，肌肉渐削。迨季夏渐形发热，而纳食阻膈，溲短便溏，气逆嗽痰，咽喉疼肿，诸医束手。秀水庄文芝阶，荐余诊之，脉数而左寸关兼弦大。是病由过扰心阳，兼伤谋虑。从前但从呆补，已成不治之证。近则吸受暑邪，犹日服滋填之剂，是以药造病也。而诒斋一见倾心，坚留数日。因谓其令兄静岩赞府曰：余仅许愈其新病也。以沙参、苡、斛、橘、半、蒿、薇、蛤、谷、浮石、茯苓，煎吞香连丸。二剂，而痛泻渐止，去香连，加鳖甲。又二剂而热退，改用参、苓、橘、半、苡、蛎、石英、首乌、象牙屑、冬虫草等出入为方，卧时另制噙化丸，以肃上焦痰滞。服四帖，已能起榻，眠食皆安，余遂归。秋杪闻其没于奥江外科家。少年博学，惜哉！余邮挽一联云：倾盖相知，讵成永诀。著书未竟，遽赴修文。知渠方注顾亭林先生《肇域志》，而即病也。其夫人即于秋杪起患赤痢，延至次年春杪，证已频危。适余游鸳湖，往视之。昼夜三四十行，汛断肌消，少腹素有聚瘕，跃跃而动，气冲胸下，绞痛难堪，仰不能眠，饥不能食，口干舌绛，五热溺无，头项汗频，音低色夺，脉来细数，右软尺空。是久积忧劳，兼伤哀痛，真阴素弱，岂可与常痢同观？以沙参、熟地、黄连、黄柏、白头翁、秦皮、冬虫夏草、枸杞、橘核、白薇，用藕、苡、燕窝煮汤煎药。服二十剂。余游瀛洲，转禾复诊。脉和痢减，安谷能眠，痛止溺行，面有华色。改用人参、熟地、龟板、归身、黄连、黄柏、枸杞、白薇、薏苡、砂仁，以藕汤煎成，入阿胶烊服而愈。", "13132": "海阳赵子升，辛卯夏病疟。急延孟英诊之，曰：暑热为患耳，不可胶守于小柴胡也。与白虎汤，一啜而瘥。（专清暑邪。）甲午秋，范丽门患温疟，孟英用白虎加桂枝以痊之。丙申夏，盛少云病湿热疟，孟英以白虎加苍术汤而安。己亥夏，予舅母患疟，服柴胡药二三帖后，汗出昏厥，妄语遗溺。或谓其体质素虚，虑有脱变，劝服独参汤。幸表弟寿者不敢遽进，乃邀孟英商焉。切其脉洪大滑数，曰：阳明暑疟也，与伤寒三阳合病同符。处竹叶石膏汤两剂而瘳。（清热兼益气。）庚子夏，滇人黄肖农自福清赴都，道出武林，患暑疟，孟英投白虎汤，加西洋参，数帖始愈。（清热益气与前方意同。）辛丑秋，顾味吾室人患瘅疟，孟英亦主是方而效。庄芝阶中翰张安人，年逾花甲，疟热甚炽。孟英审视再四，亦与竹叶石膏汤而安。闻者无不惊异。予谓如此数证，体分南北，质有壮衰，苟非识证之明，焉能药与病相当，而用皆适宜哉？", "13133": "石符生，随乃翁自蜀来浙，同时患疟。医者以小柴胡汤加姜、桂投之不效，改用四兽休疟等法。反致恶寒日甚，谷食不进。惟饮烧酒姜汤，围火榻前，重裘厚覆，胸腹痞闷，喜以热熨，犹觉冷气上冲，频吐黏稠痰沫。延至腊初，疲惫不堪，始忆及丙申之恙，访孟英过诊。脉沉而滑数，苔色黄腻不渴，便溏溺赤，曰：是途次所受之暑湿，失于清解，复以温补之品，从而附益之，酿成痰饮，盘踞三焦，气机为之阻塞。所以喜得热熨热饮，气冲反觉如冰。若不推测其所以然之故，而但知闻问在切脉之先，一听气冷喜热，无不以真赃现获。孰知病机善幻，理必合参，以脉形兼证并究，（审病要法。）则其为真热假寒，自昭昭若揭矣。与大剂苦寒之药，而以芦菔汤煎。渐服渐不畏寒，痰渐少，谷渐增。继用甘凉善后，乔梓皆得安全。", "13134": "顾云垞，体丰年迈。患疟于秋，脉芤而稍有歇止。孟英曰：芤者，暑也；歇止者，痰湿阻气机之流行也。（卓识。）大忌温补以助邪气。及与清解蠲痰之法，病不少减，而大便带血。（邪将去矣。）孟英曰：暑湿无形之气，而平素多痰，邪反得以盘踞，颇似有形之病，清解不克胜其任。气血皆受其滋扰，必攻去其痰，使邪无依附，而病自去，切勿以高年而畏峻药。伊侄桂生少府，亦精于医者也，闻之极口称是。遂以桃仁承气汤，加西洋参、滑石、芩、连、橘红、贝母、石斛为方，送礞石滚痰丸。乃郎石甫孝廉云：此药在他人必畏而不敢服。我昔年曾患暑湿证，深悉温补之不可轻试。况高明所见相同，更何疑乎？经服二剂，下黏痰污血甚多，疟即不作。仍以清润法善后而康。（此必别有外证可凭，故直断为暑与痰湿。未有专视脉之芤与歇止而如是定断者，读者勿被瞒过。此方可谓峻极，良由识高，非徒胆大。）", "13135": "九月间，张春桥患疟，寒少热多。间二日而作。甫两发，形即清瘦。孟英诊曰：脉弦而细，尺中甚数，疾作于子夜，口干嗜饮，乃足少阴热疟也。两发遽尔形消，胡可玩视！吾以妙药奉赠，可期即已，但请即服，不可商于人而致生疑义也。方用元参、生地、知母、丹皮、地骨皮、天冬、龟板、茯苓、石斛、桑叶。春桥以向所心折，遂服之。一剂疟即止，再以滋阴善后而愈。予谓此证一帖而瘳，似乎轻易，但非真才实学，焉有此种妙治？设遇别手，非温补即提表，其祸可胜道哉！然天下之病，无论轻重，总贵初治得法，何致轻者重而重者危耶？奈世俗之情，必须轻者重而后转安，始知医药之功，殊可叹也！按此证世人但知其为三阴疟，笼统治以温补之法，从未闻有分经用药者。今提出少阴二字，创立清凉之剂，用药精当，取效敏捷，法似新奇，理自完足，所谓活人治活病，全以活泼运之也。可以启人慧悟，垂作典型。", "13136": "酷热之际，疟疾甚行。有储丽波患此，陆某泥今岁寒水司天，湿土在泉，中运又从湿化，是以多疟，率投平胃理中之法，渐至危殆。伊表兄徐和圃荐孟英视之，热炽神昏，胸高气逆，苔若姜黄，溺如赭赤，脉伏口渴，不食不便。曰：舍现病之暑热，拘司气而论治，谓之执死书以困活人。幸其体丰阴足，尚可救药。然非白虎汤十剂，不能愈也。和圃然之。遂以生石膏、知母、银花、枳、贝、黄连、木通、花粉、茹、芩、杏、斛、海䖳、竹叶等，相迭为方。服旬日，疟果断。", "13137": "外甥庄迪卿患疟，大渴而喜热饮，脘闷脉伏，苔腻欲呕。孟英曰：蕴湿内盛，暑热外侵，法当清解。然脉证如是，乃痰阻气道使然。清之无益，温之助桀。宜以礞石滚痰丸先为开导。服后痰出甚多，脉即见弦滑而数，呕止胸舒，苔形黄燥，与石膏、知母、连、朴、杏、橘、半、茯、滑、斛、菖蒲、花粉等药。而安。（论证论治俱极明透。）", "13138": "庄晓村，芝阶姐夫之侄孙也。馆于金愿谷舍人家，病疟。孟英曰：吸受暑热，清涤即瘳。阅数日，疟作甚剧，目赤狂言，汗如雨下。居停大惊，闻服凉剂，疑为药误。亟速孟英至，正在披狂莫制之时。按其脉洪滑无伦，视其舌深黄厚燥，心疑其另服他药之故，而扑鼻吹来一阵姜、枣气，因诘曰：得无服姜枣汤乎？曰：恣饮三日矣。孟英即令取西瓜一枚，（解暑妙品。）劈开任病者食之。方从白虎，而生石膏用一两六钱，病即霍然。逾六年以他疾亡。继有陈仰山如君患疟，孟英连与清暑法，病不少减，孟英疑亦姜枣汤所致。询知果然，亟令屏绝遂愈。余如汪子觉、魏云裳、胡秋纫等暑疟治案，皆以白虎化裁。案多不备载，录此以备读者之偶反焉。", "13139": "何永昌者，孟英之舆人也。其妻病疟，间二日而作。乃母曰：疟不可服官料药，径服签方。旬日后势甚危，永昌乞孟英救之。脉沉细而数，尺为甚，口渴，目不欲张，两腰收痛，宛如锥刺，寒少热多，心慌不能把握。曰：异哉病也！此暑入足少阴之证。喻氏所谓汗、下、温三法皆不可行者。若病在别家，虑其未必我信。病在汝而求诊于我，事非偶然也。汝母云官料药不可治疟，此语出于何书？而药别官私，何人所创？既官料之勿服，则私料更不可妄试矣。殊属可嗤！然是证若延医诊，非表散即温补，不可谓非汝母之一得也。疏方元参八钱，龟板、石斛各一两，地骨皮六钱，知母五钱，桑叶、金银花各四钱，花粉三钱，丹皮二钱，令用大砂锅煎而频服，不必限剂。服三日，疟断而各恙皆减，粥食渐进，不劳余药而起。（暑邪入肾，必伤肾液，故重用滋阴之品以救之。）", "13140": "周某患疟，间二日而作，寒少热多。医谓老年三疟，放手温补，渐至杳不进谷。所亲李石泉孝廉，嘱迎孟英诊之。脉细硬如弦，毫无胃气，右尺洪数，舌色光绛，大渴溺滴，曰：此足少阴暑疟也。广服温补，津液尽劫，欲以草木生之，事不及矣。世但知治疟不善有三患：邪留肝络则为疟母，戕及脾元则为疟鼓，耗乎肾阴则为疟劳。而此证以药助邪，邪将劫命，求转三患亦不能得。所谓热得补而更炽，阴受烁以速亡，阴愈亡则邪愈炽，何殊炮烙之刑。病者何辜？可惨！可惨！逾日果殁。特录以为戒，医者鉴之！", "13141": "潘祥行在外患疟，买舟归就孟英视。曰：苔腻脉软，伏邪所化，不与正疟同科。风寒药一味不可犯，姜枣一滴不可啜。与知、芩、橘、半、滑、朴、杏、斛、花粉、省头草，一剂而病若失。此等案极多，姑载一二。", "13142": "陈足甫室，怀妊九月而患疟，目不能瞑，口渴自汗，便溏气短。医进育阴清解法，数剂不应。改用小柴胡一帖，而咽疼、舌黑，心头绞痛。乃翁仰山闻之，疑其胎坏，延孟英过诊曰：右脉洪滑，虽舌黑而胎固无恙也。病由伏暑，育阴嫌其滋腻。小柴胡乃正疟之主方，古人谓为和剂，须知是伤寒之和剂。在温暑等证，不特手足异经，而人参、半夏、姜枣，皆不可轻用之药。虽有黄芩之苦寒，而仲圣于伤寒之治，犹有「渴者，去半夏，加栝蒌根」之文。古人立方之严密，何后人不加体察耶？投以竹叶石膏汤，四剂疟止。便秘，口渴不休，与甘凉濡润法数帖。忽腹鸣泄泻，或疑寒凉所致，孟英曰：吾当以凉药解之。人莫识其意，问难终朝，语多不备录。果以白头翁汤，两啜而愈。迨季秋娩后，发热不蒸乳，恶露淡且少。家人欲用生化汤，孟英急止之，曰：血去阴更伤，岂可妄疑瘀停而攻之？与西洋参、生地、茯苓、石斛、女贞、旱莲、甘草为大剂，数日而安。继因触怒，少腹聚气如瘕，酸痛夜甚。人又疑为凉药凝瘀所致，孟英力为辨析。与橘核、橘叶、橘络、楝实、苁蓉、木香、栀炭、乌药、丝瓜络、海䖳、藕、石斛、两头尖等药，外以葱头捣烂贴之。两帖后，腹中雷鸣，周身汗出而痛止。人见其汗，虑为虚脱，急追孟英视之，曰：此气行而病解矣。但脉形细数，阴津大伤，苔黄苦渴，亟宜润补。奈枢机窒滞，滋腻难投，且以濡养八脉为法。服之各恙皆蠲，眠食渐适。缘平素多郁，易犯痧气，频发脘痛，屡次反复。孟英竭力图维，幸得转危为安，渐投滋补而愈。疟亦分经而治。若阳明疟，正以白虎汤为主剂。岂有专守一小柴胡，而能愈病者？", "13143": "乔有南，年三十九岁。患牝疟二旬，医治罔效。所亲徐和圃疑为伏暑，迓孟英往诊。脉微无神，倦卧奄奄，便秘半月，溺赤不饥，痰多口甘，稍呷米饮，必揉胸捶背而始下，苔色黑腻而有蒙茸之象，乃曰：此精气神三者交虚之证。不可与时行伏暑晚发同年而语也。幸前手之药，法主运中，尚无大害、与参、术、桂、附、沉香拌炒熟地、鹿角、石英、苁、杞、归、茯、杜仲、枣仁、菟丝、山茱、橘皮、霞天曲、胡桃肉等，出入为大剂。投十余帖，寒后始有热，而苔色乃退，口不作渴，甘痰亦日少，粥食渐加。即裁桂、附、白术，加石斛。又服七剂，解黑燥大便甚多。凡不更衣者，四旬二日矣。寒热亦断，安谷溲澄而竟愈。或谓先生尝訾人温补之非，何一旦放手而大用？孟英曰：温补亦治病之一法，何可废也，第用较少耳。世之医者，眼不识病，仅知此法，可以媚富贵之人。动手辄用，杀人无算。岂非将古人活世之方，翻为误世之药，可不痛恨耶！", "13144": "陈媪患牝疟月余，腹胀便秘，嗳多不饥，口淡脉滑，孟英主连、朴、橘、贝、杏、茹、旋、菀、杷、蒺为方，数剂即瘳。（此与前案虚实相反，正可对看。）", "13145": "蒋北瓯二尹，患疟，医与小柴胡、平胃散而渐甚，继以大剂温补，势濒于危，复用桂枝白虎，狂乱如故。所亲董兰初鹾尹，延孟英视之。曰：暑疟也。桂枝白虎用于起病之时则妙矣。今为温散补燥诸药，助邪烁液，脉数无伦，汗渴不已，虽宜白虎，（分别了亮）岂可监以桂枝，助热耗津，而自掣其肘耶？因与大剂白虎，加花粉、竹叶、西洋参、元参、石斛，服之即安。至十余帖，疟始瘳，而舌尚无苔，渴犹不止，与甘凉濡润，三十余剂始告痊。", "13146": "广孔愚司马之大公子，仲秋间患疟寒少热多，面目甚黄，苔腻大渴，腹胀溺赤，仍能纳谷，且素嗜肥甘，不能撙节。孟英按其脉，滑实而数，与承气加知、芩、半、贝、翘、连、滑石、石膏、大腹、花粉之类。二十余剂而始愈。是膏粱挟暑湿热之治也。", "13147": "许叔超令大母患疟，延孟英治之。脉弦滑而数，脘闷便秘，合目汗出，口渴不饥。或虑高年欲脱，孟英曰：此温邪挟素盛之痰所化，补药断不可投。与知、芩、蒌、杏、翘、贝、旋、茹、连、斛、雪羹为方，服果渐效。", "13148": "许氏妇患间疟，寒少热多，不饥大渴，善呕无汗，脉滑而弦。孟英投白虎汤，加花粉、柴胡而愈。", "13149": "海盐周子因工于画，体素弱。偶患间疟，黄某用首乌、鳖甲、姜、枣等药，病日甚。加以参、桂，狂躁妄言，始延孟英视之。面赤舌绛，溲涩便溏，渴饮汗多，脉形细数，是暑证也。与元参、银花、知母、芩、茹、贝、竹叶、荷杆、莲心、西瓜衣为剂，寻愈。", "13150": "吴西瀍患疟，寒微热甚，旬余不愈。孟英诊之，脉滑而长，疏大剂白虎汤与之。渠兄濂仲云：沈、顾二君，皆主是方，屡服无效。孟英索方阅之，汤虽白虎，而石膏既少且煨，兼不去米，因谓其兄曰：汤虽同，君药己重用，而去米，加花粉、竹茹等，其力不同科矣。濂仲大悟，服之寻愈。此可以见服药不可徒有汤头之名也。", "13151": "黄鼎如令堂，年七十七岁。季秋患间疟，每发加剧，寒甚微而热必昏痉，舌不能伸。三发之后，人皆危之。孟英视之，颧赤目垂，鼻冷额颏微汗，苔色黄腻，舌根纯红，口渴痰多，不思粥饮，脉至弦数，重按少神。证属伏暑挟痰，而阴虚阳越，先与苁蓉、鳖甲、楝、斛、茹、贝、燕窝、藕。两剂，而颧红颏汗皆蠲，继佐参、沥、薤、麦、枇杷叶、旋覆，去竹茹、苁蓉。投三帖，而昏痉不作，又去薤、楝，加生地、花粉。服五日而疟休，饮食渐加，居然告愈。方疟势披猖之际，鼎如上水两昆仲，颇以为忧。延诸名家议治，有主人参白虎汤者，有用犀角地黄汤者，有欲大剂温补者，有执小柴胡加减者，赖孟英力排众议，病家始有把握。与孟英意见相合者，何君新之也，怂恿参赞，与有功焉。", "13152": "韩妪年近花甲，患三疟于仲冬。朱某主温散，并以姜枣汤恣饮，旬日后粒米不黏，疟至大吐。黄某以热补进，势益甚。又浃旬，孟英视之，胸中痞结如柈，苔黄苦渴，溲如热汤，脉弦滑右甚，带下如注。投小陷胸合温胆，加薤白，服后大吐胶痰。十余日，胸痞始消，改授甘凉，疟亦渐罢，递参滋阴，遂以霍然。", "13153": "庄芝阶舍人三令媳，患搐搦，间日而作。孟英诊脉弦数，泛泛欲呕，口苦不饥，凛寒头痛，汛事愆期，溲热如火，乃厥阴暑疟也。投以大剂犀、羚、元参、栀、菊、木通、知、楝、花粉、银花之药，数日而愈。", "13154": "赵子善患疟，畏冷不饥。孟英诊之，脉滑数，苔黄溲赤，脘闷善呕，投竹叶石膏汤加减，以清伏暑而痊。", "13155": "王一峰次郎患疟，多服姜枣温散之药，因致壮热耳聋，谵语殿屎，不寐昏狂，见人欲咬。顾听泉从伏暑治亦不效。延至初冬，吴爱棠嘱其求诊于孟英。按脉皆滑，即以顾疏犀角等药内，加菖蒲、胆星、竹沥、珍珠、牛黄为剂，（大驱风痰，极为合法。）吞白金丸。一服即减，旬日霍然。继其令堂发热善呕，频吐黏沫，头疼如劈，口苦耳聋，神识昏瞀，脉弦而数，乃伏暑挟内风之鸱张。与犀角、元参、竹茹、花粉、知、翘、苓、斛、栀、菊、雪羹等药，七日而瘳。", "13156": "高瑞生令弟，疟久不痊，形消不食。医谓虚也，投补药而更增自汗。孟英诊之，脉弦滑，脘下聚气，投小陷胸加竹茹、旋、枳，以开痰结，渐能纳谷，继以清养，病去肌充。", "13157": "闻氏妇，孟夏患间疟，而妊身八月。数发后，热炽昏沉，腰疼欲堕。张养之嘱援于孟英，脉来洪滑且数，苔色黄腻垢浊。与黄芩、知母、竹茹、竹叶、银花、桑叶、丝瓜络、石斛、石膏、石菖蒲，一剂而痊。案中所载，多温疟、暑疟，故治多凉解。疟证多端，寒热俱有，不可执一而论。此证亦温疟也。", "13158": "朱佳木令尊患间疟，年逾七旬，人颇忧之。孟英切脉弦滑，脘闷苔黄，曰：无恐也。投清热涤痰药，数剂霍然。", "13159": "余朗斋，形瘦体弱，患间日疟，寒少热多，二便涩滞，脘膈闷极，苔腻不渴。孟英切脉缓滑而上溢，曰：素禀虽阴亏，而痰湿阻痹。既不可以提表助其升逆，亦未宜以凉润，碍其枢机，投以滑、朴、茹、旋、通草、枇杷叶、苇茎、郁金、兰叶之方。苔色渐退，即去朴、郁，加连、枳、半夏，胸闷渐开，疟亦减，便乃畅。再去滑、半、连、枳，加沙参、石斛、橘皮、黄芩，浃旬而愈。（运枢机，通经络，孟英用药秘诀。无论用补用清，皆不离此意。细观各案自知。）", "13160": "庄芝阶舍人，年七十矣。患间疟，寒则战栗，热则妄言。孟英视之，脉弦数而促，苔黑口干。是素有热痰，暑邪内伏。予知母、花粉、元参、石斛、黄芩、竹茹、连翘、海䖳、芦菔、莲子心等药，数啜而瘳。至仲冬因泛湖宴客，感冒风邪，痰嗽头疼，不饥寒栗，自服羌、苏、荆芥药二剂，势益甚，而口渴无溺。孟英切其脉，与季秋无异，但兼浮耳。证属风温，既服温散，所谓热得风而更炽也。舌绛无津，亟宜清化。以桑叶、枇杷叶、栀子、知母、冬瓜子、元参、菊花、花粉、贝母、梨汁为剂，投匕即减，旬日而痊。", "13161": "锁容亭令妹，自太仓归宁，即患时疟。顾某一手清解，业已安谷下榻矣。忽然气逆肢寒，神疲欲寐，耳聋舌蹇，杳不知饥，大便仍行，别无痛苦。顾知其素患脱血，元气久虚，改用参附等药，势愈剧，以为欲脱矣。所亲吴久山，嘱拉孟英图之。切脉弦缓，视苔黄腻，乃胎之初孕，阻气凝痰，窒碍枢机，治当宣豁。以石菖蒲、枳实、旋覆、半夏、黄连、茯苓、橘皮、葱白、海䖳、竹沥为方，投匕即效，三啜霍然。继而久山令妹，为锁绳先之室，患疟而驯致脘痞呕呃，鼻冷自汗，不食不眠，脉来歇止，医者危之。孟英视之，亦痰为患耳。即以此方去葱、䖳、竹沥，加薤白、蒌仁、竹茹，投之果验。", "13162": "朱生甫明经令郎仲和，于六月初旬患疟，寒少热多，呕渴痞闷。逆孟英视之曰：曩曾屡患此病，证形大略相同，广延名手治疗，总难即愈。病辄经年，大受其累。闻君疗疟极神，不知能否于月内即痊？孟英曰：何限之宽耶？余非神于此。盖寒暑燥湿风五气之感于人也，重则为伤寒，轻则为疟疾。今所患者，暑湿之疟也。清其暑湿，旬日可瘥。前此之缠绵岁月而不能已者，必是不分五气之源流，徒以见疟治疟，而用柴胡、姜东等风疟之方，以致暑湿之邪，滋蔓难图耳。兹以清暑化湿汤奉赠，放胆服之。不可商于人，恐其于五种伤寒未能辨晰，而泥少阳正疟之法以相争也。仲和韪之。方用石膏、杏仁、半夏、厚朴、知母、竹叶，果八剂而安。既而梁甫之仲郎亦患疟，孟英视曰：脉数舌绛，热炽寒微，素质阴亏，暑邪为患也。更不可用疟门套药，予元参、青蒿、白薇、丹皮、黄菊、知母、花粉、银花、竹叶、栀子，数剂而脉减。乃去青蒿、丹皮，加生地、甘草，数服而瘳。", "13163": "石北涯之大令媳患疟，壮热如焚，背微恶冷，汗多大渴，舌绛神烦，不食不眠，奄奄一息。亟迓孟英诊之，脉细数而芤，知其阴分久亏，暑邪深入。遂予白虎汤去米，加西洋参、元参、犀角、竹叶、银花、石斛为方，六剂而愈。人皆闻而异之，孟英曰：见病治病耳，何异之有？然与见疟治疟而不治其所以疟者，固有异焉。", "13164": "韩正甫患疟，越医王某进以柴、桂、姜、朴等药，势乃剧。所亲何新之知为药误，改用清解而不效，始乞诊于孟英。脉数而右更滑大搏指，胸闷不堪，溲赤而渴，苔极垢腻。以凉膈散去芒硝、甘草，合雪羹，加厚朴、杏仁、石膏、半夏、石菖蒲。投四帖，频下宿垢，各恙皆减。改投轻清以涤余邪，遂以向愈。其时渠兄贡甫之室，患疟初起，肢麻且冷，口渴苔黄，眩瞀善呕，心烦无寐。孟英诊曰：此亦暑湿为疟，不可温散者。而越医劝服术、朴、姜、椒等药，病家闻用温化，恪信弗疑。二剂后，呕渴愈甚，经不当期而至，四肢终日不温，汗频出而热不休。再邀孟英诊之，脉渐伏，曰：此热深厥深之谓也。温燥热补，切弗再服。病家不信，另招张某、黄某会诊，佥云阴暑，宜舍时从证。径用姜、附、六君，加萸、桂、沉香等药服之，肢愈冷，药愈重。八剂后，血脱如崩而逝。即以春间为贡甫所治之棺殓焉。岂非数已早定耶？故虽一家之中，同时之病，而疑信不同，死生判别。况春间贡甫之病，治有成效，尚蹈此辙，无怪乎未经目击温热之害者，宜其以服凉解药为可耻矣。继有赵廉士表弟潘少梅乔梓，同时患暑湿疟，孟英咸与清化法，数剂皆愈。潘反生疑，谓病邪被凉药遏伏，故疟遽止，恐将来必有他患。孟英喟然曰：甚矣！医之不可为也。世人患疟，苦无良治，缠绵不愈，习见不疑。余之治疟则不然，但专力治其所以病。故疟疾虽与伤寒同有五种之别，而受病究比伤寒为轻。苟治之如法，无有不数剂而愈者。设误药以遏其邪之出路，则苔不能化，溲不能澄，神不能清，食不能进矣。子自思之，其真愈乎？抑假愈乎？潘始恍然大悟而首肯焉。", "13165": "新秋汪子与室寡居患疟，范某叠进小柴胡法，昏热皆厥，腹痛汗淋，人皆危之。乃祖朱椿年太史逆孟英往视，两尺空数，左关弦寸溢，右寸关滑驶，曰：此真阴素亏，腹有聚气，吸受暑热，最忌升提。与元参、西洋参、百合、竹叶、莲子心、鳖甲、牡蛎、楝实、小麦、黄连等药，两剂而减。其族人谓疟禁凉剂，而尺脉无根，苟非温补，猝变可虞。母家不从，两疑莫决，因请乩方服之。数日后势复剧，苔渐黑。伊父朱次膺仍乞援于孟英，乃诊脉，更数于前，因于前法中加犀角，两帖而安。续以滋潜，善其后而愈。", "13166": "汤振甫患疟于嘉兴，医知为暑，与清解法，转为泄泻。以为暑去而湿存，改用温燥，泻益甚，而发热不休，神气昏瞀，因而束手。令其买棹旋杭，所亲陈雪舫延孟英视之。苔黑面红，胸间拒按，便如胶漆，小溲全无，谵妄耳聋，不眠善笑，脉则洪数而芤。予黄连、黄柏、黄芩、银花、石斛、栀子、楝实、知母、蒌仁、元参为方，绿豆煎清汤煮药，调下神犀丹。四剂，而胸次渐舒，稍啜稀粥，便色渐正，小溲亦通，乃去神犀、楝、柏，加生地、石膏。服三日，热净神清，脉来柔缓，以甘凉养液十余剂而瘳。大凡温热暑证，而大解溏泄者，正是热邪下行，岂可误投温燥之药，反助燎原之势哉？同时一男子患感濒危，浼孟英勘之。神昏舌黑，瘈疭脉微，曰：迟矣。此犀角地黄证，惜无人用。病家云：陆某已屡用之矣。因索其方阅之，虽用犀角屑八分、生地五钱，缘病者便溏，配以枳壳、炒焦白术三钱。孟英喟然曰：此方从无如此加减法。况清凉下敌温燥，是徒有犀角地黄之名耳。古人治病，必放出路。兹反截其去路，良由学无理路，遂致人无生路，良可哀也。", "13167": "同门相简哉室患疟，始则消散，继则补中益气。治之匝月，痿靡不堪，腹中似有聚气，时欲上冲，气促心摇，汗多眩晕，左胁震跃，渴饮无眠，骨瘦如柴，医皆束手。吾师赵菊斋先生拉孟英往诊，脉弦细而数，按之不鼓，因谓相曰：不可再以疟字横于胸中，则旬日可安。若见其久疟而欲截之，且闻前医谓令正初次患疟为胎疟，务令发透，不妨形瘦似鹤，此皆非余之所知也。夫一生不患疟者有之矣，未闻先在胞中患过疟疾而后生者也。若以初次患疟为胎疟，则他病之初患者，无不可以胎字冠之矣。何以不闻有胎痢、胎伤寒之名乎？因医者治疟，而不知治其所以疟，以致缠绵难愈者多。遂妄立胎疟、鬼疟等名，以绐世俗，而自文其浅陋。今昔相沿，贤者不免，故世人又有疟疾不可服官料药之戒。其实药亦何尝有官、私之别耶？服药不当，皆能增病。不服药为中医，不仅为疟疾而言也。令正素禀阴亏，感邪不重，过投消散，营液重虚，再升其阳，本实欲拨。补中益气，原是成方，与证不宜，于体不合，即为毒药。我仪图之，介类潜阳，重镇理怯，甘酸化液，厚味滋阴，大剂而投，肤功可奏。相极感服，如法服之，果未浃旬，霍然病已。方以西洋参、熟地、牡蛎、紫石英、龟板、鳖甲、枸杞、当归、冬虫夏草、龙齿、阿胶、麦冬、龙眼、甘草、蒲桃干、红枣、莲子心、小麦等，出入互用也。", "13168": "蒋礼园令堂，年七十三岁。患疟，寒少热多，时时自汗。咸虑其脱，议欲进补。孟英切脉洪数而滑，舌绛口干，是暑为病也。与清解法数剂而痊。", "13169": "罗氏妇先患痰嗽，气逆碍眠，后兼疟痢并作，医者佥云无法，浼人乞诊于孟英。脉见滑数，口渴苔黄，不饥脘闷，溺似沸汤，曰：无恐也。虽见三证，其实一病。盖肺胃大肠，一气流通。暑伏肺经，始为痰嗽。失于清解，气逆上奔。温纳妄投，胃枢塞滞，郁遏成疟。渴饮汗多，热甚寒微，病情毕露。温化再误，转入大肠，赤白稠黏，无非热迫，不必见证治证，但治其暑，则源清流自洁矣。以苇茎汤，加滑石、黄芩、竹茹、石膏、厚朴授之，不旬日而三证悉瘳。", "13170": "朱生甫明经令郎莱云之室，娩后月余患间疟。孟英脉之，虚数而弦，头疼腹痛，苔色甚薄，乳少善呕，乃营虚而邪客少阳也。令郎断乳，庶免蓐劳。剂以柴、芩、茹、半、桑、楝、延胡、枇杷叶。二帖，呕止腹不痛，去楝实、延胡，加当归。四帖，疟罢能餐，而头尚痛，再加杞、菊。服三剂，头不疼，改用甘麦大枣，加归、芍、杞、菊、竹茹、蒲桃干、藕调之，经行而愈。", "13171": "陈氏妇，季夏患疟，寒微热炽，舌红不渴，而思啖瓜果，不饥不食，二便皆通，夜不成眠，汗多神惫。孟英审脉虚软微数，虽属暑疟，邪不甚重，惟营阴久亏。不须重剂，诛罚无辜。以西洋参、知母、芩、茹、白薇、麦冬、西瓜翠衣为剂，果三嗓而瘳。", "13172": "胡氏妇患疟，寒少热多。自云阴分素亏，医进清解凉营之药多剂，其热愈炽。改用养阴法，呕恶烦躁，自欲投井。或谓今年中伏之时，风雨连朝，人须挟纩，有何暑热？而多服凉剂，以致疟来发躁，必属虚火，拟以姜附治之。病者云：吾舌已脱液，阴将涸矣。坚不肯服，而请决于孟英。脉至滑数，右寸关更甚。视其舌淡白而光滑，俨似无苔，其实有苔如膜，满包于舌也。证属阴虚吸暑，兼以痰阻清阳。初治失于开泄耳。授菖、茹、连、半、旋、茯、苏、枳、枇杷叶为小剂，取其轻清开上也。两服，舌即露红，呕止受谷，疟热亦减。又两服，疟竟罢。孟英曰：余亦初不料其若是之神也。随以清养善后而安。", "13173": "高某，以阴虚之体而患疟于暑月，久而不愈。冯、黄二医佥用补养矣，而杳不知饥，欲噫不畅，便溺艰涩，渴喜沸汤。孟英诊脉缓涩不调，按其胸次坚而不柔，舌上满布干黄薄苔，曰：气机郁结，痰滞未行，如何遽投补剂？予菖、贝、旋、蒌、苏、桔、连、半、紫菀、枇杷叶为方，四帖而愈。始从调养以善其后。嗣有王雨苍仲郎之证治，与此略同。", "13174": "陈德斋令侄缉庵患疟，黄某连投小柴胡汤，渐至热势如长，抚之烙手。时当盛暑，帐幔不启而不得汗，神情瞀乱，大渴苔黄，脘闷欲呕，便秘溺赤。孟英按脉软滑而数，身面肤赤。乃暑湿挟痰𫐖輵于中，气机阻痹，宜予清宣剂。以菖、茹、蒌、枳、知、滑、芩、连、花粉、枇杷叶、西瓜翠，服后痰即渐吐，异日疟来有汗。病者卧于藤榻，身穿西洋布汗衫短裤，其汗但出于衣不遮蔽之处。孟英适至，诊毕令裸其体，汗即遍出，热亦寻退。方不加减，四剂疟断更衣，胸舒安谷。另以轻清肃涤余邪而愈。（世人不论天时，不究病因，但知盖覆以取汗者，宜于此案探讨其未发之义，不可草草读过也。）", "13175": "许子芍年甫冠，平素饮食不节，气滞多痰。偶患时疟，溺赤苔黄，脉至滑数，脘闷不饥，孟英投清解一剂。其门下医者黄某云：疟疾以小柴胡汤为主方，乃舍之不用，而以竹茹大寒之品，遏伏其邪；菖蒲散心之药，耗损其神。此病虽轻，而药已误，恐有变证。病家闻而惑之，次日即服其方，病势日进，辄云菖蒲散心，以致神气不安；竹茹寒滞，以致邪不能解。小柴胡方内加入桂枝、首乌等药，狂热尤甚。黄后荐招任某会诊，交口以为开手一药之误，恐延虚脱，径用生脉、六味，加龙、牡、杜仲、续断、阿胶之类服之。半月后，病者目不能张，畏闻声响，语出无音，身挺而重，不能转侧，略一动摇，则手足震掉，如擂鼓然，房中几案皆为撼䐈。黄任二医佥云汗脱在即，举家皇皇。其堂兄兰屿虀夜拉孟英往视，脉甚弦疾，曰：病药也。其何能脱？疏方以天竹黄、竹茹、竹叶、竹沥并用。病者闻而咋舌，谓一味竹茹酿成大病，一方四竹能不杀人？仍服任某补剂，以冀留人而再治病也。又旬日，疟径不作，至时惟脑后之枕骨与两足跟著席，身则反张如弓，如是数刻，则昏乱狂走。医者诿为祟病，符醮水陆，大弗不赀，而病如故。既而黄某疽发于背，任亦托病不出。所亲陈雪舫力举孟英胸无畦畛，不妨再恳其挽救。病家计穷，始为谆请。脉仍弦疾而左尤坚搏，且善啖而腹胀如石矣。孟英曰：幸而便通，犹可无虞。以旋覆、赭石、菖蒲、胆星，枳实、黄连，青黛、整块朱砂两许，合四竹为方，调服苏合香丸。一剂而反张狂谵皆减，病者云：我今日如梦初醒，而精神自觉惘惘。次日仍用原方，调以玉枢丹。得泻四次，腹胀遂减，反张狂谵悉蠲。惟至时尚有气逆肢掣耳。乃去玉枢丹，令吞送当归龙荟丸。大便日泻，胸腹渐柔。又服五剂，逆掣皆平。改用沙参、丹参、石英、茯神、白薇、栀子、丝瓜络、贝母、海䖳、凫茈等，清理善后而愈。孟冬已完姻矣。嗣其仆陈福，陡患身面如金，便血吐血，求孟英视之。身热苔垢而肢冷手紫，脉至如丝，曰：此急黄证，而兼血溢于上下，即所谓瓜瓤瘟也，药不及救。越日果亡。（黄某，敦爱局疡医也，年逾六旬。忽患背疽，闻服参茸等药七日而亡。夫背疽之败，何至如是之速？必是暑热为患，而误从温托耳。杨素园大令批《仁术志》云：朱砂不宜入煎剂，当生研少许调服，愚谓朱砂但忌火炼，不忌汤煎。且整块而煎，仅取其气，较研服其质者尤无弊也。余涧花《印雪轩随笔》云：刑幕郑春潭，患秋感发狂，谵语喃喃，若与人争辨。谓有二鬼向其索命，乃索笔作遗嘱，处分身后事。如是者数昼夜，山右武君视之曰：非鬼也。病由邪热未清，遽服补剂耳。如法治之，浃旬而起。设非武君，不又为谈因果者，添一公案哉。子芍之证，亦犹是耳。）", "13176": "陈载陶，年五十五岁，患疟两旬，始迓孟英诊之。脉不浮而弦滑且数，按之愈甚，苔色黄腻满布，热至大渴，极喜冷饮，小溲赤臭，热时则点滴茎痛，大解不行，间数日则略下稀水。是暑热挟痰见证，疏清解法予之。及阅前医之方，初则柴、桂、姜、枣，嗣用参、甘、耆、术、首乌、草果之类，温补杂投，其疟日甚。其发日迟，其补日峻，其口日渴。乃令热时少饮西瓜汁一二杯，病者饮瓜汁而大快，辄恣饮一二碗。盖谓其体厚阳虚，中气不足，故溺赤而便稀水。又云暑是阴邪，热自湿来，不可稍犯寒凉之药，因仿景岳治阴虚伤寒以冷水与桂附并行之例，而令其服温补以治疟，少佐瓜汁以解渴也。噫！景岳此案之不可为训，叶香岩发挥于前，魏玉横辨谬于后，奚可尤而效之乎？治而勿愈，反责病人过饮瓜汁使然。余谓此证，苟非日饮瓜汁一二碗，早以液涸痰胶，燎原莫救也。病者闻而颔之。服数剂，胸前赤斑密布，疟渴皆减，溲渐通，苔转白。前医云：再不温补，恐其骤变。病者惑之，仍服其药，并加鹿茸、附子。又旬余，疟如故而形瘦面黧，气冲干嗽，白糜满舌，言蹇无眠。医者皇皇，病家戚戚，复延孟英视之。脉仍数，曰：邪较衰矣，西瓜汁之功也。阴受劫矣，温补之力也。极早回头，尚堪登岸。爰以西洋、生地、甘草、石斛、白石英、葳蕤、麦冬、黄连、阿胶、牛膝为方，并令熬鳖汁饮之。五剂，而疟罢嗽蠲，得眠安谷，苔亦全退。但舌红口辣，溲赤不清，前方去连、膝，加归、杞。服八剂，始解坚燥黑矢而愈。然病者喜温补，既愈仍嘱前医善后。故舌红口辣，与胸前斑点，久不能消，直至冬令。孟英力劝停药，始渐除也。有朱湘槎者，与载陶年相若体相似也。秋杪自越患疟旋杭，屡药不应，迟孟英视之，面赤脘闷，二便不行，热则谵言，苔焦口渴，予小陷胸汤，加菖、茹、栀、翘、花粉、竹叶等药。群谓肥人之体虑其阳，不敢服此凉剂。治载陶之前医，迎合主见，大投温补。载陶偶见孟英而述之，孟英曰：湘槎殆矣。此时恐无西瓜汁以救药误也。旬日后，果狂躁而亡。其未亡前一日，人已昏狂，毕某诊云：暑热内陷，意欲挽救，投以犀角等药一帖。故前医于陈证，则攘为温补之功，于朱证则卸为犀角之罪。盖明知温补易售，可以避罪邀功，故乐操其术，而不肯改弦易辙也。后载陶令兄哲堂乔梓，同时患疟，因前车之鉴，虽汗多懒语，酷类虚象，不敢从补，均依孟英作暑湿内伏治而愈。", "13177": "陈雪舫令郎小舫，年甫冠，人极清癯。偶患疟，医与柴、葛、羌、防数帖，遂不饥不寐，胸膈阻塞，汤水不能下咽，壮热神疲，汗出不解，二便闭涩，舌绛龈疼，齿缝血流，凝结于腭。孟英持其脉细而数，有下厥上竭之势，而肺未肃清，宜用轻剂。以苇茎、冬瓜子、紫菀、元参、通草、枇杷叶、旋覆、滑石、蒌皮、西瓜翠衣为方，数啜而安。嗣用养阴，西洋参不过一钱，生地不过三钱。缘其禀赋极弱，不但攻散难堪，即滋培稍重，亦痞闷而不能运也。耆、术之类，更难略试。故量体裁衣，乃用药之首务也。", "13178": "董茂清患疟，脉软脘胀，手紫面黄，便秘溺红，苔腻而渴，孟英曰：暑湿挟秽，气阻于募原，用菖、朴、橘、半、杏、滑、芩、翘、蒌、枳、银花，加雪羹出入为方。服五剂，便泻知饥，疟休而愈。", "13179": "陈芷浔主政患疟，跗肿便溏，痰多食少，时欲呕吐，间有振声。孟英取其脉，微弱而弦，不渴无苔，小溲不赤，乃中虚寒湿为患也。方以六君去甘草，加桂枝、苡仁、白芍、吴萸，投剂即减，半月而愈。", "13180": "沈陶安寒热初作，医用温散药，即眩悗不安。延孟英视之，舌绛无苔，大渴多汗，疟则寒微热甚，发时咳嗽兼呕，溺少不饥，脉洪且数。清癯之体，阴分素亏，而伏暑化疟也。予知、芩、茹、贝、花粉、白薇、银花、元参、枇杷叶、紫菀、冬瓜子等药出入为方。服后连解赤粪，疟即递轻，不半月而愈。乃兄秋粟贾于苏，因八月初五日上海寇警，吴门震恐，遂踉跄旋里。迨十七日忽发疟，但热无寒，汗多昏谵，脉亦洪数，呕嗽溺频，曲糵素躭，体丰痰滞。孟英即以治陶安法佐以开痰治之。溏解频行，其色皆赤。伏邪虽有去路，缘心阳过扰，谵渴不休，加犀角、竹叶、莲子心之类。至月杪诊时，适大战大汗之际，其家疑为有祟，方在禳祷，铙鼓喧阗，病者神气更不安恬。孟英令将蘸坛移远，并灌以神犀丹一丸。其家问此证何不用石膏？孟英曰：药有定性，病无定形。况旬日以来，苔退将净，疟即可罢，何必石膏？次日乃叔兰谷另邀一医视之，方虽相似，而迎合主人之意，加入石膏三钱，冰糖四钱，粳米一两。连进两帖，左胁即痞胀不堪，按之如柈，杳不思谷。病者悔恨云：月杪大汗之后，吾疟已休，何以更医？致生痞胀。仍迓孟英诊之，脉来涩滞，苔复腻黄。因询曾服滋腻之药乎？陶安始述其所以，孟英曰：石膏为治暑良药，吾非不善用者。因此证不止肺胃二经受暑，心肝二经皆有所病，故不用也。且内挟痰湿者，虽当用亦必佐以宣化之品。辛丑夏家竾伯茂才患疟，初起误服此公石膏两剂，腹遽胀，延成疟鼓，几至不起。后服多剂桂、附，及金液丹而始愈。盖此公但见其疟至睛赤，裸衣狂走，而不研察其病情也。余究其因，遽云疟发时，其热自下而上，比之心头，即觉昏冒，且口不渴而恶凉饮，乃湿上甚为热之证。彼时若以苍术同用，则湿热之邪一齐同解，奚至延鼓哉？贤昆仲之疟热亦自下而上，系挟肝阳上升，故热升则必呕嗽。而令兄更有伏痰，故余剂中多用连、夏、菖蒲、滑石之类以化之。今疟罢热去之后，痰湿未清，石膏已误，再佐糖、米之甘缓，俾腻塞而不行。苟不急为宣导，则鼓胀之萌也。遂以蒌、薤、菖、枳、连、夏、旋、橘、楝、实、延胡、鸡金、雪羹之类，出入互用。至二十剂，痞始泯然，粥食递加，苔亦退尽，而竟不更衣，改用参、归、杞、芍、橘、半、苁蓉、首乌、鳖甲等药。十剂，大解始下，坚黑异常，连解数日始净。随予峻补善后而痊。秋粟之室，怀妊九月，加以忧劳，九月初七日患疟间作。寒热之时，胎痛上窜，或下坠腰疼，更兼痰嗽带下，口渴无苔，其势甚危。孟英但于清解之中，加葱白、苏梗投之，连下赤矢，痛势递减。第疟虽渐杀，至期必两发，病者苦之。孟英曰：愈机也，毋忧焉。果浃旬而愈。复苦脘痛呕吐，勺水不纳，药亦不受，授以藕汁、芦根汁、梨汁，少加生姜汁，和入蔷薇露、枇杷叶露、香橼露，徐徐呷之渐瘥。嗣予滋养药加黄柏，服之而愈。迨冬至分娩甚快健。又秋粟令郎十岁，陶安令爱八岁，俱患间疟，佥虑胎疟难瘳。孟英曰：无是理也。小儿内无七情，苟能慎饮食，较大人易治焉。剂以清解，旬日胥痊。", "13181": "沙沛生鹾尹令堂，年五十七岁，体素弱而多怫郁。秋间患疟于诸暨，医治未效。冬初来杭，谢某叠进温补，其势孔亟。寒微热炽，昏谵瘈疭，目不识人，舌绛无液，苔色黄燥，便秘不行。延孟英视之，脉洪滑右甚，左手兼弦，乃痰热深蟠，内风煽动也。予知母、花粉、蒌仁、竹茹各三钱，佐以栀、薇、翘、贝、橘红、莲心。一饮而更衣溲畅，胸次较宽，痰嗽口糜，且知头晕，乃去知母、花粉、蒌、翘，加沙参、苡、斛、麦冬、野蔷薇露。次日疟来甚减，糜退口干，神惫音低，津虚痰滞也。去苡仁、枇杷叶、蔷薇露，加知母、花粉各一钱五分，甘草五分，和入藕汁一杯。服二帖，疟至甚微，口干倦卧，脉则右虚左数。用养气充津、蠲痰清热法，西洋参、盐橘红、归、甘、杞、斛、冬、茯、茹、蕤，和入藕汁。服两帖，疟休神爽，咽痛唇糜，饥不能餐，余焰内燃也。去杞、斛、甘草，加生地、牛膝。四剂后，咽唇皆愈。神惫懒言，仍加杞子、甘草。服二剂，胃气渐苏，口犹少液。因涉嗔怒，暮有微热，肤肿欲呕，口干便秘，即去地、冬、杞、甘、膝，加连、楝、蒺藜、石英、丝瓜络、冬瓜皮。一啜热去呕蠲，而腹犹胀，去西洋参、归身、冬瓜皮、石英、黄连，加沙参、旋、芍、延胡、香附、藕。一剂胀消，而口淡便秘，饥不能餐。改用西洋参、木瓜、银花、延胡、蒺藜、苁、归、芍、斛为方，投匕而便行，三啜而肿尽消，始予高丽参、紫石英、橘、半、归、冬、菖、茹、牡蛎调养。续去菖、半，加杞、地、鳖甲而愈。嗣因登圊跌仆而发寒热，周身骨痛，会阴穴起一瘰甚疼。乃以高丽参、骨碎补、合欢、木瓜、杜仲、丝瓜络、鹿角霜、首乌、鳖甲、杞、柏、归、甘、苡、膝、苁、斛等出入为方，外用葱白杵烂，蜜调敷患处，七日而痊。", "13182": "沛生令庶母亦在越患疟，来杭后孟英视之，脘闷欲呕，汗多头重，脉来弦数，苔色腻黄。乃余邪逗留，兼挟肝郁。以枳、朴、芩、半、茹、斛、蒌、菖，加苏叶、炒黄连投之。痰涎大吐，邪已外越，脘胀口干，寒热复作，乃去朴、半，而加艽、翘。吐犹不止，聚气上肿，渴饮无眠，筋瘈便秘，改用金铃子散合雪羹，加旋、赭、茹、半、姜汁炒栀子、苏叶、炒黄连。一饮而呕渴减，气下行，即去金铃子散、旋、赭，加沙参、归、斛。服五剂，各恙皆安，神惫汗多，为用沙参、归、斛、芩、橘、栀、连、茹、藕，二帖。又因嗔怒，左胁作胀，苦渴不饥，暮热便秘，于前方加紫、芍、金铃子散，一啜胁胀即舒。惟气冲口苦，饥不能餐，自汗耳鸣，头左筋惕，改授沙参、当归、鳖甲、石英、竹茹、牡蛎、蒺藜、菊花、丝瓜络。服旬余，眠食皆适。但暮则火升，口干易汗，去蒺藜、丝瓜络，加黄连、麦冬，合甘麦大枣汤。服浃旬，经行腰痛，头震耳鸣，八脉久亏也。调养奇经以善后而康。", "13183": "四弟妇怀娠临月，西甫起病之次日即患疟。因弟病日剧，不免忧劳。至第五日，孟英视之，脉欲离经，腰疼腹坠，伏暑化疟，将娩之征。以栀、豉、苏、归、芩、连、茹、半、知母、葱白，服两帖而产。产后疟来颇减，恶露不行，腹不胀疼，不饥而渴，投栀、滑、薇、茹、泽兰、丹参、通草、桃仁、茺蔚药。一剂，恶露即行，而狂言不寐，面红口渴，人皆危之。盖杭谚有云：夫病妻怀孕，铁船过海难逃命。未产先萦忧惧，既娩血去火炎，故昼夜辄以铁船沉海云云。孟英于前方去泽兰、通草，加琥珀、菖蒲、胆星、灯心，和以童溲投之。一饮神识渐清，再剂即安睡矣。去琥珀、菖、星、桃仁、灯草、茺蔚，加知母、麦冬、甘草、沙参、枇杷叶，冲入藕汁一杯。三服，解赤矢而苔退，疟亦减而嗽痰。改用沙参、枇杷叶、冬瓜子、甘、斛、栀、薇、茹、翘，两帖。嗽减犹渴，而身痛，去栀、薇、枇杷叶，加归、贝、鳖甲。四帖而疟罢，眠食咸安。调养至弥月，即出房矣。", "13184": "德清徐子瑞令正，屡次堕胎，复多忧郁。汛行之际，患疟经止，而两耳骤聋，虽对面疾呼，亦不闻也。不饥不渴，不语不眠，便秘遗溺，仰面静卧而已，惟热至则昏谵欲厥。乃父沈悦亭谓其热入血室，拉孟英视之。脉滑数而右大，按之皆虚，两尺尤甚，胸下拒按，曰：此下元虚损，故耳聋若是，即精脱之征，岂可因汛遽止而辄通其血乎？然气郁痰凝，苔色白腻，上焦邪实，补且缓商。先予小陷胸合蠲饮六神汤，加雪羹，开痰行气。悦亭韪之。三服便通，胸不拒按，苔化黄色，疟即较轻，改以沙参、归、斛、茹、半、翘、芩、菖、橘、甘、艽。五剂，疟止，渐思饮食，二便皆调，两耳仍聋，脉形细弱。乃用大剂培养药，善后而愈。", "13185": "仲冬余游姑苏，有长洲朱姓患久疟，求诊面肿目黄，声音不爽，溲赤腹胀，脉滑而弦。湿热蕴隆，失于宣解，苔腻无汗，食少痰多，与清化方。嘱其慎口腹，戒甜腻。渠云此间名手，皆曰药饵之外，须日饮糖汤，庶久疟易愈。余曰：渠但知表散，可以发汗解邪，糖汤可以和中已疟，而愈散愈不解，愈和愈不已者，是执死法以限活病也。再信其言，必成疟膨。病人闻之悚然。亟服余方数帖，得汗而愈。", "13186": "秀水董君枯匏之夫人，余于秋仲，偶诊其脉，知其八脉久亏，积劳多郁，故指下虚弦而涩，寒热时形，虚火易升，少眠善悸。性又畏药，不肯节劳，至冬令证类三疟。余以病未能往视，来信云：桐乡传一妙方治三疟，效验如神。方用甜茶、半夏各二钱，川贝、槟榔各三钱，橘皮、甘草各一钱五分，干姜一钱，木香五分，凡八味。已服三帖而瘳。余即函复云：此乃劫剂，仅可以治寒湿饮邪为患之实证。设虚证热证，服之虽愈，必为后患。故抄传单方，最非易事。若好仁不好学，功过恐不相敌也。既而病果复作，较甚于前。余与吕君慎庵同议镇养柔潜之法，始得渐愈。后闻服此方者，率多反复。乃郎味清茂才，深佩余之先见云。", "13187": "前月中旬，余过濮院，有香海寺前一妇，患三疟，求诊。面白唇红，舌绛而渴，寒微热盛，溲短便艰，汛事先期，不眠脉数，乃暑邪侵营也。与元参、丹皮、知、薇、蒿、栀、花粉、鲜斛、竹叶之方。至八月下旬，再游其地，渠复求视云：前方服即病减，至二十剂而痊。乃子以为病后须服补药，才四帖，疟复作，遂不敢再进。余谓此必温补方也。阅之果然。仍授清化之剂，五服而瘳。", "13188": "山妻怀孕四月，患间疟腹痛，便溏汗多呕闷，乃痰气内滞，风暑外侵，脉滑而弦。与枳、桔、苏、连、柴、芩、菖、夏，三剂而瘳。", "13189": "大女馥宜患微寒热炽，每发于夜，汛不当期而至，口渴便闭，目眩多汗，米饮不沾，暑热为疟也，脉洪数。以知、芩、橘、半、蒿、薇、鲜斛、元参、栀子、花粉。服六剂，而热减大半，去蒿、半，加西洋参、麦冬、竹茹、枇杷叶。又六剂，而便行疟止，随去元参、鲜斛，加归身调之而愈。", "13190": "季杰弟簉室之疟，日轻夜重，少腹觉有块上冲，则呕嗽并作，杳不进谷。余游禾归，已交八日矣。脉软以涩，是肝郁于内，暑侵其外也。用芩、夏、翘、滑、葛、蛤、苏、连、旋、橘、丝瓜络，服六帖，诸恙霍然。随与清养善后。仲秋二十八日，余游濮院归，是夜又徒患霍乱，腹痛异常。余起诊其脉，细数而弦，肢冷畏寒，盖覆甚厚。询其口不渴，而泻亦不热，惟小溲全无，吐者极苦，舌色甚赤。乃新凉束暑也。玉枢丹、绛雪灌之，皆不受。泻至四五次，始觉渐热，而口大渴，仍不受饮，语言微蹇。余令捣生藕汁徐灌之，渐能受。随以芩、连、苡、楝、栀、斛、桑叶煎服，痛即减，吐泻亦止。次日知饥，略受食，神惫已极，筋络酸疼，与清养法而痊。", "13191": "秋杪山妻怀孕已七月，又患疟，医从清解不应。半月后，转为间作。时余卧病省垣，家人恐添忧虑，初不我闻。延至匝月，病渐濒危，钱君意山、管君芝山，放棹迎余，扶病归来。诊脉软滑，而尺带虚弦。凡疟至一时之先，必大渴，背麻脘闷，既热则头疼腿足肿胀。寒不过一时，而热有七八时之久，骨瘦如柴，肌肤甲错，便坚溲涩，心悸无眠，目不见人，苔光无液。乃真阴素亏，水不涵木，风阳内炽，耗血伤津，兼挟劳伤，而吸秋热。热茗频啜，米饭恶沾，腰痛而胎动不安，势已十分险恶。遂与西洋参、元参、知、薇、蒿、菊、菖、麦、栀、甘、桑叶、竹沥，两剂。嗽痰甚多，渴闷稍减，去桑、菊、栀、蒿，加橘红八分，苏叶五分，葱白两茎。又两剂，疟止，吐痰更多，舌色渐润，去元参、知、薇，加冬瓜子、茯苓、蛤壳，一剂。嗽虽减，而左胁时疼，乃用北沙参、熟地、麦冬、蒌仁、楝实、石菖蒲、丝瓜络、十大功劳、藕，养阴柔木，而清痰热，服之甚妥。然目虽能视，而早晨必昏卧如迷，遂增熟地，加白薇、归身，一帖。寒热陡作，面赤气冲。或咎补早，疟复。余曰：非也。此不耐归身之窜动耳。即去此一味，加葱白、蒲桃干，服之果愈。随去葱白，加甘草、石斛，两帖。嗽大减，胃渐和，更衣较润，惟手心如烙，两足不温。乃易沙参以西洋参，去蒌、楝，而加生牡蛎一两，盐水炒橘红一钱，二帖。足渐温，痰渐浓，而腰痛胁痛未已，又加酒炒知母一钱，两帖。痰出极多，昏卧始减，惟纳食如噎，火降即饥，舌辣腭干，小溲尚热。改用西洋参、二地、二冬、二至、知、柏、牡蛎、十大功劳，少佐砂仁为剂。服六帖，各恙皆已，能起榻，而腿软腭干，神犹贸贸。即以此方加白芍、木瓜、石菖蒲，熬膏。服至冬至后，神气始爽而痊。", "13192": "汪左泉病滞下，昼夜数十行，而即日须补岁考遗才，浼孟英商速愈之策。切脉弦滑，苔黄满布，曰：易事耳。重用芩、连，佐以楂、朴，送服青麟丸四钱。投匕而痊，略无他恙。", "13193": "陈昼三病滞下，某进通因通用法，痛泄无度，呕恶不纳，汗出息微，脉弱眩晕。孟英曰：近多伏暑之痢，此独非其证也，元将脱矣。急投大剂温补，脉候渐安。一月后甫得健复。", "13194": "高若舟之庶母，年逾花甲，体丰善泻。张某向用参术取效。今秋患白痢，张谓寒湿滞中，仍与理中加减，病遂日增。因疑老年火衰，蒸变无权，前药中复加附子。白痢果减，而腹胀且痛，不食不溺，哕逆发热。势已危殆，始迓孟英视之。脉沉而滑数梗梗，曰：暑热未清，得无补药早投乎？与芩、连、杏、朴、曲、芍、滑、楝、银花、海䖳、鸡内金之类，一剂溺行痛减，而痢下仍白。其女为屠西园之室，乃云：向服补药，白痢已止。今服凉药，白痢复作。盖病本久寒，凉药不可再用矣。孟英曰：言颇近理。使他医闻之，必改温补。但病机隐伏，测识匪易。前此之止，非邪净而止之止，乃邪得补而不行之止。邪气止而不行，是以痛胀欲死。夫强止其痢，遽截其疟，犹之乎新产后妄涩其恶露也。世人但知恶露之宜通，而不知间有不可妄通者。但知疟痢之当止，而不知邪未去而强止之，其害较不止为尤甚也。今邪未清涤，而以温补药壅塞其流行之道，以致邪不能出，逆而上冲，哕不能食。此痢证之所畏。吾以通降凉润之剂，搜邪扫浊，惟恐其去之不速，胡反以白痢复作为忧？岂欲留此垢滞于腹中，冀其化脂膏而填空隙，故若是之宝惜而不愿其去耶？幸若舟深信，竟从孟英议，寻愈。（通达之论，医所宜知。）", "13195": "十八涧徐有堂病痢，医作寒湿治，广服温补之药，痢出觉冷。遂谓沉寒，改投燥热。半月后，发热无溺，口渴不饥，腹痛且胀，巅痛不眠。翁嘉顺嘱其求诊于孟英。察脉弦细，沉取甚数，舌绛无津，肌肉尽削。是暑热胶锢，阴气受烁。与北沙参、肉苁蓉、芩、斛、楝、芍、银花、桑叶、丹皮、阿胶，合白头翁汤为剂。次日，各患皆减，痢出反热。有堂不解问故，孟英曰：热证误投热药，热结而大便不行者有之。或热势奔迫，而泄泻如火者有之。若误服热药，而痢出反冷者，殊不多见也，无怪医者指为久伏之沉寒。吾以脉证参之，显为暑热。然暑热之邪，本无形质。其为滞下也，必挟身中有形之垢浊。故治之之道，最忌补涩壅滞之品。设误用之，则邪得补而愈炽，浊被壅而愈塞。耗其真液之灌溉，阻其正气之流行。液耗则出艰，气阻则觉冷。大凡有形之邪，皆能阻气机之周流。如痰盛于中，胸头觉冷；积滞于府，脐下欲熨之类，皆非真冷，人不易识。吾曾治愈多人矣，徐极叹服。仍议育阴涤热，病果渐瘳。", "13196": "庄芝阶舍人之外孙汪震官，春前陡患赤痢。孟英诊之，脉滑数而沉，面赤苔黄，手足冷过肘膝，当脐硬痛，小溲涩少，（此大实症也，何不加大黄荡涤之？）伏热为病也，与大剂芩、连、栀、楝、滑石、丹皮、砂仁、延胡、楂曲、银花、草决明等药。两服手足渐温，（清热之效。）而脚背红肿起疱如蒲桃大一二十枚。（湿热下注也。若如前方加大黄荡涤，当不至此。）四服后腹痛减，苔退而渴，于原方去楂曲、砂仁，加白头翁、赤芍、海䖳。旬日后痢色转白，而腿筋抽痛，乃去丹皮、滑石、赤芍，加鸡金、橘红、生苡、石斛。（热久伤阴也。古人急下存阴之法，原以仿此救法好。）两服痛止溲长，粪色亦正，脚疱溃黄水而平，谷食遂安，改用养胃阴清余热之法而愈。（合法。）闻孟英治此证，每剂银花辄两许，尚须半月而瘳。设病在他家，焉能如此恪信。苟遇别手，断无如此重剂。况在冬春之交，诚古所未有之痢案，后人恐难企及。（此案步步合法，特少一番荡涤之功，故觉少延时日耳。然凉剂已畏其寒，若加荡涤之品，必不敢服此。治病之所以难也。）", "13197": "王苇塘患滞下，医投枳、朴、槟、楂之药。数服后，肢冷自汗，杳不进谷，脘闷腹痛，小溲牵痛，举家皇皇。孟英视脉细涩，舌绛无津，是高年阴亏，伏暑伤液。况平昔茹素，胃汁不充，加以燥热之药，津何以堪？因与沙参、银花、苁蓉、白芍、石斛、木瓜、甘草、楝实、扁豆花、鲜稻头。（滋阴养液，兼调肝气。）数剂痛闷渐去，汗止肢温，乃加生地、阿胶、麦冬、柿饼、蒲桃干等以滋之，居然而痢止餐加。惟舌色至匝月始津润复常，阴液之难充也如此。", "13198": "一叟患滞下，色白不黏，不饥不渴，腹微痛而不胀。孟英切脉迟微，进大剂真武汤加参而愈。", "13199": "朱浚宣令堂患滞下，医闻色白，而与升提温补。旬日后，肢冷自汗，液脱肛坠，群医束手。虑其虚脱，因浼濮树堂乞诊于孟英。曰：药误耳。与大剂行气蠲痰清热之药，果渐吐痰而痢愈。又其令弟同时患此，五色并见，神昏肢搐，大渴茎肿，腹痛夜热，危险异常。孟英察脉细数，与白头翁汤，加犀角、生地、银花、石斛、楝实、延胡、芩、连、滑石、丹皮、木通、甘草梢等药。三帖后，热退神清，溺行搐止，乃去犀角、草梢、丹皮、滑石、木通，加砂仁拌炒熟地、山楂炭。服之渐安，半月而愈。", "13200": "孙渭川，年逾七旬，脉象六阴，按之如无。偶患音嘶痰嗽，舌绛无津，孟英用甘凉清润法，音开而嗽不已。仍与前药，转为滞下，色酱溺赤，脐旁坚硬，按之趯趯，舌犹枯绛，渴饮不饥，人皆危之。孟英曰：肠热由府而出，（此语甚精。）痢不足虑。第高年阴液难充，不能舍凉润为方。苟犯温燥，其败可必。幸渠家平素恪信，竟服犀角、地黄、知母、银花、苁蓉、花粉、麦冬、白芍、石斛、楝实等药。十余剂，痢止，而脐旁柔软，因去犀角，加西洋参。又服两旬，始解燥矢而溲澈胃苏。又服半月，复得畅解，舌亦润泽而愈。", "13201": "盛犀林广文之仆，患血痢，自秋徂冬，半年罔效。孟英察脉细弱而口干，腰膝酸疼，与鹿角霜、苁蓉、枸杞、杜仲、菟丝、续断、血余、木瓜、石脂、砂仁末炒熟地黄，十余剂而痊。", "13202": "丙午春，高汉芳患滞下色酱，日数十行。年已七十七岁。自去秋以来，渐形疲惫，即服补药，驯致见痢。黄某径用温补，势乃剧。延孟英诊之，右脉弦细芤迟，（脉虚证实。）口渴溲涩，时时面赤自汗。乃吸受暑邪，误作虚治。幸其所禀极坚，尚能转痢。一误再误，邪愈盛而正反虚矣。以白头翁汤，加参、术、银花、芩、芍、楝、斛、延胡，二剂即减。五剂而安。继与调补，竟得霍然。后三载以他疾终。", "13203": "孙心言以七十之年患滞下，胡某知为暑热，以青磷丸下之，治颇不谬。继则连投术、朴、夏、葛等药，渐至咽疼口糜，呃忒噤口。诸医进补，其势孔亟。伊婿童秋门迓孟英诊之，右脉滑数上溢，身热面赤，溲涩无眠，体厚痰多，时欲出汗。在痢疾门中，固为危候，第以脉证参之，岂是阳虚欲脱？实由升散温燥之剂，烁其阴液，肺胃之气窒塞而不能下行也。与大剂肃清之药，一剂知，二剂已。随以生津药溉之，痢亦寻愈。按此等痢呃，古书未载，而治法悬殊。世人但守成法，不知变通，治而不愈，诿之证危。况属年高，病家亦不之咎也。孰知有此随时而中之妙法耶？", "13204": "曹泳之二尹，将赴代理昌化任，而疟痢并作，寒少热多，滞下五色。迓孟英视之，面垢苔黄，干呕口渴，痛胀溺赤，汗出神疲，脉至洪数不清。与大剂芩、连、滑、朴、知母、花粉、银花、石膏、连翘、竹茹等药，投匕即减，三服而起。", "13205": "吴尔纯，八月下旬患滞下，腹痛异常。伊外祖许仲廉，延孟英往诊。形瘦脉数而弦，口渴音微溺涩，乃阴分极虚，肝阳炽盛，伏暑为痢。治法不但与寒痢迥异，即与他人之伏暑成痢者亦当分别用药也。与白头翁汤，（亦通治伏暑成痢之方。）加知母、花粉、银花、丹皮、金铃、延胡、沙参、芩、连服之。次日复视，痢减音开，而右腹疼胀拒按，为加冬瓜子、乌药、鼠矢。三剂而消，滞下亦愈。惟薄暮火升，面赤自汗，重加介类潜阳而痊。（此方顾及阴虚）", "13206": "谢再华请孟英治乍浦人滞下证，昼夜百余行，不饥不渴，而欲呕腹痛，上及于心胸，切其脉颇平和。是寒湿也，与时行暑湿痢大相径庭。投姜、桂、萸、朴之剂，数服霍然。", "13207": "王瘦石夫人患滞下，腹痛微呕，不饥口苦，溲短耳鸣。孟英诊曰：脉见细弱之形，肌无华泽之色，汛不行而早断，舌紫黯以无津，是素质阴亏，情怀悒郁，二阳默炽，五液潜消。虽吸暑邪，莫投套药。予白头翁汤，加雪羹、银花、栀子、楝实，数剂而减。继去雪羹，加生地、苁蓉、柿饼、藕汁而安，改授甘麦大枣、加西洋参、生地、苁蓉、竹茹、归、芍、蒲桃干，而以藕汤煎服，调养体质以痊。", "13208": "潘圣征于仲冬患感，至十四日退热之后，杳不知饥。群医杂治，迨季冬下旬，转为滞下五色，腿肿裂血，溲涩口干，始延孟英诊之。右脉弦细而数，右弦滑而空，苔色黄腻根焦，时或自汗。乃气液两竭，热毒逗留之象。必从前过服温补之药，否则热退在十四日之期，何至延今五十余朝，而见证若是之棘手哉？其弟鸿轩云：此番之病，补药不过二三剂，惟仲秋患疟时，医谓其苔白体丰，云是寒湿，尝饵附桂数十剂，且日饮烧酒耳。孟英曰：此即酿病之具矣。治病且难，何况有如许之药毒内伏，更将何法以生之耶？坚不立方，其家必欲求药，以期扶持度岁。孟英曰：是则可也。以白头翁汤，加银花、绿豆、归身、白芍、陈米、燕根、兰叶、藕为剂，而以补中益气大料蒸露代水煎药。服后焦苔渐退，粪色亦正，举家喜出望外，复丐孟英图之。奈脉无转色，遂力辞之。又沉听松鹾尹太夫人，季秋患疟。孟英尝往诊之，曰：伏暑所化。且体属阳强而多痰火。切勿畏虚，辄从温补。奈病者期于速愈，广征医疗。或以为证属三阴，或谓是子母疟，或指为老年胎疟，众楚交咻，病不能愈。延至季冬，亦转为痢，且肤肿臀疮，口糜舌疱，诸医束手。复请诊于孟英，脉与潘同，不可救药。", "13209": "王雨苍室，仲秋患滞下，治两旬而罔效。何新之荐孟英往视，脉来弦数而滑，腹坠腰疼，溲少口干，面红烦躁，知饥能食，夜不成眠，而滞下赤白，从无粪色相兼，及至更衣，又极艰涩，略无痢色相杂。通补温凉，服皆不应。稍投升举，气塞于胸。询其月事，因痢愆期。孟英曰：此病不在肠中也。能食便坚，府气并不窒滞。阴虚木旺，营液因而旁溢。缘冲任隶于阳明，平人气血循经，各行其度，岂有冲任之血液，可从大肠而出之理乎？然天地虽有定位，山泽可以通气。周身脉络，原自贯穿。挹彼注兹，风阳所煽。犹之交肠证粪从前阴而出。举一反三，病机可悟。何极叹服！爰以乌鲗、茜根、阿胶、鲍鱼、苁蓉、枸杞、柏子仁、黄柏、银花、藕为剂，一服即减，不旬而瘥。续参、熟地、当归、龟板、鹿霜、善后而愈。（鲍鱼，淡干鱼也。诸鱼皆可为之，然以石首鱼为胜，俗谓白鲞是也。惟台州三伏时所干者，味淡而香，色白尾圆，世称松门台鲞，可以入药，无腥咸作吐之弊。其误用蝮鱼者，盖失考也。）", "13210": "朱生甫明经，以花甲之年，偶在嘉兴患滞下甚剧。急买棹旋杭，集诸医议治。许敬斋宗景岳，谓痢必本于寒湿，主干姜、桂、朴，以温化；洪石生尚东垣，闻其向患脱肛，主清暑益气以举陷。或云素善饮而有鼻衄，血热阴亏。既受暑邪，宜玉女法以两清；或云痢必有积，不必问其余，宜大黄、归、枳以荡涤。聚讼纷纭，乃郎仲和等不知所从，而质诸孟英。诊毕遂问此证何？当用何药？曰：此滞下证之最难治者也。痢初作即不能起于榻，而五色并见，噤口不食，非暑热之深受，一何至于此极耶？满面红光，鼻赤尤甚。肺热素炽，暑火烁金，故水湿化源，溺少而涩，此不可以温燥再劫其津也。肢掣无眠，合目呓语，时时烦躁，视物不明，畏热喜风，口干易汗。阳气浮越，暑渐侵营，故苔虽腻黄，尖红根黑，此不可以升散再扰其阳也。胸次不舒，饮水欲噎，欲噎不达，欲嚏不能，茎缩易嗔，时有恶梦。肝多怫郁，痰阻清阳，故升降不调，中枢窒滞，此不可以滋涩再碍其机也。又非寻常之痢，病仅在府，可以推荡以为功也。参之于脉，右寸关缓滑而寸较抑，左则弦洪而数兼上溢，故知其气郁痰凝，暑火深受，风阳内动，久耗心营。所幸两尺皆平，身无大热，如能治之中肯，尽可无虞。仲和出诸方云：然则此皆不可服乎？曰：咸治痢之法也。惜尊翁之症，不能合于此药耳。若尊翁之恙，见证虽太错杂，而责重在于肝经。肝属厥阴，风火内寄，故此经之痢，宜柔宜凉，忌刚忌温。以肝为角木，龙性难驯，变化飞腾，病机莫测。但使风阳靖息，庶几险浪不兴，纵有别脉未清，自可徐为疏瀹也。仲和闻而心折，力恳图维。于是以仲圣白头翁汤为主方，加石菖蒲、川贝母、竹茹，开痰舒郁以调其气；犀角、银花、竹叶，凉血息风以清其心；冬瓜、蔗梢、凫茈、海䖳煮汤煎药，以清胃热而生津，化府气而濯垢。吞送滋肾丸三十粒，引肝火迅速下行。服后诸恙递减，粪色渐见，痰果频吐，神气亦安。既而粥食日增，夜眠恬适，始去犀角、雪羹、滋肾丸，加西洋参、阿胶，以复其津液。迨痢净而时有血随粪下，为加鸦胆仁，以龙眼肉包而吞之果止。惟肠鸣气泄，稀粪随流，肛坠难收，脉亦弦软，知其病去而正虚也，改用三奇散而安。继予气血交培善后，仍佐蠲痰舒郁，康健较胜曩时。盖并其积年宿疾而去之也，故生甫谢孟英诗五排结句云：不因施上药，那得挽沉疴？磈磊从今尽，先生殆缓和？", "13211": "朱饬庵孝廉，年未三旬。自都中奔丧回杭，患滞下赤白，腹不甚痛，而奔迫异常，能食溺长，医治罔效。孟英脉之，虚弦而软，曰：此不可以常痢视也。以三奇散加归、芍，送香连丸而愈。", "13212": "濮树堂患滞下，医者以其脉弱体虚，第三日即参补养，延至匝月，痛痢不减，谷食不思，饥瘦如柴，面浮足肿，口干舌绛，懒语音低，气短汗多，略难转侧。诸医无策，始迓孟英诊之。曰：初起脉微弱，为暑之本象。今按之尚数，乃阴液已伤，渴饮无苔，岂容温补？溲赤而痛，胡可酸收？见证虽危，治不可紊。为定白头翁汤，加西洋参、干地黄、炙草、白芍、麦冬、阿胶酒炒银花之剂，以水露煮陈仓米汤煎药。群议以为药太凉润，不可轻试。孟英曰：此厥阴证而胃液已伤。幸而脉未空数浮弦，亟予养阴清热，庶可图功。若徒议药不议病，纵有一片婆心，未免好仁不好学矣。病者忆及乙巳之病，深信不疑，遂服之。一剂知，六剂而痢净，舌润知饥，溲通得睡。第便溏腹痛，日必两行，左龈赤肿而疼，外涂以玉枢丹，内治以三奇散，加潞参、炙草、薏仁、扁豆、鸡䏶胵、黄柏、橘皮，吞香连丸。旬余而浮肿消，大便坚，舌苔生。起于榻而口腹不节，发热口干，乃食复也。按法治之热退，至七日始更衣。因嘱其加意珍摄，俾易康痊。奈家务纷繁，既愈，即不能静养，神机曲运，心气涣散不收，液涸津枯，而前功尽堕，惜哉！然此案自可传也。", "13213": "陈诵芬令堂，年越古稀，精神素旺。滞下数月，病日以剧。所亲蒋策勋嘱延孟英图之，已粒米不纳，虽啜饮而咽膈阻塞，唇舌皆紫，痰中带血，吐之甚艰，日夜更衣数十次，稀粪挟以赤垢。若欲小溲，必令人重按肛门，始能涓滴而出，热如沸汤。脉则左手弦洪涩数而上溢，软滑而大，按之无神。孟英曰：此证本滞下，良由七情郁结，木土相乘。医谓高年，辄投温补酿成危证，药不可为。诵芬云：先生之言是也。家慈因春间叠闻江南之警，心甚皇皇，举家迁避，饮食顿减。夏初旋里，似已稍安。六月间患泻，饮食又减。屡进参、术、熟地、附、桂、炮姜之剂，竟无寸效。惟望鼎力斡旋是幸。孟英曰：上不能纳，下不能分，中气无权，营津两匮。既承下问，姑拟一方，仅许小瘥，不能奏绩也。诵芬从之。服后即思粥食，小溲单行。再求转方，孟英坚不承手，果至季秋而没。其方乃沙参、冬瓜子、丝瓜络、芦根、紫菀、菖蒲、竹茹、通草、薏仁、枇杷叶、陈仓米，以水露煎服也。顾铁舟赞府，精于医者也。目击其一服而进粥溺行，因叹曰：仙方也。惜遇之不早，命矣夫！", "13214": "项君香圃，患赤痢濒危。其亲庄嵋仙少府，拉余往视，脉细不饥，口干舌绛，形消色瘁，不寐溺无。禾中医者以其素耽曲糵，辄进苦燥渗利之药。而不闻景岳云：酒之为害，阴虚者饮之，则伤阴也。况病因暑热不夹湿邪，温燥过投，阴液有立涸之虞。余将旋里，为定西洋参、生地、甘草、银花、石斛、麦冬、生白芍、扁豆花、枳椇子、藕汁一方，冬瓜汤煎，令其恣服。次年春，余往禾，候庄芝阶先生之疾，有一人来拜谢，面如重枣，素昧生平，甚讶之。嵋山曰：即香圃也。面色素赤，上年因病危而色脱，故先生不识耳。承惠之方，服十余帖而愈，今又善饮如昔矣。", "13215": "胡孟绅乃弟季权，同时患黑斑苔秽，脉浑气粗面垢，孟英即以凉膈散投之。大解得行，脘亦不闷，斑皆透绽，脉显滑数而洪，遂与大剂凉润清肃之药。直俟其旬日外大解不泻，药始缓授。复又沉卧不醒，人皆疑之，孟英曰：痰热尚炽也。仍授大剂数帖，果频吐胶痰累日，而眠食渐安。是役也，当两病披猖之际，举家皇皇。他医或以前证为神不守舍，议投温补。后证则以为必败，闻者无不危之。赖季权之夫人，独具卓识，任贤不贰，孟英始无掣肘之虑，而咸得收功也。", "13216": "姚禄皆在金陵，适遇大水。继而回杭，途次酷热患感。顾某诊为湿邪，与桂枝、葛根药三帖，病乃剧。赵笛楼知其误治，连用清解。因见蓝斑，不肯承手。迓孟英视之，脉细数而体瘦。平昔阴亏，热邪藉风药而披猖，营液得温燥而干涸。斑色既绀，危险万分。勉投大剂石膏、知母、白薇、栀子、青蒿、丹皮、竹叶、竹沥、童溲之药，调以神犀丹。三服大解下如胶漆，斑色渐退，而昏狂遗溺，大渴不已，仍与前方，调以紫雪。数剂热退神清，而言出无伦，犹如梦呓。或虑其成癫。孟英曰：痰留包络也。与犀角、菖蒲、元参、鳖甲、花粉、竹茹、黄连、生地、木通、甘草为方，调以真珠、牛黄，始得渐安。改授存阴，调理而愈。", "13217": "仁和戴君文叔令嫒，年十二，患风斑，睛赤，服升散药数帖。忽觉胸次不舒，饮食下咽即吐，时作时止，医皆莫措。六七日后，其作愈频，而有欲厥之势。其亲徐君乐亭嘱延余诊，脉弦而数，夜不成眠，目赤未蠲，苔黄口苦。是发斑不由外感，乃稚质阴亏。风阳上越。助以温散，厥少陡升，肃降无权，因而吐逆。以连、柏、橘、半、栀、菀、茹、旋、海䖳，少加苏叶煎，送当归龙荟丸。一剂知，二剂已。", "13218": "梅溪蒋君宝斋令堂，自上年夏秋间，患痢之后，神疲少寐，不能起床。医谓其虚，率投补药，驯至惊疑善悸，烦躁呓言，胁痛巅疼，耳鸣咽痛，凛寒暮热，大汗如淋，晕厥时形，愈补愈殆。李君苍雨邀余诊之，脉弦滑而数，白睛微红，而眼眶如墨，舌绛无苔。因问胸闷乎？曰：闷甚。便秘乎？曰：秘甚。溺热乎？曰：热甚。岂非气郁而痰凝，痰阻而气痹？肺胃无以肃降，肝胆并力上升，浊不下行，风自火出。虽年逾五旬，阴血不足，而上中窒塞。首要通阳，为处小陷胸，加菖、薤、旋、茹、苓、枳、郁李仁。群医谓是猛剂，无不咋舌。宝斋云：镇补滋敛，业已备尝，不但无功，病反日剧，且服之。果一剂知，三剂安。已而余有会垣之游，前医谓病既去，负进守补月余，仍便秘不眠，胸痞躁乱，加以发斑腹痛，人皆危之。时余在禾中，函气往视。仍用前法加减，合雪羹投数剂，连得大解，率皆坚燥。改与柔养，更衣渐畅，粥食渐增，以潜镇舒养之剂善其后。", "13219": "段春木之室烂喉，内外科治之束手。姚雪蕉孝廉荐孟英视之，骨瘦如柴，肌热如烙，韧痰阻于咽喉，不能咯吐，须以纸帛搅而曳之。患处红肿白腐，龈色皆糜，米饮不沾，汛事非期而至。按其脉，左细数，右弦滑。曰：此阴亏之体，伏火之病，失于清降，扰及于营。先以犀角地黄汤，清营分而调妄行之血。续与白虎汤，加西洋参等，肃气道而泻燎原之火。外用锡类散，扫痰腐而消恶毒。继投甘润药，蠲余热而充津液，日以向安，月余而起。", "13220": "陈书伯庶常令弟保和，年未冠，患失音咽痛，孟英与犀、羚、石膏、元参、豆根、牛蒡、射干等大剂清肃之药，音开而咽糜。吹以锡类散，糜愈而疹点满布，左目及耳后皆肿。方中加以鲜菊叶二两，疹愈痰嗽不已。仍主前法，服三十余帖而痊。此证脉滑且数，口大渴，初终未曾误药，故能愈。其庶母同时患喉糜，而头偏左痛，（肝风。）心悸欲呕，壮热烦躁，脉弦细数。孟英曰：此兼阴亏风动也。初以犀、羚、元参、菊花、丹参、栀子、桑叶、马勃投之，外吹锡类散，咽愈热退。续用二至、二冬、生地、石英、苁蓉、龟板、茯苓，滋阴潜阳而瘳。又其二令妹亦患喉疹，汛事适行，四肢酸痛，略难举动，气塞于咽。孟英诊脉弦滑，以犀、羚、旋、赭、茹、贝、兜铃、牛蒡、射干、豆根、花粉、银花、海䖳、竹沥、丝瓜络等，（此则专事情热蠲痰而已。须合三案，而细参其同异处，方有会心。）出入为方，兼吹锡类散而瘥。（变证虽多，不外肺胃二经积热。得其主脑，尚非难愈之证。）", "13221": "周鹤亭令郎，年甫五龄。痘后月余，清凉药尚未辍，忽发壮热。幼科治之势益张，肢瘈面赤，呕吐苔黄，渴而溺清，时或昏厥。证交六日，其外祖何新之，邀孟英诊之。脉甚弦洪滑数，心下拒按，便秘汗多，投小陷胸，加石膏、知母、花粉、竹叶、枇杷叶、贝母、雪羹。二剂，各恙皆减，溲赤便行，继与清养而安。（凉药未辍，而忽见如此之证，即不按脉，亦可知为新感温邪矣。）", "13222": "许安卿患咽痛，疡科黄秀元连与升散之药，延及龈肿，牙关不开，舌不出齿，自汗脉涩，绝谷濒危。其族兄辛泉，逆孟英往勘，即洗去满颈敷药，而以菊叶捣涂，吹以锡类散，煎犀、羚、元参、射干、马勃、栀、贝、山豆根等药灌之，数日始痊。（宜降而反升之，宜其病之增剧矣。）", "13223": "胡韵梅年已逾冠，因夜坐感寒，患头疼恶冷，呕吐肢冷。孟英视之曰：舌绛脉数，斑疹之候，断非受寒也。幸胡平昔钦信，遂与清透药服之。次日点形圆绽，细询果未出痘，但火势甚炽。恐其惑于俗论，嘱请专科王蔚文会诊，所见略同。一路清凉，自起发至落茄，毫不不杂一味温升攻托之药，而满身密布，形色粗紫，浆浓痂黑，便秘不饥，渴无一息之停。苟不如是用药，其能免乎？此建中琐言之所以有功于世也。此大实之证，故治宜如此。予见一小儿出痘，自始至终，参、茸不辍于口，稍停其药即恹然不振，正与此案相对待。可见用寒用热皆宜随证变通。未可执一而论也。", "13224": "溽暑之令，瘄疹盛行。幼科仅知套药，升、柴、防、葛乱施，殆亦疫疠之病，造化默行其杀运欤？陈仰山家患此者十余人，其长郎书芾孝廉之女势最剧。以瘄甫出，而汛至也。医者却走，始延孟英视之。脉滑而数，舌绛大渴，面赤失音，不食便泻，曰：此由发散太过，火盛风炽，气血两燔。气分之邪，由泻而略泄其焰，营分之热由汛而稍解其焚，岂可畏其脱陷，妄投止涩耶？与西洋参、石膏、知母、麦冬、犀角、生地、连翘、甘草、石斛、丹皮、桑叶、竹叶大剂投之，三日而愈。养阴善后，遂以渐安。其余或轻或重，孟英一以清解而痊。", "13225": "胡季权子珍官，甫六岁。目患内障，继则夜热痰嗽，小溲过多。医作童损治，服滋补数月，病日以甚。孟英持脉右大，口渴苔黄，曰：伏热在肺，法当清解。及详诘其因，始言病起瘄后。盖余热未净，而投补太早，与滑石、知母、花粉、桑叶、茅根、枇杷叶、芦根、冬瓜子、杏仁。服二剂，遍身发出斑块。又二剂，斑退苔化，乃去滑石，加沙参饵之。其热头面先退，次退四肢，以及胸背，又数日甫退于腹。人皆诧其热退之异，孟英谓热伏既久，复为半年之补药，腻滞于其间，焉能一旦尽涤？其势必渐清而渐去也。热退既净，溺亦有节，痰嗽递蠲，餐加饥润，而内障亦渐除矣。", "13226": "德清蔡初泉，陡发寒热，咽痛大渴，脘闷舌绛。孟英诊脉甚数，径投大剂犀、羚、元参、丹皮、桑、栀、银花、花粉、翘、蒡之药，服后遍身发赤疹，而热退知饥矣。", "13227": "仲夏瘄疹流行，幼科执用套药，夭札实多。有王子能参军所亲楚人刘某，仅一子甫五龄。陆某见其瘄点不绽，连进柽柳等药，壮热无汗，面赤静卧，二便不行。参军闻其殆，延孟英视之，投犀、羚、白虎汤而转机。陆某力阻石膏不可再饵，仍进温散，以至气喘痰升，复加麻黄八分，欲图定喘，而喘汗濒危，二便复秘。（麻黄定喘，乃方脉中感受风寒之症施之，麻疹何其不通？）再恳孟英救之，投白虎，加西洋参、竹叶而愈。继有房氏子，亦为陆某误用温散致剧。痰喘便秘，口渴神昏，溲碧肢瘈，孟英与大剂白虎汤，加犀角、元参、竹叶、木通，调紫雪，四帖而始安。（疹为阳邪，乃肺胃湿热所致，初宜辛凉发散，令其尽出。不宜骤用寒凉，恐冰伏热邪，不能发出也。继即宜大清肺胃之药，以解余毒。从未有温散之法，至麻黄尤为禁剂，何儿科之愦愦耶？）", "13228": "李新畲仲郎，瘄未齐而痰嗽气喘，（疹中应有之症。）苔色白滑，小溲不赤。或主犀角地黄汤加紫雪，服而不效。（热在气而清其肝，故不效。）延孟英诊之，右脉洪滑而口渴。乃天时酷热，暑邪薄肺，挟其素有之痰而阻其治节，所以气机不行，而疹不能达，苔不能化，溺不能赤也。温散大忌，凉血亦非。与竹叶石膏汤，合苇茎，加杏、菀、旋、杷、海石，投之气平疹透，苔退色红，小溲亦赤，数日而愈。（治疹原以清肺为第一义。）", "13229": "徐艮生室，年四十余，于酷暑之时患瘄。所亲沈悦亭连与清解，不能杀其势。为邀孟英视之，体厚痰多，脉甚滑数，扬掷谵妄，舌绛面赤，渴饮便涩。乃与大剂白虎，加犀角、元参、银花、花粉、贝母、竹黄、竹叶、竹茹、竹沥，送滚痰丸。服后大便下如胶漆，脉证渐和。数日后去丸药，其势复剧，甚至发厥，仍加丸药乃平。如是者三次，险浪始息。悦亭复以白金丸涤其膈下留痰，续用甘凉濡润法，充津液而搜余热，渐以告愈。（此大实证也，非峻攻不愈。）", "13230": "朱敦书令爱患感，医投温散，服二剂遍身麻瘄，汛事适来。医进小柴胡汤。遂狂妄莫制，乞援于孟英。脉至洪滑弦数，目赤苔黄，大渴不寐，是瘄因温邪而发。所以起病至今，时时大汗，何必再攻其表？汛行为热迫于营，胡反以姜、枣温之，参、柴升之？宜其燎原而不可遏也。与大剂犀角、元参、生地、石膏、知母、花粉、银花、竹叶、贝母、白薇，以清卫凉营。服后即眠，久而未醒。或疑为昏沉也，屡为呼唤。（俗情可哂。）病者惊寤，即令家人启箧易服，穿鞋梳发，告别父母云欲往花神庙归位，（此即一呼唤之效也，）人莫能拦，举家痛哭。急迓孟英复视，脉象依然。嘱其家静守勿哭，仍以前方加重，和以竹沥、童溲，灌下即安。继用养阴清热而愈。（温散惟宜于伤寒、何可乱投。且既已见疹，则肺胃之热已现于外矣。与柴胡汤有何干涉？此医直是不通。）", "13231": "韩石甫大令令正，患感发疹，沈悦亭治以清解，热渐退而神气不爽，舌黑难伸，太息便秘，胸次拒按，脉弦缓而滑，投凉膈散，加知母、花粉、枳实、竹茹。一帖而苔即退黄，再服而黑矢下，神气清，即以向愈。", "13232": "汤西塍年逾花甲，感证初起，周身肤赤，满舌苔黄，头痛腰疼，便溏溲痛。伊亲家何新之诊为险候，嘱延孟英诊之。脉见弦细而软，乃阴虚劳倦，湿温毒重之证。清解之中，须寓存阴。以犀角、羚、苓、茹、银、翘、桑、苇、通草、兰叶为方，煎以冬瓜汤。服之遍身赤疹，而左眼胞忽肿，右臂酸疼不举，耳聋神不清爽。亟以元参、丹皮、菊花、栀子、桑枝、丝瓜络、石斛、竹叶，煎调神犀丹为剂。偶邀疡科视外患，亦知病因湿热，连进木通等药，脉更细弱，神益昏惫，饮食不进，溲涩愈疼，新之以为难挽矣。孟英曰：急救阴液，尚可转机。授复脉汤去姜、桂、麻仁，易西洋参，加知母、花粉、竹叶、蔗浆灌之。一剂神苏脉起，再服苔退知饥，三啜身凉溺畅，六帖后肤蜕安眠，目开舌润。或疑甘柔滑腻之药，何以能清湿热？孟英曰：阴虚内热之人，蕴湿易于化火。火能烁液，濡布无权。频溉甘凉，津回气达。徒知利湿，阴气先亡。须脉证详参，法难执一也。又服数剂后，忽然肢肿，遍发风块，瘙痒异常。或又疑证之有变也，孟英曰：此阴液充而余邪自寻出路耳。与轻清药数帖，果瘥。", "13233": "石诵羲室，久患痰嗽，诸医药之勿瘳。孟英切其脉曰：非伤风也。与北沙参、熟地、百合、麦冬、贝母、紫菀、苁蓉、枇杷叶、盐水炒橘皮、燕窝，一剂知，数剂已。初秋又患脘痛，上及肩尖，向以为肝气，辄服破削之品。孟英曰：亦非也。以砂仁炒熟地、炙橘红、楝实、延胡、枸杞、当归、茯苓、桑椹、蒺藜为方，服之良效，继即受孕矣。（合观二案，其人必阴虚肺燥之质，故用药如此。）", "13234": "邻人汪氏妇之父王叟，仲秋患痰嗽不食，气喘不卧，囊缩便秘，心摇摇不能把握，势极可危。伊女浼家慈招孟英救之，曰：根蒂欲脱耳，非病也。以八味地黄汤，去丹、泽，合生脉，加紫石英、青铅、龙、牡、胡桃肉、楝实、苁蓉投之。大解行而诸恙减，乃去苁蓉、麦冬，服旬日以瘳。初冬邵可亭患痰嗽，面浮微喘。医谓年逾花甲，总属下部虚寒，进以温补纳气之药。喘嗽日甚，口涎自流，茎囊渐肿，两腿肿硬至踵，不能稍立，开口则喘逆欲死，不敢发言，头仰则咳呛咽疼。不容略卧，痰色黄浓带血，小溲微黄而长。许芷卿荐孟英视之，脉形弦滑有力，曰：此高年孤阳炽于内，时令燥火薄其外。外病或可图治，真阴未必能复。且平昔便如羊矢，津液素干，再投温补，如火益热矣。乃以白虎汤合泻白散，加西洋参、贝母、花粉、黄芩，大剂投之。并用北梨捣汁，频饮润喉，以缓其上僭之火。数帖后势渐减，改投苇茎汤合清燥救肺汤，加海䖳、蛤壳、青黛、竹沥、荸荠为方。旬日外，梨已用及百斤，而喘始息，继加坎、板、鳖甲、犀角，而以猪肉汤代水煎药。大滋其阴，而潜其阳。（此却不必，以病者难服也。何不另用）火始下行，小溲赤如苏木汁，而诸证悉平。下部之肿，随病递消。一月已来，共用梨二百余斤矣。适大雪祁寒，更衣时略感冷风，腹中微痛，自啜姜糖汤两碗，而喘嗽复作，口干咽痛，大渴舌破，仍不能眠。复用前方，以绿豆煎清汤代水煮药，始渐向安。孟英谓其乃郎步梅曰：《内经》云：阴精所奉其人寿。今尊翁津液久亏，阳气独治，病虽去矣，阴精非药石所能继续。况年愈六秩，长不胜消，治病已竭人谋，引年且希天眷。予以脉察之，终属可虞。毋谓治法不周，赠言不早，致有他日之疑、成败之论也。", "13235": "鲍继仲患哮，每发于冬，医作虚寒治更剧。孟英诊之，脉滑苔厚，溺赤痰浓。与知母、花粉、冬瓜子、杏、贝、茯苓、滑石、栀子、石斛而安。孙渭川令侄亦患此，气逆欲死。孟英视之，口渴头汗，二便不行，径与生石膏、橘、贝、桂、苓、知母、花粉、杏、菀、海䖳等药而愈。", "13236": "许守存久患痰嗽，孟英主滋水舒肝法，以阴亏而兼郁也。业已向愈，所亲某亦涉猎医书，谓滋阴药不可过服，投以温补。已而咳嗽复作，渐至咽痛。冬初又延诊于孟英，曰：六脉皆数，见于水令，其不能春乎？果验。世人不辩证之阴阳，但论药之凉热，因而偾事者多矣。", "13237": "郑妪患咳嗽，自觉痰从腰下而起，吐出甚冷。医作肾虚水泛治，渐至咽喉阻塞，饮食碍进，即勉强咽之，而胸次梗不能下，便溏溲频。无一人不从虚论，孟英诊曰：脉虽不甚有力，右部微有弦滑，苔色黄腻，岂属虚证？以苇茎汤合雪羹，加贝母、知母、花粉、竹茹、麦冬、枇杷叶、柿蒂等药，进十余剂而痊。此证明明虚寒，何以作虚寒治不效？盖虚寒乃此人之本体，而痰咳乃新受之外邪。不治其邪，而专补其虚，则邪无出路，以致积补生热，此舌胎之所以黄腻也。孟英以清热化痰为治，尚是一半治病、一半治药误也。", "13238": "邵奕堂室，以花甲之年，仲冬患喘嗽。药之罔效，坐而不能卧者旬日矣。乞诊于孟英，邵述病原云：每进参汤，则喘稍定。虽服补剂，仍易出汗，虑其欲脱。及察脉弦滑、右甚，孟英曰：甚矣。望闻问切之难，不可胸无权衡也。此证当凭脉设治，参汤切勿沾唇。以栝蒌、薤白、旋覆、苏子、花粉、杏仁、蛤壳、茯苓、青黛、海䖳为方，而以竹沥、菔汁和服。投匕即减，十余帖全愈。同时有石媪者，患此极相似。脉见虚弦细滑，孟英于沙参、蛤壳、旋覆、杏仁、苏子、贝母、桂枝、茯苓中，重加熟地而瘳。所谓病同体异，难执成方也。", "13239": "王致青鹾尹令正，患痰喘，胡某进补肾纳气，及二陈、三子诸方，证濒于危。顾升庵参军，令延孟英诊之。脉沉而涩，体冷自汗，宛似虚脱之证。惟二便不通，脘闷苔腻。是痰热为补药所遏，一身之气机，窒痹而不行也。与蒌、薤、旋、赭、杏、贝、栀、菀、兜铃、海䖳、竹沥等以开降，复杯即减，再服而安。", "13240": "王汇涵室，年逾六旬。久患痰嗽，食减形消，夜不能眠，寝汗舌绛。广服补剂，病日以增。孟英视之曰：固虚证之当补者。想未分经辨证，而囫囵颟顸，翻与证悖，是以无功。投以熟地、苁蓉、坎、板、胡桃、百合、石英、茯苓、冬虫夏草等药，一剂知，旬日愈。以其左脉弦细而虚，右尺寸皆数，为阴亏气不潜纳之候。及阅前服方，果杂用耆、术以助气，二陈、故纸、附、桂等以劫阴也，宜乎愈补而愈剧矣。", "13241": "李华甫令正，患头震，孟英脉之弦滑，乃肝经郁怒火升也，投当归龙荟丸而瘥。然不能惩忿，其病屡发之后，更兼溺团腹胀，喘汗欲绝，亟邀孟英视之。脉甚弦涩，口苦苔黄，舌色紫黯，汛虽不愆，内2有瘀滞也。以雪羹加金铃、旋覆、栀子、滑石、桃仁、茺蔚、车前子、木通，仍吞龙荟丸。外以田螺、大蒜、车前草捣贴脐下。服后果先下黑血，溲即随通，继而更衣，粪色亦黑，遂愈。", "13242": "周光远无疾而逝。其母夫人年逾七旬，遭此惨痛，渐生咳嗽，气逆痰咸，夜多漩溺，口苦不饥。孟英曰：根蒂虚而兼怫郁也。与沙参、甘草、麦冬、熟地、龟板、石斛、贝母、蛤壳、小麦、大枣而安。（滋阴解郁，丝丝入扣。）迨夏间吸暑而患腹痛滞下，小溲热涩，其嗽复作，脉仍虚弦，略加软数，但于前方增滑石（去暑），吞香连丸（治痢）而瘳。因平昔畏药，既愈即停，至仲秋嗽又作。惟口不苦而能食，因于前方去沙参，加高丽参、五味、石英、牛膝熬膏，频服而痊。十月下旬，天气骤冷，陡患吐泻腹痛，肢冷音嘶，急邀孟英视之。脉微为寒邪直中，亟与大剂理中，加吴萸、橘皮、杜仲、故纸、石脂、余粮而瘥。其夫人亦因悲郁而患崩漏，面黄腹胀，寝食皆废。孟英用龟板、海螵蛸、女贞、旱莲、贝母、柏叶、青蒿、白薇、小麦、茯苓、藕肉、莲子心而康。次年夏，其母夫人患温邪痰嗽，脘闭汗多，孟英投石膏、竹茹、知母、花粉、旋覆、贝母、蒌仁、紫菀等药，三十剂而愈。闻者无不叹异！（此因不兼外邪，故加五味、牛膝等药，径固其本。若少兼外邪者，断不可用。）", "13243": "谢某患嗽，卧难偏左。孟英切其脉，右寸软滑，曰：此肺虚而痰贮于络，以苇茎、丝瓜络、生蛤粉、贝母、冬瓜子、茯苓、葳蕤、枇杷叶、燕窝、梨肉，投之果愈。", "13244": "古方书云「喘无善证」。喘而且汗，尤属可危。潘肯堂室，仲冬陡患气喘，医治日剧。何新之诊其脉无常候，嘱请孟英质焉。孟英曰：两气口之脉，皆肺经所主。今肺为痰壅，气不流行，虚促虽形，未必即为虚谛。况年甫三旬，平时善饭，病起于暴，苔腻痰浓，纵有足冷面红、不饥、不寐、自汗等证，无非痰阻枢机，有升无降耳。遂与石膏、黄芩、知母、花粉、旋覆、赭石、蒌仁、通草、海䖳、竹沥、菔汁、梨汁等药，一剂知，三剂平。乃去二石，加元参、杏仁服，旬日而安。俟其痰嗽全蠲，始用沙参、地黄、麦冬等，以滋阴善后。", "13245": "顾仙槎，年越古稀。仲冬偶患痰嗽，服表散药数帖，气喘如奔，欲卧而不能著枕，欲食而不能吸纳，痰欲出而气不能吐，便欲行而气不能送，日夜危坐，躁汗时形。其婿家请孟英视之，按脉虚洪豁大，而舌色干绛，溲赤点滴。证属阴亏，忌投刚燥。与西洋参、熟地、苁蓉、枸杞、蒌仁、麦冬、牛膝、茯苓、白芍、冬虫夏草、青铅为大剂，以猪肉煮清汤煎服。果韧痰渐活，坚矢下行，眠食亦安，递以告愈。", "13246": "诸暨张某者，有跛疾，业点翠，终日坐，而三四年来行数十武，即喘不能已，别无他苦，饮食如常。医咸谓虚，频补不应，诣孟英视之。曰：久坐不劳，行气迟滞，痰凝久伏，故为此患。脉缓而滑，岂为虚象？授雪羹合小陷胸，加竹茹、旋覆、海石、杏仁、半夏服之，果吐多痰而愈。", "13247": "一机匠久患寒热，兼以痰嗽，形消肌削。人皆以劳怯治之，久而不愈。或嘱其就诊于孟英，脉弦缓而大，畏冷异常，动即气逆，时欲出汗，暮热从骨髓中出，痰色绿而且臭，便坚溺赤。曰：痰火为患耳，误投补药矣。以苇茎汤合雪羹，加白薇、花粉、旋覆、蛤壳，服二十剂体健加餐，其病如失。", "13248": "五舍弟树廷，时患喘逆，初冬尤甚，稍食甜物，其病即发。孟英察脉迟弱，苔黄垢而不渴，指冷腰酸，乃中虚痰湿内盛也。授参、术、苍、枳、旋、半、薤、朴、杏仁、生姜之剂，服后痰果大吐，气亦渐平。嗣以六君去甘草，加当归、木香，调补而痊。", "13249": "壬子春，沈峻扬年五十七岁，素患痰嗽。年前顾某与小青龙汤一剂，喘逆渐甚。汪某进肾气汤一服，势更濒危。医云：治实治虚，不能舍此二法，而皆不应。病真药假，不可为矣。王月鉏嘱迎孟英图之，脉来虚弦软滑，尺中小数，颧红微汗，吸气不能至腹，小便短数，大解甚艰，舌红微有黄苔，而渴不多饮，胸中痞闷不舒。曰：根蒂虚于下，痰热阻于上。小青龙，治风寒挟饮之实喘；肾气汤，治下部水泛之虚喘，皆为仲景圣法。用之得当，如鼓应桴。用失其宜，亦同操刃。所以读书须具只眼，辨证尤要具只眼也。此证下虽虚而肺不清肃，温补反助其壅塞。上虽实而非寒饮，温散徒耗其气液。耗之于先，则虚气益奔。壅之于后，则热痰愈锢。其加病也，不亦宜乎？爰以杏仁、苇茎、紫菀、白前、蒌仁、竹沥，开气行痰，以治上实；而佐苁蓉、胡桃仁，以摄纳下焦之虚阳。一剂知，再剂平，旋去紫菀、白前，加枸杞、麦冬、白石英。服三帖而便畅溺长，即能安谷，再去杏仁、竹沥、苇茎，加熟地、当归、薏苡、巴戟，填补而痊。", "13250": "兰溪吴氏妇，盛夏患恶阻，洪某进旋覆、姜、桂等药，而壮热神昏，腰疼欲坠，二便秘涩，呕吐不休，脉数而洪。予栀、芩、连、楝、竹茹、知母、银花、绿豆为剂，佐以苏叶二分，冬瓜煮汤煎药。下咽即安，数服而愈。", "13251": "吴绿园患发热呕吐，茎缩腹痛。孟英诊脉弦软而数，苔色腻黄，曰：热伏厥阴也。与楝实、通草、栀、莲、茹、斛、丝瓜络，一剂知，数剂愈。", "13252": "潘妪久患痛吐，多药莫痊。孟英视之，脉弦劲而数，曰：口苦而渴乎？大便不畅乎？小溲如沸乎？病者云：诚然。第冷气时冲，欲呕不畅，渴喜饮沸，吐沫极酸，总由积寒深重耳。孟英曰：因此谅诸医必用温燥之药矣。须知气冲觉冷者，热极似寒；渴欲饮沸者，饮邪内踞；吐沫作酸者，曲直所化；其病在络，故吐之不易。方以茹、旋、栀、楝、枇杷叶、丝瓜络、木通、生姜衣、海䖳、凫茈、苏叶炒黄连，煎吞当归龙荟丸。一剂知，五剂愈。", "13253": "许太常滇生之夫人，患腿痛而素多噫气。若指头一搓，或眉间一抹，其噫即不已。向以为虚，在都时服补剂竟不能愈。冬间旋里，孟英诊脉弦滑，乃痰阻于络，气不得宣也。以丝瓜络、竹茹、旋覆、橘络、羚羊、茯苓、豆卷、金铃、柿蒂、海䖳、荸荠、藕为方，吞当归龙荟丸而安。其媳为阮芸台太傅之女孙，在都因丧子悲哀，患发厥，屡服补剂，以致汛愆。或疑为娠，孟英曰：脉虽弦数以滑，乃痰挟风阳而为厥也。与大剂蠲痰息风、舒郁清营之剂，渐以获愈。", "13254": "一老人霍乱后，目闭呃忒。医谓脱陷在即，与桂、附回阳之药，业已煎矣。适孟英至，询知溺赤口干，诊得脉形软数，而药香扑鼻，即曰：此药中有肉桂，叟勿服也，服之必死。迫令将药倾泼，而与肃肺清胃之剂，果得渐安。", "13255": "黄履吉截疟后，患浮肿。赵某闻其体素虚，切其脉弦细，遂用温补，驯致呃忒不休，气冲碍卧，饮食不进，势濒于危。请孟英决其及返余杭否，孟英曰：脉虽弦细而有力，子必误服温补矣。肯服吾药，犹可无恐。因与栝蒌薤白合小陷胸、橘皮竹茹汤，加柿蒂、旋覆、苏子、香附、赤石、紫菀、杷叶为方，四剂而瘳。", "13256": "陈笠塘年近花甲，于初冬时偶从梯半一跌，遂发寒热，痰多咳逆。沈辛甫作虚痰、类中、挟风温治，热退便行，而痰逆不休，且兼呃忒。改从清肃镇摄，其呃日甚。因拉孟英商之，诊脉左弦涩不调，右兼软滑。察其呃，时有微甚而有欲呃不爽之象。询其喷嚏，久不作矣。曰：此气郁于肝，欲升而不能升；痰阻于肺，欲降而不能降之证也。补摄之品，咸在禁例。以柴胡、枳壳、石菖蒲、紫苏、薤白、蒌仁、竹茹、橘皮、白前为剂，复杯而减，再剂而安。", "13257": "钱某患感，医治旬日，渐致神昏瘈疭，大便泄泻。以其体素弱而吸洋烟也，胥束手矣。始丐诊于孟英，左脉弦软，右则虚大而滑，汗出不解，目瞀耳聋，呓语溲红，时时呃逆，心下拒按，舌不能伸，斡齿视苔，满黄微燥，曰：温邪虽陷，气分未清。里气虽虚，伏痰内盛。幸泻数次，邪势稍衰。先予人参、牡蛎、犀角、元参、竹叶、竹茹、银花、石斛、枇杷叶、川贝母、莲子心为剂，调服万氏清心丸一颗。目明热退，呃减舌伸，臂显赤斑，夜亦能寐，诘朝去参、蛎、牛黄丸，加竹沥、桑枝，丝瓜络，痰果大吐，瘈疭即平。再去犀、元、桑枝，加紫菀、海䖳，呃止胸舒，苔色渐退，稀糜渐进，耳听略聪。再去竹叶、莲心、紫菀，加沙参、花粉。服五贴，而下坚矢，嗣报调养而安。", "13258": "许某于醉饱后，腹中胀闷，大解不行。自恃强壮，仍饮酒食肉，二日后腹痛，犹疑为寒，又饮火酒，兼吸洋烟，并小溲而不通矣。继而大渴引饮，饮而即吐，而起居如常也。四朝走恳孟英诊之，脉促歇止，满舌黄苔，极其秽腻，而体丰肉颤，证颇可危。因婉言告之曰：不过停食耳，且饮山楂神曲汤可也。午后始觉指冷倦怠，尚能坐轿出城，到家气逆，夜分痰升。比晓，胸腹额上俱胀裂而死。盖知下之不及，故不与药也。", "13259": "许仲筠患腹痛不饥，医与参、术、姜、附诸药，疼胀日加，水饮不沾，沉沉如寐。孟英诊脉弦细，苔色黄腻，投以枳、朴，萸、连、栀、楝、香附、蒺藜、延胡等药。二剂，便行脉起，苔退知饥而愈。", "13260": "吴酝香大令四令媳，时患腹胀减餐，牙宣腿痛，久治不效，肌肉渐消。孟英诊脉，弦细而数。肝气虽滞，而阴虚营热，岂辛通温运之可投耶？以乌梅、黄连、楝、芍、栀子、木瓜、首乌、鳖甲、茹、贝，服之果愈。继与甘润滋填，肌充胃旺，汛准脉和。积岁沉疴，宛然若失。", "13261": "吴诵青室，年近五旬，天癸已绝，偶患腹胀。局医黄某，知其体素羸也，投以肾气汤，而寒热渐作。改从建中法，旬日后病剧而崩，愈补愈甚。乞援于孟英，脉洪而数，渴饮苔黄。是吸受暑邪，得温补而血下漏也。与犀角、元参、茅根、柏叶、栀、楝、知、斛、花粉、白薇等药，数剂始安。续加生地、二至、二冬，滋养而愈。次年患病，仍为误药而殒。", "13262": "何氏妇年未四旬，于庚戌冬患腹胀善呕。或云寒凝气滞，宜吸鸦片烟以温运之。及烟瘾既成，而病如故。或云冷积也，莫妙于蒜罨。往夏遂以蒜杵如泥遍涂脊骨，名曰水炙。炙后起疱痛溃，骨蒸减餐，其胀反加，经乃渐断。招越医庄某治之，云劳损也，进以温补，病乃日甚。复邀张凤喈、包次桥、姚益斋诸人视之，佥云劳损已成。或补阴，或补阳，服之冬令，便泻不饥，骨立形消，卧床不起。今春请神方于各乩坛，皆云不治。其夫因蒲艾田荐于许信臣学使，随任广东，家无主意，束手待毙而已。蒲闻而怜之，为屈孟英一诊，以决危期之迟速，初无求愈之心也。切其脉弦细数，循其尺索刺粗，舌绛无津，饮而不食，两腿肿痛，挛不能伸，痰多善怒，腹胀坚高，上肤黄粗，循之戚戚然。昼夜殿屎，愁容黎瘁，小溲短涩而如沸，大便日泻十余行。脉色相参，万分棘手。惟目光炯炯，音朗神清，是精气神之本实未拨。病虽造于极中之极，却非虚损之末传也。殆由木土相凌，为呕为胀。洋烟提涩其气，益令疏泄无权。蒜灸劫耗其阴，更使郁攸内烁。进以温补，徒为壮火竖帜而涸其津。溉以滋填，反致运化无权而酿为泻。固之涩之，煞费苦心。余谓赖有此泻，尚堪消受许多补剂。纵临证心粗，不询其泻出之热而且腻，岂有肾虚脾败之泻，可以久不安谷而延之至今乎？夫人气以成形耳。法天行健，本无一息之停。而性主疏泄者肝也，职司敷布者肺也，权衡出纳者胃也，运化精微者脾也，咸以气为用者也。肝气不疏，则郁而为火；肺气不肃，则津结成痰；胃气不通，则废其容纳；脾气不达，则滞其枢机。一气偶愆，即能成病。推诸外感，理亦相同。如酷暑严寒，人所共受，而有病有不病者，不尽关乎老少强弱也。以身中之气有愆有不愆也，愆则邪留著而为病，不愆则气默运而潜消。调其愆而使之不愆，治外感内伤诸病无余蕴矣。今气愆其道，津液不行，血无化源，人日枯瘁。率投补药，更阻气机，是不调其愆而反锢其疾也。疾日锢，腹愈胀，气日愆，血愈枯。或以为干血劳，或以为单腹胀。然汛断于腹胀半年之后，是气愆而致血无以化，非血病而成胀矣。既胀而驯致腿肿筋挛，不可谓之单胀矣。肿处裂有血纹，坚如鳞甲，显为热壅，不属虚寒。借箸而筹，气行则热自泄。首重调愆，展以轻清，忌投刚燥。热泄则液自生，佐以养血。须避滋腻，宜取流通。徐洄溪所谓「病去则虚者亦生，病留则实者亦死」，勿以药太平淡，而疑其不足以去病也。艾田云：薛一瓢谓「人须修到半个神仙身份，才可当得名医二字，聆君妙论，不愧名医。于是以沙参、竹茹、丝瓜络、银花、楝实、枇杷叶、冬瓜皮、黄柏、当归、麦冬、枸杞、白芍出入为方，用水露煮苇茎、藕汤煎药。服四剂，脉柔溲畅，泻减餐加。乃参以西洋参、生地、黄连、花粉、薏苡、栀子之类，又六剂，舌色渐淡，腿肿渐消。服至匝月，忽然周身汗出溱溱，而肿胀皆退，舌亦津润，皮肤渐蜕，肌肉渐生，足亦能伸，便溺有节。并不另授峻补，两月后，可策杖而行矣。天时渐热，服药已久，以虎潜丸方熬为膏，用藕粉溲捣成丸。因丸剂皆药之渣质，脾运殊艰。孟英凡治阴虚须滋补者，悉熬取其精华，而以可为佐使者和之为丸。不但药力较优，亦且饵之易化。如法服至长夏，健步经通，遂以康复。艾田云：此证人不能治，神亦不能治，君竟能肉白骨而生之，不仅半个神仙，殆人而仙者耶？抑仙而降为人者耶？（水露，以甜水贮甑，蒸取其露。宜临时蒸用。取其有升降之机而养津液也。一名甑汗水。停久则失性矣。）", "13263": "盛泽王西泉丈仲郎巽斋刑部夫人，年未四旬，而十八年前，诞子之后，汛即不行。医以为虚，频年温补，略无小效。董味青茂才，嘱就余诊，脉弦滑而体甚丰。乃气郁生热，热烁津液以成痰。痰复阻其气道，不能化血以流行，以致行度愆期，腹形胀痛，肢背不舒，骨疼寐惕，渴不欲饮，间或吐酸，二便不宣，苔黄口苦。皆风阳浮动，治节横斜之故也，与沙参、蛤粉各四钱，丝瓜络、石菖蒲各一钱，紫菀、仙夏、旋覆、蒺藜各一钱五分，茯苓三钱，丹参二钱，黄连四分，海䖳四两，凫茈一两。服十余剂，来转方云：胀痛蠲而腹背皆舒，夜寐安而二便亦畅，酸水不吐，痰出已松。是肝已渐柔。惟食少无味，骨节酸疼右甚，乃阳明虚无以束骨利机关也。拟通养法，参须、石菖蒲各一钱，茯神、络石各三钱，薏苡四钱，仙夏、竹茹各一钱五分，木瓜八分，姜汁炒黄连三分，十大功劳一两，仲冬招余往游复视，则诸恙皆安，惟右腿尚疼耳。即于通养方内，加黄柏、仙灵脾服之，遂愈。", "13264": "钟耀辉年逾花甲，在都患肿，起自肾囊，气逆便溏，诸治不效。急买车返杭，托所亲谢金堂邀孟英治之。切其脉微而弱，（虚象显然。）询其溺清且长，曰：都中所服，其五苓、八正耶？抑肾气、五皮也？钟云：诚如君言，遍尝之矣，而病反日剧者何哉？孟英曰：此土虚不制水也。通利无功，滋阴亦谬，法宜补土胜湿，（此即张景岳所云理中加茯苓、附子之症也。）与大剂参、术，果即向安。越八载以他疾终。", "13265": "王小谷体厚善饮，偶患气逆，多医咸从虚治，渐至一身尽肿，酷肖《回春录》所载康副转之证，因恳治于孟英。脉甚细数，舌绛无津，闻有谵语，乃真阴欲匮。外候虽较轻于康，然不能收绩矣。再四求疏方，与西洋参、元参、二地、二冬、知母、花粉、茹、贝、竹沥、葱须等药。三剂而囊肿全消，举家忻幸。孟英以脉象依然，坚辞不肯承手，寻果不起。（脉至细数，则阴竭阳亢，不拘何病，均忌此脉，而虚劳为尤甚。）", "13266": "石北涯令正，久患龈疼，渐至身面浮肿。或以为虚，或以为湿，病日以剧，气逆不饥。孟英察脉，左洪数，右弦滑。阴分虽虚，先当清其肺胃之痰热者。投白虎加沙参、花粉、冬瓜皮、枇杷叶、栀子、竹茹、芦根，服之肿即消，继佐滋阴，龈疼亦止。", "13267": "一妪患面目肢体浮肿，便溏腹胀，肠鸣时痛，饮食日减，医与理中、肾气多剂，病日剧而束手矣，始丐孟英诊焉。按脉弦细，沉之带数，舌绛口干，肿处赤痛，溺少而热，乃阴虚肝热，郁火无从宣泄而成此病。火愈郁则气愈胀，气愈胀则津愈枯，再服温燥，如火益热矣。授白头翁汤，加楝实、银花、元参、丹皮、绿豆皮、栀子、冬瓜皮数剂，证减知饥，渐佐养血充津之品而愈。前此诸医谓其山居久受湿蒸，且病起霉雨之时，而又便溏脉细，遂不察其兼证，而群指为寒湿也。嗣有黄梅溪令堂，患证类此而燥热之药服之更多，肌削津枯，脉无胃气，邀孟英往勘，不遑救药矣。", "13268": "马翠庭鹾尹令宠，患两腿疼肿，便溏不渴。医进苍术、木瓜、萆薢、独活等药，其病日甚，不食不眠，筋掣欲厥。孟英切其脉弦滑而数，询其溺极热如沸，曰：非寒湿也，肝火为患耳。便泻是土受木乘，不渴乃内有伏痰。予栀、柏、芩、连、茹、楝、通草、半夏、蚕砂、丝瓜络为方，一剂知，二剂已。", "13269": "方氏妇劳伤挟感，业已治愈，服补药数剂，渐形浮肿。或谓邪未净而补之早也，用消导、清解法皆不应，且兼咳逆碍眠，便溏溲涩。又谓肾气不纳，改从滋填，其势益增，遂束手矣。浼余视之，脉浮无汗，尺静经行，既非根蒂之虚，亦岂邪留误补？殆愈后复感风邪，肺气阻痹，水津失布，所谓皮水证也。与香薷、杏仁、紫苏、橘皮、兜铃、射干、紫菀、通草、葱白，天泉水、芦火煎服，复杯而愈。", "13270": "沈雪江光禄年五十岁，于客腊偶患头晕，既而右手足麻木。医进再造丸九十余颗，渐至挛曲不伸，针药无效。仲春余游檇李，吴门李君雨村招往视之。手足亦肿而疼，便坚溲赤，口干舌绛，准头一瘰磊然，脉象弦滑而数。平时屡有鼻衄，肝阳易动，曲运神机，体质性情，阴虚火盛，风自火出，烁液成痰，窜入络中，则为是证。初起若以竹沥一味灌之，可以渐愈。乃温补率投，遂成锢疾。幸而病在经络，停补尚可延年。苟欲望有转机，必用清通宣泄。拟方三剂，肿痛稍瘥。议者谓药太清凉，多服恐妨脾胃。更医复进温补，并雨村亦不延诊矣。迨四月中旬，大便忽秘，饮食不思。半月余，更衣极艰滞，而解后胸次愈形窒塞，遂不食，然参药不辍也。至五月十八日，复解燥矢，仍不思食，勉强啜粥辄呕吐。次日转为滞下，色如鱼脑，日数十行。医谓有出无入，脾胃两败矣。温补方再加固涩之品，遂鼻衄如注，且有成块成条之坚韧紫血，自喉间涌出，虽米饮不能下咽，小溲涩滞不行，时欲呷茶以润口。或云已传关格，无药可施。而引火归元之法，愈用愈剧，诸医无策，眷属皇皇，业办后事矣。乃弟云峰待诏余春日所嘱，浼入聘余往援。二十四日余抵禾，见其面色枯黧，牙关紧而舌不出齿，脉至右滑左弦细数皆上溢，而尺不应指，胸闷溺涩。阳宜通而不通，是滋腻阻寒气道也。血溢下利，阴宜守而不守，是温燥灼烁营液也。吾先慈所谓人身如欹器，满则必覆。半年蛮补，填满胃中，设不倾筐倒箧而出，亦必塞死。岂可不加揣测，而误认为神机化灭之出入废，关闸不禁之下利，阴盛格阳之吐衄，而再施镇纳堵截之药哉？古云上部有脉，下部无脉，其人当吐，不吐者死。今火炽上炎，鼻血大流，汤水不能下咽，有升无降，与吐何殊？况见证虽危，而呼吸不促，稍能安寐，皆是未绝之生机。考古下利而渴者属厥阴，白头翁汤主之。滞下不食者为噤口，参连汤主之。余合而用之，加石菖蒲宣气通阳，石斛、茅根生津凉血。一服而利减其半。次日去连、柏，加元参、犀角、童便，专治其衄。一服血渐少，利渐止。然离络之血，不可不使之出。未动之血，亟当使其各安于位。故以西洋参、丹参、麦冬、茯苓、菖蒲、石斛、小麦、竹叶、栀子、甘草梢、燕窝等出入，三剂。血既止，牙关渐开，苔色黄腻，啜饮必拍膈始得下行，因参以小陷胸法数剂。自觉身体略轻，手腕稍舒，改清肃肺胃，展气化以充津，苔渐退，渴亦减，脉较平。守至闰月二十二日，尺脉滑动，于方中加肉苁蓉、麻仁二味。夜间即解坚黑燥矢，而渐能进粥，随去麻、苁，加生地。服至六月初七日，口始不渴而吃饮。继因过饮西瓜汁，大便溏泻，复延余往。以六君去术、草，加苡、藿，数贴而安。随去藿，加首乌、络石、石斛、十大功劳。服二十剂，渐能起坐，右腿可以屈伸，但软而无力耳。中秋后，又邀余往，则胃气已复，右指已伸，皮肤色泽，而右臂未能动，右颊犹觉木硬，是络中之痰未净，肝藏之风易生。气血之灌溉流行，因有所阻碍，而不能贯注也。以养血息风、蠲痰宣气之方，加竹沥为响导，服后足渐能立。十月间食蟹过多，大解泄泻，余以六君加藕、木香、苏叶调愈。嗣余游盛湖转禾，适交至节，而天暖不藏，又因劳怒，陡发头晕，呕吐痰涎，目闭不言，不食不便，举家无措。医者率主首乌、牡蛎等滋摄之治。余脉之，弦而缓，是中虚不能御木，故内风上僭。阴柔之品，徒滞中枢，不可服也。仍用六君，去甘草，加菖蒲、黄连、旋覆花、姜皮、钩藤，三贴霍然。小寒后，余游姑苏转禾。又因天暖而发鼻衄，改换养阴潜阳法而瘳。次年春季出门，因不节劳，至端阳复中而逝。", "13271": "贤倡桥朱君兰坡令堂，年已六旬。素患跗肿，夏季患疟转痢，痢止而腹之疼胀不休，渐至脘闷，面浮，一身俱肿，遍治罔效。卧床百日，后事皆备。闻余游禾，谆乞一诊。左极弦细，右弱如无，舌赤无津，呻吟呕沫，不眠不食，溲短目眵。系肝旺之体，中土受伤，运化无权，气液两竭。如何措手，勉尽人谋。方用参须、石菖蒲、仙夏各一钱，石斛、冬瓜皮、建兰叶各三钱，竹茹一钱五分，姜汁炒川连四分，陈米汤煎服。诘朝兰坡忻忻然有喜色而相告曰：已转机矣。求再诊，余往视，面浮已减，病者冁然曰：胸腹中舒服多矣，故不呻吟，且进稀粥。按脉略起，遂于原方，加冬虫夏草一钱、乌梅肉炭四分。服后连得大解，色酱而夹蠕蠕之虫盈万，腹之疼胀遂蠲，肢肿亦消，舌润进粥。又邀余诊，色脉皆和，喜出望外。初亦不知其虫病也，所用连梅，不过为泄热生津、柔肝和胃之计，竟能暗合病情。殆兰坡孝心感格，故危险至是，可以一二剂取效。谨志之，以见重证，不可轻弃，而余侥幸成功，实深渐。将返棹，留与善后方，惟加燕窝根、薏苡、白蒲桃干而已。冬初余再游禾，询其所亲云已出房矣。因素原方案归录之。", "13272": "高若舟偶患腹胀，医投温运，渐至有形如痞，时欲冲逆吐酸，益信为虚寒之疾。温补之药备尝，饮食日减，其痞日增，肌肉渐消，卧榻半载。甲辰春，迓孟英诊脉，沉弦而软滑，大解不畅，小溲浑短，苔色黄腻。乃肝郁气结，郁则生热，补则凝痰。与栀、楝、萸、连、元胡、乌药、旋、枳、鸡金、鳖甲、茹、橘、苓、夏等药，服之证虽递减，时发寒热，四肢酸痛。或疑为疟，（此少阳之气郁而欲伸之象。）孟英曰：此气机宣达，郁热外泄，病之出路，岂可截乎？参以秦艽、柴胡、豆卷、羚羊、蚕砂、桑枝之类，（清热涤饮，条达肝气，允属合法。）迎而导之。人皆疑久病元虚，药过凉散，而若舟坚信不疑，孟英识定不惑。寒热渐息，攻冲亦止，按其腹尚坚硬，时以龙荟滚痰丸缓异之，（峻药缓投法。）饮食递加，渐次向愈，若舟善作隶，因集诗品书一联以赠孟英云：古镜照神，是有真宰；明漪绝底，如见道心。盖颂其隔垣之视也。", "13273": "王士干室素多郁怒，气聚于腹，上攻脘痛，旋发旋安，花甲外病益甚，医治益剧。李西园荐孟英视之曰：此非人间之药所能疗矣。辞不与方。其夫子及婿环乞手援，孟英曰：既尔，吾当尽力以冀延可也。然腹中聚气为瘕，攻痛呕吐，原属于肝。第病已三十载，从前服药，谅不外乎温补一途。如近服逍遥散，最劫肝阴；（用古方不可有知此意。）理中汤，极伤胃液。名虽疗疾，实则助桀。人但知呕吐为寒，而未识风阳内煽，水自沸腾。专于炉内添薪，津液渐形涸竭。奈医者犹云水已不吐，病似渐轻，是不察其水已吐尽，仅能哕逆空呕。所以不能纳谷，便秘不行，脉弦无胃，舌痿难伸，蕴隆虫虫，何所措手，可谓女人亦有孤阳之病矣。勉以西洋参、肉苁蓉、麦冬、葳蕤、生白芍、石斛、竹茹、柏子霜、紫石英为方，猪肉煮汤煎药，和入青蔗浆、人乳。服后呕哕皆止，人以为转机，孟英曰：譬草木干枯已久，骤加灌溉，枝叶似转青葱，奈根荄槁矣，生气不存，亦何益耶？继而糜粥渐进，颇思肉味，其家更喜以为有望，孟英曰：且看解后何如。越数日大便颇畅，殊若相安，亟迓复诊，孟英曰：枉费苦心矣。脉不柔和，舌不润泽，（审病者，宜识此二语。）虽谷进便行，而生津化液之源已绝，药石焉能于无中生有哉？夏至后果殒。", "13274": "王天成牙行一妇，年五十余。初患左目赤，渐至发热，医投温散，便泄而厥。进以补剂，少腹宿瘕攻痛，势极危殆。丐孟英诊之，脉甚弦软，舌绛而渴。与苁蓉、橘核、当归、元胡、龟板、石英、螵蛸、茯苓、栀、楝、萸、连，数服而安。逾年以他病卒。", "13275": "蔡西斋令正，腹有聚气，时欲攻冲，医者以为下部虚寒，进以温补摄纳，如桂、附、沉香、芦巴、故纸、吴萸之类，愈服愈剧。酷暑之时，其发益横，日厥数十次。医皆望而却走，乃迎孟英视之。脉数舌绛，面赤睛红，溺如沸汤，渴同奔骥，少腹拒按，饥不能餐，曰：事急矣，缓剂恐无速效。令以豆腐皮包紫雪一钱，另用海䖳、凫茈煎浓汤，俟冷吞下。取其芳香清散之性，直达病所也。服后腹如雷鸣，浑身大汗，小溲如注，宛似婴儿坠地，腹中为之一空，其病已如失矣。继有许梅生八令爱，患痛屡日，筋掣神迷，肢冷息微，脉伏唇紫，多药无效，孟英亦以此药灌之而苏。", "13276": "蒋礼园三令弟拜枫，自去年疟后左胁聚气不消，时时窜痛，疑为疟母。孟英脉之弦软且滑，曰：非疟母也。予旋覆、海石、竹茹、丝瓜络、绛屑、葱白、蛤谷、岛茈、海䖳为方，十余剂而刈其根。", "13277": "高鲁川三令爱，为外科姚仰余令郎杏村之室，年三十五岁。自去年仲夏患痢，白少赤多，昼夜一二十行，或有溏粪相杂，医治日殆，延至今冬。经断半年，胁腹聚块，时时上窜，宛如虫行，痒至予咽，食压始下，腹胀腿肿，唇白口糜，舌绛无津，耳鸣巅痛，略有干呛，渴饮汗频，热泪常流，溺短而热，善嗔多劳，暮热无眠，心似悬旌，屡发昏晕。痢门与虫门方药，遍试无功。舍病而补法备施，亦无寸效。佥云不能过冬至，棺衾咸备，无生望矣。杏村之僚婿蒋礼园、黄上水交荐孟英图之。脉至左弦数上溢，尺中滑大，按之细弱，右手软滑，略兼弦数，诊毕谓杏村曰：令正幸能安谷，得以久延。然下痢至五百日，喉腭辣燥，阴液固已耗伤，而尺肤淖泽，脂膏未剥，其中盖别有故焉。腹中之块，痢前曾有乎？痢后始起乎？杏村云：起于痢前。然则前此曾有产育乎？云：去年二月间分娩艰难，胞已糜碎，生而未育。曰：是矣，此实似痢而非痢也。夫胞衣糜碎，必有收拾未尽而遗留于腹中者。恶露虽行，此物未去，沾濡血气，结块渐成，阻碍冲任之常道。而冲任二脉，皆隶阳明，月事既不能循度以时下，遂另辟捷径，旁灌于阳明，致赤白之物，悉由谷道而出，宛如痢疾。据云姅期向在中旬，故每月此时，痢必加甚，仍与月汛相符。虽改途易辙而行，尚是应去之血，所以痢至年半，尺肤犹不至枯瘁也。且其痢由腰脊酸楚而下，显非肠胃之本病。缘病起夏月，正痢疾流行之候，病者自云患痢，医者何暇他求。通之、涩之、举之、填之，无非肠胃之药，不但未切于病情，抑且更广其病机。试思肠胃之痢，必脂膏削尽而后经枯，则焉能纳食如常而充肌肤耶？然非谓不必治其痢也，欲治痢，必治其所以痢，则当治冲任。必治冲任之所以病，则当去其遗留之物。遗留之物去，则冲任二脉遵道而行，月事如期，痢亦自愈。第物留已将两载，既能上行求食，谅已成形。前医指为虫病，而无面白、唇红之证据者。虫必饮食挟湿热之气所化，此但为本身血气所凝，似是而非，判分霄壤。况此物早已脱蒂，不过应去而未去，欲出而不能，开通冲任二脉，其物自下。不比肠覃、石瘕，有牢不可拔之势，必用毒药以攻之者。爰以乌鲗、鲍鱼、茜根、龟、鳖甲、血余、车前子、茺蔚子、藕汁为初方。众见方案，佥云舍垂危之痢而不顾，乃远推将及两年之产后，而指为未经人道之怪证，不但迂远穿凿，未免立异矜奇，疑不敢从。蒋礼园令弟敬堂云：徐洄溪批叶案，以十年九年之病，仍标产后为大不然。谓产后过百日而起病者，不作产后看，举世皆以为定评。余读孟英所辑叶案瑕瑜，谓案中所云十年九年者，乃病从产后起，延至于今而屡发也。否则胀泻浮肿，何必远推多载之前而隶于产后耶？更有新产之后，其病不因产育所致者，虽在百日之内，亦不可谓之产后病，仅可云病于产后耳。此证痢虽起于百日之外，块早形于两月之前，因流溯源，正是治病必求其本也。今人之病，何必古书尽载？此医之所以不易为，而辨证之所以为最难也。听其议论，具有根柢，并非捕风捉影之谈。况药极平和，又非毒剂，似与久病元虚无碍。他医既皆束手，盍从其计求生。具嘱仰余勿改其方，于是群议始息。服两剂后，病者忽觉粪从前阴而出，大骇。急视之，乃血裹一物，头大尾小，形如鱼鳔而有口，剖之甚韧，血满其中，众始诧为神治。而病者汗晕不支，孟英即与人参、龙骨、牡蛎、茯苓、麦冬、甘草、小麦、红枣为方。服数剂神气安爽，始知脐下之块已落，而左胁下者犹存，然上窜之势，向亦脐下为甚。窜势既减，痢亦渐稀，改用白头翁汤，加阿胶、甘草、小麦、红枣，吞仲景乌梅丸。和肝脾之相贼，养营液而息风。旬日后，头目渐清，肿消胀减，复以初方合《金匮》旋覆花汤。服四剂，又下一物，较前差小，而胁块乃消，窜痒悉罢，痢赤径止。惟溺热便溏，口犹辣渴，心摇易汗，腿软无眠，烦躁火升，脉形虚豁，乃阴火内炽，脾受木乘，营液久伤，浮阳不敛也。授归耆建中汤去姜，加黄柏、乌梅、龙骨、牡蛎、小麦，以羊肉汤煎，送下交泰丸一钱。脉证虽觉渐和，惟病久元虚，屡生枝节，孟英坚持此法，不过随机略为进退而已。而旁观者议论纷纭，因嘱邀王竾伯会诊。竾伯亦主是法，浮言乃息。服至匝月，喉间渐生甘液而各恙递平。又匝月，甘液布及舌尖而满口皆润，次年二月中旬，经至肌充而愈。适吴楚之警，遂辍药，迨仲冬患疮，误用药水洗之，致毒内陷而殒。惜哉！（交泰丸系黄连、桂心，研末为丸）", "13278": "吴曲城仲郎，偶患少腹坚胀，左胁聚气。群医见其面黄，作暑湿治，攻补杂施，两月弗效。孟英视脉弦涩，溺赤便艰，口苦不饥，肢冷形瘦，曰：非外因也，肝郁耳。予旋覆花汤合金铃子散，加雪羹、竹茹、青皮、白芍煎，吞当归龙荟丸，八剂而病如失矣。", "13279": "沛生令宠，平素阴虚肝旺，而腹有聚瘕，时胀时疼。初冬患疟，苔黑口干。孟英脉左弦数而洪，右滑数而溢，初以栀豉合金铃子散、雪羹，加元参、白薇、竹茹。服四贴，疼胀皆减，疟缓汗多，溲涩口干，饥不能食，气时冲逆，予沙参、归、斛、茹、橘、石英、丝瓜络、蛤壳、藕。两贴后，汛行腰痛，口渴少餐，气郁营虚，兼有痰滞也。去蛤壳，加旋覆、冬瓜子、花粉。两贴而更衣乃畅，然犹脘闷不饥，汛少且黑，口渴头疼，疟亦未罢，乃去石英、旋覆，加栀、滑、枳实。四剂，各恙皆安，疟犹未断，以归、苁、甘、杞、橘、半、蒌、芩、竹茹、花粉，少佐桂枝调其营卫。奈病者因口苦而恶粥食，嗜啖甘酸，病既曲折，邪益留恋，此方服至半月而疟始休。惟宿瘕时痛，肛痔便难，口苦吞酸，神疲寝汗，去芩、桂、甘草、花粉，加鳖甲、乌鲗骨、白芍、延胡、仙灵脾，出入调补而痊。", "13280": "邱氏妇，年四十余，患少腹瘕聚，时欲上冲，昏晕而厥。卧榻数月，足冷面红，夜不成寐，诸治不应。余按脉虚细而弦，口干无液，与大剂一贯煎，复杯即愈。人咸诧异称神，余却愧钞来墨卷也。", "13281": "崇明刑幕吴江史励斋令正，久患少腹聚瘕，时欲攻痛，羞明心悸，汛速带频，向服补药，交夏发之更剧。医用胶艾汤加参、术、耆、茸峻补，痛益难支，遂成晕厥，不眠不食。业已四朝，屈余视之。脉来弦滑，苔黄苦渴，溺热便难，与沙参、石英、龟板、鳖甲、蒿、薇、苡、柏、鲗、䖳、茹、菖一饮，而病如失，眠食皆安，赠以清养柔潜而别。", "13282": "硖石镇蒋寅昉大理令正，久患少腹聚气，时或上冲于胸，而为脘痛，时或下坠，而为腿肿，带多汛速，腹胀胸闷，口腻不渴，便虽溏而欲解不行，心啖盐而始畅。皆为脾虚，率进补剂，病日以甚。迎余诊之，脉弦滑，以栀、芩、菖、枳、连、夏、茹、旋、雪羹，清肝热以豁痰。滞气果下行至足，而胸腹渐舒。", "13283": "九月初旬，蒋君寅昉，招余治其令兄仲卿孝廉夫人之病。年五十九岁，平素操持，腹有聚气，脘痛时作，大便易溏。半月以来，身热耳聋，病泻不食，胸中痞塞，痰韧如胶，口腻欲呕，神情惫甚，脉来虚弦而软，舌苔黄腻无津。乃营津久耗，气郁不舒，虽挟客邪，过投清散，以致本实欲拨也。与参、苓、橘、半、蒌、薤、茹、连、菖、斛、燕窝、枇杷叶，用水露煎服。三贴后，泻止痰稀，胸宽进粥。医见苔退舌红，惊为脱液，仲卿复邀余往视，乃病退之象也。舌上无津，前案已述，今脉渐转，如何反为诧虑？于前方去蒌、薤、连、半，加归、地、麦冬、藕，服之而愈。", "13284": "朱恒山，久患胸痞多痰，诸药罔瘳。孟英诊曰：清阳之气不司旋运也。与参、耆、苓、术之剂，豁然顿愈，因极钦服。后数年果以汗脱，闻其垂危之际，口不能言，犹以左手横三指，右手伸一指加于上，作「王」字状以示家人。有会其意者，急追孟英至，而他医之中风药早灌入矣，遂以长逝。癸卯冬至前一日，管大中丞亦是气从溺脱，当以参、附挽回者，及孟英至，而痰药、痧药、风药，灌之遍矣，脉仅若蛛丝过指，孟英坚不与方，须臾而卒。", "13285": "丁酉中秋夜，牙行张鉴录，年逾花甲，卒仆于地，急延孟英脉之，弦滑而大，曰：痰、气、食相并而逆于上也。先以乌梅擦开牙关，横一竹箸于口，灌以淡盐姜汤，随入鹅翎探之，吐出痰食，太息一声而苏，次与调气和中而愈。后数年以他疾终。此案虽无奇，而辨证之明，不可不录。", "13286": "张养之令侄女，患汛愆而饮食渐减。于某与通经药，服之尤恶谷。请孟英诊之，脉缓滑，曰：此痰气凝滞，经隧不宣，病由安坐不劳，法以豁痰流气，勿投血药经自流通。于某闻而笑曰：其人从不吐痰，血有病而妄治其气，胀病可立待也。及服孟英药，果渐吐痰而病遂愈，养之大为折服。予谓世人头痛治头，脚疼疗脚，偶中而愈，贪为己功，误药而亡，冤将奚白？此《寓意草》之所以首列议病之训也。孟英深得力于喻氏，故其议病，迥出凡流。要知识见之超，总由读书而得。虽然，人存政举，未易言也。", "13287": "一妪，患右腰痛胀欲捶，多药不效。孟英视其形虽羸瘦，而脉滑痰多，苔黄舌绛，曰：体虚病实，温补非宜。苟不攻去其疾，徒以疲药因循，则病益实，体益虚，糜帑劳师，养成寇患，岂治病之道哉。先以雪羹加竹茹、楝实、绿萼梅、杏仁、花粉、橘红、茯苓、旋覆花，送控涎丹。服后果下胶痰，三进而病若失，嗣与调补获痊。", "13288": "沈某患脘痛呕吐，二便秘涩，诸治不效。请孟英视之，脉弦软，苔黄腻，曰：此饮证也。岂沉湎于酒乎？沈云：素不饮酒，性嗜茶耳。然恐茶寒致病，向以武彝红叶，熬浓而饮，谅无害焉。孟英曰：茶虽凉而味清气降，性不停留。惟蒸遏为红，味变甘浊，全失肃清之气，遂为酿疾之媒。较彼曲糵，殆一间耳。医者不察，仅知呕吐为寒，姜、萸、沉、附，不特与病相反，抑且更煽风阳。饮藉风腾，但升不降，是以上不能纳，下不得通，宛似关格，然非阴枯阳结之候。以连、楝、栀、芩、旋覆、竹茹、枇杷叶、橘、半、苓、泽、蛤壳、荷茎、生姜衣为方，送服震灵丹。数剂而平，匝月而起。此上有停饮，下元虚寒，故用药如此。", "13289": "定州杨素园明府宰宜黄，吏治有声，精于医药。其夫人多病，自治不痊。毗陵吴子和嘱其函恳酝香，屈孟英诊视。而孟英因母老急欲旋里，坚辞不往，即据来信所述病状，拟方立案云：细阅病原，证延二十余年。始因啖杏，生冷伤乎胃阳，肝木乘虚，遂患胁疼亦掣。身躯素厚，湿盛为痰，温药相投，是其效也。驯致积温成热，反助风阳，消烁胃津，渐形瘦削。而痰饮者，本水谷之悍气。缘肝升太过，胃降无权，另辟窠囊，据为山险。初则气滞以停饮，继则饮蟠而气阻。气既阻痹，血亦愆其行度，积以为瘀。前此神术丸、控涎丹之涤饮，丹参饮、桃核承气之逐血，皆为杰拘，已无遁情。迨延久元虚，即其气滞而实者，亦将转为散漫而无把握矣。是以气升火浮，颧红面肿，气降火息，黄瘦日增。苟情志不怡，病必陡发。以肝为刚脏，在志为怒，血不濡养，性愈侜张。胃土属阳，宜通宜降，通则不痛。六腑以通为用，更衣得畅，体觉宽舒，是其征也。体已虚，病似实。虚则虚于胃之液，实则实于肝之阳。中虚原欲纳食，而肝逆蛔扰欲呕。吐出之水，已见黑色，似属胃底之浊阴，风鼓波澜，翻空向上，势难再攻。承示脉至两关中，取似形鼓指，重按杳然，讵为细故？际此春令，正鸢飞鱼跃之时，仰屋图维，参彻土绸缪之议，是否有当，仰就斤绳。（予室人患痰饮胁痛二十年矣，初则畏寒喜热，颇宜健脾利气之品。至甲辰冬，服神术丸一料，夙患顿损，渐不畏寒。己酉冬，因气恼而复病，误服游山散钱许，势遂披猖，得孟英诊视，始渐就安痊。但痰饮未能尽除，每日须按摩数百下，嗳气数十口，方觉稍快。否则，胸痞异常，二便恒秘，而便出仍不干燥，偶有时二便通调，则为之体适者终日。正《内经》所谓得后与气，则快然而衰也。明明痰饮之证，特以阴血久亏，既不任香燥，而气机素滞，又不利滋填，遂至莫可为计。安得孟英常加诊视，而尽刈其根株耶？）", "13290": "沙参（八钱），鲜竹茹（四钱），川椒红（二分），乌梅肉炭（六分），茯苓（二钱），旋覆（三钱），金铃肉（二钱），柿蒂（十个），仙半夏（一钱），淡肉苁蓉（一钱五分），吴萸汤炒黄连（四分），冬虫夏草（一钱五分）。另用炙龟板、藕各四两，漂淡陈海䖳二两，凫茈一两，赭石四钱，先煮清汤代水煎药。（正月十四日）右拟方案，来差星夜赍回，于十六日到宜。素园读案狂喜，以为洞见脏腑，必欲孟英一诊，以冀霍然。遂夤夜备舆，专丁持函，求孟英暂缓归期。酝香笃于寅谊，再四劝驾，并嘱四令郎季眉偕行。孟英迫于情不可却，二十二日抵宜署。初诊案云：证逾二十年，右胁聚气，有升无降，饮阻不宣，呕逆减餐，亦将半载。二便非攻不畅，容色改换不常，吐苦吞酸，苔黄舌绛，渴喜冷饮，畏食甘甜。甘能缓中，冷堪沃热，病机于此逗露。根深难即蠲除，标实本虚，求痊匪易。据述脉亦屡迁，似无定象。夫既流善幻，显属于痰。兹按脉左缓滑，右软迟，两尺有根，不甚弦涩，是汛愆因乎气阻，尚非阴血之枯。春令肝木乘权，胃土久受戕克，病已入络，法贵缓通，通则不痛，腑以通为补。法虽时变，不能舍「通」字以图功。布鼓雷门，诸希教正。", "13291": "再诊：左脉如昨，兼弦，右寸亦转缓滑，中脘气渐下降，二便欲解不行。盖升降愆常，枢机窒涩，由乎风阳浮动，治节横斜，肺既不主肃清，一身之气皆滞也。轻可去实，先廓上游。前方去海石，加栝蒌三钱，枳实一钱。", "13292": "三诊：脉来较静，小溲渐行，虽未更衣，已能安谷。浊得下降，导以清通。前方去贝、楝，加归尾钱半，桃仁十粒，送服导水丸十粒。", "13293": "四诊：腿凉便滞，气少下趋，颧面时红，火炎上僭，两胁较热，络聚痰瘀。叠授清宣，更衣色黑，噫气渐罢，酸水不呕，纳谷颇增，脉稍和缓。法仍缓导，冀刈根株。前方去枳实、归尾，减导水丸五粒。", "13294": "五诊：各恙皆减，眠食渐安，火犹易升，头疼面赤，颊酸结核，胁热未蠲，脉渐柔和，且参清养。前方去白前、青黛、紫菀、黄连，加银花、贝母、黄菊、丹参、陈细茶、橄榄。", "13295": "鲍继仲于季春望日，忽然发冷而喘汗欲厥。速孟英视之，脉沉弦而软滑带数。是素患痰饮，必误服温补所致也。家人始述去冬服胡某肾气汤，颇若相安，至今久不吐痰矣。孟英曰：病在肺。肺气展布，痰始能行，虽属久病，与少阴水泛迥殊。辨证不明，何可妄治？初服颇若相安者，方中附、桂刚猛，直往无前，痰亦不得不为之辟易。又得地黄等厚浊下趋之品，回护其跋扈跳梁之性。然暴戾之气，久而必露。柔腻之质，反阻枢机。治节不伸，二便涩少，痰无出路，愈伏愈多。一朝卒发，遂壅寒于清阳升降之路，是以危险如斯，须知与少阴虚喘，判分霄壤，切勿畏虚妄补。投以薤、蒌、枳、杏、旋、赭、橘、半、菀、茹、芦根、蛤粉、雪羹之剂而平，继与肃清肺气而涤留痰，匝月始愈。", "13296": "朱绀云令正，去年娩后，自乳而月事仍行，至仲冬乳少汛愆，咸以为妊也。既而右胁筋绊作疼，渐及肩背。医投平肝药，痛益甚。改用补剂，遂嗽痰带血，人皆以为损矣。广服温补，其病日增。延至仲春，卧榻已匝月。群医束手，始求诊于孟英。面赤足冷，时时出汗，食减无眠，脉来右寸溢，关尺滑而微数，左手弦而带滑，舌赤而润，微有白苔，气逆口渴。所吐之血，淡红而夹痰涎。大解溏，小溲短且热。曰：冲为血海，而隶于阳明。自乳而姅不爽期者，血本有余也。因阳明经气为痰所阻，而不能流通输布，致经断乳少，痰血𫐖輵而为络痹窜痛，医者不为分导下行，病无出路，以致逆而上溢。再投补剂，气愈窒塞，在山过颡，夫岂水之性哉！予苇茎汤，加茜根、海螵蛸、旋覆、滑石、竹茹、海䖳为剂，和藕汁、童溺服。以肃肺通胃，导气化痰，而领血下行，复杯即愈。旬余汛至，不劳培补，寻即受孕。此证不遇孟英，必至补死，而人亦但知其死于虚劳也。服药可不慎耶？", "13297": "朱仲和令正，向于娩后陡患痉厥，多医以图，广服补剂，其人虽起，厥疾弗瘳，再产亦然。延已数载，安之若素。孟英闻之，尝谓仲和曰：将来受孕，宜予药以痊之。今冬怀妊，病发益频，遂邀过诊，脉甚弦滑。厥前必先作胀，更衣得泻始舒。巅顶时疼，饮食不减，曰：肝风挟痰为患耳。仲和云：肝风则良是，痰则从来未吐。曰：惟其不吐，所以为患。沈尧封谓胎前病痰证居半，产时痰涎不下，诸病丛生。医者未知此理，徒知产后为虚，痰处络中，如何自吐？亦幸而痰在络中，补之不为大害，不过锢之愈深耳。岂可以不见痰面，遂云无痰乎？爰授蠲饮六神汤合雪羹，加蒌仁、竹沥，服三十剂病果渐愈。次年娩后安然，知病根已拔矣。", "13298": "东垣云：中年以后，已行降令，清阳易陷，升举为宜。吾师赵菊斋先生，年逾花甲，偶因奔走之劳，肛翻患痔，小溲不行，医者拟用补中益气及肾气丸等法。孟英按其脉软滑而数，苔色腻滞。此平昔善饮，湿热内蕴，奔走过劳，邪乃下注。想由强忍其肚坠之势，以致膀胱气阻，溲涩不通。既非真火无权，亦讵清阳下陷。师闻而叹曰：论证如见肺肝。虽我自言，无此明切也。方以车前、通草、乌药、延胡、栀子、橘核、金铃子、泽泻、海金砂，调膀胱之气化而渗水，服之溲即渐行。改用防风、地榆、丹皮、银花、荆芥、槐蕊、石斛、黄连、当归，（后治痔漏）清血分之热而导湿，肛痔亦平。设不辨证而服升提、温补之方，则气愈窒塞，浊亦上行。况在高年，告危极易也。", "13299": "孙氏子患腿酸寝汗，溺赤脘疼，食减口干，或疑为损。孟英按脉缓大，苔色微黄，乃劳力火升，内兼湿热也。以沙参、竹茹、甘草梢、小麦、石斛、楝实、丝瓜络、绿萼梅、建兰叶、带露桑叶为方，送服松石猪肚丸，旬日而愈。嗣有任氏女校书患带，诸药罔瘳，孟英视曰：脉软数而长，非虚也，宜猪肚丸清其湿火。服匝月，病良已。", "13300": "无棣张柳吟封翁，于乙未夏偕令嗣恒斋刺史赴滇南任，道出武林。其家人郑九者，封翁宠人之弟也。途次抱恙，抵杭日招越医陈六顺诊治。服药后，汗出昏狂，精流欲脱。封翁大骇，躬诣孟英以希挽救。孟英切其脉，既数且乱，沉取极细，乃语封翁曰：此证颇危，生机仅存一线。亦斯人之阴分素亏，不可竟谓附、桂之罪也。封翁闻言大悦曰：长者也。不斥前手之非以自伐，不以见证之险而要誉。相见恨晚，遂定忘年之交，彼此尽吐生平。始知封翁最喜谈医，岐黄之言，无所不览，惟不肯为人勘病，亦慎重之意耳。于是孟英以元参、知柏、桑枝、龙、牡、生地、白芍、甘草、百合、石斛、栀子、盐水炒淡豆豉为大剂灌之，下咽即安。次日，去栀、豉、甘草，加龟板、鳖甲、盐水炒橘红，十余帖而康。", "13301": "胡秋纫，于酷热时偶有不适，医以柴、葛、香薷散之，反恶寒胸痞。更医用枳、朴、槟榔以泻之，势日剧。延孟英视之，自汗不收，肢背极冷，奄奄一息，脉微无神，曰：禀赋素亏，阳气欲脱，此必误认表证使然。与救逆汤，加参、耆，服之渐安。继以补气生津，调理匝月而痊。", "13302": "温敬斋令正，九月间忽然四肢麻木，头晕汗淋，寻不能言，目垂遗溺，浑身肤冷，急请孟英视之，脉微弱如无。乃虚风内动，阳浮欲脱也。先令煮水以待药，与东洋参、黄耆、龙、牡、桂枝、甘草、茯苓、木瓜、附子九味，煎数沸，随陆续灌之。未终剂，人渐苏，盖恐稍缓则药不能追也。", "13303": "叶茂栽，年三旬余，寒热时形，身振多汗，医从疟治，数日而危。速孟英视之，脉微欲脱，语难出声，舌光无苔，筋惕肉𥆧，亟宜救逆。合建中汤灌之，复杯即愈。续服多剂培补而安。", "13304": "湖墅张春桥，素禀不坚，头眩脑鸣，频服温补药，甚觉畏冷，人皆谓其体偏于寒也。辛丑春，始请孟英诊之，脉甚数，曰：阴亏也，温补非宜。改服滋水培元之剂，颇为有效。夏间或劝以灸火，云可以除百病。盖未知灼艾之可以除百病者，谓可除寒湿凝滞、阳气不能宣通之证，非谓内伤外感一切之病，皆可灸而除之也。故仲景有微数之脉，慎不可灸之训，正以艾火大能伤阴也。灸后数日，即寒少热多，宛如疟疾。医者以为脾寒病，投以温散，日以滋甚。春桥知药治未符，坚不肯服。乃父与之询其故，漫曰：要儿服药，须延王先生诊视。与之遂邀孟英治之，切其脉滑数倍加，曰：阴虚之体，内热自生；灸之以艾，火气内攻；时当溽暑，天热外烁，三者相交，阴何以堪？再投温散，如火益热，当从瘅疟治。专以甘寒息热，（孟英长技）则阴津不至枯涸，而寒热不攻自去，所谓治病必求其本也。竟不用一分表散药而治愈。（眼前道理，而人多不悟，一经拈出，便成名论。此与以针治虚损者，同一悖谬。）", "13305": "萧某素患痰多，常服六君子汤。偶延孟英诊之，脉细数而兼弦滑，曰：六君亟当屏绝。病由阴亏火盛，津液受灼而成痰，须服壮水之剂，庶可杜患将来。萧因向吸鸦片烟，自疑虚寒，滋阴不敢频服。继患咽痛，专科治而不效，仍乞诊于孟英。因谓曰：早从吾策，奚至是耶？此阴虚于下，阳浮于上，喉科药不可试也。大剂育阴潜阳，其痛日瘥，而喉腭皆形白腐，孟英曰：吸烟既久，毒气薰蒸之故耳。令吹锡类散，始得渐退。愈后复患滞下，孟英曰：今秋痢虽盛行，而此独异于人，切勿以痢药治之。盖火迫津液，结为痰饮，酿以烟毒，熏成喉患。吾以燃犀之照，而投激浊扬清之治。病虽愈矣，内蕴之痰浊尚多，奈向来为温补药所禁，锢于肠胃曲折之间，而不得出。今广投壮水之剂，不啻决江河而涤陈莝，岂可与时行暑热之痢同年而语耶？治不易法，食不减餐，日数十行，精神反加。逾月之后，大解始正，计服甘凉约二百剂，肌肉复充，痰患若失。", "13306": "吴芸阁，因壮年时患霉疮，过服寒凉之药，疮虽愈，阳气伤残。虚寒病起，改投温补，如金液丹、大造丸之类，始得获安。奈医者昧于药为补偏救弊而设，漫无节制，率以为常，驯致血溢于上，便泄于下，食少痰多，喘逆碍卧，两足不能屈伸。董某犹云寒湿为患，进以苓姜术桂汤多剂，势益剧，且溲渐少而色绿如胆汁。医皆不能明其故，延孟英诊之，脉弦硬无情，曰：从前寒药戕阳，今则热药竭阴矣。胃中津液，皆灼烁以为痰。五脏咸失所养，而见证如上。水源欲绝，小溲自然渐少。木火内焚，乃露东方之色。与章虚谷所治暑结厥阴，用来复丹攻其邪从溺出，而见深碧之色者，彼实此虚，判分天壤。恐和缓再来，亦难为力矣。寻果殁。", "13307": "石芷卿骤患腹胀，旬日后脐间出脓，（湿热积于小肠。）外科视为肠痈，与温补内托之药，遂咳嗽不眠，腹中绞痛异常，痰色红绿，大便不行，乃延孟英商之。脉弦细以数，舌绛而大渴，曰：察脉候是真阴大虚之证。（乃真阴为热药所耗，非本如是也。）耆、术、归、桂，皆为禁剂。以甘露饮，加西洋参、花粉、贝母、杏仁、冬瓜子投之，痰咳即安。外科谓此恙最忌泄泻，润药不宜多服，（此何恙也，而以为最忌泄泻，真呓语也。）孟英曰：阴虚液燥，津不易生，虽求其泻，不可得也。恶可拘泥一偏，而不知通变哉。仍以前法去杏、贝、花粉，加知母、百合、合欢为方。并嘱其另邀老医朱嵩年敷治其外。如法施之，果渐向安，久之当脐痂落，如小儿蜕脐带状，脐内新肉莹然而愈。（肠痈无温补内托之法。清其上源，而下流自清，亦喻氏法也。）", "13308": "董晓书令正，素患脘痛，甚至晕厥。今秋病腰疼腿木，胸闷气逆，不能卧，胡某进温补药而喘汗欲脱，杳不思谷。孟英切脉，虚细中兼有弦滑，舌绛而渴，乃阴虚挟痰耳。与沙参、苁蓉、木瓜、石斛、蛤壳、蒺藜、石英、茯苓、紫菀、杏仁、楝实、首乌、牛膝诸药，（滋阴调肝而不腻，祛饮利痰而不燥，此孟英独得之秘。）旬日而安，继加熟地黄服之全愈。", "13309": "张与之令堂，久患痰嗽碍卧，素不投补药。孟英偶持其脉，曰：非补不可。与大剂熟地药，一饮而睡。与之曰：吾母有十七载不能服熟地矣，君何所见而重用颇投？孟英曰：脉细痰咸，阴虚水泛，非此不为功。从前服之增病者，想必杂以参、术之助气。昔人云勿执一药以论方，故处方者贵于用药之恰当病情，而取舍得宜也。", "13310": "顾云萝令正，久患脚气，屡治屡发，驯致周身筋掣，上及于巅，龈痛指麻，腰酸目眩，口干食少，夜不成眠。孟英察其脉芤而弦数，真阴大亏。腿虽痛，从无赤肿之形，脚气药岂徒无益而已。与二地、二冬、二至、知，柏、桑、菊、栀、楝、蒿、薇、龟板、鳖甲、藕等药，服之各恙渐减。盖因平素带下太甚，阴液漏泄，而筋骨失其濡养也。故治病须澄源以洁流。秋间以海螵蛸粉、鱼鳔、黄柏、阿胶为丸，服之痊愈。", "13311": "《薛氏医案》每以补中益气汤与地黄丸并用为治。虽卢不远之贤，亦或效尤。其实非用药之法也。如果清阳下陷而当升举者，则地黄丸之阴凝滞腻非所宜也；设属真阴不足，当用滋填者，则升柴之耗散不可投也。自相矛盾，纪律毫无，然上下分治，原有矩矱。屠敬思素属阴亏，久患痰嗽，动即气逆，夜不能眠，频服滋潜，纳食渐减，稍沾厚味，呕腐吞酸。孟英视脉左弦而微数，右则软滑兼弦。水常泛滥，土失堤防，肝木过升，肺金少降。良由久投滋腻，湿浊内蟠。无益于下焦，反碍乎中运。左强右弱，升降不调。以苁蓉、黄柏、当归、芍药、熟地、丹皮、茯苓、楝实、砂仁研为末，藕粉为丸。早服温肾水以清肝，以党参、白术、枳实、菖蒲、半夏、茯苓、橘皮、黄连、蒺藜，生晒研末，竹沥为丸；午服培中土而消痰；暮吞咸喜丸，肃上源以化浊。三焦分治，各恙皆安。悉用丸剂者，避汤药之助痰湿耳。（方俱灵妙，可以为法。）", "13312": "真阴素亏，两番半产，兼以劳瘁，内风陡升，病起头疼，左偏筋掣，旬日不语，二便不行，不食唇焦，苔黑边白，胸腹柔软，神气不昏，脉至弦缓，并不洪数。此非热邪内陷，乃阴虚痰滞机缄，宜予清宣，勿投寒腻，转其关键，可许渐瘳。（十月二十五日初诊。）", "13313": "舌稍出齿，未能全伸，苔稍转黄，小溲较畅，羞明头痛，显属风升；咽膈不舒，痰凝气阻。本虚标实，脉软且弦，不可峻攻，法先开泄。（二十六日再诊。）前方去胆星、半夏、茯苓，加枸杞三钱，淡苁蓉一钱，蒌仁五钱。", "13314": "舌能出齿，小溲渐行，神识稍清，苔犹灰滞，头疼似减，语未出声，脉至虚弦，右兼微弱。本虚标实，难授峻攻。开养兼参，庶无他变。（二十七日三诊。）前方去枳实、旋覆、钩藤、竹沥、姜汁，加参须一钱，麦冬三钱，远志七分，老蝉一对，淡海䖳一两，凫茈三个。", "13315": "稍能出语，尚未有声，舌色淡红，苔犹灰腻，毫不作渴，非热可知，脉软以迟，不食不便，宜参温煦，以豁凝痰。（二十八日四诊。）前方去雪羹，加酒炒黄连、肉桂心各五分。", "13316": "苔渐化而舌渐出，语稍吐而尚无音，头痛未蠲，略思粥食，胃气渐动，肝火未平，久不更衣，脉仍弦软。徐为疏瀹，法主温通。（二十九日五诊。）前方去麦冬，加麻仁四钱，野蔷薇露二两和服。", "13317": "连投温养，神气渐清，语亦有声，头犹左痛，苔退未净，大解不行，左脉微迟，法当补血。血充风息，腑气自行。（十一月初一日六诊。）前方去远志、菖蒲、老蝉，加天麻一钱，白芍二钱，桑椹三钱。", "13318": "脉已渐起，尚未更衣，浊未下行，语犹错乱，时或头痛。寐则梦多。濡导下行，且为先授。（初二日七诊。）前方去天麻、桑椹，加牛膝三钱，生首乌四钱，柏子仁二钱。", "13319": "虽已知饥，未得大解，肝无宣泄，时欲上冲。阴分久亏，岂容妄下。素伤思虑，肝郁神虚，脉软而迟，语言错乱。法当养正，通镇相参。（初三日八诊。）前方去白芍、首乌，加紫石英四钱，砂仁末炒熟地六钱，远志七分，菖蒲五分。", "13320": "神气渐振，安谷耳鸣，脉弱口干，面无华色，积虚未复，平补是投。（十一日十一诊。）前方去桂心、橘饼、乌梅，加龟板六钱，麦冬，蒲桃干各三钱。十贴后，汛至体康而愈矣。", "13321": "胡某素患耳鸣，且吸鸦片，时服补药，渐至食减痰多，舌上起灰黄厚腻之苔者三年矣，多医莫愈。孟英脉之弦细软滑，曰：阴亏真于下，痰热阻于上耳。以西洋参、菖蒲、远志、麦冬、竹茹、苁蓉、归身、石英、牡蛎、冬虫夏草，少加黄连服之。不半月，痰少餐加，舌苔尽退，三年之病，遂以霍然。", "13322": "王炳华之媳屡次堕胎，人渐尪羸，月事乱行，其色甚淡。医谓虚也，大投补剂。其瘦日甚，食少带多，遂加桂、附。五心如烙，面浮咳逆，痰壅碍眠，大渴喜嗔。医皆束手，始请孟英脉之，两尺虚软，左寸关弦数，右兼浮滑，乃阴虚火炎也。然下焦之阴虽虚，而痰火实于上焦。古人治内伤，于虚处求实；治外感，于实处求虚，乃用药之矩矱也。爰以沙参、竹茹、冬瓜子、芦笋、枇杷叶、冬虫夏草、石英、紫菀、苁蓉、旋覆为方，两剂即能寐。五六剂嗽止餐加，乃去紫菀、旋覆、沙参，加西洋参、归身、黄柏。服五剂，热减带稀，口和能食，再去芦笋、冬瓜子、枇杷叶，加熟地、枸杞、乌鲗骨服之而愈。又吴氏妇陡患咳嗽，痰不甚多，不能著枕者旬日也，神极萎顿。孟英察脉虚数，授枸杞、苁蓉、归身、石英、龟板、牡蛎、冬虫夏草、麦冬、牛膝、胡桃肉之剂，复杯而病若失。", "13323": "舜传之舅嫂，因用力拔针，而患指痛。内外杂治，渐至痛遍一身，卧榻不起，食少形消。余诊之，脉细而数，口干舌绛，乃营阴大亏，无以营养筋骨，岂可因拔针起病，遂以为外伤而妄投燥烈之药乎？宜其病日以甚也。以集灵膏加减为方而愈。", "13324": "张养之令正，饮食如常，而肌肤消瘦，（叙症详明）信事如期，而紫淡不恒，两腓发热，而别处仍和，面色青黄，而隐隐有黑气。俨似虚寒，多药不效，始逆孟英诊之。脉似虚细而沉分略形弦滑，曰：此阳明有余，少阴不足，土燥水涸，仲圣有急下存阴之法。然彼外感也，有余之邪，可以直泻；此内伤也，无形之热，宜以甘寒，义虽同而药则异也。赠以西洋参、生地、生白芍、生石膏、知、柏、苓、栀、麦冬、花粉、楝实、丹皮、木通、天冬诸品，服至数斤，黑气退而肌渐充，腓热去而经亦调矣。（孟英善用甘寒，投之此证尤宜。）", "13325": "朱氏妇素畏药，虽极淡之品，服之即吐。近患晡寒夜热，寝汗咽干，咳嗽胁疼。月余后渐至减餐经少，肌削神疲，始迓孟英诊之。左手弦而数，右部涩且弱，曰：既多悒郁，又善思虑，所谓病发心脾是也。而平昔畏药，岂可强药再戕其胃？诚大窘事。再四思维，以甘草、小麦、红枣、藕四味，令其煮汤频饮勿辍。病者尝药大喜，径日夜服之。逾旬复诊，脉证大减。其家请更方。孟英曰：毋庸。此本仲圣治藏燥之妙剂。吾以红枣易大枣，取其色赤补心，气香悦胃；加藕以舒郁怡情，合之甘、麦，并能益气养血、润燥缓急。虽若平淡无奇，而非恶劣损胃之比，不妨人任，胡可以果子药而忽之哉！恪守两月，病果霍然。", "13326": "余某年三十余，发热数日，医投凉解之法，遂呕吐自汗，肢冷神疲。亟延孟英诊之，脉微弱，曰：内伤也。岂可视同伏暑，而一概治之，径不详辨其证耶？与黄耆建中去饴，加龙骨、生姜、茯苓、橘皮，投剂即安。续加参、术，逾旬而愈。", "13327": "陈氏妇素无病，娩后甚健，乳极多而善饭。六月初，形忽遽瘦，犹疑天热使然，渐至减餐。所亲徐丽生嘱延孟英视之，脉细数，舌光绛，曰：急劳也，无以药为。夫乳者，血之所化也。乳之多寡，可征血之盛衰。兹乳溢过中，与草木将枯，精华尽发于外者何异？即令断乳，亦不及矣。其家闻之，尚未深信。即日断乳服药，及秋而逝。", "13328": "张慈斋室，自春间半产后，发热有时，迄于季秋。广服滋阴之药，竟不能愈。其大父陈霭山延孟英诊脉，按之豁然。投当归补血汤而热退，继以小建中愈之。（此众人用滋阴者，而孟英以阳和之品愈之。可见医者认证，不在执方也）", "13329": "沈辛甫善轩岐之学。其令正体素弱而勤于操作，年逾四秩，汛事过多，兼以便溏，冷汗气逆，参耆屡进，病日以危。孟英诊曰：心脾之脉尚有根，犹可望也。与龙骨、牡蛎、龟板、鳖甲、海螵蛸、石英、石脂、余粮、熟地、茯苓为方，一剂转机，渐以向愈。（亦下虚而误补其上者。应补之证，补不如法，尚且致害，况不应补而补者乎？）", "13330": "董哲卿二尹令正，胎前患嗽，娩后不痊。渐至寝汗减餐，头疼口燥，奄奄而卧，略难起坐。孟英珍脉虚弦软数，视舌光赤无苔，曰：此头疼口燥，乃阳升无液使然。岂可从外感治？是冲气上逆之嗽，初非伤风之证也。与苁蓉、石英、龟板、茯苓、冬虫夏草、牡蛎、穞豆衣、甘草、小麦、红枣、藕，数帖嗽减餐加，头疼不作。加以熟地，服之遂愈。", "13331": "室女多抑郁，干嗽为火郁，夫人而知之者。王杞庭之姐，年逾标梅，陡患干嗽，无一息之停，目不交睫。服药无功，求孟英诊焉。两脉上溢，左兼弦细，口渴无苔，乃真阴久虚，风阳上潜，冲嗽不已，厥脱堪虞，授牡蛎、龟板、鳖甲、石英、苁蓉、茯苓、熟地、归身、牛膝、冬虫夏草、胡桃肉之方。药甫煎，果欲厥，亟灌之即寐。次日黄昏，犹发寒痉，仍灌前药。至第三夜，仅有寝汗而已。四剂后，诸恙不作，眠食就安。设此等潜阳镇逆之方，迟投一二日，变恐不可知矣。况作郁治，而再用开泄之品耶？故辨证为医家第一要务也。", "13332": "谢谱香体属久虚，初冬患嗽痰减食，适孟英丁艰，邀施某视之，云是肾气不纳，命火无权，叠进肾气汤月余，遂致呕恶便溏，不饥无溺，乃束手以为必败矣。季冬仍延孟英诊之，脉甚弦软，苔腻舌红。乃中虚而健运失职，误投滋腻，更滞枢机。附桂之刚，徒增肝横。予党参、白术、茯苓、泽泻、橘皮、半夏、竹茹、栀子、薏苡、蒺藜、兰叶、柿蒂之剂，培中泄木、行水蠲痰，旬日而愈。（古人补肾不如补脾、补脾不如补肾之说，均有至理，而用违其宜，亦均足致败。此医所以首贵认证也。）", "13333": "钱氏妇患嗽数月，多医莫治，渐至废寝忘餐，凛寒乍热，经停形瘦，心悸耳鸣，滋补填阴，转兼便泄。孟英视脉虚弦缓大，而气短懒言，卧榻不支，动即自汗，曰：固虚也，然非滋阴药所宜。予参、耆、龙、牡、桂、芩、甘、芍、冬虫夏草、饧、糖，大剂，服旬日而安。继去龙、牡，加归、杞。服二十剂，汛至而康。病者欲常服补药，孟英止之曰：病痊体健，何以药为？吾先慈尝云：人如欹器，虚则欹，中则正，满则覆。世之过服补剂，致招盈满之灾者，比比焉。可不鉴哉！", "13334": "许子厚令庶母，年未四旬。患晡热，发于上焦，心悸头痛，腰酸腿软，饥不欲食，暮则目如盲而无所睹，时或腹胀，自汗带多。孟英脉之弦细而弱，气短不足以息，舌赤无苔，曰：此营血大亏，不可作暑治也。授人参、熟地、枣仁、枸杞、归身、麦冬、乌鲗骨、牡蛎、龟板、蒺藜、芍药、杜仲、羊藿等药，数十剂而康复如常。", "13335": "许兰屿令正，正月中旬偶食蒸饼，即觉腹中攻痛，而寒热间作，以为疟也。请孟英诊之，脉弦软而微数，曰：此不可以疟论。缘营素亏，往岁愈后，少于调补，仍当濡养奇经。盖阳维为病，亦能作寒热。而八脉隶于肝肾，温肾凉肝，病即霍然矣。授以苁蓉、枸杞、当归、白薇、青蒿、茯苓、竹茹、鳖甲、楝实、藕，数帖果愈。迨二月中旬，其病复作，举家佥以为疟。或云必前次早补，留邪未去使然。而兰屿远出，家无主议之人。孟英曰：前次愈之太易，我之罪也。不为善后，谁之过欤？如信我言，指日可瘳。第须多服培养之剂，保无后患。于是仍服前药，亦数剂而安。续以集灵膏去牛膝，加羊藿、阿胶、当归、黄柏、菟丝、苁蓉、蒲桃干，熬膏服之，竟不再发。", "13336": "李健伯夫人，因伤情志而患心跳，服药数月，大解渐溏，气逆不眠，面红易汗，卧榻不起，势已濒危。其次婿余朗斋浼孟英诊之，坚辞不治。其长婿瞿彝斋力恳设法，且云妇翁游楚，须春节旋里，纵使不治，亦须妙药稽延时日。孟英曰：是则可也。立案云：此本郁痰证，缘谋虑伤肝，营阴久耗，风阳独炽，烁液成痰。痰因火动，跳跃如舂。若心为君主之官，苟一跳动，即无生理，焉能淹缠至此乎？但郁痰之病，人多不识，广服温补，阴液将枯。脉至右寸关虽滑，而别部虚弦软数，指下无情。养液开痰，不过暂作缓兵之计。一交春令，更将何物以奉其生？莫谓赠言之不详，姑顺人情而予药。方用西洋参、贝母、竹茹、麦冬、茯神、丹参、苁蓉、薏苡、紫石英、蛤壳等。服之痰果渐吐，火降汗收，纳谷能眠，胸次舒适。而舌色光绛，津液毫无，改授集灵膏法。扶至健伯归，因谓其两婿曰：我辈之心尽矣，春节后终虞痉厥之变也。已而果然。", "13337": "仁和彭君芝亭之三令嫒，年甫逾笄，自去秋患痰嗽内热，渐至汛愆减食，咽烂音嘶，肌瘦便溏，不眠心悸。丁巳正月下旬，专人迎余往视，左脉细软而数，寸尤甚，右尺洪数，寸关不耐寻按。盖燥邪薄肺，初失肃清，阴分素亏，源流两涸。今胃气已败，万物发蛰之时，如何过去？其二令嫒深谙医理，极以为然。适邵位西枢部持蒋大理之函相召，余即解缆。嗣接赵君笛楼信云：彭女果殁于惊蛰前三日，抑何脉之神耶？余曰：亦偶然事耳。如前年五月间，偶诊顾听泉明经之脉，即谓家竾伯茂才云：顾君不可以冬，盖死象已见也。后竟殁于立冬之时。今年二月，诊庄文芝阶脉，谓其文孙嵋仙少君云：恐难过夏，而立夏前三日竟逝。十月初，游武林，访家瘦石兄切其脉，尺中微露浮弦，即谓其子曰：春令可虞。亦于次年惊蛰日，无疾而终。脉之可凭者如是，而竟有不可凭者，此其所以为微妙之学乎！", "13338": "许康侯令堂，初夏患坐卧不安，饥不能食，食则滞膈，欲噫不宣，善恐畏烦，少眠形瘦，便艰溲短，多药莫瘳。孟英按脉弦细而滑，乃七情怫郁，五火烁痰。误认为虚，妄投补药，气机窒塞，升降失常。面赤痰黄，宜先清展，方用旋覆、菖蒲、紫菀、白前、竹茹、茯苓、黄连、半夏、枇杷叶、兰叶。不旬而眠食皆安。为去前四味，加沙参、归身、紫石英、麦冬，调养而痊。", "13339": "沈峻扬令妹，年逾五旬，体素瘦弱，不能寐者数夜，证遂濒危。乃兄延孟英视之，目张不能阖，泪则常流，口开不能闭，舌不能伸，语难出声，苔黄不渴，饮不下咽，足冷不温，筋瘛而疼，胸膈板闷，溲少便秘，身硬不柔，脉则弦细软涩，重按如无。或疑中暑，或虑虚脱，孟英曰：身不发热，神又不昏，非中暑也。二便艰涩，咽膈阻闷，非脱证也。殆由情志郁结，怒木直升，痰亦随之，堵塞华盖，故治节不行，脉道不利也。误进补药，其死可必。但宜宣肺，气行自愈。方用紫菀、白前、兜铃、射干、菖蒲、枇杷叶、丝瓜络、白豆蔻，果一剂知，四剂瘳。", "13340": "邵鱼竹给谏，起居食饮如常，惟仅能侧卧，略难仰卧。仰而寤，无恙也，稍一合眼，则惊窜而醒。虽再侧眠，亦彻夜不得寐矣。多年莫能治。凡心肾不交之人，多不能仰卧。以仰则肾气不能上承而心气愈浮也。孟英以三才合枕中丹，加黄连，肉桂服之良效。（心肾交治，而以黄连、肉桂媾合之，用意甚巧。）其长郎子旊，久患痰多，胸膈满闷，连年发痫，药之罔效。孟英脉之曰：气分偏虚，痰饮阻其清阳之旋运，宜法天之健以为方，则大气自强，而流行不息，胸次乃廓然如太空矣。与六君去甘草，加黄耆、桂枝、薤白、蒌仁、石菖蒲、蒺藜、旋覆，服之满闷渐舒，痫亦不发矣。", "13341": "周菊生令正，患少腹酸坠，小溲频数而疼，医投通利不效，继以升提温补。诸法备试，至于不食不寐，大解不行，口渴不敢饮水，闻声即生惊悸。孟英脉之曰：厥阳为病也，不可徒治其太阳。先与咸苦，以泄其热；续用甘润，以滋其阴，毫不犯通渗之药而愈。", "13342": "杨某方作事，不知背后有人潜立，回顾失惊，遂不言不食，不寐不便，别无他苦。孟英按脉沉弦，以石菖蒲、远志、琥珀、胆星、旋、贝、竹黄、杏仁、省头草、羚羊角为剂，化服苏合香丸。二帖，大解行而啜粥，夜得寐而能言，复与调气宁神蠲饮药，数日霍然。", "13343": "章养云室患感，适遇猝惊，黄、包二医，皆主温补，乃至昏谵痉厥，势极危殆，棺衾咸备，无生望矣。所亲陈仰山闻之，谓云：去秋顾奏云之恙，仅存一息，得孟英救愈，子盍图之。章遂求诊于孟英，证交三十八日，脉至细数无伦，（阴将竭矣。）两手拘挛，（肝无血养。）宛如角弓之反张，痰升自汗，渴饮苔黄，面赤臀穿，昼夜不能合眼。先与犀、羚、贝、斛、元参、连翘、知母、花粉、胆星、牛黄、鳖甲、珍珠、竹黄、竹叶、竹沥、竹茹为方。三剂，两手渐柔，汗亦渐收。又五剂，热退痰降，脉较和，而自言自答，日夜不休，乃去羚、斛、珠、黄，加西洋参、生地、大块朱砂两许。服之，聒絮不减。或疑为癫，似有摇惑之意。孟英恐其再误，嘱邀许芷卿商之。芷卿极言治法之丝丝入扣，复于方中加青黛、龙、牡。服二剂，仍喋喋不已。（热在心，而用肝肾药，宜乎不效。）孟英苦思数四，径于前方加木通一钱，投匕即效。次日病者自语：前此小溲业已通畅，不甚觉热，昨药服后，似有一团热气从心头直趋于下，由溺而泄。从此神气安谧，粥食渐加，两腿能动，大解亦坚。忽咽肿大痛，水饮不下，孟英曰：余火上炎也。仍与前方，更吹锡类散而安。惟臀疮未敛，腿痛不已，乃下焦气血伤残，改用参、耆、归、芍、生地、合欢、山药、麦冬、牛膝、石斛、木瓜、桑枝、藕肉。数服痛止餐加，又与峻补，生肌而愈。（温病误补，未有能生者。孟英独出手眼，实发前人所未发。用木通精当。凡心经蕴热，用犀角、黄连等药，必兼木通，其效乃捷，以能引心经之热从小肠出也。）", "13344": "杭城温元帅，例于五月十六日出巡遣疫。有魏氏女者，家住横河桥之北，会过其门，将及天晓，适有带发头陀，由门前趋过，瞥见之大为惊骇，注目视之，知为僧也，遂亦释然。而次日即不知饥，眩晕便秘。医谓神虚，投补数帖，反致时欲昏厥。（不问何证，竟投温补，何其愚耶？）更医作中风治，势益甚。旬日后，孟英持其脉弦伏而滑，胸腹无胀闷之苦，旬余不更衣。是惊则气乱，挟痰逆升，正仲圣所谓诸厥应下者，应下其痰与气也。以旋、赭、栀、连、雪羹、楝、贝、金箔、竹沥、菔汁为方，并以铁器烧红淬醋，令吸其气。二剂，厥止，旬日而痊。", "13345": "王瘦石禀属阴亏，卒闻惊吓之声，而气逆肢冷，自汗息微。速孟英视之，身面皆青绿之色，脉沉弦而细。乃素伤忧虑，而风阳陡动也。与牡蛎四两，鳖甲二两，蛤壳一两，石英五钱，龙齿、小麦、辰砂、麦冬、茯神、贝母、竹茹为方，一剂知，二剂已，续以滋养而瘳。（凡阴虚之体；血不足以养肝，则肝阳易潜。用大剂镇逆，养阴开郁法治，丝丝入扣，宜乎应手辄效也。）", "13346": "顾媪因比邻失火，几焚其店，惊吓之余，不能起榻，胁痛偏右，便秘神瞀，身面发黄。医云湿热，治之罔效，乞诊孟英，脉涩而弦，按之甚软，曰：此因惊恐气结不行所致。予沙参、桑叶、栀子、丝瓜络、冬瓜子、苇茎、枇杷叶、旋覆、葱须、竹茹，数剂而痊。", "13347": "太仓陆竹琴令正，陡患心悸，肢冷如冰。其子皇皇，浼吴江程勉耘恳援于孟英。察其脉浮弦而数，视其舌尖赤无苔。乃阴虚阳越，煎厥根萌。予元参、二至、三甲、龙齿、石英、生地、牛膝、茯神、莲子心而愈。", "13348": "李叟年越古稀，意欲纳妾，虽露其情，而子孙以其耄且瞽也，不敢从，因此渐病狂惑。群医咸谓神志不足，广投热补之药，愈服愈剧，始延孟英诊之。脉劲搏指，面赤不言，口涎自流，力大无制，曰：此禀赋过强，阳气偏盛，姑勿论其脉证，即起病一端，概可见矣。如果命门火衰，早已痿靡不振，焉能兴此念头？医见其老，辄疑其虚。须知根本不坚实者，不能享长年，既享大寿，其得于天者必厚。况人年五十，阴气先衰，徐灵胎所谓千年之木，往往自焚，阴尽火炎，万物皆然。去冬吾治邵可亭孤阳喘逆，壮水清火之外，天生甘露饮，灌至二百余斤，即梨汁也。病已渐平，仅误于两盏姜汤，前功尽堕。可见阴难充长，火易燎原，今附、桂、仙茅、鹿茸、参、戟、河车等药，服之已久，更将何物以生其涸竭之水，而和其亢极之阳乎？寻果不起。", "13349": "江某年三十余，忽两目发赤，牙龈肿痛，渐致狂妄，奔走骂人，不避亲长。其父皇皇，求孟英诊之。脉大而数，重按虚散，与东洋参、熟地黄、辰砂、磁石、龙齿、菖蒲、枣仁、琥珀、肉桂、金箔、龙眼肉为剂，投匕即安，翼日能课徒矣。（昔余友彭香林，患此证，医虽知其虚，而治不如法，竟以不起。今读此案，弥增惋叹。）", "13350": "王月锄令媳，于庙见时忽目偏左视，扬手妄言，诸亲骇然，诘其婢媵，素无此恙。速孟英视之，脉弦滑而微数，苔黄脘闷。盖时虽春暮，天气酷热，兼以劳则火升，挟其素有之痰而使然也。与犀、羚、栀、翘、元参、丹参、薄荷、花粉，送礞石滚痰丸。三服而痰下神清，改投清养遂愈。次年即诞子。", "13351": "费伯元分司，患烦躁不眠。医见其苔白也，投以温药，因而狂妄瘛疭，多方不应。余荐孟英视之，左脉弦细而数，右软滑，乃阴虚之体，心火炽，肝气动，而痰盛于中也。先以犀、羚、桑、菊，息其风；元参、丹皮、莲心、童溲，清其火；茹、贝、雪羹，化其痰，两剂而安。随与三甲、二至、磁朱，潜其阳；甘、麦、大枣，缓其急；地黄、麦冬，养其阴，渐次康复。", "13352": "朱养心后人名大镛者，新婚后神呆目瞪，言语失伦。或疑其体弱神怯，与镇补安神诸药，驯致善饥善怒，骂詈如狂。其族兄已生邀孟英诊之，右脉洪滑。与犀角、石膏、菖蒲、胆星、竹沥、知母，吞礞石滚痰丸而愈。其大父患四肢冷颤，常服温补，延久不痊。孟英切其脉弦而缓，曰：非虚也。与通络方，吞指迷茯苓丸而瘥。", "13353": "藁砧远出，妇病如狂。似属七情，而亦有不尽然者。有陈氏妇患此月余，巫医屡易，所费既巨，厥疾日增。孟英切其脉弦而数，能食便行，气每上冲，腹时痛胀。询其月事，云病起汛后，继多白带，孟英曰：病因如是。而昼则明了，夜多妄言，酷似热入血室之候。径从瘀血治可也。予桃仁、红花、犀角、菖蒲、胆星、旋覆、赭石、丹参、琥珀、葱白之剂，两服而瘀血果行，神情爽慧。继去桃仁、红花，加当归、元参，服数剂而瘳。", "13354": "陈氏妇，年逾四旬，娩后忽然发狂。时值秋热甚烈，或以为受热，移之清凉之所，势不减。或以为瘀，投以通血之药而不效。金、顾二医皆为虚火，进以大剂温补，则狂莫能制。或云痰也，灌以牛黄丸亦不应。浼孟英视之，切脉弦数，头痛睛红，胸腹皆舒，身不发热，乃阴虚而肝阳陡动也。先灌童溲，势即减。剂以三甲、二至、丹参、石英、生地、菊花、牛膝、藕，用金饰同煎。一饮而病若失。愈后询之，果因弄瓦而拂其意耳。", "13355": "陆渭川令媳患感，适遇姅期医治数日，经止而昏狂陡作。改从热入血室治，转为痉厥，不省人事。所亲沈雨阶为延孟英诊之，脉弦软而虚滑，气逆面青，牙关不开，遗溺便秘。令按胸次，坚硬如柈。此冬温尚在气分。如果热入血室，何至昼亦昏迷。良由素多怫郁，气滞痰凝。用柴胡则肝气愈升，攻瘀血则诛伐无过。予小陷胸合蠲饮六神汤，加竹沥，调服牛黄至宝丹一颗。外以苏合丸涂于心下。痰即涌出，胸次渐柔，厥醒能言，脉较有力。次日仍用前方，调万氏清心丸一粒。果下痰矢，渐啜稀糜。改授肃清，数日而愈。续有顾某陡患昏狂，苔黄便秘，卧则身挺，汗出五心。医云热入膻中，宜透斑疹，治之加剧。孟英诊脉弦缓不鼓，身无大热，小溲清长。的非外感。乃心虚胆怯，疑虑忧愁，情志不怡，郁痰堵窍也。以蠲饮六神汤，合雪羹，加竹叶、莲子心、竹沥。服二剂，狂止，自言腹胀而头偏左痛，仍以前方，吞当归龙荟丸。大解始下，改用清火、养心、化痰舒郁之法而愈。", "13356": "朱君庆雨次郎，夙有痫证。因劳伤之后，发冷吐酸，不饥神惫，服药数剂，遂致故疾日作数次。医者术穷。余脉之，弦细若伏，而肢冷如冰，苔白如砂，涎沫频吐，头疼而晕，重裘不知温。是热深厥深，误投热药，而饮邪内盛，故热邪隐伏不显也。询其小溲果甚赤。以导痰汤去草，合雪羹，加芩、连、栀、茹、木通煎，吞当归龙荟丸，复杯而愈。", "13357": "顾升庵参军之仲郎，久患多疑善恐，（痰之见证）不出房者数年矣。食则不肯与人共案，卧则须人防护，寡言善笑，（热之见症）时或遗精。多医广药，略无寸效。孟英切脉甚滑数，（脉与证合）与元参、丹参、竹黄、竹茹、丹皮、黄连、花粉、栀子、海䖳、荸荠为剂，送服当归龙荟丸。四帖，即能出署观剧，游净慈而登吴山。参军大喜，以为神治，次年为之配室。", "13358": "己酉春，胡孟绅山长患疑，坐卧不安，如畏人捕。自知为痰，饵白金丸吐之，汗出头面，神躁妄闻。（撩动其猖狂之势）孟英切其脉弦滑洪数，不为指挠，投石膏、竹茹、枳实、黄连、旋覆、花粉、胆星、石菖蒲，加雪羹、竹沥、童溲，吞礞石滚痰丸。下其痰火，连得大解，夜分较安。惟不能断酒，为加绿豆、银花、枳椇子，吞当归龙荟丸。旬余脉证渐平，神气亦静。尚多疑惧，改授犀角、元参、丹皮、竹叶、竹茹、贝母、百合、丹参、莲心、猪胆汁炒枣仁、盐水炒黄连，吞枕中丹，以清包络肝胆之有余而调神志。又旬日，各恙皆蠲，即能拈韵，继与十味温胆法善其后。", "13359": "洪张伯孝廉令弟苏仲，乡试后，自以场作不惬于怀，怏怏数日，渐以发热。医作伏暑治，日形困顿，懒语音低，神情恍惚，稍合眼辄以文有疪累如何中式云云。屡服牛黄、犀角等药，竟无寸效。延孟英视之，时时出汗，不饥溺少，舌绛口干，切脉虚软以数，曰：此心火外浮也，昔贤惟王损庵论之独详。今人罕读其书，每与温暑逆传证混淆施治。夫心犹镜也，彼热邪内陷，袭入心包，则雾障尘蒙之象也，故可磨之使明，是为实证，今心阳过扰，火动神浮，乃铜质将镕之候也。法宜坚之使凝，是为虚证。良由阴分素亏，心营易耗。功名念切，虑落孙山。病属内伤，似乎外感，大忌发表，更禁寒凉，又非东垣补中益气之例，无怪医者为之技窘也。而有药治病，无药移情，余有一言，可广其意。文之不自惬于怀者，安知不中试官之意乎？且祸盈福谦，《易》之道也。尝见自命不凡者，偏不易售；而自视欿然之士，恒于意外得之。即此一端，吾可必其中也。病者闻之，极为怡旷。服药后各恙渐安，半月而愈。及榜发，果获隽。佥云药既神妙，而慧吐齿牙，竟成吉忏。仁言仁术，医道通仙，可于孟英信之矣。其方则甘草、干地黄、麦冬、枸杞、盐水炒黄连、紫石英、龟板、龙齿、珍珠也。迨季冬，两孝廉将北上，其母夫人陡病恍忽，孟英往诊曰：高年素多忧虑，而别离在即，神倏飞阳，纵有仙丹，亦难救药。另邀他医视之，皆云冬温。须过十四日，及旬而没，神气不昏。始信孟英镜质消镕，与尘蒙雾障有殊也。", "13360": "张友三室，去春受孕后，忽梦见其亡妹。而妹之亡也，由于娩难，心恶之。因嘱婢媪辈广购堕胎饵服，卒无验。冬间娩子后亦无恙。自疑多饵堕胎药，元气必伤，召朱某治之。述其故，朱即迎合其意，而断为大虚之候，且云苟不极早补救，恐延蓐损。病者闻而益惧，广服补剂，渐至卧榻不起，多药弗效。延至仲春，族人张镜江为邀孟英视之，不饥不寐，时或气升，面赤口干，二便闭涩，痰多易汗，胸次如舂，咽有炙脔，畏明善怒，刻刻怕死，哭笑不常，脉至左部弦数，右手沉滑，曰：此郁痰证，误补致剧也，与上年李健伯令正之病情极相类。第彼已年衰而伤于忧思谋虑，是为虚郁；此年壮体坚，而成于惊疑惑惧，是为实郁。虚郁不为舒养，而辄投温补，则郁者愈郁，而虚者愈虚。实郁不为通泄，而误施温补，则郁不能开，而反露虚象，所谓大实有羸状也。医者但云补药日投，虚象日著。不知虚象日形，病机日锢。彼岂故酿其病而使之深耶？亦是一片仁心，无如药与病相僢而驰，盖即好仁不好学之谓耳。余非好翻人案，恐不为此忠告，未必肯舍补药而从余议也。病者闻之大悟，即授小陷胸合雪羹，加菖蒲、薤白、竹茹、知母、栀子、枳实、旋、赭出入为方，吞当归龙荟丸。三剂后，蒌仁每帖用至八钱，而大解始行，各恙乃减。半月后，心头之舂杵始得全休。改用清肃濡养之法，调理匝月，汛至而痊。", "13361": "秀水严小亭令正，五十八岁。因数年前，家有讼事，屡遭惊吓，而起疑病。自欲吞金，虽己衣不敢用钮扣，并时絷手足。即夫媳儿孙，皆屏绝不许入房，云恐自摘他人之衣扣、环饰咽下也。仅留一媪，在室服侍，而饮食起居如常人。医皆谓其神虚，率投镇补。今秋患右腿青紫肿痛，牙龈臭腐。季秋延余视之，脉弦滑而数，曰：此病不在心而在胆，故能记忆往事，而善谋虑，岂可指为神志不足乎？胆热则善疑，愈补则热愈炽，炽极则传于胃，胃热蕴隆，乃成青腿牙疳也。锢疾已六七年，宜先治其新病。以菖蒲、胆星、石膏、胆草、知母、元参、银花、栀子、白薇、竹茹、黄连，煎调玉枢丹。并令购白马乳饮之。六剂而病减，半月新病愈。仲冬余又游禾，复诊脉较平，而胆亦稍和。盖白马乳，善清胆胃之热也。", "13362": "朱庆云室，年六十六岁。初发热即舌赤无津，钱、丁、任、顾诸医胥云高年液少，津涸堪忧。甘润之方，连投八剂，驯致神悗耳聋，不饮不食，沉沉欲寐，呃忒面红，势已濒危。徐德生嘱其延孟英图之，审其脉弦滑而数，视其舌绛而扪之甚燥。然体丰呼吸不调，呃声亦不畅达。合脉证与体而论之，虽无脘闷拒按之候，确是肝阳内炽，痰阻枢机，液不上承，非津涸也。剂以小陷胸汤，加茹、薤、旋、菖、枇杷叶、苏叶。一饮而夜得微汗，身热即退。次日，痰嗽大作，舌滑流涎，病家诧曰：奇矣。许多润药，求其润而愈燥。何以此剂一投，而反津津若是耶？殆仙丹矣。三帖后，更衣呃止，痰嗽亦减，渐进稀粥，改用沙参、紫菀、苡、斛、归、茹、麦冬、瓜子。服数帖溲畅餐加，而觉肢麻头晕，予参、耆、归、芍、橘、半、熟地、天麻、石英、牛膝、茯苓、桑枝，补虚、息风、化痰而健。", "13363": "曹氏妇孀居而操家政，人极精干，患恙旬余，诸医以为冬温，而多药罔瘥，势濒于危。伊亲孙位申速孟英挽之，面赤耳聋，脉状细软，舌赤无液，粒米不沾，夜不成眠，便溏溲赤，痰咸咳逆，腹胀气冲，龈肿巅疼，音低自汗，口中甚辣，心下如焚，两足不温，时欲发晕。乃肝肾素亏，心阳内亢。原非感证，药误已深，纵是冬温，亦不可妄施柴葛。况足冷面赤，非浑身发热之比也。既耗其气，更烁其营，阴火潜燃，治宜镇息。方以参、蛎、连、芍、茹、冬、楝、斛、丹参、小麦、龟板、鳖甲，煎吞磁朱丸。一饮胀消，余证不减，去楝、芍、龟板、鳖甲，加龙齿、银花、导赤散。三服，晕止便坚，小溲亦畅，略安寝食，再去银花、木通、磁朱丸，加知、柏、红枣、紫石英，而麦冬以朱砂染。两帖，火降足和，舌色渐润。又两帖，汗嗽胥减，心下始凉，乃易生地以熟地，滋补而瘳。", "13364": "癸丑孟春，陈舜廷自宁波旋杭，迓孟英诊视，云：去冬患痰嗽，彼处医家初以疏散，继则建中，诸药备尝，日渐羸困，左胁跃跃跳动，胸次痒如虫行，舌素无苔，食不甘味，嗽甚则汗，夜不安眠，痰色清稀，便溏溲短，恐成肺痿，惟君图之。孟英诊曰：病始肺伤于燥，治节不行。体质素属阴亏，风阳内煽，烁其津液，故右脉软滑而虚。温以辛甘，致左脉浮弦且数。虽非肺痿，而上下交虚。治先保液息风，续宜壮水，可奏肤功。徒化痰理嗽，见病治病，有何益乎？爰以沙参、苇茎、冬瓜子、丝瓜络、竹茹肃肺气，甘草、石斛、燕窝生津液，冬虫夏草、石英、牡蛎息风阳。投剂即嗽减能眠，旬日后去冬子、石斛，加归身、麦冬、茯苓。服数帖，两脉较和，餐加溺畅，再去牡蛎、甘草、丝瓜络，加熟地、盐橘红。十余剂，各恙皆安。以高丽参易沙参，善后而康。", "13365": "孟夏许芷卿偶自按脉，左寸如无。招他医诊之，佥云心散，举家惊惧，己亦皇皇。屈孟英视之，曰：劳心而兼痰火之郁，故脉伏耳。其火升面赤，不寐胁鸣，乃惊骇激动肝胆之阳勃然升越，非本病也。予人参、黄连、菖蒲、紫石英、小麦、麦冬、莲子心、红枣、竹叶、甘草为方，一剂知，二剂已。", "13366": "石北涯之大令媳，忽患多言不寐，面赤火升，汗出心摇，仓皇欲死。孟英察脉虚弦小数，乃赋质阴亏。将交春令，虚阳浮动，有鸢飞鱼跃之虞。亟以人参、龙齿、牡蛎、石英、甘草、百合、小麦、竹叶、红枣、青盐水炒黄连为剂，引以鸡子黄，投匕即安，续加熟地、阿胶滋填而愈。", "13367": "乙卯冬初，余挚眷回藉，卜居济諪溪。秀水吕君慎庵邀余游新塍，视屠舜传之女适张氏者。据云病起产后，延至五年，久卧于床，势成瘫痪。广服补剂，迄不见功。及入室视之，病者尚著单衣，贴身仅铺草席，而窗户尽扃，因询畏热而喜暗乎？曰：然。按脉弦而滑，执烛照之。面有赤色，苔甚黄腻。复询其胸闷气升乎？溲热易汗乎？亦曰然。且汛事仍行，饥不能食，耳鸣头晕，腿软痰多，病不在于血分。虽起自产后，而根株实不在是。细诘之，始云未嫁之前，宿有气升眩晕之疾，于今已十载矣。余曰：是也。此固风阳内炽，搏液成痰之证。因娩而血大去，故发之较剧。医者不揣其本，而齐其末，遂以为产后之虚，温补率投，升逆愈甚。下虚上实，致不能行。与清火降痰之剂而别，曰：气得下趋，病可渐愈。后闻其西席钟君子安向慎庵云：服王药五帖，即能扶杖而出矣。", "13368": "谢君再华之室，偶患齿痛，日以加甚。至第五日，知余游武林，拉往视之，已呻吟欲绝，浑身肉颤。按脉不能准，问病不能答，苔色不能察，惟欲以冷物贴痛处。余谛思良久，令以淡盐汤下滋肾丸三钱，外以坎宫锭涂痛处，吴茱萸末醋调贴涌泉穴。次日复诊，已谈笑自若，如常作针黹矣。向余致谢曰：昨夜一饮即寐，而病如失，真仙丹也。余曰：昨日大窘，若非素知为肝阳内炽之体，几无措手。今火虽降，脉尚弦数，宜用滋潜善后。以一贯煎方，嘱其熬膏服之，遂不复发。", "13369": "仁和胡次瑶孝廉，北上未归，其令正于仲夏陡患肢麻昏晕，速余往视。面微红，音低神惫，睛微赤，舌苔微黄，足微冷，身微汗，胸微闷，脉微弦。乃本元素薄，谋虑萦思，心火上炎，内风随以上僭也。不可误以为痧闭，而妄投香燥辛散之品。以人参、龙、蛎、菖、连、石英、麦冬、小麦、竹叶、莲子心为方，两服而愈。寻与平补，以善其后。", "13370": "钱塘姚欧亭大令宰崇明，其夫人自上年九月以来，夜不成寐，佥以为神虚也。补药频投，渐不起榻，头重如覆，善悸便难，肢汗而心内如焚，多言，溺畅畏烦，而腹中时胀，遍治无功。其西席张君心锄屡信专丁邀诊，余不得辞，初夏乘桴往视。左寸关弦大而数，右稍和而兼滑，口不作渴，舌尖独红。乃忧思谋虑，扰动心肝之阳，而中挟痰饮，火郁不宣。温补更助风阳，滋腻尤增痰滞。至鹿茸，为透生巅顶之物，用于此证，犹舟行逆风，而扯满其帆也。明粉为芒硝所炼，投以通便，是认为阳明之实秘也。今胀能安谷，显非腑实，不过胃降无权，肝无疏泄，乃无形之气秘耳。遂以参、连、旋、枳、半、芍、蛤、茹、郁李、麻仁、凫茈、海䖳，两服即寐，且觉口苦溺热。余曰：此火郁外泄之征也。去蛤壳，加栀子。便行胀减，脉亦渐柔，再去麻、郁、雪羹，加石英、柏子仁、茯苓、橘皮、小麦、连子心、红枣核。三帖各恙皆安，去石英、栀子，加冬虫夏草、鳖甲为善后，余即挂帆归矣。然不能静摄，季夏渐又少眠，复遣丁谆请。余畏热不行，命门人张笏山茂才（即渠西席之子也。）往诊，遵前而治，遂以告愈。", "13371": "书贾陈南桥患冬温，数日后谵妄不眠，所亲任殿华竭力清解，热退便行，忽然不语，因迓孟英视之。入房见其危坐于榻，面无病容，两目开阖自如，呼之不闻不答，若无知识者。按脉左寸细数无伦，尺中微细如丝。乃肾阴素伤，心阳过扰，真水下竭，真火将施，纵有神丹，不能接续。吾师赵菊斋先生暨许少卿皆在座，佥云渠有八旬老父，一岁孤儿，盍忍恝然，勉为设法。如犀角、紫雪之类，以图万一，不亦可乎？孟英曰：此非痰滞于络，亦非热传手少阴。适从高孙两家来，并此为三败证。余一日而遇之，皆无药可用，不敢立方。平素不畏大证，君辈共知，稍有可为，毋劳谆嘱也。既而果逝。", "13372": "仁和邵位西枢部令爱，字许子双司马为媳者，在都患心悸头晕，渐不起榻，驯致不能出语。旋杭，多医治之，佥以为虚，广眼补剂。遂减餐少寐，频吐痰涎，畏风怕烦，溲短便闭，汛愆带盛，以为不能过冬至矣。适余游武林，赵君菊斋，嘱其邀诊。脉象弦数而滑，面白唇红，目光炯炯而眉蹙，苔黄羞明乳裂。既非瘄证，又非失音。强使出一二字，则艰涩异常，摇手点头，或以笔代口，又无妄见，亦非祟病。余谛审之，谓其必起予惊恐，而痰涎阻于窍隧。病者颔之，以起病时，为一大瓶堕地，乍闻其声，而一吓也。遂与清心、肝、胆、胃之法，加舒络、涤痰、开郁之品。服后各恙渐减，眠食渐安。丙辰春，余复视之，仍卧于床，仍不出语。按钮氏续觚剩鼠魂一条，与此相似，彼特神其说耳。然余竟不能治之使语，殊深抱愧，录之以质高明。戊午季秋，复游武林往诊，尚如故。闻其仍服补剂，因力劝阻，而赠以清肺、通络、涤痰之品，制丸噙化。服至次年春仲，遍身发疹，频吐秽痰，语能渐出。乃蕴结外解，从此肃清，可期奏绩，初论尚不甚爽。", "13373": "徐梦香，年近六旬，患手颤不能握管。孟英以通补息风药，吞指迷茯苓丸而安。仲秋类中，遗溺痰升，昏瞀妄言，汗多面赤，急延孟英视之，脉浮弦洪滑。盖吸受热邪，而连日适服参汤也。与羚羊角、石菖蒲、连翘、栀子、桑叶、菊花、楝、斛、知母、花粉、竹沥、银花、蒿、薇等药。一剂知，二剂神清，乃去羚、菖，加茹、贝、滑石。投之，下利赤白如脓垢者数日，始知饥纳谷，渐以调理而愈。匝月即能作画，季秋仍幕游江右。", "13374": "徐月岩室，患周身麻木，四肢瘫痪，口苦而渴，痰冷如冰，气逆欲呕，汛愆腹胀，频饮极热姜汤，似乎畅适。深秋延至季冬，服药不愈。孟英诊脉沉弦而数，曰：溺热如火乎？间有发厥乎？病者唯唯。遂以雪羹、旋、赭、栀、楝、茹、斛、知母、花粉、桑枝、羚羊、橄榄、蛤壳为方，送下当归龙荟丸。服之递效，二十剂即能起榻，乃去羚、赭，加西洋参、生地、苁蓉、藕，投之渐愈。", "13375": "赵秋舲进士，去秋患左半不遂。伊弟笛楼，暨高弟许芷卿茂才，主清热蠲痰，治之未能遽效。邀孟英诊之，脉甚迟缓，苔极黄腻，便秘多言，令于药中和入竹沥一碗，且以龙荟滚痰二丸，（用药固甚合法，何于脉之迟缓处未见照顾？）相间而投。二丸各用斤许，证始向愈。（如此而止，殊少善后之法）今春出房，眠食已复，而素嗜厚味，不戒肥甘，孟夏其病陡发。孟英诊之，脉形滑驶如蛇，断其不起，秋初果殁。", "13376": "赖炳也令堂，年近古稀，患左半不遂。医与再造丸暨补剂，服二旬病如故。孟英按脉弦缓而滑，颧赤苔黄，音微舌蹇，便涩无痰，曰：此痰中也，伏而未化。与犀、羚、茹、贝、菖、夏、花粉、知母、白薇、豆卷、桑枝、丝瓜络等药。服三剂而苔化，音渐清朗。六七剂腿知痛，痰渐吐，便亦通。既而腿痛难忍，其热如烙，孟英令涂葱蜜以吸其热，痛果渐止。半月后，眠食渐安。二旬外，手能握。月余，可扶掖以行矣。", "13377": "魏翎谷浼孟英视其郁甥之病，热逾半月，自胸次胀及少腹，痛而不可抚摩，便秘溺赤，舌黑口干，自汗烦躁，六脉弦强无胃，曰：此恙酷似伤寒大结胸证。结胸烦躁，无药可治。越二日便行而殁。孟英曰：伤寒之邪在表，误下则邪陷而成结胸。未经误下，不为结胸。温热之邪在里，逆传于心包而误汗，则内闭似外脱，顺传于胃府而误汗，则盘踞而结胸。前人但云误汗劫夺胃汁，而未及于结胸者，因结胸证不多见耳。然亦不可不知也，故谨识之。郁病初起，某医用葛根一剂，继则胡某之柴、葛、羌、防十余剂，酿成是证。（温病忌误汗，不忌误下。以汗则津涸而热益炽，下则热势可借以少减也。）", "13378": "王雪山于上年误饵透土丹之时，孟英诊治向愈，即嘱其常饮柿饼汤，以杜关格于将来。迨今四月间，形体日瘦，张某进以导湿、疏风、补气之药。孟英偶见之，力劝其温补莫投。且以凡物遇火则干瘪，得滋则肥润为譬。雪山深韪之，奈为张某辈朝夕虚言所眩，仍服补剂。延至秋间，始延孟英视之。胁痛畏风，周身络胀，时欲敲扑，食少便难，日哺微有寒热，脉来弦涩而数，右寸关弦软以滑。是升降之令久窒，痰邪袭于隧络，（将断语与脉证合参，便知审病之法。）关格之势将成。再四求治，与沙参、茹、贝、薇、蒿、旋、斛、栀、楝、兰草、枇杷叶、丝瓜络、冬瓜子、芦根、茅根等，出入为方。服之寒热既蠲，胁痛亦减。雪山大喜，复请诊之，脉颇转和。第肝阴久为谋虑所伤，最怕情志不怡，必生枝节，小愈奚足为恃，嘱其另邀明眼图之。渠即招沈辛甫、顾听泉、吴卯君、任心柏诸君商之，方案皆与孟英相合。雪山转恳孟英设法，且云：读君之案，洞彻病情，侥幸成全，足感再生之德。即使无效，我亦瞑目而亡。孟英感其言，殚竭心力，以图久延。无如嗔怒萦思，诸多枨触，频有转关，屡生枝节。大便必极捶背尻而始解，上则吐痰恶谷，果成关格之候。肩至伊子旋杭，惑于谗言，翻以竹茹、竹沥为药性太凉，而以不用温补为谤，求乩方，径以麻黄、细辛、鹿角等药投之，遂至舌色干紫，津涸而亡。不知者未免以成败论，所谓道高谤多。然柿饼汤投于年余未病之前，其卓见已不可及。而见危受命，勉力图维，肠热心孤，更可钦也。特采其案，以为世之有识者鉴焉。此证即叶氏所谓下竭上结之候也。叶氏虽有方案，亦未知果能取效否？不知古名家遇此，当作何治法，方书中迄无及者。孟英此案，已是开人不敢开之口。至其悉当病情与否，则殊未敢轻论也。", "13379": "王雪山令媳，患心悸眩晕，广服补剂，初若甚效，继乃日剧，时时出汗，肢冷息微，气逆欲脱。灌以参汤，稍有把握。延逾半载，大费不赀。庄之阶舍人，令延孟英诊视，脉沉弦且滑，舌绛而有黄腻之苔，口苦溲热，汛事仍行。病属痰热𫐖輵，误补则气机壅塞。与大剂清热涤痰药，吞当归龙荟丸，服之渐以向安。（痰热体实者，此丸须有殊功。）仲夏即受孕，次年二月诞一子。惜其娠后停药，去痰未尽，娩后复患悸晕不眠，气短不饥。或作产后血虚治不效，仍请孟英视之。脉极滑数，曰：病根未刈也。与蠲痰清气法果应。", "13380": "比邱尼心能，体厚蹒跚，偶患眩悸。医以为虚，久服温补，渐至发肿不饥。仲夏延孟英视之，脉甚弦滑，舌色光绛。主清痰热，尽撤补药，彼不之信，仍服八味等方。至季夏再屈孟英诊之，脉数七至，眠食尽废，不可救药矣。果及秋而茶毗。", "13381": "胡秋谷令爱，年甫笄，往岁患眩晕。孟英切其脉滑，作痰治，服一二剂未愈。更医谓虚，进以补药颇效，渠信为实。然今冬复病，径服补药半月后，眠食皆废，闻声惊惕，寒颤自汗，肢冷如冰。以为久虚欲脱，乞援于孟英，脉极细数，（阴已伤矣）目赤便秘，胸下痞塞如柈，力辨其非虚证。盖痰饮为患，乍补每若相安，具只眼者，始不为病所欺也。投以旋、赭、茹、贝、蛤壳、花粉、桑、栀、蒌、薤、连、枳等药，数服即安，而晕不能止。乃去赭、薤、蒌、枳，加元参、菊花、二至、三甲之类，服匝月始能起榻。（痰火为患，十人常居八九。而医书所载，皆治寒痰之法，十投而十不效。今得孟英大阐治热痰之法，真可谓独标精义矣。）", "13382": "曹稼梅令爱，患眩晕脘痛，筋掣吐酸，渴饮不饥，咽中如有炙脔。朱某与温胃药，病日剧。孟英诊脉弦滑，投茹、贝、萸、连、旋、赭、栀、楝、枳、郁、雪羹之药，（和肝、开郁、清痰）十余剂始愈。", "13383": "王瘦石令郎迟生，年未冠而体甚弱。夜梦中忽如魇如惊，肢摇目眩，虽多燃灯烛，总然黑暗，醒后纳食如常，月一二发，乃父以为忧而商于孟英。脉之弦细而涩，曰：真阴不足，肝胆火炎所致耳。令服神犀一月，病遂不发。继与西洋参、二地、二冬、三甲、黄连、阿胶、甘草、小麦、红枣，熬膏服之，竟刈其根。逾年完姻，癸丑已生子矣。", "13384": "秋初家慈猝仆于地，急延孟英诊之，脉浮弦以滑。用羚羊角、胆星、牡蛎、石菖蒲、丹参、茯苓、钩藤、桑叶、贝母、橘红、蒺藜等，以顺气蠲痰，息风降火而痊。癸卯春前数日，忽作欠伸而厥，孟英切脉微弱而弦，曰：病虽与前相似，而证则异矣。以高丽参、白术、何首乌、山茱萸、枸杞、桑椹、石斛、牛膝、蒺藜、橘红、牡蛎等，镇补摄纳以瘳。予谓此等证安危在呼吸之间，观前后卒仆数案，可见其辨证之神，虽古人不多让，况世俗之所谓医乎？家慈两次类中，予皆远出，微孟英吾将焉活，感铭五内，聊识数言。惟愿读是书者，体其济世之心，临证得能如是，将胥天下之沉疴而尽起矣。", "13385": "牙行王炳华室，夏患臂痛，孙某曰风也，服参、耆、归、芍数帖，臂稍愈而脘痛。孙曰寒也，加以附、桂，痛不止而渐觉痰多。孙曰肝肾不足也，重用熟地、枸杞，令其多服取效。不料愈服愈剧，渐至昏厥，孙尚以为药力之未到，病体之久虚。前方复为加重，甚而时时发厥，始请孟英诊之。脉沉而有弦滑且数之象，乃谓炳华曰：此由过投温补，引动肝风，煽其津液为痰，痰复乘风而上，此晕厥之由来也。余波则奔流经络，四肢因而抽搐；阳气尽逆于上，宜乎鼻塞面浮；浊气不能下达，是以便滞不饥。炳华曰：神见也。温补药服几三月矣，不知尚可救乎？孟英曰：勿疑吾药，犹有望焉。遂与大剂甘寒，息风化饮，佐以凉苦、泄热、清肝，厥果渐止，各恙递蠲。两月后，康复如常。予偶于旧书中检得无名氏钞本一册，所录多岐黄之言，内一条云：附桂回阳，在一二帖之间；万一误投，害亦立至。功过不掩，其性之毒烈，也概可见矣。奈世人不知药为治病而设，徒以贪生畏死之念，横于胸中，遂不暇顾及体之有病无病，病之在表在里，但闻温补之药，无不欣然乐从者，模棱之辈，趋竞存心，知其死于温补而无怨悔也，乃衣钵相传。不必察其体病脉证之千头万绪，仅以温补之品二十余味，相迭为用，即成一媚世之方。且托足《金匮》之门，摹拟肾气之变。盖知熟地之阴柔，可缚附桂之刚猛，误投不至即败，偶中又可邀功。包藏祸心，文奸饰诈，何异新莽比周公、子云学孔圣哉！人以其貌古人而口圣贤也，多深信而不疑。迨积薪既厚，突火顿燃，虽来烂额焦头之客，其不至于焚身者幸矣！较彼孟浪之徒，误投纯阳药，致人顷刻流血而死者，其罪当加十等。诛心之论，救世之言，知我罪我，不遑计焉。孟英见之，拜读千过，且曰：剿汉学以欺世，由来久矣。徐灵胎之论，无此透彻，可与退之原道文并峙。当考其姓字，于仲景先师庙内建护圣祠以礼之。予谓孟英如此称许，则其可传也奚疑。故附刊此案之后，以证王氏妇温补药服及三月，即所谓阴柔束缚刚猛之故，致人受其愚而不觉者，后之人可以鉴矣。", "13386": "孟英治其令弟季杰之簉室，因夜间未寐，侵晨饮酒解寒，适见人争谇，即觉心跳欲吐。家人疑其醉也，而欲吐不出，气即逆奔如喘，且肢麻手握，语言难出。又疑为急痧而欲刺之，孟英闻而视之，脉象弦驶，曰：夜坐阳升，饮醇则肝阳益浮，见人争谇，是惊则气更上逆，不可刺也。灌以苏合香丸一颗，下咽即瘥。（此当是痰闭气结之故。苏合丸，辛香通气，故愈。若是肝浮气逆，益以香窜之药，安能愈乎？）", "13387": "朱湘槎令郎留耕，忽于饱食后大吐而厥，冷汗息微。急延孟英视之，厥甫回而腹痛异常，口极苦渴，二便不行，脉来弦缓，乃痰滞而热伏厥阴，肝气无从疏泄也。投雪羹、栀、楝、元胡、苁蓉、萸、连、橘核、旋覆、竹茹、菔汁之药，一剂痛减，再服便行而愈。", "13388": "张伯虎纪纲李贵，患感数日，忽然昏厥，比沿途追求孟英往视，业已薄暮。主人谓自朝至此，一息奄奄，恐不及灌药矣，实不便屈诊。孟英曰：余既来，且视之。见其面色灰黯，戴眼口开，按其脉尚不绝。与菖蒲、胆星、竹茹、旋覆等为剂，和入童溺，调以牛黄至宝丹灌之，复杯而起。", "13389": "邵子受令壶，患吐血，肌肤枯涩，口渴脉虚大。孟英曰：气分之阴亏也，温补既非，滋填亦谬。以参、耆、二冬、知母、百合、萎蕤、石斛、桑叶、枇杷叶，投之而愈。用补亦要用得其宜，方能奏效。非一味蛮补，即能愈疾也。案中诸法，可以为法。", "13390": "郑某吐血盈碗，孟英脉之，右关洪滑，自汗口渴，稍一动摇，血即上溢。人皆虑其脱，意欲补之，孟英曰：如脱惟我是问。与白虎汤，加西洋参、大黄炭，一剂霍然。", "13391": "顾石甫宰娄县，患恙，医治日剧。解任归，求诊于孟英。脉见左寸如钩，曰：病不能复矣。许子双适至，闻而疑之，谓此证气逆血溢，腹胀囊肿，宛似上年康康侯之疾，若以外象观之，似较轻焉，胡彼可愈而此勿治耶？孟英曰：彼为邪气之壅塞，脉虽怪而搏指不挠，证实脉亦实也。此为真气之散漫，脉来瞥瞥如羹上肥，而左寸如钩，是心之真脏见矣。壅塞可以疏通，散漫不能收拾。客邪草木能攻，神病刀圭莫济。证虽相似，病判天渊，纵有神丹，终无裨也。季春果殁。", "13392": "孙氏女年将及笄，久患齿衄，多医莫疗。孟英诊曰：六脉缓滑，天癸将至耳。与丹参、生地、桃仁、牛膝、茯苓、白薇、滑石、茺蔚子，一剂知，数日愈。（亦治倒经之法。）寻即起汛，略无他患。", "13393": "锁某，弱冠吐血，杨医连进归脾汤，吐益甚。孟英视之，面有红光，脉形豁大，因问曰：足冷乎？探之果然。遂与六味地黄汤，送饭丸肉桂心一钱，复杯而愈。（此虚火上炎之证，归脾、中参、耆，性皆上升，故吐益甚。易以引火归原之法，斯愈矣。）", "13394": "孙执中于春前四日，忽患鼻衄如注，诸法莫塞。夤夜请孟英视之，脉弦而数，曰：冬暖气泄，天令不主闭藏。今晚雷声大振，人身应之，肝阳乃动，血亦随而上溢。不可以其体肥头汗，畏虚脱而进温补也。投以元参、生地、犀角、牡蛎、知母、生白芍、牛膝、茯苓、侧柏叶、童溺诸药，一剂知，二剂已。既而胁痛流乳，人皆异之，孟英与甘露饮加女贞、旱莲、龟板、鳖甲、牡蛎而瘳。", "13395": "一男子患便血，医投温补，血虽止而反泄泻浮肿。延及半年，孟英诊之，脉数舌绛，曰：此病原湿热，温补翻伤阴液。与芩、连、栀、芍、桑叶、丹皮、银花、石斛、楝实、冬瓜皮、鳖甲、鸡金等药，旬余而愈。", "13396": "丁未春，金朗然令堂，陡吐狂血，肢冷自汗。孟英切脉弦涩，察血紫黯，乃肝郁凝瘀也。证虽可愈，复发难瘳。与丹参、丹皮、茺蔚、旋覆、苓、栀、柏叶、郁金、海䖳之方，复杯果愈。然不能惩忿，逾二年复吐，竟不起。", "13397": "戊申元旦，陈秋槎参军，大便骤下黑血数升，（血为热迫而妄行。）继即大吐鲜红之血，而汗出神昏，（心无血养故神昏。）肢冷搐溺，（肝无血养故痉厥。）躁乱妄言。速孟英至，举家跪泣救命。察其脉左手如无，右弦软，（虚在阴分）按之数。（热在气分）以六十八岁之年，佥虑其脱，参汤煎就，将欲灌之。孟英急止勿服，曰：高年阴分久亏，肝血大去，而风阳陡动。殆由忿怒，兼服热药所致耳？其夫人云：日来颇有郁怒，热药则未服也。惟冬间久服姜枣汤，且饮都中药烧酒一瓶耳。孟英曰：是矣。以西洋参、犀角、生地、银花、绿豆、栀子、元参、茯苓、羚羊、茅根为剂，冲入热童溲灌之；外以烧铁淬醋，令吸其气；龙牡研粉扑汗；生附子捣贴涌泉穴，引纳浮阳。两服血止，左脉渐起，又加以龟板、鳖甲。（介以潜阳法。）服三帖，神气始清，各恙渐息，稍能啜粥，乃去犀、羚，加麦冬、天冬、女贞、旱莲投之，眠食日安。半月后，始解黑燥矢。两旬外，便溺之色皆正，与滋补药调痊。仍充抚辕巡捕，矍铄如常。秋间赴任绍兴，酉秋以他疾终。", "13398": "蒲艾田，年逾花甲，陡患鼻衄，诸法不能止。速孟英救之，面色黑黯而有红光，脉弦洪而芤。询知冬间广服助阳药，是热亢阴虚之证。与大剂犀角、元参、茅根、女贞、旱莲、石斛、茯苓、泽泻、天冬、知母，投匕而安。续予滋阴药，填补而康。", "13399": "沈悦亭令正齿衄，五日不止，去血已多，诸方不应。孟英脉之弦滑上溢，投犀角、泽兰、元参、旋覆、生地、花粉、茯苓、牛膝、桃仁、泽泻而安。既而询其经事，本月果已愆期。盖即逆行之候也。继用滋阴清热，乃渐康复。", "13400": "王子能参军令正，久患吐血，医不能愈。延孟英视之，脉弦滑而搏指，右手较甚，渴喜冷饮，米谷碍于下咽，小溲如沸，夜不成眠，久服滋阴，毫无寸效。孟英以苇茎汤合雪羹，加石膏、知母、花粉、枇杷叶、竹茹、旋覆、滑石、梨汁，大剂投三十剂而痊。继而参军旋省，患久积忧劳，真阴欲匮，竟难救药，寻果仙游。", "13401": "便血至三十余年，且已形瘦腰疼，嗽痰气逆，似宜温补之法矣。而嘉定沈酝书患此濒危，求孟英以决归程之及否。比按脉弦数，视舌苔黄，询溺短赤，曰：痔血也。殆误于温补矣。肯服吾药，旬日可瘳。酝书欣感，力排众论，径服其方，果不旬而愈。方用苇茎合白头翁汤，加枇杷叶、旋覆花、侧柏叶、藕，是肃肺、祛痰、清肝、凉血互用也。（徐灵胎批叶案云：便血无至十余年者，惟痔血则有之。今便血三十余年，不问可知为痔血矣。惟徐氏未尝出方，孟英此案足为程式。）", "13402": "孟英治其令弟季杰之簉室，怀妊患嗽，嗽则鼻衄如喷，憎寒乍热，口渴头疼，右脉洪数，授白虎汤合葱豉，投匕而瘳。或云时已隆冬，何以径投白虎？孟英曰，脉证如是，当用是剂。况今年自夏徂冬，亢旱不雨，寒虽外束，伏热蕴隆。此即麻杏甘膏之变法耳。", "13403": "关琴楚令孙少西，年三十四岁，素善饮。夏间已患著枕即嗽，讳而不言，家人未之知也。迨秋发热，呕吐腹痛。伊父母以为痧也，诸痧药遍投之，寻即气冲咳嗽，血涌如泉，不能稍动，动即气涌血溢。沈某但知其素禀阴亏，遽从滋补，服后益剧。迟孟英诊焉，脉弦洪而数，曰：虽属阴虚，但饮醇积热于内，暑火外侵，而加以治痧丹丸，无不香窜燥烈，诚如火益热矣。亟当清解客热。昔孙东宿治族侄明之一案，与此略同。必俟热退血止，再为滋养。知所先后，则近道矣。病家素畏凉药，而滋补又不应，遂求乩方服之。药甚离奇，并木鳖、麝香亦信而不疑。旬日后，血已吐尽，气逆如奔，不寐形消，汗多热壮。再乞诊于孟英，已不可救药矣。", "13404": "秀水怀某，三十五岁，自春前偶失血一日，嗣即频发，所吐渐多。延至季冬，聘余往视，左脉虚弦而数，右软大，气逆自汗，足冷面红，夜不成眠，食不甘味，音低神惫，时欲呕酸。此由心境不怡，肝多怫郁，而脉候如斯，有气散血竭之虞。坚欲返棹，然既邀余至，不得不勉写一方，聊慰其意。而病者强作解事，反以所疏舒郁之品为不然，执意要用五味、山萸、姜、桂之类。性情刚愎，此病之所由来。而执迷不悟，更为速死之道矣。既而其妻出诊，脉至弦细，顶癣头疼，心悸带多，不饥五热，亦是水亏木旺。退而谓其所亲曰：兹二人何郁之深耶？始知其无子欲买妾，而妻不许，遂以反目成病。及病成，而妻乃忧悔交萦，因亦致疾。此与曩视省垣顾金城之病同，因家拥巨资，故壮年即虑无子，亦可谓欲速不达矣。而愚妇不知大计，径为一妒字，以致溃败决裂。此时虽亟为置妾，亦无济矣。即以身殉，亦何益乎？录之以垂炯戒。", "13405": "一少年久患内热，鼻衄龈宣，溺赤便艰，睛红口渴，热象毕露。因阳萎经年，医者但知为阳虚之证，而不知有因热而萎之病，遂进温补，其热愈炽。父母不知，为之毕姻，少年大窘，求治于余。脉滑而数，曰：无伤也。与元参、丹皮、知、柏、薇、栀、石菖蒲、丝瓜络、沙参、蛤壳、竹茹，服六剂。来报昨夜忽然梦遗，余曰：此郁热泄而阳事通矣，已而果然。", "13406": "金某久患脘痛，按之漉漉有声，便闭溲赤，口渴苔黄，杳不知饥，绝粒五日。诸药下咽，倾吐无余。孟英察脉沉弱而弦，用海䖳、荸荠各四两，煮汤饮之，径不吐，痛亦大减。继以此汤煎高丽参、黄连、楝实、延胡、栀子、枳椇、石斛、竹茹、柿蒂等药，送服当归龙荟丸，旬日而安。续与春泽汤调补收绩。盖其人善饮，而嗜瓜果，以成疾也。此肝气挟停饮上逆也。缘素嗜瓜果，胃阳久伤，故于平肝涤饮之中，加参以扶胃气。", "13407": "单小园巡检，患右胁痛，医与温运药，病益甚。至于音瘖不能出声，仰卧不能反侧，坐起则气逆如奔，便溺不行，汤饮不进者，已三日矣。孟英诊其脉沉而弦，与旋覆、赭石、薤白、蒌仁、连、夏、茹、贝、枳实、紫菀，加雪羹服之，一剂知，数剂愈。", "13408": "某媪年六十余，患腰腿串痛，闻响声即两腿筋掣不可耐，日必二三十次。卧榻数载，诸药罔效。孟英察脉沉弦，苔腻便秘，亦广服温补而致病日剧也。与雪羹、羚、楝、胆星、橘络、竹沥、丝瓜络，吞礞石滚痰丸，及当归龙荟丸。四剂，大泻数十次，臭韧异常，筋掣即已，乃去二丸，加栀、连、羊霍。服六剂，即健饭而可扶掖以行矣。此人初病必系血虚不足以养肝，因妄服温补，以致积痰蕴热，胶固不开。孟英治法亦是救药误为多，愈后必继以滋养血液之药，方收全功。", "13409": "吴沄门，年逾花甲，素患脘痛。以为虚寒，辄服温补，久而益剧。孟英诊曰：肝火宜清。彼不之信，延之仲夏，形已消瘦，倏然浮肿，胁背刺痛，气逆不眠，心辣如焚，善嗔畏热，大便时泻，饮食下咽即吐。诸医束手，乃恳治于孟英，脉弦软而数。与竹茹、黄连、枇杷叶、知母、栀、楝、旋、赭等药，而吐止。饮食虽进，各恙未已，投大剂沙参、生地、龟板、鳖甲、女贞、旱莲、桑叶、丹皮、银花、茅根、茹、贝、知、柏、枇杷叶、菊花等药，出入为方。二三十剂后，周身发疥疮而肿渐消，右耳出黏稠脓水而泻止。此诸经之伏热，得以宣泄也。仍以此药，令其久服，迨秋始愈，冬间能出门矣。所现诸证，俱属痰热，与弦数之脉相合。但软则根柢不坚，初方乃急则治标之法，次方乃顾及根本，亦不易之次第也。", "13410": "陈春湖令郎子庄，体素弱，季秋患腹痛自汗，肢冷息微，咸谓元虚欲脱。孟英诊之，脉虽沉伏难寻，（痛脉多沉）而苔色黄腻，口干溺赤，当从证也。与连、朴、楝、栀、元胡、蚕砂、醒头草等药而康。次年患感，复误死于补。又夏酝泉延孟英视钱妪腹痛欲绝证，因见弦滑之脉，与当归龙荟丸而安。", "13411": "朱湘槎令媳，患小溲涩痛，医与渗利，反发热头疼，不饥口渴，夜不成眠。孟英诊之，脉细数，乃阴虚肝郁，化热生风，津液已烁，岂容再利。与白薇、栀子、金铃、知母、花粉、紫菀、麦冬、石斛、菊花，服之即愈。（愈后仍当以滋阴善后）其侄新泉之室，怀娠患痢，医投温燥止涩，腹痛甚而遍身发黄，饮食不思，孟英视之暑湿也。与芩、连、银花、茅根、桑叶、栀、楝、竹叶、茵陈、冬瓜皮而愈。", "13412": "吴酝香大令仲媳，汛愆而崩之后，脘痛发厥，自汗肢冷。孟英脉之，细而弦滑，口苦便涩。乃素体多痰，风阳内鼓。虽当崩后，病不在血。与旋、赭、羚、茹、枳、贝、薤、蒌、蛤壳为方。痛乃渐下，厥亦止，再加金铃、延胡、苁蓉、鼠矢，服之而愈。迨季冬因卒惊发狂，笑骂不避亲疏。孟英察脉，弦滑而数。与犀、羚、元参、丹皮、丹参、栀子、菖蒲、竹叶、鳖甲、竹沥，吞当归龙荟丸。息风阳以涤痰热，果数剂而安。然平时喜服补药，或有眩晕，不知为风痰内动，益疑为元气大虚。孟英尝谏阻之，而彼不能从。至次年季春，因伤感而狂证陡发，毁器登高，更甚于昔。孟英视之，苔黑大渴，与前方，加真珠、牛黄服之。苔色转黄，弦滑之脉略减，而狂莫可制，改以石膏、朱砂、铁落、菖蒲、青黛、知母、胆星、鳖甲、金铃、旋覆、元参、竹沥为大剂，送礞石滚痰丸，四服而平。继而脚气大发，腹痛便秘，上冲于心，肢冷汗出，昏晕欲厥，与连、楝、栀、茹、小麦、百合、旋、贝、元胡、乌药、雪羹、石英、鼠矢、黄柏、藕等药而安。凡药中用朱砂者，宜另研冲服，不可同入煎剂。", "13413": "谢谱香素属阴亏，情志抑郁，因远行持重而患咳逆，左胁刺痛，寸步难移，杳不知饥，卧难著枕。延孟英诊之，脉象弦细软数，苔腻痰黏，便难溲少，乃肾气不纳，肝气不舒，肺气不清，胃气不降。投以沙参、枇杷叶、茹、贝、旋、栀、龟板、鳖甲、丝瓜络、瓜冬子、青铅、白前、金铃、藕肉，而以熟地汤煎服。数剂而平，继渐滋填向愈。", "13414": "张月波令弟，陡患腹痛，适啖羊肉面条之后，医皆以为食滞，连进消导，痛甚而渴，得饮大吐，二便不行。又疑寒结，叠投燥热，其病益加，呻吟欲绝，已四日矣。孟英视之，脉弦数，苔干微黄，按腹不坚。以海䖳一斤，凫茈一斤，煎汤频灌，果不吐。令将余汤、煎栀、连、楝、斛、茹、芩、枇杷叶、知母、延胡、柿蒂、旋覆为剂，吞龙荟丸。投匕而溲行痛减，次日更衣而愈。", "13415": "谢谱香素体阴虚，忽患环跳穴痛，始而下及左腿，继而移于右腿，甚至两足转筋，上冲于腹间，或痛自乳起，下注于髀，日夜呼号，肢冷自汗，略难反侧。医见其血不华色，辄投补剂。迨仲春孟英自江西归，诊脉弦软微滑，畏热知饥，溲赤便坚，舌红不渴，乃阴虚而痰气滞于厥阴也。以苁蓉、鼠矢、竹茹、丝瓜络、橘核、茴香汤炒当归、吴萸汤炒黄连、川椒汤炒乌梅、延胡汤炒楝实、海䖳、凫茈为剂，一服即减，数啜而安。继与虎潜加秦艽而起。", "13416": "庄芝阶舍人令爱，孀居在室，陡患气冲欲厥，脘痛莫当，自服沉香、吴萸等药，病益剧，而呕吐发热，略有微寒。孟英按脉弦滑且数，苔色滑腻微黄，而渴喜冷饮，便秘溲热，眠食皆废。是伏痰内盛，肝逆上升，而兼吸受暑热也。予吴萸水炒黄连、枳实、竹茹、栝蒌、石膏，旋覆、赭石、知母、半夏、雪羹。服二剂，吐止痛减；五剂热退，而解犹不畅；旬日始得豁然。乃去石膏、知母、旋、赭，调之而愈。", "13417": "儒医何新之，素患脘痛，每日必吐水数缶始舒畅。吐后啖面食肉，如汤沃雪，第不能吃饭者十余年矣。季秋痛吐益甚，饮食不进，平肝通络，诸治不瘳。人极委顿，屈孟英视之。脉弦滑而软，曰：中虚停饮也。以六君去甘草，加桂枝、厚朴、牵牛，服之积饮果下，痛亦渐休，吐止餐加，精神稍振。乃去牵、朴，加附子、白芍、慧仁，与之遂愈，且能吃饭。病者谓既能吃饭，善后药不肯多服。迨仲冬中旬出门诊疾，骤与严寒，归即痛作，连服荔香散数日而逝。盖中气素虚者，不可专用香散之药也。", "13418": "许兰屿令正，自夏间半产后患感证，虽已治愈，而腰腹左痛时作。多医杂治，其痛日增，食减汛愆，卧床不起。黄某谓诸药无功，惟有肾气汤先固其根本。频服之痛益剧，且痛作之时，则带下如注。黄谓显系真火无权，附、桂复为加重，遂至痛无停晷，呻吟欲绝，陈春湖嘱迎孟英诊之。左关尺弦数无伦，形消舌赤，彻夜无眠，是肾阴大亏，肝阳极炽，营液耗夺，八脉交虚之证也。用龟板、乌鲗、苁蓉、枸杞、归身、楝实、竹茹、白薇、黄柏、丝瓜络、蒲桃干、藕为方，一剂知，数剂已。续加熟地、阿胶，调理月余，经行而愈。", "13419": "孙位申，陡患喉偏左痛，下及乳旁，神疲欲卧，动即凛寒，速孟英视之。脉弦细以软，苔薄白，口不渴，痰多且韧，溺赤不饥。是暑湿内伏而肝郁不舒，且阴分素亏，复伤劳倦也。昔人之清暑益气汤、藿香正气丸，皆是成法。设误投之，悉为戈戟。幸病家深信不疑，旁无掣肘。予射干、兜铃、蒌壳、通草、滑石、竹茹、丝瓜络、冬瓜子、枇杷叶、荷杆。极轻清之药一剂，即吐胶痰数碗，汗出周身，喉痛较松，凛寒亦罢，而身痛微热，苔色转黄。去射干、兜铃，加栀子、豆卷服之，热退痛减。再去滑石、豆卷，加石斛、沙参、野蔷薇露投之，知饥啜粥，诸恙悉安，嗣用养阴充液而愈。", "13420": "乙巳秋，拙荆年三十二岁，忽患四肢酸痛，早晚尤甚。初谓其平素劳瘁所致，己而日剧。延医治之，以为痛风，服药不效，单方针灸，无不遍试，至冬令渐难行走。次年春，山阴俞某作虚风治，用参、术、熟地、桂、附等药。（文）恐方热，减去附子，服十余剂，遂手足拘挛，不能屈伸，日夜号痛，如受炮烙，眠食皆废，痰韧如石，皮肤燥裂，鳞起如松。至夏更加两腋肿核，阴户疮糜，痛不可支。业师顾听泉先生，荆人之舅氏也，求其援手。云两脉弦数，舌绛无津，况汛断半年，破䐃脱肉。《经》言九候虽调，犹属不治，危殆若此，不能过夏至也。因请孟英先生救之，先生来视曰：营分素亏，阴液尽烁，幸病在经络，犹可图治，第恐成废耳。授以西洋参、元参、生地、天冬、麦冬、知母、花粉、银花、甘草、葳蕤、石斛、丝瓜络等药，出入为剂，用竹沥、梨蔗诸汁和服。酷暑之时，则加生石膏、西瓜汁。（文）遵方恪服，计烧沥之竹四五十竿，榨浆之蔗七八十枝，捣汁之梨五六十斤，绞汁之瓜三四十枚，果痛渐以减，疮渐以平，肤渐以蜕，食渐以增。仍溉以凉润生津，兼佐熟地、枸杞、归身之类。服至两载，月事乃行。又半年，肌肉渐充，手足亦能舒展，闻者无不惊异。今则形神如昔，步履虽未能如常，已可坐轿出门。是证也，不遇先生，必致夭枉。既铭诸心，复录之以为后人鉴。钱塘张文辉月卿谨识。（病人久卧床蓐，则腰臀磨穿，《内经》谓之破䐃，俗呼㾬疮是也。最为难治。孟英令人于初起时，即用广东羊皮金贴之甚效。然此等隹案，前未收辑。今张君闻有三编之辑，附录于此，益信遗珠不少也。）", "13421": "许兰屿令正，素属阴亏，舌常脱液。季秋患脘下疼胀，得食愈甚，映及胁背，宛如针刺，稍合眼则心掣动而惊寤。自按痛处，则涌水苦辣，渴不欲饮，溲少神疲。自疑停食，服楂曲而益剧。孟英视脉弦软，曰：此停饮也。饮停则液不能上，故口渴。而饮，即水也。内有停水，故不喜饮。其舌上脱液，虽属阴虚，亦由饮隔。寐即心掣者，水凌火也。得食痛加者，遏其流也。以苓、泽、橘、半、旋、蛤、连、䖳，加生姜衣投之，溲行得睡。惟晚食则脘下犹疼，疼即心热如火，且面赤头痛，腿冷腰酸，必俟脘间食下，则诸恙皆平。孟英曰：此停饮虽蠲，而肝火升也，宜参潜养为治矣。改授沙参、苁、归、竹茹、楝、柏、石决明、丝瓜络、姜汁炒栀子，少佐生黄连，服之遂愈。", "13422": "屠某患梦遗，久治不愈。耳出脓水，目泪难开，肩胁胸背酸疼，微有寒热，食减神疲。孟英察脉左弦数，右虚软，以三才封髓加龙、牡、黄耆、桑、丹、栀、菊，旬日而瘳。", "13423": "殳某，久患寒热，精遗自汗，能食神疲，肌肉渐瘦，诣孟英诊之，脉大微弦，予黄耆建中加参、归、龙、牡而瘥。", "13424": "沈东屏，年愈八秩，患腹胀便秘。孟英诊曰：耄年脉实，天异独厚，证属阳结，法宜清火。与四洋参、石膏、白芍、知母、花粉、桑皮、杏仁、橘皮、枳壳、甘草，送更衣丸。四剂而愈。设投别药，势必迁延而败。人亦谓其天年之得尽，断不料其药治之误也。后四年始殁。夏间汪湘筠明府，因食肉病胀，医谓老年气弱火衰，辄投温补，直至腹如抱瓮，始延孟英视之。弥留已极，不可救药矣。", "13425": "张孟皋少府令堂，年逾古稀，患气逆殿屎，躁烦不寐。孟英切脉滑实，且便秘面赤，舌绛痰多，以承气汤下之霍然。逾年以他疾终。", "13426": "毕方来室，患痰嗽碍眠。医与补摄，而至涕泪全无，耳闭不饥，二便涩滞，干嗽无痰，气逆自汗。孟英切脉，右寸沉滑，左手细数而弦。乃高年阴亏，温邪在肺，未经清化，率为补药所锢。宜开其痹而通其胃。与蒌、薤、紫菀、兜铃、杏、贝、冬瓜子、甘、桔、旋、茹之剂而安。逾二年，以他疾终。（亦少善后之法。）", "13427": "运粮千总马香谷，患溺秘欲死。所亲赵春山司马，延孟英视之，脉坚体厚，口渴苔黄。投知、柏、栀、楝、犀、菀、蒌、茹之药，送当归龙荟丸而瘳，竟不复发。", "13428": "阮范书明府令正，患腹痛欲厥。医见其体甚弱也，与镇逆通补之法，而势日甚。孟英察脉弦数左溢，是因忿怒而肝阳勃升也。便秘不饥，口苦而渴，与雪羹、栀、楝、旋、绛、元胡、丹皮、茹、贝，下左金丸而愈。逾年以他疾殁于任所。", "13429": "吴薇容太史令堂，患痰嗽喘逆，便秘不眠，微热不饥，口干畏热。年逾六旬，多药勿痊。孟英切其脉，右寸关弦滑而浮，左关尺细软无神。是阴虚于下，痰实于上，微兼客热也。攻补皆难偏任，与茹、贝、旋、斛、浮石、芦根、冬瓜子、枇杷叶、杏仁、花粉为剂，而以熟地泡汤煎服。则浊药轻投，清上滋下，是一举两全之策也。投匕果应。再服而大便行，渐次调养获瘳。戌春患感证，比孟英自江西归，已不能治矣。", "13430": "海盐任斐庭，馆于关琴楚家。季夏患感，黄某闻其身热而时有微寒也，进以姜、萸、柴、枣等药。数帖热愈壮，而二便不行。更医连用渗利之剂，初服溲略通，既而益秘。居停以为忧，始延孟英视焉。证交十四日，骨瘦如柴，脉弦细而涩，舌色光紫，满布白糜，夜不成眠，渴不多饮，粒米不进，少腹拒按，势将喘逆。虽属下证，而形脉如斯，法难直授。先令取大田螺一枚，（外治法甚妥。）鲜车前草一握，大蒜六瓣，共捣烂，加麝香少许，罨脐下水分穴。方以元参、紫菀、栀子、知母、花粉、海䖳、凫茈，苁蓉、牛膝、天冬为剂，加鲜地黄汁服之。其夜小溲即行，气平略寐。又两剂，大解始下，退热而渐进稀糜，乃去雪羹、栀、菀、苁蓉、膝、地黄汁，加西洋参、麦冬、石斛、干生地、竹茹、银花等药。又服十余剂，凡三解黑矢，而舌色复于红润，眠食渐安而起矣。", "13431": "高氏妇，因戒鸦片而服外洋丸药，诸无所苦，惟便秘不通。医治两月，迄不能下，且仍安谷。而面赤龈胀欲挑，每以银针嵌入齿缝，而拔出之时，银色已如煤黑。孟英诊脉滑数，予犀角、石膏、硝、黄、升麻、蜣螂为剂，（解毒妙品。）和以鲜银花汁一杯。服后夜间登圊三四行，而病去及半，再予清解化毒而痊。", "13432": "屠小苏令正，自乳经停，泛泛欲吐，或疑为妊。所亲高啸琴进以养阴之药，渐致时有微热，脘闷不饥，气逆嗽痰，卧难著枕，二便秘涩，耳闭汗频。孟英脉之，虚软而涩，曰：根蒂素亏，经停乳少，血之不足；泛泛欲呕，肝乘于胃；率投滋腻，窒滞不行；略受风邪，无从解散，气机痹塞，九窍不和。先以葱、豉、通草、射干、兜铃、杏仁、蒌壳、枇杷叶、白蔻开上，两剂热退。次用小陷胸合雪羹，加竹茹、旋覆、白前、紫菀宣中，三剂便行安谷。继予冬虫夏草、苁蓉、当归、枸杞、麦冬、紫石英、楝实、熟地、牛膝滋下而瘳。", "13433": "金愿谷中翰，患便秘，广服润剂，粪黑而坚如弹丸，必旬余始一更衣，极其艰涩。孟英诊脉迟软，舌润不渴，小溲甚多。乃久患痹证，坐卧不安，健运迂迟。法宜补气，俾液濡布。所谓中气足，则便溺如常矣。非凉润药所能治也。予大剂参、术、橘、半，加旋覆花以旋转中枢，鸡䏶胵以宣通大肠之气，鸡不溺而粪易下也。更仿《金匮》谷实之例，佐血余、苁蓉，俾为流通府气之先导。如法服之，数日即解，且较畅润。至三十剂，其病若失。", "13434": "王子庵令堂，年已古稀。患便秘不舒，时欲挐挣，汗出头晕。医谓其肝气素滞，辄与麻仁丸等药，其势孔亟。伊婿陈载陶屈孟英诊之，脉虚弦而弱，是虚风秘结。予人参、苁蓉、当归、柏子仁、冬虫夏草、白芍、枸杞、楝实、胡桃仁，数帖而痊。次年秋患脘痞疼胀，医者率进温补香燥之药，驯致形消舌绛，气结津枯，始延孟英视之，不及救矣。", "13435": "管君芝山，拉余治其表嫂吴媪，年五十五岁，上年仲夏患癃二十余日，愈后小溲迄未通畅，已成锢疾。今秋分后，溺秘不行，医疗旬余，温如姜、桂、乌药，凉如栀、芩、黄柏，利如木通、滑石，皆不效。甚有用益智等以涩之者，渐至腰腹皆胀而拒按，胸高腿肿，不饥不食，大便不通，小便略滴几点，热痛异常，舌绛无津，渴喜沸饮，而不敢多啜，以增胀满，呻吟待毙。脉软而微，乃阴虚气化无权也。以沙参、熟地、连、蒌、芩、泽、麦冬、紫菀、牛膝、车前，加附子一钱、桂心五分，煎成冷服。一周时，溺出桶许，而大便随行，进粥得眠，口苦而喜凉饮。即去附子、桂、连、蒌、菀、膝，加知、柏、芍药、砂仁，数帖而起。缘境窘不复调理，锢疾闻犹存也。", "13436": "孟英邃于医学，从不侈谈脉理，足以见其欿然不自足也。而脉理之最不易切者，莫如妊娠。予闻孟英于乙未春，诊黄履吉室人之脉，曰：妊也。是月天癸犹来，人皆不以为然。次月仍转，但不多耳。复邀孟英诊之，曰：果妊也。汛不断者，荫胎之血有余耳。逾月汛复行，觉更少矣，人犹以为妄也。四月后经始停，娠亦显，娩如期，人始服其见老。", "13437": "表弟胡寿者室，偶有小忿，经事涩少，腰腹微胀，自以为怒气所滞也。延孟英诊之，切其脉，曰：怀麟矣。初犹疑之，既而始信，卯春果弄璋。", "13438": "癸秋，孟英治石诵义室，脘痛甫愈，适汛逾期，即曰娠矣。既而果日形著，其指下之神妙如此。娠孕之脉，最为难凭。有初娠即现于脉者，有三四月始现于脉者，有始终不现于脉者，此与凭脉断证，有时可凭，有时不足凭，同一至理。予尝以此质之孟英。孟英也以为然。可见真学问人，必不恃虚言以眩世也。", "13439": "金畹香令媳，半产后，营分不摄，淋漓数月，治之勿瘳。孟英于夏季诊视，两尺皆浮，左寸关弦。与三甲、二至、二地、蒿、薇、柏叶、螵蛸、黄柏为方，服之渐愈。仲秋诊其脉，即断受孕。渠谓怀娠必无病矣，而不知病久初痊，正须培养，虽即受孕，涵养无权，果至仲冬而胎堕矣。肝主疏泄，肾主闭藏，两尺浮而不沉，是肾失其闭藏之职矣；左寸关弦，是肝木太过，独行其疏泄之权矣。填补肾阴，即以涵养肝木。加黄柏之苦以坚之。螵蛸之涩以固之，用药如法，故收效倍捷。", "13440": "《仁术志》者，海丰张君柳吟所题孟英之医案也，吾师赵菊斋先生，暨庄舍人芝阶为之序。余以未与其事，深以为歉！秋间偶过孟英，适有陈姓者牵羊来谢。孟英颇疑之，其人曰：三月间次媳患时感，而气逆不能眠，医皆畏却，特延君诊。甫按脉云甚滑疾，是为娠象，用药必须顾及。此时次媳于去秋娩后，月事尚未一行，君为此言，阖家未尝不窃笑也。迨疾渐平，哺儿之乳亦不觉少，虽自问亦断断非孕。至六月间腹渐胀，方谓有病，不料昨日倏产一孙，举家敬服高明，故来致谢耳。孟英因谓余云：昨诊魏子恒之室亦妊也，诸医作虚损治。脉虽虚微软数，而滑象仍形。病家深不以吾言为然者，缘病人之女兄二人，皆死于虚劳也。然其伯仲之证，吾皆诊焉。今已十余年矣，犹忆伯字于关氏，未嫁而卒。证非不治，亦为药误。病中阅吾方案，极为折服，且曰：先生来暮，侬不能起矣。前此延致诸名家，徒曰虚证宜补，而不治其所以虚，方则群聚补药，必以地黄为之冠，虽有参耆，亦列于后。即使用药不乖，而阳生阴长，气为血帅之旨，尚未分晓，况其他乎？吾闻而愕然，何以闺中女子，亦解谈医，细询始知为乾隆间名医吴颖昭先生之女孙也，尤为惋惜。仲适于陈少帘少府，的系损证，若季者因其家怀先入之见，遂致医人迎合误事，岂不可叹！迨秋仲果闻魏氏分娩母子皆亡，方叹孟英之卓见为不可及也。爰采秋冬诸案之治法不同于寻常者，而续成一卷云。", "13441": "孙位申室，平昔阴虚肝滞，痛胀少餐，暮热形消，咽疼喉癣，不孕育者九年矣。往岁汛愆，人皆谓将不起，而孟英切其脉尚不细，肤犹淖泽，许筹带病延年之策，果月事仍行，而诸恙皆缓，且能作劳。惟饭食日不过合米，今秋延孟英往诊云：经自三月至今未转，一切旧恙，弥见其增。君术虽仁，恐难再延其算矣。及举脉弦滑左甚，遽曰：岂仅可延其算哉，且有熊罴入梦矣。其家闻之骇异，迨季冬果得一子，颇快而健。", "13442": "胎前产后，疑似极多，号曰专科，尚难措手。陈肖岩孝廉媳，屠仲如之女也。汛愆一度，次月仍行，方疑其病也。孟英诊曰：尺虽小弱，来去缓和，是娠也。继而果然。仲如令弟子缘之室，轻事稍迟，孟英偶诊，亦以孕断，寻验。甫三月，患胎漏，适孟英丁内艰，遂不克保而堕。堕后恶露虽行，而寒热头疼，时或自汗，且觉冷自心中出。医谓类疟，与温化之药，病日甚。交八日，孟英始出门，即延诊之。脉来沉实而数，舌色紫黯，乃瘀血为患耳。予桃仁、泽兰、山楂、茺蔚、旋覆、红花、丹参、通草、琥珀、蛤壳、丝瓜络之剂，服后腹大痛，下瘀血如肺者一枚。次日诸恙较减，乳汁大流，再以前方去通草，加麦、柏投之。服后腹仍痛，复下瘀块累累，而诸恙若失。或问先生，尝言产后腹无痛苦者，不可妄行其血。此证恶露已行，腹无疼胀，何以断为瘀阻，而再行其血耶？孟英曰：正产如瓜熟蒂落，诸经荫胎之血，贯串流通，苟有瘀停，必形痛胀。堕胎如痈疡未熟，强挤其脓，尚有未化之根柈，不能一齐尽出，所以胎虽堕而诸经荫胎之血，萃而未涣，浅者虽出，深者尚留。况是血旺之躯，加以温升之药，挽其顺流之路，窒其欲出之机，未到腹中，胀疼奚作？吾以循经通络、宣气行瘀之法，导使下行，故出路始通，而后腹痛瘀来。然必有脉可征，非谓凡属堕胎皆有是证也。孟英诸案，大抵救温补之失，故寒凉为多。然斟酌尽善，不以苦寒伤生气，则非他人所能学步也。通血之剂，亦清灵无弊。", "13443": "张氏妇，先于四月间患呕吐。医以为寒，叠进姜、萸之药，致血溢自汗。丐孟英诊之，脉甚滑，按之不绝，舌光无苔，曰：孕也。询其经事，果愆两度。予沙参、枇杷叶、生地、芦根、连、苏、旋、斛之剂而安，仲冬举一男。胎前即患痰嗽，娩后招专科治之，服四物汤增损多剂，而气逆碍眠，嗽则汗出，便溏遗溺，口渴不饥。再乞援于孟英，脉洪大，按之虚软。授沙参、石英、黄耆、薏仁、甘草、牡蛎、石斛、茯苓、小麦、红枣、冬虫夏草之方，两帖而汗收安谷，四帖而渴减便坚，旬余遂愈。", "13444": "冯益三令正，上年春汛偶愆，颇露虚象。群贤咸以为损，余诊为孕，秋季果举一男。至丁巳春初，产逾三月，既不自乳，汛亦未行，偶感客邪，医疗半月，渐至不饥不食，气自少腹上冲，似有聚瘕，呕恶腹痛，面黄形瘦，溲热便溏，口渴带多，面浮咳逆，佥云己成蓐损，复延余诊，脉滑而弦，遂以孕断。与沙参、苏叶、桑皮、冬瓜皮、黄芩、枳壳、石菖蒲、白薇、橘核、楝实，煎香连丸。三服霍然。后闻六月中旬，产一女甚快。", "13445": "赤山埠李氏女，素禀怯弱，春间汛事不行，胁腹聚气如瘕，减餐肌削，屡服温通之药。至孟秋加以微寒壮热，医仍作经闭治，势濒于危。乃母托伊表兄林豫堂措办后事，豫堂特请孟英一诊以决之。孟英切其脉时，壮热烙指，汗出如雨，其汗珠落于脉枕上，微有粉红色，乃曰：虚损是其本也。今暑热炽盛，先当治其客邪，庶可希冀。（急则治标之法）疏白虎汤，加西洋参、元参、竹叶、荷杆、桑叶。及何医至，一筹莫展，闻孟英主白虎汤，乃谓其母曰：危险至此，尚可服石膏乎？且《本草》于石膏条下致戒云：血虚胃弱者禁用，岂彼未之知也？豫堂毅然曰：我主药，与其束手待毙，盍从孟英死里求生之路耶？遂服二帖，热果退，汗渐收。改用甘凉清余热，日以向安。继与调气养营阴，宿瘕亦消。培补至仲冬，汛至而痊。次年适孙𢵡伯之弟。", "13446": "赵听樵室，高若舟之妹也。去冬偶患脘痛，黄某治之，渐增头疼眩晕，气逆呕吐，痰多不寐，（脘痛而过投香燥，亦能致此证，况误投补乎？）便溏不食，经事不行。始谓其虚，三月后又疑为娠，诸药遍试，病日以进。若舟延孟英脉之，左弦而数，右滑以驶，曰：病药耳，旬余可瘳。赵疑大病小视，不服其方。越半月，病者颈软头难举，医谓天柱已倒，势无望矣。若舟闻之，复恳援于孟英，疏方仍是前诊之法。赵问此病，诸医束手，大剂补药，尚无寸效，而君两次用药，皆极清淡，虽分两颇重，亦焉能有济乎？孟英曰：子何愚耶！药惟对证，乃克愈病，病未去而补之，是助桀也，病日加而补益峻，是速死也。原彼初意，非欲以药杀人。总缘医理未明，世故先熟，不须辨证，补可媚人，病家虽死不怨，医者至老无闻，一唱百和，孰能挽此颓风？令壶体质虽丰，而阴虚有素，是以木少水涵，肝阳偏盛，上侮于胃，则为脘痛。斯时投以酸苦泄肝、甘凉养胃，（叶氏独得之秘。）数日而愈矣。乃温补妄施，油添火上，肺津胃液，灼烁无余，怒木直升，枢机窒塞，水饮入胃，凝结为痰。虽见证多端，皆气失下降，岂可指眠食废以为劳，月汛爽而为妊耶？予以大剂轻淡之品，肃清气道，俾一身治节之令，肝胆逆升之火，胃府逗遛之浊，枢机郁遏之热，水饮凝滞之痰，咸得下趋，自可向愈。不必矫枉过正，而妄以硝黄伤正气。所谓药贵对证，而重病有轻取之法。非敢藐视人命，故将疲药塞责也。赵极感悟，投匕即效，逾旬果安。又一月经至，嗣与滋养，康复如常。越二载又病，复惑于黄某，而孟英之功尽堕，惜哉！", "13447": "里中张君雪沂令正，三十七岁。于乙巳年患经行腹痛，医进胶艾汤多剂，痛乃日盛，而加以呕吐。迄今十载，诸药备尝，迩年经至益频，痛势益剧，满床乱滚，声彻比邻。乞余诊之，脉弦滑而数，曰：巅痛口渴乎？带多腰痛乎？汛色紫黑乎？病者惊以为神，惨容为之一展。余谓雪沂曰：此证不但温燥腻补不可用，即四物汤亦在禁例，宜乎遍访女科，而竟无一效也。与芩、连、栀、胆、茹、柏、蒿、薇、乌鲗、茅根、藕为剂。服至下月经行，即不吐，痛亦大减。此等药服逾半载，各恙悉蠲。", "13448": "钱塘张君篪伯令郎韵梅茂才之室，自去年夏间娩后，虽不自乳，经亦未行，方疑其劳也。四月间患感，医进升散药，遂腹膨气逆，肢痉欲厥，或又疑其娠也。延余诊之，脉弦巅痛，乃营虚肝郁，微挟客邪，误投提表耳。以清解轻宣之品，数剂而愈。继参养荣，月事亦至。人皆诧为神治，其实非大病也。", "13449": "管君幼斋令正，汛停七月，至仲秋经行不多，腹乃微胀，继则胸闷不饥，身有寒热。吕某以桂枝、黄连等药进，而痞闷转加，二便不行，口糜而渴，得饮即吐，夜不能寐，五内如焚。余诊之，脉弦软而细，面赤足冷，神惫不支，是营阴素亏，气机多郁，郁久生热。辛燥忌投，授沙参、蒌、薤、栀、茹、旋、菀、冬瓜子、枇杷叶。二剂，而燥矢行，胸腹舒知饥，吐止，继以宣养而瘥。其汛停良由血不足，非有血不行而阻也。", "13450": "王西翁令孙芝生茂才室，久患汛行太速，头痛神疲，形瘦内烦，渴喜热饮，纳食滞膈，络胀少眠，脉至软滑虚弦，腿酸而有赤块，甚痛。乃阴亏，水不涵木，风阳内炽，气郁痰凝。议宣养清潜互用法。沙参六钱，鳖甲八钱，首乌三钱，茯苓、菊花各二钱，栀炭、竹茹、桑叶各一钱五分，白薇、黄柏、丝瓜络各一钱，以藕二两、十大功劳一两煮汤煎药。外用葱白杵烂，蜜调涂腿上赤块。仲冬复视，烦减能眠，汛行较缓，头疼腿块均已渐瘥。乃与通补柔潜之剂，后信来，服之甚效。", "13451": "张宝商室，患凛寒乍热，咳逆，形消面赤，少餐经迟，眩晕。医投补剂，盗汗带频，咸谓不能过春矣。余诊之，脉弦滑而数。本非虚劳，无须补药。乃肝阳内盛，搏液成痰，阻塞气机，法宜清展。以元参、丹参、紫菀、白薇、青蒿、黄柏、石菖蒲、菊花、竹茹、竹叶为方，每服送当归龙荟丸一分。二十剂遂健如初。", "13452": "枫泾程笙伯令正，半产之后，汛事先期，淋漓不断，时见痛胀，龈衄减餐，苦渴苔黄，脉弦而数。频服补剂，久不能瘳。余投沙参、龟板、制香附、丝瓜络、茹、陈、菖蒲、蒿、栀、薇、柏、藕，十余帖次，月经即调。复来求诊，与以柔养善其后。", "13453": "管授青翁季郎蓉舫之室，初冬患寒热，耳聋胸闷，便秘，带下如注，呕渴不眠，粒米不沾者旬余矣，人皆危之。余按脉弦数，舌绛无苔，气逆面红，自求速死。此肝郁深沉，木火内烁，耗津阻气，出入无权。小柴胡汤、逍遥散，皆貌合而神离，误施必然决裂。此辨证用药之所以难也。幸其乔梓深信，遂以小陷胸，加菖、茹、旋覆、栀、芩，芦根汤煎服。一帖，胸渐舒，气渐平。再服稍寐，三服呕止进粥。五剂便行溺畅，寒热亦休，苔布知饥，始改柔养而痊。", "13454": "娼女荣瑛，就诊于余。自述本良家子，十四岁而天癸至，二十二岁而适人。二十五岁初产，但觉腰腹微酸，子即堕地。三十二岁，再产亦尔。兹又嫁二夫，向不自乳，而产育渐频，分娩渐慢。今春诞子为第十胎，腹痛逾四时而生。在他人犹以为极快，而我已觉渐徐。且年虽五十，天癸不衰，锢疾全无，向不服药。素有微带，近年全无。惟每日吐痰，别无他苦。恐此后有难产之虞，求为设法。余闻而讶之。其貌虽不甚都，而粉黛不施，风致嫣然，肌肤尚似三十许人，真尤物也，始信鸡皮三少之说为不诬。按脉六部皆缓滑而长，左寸关带弦数，是聪明有寿之征。故年愈长而气愈固，是以分娩渐慢也。向有带而近有痰，以左寸关合之，火搏其液，而不下趋也。嘱以六君子加减为常服之方。设再孕，至七八月，以束胎饮频服，可期易娩。渠闻之忻然，受方而去。录之以见赋体之奇。", "13455": "郎氏妇，崩后淋带，五内如焚，溲热口干，不饥，脘闷腰疼，肌削，卧榻呻吟，头晕耳鸣，夜不能寐，脉来细数，少腹不舒，滋补杂投，皆不见效。余以菖蒲、沙参、斛、柏、薇、芩、蛤壳、冬瓜子、藕、十大功劳，先为清展。服五帖，热退，渴解，脘舒安谷，且能起坐，夜亦能眠，其气机已调畅矣。参入潜阳养血而痊。", "13456": "满洲少妇，怀娠漏血，医投补药漏如故。间或不漏则吐血。延逾二载，腹中渐动，孕已无疑。然血久溢于上下，甚至纳食即吐，多医不能治。孟英诊之，脉滑数有力，是气实而血热也。证不属虚，补药反能助病，愈补愈漏。胎无血荫而不长，其所以不堕者，气分坚实耳。与大剂清营药，血溢遂止。而稀沫频吐，得饮即呕，口渴心忡，气短似促，乃用西洋参、麦冬、知母、石斛、枇杷叶、竹茹、柿蒂、生白芍、木瓜，重加乌梅投之，复杯即安，（清肺柔肝，益气生津，与证针锋相对。）次日能吃饭矣。", "13457": "朱砥斋司李之夫人，屡患半产，每怀妊，服保胎药，卒无效。今秋受孕后病嗽，孟英视之，尽屏温补，纯与清肺。或诘其故，曰：胎之不固，或由元气之弱者，宜补正；或由病气之侵者，宜治病。今右寸脉滑大搏指，吾治其病，正所以保其胎。苟不知其所以然，而徒以俗尚保胎之药投之，则肺气愈壅，咳逆愈盛，震动胞系，其胎必堕矣。朱极钦佩，服之良效。次年夏，诞子甚茁壮。通达之论，凡病俱宜如此看。", "13458": "李华甫继室，娠三月而崩。孟英按脉弦洪而数，与大剂生地、银花、茅根、柏叶、青蒿、白薇、黄芩、续断、驴皮胶、藕节、胎发灰、海螵蛸而安。奈不能安佚，越数日胎堕复崩，孟英于前方去后六味，加犀角、竹茹、元参为治。或谓胎前宜凉，产后则否，乃招专科暨萧山竹林寺僧治之。咸用温药，且热暴崩宜补。服药数剂，虚象日著，时时汗出昏晕，畏闻人声，懒言息微，不食不眠，间有呃忒，崩仍不止，皆束手待弊矣。复邀孟英视之，曰：此执死书以治活病也。夫血因热而崩，胎因崩而堕，岂胎堕之后，热即化为寒乎？（妙语解颐。）参、术、姜、桂、棕灰、五味之类，温补酸涩，既助其热，血益奔流，又窒其气，津亦潜消，致现以上诸证。脉或不知，而苔黄黑燥，岂不见乎？因与犀角、石膏、元参、知母、花粉、竹沥、麦冬、银花、栀子、石斛、旋覆、青蒿、白薇等大剂投之，神气渐清。旬日后，各恙始平。继去犀角，加生地，服两月全愈。", "13459": "徐氏妇怀妊患痢，医投温补，胸腹痛极，昏厥，咽糜，水饮碍下。孟英诊之，脉洪数，舌绛燥。亟吹锡类散，灌以犀角、元参、海䖳、茹、贝、栀、菀、知、斛、豆根、射干、银花、楝实诸药。胎下已朽，咽腹之疾随愈。续用甘凉清热存津调之。", "13460": "汪氏妇，自孟秋患痢之后，大解溏泄未愈，已而怀娠，恐其堕也，投补不辍。延至仲冬，两目赤障满遮，气逆碍眠，脘疼拒按，痰嗽不食，苦渴无溺。屈孟英诊之，脉甚滑数，曰：此温补所酿之疾也。夫秋间滞下，原属暑湿热为病。既失清解，逗留而为溏泄。受孕以来，业经四月，虑其堕而补益峻，将肺胃下行之令，皆挽以逆升，是以胸次堵塞而疼，喘嗽不能卧。又恐其上喘下泄而脱也，补之愈力，治节尽废，溲闭不饥，浊气壅至清窍，两目之所以蒙障而瞽也。与沙参、蛤壳、枇杷叶、冬瓜子、海石、旋覆、苏子、杏仁、黄连、枳实、海䖳、黄芩、栀子，重加贝母。服二剂，即知饥下榻，目能睹物矣。论极透快，说尽庸医之弊。", "13461": "叶承恩室，怀妊患感，昏谵不眠，善呕便秘，汗出不解，脉涩口干。乃营阴素亏，邪热内炽。以元参、石膏、知、芩、茹、贝、银花、枇杷、薇、栀、楝、斛，投数帖而愈。", "13462": "夏氏妇怀娠患感，医投温散，渐至气冲不寐，时欲痉厥，脘闷呻吟，渴难受饮。所亲张养之，延孟英诊之，脉滑数而溢。与小陷胸，加旋、薤、石膏、知、栀、茹、杏、腹皮、苏子、竹沥、海䖳大剂，投旬日而愈。设用轻浅之方，焉克有济耶？", "13463": "朱次膺令正，姅后偶有微寒微热，医与解散药一剂，遂神疲自汗，不食不眠，泛泛欲呕，时时欲晕，肢麻且软，气欲上冲，舌赤微苔，溺频脘痛，便溏不畅，目不欲张，心悸懒言，欲噫不达。孟英察其脉，虚弦软数，曰：此阴虚素亏，忧愁劳瘁之余，血从下夺，八脉交虚，正所谓阳维为病苦寒热，阴维为病苦心痛也。岂可以有寒热而即从疟治哉？授以龟板、鹿角霜、当归、枸杞、白薇、紫石英、甘草、大枣、小麦、牡蛎，数剂而安。嗣与熟地、枣仁、当归、杞子、麦冬、楝实、苡仁、黄连，壮水和肝而愈。", "13464": "朱逵士令正，怀妊八月，脘痛便溏，跗肿腰疼，频吐绿水，温补不效。孟英诊之，脉软而弦，舌绛无液，口干少寐，形瘦神疲。木土相乘，阴液大耗。虽宜培养，燥烈禁施。以参、连、归、斛、杜仲、灵脾、冬虫夏草、柏、橘、茹、英为剂，果各恙递安，脘舒泻止。加以熟地，舌渐生津而愈。", "13465": "钱希敏室，坐草二日，既未分娩，忽患小便不通，势甚亟，乃速孟英视之。脉至滑数，睛赤口干，以为热结膀胱，气不化达。予车前子、滑石、血余、栝蒌、知母、栀子、牛膝、紫菀、紫草为大剂投之，是通溺催生互用之法。服后溲仍不行，径产一男。既而胞下，溺满其中。始知儿出胞后，频饮汤水，尽贮其中也。孟英曰：此证古所未闻。余虽初不料其如此，然非开泄导下，则儿不即娩，吉凶未可知矣。而《折肱漫录》云：孕妇将产，如患小便不通，乃脾气虚弱不能胜胞，故胞下坠，压塞膀胱使然。宜重剂白术，大健其脾，则胞举而小便自通者。正与此证虚实相对待。想其脉必有虚微之象也。", "13466": "夏间，牙行倪怀周室，新产数日，泄泻自汗，呕吐不纳，专科谓犯三禁，不敢肩任。孟英诊脉，虚微欲绝，证极可虞，宜急补之，迟不及矣。用东洋参、耆、术、龙、牡、酒炒白芍、桑枝、木瓜、扁豆、茯神、橘皮、紫石英、黑大豆投之，四剂渐以向安。予谓新产后，用参耆大补，而又当盛夏之时，非有真知灼见者不能也。诚以天下之病，千变万化，原无一定之治。奈耳食之徒，惟知执死方以治活病，岂非造孽无穷，亦何苦人人皆欲为医，而自取罪戾耶！", "13467": "张郑封室，娩后即发热，服生化汤二帖，热益炽而发赤疹。顾听泉诊之，即与清解，三剂不应，欲进犀角地黄汤，而恐病家之狃于产后以生疑也。乃拉孟英质之，诊其脉弦滑而数，面赤热躁，胸闷善悲，肢肿而疼，两肘白泡如扁豆大者数十颗，舌上亦有一颗，痛碍食饮，大便不解，已旬日矣。曰：此不但胎前伏暑，且有蕴毒，而误服生化汤，以助其虐。幸初手即用清解，尚不致于昏陷。犀角地黄，极是治法，犹恐不能胜任。乃与听泉商，加西洋参、滑石、知母、银花、花粉、人中白、蒌仁、竹黄、贝母、桑叶、栀子为剂。其所亲曰：高明断为热证，何以病者虽渴而喜热饮耶？孟英曰：此方中所以多用痰药也。凡胸中有热痰阻碍气机者，每如是，不可以其向不吐痰，而疑吾言之妄也。若因此而指为寒证，则祸不旋踵矣。进四帖，始得大解，频吐稠痰，而各恙皆减，饮食渐加。孟英曰：病势虽稳，余热尚炽，苟不亟为清涤，而遽投补益，犹有蓐损之虞。其母家果疑药过寒凉，必欲招专科调治，幸将前方示彼，尚不妄施温补，然隔靴搔痒，纪律全无。旬日后，余火复燃，郑封坚恳孟英设法，仍用甘寒疗之。周身肤蜕如蛇皮，爪甲更新。其病之再生也可知，继与滋补真阴而起。", "13468": "翁嘉顺室，娩后发热，竹林寺僧治之不应。温龚二医，皆主生化汤加减，病益剧。请孟英诊之，脉软滑微数，曰：素体阴亏，热自内生，新产血去，是以发热。惟谵妄昏瞀，最是吓医之证。渴喜热饮，宛似虚寒之据，宜其猜风寒而表散，疑瘀血以攻通。帖帖炮姜，人人桃、桂，阴愈受劫，病乃日加。幸而痰饮内盛，津液未致涸竭。与蠲饮六神汤去橘、半，加西洋参、生地、花粉、竹茹、知母、生白芍为剂，数日而瘳。逾旬夏发热，或疑凉药之弊，或谓产蓐成劳，众楚咻之，病渐进矣。其小姑适吴氏者，向役于冥曹，俗谓之活无常，偶来探病，忽仆地而僵，口中喃喃。或问汝嫂病何如？答云：须服王先生药。人皆异之，次日仍乞诊于孟英。曰：脉浮数而弦，是风温也，与前病异。便泻无溺，肺热所迫；大渴无苔，胃汁受烁。亟与天生建中汤频灌，即蔗汁也。药主大剂甘凉，果得津回舌润，渐以痊可。凡痰饮内盛之人，服寒热药皆如石投水，人皆以为禀赋之异，不知皆痰饮为患也。", "13469": "施氏妇，产后四肢串痛，药治罔效，医谓其成瘫痪矣。延已逾月，丐孟英视之。膏药遍贴，呻吟不息，脉数而洪，舌绛大渴，曰：此非风湿为病，膏药亟为揭去。近日服药，谅皆温补祛风之剂。营血耗伤，内风欲动，势将弄假成真。且吾向见其体丰血旺，何以娩后遽患斯疾？必生化汤、沙糖、酒之类所酿耳。其父倪某，目虽瞽，闻而笑云：君诚天医也。小女服过生化汤二帖，赤沙糖八斤，从此渐病，不识尚可起废图全否？孟英曰：幸其体足于阴，恢复尚易。若阴虚血少之人，而蹈此辙，虽不即死，难免不成蓐损。因投大剂凉润壮水之药，一剂知，旬日安，匝月起。", "13470": "慎氏妇，产后腹胀泄泻，面浮足肿，医与渗湿温补，月余不效，疑为蓐损。孟英视之，舌色如常，小溲通畅，宛似气虚之证。惟脉至梗涩，毫无微弱之形。因与丹参、滑石、泽兰、茯苓、茺蔚、蛤壳、桃仁、海䖳、五灵脂、豆卷，数服即瘥。（亦行瘀利水之法）", "13471": "陆厚甫室，陈芷浔主事之女也。产后经旬，偶发脘痛，专用温补药，因寒热气逆，（脘痛何以投温补，不问可知其误矣。）自汗不寐，登圊不能解，而卧则稀水自流，口渴善呕，杳不纳谷，佥云不起矣。乃父速孟英诊之，脉弦数而滑，曰：本属阴亏，肝阳侮胃，误投温补涩滞之剂，（产后肝血大亏，所以阴虚，肝失血养，故阳独盛）气机全不下降，以致诸证蜂起。医见而却走，是未明其故也。与沙参、竹茹、楝实、延胡、栀、连、橘、贝、杏、斛、枇杷叶，为肃肺以和肝胃法，复杯即安。但少腹隐隐作痛，于前方去杏、贝、竹茹，加知母、花粉、苁蓉、白芍、橘核、海䖳，乃解宿垢而瘳。（此脘痛之根）", "13472": "何新之令爱适汤氏，孟冬分娩。次日便泻一次，即发热痉厥，谵语昏狂。举家皇皇，乃翁邀孟英审之。脉弦滑，恶露仍行，曰：此胎前伏暑，乘新产血虚痰滞而发也。与大剂犀、羚、元参、竹叶、知母、花粉、栀、楝、银花投之，遍身得赤疹，而痉止神清。乃翁随以清肃调之而愈。有是病则有是药，不拘拘于产后之元虚。此明医之所以异于庸医也。", "13473": "高禄卿室，吴濂仲之妹也。孟夏分娩发热，初疑蒸乳，数日不退。产科治之，知挟温邪，进以清解，而大便溏泄，遂改温燥，其泄不减。（此邪去之征，识力不坚，遂为所眩。）另招张某视之，因谓专科误用蒌仁所致。与参、耆、姜、术、鹿角、肉果等药，泄泻愈甚。连服之，热壮神昏，汗出不止，势濒于危。酝香孝廉徐夫人，病者之从母也，心慈似佛，有子十人皆己出。闻其殆，夤夜命四郎季眉，请援于孟英。按脉洪数七至，口渴苔黄，洞泻如火，小溲不行，因谓季眉曰：病犹可治。第药太惊人，未必敢服。季眉坚欲求方，且云在此监服。乃疏白头翁汤，加石膏、犀角、银花、知母、花粉、竹叶、栀、楝、桑叶与之。次日复诊，脉证较减，仍用前方，而病家群哗。以为产后最忌寒凉，况洞泄数日乎？仍招张某商之，张谓幸我屡投温补在前，否则昨药下咽，（盲语）顷刻亡阳。复定耆、术之方，业已煎矣。所亲张芷舟孝廉闻之，飞告于酝香处，汾伯昆季，即驰至病家，幸未入口，夺盏倾之。索孟英方，煎而督灌，且属群季轮流守视，免致再投别药。孟英感其情谊，快舒所长。大剂凉解，服至七帖，泻全止，热尽退。乃去白头翁汤，加生地、元参、茹、贝。服半月，始解黑色燥矢，而眠食渐安。第腑脏之邪，虽已清涤，而从前温补，将热邪壅滞于膜络之间者，复发数痈于胸乳之间。孟英令其恪守前法，复入蒲公英、丝瓜络、橘叶、菊叶等药，服至百剂，始告全愈，而天癸亦至。方遵古法并不惊人，特读立斋、景岳书者见之，未免吃惊耳。不意浙省名手，狃于温补如此，真不能不归咎于景岳、立斋诸公矣。孟英曰：世俗泥于产后宜温之谬说，况兼泄泻，即使温补而死，病家不怨，医者无憾也。或具只眼，其谁信之？此证苟非汾伯昆仲笃信于平时，而力排众论于危难之间，余虽见到不疑，亦恶能有济耶？余尝曰：病不易识，尤不易患；医不易荐，尤不易任；药不易用，尤不易服，诚宇宙间第一难事也。而世人浅视之，可不悲哉！", "13474": "魏西林令侄女，娩后恶露延至两月。继闻乃翁条珊主政及两弟卒于京，悲哀不释，而为干嗽吐血，头痛偏左，不饥不食，不眠不便，渴饮而溲必间日一行，久治不效。孟英切脉，虚弦豁大，与甘麦大枣，加熟地、首乌、鳖甲、二至、菊花、旋覆、芍药、贝母、麻仁、青盐等药，服后脉渐敛，血亦止。七八剂头疼始息，旬日后便行安谷。逾年接柩悲恸，血复溢，误投温补而亡。", "13475": "陈书伯太史令弟妇，娩后三日，发热汗多，苔黄眩悸，孟英切脉，弦细虚数。乃营阴素亏，酷热外烁，风阳浮动，痉厥之萌也。予元参、白薇、青蒿、生地、小麦、穞豆衣、石斛、鳖甲、竹叶。两剂，热退，知饥，悸汗不止，去蒿、薇，加龙、牡、莲心、龟板、石英而安。继又暑风外袭，壮热如焚，渴饮不饥，视物尽赤，改授白虎加西洋参、竹叶、莲杆，一啜而瘳。仍与镇摄滋潜，善其后而愈。", "13476": "赵子循室，娩后服生化汤二帖，更因惊吓，三朝发热，连投四物、六合等汤，病日以甚。半月后，始延孟英诊之，脉象左弦急，右洪滑数，苔黄大渴，谵语嗽痰，恶露仍行，唇齿干燥。是因阴虚之体，血去过多，木火上浮，酷暑外烁，津液大耗，兼有伏痰之候也。亟与营卫两清，冀免他变。而母家极畏石膏，坚不与服。越三日，势益剧，计无所施。子循之叔笛楼，与其表兄许芷卿，径以白虎加减投之，证有转机。翌日再迓孟英，会同笛楼，暨其舅氏许吉斋山长，协商妥治，咸是王议。且以西瓜汁助其药力，热始日渐下行，二便如火。又数日，渐安粥食，神气亦清，起坐梳头，夜能静寐。然热蕴太久，下焦患痈，脓虽即溃，阴液漏伤，脉复空数浮大，便泄善嗔，口干多梦。皆木少水涵，烁津侮胃之见证也。孟英与笛楼商，以白头翁汤，加龙骨、三甲、甘草、木瓜，以育阴潜阳；余粮石脂丸中，加梅、连以息风镇胃。果得疮口脓干，餐加泻止，脉柔热净，苔退神怡。正须善后，甫授滋填。不期酷热兼旬，甘霖忽降，窗开彻夜，复感风邪，身热微寒，鼻流清涕。而阴液久夺，外患未痂，培养碍投，又难发汗，肝风内应，瘈噤旋形。九仞之功，遂成画饼。门外汉未免以成败论，然此案自堪传也。仍是阴血大虚，故变证如此，非盖由于风邪也。", "13477": "产后诸证，首必通瘀，然亦不可以常理测者。表弟周鹤庭室，新产晕汗，目不能开，心若悬旌，毫无恶露，乃父何君新之，按其脉有虚弦豁大之形，亟拉孟英图之。予以三甲、石英、丹参、琥珀、甘草、小麦、穞豆衣等药，（滋阴镇逆，仍兼行血之品，斯灵动而不滞。）复杯即安，数服而愈。或诘其何以知非瘀血为患？曰：此阴虚之体，既产而营液大脱，风阳上冒，虽无恶露，胸腹皆舒，岂可误作瘀冲，而妄投破血之药耶？", "13478": "辛亥春，孟英治其令正，诞子三朝，忽浑身麻冷，寻即壮热大渴，汗出不解，耳鸣眼泪，舌绛无津，苔色燥黄，腹痛拒按，不饥脘闷，恶露仍行，小溲极热，脉则弦滑右甚。是胎前吸受风温，兼挟痰食内滞。虽新产血去阴伤，见证较剧。然病不在营，亟宜撤热以安营，不可破血以伤营，亦不可养阴而助病。遂以元参、白薇、栀子、知母、竹茹、旋覆、菖蒲、枳实、栝蒌为方。服之热虽退，而脉不减，仍用此方。越二日，复麻冷而后热，惟舌稍润，苔较薄耳。再饮之，热亦即退，并吐胶痰数碗，略进稀糜。间一日，又发寒热。或疑为疟，或疑分娩不易，用力劳伤，恐是虚证。苟不及早温补，蓐损堪虞。孟英一一颔之，复与前药，热果渐减，渴亦递减。逾日，寒热犹来，亦不更方。至十一朝，始下黑燥矢，而寒热乃休，即能安谷。计服此药已十大剂矣，始出方与戚邻阅之。盖恐眷属之预闻凉解而有阻挠也。诸亲莫不骇诧，然此证非孟英独断独行，断难成功。设泥新娩而通瘀，或以为疟而温散，或疑其虚而滋补，势必骤变。即稍有瞻顾，亦必邪热纠缠而延成蓐损。世人之病，往往弄假成真者，大率类此。", "13479": "吾师赵菊斋先生令郎廉士之如君，新娩后微寒壮热，小溲全无，恶露稍行，大便如痢，神项善哭，大渴不眠。专科谓疟痢交作，不能图治，遂请孟英援手。脉来洪大滑数，曰：暑为患耳，不必治其疟痢。以辰砂益元散，加竹叶、银花、丹皮、木通、元参、丹参、莲杆，为大剂投之。三帖，各恙皆平。第营阴素亏，即改甘凉濡养，善后而愈。尚且乳汁全无，显由血少。设非清解，又当何如耶？", "13480": "石北涯仲媳，胎前患泻，季秋娩后，泻如漏水，不分遍数，恶露不行，专科束手，咸虑其脱。亟请孟英脉之，左弦而数，右大不空，口苦不饥，苔黄无溺，曰：非虚证也，参汤断弗沾唇。予白头翁，合石顽伏龙肝汤丸治之，一剂知，三剂愈。", "13481": "孙画三仲郎菊如之室，因儿女过多，不欲生产，怀妊屡服下胎药不应。娩后三朝，陡发寒热，兼以痛泻，所下皆黑，而小溲不行。医作瘀治，用回生丹等药已觉渐愈，惟寒热间作不休。至八朝，或嘱其邀孟英诊视。神气颇安静，苔色黄腻不厚，胃略知饥，惟右寸关空大，有静中一跃之形。诊毕适前医至，孟英谓右脉不佳，恐有骤变。彼按脉云，较昨已大和矣，必无害也。孟英唯唯而退，菊如送至门外，复嘱以令正元气大伤，莫投峻药而别。继闻是夜寒热复作，腹仍大痛，更服回生丹，越日而亡。", "13482": "沙沛生鹾尹令正，胎前痰嗽，娩后尤甚，孟英视之，面赤能餐，汗多畏热，脉滑而数，呕渴苔黄，恶露流通。血分无病，乃燥火伏于肺胃。法宜清肃上焦，不可谓产后禁凉润也。剂以沙参、茹、滑、知、斛、冬、甘、枇杷叶、冬瓜子、苇茎、梨皮、桑叶、蛤壳出入互用，旬日而痊。", "13483": "陈舜廷继室，娩后略有咳嗽，微有寒热，恶露不多，少腹似有聚瘕，时觉窜痛，腰疼不能反侧，齿衄频流，溺少口干，仍不喜饮，舌色无液，善怒不眠，四肢牵掣不舒，易于出汗。逆孟英诊之，脉至虚弦细弱。系素属阴亏，新产血去之后，八脉皆空，阳不能潜，游行于上。见证虽然错杂，治当清息风阳。表散攻瘀，毫不可犯。爰以沙参、竹茹、白薇、丹参、丝瓜络、石斛、栀子、小麦、甘草、红枣、藕为方。服数帖，嗽衄皆蠲，为去丹参、麦、枣、栀、斛，加归身、熟地、枸杞、麦冬、楝实，服之各恙渐瘥。复因卒闻惊吓之声，心悸自汗，肢麻欲厥，乃定集灵膏，加紫石英、牡蛎、龙齿，合甘麦大枣，熬膏服之而康。继有汪少洪令侄女，适孙彬士者，产后患证与此相似，误投温散，发热愈壮。但在上部，医者犹不知为阴虚阳越，仍从感治，迨脉脱汗淋，始邀孟英视之。始知是虚阳外越，然已不能拯救，病者自赋绝命词而逝。盖凡属虚脱之证，至死而神不昏也。医者识之。", "13484": "沈君云峰令正诞子后，患身热痰嗽，白㾦头疼，腹痛便溏，不饥口渴。医者治此碍彼，专事模棱。至九朝，余抵禾，视脉滑数，苔微黄，胎前感受冬温也，主以清解法。或疑有碍便溏，余曰：便溏为肺热之去路，设便闭则将喘逆矣。况夏间余尝治其胎前溺涩，群医渗利而不应，余专清肺而得手。今虽产后，体脏未更，兼有客热外侵，所谓有病则病受也。连服多剂，果即向安。", "13485": "管君锡棠仲郎兰谷之室，季秋患寒热，娠已八月矣。继因其子患惊，忧劳数月，遂兼痰嗽，而舌糜口臭。服药数帖而娩，其胎已腐。然寒热、咳嗽、口糜诸恙不减。医以其产后也，用药益无把握，驯致气逆自汗，面赤无眠，束手嘱备后事矣。适余游武原归，延诊其脉，寸关弦滑，右大，恶露流通，二便无阻，是下焦无病。虽在产后，而病与产后无涉。若云产后宜温，固是谬说。而此之口舌糜臭，亦非大热，毋庸重剂凉解。良由胎已早殒，失于早下，以致浊气薰蒸于肺胃，故见以上诸证。既见诸证，而早为肃清，则源澄流洁，奚至是耶？设再误作产后虚喘，而妄投补剂，则虽死而莫知其所以死也。爰以南沙参、省头草、厚朴、杏仁、菖蒲、桑皮、竹茹、枇杷叶、冬瓜子、丝瓜络为方，蔷薇叶、芦根煮汤煎服。两剂，气顺嗽止，知饥进谷，去杏、朴，加苡仁、甘草。口舌随愈，寒热亦休，惟骨节酸疼，合目即汗，改清热养阴而起榻。腰足尚酸软，授滋补气血而痊。", "13486": "余游瀛洲，有越人李姓浼心，鉏茂才见余云：亲串中一妇人，因娩后嗽血，遂致两目无光，四肢軃不能动，欲求一方。张谓如此大证，未审其脉，如何施治？余曰：吾知之矣。此肺热欲成痿躄也。遂以西洋参、桑皮、元参、百合、知母、苡仁、藕、茅根、枇杷叶为方。服六帖，闻余将归，李亟来署致谢云：病去大半矣，真仙丹也。欲再求一方，余为加葳蕤一味。然此由海外，因不知有产后宜温之谬说，故无人阻挠，而得偶然幸愈也。", "13487": "金氏妇自仲夏堕胎，迄今四月有余，恶露淋漓不断，两臀近复患疮，浑身肤痒，脉数而弦，多药罔效。亦为产后宜温之谬说所误也。用西洋参、银花各二钱，生地、龟板各四钱，冬瓜皮三钱，栀炭、竹茹各一钱五分，白薇、青蒿、黄柏各一钱，甘草六分。不十帖愈矣。", "13488": "都城售透土长寿丹，极言其功之大，能治诸疾，而价甚廉，人皆称之。孟英谓勿论其所用何药，执一方以疗百病，无此治法。每以禀赋不齐，证因有别，劝人切勿轻尝。况以绿豆汤为引，必有热毒之品在内，不可不慎也。继而张孟皋少府饵之患疽，广粤亭司马服之咽烂，孟英投多剂甘寒而愈。王雪山久患下部畏冷，吞未百丸，齿痛目赤，诸恙蜂起。孟英察脉弦滑，与多剂石膏药，兼以当归龙荟丸频服。新疾既瘳，腿亦渐温。令其常饮柿饼汤，以杜将来之恙。伊弟患腹胀而喜服温补，久而不效，孟英曰：湿热也，宜清化。彼不信，因服透土丹，初颇应，已而血大溢，始得悔悟。志此数则，以为世之好服奇药者戒！", "13489": "婺人罗元奎，丁亥夏卒发寒热，旋即呕吐不能立，自言胯间痛不可当。孟英视其痛处，焮赤肿硬，形如肥皂荚，横梗于毛际之左，乃曰：此证颇恶。然乘初起，可一击去之也。用金银花六两，生甘草一两，皂角刺五钱，水煎和酒服之。一剂减其势，再剂病若失。逾年患伤寒，孟英切脉，虚细已极，曰：此不可徒攻其病者，以阴分太亏耳。与景岳法，以熟地、当归、酒炒白芍、炙甘草、橘皮、柴胡等药，一剂而瘳。（此法予亦屡用获效。气虚者，并可加参。但表药止柴胡一味，犹嫌力微。予每以此法治阳证疮毒，莫不应手取效，真妙方也。）", "13490": "牙行王炳华妻，患舌疮，痛碍饮食，内治、外敷皆不效。孟英视其舌色红润，脉形空数，曰：此血虚火浮也，以产后发热例施之。用熟地、当归、酒炒白芍、炙甘草、茯苓、炮姜投之，其病如失。", "13491": "茅家埠翁嘉润，患腰疽，愈而复发者五年，费用不赀，诸疡医治之不效。盛少云嘱其求治于孟英，切其脉弦细以数，曰：子之幸也。此内损证，（肾俞发亦然。）外科恶乎知？与大剂甘润滋填之药，匝月而痊，至今不发。", "13492": "李燕标参戎，于癸夏将欲赴都，馆于石北涯家。项后患疽，外科佥云不治，孟英荐老医朱蒿年疗之渐安。孟英偶诊其脉，谓北涯曰：李证有可愈之机，脉难久享其年。北涯惊问所以，孟英曰：左尺坚搏，真阴已伤，非善象也。既而告痊北上，今春果卒于京。", "13493": "濮妪于酷热之秋，浑身生疖如疔，痛楚难堪，小溲或秘或频，大便登圊则努挣不下，卧则不能收摄，人皆谓其虚也。（未闻虚而生疖者）孟英诊脉滑数，舌紫苔黄而渴，与白虎，加花粉、竹叶、栀子、白薇、紫菀、石斛、黄柏，十余剂而痊。", "13494": "翁氏妇患目疾，自春徂夏，治不能瘳，渐至腹中痞胀，痛不可当，食不能下，便秘形消。孟英视之，乃肝郁痰滞，而误补以致殆也。脉弦数而滑，与金铃子散合雪羹，煎吞当归龙荟丸暨礞石滚痰丸。三投即效。服至二十余日，各恙皆蠲，眠食如旧。", "13495": "江梦花如君，患两目肿痛，不能略张。医投风药，昏痉欲厥。浼孟英诊之，脉至洪滑，大渴便秘，与白虎汤二剂霍然。", "13496": "高若舟庶母患脱肛，孟英脉之弦而滑，溲涩苔黄。虽属高年，非虚证也。清其湿热而痊。", "13497": "翁嘉顺，于去年秋间，偶从梯半跌仆，初无所伤，旬日外陡发寒热，膝旁肿痛。外科汪某治之，溃后不能收功。另招许某疗之，识为伤络，应手渐效，翁极信服。然培补年余，虽纳食不减，而肌肉渐削，面色黧黑，步履蹇滞。且一旬半月之间，必患处肿疼，大发寒热，卧榻数日，始能强起。大费不赀，愈发愈剧。至冬间咽糜龈腐，睛赤音嘶，乃恳孟英以决吉凶。按脉滑数，舌绛便难，口臭溲少，蕴隆虫虫。良由疡医仅知温托一法，既溃之后，更以温补收功善后，竟未察其体气病情，以致平时所有之湿热痰火，一齐关住。病犹自寻出路，寒热频作，而医者不识，妄指为虚。补及逾年，人财两瘠，真谚所云将钱买憔悴也。予元参、黄柏、知母、甘草、银花、花粉、绿豆、栀子、海䖳、凫茈为大剂投之，外吹以锡类散，且令日啖梨、蔗、麟鳞菜、柿饼等物。至五十日，诸恙悉蠲，体腴善步。", "13498": "韩贡甫于去冬偶患足疮，疡科治之，疮愈而大便下血，渐至腰背疼胀。医谓其虚，率投温补，病日以剧。迨仲春寒热时作，卧榻不起，诸医束手，已治木矣。所亲陈季竹嘱延孟英图之，脉弦缓而涩，苔黄溺赤，饮食不思，曰：此药病也。良由气机郁滞，湿热不清，补药乱投，病渐入血，然犹自寻出路。奈医者不知因病而下血，不治其病，徒涩其血，则气机愈窒，营卫不通，寒热不饥，固其宜也。而又疑为土败阴亏，脾肾两补，药力愈峻，病势愈危。若我视之，原非大病，肯服吾药，不日可瘳。乃兄聪甫闻之，大为折服。以海䖳、芦菔汤，煎芦根、厚朴、丝瓜筋、通草、白薇、栀子、楝实、竹茹等药投之，三剂而寒热不作，胃渐知饥。旬余血止溺澄，各恙皆已，改服清养药而康。", "13499": "许自堂叔岳，年越古稀，忽头面赤肿磊痒，渐及两臂，烦躁不眠，饮食日减，外科治而勿效。孟英脉之，弦洪疾驶，重按细软，曰：高年气血两亏，郁火内燔，不可从疡科治。予黄耆、当归、栀、芍、元参、生地、甘草、桑叶、菊花、丹皮、蒺藜、荆芥等出入为方，十余剂而瘳。", "13500": "黄漱庄司马，素患左目失明，今春右目患障，多药未瘳。延至秋间，孟英视曰：脉甚弦滑，痰火之疴，温补宜停，庶免瞽患。奈司马性喜温补，不以为然，渐至耳亦失聪。冬季再请孟英往诊，右目但能视碗大之字，稍小者不能见矣。耳则虽对面撞钟放炮，胥无闻也。且巅肿而疼，时咳白沫，脉来搏劲不挠。见其案头有顾某所定丸方，用药四十味，皆贵重温补及血肉之品。盖其病在络，不在脏腑，故服此如胶似漆之药，仅能锢疾成废，而无性命之虞也。闻辛亥春，许辛泉患类中，诸医佥从虚治。孟英诊脉沉滑而数，且体厚苔黄，亟宜化痰清热。疏方毕，人皆不以为然，惟其子秋芦极佩服，云：五年前，家父患恐惧多疑，曾屈诊视，方案犹存，若合符节。只因家父性喜温补，前之病根不拔，酿成今日之疴，先生卓见不可及也。奈病者依然不悟，不刈根株，延至壬子夏复中而殒，年未五旬也。并识之以为不究病情、好服温补者鉴。", "13501": "孙位申令正，左内踝患一疮，外科敷割，杂治两月，渐至疮色黑陷，食减神疲，寒热时形，痛无停晷。始延孟英诊之，脉象弦细无神，曰：此营阴大亏之证。余于外科虽疏，然初起既无寒热，患处亦不红肿，其非火毒可知，并不流脓，虚象更著。始则攻散劫津，继则温托壅气，妄施敷割，真是好肉剜成疮矣。况病在下焦，素患肝郁，耆、茸、芎、归，益令阳浮。两腿不温，岂为真冷？亟煎葱汤，将患处洗净，切勿再行钩割。以生附子杵烂，贴涌泉穴，引火下行。患处日用葱汤温洗。方用血余、当归、冬虫夏草、枸杞、牛膝、苁蓉、猪肤、藕、白蒲桃干煎服。五剂，寒热全休，腿温安谷，黑处转紫，痛减脉和。旬日后，紫转为红，陷处日浅，始令以珍珠八宝丹糁之，匝月而肌生体泰。", "13502": "家嫂患疥遍身，外科治之不愈且形瘦，而左臂酸疼不能举。孟英按脉弦洪而数，授清肝涤暑之剂，旬余而愈。又闻治一妊妇患疥，疡科治而弗愈，以寿灵寺所售疮药搽之，遂浑身壮热，肤赤神昏，阴户疼肿，尤为惨酷。气逆不饥，彻夜无寐，医皆无策。延孟英视之，脉甚洪数，舌绛无苔，四肢拘挛，溲热如火。乃暑火证，而复为毒烈燥热之药助其虐也。谁谓外治不比内服，可以擅用哉？与大剂银花、元参、石膏、甘草、栀子、鲜生地、竹叶、莲子心，菊叶、冬瓜皮、丝瓜络、西瓜翠衣，而以绿豆、黑豆煮清汤煎药。服三帖，肤淡神清，略进稀粥。又三帖，热退始尽，四肢渐舒。浃旬肿尽消，周身肤蜕如蛇皮而愈。", "13503": "细君上年病后，以清养药熬膏，服至岁杪，已康复胜常。孟春十八日，分娩亦快健。七日后，余即游武林，继返硖川，由梅溪而游嘉秀，至清明归，为展墓也。知其左乳裂疼，乳房亦痒，搔即水出。起已月余，初谓外恙不足虑，令取疡科善药敷之。余复鼓棹游梅泾而至檇李，又浮海由崇沙，迨归已届端阳矣。见有右目胞坍而甚赤，询其乳患左加甚，而更及于右。诸药久敷，皆不见效，且兼气冲痰嗽，口渴肤糙，盖津液悉从外患而耗也。察其脉滑而数，良由肺胃热炽使然。遂授元参、石膏、知、翘、甘、苡、蒌、栀、菖、菊、蛤壳、银花等，二十余剂，而各恙并蠲。既而余游吴越间者月余归，见其遍身暑疖，形瘦少餐，食后神疲，二便不畅，脉则弦涩不调。与元参、丝瓜络、栀、连、菖、橘、蒌、菀、薇、苏，四帖，而经月之病若失。亦因气郁热壅也。可见治病必探其源，勿徒遏其流。而故人菅君荣棠，尝为外证不宜服药，盖为服不得其当，及信书太过，泥用成方者言耳。若宣气清血之法，原不禁也。", "13504": "临证医案，非古也。古人视病不立案语，但书方药。自宋设医学科命题考试医生，取其学问高等者，入太医局。自后医生诊病，相沿先立案语，后书方药，但随作随弃，无有辑之者。如宋之许知可、张季明，明之薛立斋、陈维宜、孙文垣，以及国初喻嘉言、徐大椿辈，虽有医案类，皆因治疗效验，笔诸于书，其文乃记事，非临证也。良以病多转变，方难一定，恐泥学者眼目，故作者恝置之。然余谓医之有方案，犹名法家之有例案，文章家之有试牍。对病书方，因题立义，相对斯须，人之性命系焉，己之得失亦系焉。虽不足为根柢之学，而病者之情形，医者之学识心思，尽在于是。苟能溯其脉证，观其变化，奚啻与病者医者一堂共语，不大可触发手眼哉！故叶氏《临证指南》，海内风行。然叶案语意高深，方多平淡，学者践其迹，未必入其室。因叶负一时重名，所视者非富贵膏粱，即病深气竭，贫贱初病者寥寥焉。盖气体不同，方法即异，读其书而得其用者鲜矣！余旧得无锡王泰林旭高先生方案二卷，爱而藏之，以篇页无多，未梓。更求二十余年，不可得。客春游梁溪访老友刘君石香，石香出十卷示余，云新得于李氏者。亟假归读之，其心思之敏，见识之超，清华而不高深，灵变而有矩矱，视叶案易于学步。且复诊甚多，前后推究，考其得失，尤足以资助学者。因并余所藏者，去其重复，合而选之。间有字句冗沓率意处，略为删整，依类编次，分二十六门。每门附以拙论，略见大意。其有精警与未惬意者，复随案指出，正之有道，非敢有意毁誉也。原书十卷，约得五六，厘为四卷，命儿辈录出，不敢自私，付之梓人，以公同学焉。", "13505": "宋湿温过候，斑疹并见，心胸烦懊，神识模糊。脉数混混而不清，舌心苔干而不腻。湿蕴化热，热渐化燥。气粗短促，目赤耳聋。阴精下亏，风阳上亢。虑其内陷昏痉。拟生津达邪，兼芳香逐秽。", "13506": "又湿温邪在太阴、阳明，湿胜于热，太阴为多；热胜于湿，阳明为甚。日晡烦躁，阳明旺时也。口虽渴，苔仍白腻，乃湿蕴化热，余湿犹滞，气火熏蒸，蒙蔽清窍，故斑疹虽透而神识时糊，脉沉小而数疾，皆邪郁不达之象。倘若热甚风动变劲，便难措手。", "13507": "又湿温旬日，脉数较大于昨，热势较盛于前，所谓数则烦心，大为病进，并非阴转为阳、自内达外之象。舌苔白厚，上罩微灰，面红目赤，阳盛之征；头昏耳聋，阴虚之象；小溲窒塞，气化不及也。当生津以彻热，利窍以化湿。救阴不在肾而在生胃津，去湿不可燥而在通小便。盖汗生于津，津充汗出而热解；小肠为心之府，小便通利，心火降而神清。", "13508": "又湿热郁蒸，如烟如雾，神识沉迷，脉时躁时静。静则神倦若寐，躁则起坐如狂，邪内陷矣。虽便不通，而腹鸣不满，肠胃不实，其粪必溏，未可骤攻下之。大凡温邪时症，验舌为先。今尖苔白，上罩微霉，邪在营气之交。叶氏云：邪乍入营，犹可透热，仍转气分而解，如犀、羚、元、翘等是也。从此立方，参以芳香宣窍。", "13509": "又下后舌黑稍退，而脉反洪大，神识仍昏，阳明火旺也。清阳明燔灼之火，救少阴涸竭之阴，用景岳玉女煎。", "13510": "胡素有肝胃病，适挟湿温，七日汗解，八日复热。舌灰唇焦，齿板口渴，欲得热饮。右脉洪大数疾，左亦弦数。脘中仍痛，经事适来。静思其故，请明析之。夫肝胃乃腹中一脏一府，木乘土则气郁而痛。若不挟邪，安得寒热？即有寒热，断无大热，以此为辨也。又询大便坚硬而黑，是肠胃有实热，所谓燥屎也。考胃气痛门，无燥屎症，惟瘀血痛门有便血，然此症无发狂妄喜之状，则断乎非蓄血，此又一辨也。渴喜热饮，疑其为寒似矣。不知湿与热合，热处湿中，湿居热外，必饮热汤而湿乃开，胸中乃快，与阴寒假热不同，再合脉与唇，其属湿温挟积无疑。《伤寒大白》云：唇焦为食积。此言诸书不载，可云高出前古。", "13511": "按：病本湿温挟食，交候战汗而解，少顷复热为一忌。汗出而脉躁疾者，又一忌。适值经来，恐热邪陷入血室，从此滋变，亦一忌。故用豆豉以解肌，黑栀以清里，一宣一泄，祛表里之客邪。延胡索通血中气滞、气中血滞，兼治上下诸痛。郁金苦泄以散肝郁，香附辛散以利诸气，二味合治妇人经脉之逆行，即可杜热入血室之大患。栝蒌通府，赤苓利湿。加竹茹、连翘，一以开胃气之郁，一以治上焦之烦。外用葱、盐热熨，即古人摩按之法，相赞成功。", "13512": "又服药后大便一次，色黑如栗者数枚，兼带溏粪。脘痛大减，舌霉、唇焦俱少退，原为美事。惟脉数大者变为虚小无力，心中觉空，是邪减正虚之象，防神糊痉厥等变。今方九日，延过两候乃吉。", "13513": "秦温邪十二日，斑疹遍透，神识仍糊，大便屡行，齿垢未脱。舌尖红，中心焦，阴津灼也。左脉大，右脉小，元气弱也。昨投清泄芳开，是从邪面著笔；今诊脉神委顿，当从元气推求。要知温属阳邪，始终务存津液；胃为阳土，到底宜济甘凉。所虑液涸动风，易生痉厥之变；胃虚气逆，每致呃忒之虞耳！", "13514": "渊按：帆随湘转，妙于转环。脾肾阳气素虚，阳邪一化，阴湿即来。在脉神委顿时早防之，庶免此日波变。然不料其变之如是速耳。古方大豆卷治筋挛湿痹，苏地用麻黄汤浸，借以发汗，与此症总不相宜。", "13515": "又温邪甫退，少腹板硬，膀胱气化无权。昨议疏泄三焦，小便仍不畅。今少腹硬满过脐，其大如盘，按之不痛，脉沉小，舌白腻，身无热，口不渴，所谓上热方除中寒复起是也。夫膀胱与肾相表里，膀胱气化赖肾中阳气蒸腾。肾阳不足，膀胱水气凝而为瘕，须防犯胃冲心呃厥等变。急急温肾通阳泄水，犹恐莫及。", "13516": "尤症交十二日，目赤耳聋，舌白烦渴，脉洪大而汗出。当辛凉以彻气分之热邪，甘凉以救肺胃之津液。", "13517": "又目张不语而神慧，与汤则咽，身能转侧。舌苔灰白，脉形洪滑。并非邪闭心包，乃肝阳夹痰火阻塞清明之府。勿再芳香开达，开则邪反内陷矣，慎之！", "13518": "又目张不语，多汗脉大。阳盛阴虚，防其厥脱。急救其阴，希图万一。", "13519": "又目已能合，口已能言，但舌蹇而言涩。汗多稍收，脉大稍敛，似有一线生机。所嫌两臂动强，恐其发痉。拟存阴熄风法。", "13520": "华温邪八日，神识模糊，斑色红紫，脘腹拒按，结热旁流。舌红干燥，目赤唇焦，而又肤冷汗出，脉伏如无。邪热内闭，阴津外泄，颇有内闭外脱之虑。勉进黄龙汤法。", "13521": "渊按：肤冷、汗出、脉伏，非虚象，乃闭象也。从斑色红紫上看出。参须可斟酌。", "13522": "某久病元气未复，又感湿温，已愈旬日。解表、疏中、通下之药，皆已服过。现脉仍数，舌白腻。头汗多，身热不解，咳嗽不扬，小溲不爽。且以分泄三焦，再看转机。", "13523": "又温邪挟积化燥。昨服药后战汗不透，大热虽减，里热仍炽。舌霉边白，脉形不显。高年恐其内陷。", "13524": "又用和胃化邪法，一剂颇安，二剂反剧。良以畏虚多进谷食，留恋其邪，不能宣化，郁于心胸之间，湿蕴生痰，热蒸灼液，烦躁、恶心、错语。两手寸关脉细滑数，两尺少神，舌边乾红，心苔黄腻，皆将燥未燥，将陷未陷之象。拟导赤泻心各半法，生津化浊，和胃清心。", "13525": "又口臭喷人，胃火极盛。斑疹虽见，透而未足。目赤神糊，脉洪口渴。急急化斑为要。古法化斑，以白虎为主。今仍参以犀地清营解毒，再复存阴玉女煎。", "13526": "又黑苔剥落，舌质深红，阴津大伤，燥火未退，左脉细小，右脉洪大，是其征也。际此阴伤火旺，少阴不足，阳明有余，惟景岳玉女煎最合。一面存阴，一面泻火，守过三候，其阴当复。", "13527": "渊按：右脉洪大，阳明热结夹滞显然。", "13528": "又耳聋无闻，舌干难掉，阴津大伤。用复脉法。", "13529": "又症逾旬日，系温邪挟湿，病在气营之交。苔白腻而边红，疹点透而不爽，寐则谵语，寤则神清，呃声徐而未除，脉象软而小数。周先生清营泄卫、理气化浊，恰如其分。", "13530": "又热处湿中，神蒙嗜卧，呼之则清，语言了了。舌白腻，脉软数，知非邪陷膻中，乃湿热深漫于上焦，肺气失宣布耳。呃尚未除，胃浊未化。拟从肺胃立法。", "13531": "孙温邪袭肺，肺失清肃，湿挟热而生痰，火载气而逆上。喘息痰嘶，舌干口腻。昨日之脉据云弦硬，现诊脉象小而涩数，阴津暗伤，元气渐馁，颇有喘汗厥脱之虑。夫温邪为病，隶乎手经，肺胃位高，治宜清肃。痰随气涌，化痰以降气为先；气因火逆，降气以清肃为要。姑拟一方，备候高明酌夺。", "13532": "黄舌干而绛，齿燥唇焦，痰气喘粗，脉象细数。无形邪热薰蒸于膻中，有形痰浊阻塞于肺胃，而又津枯液燥，正气内亏，恐有厥脱之变。拟化痰涤热治其标，扶正生津救其本。必得痰喘平，神气清，庶几可图。", "13533": "又头汗淋沥，痰喘不止，脉形洪大，面色青晦，舌红干涸，齿板唇焦。此少阴阴津不足，阳明邪火有余，火载气而上逆，肺失降而为喘，症势危险，深虑厥脱。勉拟救少阴之津，清阳明之火，益气以敛其汗，但肺以定其喘，转辗图维，冀其应手乃妙。", "13534": "渊按：脉形洪大，合之头汗面青，上实下虚大著。从补下纳气之中，想出清热救津之法，故能应手。人参、石膏、粳米，救肺清热，亦所以救肾也。", "13535": "又汗稍收，喘稍平，脉大稍软。但气仍急促，心中烦躁，舌红干涸，齿垢唇焦。津液犹未回，虚阳犹未息，上逆之气犹未降，虽逾险岭，未涉坦途。今少腹似有透㾦之象，是亦邪之出路。仍拟救少阴，清阳明，再望转机。", "13536": "张温邪两候不解，脉形洪大中空；神昏蒙而如醉，舌淡红而无苔。与汤亦不却，不与亦不讨；呓语如呢喃，叮咛重复道。昨日用芳开，神情略觉好。然凭症而论之，乃津枯而液燥。是必甘寒润燥生津液，俾得气化津回方保吉。聊立方法以备参，候高明以商夺。", "13537": "又战而得汗，脉静身凉，邪已解矣。舌黄未去，胃中余浊未清，尚宜和化。", "13538": "凡战汗后脉静身凉，用方大法，不外乎此。", "13539": "孙营阴素亏之体，感受温邪，病起肢麻寒热，旋即便泄神糊。今交七日，脉数而洪，舌燥齿干，必荡气促。阳明之火方炽，少阴之阴已涸。又腹硬痛，大便三日不通。积聚于中不下，气火尽浮于上。似宜通降为先。然阴津大涸，不得不先养其津。姑拟一方备商。", "13540": "又温邪上受，自气传营；而化火上炎，由胃及肺。喉属肺经，咽属胃经。凡咽喉之症，属实火者多，因肺胃之阳盛。肾脉循喉，肝脉绕咽，系虚火者，始关肝肾之阴亏。是其大略也。此症乃斑痧之后，喉痛色赤，全由邪火炽张。图治之方，犀角地黄，不出甘寒清解。昨吐红痰，无非气火熏蒸。今观脉色，已觉神清爽朗。喜逢知己，共斟酌而揣摩，幸谢主人，转忧疑为欣慰。立夏恰今朝，病能减而即是退；怀麟当此疾，胎不动即是安。大便才通，亦是转机之兆。小心调理，冀无欲速之讥。略泐数行，伏希晒政。", "13541": "又夫温邪燔亢之余，余热固未能净；肺胃燎原之下，阴津必受其戕。养阴不在血而在津与汗，叶氏之名言；安胎须顺气，阴火忌上冲，妇科之要论。此症儿及两候，温痧既退，安得邪火复炽？喉肿既消，何以燥痛复盛？所以然者，胎当七八月之间，正肺与大肠司养之际，肺肠相为表里，肺主气而大肠主津，肺受火淫，燥热移于大肠，大肠当养胎之际，遂移热于胞络。《内经》云：人有重身，九月而暗，是胞之络脉绝也。胞脉者，系于肾而络胞胎。今热上迫肺，故音哑、咳嗽而喉复痛也。按此段经文，明指胎中阴火，当九月之期有此音哑一症，教人勿亟治之，惟恐伤其胎气耳。兹方八月，即得音哑咳频，岂非殃及池鱼之谓欤！今以甘凉生津治其上燥，参入咸寒以降阴中伏火，经所谓热淫于内，治以咸寒是也。须知治病要察机宜，养阴而火自降，指久病虚羸而言。火退而阴自充，乃暴病未虚之症。先辈有提其要曰：暴病多实，久病多虚。是其义也。然欤否欤，仍候华先生裁正。", "13542": "渊按：伏温由内达外，由里传表，从少阴而出太阴，所以退而复来，轻而再重，不尽由乎胎热。疹属肺，肺主一身之表。斑属胃，胃为万物所归，温邪每从两经而达也。胞络者，乃胞门子户之胞，非心包络。胞络系肾，少阴之脉贯肾，上入喉中，热邪由少阴上干喉中，故音哑。甚则喉痛。", "13543": "沈阴虚之体，感受温邪，反复。今交九日，神识时迷，舌满碎腐，脉象渐沉。防其昏厥。备方候致和先生晒政。", "13544": "秦发汗太过，津液内夺。昨日生津以达邪，汗虽未出而疹点已化，热虽未退而脉象稍和，是佳兆也。苔煤而不甚燥，神糊而有时清，犀角、地黄虽可用，然大势无变，方亦无事更张，仍照前方加味。", "13545": "张久患便血，阴气先伤于下。今感温邪挟积，肺胃之气阻窒。上喘下泄，发热口渴，舌绛如朱，额汗不止，遍体无汗，脉小数疾。厥脱险象，勉拟一方备正。", "13546": "渊按：阴血既耗于下，脾气复伤于中，故一感温邪而上喘下泄。泄为脾陷，喘为肾逆，两脏不守，厥脱易易。头汗者，阴不守而阳越也。身无汗者，阴液虚而气不能化也。舌绛如朱，胃阴亏而心火炽。脉小数疾，阴血虚而邪火伏。两方颇有心思，惟葛根嫌升发，牛蒡嫌泄肺。盖阴阳两虚，中气不守，气虽陷，不可升，汗虽无，不可发，急急顾虑中气阴液，犹恐不及。然肯用心如此，敬服之至。", "13547": "李暑邪内闭，恶寒发热，脉象不达，口不能言，先有咳嗽，此肺气闭塞。拟开而达之。", "13548": "安连日烦劳忧虑深，暑邪伤气易归心。神昏脉数细而沉，病危甚！邪闷心包，如火如焚。舌色干黄唇齿燥，耳聋便泄津枯了！三焦皆病须分晓，究治疗，河间热论宜参考。", "13549": "李暑湿先伏于内，凉风复袭于外，交蒸互郁，皆能化火，湿遏热伏，其热愈炽。故其为疟也，先寒后热，日轻夜重。经旨所谓先伤于热，后感于寒。喻氏所谓阴日助阴，则热减而轻，阳日助阳，则热甚而重也。夫疟之发，必从四末始，既必扰及中宫，故心胸烦躁，中脘痞塞。又必先呕吐而泄泻，泻已乃衰，腹中犹胀。所以然者，热甚于中，蒸熏水谷之湿，上泛而复下泄，热势得越，烦躁乃安，余湿复聚，故仍作胀也。今当疟退，脉弦带数，舌苔白腻，小溲不爽，本有胃寒，痰浊素盛，虽从未得汗，表邪未解，而病机偏重于里，法从里治。大旨泄热为主，祛湿兼之，解表佐之，是亦表里分消，三焦并治意。", "13550": "杨年过花甲，病逾旬日，远途归家，舟车跋涉，脉沉神昧，舌强白，中心焦，身热不扬，手足寒冷，气短作呃，便泄溏臭。是属伏邪挟积，正虚邪陷之象。深虑厥脱。", "13551": "又伏暑化燥，劫津动风，舌黑唇焦，鼻煤齿燥，神昏，手指牵引。今早大便自通，据云病势略减。然两脉促疾，阴津消涸，邪火燎原，仍属险象，恐其复剧。", "13552": "又投两解法，得汗得便，竟安两日。昨以起床照镜，开窗看菊，渐渐发热，热甚神糊，两目上视，几乎厥脱。逮黄昏，神渐清，热渐减，脉沉不起。据述热时舌色乾红，热退舌色黄腻。此乃湿遏热炽，将燥未燥，将陷未陷，但阳症阴脉，相反可虞。勉拟河间甘露饮，涤热燥湿之中，更借桂以通阳，苓以通阴，复入草果祛太阴湿土之寒，知母清阳明燥金之热。", "13553": "某伏暑为病，湿热居多，阴虚之体，邪不易达，此其常也。然阴虚大有轻重之分，须知此症虚亦不甚，邪亦不多。耳鸣眩悸，口渴胸痞，微寒微热，脉形弦数。未便大补，亦不可重剂攻邪。但得脉情无变，可保无虞。", "13554": "胡伏暑三候，神糊呃逆，手肢微痉，痰多舌白，渴不多饮，音低，脉大而虚，殊属棘手。今日忽周身干燥而痒，烦躁不安。细询病原，从未得汗。按仲景云：汗出不彻，身痒如虫行皮肤中，久虚故也。吴又可云：发根燥痒，心烦如灼，名曰药烦，中气虚也。《金匮》云：声如从瓮中出，是中气之湿也。又按《内经》：言微音低，谓之夺气。由此推之，明是中虚浊恋，液涸痰蒙，势极凶危。惟有和中宣化，听其胃气自为敷布，以冀万一生机。", "13555": "吴暑湿伏于太阴，中焦阳气不化。神蒙若寐，身热不扬，肢冷脉濡，手指牵引，舌根牵强，风痰阻络之象。服过通阳益阴，云蒸化雨之法，病亦无甚增损。然舌苔灰白厚指，口泛甜味极甚，中宫有浊，阳不舒化。仿缩脾饮醒中化湿浊。浊化则口甜减，阳舒则蒙昧清。", "13556": "赵高年元气素亏，未病以前先已倦怠乏力，微觉咳嗽。五六日以来加以发热，热势起伏，是有新邪乘虚而袭，引动伏邪晚发也。今诊脉小数而虚，干咳欲呕，舌边光红，根苔白掯，热甚无汗，津枯邪恋，虑其化燥神昏。", "13557": "李伏邪湿热内蕴，三焦气机不达。午后发热，胸闷头胀，尿少无汗。舌苔白腻，脉象软细。拟开上、疏中、渗下，仿河间法。", "13558": "浦伏邪挟积，阻塞中宫。疟发日轻日重，重则神糊烦躁，起卧如狂。此乃食积蒸痰，邪热化火，痰火上蒙包络，怕其风动痉厥。脉沉实而舌苔黄，邪积聚于阳明，法当通下，仿大柴胡例备商。", "13559": "又昨日疟来，手足寒冷，即腹中气撑，上塞咽喉，几乎发厥，但不昏狂耳。此乃少阴疟邪，内陷厥阴，上走心包为昏狂，下乘脾土为腹撑。脾与胃为表里，前日昏狂，病机偏在阳明，故法从下夺。今腹胀，舌白，脉细，病机偏在太阴，法当辛温通阳，转运中气为要。随机应变，急者为先，莫道用寒用热之不侔也。", "13560": "又投姜、附、达原、神、香、二陈合剂，喉中汩汩痰声顿时即平，腹胀遂松。今脉缓大，神气安和，腹中微觉胀满，痰多黏腻。脾脏阳气虽通，寒热痰涎未化。仍宗前法，轻减其制。", "13561": "严年届六旬，元气素弱，向有肝气，近患三疟。两月以前，先受伏暑；小愈之后，三疟遂作。脉弦，肝胃尤甚。木胜胃土，恶谷厌纳，痰多呕恶，心跳少寐，便闭溺赤。盖胃气一虚，百病丛生矣。高年虽大便两旬不通，未可以通阳为务。培养中气，启胃化痰，是为扼要；调和营卫，退其寒热佐之。", "13562": "渊按：运脾气，补脾阴，和营卫，温督脉，前数方皆虚疟，久疟治法。", "13563": "营久患疮疥，湿热浸淫，复因外感暑湿为疟，缠绵不已，变为三疟。诊脉濡小，其湿仍恋，而元气渐伤，虑加腹满，宜早图之。然须安逸忌口为要。", "13564": "徐左脉细弦，肝肾亏也；右脉软弱，脾胃虚也。三疟之后，气血两亏。补肝肾，调脾胃，养气血，必得安逸少劳而后可也。", "13565": "又疟脉自弦，弦大者为阳，其邪易达。今疟来热势稍轻而短，邪有退机矣。仍从前法。", "13566": "丁三疟久延，营卫两伤，复因产后，下焦八脉空虚。今病将九月，而疟仍未止，腹中结块偏左，此疟邪阻于血络，聚于肝募，是属疟母。淹缠不已，虑成疟劳。夏至在迩，乃阴阳剥复之际，瘦人久病，最怕阴伤。趁此图维，迎机导窍，和阳以生阴，从产后立法。稍佐搜络，以杜疟邪之根。", "13567": "马高年下痢，一日夜百余次。舌苔白掯，身热恶心，诊脉细，饮食不纳，痢下五色，皆为忌款。败毒散法初起的是，然须人参扶正和胃。若喻氏痢疾门中，五色噤口，不治者多。尚祈商政是荷。", "13568": "孙湿温邪陷厥阴，下痢色紫后重，左脉沉小，右脉弦大，舌黄，晡热，是阳明积热内恋，而木来乘土。高年体虚神怯，防其厥脱。", "13569": "某红痢日久，脾气必虚，营气必耗。前方理中汤下驻车丸，颇验。奈轻听人言，服红曲、滑石末，致痢复剧。脉迟缓而涩，舌薄白而底绛。渴不贪饮，口恶甜味。素体多湿，今脾阳失运，湿又动于中矣。徐灵胎云：血痢挟湿者，胃风汤最妙。《医归·痢疾门》亦采是法。", "13570": "渊按：理中汤温运中阳，驻车丸分导湿热，从脉象迟涩看出。红曲、滑石适与相反。", "13571": "李久吃洋烟，脉沉而细。病方三日，微寒微热，头略胀痛，昼不痢，痢在夜，是属寒邪；而反色赤者，寒伤营也。当以和营散寒、温通阳气为法。勿与常痢同治。", "13572": "渊按：脉细肢寒，昼不痢，痢在夜，乃脾阳不能统摄营阴也。", "13573": "蔡右脉细弦，木侮土也；左脉细弱，肾水亏也。病由肝气而起，水不涵木也。兹患下痢赤白，木胜土衰，湿热不化也。华先生用补中升阳，参入育阴，从本求治，极有见地。鄙意再参温化，乃兼顾脾肾之阳气也。", "13574": "此病两脉虚濡，脾胃元气大弱，似宜参入扶正为善。然下痢古称滞下，起于湿热居多，早补早敛，往往受累，此河间苦辛宣通腑滞之法，所以为痢门必采之方。若补阴阳，治脾胃，多为久痢而设也。", "13575": "陆《脉经》云：代则气衰，细则气少。多指阳气为言。今下痢而得促脉，脾胃之阳微特著。况形衰畏冷，而小便清长者乎！惟是下痢赤者属血分，腹中痛为有积，立方从此设想，寻其罅而通之补之，亦治病之机巧也。", "13576": "薛先患红痢，续加以疟，又变泄泻，泻止仍痢，两月有余。脉弦硬，昼无小便，每交子后至辰便痢数次，小溲亦得稍通。此伏暑湿热蕴于肠胃及厥阴。厥阴之表便是少阳，故先见热痢，后兼疟象，乃厥阴、少阳表里同病也。疟后大便溏泄者，少阳木邪侮土也。泻止而疟痢仍作者，胃气强旺，土不受邪，仍还厥、少两经也。小便少者，阴气亏则渗愈少，当滋其化源也。今清厥阴之热而举清阳，兼益肾之阴，运脾之湿，从白头翁合胃风汤意。", "13577": "又痢减腹仍痛，肝胃未和也。现值经来，脉弦寒热，血虚木郁。拟养血疏肝。", "13578": "张便痢白腻如水晶鱼脑色，小便不利，少腹偏右板窒。诸医以为肠痈，固以相似。然考肠痈为病，有寒有热。《金匮》并出二方，如大黄牡丹汤，苡仁附子败酱散，概可见矣。但此症则属寒积，脉弦紧而数，面色青而不渴，宜用温通。", "13579": "某休息痢将及五年，腹中块垒时痛，痢下仍兼干粪。脉弦迟，苔灰白。此虚而有寒积也。《本事方》云：痼冷在肠胃，泄泻腹痛，宜先取去，然后调理，不可畏虚养病。此症的是。姑拟一方备采。信则服之，疑则勿服。", "13580": "某泄痢白腻，腹不痛，脉沉细。此寒也。宜温之。", "13581": "李河间论痢属热者多，而景岳论痢属寒者不少。此症腹不甚痛，但肛酸且胀，脉紧肢寒，并不发热，兼素有寒疝，苔白不渴，寒象为多。宗景岳论治之。", "13582": "徐红痢匝月，仍腹痛后重。据云，先曾发热三次。此属中虚表邪传里。现今脉细肢寒，太阴阳气已弱；小便艰难，膀胱气化又钝。拟开其中焦，化其湿热，兼升阳解表，亦表里双解之法也。", "13583": "仁渊曰：洁古芍药汤亦治痢要方，湿热积郁结肠胃甚者，宜通下以开壅塞，使邪不久留，正气不致大伤，何数十证无一及之者，或未遇此等耳。夫痢疾古名肠澼，夏秋湿热居多。邪壅肠胃重而经络轻者成痢，肠胃轻而经络重者为疟疾、伏暑。亦有经腑同病，寒热痛痢并作者，初宜苦辛芳淡通而化之。挟表则活人败毒散。积重痛甚者，因而竭之，洁古芍药汤。病有寒热虚实，药有补泻温凉，非一法所能概也。若噤口不纳者难治。乃湿热伤胃，邪势捍格，绝不思谷，治法虽多，须中气尚有根柢，犹或可治。烟痢亦难治，因久吸洋烟，肾精脾气先已告困，迨痢疾一发，势即不支，故诸药不效耳。初起视其正尚可支，急为逐邪，切勿彷徨。辗转三五日后，脏真伤而津气竭，欲攻不能，欲补不可，即棘手矣。若邪正并急，尤宜舍邪顾正，或温补脾胃，或清补气液，佐彻邪一二味，能受即是生机。否恐邪未化而正已脱，但不可早用兜涩，无益而害之。盖兜涩莫过洋烟，洋烟不灵，岂禹粮、石脂、诃、粟、榴皮能为力乎？苟元气津液可恃，邪不自容，痢中自有去邪，邪化痢止，必然之理。虚不受补者死，且胃气亦不可恃。平人能纳谷者，虽重可治。烟痢脾肾脏真受伤，虽能纳谷，不过稍延时日，待胃败则死耳。盖脾为仓廪，后天之本；肾为先天，二阴锁钥故也。根柢一坏，神丹莫挽矣。论脉弦急大者死，缓弱者生。须看其所下何如。若虚坐努责，或紫水败酱，虽腹痛后重，虚象大著矣。切勿再进苦寒伤胃，宜温运脾肾，疏达肝木。木达气升，其痛自止；痢随痛减，胃气亦醒。达木用肉桂最妙，盖甘缓辛通发散为阳，最能畅达郁结也。", "13584": "曾脉形乍大乍小，面色暗晦不泽，似有一团阴气阻遏于中。苔黄而湿，腹满足肿，小便黄赤，又有湿遏热伏之形。色症合参，是属女劳黑疸。变为腹满，在法难医。姑拟泄肾热以去脾湿，仿《金匮》法。", "13585": "施三疟止而复作，腹满平而又发。今目黄脉细，面黑溺少，防延黑疸。然疸而腹满者难治，姑与分消。", "13586": "又面色黎黑，腹满足肿，脉沉而细。此脾肾之阳不化，水湿阻止于中，证势甚重。且与通阳燥湿。", "13587": "仁渊曰：黄疸亦湿热郁遏之病，与伏暑、疟疾同一来路。古人谓如盦酱，湿热壅遏不泄所致。但有阴黄、阳黄、女劳、谷、酒之分。同是湿热，阳黄则黄色鲜明，脉大口渴，其证多实，治如茵𫈟五苓、平胃、栀子柏皮等，甚则茵𫈟大黄之类，开化中宫，分泄湿热，从小便而出，其黄自退。阴黄则脾肾阳气素虚，不能升化其邪，黄色暗晦，脉细皮寒，口不渴，分化湿热，宜佐通阳理脾，如茵𫈟五苓佐理中、真武之类。谷疸则食伤脾胃，酒疸则酒伤肺脾，皆湿热阻而不化，各有所主。女劳黑疸，最为难治，乃内伏湿邪，更伤女劳而得，肾精大伤，根本已坏，湿热之邪深伏厥、少，正气不能胜任故也。又有虚黄一证，并非黄疸，乃中虚木胜，土色发见于外，其黄色淡白，小便不变，脉弱口淡，能食而无力，俗名懒黄，乃劳倦内伤之症，宜崇土疏木，调补中气，如补中益气之类。诸黄证虽以分泄湿热为主，尤须察其阴阳虚实，有无兼证而调之，始为尽善。", "13588": "王两手关脉皆见一粒厥厥动摇之象，此脾虚木盛，内风动跃之候也。左半肢体麻木不仁，头眩面麻，此属偏枯，虑延仆中。", "13589": "复两关脉厥厥动摇之象大减，其内风有暗熄之机。左手屈伸稍安，左足麻木未愈。今拟补肾生肝，为治本之计。", "13590": "金左手脉沉弦而涩数不调，乃血虚而肝风暗动也；右关脉独缓滑，胃有湿痰，尺寸俱弱，金水两虚。症见耳聋，两肩膊酸而难举，痰多，口中干腻，是其征也。", "13591": "丁脉左弱为血虚，右弱为气虚，气血两虚，上为头眩，半身以下皆形麻木而成瘫痪，甚则心乱神昏，此肝风挟痰所致。法当清上补下。", "13592": "谢久患肝风眩晕，复感秋风成疟。疟愈之后，周身筋脉跳跃，甚则发厥。此乃血虚不能涵木，筋脉失养，虚风走络，痰涎凝聚所致。拟养血熄风，化痰通络。", "13593": "何右关脉独滑动如豆，此有痰浊在中焦也。中脘皮肉觉厚，手足筋脉时或动惕，痰走经络之象。法当攻补兼施。", "13594": "陆素有痰饮咳嗽，土弱金虚。金虚不能制木，并不能生水；土弱不能御木之侮，并不能生金而化痰。病情有似风痰瘫痪，足软难行，口流涎沫，舌左半无苔，口常不渴，脉虚弦滑，大便坚燥。种种见症，皆显金土水不足而风痰有余。病根日久，调之不易，姑拟一方备采。", "13595": "顾血不养筋，筋脉牵掣，昼日则安，暮夜则发，不能安卧，病在阴经。宜养血以和经脉。", "13596": "吴上年夏季痰火迷心，神呆语乱。愈后至今复发。现诊脉浮小弱，舌心红而苔白。语言错乱，哭笑不常。凭脉而论，似属心风。盖由风入心经，蕴热蒸痰所致。用《本事方》独活汤。", "13597": "徐少腹之块已平，小便已利而反不禁。素有肝风脾泄宿恙，近增右手麻木。脉象弦大而滑，时觉痰多气升。此中气已虚，精血不足，内风走络，脾湿生痰。法当兼顾。", "13598": "胡少腹胁肋，肝之部也。腰，肾之府也。年老则精血枯而络脉空，肝气乘虚入络，湿热又从之为患。补养精血，疏肝通络，兼化湿热以治之。", "13599": "又补养精血，疏通脉络，胁肋之痛稍减。惟小溲短少，夜半以后脘腹觉胀，是浊气不化也。前方加通阳泄浊之品。", "13600": "华病久正虚，阴阳两弱，坎离不交，夜不成寐，久卧于床，不耐烦劳。兹因舟行跋涉，远道就诊，忽然神糊不语，两手不定，遮睛挦发，烦躁不安。诊脉促乱，饮食不进。想由舟中热闷，鼓动风阳，扰乱神明，卒然生变。姑拟熄风和阳，安神定志。冀得神清谷进，或可再商。", "13601": "陈脉诊左关独弦滑，风阳挟痰上扰阳明，头额偏左连及腮齿皆痛。拟熄风阳，兼清痰火。", "13602": "又脉细数，懒言倦卧，其为精气神三者皆虚。然舌苔白腻，有痰且有饮。再察神情，静则气怠而若虚，动则气上而自乱，是虚而有痰兼有火也。火伏则痰不上升则静，静则虚象现；火动而痰升则躁，躁则虚象隐。非不虚也，痰火为之起伏也。治不越十味温胆加减。临症各有心思，悉关根柢。", "13603": "又阴遏于外，阳伏于内。阴如迷雾，阳若日光。今阳为阴遏，故沉沉默默而蒙昧，脉亦为之不显。有时阳光见𬀪，则起坐而神清，脉亦为之稍起。顷之阴霾四合，阳气复翳，则仍昏昏如寐。前案谓有痰饮郁于其中，十味温胆屡投不应。再思病源起于头眩心悸，苔白多痰，常服苍术见效。近因神乱若痴，多从事于痰火，清滋重镇，阴胜于阳，以致变幻。然欲开阴雾，法必通阳，譬之离照当空，而后阴雾始散。议进仲景苓桂术甘汤加味。", "13604": "侯病已两月，外皮不热，而脉微数急，是里有热也。里热属阴虚，非关表邪，并无头痛恶寒。愈散其邪，愈虚其表，故反增咳嗽也。若谓湿热，亦似是而非。夫湿热蕴于中焦，必有胸痞恶心见症。此证无之，其非湿热明矣。近来数日腹中不和，大便溏。且以和中为主，兼理其脾肺，再商治本可耳。", "13605": "又和补相投，诸恙俱减。惟脉数未静，究属元气真阴亏损。但前之补在肺脾，再参入肾药，兼养其阴，以观动静。", "13606": "薛便泄半载，脾肾两亏；脉沉细涩，阴阳并弱。阳萎不举，精伤特甚；面白无华，气虚已极。足跗浮肿，阳虚湿注于下；纳食嗳气，胃虚气逆于中。调治之方，自宜脾肾双补，阴阳并顾。然刚热补阳，恐劫其阴；滋腻补阴，恐妨其胃。刻下节届清明，木旺土衰之候。脾者，土也。肾属坎水，一阳藏于二阴之中。当于补土中兼顾肾脏阴阳为是。", "13607": "复脾肾双补，略见小效。今腹中鸣响，气向下坠，属脾虚气陷。舌心光红，脉沉细数，为肾脏阴伤。用补中升阳法。", "13608": "李病将半载，寒热淹缠。前方补营，兼以疏郁，心悸腹胀仍然。兹更便溏足肿，是脾气虚弱也。脉缓无力，当补其脾，进归脾加减法。", "13609": "钱心脾营阴内亏，肝胆风火上逆。内热头眩，项间结核。脉虚形弱，治以养营。然病由内生，不易速效。", "13610": "金骨胳瘦小，先天元气不足。夏秋寒热，至今不已。脉细数弱，气血两亏。头不痛而但身疼，或口沃清水，此胃气虚寒也。当商温补，仿东垣法。", "13611": "某咳嗽发热日久，前投补益脾胃之药六、七剂，谷食加增，起居略健。但热势每交寅卯而盛，乃少阳旺时也。少阳属胆，与肝相为表里。肝胆有郁热，戕伐生生之气，肺金失其清肃，脾胃失其转输，相火日益炽，阴津日益涸，燎原之势，不至涸竭不止也。其脉弦数者，肝胆郁热之候也。刻下初交夏令，趁其胃旺加餐，拟进酸苦益阴和阳，清彻肝胆之郁热。考古有柴前梅连散，颇有深意。", "13612": "徐肺脾两虚，心营亏损。咳嗽气塞，骨蒸夜热，脉形软数，面白无华。劳损根深，夏至防剧。", "13613": "又脉软数为气虚，骨蒸心跳为血虚，咳嗽头眩，面色萎黄，脾肺两虚之候也。", "13614": "又投扶土生金法，谷食反减，夜热增重，乃胃阴失降，虚阳外浮也。夫脾宜升则健，胃宜降则和，胃为阳土生肺金。今诊左脉数疾，为心肝阳亢之象。肝火戕胃，心火烁金。宜其食减热增，夏令防剧。", "13615": "又咳嗽内热俱减，惟脉之细数不退，仍为可虑。", "13616": "王病后胃气不醒，脘腹饱胀，近增寒热恶心，痰升气逆，咳呛口干，阻塞咽嗌，大便艰难，小便短涩，左胁有块，大如复杯，撑攻作痛。此因脾胃不足，肝木亢逆，清气不升，浊气不降，攻消克伐，元气愈伤，纳谷大减，津液日枯，虚火内炽，戕及肺胃，渐见火升颧赤、脉数内热之象，当成劳损。宜以扶土为主，升清降浊，佐以泻火清金，俾得中气安和，自然饱胀渐解。", "13617": "又就脉数内热，咳嗽，脘胁仍痛而论，乃阴虚肝郁成热，肺失清肃，仍防吐血。", "13618": "王脾虚气陷，肛门先发外疡。疡溃之后，大便作泻，迄今一月有余。自云下部畏冷，而两脉弦硬不柔，此谓牢脉，症属阴虚。法以温中扶土，升阳化湿。", "13619": "冯病延半载，骨蒸不已，鼻血时流，周身骨痛。营阴大亏，虚火内亢。脉沉搏数，口燥渴饮。劳损根深，入夏防剧。拟滋少阴，清阳明。", "13620": "王左脉空大，肾水亏也。倦怠无力，脾气弱也。食少则阴虚，阴虚生内热，症属内伤。", "13621": "徐二月间吐痰带血，血止之后，略兼干咳。交清明节，咳嗽渐甚。四月初，身加发热。今诊脉细数，形容消瘦，行动气升。此属肾气先亏于下，复因劳碌感邪，延绵不已，虑成劳损。静养为佳。", "13622": "孙久有咳嗽血痰之恙，今复肛门结疡，是肺遗热于大肠。脉数音哑，劳损之根。时当夏令，火旺金衰，颇有气逆血沸之虑。", "13623": "高脉沉取数，其阴内亏，其热在里，劳损之候。症见咳吐白痰，心腹不时疼痛，痛则气满，得矢气则稍宽。病兼肝郁。据云咳嗽已及三年，初无身热，则病从痰饮而始，宜从痰饮气郁例治之。", "13624": "赵脉沉数，手足冷，胸闷食少，脾胃衰弱。大便干燥者，肠中之津液枯也。法当温中土，润大肠，仿菟丝子丸加减。", "13625": "冯久咳痰稠，上午发热，面色青黄。左脉细数，右脉软弱。病属上损。幸大便不溏，尚未过中及下。加谨调养，交夏至节无变再议。", "13626": "又咳嗽脉细数，前上午发热，今下午亦热，阴气渐伤。大便间或带血，脾气虚也。从景岳理阴煎例。扶过夏至节，一阴来复，病无增变，庶几可延。", "13627": "四君子汤合生脉散，加生地、怀山药、白芍、白扁豆、川贝、阿胶、红枣。", "13628": "赵漏疡日久，阴津暗渗。加以咳嗽气耗，考试劳神，于是咳甚气升，便溏内热、音哑喉痛等等，接踵而至。脉象细数，已成劳损。夫精、气、神为人身三宝，一有所伤，便为大患，况三者皆虚乎！敢谢不敏，幸熟察焉。", "13629": "仁渊曰：此编集痰饮咳嗽，五脏阴阳偏虚之证，非尽属虚劳也。若虚劳证，经谓：有所劳倦，形气衰少，谷气不盛，上焦不行，下脘不通，胃气热，热气熏胸中，故内热。言努力劳倦，伤其中气，致中气衰少，不能布化水谷，肺经治节不行，热气蕴于胸中，不得发越而生内热，乃伤脾胃氤氲之气也。治曰：劳者温之。《金匮》曰：男子平人脉大为劳，极虚亦为劳。遗精、失血、盗汗，劳之病也。治以桂枝龙牡、小建中、黄耆建中等汤，即祖《内经》劳者温之之法。巠巠相传，后人莫得异议。然余窃有疑焉。盖《内经》之所谓劳，乃劳伤其中气也。故以酸甘温煦之药，温之补之，使卫旺生营，脾胃阴阳之气有所依赖，则虚可补，劳可复。若《金匮》则相火旺而遗精，阴精虚而火升失血，热蒸于营而盗汗，亦用甘酸温煦以养之。一则伤其中气，一则损其精血，病不同而治则同，此何故也？近世治法，于劳倦伤中者，祖仲景、东垣。于遗精失血者，不敢祖桂枝、建中等法，都从事于朱丹溪、葛可久滋阴之法，亦始效而终不效。良以苦寒滋降，能平炎上之火，易伤中焦之气，胃气一伤，百药莫治，故越人有上损及中，下损及中皆不可治之说。然则丹溪、可久既不可恃，《金匮》方究竟可用否？曰：仲景为千古医祖，非贻误后人者。若内伤劳倦，于仲景、东垣法不得异议。若遗精失血，自元明后诸贤无敢用其方者，诚以相火方炎，阴血上溢，投以刚热，恐益其势耳。昔人聪明才智，岂逊于今，必有试而不合者矣。议者多疵丹溪，余则不敢出违心之论。盖滋降之法，可暂用，不可久用。审其胃气元气可任，暂投以平炎上之火，止其逆流之血，亦治之必须。否则温既助火，凉则伤中，日从事于轻描淡写，坐以待毙，亦何取乎！俟血止火降后，以甘平味厚固精纳气之药以补养之。经曰：损者益之，精不足者，补之以味。《难经》曰：损其肾者益其精，损其肺者养其气。病伤精气者，仍从精气求之，庶于病情有益耳。", "13630": "叶血止咳不已，脉沉带数，其根犹未去也。盖气犹风也，血犹水也，咳则气逆不顺，血亦逆而不顺矣。经络不和，血不宁静，必降其气而后血不复升，亦必充其阴而后火乃退耳。", "13631": "侯脉数血涌，胃气大虚。胸中痞塞，大便带溏，是痞为虚痞，数为虚数。咳血三月，今忽冲溢，唇白面青，断非实火。大凡实火吐血，宜清宜降；虚火吐血，宜补宜和。古人谓见痰休治痰，见血休治血，血久不止，宜胃药收功。今援引此例。", "13632": "又脉数退，血少止，而反恶寒汗出。盖血脱则气无所依，气属阳，主外，卫虚则不固也。最怕喘呃暴脱。犹幸胸痞已宽，稍能容纳。仿血脱益气例。经曰阳生阴长，是之谓耳。", "13633": "邢先天不足之体，曾发虚痰，溃而将敛。交春阳气升发，渐觉喉痒，咳嗽，二三日来，忽然吐血。今又大吐血，色鲜红。诊脉细促，心嘈若饥。一团虚火，炎炎莫御。用药虽已清降，亦当预顾真阴。否则恐血脱阴伤而晕。", "13634": "张阴虚内热，咳嗽痰红，脉数无神，渐延劳损。", "13635": "程咳嗽而至于失血音哑，津液枯槁，劳损成矣。脉形细弱，精气内亏。《内经》于针药所莫治者，调以甘药。《金匮》遵之而立黄耆建中汤，急建其中气，俾饮食增，津气旺，阳生阴长，而复其真阴之虚，盖舍此别无良法也。今仿其意而损益之。", "13636": "某始由寒饮咳嗽，继而化火动血。一二年来血证屡止屡发，而咳嗽不已，脉弦形瘦，饮邪未去，阴血已亏。安静则咳甚，劳动则气升。盖静则属阴，饮邪由阴生也；动则属阳，气升由火动也。阴虚痰饮，四字显然。拟金水六君同都气丸法，补肾之阴以纳气，化胃之痰以蠲饮。饮去则咳自减，气纳则火不升。", "13637": "范脉虚数，两尺愈虚。心肝脾胃俱受其病，惟肾独虚。心肝火亢，肺胃受戕，痰由湿生，血随气逆，咳嗽黄痰带血，掌中觉热。法宜养肾之阴，以清心肝之火，而肃肺胃之气。", "13638": "吕脉数左寸独锐，心经有火，吐血不止，法宜清养。", "13639": "庞去秋咳嗽，些微带血，已经调治而痊。交春吐血甚多，咳嗽至今不止，更兼寒热，朝轻晡甚，饮食少纳，头汗不休。真阴大亏，虚阳上亢，肺金受烁，脾胃伤戕，津液日益耗，元气日益损。脉沉细涩，口腻而干。虚极成劳，难为力矣。姑拟生脉六君子汤，保肺清金，调元益气。扶过夏令再议。", "13640": "生脉散保肺清金。六君子去术嫌其燥，加扁豆培养脾阴，土旺自能生金也。不用养阴退热之药，一恐滋则腻肠，一恐凉则妨胃耳。从来久病总以胃气为本，经云有胃则生，此其道也。", "13641": "薛吐血鼻血，牙血发斑，斑中出血，阳明之火极炽。而腹满濡软，少阴之气不运。病已三月，血有间断，有瘀血在腹中故也。食少，身热，脉数，其阴已虚。拟养阴化瘀，清胃和中。", "13642": "薛痰饮久咳，咳伤肺络，失血。脉不数，舌苔白。不必过清。但顺气化痰，气顺则血自归经，痰化则咳嗽可止。", "13643": "华咳嗽内伤经络，吐血甚多。脉不数，身不热，口不渴，切勿见血投凉。法当益胃，拟理中加味。", "13644": "钱内则阴虚有火，外则寒邪深袭。失血咳嗽，又兼三疟，病已数月。疟来心口酸痛，胸腹空豁难过。经云：阳维为病苦寒热，阴维为病苦心痛。此阴阳营卫之偏虚也。拟黄耆建中法，和中脏之阴阳而调营卫。复合生脉保肺之阴，复脉保肾之阴。通盘合局，头头是道矣。", "13645": "郁历春夏秋，血症屡发。诊脉虚弱，形容清瘦，年方十七，精未充而早泄，阴失守而火升。异日难名之疾，恐应褚氏之言。治宜滋水降火，须自保养为要。", "13646": "朱肿胀已退，脉象较前稍大，汗出至膝而止。阳气有流通之象，阴湿有消化之机。今以温理中州，中州得运，庶几决渎流通，寒转为温，否转为泰矣。然须调养百日，庶无反复之虞。", "13647": "复面黧腹肿，脉沉而细。此脾肾之阳不化，水湿阻滞于中。症防加剧，姑且渗湿通阳。", "13648": "金风湿相搏，一身悉肿，咽痛发热，咳而脉浮，拟越脾法。", "13649": "杨脉沉，小便不利，面目肢体大腹阴囊悉肿，病属里水。鼻中流血，喉间略痛，肺家有郁热也。拟越婢汤。", "13650": "张痢后阳虚，水湿不化，腹满面浮足肿，而色青黄，脉来虚细。虑延臌胀重症。", "13651": "某痞块由大疟日久而结，多因水饮痰涎与气相搏而成。久则块散腹满，变为臌胀，所谓癖散成臌也。脉细如丝，重按至骨乃见弦象，是肝木乘脾也。口干，小便短少，是湿热不运也。匝月腹日加大，急宜疏通水道，泄木和中。", "13652": "某暑湿伏邪挟积，阻滞肠胃，中州不运，大腹骤满，腹中时痛，痛则大便黏腻，色红如痢，小水短少。脉沉滑数，是积之征也。拟大橘皮汤送下木香槟榔丸。", "13653": "又气与水相搏，大腹骤满，脉沉，小便不利，大便欲泄不泄。法以疏气逐水。", "13654": "张木旺乘脾，腹胀如鼓，形瘦脉细，症属瘅胀。法当温通。", "13655": "孙脾虚胀满，面浮足肿，小便不利。脉形细数，元气大亏。虑其喘急之变。", "13656": "杨两尺脉滑，湿热积滞在于下焦。小便不利，大腹胀满，是下焦不利，中焦气不通也。", "13657": "渊按：水寒血气凝聚冲脉之分，果是实证，此方必效。", "13658": "金气从少腹上冲咽嗌，则心中跳，胁中痛，初起寒热而呕，此奔豚气之挟肝邪者也。半月以来，寒热虽止，气仍上逆。脉沉弦小。宜宗《金匮》法。", "13659": "丁久患休息痢，止数日后气攻胸脘板痛，上下不通，几至发厥，须大便通始减其痛。匝月大便仅通三次。板痛者聚而成块，偏于右部，是脾之积也。脉沉紧而细，当与温通。", "13660": "唐经停十月，腹微满，脉沉细涩，脐上心下块长数寸，是属伏梁，因七情恚怒气郁痰凝所致。经曰：大积大聚，其可犯也，衰其大半而止。洁古谓：养正积自除，不得过用克伐。今拟开郁正元散法，理气行血，和脾化痰，寓消于补之中。", "13661": "钱少腹有块，痛则经来如注，气升如喘。冲脉久伤，肝木肆横。", "13662": "钱脉微细，阴之象也。少腹有块，上攻及脘，自脘至嗌一条气塞，发作则大痛欲厥，头汗如雨。用方大法，固宜以温通为主矣。惟舌有黄腻浊苔，便泄臭秽，必兼湿热，而块痛得按稍减，中气又虚，方法极难周顾，尚祈斟酌是荷。", "13663": "又下焦浊阴之气，上干清阳之位。少腹胸胁有块，攻撑作痛，痛甚发厥。昨用温通，病势稍减，脉仍微细，泄仍臭秽，恶谷厌纳，中气大亏，阴气凝结，当脐硬痛。恐属脏结，攻之不可，补之亦难，诚为棘手。", "13664": "丁脉迟细，脘中有块，纳食撑胀，腹中漉漉作声，嗳腐吞酸，大便坚结。此脾胃有寒积也。当以温药下之，仿温脾法。", "13665": "洪结癖累累，久踞腹中。年逾六旬，元气下虚，中气已弱，肝气肆横，腹渐胀满。脉沉弦细，细而沉为虚为寒，沉而弦为气为郁。病关情志，非湿热积滞可比，攻消克伐难施。拟商通补。补者补其虚，通者通其气。", "13666": "冯脉右关滑动，舌苔黄白而腻，是痰积在中焦也。左关弦搏，肝木气旺，故左肋斜至脐下有梗一条，按之觉硬，乃肝气入络所结。尺寸脉俱微缓，泄痢一载，气血两亏。补之无益，攻之不可，而病根终莫能拔。根者何？痰积，湿热，肝气也。夫湿热、痰积，须借元气以运行。洁古所谓养正积自除，脾胃健则湿热自化，原指久病而言。此病不谓不久，然则攻消克伐何敢妄施。兹择性味不猛而能通能化者用之。", "13667": "丁血虚木横，两胁气撑痛，腹中有块，心荡而寒热。病根日久，损及奇经。经云：冲脉为病，逆气里急，任脉为病，男疝女瘕。阳维为病苦寒热；阴维为病苦心痛。合而参之，谓非奇经之病乎？调之不易。", "13668": "范素有肝胃气痛，兼挟寒积。脘腹胀满，痛及于腰，咳不可忍，舌苔白腻，渴不欲饮，大便似利不利，脉沉弦而紧。恐属脏结，颇为险候。非温不能通其阳，非下不能破其结，仿许学士温脾法。", "13669": "又两投温下，大便仍然不通。胸腹高突，汤水下咽辄吐，肢渐冷，脉渐细，鼻煽额汗，厥脱可忧。按结胸、脏结之分，在乎有寒热、无寒热为别。下之不通，胀满愈甚，乃太阴脾脏受戕，清阳失于转运。崔行功有枳实理中一法，取其转运中阳，通便在是，挽回厥脱亦在是，惟高明裁酌之。", "13670": "又腹痛，下午则胀，脉沉弦。此属虚寒挟积。前用温下，痛势稍减。今以温中化积。", "13671": "又腹痛三年，时作时止，寒在中焦，当与温化无疑。然脉小弦滑，必有宿积。前用温下、温通两法，病虽减而未定。据云每交午月其痛倍甚，则兼湿热，故脉浮小而沉大，按之有力，此为阴中伏阳也。当利少阴之枢，温厥阴之气，运太阴之滞，更参滑以去著法。", "13672": "渊按：既知宿积，何不再进温下？三年之病，谅非久虚。脉浮小沉大，乃积伏下焦。盖痛则气聚于下，故脉见沉大。此论似是而非。", "13673": "又腹痛，左脉弦，木克土也。仲景云：腹痛脉弦者，小建中汤主之。若不止者，小柴胡汤。所以疏土中之木也。余前用四逆散，即是此意。然三年腹痛，痛时得食稍安，究属中虚，而漉漉有声，或兼水饮。今拟建中法加椒目，去其水饮，再观动静。", "13674": "又用建中法，痛势上攻及胃脘，连于心下，左脉独弦滑，是肝邪乘胃也。姑拟疏肝。", "13675": "又用五积合通圣温通散寒，便通而痛未止。脉迟，喜食甜味，痛在当脐，后连及腰，身常懔懔恶寒。此中虚阳弱，寒积内停。拟通阳以破其沉寒，益火以消其阴翳。", "13676": "某自咸丰四年秋季，饱食睡卧起病，今已五载。过投消积破气之药，中气伤戕。脘间窒痛，得食则安，不能嗳气，亦不易转矢气，脉迟弦。肝胃不和，阳虚寒聚于中。拟通阳泄木法。", "13677": "钱脉微细，阴之象也。少腹有块，上攻及脘，自脘至嗌一条气塞，发作则块攻大痛欲厥，头汗如雨。用方大法，温通无疑。惟舌黄腻浊苔，便泄臭秽，必兼湿热；而块痛得按稍减，又属虚象。", "13678": "又水饮痰涎与下焦浊阴之气，盘踞于中。中脘腹胁有块，攻撑作痛，痛甚发厥。昨用温通，痛势稍减。但脉仍微细，泄仍臭秽，谷食厌纳，中气大虚，阴气凝结，当脐硬痛，恐属脏结。攻之不可，补之亦难，仍为棘手。", "13679": "仁渊曰：脘痛属胃，腹痛属脾。吞酸呕苦，俗名肝气，乃积饮病也。或得之喜餐生冷，或忧思郁结。夫肝胆属木而喜升达，寄根于土。今脾胃为生冷忧思伤其阳和之气，布化转运失职，肝胆无温润升达之机，郁久而肆其横逆，侮其所胜，脾胃受克，气机与痰饮凝滞于中脘，故作痛耳。其吞酸呕苦者，脾寒不化，胃中之水饮停积，如食物置器中不动，其味变焉。稼穑味甘，今胃不能化，木乘其胜，而齐木之味，化而为酸，齐胆火之味，化而为苦。木气冲逆，泛呕不已，久久积饮成囊，亦生癖块。由餐凉而起者，尚可治；由七情而起者，每成噎膈。盖忧思既久，中阳受伤，呕多胃汁槁枯，始则阳气伤，继则阴津竭，营卫少生化之源，胃管干瘪，肠液不充矣。徒恃医药无益，须怡神静养。治法喻氏进退黄连汤，最有深意，辛以化胃，苦以降逆，所谓能变胃而不受胃变也。罗谦甫治中汤亦合，用金以制木。若南阳之栝蒌薤白等，或辛或苦，或通或润，皆可用，务在通中焦阳气，使脾胃之阴凝开，肝木之郁结达，其痛自已。若腹痛须分部位，当脐太阴，脐旁少阴，少腹厥阴。尤宜辨寒热虚实，大抵寒多热少，虚多实少，热者多实，虚者多寒。《内经·举痛论》：寒者八九，热者一二，须从脉证细辨焉。湿郁之年，亦多是证，亦脾胃为寒湿所郁，阳气不得宣化耳。", "13680": "丁脉形弦硬。春令见此，是即但弦无胃。纳食哽痛，大便坚燥，已见木火亢逆，胃汁肠液干枯，治之不易。", "13681": "陈丧子悲伤，气逆发厥，左脉沉数不利，是肝之气郁，血少不泽也。右关及寸滑搏，为痰为火，肺胃之气失降，肝木之火上逆，将水谷津液蒸酿为痰，阻塞气道，故咽喉胸膈若有阻碍，纳食有时呕噎也。夫五志过极，多从火化，哭泣无泪，目涩昏花，皆属阳亢而阴不上承。目前治法，不外顺气降火，复入清金平木。", "13682": "徐气郁于胸为膈，气滞于腹为臌。饮食不纳，形肉顿瘦。阴气凝聚，阳气汩没。脉细如丝。姑与培土、通阳、化气一法。", "13683": "沈食下则饱胀，作酸呕吐，病属反胃。胃脉浮按则紧，沉按则弦。弦者木侮土，紧者寒在中。", "13684": "许吐血后呃逆，迄今一月。舌白腻，右脉沉滑，左脉细弱。其呃之气自少腹上冲，乃瘀血挟痰浊阻于肺胃之络，下焦冲脉相火上逆，鼓动其痰，则呃作矣。酌方必有济，幸勿躁急为嘱。", "13685": "朱脉滑大，食入哽噎不下，舌腻，此属痰膈，大肠燥火凝结。拟清痰火，佐以宣通。", "13686": "孔先曾呕血，胃中空虚，寒饮停留，阳气不通，水谷不化，食入呕吐酸水，谷食随之而出。脉细肢寒，阳微已甚。证成翻胃，虑延脾败难治。", "13687": "查脉沉细数而涩，血虚气郁，经事不来。夫五志郁极，皆从火化。饥而善食，小溲如脓，三消之渐。然胸痛吐酸水，肝郁无疑。", "13688": "又服药后，大便之坚难者化溏粪而出，原得苦泄之功也。然脉仍数涩，郁热日盛，脏阴日消。舌红而碎，口渴消饮，血日干而火日炽。头眩、目花、带下、皆阴虚阳亢之征。当寓清泄于补正之中。", "13689": "朱脉左寸关搏数，心肝之火极炽。口干，小溲频数而浑浊，此下消症也。久有脚气，湿热蕴于下焦。拟清心肝之火，而化肾与膀胱之湿。", "13690": "潘肛有漏疡，阴津先损于下。兼以嗜酒，湿热又盛于中。继因劳碌感寒，寒入肺经，与胸中素盛之痰湿相合，咳嗽，呕吐清水，而成痰饮为患。仍饮烧酒祛寒，宜其血溢矣。况内热脉数，阴津亦亏。欲蠲痰饮，恐温则劫其阴；欲除内热，恐清则加其咳。宜和胃降气。", "13691": "又咳呕清水，痰饮之病。脉细数，内热，阴虚之候。治痰饮宜温，治阴虚宜滋，药适相背。肝肾为子母，不妨补母以益子；而胃土又为肺金之母，又当和胃以化痰。拟滋燥兼行，仿东垣法而不碍。", "13692": "王脉弦迟，脐以上连胃脘胀痛，此有寒饮。《脉经》云：迟则为寒。仲景云：口不渴而脉双弦者，饮也。", "13693": "又当脐腹痛，痛则气塞胸中，气嗳不得语，脉弦大而迟。此胃中阳气不足，而有寒饮也。当以温药通之。", "13694": "顾头眩心悸，脉沉弦者，饮也。病发则呕吐酸水，满背气攻作痛，得嗳则痛松，此浊阴之气上攻阳位。当以温药和之。", "13695": "强中气不足，湿化为痰，气逆不降，喘息不安，夜重于昼。脉象弦滑，滑主痰饮，痰饮属阴，故病甚于夜也。拟降气化痰，兼扶中气。", "13696": "某春脉当弦而反微，是肝虚也。肝虚魂不藏，夜不得寐，昼日当寤而反寐，是胃虚也。胃为两阳合明之腑，胃虚则阳气失明，故昼日反寐。补肝之虚以藏魂，益胃之虚以补气。", "13697": "单痰饮久留，咳喘不已。痰多黏腻，脾肾两亏。脾虚则痰不化而食减，肾虚则阳气衰而水泛，以致腹满足肿面浮，病成溢饮。《金匮》云：病溢饮者，当发其汗，小青龙汤主之。然脉细阳衰，便难液涸，肾气久虚，何堪更投发泄耗阴伤阳之剂！拟进附子都气丸，裁去熟地者，以其痰多痞塞也。", "13698": "孙风邪久恋肺中，寒饮停留胃脘。风能化热，咳久伤阴。积饮生痰，胃阳失布。肺之子，肾也。胃之妻，脾也。肺伤肾亦亏，胃虚脾亦弱。脾弱故便泄，肾亏故左尺脉弦而大也。咳将一载，虽曾吐血，而时呕清水，其为寒饮无疑。今从饮门例治。", "13699": "顾嗜酒多湿，湿蕴生痰。体质阴虚，烦劳伤气。去冬咳嗽，须微带血，行动气升，至今不愈。诊脉虚小，恐加喘急。兹以金水六君煎加味。", "13700": "方向有心痛呕吐之病，得食则安，明系中虚而有痰饮伏留于心下也。上年春季，头痛寒热，从此咳嗽喉有痰声。当时设遇明眼，用小青龙发汗散水，表邪与痰饮悉解，何至淹缠不愈耶！迨至酷暑，邪郁化热，咳嗽带臭，肺气受伤。交白露节，秋金得令，肺气清肃而后渐愈。至冬阳气少藏，其咳复作。交春入夏，咳频不已，病延一载有余。诊脉双弦，形肉瘦削，口不干渴，身不发热，头眩心悸，肝肾之阴已虚，脾胃之气亦弱，痰饮恋而未化，自浅及于深矣。昔贤谓外饮治脾肺，内饮治肾。今自外而至于内，从肺脾肾三经立法，前后绾照，以冀各得其所。", "13701": "又脘胁之痛虽除，脾胃之气大惫。面浮足肿，土衰水泛，脉细少神，虑其腹满。急宜温补中阳以消水湿，又当自知节爱为上。", "13702": "仁渊曰：《内经》无痰饮证，并无痰字。痰饮之病，始于仲景，详于《金匮》。其论痰饮有四，曰痰饮，悬饮，支饮，溢饮。《千金》有五饮丸，治留饮，痰饮，溢饮，流饮，澼饮。明·李时珍即《金匮》四饮加伏饮为五饮。古人以胸胃肠间有水饮内积，即名曰饮。不必尽有咳嗽也。今人以咳嗽气逆，倚息不得卧，名之曰痰饮，乃《金匮》之支饮也。其余或已更名，如脘痛吐酸，即古之悬饮也。饮水不化，不得汗出，身体疼重浮肿，古之溢饮也。去古渐远，其名遂更。夫五饮之生，总由肺脾阳虚，致水饮入胃不能布化通调，停蓄胃肠之间，遂生种种病情。射肺则咳，凌心则悸，犯肝则胁痛眩冒，入肾则喘逆，侮脾则胀满痞闷，皆中上阳气不能布化之过也。然肺脾之阳虽虚，肾中之阳尚旺，其病犹可支持，故痰饮病有积延岁月而不死者。如此篇亦以咳嗽气逆为痰饮，然即以咳嗽气逆而论，其因多端，未必尽属痰饮也。大抵痰饮咳嗽，其痰多沫，其气多逆，其脉多弦、多滑，其心多悸荡，其头多眩冒，其表畏寒，冬发夏愈，其口不渴，其舌苔多白，此痰饮咳嗽之状也。治法，《金匮》要言不繁曰：须以温药和之。盖无论何饮，化其中上焦之阳气为先，而肾气丸一方，即开后人内饮治肾之门。故后人有外饮治肺脾，内饮治肝肾之说。盖饮邪久延，穷而伤肾，肾阳虚而肾气上奔，非温纳补摄不效。后贤之人参蛤蚧，黑锡丹，天真丸等，都从肾气丸得来，为温纳肾气之法。若得病之由，或冒冷雨，或卧而受凉，或过饮伤其肺脾，非一端耳。", "13703": "六味地黄合生脉散，加青铅。", "13704": "冯年逾七旬，伏暑挟湿，湿能生热。病起微寒微热，咳嗽痰稠，曾经吐血。今血虽止而咳仍然，脉涩而数，舌苔灰白而渴，乃湿热痰浊恋于肺胃。病将匝月，元气大伤。脾胃不醒，谷食少进。初起大便坚，今则软而带溏矣。病在肺脾胃三经，治在化痰、降气、和中。", "13705": "又夫咳嗽痰喘之病，浅则在肺胃，深则属肝肾。凡用方之法，由浅而深。按脉察色，知其虚中挟实。实者，痰浊也，故先以化痰、降气、和中为法。两剂，咳嗽稍平，惟气之喘而短者有出多纳少之意，则其本虚矣。左脉细微，肝肾之虚大著。虽舌苔黄浊不化，亦当以摄纳为要。且额上汗冷，胃泛不纳，将有虚脱之虑。", "13706": "上三味，各研末，和一处，再研细，分作二服。今晚一服，燕窝汤调下。明日再进一服。若得额汗收敛，左脉稍起，犹有生机可理。若不应手，难为力矣。", "13707": "又喘哮频发，脉形细数，身常恶寒。下焦阴虚，中焦痰盛，上焦肺弱。肺弱故畏寒，阴虚故脉数。喘之频发，痰之盛也。有所感触，则病发焉。病有三层，治有三法。层层护卫，法法兼到。终年常服，庶几见效，否恐无益也。", "13708": "叶喘之标在肺，喘之本在肾。脉迟者，寒也。舌白者，痰也。以金水六君煎加味。", "13709": "又周身之汗已收，头汗之多未敛。气喘较前觉重，交午愈甚。掌心觉热，脉形细数，饮食减少。阴津大亏，肺气伤戕。兹当炎暑，水衰火旺，金受其灼。咳嗽痰黄，渐延损症。拟清金丽水，冀其应手为妙。", "13710": "仁渊曰：痰喘之因不一，须分虚实两途。实者因风寒痰火，大都病在肺胃，从外感而来，或寒热无汗，或不热有汗，咳嗽痰浓，便溺短赤，舌苔厚，脉数浮滑不空，乃风温痰热壅于肺胃不得降化也。宜宣通肺络，清降胃气。有汗葶、杏、橘、贝、芩、翘、石膏等剂，无汗麻杏甘石、桑、贝、橘、桔之类。若形寒表热不扬，咳窒不爽，脉浮而紧，乃风寒闭其肺络，元府不宣，肺气不利，不得肃降也。宜麻、杏、苏、桔或防风通圣等开其腠理。虚者乃平素肺肾内虚，肃降摄纳无权，脾胃气弱，不克化饮食精微，即痰饮之类。痰留肺系胃络，一触外邪，肺胃即失顺降，肾气即为奔逆，喉间嗘吼有声，倚几布息，甚至自汗淋漓，无表热外感见证，脉浮滑空豁，或形瘦浮肿，种种虚象，宜温纳镇摄。又有半虚半实之证，如素有痰饮，感寒遇劳即发，咳嗽痰沫，喘逆倚息。仿痰饮例治之，若久病全属虚证。更有无痰而喘，火迫而喘，糖哮盐哮而喘，俱伤其肺气使然。当求其因。古人谓实喘治肺，虚喘治肾，确有见地，然不可执一。实喘治肺，须兼治胃；虚喘治肾，宜兼治肺。如肾气丸、黑锡丹治肾，人参蛤蚧汤治肺，人参胡桃汤肺肾兼治也。大抵痰多，脉空弦者，以肾为主。痰少，脉虚不甚大者，以肺为主。痰稀多沫者，宜温纳，痰少色黄厚者，宜平降。一则肾阳虚，一则肾阴虚而肺有火也。夫熟地最能消虚痰，以其能填补肾气而化无形之痰也。勿嫌腻膈而畏之。", "13711": "张十年前三疟之后，盗汗常出，阴津大伤。去秋咳嗽气升，痰中带血。至今行动气喘，内热多汗，食少无力，脉虚细数，劳损根深。", "13712": "又盗汗气喘，咳嗽脉细。精气两虚，舍补摄肺肾之外，更将何法以治！景岳云：大虚之症即微补尚难见效，而况于不补乎？", "13713": "又脉数未退，阴虚未复。咳嗽不止，肺气日虚。夏暑将临，病尚未稳，仍宜小心安养为要。", "13714": "唐七旬有六之年，面色红润，脉形坚搏，外似有余，里实不足。屡患咳嗽，娇脏暗伤。本月初旬微感风温，咳嗽又作。舌苔薄白，底有裂纹，饮食略减。风温久恋，劫胃津，灼肺阴。不可再投辛散，当以甘润生津。", "13715": "李咳嗽喉痒，痰或稀或浓，浓则腥臭。脉象右弦而滑，左弦小数。肝经有郁勃之热，肺家有胶黏之痰。此痰为火郁而臭，并非肺痈可比。当以平肝开郁，参清金化痰。", "13716": "许咳嗽面白为金伤，脉数而洪属虚火，是脉克色而火胜金也。夏至一阴生，正属火令，为剥极则复之际。倘若剥而不复，颇有火灼金销之虑。", "13717": "此生脉散合六君子汤加紫菀。夫四君去术加黄耆、山药、陈皮，亦名六君，在《医方集解》中。", "13718": "王暑风从背俞而内薄于肺，湿热从胃脉而上注于肺，外内合邪，其气并于胸中，气不得通，因而上逆，气升作咳。舌苔薄白，口腻不渴，治属饮家。", "13719": "阙体弱素亏，频年屡患咳嗽。今春产后悲伤，咳嗽复作，背寒内热，气逆痰多，脉虚数，大便溏。延今百日，病成蓐劳。按产后血舍空虚，八脉之气先伤于下，加以悲哀伤肺，咳嗽震动，冲脉之气上逆。经云：冲脉为病，逆气里急。阳维为病苦寒热。频进疏风清热，脾胃再伤，以致腹痛便溏，食减无味，斯皆见咳治咳之弊。越人谓上损及脾，下损过胃，俱属难治。姑拟通补奇经，镇摄冲脉，复入扶脾理肺。未能免俗，聊复尔尔。", "13720": "戴五脏皆有咳，总不离乎肺。肺为娇脏，不耐邪侵，感寒则咳，受热则咳，初起微有寒热，必夹表邪。邪恋肺虚，脉形空大。前方降气化痰，保肺涤饮，俱无少效。据云得汗则身体轻快，想由肺气虽虚，留邪未尽。补虚而兼化邪，亦一法也。用钱氏法。", "13721": "沈脉虚软而似数，内伤虚弱奚疑！夫邪之所凑，其气必虚。虚处受邪，其病则实。咳嗽虽由外感，而实则因于气虚。以为风寒固不可，以为虚损未必可。玉竹饮子主之。", "13722": "仁渊曰：咳嗽一证，最为难治。外感固不可擅用清滋，即内伤之咳，亦未可擅用冬、地，须察其病因在何脏腑而施治。疗久咳必先顾其胃气，未有胃不顺而咳可愈者。经谓：十二经皆有咳，非独肺也。皮毛者，肺之合也。皮毛先受邪气，邪气以从其合也。其寒饮食入胃，则肺寒。肺寒则内外合邪，因而客之，则为肺咳。此言外感之咳，从感寒饮寒而起，邪由皮毛而内合于肺，或散或温或凉，从肺主治。其饮热受热者，亦可隅反。若内伤之咳，则五脏十二经皆有，断不可专治其肺。盖咳在肺，所以致咳不在肺。五脏六腑苟有一气之逆，触动肺气，即能作咳。医经旨「聚于胃、关于肺」二语，深得咳嗽要言。夫胃有五窍，如闾里门户。水谷入胃，渣滓由下脘传小肠，水液即从旁窍而出，传布三焦，由中焦蒸化，至上焦为津液，渗下焦为便溺。今脏腑之气失顺，逆击于肺作咳，胃窍之水饮不能尽化津液，聚于上脘而为痰涎，寒则痰稀，热则痰浓。前人论脾乃生痰之源，肺为贮痰之器。今读西国医书，谓咳痰不从肺出，即从胃脘而来。证以经文「聚于胃、关于肺」二语，始知前人所论非是。按前贤论咳嗽者甚多，至「聚于胃」三字，从未论及，岂《内经》此言漫无著落耶？今得西医剖视之书，益见《内经》之精。至何脏何腑之逆，虚实之辨，当详参脉证。经文于此尤为精细，不难按证用药。兹集外感内伤为一编，读者宜细绎之，勿混治也。", "13723": "仁渊曰：古人谓七疝都隶于肝，以少腹前阴皆厥阴经脉部位故也。湿热寒邪袭郁厥少而成疝，此言诚是。然余谓病标在肝，病本在脾肾。盖厥阴风木，寄体在土，滋灌赖水。苟日暄雨润燥湿得宜，欣欣向荣，何疝之有？惟水寒土湿，木失其荣，藏舍空而经络虚，始寒湿、热湿之邪乘虚袭入；邪郁不化，木不条达，愈郁愈横，于是将军之性猝发难遏，其气不得升达，横塞本位经脉之间而作疝也。所以不涉他部者，他脏尚不虚耳。冲心则死，亦以心阳大虚，寒邪得以直犯君主耳。气体实而标邪盛者，其治尚易；惟积年累月，邪虽不重，而脏真大虚，一切苦寒辛通之药，未可径施，施亦未必效验，最为难疗。若治疝都用辛通温散入方者，不独散其寒，亦所以通其气耳。通则不痛，痛则不通，是之谓乎！", "13724": "须精浊连年不断，兼有血块淋漓。肝肾大虚，八脉无以固摄，湿热混乱不清。舌苔白腻。法当脾肾双补，固摄下焦。", "13725": "渊按：肝肾八脉之虚，由湿浊混淆，精血频下。若不先清湿热以宁相火，徒事补肾固精，所谓不清其源而欲塞其流，能乎否乎？", "13726": "丁水窍精窍，异路同门，二窍不并开。水窍开则湿热常泄，相火常宁，精窍常闭。若水窍为败精瘀浊阻塞不通，则湿热不泄。病已二载，颇服滋补，使湿热败浊漫无出路，致下焦浊气上攻及胃，时时嗳气，腹中不和，二便不爽，失下行为顺之理。诊脉细肢寒，肾阳与胃阳不布。法宜通阳渗湿，益肾化浊。", "13727": "薛左尺极细，寸关微而似数，右三部俱弦滑。下有遗精暗疾，肛门痒而出水；上则头眩耳鸣，舌苔粉白。以脉合症，肾阴下亏，湿热相火下淫上混，清窍为之蒙闭。法当补肾之阴而清相火，清金和胃，分利膀胱以化湿热。", "13728": "高脉细固属阴虚，若下垂尺泽，是相火下淫，故精血下流，小溲便数，溺窍疼痛，大便干结也。补养肾阴，兼清相火为法。", "13729": "张操觚莲幕，形逸心劳。肾水下亏不能上承于心，心阳内亢而反下趋于肾，即坎离之不交也。不交则诸病生，由是而下为淋浊尿血，宗筋绊痛；上为眩晕咳嗽，心中震跃，诊脉左小右大，内伤虚症何疑！今远道初归，跋涉劳顿，且拟和平补益，庶无畸重畸轻之病。", "13730": "又心阴耗损，君不制相，相火妄动，强阳常举，精浊时流，肛门气坠，大便溏薄，心中嘈辣，干嗽无痰。右脉空大，两尺皆虚。法宜补心阴以制相火，益肾气以固元精。", "13731": "袁疡脓之后，气血必虚。奔走烈日之中，汗出招风，风与热毒舍于皮肤脉络之间。至秋凉气外束，热郁于皮中，遂觉遍体瘙痒，几及两月。近来面色带黑而浮，少腹略满。据云奇痒之时，唇舌俱麻，是外风引动内风也。经云：面肿曰风。夫风行必燥，木胜克土，此症现为风癞，久防腹满，理势所必然也。", "13732": "胡脉软无力属气虚，便溏食少属脾虚，干咳无痰属肺虚，时觉口苦属心热移脾也。宜十补一清。", "13733": "潘年近六旬，天癸久去而反频来，是谓脱营。脱营者，元气极虚不能固摄，血从外脱也。又名下竭，故腰痛如折。下竭者必上厥，故面赤、火升、发热也。血属阴，阴虚则阳亢，故脉弦硬无情。其脉愈数，其阴愈虚。夏令一交，阳亢无制，恐致水涸龙飞，难为力矣。", "13734": "王经来半月不止，有紫血块，少腹疼痛，气坠阴门，诊脉沉涩，下午恶寒。阳陷入阴，营虚失守。法以升阳收摄其阴。", "13735": "陆营分有热，则经至而淋漓；卫分有寒，则脉小而迟缓。脾为营之本，胃为卫之源。经至而舌苔反布，胸无痞闷，是胃阳虚而无气以化浊也。拟醒胃阳以摄脾阴为法。", "13736": "又经行过多，血气两衰，肝肾失固，丽翁所论包括尽矣。然治病之道，有相机从事之权。夫舌白多痰，胃有浊也。咽干色红，阴虚而火浮也。脉细迟缓，中气不足也。考古人肾虚有痰浊者，金水六君煎；气虚而上有浮火者，生脉四君子。合而参之，似觉不可擅易，还祈晒政。", "13737": "又肝肾与脾胃同治，经漏仍然不止。左脉稍觉有力，原得归、地之功；右脉更觉细微，脾气虚衰不振。许学士谓补肾不如补脾，盖谓脾胃虚者言之。今心跳食少，心脾不足可知。经血如漏卮不息，冲任不得不固；腹中微痛，气虚且滞，不得不补，不得不通。仿黑归脾法。", "13738": "渊按：既云固冲任，而无固冲任之药。仍用归脾，恐漏仍不止。古人治崩漏急证，自有专方，如血余、棕炭、百草霜、倒挂尘等，殊有效验。且脉小迟缓，其漏未必属热，或脾肾阳虚，不能固摄其血，尤非固而兼温不效，未可见血即以为热也。", "13739": "王经后少腹痛连腰股，肛门气坠，大便不通，小便赤涩热痛。拟宣肝经之郁热，通络脉之凝涩。", "13740": "渊按：此经未尽而行房过度所致，乃经血乘虚入络，冲任入脉受伤也。", "13741": "某寒热无序，脉促数，下有淋带，上则心跳，又少腹痛，大便坚，面色萎黄，血瘀之候也。虑延劳损。", "13742": "王向有淋带，月前血崩，崩止淋滞不断，少腹板痛，脉象细数，身发寒热，脾胃大虚。此血瘀未尽，复兼肝气夹寒也。法当通补。", "13743": "仁渊曰：妇科首重调经。夫经乃心血与肾液相合而成，为天一之真水，故名天癸；按月而下，犹月魄之有盈虚，故名月信；不差时日，犹海水之有潮汐，故名月潮。夫月也，潮也，癸也，皆阴类也。然月魄不得日光丽照则不明，潮汐不得阳气鼓荡则不盛，其质虽阴，其用则阳。妇人经水之盛衰，亦犹是耳。叶天士云：妇女以心脾为立命之本，心生血，脾统血，心气旺则阴血自足，脾气盛则统驭有权，无愆期崩塞之病。今世医调经，动曰冲任八脉，皆言末而忘其本耳。夫冲为血海，任主胞胎，在女科原不可不讲，而经水之所以盛衰通塞，其根源不在乎是。《内经》言奇经之于十二经，犹江河之于沟渠也。江河充足，沟渠自盈溢。可知江河不充足，则沟渠涸竭窒塞矣。又可知江河充足，沟渠偶有不通不足，欲通之足之亦甚易矣。能知此理，断不以通瘀养血套剂了事。即带下一证，虽有阴虚、湿热之辨，亦莫非心脾之气不通不化而来。即症瘕、癖疝、鬼胎、肠覃等疾，虽由痰凝血滞，风寒闭塞，肝胆生阳不能布化，其因甚多，其根亦莫非心脾郁结所致。盖男子用阳而体阴，女手用阴而体阳。男子以肾为先天，女子以心为先天。心阳足则脾阳亦旺，阳生阴长，血气充沛，乃宜男之兆。若心阳不振，则脾阳亦弱，肝木生生之气少布，饮食少化，聚湿生饮，肝气郁陷而逆升，为气撑饱胀，为脘痛作呕，或错经妄行而鼻衄，或脾气下陷而崩漏，或风寒瘀污客于子门冲任，为鬼胎、石瘕，种种病情，相引而至。盖有形之病皆属阴邪，大抵阳气不化而生，断非通瘀行血所能了事也。", "13744": "张寒气客于下焦，瘀凝停于小腹中央，乃膀胱之部也。寒气瘀凝，阻塞胞门，膀胱阳气失化，以致癃闭。产后八日而小溲不通，脉细肢寒，腹中觉冷，恐其气逆上攻发厥。法以温通下焦，化瘀利水。", "13745": "某左脉细数，营阴亏也；右脉细软，脾气虚也。产后不能安息，反加劳碌，气血伤而不复，致身常内热，心荡若嘈，久延虑成劳损。人参养营汤加减。", "13746": "孙前年小产，恶露数日即止，因而腹中作痛结块，心神妄乱，言语如癫。此谓血风病也。胞络下连血海，上系心包，血凝动火，火炽生风，故见诸症。诊脉弦搏，肝阳有上亢之象，防加吐血。为治之法，当以化瘀为先，清火化痰为佐。", "13747": "章先痉厥半日而后产，产后厥仍不醒，痉仍不止，恶露稀少，汤水不能纳，纳则仍复吐出，面赤身温，脉洪而荒。肝风炽张，营虚气耗，虚阳外越，冷汗遂出，恐其厥而不返，奈何奈何！姑拟一方，希冀万一。", "13748": "渊按：脉荒者，乱也。究属杜撰。虚风挟痰上逆，化痰降火，冲入童便最妙。", "13749": "又前方勉灌三分之一，恶露稍多，面赤稍退，脉大稍软，而厥仍不醒，舌色灰黄，时沃涎沫，两日饮食不进。营虚气滞，胃虚浊泛。必得温通化浊，以冀阳回厥醒为妙。", "13750": "范产未满月操作，猝遇大雨淋身，水寒之气自毛窍而入于骨节，内舍于肾，外达太阳、阳明，是以始病腰疼，继而上攻头痛，遍体机关不利也。脉沉而寒热，寐少而恐惧，纳少而恶心，邪气留连于胃肾。据云头痛甚则汗出，太阳之表虚矣。用许学士法。", "13751": "仁渊曰：产后病最难治，最多变证，难以殚述。朱丹溪云：产后以大补为主，虽有别证，从未治之。此言虽是，亦未可泥。有少壮之妇素体不虚，或兼外感六淫，内阻瘀滞，当见证治证。若执产后须补之论，不但本病不退，势必转增他变。盖新产百脉虽虚，感邪则实，急去其邪，即所以养其正也。倘遇可攻可下之证，即白虎、承气不为过。胎前亦然。惟下笔切宜仔细，未可率意轻忽。心中须念此产后虚体，若一击而中，便与轻松调理。果是纯虚，自当大补，补之有方，不可集几味养血套剂便为了事。再者，胎前温药宜慎，产后凉药宜慎。谚云：胎前一把火，产后一块冰。虽未尽然，却也不差。盖胎前多实，实者多热，产后多虚，虚者多寒，理固然也。", "13752": "仁渊曰：幼儿不能明告病情，脉亦难凭，虽以一指按寸口，惟得浮沉迟数大略而已，故称哑科。四诊只得其二，惟察声望色，询之乳母，得其梗概，最为难看。而难中亦有易焉。易者何？乃三因之中绝少内因，大都外感六淫、内伤乳食而已。即有内伤，亦因病致虚，非七情六欲因虚致病者可比。苟仔细详审，不难得其要领。近世风气之最坏者，莫若挑惊。不问外感内伤，概以惊风呼之，非推即挑，继以牛黄、脑、麝香开之药。明理之家亦蹈此习，不知冤杀多少婴儿矣。夫惊病偶亦有之，儿体脆弱，魂魄未坚，猝见异言异服及奇怪之物，惊恐惶骇，此必有因。须将惊风二字拆开，惊自惊，风自风，断不可混治。夫惊乃惊骇受病，风为温热所化，或感触风邪，治判天渊。喻氏云：幼科与大方一理，苟请伤寒名家视之，断无错误。此乃见道之言。夫六淫之邪，皆能化火。幼儿病热者多，病寒者少，由阴气未充，生阳正旺，化火尤易耳。为父母者，每未寒先衣，未饥先食，食不化即变为痰，痰与风热相并，最易痉厥，俗医即呼为惊风，病家亦认为惊风，非一日矣。吾愿同志大发慈悲，相与挽此颓风，功德无量。", "13753": "刘偏脑疽自右延及于左，三候有余。偏右穿溃脓少，偏左木肿未腐，头顶平塌，根脚散蔓。此气虚不能引血化腐成脓，托毒外出，高年殊虑内陷。至舌苔白腻，大便闭结，在疡科指为火毒内闭，湿热上蕴，而用内疏黄连等法。阅倪先生方案，谓内夹杂气，邪伏膜原，引用达原、三消数剂，异想超出寻常。今大便已通，舌苔稍化，然右脉软弱，胃气残惫，疡不甚肿，色不甚红，深恐阳变为阴。大凡外疡起发脓腐，须赖元气承载。所谓元气者，卫外捍御之气、胃中冲和之气、三焦升降之气也。亏则脓腐不克依期，从此生变。故黄耆为外疡托毒之圣药，即兼别症，再参他方。古法有攻补兼施、补泻同用者。拙见欲托毒，必扶正。", "13754": "张怒则肝气逆而血苑于上，章门结块硬痛，寒热脉数，小便短少。症属肝痈，防其内溃咳吐脓血而剧。", "13755": "缪病起微寒微热，右肋章门穴酸疼。两月后痛处略肿，食少便溏，面浮足肿，腰脊酸痛。脉附骨极细而锐。此脾家有湿热瘀伤，症属脾痈。日久正虚胃弱，恐其不克支持。", "13756": "又肠内痈脓将足，脉细食少。治以托里，冀其外溃为妙。", "13757": "刘肾俞漫肿色白，脉虚微热，此肾俞发也。属三阴亏损，湿热入络，气血凝滞而生。最为淹缠。姑与消散法。", "13758": "胡胃脘生痈，脉虚形瘦。初起寒热，延今四十余日，晨必泄泻无度。是中气大虚，不胜攻消之任也。今与内托法。倘仍作泻，则难矣。", "13759": "许肝胆郁火，凝结成痰。腮颊硬肿，牙关不开，此骨槽痰也。脉象郁涩，气失利畅，药力不易见效。", "13760": "汪《内经》云：一阴一阳结，谓之喉痹。指少阴君火合少阳相火上逆而为病也。病由内生，非关外感风温，故治之不易速效。养阴降火化痰，每相须为法。惟嫌脉息太细，系素禀六阴，真阳不足。然清药亦宜酌用，恐阴未足而阳先伤耳。慎之。", "13761": "周咳吐臭痰，已延三月。脉数而虚，其阴已伤。面白无华，饮食渐减，肺失所恃，防成肺痿。", "13762": "又咳痰腥臭，面色青晦，脉数而虚，纳谷大减。此木火乘金，金伤及土，脏气克贼，恐延不治。", "13763": "某营行脉中，卫行脉外。体肥湿胜之人，卫恒虚冷，营多盛热。故肥人当暑，往往肌肤常冷，而易生外疡也。疡发背脊三候，内脓已结，外腐未透。营中之火极炽，卫弱失于敷布，不能引血化腐，载毒外出，渐显内陷之机，颇为可虑。非温不能助卫阳以鼓舞，非清不能解营热以化毒。经曰：血实宜决之，气虚宜掣引之。此法是矣。", "13764": "婺人罗元奎，丁亥夏卒发寒热，旋即呕吐不能立，自言胯间痛不可当。孟英视其痛处，焮赤肿硬，形如肥皂荚，横梗于毛际之左。乃曰：此证颇恶，然乘初起，可一击去之也。用金银花六两，生甘草一两，皂角刺五钱，水煎和酒服之。（眉批：予每以此法治阳证疮毒，莫不应手取效，真妙方也。）一剂减其势，再剂病若失。逾年患伤寒，孟英切脉，虚细已极。曰：此不可徒攻其病者，以阴分太亏耳。与景岳法，以熟地、当归、酒炒白芍、炙甘草、橘皮、柴胡等药，一剂而瘳。（此法予亦屡用获效，气虚者并可加参，但表药止柴胡一味，犹嫌力微。）", "13765": "海阳赵子升，辛卯夏病疟，急延孟英诊之。曰：暑热为患耳，不可胶守于小柴胡也。与白虎汤（专清暑邪。）一啜而瘥。甲午秋，范丽门患温疟，孟英用白虎加桂枝（清热兼驱风。）以痊之。丙申夏，盛少云病湿热疟，孟英以白虎加苍术汤（清热兼燥湿。）而安。己亥夏，予舅母患疟，服柴胡药二三帖后，汗出昏厥，妄语遗溺。或谓其体质素虚，虑有脱变，劝服独参汤，幸表弟寿者不敢遽进，乃邀孟英商焉。切其脉洪大滑数，曰：阳明暑疟也，与伤寒三阳合病同符。处竹叶石膏汤（清热兼益气，两剂而瘳。）庚子夏，滇人黄肖农自福清赴都，道出武林，患暑疟。孟英投白虎汤加西洋参（清热益气与前方意同。）数帖始愈。辛丑秋，顾味吾室人患瘴疟，孟英亦主是方而效。庄芝阶中翰张安人，年逾花甲，疟热甚炽，孟英审视再四，亦与竹叶石膏汤而安。闻者无不惊异，予谓：如此数证，体分南北，质有壮衰，苟非识证之明，焉能药与病相当而用皆适宜哉！", "13766": "钟耀辉年逾花甲，在都患肿。起自肾囊，气逆便溏，诸治不效，急买车返杭，托所亲谢金堂邀孟英治之。切其脉微而弱，（虚象显然。）询其溺清且长。曰：都中所服，其五苓、八正耶？抑肾气、五皮也？钟云：诚如君言，遍尝之矣，而病反日剧者何哉？孟英曰：此土虚不制水也。通利无功，滋阴亦谬。法宜补土胜湿，（此即张景岳所云理中加茯苓、附子之证也。）与大剂参、术，果即向安。越八载、以他疾终。", "13767": "孟英邃于医学，从不侈谈脉理，足以见其欿然不自足也。而脉理之最不易切者，莫如妊娠。予闻孟英于乙未春诊黄履吉室人之脉，曰：妊也。是月天癸犹来，人皆不以为然。次月仍转，但不多耳。复邀孟英诊之，曰：果妊也。汛不断者，荫胎之血有余耳。逾月汛复行，觉更少矣，人犹以为妄也。四月后经始停，娠亦显，娩如期，人始服其见老。丙申夏，满洲某选粤东盐场，携眷之任，过浙主于李云台家，请孟英视其如君之恙。孟英诊曰：非病也，熊罴入梦矣。某颇不信，谓经甫停何以遽断为孕？而又必其为男乎？反生言过其实之疑。既而某延云台入幕，偕赴粤任。次年云台于家书中述及居停果得子，深叹孟英指妙。予荆人久无孕，辛丑秋汛事偶愆，孟英一诊即以妊断，且以男许。次夏果举一子，惜不育耳。邵鱼竹给谏仲媳怀妊，孟英于寅春初诊即许抱孙。秋杪果应。表弟胡寿者室，偶有小忿，经事涩少，腰腹微胀，自以为怒气所滞也，延孟英调之。切其脉，曰：怀麟矣。初犹疑之，既而始信。卯春果弄璋。吴云阶室年四十余，寅秋汛断，其腹日胀，医谓病也，治之罔效。迓孟英诊之：孕也。彼犹不自信，及腹中渐动，始服其言。至期产一女。癸秋，孟英治石诵羲室，脘痛甫愈，适汛逾期，即曰：娠矣。既而果日形著，其指下之神妙如此。（眉批：娠孕之脉最为难凭，有初娠即现于脉者，有三四月始现于脉者，有始终不现于脉者。此与凭脉断证有时可凭，有时不足凭，同一至理。予尝以此质之孟英，孟英亦以为然。可见真学问人，必不恃虚言以眩世也。）", "13768": "朱恒山久患胸痞多痰，诸药罔瘳。孟英诊曰：清阳之气不司旋运也。与参、耆、苓、术之剂，豁然顿愈，因极钦服。后数年果以汗脱。闻其垂危之际，口不能言，犹以左手横三指，右手伸一指加于上，作王字状以示家人。有会其意者，急追孟英至，而他医之中风药早灌入矣，遂以长逝。癸卯冬至前一日，管大中丞亦是气从溺脱，当以参、附挽回者，及孟英至而痰药、痧药、风药，灌之遍矣。脉仅若蛛丝过指，孟英坚不与方，须臾而卒。", "13769": "无棣张柳吟封翁，于乙未夏偕令嗣恒斋刺史赴滇南任，道出武林。其家人郑九者，封翁宠人之弟也，途次抱恙。抵抗日招越医陈六顺诊治，服药后汗出昏狂，精流欲脱。封翁大骇，躬诣孟英以希挽救。孟英切其脉，既数且乱，沉取极细。乃语封翁曰：此证颇危，生机仅存一线，亦斯人之阴分素亏，不可竟谓附、桂之罪也。封翁闻言大悦，曰：长者也。不斥前手之非以自伐，不以见证之险而要誉。相见恨晚，遂订忘年之交。彼此尽吐生平，始知封翁最喜谈医，岐黄之言，无所不览，惟不肯为人勘病，亦慎重之意耳。于是孟英以元参、知、柏、桑枝、龙、牡、生地、白芍、甘草、百合、石斛、栀子、盐水炒淡豆豉为大剂灌之，下咽即安。次日去栀、豉、甘草，加龟板、鳖甲、盐水炒橘红，十余帖而康。", "13770": "丙申春蜀人石符生，将赴邓云厓司马之招，经杭抱病，侨于张柳吟之旧馆，亦为寓侧陈六顺治困。居停主人知之，即告以柳吟仆病之事，石闻之悚然，亟遣人延孟英诊焉。脉沉而涩滞，模糊不分至数，肢凉畏冷，涎沫上涌，二便涩少，神气不爽。曰：此途次感风湿之邪，失于解散，已从热化，加以温补，致气机愈形窒塞，邪热漫无出路，必致烁液成痰，逆行而上。但与舒展气机，则痰行热降，诸恙自瘳矣。以黄连、黄芩、枳实、橘皮、栀子、淡豉、桔梗、杏仁、贝母、郁金、通草、紫菀、竹茹、芦菔汁等药，三服而起，调理匝旬遂愈。", "13771": "夏间王某患感，越医谢树金治之，病虽退而能食矣，但不能起坐，类乎瘫痪，延已月余，人皆谓其成废。所亲钟某，浼孟英视之，曰：此多服表散，汗出过分，气血两伤，肢骸失其营养。脉微而细，舌亮无苔。与大剂参、耆、归、术、熟地、杜仲、菟丝、牛膝、枸杞、山药、木瓜、萸肉、萎蕤、续断、桑枝，（气血双补，而补血之药重于补气，以汗为血液，阴分偏伤也。）数十帖而起。", "13772": "张养之令正，饮食如常，而肌肤消瘦，（叙证详明。）信事如期，而紫淡不恒，两腓发热，而别处仍和，面色青黄，而隐隐有黑气，俨似虚寒，多药不效，始逆孟英诊之。脉似虚细，而沉分略形弦滑。曰：此阳明有余，少阴不足，土燥水涸。仲圣有急下存阴之法。然彼外感也，有余之邪可以直泻；此内伤也，无形之热宜以甘寒，义虽同而药则异也。赠以西洋参、生地、生白芍、生石膏、知、柏、苓、栀、麦冬、花粉、楝实、丹皮、木通、天冬诸品，服至数斤，黑气退而肌渐充，腓热去而经亦调矣。（眉批：孟英善用甘寒，投之此证尤宜。）", "13773": "牙行王炳华妻患舌疮，痛碍饮食，内治外敷皆不效。孟英视其舌色红润，脉形空数，曰：此血虚火浮也，以产后发热例施之。用熟地、当归、酒炒白芍、炙甘草、茯苓、炮姜投之，其病如失。", "13774": "一老人霍乱后目闭呃忒，医谓脱陷在即，与桂、附回阳之药，业已煎矣。适孟英至，询知溺赤口干，诊得脉形软数，而药香扑鼻，即曰：此药中有肉桂，叟勿服也，服之必死。迫令将药倾泼，而与肃肺清胃之剂，果得渐安。", "13775": "丁酉中秋夜，牙行张鉴录，年逾花甲，卒仆于地，急延孟英脉之，弦滑而大，曰：痰、气、食相并而逆于上也。先以乌梅擦开牙关，横一竹箸于口，灌以淡盐姜汤。随入鹅翎探之，吐出痰食，太息一声而苏。次与调气和中而愈。后数年以他疾终。此案虽无奇，而辨证之明，不可不录。", "13776": "夏间牙行倪怀周室，新产数日，泄泻自汗，呕吐不纳。专科谓犯三禁，不敢肩任。孟英诊脉虚微欲绝，证极可虞，宜急补之，迟不及矣。用东洋参、耆、术、龙、牡、酒炒白芍、桑枝、木瓜、扁豆、茯神、橘皮、紫石英、黑大豆投之。四剂渐以向安。予谓：新产后用参、耆大补，而又当盛夏之时，非有真知灼见者不能也。诚以天下之病，千变万化，原无一定之治。奈耳食之徒，惟知执死方以治活病，岂非造孽无穷，亦何苦人人皆欲为医，而自取罪戾耶？", "13777": "张养之令侄女，患汛愆而饮食渐减，于某与通经药，服之尤恶谷，请孟英诊之。脉缓滑，曰：此痰气凝滞，经隧不宣，病由安坐不劳。法以豁痰流气，勿投血药，经自流通。于某闻而笑曰：其人从不吐痰，血有病而妄治其气，胀病可立待也。及服孟英药，果渐吐痰而病遂愈，养之大为折服。予谓：世人头痛治头，脚疼疗脚，偶中而愈，贪为己功，误药而亡，冤将奚白？此《寓意草》之所以首列议病之训也。孟英深得力于喻氏，故其议病迥出凡流。要知识见之超，总由读书而得，虽然人存政举，未易言也。", "13778": "毛允之戌冬患感，初治以温散，继即以滋阴，病日以剧，延至亥春。或疑为百日之劳，或谓是伤寒坏证，而凤山僧主升、柴、耆、术以补之，丁卯桥用轻粉、巴霜以下之，杂药遍投，形神日瘁。乃尊学周延孟英视之。脉来涩数上溢，呃忒口腻，虽觉嗜饮，而水难下膈，频吐涎沫，便秘溺赤，潮热往来，少腹如烙，按之亦不坚满。曰：此病原属冬温，治以表散，则津液伤而热乃炽。继以滋填，热邪愈锢，再施温补，气机更窒。升、柴、耆、术欲升其清，而反助其逆；巴霜、轻粉欲降其浊，而尽劫其阴。病及三月，发热不是表邪；便秘旬余，结涩非关积滞。且脉涩为津液之已伤，数是热邪之留著，溢乃气机为热邪所壅而不得下行，岂非温邪未去，得补而胶固难除，徒使其内烁真阴，上薰清道，以致一身之气，尽失肃清之令。法当搜剔余邪，使热去津存，即是培元之道；伸其治节，俾浊气下趋，乃为宣达之机。何必执参、茸为补虚，指硝、黄为通降哉？以北沙参、紫菀、麦冬、知母、花粉、兰草、石斛、丹皮、黄芩、桑叶、栀子、黄连、木通、银花、橘皮、竹茹、芦根、橄榄、枇杷叶、地栗、海䖳等，出入为方。服之各恙递减，糜粥渐加，半月后始得大解，而腹热全消，谷食亦安，乃与滋阴善后而愈。眉批：清热生津，治法固善。然亦此人本元坚固，故屡误之后，犹能挽回，否则亦难为力矣。", "13779": "茅家埠翁嘉润患腰疽，愈而复发者五年，费用不赀，诸疡医治之不效。盛少云嘱其求治于孟英。切其脉弦细以数，曰：子之幸也。此内损证，（肾俞发亦然。）外科恶乎知？与大剂甘润滋填之药，匝月而痊，至今不发。", "13780": "秋初家慈猝仆于地，急延孟英诊之。脉浮弦以滑，用羚羊角、胆星、牡蛎、石菖蒲、丹参、茯苓、钩藤、桑叶、贝母、橘红、蒺藜等，以顺气蠲痰、息风降火而痊。癸卯春前数日，忽作欠伸而厥，孟英切脉微弱而弦。曰：病虽与前相似，而证则异矣。以高丽参、白术、何首乌、山茱萸、枸杞、桑椹、石斛、牛膝、蒺藜、橘红、牡蛎等，镇补摄纳以瘳。予谓：此等证，安危在呼吸之间，观前后卒仆数案，可见其辨证之神，虽古人不多让，况世俗之所谓医乎？家慈两次类中，予皆远出，微孟英吾将焉活？感铭五内，聊识数言，惟愿读是书者，体其济世之心，临证得能如是，将胥天下之沉疴而尽起矣。", "13781": "张养之弱冠失怙后，即遘无妄之疾，缠绵七载，罄其赀财，经百十三医之手，而病莫能愈。因广购岐黄家言，静心参考，居然自疗而痊，然鼻已坏矣。抱此不白之冤，自渐形秽，乃闭户学书，专工作楷，其志良可悼也。孟英因与之交，见具体怯面青，易招外感，夏月亦著复衣，频吐白沫，询知阳痿多年，常服温辛之药，孟英屡谏之。而己亥九月间，患恶寒头痛，自饵温散不效，逆孟英诊之。脉极沉重，按至骨则弦滑隐然。卧曲房密帐之中，炉火重裘，尚觉不足以御寒，且涎沫仍吐，毫不作渴，胸腹无胀闷之苦，咳嗽无暂辍之时，惟大解坚燥，小溲不多，口气极重耳。乃谓曰：此积热深锢，气机郁而不达，非大苦寒以泻之不可也。养之初犹疑焉，及见方案，辨论滔滔，乃大呼曰：弟之死生，系乎一家之命，唯君怜而救之。孟英慰之曰：我不惑外显之假象，而直断为实热之内蕴者，非揣度之见，而确有脉证可凭，但请放心静养，不必稍存疑畏。及二三帖后，病不略减，诸友戚皆诋药偏于峻，究宜慎重服之。有于某者，扬言于其族党曰：养之之命，必送于孟英之手矣。众楚交咻，举家惶惑，次日另延陈启东暨俞某并诊。孟英闻之，急诣病榻前谓曰：兄非我之知已也，则任兄服谁之药，我不敢与闻也：兄苟裕如也，则任兄广征明哲，我不敢阻挠也。今兄贫士也，与我至交也，拮据资囊，延来妙手，果能洞识病情，投剂必效，则我亦当竭力怂恿也。第恐虽识是病，而用药断不能如我之力专而剂大也。苟未能确识是证，而以无毁无誉之方，应酬塞责，则因循养患，谁任其咎也？或竟不识是病，而开口言虚，动手即补，甘言悦耳，兄必信之，我不能坐观成败，如秦人视越人之肥瘠也。今俞某之方如是，陈医殊可却之，速著人赶去辞绝，留此一款，以作药资，不无小补。况连服苦寒，病无增减，是药已对证，不比平淡之剂，误投数帖，尚不见害也。实由热伏深锢，药未及病。今日再重用硝、黄、犀角，冀顽邪蕴毒，得以通泄下行，则周身之气机，自然流布矣。养之伏枕恭听，大为感悟。如法服之，越二日大便下如胶漆，秽恶之气达于户外，而畏寒即以递减，糜粥日以加增。旬日后粪色始正。百日后康健胜常。嗣后虽严冬亦不甚畏冷，偶有小恙，辄服清润之方，阳道复兴，近添一女。养之尝颂于人曰：孟英之手眼，或可得而学也；孟英之心地，不可得而及也。我之病，奇病也，孟英虽具明眼，而无此种热情，势必筑室道旁，乱尝药饵，不能有今日矣。况不但有今日，而十余年深藏久伏之疴，一旦扫除，自觉精神胜昔，可为后日之根基，再生之德，不亦大哉。", "13782": "石符生，随乃翁自蜀来浙，同时患疟。医者以小柴胡汤加姜、桂，投之不效，改用四兽、休疟等法，反致恶寒日甚，谷食不进，惟饮烧酒姜汤，围火榻前，重裘厚覆，胸腹痞闷，喜以热熨，犹觉冷气上冲，频吐黏稠痰沫。延至腊初，疲惫不堪，始忆及丙申之恙，访孟英过诊。脉沉而滑数，苔色黄腻不渴，便溏溺赤。曰：是途次所受之暑湿，失于清解，复以温补之品，从而附益之，酿成痰饮，盘踞三焦，气机为之阻塞，所以喜得热熨热饮，气冲反觉如冰。若不推测其所以然之故，而但知闻问在切脉之先，一听气冷喜热，无不以为真赃现获，孰知病机善幻，理必合参，以脉形兼证并究，（审病要法。）则其为真热假寒，自昭昭若揭矣。与大剂苦寒之药，而以芦菔汤煎，渐服渐不畏寒，痰渐少，谷渐增。继用甘凉善后，乔梓皆得安全。", "13783": "赤山埠李氏女，素禀怯弱。春间汛事不行，胁腹聚气如瘕，减餐肌削，屡服温通之药。至孟秋，加以微寒壮热，医仍作经闭治，势濒于危。乃母托伊表兄林豫堂措办后事，豫堂特请孟英一诊以决之。孟英切其脉时，壮热烙指，汗出如雨，其汗珠落于脉枕上，微有粉红色，乃曰：虚损是其本也。今暑热炽盛，先当治其客邪，急则治标之法。庶可希冀。疏白虎汤加西洋参、元参、竹叶、荷杆、桑叶。及何医至，一筹莫展，闻孟英主白虎汤，乃谓其母曰：危险至此，尚可服石膏乎？且《本草》于石膏条下致戒云，血虚胃弱者禁用，岂彼未之知也。豫堂毅然曰：我主药，与其束手待毙，盍从孟英死里求生之路耶？遂服二帖，热果退，汗渐收。改用甘凉清余热，日以向安。继与调气养营阴，宿瘕亦消。培补至仲冬，汛至而痊，次年适孙夔伯之弟。", "13784": "牙行王炳华室，夏患臂痛，孙某曰风也。服参、耆、归、芍数帖，臂稍愈而脘痛，孙曰寒也。加以附、桂，痛不止而渐觉痰多，孙曰肝肾不足也。重用熟地、枸杞，令其多服取效，不料愈服愈剧，渐至昏厥。孙尚以为药力之未到，病体之久虚，前方复为加重，甚而时时发厥，始请孟英诊之。脉沉而有弦滑且数之象，乃谓炳华曰：此由过投温补，引动肝风，煽其津液为痰，痰复乘风而上，此晕厥之由来也。余波则奔流经络，四肢因而抽搐。阳气尽逆于上，宜乎鼻塞面浮；浊气不能下达，是以便滞不饥。炳华曰：神见也。温补药服几三月矣，不知尚可救乎？孟英曰：勿疑吾药，犹有望焉。遂与大剂甘寒息风化饮，佐以凉苦泄热清肝，厥果渐止，各恙递蠲，两月后康复如常。予偶于旧书中检得无名氏钞本一册，所录多岐黄之言，内一条云：附、桂回阳，在一二帖之间，万一误投，害亦立至，功过不掩，其性之毒烈也，概可见矣。奈世人不知药为治病而设，徒以贪生畏死之念，横于胸中，遂不暇顾及体之有病无病，病之在表在里，但闻温补之药，无不欣然乐从者，模棱之辈，趋竟存心，知其死于温补而无怨悔也。乃衣钵相传，不必察其体病脉证之千头万绪，仅以温补之品二十余味，相迭为用，即成一媚世之方。且托足《金匮》之门，摹拟肾气之变，盖知熟地之阴柔，可缚附、桂之刚猛，误投不至即败，偶中又可邀功，包藏祸心，文奸饰诈，何异新莽比周公，子云学孔圣哉？人以其貌古人而口圣贤也，多深信而不疑。迨积薪既厚，突火顿燃，虽来烂额焦头之客，其不至于焚身者幸矣。较彼孟浪之徒，误投纯阳药，致人顷刻流血而死者，其罪当加十等。诛心之论，救世之言，知我罪我，不遑计焉。孟英见之，拜读千过，且曰：剿汉学以欺世，由来久矣。徐灵胎之论，无此透彻，可与退之《原道》文并峙，当考其姓字，于仲景先师庙内建护圣祠以祀之。予谓：孟英如此称许，则其可传也奚疑，故附刊此案之后，以证王氏妇温补药服及三月，即所谓阴柔束缚刚猛之故，致人受其愚而不觉者，后之人可以鉴矣。", "13785": "胡蔚堂舅氏，年近古稀，患囊肿，小溲赤短，寒热如疟。孟英曰：非外感也，乃久蕴之湿热下流，气机尚未宣泄。与五苓合滋肾，加楝实、栀子、木通。两剂后囊间出腥黏黄水甚多，小溲渐行，寒热亦去。继与知柏八味去山药、萸肉，加栀子、楝实、芍药、苡仁等，久服而愈。壬寅夏感受暑湿，误投温散，以致谵语神昏，势濒于危，而肛前囊后之间，溃出腥脓，疮口深大，疡科以为悬痈也，敷治罔效。时孟英患痁未痊，予固邀其扶病一诊。孟英曰：悬痈乃损怯证，成之以渐。（卓识。）今病来迅速，腥秽异常，是身中久蕴厚味湿热之毒，挟外受之暑邪，无所宣泄，下注而为此证。切勿敷药以遏其外走之势，但舌强而紫赤，脉细而滑数，客邪炽盛，伏热蕴隆，阴分甚亏，深虞津涸。先与清营之剂，三投而神气渐清。次以凉润阳明，便畅而热蠲脓净。改用甘柔滋养，月余溃处肌平。善后参入参、耆，竟得康强如昔。（眉批：用药次第可法。）", "13786": "湖墅张春桥，素禀不坚，头眩脑鸣，频服温补药，甚觉畏冷，人皆谓其体偏于寒也。辛丑春，始请孟英诊之。脉甚数，曰：阴亏也，温补非宜。改服滋水培元之剂，颇为有效。夏间或劝以灸火，云可以除百病。盖未知灼艾之可以除百病者，谓可除寒湿凝滞、阳气不能宣通之证，非谓内伤外感一切之病，皆可灸而除之也。故仲景有微数之脉，慎不可灸之训，正以艾火大能伤阴也。灸后数日，即寒少热多，宛如疟疾。医者以为脾寒病，投以温散，日以滋甚。春桥知药治未符，坚不肯服，乃父与之询其故，漫曰：要儿服药，须延王先生诊视。与之遂邀孟英治之。切其脉滑数倍加，曰：阴虚之体，内热自生，灸之以艾，火气内攻，时当溽暑，天热外烁，三者相交，阴何以堪？再投温散，如火益热，当从瘅疟治。专以甘寒息热，（孟英长技。）则阴津不至枯涸，而寒热不攻自去，所谓治病必求其本也。竟不用一分表散药而治愈。（眉批：眼前道理，而人多不悟，一经拈出，便成名论。此与以针治虚损者，同一悖谬。）", "13787": "栖流所司药陈芝田，于仲夏患感，诸医投以温散，延至旬日，神昏谵妄，肢搐耳聋，舌黑唇焦，囊缩溺滴，胸口隐隐微斑，一望而知其危矣。转邀孟英诊之，脉细数而促，曰：阴亏热炽，液将涸矣。遂用西洋参、元参、生地、二冬、知、柏、楝实、石斛、白芍、甘草梢、银花、木通、犀角、石菖蒲，大剂投之。（孟英能善用大剂，故能起不治之证，亦古人所未有也。）次日复诊，其家人云：七八日来小溲不过涓滴，昨药服六七个时辰后，解得小溲半杯。孟英曰：此即转机也。然阴气枯竭，甘凉濡润，不厌其多。于前方再加龟板、鳖甲、百合、花粉，大锅煎之，频灌勿歇。如是者八日，神气始清，诸恙悉退，纯用滋阴之药，调治匝月而瘳。（眉批：一派甘寒之药，既可涤热，又以生津，真治温良法也。惟湿温证宜稍加斟酌耳。）予谓：孟英学识过人，热肠独具。凡遇危险之候，从不轻弃，最肯出心任怨以图之。如此案，八日后神气始清，若经别手，纵使治法不错，而一二帖后不甚起色，必规避坚辞，致病家惑乱，谋及道旁，虽不死于病，亦必死于药矣。此在医者之识老心坚，又须病家之善于择而任之专也，谈何易耶？且闻孟英尝云：温热液涸神昏，有投犀角、地黄等药至十余剂，始得神清液复者，因温热案最伙，不暇详录，姑识此以告司人之命者。", "13788": "江小香病势危笃，浼人迎孟英诊之。脉虚弦而小数，头痛偏于左后，子夜热躁，肢冷欲呕，口干不欲饮，不饥不欲食，舌蹇言涩，溺黄而频。曰：体属素虚，此由患感时过投温散，阴津阳气皆伤，后来进补而势反日剧者，滋腻妨其中运，刚烈动其内风，（知此二语，方可论药。）以致医者佥云表之不应，补亦无功，竟成无药可治之证。虽然，不过难治耳，未可遽弃也。与秋石水拌制高丽参、苁蓉、首乌、生白芍、牡蛎、楝实、盐水炒橘红、桑椹、石斛、蒺藜、茯苓煎，吞饭丸肉桂心五分。一剂躁平呕止，各恙皆减。连投数服，粥食渐安，乃去首乌、桂、楝，加砂仁末拌炒熟地、菊花、枸杞，半月而瘳。（眉批：从阴引阳，从阳引阴，绝妙机轴。）", "13789": "溽暑之令，瘄疹盛行，幼科仅知套药，升、柴、防、葛乱施，殆亦疫疠之病，造化默行其杀运欤？陈仰山家患此者十余人，其长郎书芾孝廉之女，势最剧，以瘄甫出，而汛至也。医者却走，始延孟英视之。脉滑而数，舌绛大渴，面赤失音，不食便泻，曰：此由发散太过，火盛风炽，气血两燔。气分之邪，由泻而略泄其焰；营分之热，由汛而稍解其焚，岂可畏其脱陷，妄投止涩耶？与西洋参、石膏、知母、麦冬、犀角、生地、连翘、甘草、石斛、丹皮、桑叶、竹叶，大剂投之，三日而愈。养阴善后，遂以渐安。其余或轻或重，孟英一以清解而痊。", "13790": "石诵羲夏杪患感，多医广药，病势日增，延逾一月，始请孟英诊焉。脉至右寸关滑数上溢，左手弦数，耳聋口苦，热甚于夜，胸次迷闷，频吐黏沫，啜饮咽喉阻塞，便溏溺赤，间有谵语。曰：此暑热始终在肺，并不传经，一剂白虎汤可愈者，何以久延至此也？乃尊北涯，出前所服方见示，孟英一一阅之，惟初诊顾听泉用清解肺卫法为不谬耳，其余温散升提、滋阴凉血，各有来历，皆费心思，原是好方，惜未中病。而北涯因其溏泄，见孟英君石膏以为治，不敢与服。次日复诊，自陈昨药未投，惟求另施妥法。孟英曰：我法最妥，而君以为未妥者，为石膏之性寒耳。第药以对病为妥，此病舍此法，别无再妥之方。若必以模棱迎合为妥，恐贤郎之病不妥矣。北涯闻而感悟，颇有姑且服之之意。而病者偶索方一看，见首列石膏，即曰：我胸中但觉一团冷气，汤水皆须热呷，此药安可投乎？坚不肯服。然素仰孟英手眼，越日仍延过诊，且告之故。孟英曰：吾于是证，正欲发明。夫邪在肺经，清肃之令不行，津液凝滞，结成诞沫，盘踞胸中，升降之机亦窒，大气仅能旁趋而转旋，是一团涎沫之中，为气机所不能流行之地，其觉冷也，不亦宜乎？（眉批：论亦根柢喻氏，而更加明透。）且予初诊时，即断为不传经之候，所以尚有今日，而能自觉胸中之冷。若传入心包，则舌黑神昏，才合吴古年之犀角地黄矣。然虽不传经，延之逾月，热愈久而液愈涸，药愈乱而病愈深，切勿以白虎为不妥，急急投之为妙。于是有敢服之心矣。而又有人云：曾目击所亲某，石膏甫下咽，而命亦随之。况月余之病，耳聋泄泻，正气已亏，究宜慎用。北涯闻之惶惑，仍不敢投，乃约翌日广征名士，会商可否。比孟英往诊，而群贤毕至，且见北涯求神拜佛，意乱心慌，殊可怜悯。欲与众商榷，恐转生掣肘，以误其病。遂不遑谦让，援笔立案云：病既久延，药无小效，主人之方寸乱矣。予三疏白虎而不用，今仍赴招诊视者，欲求其病之愈也。夫有是病则有是药，诸君不必各抒高见，希原自用之愚。古云：鼻塞治心，耳聋治肺，肺移热于大肠，则为肠澼，是皆白虎之专司，何必拘少阳而疑虚寒哉？放胆服之，勿再因循，致贻伊戚也。坐中顾听泉见案，即谓北涯曰：孟英肠热胆坚，极堪倚赖，如犹不信，我辈别无善法也。顾友梅、许芷卿、赵笛楼亦皆谓是。疏方以白虎加西洋参、贝母、花粉、黄芩、紫菀、杏仁、冬瓜仁、枇杷叶、竹叶、竹茹、竹黄。而一剂甫投，咽喉即利，三服后，各恙皆去，糜粥渐安，乃改甘润生津，调理而愈。予谓此案不仅治法可传，其阐发病情处，识见直超古人之上。", "13791": "刘廉方，常州名士也，在西湖受暑，移榻于崔仲迁别驾处，医治垂危。庄芝阶舍人拉孟英往诊之。裸卧昏狂，舌黑大渴，溺赤便秘，脉数而芤。与犀角地黄汤加减服之，神识已清，略能进粥。次日复诊，颇知问答，大有生机，仍处甘凉法以赠之，并嘱伊格外谨慎。而越日庄半霞诣孟英偕往诊视，见其目张睛瞪，齿露唇焦，气喘汗出，扬手掷足，而不可救药矣。众楚交咻，谓是寒凉药凝闭而然。孟英曰：病之宜凉宜热，汝辈不知也。脉乃皮里之事，汝等不见也，吾亦不屑为之争辨。惟目瞪唇焦，人所共睹，则其死于何药，自有定论。遂拂衣出，半霞再三请罪，孟英曰：俗人之见，何足介怀？是非日后自明，于我心无慊焉。第斯人斯病，皆可惜也。既而始知有人主热药以偾事，岂非命耶？仅二载而仲迁病，孟英闻之曰：殆矣。盖知其阴虚而受暑湿，恐主药者未必能悔悟于前车也。后果闻其广服温补之剂，以致真阴竭绝而死。覆辙相寻，迷而不醒，可哀也已！", "13792": "仲冬大雪连朝，积厚丈许，严寒久冻，西湖可行车马。斯时也，盛少云患痰嗽夜热，自汗不寐，左胁痛如针刺，肌削不饥，自问不起矣。请孟英托以后事，及诊其脉，许以可生。盖病来虽恶，未经误药也。与固本加龟板、鳖甲、苁蓉、知、柏、青黛、石斛、花粉、白芍、楝实、海石、旋覆、贝母、蛤壳、牛膝，出入为大剂，投之即效。连服四五十帖而痊，予谓斯证患于斯时，若经别手，未有不投温补者，而少云能与孟英游，其亦具眼之人乎？此真所谓患难交，不可不留心于平日也。然亦不能人人而遇之，殆佛氏所谓有缘存乎其间欤？", "13793": "一人患晨泄有年，累治不效，而春间尤甚。孟英按其脉曰：汝虽苦泻，而泻后腹中反觉舒畅乎？曰：诚然。苟不泄泻，又胀闷减食矣。而服四神、附、桂之药，其泻必加，此曷故也？曰：此非温升补涩之证，乃肝强脾弱，木土相凌，处一方令其常服，数帖即安，后竟无此恙矣。方用白术、苡仁、黄连、楝实、桂枝、茯苓、木瓜、芍药、蒺藜、橘皮而已。（眉批：扶脾抑肝，制方灵动。）", "13794": "邵鱼竹给谏，起居食饮如常，惟仅能侧卧，略难仰卧，仰而寤无恙也。（眉批：凡心肾不交之人，多不能仰卧，以仰则肾气不能上承，而心气愈浮也。）稍一合眼，则惊窜而醒，虽再侧眠，亦彻夜不得寐矣。多年莫能治，孟英以三才合枕中丹，加黄连、肉桂，服之良效。（心肾交治，而以黄连、肉桂媾合之，用意甚巧。）其长郎子瓬，久患痰多，胸膈满闷，连年发痫，药之罔效。孟英脉之曰：气分偏虚，痰饮阻其清阳之旋运，宜法天之健以为方，则大气自强，而流行不息，胸次乃廓然如太空矣。与六君去甘草，加黄耆、桂枝、薤白、蒌仁、石菖蒲、蒺藜、旋覆，服之满闷渐舒，痫亦不发矣。", "13795": "戚媪者，年六十余矣，自幼佣食于黄莲泉家，忠勤敏干，老而弥甚，主仆之谊，胜于亲戚也。秋间患霍乱转筋，孟英视之：暑也。投自制蚕矢汤，两服而安。三日后忽然倦卧，不能反侧，气少不能语言，不饮不食。莲泉惶惧，不暇远致孟英，即邀济仁堂朱某诊之。以为霍乱皆属于寒，且昏沉欲脱，疏附子理中汤与焉。莲泉知药猛烈，不敢遽投，商之王安伯。安伯云：以予度之，且勿服也。若谓寒证，则前日之药下咽即毙，吐泻安能渐止乎？莲泉闻之大悟，著人飞赶孟英，至而切其脉，曰：此高年之体，元气随泻而泄，固当补者。第余暑未清，热药在所禁耳。若在孟浪之家，必以前之凉药为未当，今日温补为极是，纵下咽不及救，亦惟归罪于前手寒凉之误也。设初起即误死于温补，而世人亦但知霍乱转筋，是危险之证，从无一人能知此证有阴阳之异，治法有寒热之殊，而一正其得失者，此病之所以不易治，而医之所以不可为也。今君见姜、附而生疑，安伯察病机之已转，好问者心虚，识机者智赡，二美相济，遂使病者跳出鬼门关，医者卸脱无妄罪，幸矣幸矣！乃以高丽参、麦冬、知母、萎蕤、木瓜、扁豆、石斛、白芍、苡仁、茯苓、蒺藜为方，服六剂始能言动，渐进饮食，调理月余而健。", "13796": "七月十八日夜，予患霍乱转筋甚剧，仓卒间误服青麟丸钱许，比晓急邀孟英诊之。脉微弱如无，耳聋目陷，汗出肢冷，音哑肌削，危象毕呈。（眉批：可见浙人禀赋之薄，若幽、冀之人，即误服青麟丸数钱，亦不至如斯之甚也。）药恐迟滞，因嘱家慈先浓煎高丽参汤，亟为接续。随以参、术、白芍、茯苓、附、桂、干姜、木瓜、苡仁、扁豆、莲实为方，一剂而各证皆减。次日复诊，孟英曰：气分偏虚，那堪吐泻之泄夺？误饵苦寒，微阳欲绝。昨与真武、理中合法，脾肾之阳复辟矣。刚猛之品，可以撤去。盖吐泻甚而津液伤，筋失其养则为之转，薛生白比之痉病，例可推也。凡治转筋，最要顾其津液。若阳既回而再投刚烈，则津液不能复，而内风动矣。此治寒霍乱之用附、桂、亦贵有权衡，而不可漫无节制，致堕前功也。（此一段议论极精微，凡用寒用热，俱宜具此权衡，方无过当之弊。）否则药虽中病，而服之不止，反受其害矣。喻氏论中寒证亦具此意。即于前方裁去姜、附、肉桂，加黄耆、石斛，服至旬日而愈。予谓此番之病，危同朝露，若非孟英，恐不能救。常闻张柳吟云：但使病者听孟英论病之无微不入，用药之无处不到，源源本本，信笔成章，已觉疾瘳过半。古云：檄愈头风。良有以也。", "13797": "顾云垞，体丰年迈，患疟于秋，脉芤而稍有歇止。孟英曰：芤者，暑也；歇止者，痰湿阻气机之流行也，（卓识。）大忌温补以助邪气。（眉批：此必别有外证可凭，故直断为暑与痰湿，未有专视脉之芤与歇止而如是定断者，读者勿被瞒过。）及与清解蠲痰之法，病不少减，而大便带血，（邪将去矣。）孟英曰：暑湿无形之气，而平素多痰，邪反得以盘踞，颇似有形之病。清解不克胜其任，气血皆受其滋扰。必攻去其痰，使邪无依附而病自去，切勿以高年而畏峻药。伊侄桂生少府，亦精于医者也，闻之极口称是，遂以桃仁承气汤加西洋参、滑石、芩、连、橘红、贝母、石斛为方，送礞石滚痰丸。（眉批：此方可谓峻极，良由识高，非徒胆大。）乃郎石甫孝廉云：此药在他人必畏而不敢服，我昔年曾患暑湿证，深悉温补之不可轻试，况高明所见相同，更何疑乎？径服二剂，下黏痰污血甚多，疟即不作，仍以清润法善后而康。", "13798": "邵子受令壶患吐血，肌肤枯涩，口渴，脉虚大。孟英曰：气分之阴亏也。温补既非，滋填亦谬。以参、耆、二冬、知母、百合、萎蕤、石斛、桑叶、枇杷叶投之而愈。（眉批：用补亦要用得其宜，方能奏效，非一味蛮补即能愈疾也。案中诸法可以为法。）", "13799": "九月间张春桥患疟，寒少热多，间二日而作，甫两发形即清瘦。孟英诊曰：脉弦而细，尺中甚数，疾作于子夜，口干嗜饮，乃足少阴热疟也。两发遽尔形消，胡可玩视？吾以妙药奉赠，可期即己。但请即服，不可商于人而致生疑议也。方用元参、生地、知母、丹皮、地骨皮、天冬、龟板、茯苓、石斛、桑叶。春桥以向所心折，遂服之。一剂疟即止，再以滋阴善后而愈。予谓此证一帖而瘳，似乎轻易，但非真才实学，焉有此种妙治？设遇别手，非温补即提表，其祸可胜道哉！然天下之病，无论轻重，总贵初治得法，何致轻者重而重者危耶？奈世俗之情，必使轻者重而后转安，始知医药之功，殊可叹也。按：此证，世人但知其为三阴疟，笼统治以温补之法，从未闻有分经用药者。今提出少阴二字，创立清凉之剂，用药精当，取效敏捷，法似新奇，理自完足，所谓活人治活病，全以活泼运之也，可以启人慧悟，垂作典型。", "13800": "癸卯春，邵秋子令堂年近六旬，患寒热如疟者久矣。诸医杂治罔效，孟英视之曰：此湿邪久蕴，已从热化，误投提补，动其肝阳，痰饮因而上逆，与通降之法，寒热即减。而包某谓疟久阴虚，理宜滋养。病家闻之近是，遂进首乌、鳖甲等药，渐至脉伏胸痞，呃忒自汗，渴饮不食，颧赤便泄。包某束手，疏生脉散以塞责，举家彷徨，再求孟英诊之。曰：此滋腻阻塞气机，（喜用熟地者鉴之。）清阳不司旋运，痰饮闭滞隧络，非脱象也，补药不可进。以栝蒌薤白合小陷胸，加菖蒲、竹茹、旋覆、贝母、杏仁、紫菀、枇杷叶投之。（清热涤饮，旋转气机，以救滋腻之失。）呃止脉出，大有转机，而郑某谓病固属痰，须温热以宣通，勿寒凉而凝遏，病家又惑焉。姜、桂频投，既而唇肿咽疼，不能进饮，舌干短硬，难出语言，复请孟英救疗。与犀角地黄汤加元参、知母、银花、竹黄、花粉、胆星、石菖蒲、竹沥之类，（甘寒生津，以救燥烈之失。）六七剂吐出极臭胶痰甚多，粥饮渐进，此第三次生机也。奈狂澜莫障，邪说横行，辄以凉药不宜擅服，久病必定元虚，甘言悦耳，遂至升散温补，各逞所能，符咒乩方，罔不遍试。延至仲夏，腭腐龈糜，唇高数寸，竟成燎原莫救，仍恳孟英设法，乃坚辞不能措手，付局医黄某敷治，肿烂日甚而终。", "13801": "段春木之室烂喉，内外科治之束手，姚雪蕉孝廉荐孟英视之。骨瘦如柴，肌热如烙，韧痰阻于咽喉，不能咯吐，须以纸帛搅而曳之，患处红肿白腐，龈舌皆糜，米饮不沾，汛事非期而至，按其脉左细数，右弦滑。曰：此阴亏之体，伏火之病，失于清降，扰及于营。先以犀角地黄汤清营分，而调妄行之血；续与白虎汤加西洋参等，肃气道而泻燎原之火。外用锡类散，扫痰腐而消恶毒。继投甘润药，蠲余热而充津液，日以向安，月余而起。", "13802": "胡秋纫于酷热时偶有不适，医以柴、葛、香薷散之，反恶寒胸痞，更医用枳、朴、槟榔以泻之，势日剧，延孟英视之。自汗不收，肢背极冷，奄奄一息，脉微无神。曰：禀赋素亏，阳气欲脱，此必误认表证使然。与救逆汤加参、耆，服之渐安。继以补气生津，调理匝月而痊。", "13803": "石诵羲室，久患痰嗽，诸医药之勿瘳。孟英切其脉曰：非伤风也。与北沙参、熟地、百合、麦冬、贝母、紫菀、萎蕤、枇杷叶、盐水炒橘皮、燕窝，一剂知，数剂已。初秋又患脘痛，上及肩尖，向以为肝气，辄服破削之品。孟英曰：亦非也。以砂仁、炒熟地、炙橘红、楝实、延胡、枸杞、当归、茯苓、桑椹、蒺藜为方。服之良效，继即受孕矣。（眉批：合观二案，其人必阴虚肺燥之质，故用药如此。）", "13804": "石芷卿患感，张某连投柴、葛药，热果渐退，而复热之后，势更孔甚，乃延孟英诊焉。先以栀、豉、芩、连等药，清解其升浮之热，俟邪归于府，脉来弦滑而实，径用承气汤下之。时其尊人北涯赴瓯，无人敢主其可服否也，另招他医决之，以为太峻，且腹不坚满，妄攻虑变，举家闻之摇惑，暮夜复恳再诊。孟英辨论洋洋，坚主前议，服后果下黑矢。次日大热大汗，大渴引饮，孟英曰：此府垢行而经热始显。与竹叶石膏汤，二剂而安。继以育阴充液，调理而康。", "13805": "邻人汪氏妇之父王叟，仲秋患痰嗽不食，气喘不卧，囊缩便秘，心摇摇不能把握，势极可危，伊女浼家慈招孟英救之。曰：根蒂欲脱耳，非病也。以八味地黄汤去丹、泽合生脉，加紫石英、青铅、龙、牡、胡桃肉、楝实、苁蓉投之，大解行而诸恙减，乃去苁蓉、麦冬，服旬日以瘳。初冬邵可亭患痰嗽，面浮微喘，医谓年逾花甲，总属下部虚寒，进以温补纳气之药，喘嗽日甚，口涎自流，茎囊渐肿，两腿肿硬至踵，不能稍立，开口则喘逆欲死，不敢发言，头仰则咳呛咽疼，不容略卧，痰色黄浓带血，小溲微黄而长。许芷卿荐孟英视之，脉形弦滑有力，曰：此高年孤阳炽于内，时令燥火薄其外，外病或可图治，真阴未必能复。且平昔便如羊矢，津液素干，再投温补，如火益热矣。乃以白虎汤合泻白散，加西洋参、贝母、花粉、黄芩，大剂投之，并用北梨捣汁，频饮润喉，以缓其上僭之火。数帖后势渐减，改投苇茎汤合清燥救肺汤，加海䖳、蛤壳、青黛、荸荠、竹沥为方，旬日外梨已用及百斤而喘始息。继加坎版、鳖甲、犀角，而以猪肉汤代水煎药，大滋其阴而潜其阳。（此却不必，以病者难服也，何不另用之。）火始下行，小溲赤如苏木汁，而诸证悉平，下部之肿，随病递消，一月已来，共用梨二百余斤矣。适大雪祁寒，更衣时略感冷风，腹中微痛，自啜姜糖汤两碗，而喘嗽复作，口干咽痛，大渴舌破，仍不能眠。复用前方，以绿豆煎清汤代水煮药，始渐向安。孟英谓其乃郎步梅曰：《内经》云：阴精所奉其人寿。今尊翁阴液久亏，阳气独治，病虽去矣，阴精非药石所能继续，况年逾六秩，长不胜消，治病已竭人谋，引年且希天眷，予以脉察之，终属可虞，毋谓治法不周，赠言不早，致有他日之疑成败之论也。", "13806": "张郑封室，娩后即发热，服生化汤二帖，热益炽，而发赤疹。顾听泉诊之，即与清解，三剂不应，欲进犀角地黄汤，而恐病家之狃于产后以生疑也，乃拉孟英质之。诊其脉弦滑而数，面赤热燥，胸闷善悲，肢肿而疼，两时白泡如扁豆大者数十颗，舌上亦有一颗痛碍食饮，大便不解，已旬日矣。曰：此不但胎前伏暑，且有蕴毒，而误服生化汤以助其虐，幸初手即用清解，尚不致于昏陷，犀角地黄极是治法，犹恐不能胜任。乃与听泉商加西洋参、滑石、知母、银花、花粉、人中白、蒌仁、竹黄、贝母、桑叶、栀子为剂。其所亲曰：高明断为热证，何以病者虽渴而喜热饮耶？孟英曰：此方中所以多用痰药也。凡胸中有热痰阻碍气机者每如是，不可以其向不吐痰，而疑吾言之妄也。若因此而指为寒证，则祸不旋踵矣。进四帖，始得大解，频吐稠痰，而各恙皆减，饮食渐加。孟英曰：病势虽稳，余热尚炽，苟不亟为清涤，而遽投补益，犹有蓐损之虞。其母家果疑药过寒凉，必欲招专科调治，幸将前方示彼，尚不妄施温补，然隔靴搔痒，纪律全无。旬日后余火复燃，郑封坚恳孟英设法，仍用甘寒疗之。周身肤蜕如蛇皮，爪甲更新，其病之再生也可知。继与滋补真阴而起。", "13807": "郑某吐血盈碗，孟英脉之，右关洪滑，自汗口渴，稍一动摇，血即上溢，人皆虑其脱，意欲补之。孟英曰：如脱惟我是问，与白虎汤加西洋参、大黄炭，一剂霍然。", "13808": "季秋顾听泉邀孟英视康康侯副转之恙，切其脉滑数，而右歇左促，且肝部间有雀啄，气口又兼解索，望其面宛如薰黄，头汗自出，呼吸粗促，似不接续，坐卧无须臾之宁，便溺涩滞，浑赤极臭，心下坚硬拒按，形若覆碗，观其舌色，边紫苔黄，殊不甚干燥。问其所苦，曰：口渴甜腻，不欲饮食，苟一合眼，即气升欲喘，烦躁不能自持，胸中懊𢙐，莫可言状。孟英曰：此由湿热误补，漫无出路，充斥三焦，气机为其阻塞而不流行，蔓延日久，津液为之凝滞而成痰饮，不啻人禽杂处，苗莠同畴，邪正混为一家。医见肢冷自汗，不知病由壅闭而然，欲以培正，而邪气方张，得补反为树帜，岂非资寇兵而赍盗粮哉？非其类者锄而去之，乃为吃紧之治。听泉曰：良是也。夏间起病，闻自心悸少寐，杨某以为虚而补之，时尚出差办事，暑湿外侵，受而不觉，迨闱差未竣，其病斯发，而诸医之药，总不外乎温补一途，以致愈补愈剧。今拟温胆法待君可否？孟英曰：脉证多怪，皆属于痰，今胸痞如斯，略无痰吐，盖由痰能阻气，气不能运痰耳。宜于温胆中加薤白、蒌仁，通其胸中之阳；又合小陷胸为治饮痞之圣法；参以栀、豉泄其久郁之热，以除懊𢙐；佐以兰草，涤其陈腐之气而醒脾胃。听泉深然之。连投二剂，各恙皆减，脉亦略和，而病者以为既系实证，何妨一泻而去之。连服大黄丸二次，承气汤半帖。孟英急止之曰：畏虚进补固非，欲速妄攻亦谬。盖湿蒸为热，灼液成痰，病非一朝一夕而成，治以上下分消为是，不比热邪传府，可一泻而愈也。越日下部果渐肿，孟英曰：攻痞太速之戒，古人不我欺也。与听泉商以前法加黄芩合泻心意，再配雪羹投之，痰果渐吐，痞亦日消，而自腹至足，以及茎囊，肿势日加。孟英谓：势已如此，难以遽消，但从三焦设法，则自上而下，病必无虞。与听泉商用河间桂苓甘露饮意。而姚平泉孝廉，力主崇土胜湿之法，深以寒凉为不可用，众议仍投前日之药。孟英曰：前药原可服也，嫌力不足耳。次日痰中带血甚多，孟英曰：湿热薰蒸不已，自气及营矣。与听泉暨王子能参军，商以知、柏、生地、犀角、鳖甲、白芍、苡仁、贝母、石斛、茅根、麦冬、滑石、栀子、藕汁、童溺，投之而止。逾数日又吐，且肢冷自汗，心馁畏脱。姚平泉谓气不摄血，当主归脾汤以统之。举家皇皇，连请诊脉者三次。孟英曰：脉来屡变，陈芝江所以不能指实其病，而杨、阮诸人，皆疑为大虚之候也。然望闻问切，不可独凭于指下，今溲如赭石汤、浑赤有脚，其为湿热之病，昭昭若揭。初伤于气分，则津液受灼以为痰，渐及于营分，则阴血不安而妄溢，邪气内盛，岂非病实，而真实类虚，吾不受病之欺也。坚守前议，静镇不摇，服二剂果止。孟英曰：血之复吐也，由于气分之邪以扰及也，欲清气道之邪，必先去其邪所依附之痰。盖津液既为邪热灼烁以成痰，而痰反即为邪热之山险也，不妨峻攻其实，而缓行其势。（眉批：前云不可妄攻，此又投峻下之剂，何也？盖前徒攻其热，故不中病而致生他证，此则直攻其痰，始能与病相当也。）初进滚痰丸三钱，得下泄气一次。副转云：四十日来未有之通畅也。连投数日，始解胶痰黑矢多遍，而小溲亦渐清长，苔色亦退，寝食遂安，惟下部之肿犹尔也。马香崖、陆虚舟皆主实脾行水之法，孟英曰：谛参脉证，病不在脾，况善饥便燥，口渴溺多，吾方虑转消证，亟投甘润之不遑，恶可渗利伤阴，补土劫液耶？且脾虚下陷之肿，与湿盛而肿之肿，其膝之上下内外形势，必然相贯。今膝之上下内外凹凸迥判，毫不毗连，盖由湿热所酿之痰饮，既误补而痞塞中焦，复妄攻以流窜隧络，所谓不能一荡而蠲，势必旁趋四射，吾当以法取之。会又咳痰带血，而精神食饮如常。孟英曰：无恐也，此乃前次嚼三七太多，兜涩留瘀，最不宜用，吐而去之极妙，但须金水同治，冀咳止而血络不震动为要耳。与甘露饮加藕汁、童溺服之。四剂而止，咳嗽亦宁。于是专治其下部之肿以固本，加知、柏、贝母、花粉、旋覆、橘络、丝瓜络、羚羊角、楝实、葱须、豆卷、薏苡、竹沥，出入为剂。二三贴间，其高突隆肿之处，即觉甚痒，搔之水出如汗，而作葱气。六七日后，两腿反觉干瘦燥痛，茎囊亦随之而消矣。孟英曰：用此润药消肿，尚且干痛咽燥，设从他议而投燥脾利水之法，更当何如哉？盖寒湿则伤阳，热湿则伤阴，血液皆阴也。善后之法，还宜滋养血液，稍佐竹沥以搜络中未净之痰，使愈后不为他日之患，更属法中之法。服之饮食中节，便溺有权，幸无消渴之虞，而竟愈焉。", "13809": "周菊生令正，患少腹酸坠，小溲频数而疼，医投通利不效，继以升提温补，诸法备试，至于不食不寐，大解不行，口渴不敢饮水，闻声即生惊悸。孟英脉之曰：厥阴为病也，不可徒治其太阳。先与咸苦以泄其热，续用甘润以滋其阴，毫不犯通渗之药而愈。", "13810": "尝闻有是病，即有是药。但些小之病，脏气固有抵抗病菌之能力，虽不药亦能自愈。若偶遇疑难危症，认为寒者必投热；认为热者必投寒；认为虚者必投补；认为实者必投泻；虽广延诸医于一堂，其主见必各是其是，际此吉凶反掌之时，反令人茫无适从，甚至日易多医，不问寒凉补泻，遇药即投，直至气绝人亡，病家亦竟委之于寿命，听之于大数。呜呼！兴言及此，不胜扼腕。讵知皆由后人学识未精，审证不确之误耳！苟能推寻奥妙，研究精微，博览前人医案，参察脉理，一思百虑，感而遂通，鲜有不能取效者。俞桂庭先生云：医理深微，非上智不能讨究。以百人习医，无十人成就。成就之中，无一人精通。得一明医，谈何容易。然事在人为，贵乎自立。如王甥孟英之锐志于医也，足不出户者十年，手不释卷者永夜。迩年在婺屡起沉疴，余每闻而喜跃。所有历年治验，曾令其须存底稿。史缙臣先生亦云：无论内外大小，一年之中，岂无一二奇证，若怀之于胸臆，则近于秘道不传，何不将所治奇病，现何证、服何药、如何疗、如何愈以为医案，使后人有迹可循，而无识认不真之憾。俞氏又云：缙臣先生亦有此话，可谓先得我心。世之为医者，遵史氏之格言，效吾甥之苦志，出而问世，必可加人一等也。孟英之留存案，可谓承舅氏之遗训，遵史氏之格言，久而行之，渐积成卷。迨癸卯冬，周君光远，选刊自道光甲申迄癸卯医案二卷，曰《回春录》。张君柳吟等，复集甲辰至庚戌医案七卷，题曰《仁术志》。咸丰丁亥春，杨大令素园，重为删定，详加评点，附霍乱于后，合梓于江西，改题曰《王氏医案正续编》，总刊于江浙，久已脍炙人口。后如徐君亚枝等，续采自辛亥至咸丰甲寅之验案，亦名《王氏医案三编》，然仍编年之例，以期递增无已也。又如乙卯至丁巳医案，由先生自编，即《归砚录》之卷四是也。其余验案，散见于《古今医案按选》及《洄溪医案》、《名医类案》者亦不少。惟《医案三编》及《归砚录》，刻于《潜斋十种》之末，原版已遭兵燹，且后无翻印行世，故流传甚稀。民国元年，李氏校刊《潜斋八种》，亦未采此二种。余于丁巳秋，偶在旧书肆，得《潜斋十种》，备重价购归，恐再散佚，为此即谋石印，并增王案正续编，冠于三编前，俾相接续，而成全璧。余尝读先生案，益佩先生敏而好学，尝寝馈于医学，更能参究性理诸书，以格物穷理，故审病辨证，能探虚实，察浅深，权缓急，每多创辟之处，然仍根据古书。其裁方用药，无论用补用泻，皆不离运枢机，通经络，能以轻药愈重证，为自古名家所未达者。更有自始至终，一法到底，不更方而愈者。良由读书多，而能融会贯通，悟超象外。故杨氏有云：王氏医案，议论精透，前无古人。周氏谓其治病若天授。皆不易之定评也。", "13811": "辛亥春，孟英治其令正，诞子三朝，忽浑身麻冷，寻即壮热大渴，汗出不解，耳鸣眼泪，舌绛无津，苔色燥黄，腹痛拒按，不饥脘闷，恶露仍行，小溲极热，脉则弦滑右甚。是胎前吸受风温，兼挟痰食内滞，虽新产血去阴伤，见证较剧，然病不在营，亟宜撤热以安营，不可破血以伤营，亦不可养阴而助病。遂以元参、白薇、栀子、知母、竹茹、旋覆、菖蒲、枳实、栝蒌为方，服之热虽退而脉不减，仍用此方。越二日复麻冷而后热，惟舌稍润，苔较薄耳；再饮之，热亦即退，并吐胶痰数碗，略进稀糜。间一日又发寒热，或疑为疟，或疑分娩不易，用力劳伤，恐是虚证，苟不及早温补，蓐损堪虞，孟英一一颔之。复与前药，热果渐短，渴亦递减。逾日寒热犹来，亦不更方。至十一朝，始下黑燥矢而寒热乃休，即能安谷。计服此药已十大剂矣，始出方与戚䣊阅之，盖恐眷属之预闻凉解而有阻挠也，诸亲莫不駴诧。然此证非孟英独断独行，断难成功。设泥新娩而通瘀，或以为疟而温散，或疑其虚而滋补，势必骤变，即有瞻顾，亦必邪热纠缠而延成蓐损。世人之病，往往弄假成真者，大率类此。", "13812": "王瘦石令郎迟生，年未冠而体甚弱，夜梦中忽如魔如惊，肢摇目眩，虽多燃灯烛，总言黑暗，醒后纳食如常，月一二发。乃父以为忧而商于孟英。脉之弦细而涩。曰：真阴不足，肝胆火炎所致耳。令服神犀丹一月，病遂不发。继予西洋参、二地、二冬、三甲、黄连、阿胶、甘草、小麦、红枣熬膏服之，竟刈其根。逾年完姻，癸丑已生子矣。", "13813": "朱绀云令正，去年娩后，自乳而月事仍行，至仲冬乳少汛愆，咸以为妊也。既而右胁筋绊作疼，渐至肩背。医投平肝药，痛益甚，改用补剂，遂嗽痰带血，人皆以为损矣，广服温补，其病日增。延至仲春，卧榻已匝月，群医束手，始求诊于孟英。面赤足冷，时时出汗，食减无眠，脉来右寸溢，关尺滑而微数，左手弦而带滑，舌赤而润，微有白苔，气逆口渴，所吐之血淡红而夹痰涎，大解溏，小溲短且热。曰：冲为血海而隶于阳明，自乳而姅不爽期者，血本有余也。因阳明经气为痰所阻而不能流通输布，致经断乳少，痰血𫐖轕而为络痹窜痛，医者不为分导下行，病无出路，以致逆而上溢，再投补剂，气愈窒塞，在山过颡，夫岂水之性哉！予苇茎汤加茜根、海螵蛸、旋覆、滑石、竹茹、海䖳为剂，和藕汁、童溺服，以肃肺通胃，导气化痰而领血下行，复杯即愈。旬余汛至，不劳培补，寻即受孕。此证不遇孟英，必至补死，而人亦但知其死于虚劳也，服药可不慎耶！", "13814": "韩贡甫于去冬偶患足疮，疡科治之，疮愈而大便下血，渐至腰背疼胀。医谓其虚，率投温补，病日以剧。迨仲春寒热时作，卧榻不起，诸医束手，已治木矣。所亲陈季竹嘱延孟英图之。脉弦缓而涩，苔黄溺赤，饮食不思，曰：此药病也，良由气机郁滞，湿热不清，补药乱投，病渐入血，然犹自寻出路，奈医者不知因病而下血，不治其病，徒涩其血，则气机愈窒，营卫不通，寒热不饥，固其宜也。而又疑为土败阴亏，脾肾两补，药力愈峻，病势愈危。若我视之，原非大病，肯服吾药，不日可瘳。乃兄聪甫闻之，大为折服，以海䖳芦菔汤煎芦根、厚朴、丝瓜筋、通草、白薇、栀子、楝实、竹茹等药投之。三剂而寒热不作，胃渐知饥。旬余血止溺澄，各恙皆已，改服清养药而康。", "13815": "殳某久患寒热，精遗自汗，能食神疲，肌肉渐瘦，诣孟英诊之。脉大微弦，予黄耆建中，加参、归、龙、牡而瘥。", "13816": "钱希敏室坐草二日，即未分娩，忽患小便不通，势甚亟，乃速孟英视之。脉至滑数，睛赤口干，以为热结膀胱，气不化达。予车前子、滑石、血余、栝蒌、知母、栀子、牛膝、紫菀、紫草为大剂投之，是通溺催生互用之法。服后溲仍不行，径产一男，既而胞下，溺满其中，始知儿出胞后，频饮汤水，尽贮其中也。孟英曰：此证古所未闻，余虽初不料其如此，然非开泄导下，则儿不即娩，吉凶未可知矣！而《折肱漫录》云：孕妇将产，如患小便不通，乃脾气虚弱，不能胜胞，故胞下坠，压塞膀胱使然，宜重剂白术大健其脾，则胞举而小便自通者，正与此证虚实相对，想其脉必有虚微之象也。", "13817": "幼科王蔚文之甥女，向依舅氏。于三年前患热病甚危，服多剂凉解始愈。第寝食虽如常人，而五心恒热，黑苔不退，口苦而渴，畏食荤膻，频饵甘凉之药，经来色黑不红。去年适吴氏，仍服凉药，迄不能痊。今夏伊舅氏浼孟英诊之，脉甚滑数。曰：此热毒逗留阳明之络，陷入冲脉，以冲隶阳明也。然久蕴深沉，尚不为大患者，以月事时下，犹有宣泄之路也。其频年药饵，寒之不寒者，以热藏隧络，汤剂不能搜剔也。令每日以豆腐皮包紫雪五分吞下。半月后，苔果退，渴渐减，改用元参、丹参、白薇、黄芩、青蒿煎汤，送服当归龙荟丸。又半月经行色正，各恙皆蠲，寻即受孕焉。", "13818": "朱生甫明经令郎仲和，于六月初旬患疟，寒少热多，呕渴痞闷，逆孟英视之。曰：曩曾屡患此疾，证形大略相同，广延名手治疗，总难即愈，病辄经年，大受其累。闻君疗疟极神，不知能否于月内即痊？孟英曰：何限之宽耶！余非神于此，盖寒暑燥湿风五气之感于人也，重则为伤寒，轻则为疟疾，今所患者，暑湿之疟也。清其暑湿，旬日可瘥。前此之缠绵岁月而不能已者，必是不分五气之源流，徒以见疟治疟，而用柴胡、姜、枣等风疟之方，以致暑湿之邪滋蔓难图耳。兹以清暑化湿汤奉赠，放胆服之，不可商于人，恐其于五种伤寒未能辨晰，而泥少阳正疟之法以相争也。仲和韪之。方用石膏、杏仁、半夏、厚朴、知母、竹叶。果八剂而安。既而梁甫之仲郎亦患疟，孟英视曰：脉数舌绛，热炽寒微，素质阴亏，暑邪为患也，更不可稍用疟门套药。予元参、青蒿、白薇、丹皮、黄菊、知母、花粉、银花、竹叶、栀子。数帖而病减，乃去青蒿、丹皮，加生地、甘草，数服而瘳。", "13819": "石北涯之大令媳患疟，壮热如焚，背微恶冷，汗多大渴，舌绛神烦，不食不眠，奄奄一息。亟迓孟英诊之。脉细数而芤，知其阴分久亏，暑邪深入，遂予白虎汤去米，加西洋参、元参、犀角、竹叶、银花、石斛为方，六剂而愈。人皆闻而异之，孟英曰：见病治病耳，何异之有？然与见疟治疟，而不治其所以疟者，固有异焉。", "13820": "韩正甫患疟，越医王某进以柴、桂、姜、朴等药，势乃剧。所亲何新之知为药误，改用清解而不效，始乞诊于孟英。脉数而右更滑大搏指，胸闷不堪，溲赤而渴，苔极垢腻，以凉膈散去芒硝、甘草，合雪羹加厚朴、杏仁、石膏、半夏、石菖蒲。投四帖，频下宿垢，各恙皆减，改投轻清以涤余邪，遂以向愈。其时渠兄贡甫之室，患疟初起，肢麻且冷，口渴苔黄，眩瞀善呕，心烦无寐。孟英诊曰：此亦暑湿为疟，不可温散者。而越医劝服术、朴、姜、椒等药，病家闻用温化，恪信弗疑。二剂后，呕渴愈甚，经不当期而至，四肢终日不温，汗频出而热不休。再邀孟英诊之，脉渐伏，曰：此热深厥深之谓也，温燥热补，切弗再服。病家不信，另招张某、黄某会诊。佥云阴暑，宜舍时从证，径用姜、附、六君，加萸、桂、沉香等药服之，肢愈冷，药愈重。八剂后，血脱如崩而逝，即以春间为贡甫所治之棺殓焉，岂非数已早定耶！故虽一家之中，同时之病，而疑信不同，死生判别，况春间贡甫之病，治有成效，尚蹈此辙，无怪乎求未经目击温热之害者，宜其以服凉解药为可耻矣。", "13821": "吾师赵菊斋先生令郎廉士之如君，新娩后微寒壮热，小溲全无，恶露稍行，大便如痢，神烦善哭，大渴不眠，专科谓疟痢交作，不能图治，遂请孟英援手。脉来洪大滑数，曰：暑为患耳，不必治其疟痢。以辰砂益元散加竹叶、银花、丹皮、木通、元参、丹参、莲杆，为大剂投之。三帖各恙皆平，第营阴素亏，即改甘凉濡养善后而愈。尚且乳汁全无，显由血少，设非清解，又当何如耶？继有表弟潘少梅乔梓同时患暑湿疟，孟英咸与清化法，数剂皆愈。潘反生疑，谓病邪被凉遏伏，故疟遽止，恐将来必有他患。孟英喟然曰：甚矣！医之不可为也。世人患疟，苦无良治，缠绵不愈，习见不疑。余之治疟则不然，但专力治其所以病，故疟疾虽与伤寒同有五种之别，而受病究比伤寒为轻。苟治之如法，无有不数剂而愈者。设误药以遏其邪之出路，则苔不能化，溲不能澄，神不能清，食不能进矣。子自思之，其真愈乎？抑假愈乎？潘始恍然大悟而首肯焉。", "13822": "蔡西斋令正，腹有聚气，时欲攻冲，医者以为下部虚寒，进以温补摄纳，如桂、附、沉香、芦巴、故纸、吴萸之类，愈服愈剧。酷暑之时，其发益横，日厥数十次，医皆望而却走，乃迎孟英视之。脉数舌绛，面赤睛红，溺如沸汤，渴同奔骥，少腹拒按，饥不能餐，曰：事急矣，缓剂恐无速效。令以豆腐皮包紫雪一钱，另用海䖳、凫茈煎浓汤，俟冷吞下，取其芳香清散之性，直达病所也。服后腹如雷鸣，浑身大汗，小溲如注，宛似婴儿坠地，腹中为之一空，其病已如失矣。继有许梅生八令爱，患痛厥屡日，筋掣神迷，肢冷息微，脉伏唇紫，多药无效，孟英亦以此药灌之而苏。", "13823": "新秋汪子与室寡居患疟，范某叠进小柴胡法，昏热欲厥，腹痛汗淋，人皆危之。乃祖朱椿年太史逆孟英往视。两尺空数，左关弦寸溢，右寸关滑驶。曰：此真阴素亏，腹有聚气，吸受暑热，最忌升提。与元参、西洋参、百合、竹叶、莲子心、鳖甲、牡蛎、楝实、小麦、黄连等药，两剂而减。其族人谓疟禁凉剂，而尺脉无根，苟非温补，猝变可虞，母家不从，两疑莫决，因请乩方服之。数日后势复剧，苔渐黑。伊父朱次膺仍乞援于孟英。及诊脉更数于前，因于前法中加犀角，两帖而安。续以滋潜善其后而愈。", "13824": "汤振甫患疟于嘉兴，医知为暑，与清解法，转为泄泻，以为暑去而湿存，改用温燥，泻益甚而发热不休，神气昏瞀，因而束手，令其买棹旋杭。所亲陈雪舫延孟英视之。苔黑面红，胸间拒按，便如胶漆，小溲全无，谵妄耳聋，不眠善笑，脉则洪数而芤。予黄连、黄柏、黄芩、银花、石斛、栀子、楝实、知母、蒌仁、元参为方，绿豆煎清汤煮药，调下神犀丹。四剂而胸次渐舒，稍啜稀粥，便色渐正，小溲亦通，乃去神犀、楝、柏，加生地、石膏。服三日热净神清，脉来柔缓，以甘凉养液十余剂而瘳。大凡温热暑证，而大解溏泄者，正是热邪下行，岂可误投温燥之药，反助燎原之势哉！同时一男子患感濒危，浼孟英勘之。神昏舌黑，瘛疭脉微，曰：迟矣！此犀角地黄证，惜无人用。病家云：陆某已屡用之矣。因索其方阅之，虽用犀角屑八分、生地五钱，缘病者便溏，配以枳壳炒焦白术三钱。孟英喟然曰：此方从无如此加减法，况清凉不敌温燥，是徒有犀角地黄之名耳。古人治病，必放出路，兹反截其去路，良由学无理路，遂致人无生路，良可哀也！（眉批：近日庸手每多患此，全不揣摹古人处方之义，复方之法，矛盾混施，深堪痛恶。又犀角与枳术合方，可谓善做截搭题，一笑。炳章志）", "13825": "朱次膺令正，姅后偶有微寒微热，医与解散药一剂，遂神疲自汗，不食不眠，泛泛欲呕，时时欲晕，肢麻且软，气欲上冲，舌赤微苔，溺频脘痛，便溏不畅，目不欲张，心悸懒言，欲噫不达。孟英察其脉，虚弦软数，曰：此营阴素亏，忧愁劳瘁之余，血从下夺，八脉交虚，正所谓阳维为病苦寒热，阴维为病苦心痛也，岂可以有寒热而即从疟治哉！授以龟板、鹿角霜、当归、枸杞、白薇、紫石英、甘草、大枣、小麦、牡蛎，数剂而安。嗣与熟地、枣仁、当归、杞子、麦冬、楝实、苡仁、黄连，壮水和肝而愈。", "13826": "陈妪年已七旬，患霍乱转筋甚危，亟拉孟英救之，已目陷形消，肢冷音飒，脉伏无溺，口渴汗多，腹痛苔黄，自欲投井。令取西瓜汁先与恣饮，方用白虎加芩、连、黄柏、木瓜、威灵仙，略佐细辛分许为剂，复杯即安。人皆疑用药太凉，何以径效？孟英曰：凡夏热亢旱之年，入秋多有此病，岂非伏暑使然，况见证如是之炽烈乎？今秋余已治愈多人。询其病前有无影响？或曰：五心烦热者数日矣；或曰：别无所苦，惟睹物皆红如火，已而病即陡发。夫端倪如此，更为伏暑之的据焉。", "13827": "李华甫继室，陡患霍乱而兼溺血如注，头疼如劈，自汗息微，势极危殆，迎孟英诊视。脉极弦驶，是肝阳内炽，暑热外侵。先用犀角、木通、滑石、栀子、竹茹、薏苡、银花、茅根、菊叶为大剂，和入藕汁，送当归龙荟丸，而霍乱即安，惟溺血虽减，而小溲时头犹大痛，必使人紧抱其头，重揿其巅，始可略耐。尚是风阳僭极，肺胃不清也。以苇茎汤去桃仁，加百合、白薇、元参、竹叶、西瓜翠衣、菊叶、莲子心为方，和入童溺，仍吞龙荟丸，服旬日而愈。继有祝氏妇患溺血五六年矣，医皆作淋治。孟英诊视脉弦数，苔黄口苦，头疼溺热，曰：是溺血也，法宜清肝，与久淋当滋补者迥殊。病者极为首肯，盖其出路自知，而赧于细述，故医者但知其为淋也。", "13828": "陈楚珍仲媳，陡患霍乱，亟迓孟英治之。云：昨晚曾食冷鱼，夜深病作，想由寒重致此，然脐间贴以回阳膏而不效奈何？及诊脉右甚滑数，口渴苔黄，令按胸下，果坚硬而痛，曰：吐泻虽多，宿食恋膈，非寒证也。回阳膏亟为揭去，以石菖蒲、枳实、苏叶、黄连、半夏、竹茹、海䖳、芦菔为方服之，一剂霍然。", "13829": "同门相简哉室患疟，始则消散，继则补中益气，治之匝月，萎靡不堪，腹中似有聚气，时欲上冲，气促心摇，汗多眩晕，左胁震跃，渴饮无眠，骨瘦如豺，医皆束手。吾师赵菊斋先生拉孟英往诊。脉弦细以数，按之不鼓，因谓相曰：不可再以疟字横于胸中，则旬日可安。若见其久疟而欲截之，且闻前医谓令正初次患疟为胎疟，务令发透，不妨形瘦似鹤，此皆非余之所知也。夫一生不患疟者有之矣，未闻先在胞中患过疟疾而后生者也。若以初次患疟为胎疟，则他病之初患者，无不可以胎字冠之矣。何以不闻有胎痢、胎伤寒之名乎？因医者治疟而不知治其所以疟，以致缠绵难愈者多，遂妄立胎疟、鬼疟等名以绐世俗而自文其浅陋，今昔相沿，贤者不免，故世人又有疟疾不可服官料药之戒，其实药亦何尝有官私之别耶？服药不当，皆能增病，不服药为中医，不仅为疟疾而言也。令正素禀阴亏，感邪不重，过投消散，营液重虚，再升其阳，本实欲拨，补中益气，原是成方，与证不宜，于体不合，即为毒药，我仪图之。介类潜阳，重镇理怯，甘酸化液，厚味滋阴，大剂而投，肤功可奏。相极感服，如法服之，果未浃旬，霍然病已。方以西洋参、熟地、牡蛎、紫石英、龟板、鳖甲、枸杞、当归、冬虫夏草、龙齿、阿胶、麦冬、龙眼、甘草、蒲桃干、红枣、莲子心、小麦等，出入互用也。", "13830": "王雨苍室，仲秋患滞下，治两旬而罔效。何新之荐孟英往视。脉来弦数而滑，腹坠腰疼，溲少口干，面红烦躁，知饥能食，夜不成眠，而滞下赤白，从无粪色相兼，及至更衣，又极艰涩，略无痢色相杂，通补温凉，服皆不应，稍投升举，气塞于胸，询其月事，因痢愆期。孟英曰：此病不在肠中也，能食便坚，府气并不窒滞，阴虚木旺，营液因而旁溢，缘冲任隶于阳明，平人气血循经，各行其度，岂有冲任之血液，可从大肠而出之理乎？然天地虽有定位，山泽可以通气，周身脉络，原自贯穿，挹彼注兹，风阳所煽，犹之交肠证粪从前阴而出，举一反三，病机可悟。何极叹服。爰以乌鲗、茜根、阿胶、鲍鱼、苁蓉、枸杞、柏子仁、黄柏、银花、藕为剂。一服即减，不旬而瘥。续参熟地、当归、龟板、鹿霜善后而愈。（鲍鱼，淡干鱼也。诸鱼皆可为之，然以石首鱼为胜，俗谓白鲞是也。惟台州三伏时所干者，味淡而香，色白尾圆，世称松门台鲞，可以入药，无腥咸作吐之弊，其误用蝮鱼者，盖失考也。）", "13831": "洪张伯孝廉令弟苏仲，乡试后自以场作不惬于怀，怏怏数日，渐以发热，医作伏暑治，日形困顿，懒语音低，神情恍惚，稍合眼辄以文有疵累如何中式云云。屡服牛黄、犀角等药，竟无寸效。延孟英视之。时时出汗，不饥溺少，舌绛口干，切脉虚软以数，曰：此心火外浮也。昔贤惟王损庵论之独详。今人罕读其书，每与温暑逆传证混淆施治。夫心，犹镜也，彼热邪内陷，袭入心包，则雾障尘蒙之象也，故可磨之使明，是为实证，今心阳过扰，火动神浮，乃铜质将熔之候也。法宜坚之使凝，是为虚证，良由阴分素亏，心营易耗，功名念切，虑落孙山，病属内伤，似乎外感，大忌发表，更禁寒凉，又非东垣补中益气之例，无怪医者为之技窘也，而有药治病，无药移情。余有一言，可广其意：文之不自惬于怀者，安知不中试官之意乎？且祸盈福谦，《易》之道也。尝见自命不凡者，偏不易售，而自视欿然之士，恒于意外得之，即此一端，吾可必其中也。病者闻之，极为怡旷，服药后各恙渐安，半月而愈。及榜发，果获售。佥云：药即神妙，而慧吐齿牙，竟成吉忏，仁言仁术，医道通仙，可于孟英信之矣。其方则甘草、干地黄、麦冬、红枣、枸杞、盐水炒黄连、紫石英、龟板、龙齿、珍珠也。迨季冬，两孝廉将北上，其母夫人陡病恍惚，孟英往诊曰：高年素多忧虑，而别离在即，神倏飞扬，纵有仙丹，亦难救药。另邀他医视之，皆云冬温，须过十四日。及旬而没，神气不昏，始信孟英镜质消熔，与尘蒙雾障有殊也。", "13832": "一妪患面目肢体浮肿，便溏腹胀，肠鸣时痛，饮食日减。医与理中、肾气多剂，病日剧而束手矣，始丐孟英诊焉。按脉弦细，沉之带数，舌绛口干，肿处赤痛，溺少而热。乃阴虚肝热，郁火无从宣泄而成此病，火愈郁则气愈胀，气愈胀则津愈枯，再服温燥，如火益热矣。授白头翁汤加楝实、银花、元参、丹皮、绿豆皮、栀子、冬瓜皮数剂。证减知饥，渐佐养血充津之品而愈。前此诸医谓其山居久受湿蒸，且病起霉雨之时，而又便溏脉细，遂不察其兼证而群指为寒湿也。嗣有黄梅溪令堂，患证类此，而燥热之药服之更多，肌削津枯，脉无胃气，邀孟英往勘，不遑救药矣。", "13833": "石北涯仲媳，胎前患泻，季秋娩后，泻如漏水，不分遍数，恶露不行，专科束手，咸虑其脱，亟孟英脉之。左弦而数，右大不空，口苦不饥，苔黄无溺，曰：非虚证也。参汤断弗沾唇。予白头翁合石顽伏龙肝汤丸治之。一剂知，三剂愈。", "13834": "孙位申陡患喉偏左痛，下及乳旁，神疲欲卧，动即凛寒，速孟英视之。脉弦细以软，苔薄白，口不渴，痰多且韧，溺赤不饥。是暑湿内伏而肝郁不舒，且阴兮素亏复伤劳倦也。昔人之清暑益气汤、藿香正气丸，皆是成法，设误投之，悉为戈戟。幸病家深信不疑，旁无掣肘。予射干、兜铃、蒌壳、通草、滑石、竹茹、丝瓜络、冬瓜子、枇杷叶、荷杆极轻清之药一剂，即吐胶痰数碗，汗出周身，喉痛较松，凛寒亦罢，而身痛微热，苔色转黄。去射干、兜铃，加栀子、豆卷服之。热退痛减，再去滑石、豆卷，加石斛、沙参、野蔷薇露投之，知饥啜粥，诸恙悉安。嗣用养阴充液而愈。", "13835": "施玉林患感，治经多手，延将匝月，热退未净，苔腻垢黄，脘闷便溏，腰痛溺短，不饥不眠，气短音低。医者技穷，李华甫荐孟英视之。脉弦软不调，而尺中虚细，是痰热尚结于上焦，房劳素伤于下部，初治即从清解，并无背谬之方，奈不足以开有形之结，而滋久耗之阴，以致旷日相持，神气日形消索也。以小陷胸汤加苇茎、竹茹、枇把叶、兰叶、石斛、归身、枸杞为方，加野蔷薇露和服。一剂苔即化，三服而结粪下，胸乃舒，去蒌仁，加西洋参服四帖，苔净能餐，诸恙冰释。续投峻补肝肾而康。", "13836": "儒医何新之素患脘痛，每日必吐水数缶始舒畅，吐后啖面食肉，如汤沃雪，第不能吃饭者十余年矣。季秋痛吐益甚，饮食不进，平肝通络，诸治不瘳，人极委顿。屈孟英视之。脉弦滑而软，曰：中虚停饮也。以六君去甘草，加桂枝、厚朴、牵牛。服之积饮果下，痛亦渐休，吐止餐加，精神稍振，乃去牵、朴，加附子、白芍、薏仁与之遂愈，且能吃饭。病者谓既能吃饭，善后药不肯多服。迨仲冬中旬出门诊疾，骤与严寒，归即痛作，连服荔香散数日而逝。盖中气素虚者，不可专用香散之药也。", "13837": "许兰屿令正，自夏间半产后患感证，虽已治愈，而腰腹左痛时作，多医杂治，其痛日增，食减汛愆，卧床不起。黄某谓诸药无功，惟有肾气汤先固其根本。频服之，痛益剧，且痛作之时则带下如注。黄谓显系真火无权，附、桂复为加重，遂至痛无停晷，呻吟欲绝。陈春湖嘱迎孟英诊之。左关尺弦数无伦，形消舌赤，彻夜无眠，是肾阴大亏，肝阳极炽，营液耗夺，八脉交虚之证也。用龟板、乌鲗、苁蓉、枸杞、归身、楝实、竹茹、白薇、黄柏、丝瓜络、蒲桃干、藕为方。一剂知，数剂已。续加熟地，阿胶，调理月余，经行而愈。", "13838": "陈笠塘年近花甲，于初冬时偶从梯半一跌，遂发寒热，痰多咳逆。沈辛甫作虚痰类中挟风温治，热退便行，而痰逆不休，且兼呃忒，改从清肃镇摄，其呃日甚。因拉孟英商之。诊脉左弦涩不调，右兼软滑，察其呃，时有微甚而有欲呃不爽之象，询其喷嚏，久不作矣。曰：此气郁于肝，欲升而不能升，痰阻于肺，欲降而不能降之证也。补摄之品，咸在禁例，以柴胡、枳壳、石菖蒲、紫苏、薤白、蒌仁、竹茹、橘皮、白前为剂。复杯而减，再剂而安。", "13839": "翁笠渔素健啖，偶患发热，钱某谓劳倦内伤，进补中益气法，病日剧。张某诊为停食感冒，用承气法下之，连解黑矢，热如故。与养阴药多剂，热仍不退，且从此不食不便，不渴不眠。佥云：攻补难施，已成坏证。所亲孙诒堂迓孟英诊之。脉形涩数不调，神呆静卧，倦于语言，溺少苔黄，时时面赤，曰：无虑也，卫分之邪失于清解，补中益气实卫锢邪，何异适燕而南其指乎？承气通府，但能下其肠胃有形之物，不能散其卫分无形之邪，下后养阴，固是方法，然必表里皆和者，方可投之。卫气未清，徒增窒滞，枢机日钝，此神识之所以如呆也；升降失司，此出入之所以皆废也。延之虽久，病犹在卫，故可治也。予苇茎、葱豉，加芩、桔、栀子、栝蒌。服一剂而遍身赤疹，神气爽悟，乃去芩、桔、葱，加雪羹、芦菔、银花、兰叶。服数帖解酱矢二十余次，苔退知饥，脉和而愈。", "13840": "真阴素亏，两番半产，兼以劳瘁，内风陡升。病起头疼，左偏筋掣，旬日不语，二便不行，不食唇焦，苔黑边白，胸腹柔软，神气不昏，脉至弦缓，并不洪数。此非热邪内陷，乃阴虚痰滞机缄。宜予清宣，勿投寒腻，转其关键，可许渐瘳。（十月二十五日初诊。）", "13841": "舌稍出齿，未能全伸，苔稍转黄，小溲较畅，羞明头痛，显属风升，咽膈不舒，痰凝气阻，本虚标实，脉软且弦，不可峻攻，法先开泄。（二十六日再诊。）", "13842": "舌能出齿，小溲渐行，神识稍清，苔犹灰滞，头疼似减，语未出声，脉至虚弦，右兼微弱，本虚标实，难授峻攻，开养兼参，庶无他变。（二十七日三诊。）", "13843": "稍能出语，尚未有声，舌色淡红，苔犹灰腻，毫不作渴，非热可知，脉软以迟，不食不便，宜参温煦，以豁凝痰。（二十八日四诊。）", "13844": "苔渐化而舌渐出，语稍吐而尚无音，头痛未蠲，略思粥食，胃气渐动，肝火未平，久不更衣，脉仍弦软，徐为疏瀹，法主温通。（二十九日五诊。）", "13845": "连投温养，神气渐清，语亦有声，头犹左痛，苔退未净，大解不行，左脉微迟，法当补血，血充风息，府气自行。（十一月初一日六诊。）", "13846": "脉已渐起，尚未更衣，浊未下行，语犹错乱，时或头痛，寐则梦多，濡导下行，且为先授。（初二日七诊。）", "13847": "虽已知饥，未得大解，肝无宣泄，时欲上冲，阴分久亏，岂容妄下。素伤思虑，肝郁神虚，脉软而迟，语言错乱。法当养正，通镇相参。（初三日八诊。）", "13848": "神气渐振，安谷耳鸣，脉弱口干，面无华色，积虚未复，平补是投。（十一日十一诊。）", "13849": "许自堂叔岳，年越古稀，忽头面赤肿磊痒，渐及两臂，烦燥不眠，饮食日减，外科治而勿效。孟英脉之弦洪疾驶，重按细软，曰：高年气血两亏，郁火内燔，不可从疡科治。予黄耆、当归、栀、芍、元参、生地、甘草、桑叶、菊花、丹皮、蒺藜、荆芥等出入为方，十余剂而瘳。", "13850": "顾仙槎年越古稀，仲冬偶患痰嗽，服表散药数帖，气喘如奔，欲卧而不能著枕，欲食而不能吸纳，痰欲出而气不能吐，便欲行而气不能送，日夜危坐，躁汗时形，其婿家请孟英视之。按脉虚洪豁大而舌色干绛，溲赤点滴。证属阴亏，忌投刚燥。与西洋参、熟地、苁蓉、枸杞、蒌仁、麦冬、牛膝、茯苓、白芍、冬虫夏草、青铅为大剂，以猪肉煮清汤煎服。果韧痰渐活，坚矢下行，眠食亦安，递以告愈。", "13851": "伤风虽小恙，过表伤阴，与邪未净而早投补剂，皆能延损，其高年下虚而误服升提者，往往阳浮上戴，须以温补救之。更有一种似伤风而实非伤风之证，乃根蒂空虚，肾水泛溢以成痰，浮阳冲逆而为嗽也，此自古未经道及者。今年四月十二日，孟英诣高石泉处谢吊，偶诊其脉，左关尺忽见浮弦而空，因私嘱其次郎隽生曰：尊翁之脉，颇有可虑，子其慎之。继无所苦，方疑其言之未当，虽有小恙，亦未邀诊。迨隽生登贤书，计偕有日，石泉忽患痰嗽，酷似伤风。冯某视之，与解散药一帖，次日便泻数行。黄某进分清药一剂，第三日痰升气逆，自觉唇肿不能啜饮。隽生始忆及孟英之言，速其拯治。脉如蛛丝过指，舌色晦黯无津，唇不略肿，其不能吸饮者，盖由气有出而无入耳，阴既脱于下，阳将脱于上，莫可救药。翼日云亡。此十二月春前事也。闻霜降后许吉斋山长微患伤风，数日而逝。立春后许砚邻亦然，皆同为似伤风证也。据孟英曰：儿子阿心，长成太速，心性太灵，余固知其不秀，秋分后小患伤风，适余酬应纷繁，不遑顾视，且闻无甚大病，亦不延儿科诊视，不料三日后倏然而殇。或云：惜不早治。余谓襁褓而患根蒂之病，虽治愈亦何益哉！然则不必高年虑有此证，即小儿亦间有之矣。医者其可以伤风而概视为小恙哉！《不居集》专论伤风误补成劳，犹是一隅之见焉。", "13852": "孙书三仲郎菊如之室，因儿女过多，不欲生产，怀妊屡服下胎药不应。娩后三朝，陡发寒热，兼以痛泻，所下皆黑，而小溲不行。医作瘀治，用回生丹等药，已觉渐愈，惟寒热间作不休，至八朝，或嘱其邀孟英诊视。神气颇安静，苔色黄腻不厚，胃略知饥，惟右寸关空大，有静中一跃之形。诊毕适前医至，孟英谓右脉不佳，恐有骤变，彼按脉云：较昨已大和矣，必无害也。孟英唯唯而退，菊如送至门外，复嘱以令正元气大伤，莫投峻药而别。继闻是夜寒热复作，腹仍大痛，更服回生丹，越日而亡。", "13853": "书贾陈南桥患冬温，数日后谵语不眠，所亲任殿华竭力清解，热退便行，忽然不语，因迓孟英视之。入房见其危坐于榻，面无病容，两目开阖自如，呼之不闻不答，若无知识者。按脉左寸细数无伦，尺中微细如丝。乃肾阴素伤，心阳过扰，真水下竭，真火将灺，纵有神丹，不能接续。吾师赵菊斋先生暨许少卿皆在座，佥云：渠有八旬老父，一岁孤儿，盍忍契然？勉为设法，如犀角、紫雪之类以图万一，不亦可乎？孟英曰：此非痰滞于络，亦非热传手少阴，适从高、孙两家来，并此为三败证，余一日而遇之，皆无药可用，不敢立方。平素不畏大证，君辈共知，稍有可为，毋劳谆嘱也。既而果逝。", "13854": "李健伯夫人因伤情志而患心跳，服药数月，大解渐溏，气逆不眠，面红易汗，卧榻不起，势已濒危。其次婿余朗斋浼孟英诊之，坚辞不治。其长婿瞿彝斋力恳设法，且云妇翁游楚，须春节旋里，纵使不治，亦须妙药稽延时日。孟英曰：是则可也。立案云：此本郁痰证，缘谋虑伤肝，营阴久耗，风阳独炽，烁液成痰，痰因火动，跳跃如舂，若心为君主之官，苟一跳动，即无生理，焉能淹缠至此乎？但郁痰之病，人多不识，广服温补，阴液将枯，脉至右寸关虽滑，而别部虚弦软数，指下无情，养液开痰，不过暂作缓兵之计，一交春令，更将何物以奉其生？莫谓赠言之不详，姑顺人情而予药。方用西洋参、贝母、竹茹、麦冬、茯神、丹参、苁蓉、薏苡、紫石英、蛤壳等。服之痰果渐吐，火降汗收，纳谷能眠，胸次舒适，而舌色光绛，津液毫无。改授集灵膏法，扶至健伯归。因谓其两婿曰：我辈之心尽矣，春节后终虞痉厥之变也。已而果然。", "13855": "朱仲和令正，向于娩后陡患痉厥，多医以图，广服补剂，其人虽起，厥疾弗瘳，再产亦然，延已数载，安之若素。孟英闻之，尝谓仲和曰：将来受孕，宜预药以痊之。今冬怀妊，病发益频，遂邀过诊。脉甚弦滑，厥前必先作胀，更衣得泻始舒，巅顶时疼，饮食不减。曰：肝风挟痰为患耳！仲和云：肝风则良是，痰则从来未吐。曰：惟其不吐，所以为患。沈尧封谓胎前病痰证居半，产时痰涎不下，诸病丛生，医者未知此理，徒知产后为虚，痰处络中，如何自吐，亦幸而痰在络中，补之不为大害，不过锢之愈深耳，岂可以不见痰面，遂云无痰乎？爰授蠲饮六神汤合雪羹，加蒌仁、竹沥，服三十剂病果渐愈。次年娩后安然，知病根已拔矣。", "13856": "壬子春，沈峻扬年五十七岁，素患痰嗽，年前顾某与小青龙汤一剂，喘逆渐甚。汪某进肾气汤一服，势更濒危。医云治实治虚，不能舍此二法而皆不应，病真药假，不可为矣。王月鉏嘱迎孟英图之。脉来虚弦软滑，尺中小数，颧红微汗，吸气不能至腹，小便短数，大解甚艰，舌红微有黄苔，而渴不多饮，胸中痞闷不舒。曰：根蒂虚于下，痰热阻于上。小青龙治风寒挟饮之实喘，肾气汤治下部水泛之虚喘，皆为仲景圣法。用之得当，如鼓应桴，用失其宜，亦同操刃。所以读书须具只眼，辨证尤要具只眼也。此证下虽虚而肺不清肃，温补反助其壅塞，上虽实而非寒饮，温散徒耗其气液。耗之于先，则虚气益奔；壅之于后，则热痰愈锢，其加病也，不亦宜乎？爰以杏仁、苇茎、紫菀、白前、蒌仁、竹沥开气行痰以治上实，而佐苁蓉、胡桃仁以摄纳下焦之虚阳。一剂知，再剂平。旋去紫菀、白前，加枸杞、麦冬、白石英，服三帖而便畅溺长，即能安谷。再去杏仁、竹沥、苇茎，加熟地、当归、薏苡、巴戟，填补而痊。", "13857": "陈舜廷继室，娩后略有咳嗽，微有寒热，恶露不多，少腹似有聚瘕，时觉窜痛，腰疼不能反侧，齿衄频流，溺少口干，仍不喜饮，舌色无液，善怒不眠，四肢牵掣不舒，易于出汗，逆孟英诊之。脉至虚弦细弱，系素属阴亏，新产血去之后，八脉皆空，阳不能潜，游行于上，见证虽然错杂，治当清息风阳，表散攻瘀，毫不可犯。爰以沙参、竹茹、白薇、丹参、丝瓜络、石斛、栀子、小麦、甘草、红枣、藕为方。服数帖嗽衄皆蠲，为去丹参、麦、枣、栀、斛，加归身、熟地、枸杞、麦冬、楝实。服之各恙渐瘥，复因卒闻惊吓之声，心悸自汗，肢麻欲厥，乃定集灵膏加紫石英、牡蛎、龙齿，合甘麦大枣熬膏服之而康。继有汪少洪令侄女适孙彬士者，产后患证与此相似，误投温散，发热愈壮，但在上部。医者犹不知为阴虚阳越，仍从感治，迨脉脱汗淋，始邀孟英视之。始知是虚阳外越，然已不能拯救。病者自赋绝命词而逝。盖凡属虚脱之证，至死而神不昏也，医者识之。", "13858": "许兰屿令正，正月中旬，偶食蒸饼，即觉腹中攻痛而寒热间作，以为疟也，请孟英诊之。脉弦软而微数。曰：此不可以疟论，缘营素亏，往岁愈后少于调补，仍当濡养奇经。盖阳维为病亦能作寒热，而八脉隶于肝肾，温肾凉肝，病即霍然矣。授以苁蓉、枸杞、当归、白薇、青蒿、茯苓、竹茹、鳖甲、楝实、藕，数帖果愈。迨二月中旬，其病复作，举家佥以为疟，或云：必前次早补，留邪未去使然。而兰屿远出，家无主议之人。孟英曰：前次愈之太易，我之罪也，不为善后，谁之过欤！如信我言，指日可瘳，第须多服培养之剂，保无后患。于是仍服前药，亦数剂而安。续以集灵膏去牛膝，加羊藿、阿胶、当归、黄柏、菟丝、苁蓉、蒲桃干，熬膏服之，竟不再发。", "13859": "张友三室，去春受孕后，忽梦见其亡妹，而妹之亡也，由于娩难。心恶之，因嘱婢温辈广购堕胎药饵服，卒无验。冬间娩子后亦无恙，自疑多饵堕胎药，元气必伤，召朱某治之。述其故，朱即迎合其意，而断为大虚之候。且云：苟不极早补救，恐延蓐损。病者闻而益惧，广服补剂，渐至卧榻不起，多药弗效。延至仲春，族人张镜江为邀孟英视之。不饥不寐，时或气升，面赤口干，二便秘涩，痰多易汗，胸次如舂，咽有炙脔，畏明善怒，刻刻怕死，哭笑不常，脉至左部弦数，右手沉滑。曰：此郁痰证误补致剧也，与上年李健伯令正之病情极相类。第彼已年衰而伤于忧思谋虑，是为虚郁；此年壮体坚，而成于惊疑惑惧，是为实郁。虚郁不为舒养而辄投温补，则郁者愈郁，而虚者愈虚；实郁不为通泄而误施温补，则郁不能开，而反露虚象，所谓大实有羸状也。医者但云补药日投，虚象日著，不知虚象日形，病机日锢，彼岂故酿其病，而使之深耶？亦是一片仁心，无如药与病相僢而驰，盖即好仁不好学之谓耳。余非好翻人案，恐不为此忠告，未必肯舍补药而从余议也。病者闻之大悟，即授小陷胸合雪羹，加菖蒲、薤白、竹茹、知母、栀子、枳实、旋、赭出入为方，吞当归龙荟丸。三剂后，蒌仁每帖用至八钱而大解始行，各恙乃减。半月后，心头之舂杵始得全休。改用清肃濡养之法，调理匝月，汛至而痊。", "13860": "蒋礼园三令弟拜枫，自去年疟后，左胁聚气不消，时时窜痛，疑为疟母。孟英脉之弦软且滑，曰：非疟母也。予旋覆、海石、竹茹、丝瓜络、绛屑、葱白、蛤壳、凫茈、海䖳为方，十余剂而刈其根。", "13861": "关寅伯赞府家某厨，患春温，渠主人颖庵治之弗瘳，为速孟英诊焉。脉来弦软而寸数，舌绛苔黑而神昏，谵渴溺红，胸腹拒按，是双传证也。夫顺传者宜通其胃，逆传者宜清其营，治法不容紊也。然气血流通，经络贯串，邪之所凑，随处可传，其合其分，莫从界限，故临证者宜审病机而施活变，弗执死法以困生人。此证属双传，即当双解。予凉膈散加犀角、菖蒲、元参，下之果愈。", "13862": "何氏妇年未四旬，于庚戌冬患腹胀善呕。或云寒凝气滞，宜吸鸦片烟以温运之，及烟瘾既成而病如故。或云冷积也，莫妙于蒜罨，往夏遂以蒜杵如泥，遍涂脊骨，名曰水灸。灸后起疱痛溃，骨蒸减餐，其胀反加，经乃渐断。招越医庄某治之，云：劳损也。进以温补，病乃日甚。复邀张凤喈、包次桥、姚益斋诸人视之，佥云劳损已成，或补阴，或补阳，服至冬令，便泻不饥，骨立形消，卧床不起。今春请神方于各乩坛，皆云不治。其夫因蒲艾田荐于许信臣学使，随任广东。家无主意，束手待毙而已。蒲闻而怜之，为屈孟英一诊，以决危期之迟速，初无求愈之心也。切其脉弦细数，循其尺索刺粗，舌绛无津，饮而不食，两腿肿痛，挛不能伸，痰多善怒，腹胀坚高，上肤黄粗，循之戚戚然，昼夜殿屎，愁容黎瘁，小溲短涩而如沸，大便日泻十余行，脉色相参，万分棘手，惟目光炯炯，音朗神清，是精气神之本实未拨，病虽造于极中之极，却非虚损之末传也。殆由木土相凌，为呕为胀。洋烟提涩其气，益令疏泄无权；蒜灸劫耗其阴，更使郁攸内烁；进以温补，徒为壮火竖帜而涸其津；溉以滋填，反致运化无权而酿为泻。固之涩之，煞费苦心，余谓赖有此泻，尚堪消受许多补剂，纵临证心粗，不询其泻出之热而且腻，岂有肾虚脾败之泻，可以久不安谷而延之至今乎？夫人气以成形耳，法天行健，本无一息之停，而性主疏泄者肝也，职司敷布者肺也，权衡出纳者胃也，运化精微者脾也，咸以气为用者也。肝气不疏，则郁而为火；肺气不肃，则津结成痰；胃气不通，则废其容纳；脾气不达，则滞其枢机。一气偶愆，即能成病，推诸外感，理亦相同。如酷暑严寒，人所共受，而有病有不病者，不尽关乎老小强弱也。以身中之气有愆有不愆也，愆则邪留著而为病，不愆则气默运而潜消。调其愆而使之不愆，治外感内伤诸病无余蕴矣。今气愆其道，津液不行，血无化源，人日枯瘁，率投补药，更阻气机，是不调其愆而反锢其疾也。疾日锢，腹愈胀，气日愆，血愈枯。或以为干血劳，或以为单腹胀，然汛断于腹胀半年之后，是气愆而致血无以化，非血病而成胀矣。既胀而驯致腿肿筋挛，不可谓之单胀矣。肿处裂有血纹，坚如鳞甲，显为热壅，不属虚寒。借箸而筹，气行则热自泄。首重调愆，展以轻清，忌投刚燥，热泄则液自生；佐以养血，须避滋腻，宜取流通。徐洄溪所谓病去则虚者亦生，病留则实者亦死。勿以药太平淡，而疑其不足以去病也。艾田云：薛一瓢谓人须修到半个神仙身分，才可当得名医二字，聆君妙论，不愧名医。于是以沙参、竹茹、丝瓜络、银花、楝实、枇杷叶、冬瓜皮、黄柏、当归、麦冬、枸杞、白芍出入为方，用水露煮苇茎、藕汤煎药。服四剂，脉柔溲畅，泻减餐加，乃参以西洋参、生地、黄连、花粉、薏苡、栀子之类。又六剂，舌色渐淡，腿肿渐消，服至匝月，忽然周身汗出溱溱，而肿胀皆退，舌亦津润，皮肤渐脱，肌肉渐生，足亦能伸，便溺有节，并不另授峻补，两月后可策杖而行矣。天时渐热，服药已久，以虎潜丸方熬为膏，用藕粉溲捣成丸，因丸剂皆药之渣质，脾运殊艰。孟英凡治阴虚须滋补者，悉熬取其精华而以可为佐使者和之为丸，不但药力较优，亦且饵之易化。如法服至长夏，健步经通，遂以康复。艾田云：此证人不能治，神亦不能治，君竟能肉白骨而生之，不仅半个神仙，殆人而仙者耶，抑仙而降为人者耶？（水露以甜水贮甑，蒸取其露，宜临时蒸用，取其有升降之机，而养津液也，一名甑汗水，停久则失性矣。）", "13863": "一机匠久患寒热，兼以痰嗽，形消肌削，人皆以劳怯治之，久而不愈，或嘱其就诊于孟英。脉弦缓而大，畏冷异常，动即气逆，时欲出汗，暮热从骨髓中出，痰色绿而且臭，便坚溺赤。曰：痰火为患耳，误投补药矣。以苇茎汤合雪羹，加白薇、花粉、旋覆、蛤壳。服二十剂体健加餐，其病如失。", "13864": "诸暨张某者，有跛疾，业点翠，终日坐，而三四年来行数十武，即喘不能已，别无他苦，饮食如常。医咸谓虚，频补不应，诣孟英视之。曰：久坐不劳，气行迟滞，痰凝久伏，故为此患。脉缓而滑，岂为虚象？授雪羹合小陷胸加竹茹、旋覆、海石、杏仁、半夏服之，果吐多痰而愈。", "13865": "孟夏许芷卿偶自按脉，左寸如无，招他医诊之，佥云心散。举家惊惧，己亦皇皇，屈孟英视之。曰：劳心而兼痰火之郁，故脉伏耳。其火升面赤，不寐胁鸣，乃惊骇激动肝胆之阳，勃然升越，非本病也。予人参、黄连、菖蒲、紫石英、小麦、麦冬、莲子心、红枣、竹叶、甘草为方。一剂知，二剂已。", "13866": "蒋礼园令堂年七十三岁，患疟寒少热多，时时自汗，咸虑其脱，议欲进补。孟英切脉洪数而滑，舌绛口干，是暑为病也，与清解法数剂而痊。", "13867": "许子厚令庶母，年未四旬，患晡热发于上焦，心悸头疼，腰酸腿软，饥不欲食，暮则目如盲而无所睹，时或腹胀，自汗带多。孟英脉之弦细而弱，气短不足以息，舌赤无苔。曰：此营血大亏，不可作暑治也，授人参、熟地、枣仁、枸杞、归身、麦冬、乌鲗骨、牡蛎、龟板、蒺藜、芍药、杜仲、羊藿等药数十剂，而康复如常。", "13868": "兰溪吴氏妇，盛夏患恶阻。洪某进旋覆、姜、桂等药，而壮热神昏，腰疼欲堕，二便秘涩，呕吐不休，脉数而洪。予栀、芩、连、楝、竹茹、知母、银花、绿豆为剂，佐以苏叶二分，冬瓜煮汤煎药。下咽即安，数服而愈。", "13869": "朱生甫明经以花甲之年，偶在嘉兴患滞下甚剧，急买棹旋杭，集诸医议治。许敬斋宗景岳，谓痢必本于寒湿，主干姜、桂、朴以温化；洪石生尚东垣，闻其向患脱肛，主清暑益气以举陷。或云素善饮而有鼻衄，血热阴亏，既受暑邪，宜玉女法以两清；或云痢必有积，不必问其余，宜大黄、归、枳以荡涤。聚议纷纭，乃郎仲和等不知所从而质诸孟英。诊毕，遂问此证何如？当用何药？曰：此滞下证之最难治者也。痢初作即不能起于榻，而五色并见，噤口不食，非暑热之深受，一何至于此极耶？满面红光，鼻赤尤甚，肺热素炽，暑火烁金，故水失化源，溺少而涩，此不可以温燥再劫其津也；肢掣无眠，合目呓语，时时烦躁，视物不明，畏热喜风，口干易汗，阳气浮越，暑渐侵营，故苔虽腻黄，尖红根黑，此不可以升散再扰其阳也；胸次不舒，饮水欲噎，欲噫不达，欲嚏不能，茎缩易嗔，时有恶梦，肝多怫郁，痰阻清阳，故升降不调，中枢窒滞，此不可以滋涩再碍其机也。又非寻常之痢，病仅在府，可以推荡以为功也；参之于脉，右寸关缓滑而寸较抑，左则弦洪而数兼上溢，故知其气郁痰凝，暑火深受，风阳内动，久耗心营，所幸两尺皆平，身无大热，如能治之中肯，尽可无虞。仲和出诸方云：然则此皆不可服乎？曰：咸治痢之法也。惜尊翁之证，不能合于此药耳！若尊翁之恙，见证虽太错杂，而责重在于肝经，肝属厥阴，风火内寄，故此经之痢，宜柔宜凉，忌刚忌温，以肝为角木，龙性难驯，变化飞腾，病机莫测，但使风阳靖息，庶几险浪不兴，纵有别脉未清，自可徐为疏瀹也。仲和闻而心折，力恳图维。于是以仲圣白头翁汤为主方，加石菖蒲、川贝母、竹茹开痰舒郁以调其气，犀角、银花、竹叶凉血息风以清其心，冬瓜、蔗梢、凫茈、海䖳煮汤煎药，以清胃热而生津，化府气而濯垢，吞送滋肾丸三十粒，引肝火迅速下行。服后诸恙递减，粪色渐见，痰果频吐，神气亦安。既而粥食日增，夜眠恬适，始去犀角、雪羹、滋肾丸，加西洋参、阿胶以复其津液。迨痢净而时有血随粪下，为加鸦胆仁，以龙眼肉包而吞之果止。惟肠鸣气泄，稀粪随流，肛坠难收，脉亦弦软。知其病去而正虚也，改用三奇散而安。继予气血交培善后，仍佐蠲痰舒郁，康健较胜曩时，盖并其积年宿疾而去之也。故生甫谢孟英诗五排结句云：不因施上药，那得挽沉疴。磈磊从今尽，先生殆缓和。", "13870": "顾媪因比邻失火，几焚其庐，惊吓之余，不能起榻，胁痛偏右，便秘神瞀，身面发黄。医云湿热，治之罔效。乞诊孟英，脉涩而弦，按之甚软。曰：此因惊恐气结不行所致。予沙参、桑叶、栀子、丝瓜络、冬瓜子、苇茎、枇杷叶、旋覆、葱须、竹茹，数剂而痊。", "13871": "金愿谷中翰患便秘，广服润剂，粪黑而坚如弹丸，必旬余始一更衣，极其艰涩。孟英诊脉迟软，舌润不渴，小溲甚多，乃久患痹证，坐卧不行，健运迂迟。法宜补气，俾液濡布，所谓中气足，则便溺如常矣，非凉润药所能治也。予大剂参、术、橘、半，加旋覆花以旋转中枢，鸡膍胵以宣通大肠之气，鸡不溺而粪易下也。更仿《金匮》谷实之例，佐血余、苁蓉，俾为流通府气之先导。如法服之，数日即解，且较畅润，至三十剂其病若失。", "13872": "沈氏子年甫髫，仲秋患感两旬，屡医弗愈，求孟英视之。神昏谵语，面惨无眠，舌绛耳聋，频吐白沫，脉数溺少，渴饮不饥，热已甚微，汗亦频出，牛黄、紫雪，数进无功。以元参、丹参、白薇、知母、苇茎、竹茹、旋覆、冬瓜子、蛤壳、石斛、枇杷叶、竹叶、花粉、莲子心、西瓜翠衣等出入为方，数服而愈。盖邪虽传营，气分未廓，故虽善饮水而敷布无权，不能下行为溺，但能旁溢为汗，上行为沫，良由初起不知为暑，治以表散风寒之药。及至传营，又不知营卫两解之法，徒以直走膻中之药，漫图侥幸，何异鹦鹉学人言，而不知所以言耶！", "13873": "沙沛生鹾尹患身热头重，腹胀便溏，脘闷不饥，口流涎沫，腿酸溺少，脉软神疲。孟英诊曰：内湿素盛，兼吸客邪，不可谓值此亢旱之年，竟无泛滥之病也。予槟、朴、蔻、苓、猪、泽、橘、半、防己、秦艽之剂。小溲虽行，其口中涎水流出尤多，病遂以愈。既而其子龙官初次患疟，耳聋舌绛，溺赤痰多，脉数而弦，寒微热甚。幼科云：胎疟不能即愈。孟英曰：此齐东野语也。予滑石、竹茹、知母、花粉、苓、翘、橘、半、青蒿、鳖甲，八帖而痊。", "13874": "温敬斋令正，九月间忽然四肢麻木，头晕汗淋，寻不能言，目垂遗溺，浑身肤冷，急请孟英视之。脉微弱如无，乃虚风内动，阳浮欲脱也。先令煮水以待药，与东洋参、黄耆、龙、牡、桂枝、甘草、茯苓、木瓜、附子九味煎数沸，随陆续灌之。未终剂，人渐苏，盖恐稍缓则药不能追也。", "13875": "朱饬庵孝廉，年未三旬，自都中奔丧回杭，患滞下赤白，腹不甚痛，而奔迫异常，能食溺长，医治罔效。孟英脉之，虚弦而软，曰：此不可以常痢视也。以三奇散加归、芎，送香连丸而愈。", "13876": "王子庵令堂，年已古稀，患便秘不舒，时欲弩挣，汗出头晕。医谓其肝气素滞，辄与麻仁丸等药，其势孔亟。伊婿陈载陶屈孟英诊焉。脉虚弦而弱，是虚风秘结。予人参、苁蓉、当归、柏子仁、冬虫夏草、白芍、枸杞、楝实、胡桃仁数帖而痊。次年秋患脘痞疼胀，医者率进温补香燥之药，驯致形消舌绛，气结津枯，始延孟英视之，不及救矣。", "13877": "屠小苏令正，自乳经停，泛泛欲吐，或疑为妊。所亲高啸琴进以养阴之药，渐致时有微热，脘闷不饥，气逆嗽痰，卧难著枕，二便秘涩，耳闭汗频。孟英脉之虚软而涩。曰：根蒂素亏，经停乳少，血之不足；泛泛欲呕，肝乘于胃，率投滋腻，窒滞不行；略受风邪，无从解散，气机痹塞，九窍不和。先以葱、豉、通草、射干、兜铃、杏仁、蒌壳、枇杷叶、白蔻开上，两剂热退，次用小陷胸合雪羹，加竹茹、旋覆、白前、紫菀宣中。三剂便行安谷。继予冬虫夏草、苁蓉、当归、枸杞、麦冬、紫石英、楝实、熟地、牛膝滋下而瘳。又顾氏子患发热独炽于头，医进发散，汗出不解，胸次痞闷，便滞溺艰，舌绛口干，饮不下膈，不眠头痛，脉数而弦。孟英曰：体质素虚，热薄于肺，痰结于胸，治宜轻解。羌、防、柴、葛，恶可妄投？膏粱与藜藿有殊，暑热与风寒迥异，治上焦如羽，展气化宜轻。以通草、苇茎、冬瓜子、丝瓜络、紫菀、枇杷叶、射干、兜铃、白前九味，天泉水急火煎服，复杯即已。盖席丰履厚之家，密室深居，风寒湿三气所不能侵，惟暑燥之邪易于吸受，误用温散，最易劫津。若田野农夫，栉风沐雨，肌坚气实，当用辛温。设进轻清，焉能济事？故医者须量体以裁衣，弗胶柱而鼓瑟也。（炳按：汪谢城云：复杯即已下宜删去，以言过当也。若然则藜藿人温证暑证，亦可用辛温矣。此评甚是。）", "13878": "孙氏子患腿酸寝汗，溺赤脘疼，食减口干，或疑为损。孟英按脉缓大，苔色微黄，乃劳力火升，内兼湿热也。以沙参、竹茹、甘草梢、小麦、石斛、楝实、丝瓜络、绿萼梅、建兰叶、带露桑叶为方，送服松石猪肚丸，旬日而愈。嗣有任氏女校书患带，诸药罔瘳。孟英视曰：脉软数而长，非虚也，宜猪肚丸清其湿火。服匝月，病良已。", "13879": "沈妪素患肝气，初冬便泻，医药勿瘥。所亲吴馥斋迓孟英诊之。脉至弦梗，舌赤无津，杳不知饥，胁腹时胀，乃风阳内炽，津液耗伤，香燥忌投，法宜濡润，否将阴涸，毋畏甘凉。予甘草、地黄、麦冬、阿胶、枸杞、薏苡、楝实、葳蕤、乌梅为剂，牡蛎一斤，甘澜水煮浓汤煎药，和入蔗浆服之。数日而瘳，已能安谷，忽然舌不能伸，心摇语蹇，不眠头晕，面赤火升。仍速请孟英视之。脉梗虽和，极其弦细，是阴液未复，木火失涵。以前方去薏、楝、乌梅，加人参、龙眼肉，少佐黄连授之而愈。", "13880": "罗氏妇先患痰嗽，气逆碍眠，后兼疟痢并作。医者佥云无法，浼人乞诊于孟英。脉见滑数，口渴苔黄，不饥脘闷，溺似沸汤。曰：无恐也，虽见三证，其实一病，盖肺胃大肠，一气流通，暑伏肺经，始为痰嗽，失于清解，气逆上奔，温纳妄投，胃枢塞滞，郁遏成疟，渴饮汗多，热甚寒微，病情毕露，温化再误，转入大肠，赤白稠黏，无非热迫，不必见证治证，但治其暑，则源清流自洁矣。以苇茎汤加滑石、黄芩、竹茹、石膏、厚朴授之。不旬日而三证悉瘳。", "13881": "沙沛生鹾尹令正，胎前痰嗽，娩后尤甚。孟英视之，面赤能餐，汗多畏热，脉滑而数，呕渴苔黄，恶露流通，血分无病，乃燥火伏于肺胃。法宜清肃上焦，不可谓产后禁凉润也。剂以沙参、茹、滑、知、斛、冬、甘、枇杷叶、冬瓜子、苇茎、梨皮、桑叶、蛤壳，出入互用，旬日而痊。", "13882": "钱氏妇患嗽数月，多医莫治，渐至废寝忘餐，凛寒乍热，经停形瘦，心悸耳鸣，滋补填阴，转兼便泄。孟英视脉虚弦缓大，而气短懒言，卧榻不支，动即自汗。曰：固虚也，然非滋阴药所宜。予参、耆、龙、牡、桂、苓、甘、芍、冬虫夏草、饴糖，大剂服旬日而安。继去龙、牡，加归、杞服二十剂，汛至而康。病者欲常服补药，孟英止之曰：病痊体健，何以药为？吾先慈尝云，人如欹器，虚则欹，中则正，满则覆。世之过服补剂，致招盈满之灾者比比焉，可不鉴哉！", "13883": "高鲁川三令爱，为外科姚仰余令郎杏村之室，年三十五岁，自去年仲夏患痢，白少赤多，昼夜一二十行，或有溏粪相杂，医治日殆，延至今冬，经断半年，胁腹聚块，时时上窜，宛如虫行，痒至于咽，食压始下，腹胀腿肿，唇白口糜，舌绛无津，耳鸣巅痛，略有干呛，渴饮汗频，热泪常流，溺短而热，善嗔多梦，暮热无眠，心似悬旌，屡发昏晕，痢门与虫门方药，遍试无功，舍病而补法备施，亦无寸效，佥云不能过冬至。棺衾咸备，无生望矣。杏村之僚婿蒋礼园、黄上水交荐孟英图之。脉至左弦数上溢，尺中滑大，按之细弱，右手软滑，略兼弦数。诊毕谓杏村曰：令正幸能安谷，得以久延，然下痢五百日，喉腭辣燥，阴液固已耗伤，而尺肤淖泽，脂膏未剥，其中盖别有故焉。腹中之块，痢前曾有乎？痢后始起乎？杏村云：起于痢前。然则前此曾有产育乎？云：去年二月间分娩艰难，胞已糜碎，生而未育。曰：是矣，此实似痢而非痢也。夫胞衣糜碎，必有收拾未尽而遗留于腹中者，恶露虽行，此物未去，沾濡血气，结块渐成，阻碍冲任之常道。而冲任二脉，皆隶阳明，月事既不能循度以时下，遂另辟捷径，旁灌于阳明，致赤白之物悉由谷道而出，宛如痢疾。据云：姅期向在中旬，故每月此时，痢必加甚，仍与月汛相符，虽改途易辙而行，尚是应去之血，所以痢至年半，尺肤犹不至枯瘁也。且其痢由腰脊酸楚而下，显非肠胃之本病。缘病起夏月，正痢疾流行之候，病者自云患痢，医者何暇他求，通之、涩之、举之、填之，无非肠胃之药，不但未切于病情，抑且更广其病机。试思肠胃之痢，必脂膏削尽而经枯，则焉能纳食如常而充肌肤耶？然非谓不必治其痢也。欲治痢，必治其所以痢，则当治冲任；治冲任，必治冲任之所以病，则当去其遗留之物。遗留之物去，则冲任二脉遵道而行，月事如期，痢亦自愈。第物留已将两载，既能上行求食，谅已成形。前医指为虫病，而无面白唇红之证据者，虫必饮食挟湿热之气所化，此但为本身血气所凝，似是而非，判分霄壤。况此物早已脱蒂，不过应去而未去，欲出而不能。开通冲任二脉，其物自下，不比肠覃石瘕，有牢不可拔之势，必用毒药以攻之者。爰以乌鲗、鲍鱼、茜根、龟板、鳖甲、血余、车前子、茺蔚子、藕汁为初方。众见方案，佥云：舍垂危之痢而不顾，乃远推将及两年之产后，而指为未经人道之怪证，不但迂远穿凿，未免立异矜奇。疑不敢从。蒋礼园令弟敬堂云：徐洄溪批叶案，以十年九年之病，仍标产后为大不然。谓产后过百日而起病者，不作产后看。举世皆以为定评。余读孟英所辑叶案瑕瑜，谓案中所云十年九年者，乃病从产后起，延至于今而屡发也，否则胀泻浮肿，何必远推多载之前而隶于产后耶？更有新产之后，其病不因产育所致者，虽在百日之内，亦不可谓之产后病，仅可云病于产后耳。此证痢虽起于百日之外，块早形于两月之前，因流溯源，正是治病必求其本也。今人之病，何必古书尽载？此医之所以不易为，而辨证之所以为最难也。听其议论，具有根柢，并非捕风捉影之谈，况药极平和，又非毒剂，似与久病元虚无碍，他医既皆束手，盍从其计求生，具嘱仰余勿改其方。于是，群议始息。服两剂后，病者忽觉粪从前阴而出，大駴，急视之，乃血裹一物，头大尾小，形如鱼鳔而有口，剖之甚韧，血满其中。众始诧为神治，而病者汗晕不支。孟英即与人参、龙骨、牡蛎、茯苓、麦冬、甘草、小麦、红枣为方。服数剂神气安爽，始知脐下之块已落，而左胁下者犹存，然上窜之势，向亦脐下为甚，窜势既减，痢亦渐稀，改用白头翁汤加阿胶、甘草、小麦、红枣，吞仲景乌梅丸，和肝脾之相贼，养营液而息风。旬日后头目渐清，肿消胀减。复以初方合《金匮》旋覆花汤，服四剂，又下一物，较前差小而胁块乃消，窜痒悉罢，痢亦径止，惟溺热便溏，口犹辣渴，心摇易汗，腿软无眠，烦躁火升，脉形虚豁。乃阴火内炽，脾受木乘，营液久伤，浮阳不敛也，授归耆建中汤去姜，加黄柏、乌梅、龙骨、牡蛎、小麦。以羊肉汤煎，送下交泰丸一钱。脉证虽觉渐和，惟久病元虚，屡生枝节。孟英坚持此法，不过随机略为进退而已。而旁观者议论纷纭，因嘱邀王篪伯会诊，篪伯亦主是法，浮言乃息。服至匝月，喉间渐生甘液而各恙递平。又匝月，甘液布及舌尖而满口皆润。次年二月中旬，经至肌充而愈。适吴楚之警，遂辍药。迨仲冬患疮，误用药水洗之，致毒内陷而殒。惜哉！（炳按：交泰丸系黄连、瑶桂心研末为丸。——", "13884": "顾子襄体素丰，患颐肿，医投升散之药，神昏气逆，鼻衄大流。伊舅氏朱生甫明经为延孟英视之。面赤音低，不眠脘闷，大渴溺赤，脉滑数而洪。曰：冬温也。其苔色白而不燥者，内有伏痰耳；便泻如水者，肺热下大肠耳；岂可以为寒乎？予犀角、元参、旋覆、栀、芩、射干、竹茹、通草、银花、石菖蒲服之。衄止神清，泻亦不作。去犀、射，加花粉、贝母。服二剂，解坚矢，吐胶痰，知饥热退而愈。继有朱氏子右颈肿突，外科围药甚痛，身热不饥。孟英诊曰：冬温耳，非患痈也。敷药亟令洗净，另以芙蓉叶杵烂涂之，投以清解肺卫药，数日而痊。", "13885": "陆渭川令媳患感，适遇姅期，医治数日，经止而昏狂陡作，改从热入血室治，转为痉厥不省人事，所亲沈雨阶为延孟英诊之。脉弦羍而虚滑，气逆面青，牙关不开，遗溺便秘，令按胸次，坚鞕如柈。此冬温尚在气分，如果热入血室，何至昼亦昏迷？良由素多怫郁，气滞痰凝，用柴胡则肝气愈升，攻瘀血则诛伐无过。予小陷胸合蠲饮六神汤加竹沥，调服牛黄至宝丹一颗，外以苏合丸涂于心下，痰即涌出，胸次渐柔，厥醒能言，脉较有力。次日仍用前方，调万氏清心丸一粒，果下痰矢，渐啜稀糜，改授肃清，数日而愈。续有顾某陡患昏狂，苔黄便秘，卧则身挺，汗出五心。医云热入膻中，宜透斑疹，治之加剧。孟英诊脉弦缓不鼓，身无大热，小溲清长，的非外感，乃心虚胆怯，疑虑忧愁，情志不怡，郁痰堵窍也。以蠲饮六神汤合雪羹加竹叶、莲子心、竹沥。服二剂狂止，自言腹胀而头偏左痛，仍以前方吞当归龙荟丸，大解始下。改用清火养心，化痰舒郁之法而愈。", "13886": "孟英治其令弟季杰之簉室，怀孕患嗽，嗽则鼻衄如喷，憎寒乍热，口渴头疼，右脉洪数，授白虎汤合葱豉，投匕而瘳。或云时已隆冬，何以径投白虎？孟英曰：脉证如是，当用是剂，况今年自夏徂冬，亢旱不雨，寒虽外束，伏热蕴隆，此即麻杏甘膏之变法耳。", "13887": "朱介眉年逾花甲，患感于季冬，初服温散，苔色遂黑，即投白虎，胸胁大疼，面赤不眠。口干气逆，音低神惫，溺赤便溏。医者佥云不治。孟英切脉虚数而弦，是真阴素亏，痰多气郁，今年自夏徂冬，亢旱已极，所伏之邪，无非燥热，稍一温散，火即燎原。一见黑苔，即投白虎，而不知其枢机窒滞，气道未舒，且阴液耗伤，亦非白虎汤仅能涤热者之任也。予沙参、苇茎、竹茹、冬瓜子、丝瓜络展气开痰，苁蓉、当归、紫石英、冬虫夏草潜阳镇逆。复杯即减，旬日而瘥。", "13888": "石北涯之大令媳，忽患多言不寐，面赤火升，汗出心摇，仓皇欲死。孟英察脉虚弦小数，乃赋质阴亏，将交春令，虚阳浮动，有鸢飞鱼跃之虞。亟以人参、龙齿、牡蛎、石英、甘草、百合、小麦、竹叶、红枣、青盐水炒黄连为剂，引以鸡子黄，投匕即安。续加熟地、阿胶滋填而愈。", "13889": "乙巳秋拙荆年三十二岁，忽患四肢酸痛，早晚尤甚，初谓其平素劳瘁所致，已而日剧。延医治之，以为痛风，服药不效。单方针灸，无不遍试，至冬令渐难行走。次年春，山阴俞某作虚风治，用参、术、熟地、桂、附等药。（文）恐太热，减去附子服十余帖，遂手足拘挛，不能屈伸，日夜号痛，如受炮烙，眠食皆废，痰韧如石，皮肤燥裂，鳞起如松。至夏更加两腋肿核，阴户疮糜，痛不可支。业师顾听泉先生，荆人之舅氏也，求其援手。云：两脉弦数，舌绛无津，况汛断半年，破䐃脱肉。经言九侯虽调，犹属不治，危殆若此，不能过夏至矣。因请孟英先生救之。先生来视曰：营分素亏，阴液尽烁，幸病在经络，犹可图治，第恐成废耳！授以西洋参、元参、生地、天冬、麦冬、知母、花粉、银花、甘草、葳蕤、石斛、丝瓜络等药，出入为剂。用竹沥、梨、蔗诸汁和服。酷暑之时，则加生石膏、西瓜汁。文遵方恪服，计烧沥之竹四五十竿，榨浆之蔗七八十枝，捣汁之梨五六十斤，绞汁之瓜三四十枚。果痛渐以减，疮渐以平，肤渐以蜕，食渐以增。仍溉以凉润生津，兼佐熟地、枸杞、归身之类。服至两载，月事乃行。又半年，肌肉渐充。手足亦能舒展，闻者无不惊异。今则形神如昔，步履虽未能如常，已可坐轿出门。是证也，不遇先生，必致夭枉。既铭诸心，复录之以为后人鉴。", "13890": "癸丑孟春，陈舜廷自宁波旋杭，迓孟英诊视。云去冬患痰嗽，彼处医家初以疏散，继则建中，诸药备尝，日渐羸困，左胁跃跃跳动，胸次痒如虫行，舌素无苔，食不甘味，嗽甚则汗，夜不安眠，痰色清稀，便溏溲短，恐成肺痿，惟君图之。孟英诊曰：病始肺伤于燥，治节不行，体质素属阴亏，风阳内煽，烁其津液，故右脉软滑而虚。温以辛甘，致左脉浮弦且数，虽非肺痿，而上下交虚。治先保液息风，续宜壮水，可奏肤功。徒化痰理嗽，见病治病，有何益乎？爰以沙参、苇茎、冬瓜子、丝瓜茹、竹茹肃肺气，甘草、石斛、燕窝生津液，冬虫夏草、石英、牡蛎息风阳。投剂即嗽减能眠。旬日后去冬子、石斛，加归身、麦冬、茯苓。服数帖两脉较和，餐加溺畅。再去牡蛎、甘草、丝瓜络，加熟地、盐橘红。十余剂各恙皆安，以高丽参易沙参，善后而康。", "13891": "马翠庭鹾尹令宠，患两腿疼肿，便溏不渴，医进苍术、木瓜、萆薢、独活等药，其病日甚，不食不眠，筋掣欲厥。孟英切其脉弦滑而数，询其溺极热如沸。曰：非寒湿也，肝火为患耳。便泻是土受木乘，不渴乃内有伏痰。予栀、柏、芩、莲、茹、楝、通草、半夏、蚕砂、丝瓜络为方。一剂知，二剂已。", "13892": "许康侯令堂，初夏患坐卧不安，饥不能食，食则滞膈，欲噫不宣，善恐畏烦，少眠形瘦，便艰溲短，多药莫瘳。孟英按脉弦细而滑，乃七情怫郁，五火烁痰，误认为虚，妄投补药，气机窒塞，升降失常，面赤痰黄，宜先清展。方用旋覆、菖蒲、紫菀、白前、竹茹、茯苓、黄连、半夏、枇杷叶、兰叶。不旬而眠食皆安，为去前四味，加沙参、归身、紫石英、麦冬调养而痊。", "13893": "钱某患感，医治旬日，渐致神昏瘛疭，大便泄泻。以其体素弱而吸洋烟也，胥束手矣，始丐诊于孟英。左脉弦软，右则虚大而滑，汗出不解，目瞀耳聋，呓语溲红，时时呃逆，心下拒按，舌不能伸，斡齿视苔，满黄微燥。曰：温邪虽陷，气分未清，里气虽虚，伏痰内盛，幸泻数次，邪势稍衰。先予人参、牡蛎、犀角、元参、竹叶、竹茹、银花、石斛、枇杷叶、川贝母、莲子心为剂，调服万氏清心丸一颗。目明热退，呃减舌伸，臂显赤斑，夜亦能寐。诘朝去参、蛎、牛黄丸，加竹沥、桑枝、丝瓜络。痰果大吐，瘛疭即平，再去犀、元、桑枝，加紫菀、海䖳。呃止胸舒，苔色渐退，稀糜渐进，耳听略聪，再去竹叶、莲心、紫菀，加沙参、花粉，服五帖而下坚矢。嗣投调养而安。", "13894": "李华甫年六十三岁，仲夏患恶寒，气逆不饥，即请孟英视之。脉甚虚软，舌本紫而滑泽无苔，溲频数而浓赤不禁，阴茎已缩，两手紫黯。乃心阳过扰，热伏厥阴之象，不可谓无热恶寒发于阴，而认为真伤寒也。虽平昔耽饮嗜茶，设投燥剂，则液之涸也不须旋踵。爰以葱、豉、茹、芩、栀、薇、桑叶、通草轻解其外。至夜始发热，再剂微汗而解，独腹热如烙，舌渐干而口渴，改予西洋参、元参、生地、麦冬、甘草、花粉、栀、楝、苁、茹和青蔗汁。服二帖下坚矢而舌愈干，且讝语不寐，于前方加竹叶、木通，服之舌根始见黄苔，知伏热渐化，再一剂苔转黑。原方调以神犀丹一丸，即战解而舌始润，稍啜稀糜，犹妄言无寐，乃心阴久耗，阳不能收也，仍以前方加童溲和服两帖，大解复行，神气渐谧，诸恙寻愈。此证设犯温升，即难救药，幸初发得遇名手，始克扶危持颠，旬日而愈。故为相者治天下，当因民之所利而利之，不必务虚名而复井田肉刑也；为医者治人，亦当因病之所利而利之，不可守成法而泥麻黄、桂枝也。", "13895": "王炳华之媳，屡次堕胎，人渐尪羸，月事乱行，其色甚淡，医谓虚也。大投补剂，其瘦日甚，食少带多，遂加桂、附，五心如烙，面浮咳逆，痰壅碍眠，大渴善嗔，医皆束手，始请孟英脉之。两尺虚软，左寸关弦数，右兼浮滑，乃阴虚火炎也。然下焦之阴虽虚，而痰火实于上焦，古人治内伤，于虚处求实，治外感于实处求虚，乃用药之矩矱也。爰以沙参、竹茹、冬瓜子、芦笋、枇杷叶、冬虫夏草、石英、紫菀、苁蓉、旋覆为方。两剂即能寐，五六剂嗽止餐加，乃去紫菀、旋覆、沙参，加西洋参、归身、黄柏。服五剂，热减带稀，口和能食，再去芦笋、冬瓜子、枇杷叶，加熟地、枸杞、乌鲗骨服之而愈。又吴氏妇陡患咳嗽，痰不甚多，不能著枕者旬日矣，神极委顿，孟英察脉虚数，授枸杞、苁蓉、归身、石英、龟板、牡蛎、冬虫夏草、麦冬、牛膝、胡桃肉之剂，复杯而病若失。", "13896": "吴箓园患发热呕吐，茎缩腹痛，孟英诊脉弦软而数，苔色腻黄。曰：热伏厥阴也。与楝实、通草、栀、莲、茹、斛、丝瓜络。一剂知，数剂愈。", "13897": "朱生甫明经令郎莱云之室，娩后月余患间疟，孟英脉之虚数而弦，头疼腹痛，苔色甚薄，乳少善呕，乃营虚而邪客少阳也。令郎断乳，庶免蓐劳。剂以柴、芩、茹、半、桑、楝、延胡、枇杷叶。二帖呕止腹不痛，去楝实、延胡，加当归。四帖疟罢能餐，而头尚痛，再加杞菊。服三剂，头不疼，改用甘麦大枣，加归、芍、杞、菊、竹茹、蒲桃干、藕调之，经行而愈。", "13898": "陈氏妇季夏患疟，寒微热炽，舌红不渴而思啖瓜果，不饥不食，二便皆通，夜不成眠，汗多神惫。孟英审脉虚软微数，虽属暑疟，邪不甚重，惟营阴久亏，不须重剂诛罚无辜。以西洋参、知母、芩、茹、白薇、麦冬、西瓜翠衣为剂，果三啜而瘳。", "13899": "胡氏妇患疟寒少热多，自云阴分素亏，医进清解凉营之药多剂，其热愈炽；改用养阴法，呕恶烦躁，自欲投井。或谓今年中伏之时，风雨连朝，人须挟纩，有何暑热？而多服凉剂，以致疟来发躁，必属虚火。拟以姜、附治之。病者云：吾舌已脱液，阴将涸矣！坚不肯服而请决于孟英。脉至滑数，右寸关更甚。视其舌，淡白而光滑，俨似无苔，其实有苔如膜，满包于舌也。证属阴虚吸暑，兼以痰阻清阳，初治失于开泄耳！授菖、茹、连、半、旋、茯、苏、枳、枇杷叶为小剂，取其轻清开上也，两服舌即露红，呕止受谷，疟热亦减。又二服疟竟罢。孟英曰：余亦初不料其若是之神也。随以清养善后而安。", "13900": "高某以阴虚之体而患疟于暑月，久而不愈，冯、黄二医佥用补养矣，而杳不知饥，欲噫不畅，便溺艰涩，渴喜沸汤。孟英诊脉缓涩不调，按其胸次坚而不柔，舌上满布干黄薄苔，曰：气机郁结，痰滞未行，如何遽投补剂？予菖、贝、旋、蒌、苏、桔、连、半、紫菀、枇杷叶为方，四帖而愈。始从调养以善其后。嗣有王雨苍仲郎之证治，与此略同。", "13901": "沈峻扬令妹年逾五旬，体素瘦弱，不能寐者数夜，证遂濒危，乃兄延孟英视之。目张不能阖，泪则常流，口开不能闭，舌不能伸，语难出声，苔黄不渴，饮不下咽，足冷不温，筋瘛而疼，胸膈板闷，溲少便秘，身硬不柔，脉则弦细软涩，重按如无，或疑中暑，或虑虚脱。孟英曰：身不发热，神又不昏，非中暑也；二便艰涩，咽膈阻闷，非脱证也。殆由情志郁结，怒木直升，痰亦随之，堵塞华盖，故治节不行，脉道不利也。误进补药，其死可必。但宜宣肺，气行自愈。方用紫菀、白前、兜铃、射干、菖蒲、枇杷叶、丝瓜络、白豆蔻。果一剂知，四剂瘳。", "13902": "胡某素患耳鸣，且吸鸦片，时服补药，渐至食减痰多，舌上起灰黄厚腻之苔者三年矣。多医莫愈。孟英脉之弦细软滑。曰：真阴亏于下，痰热阻于上耳。以西洋参、菖蒲、远志、麦冬、竹茹、苁蓉、归身、石英、牡蛎、冬虫夏草，少加黄连服之。不半月痰少餐加，舌苔尽退，三年之病，遂以霍然。", "13903": "陈德斋令侄缉庵患疟，黄某连投小柴胡汤，渐至热势加长，抚之烙手，时当盛暑，帐幔不启而不得汗，神情瞀乱，大渴苔黄，脘闷欲呕，便秘溺赤。孟英按脉软滑而数，身面肤赤。乃暑湿挟痰𫐖轕于中，气机阻痹。宜予清宣剂。以菖、茹、蒌、枳、知、滑、芩、连、花粉、枇杷叶、竹叶、西瓜翠。服后痰即渐吐，异日疟来有汗。病者卧于藤榻，身穿西洋布汗衫短裤，其汗但出于衣不遮蔽之处。孟英适至，诊毕，令裸其体，汗即遍出，热亦寻退。方不加减，四剂疟断更衣，胸舒安谷，另以轻清肃涤余邪而愈。（世人不论天时，不究病因，但知盖覆以取汗者，宜于此案探讨其未发之义，不可草草读过也。）", "13904": "许子芍年甫冠，平素饮食不节，气滞多痰，偶患时疟，溺赤苔黄，脉至滑数，脘闷不饥，孟英投清解药一剂。其门下医者黄某云：疟疾以小柴胡汤为主方，乃舍之不用，而以竹茹大寒之品遏伏其邪，菖蒲散心之药耗损其神，此病虽轻，而药已误，恐有变证。病家闻而惑之。次日即服其方，病势日进。辄云菖蒲散心以致神气不安，竹茹寒滞以致邪不能解。小柴胡方内加入桂枝、首乌等药，狂热尤甚。黄复荐招任某会诊，交口以为开手一药之误，恐延虚脱，径用生脉六味，加龙、牡、杜仲、续断、阿胶之类服之。半月后病者目不能张，畏闻声响，语出无音，身挺而重，不能转侧，略一动摇，则手足震掉如擂鼓然，房中几案皆为撼簸。黄、任二医佥云汗脱在即。举家皇皇，其堂兄兰屿夤夜拉孟英往视，脉甚弦疾。曰：病药也，其何能脱？疏方以天竹黄、竹茹、竹叶、竹沥并用，病者闻而咋舌，谓一味竹茹酿成大病，一方四竹能不杀人？仍服任某补剂，以冀留人而再治病也。又旬日疟径不作，至时惟脑后之枕骨与两足跟著席，身则反张如弓，如是数刻，则昏乱狂走，医者诿为祟病，符醮水陆，大费不赀，而病如故。既而黄某疽发于背，任亦托病不出。所亲陈雪舫力举孟英胸无畦畛，不妨再恳其挽救。病家计穷，始为谆请。脉仍弦疾而左尤坚搏，且善啖而腹胀如石矣。孟英曰：幸而便通，犹可无虑，以旋覆、赭石、菖蒲、胆星、枳实、黄连、青黛、整块朱砂两许合四竹为方，调服苏合香丸。一剂而反张、狂谵皆减。病者云：我今日如梦初醒，而精神自觉惘惘。次日仍用原方，调以玉枢丹。得泻四次，腹胀遂减，反张狂谵悉蠲，惟至时尚有气逆肢掣耳。乃去玉枢丹，令吞送当归龙荟丸。大便日泻，胸腹渐柔。又服五剂，逆掣皆平，改用沙参、丹参、石英、茯神、白薇、栀子、丝瓜络、贝母、海䖳、凫茈等清理善后而愈。孟冬已完姻矣。嗣其仆陈福，陡患身面如金，便血吐血，求孟英视之。身热苔垢，而肢冷手紫，脉至如丝。曰：此急黄证而兼血溢于上下，即所谓瓜瓤瘟也，药不及救。越日果亡。（黄某，敦爱局疡医也。年逾六旬，忽患背疽，闻服参、茸等药七日而亡。夫背疽之败，何至如是之速？必是暑热为患，而误从温托耳。杨素园大令批《仁术志》云：朱砂不宜入煎剂，当生研少许调服。愚谓朱砂但忌火炼，不忌汤煎，且整块而煎，仅取其气，较研服其质者尤无弊也，余磵花《印雪轩随笔》云：刑幕郑春潭患秋感发狂，谵语喃喃，若与人争辨，谓有二鬼向其索命，乃索笔作遗嘱，处分身后事，如是者数昼夜。山右武君视之曰：非鬼也，病由邪热未清，遽服补剂耳。如法治之，浃旬而起。设非武君不又为谈因果者添一公案哉。子芍之证，亦犹是耳。）", "13905": "邱小敏初发热，即肢瘛腹痛，卧则昏谵，坐起即清，膈间痞闷，饮亦碍下，舌色紫肿，苔厚腻黄，身面赤色，龈肿而疼。医见其病情错杂，初以为斑疹之候，进透发之剂，浑身冷汗，又虑内闭外脱，灌以紫雪，病如故。又疑热入血室，用桃仁、茺蔚、丹皮、藕汁、童溲等药，又恐其虚，用西洋参、龟板等味。遂言蹇呃逆，正在彷徨，适病者登圊更衣，忽然昏晕，谓欲虚脱，欲进生脉散以固元气。举家无措，所亲姜柳湖请孟英往诊之。脉洪弦而兼滑数，病属暑湿，惟肝气素郁，肺胃多痰，是以升降失常，邪气壅塞，卧即神昏者，乃湿热上熏也，故坐起则爽，彼热入血室，乃昼明了而夜谵语，非昼卧即昏，夜坐即明也。治宜清展气机，病必化疟而解。设以温散表其汗，则邪炽而津劫；若以滋补固其元，则邪闭而正脱，误用血分药，则引邪入营；徒用寒润法，则遏邪不化。先以雪羹、栀、楝、旋、枳、连、蒌、芩、半、菖、茹、元参、银花、丝瓜络等出入为方，吞当归龙荟丸。果转为疟，各恙递减，连下黑矢，半月后便色始正而疟亦止，胃醒安谷而瘳。停药数日，偶因嗔怒，其疟复作，寒少热多，睛赤龈疼，汗多足冷，孟英曰：余热逗留，风阳内煽也。视其苔灰黄夹黑，因谓其弟桂山曰：但看黑苔退净，则邪自清矣。仍予元参、白薇、知、芩、栀、茹、银花、木通、丝瓜络、菊叶等，送龙荟丸。疟即递减，逾旬苔净，眠食如常而起矣。", "13906": "陈雪舫令郎小舫，年甫冠，人极清癯，偶患疟，医与柴、葛、羌、防数帖，遂不饥不寐，胸膈阻塞，汤水不能下咽，壮热神疲，汗出不解，二便秘涩，舌绛龈疼，齿缝血流，凝结于腭。孟英持其脉细而数，有下厥上竭之势，而肺未肃清，宜用轻剂。以苇茎、冬瓜子、紫菀、元参、通草、枇杷叶、旋覆、滑石、蒌皮、西瓜翠衣为方。数啜而安。嗣用养阴，西洋参不过一钱，生地不过三钱，缘其禀赋极弱，不但攻散难堪，即滋培稍重，亦痞闷而不能运也。耆、术之类，更难略试，故量体裁衣，乃用药之首务也。", "13907": "傅与三令正，年已花甲，患疟服药，浃旬而断，乃夜不能眠者数日，忽然吐泻交作，肢冷自汗，渴喜热汤，神气张皇而有谵语。张某谓元虚，而所用之药乃桂、芍、萸、连、葛、藿、乌药、木香之类。病家欲投温补，迎孟英质之。脉来浮弦软数，尺中甚弱，舌绛无液，稍有黄苔，乃真阴素亏，久伤谋虑，吸受暑热，化疟未清，扰及中州，则为吐泻。询所吐，果有酸甘苦辣之味，泻亦色酱而热如火，岂非伏热之的据耶？然邪已自寻出路，故腹无痛苦，况汗出如淋，不独用香燥疏散之药为耗液，即温补如理中、四逆，亦无非助热而重劫其津也。乃定沙参、龙、牡、朱染茯神、黑豆皮、薏苡、木瓜、小麦、竹针、鲜莲子之方。一剂则吐泻皆止，得寐神清，且略知饥，稍能收谷。次日复诊，病者云：依舌上脱液者三十年矣，是以最怕热药，奈群医谓疟宜温化，以致愈服愈殆，设非先生眼光如炬，恐昨日已登鬼录矣。寻以充液柔肝而愈。", "13908": "高鲁川，家兄礼园之外舅也。年近古稀，新秋患感，顾某进清解药二剂热即退。以其年高遂用滋养，越日复热，谓欲转疟。改用厚朴、姜、枣等药，遂热壮神昏，速孟英视之。脉形滑数，舌心已黑，溲赤干呕，粥饮不入。亟予元参、知母、花粉、银花、竹茹、枇杷叶、莲子心、栀子、白薇、西瓜翠衣为剂，数帖霍然。", "13909": "陈载陶年五十五岁，患疟两旬，始迓孟英诊之。脉不浮而弦滑且数，按之愈甚，苔色黄腻满布，热至大渴，极喜冷饮，小溲赤臭，热时则点滴茎痛，大解不行，间数日则略下稀水，是暑热挟痰见证。疏清解法予之。及阅前医之方，初则柴、桂、姜、枣，嗣用参、甘、耆、术、首乌、草果之类，温补杂投，其疟日甚，其发日迟，其补日峻，其口日渴，乃令热时少饮西瓜汁一二杯。病者饮瓜汁而大快，辄恣饮一二碗，盖谓其体厚阳虚，中气不足，故溺赤而便稀水。又云：暑是阴邪，热自湿来，不可稍犯寒凉之药，因仿景岳治阴虚伤寒以冷水与桂、附并行之例，而令其服温补以治疟，少佐瓜汁以解渴也。噫！景岳此案之不可为训，叶香岩发挥于前，魏玉横辨谬于后，奚可尤而效之乎？治而勿愈，反责病人过饮瓜汁使然。余谓此证苟非日饮瓜汁一二碗，早已液涸痰胶，燎原莫救矣！病者闻而颌之。服数剂，胸前赤斑密布，疟渴皆减，溲渐通，苔转白。前医云：再不温补，恐其骤变，病者惑之，仍服其药，并加鹿茸、附子。又旬余，疟如故而形瘦面黧，气冲干嗽，白糜满舌，言蹇无眠，医者皇皇，病家戚戚。复延孟英视之。脉仍数，曰：邪较衰矣，西瓜汁之功也；阴受劫矣，温补药之力也。极早回头，尚堪登岸。爰以西洋参、生地、甘草、石斛、白石英、葳蕤、麦冬、黄连、阿胶、牛膝为方，并令熬鳖汁饮之。五剂而疟罢、嗽蠲，得眠安谷，苔亦全退，但舌红口辣，溲赤不清。前方去连、膝，加归、杞。服八剂，始解坚燥黑矢而愈。然病者喜温补，既愈仍嘱前医善后，故舌红口辣，与胸前斑点久不能消，直至冬令，孟英力劝停药，始渐除也。有朱湘槎者，与载陶年相若，体相似也，秋杪自越患疟旋杭，屡药不应，迟孟英视之，面赤脘闷，二便不行，热则谵言，苔焦口渴。予小陷胸汤加菖、茹、栀、翘、花粉、竹叶等药。群谓肥人之体虑虚其阳，不敢服此凉剂，治载陶之前医迎合主见，大投温补。载陶偶见孟英而述之，孟英曰：湘槎殆矣，此时恐无西瓜汁以救药误也。旬日后果狂躁而亡，其未亡前一日，人已昏狂，毕某诊云：暑热内陷。意欲挽救，投以犀角等药一帖，故前医于陈证，由攘为温补之功，于朱证则卸为犀角之罪，盖明知温补易售，可以避罪徼功，故乐操其术，而不肯改弦易辙也。后载陶令兄喆堂乔梓同时患疟，因前车之鉴，虽汗多懒语，酷类虚象，不敢从补，均依孟英作暑湿内伏治而愈。", "13910": "家嫂患疥遍身，外科治之不愈，且形瘦而左臂酸疼不能举。孟英按脉弦洪而数，授清肝涤暑之剂，旬余而愈。又闻治一妊妇患疥，疡科治而弗愈，以灵寿寺所售疮药搽之，遂浑身壮热，肤赤神昏，阴户疼肿，尤为惨酷，气逆不饥，彻夜无寐，医皆无策，延孟英视之。脉甚洪数，舌绛无苔，四肢拘挛，溲热如火，乃暑火证而复为毒烈燥热之药助其虐也，谁谓外治不比内服，可以擅用哉？与大剂银花、元参、石膏、甘草、栀子、鲜生地、竹叶、莲子心、菊叶、冬瓜皮、丝瓜络、西瓜翠衣，而以绿豆、黑豆煮清汤煎药。服三帖，肤淡神清，略进稀粥。又三帖热退始尽，四肢渐舒，浃旬肿尽消，周身肤蜕如蛇皮而愈。", "13911": "家慈年七十四岁，陡患泄泻，腹微痛，身发热，神思不清，自汗呕恶，不进饮食，亟延医视。云虑其脱，拟进参药。迨孟英来诊，曰：暑脉微弱，不可谓之虚也，且兼数象，参不可投。高年固属阴亏，然去其所本无，即所以全其所本有也。爰定芩、连、滑、斛、茹、柏、竹叶、银花、橘皮、枇杷叶之方，东瓜汤煎药，一剂而热退神清，二剂霍然矣。既而五弟妇偶患微寒发热，医与柴、芎等药一剂，遂昏狂悲哭，见人辄怒詈欲搏。屈孟英过诊，脉弦滑而数，面赤不瞑，苔色黄腻，胸下拒按，曰：痰热肝火为患耳。以菖蒲、胆星、旋、赭、连、蒌、枳、半，合雪羹投之，一剂而安。翼日寒热复作，孟英曰：幸其体实，药不可缓，庶免化疟也。照方服五剂，果寒热三作而遂痊。", "13912": "关琴楚令孙少西，年三十四岁，素善饮，夏间已患著枕即嗽，讳而不言，家人未之知也。迨秋发热，呕吐腹痛，伊父母以为痧也，诸痧药遍投之，寻即气冲咳嗽，血涌如泉，不能稍动，动即气涌血溢。沈某但知其素禀阴亏，遽从滋补，服后益剧。迟孟英诊焉，脉弦洪而数，曰：虽属阴虚，但饮醇积热于内，暑火外侵，而加以治痧丹丸，无不香窜燥烈，诚如火益热矣。亟当清解客热。昔孙东宿治族侄明之一案与此略同，必俟热退血止，再为滋养，知所先后，则近道矣。病家素畏凉药，而滋补又不应，遂求乩方服之。药甚离奇，并木鳖、麝香亦信而不疑。旬日后血已吐尽，气逆如奔，不寐形消，汗多热壮，再乞诊于孟英，已不可救药矣。", "13913": "沈友闻令郎厚栽，久患羸弱，驯致腹痛便泻，恶谷形消，诸医束手，求孟英图之。脉虚弦而空软，曰：不可为矣。虽然，治之得法，尚可起榻，可虞者，其明年春令乎。爰以潞参、鳖甲、耆、芍、甘、柏、薏、斛、木瓜、橘皮为方，吞仲景乌梅丸。不旬日而便坚食进，又旬日即下楼而肌充矣。又其大令郎子槎之室，体素怯，夏间曾患久泻，多剂温补始瘳。忽发寒热，肢麻头痛，彻夜不眠，嘈杂如饥，咽喉似阻，食饮难下，汗仅出于上焦，佥以为虚损将成。孟英持其脉弦弱而数，视苔微黄满腻，曰：暑湿时疟也，补药乌可投耶？以茹、滑、芩、连、桑叶、紫菀、银花、橘皮、冬瓜子、枇杷叶、丝瓜络等药，芦根汤煎服数剂而痊。嗣与滋养善其后。既而子槎自上海归，亦患疟，孟英视之：暑湿挟痰也。予温胆汤数服而愈。次年春杪，厚栽竟逝。", "13914": "陈氏妇年逾四旬，娩后忽然发狂，时值秋热甚烈，或以为受热，移之清凉之所势不减；或以为瘀，投以通血之药而不效。金、顾二医皆谓虚火，进以大剂温补，则狂莫能制；或云痰也，灌以牛黄丸亦不应。浼孟英视之，切脉弦数，头痛睛红，胸腹皆舒，身不发热，乃阴虚而肝阳陡动也。先灌童溲势即减，剂以三甲、二至、丹参、石英、生地、菊花、牛膝、藕，用金饰同煎，一饮而病若失。愈后询之，果因弄瓦而拂其意耳。", "13915": "吴曲城仲郎偶患少腹坚胀，左胁聚气，群医见其面黄，作暑湿治，攻补杂施，两月弗效。孟英视脉弦涩，溺赤便艰，口苦不饥，肢冷形瘦，曰：非外因也，肝郁耳。予旋覆花汤合金铃子散，加雪羹、竹茹、青皮、白芍煎，吞当归龙荟丸，八剂而病如失矣。", "13916": "濮树堂患滞下，医者以其脉弱体虚，第三日即参补养，延至匝月，痛痢不减，谷食不思，肌瘦如豺，面浮足肿，口干舌绛，懒语音低，气短汗多，略难转侧，诸医无策。始迓孟英诊之。曰：初起脉微弱，为暑之本象，今按之尚数，乃阴液已伤，渴饮无苔，岂容温补？溲赤而痛，胡可酸收？见证虽危，治不可紊。为定白头翁汤加西洋参、干地黄、炙草、白芍、麦冬、阿胶、酒炒银花之剂，以水露煮陈仓米汤煎药。群议以为太凉润，不可轻试，孟英曰：此厥阴证而胃液已伤，幸而脉未空数浮弦，亟予养阴清热，庶可图功，若徒议药不议病，纵有一片婆心，未免好仁不好学矣。病者忆及乙巳之病，深信不疑，遂服之。一剂知，六剂而痢净，舌润知饥，溲通得睡，第便溏腹痛，日必两行，左龈赤肿而疼。外涂以玉枢丹，内治以三奇散加潞参、炙草、薏仁、扁豆、鸡膍胵、黄柏、橘皮，吞香连丸。旬余而浮肿消，大便坚，舌苔生，起于榻，而口腹不节，发热口干，乃食复也，按法治之热退，至七日始更衣，因嘱其加意珍摄，俾易康痊。奈家务纷繁，既愈即不能静养，神机曲运，心气涣散不收，液涸津枯，而前功尽堕，惜哉！然此案自可传也。", "13917": "孙位申令正，左内踝患一疮，外科敷割，杂治两月，渐至疮色黑陷，食减神疲，寒热时形，痛无停晷，始延孟英诊之。脉象弦细无神，曰：此营阴大亏之证，余于外科虽疏，然初起既无寒热，患处亦不红肿，其非火毒可知，并不流脓，虚象更著，始则攻散劫津，继则温托壅气，妄施敷割，真是好肉剜成疮矣。况病在下焦，素患肝郁，耆、茸、芎、归，益令阳浮，两腿不温，岂为真冷？亟煎葱汤将患处洗净，切勿再行钩割。以生附子杵烂贴涌泉穴引火下行，患处日用葱汤温洗。方用血余、当归、冬虫夏草、枸杞、牛膝、苁蓉、猪肤、藕、白蒲桃干煎服。五剂寒热全休，腿温安谷，黑处转紫，痛减脉和。旬日后紫转为红，陷处日浅，始令以珍珠八宝丹糁之。匝月而肌生体泰。", "13918": "沈陶安寒热初作，医用温散药，即眩悗不安，延孟英视之。舌绛无苔，大渴多汗，疟则寒微热甚，发时咳嗽兼呕，溺少不饥，脉洪且数。清癯之体，阴分素亏，而伏暑化疟也。予知、芩、茹、贝、花粉、白薇、银花、元参、枇杷叶、紫菀、冬瓜子等药出入为方。服后连解赤粪，疟即递轻，不半月而愈。乃兄秋粟贾于苏，因八月初五日上海寇警，吴门震恐，遂踉跄旋里。迨十七日忽发疟，但热无寒，汗多昏谵，脉亦洪数，呕嗽溺频，曲糵素耽，体丰痰滞。孟英即以治陶安法，佐以开痰治之，溏解频行，其色皆赤，伏邪虽有去路，缘心阳过扰，谵渴不休。加犀角、竹叶、莲子心之类。至月杪诊时，适大战大汗之际，其家疑为有祟，方在禳祷，铙鼓喧阗，病者神气更不安恬。孟英令将醮坛移远，并灌以神犀丹一丸。其家问此证何不用石膏？孟英曰：药有定性，病无定形，况旬日以来苔退将净，疟即可罢，何必石膏？次日乃叔兰谷另邀一医视之，方虽相似，而迎合主人之意，加入石膏三钱，冰糖四钱，粳米一两。连进两帖，左胁即痞胀不堪，按之如柈，杳不思谷。病者悔恨云：月杪大汗之后，吾疟已休，何以更医致生痞胀。仍迓孟英诊之。脉来涩滞，苔复腻黄，因询曾服滋腻之药乎？陶安始述其所以。孟英曰：石膏为治暑良药，吾非不善用者，因此证不止肺胃二经受暑，心肝二经皆有所病，故不用也，且内挟痰湿者，虽当用亦必佐以宣化之品。辛丑夏家篪伯茂才患疟，初起误服此公石膏两剂，腹遽胀，延成疟鼓，几至不起。后服多剂桂、附及金液丹而始愈，盖此公但见其疟至睛赤，裸衣狂走，而不研察其病情也。余究其因，遽云：疟发时其热自下而上，比至心头，即觉昏冒，且口不渴而恶凉饮，乃湿上甚为热之证，彼时若以苍术同用，则湿热之邪一齐同解，奚至延鼓哉？贤昆仲之疟热亦自下而上，系挟肝阳上升，故热升则必呕嗽，而令兄更有伏痰，故余剂中多用连、夏、菖蒲、滑石之类以化之。今疟罢热去之后，痰湿未清，石膏已误，再佐糖米之甘缓，俾腻塞而不行，苟不急为宣导，则鼓胀之萌也。遂以蒌、薤、菖、枳、连、夏、旋、橘、楝实、延胡、鸡金、雪羹之类。出入互用至二十剂，痞始泯然，粥食递加，苔亦退尽，而竟不更衣，改用参、归、杞、芍、橘、半、苁蓉、首乌、鳖甲等十剂，大解始下，坚黑异常，连解数日始净，随予峻补善后而痊。秋粟之室，怀妊九月，加以忧劳，九月初七日患疟间作，寒热之时，胎痛上窜，或下坠腰疼，更兼痰嗽带下，口渴无苔，其势甚危，孟英但于清解之中加葱白、苏梗投之，连下赤矢，痛势递减，第疟虽渐杀，至期必两发，病者苦之。孟英曰：愈机也，毋忧焉。果浃旬而愈。复苦脘痛呕吐，勺水不纳，药亦不受，授以藕汁、芦根汁、梨汁，少加姜汁，和入蔷薇露、枇杷叶露、香橼露，徐徐呷之渐瘥。嗣予滋养药加黄柏服之而愈。迨冬至分娩甚快健。又秋粟令郎十岁，陶安令爱八岁，俱患间疟，佥虑胎疟难瘳。孟英曰：无是理也，小儿内无七情，苟能慎饮食，较大人易治焉。剂以清解，旬日胥痊。", "13919": "陈载陶令郎夏间患嗽泻愈后，时发微热，寝汗如蒸，医治两月，迄不能退，时犹作嗽，咸以为劳。其世父喆堂逆孟英视之。热甚于颈面，形瘦口干，脉则右大。曰：肺热不清也。养阴之药久服，势必弄假成真，热锢深入而为损怯之证，亟宜澹泊滋味，屏绝补物。以芩、栀、地骨、桑叶、苡仁、枇杷叶、冬瓜皮、梨皮、苇茎为剂。服后热汗递减，至九帖解酱矢赤溲，皆极热而臭，自此热尽退而汗不出矣。惟噫犹不畅，时欲太息，饱则胸下不舒，乃滋腻药所酿之痰未去也。改用沙参、枳实、旋覆、冬瓜子、竹茹、白前、栝蒌、海䖳、橘皮数帖而胸舒嗽断，体健餐加。", "13920": "张某患四肢发热，久治不痊，食减便溏，汗多形瘦。张孝子谓此证非孟英不能愈。遂往就诊，曰：热厥也，前此必误服补药矣，故脉来甚涩，以芩、栀、连、柏、白薇、通草、地骨、青蒿、丝瓜络为方，十余剂而瘥。", "13921": "董茂清患疟，脉软脘胀，手紫面黄，便秘溺红，苔腻而渴。孟英曰：暑湿挟秽气阻于募原，用菖、朴、橘、半、杏、滑、芩、翘、蒌、枳、银花，加雪羹，出入为方。服五剂便泻知饥，疟休而愈。", "13922": "陈诵芬令堂年越古稀，精神素旺，滞下数月，病日以剧。所亲蒋策熏嘱延孟英图之，已粒米不纳，虽啜饮而咽膈阻塞，唇舌皆紫，痰中带血，吐之甚艰，日夜更衣数十次，稀粪挟以赤垢，若欲小溲，必令人重按肛门，始能涓滴而出，热如沸汤，脉则左手弦洪涩数而上溢，右软滑而大，按之无神。孟英曰：此证本滞下，良由七情郁结，木土相乘，医谓高年，辄投温补，酿成危证，药不可为。诵芬云：先生之言是也，家慈因春间叠闻江南之警，心甚皇皇，举家迁避，饮食顿减，夏初旋里，似已稍安，六月间患泻，饮食又减，屡进参、术、熟地、附、桂、炮姜之剂，竟无寸效，惟望鼎力斡旋是幸。孟英曰：上不能纳，下不能分，中气无权，营津两匮，既承下问，姑拟一方，仅许小瘥，不能奏绩也。诵芬从之。服后即思粥食，小溲单行。再求转方，孟英坚不承手。果至季秋而没。其方乃沙参、冬瓜子、丝瓜络、芦根、紫菀、菖蒲、竹茹、通草、薏仁、枇杷叶、陈仓米，以水露煎服也。顾铁舟赞府，精于医者也，目击其一服而进粥溺行，因叹曰：仙方也。惜遇之不早，命矣夫！", "13923": "徐仲荣四令弟德生，患感至旬余，忽然大战大汗，而大便兼下瘀血。朱茂才视之，不知战解之义，以为将脱也，率投大剂温补药一服，汗收壮热，杳不知饥，渴饮无眠，舌赤溲少，遂束手。更医谓汗下伤阴，滋填叠进，驯致身难转侧，懒语音低者，又旬余矣。所亲吴爱棠嘱延孟英图之。脉弦数而驶，按其胸下坚且痛，舌绛而根苔黄滞，曰：汗下伤阴固然，惟府犹实也，滋腻曷可投耶？然一病至此，又难攻夺，姑以善药通之。因予小陷胸汤合雪羹，加茹、杏、紫菀、白前、冬瓜子、芦菔和梨汁，服二帖，坚黑之矢果下，仍夹瘀血，身热遂缓，稍进稀糜，改用清养肺胃以充津液。旬日后热净溲澄，知饥安谷，惟舌不生苔，寐即汗出，授大剂滋阴而愈。德生有一婢，年十七矣，陡患腹痛，稍一言动，则痛不可支，举家疑为急痧中恶，多方以图皆不应，飞速孟英往视。见其神色如常，并不吐泻，脉则牢涩，苔则腻黄。曰：此多食酸甘而汛阻也。询之果然。以桃仁、红花、生蒲黄、灵脂、海䖳、香附、延胡、芍药，芦菔汤煎药，吞当归龙荟丸而愈。", "13924": "许梅生仲郎恬甫，年未冠，仲秋患感，医知其阴虚伏暑也。叠进清卫凉营之法，旬余热退，以为无虑矣。惟六日不更衣，因用生地、麻仁、花粉等药。服后果欲大解，及登圊大泻一次，人即汗晕，急扶上榻，连泻二三十次，满床皆污，尽是黄水，身复发热，肢痉音低，唇焦齿槁，苔色干黄而渴，舌不能伸，目不欲张，速孟英勘之。脉微细欲绝，而呼吸甚促，按其心下坚而且痛。曰：疾不可为也。缘初治失于开泄，胸中痞结而津液不能敷布，尽从下脱，攻补皆难措手矣。翼日果殒。", "13925": "许兰屿令正素属阴亏，舌常脱液，季秋患脘下疼胀，得食愈甚，映及胁背，宛如针刺，稍合眼则心掣动而惊寤，自按痛处，则涌水苦辣，渴不欲饮，溲少神疲，自疑停食，服楂、曲而益剧。孟英视脉弦软，曰：此停饮也，饮停则液不能上布，故口渴；而饮即水也，内有停水，故不喜饮；其舌上脱液虽属阴虚，亦由饮隔；寐即心掣者，水凌火也；得食痛加者，遏其流也。以芩、泽、橘、半、旋、蛤、连、䖳加生姜衣投之，溲行得睡，惟晚食则脘下犹疼，疼即心热如火，且面赤头痛，腿冷腰酸，必俟脘间食下，则诸恙皆平。孟英曰：此停饮虽蠲而肝火升也，宜参潜养为治矣。改授沙参、苁、归、竹茹、楝、柏、石决明、丝瓜络、姜汁炒栀子，少佐生黄连，服之遂愈。", "13926": "蔡湘帆年二十岁，体素丰，偶发寒热，翼日尚吃饭出门，自不知为病也。第三日寒热大作，茎缩不能小溲，气喘大汗，眩晕不支，乞孟英往诊，举家仓皇大哭。循其脉缓大而滑，苔色黄腻，脘下拒按。曰：无恐也。予菖、枳、旋、蒌、栀、豉、连、半、茹、䖳，以芦菔汤煎服一剂，大吐痰涎而喘汗平，二剂茎舒溲畅而大解行，越日寒热即减。又两剂疟罢知饥而愈。然李东垣谆谆以内伤类外感为言，而温热暑湿之病，初起极类内伤，往往身未发热而手心先热，或兼眩晕自汗，设泥古法而不辨证，祸可言哉！", "13927": "叶承恩年五十岁，患发热暮甚，肢厥头疼，呕恶便溏，睡则呓语，不饥不渴，汗出上焦，自觉把握不住。延孟英诊之。脉软涩而不鼓指，右手尤甚，宛似虚寒之证，惟舌本紫，苔虽薄而黄腻口苦，眼鼻时觉出火，是真阴素亏而热伏于内也。予栀、连、桑、菊、茹、翘、芩、斛、银花、丝瓜络、莲子心出入数剂，热呓皆减，脉亦较和，溲赤而疼，大解色酱，知其伏热下行矣。又数剂，苔始退而知饥，参以养阴而愈。", "13928": "一劳力人发热，左胁疼，咳嗽碍眠，痰出甚臭，苔黄舌绛，渴饮谵语，便秘溲赤，脉形滑数，乃伏暑证。询其平昔嗜饮，醉后必向左卧，故湿热酿痰，久积于左，非内痈也。以苇茎汤去苡仁，加雪羹、芩、滑、茹、翘、栀、蒌、旋覆、木通等出入三剂，大便行，谵语止，而痰出更多，其臭益甚。仍用前药。又四剂痰始少而不臭，热净能眠，知饥苔退。改授甘凉养液而瘳。", "13929": "陈芷浔主政患疟，跗肿便溏，痰多食少，时欲呕吐，间有郑声。孟英取其脉微弱而弦，不渴无苔，小溲不赤，乃中虚寒湿为患也。方以六君去甘草，加桂枝、苡仁、白芍、吴萸，投剂即减，半月而愈。", "13930": "周光远令正，孀居十载，年已五十三岁，汛犹未绝，稍涉劳瘁，甚至如崩。偶患少腹偏左掌大一块作疼，其疼似在皮里膜外，拊之痛甚，越日发热自汗，眩冒谵语，呕渴不饥，耳聋烦躁。孟英循其脉虚软微数，左兼弦细，便溏溲热，舌本不赤，略布黄苔。营分素亏，而有伏热阻于隧络，重药碍投，姑予芩、连、芍、楝、竹茹、桑叶、白薇、通草、橘核、丝瓜络、灯芯，少加朱砂和服。一剂势即减，二剂热退呕止，啜粥神清，第腹犹痛，去桑、芩、灯芯、朱砂，加苁、归、苡、藕，服数帖而起。迫季冬，其君姑七十八岁，患腹痛，痛亦仅在皮膜，仍能纳食，二便无疴，数日后痛及两腰，机关不利，碍于咳嗽，痰出甚艰，而有咸味，夜不能瞑。孟英视曰：肝肾大虚，脉络失养也。以沙参、熟地、归、杞、苁、膝、杜仲、石英、羊藿、络石、薏苡、胡桃等药进之，日以递愈。继用一味桑椹，善后而康。", "13931": "四舍弟西甫年二十四岁，秋杪患感，至六日神渐昏，延孟英诊之。脉形涩滞，苔垢头疼，气逆汗频，腰疼溲少，脘闷拒按，乃伏暑晚发而本元极亏也。亟与开中，俾有去路，小陷胸加栀、豉、菖、芩、白薇、翘、枳，芦菔汤煎服一剂，脘不拒按，苔亦稍退，汗不达于下部，脉来软而且涩，改授茹、半、芩、栀、橘、翘、知、蛤、花粉、莲子心之剂。三帖脉转弦数，大解未行，谵语不休，夜间热炽，腿凉头晕，浊热上熏也。以芩、蒌、栀、连、茹、翘、元参、白薇、丹皮、海䖳、竹叶投之。乃下坚黑大便，而圊后神晕，苔渐薄而转黑，为去芩、连、蒌、䖳，加犀角、鲜生地、知母、花粉两帖。更衣仍黑，气乃渐平，腿亦渐温，热渴均减，犹不知饥，脉软而虚，苔退未净，乃去犀、翘，加西洋参、麦冬、银花、菖蒲。服三剂，又解黑矢，舌色始津，而寐不安神，汗多心悸，因去知母、花粉、丹皮，加甘草、丹参、茯苓，而地黄用干者。两帖，大解甚畅，胃渐知饥，稍渐稀糜，力不胜啜，脉亦虚大，寐即神驰，乃邪未清而虚毕露也。用西洋参、生地、龙齿、归、芍、芩、甘、连、柏、麦冬、小麦。服五剂，复下酱矢，而右脉尚虚大。又六帖，粪色始正，汗减神安，脉渐柔和，寝食乃适。嗣又食复数次，赖孟英活泼如龙，随机应变，竟以告愈，洵属再生。", "13932": "四弟妇怀娠临月，西甫起病之次日，即患疟，因弟病日剧，不免忧劳，至第五日孟英视之。脉欲离经，腰疼腹坠，伏暑化疟，将娩之征。以栀、豉、苏、归、芩、连、茹、半、知母、葱白服两帖而产。产后疟来颇减，恶露不行，腹不胀疼，不饥而渴。投栀、滑、薇、茹、泽兰、丹参、通草、桃仁、茺蔚药一剂，恶露即行，而狂言不寐，面红口渴，人皆危之。盖杭谚有云：夫病妻怀孕，铁船过海难逃命。未产先萦忧惧，既娩血去火炎，故昼夜辄以铁船沉海云云。孟英于前方去泽兰、通草，加琥珀、菖蒲、胆星、灯芯，和以童溲投之。一饮神识渐清，再剂即安睡矣。去琥珀、菖、星、桃仁、灯草、茺蔚，加知母、麦冬、甘草、沙参、枇杷叶，冲入藕汁一杯。三服解赤矢而苔退，疟亦减而嗽痰，改用沙参、枇杷叶、冬瓜子、甘、斛、栀、薇、茹、翘两帖。嗽减犹渴而身痛，去栀、薇、枇杷叶，加归、贝、鳖甲。四帖而疟罢，眠食咸安，调养至弥月，即出房矣。", "13933": "三舍弟拜枫之室，汛后患感。孟英视曰：冬温也，而营分素亏，左腹聚气，肝阳烁液，痰阻枢机。脉数而虚，黄苔满布，腰疼碍于呼吸，口淡不饥不渴，嗽则欲呕，溲热便秘，当变法治之。初授葱、豉、连、楝、栀、薇、延胡、丝瓜络、竹茹，少加苏叶。服二剂解溏矢，苔稍化而身热退，起榻梳发。复发热，脉尚数，改用南沙参、枇杷叶、橘、斛、栀、薇、芩、翘、芦菔。服二帖，脉数渐退，大解复行，心悸汗多，时或发热，间有谵语，胁痛不饥，苔色根黄，即参养血。以北沙参、归身、石英、丹参、茯苓、黄连、葳蕤、甘草、小麦、红枣核为方。服三帖虚热不作，谵语亦休，大解已坚，夜不成寐，不饥胸痞，痰滞未清也。为去后四味，加竹茹、半夏、盐橘红、姜汁炒栀子。二帖痰果吐，胸渐舒，仍不知饥，神疲不语，脉甚细软，乃去芩、连、栀、半，加石斛、麦冬、冬瓜子、藕，而易沙参以西洋参，用陈仓米汤煎药，和入野蔷薇露。服五帖脉渐起，神亦振。七帖后知饥，而苔花少液，去竹茹、冬瓜子、蔷薇露，加甘草、生地、白蒲桃干。服二帖粥食虽增，耳鸣神惫，复加枸杞，而地黄用熟者，易洋参以高丽参。服后苔净加餐，再加黄耆、杜仲而愈。惟素患带多，仿虎潜法善其后，汛至而康。", "13934": "五舍弟树廷，时患喘逆，初冬尤甚，稍食甜物，其病即发。孟英察脉迟弱，苔黄垢而不渴，指冷腿酸，乃中虚痰湿内盛也。授参、术、苍、枳、旋、半、薤、朴、杏仁、生姜之剂。服后痰果大吐，气亦渐平，嗣以六君去甘草，加当归、木香调补而痊。", "13935": "沙沛生鹾尹令堂年五十七岁，体素弱而多怫郁，秋间患疟于诸暨，医治未效。冬初来杭，谢某叠进温补，其势孔亟，寒微热炽，昏谵瘛疭，目不识人，舌绛无液，苔色黄燥，便秘不行，延孟英视之。脉洪滑右甚，左手兼弦，乃痰热深蟠，内风煽动也。予知母、花粉、蒌仁、竹茹各三钱，佐以栀、薇、翘、贝、橘红、莲心。一饮而更衣溲畅，胸次较宽，痰嗽口糜，且知头晕，乃去知母、花粉、蒌、翘，加沙参、苡、斛、麦冬、野蔷薇露。次日疟来甚减，糜退口干，神惫音低，津虚痰滞也。去苡仁、枇杷叶、蔷薇露，加知母、花粉各一钱五分，甘草五分，和入藕汁一杯。服二帖疟至甚微，口干倦卧，脉则右虚左数，用养气充津、蠲痰清热法：西洋参、盐橘红、归、甘、杞、斛、冬、茯、茹、蕤，和入藕汁。服两帖疟休神爽，咽痛唇糜，饥不能餐，余焰内燃也。去杞、斛、甘草，加生地、牛膝。四剂后咽唇皆愈，神惫懒言，仍加杞子、甘草。服二剂胃气渐苏，口犹少液，因涉嗔怒，暮有微热，肤肿欲呕，口干便秘，即去地、冬、蕤、杞、甘、膝，加连、楝、蒺藜、石英、丝瓜络、冬瓜皮。一啜热去呕蠲而腹犹胀。去西洋参、归身、冬瓜皮、石英、黄连，加沙参、旋、芍、延胡、香附、藕。一剂胀消，而口淡便秘，饥不能餐。改用西洋参、木瓜、银花、延胡、蒺藜、苁、归、芍、斛为方。投匕而便行，三啜而肿尽消，始予高丽参、紫石英、橘、半、归、冬、菖、茹、牡蛎调养。续去菖、半，加杞、地、鳖甲而愈。嗣因登圊跌仆而发寒热，周身骨痛，会阴穴起一瘰甚疼，乃以高丽参、骨碎补、合欢、木瓜、杜仲、丝瓜络、鹿角霜、首乌、鳖甲、杞、柏、归、甘、苡、膝、苁、斛等出入为方，外用葱白杵烂，蜜调傅患处，七日而痊。", "13936": "沛生令庶母亦在越患疟，来杭后孟英视之。脘闷欲呕，汗多头重，脉来弦数，苔色腻黄。乃余邪逗留，兼挟肝郁。以枳、朴、芩、半、茹、斛、蒌、菖，加苏叶炒黄连投之，痰涎大吐，邪已外越，脘胀口干，寒热复作。乃去朴、半，而加艽、翘。吐犹不止，聚气上冲，渴饮无眠，筋瘛便秘。改用金铃子散合雪羹，加旋、赭、茹、半、姜汁炒栀子、苏叶炒黄连。一饮而呕渴减，气下行。即去金铃子散、旋、赭，加沙参、归、斛。服五剂，各恙皆安，神惫汗多，为用沙参、归、斛、芩、橘、栀、连、茹、藕二帖。又因嗔怒，左胁作胀，苦渴不饥，暮热便秘，于前方加柴、芍、金铃子散。一啜胁胀即舒，惟气冲口苦，饥不能餐，自汗耳鸣，头左筋惕，改授沙参、当归、鳖甲、石英、竹茹、牡蛎、蒺藜、菊花、丝瓜络。服旬余眠食皆适，但暮则火升，口干易汗，去蒺藜、丝瓜络，加黄连、麦冬合甘麦大枣汤，服浃旬，经行腰痛，头震耳鸣，八脉久亏也，调养奇经以善后而康。", "13937": "沛生令宠平素阴虚肝旺，而腹有聚瘕，时胀时疼，初冬患疟，苔黑口干。孟英脉左弦数而洪，右滑数而溢。初以栀、豉合金铃子散、雪羹，加元参、白薇、竹茹。服四帖，疼胀皆减，疟缓汗多，溲涩口干，饥不能食，气时冲逆。予沙参、归、斛、茹、橘、石英、丝瓜络、蛤壳、藕。二帖后汛行腰痛，口渴少餐，气郁营虚，兼有痰滞也。去蛤壳加旋覆、冬瓜子、花粉。两帖而更衣乃畅，然犹脘闷不饥，汛少且黑，口渴头疼，疟亦未罢，乃去石英、旋覆，加栀、滑、枳实。四剂各恙皆安，疟犹未断，以归、苁、甘、杞、橘、半、蒌、芩、竹茹、花粉，少佐桂枝调其营卫。奈病者因口苦而恶粥食，嗜啖甘酸，病既曲折，邪益留恋。此方服至半月而疟始休，惟宿瘕时痛，肛痔便难，口苦吞酸，神疲寝汗。去芩、桂、甘草、花粉，加鳖甲、乌鲗骨、白芍、延胡、仙灵脾、藕，出入调补而痊。", "13938": "德清徐子瑞令正，屡次堕胎，复多忧郁，汛行之际，患疟经止，而两耳骤聋，虽对面疾呼，亦不闻也，不饥不渴，不语不眠，便秘遗溺，仰面静卧而已，惟热至则昏谵欲厥。乃父沈悦亭谓其热入血室，拉孟英视之。脉滑数而右大，按之皆虚，两尺尤甚，胸下拒按。曰：此下元虚损，故耳聋若是，即精脱之征，岂可因汛遽止而辄通其血乎？然气郁痰凝，苔色白腻，上焦邪实，补且缓商，先予小陷胸合蠲饮六神汤，加雪羹开痰行气。悦亭韪之，三服便通，胸不拒按，苔化黄色，疟即较轻，改以沙参、归、斛、茹、半、翘、芩、菖、橘、甘、艽。五剂疟止，渐思饮食，二便皆调，两耳仍聋，脉形细弱，乃用大剂培养药善后而愈。", "13939": "沈南台年三十七岁，初冬在乡收租，将归饱啖羊肉面条，途次即发热头疼，到家招沈某视之，谓其体丰阳气不足，以致伤寒夹食，表散消导之中，佐以姜、附。数帖后，热壮神昏，诸医束手，交八日，所亲许锡卿、吴久山交荐孟英图之。苔色黄腻，口不甚渴，粒米不沾，时时火升，汗躁谵语，溲赤便秘，面晦睛红，呼吸不调，胸前拒按，脉则虚软微带弦滑，不甚鼓指，曰：体气素亏，然脉证太觉悬殊，必因痰阻清阳，故气壅塞而脉更无力也。剂以小陷胸合雪羹，加旋、菖、薤、枳、栀子、胆星。服后痰即吐，脉较起。再服谵语息，三服痰中带出紫血数块，四服热退而汗躁胥蠲，七服苔净胸舒，溲长口渴。改予甘凉濡润之法，服数帖痰已渐少，舌布新苔而仍不更衣，觉有秽气上冲，亦不知饥。仍予甘凉养胃，佐以兰叶、野蔷薇露降其浊气。数帖后，秽气除，粥食进，但不大解，家人忧之。孟英曰：既无所苦，能食脉和，静俟水到渠成，不可妄行催动也。既而加谷起床，便犹不解，病者停药旬日，计起病已交一月矣。粥嫌不饱，意欲食饭，复请孟英商之。孟英曰：可食也，药则不当停，亟宜培养涵濡俾其转运也。授参、术、归、苁、杞、麻、半、芍，少佐枳壳为方。服十二剂始得畅解坚矢，嗣与峻补善后，寻即复元。续有宣氏妇脉体极虚，患温而胸次痞闷，苔黄垢腻，医皆畏难而退。孟英以轻清肃化之药数剂，苔退胸舒，即能进粥，随予生津养血，又旬日更衣而愈。观此则黄苔宜下之说，须合脉体以为可否也。", "13940": "曹氏妇孀居而操家政，人极精干，患恙旬余，诸医以为冬温而多药罔瘥，势濒于危，伊亲家孙位申速孟英挽之。面赤耳聋，脉状细软，舌赤无液，粒米不沾，夜不成眠，便溏浸赤，痰咸咳逆，腹胀气冲，龈肿巅疼，音低自汗，口中甚辣，心下如焚，两足不温，时欲发晕。乃肝肾素亏，心阳内亢，原非感证，药误已深，纵是冬温，亦不可妄施柴、葛，况足冷面赤，非浑身发热之比也。既耗其气，更烁其营，阴火潜燃，治宜镇息。方以参、蛎、连、芍、茹、冬、楝、斛、丹参、小麦、龟板、鳖甲，煎吞磁朱丸。一饮胀消，余证不减，去楝、芍、龟板、鳖甲，加龙齿、银花、导赤散。三服晕止便坚，小溲亦畅，略安寝食，再去银花、木通、磁朱丸，加知、柏、红枣、紫石英，而麦冬以朱砂染。两帖火降足和，舌色渐润。又两帖，汗嗽胥减，心下始凉，乃易生地以熟地滋补而瘳。", "13941": "叶茂栽年三旬余，寒热时形，身振多汗，医从疟治，数日而危，速孟英视之。脉微欲脱，语难出声，舌光无苔，筋惕肉𥆧。亟宜救逆合建中汤灌之，复杯即愈，续服多剂培补而安。", "13942": "翁某年甫冠，仲冬患感，医与温散药数帖，神悗耳聋，苔黑便泻，胸痞腹胀，溲少妄言。孟英切脉细数而涩，乃暑湿内伏，气郁不宣也。投以犀角、银花、元参、连翘、菖蒲、郁金、黄连药一剂。热退神清，脘不拒按，别恙未减，脉则弦细而数，口转发渴。改用芩、翘、朴、斛、连、楝、银花、通草、兰叶、冬瓜皮为剂。两啜化为间疟，其疟发一次，则苔化一层，胀减一分，粥加一盏。药不更张，凡四发而苔净胀消，脉和溲畅，嗣予调养而康。", "13943": "潘妪久患痛吐，多药莫痊。孟英视之，脉弦劲而数。曰：口苦而渴乎？大便不畅乎？小溲如沸乎？病者云诚然。第冷气时冲，欲呕不畅，渴喜饮沸，吐沫极酸，总由积寒深重耳。孟英曰：因此谅诸医必用温燥之药矣。须知气冲觉冷者，热极似寒；渴欲饮沸者，饮邪内踞；吐沫作酸者，曲直所化；其病在络，故吐之不易。方以茹、旋、栀、楝、枇杷叶、丝瓜络、木通、生姜衣、海䖳、凫茈、苏叶炒黄连，煎吞当归龙荟丸。一剂知，五剂愈。", "13944": "张氏妇先于四月间患呕吐，医以为寒，叠进姜、萸之药，致血溢自汗，丐孟英诊之。脉甚滑，按之不绝，舌光无苔。曰：孕也。询其经事，果愆两度。予沙参、枇杷叶、生地、芦根、连、苏、旋、斛之剂而安。仲冬举一男，胎前即患痰嗽，娩后招专科治之，服四物汤增损多剂，而气逆碍眠，嗽则汗出，便溏遗溺，口渴不饥。再乞援于孟英，脉洪大按之虚软。授沙参、石英、黄耆、苡仁、甘草、牡蛎、石斛、茯苓、小麦、红枣、冬虫夏草之方，两帖而汗收安谷，四帖而渴减便坚，旬余遂愈。", "13945": "朱庆云室，年六十六岁，初发热即舌赤无津，钱、丁、任、顾诸医胥云：高年液少，津涸堪忧。甘润之方，连投八剂，驯致神悗耳聋，不饮不食，沉沉欲寐，呃忒面红，势已濒危。徐德生嘱其延孟英图之，审其脉弦滑而数，视其舌绛而扪之甚燥，然体丰呼吸不调，呃声亦不畅达，合脉证与体而论之，虽无脘闷拒按之候，确是肝阳内炽，痰阻枢机，液不上承，非津涸也。剂以小陷胸汤加茹、薤、旋、菖、枇杷叶、苏叶。一饮而夜得微汗，身热即退，次日痰嗽大作，舌滑流涎。病家诧曰：奇矣！许多润药求其润而愈燥，何以此剂一投而反津津若是耶？殆仙丹矣？三帖后更衣呃止，痰嗽亦减，渐进稀粥。改用沙参、紫菀、苡、斛、归、茹、麦冬、冬瓜子。服数帖溲畅餐加，而觉肢麻头晕。予参、耆、杞、归、芍、橘、半、熟地、天麻、石英、牛膝、茯苓、桑枝，补虚息风化痰而健。", "13946": "朱逵士令正，怀妊八月，脘痛便溏，跗肿腰疼，频吐绿水，温补不效。孟英诊之：脉软而弦，舌绛无液，口干少寐，形瘦神疲。木土相乘，阴液大耗，虽宜培养，燥烈禁施。以参、连、归、斛、杜仲、灵脾、冬虫夏草、柏、橘、茹、英为剂。果各恙递安，脘舒泻止，加以熟地，舌渐生津而愈。", "13947": "黄漱庄司马，素患左目失明，今春右目患障，多药未瘳，延至秋间，孟英视曰：脉甚弦滑，痰火之疴，温补宜停，庶免瞽患。奈司马性喜温补，不以为然，渐至耳亦失聪，冬季再请孟英往诊。右目但能视碗大之字，稍小者不能见矣，耳则虽对面撞钟放炮，胥无闻也，且巅肿而疼，时咳白沫，脉来搏劲不挠，见其案头有顾某所定丸方，用药四十味，皆贵重温补及血肉之品。盖其病在络，不在藏府，故服此如胶似漆之药，仅能锢疾成废，而无性命之虞也。闻辛亥春，许辛泉患类中，诸医佥从虚治。孟英诊脉沉滑而数，且体厚苔黄，亟宜化痰清热。疏方毕，人皆不以为然，惟其子秋芦极佩服云：五年前家父患恐惧多疑，曾屈诊视，方案犹存，若合符节，只因家父性喜温补，前之病根不拔，酿成今日之疴，先生卓见不可及也。奈病者依然不悟，不刈根株，延至壬子夏复中而殒，年未五旬也。并识之以为不究病情，好服温补者鉴。", "13948": "施瀛洲体丰色白，夏月在绍患泻，医进参、术、桂、附、熟地、四神之类，略无寸效。季冬来杭就诊于孟英。其脉微弱，左手及右尺沉取有弦数之象，眩晕形消，舌色深紫，无苔不渴，纳食腹胀，溲少而赤，泻必肠鸣。中气固虚，理应投补，但不可佐滋腻以滞中枢，而助其溜下之势；又不宜杂燥热以煽风阳，而壮其食气之火。予参、耆、术、苡、升、柴、苓、泽、香连为剂，吞通关丸，乃宣清升降补运兼施之法也。服之良效，浃旬舌淡溲行，胀消晕止，惟大便未实耳，去苓、泽、升、柴、香连、通关丸，加菟丝、木瓜、橘皮、黄柏、石脂、白芍善后而瘳。", "13949": "清道光朝。浙医王孟英先生名士雄，潜斋半痴梦影。皆研医后之别字。其字梦影者。示药因证异。不执效方之义。著有温热经纬。即王氏五种行世。就中医案。都凡十一卷。虽大旨为救温补而设。实则随证制方。丝丝入扣。果得融会贯通。则古今医籍兼读可。缓读亦可。先生深得力于喻子嘉言。（念）读先生书。而后得门。原案或脉证方药并叙。或叙证遗脉。或叙脉遗证。若方药注铢两者。则更千百首中一二。窥其编次苦心。殆欲人深思自得。中材而下。难觅金针。（念）不敢忘得门所自。谨就原案笺释其病情脉义。方药之偶阙者僭补之。铢两之不注者僭拟之。顾于原案显不吻合者有二。勘病制方。本有得意疾书之乐。移时或铢两皆忘。何况据案悬拟。元运衰薄。气体渐就劣弱。拟注不得不故减铢两。以便揣摩。若温病中风升阳浮各案。潜阳重镇之品。不得宗法。先生函诊杨素园室人方案。一药辄至数两。匪独偏证偏治急证急治非此不生。并取（念）所屡试屡效者折中规定。不敢执死书以困活人。览者慎勿疑信参半。致千虑一失。若用多备少服法。分次徐投。药效即止。则无不可。稿成。颜曰中医指掌。邑同学束子劭直慨任印赀。除（念）续刊最简单之本草外。览者手此一编。可以寻途辙。资事蓄。谓保国粹。则吾岂敢。", "13950": "一切脉以沉脉为要。是书于沉脉之吻合病情者详注之。", "13951": "一切脉病者正坐。尽前两手肘置案上。重按久按。方切得出沉脉脉情。", "13952": "范庆簪年逾五十。素患痰嗽。乙酉秋在婺。骤然吐血。势颇可危。孟英诊曰。气虚而血无统摄也。虽向来咳嗽阴亏。阴药切不可服。然非格阳吐血。附桂更为禁剂。乃以潞参耆术苓草山药扁豆橘皮木瓜酒炒芍药为方。五帖而安。（素患痰嗽。病在气分。不在血分。孟英诊断气虚。必左右脉皆无力。右脉重按尤软。气虚忌用冬地阴药固己。但非格阳吐血。若用一毫附桂。便伤其兼证之阴亏。宜用炒潞参五钱。炒西耆四钱。炒白术三钱。云苓片三钱。炒粉草一钱五分。炒山药三钱。炒扁豆三钱。陈橘皮一钱五分。陈木瓜一钱五分。酒炒白芍一钱五分。此证注重气虚。但补气不可伤阴。方中甘草木瓜并用。于补气中取酸甘化阴之义。亦即引阳入阴之法。但主要病情在气虚。参耆少用不足补气。全方一时全服。亦恐非重药轻投之义。宜仿仲景许叔微成法。分次徐服。此必孟英当日所有。）继去甘草木瓜。加熟地阿胶紫石英麦冬五味子龙骨牡蛎熬膏。服之全愈。（更方系从阳引阴之义。除前方各加十倍外。去甘草木瓜。恐甘酸之性滞腻气分。不能摄阳入阴。使阴亏咳嗽之兼证并蠲。宜用熟地二两。阿胶二两紫石英一两。整麦冬一两。五味子一两杵。煅龙骨二两。煅牡蛎二两。石英龙牡先煨。熟地阿胶麦冬治阴虚。石英五味龙牡敛镇。为阴药下行之使。）", "13953": "郑德顺春患急证。时已二鼓。丐孟英视之。见其扒床拉席。口不能言。惟以两手指心抓舌而已。孟英曰。中毒也。取绿豆二升。急火煎清汤澄冷灌之。果即霍然。诘期询其故。始言久患臂痛。因饵草头药。下咽后即心闷不可耐。舌麻不能言。（绿豆为清凉解毒之品。用二升及急火煎清汤澄冷灌之。各有深义。阳动阴静。扒床拉席。是热证非寒证。口不能言。两手指心抓舌。是病在气分不在血分。两手指心抓舌。毒重病急。急证急治。绿豆少用。则有杯水车薪之祸。煎药文火药性入下焦。武火药性入上焦。故宜急火煎清汤。其澄冷灌之者。前项病情。热毒虽在上焦气分。然煎成热服。则证热汤热。下咽后嫌与病势扦格。澄冷灌之。即用寒远寒之义。）婺人罗元奎。夏令猝发寒热。旋即呕吐不能自立。自言胯间痛不可当。孟英视其痛处。焮赤肿硬。形如肥皂荚。横梗于毛际之左。乃曰。此证颇恶。然乘初起。可一击去之。用金银花六两。生甘草一两。皂角刺五钱。水煎和酒服之。一剂减其势。再剂病若失。（猝发寒热三句病在气。胯痛难当四句病在血。此证系血病及气。本病在血。标病在气。若治血遗气。则本得标失。若徒治气病。则更与病情根键不合。此证颇恶三句。即急证急治。偏证偏治之义。暴病多热证实证。银花治血热血瘀君药。凡病偏于阳者。必不足于阴。且血热贼气。气不降则气不治。血亦不治。故用生草一两以缓中顾阴。兼储作汗基本。角刺少用则发外证。多用则散外证。银花生草缓上中以入血分。角刺五钱煎和酒服。引甘寒之银花生草上入气分。合之为一升一降。且酒能引银花入血分凉血散瘀。陈酒和服。宜用一两。高粮减半。）逾年患伤寒。孟英切脉虚细已极。曰。此不可徒攻其病者。以阴分太亏耳。予景岳法。以熟地当归酒炒白芍炙甘草橘皮柴胡等药。一剂而瘳。（此证阴中之阳亦虚。故方中参用当归炒芍。喻氏嘉言医门法律论治病三分内伤。七分外感。外感为重。七分内伤。三分外感。内伤为重。实为万世南针。孟英深得力于喻氏。世医治伤寒满纸温散。无一药顾及内伤。误人无限。宜用炒熟地一两。开水泡汤。去渣用汤煎药。当归身三钱。酒炒白芍一钱五分。炙甘草三钱。橘皮一钱五分。柴胡三钱。橘柴均次入。）", "13954": "赵子升夏病疟。急延孟英视之。曰。暑热为患耳。不可胶守小柴胡也。予白虎汤一啜而瘥。（此证必面赤大汗饮冷舌赤脉数重按有力。生石膏一两先煎。酒炒知母三钱。宜去原方甘草粳米。加鲜竹叶二钱。黑栀皮三钱。冬瓜皮三钱。生冬瓜子四钱。鲜荷茎一尺五寸。）范丽门患温疟。孟英用白虎加桂枝以痊之。（生石膏六钱先煎。酒炒知母一钱五分。川桂枝四分。去草米。加丝瓜络三钱。晚蚕砂三钱。苦杏泥一钱。陈香薷五分。桂枝杏仁香薷同次入。）盛少云夏病湿热疟。孟英以白虎汤加苍术汤而安。（此证湿虽化热。与湿未脱离关系。生石膏五钱先煎。酒炒知母一钱五分。生茅苍术二钱。去米草加云茯苓一钱五分。生苡仁三钱。鲜荷叶三钱。鲜芦根三钱。）某夏患疟。服柴胡药二三帖后。汗出昏厥。妄语遗溺。孟英切其脉洪大滑数。曰。阳明暑疟也。与伤寒三阳合病同符。处竹叶石膏汤。两剂而瘳。（此必阴虚之体。柴胡汤劫汗伤阴。汗出昏厥。妄语者。胃脘部位与心相近。胃热侵心则妄语。遗溺者。肺胃相近。热伤胃即伤肺。肺司周身气机升降。肺阴为热邪所伤。则肺阳亦失其宣摄之用。故遗溺。脉洪大为阴虚。滑数为热实。生石膏八钱先煎。酒炒知母二钱。生甘草三钱。去粳米。加麦冬三钱。北沙参四钱。鲜竹叶二钱。黑栀皮三钱。冬瓜皮三钱。晚蚕砂三钱。炒苦杏云茯苓各一钱五分。）黄肖农患暑疟。孟英投白虎汤加西洋参数帖始愈。（暑能伤阴。生石膏八钱先煎。酒炒知母二钱。西洋参三钱。去米草。加元参片三钱。开水泡冲去渣鲜荷梗三钱。鲜芦根五钱。冬瓜皮三钱。晚蚕砂三钱。鲜茅根三钱。苦杏泥一钱。陈香薷五分。）顾味吾妻病瘅疟。亦主是方而效。庄芝阶妻年逾花甲。痰热甚炽。孟英审视再四。亦予竹叶石膏汤而安。（人有阴脏阳脏之分。业医者不可不知。年逾花甲。痰热甚炽。必系阳脏。亦名偏阳之体。生石膏一两先煎。酒炒知母三钱次入。鲜竹叶二钱。去米草。加陈胆星一钱。炖和服。九节蒲六分研次入。川贝母三钱。姜竹茹三钱。生冬瓜子四钱。黑栀皮三钱。鲜荷茎三钱。苦杏泥钱半。）", "13955": "何叟年近八旬。冬月伤风。有面赤气逆烦躁不安之象。孟英曰。此喻氏嘉言所谓伤风亦有戴阳证也。不可忽视。以东洋参细辛炙甘草熟附片白芍茯苓干姜五味胡桃肉细茶葱白一剂而瘳。孟英曰。此真阳素虚。痰饮内动。卫阳不固。风邪外入。有根蒂欲拔之虞。误投表散。一汗亡阳。故以真武四逆诸法回阳镇饮。攘外安内以为剂。不可施之阳实邪实之伤寒。（戴阳阳外阴内。外实内虚。面赤气逆。烦躁不安。孟英诊断戴阳。必脉重按无力。不嗜冷饮。高丽参三钱。北细辛八分次入。炒甘草三钱。熟附片五钱。炒白术三钱。酒炒白芍一钱五分。白茯苓干切三钱。炒干姜四钱。北五味杵先三钱。连衣胡桃肉五钱先煎。陈细茶一钱。连须鲜葱白三钱。去葱管次入。姜附分两重于参苓术草。则四君能动荡补阳。而无著滞不行之弊。细辛为药入下焦之引导。干姜合四君坐镇中枢。五味胡桃潜纳浮阳。胡桃滋润得阳中之阴。与病情有相悦以解之妙。白芍细茶反佐。葱白正治伤寒。）", "13956": "钟耀辉年逾花甲。在都患肿。起自肾囊。气逆便溏。诸治不效。孟英治之。切其脉微而弱。询其溺清且长。五苓八正肾气五皮遍尝之矣。孟英曰。此土虚不制水也。通利无功。滋阴亦谬。法宜补土胜湿。予大剂参术。果即向安。（土炒潞党五钱。土炒茅术五钱。酒炒白芍一钱五分。土炒西耆三钱。土炒甘草二钱。土炒干姜五钱。炒故纸杵五钱。熟附片五钱。北五味杵三钱。土炒陈木瓜三钱。肾为脾胃根键。大凡脾阳极败。如不挟风寒痰滞。非兼补肾阳不可木瓜不独入脾消肿合参草耆酸甘化阴。姜附虽多。绝无偏阳温燥流弊。）", "13957": "郑九经越医陈六顺诊治。服药后汗出昏狂。精流欲脱。孟英切其脉。既数且乱。沉取极细。曰此证颇危。生机仅存一线。亦斯人之阴分素亏。不可尽谓附桂之罪也。以元参知柏桑枝龙牡生地白芍甘草百合石斛栀子盐水炒淡豆豉为大剂灌之。下咽即安。次日去栀豉甘草。加龟板鳖甲盐水炒橘红。十余帖而康。（阴分素亏。何堪附桂劫阴。孟英立言忠厚。学医者不可自恕。元参片一两。大生地八钱。二味开水泡汤去渣。用汤煎药。炒知母一钱五分。炒川黄柏一钱。整白芍杵先煎一两。生桑枝四钱。生甘草三钱。百合须三钱。鲜石斛杵先煎一两。黑栀皮三钱。淡盐水炒豆豉一钱五分。二味同次入。煅龙骨杵一两。煅牡蛎八两。石斛三味炭先煨六句钟。取汤合前元参生地汤代水煮药。此证险在精流欲脱。龙牡涩精。急证急治。不得不用大剂。服法则分次徐灌。次日去栀豉甘草。则表解无汗可知。甘草非入下焦之品。故并去之。宜加血龟板二两。血鳖甲四两。以助龙牡而涩精止汗。煨时同前淡盐水炒橘红一钱。一派阴药中。不可无宣中降气之品以为反佐。）", "13958": "石符生抱病。亦为陈六顺治困。孟英诊焉。脉沉而涩滞模糊。不分至数。肢凉畏冷。涎沫上涌。二便涩少。神气不爽。曰。此途次感风湿之邪。失于解散。已从热化。加以温补。致气机愈形窒塞。邪热漫无出路。必致烁液成痰。逆行而上。但予舒展气机。则痰行热降。诸恙自瘳矣。以黄连黄芩枳实橘皮栀子淡豆豉桔梗杏仁贝母郁金通草紫菀竹茹芦菔汁等药。三服而起。调理匝旬遂愈。（脉为气道。痰热阻气。则气不能升降应指。故脉沉而涩滞模糊。不分至数。肢凉畏冷。胸中一团痰浊。清气反从四旁旋绕。气不流行则表虚。故肢凉畏冷。阳动阴静。热证病邪多上行。热邪煽痰逆升。故涎沫上涌。二便涩少。气不升则亦不降。痰热窒肺。肺气不行。故二便涩少。神气不爽。肺若华盖。下覆心脏。热邪窒肺。心处于被动地位。天君岂能泰然。故神气不爽。姜制雅连八分。姜制枯芩二钱。炒枳实一钱。黑栀皮一钱五分。淡豆豉次入三钱。苦桔梗次入一钱五分。薄橘红八分。川贝母杵三钱。苦杏泥一钱。姜竹茹三钱。此方服一帖。更方去栀豉。加方通草三钱。黄郁金八分。紫菀茸次入一钱。芦菔汁和服二钱。此方服两帖。）", "13959": "王某夏患感。谢树金治之。病虽退能食。但不能起坐。类乎瘫痪。延已月余。孟英视之。曰：此多服表散。汗出过分。气血两伤。肢骸失其营养。脉微而细。舌亮无胎。予大剂参耆归术熟地杜仲菟丝牛膝山药木瓜萸肉桑枝。数十帖而起。（血赖气生。表散过分。则气伤而血亦伤。不能起坐。气伤则气不能下行以滋培腰肾。血伤则血不能上行以衔接清阳。脉微而细。是脉细尤过于脉微。微阳弱。细阴弱。合之舌亮无胎。阴亏尤过于阳亏。潞党参五钱。生西耆四钱。净归身二钱。炒白术三钱。炒熟地八钱。绵杜仲三钱。菟丝饼四钱。制牛膝二钱。甘枸杞三钱。淮山药四钱。陈木瓜三钱。山萸肉三钱。肥玉竹三钱。川续断三钱。酒炒桑枝四钱。以参耆术补气以生血。以熟地菟丝枸杞补阴。以杜仲萸肉续断补阴中之阳。使阴能上行以交乎阳。以山药玉竹调和乎阴阳之间。以牛膝桑枝分别下行入络。）", "13960": "张养之妻饮食如常。而肌肤消瘦。汛事如期。而紫淡不恒。两腓发热。而别处仍和。面色青黄。而隐隐有黑气。俨似虚寒。多药不效。孟英诊之。脉似虚细。而沉分略形弦滑。曰：此阳明有余。少阴不足。仲景有急下存阴之法。然彼外感也。有余之邪可以直泻。此内伤也。无形之热宜以甘寒。义虽同而药则异。赠以西洋参生地生白芍生石膏知柏苓栀麦冬花粉楝实丹皮木通天冬诸品。服至数斤。黑气退而肌渐充。腓热去而经亦调矣。（饮食如常。气分无病。肌肤消瘦。血为热伤。则血不充肌华色。汛事如期。气能生血可知。紫淡不恒。血有伏热。血热贼气。气亦失常。气不充血则色淡。紫则郁热之象也。两腓为足阳明部位。两腓发热。胃热可知。面隐黑气。热郁甚则不能以自达。切脉以沉分为主。热邪阻滞气机。脉情反不能宣达于浮分。生石膏先煎八钱。西洋参三钱。酒炒知母二钱。黑栀皮三钱。赤苓皮三钱。南花粉三钱。花麦冬四钱。细木通一钱。数服后去石膏栀皮洋参花粉木通知母。加大生地八钱。明天冬切六钱。粉丹皮四钱。炒川黄柏一钱。生白芍三钱。川楝实杵先三钱。）", "13961": "姚氏妇产后昏谵汗厥。肌肤浮肿。医投补虚破血祛祟安神之药。皆不能治。孟英诊询恶露仍行。曰：此证医家必以为奇病。其实易愈也。昔金尚陶先生曾治一人与此相似。载于沈尧夫妇科辑要中。方用石菖蒲胆星旋覆茯苓橘红半夏曲。名蠲饮六神汤。凡产后恶露行而昏谵者多属痰饮。不可误投攻补。此汤最著神效。如方服之良愈。（昏谵汗厥。肌肤浮肿。病在气分。恶露仍行。血分无病。则昏谵为气分痰饮病可断。石菖蒲次入六分。陈胆星一钱炖和服。云苓干切三钱。赖氏橘红一钱五分。半夏曲杵四钱。）王炳华妻患舌疮。痛碍饮食。内治外敷皆不效。曰：此血虚火浮也。以产后发热例施之。用熟地当归酒炒白芍炙甘草茯苓炮姜投之。其病如失。（舌红脉数为阴虚。舌红润。脉空数。为阴中之阳亦虚。炒松熟地五钱。净归身三钱。炒甘草三钱。酒炒白芍一钱五分。白茯苓干切三钱。炮干姜八分。）", "13962": "一老人霍乱后。目闭呃忒。医谓脱陷在即。拟予桂附回阳未服。孟英询知溺赤口干。脉情耎数。改予肃清肺胃之剂。果得渐安。（目为肝窍。肝热逆冲则目闭。呃为动象。热伤肺气则呃忒。溺赤口干。为肺热津虚。脉情耎数。为阴虚中兼挟阳虚。黑栀皮三钱。酒炒知母一钱五分。酒炒川连六分。淡豆豉次入三钱。南花粉三钱。云茯苓三钱。苦杏泥一钱五分。姜竹茹三钱。鲜芦根八钱。）", "13963": "张鉴录年逾花甲。中秋夜猝仆于地。孟英脉之。弦滑而大。曰：痰气食相并而逆于上也。先以乌梅擦开牙关。横一竹箸于口。灌以淡盐姜汤。随入鹅翎探之。太息一声而苏。次予调气和中而愈。（暴病无虚。脉弦滑为痰食。脉大为气虚。淡盐淡字注意。盐多则沉降不行。）", "13964": "姚树庭古稀久泻。群医不效。孟英曰：弦象独见于右关。按之极弱。乃土虚木贼也。前方皆主温补升阳。理原不背。义则未尽。如姜附肉蔻骨脂之类。气热味辣。虽温脾脏。反助肝阳。肝愈强则脾愈受戕。且辛走气而性能通泄。与脱者收之之义大相刺谬。鹿茸升麻。可治气陷之泻。非斡旋枢机之品。至熟地味厚滋阴。更非土受木克。脾失健行之所宜。纵加砂仁酒炒。终不能革其腻滞之性。方方用之。无怪乎愈服愈泻。徒借景岳穷必及肾为口实也。予异功散加山药扁豆莲子乌梅木瓜芍药石脂余粮。服之果效。恪守百日。竟得康强。（右关脉主脾胃。切脉以沉分为主。土虚木贼。土虚则木贼之。偏重土虚。木贼则兼证也。潞党参五钱。炒白术四钱。白茯苓三钱。炒甘草三钱。炒焦蛀陈皮一钱。炒山药三钱。炒扁豆三钱。生建莲去心不去皮三钱。乌梅肉三钱。陈木瓜三钱。土炒白芍一钱五分。炒白蒺藜去刺六分。土炒赤石脂余粮各一钱。药和服。四君合山药扁豆莲子补土虚为正治。莲子留皮去敛涩。去心恐苦寒败土。无陈皮。则一派补土中无宣降之品。炒焦者恐其辛窜。乌梅木瓜白芍为兼证肝阳药。白芍减用恐微寒。蒺藜又为乌梅木瓜白芍反佐之品。石脂余粮和服。取其涩肠止泻。急则治标之义也。）", "13965": "倪怀周妻夏产数日。泄泻自汗。呕吐不纳。专科谓犯三禁。不敢肩任。孟英诊脉虚微欲绝。证极可虞。宜急补之。迟不及矣。用东洋参耆术龙牡酒炒白芍桑枝木瓜扁豆茯神橘皮紫石英黑大豆投之。四剂渐以向安。（辨阳虚在脉虚微欲绝。案中数日及专科不敢肩任两层不可忽。盖病期不久。幸未误药。此证阳虚微挟阴虚。于方中用龙牡黑大豆知之。高丽参五钱。炒西耆五钱。炒白术三钱。酒炒白芍一钱五分。酒炒桑枝三钱。陈木瓜四钱。炒扁豆三钱。云茯神三钱。赖氏橘红一钱五分。紫石英五钱。醋煅龙骨一钱。醋煅牡蛎三钱。三味同杵先。炒黑大豆杵三钱。参耆术茯正治阳虚。龙牡石英重镇。合木瓜白芍扁豆之敛涩。以止泄泻自汗呕吐。橘红宣中。桑枝通络。茯神坐镇中枢。黑大豆入阴止汗。）", "13966": "张养之侄女汛愆。饮食渐减。于某予通经药。服之尤恶谷。孟英诊之。脉缓滑。曰：此痰气凝滞。经隧不宣。病由安坐不劳。法应豁痰流气。勿投血药。经自流通。及服孟英药。果渐吐痰而病遂愈。（汛愆而饮食渐减。是病在气分。于某予通经药。服之尤恶谷。病在气分明矣。气病治血。宜乎不效。脉缓为阳虚。脉滑为痰郁生热。制半夏米五钱。赖橘红一钱五分。旋覆花绢包一钱五分。九节蒲研次入一钱。陈胆星炖和服七分。焦麦芽四钱。炒枳实一钱。紫菀茸一钱。）", "13967": "毛允之戌年冬患感。初治以温散。继治以滋阴。延至次春。病日以剧。凤山僧补以升柴耆术。丁卯桥下以轻粉巴霜。杂药遍投。形神日瘁。孟英视之。脉来涩数上溢。呃忒口腻。虽觉嗜饮。而水难下咽。频吐涎沫。便秘溺赤。潮热往来。少腹如烙。按之亦不坚满。此病原属冬温。治以表散。则津液伤而热乃炽。继以滋填。热邪愈锢。再施温补。气机更窒。升柴耆术。欲升其清。而反助其逆。巴霜轻粉。欲降其浊。而尽劫其阴。病及三月。发热不是表邪。便秘旬余。结涩非关积滞。且脉涩为津液之已伤。数是热邪之留著。溢乃气机为热邪所壅而不得下行。岂非温邪未去。得补而胶固难除。徒使其内烁真阴。上熏清道。以致一身之气。尽失肃清之令。法当搜剔余邪。使热去津存。即是培元之道。伸其治节。得浊气下趋。乃为宣达之机。以北沙参麦冬知母花粉兰草石斛丹皮黄芩桑叶栀子黄连木通银花橘皮竹茹芦根橄榄枇杷叶地栗海䖳等出入为方。服之各恙递减。糜粥渐加。半月后始得大解。而腹热全消。谷食亦安。乃予滋阴善后而痊。（论证略尽原案。脉来涩数上溢九句。合言之皆热邪窒肺之象。析言之。虽觉嗜饮。水难下咽。热邪煽痰逆升阻气。气不降则水不入。少腹如烙。按之亦不坚满。则热邪不在血分可知。北沙参四钱。姜制黄连八分。姜制枯芩二钱。黑栀皮三钱。姜制竹茹三钱。活水芦根一两。细木通一钱。赖橘红次入一钱五分。姜枇叶刷包三钱。更方去沙参栀皮竹茹枇叶。加南花粉四钱。鲜石斛杵先一两。建兰叶次入三钱。再更方去连芩花粉兰叶。加花麦冬三钱。酒炒知母三钱。粉丹皮三钱。冬桑叶三钱。济银花八钱次入。鲜青果连核杵先两个。地栗泡淡海䖳各一两。每五日易一方。）", "13968": "翁嘉润患腰疽。愈而复发者五年。孟英切其脉。弦细以数。曰：此内损证。外科乌乎知。予大剂甘润滋填之药。匝月而痊。后不复发。（脉弦细数为阴虚。大熟地八钱。明天冬切六钱。女贞子杵五钱。酒炒桑枝三钱。山萸肉三钱。枸杞子三钱。净归身二钱。济银花五钱。菟丝饼四钱。龟板胶炖和服二钱。）", "13969": "某母秋初猝仆于地。孟英诊之。脉浮弦以滑。用羚角胆星牡蛎石菖蒲丹参茯苓钩藤桑叶贝母橘红蒺藜等。以顺气蠲痰息风降火而痊。（羚角磨冲二钱。陈胆星炖和服一钱五分。石菖蒲次入一钱。紫丹参四钱。白茯苓三钱。钩藤钩次入五钱。冬桑叶四钱。川贝母杵一两。赖橘红次入一钱五分。白蒺藜三钱。煅牡蛎八两杵。炭先煨六句钟。取汤代水煎药。此证以息风降火为主治。顺气蠲痰为辅佐。）嗣其人至某年春前数日。忽欠伸而厥。孟英切脉微弱而弦曰。病虽与前相似。而证则异矣。以高丽参白术何首乌山茱萸枸杞桑椹石斛牛膝蒺藜橘红等镇补摄纳以瘳。（脉微弱固为阳虚。弦亦虚脉。既厥则肝阳亦旺。高丽参五钱。炒白术三钱。制首乌四钱。山萸肉三钱。甘枸杞二钱。干桑葚四钱。钗石斛八钱。制牛膝四钱。白蒺藜三钱。赖橘红一钱五分。煅牡蛎六两杵。炭先煨六句钟。取汤代水煎药。参术针对脉微弱。补其气分阳虚。杞子桑葚石斛顾阴敛肝。首乌山萸。补其阴中之阳。乃能使阴中一线之阳上升。牛膝引药下行。蒺藜反佐舒肝。牡蛎镇怯潜阳。橘红反佐全方以行使。）", "13970": "张养之病延七载。经百十三医之手不愈。体怯面青。易招外感。夏月亦著复衣。频吐白沫。阳痿多年。常服温辛之药。九月患恶寒头痛。自饵温散不效。孟英诊之。脉极沉。重按至骨。则弦滑隐然。卧曲房密帐之中。炉火重裘不足御寒。且涎沫仍吐。毫不作渴。胸腹无胀闷之苦。咳嗽无暂辍之时。惟大解坚燥。小溲不多。口气极重耳。此积热深锢。气机郁而不达。非大苦寒以泻之不可。二三帖后病不略减。（中略）连服苦寒。病无增减。不比平淡之剂。误投数帖。尚不见害。实由热伏深锢。药未及病。今日再重用硝黄犀角。冀顽邪蕴毒。得以通泄下行。则周身之气机自然流布矣。如法服之。越二日大便下如胶漆。臭达户外。畏寒递减。糜粥日增。旬日后粪色始正。（热伤肺。气不流行则恶寒。头痛为肝阳。若感寒则温散已效。脉极沉。已见胃腑积滞。重按至骨则弦滑隐然。更见痰热遏伏。炉火不足御寒。热深厥亦深也。涎沫仍吐。毫不作渴。痰虽热有滑润性质。故不作渴。胸腹无胀闷。病不在气分。咳嗽无暂辍。则胃热逆冲于肺。大解坚燥为热结固已。热证溲多则愈。溲竭则死。口气重为肺胃之热逆冲。镑犀角磨冲六分。元明粉一钱。生大黄三钱。二味开水同泡冲。炒枳实一钱。元参片五钱。黑栀皮三钱。苦桔梗次下三钱。赖氏橘红一钱。姜竹茹三钱。白茅根三钱。丝瓜络三钱。石菖蒲一钱。陈胆星一钱炖和服。更方去桔梗竹茹茅根栀皮丝瓜络。加镑犀角磨冲一钱。元明粉二钱。生大黄五钱。开水同泡冲。炒枳实二钱。制根朴一钱。赖橘红一钱五分。川贝母杵一两。石菖蒲次入一钱。陈胆星二钱炖和服。）", "13971": "石符生患疟。医以小柴胡汤加姜桂投之。不效。即用四兽休疟等法。反致恶寒日甚。谷食不进。惟饮烧酒姜汤。围火榻前。胸腹痞闷。喜以热熨。犹觉冷气上冲。频吐黏稠痰沫。延至腊初。疲惫不堪。孟英诊之。脉沉而滑数。苔色黄腻不渴。便溏溺赤。曰：是途次所受之暑湿。失于清解。复以温补之品从而附益之。酿成痰饮。盘踞三焦。气机为之阻塞。所以喜得热熨热饮。气冲反觉如冰。（中略）以脉情兼证并究。其为真热假寒。昭昭若揭。予大剂苦寒之药。以芦菔汤煎。渐服渐不畏寒。痰渐少。谷渐增。继用甘凉善后。（疟分寒热虚实。此证本非寒疟虚疟。小柴非。四兽亦非。论证尽于原案。便溏忌用硝黄。姜制黄连八分。姜炒枯芩三钱。赖橘红一钱。净橘络七分。石菖蒲六分。炒枳实一钱五分。川贝母八钱。贫者以生冬瓜子八钱代之。生莱菔子研和服一钱。陈胆星炖和服一钱。姜竹茹三钱，丝瓜络三钱，鲜芦菔一两。煎汤代水。）", "13972": "王某久患吐血。体极孱弱。孟英治之小愈。酷暑患霍乱转筋。大汗如雨。一息如丝。孟英视曰。阴血久夺。暑热鸱张。吾霍乱论中缺典也。姑变法救之。用北沙参枇叶龙牡木瓜扁豆苡仁西滑石桑叶蚕砂石斛豆卷投之良愈。嗣后每日调理。仍服滋补以治宿恙。（此证危险在大汗如雨。汗为阴液。汗多则阴伤。汗止则阴复。阴复则转筋止。脉息起。阴血久夺句本病重。暑热鸱张句标病轻。北沙参四钱。生龙骨杵二两。煅牡蛎杵八两。二味炭先煨六句钟取汤煎药。鲜枇叶刷包三钱。陈木瓜三钱。生扁豆杵三钱。生苡仁杵八钱。西滑石四钱包先。冬桑叶四钱。晚蚕砂五钱。钗石斛杵先一两。大豆卷次入三钱。龙牡重镇止汗为君。沙参石斛顾阴止汗为臣。木瓜扁豆酸涩止汗。苡仁滑石蚕砂清肝泻暑。使以枇叶桑叶轻浮止汗。豆卷反佐清余热。豆卷在热霍乱证本禁药。入大剂重镇清肝药中。反能上清浮热。）", "13973": "李氏女素禀怯弱。春间汛事不行。胁腹聚气如瘕。减餐肌削屡服温通之药。至孟秋加以微寒壮热。医仍作经闭治。势濒于危。孟英切脉时。壮热烙指。汗出如雨。汗珠落脉枕上。微有粉红色。曰：虚损是其本也。今暑热炽盛。先当治其客邪。书白虎汤加西洋参元参竹叶荷杆桑叶。服二帖。热果退。汗渐收。改用甘凉清余热。日以向安。继予调气养营阴。宿瘕亦消。培补至仲冬。汛至而痊。（汛事不行。胁腹聚气如瘕。是血病及气。至减餐肌削。屡服温通。微寒壮热。则血病及气。由气分而外达皮毛。先治客邪。急则治标之义。生石膏一两六钱先煎。酒炒知母次入三钱。去草米。加西洋参三钱。元参片五钱开水泡冲去渣。鲜竹叶次入三钱。鲜荷杆二尺。冬桑叶四钱。二帖后改用甘凉清余热。方用蜜炙枇叶刷包三钱。生甘草三钱。鲜竹叶二钱。鲜茅根四钱。活水芦根二两。生苡仁八钱。鲜敛斛杵先一两。连皮梨切一两。继予调气养营阴。方用鲜竹茹三钱。苦杏仁二钱。薄橘红一钱五分。紫菀茸一钱。旋覆花绢包一钱五分。连节藕切先二两。蒲桃干三钱。鲜茅根三钱。箱归身二钱。大生地八钱。女贞杵先四钱。）", "13974": "张氏妇患气机不舒。似喘非喘。似逆非逆。似太息非太息。似虚促非虚促。似短非短。似闷非闷。面赤眩晕。不肌不卧。补虚清火行气消痰服之不应。孟英诊之。曰：小恙耳。旬日可安。但须惩忿是嘱。予黄连黄芩栀子楝实鳖甲羚角旋覆赭石海䖳地栗为大剂。送当归龙荟丸。未及十日汛至。其色如墨。其病已若失。后予养血和肝调理而康。（气机不舒以下十一句。皆病不在气分之象。孟英诊曰小恙者。脉病人不病则病重。人病脉不病则病轻。此证必肝脉沉实数有力。能受苦甘寒大剂。故曰小恙。属惩忿。人忿则全身气血颠倒。最易伤肝。肝郁热亦易忿怒。酒炒川连八分。酒炒枯芩一钱五分。黑栀皮三钱。川楝实杵先三钱。血鳖甲杵四两。生赭石一两杵。二味同先炭煨六句钟。取汤代水煎药。羚角磨冲一钱。旋覆绢包三钱。荸荠八钱。泡淡陈海䖳二两。药送当归龙荟丸二钱。此证血分中肝有实热。肝阴虚。肝阳浮。养血和肝方。大生地八钱。连皮藕二两切先。箱归身二钱。蒲桃干三钱。干桑叶四钱。陈木瓜三钱。酒炒桑枝次入三钱。生白蒺去刺次入三钱。血鳖甲杵先四两。夜交藤三钱。生甘草三钱。）", "13975": "王炳华室夏患臂痛。孙某曰。风也。服参耆归芍数帖。臂稍愈而脘痛。孙曰。寒也。加以附桂。痛不止而渐觉痰多。孙曰：肝肾不足也。重用熟地枸杞。令其多服取效。不料愈服愈剧。渐至昏厥。孙尚谓体虚药轻。前方加重。时时发厥。孟英诊之。脉沉而有弦滑且数之象。此由过投温补。引动肝风。煽其津液为痰。痰复乘风而上。此晕厥之所由来也。余波则奔流经络。四肢因而抽搐。阳气尽逆于上。宜乎。鼻塞面浮。浊气不能下达。是以便滞不饥。予大剂甘寒息风化饮。佐以凉苦泄热清肝。厥果渐止。各恙递蠲。两月后康复如常。（此证臂痛。本系阳虚挟痰。孙某过投温补。引动肝风。痰乘风上。脉沉为痰浊遏伏。脉弦滑为痰乘风上。脉数为温补。以致阴虚挟热。方义以息风化饮为主治。尤重息风。风不息则饮不能化。姜竹沥三两。和服花粉五钱。荸荠二两。泡淡海䖳一两。鲜敛斛一两杵先。冬桑叶四钱。川楝实三钱。炒川黄柏一钱五分。胆星一钱炖和服。石菖蒲次入一钱。生白蒺去刺三钱。生赭石一两，青果四钱杵。煅牡蛎六两。石斛赭石楝实青果牡蛎五味。先炭煨六句钟。取汤代水煎药。）庄半霞闱后患感。日作寒热七八次。神气昏迷。微斑隐隐。孟英视之。曰：此平昔饮酒。积热深蕴。挟感而发。理从清解。必误投温补。以致热势披猖若是。询之果三场皆服参。且携枣子浸烧酒入闱。初病尚不至此。因连服羌防姜桂。渐以滋甚孟英先予白虎汤三剂。斑化而寒热渐已。（日作寒热七八次三句。此外感之邪欲外达。温补锢邪。邪欲达而不能径达。生石膏先煎八钱。酒炒知母三钱。去米草。加黑栀皮三钱。淡豆豉次入三钱。炒枳实一钱。姜竹茹三钱。陈胆星炖和服八分。石菖蒲次入六分。赖橘红八分。姜川连六分。）继用大苦寒之药泻其结热。所下黑矢皆作枣子气。（生厢黄三钱。开水泡冲去渣。炒枳实二钱。生冬瓜子四钱。晚蚕砂五钱。制根朴一钱。鲜莱菔一两先煎。药送滚痰丸三钱。）旬日后予甘润滋濡之法。两月始得全愈。（南花粉四钱。花麦冬三钱。蜜炙桑皮三钱。甜杏仁三钱。蜜炙枇叶刷包三钱。大荸荠打三个，泡淡海䖳八钱。青蔗浆一酒杯和服。生粉草三钱。）", "13976": "壬寅夏感受暑湿。误投温散。以致谵语神昏。势濒于危。肛前囊后溃出腥脓。疮口深大。疡科以为悬痈。敷治罔效。孟英诊曰。悬痈乃损怯证。成之以渐。今病来迅速。腥秽异常。是身中久蕴厚味湿热之毒。挟外受之暑邪无所宣泄。下注而为此证。切勿敷药。以遏其外走之热。但舌强而紫赤。脉细而滑数。客邪炽盛。伏热蕴隆。阴分甚亏。深虞津涸。先予清营之剂。三投而神气渐清。（一人之身。前患湿热挟实。此患暑邪挟虚。编次具有苦心。温散伤阴。故云阴分甚亏。常法治病先治气。后治血。此主清营。系变法医药之义。元参片一两。大生地八钱。二味开水泡汤去渣冲入。酒炒川连六分。莲子心一钱。陈胆星炖和服八分。九节蒲研次入一钱。生冬瓜子四钱。鲜茅根五钱。鲜荷杆三钱。竹叶卷心十个。木通一钱。）次以凉润阳明。便畅而热蠲脓净。（清营系急则治标。心肺热邪。必由胃腑宣泄。故主凉润阳明。方用生石膏八钱。酒炒知母三钱。南花粉四钱。姜竹沥两酒杯冲大荸荠三个打。花麦冬三钱。钗石斛杵先八钱。鲜枇叶刷包三钱。生苡仁杵八钱。竹叶二钱。）改用甘柔滋养。月余溃处肌平。善后参入参耆。竟得康强如昔。（甘柔滋养方。大生地八钱。生甘草三钱。白茯苓三钱。肥玉竹三钱。甜杏仁三钱。箱归身二钱。酒桑枝三钱。木瓜三钱。）", "13977": "张春桥素禀不坚。头眩脑鸣。频服温补药。甚觉畏冷。辛丑春延孟英诊之。脉甚数。曰：阴亏也。温补非宜。改服滋水培元之剂。颇为有效。夏间或劝以灸火云可以除百病。盖未知灼艾之可以除百病者。谓可除寒湿凝滞。阳气不能宣通之证。非谓内伤外感。一切之病皆可灸以除之也。故仲景有微数之脉慎不可灸之训。正以艾火大能伤阴也。灸后数日即寒少热多。宛如疟疾。医者以为脾寒病。投以温散。日以滋甚。孟英切其脉滑数倍加。曰：阴虚之体。热自内生。灸之以艾。火气内攻。时当溽暑。天热外烁。三者相交。阴何以堪。再投温散。如火益热。当从瘅疟治。专以甘寒息热。则阴津不致枯涸。而寒热不攻自去。所谓治病必求其本也。竟不用一分表散药而治愈。（头眩脑鸣。阴本不足。温补畏冷。热深厥亦深也。脉滑为痰。数为阴虚挟热。生石膏一两六钱包先。酒炒知母次入三钱。南花粉四钱。姜竹沥两大酒杯冲服。活水芦根二两。鲜枇叶刷包三钱。生北梨三两。青甘蔗一两。皆不去皮。同榨汁冲。）", "13978": "陈芝田仲夏患感。诸医投以温散。延至旬日。神昏谵妄。肢搐耳聋。舌黑唇焦。囊缩溺滴。胸口隐隐微斑。孟英诊之。脉细数而促曰：阴亏热炽。液将涸矣。用西洋参元参生地二冬知柏楝实石斛白芍甘草梢银花木通犀角石菖蒲大剂投之。（此证可救。在溺滴胸口隐隐微斑脉细数以促三句。肝阴绝则溺绝。胸口隐隐微斑。邪旺正亦旺。病邪尚能外达。脉细数而促。固属热极风生。然系阳证阳脉。能任阴药。若脉耎弱则不治。元参片一两。大生地八钱。明天冬六钱切。花麦冬五钱。四味开水泡汤去渣用汤煎药。西洋参四钱。酒炒知母三钱。酒炒川柏一钱五分。酒炒楝皮去核二钱。钗石斛一两杵先。整白芍杵先二两。生草梢三钱。济银花一两五钱。细木通一钱。镑犀角片磨冲一钱。石菖蒲次入一钱。）次日其家人云。七八日来小溲不过涓滴。昨服药后约六七个时辰解得小溲半杯。孟英曰：此即转机也。然阴气枯竭。甘凉濡润不厌其多。于前方再加龟板鳖甲百合须花粉大锅煎之。频灌勿歇。如是者八日。神气始清。诸恙悉退。纯用滋阴之药。调理匝月而瘳。孟英尝云。温热液涸神昏。有投犀角地黄等药至十余剂。始得神清液复者。（药随气为升降。气不降则药亦不降。此证孟英如接诊即用龟板鳖甲则不效。盖气火尚浮而上逆也。至添解小溲半杯。则阴津有濡润将复之机。故介属加入能收效。但少用则药不胜病。宜用血龟板四两。血鳖甲四两同杵。先炭煨八句钟。百合须四钱。南花粉五钱。频灌则药力不断。）", "13979": "江小香病热危笃。孟英诊之。脉虚弦而小数。头痛偏于左后。子夜热躁。肢冷欲呕。口干不欲饮。不饥不欲食。舌謇言涩。溺黄而频曰：体属素虚。此由患感时过投温散。阴津阳气皆伤。后来进补而势反剧者。滋腻妨其中运。刚烈动其内风。以致医者佥云表之不应补亦无功竟成无药可治之证。虽然。不过难治耳。未可遽弃也。予秋石水拌制高丽参苁蓉首乌生白芍牡蛎楝实盐水炒橘红桑葚石斛蒺藜茯苓药吞饭丸肉桂心五分。一剂躁平呕止。各恙皆减。连投数服。粥食渐安。（叙证惟肢冷及口干不欲饮不饥不欲食暨溺频属阳虚。余皆阴虚挟热之象。秋石水拌制丽参三钱。淡苁蓉三钱。制首乌三钱生白芍四钱。煅牡蛎一两杵。先煨六句钟。川楝实三钱杵先。盐水炒蛀陈皮一钱。干桑葚三钱。鲜石斛杵先八钱。生白蒺去刺次入三钱。白茯苓三钱。药送饭丸肉桂心五分。此杂证杂治之法。须玩其从阳引阴，从阴引阳。机轴灵动。此证阴虚重于阳虚。）乃去首乌桂楝。加砂仁末拌炒熟地菊花枸杞。半月而瘳。（砂仁末二分。炒松熟地四钱去砂仁。杭菊花二钱。甘枸杞三钱。）", "13980": "溽暑之令。瘄疹盛行。幼科仅知套药。升柴防葛乱施。陈书芾女势最剧。以瘄甫出而汛适至也。医者却走。孟英视之。脉滑而数，舌绛大渴。面赤音失。不食便泻。曰：此由发散太过。火盛风炽。气血两燔。气分之邪由泻而略泄其焰。营分之热由汛而稍解其焚。岂可畏其脱陷。妄投止涩耶。予西洋参石膏知母麦冬犀角生地连翘甘草石斛丹皮桑叶竹叶大剂投之。三日而愈。养阴善后。遂以渐安。其余或轻或重。孟英一以清解而痊。（脉滑而数。热邪皆在气分。惟舌绛二字。热邪在血分。病邪以有出路为宜。泻泄其热。汛解其焚。正是此病生机。畏脱陷。投止涩。系治虚证之法。此病系热实证。脉滑而数。数脉热中挟虚。故方中以麦冬生地等补之。病情气分热邪过于血分。故此方清气之药较多。西洋参三钱。生石膏先煎一两二钱。酒炒知母次入三钱。花麦冬四钱。镑犀角磨冲一钱。大生地开水泡冲八钱。连翘壳次入三钱。生粉草三钱。粉丹皮二钱。鲜石斛杵先一两。冬桑叶四钱。鲜竹叶次入二钱。）", "13981": "石诵羲夏杪患感。多医广药。病势日增。延逾一月。孟英诊焉。脉至右寸关滑数上溢。左手弦数。耳聋口苦。热甚于夜。胸次迷闷。频吐黏沫。啜饮咽喉阻塞。便溏溺赤。间有谵语。曰：此暑热始终在肺。并不传经。一剂白虎汤可愈。何以久延。前方惟初诊顾听泉用清解肺卫法为不谬。余则温散升提。滋阴凉血。皆不中病。病家因溏泄畏服石膏。告孟英以胸中一团冷气。汤水皆须热呷。孟英答以邪在肺经。清肃之令不行。津液凝滞。结成涎沫。盘踞胸中。升降之机亦窒。大气仅能旁趋而转旋。是一团涎沫之中。为气机所不能流行之地。其觉冷也固宜。且予初诊时。即断为不传经之候。所以尚有今日。能自觉胸中之冷。若传入心包。舌黑神昏。则合古年之犀角地黄汤。然虽不传经。延已逾月。热愈久。液愈涸。药愈乱。病愈深。宜急投白虎。古云鼻塞治心。耳聋治肺。是皆白虎之专司。不可拘少阳而疑虚寒。书方以白虎加西洋参贝母花粉黄芩紫菀杏仁冬瓜仁枇叶竹茹竹黄。一剂甫投。咽喉即利。三服各恙皆去。糜粥渐安。改甘润生津调理而愈。（右寸关滑数上溢九句。热邪多在气分。惟左手脉弦数稍挟阴虚。但右不降则左升。法宜治肺。病邪此脏传彼脏名传经。热证右脉无力。便溏则肺阳已败。忌服柔剂及石膏。热证右脉有力。则便溏为热邪出路。宜服阴剂及石膏。右寸关滑数上溢。则右脉有力可知。故不忌白虎。左脉弦数。虽挟阴虚。惟清肺则肺阴能生肝阴。且洋参花粉等一派清润。肃肺即以补肝。斯为一笔两用。一丝不漏。生石膏八钱先煎。西洋参三钱。川贝母杵三钱。酒炒知母一钱。南花粉三钱。酒炒枯芩二钱。杏仁泥一钱五分。紫菀茸一钱。生冬瓜子三钱。姜枇叶刷包三钱。鲜竹叶二钱。姜竹茹三钱。天竺黄三钱。甘润生津方。生甘草三钱。花麦冬三钱。花粉四钱。北沙参四钱。甜杏仁三钱。蜜枇叶刷包三钱。鲜地骨皮四钱。清阿胶炖和二钱。活水芦根八钱。）", "13982": "刘廉方受暑。医治垂危。孟英诊之。裸卧昏狂。舌黑大渴。溺赤便秘。脉数而芤。予犀角地黄汤加减。服之神识已清。略能进粥。颇知问答。大有生机。仍处甘凉以赠之。嗣误热药致死。（此证可生在大渴。大渴则肺阳尚旺。病情全系热邪由气传营之象。脉数而芤。芤为虚。此证阴虚重于热实。磨犀角冲一钱。大生地八钱。元参片一两。二味开水泡汤。去渣用汤煎药。酒炒知母三钱。明天冬六钱。鲜地骨皮五钱。鲜石斛杵先一两。鲜茅根五钱。枯青果连核杵先三个。云茯神三钱。龟板胶二钱炖和服。济银花次入八钱。神识已清。颇知问答。则营热已解。亟宜清其气分之热。故处甘凉以赠之。方用生石膏先煎八钱。酒炒知母三钱。北沙参八钱。花麦冬四钱。蜜炙枇叶刷包三钱。生粉草三钱。南花粉四钱。鲜地骨皮五钱。蜜水拌鲜芦根一两。甜杏仁三钱冬桑叶三钱。青果连核杵先三个。）", "13983": "孙楚楼途次患寒热如疟。胁痛痰嗽。面黧形瘦。医投疏散。甚不相安。孟英诊断阴亏。忌从疟治。以苇茎汤加北沙参熟地桑叶丹皮海石旋覆贝母枇叶为剂。方义主肃肺润燥。滋肾清肝。数服而痊。（孟英诊断阴亏。必有脉情。疟分正疟时疟。正疟属寒挟实。时疟属热挟虚。疏散甚不相安。其为阴亏何疑。胁痛痰嗽。为虚中挟实。鲜芦根二两。生冬瓜子四钱。生苡仁杵八钱。生桃仁杵三钱。北沙参四钱。大熟地泡煎去渣八钱。冬桑叶三钱。粉丹皮二钱。海浮石先煎五钱。旋覆花绢包三钱。川贝母杵五钱。姜炙枇叶刷包三钱。）", "13984": "一人患晨泄有年。累治不效。春间尤甚孟英按脉曰。汝虽苦泻。而泻后腹中反觉舒畅。其人对曰诚然。苟不泄泻。又胀闷减食矣。服四神附桂之药。其泻必加何故。曰：此非温升补涩之证。乃肝强脾弱。木土相凌。处一方令其常服。数帖即安。后竟无恙。方用白术苡仁黄连楝实桑枝茯苓木瓜芍药蒺藜橘皮而已。（春间尤甚。已露肝强。泻后腹中反觉舒畅者。肝强贼脾。得泄泻稍解其郁抑之苦。服四神附桂反加者。温热助肝贼脾。肝强脾弱。两脏俱病。惟肝强较重。炒白术三钱。炒苡仁杵八钱。酒炒川连八分。川楝实杵先四钱。鲜桑枝三钱。白茯苓四钱。陈木瓜三钱。整白芍杵先二两。生白蒺去刺三钱。蛀陈皮一钱五分。）", "13985": "邵鱼竹孙久患痰多。胸膈满闷。连年发痫。药之罔效。孟英脉之。曰：气分偏虚。痰饮阻其清阳之旋运。宜法天之健以为方。则大气自强。而流行不息。胸次乃廓然如太空矣。予六君去甘草。加黄耆桑枝薤白蒌仁石菖蒲蒺藜旋覆服之。满闷渐舒。痫亦不发。（此证气先虚而痰饮中之。一味治痰。则气愈虚。故以补气治本。豁痰治标。以桑枝蒌仁白蒺柔肝舒肝。治兼证之痫。潞党参五钱。炒白术三钱。白茯苓三钱。炒黄耆三钱。制半夏八钱。蛀陈皮一钱五分。姜汁炒桑枝二钱。姜汁拌炒蒌仁一钱。九节蒲研次入三钱。西薤白打次入三钱。生白蒺去刺三钱次入。旋覆花绢包一钱。）", "13986": "周热妻娩后恶露不行。或劝服生化汤。孟英诊曰。阴虚内热。天令炎蒸。虽赤沙糖不可服也。以生地丹参丹皮豆卷茺蔚子茯苓桃仁山楂栀子泽兰琥珀投之即效。并曰：生化汤体寒固妙。若血热或兼感温热者概投之。骤则变证蜂起。缓则蓐损渐成。（阴虚内热。必另有脉象病情可据。非但以天令炎蒸。遂制此方。大生地八钱。丹参三钱。丹皮二钱。大豆卷次入一钱五分。白茯苓人乳拌蒸三钱。生桃仁研三钱。茺蔚子杵先四钱。焦楂肉杵一钱五分。黑栀皮三钱。泽兰叶一钱五分。琥珀研冲八分。）", "13987": "戚媪年六十余。秋患霍乱转筋。孟英视之。暑也。投自制蚕矢汤两服而安。三日后忽倦卧不能反侧。气少不能语言。不饮不食。孟英切脉曰：此高年之体。元气随泻而泄。固当补者。第余暑未清。热药在所禁耳。以丽参麦冬知母玉竹木瓜扁豆石斛白芍苡仁茯苓蒺藜为方。服六剂始能言动。渐进饮食。调理月余而健。（蚕矢汤前后另案均见。元气随泻而泄。此霍乱治迟之故。高丽参切三钱。整麦冬三钱。酒炒知母二钱。肥玉竹三钱。陈木瓜三钱。生扁豆杵三钱。鲜石斛杵先四钱。生苡仁杵四钱。白茯苓三钱。生白蒺去刺三钱。）", "13988": "周热七月夜患霍乱转筋甚剧。仓猝间误服青麟丸钱许。孟英晓诊脉微弱如无。耳聋目陷。汗出肢冷。音哑肌削。药恐迟滞。先浓煎高丽参汤。急为接续。随以参术白芍茯苓附桂干姜木瓜苡仁扁豆莲实为方。一剂而各证皆减。（辨阳虚在脉微弱如无。音哑肌削。先浓煎丽参一两。分次服以接续微阳。方用丽参五钱。炒白术三钱。酒炒焦白芍一钱五分。白茯苓干切三钱。炒熟附片五钱。肉桂心二钱。炒干姜三钱。陈木瓜三钱。炒苡仁三钱。炒白扁豆三钱。炒莲肉去心不去皮三钱。重用附桂干姜。方能鼓舞一派补药。）次日复诊。孟英曰：气分偏虚。那堪吐泻之泄夺。误饵苦寒。微阳欲绝。昨予真武理中合法。脾肾之阳复辟矣。刚猛之品可以撤去。盖吐泻甚而津液伤。筋失其养则为之转。薛生白比之痉病例可推也。凡治转筋。最要顾其津液若阳既回而再投刚烈。则津液不能复而内风动矣。此治寒霍乱之用附桂亦贵有权衡。不可漫无节制致堕前功也。即于前方裁去姜附肉桂。加黄耆石斛。服至旬日而愈。（前方加生黄耆五钱。钗石斛杵先五钱。）", "13989": "顾云坨体丰年迈。患疟于秋。脉芤而稍有歇止。孟英曰：芤者暑也。歇止者。痰湿阻气机之流行也。大忌温补助邪。及予清解蠲痰之法。病不少减。而大便带血。孟英曰。暑湿无形之气。平素多痰。邪反得以盘踞。颇似有形之病。清解不克胜其任。气血皆受其滋扰。必攻去其痰。使邪无依附而病自去。切勿以高年而畏峻药。遂以桃仁承气汤加西洋参滑石芩连橘红贝母石斛为方。送礞石滚痰丸。径服二剂。下黏痰污血甚多。疟即不作。仍以清润法善后而康。（勘病制方。本参脉证。年迈而体丰。则必其人阳气尚充。且便血有倦否之分。倦者阳虚。不倦阳实。脉芤而稍有歇止句。重稍有歇止。痰阻气则脉有歇止。去痰则脉无歇止。即无所谓芤。非单纯芤脉。妄用桃仁承气方义也。生厢黄三钱。开水泡冲去渣。生桃仁研三钱。西洋参三钱。西滑石四钱。姜炒枯芩一钱。姜炒川连六分。赖橘红一钱。川贝母杵三钱。钗石斛杵先五钱。药送礞石滚痰丸三钱。）", "13990": "邵子受妻患吐血。肌肤枯涩。口渴脉虚大。孟英曰。气分之阴亏也。温补既非。滋填亦谬。以参耆二冬知母百合玉竹石斛桑叶枇叶投之而愈。（吐血分虚实两大门。此为虚证。辨气分阴亏。在肌肤枯涩口渴脉虚大。温补固与病情相反。滋填则系应补肺阴。误补肾阴。潞党参五钱。生黄耆五钱。花麦冬四钱。明天冬切三钱。酒炒知母一钱五分。百合须三钱。肥玉竹三钱。钗石斛八钱。冬桑叶四钱。蜜炙枇叶刷包三钱。）", "13991": "张春桥九月患疟。寒少热多。间二日而作。甫两发。形即清瘦。孟英诊曰。脉弦而细。尺中甚数。疾作于子夜。口干嗜饮。乃足少阴热疟也。两发遽尔形消。胡可玩视。方用元参生地知母丹皮地骨皮天冬龟板茯苓石斛桑叶。（辨肾经热疟。固在疾作子夜。口干嗜饮。尤在尺中甚数。切脉万勿心粗气浮。炒元参八钱。炒大生地五钱。酒炒知母三钱。丹皮二钱。地骨皮四钱。明天冬切六钱。血龟板杵先三两。白茯苓三钱。钗石斛八钱。冬桑叶四钱。）", "13992": "邵秋子母年近六旬。春患寒热如疟。诸医杂治罔效。孟英视之。曰：此湿邪久蕴。已从热化。误投升补。动其肝阳。痰饮因而上逆。予通降之法。寒热即减病家误进首乌鳖甲等药。渐至脉伏胸痞。呃忒自汗。渴饮不食。颧赤便泄。孟英再诊曰。此滋腻阻塞气机。清阳不司旋运。痰饮闭滞隧络。非脱象也。补药不可进。以栝蒌薤白合小陷胸加菖蒲竹茹旋覆贝母杏仁紫菀枇叶投之。呃止脉出。大有转机。（脉伏胸痞四句。皆邪实热浮之象。病在气分。姜汁拌蒌仁四钱。鲜薤白打一钱五分。姜炒川连八分。半夏曲一钱五分。石菖蒲次入六分。姜竹茹三钱。旋覆花绢包一钱五分。川贝母杵三钱。苦杏仁一钱五分。紫菀茸一钱。姜汁炒枇叶刷包三钱。）病家又误姜桂频投。既而唇肿咽疼。不能进饮。舌干短硬。难出语言。复请孟英救疗。予犀角地黄汤加玄参知母银花竹黄花粉胆星石菖蒲竹沥之类。六七剂吐出极臭胶痰甚多。粥饮渐进。（唇肿咽疼四句。温燥大伤气分之阴。不能进饮。为痰升风上。壅塞清道。大生地一两。玄参片一两。二味开水泡冲去渣。酒炒知母三钱。济银花八钱。天竹黄三钱。南花粉四钱。陈胆星炖和服八分石菖蒲次入一钱。姜竹沥二两冲。）", "13993": "段春木妻烂喉。内外科治之束手。孟英视之。骨瘦如柴。肌热如烙。韧痰阻于咽喉不能咯吐。须以纸帛搅而曳之。患处红肿白腐。龈舌皆糜。米饮不沾。汛事非期而至。脉左细数。右弦滑。曰：此阴亏之体。伏火之病。失于清降。扰及于营。先以犀角地黄汤清营分而调妄行之血。（阴亏之体四句。确是此证病因。脉左细数为阴亏营热。右弦滑为气热痰实。治法先血后气。此急则治标之权衡也。大生地八钱。开水泡冲去渣。济银花一两五钱。玄参片一两。泡冲去渣。鲜荷根五钱。黑栀皮三钱。粉丹皮二钱。洋地滑皮五钱。钗石斛杵先一两。）续予白虎汤", "13994": "屠之五子患痰嗽数年。近因悲哀病作。误投参术。病益甚。孟英诊曰。此阴虚劳嗽。嗽久而冲气不纳则呕吐。非胃寒也。经言劳者温之。亦温养之谓。非可以温补也。方用西洋参熟地苁蓉二冬茯苓龟板牡蛎紫石英玉竹枇叶橘皮。服之果安。（投参术病益甚。病非阳虚明甚。孟英诊断阴虚。必有脉情可据。冲脉系于肝。肝病则冲逆。劳者温之。言阴虚者阴中之阳亦虚。不可用甘寒偏剂。必于甘寒中参以温药。至冲气不纳。宜潜阳中稍参重镇。西洋参三钱。炒熟地八钱。明天冬六钱切。整麦冬三钱。云苓片三钱。炙龟板八钱。煅牡蛎三两。紫石英五钱。三味同杵先炭煨六句钟。肥玉竹三钱。蜜炙枇叶刷包三钱。淡苁蓉三钱。盐水炒橘红一钱五分。）", "13995": "胡秋纫酷热偶有不适。医以柴葛香薷散之。反恶寒胸痞。更医用枳朴槟榔以泻之。势日剧。孟英视之。自汗不收。肢背极冷。奄奄一息。脉微无神曰。禀赋素亏。阳气欲脱。此必误认表证使然。予救逆汤加参耆。服之渐安。继以补气生津。调理匝月而痊。（恶寒胸痞为阳虚。肢背极冷。脉微无神。奄奄一息。合之自汗不收。为阳气欲脱。方用炒潞党五钱。炒西耆五钱。炒粉草三钱。炒干姜五钱。炒熟附片五钱。）", "13996": "陈芰裳患淋久不愈。延至溽暑。孟英诊之曰：易事耳。予补中益气汤而愈。（淋证之因不一。此证因脾阳衰败。气不摄精。右脉必重按无力。炒潞党五钱。炒西耆五钱。炒粉草三钱。炒白术三钱。炒茅苍术四钱。炒焦陈皮一钱五分。炒干姜五钱。制半夏五钱。炒故纸研五钱。）", "13997": "段尧卿母年逾七十。患霍乱转筋。孟英投自制连朴饮三啜而瘳。原方治湿热蕴伏而成霍乱。兼能行食涤痰。原方姜制厚朴（二钱）姜炒雅连（一钱）石菖蒲（一钱）制半夏（一钱）炒香豉（三钱）黑栀皮（三钱）活水芦根（二两）石诵羲妻久患痰嗽。诸医药之勿瘳。孟英切脉曰。非伤风也。予北沙参熟地百合麦冬玉竹贝母紫菀枇叶盐水炒橘红燕窝。一剂知。数剂已。（此证阴虚肺燥。前医必作伤风治。迭投温散。致伤上焦气分之阴。伤食为外感实证。此证为内伤虚证。北沙参八钱。大熟地开水泡冲去渣五钱。百合须三钱。花麦冬三钱。川贝母杵三钱。肥玉竹二钱。鲜枇叶刷包三钱。淡盐水炒橘皮一钱五分。燕窝包先三钱。）其人初秋又患脘痛。上及肩尖。向以为肝气。转服破削之品。孟英曰。亦非也。以砂仁炒熟地炙橘红楝实延胡枸杞当归茯苓桑葚蒺藜为方。服之良效。继即受孕。（阴虚则肝肺易燥。此证系阴虚肝旺。肝阳贼胃。肝阳有余。即系肝阴不足。非真有余也。服破削之品。则肝阴愈伤。砂仁末二分拌炒大熟地去砂仁八钱。赖橘红一钱。川楝实杵先四钱。延胡索一钱。甘枸杞三钱。箱归身二钱。白茯苓三钱。干桑葚杵先三钱。生白蒺去刺一钱五分。）", "13998": "石芷卿患感。张某连投柴葛药。热果渐退。复热之后势更甚。孟英先以栀豉芩连清解其升浮之热。（大凡实热挟感。初误温散。热无不退。以其人本身固有之阴。尚能供温剂劫汗之取求也。迨劫汗以后。阴伤热炽。热势更甚。医者不可不知。孟英先用栀豉芩连清解其升浮之热。俟邪归胃腑。脉沉实滑。方用承气下之。此治病分初中末之定法也。黑山栀皮三钱。淡豆豉三钱。酒炒雅连八分。酒炒枯芩二钱五分。鲜枇杷叶刷包三钱。姜竹茹三钱。连翘壳三钱。活水芦根一两。钗石斛杵先五钱。薄橘红。旋覆绢包。各一钱五分。）俟邪归胃腑。脉来沉实而滑。径用承气下之。（生厢黄四钱。开水泡冲去渣。炒枳实二钱。川楝实杵先二钱。石菖蒲一钱。赖橘红一钱五分。陈胆星一钱炖和服。）服次方后。翼日大热大汗。大渴引饮。孟英曰。此腑垢行而经热显。予竹叶石膏汤二剂而安。（鲜竹叶二钱。生石膏一两六钱先煎。酒炒知母三钱。黑山栀皮三钱。鲜枇杷叶刷包三钱。活水芦根二两。炒枳实三钱。晚蚕砂五钱。陈木瓜一钱五分。）继以育阴充液调理而康。", "13999": "王叟仲秋患痰嗽不食。气喘不卧。囊缩便秘，心摇摇不能把握。势极可危。孟英诊之曰。根蒂欲脱耳。非病也。以八味地黄汤去丹泽合生脉加紫石英青铅龙牡胡桃肉楝实苁蓉投之。大解行而诸恙减。乃去苁蓉麦冬服旬日以瘳。（此证认阴虚阳浮。全在囊缩便秘心摇摇不能把握二语。大熟地八钱。淮山药四钱。山萸肉三钱。白茯苓干切三钱。花麦冬三钱。五味子杵三钱。酒炒知母一钱五分。酒炒川黄柏一钱。加紫石英杵五钱。青铅一两。煅龙骨二两。煅牡蛎八两。四味先炭煨八句钟。取汤代水煎药。连衣胡桃肉五钱。川楝核杵先三钱。淡苁蓉三钱。）", "14000": "邵可亭冬患痰嗽。面浮微喘。医进温补纳气之药。喘嗽日甚。口涎自流。茎囊渐肿。两腿肿硬至踵。不能稍立。开口则喘逆欲死。不敢发言。头仰则咳呛咽疼。不容略卧。痰色黄浓带血。小溲微黄而长。孟英视之。脉形弦滑有力。曰：此高年孤阳炽于内。时令燥火薄其外。外病或可图治。真阴未必能复。且平昔便如羊矢。津液已干。再投温补。如火益热矣。乃以白虎汤合泻白散加西洋参贝母花粉黄芩大剂投之。并用北梨捣汁频饮润喉。以缓。其上僭之火。数帖后势渐减。（此证为阴虚痰实。辨证尤在脉弦滑有力。脉证互参。方用生石膏先煎一两。酒炒知母三钱。生粉草三钱。生桑皮四钱。鲜地骨皮五钱。西洋参三钱。川贝母杵一两。南花粉四钱。酒炒枯芩三钱。并用连皮北梨捣汁生饮润喉。不限时刻斤数。）", "14001": "陆某酒业极窘。又遭颠沛。久而患一异疾。形消善痒。虱从皮肤而出。搔之蠕蠕。医治莫效。孟英诊曰：悲哀劳苦。阳气受伤。曲糵浸淫。乃从虫化。予补气药加杉木桑枝而愈。（此证阳衰必有脉情可据。医治莫效句宜注意。若系实证。则杀虫套药早效矣。方用炒潞党五钱。炒西耆五钱。制茅术四钱。制白术三钱。炒粉草三钱。炒合欢皮三钱。云茯神三钱。白茯苓干切三钱。使君子连壳杵三钱。炒杉木皮三钱。酒桑枝三钱。）", "14002": "陈芰裳母陡患呕吐。彻夜不止。孟英诊以芩连栀楝大苦寒为剂。投之良愈。（暴病无虚。况彻夜不止乎。此证认气分实热。在彻夜不止四字。酒炒枯芩二钱。酒炒雅连一钱。川楝核杵先三钱。黑栀皮三钱。川贝母杵三钱。生冬瓜子四钱。生苡仁杵八钱。石菖蒲次入一钱。炒枳实一钱。陈胆星炖和服一钱。姜竹茹三钱。旋覆花绢包三钱。枯青果杵先三个。生赭石一两同杵先。）张郑封妻娩后即发热。服生化汤二帖。热益甚而发赤疹。顾听泉予清解。三剂不应。拟进犀角地黄汤。质之孟英。脉弦滑而数。面赤热躁。胸闷善悲。肢肿而疼。两肘白疱如扁豆大者数十颗。舌上亦有一颗。痛碍水饮。大便不解已旬日。曰：此不但胎前伏暑。且有蕴毒。误服生化汤以助其。虐。幸入手即清解。尚不至于昏陷。犀角地黄极是治法。犹恐不能胜任。商加西洋参滑石知母银花人中白蒌仁竹黄贝母桑叶栀子为剂。（热发赤疹。脉弦滑数。病邪俱在上焦气分。镑犀角磨冲八分。大生地开水泡冲去渣八钱。西洋参三钱。西滑石四钱。济银花次入八钱。南花粉四钱。人中白八分研冲。姜汁炒蒌仁研三钱。天竹黄三钱。川贝母杵一两。冬桑叶四钱。黑栀皮三钱。）病者虽渴而喜热饮。凡胸中有热痰阻碍气机者每如是。所以方中多用痰药。进四帖始得大解。频吐稠痰。各恙皆减。饮食渐加。专科隔靴搔痒。纪律全无。旬日余火复然。孟英仍用甘寒疗之。周身肤蜕如蛇皮。爪甲更新。继予滋补真阴而起。", "14003": "郑某吐血盈碗。孟英诊之。右关洪滑。自汗口渴。稍一动摇。血即上溢。予白虎汤加西洋参大黄炭。一剂霍然。（洪脉为虚。滑脉为实。玩稍一动摇血即上溢二语。此证实多虚少。生石膏先煎八钱。酒炒知母三钱。西洋参三钱。大黄炭一钱。入药汁内泡服去渣。）", "14004": "孟英切康伯侯脉滑数而左歇右促。且肝部间有雀啄。气口又兼解索。望其面宛如熏黄。头汗自出。呼吸粗促。似不接续。坐卧无须叟之宁。便溺涩滞。浑赤极臭。心下坚硬拒按。形若覆碗。舌色边紫苔黄。殊不甚干。燥。问其所苦。曰：口渴甜腻。不欲饮食。苟一合眼。即气升欲喘。烦躁不能自持。胸中懊𢙐。莫可言状。孟英曰：此由湿热误补。漫无出路。充斥三焦。气机为其阻塞而不流行。蔓延日久。津液为之凝滞而成痰饮。医见肢冷自汗。不知病由壅闭而然。（中略。）凡脉证多怪。皆属于痰。今胸痞如斯。略无痰吐。由痰能阻气。气不能运痰。宜于温胆中加薤白蒌仁。通其胸中之阳。又合小陷胸为治饮痞之圣法。参以栀豉。泄其久郁之热以除懊𢙐。佐以兰草。涤其陈腐之气以醒脾胃。（由脉滑数左歇右促二十一句。皆湿热误补。因实致虚。易升难降之病情。须逐句深思之。半夏曲一钱五分。淡盐水炒陈皮一钱。白茯苓一钱五分。炒枳实一钱。姜竹茹四钱。姜栀皮三钱。西薤白打次入一钱五分，姜汁炒蒌仁研三钱。姜汁炒雅连八分。建兰叶次入三钱。炒香豉一钱五分。）连投二剂。各恙皆减。脉亦略和。病者误服大黄丸二次。承气汤半帖。孟英急止之曰。畏虚进补固非。欲速妄攻亦谬。盖湿蒸为热。灼液成痰。病非一朝一夕而成。治以上下分消。为是。不比热邪传腑。可一荡而愈也。越日下部果渐肿。以前法加黄芩合泻心意。再配雪羹投之。（前方去栀豉。加酒炒枯芩一钱五分。淡海䖳八钱。连皮荸荠打一两。）痰果渐吐。痞亦日消。而自腹至足以及茎囊。肿势日加。孟英谓势已如此。难以遽消。但从三焦设法。病必无虞。前药嫌力不足。拟用河间桂苓甘露意。众议仍投前药。次日痰中带血甚多。孟英曰：湿热熏蒸不已。自气及营矣。以知柏生地犀角鳖甲白芍苡仁贝母石斛茅根麦冬滑石栀子藕汁童溺投之而止。（世所畏者劳怯吐血。此证湿热扰营。系属实证。血不足虑。酒炒知母三钱。酒炒川黄柏一钱五分。大生地开水泡冲去渣八钱。镑犀角磨冲一钱。血鳖甲杵先八钱。酒炒白芍一钱五分。生苡仁杵八钱。川贝母杵三钱。钗石斛杵先一两。鲜茅根五钱。花麦冬四钱。西滑石先煎五钱。黑栀皮一钱五分。藕汁一酒杯冲。童溺一大酒杯煎去沫冲。）逾数日又吐。且肢冷自汗。心馁畏脱。孟英曰。脉来屡变。无怪疑为大虚。然望闻问切。不可独凭于指下。今溲如赭石汤。浑赤有滓。其为湿热之病。昭昭若揭。初伤于气分。则津液受灼以为痰继及于营分。则阴血不安而妄溢。邪气内盛。岂非病实。而真实类虚。前方令服二剂。血果止。孟英曰。血之复吐。由气分之邪扰之。欲清气道之邪。必先去其邪所依附之痰。盖津液既为邪热灼烁以成痰。痰即为邪热之窝巢。不妨峻攻其实而缓行其势。初进滚痰丸三钱。得下泄气一次。为四旬余未有之通畅。连投滚痰丸数日。始解胶痰黑矢多遍。而小溲亦渐清长。苔色亦退。寝食遂安。（此证中间清肝止血。旋以滚痰缓进攻痰。先治血。后治痰。系湿热扰营吐血。急则治标之变法。）惟下部之肿犹尔。孟英曰：谛参脉证。病不在脾。况善饥便燥。口渴溺多。吾方虑转消证。亟投甘润之不遑。乌可渗利伤阴补土劫液耶。且脾虚下陷之肿。与湿盛而肿之肿。其膝之上下内外。形势必然相贯。今膝之上下内外凹凸迥判。毫不昆连。盖由湿热所酿之痰饮。既误补而痞塞中焦。复妄攻以流窜隧络。所谓不能一荡而蠲。势必旁趋四射。吾当以法取之。会又咳痰带血。而精神食饮如常。孟英曰：无恐也。乃前比嚼三七太多。兜涩留瘀。最不宜止。吐而去之极妙。但须金木同治。冀咳止而血络不震动为要耳。予甘露饮加藕汁童溺服之。四剂而止。咳嗽亦宁。（大生地八钱。明天冬切薄片六钱。花麦冬四钱。开水泡绞冲去渣。钗石斛杵先一两。酒炒西茵陈二钱。酒炒枯芩一钱。炒枳壳一钱五分。姜枇叶刷包次入三钱。藕汁一酒杯冲。童溺两大酒杯煎去沫冲药温服。）于是专治其下部之肿。以固本加知柏贝母花粉旋覆橘络丝瓜络羚羊角楝核葱须豆卷苡仁竹沥出入为剂。二三帖间。其高突隆肿之处。即觉甚痒。搔之出水如汗而作葱气。（大生地八钱。明天冬切六钱。花麦冬四钱。酒炒知母二钱。酒炒川黄柏一钱。川贝母四钱。南花粉三钱。旋覆花绢包三钱。净橘络次入一钱五分。两帖后去知柏贝母。加丝瓜络三钱。羚角磨冲一钱。楝核杵先四钱。鲜葱须次入一钱。大豆卷次入三钱。生苡仁杵八钱。姜竹沥一大酒杯冲。药温服。）六七日后。两腿反觉干瘦燥痛。茎囊亦随之而消矣。孟英曰用此润药消肿。尚且干燥咽痛。设从群议投燥脾利水之剂。当更何如。盖寒湿则伤阳。热湿则伤阴。血液皆阴也。善后之法。还宜滋养血液。稍佐竹沥以搜络中未涤之痰。使愈后不为他日之患。更属法中之法。服之饮食中节。便溺有权。幸无消渴之虞。竟愈。", "14005": "周菊生妻患少腹酸坠。小溲频数而疼。医投通利不效。继以升提温补。诸法备试。至于不食不寐。口渴不敢饮水。闻声即生惊悸。孟英脉之曰。厥阴为病也。不可徒治其足太阳。先予咸苦以泄其热。续用甘润以滋其阴。毫不犯通渗之药而愈。（通渗所以治实证。少腹酸坠。酸为热邪灼液。小溲频数而疼。此为热实兼挟阴虚。大解不行。肺胃生化之源已伤。闻声即生惊悸。心肝之阴大耗。先予咸苦泄热以治其实。续用甘润滋阴以治其虚。此证实中挟虚。通渗则犯虚虚之戒。方用白头翁三钱。酒炒川连八分。酒炒川黄柏三钱。乌梅肉三钱。生白蒺去刺三钱。整白芍杵先二两。血鳖甲杵先炭煨八句钟四两。干海参五钱。温水泡发去沙用汤煎药。玄参片八钱。更方大生地八钱。玄参片一两。济银花一两五钱。蒲桃干三钱。明天冬切六钱。肥玉竹三钱。菟丝饼五钱。乌梅肉三钱。龟板胶二钱炖和服。川楝核杵先四钱。）", "14006": "高若舟偶患腹胀。医投温运。渐至有形如痞。时欲冲逆吐酸。误信虚寒。温补之药备尝。饮食日减。其痞日增。肌肉渐消。卧榻半载。孟英春诊。脉沉弦而软滑。大解不畅。小溲浑短。苔色黄腻。乃肝郁气结。郁则生热。补则凝痰。予栀楝萸连元胡乌药旋枳鸡金鳖甲茹橘苓夏等药。（脉弦滑为肝热挟痰。脉沉软为肝郁气结。黑栀皮一钱五分。川楝核杵先三钱。淡吴萸六分。姜炒川连八分。元胡索八分。台乌药一钱。旋覆花绢包三钱。炒枳实一钱五分。炙鸡金研四钱。血鳖甲杵先八钱。姜竹茹三钱。蛀陈皮一钱五分。白茯苓三钱。半夏曲三钱。）服之证虽递减。时发寒热。四肢酸痛。或疑为疟。孟英曰：此气机宣达。郁热外泄。病之出路。岂可截乎。参以秦艽柴胡豆卷羚羊蚕砂桑枝之类迎而导之。（前方当去栀连鳖甲。加左秦艽三钱。春柴胡一钱五分。大豆卷三钱。三味同次入。羚角磨冲八分。晚蚕砂三钱。酒炒桑枝次入三钱。）寒热渐息。攻冲亦止。按其腹尚坚硬。时以龙荟滚痰丸缓导之。饮食递加。渐次向愈。（此坚硬必在大腹。滚痰丸二钱。龙荟丸一钱作一服。）", "14007": "赵听樵妻去冬偶患脘痛。黄某治之。渐增头疼眩晕。气逆呕吐。痰多不寐。便溏不食。经事不行。始疑其虚。继疑其娠。诸药遍试。病日以进。孟英脉之。左弦而数。右滑以驶。曰：病药耳。旬余可瘳。盖病者体质虽丰。阴虚有素。是以木少水涵。肝阳偏盛。上侮于胃。则为脘痛。斯时投以酸苦泄肝。甘凉养胃。数日而愈矣。乃温补妄施。油添火上。肺津胃液。灼烁无余。怒木直升。枢机窒塞。水饮入胃。凝结为痰。虽见证多端。皆气失下降。岂可指眠食废以为劳。月汛爽以为妊耶。予以大剂清淡之品肃清气道。俾一身治节之令。肝胆逆升之火。胃腑逗留之浊。枢机郁遏之热。水饮凝滞之痰。咸得下趋。自可向愈。投匕即效。逾旬果安。又一月经至。（方用活水芦根二两。生冬瓜子四钱。生苡仁杵八钱。川贝母杵一两。南花粉四钱。花麦冬三钱。姜炒枯芩三钱。旋覆花绢包三钱。连皮荸荠二两。连皮北梨一两。鲜青果两个。连核杵。生蛤壳一两。海浮石五钱。三味同先煨。）马某年三十余。素用力。患发热恶寒。肢振自汗。少腹气上冲胸。头疼口渴。孟英诊曰。卫虚风袭。而络脉久伤。肝风内动。予建中去饧加龙牡石英苁蓉楝实桑枝数帖而痊。（劳力伤阳。此证卫虚。必另有脉情可据。至论证则以恶寒为卫虚。肢振自汗三句。皆阴虚肝风内动之象。生西耆三钱。大生地八钱。酒炒白芍一钱五分。花麦冬四钱。煅龙骨杵一两。煅牡蛎杵四两。紫石英杵五钱。三味先炭煨八句钟。淡苁蓉三钱。三楝核杵先四钱。酒炒桑枝次入三钱。黄耆治卫虚。冬地治液虚口渴。龙牡石英医法重以镇怯。治自汗气逆头疼。酒炒白芍上行止汗。酒炒桑枝入肢治肢振之标。）", "14008": "李燕标夏项患疽。外科佥云不治。朱嵩年疗之渐安。孟英诊脉。谓李证可愈难享年。左尺坚搏。真阴已伤。非善象也。痊后春卒。（脉诀久病生死察左尺脉之盛衰。）", "14009": "李叟年越古稀。意欲纳妾。子孙不敢从。因此渐病狂惑。群医广投热补。愈服愈剧。孟英诊之。脉劲搏指。面赤不言。口涎自流。力大无制。曰：此禀赋过强。阳气偏盛。故前欲纳妾。医不知既享大寿。得天必厚。况人年五十。阴气先衰。徐灵胎所谓千年之木往往自焚。阴尽火然。万物皆然。去冬吾治邵可亭孤阳喘逆。壮水清火之外。以天生甘露饮（即梨汁。）灌至二百余斤。病已渐平。仅误于两盏姜汤。前功尽堕。可见禀赋偏阳者。阴难充长。火易燎原。今附桂仙茅鹿茸参戟河车等药。服之已久。更将何物以生其涸竭之水而和其亢极之阳乎。寻果不起。", "14010": "翁嘉顺妻娩后发热。竹林寺僧治之不应。温龚二医皆主生化汤加减。病益剧。孟英诊之。脉软滑微数。曰：素体阴亏。热自内生。新产血去。是以发热。憔谵妄昏瞀。最是吓医之证。渴喜热饮。宛似虚寒之据。宜其猜风寒而表散。疑瘀血以攻通。帖帖炮姜。人人桃桂。阴愈受劫。病乃日加。幸而津液内盛。痰饮未致涸竭。予蠲饮六神汤去橘半。加西洋参生地花粉竹茹知母生白芍为剂。数日而瘳。（脉软为阳虚。脉滑为痰实。脉数为阴虚挟热。石菖蒲次入一钱。陈胆星炖和服七分。旋覆花绢包三钱。白茯苓三钱。西洋参三钱。大生地八钱。南花粉四钱。姜竹茹三钱。酒炒知母三钱。生白芍四钱。）逾旬复发热。仍乞诊。孟英曰。脉浮数而弦。是风温也。与前病异。便泻无溺。肺热所迫。大渴无苔。胃汁受烁。亟与天生建中汤频灌。即蔗汁也。药主大剂甘凉。果得津回舌润。渐以痊可。（脉数为阴虚挟热。兼浮弦为津枯风动。活水芦根二两。酒炒知母三钱。酒炒枯芩一钱。南花粉五钱。花麦冬四钱。连皮北梨三两。鲜竹茹三钱。鲜荷根五钱。济银花八钱。钗石斛杵先一两。乌梅肉三钱。青蔗汁一大酒杯和服。）", "14011": "翁嘉顺亦染温病。初发热即舌赤而渴。脉数且涩。孟英曰。非善证也。盖阴虚有素。值此忧劳哀痛之余。五志内燔。温邪外迫。不必由卫及气自气而营。急予清营。继投凉卫。病来颇恶。治虽合法。势必转重。病果日重。昏瞀耳聋。自利红水。目赤妄言。孟英惟以晋三犀角地黄汤加银花石膏知母石斛栀贝花粉兰草菖蒲竹沥竹茹竹叶凫茈海䖳等出入互用。（治法先气后营为正治。先营后气为变法。昏瞀目赤。营阴素虚。温邪径伤营分。若执先气后营常法。治必无及。此证可生。全在妄言。盖妄言则热邪虽渐侵营分。尚未全离气分。若热邪全入营分。则并无所谓言。方用镑犀角磨冲二钱。大生地八钱。元参片一两。二味开水泡汤去渣。用汤煎药。济银花一两五钱。酒炒知母三钱。生石膏八钱先煎。黑栀皮三钱。石菖蒲次入一钱。建兰叶次入三钱。更方去生地加钗石斛杵先一两。再更方去石膏栀皮。加川贝母杵一两。南花粉五钱。再更方去元参。加姜竹沥二两。再更方去银花入姜竹茹四钱。鲜竹叶二钱。再更方去花粉。加连皮荸荠打三两。泡淡陈海䖳二两。）至十余剂。舌上忽布秽浊垢苔。口气喷出。臭难向迩。手冷如冰。头面自汗。孟英曰。生机也。阴虚热邪深入。予一以清营凉卫之法。服已逾旬。始得营阴渐振。推邪外出。乃现此苔。惟本元素弱。不能战解。故显肢冷，而汗仅出于头面。非阳虚欲脱也。（阳虚欲脱。则上半身全有汗。）复予甘寒频灌。越三日。汗收热退。苔花肢温。（阴虚之质。最重津液。甘寒频灌。津回液复。周身气机乃得伸其用。与阳虚补阳。气机乃能有权。初无二理。）自始至终。犀角共用三两许。未犯一毫相悖之药。继以滋填肾阴而康。", "14012": "沈东屏年逾八秩。患腹胀便秘。孟英诊曰。耄年脉实。天畀独厚。证属阳结。法宜清火。予西洋参石膏白芍知母花粉桑皮橘皮枳壳甘草送更衣丸四剂而愈。（西洋参三钱。生石膏先煎八钱。整大白芍杵先二两。酒炒知母三钱。南花粉五钱。生桑白皮四钱。甜杏仁三钱。盐水炒橘皮一钱。生枳壳二钱。生粉草三钱。药送更衣丸三钱。）", "14013": "顾石甫患恙。医治日剧。求诊孟英。脉现左寸如钩。曰：病不能夏矣。许医诘曰：此证气逆血溢。腹胀囊肿。宛似康伯侯前疾。胡彼可愈而此不治。孟英曰：彼为邪气之壅塞。脉虽怪而搏指不挠。此为真气之散漫。脉来瞥瞥如羹上肥。而左寸如钩。是心之真脏脉见矣。壅塞可以疏通。散漫不能收拾。季春果殁。", "14014": "孙氏女年将及笄。久患齿衄。多医莫疗。孟英诊曰：六脉缓滑。天癸将至耳。予丹参生地桃仁牛膝茯苓白薇滑石茺蔚子。一剂知。数日愈。寻即起汛。略无他患。（脉缓为脾脏挟湿。脉滑为挟热气不下行。气不下行则血上逆故齿衄。齿衄为血热。血上逆必挟瘀。故治以凉血行瘀。紫丹参四钱。大生地五钱。生桃仁研三钱。白茯苓三钱。西滑石先煎五钱。香白薇一钱。茺蔚子杵先四钱。酒炒淮牛膝一钱。）", "14015": "朱念民患泄泻。自谓春寒偶薄而饮烧酒。次日转为滞下。左腹起一痞块。痢时绞痛异常。孟英曰。阴虚木燥。侮胃为泄。误饮火酒。怒木愈张。非寒也。亟屏辛温之物。用白头翁加芩楝栀连海䖳银花草决明枳椇子绿豆皮。十余剂而愈。（论证尽于原案。且左脉必浮弦数重按有力。白头翁三钱。黑栀皮三钱。酒炒川连一钱。酒炒枯芩二钱。济银花次一两五钱。草决明三钱。绿豆皮五钱。更方去连芩栀皮。加泡淡陈海䖳四两先煎。枳椇子杵先八钱。以苦寒泻热治标。以咸寒育阴治本。）", "14016": "锁某弱冠吐血。医进归脾汤。吐益甚。孟英视之。面有红光。脉形豁大。因问曰。足冷乎。探之果然。遂与六味地黄汤送饭丸肉桂心一钱。复杯而愈。（面有红光。为虚火上炎。脉形豁大及足冷。为阴中之阳亦虚。肾气不能潜纳。归脾中参耆性皆上升。故吐益甚。易以引火归原之法斯愈矣。大熟地八钱。淮山药四钱。白茯苓三钱。山萸肉三钱。药送饭丸肉桂心一钱。）", "14017": "沈裕昆妻偶发脘痛。范某予逍遥法。痛颇止。而发热咽疼。顾听泉知感温邪。予清解法。疼已而热不退。七日后目闭鼻塞。耳聋肢搐。不言语。不饮食。孟英往诊。见其外候如是。而左手诊毕即缩回。旋伸右手备诊。曰：非神昏也。继挖牙关。察其苔色白滑。询知大解未行。曰：病是风温。然不逆传膻中而顺传胃腑。证可无恐。此证如是骇人。因素有痰饮盘踞胸中。外邪入之得以凭借。苔色之不形黄燥。亦此故耳。不可误认为寒。脉象既形弦滑以数。但令痰饮一降。苔必转黄。昔人于温证仅言逆传不言顺传。后世遂误执伤寒在足经。温热在手经。不知经络贯穿。岂容界限。喻氏嘉言谓伤寒亦传手经。但足经先受之耳。吾谓温热亦传足经。但手经先受之耳。盖自肺之心包。病机渐进而内陷。故曰逆。自肺之胃腑。病机欲出而下行。故曰顺。今邪虽顺传。欲出不能。所谓胃病则九窍不和。与逆传神昏之犀角地黄汤证大相径庭。郭云台云：胃实不和。投滚痰而非峻。可谓治斯疾之真诠。遂书小陷胸合蠲饮六神汤加枳朴以芦菔煮水煎药和入竹沥一杯送下礞石滚痰丸四钱。且谓既患骇人之病。必服骇人之药。药不瞑眩。厥疾不瘳。（热邪逆传于膻中而神昏则宜犀角地黄汤。顿传于胃腑而便结。则宜滚痰丸之类。此证右关脉必弦滑数重按有力。至此方佐蠲饮六神加朴。因苔色白滑。苦寒中必佐以辛温。姜炒川连八分。制半夏米三钱。石菖蒲次入一钱。陈胆星炖和一钱。旋覆花绢包三钱。赖橘红一钱五分。炒枳实一钱五分。制根朴二钱。芦菔切一两煮汤代水煎药。和入姜竹沥一酒杯。药送礞石滚痰丸四钱。）翼日诊。脉证不甚减。询知昨药分数次服下。孟英曰：是势分力缓之故。如法服之。黎明果解胶韧痰秽数升。各恙即减。略吐语言。稍啜稀粥。苔转黄燥。药改轻清。渐以向安。嗣予育阴柔肝而愈。", "14018": "朱氏妇素畏药。虽极淡之品。服之即吐。近患晡寒夜热。寝汗咽干。咳嗽胁疼。月余后渐至减餐经少。肌削神疲。孟英诊之。左手弦而数。右部涩且弱。曰：既多悒郁。又善思虑。所谓病发心脾是也。而平昔畏药。岂可强药再戕其胃。以甘草小麦红枣藕四味。令其煮汤频饮勿辍。病者日夜服之。逾旬复诊。脉证大减。孟英曰：此仲景治脏燥之妙剂。吾以红枣易大枣。取其色赤补心。气香悦胃。加藕以舒郁怡情。合之甘麦并能益气养血。润燥缓急。恪守两月。竟得霍然。（生粉草三钱。连皮肥藕切先二两。北小麦杵四钱。红枣擘先四钱。）", "14019": "江某年三十余。忽两目发赤。牙龈肿痛。奔走骂人。不避亲长。孟英诊之。脉大而数。重按虚散。予东洋参熟地辰砂磁石龙齿菖蒲枣仁琥珀肉桂金箔龙眼肉为剂。投匕即安。（脉大为虚。数为阴虚挟热。重按虚散。则阴中之阳尤虚。高丽参三钱。炒松熟地八钱。整辰砂五钱。灵磁石一两。煅龙齿八钱。三味同先炭煨八句钟。九节蒲研次入一钱。炒枣仁研三钱。西毛珀研冲四分。肉桂心次入二钱。金箔次入七片。桂元肉去核三钱。）", "14020": "金禄卿妻患温。顾听泉连进轻清凉解而病不减。气逆无味。咳吐黏痰。舌绛咽干。耳聋谵语。旬日外孟英诊之。曰：体瘦脉细数。尺中更乱。竟是阴气先伤。阳气独发。所谓伤寒偏死下虚人。再四研诘。乃知发热前一日陡然带下如崩。是真液早经漏泄矣。否则药治不讹。胡勿燎原益炽。痉厥之变不须旋踵。勉以西洋参生地二冬二至元参犀角黄连鸡子黄知母为方。另用石斛龟板鳖甲各四两。左牡蛎一斤。煮汤代水煎药。（西洋参三钱。大生地八钱。明天冬切六钱。花麦冬四钱。女贞子杵五钱。旱莲草四钱。元参片一两。镑犀角磨冲二钱。淡盐水炒川连二钱。淡盐水炒知母四钱。鸡子黄三个。沥去蛋白。另用石斛龟鳖甲各四两。牡蛎一斤煮汤代水煎药。顾听泉又加清阿胶三钱。炖和服。）服两剂果不能减。后服签方温药。四肢拘挛而逝。", "14021": "一妪患右腰痛胀欲捶。多药不效。孟英视其形虽羸瘦。而脉滑痰多。苔黄舌绛。曰：体虚病实。温补非宜。苟不攻去其疾。徒以疲药因循。则病益实。体益虚。先以雪羹加竹茹楝实绿萼梅杏仁花粉橘红茯苓旋覆送控涎丹。服后果下胶痰。三进而病若失。嗣予调补获痊。（脉滑苔黄舌绛。皆为热邪。舌绛为阴虚挟热。连皮荸荠打二两。泡淡海䖳先煎一两。姜竹茹三钱。川楝核杵先三钱。绿萼梅二钱。苦杏泥一钱五分。南花粉四钱。赖橘红八分。白茯苓一钱五分。旋覆花绢包三钱。药送控涎丹三钱。）", "14022": "郁某热逾半月。自胸次胀及少腹。痛而不可抚摩。便秘溺赤。舌黑口干。自汗烦躁。六脉弦强无胃。曰：此恙酷似伤寒大结胸证。结胸烦躁。无药可治。越二日便行而殁。孟英论曰：伤寒之邪在表。误下则邪陷而成结胸。未经误下不为结胸。温热之邪在里。逆传于心包。误汗则内闭以外脱。顺传于胃腑。误汗则盘踞而成结胸。前人但云误汗劫夺胃汁。而未及于结胸。因结胸证不多见耳。然亦不可不知也。故谨识之。郁病初起。某医用葛根一剂。继则胡某柴葛羌防十余剂。酿成是证。", "14023": "施氏妇产后四肢串痛。药治罔效。膏药遍贴。呻吟不息。脉数而洪。舌绛大渴。此非风湿为病。膏药亟为揭去。近日服药，谅皆温补祛风之剂。营血耗伤。内风欲动，向见体丰血旺。何以娩后若是。必生化汤砂糖酒之类所酿。询悉果服生化汤二帖。赤砂糖八斤。幸素足于阴。恢复尚易。若阴虚血少。虽不即死。难免不成蓐损。因投大剂凉润壮水之药。一剂知。旬日安。匝月起。（脉数为阴虚挟热。洪为阴虚。舌绛大渴及呻吟。热已侵营。未离气分。大生地八钱。济银花一两五钱。明天冬切六钱。元参片一两。钗石斛一两杵先。肥玉竹三钱。酒炒知母三钱。白茯苓三钱。乌梅肉三钱。南花粉五钱。花麦冬四钱。酒炒桑枝三钱。）", "14024": "王士干妻素多郁怒。气聚于腹。上攻脘痛。旋发旋安。花甲外病益甚。医治益剧。孟英诊不书方。因论曰。腹中聚气为瘕。攻痛呕吐。原属于肝。第病已三十载。从前服药谅不外温补一途。如近服逍遥散最劫肝阴。理中汤极伤胃液。人但知呕吐为寒。未识风阳内煽。水自沸腾。专用温补。津液渐形涸竭。医者妄谓水已不吐。病势渐轻。不察其水已吐尽。仅能哕逆空呕所以不能纳谷。便秘不行。脉弦无胃。舌痿难伸。可谓女人亦有孤阳之病矣。勉以西洋参肉苁蓉麦冬玉竹生白芍石斛竹茹柏子霜紫石英为方。猪肉煮汤煎药和入青蔗浆人乳。服后呕哕皆止。人以为转机。孟英譬草木干枯已久。骤加灌溉。枝叶似转青葱。根荄已槁。生气不存。奈何。继而糜粥渐进。颇思肉味。越数日大便颇畅。孟英曰：脉不柔和。舌不润泽。虽谷进便行。生津化液之源已绝。夏至后果殒。（呕分寒热两大门。此证本系肝阳犯胃热呕。迭误温补戕阴。阴精已竭。西洋参三钱。淡苁蓉三钱。花麦冬五钱。肥玉竹三钱。整大白芍杵先二两。钗石斛杵先一两。鲜竹茹四钱。柏子霜三钱。紫石英杵先五钱。干猪肉皮一斤。急火煎汤。吹去浮油代水煎药。和入蔗浆两杯。人乳一杯。）", "14025": "储丽波酷热患疟。陆某率投平胃理中。渐至危殆。孟英诊之。热炽神昏。胸高气逆。苔若姜黄。溺如赭赤。脉伏口渴。不食不便。曰：舍现病之暑热。拘司气以论治。谓之执死书以困活人。幸其体丰阴足。尚可救药。然非白虎汤十剂。不能愈也。遂以生石膏知母银花枳贝黄连木通花粉茹芩杏斛海䖳等相迭为方。服旬日疟果断。（热炽神昏六句。热邪皆在气。心与肺胃相近。温补伤肺胃之阴。则热炽神昏。此神昏非热传营也。生石膏先煎一两二钱。酒炒知母四钱。炒枳壳一钱五分。川贝母杵一两。南花粉五钱。苦杏泥次入一钱五分。姜竹茹四钱。济银花一两五钱。更方去知母银花。加酒炒川连一钱。酒炒枯芩三钱。细木通一钱。钗石斛杵先一两。再更方去枳贝。加泡淡海䖳二两。再更方去竹茹。加鲜竹叶次入二钱。）", "14026": "庄迪卿患疟。大渴而喜热饮。脘闷脉伏。苔腻欲呕。孟英曰：蕴湿内盛。暑热外侵。法当清解。然脉证如是。乃痰阻气道使然。清之无益。温之助桀。宜以礞石滚痰丸先为开导。（此证脉伏必重按沉实有力搏指。若脉伏重按无力。大忌峻下。此证宜用滚痰丸三钱。）服后痰出甚多。脉即现弦滑而数。呕止胸舒。苔引黄燥。予石膏知母连朴杏橘半茯滑斛菖蒲花粉等药而安。（生石膏先煎八钱。姜炒知母三钱。姜炒川连一钱。制根朴八分。苦杏泥二钱。五爪红一钱。半夏曲一钱五分。赤茯苓一钱五分。西滑石先煎四钱。钗石斛杵先八钱。石菖蒲次入六分。南花粉四钱。）", "14027": "庄晓村病疟。孟英曰：吸受暑热。清涤即瘳。阅数日疟作甚剧。目赤狂言。汗如雨下。按其脉洪滑无伦。视其舌深黄厚燥。询悉恣饮姜枣汤三日。令取西瓜一枚任食之。方从白虎。而生石膏用一两六钱。（生石膏先煎一两六钱。酒炒知母四钱。活水芦根二两。生瓜子四钱。生苡仁杵八钱。炒枳壳二钱。川贝母杵八钱。南花粉五钱。鲜枇叶刷毛次入三钱。）", "14028": "潘翼廷酷热。啜冷石膏一碗。遂致心下痞闷。四肢渐冷。上过肘膝。脉伏自汗。孟英往视。曰：既受暑热。复为冷饮冰伏胸中。大气不能转旋。是以肢冷脉伏。二便不行。速取六一散一两。以淡盐汤搅之澄去滓调下紫雪丹一钱。（六一散本受暑正治之药。调以紫雪。以辛香通冰伏之气。以治误啜石膏。其先以淡盐汤搅之澄去滓者。治暑贵在去邪。尤贵功无旁挠。紫雪少用。则辛香不足以通冰伏之气。用至一钱。恐辛通后挠六一散下行泻暑之权。故先以淡盐汤搅之。使辛通后无损六一散泻暑下行之效。其必澄去滓者。药虽泻暑下行。暑先伤气。暑邪实侵气分最高之处。澄去滓则用其气不用其质。使之上而复下。尤为丝丝入扣。）翌日再诊。脉现胸舒。溺行肢热。口干舌绛。暑象毕呈。化而为疟。予多剂白虎汤而愈。（脉现胸舒五句。热邪皆在上焦气分。生石膏先煎八钱。酒炒知母三钱。活水芦根一两。生冬瓜子四钱。生苡仁杵八钱。南花粉四钱。钗石斛杵先八钱。姜竹沥一大酒杯冲。细木通一钱。）", "14029": "何永昌妻病疟。间二日而作。旬日后势甚危。孟英诊之。脉沉细而数。尺为甚。口渴目不欲张。两腰收痛。宛如锥刺。寒少热多。心慌不能把握。曰：此暑入足少阴之证。喻氏嘉言所谓汗下温三法皆不可行。书方元参八钱。龟板石斛同先煎八句钟。各一两。酒炒知母五钱。桑皮银花各四钱。花粉三钱。丹皮二钱。令用大砂锅煎而频服。不必限剂。服三日疟断而各恙皆减。粥食渐进。不劳余药而起。（此病认证在尺为甚三字。数为阴虚挟热。沉细为阴分不足。口渴液耗。目不欲张。目为肝窍。肾为肝母。肝肾之阴不足。则目不欲张。腰为肾腑。肾亏则腰痛。寒少热多。热疟何疑。心为火脏。得肾阴以济心阳。则天君泰然。心慌不能把握。为肾阴不能上朝于心。）", "14030": "慎氏妇产后腹胀泄泻。面浮足肿。医予渗湿温补。月余不效。疑为蓐损。孟英视之。舌色如常。小溲通畅。宛似气虚之证。惟脉至梗涩。毫无微弱之形。因予丹参滑石泽兰茯苓茺蔚蛤壳桃仁海䖳五灵脂豆卷。数服即瘥。（此证必系产后恶露未净。瘀停化热。腹胀为瘀停。泄泻为热邪自寻出路。面浮足肿。为瘀停化热。上贼气阴。气机失其下降。渗湿则愈伤其阴。温补则愈助热。舌色如常。小溲通畅。为病在血不在气之明证。瘀停阻气。故脉至梗涩。瘀系实邪。故脉无微弱之形。紫丹参四钱。西滑石先煎五钱。泽兰叶三钱。白茯苓三钱。茺蔚子杵先五钱。生蛤壳杵先一两。生桃仁研三钱。淡海䖳先煎一两。五灵脂二钱。大豆卷次入三钱。）", "14031": "汪左泉病滞下。昼夜数十行。孟英切脉弦滑。苔黄满布。曰：易事耳。重用芩连。佐以楂朴。送服青麟丸四钱。投匕而痊。（此证脉弦滑必重按有力搏指。方任大剂苦寒。姜炒枯芩四钱。姜炒川连二钱。姜制根朴一钱。焦楂肉杵二钱。药送青麟丸四钱。）", "14032": "陈昼三病滞下。某进通因通用法。痛泄无度。呕恶不纳。汗出息微。脉弱眩晕。孟英曰：近多伏暑之痢。此独非其证也。元将脱矣。急投大剂温补。脉候渐安。一月后甫得健复。（此证认阳微在息微脉弱。炒西耆五钱。炒潞党五钱。炒白术三钱。制半夏四钱。炒焦陈皮一钱五分。炒干姜五钱。炒厚附片杵三钱。五味子研三钱。陈木瓜三钱。紫石英五钱。杵炭先煨八句钟。）", "14033": "金朗然母偶发脘疼呕吐。医予温补药。初若相安。渐至畏寒不寐。四肢不仁更医云是风痹。仍投温补。因而不饥不食。二便不行。肌肉尽削。带下如溺。孟英诊之。曰：暑伏肺胃耳其多投温补而不遽变者。以熟地等阴柔腻滞为之挟制也。然津气灼烁而殆尽。脂液奔迫以妄行。治节无权。阳明涸竭。予白虎汤加西洋参竹茹橘皮丝瓜络石斛花粉竹沥海䖳。（脘疼呕吐。本系阴虚肝阳犯胃。先后温补。愈助肝阳灼烁肺胃阴液。案叙病情六语。热邪皆在上焦气分。生石膏先煎八钱。姜炒知母四钱。西洋参三钱。姜竹茹四钱。赖橘红一钱五分。丝瓜络三钱。钗石斛杵先一两。南花粉四钱。姜竹沥两大酒杯和服。淡海䖳先煎二两。）连进二十剂。始解黑矢。各恙渐安。嗣予和肝胃调八脉以善后遂愈。", "14034": "赵子善因事抑郁。凛寒发热。汤某作血虚治。进以归芎丹参之类。多剂不效。孟英诊之。脉涩而兼沉弦以数。然舌无胎。口不渴。便溺如常。纳谷稍减。惟左胁下及少腹自觉梗塞不舒。按之亦无形迹。时欲抚摩似乎稍适。曰：阴虚挟郁。暑邪内伏。夫郁则气机不宣。伏邪无从走泄。连投血药。引之深入。血为邪踞。更不流行。胁腹不舒。乃其真谛。第病虽在血。治宜清气为先。气得展布。热象必露。瘀滞得行。厥疾始瘳。连投清气。（方用酒炒枯芩一钱五分。姜炒牛蒡子研三钱。姜栀皮三钱。姜炒枇叶刷包三钱。姜炒川连六分。姜竹茹三钱。川贝母杵四钱。苦杏泥次入二钱。薄橘红次入一钱五分。紫菀茸次入一钱。）热果渐壮。谵妄不眠。口干痰嗽。孟英曰：脉已转为弦滑。瘀血伏邪皆有欲出之机。继此当用凉血清瘀为治。遂定犀角地黄加味。（大生地开水泡冲八钱。镑犀角磨冲一钱。酒炒川连八分。酒炒川黄柏一钱五分。石菖蒲一钱次入。半夏曲二钱。川贝母杵八钱。生冬瓜子四钱。姜竹茹三钱。丝瓜络三钱。姜汁拌姜根八钱。紫菀一钱。旋覆绢包三钱。）适病者鼻衄大流。径煎服之。次日衄复至。苔色转黑。孟英曰：三日不大便。瘀热未能下行也。于前方加滑石桃仁木通海䖳竹沥石斛银花知母花粉。（前方宜去连柏竹茹丝瓜络芦根。加西滑石先煎四钱。生桃仁研三钱。细木通一钱。淡海䖳先煎二两。姜竹沥两大酒杯冲。钗石斛杵先一两。银花八钱。酒炒知母三钱。南花粉四钱。）又二剂大解始行。黑如胶漆。三日间共下七十余次而止。乃去木通桃仁辈。加西洋参麦冬以生液。（加西洋参三钱。花麦冬五钱。）病者疲惫已极。沉寐三昼夜。人皆危之。孟英曰：听之。使其阴气来复。最是好机。醒后尚有微热谵语。药仍前法。又旬日始解一次黑燥大便。而各恙悉退。惟口尚渴。予大剂甘凉以濡之。又旬日。大便甫得复行。色始不黑。乃用滋阴填补而康。（此病必系阳证阳脉。故以大剂辛寒收效。若阳证阴脉。阴药即苦伤阳。故多不治。）", "14035": "高若舟庶母年逾花甲。体丰善泻。张某向用参术取效。今秋患白痢。张谓寒湿滞中。仍予理中加减。病遂日增。因疑高年火衰。蒸变无权。前药中复加附子。白痢果减。而腹胀且疼。不食不溺。哕逆发热。势已危殆。孟英视之。脉沉而滑数梗梗。曰：暑热未清。得毋补药早投乎。予芩连杏朴曲芍滑楝银花海䖳鸡金之类。（白痢果减四句。热邪皆在气分。玩腹胀且疼上而字。则白痢不当止可知。脉沉而滑数梗梗。则实热结遏。不能自行宣达又可知。方用姜炒枯芩一钱五分。姜炒川连八分。苦杏泥二钱。姜制根朴一钱。生神曲杵一钱五分。酒炒白芍一钱五分。西滑石先煎四钱。川楝核先三钱。济银花八钱。淡海䖳先煎一两。炙鸡金研三钱。）一剂溺行痛减。痢下仍白。孟英曰。病机隐伏。测识匪易。前此之止。非邪净而止之止。乃邪得补而不行之。邪气止而不行。是以痛胀欲死。夫强止其痢。遽截其疟。犹之乎新产后妄涩其恶露也。世人但知恶露之宜通。而不知间有不可通者。但知疟痢之当止。不知邪未去而强止之。其害较不止为尤甚也。今邪未清涤。而以温补药壅塞其流行之道。以致邪不能出。逆而上冲。哕不能食。是痢证之所畏。吾以通降凉润之剂。搜邪扫浊。惟恐其去之不速。病家勿以白痢为忧。寻愈。", "14036": "徐有堂妻病痢。医作寒湿治。广服温补之剂。痢出觉冷。遂谓沉寒。改投燥热。半月后发热无溺。口渴不饥。腹疼且胀。巅痛不眠。孟英察脉弦细。沉取甚数。舌绛无津。肌肉尽削。是暑热胶锢。阴气受烁。予北沙参苁蓉芩斛楝芍银花桑叶丹皮阿胶合白头翁汤为剂。（发热无溺四句。暑邪大伤气分之阴。弦细为阴虚。沉取甚数为温补胶锢其暑热之象。腹疼为暑热胶锢。胀及巅痛不眠。为肝阴受烁。苁蓉补肝阳。作胶斛沙参反佐。使芩楝无偏于苦寒流弊。北沙参八钱。淡苁蓉三钱。酒炒枯芩一钱五分。鲜钗斛杵先一两。酒炒川楝核杵先三钱。整大白芍杵先八钱。济银花一两五钱。冬桑叶四钱。粉丹皮二钱。酒炒白头翁一钱。）次日各患皆减。痢出反热。孟英曰。热证误投热药。热结为大便不行者有之。或热势奔迫而泄泻如火者有之。若误服热药而痢出反冷者。殊不多见。无怪医者指为久挟之沉寒。吾以脉证参之。显为暑热。然暑热之邪本无形质。其为滞下也。必挟身中有形之垢浊。故治之之道。最忌补涩壅滞之品。设误用之。则邪得补而愈炽。浊被壅而愈塞。耗其真液之灌溉。阻其正气之流行。液耗则出艰。气阻则觉冷。大凡有形之邪。皆能阻气机之周流。如痰盛于中。胸头觉冷。积滞于腑。脐下欲熨之类。皆非真冷。人不易识。吾曾治愈多人矣。仍议育阴涤热。病果渐瘳。", "14037": "萧某素患痰多。常服六君子汤。孟英诊之。脉细数而兼弦滑。曰：六君极当屏绝。病由阴亏火盛。津液受灼而成痰。须服壮水之剂。庶可杜患将来。萧吸鸦片。自疑虚寒。滋阴不敢频服。继患喉痛。专科治而不效。孟英诊曰：早从吾策。奚至是耶。此阴虚于下。阳浮于上。喉科药不可试也。大剂育阴潜阳。（脉细数为阴分挟虚。弦滑为气分挟痰热。专科治而不效。必用温散套药。以致阳浮于上。淡海䖳二两。连皮荸荠一两。酒炒枯芩一钱五分。黑栀皮三钱。冬桑叶四钱。地骨皮四钱。粉丹皮二钱。旋覆花绢包三钱。钗石斛血龟板多杵各一两。先煨八句钟。济银花八钱。）其痛日瘥。而喉腭皆形白腐。孟英曰：吸烟既久。毒气熏蒸之故耳。令吹锡类散始得渐愈。愈后复患滞下。孟英曰：今秋痢虽盛行。而此独异于人。切勿以痢药治之。盖火迫津液结为痰饮。酿以烟毒。熏成喉患。吾以然犀之照。而投激浊扬清之治。病虽愈矣。内蕴之痰浊尚多。奈向来为温补药所禁锢于肠胃曲折之间而不得出。今广投壮水之剂。不啻决江河而涤陈莝。岂可与时行暑热之痢同年而语耶。（时行暑热之痢为实邪。宜清涤。此证温补耗液为内伤。宜育阴。）治不易法。食不减餐。日数十行。精神反加。逾月之后。大解始正。计服甘凉约二百剂。（此为偏证偏治。未可以平证例也。）肌肉复充。痰患若失。", "14038": "孙位申患感。证见耳聋。医者泥于少阳小柴胡之例。聋益甚。孟英视之。曰：伏暑也。与伤寒治法何涉。改投清肺之药。聋减病安。（耳聋治肺。诊断伏暑。必有脉证可凭。此必小柴胡汤中多用参草枣胶锢暑邪。酒炒知母三钱。鲜芦根二两。鲜枇叶刷包三钱。生石膏先煎八钱。西滑石先煎四钱。姜竹茹三钱。淡吴萸次入六分。陈香薷次入三分。鲜荷梗三钱。）将进善后法矣。忽一日耳复聋。询悉误服葛粉一碗。不啻误服小柴胡一剂。复投肃清肺胃药。寻愈。（酒炒知母三钱。生石膏先煎八钱。南花粉四钱。姜竹沥一大酒杯冲。生苡仁杵八钱。西滑石先煎四钱。花麦冬三钱。钗石斛杵先八钱。浮石蛤壳各五钱同先煎。）", "14039": "顾宗武偶患微寒发热。医进温散法。热虽退而不饥不大便。复用平胃散数帖。腹渐胀而偏于右。尚疑其中气之虚寒也。遂予温运燥补诸药。胀乃日增。杳不进谷。外科连某作胁疽治。病如故。黄某作肠痈论。以大黄泻之亦不应。严某谓胁疽部位不对。肠痈证据不符。作内疝治。仿子和活人之法及当归龙荟丸相间投之。亦无效。孟英视之。脉极弦细而促。舌绛大渴。小溲赤少。饮而不食者月余矣。证实脉虚。坚辞不治。（脉极弦细而促。为阴津已竭。即系脉虚。舌绛大渴为肺肾阴竭热炽。小溲赤少为肝肾阴竭热炽。合之为证实脉虚。）孟英曰：据述病人素慎起居而薄滋味。显非停滞与痈疽之患。良由暑湿内蕴。热欲外泄。是以初起有微寒发热之候。（斯时宜以酒炒知母三钱。炒香豉三钱。黑栀皮一钱五分。姜竹茹三钱。鲜荷梗三钱。晚蚕砂五钱。西滑石先煎四钱。酒炒桑枝三钱等药迎而导之。）误予风寒药。（必误一派温散。）热虽暂退于表。邪仍伏处于中。不饥不便。肺胃失其下行。（斯时宜投清肃肺胃。如姜炒枯芩一钱五分。姜炒川连八分。姜炒枇叶刷包三钱。鲜芦根二两。生冬瓜子四钱。姜竹沥一酒杯冲。薄橘红一钱。旋覆花绢包一钱五分。鲜荷梗三钱。淡吴萸次入四分。西滑石先煎五钱等药投之。）加误辛燥温补。气机更形窒滞。伏邪永无出路。以暑湿流行之脏腑。为暑湿割据之窝巢。补之不可。攻之不能。逾旬径殁。", "14040": "戚妪病痢。某以年老为舍病顾虚之治。渐至少腹结块。攻痛异常。大渴无溺。杳不知饥。昼夜百余行。五色并见。呼号欲绝。孟英诊之。脉至沉滑而数。因谓曰：纵使暑湿深受。见证奚至是耶。此必温补所酿。夫痢疾古称滞下。明指欲下而涩滞不通。顾名思义。岂可以守补之品。更滞其气。燥烈之药。再助其虐。少腹聚气如瘕。痢证初起。因于停滞者有之。今见于七八日之后。时欲冲逆。按之不硬。则显非停滞之可拟。实为药剂之误投。诸方果是参术姜萸附桂粟壳故纸川椒乌梅等一派与病刺谬之药。但知年老元虚。不闻邪盛则实。幸未呕哕。尚可希冀一二。遂予苁蓉楝芍芩连橘斛楂曲延胡绿梅鳖甲鸡金鼠矢海䖳出入互用。数帖渐安。（舍病顾虚最谬。邪能伤正。邪不去则虚者愈虚。少腹结块七语及脉至沉滑而数一语。皆温补助热耗伤肺胃阴分之象。脉沉滑为热痰结伏。数为阴虚挟热。幸未呕哕。尚可希冀一二者。热痢误投温补。全仗胃气通润下行。方得热蠲阴复。呕哕则肝阳贼胃。胃且自失其用。何能通润下行。酒炒枯芩三钱。酒炒川连一钱。陈橘皮一钱。生山楂杵一钱五分。生神曲杵二钱。三味同次入。整大白芍杵先二两。两头尖三钱。钗石斛杵先一两。更方去岑连橘皮。加绿萼梅次入一钱五分。川楝核杵先四钱。再更方去楂曲。加元胡索次入一钱五分。血鳖甲一两多杵。先煨六句钟。再更方去元胡绿梅。加泡洗海䖳。先煎二两。淡苁蓉三钱。炙鸡金研五钱。）继加驻车丸吞服。（前方每日以药送丸二钱。）逾月始健。", "14041": "周某患疟。间一日而作。寒少热多。医谓老年三疟。放手温补。渐至杳不进谷。孟英诊之。脉细硬如弦。毫无胃气。右尺洪数。舌色光绛。大渴溺滴。（脉细硬如弦。胃阴竭。右尺洪数。肾阴竭。舌色光绛。心肾阴竭。大渴溺滴。肺肝阴竭。）孟英曰：证本足少阴暑疟。（宜如另案治足少阴暑疟。用酒炒知母四钱。石斛龟板各一两。地骨皮五钱。冬桑叶四钱。银花八钱。天冬六钱。丹皮二钱。大锅煎而频灌。）广服温补。津液尽劫。欲以草木生之。事不及矣。世但知治疟不善有三患。邪留肝络则为疟母。戕及脾元则为疟鼓。耗乎肾阴则为疟劳。此证以药助邪。求转三患。亦不能得。所谓热得补而更炽。阴受烁以速亡。阴愈亡则邪愈炽。逾日果殁。", "14042": "陈茂才患头痛。三日一发。发则恶寒。多药不效。孟英察脉甚弦。重按则滑。曰：热暑伏厥阴也。若用温补。皆为戈戟。予左金加楝芍栀桑羚丹菊橘为剂。兼吞当归龙荟丸。三服而减。旬日即痊。（三日一发者。邪正相争。正能胜邪则止。正不胜邪则发。发则恶寒者。热伤肺。肺气不能宣达则恶寒。脉甚弦。为暑伏厥阴。重按则滑。为肝挟热痰。龙荟中有大黄。故以煎方送龙荟丸。酒炒川连一钱。淡吴萸次入四分。川楝核杵先三钱。整大白芍杵先八钱。黑栀皮一钱五分。冬桑叶四钱。磨羚角冲一钱。粉丹皮二钱。杭菊花四钱。赖氏橘红次入一钱。药送龙荟丸三钱。）", "14043": "余某年三十余。发热数日。医投凉解。遂呕吐自汗。肢冷神疲。孟英诊脉微弱。曰：内伤也。岂可视同伏暑。予黄耆建中去饧加龙骨生姜伏苓橘皮。投剂即安。（辨阳虚内伤。在脉微弱。炒干姜五钱。炒厚附片五钱。炒黄耆三钱。制半夏米杵三钱。浓姜汁煅龙骨杵先四钱。连皮生姜三钱。炒云苓三钱。炒焦陈皮一钱五分。肉桂心次入一钱。）续加参术。（前方去龙骨。加炒潞党三钱。炒白术二钱。）逾旬而愈。", "14044": "钱氏怀妊四月。患寒热如疟。医予发散安胎。乃至舌黑神昏。大渴便泄。臭痰频吐。腰腹痛坠。孟英诊曰：伏暑失于清解。舌虽黑而脉形滑数。痰虽臭而气息调和。是胎尚未坏。犹可治也。重予气血两清之药。五剂而安。（舌黑神昏。腰腹痛坠。热踞血分。大渴便泄。臭痰频吐。热踞气分。舌虽黑而脉形滑数。为阳证阳脉。阳证阴脉则不治。痰虽臭而气息调和。玩臭痰频吐。是气息尚能频频送痰外出。若死胎阻气机往来之清道。何能臭痰频吐。镑犀角磨冲一钱。大生地泡冲去渣八钱。酒炒雅连八分。酒炒知母三钱。陈胆星炖和服八分。姜竹沥两大酒杯冲。川贝母杵一两。鲜茅根五钱。细木通一钱。石菖蒲次入一钱。）糜粥渐进。腰腹皆舒。胎亦跃跃。", "14045": "方氏女久患泄泻脘痛。间兼齿痛。汛事不调。极其畏热。治不能愈。孟英诊之。体丰脉不甚显。而隐隐然弦且滑焉。曰：此肝强痰盛耳。病家惑医说疑虚。不知医者每以漫无著落之虚字。括尽天下之病。且所谓虚者。不外阴阳。今肌肉不瘦。冬不知寒。是阴虚乎。抑阳虚乎。只因久泻。遂不察其脉证。佥疑为虚寒之候。须知痰之为病。最顽且幻。益以风阳。性尤善变。治必先去其病。而后补其虚。（此证肝阳犯胃则脘痛。泄泻为热寻出路。齿属胃肾。肝阳犯胃亦齿痛。脉弦为肝强。滑为痰甚。酒炒川黄柏一钱五分。川楝核杵先三钱。济银花八钱。青果核杵先三钱。生赭石杵先一两。陈胆星炖和服八分。赖橘红一钱。石菖蒲六分。药送礞石滚痰丸二钱。当归龙荟丸一钱。）病家不信。其秋颈下起核。又误温补百日。吐泻胶痰斗许而亡。", "14046": "鲍继仲患哮。每发于冬。医作虚寒治更剧。（其为热实可知。）孟英诊之。脉滑苔厚。溺赤痰浓。（皆热痰盘踞气分之象。）予知母花粉冬瓜子杏贝茯苓滑石栀子石斛而安。（姜炒知母三钱。姜汁炒花粉四钱。生冬瓜子八钱。苦杏泥次入二钱。赤茯苓三钱。西滑石先煎四钱。黑栀皮三钱。鲜钗斛杵先八钱。）孙渭川侄亦患哮。气逆欲死。口渴头汗。二便不行。（气分热炽阴伤。）径予生石膏橘贝桂苓知母花粉杏苑海䖳等药而愈。（生石膏先煎一两二钱。赖橘红一钱。川贝母杵八钱。粗桂木次入三分。白茯苓三钱。酒炒知母三钱。南花粉四钱。苦杏泥二钱。紫菀茸一钱五分。泡淡海䖳先煎八钱。）", "14047": "耳姓回妇病哮。自以为寒。频饮烧酒。不但病加。更兼呕吐泄泻。两脚筋掣。既不能卧又不能坐。孟英诊曰。口苦而渴乎。泻出如火乎。小溲不行乎。痰黏且韧乎。病者曰诚然。孟英曰。只因时值小寒。哮喘霍乱。人皆误指为寒。予北沙参生苡仁冬瓜子丝瓜络竹茹石斛枇叶贝母知母栀子芦根青果海䖳菔汁为方。一剂知。二剂已。（此证可治。除当日察脉外。全在痰黏且韧一语。凡热证体实阳旺则痰黏韧。体虚阳衰则痰稀清。热证阳旺可治。阳虚不治。北沙参四钱。生苡仁杵八钱。生冬瓜子四钱。丝瓜络三钱。姜竹茹三钱。鲜石斛杵先一两。姜枇叶刷包三钱。川贝母杵五钱。酒炒知母三钱。黑栀皮三钱。鲜芦根二两。青果杵先三枚。淡海䖳先一两。芦菔八钱。打汁和服。）", "14048": "吴芸阁因壮年时患梅疮。过服寒凉之药。虚寒病起。改投温补。如金液丹大造丸之类获安。医昧药为补偏救弊而设。漫无节制。率以为常。驯致血溢于上。便泄于下。食少痰多。喘逆碍卧。两足不能屈伸。童某犹云寒湿。进以苓姜术桂多剂。势益剧。且溲渐碧而色绿如胆汁。孟英诊之。脉弦硬无情。（胃阴已竭。）曰：从前寒药戕阳。今则热药竭阴矣。胃中津液。皆灼烁以为痰。五脏咸失所养。而见证如上。水源欲绝。小溲自然渐少。木火内焚。乃露东方之色。与章虚谷所治暑结厥阴。用来复丹攻其邪从溺出而见深碧之色者。彼实此虚。判分霄壤。寻果殁。（来复丹原方。玄精石一两。洋硫黄一两。生硝石一两。五灵脂一两。青皮陈皮各一两。醋糊丸米饮下。治伏暑泄泻身热脉弱。念按此必治阳虚伏暑。用此丹于阴药中。开泄其中焦之伏暑。使从二便疏泄。）", "14049": "戴氏妇年五十六。仲冬患感。初服杨某归柴丹参药一剂。继服朱某干姜苍术厚朴药五剂。遂崩血一阵。孟英诊之。脉形空耎促数。苔黑舌绛。足冷而强。息微善笑。询其汛断逾十载。（此证可治。在汛断十载。阴精基础。尚不亏损。）曰：冬温失于清解。营血暴脱于下。岂可与热入血室同年而语耶。必由误服热药所致。检各方叹曰：小柴胡汤与冬温何涉。即以伤寒论。亦不能初感即投。况以丹参代人参。尤为悖谬。夫人参补气。丹参行血。主治天渊。不论风寒暑湿。初起皆禁用血药。为其早用反致引邪深入也。既引而入。再误于辛热燥烈之数投。焉得不将其仅存无几之血。逼迫而使之尽脱于下乎。女人以血为主。天癸既绝。无病者尚不宜有所漏泄。况温邪方炽。而阴从下脱。可不畏哉。病家再四求治。孟英予西洋参生地苁蓉犀角石斛生芍银花知母麦冬甘草蔗浆童溺两剂。得解酱粪。（西洋参三钱。大生地六钱。淡苁蓉三钱。磨犀角冲五分。生白芍杵先四钱。酒炒银花五钱。酒炒知母一钱五分。整麦冬三钱。生粉草二钱。蔗浆冲大半酒杯。童溺一酒杯煎去沫冲药温服。）脉数渐减而耎益甚。乃去犀角。加高丽参。（宜加丽参三钱。）数帖脉渐和。热退进粥。随以调补得安。", "14050": "王开荣素患痰嗽。兼有红证。今夜病头痛发热。渴饮不饥。便溏溺少。谵语神昏。面赤痰喘。自述胸中冷气上冲。孟英诊之。脉滑且数。曰：温邪挟宿饮上逆。法当清解。予北沙参冬瓜子知母滑石花粉石菖蒲贝母杏仁芦根葱白淡豉竹沥。（脉滑为痰。数为阴虚挟热。头痛即系阴虚。以葱豉升知母苦寒于至高之分。始能解其发热面赤痰喘。北沙参八钱。生冬瓜子四钱。酒炒知母三钱。西滑石先煎四钱。石菖蒲次入一钱。川贝母杵五钱。南花粉四钱。苦杏仁一钱五分。姜汁拌芦根一两次入。连须葱白打二钱。淡豆豉三钱同次入。姜竹沥大半酒杯和服。）两剂后面赤退。乃去葱豉。加麦冬桑叶枇叶。（花麦冬三钱。冬桑叶二钱。鲜枇叶刷包三钱。）数帖热去泻减。谵语止。头痛息。喘定神清。乃去菖蒲。加梨汁地栗海䖳。（梨一两。荸荠二两。同绞汁冲。淡海溺先煎一两。）服数日痰渐少。谷渐安。渴止溺行。始进养阴之法遂愈。", "14051": "石子章患腹胀。朱某予大剂温补之药。殊若相安。孟英曰：形瘦脉数。舌色乾红。此为阴虚热胀。昔年范次侯妻暨杨改之妾之恙皆类是。多医攻补遍施。病无小效。吾以极苦泄热微辛通络之法投之。应手而瘳。（白头翁一钱。炒川黄柏一钱五分。川楝核杵先三钱。青果杵先三钱。生白蒺次入三钱。大生地开水泡汤煎药去渣八钱。鲜钗斛杵先一两。济银花八钱。元参片泡煎去渣一两。陈木瓜三钱。生赭石杵先一两。旋覆花绢包三钱。）今子初起时。胀不碍食。证非气分可知。误信温补不助胀。遂服之不疑。不知阴愈耗。（温补劫阴。）络愈痹。（阴虚者气随津布。津液耗则气不行。）胀虽不加。而肌愈削。（气不随津布则肉枯。）脉愈数。（温补伤阴则脉数。）干呛气急。（温补伤阴。阳日见其有余。阴日见其不足。则干呛气急。）与女子之风消息贲何以异耶。（女。子患阳有余阴不足。致水不涵木。则肝阳逆上。名内风。风消者。言内风能消耗其肌肉。肉阴类。息贲者。贲训奔。言肺气有升无降。若人之奔驰者言。以上皆温补劫阴所必致。）寻果不起。按喻氏嘉言始言男子亦有血蛊证。可见男女虽别。而异中有同。同中有异。临证者不可胶柱鼓瑟。", "14052": "沈某患脘痛呕吐。二便秘涩。诸治不效。孟英视之。脉弦耎苔黄腻。曰：此饮证也。岂沉湎于酒乎。沈云不饮酒。素以武彝红茶熬浓饮之。茶经蒸遏为红。味变甘浊。全失肃清之气。遂为酿疾之媒。医者不察。仅知呕吐为寒。姜萸沉附。不时与病相反。抑且更煽风阳。饮藉风腾。但升不降。是以上不能纳。下不能通。宛似关格。然非阴枯阳结之候。以连楝栀芩旋覆竹茹枇叶橘半苓泽蛤壳荷茎生姜衣为方。送服震灵丹。数剂平。匝月起。（方义苦寒泻风阳医药。辛温豁停饮医病。酒炒川连八分。黑栀皮三钱。酒炒楝核杵先二钱。酒炒枯芩一钱五分。旋覆花绢包三钱。姜竹茹次入三钱。姜枇叶刷包三钱。赖橘红一钱五分。制半夏四钱。白茯苓三钱。炒泽泻一钱五分。生蛤壳杵先五钱。鲜荷茎三钱。生姜皮五分。药送震灵丹三钱。）", "14053": "石芷卿骤患腹胀。旬日后脐间出脓。外科视为肠痈。予温补内托之药。遂咳嗽不眠。腹中绞痛异常。痰色红绿。大便不行。孟英诊之。脉弦细以数。舌绛而大渴。曰：察脉候是真阴大虚之证。耆术归桂。皆为禁剂。以甘露饮加西洋参花粉贝母杏仁冬瓜子投之。痰咳即安。外科谓此恙最忌泄泻。润药不宜多服。孟英曰：阴虚液燥。津不易生。虽求其泻。不可得也。乌可拘泥一偏。不知通变。仍以前法去杏贝花粉。加知母百合合欢为方。并属老医朱嵩年敷治其外。如法施之。果渐向安。久之当脐痂落。如小儿蜕脐带状。脐内新肉莹然而愈。（出脓较速。本非寒虚之证。加误温补。咳嗽不眠四句。热邪皆在气分。温补最易伤阴。大生地八钱。明天冬切六钱。开水泡冲去渣。花麦冬四钱。南花粉五钱。川贝母杵一两。苦杏泥次入二钱。钗石斛杵先一两。姜炒西茵陈二钱。姜炒枯芩一钱。姜炒枇叶刷包三钱。炒枳壳一钱五分。更方去川贝花粉。加姜炒知母一钱五分。百合花三钱。合欢皮三钱。敷药亦宜辛凉。）", "14054": "沈春旸母偶患咽喉微痛。服轻清药一剂。即觉稍安。且起居作劳如常。第六日忽云坐立不支。甫就榻即昏沉如寐。王瘦石用犀角地黄汤化万氏牛黄丸灌之。孟英切其脉左数右滑。皆极虚耎。（此证第六日甫就榻即昏沉如寐。阴虚之体。肝阳灼痰。逆升而厥。万不可拘先气后营常治之法。以犀角地黄清营。以牛黄化痰热。清营中仍兼清气。脉左数为血分挟热。右滑为气分挟痰。皆极虚耎。则阴液素虚。阳气不随津液为流布。阴虚病温。治最棘手。）曰：所见极是。但虽感冬温。邪尚轻微。因积劳久虚之体。肝阳内动。烁液成痰。逆升而厥。俨似温邪内陷之候。方中犀角靖内风。牛黄化痰热。不妨借用。病可无虞。今日不必再投药饵矣。翼日复诊。神气虽清。苔色将黑。（苔色将黑。此犀角地黄及牛黄丸之效力。犀角地黄息风充液。牛黄化痰热。阴稍复。热稍轻。乃能托邪外出。现此将黑之苔。）孟英予肃肺蠲痰。息风充液之剂。（姜竹茹三钱。姜竹沥一酒杯和服。干柿蒂一钱。淡海䖳先煎一两六钱。川贝母杵八钱。姜枇叶刷包三钱。酒炒知母三钱。半夏曲一钱五分。元参泡冲去渣五钱。黑栀皮三钱。陈胆星炖和服八分。乌梅三钱。赖橘红次入一钱。）热退而苔色松浮。孟英曰：舌将蜕矣。仍予前药。越宿视之。苔果尽褪。宛如脱液之舌。且呕恶时作。大解未行。孟英于甘润生津药内。仍佐竹茹竹沥柿蒂海䖳。（南花粉四钱。鲜芦根二两。生冬瓜子四钱。鲜钗斛杵先一两。炒枳壳一钱五分。赖橘红一钱五分。姜炒枯芩一钱五分。川贝母一钱。淡姜汁磨冲茹沥柿蒂海䖳同前方。）数剂呕止便行。而舌上忽布白腐之苔。以及齿龈唇颊满口遍生。揩试不去。孟英坚守肃清肺胃。仍佐茹沥加青果银花建兰叶。（姜枇叶刷包三钱。黑栀皮一钱五分。酒炒枯芩一钱五分。姜芦根八钱。陈胆星炖和服七分。苦杏泥一钱五分。赖橘红八分。姜竹茹三钱。姜竹沥一酒杯冲。济银花次入五钱。建兰叶次入三钱。）数剂白腐渐脱下。舌色始露。惟啜粥则胸次梗梗不舒。孟英曰：胃汁不充。热痰未净也。仍守前议。（前方去栀。皮芦根。加生姜自然汁磨冲枳实五分。连皮北梨一两。打汁和服。）既而吐痰渐少。纳谷颇适。两胁又添辣痛。孟英诊脉左关弦数。曰：必犯忿怒矣。诘之果然。加栀楝旱莲女贞生白芍绿萼梅等。（前方去枯芩橘红竹茹枳实。加黑栀皮三钱。川楝核杵先四钱。女贞子杵先五钱。旱莲草四钱。生白芍先煎八钱。绿萼梅次入二钱。）数服各恙皆安。肤蜕成片。而右腿肿痛。不能屈伸。或疑风气。思用艾炙孟英急止之曰。此阴亏耳。误炙必成废疾。但难速效。书方以西洋参熟地苁蓉桑葚石斛木瓜归芍二冬杞菊楝实牛膝无核白葡萄干为剂。久服果得向愈。（西洋参三钱。大熟地八钱。淡苁蓉三钱。干桑葚杵先三钱。鲜钗斛杵先一两。陈木瓜三钱。箱归身二钱。生白芍四钱。明天冬切六钱。花麦冬四钱。甘枸杞三钱。川楝核杵先四钱。杭白菊二钱。酒制牛膝一钱。无核白葡萄干三钱。）", "14055": "孙执中春前四日。忽患鼻衄如注。诸法莫塞。孟英视之。脉弦而数。曰：冬暖气泄。天令不主闭藏。今晚雷声大震。人身应之。肝阳乃动。投以元参生地犀角牡蛎知母生白芍牛膝茯苓侧柏叶童溺诸药。（元参片一两。大生地八钱。磨犀角冲一钱。煅牡蛎杵先六两。酒炒知母二钱。生大白芍一两。酒制牛膝一钱。白茯苓三钱。酒炒柏叶次入一钱五分。清童便一酒杯冲。）既而胁痛流乳。孟英予甘露饮加女贞旱莲三甲而瘳。（大生地一两。大熟地八钱。明天冬切六钱。女贞子杵五钱。旱莲草四钱。煅牡蛎八两。血鳖甲四两。血龟板二两。合石斛先炭煨八句钟。取汤代水煎药。石斛一两。酒炒枯芩一钱五分。蜜炙枇叶刷包三钱。大片生粉草三钱。）", "14056": "汪震官春前陡患赤痢。孟英诊之。脉滑数而沉。面赤苔黄。手足冷过肘膝。当脐硬痛。小溲涩少。伏热为病也。予大剂芩连栀楝滑石丹皮砂仁延胡楂曲银花草决明等药。两服手足渐温。而脚背红肿。起疱如蒲桃大一二十枚。四服后腹痛减。苔退而渴。于原方去楂曲砂仁。加白头翁赤芍海蜇。旬日后痢色转白。而腿筋抽痛。乃去丹皮滑石赤芍。加鸡金橘红生苡石斛。两服痛止溲长。粪色亦正。脚疱溃黄水而平。谷食遂安。改用养胃阴清余热之法而愈。每剂银花辄两许。尚须半月而瘳。（脉滑数而沉。为痰热遏伏兼挟阴虚。面赤为热伤肺气。苔黄为湿郁化热。手足冷过肘膝。此证必误补助邪。热伤肺气。气不外达下行。故冷过肘膝。当脐硬痛。为痰食结于腹中之明证。小溲涩少。热伤肺胃之阴。肺胃气失下行。酒炒枯芩一钱五分。酒炒川连八分黑栀皮三钱。川楝核杵先三钱。西滑石包先五钱。粉丹皮二钱。西砂仁研冲和服六分。玄胡索次入一钱五分。生山楂杵次入一钱五分。生神曲杵次入二钱。济银花一两。草决明三钱。手足渐温。为邪减气通。脚背红肿起疱。为热邪下行外泄。腹痛减。热邪伤阴。气不随津液流行。则邪不尽去。苔退而渴。热邪前因痰滞阻遏。故当脐硬痛。得迭次苦辛宣泄。邪浊渐减。则热邪仍返还于气分。此温病病情所必至。去楂曲砂仁。加白头翁赤芍海䖳。邪浊渐减。热邪已得宣达于气分。再用砂仁楂曲。则过剂伤阴。加白头翁赤芍海䖳者。病本赤痢。热邪已得宣达。恐其耗伤血液。故加白头翁息风泻热。赤芍入血行瘀。数脉为阴虚挟热。前因邪浊盘踞腹中。方藉砂仁楂曲辛温佐芩连楝苦寒以宣泄。斯时中焦胃脘不通。若遽用海䖳顾阴。则一派苦咸寒过剂。辛温失其佐使之权。寒凉不能涤秽。反行冰伏胸中。此际苔退而渴。热象得宣。不加海䖳。则热邪将耗肺胃之阴。应加酒炒白头翁一钱。赤芍三钱。淡海䖳先一两。腿筋抽痛。肝主周身之筋。此为肝胃之阴不足。去丹皮滑芍。恐凉泄伤脾。加鸡橘运脾宣气。苡斛清肝顾阴。鸡金三钱。橘皮一钱。生苡仁八钱。石斛一两。）", "14057": "郑妪患咳嗽。自觉痰从腰下而起。吐出甚冷。医作肾虚水泛治。渐至咽喉阻塞。饮食碍进。即勉强咽之。而胸次梗不能下。便溏溲频。无一人不从虚论。孟英诊曰：脉虽不甚有力。右部微有弦滑。苔色黄腻。岂属虚证。以苇茎汤合雪羹加贝母知母花粉竹茹麦冬枇杷叶柿蒂等药。进十余剂而痊。（右部微有弦滑。苔色黄腻。为痰热实证。但痰热不达极点。姜汁拌芦根五钱。生冬瓜子四钱。连皮荸荠打一两。淡海䖳先煎八钱。川贝母杵五钱。姜汁炒知母三钱。南花粉三钱。姜竹茹次入三钱。姜枇叶刷包次入三钱。干柿蒂十枚。姜汁拌花麦冬一钱。前医作肾虚水泛治必误用温补脾肾之药。故现证如是。肾虚水泛。左尺脉必虚耎。右脉亦必无力。水泛则痰为虚痰。）", "14058": "满洲少妇怀娠漏血。医投补药。漏如故。间或不漏则吐血。延逾二载。腹中渐动。孕已无疑。然血久溢于上下。甚至纳食即吐。脉滑数有力。是气实而血热也。证不属虚。补药反能助病。愈补愈漏。胎无血荫而不长。其所以不堕者。气分坚实耳。予大剂清营药。血溢遂止。而稀沫频吐。得饮即呕。口渴心忡。气短似促。乃用西洋参麦冬知母石斛枇杷叶竹茹柿蒂生白芍木瓜重加乌梅投之。复杯即安。（辨证原案已尽。治病常法。先卫后营。此入手即予清营。此保胎变法之治。清营方。大生地八钱。开水泡冲去渣。鲜茅根五钱。鲜竹茹三钱。丝瓜络三钱。地骨皮五钱。粉丹皮二钱。生赤芍先八钱。酒炒黄柏三钱。生藕汁一大酒杯冲。童便两酒杯煎。去头尾冲药温服。清气方。西洋参三钱。花麦冬三钱。酒炒知母四钱。鲜石斛杵先一两。鲜枇叶刷包三钱。鲜竹茹三钱。干柿蒂十个。生大白芍二两先煎。陈木瓜三钱。乌梅肉杵先五钱。血溢止而稀沫频吐。得饮即呕。口渴心忡。气短似促者。原案气实血热。是气血两热。清营后血分之热虽减。气分之热未除。且血分之热虽减。余热仍从气分上行。故现以上诸证。其清气方中参用洋参麦冬石斛柿蒂者。必前医作肾虚水泛治时。误用温补。大伤肺胃之阴。重用知母乌梅木瓜白芍酸苦。泄肝即以清肺。则不致得饮即呕。气短似促。知母与麦冬柿蒂洋参石斛同用。义取苦甘化阴。则不致口渴心忡。）", "14059": "男子患便血。医投温补。血虽止而反泄泻浮肿。延及半年。脉数舌绛。此病原湿热。温补翻伤阴液。与芩连栀芍桑叶丹皮银花石斛楝实冬瓜皮鳖甲鸡金等药。旬余而愈。（脉数舌绛。均属阴虚挟热。酒炒枯芩一钱五分。酒炒川连六分。黑栀皮一钱五分。川楝核杵先二钱，整大白芍杵先八钱。冬桑叶四钱。丹皮二钱。济银花一两。鲜石斛杵先一两。冬瓜皮三钱。血鳖甲一两杵。先煨八句钟。炙鸡金研三钱。）", "14060": "陆厚甫室产后经旬。偶发脘痛。专科予温补药。因寒热气逆。自汗不寐。登圊不能解。而卧则稀水自流。口渴善呕。杳不纳谷。脉弦数而滑。本属阴亏肝阳侮胃。误投温补涩滞之剂。气机全不下降。以致诸证蜂起。予沙参竹茹楝实延胡栀连橘贝杏斛枇杷叶。为肃肺以和肝胃法。复杯即安。但少腹隐隐作痛。于前方去杏贝竹茹。加知母花粉苁蓉白芍橘核海蜇。乃解宿垢而瘳。（阴亏肝阳侮胃为远因。温补窒肺为近因。治法近因较重。北沙参四钱。姜竹茹四钱。川楝核杵先三钱。黑栀皮三钱。酒炒川连一钱。赖橘红一钱。苦杏泥二钱。川贝母杵八钱。鲜石斛杵先一两。姜枇叶刷包三钱。元胡索七分。沙参竹茹橘贝杏枇肃肺。楝栀连斛和肝胃。延胡反佐为使。少腹隐隐作痛。此是好消息。盖口渴善呕。杳不纳谷。皆热邪上阻清道之象。兹则少腹隐痛。热邪得肃肺以下行。惟阴亏者。气必资津液以濡布。津液不复。则气无所实以下行。加酒炒知母三钱。南花粉三钱。淡苁蓉一钱半。整大白芍杵先八钱。橘核杵次入一钱。淡海䖳先煎一两。苁蓉为花粉海䖳反佐。橘核为知母白芍反佐。）", "14061": "周子朝患恶寒头痛发热。酷似伤寒。而兼心下痛胀。脉右部沉滑。苔黄不渴。溲如苏木汁。先以葱豉汤加栀连杏贝蒌橘为方。服后微汗。而不恶寒反恶热。虽汤饮略温。即气逆欲死。客邪解矣。清其痰热可也。与知母花粉杏贝旋滑斛橘枇杷茅根芦根地栗海蜇等药。果吐胶痰甚多。惟动则欲喘。于肃上之中佐以滋下。为善其后而瘥。（头痛多属肝阳。心下痛胀。为肝阳侮胃。脉右沉滑。为痰热结伏气分。与苔黄不渴溲如苏木汁同为伏热。故先以葱豉合黄连之苦寒以升泄之。鲜葱白二钱。淡豆豉三钱。黑栀皮三钱。姜炒川连二钱。苦杏泥二钱。薄橘红一钱。川贝母杵四钱。姜蒌皮三钱。不恶寒反恶热三句。为痰热得清解而愈宣达之象。酒炒知母三钱。南花粉三钱。苦杏泥二钱。赖橘红一钱五分。川贝母杵五钱。旋覆花绢包三钱。西滑石先煎四钱。鲜石斛杵先五钱。姜炒枇叶三钱。姜汁拌芦根八钱。连皮荸荠打二两。淡海䖳一两。动则欲喘。前方去橘红滑石枇叶芦根。佐生蛤壳杵先一两。生赭石杵先八钱。血鳖甲杵先一两。元参片八钱。明天冬切六钱。乌梅肉杵先一两。）", "14062": "胡振华以花甲之年。患溺后出血水甚痛。自云溲颇长激。似非火证。孟英察脉有滑数之象。予元参生地犀角栀楝槐蕊侧柏知母花粉石斛银花甘草梢绿豆等药。旬日而痊。逾四载以他疾终。（此必气体偏阳。滑数有力之脉。方义取苦甘寒为治。元参片一两。大生地八钱。磨犀角冲二钱。黑栀皮一钱五分。川楝核杵先二钱。酒炒陈槐花一钱五分。酒炒侧柏叶八分。酒炒知母三钱。济银花一两五钱。生草梢三钱。连皮绿豆四两。煮汤代水煎药。）", "14063": "管氏妇自去秋患赤痢。多医罔效。延至暮春。孟英诊脉弦数。苔黄渴饮。腹胀而坠。日热夜甚。用白头翁汤合金铃子散加苓芍栀斛吞驻车丸。浃旬而愈。（此证热邪大伤气分之阴。其人体气必实。酒炒白头翁一钱五分。酒炒川连八分。川楝核杵先三钱。酒炒枯芩一钱五分。元胡索次入一钱五分。整大白芍杵先二两。黑栀皮三钱。鲜钗斛杵先一两。药送驻车丸三钱。方义取驻车丸内有干姜。可以行使一派苦寒。）", "14064": "濮树堂病。起即四肢厥逆。脉伏恶寒。发热头痛左为甚。惟口渴。因予葱豉二剂。热虽退。脉仍伏。四肢冷过肘膝。大解频行。人皆疑为虚寒。孟英曰：此证俨似阴厥。然渴饮溲赤。真情已露。岂可泥于一起即厥。而必定其为寒乎。径投凉解。热果复发。而肢冷脉伏如故。幸病者坚信。服药不疑。至第七日大便泻出红水。溺则管痛。呕恶烦躁。彻夜不瞑。人更危之。孟英曰：热邪既已下行。可望转机。以白头翁汤加银花通草芩芍茹滑知斛栀楝羚角之类投三日。红水始止。四肢渐和。颇有昏瞀谵语。用王氏犀角地黄汤一剂。四肢热而脉显滑数。苔转灰黄。大渴遗溺。病人自述如卧烘箱上。于昨方加入元参银花竹叶生石膏知贝栀斛。服一剂。夜间即安寐。而苔转黑燥。于昨方复加花粉。服一剂。热退而头面汗多。懒言倦寐。小溲欲解不通。孟英论曰：此证幸初起即予诊视。得尽力以为死里求生之举。非比他人之病。皆因误治致危。然不明言其险者。恐病家惶惑。而筑室于道旁也。今生机已得。不过邪去真阴未复。但当恪守予法。自然水到渠成。切勿二三其德。以致为山亏篑。赖有一二知音。竟从孟英议。服西洋参生地苁蓉麦冬楝芍知斛药。一剂溺行索粥。再服而黑苔退。三服而神清音朗。舌润津回。唯有韧痰不能吐。左偏头微痛。于原方加二至桑菊贝母牡蛎。又复五剂。得解硬矢一次。各患始安。眠食渐适而瘳。（渴饮溲赤合肢厥。为伏热铁券。葱豉凉解方。鲜葱白次入三钱。淡豆豉三钱。黑栀皮三钱。酒炒知母三钱。酒炒川连八分。苦杏泥一钱五分。赖橘红八分。石菖蒲次入二钱。炒枳实一钱五分。连皮荸荠二两打。淡海䖳先煎一两。念按：病家俗见万不能除。即孟英当日立方。定有不便放胆放手之处。仅能从轻清宣解立方。若初治参用雪羹荸荠海䖳名雪羹汤。以辛苦合凉润并用。病人得周身透汗。伏热即从汗孔尽泄。徐灵胎所谓燥邪即用滋清以作汗。患温头痛。麦面肝阳。内容即系阴虚。念每治温病头痛。除用苦辛轻剂清解外。率用元参生地一两。二者只用其一。以开水泡汤去渣。用汤煎药。取孟英另案浊药轻投。清上实下。一举两全之义。阴虚轻重。准前法为增减。屡用屡效。不敢自秘。此证若初治参用轻清汗解。未必伏热宣达。如本案所云之重。盖感证无汗。阳虚者补阳以作汗。阴虚者补阴以作汗。喻氏嘉言云三分外感。七分内伤。内伤为重。孟英明哲。断非见不及此。念论及此。见病家破格专任之难。惟念既拟立前方。本案各方不便挨拟。读者悉心揣摩。参观念注另案自悉。）", "14065": "王开荣偶患腹中绞痛。自服治痧诸药。而大便泻血如注。孟英诊之。左颇和。右关尺弦大而滑。面色油红。喘逆不寐。予苇茎汤合金铃子散加银花侧柏叶栀斛芩连。二剂后面红退。血亦止。乃裁柏叶银花。加雪羹枯荷杆。又二剂始发热一夜。得大汗周身。而腹之痛胀爽然若失。即能安寐进粥。改投沙参知母花粉桑叶枇杷叶石斛白芍橘络杏仁冬瓜子茅根荷杆。三剂大解行而脉柔安谷。（痧分寒热两大门。寒痛痛止不移。热痛痛必不静。此阳动阴静之定理。此证腹中绞痛。本系热痛。自服治痧诸药。必误服治寒痧之药。大便泻血如注。肺与大肠相表里。香燥大伤肺阴。脉弦大为肝热挟虚。滑为肺有热痰。面色油红二句。皆肺阴大伤之明证。活水芦根二两。生冬瓜子八钱。生桃仁研三钱。济银花一两五钱。酒炒侧柏叶次入一钱五分。川楝核杵先四钱。酒炒元胡索次入一钱五分。黑栀皮三钱。鲜石斛杵先一两。酒炒枯芩三钱。酒炒川连一钱。二剂面红退血亦止。方义以清肺阴为君。泻肝热为臣。佐以银花石斛栀皮。使以桃仁胡索。嗣裁柏叶银花。加雪羹枯荷杆连皮大荸荠二两打。泡淡海䖳二两。枯荷杆三钱。大凡涉及气阴血阴温病。必由阴分血分反还于气分。周身得汗乃解。沙参八钱。酒炒知母三钱。花粉四钱。桑叶三钱。枇叶刷包三钱。石斛杵先一两。酒炒白芍一钱半。橘络一钱。苦杏仁一钱半。生冬瓜子茅根荷杆各三钱。）", "14066": "陈叟久患痰嗽气逆。夏初因恶寒。自服理中汤。遂痰中带血。气喘而厥。二便不通。冷汗腹胀。孟英察脉洪大。按腹如烙。予苇茎汤加栀楝旋贝花粉海蜇。外以田螺大蒜车前草捣贴脐下。即溺行而平。（痰嗽气逆。则肺气不能充周于肌表。故畏寒。并非阳虚恶寒误服温补。现证如上。脉洪大为阴虚。按腹如烙。为热蒸气分。活水芦根二两。生冬瓜子八钱。黑栀皮三钱。川楝核杵先四钱。旋覆花绢包次入三钱。川贝母杵一两。南花粉四钱。淡海䖳先煎二两。整田螺三个。生车前草一握。生大蒜六瓣。田螺介以潜阳。咸以耎坚。车前草清凉导水。大蒜辛温反佐。同捣贴脐下。外以本青布当脐横扎。）", "14067": "高某患两膝筋络酸痛。略不红肿。卧则痛不可当彻夜危坐。孟英切脉虚细。苔色黄腻。咽燥溺赤。予知斛栀楝牛膝豆卷桑枝竹沥为方。送虎潜丸。旬日而瘳。（此证为阴虚挟热。以豆卷升知楝之苦寒于咽喉至高之处。证虽阴虚。苔色黄腻。滋腻难投。竹沥顾阴豁痰。两擅其长。酒炒知母三钱。鲜石斛杵先八钱。黑栀皮三钱。川楝核杵先二钱。生牛膝五分。大豆卷次入三钱。酒炒桑枝次入三钱。姜竹沥两酒杯冲。药送虎潜丸三钱。）", "14068": "杨某方作事。不知背后有人潜立。回顾失惊。遂不言不食。不寐不便。别无他苦。孟英按脉沉弦。以石菖蒲远志琥珀胆星旋贝竹黄杏仁省头草羚羊角为剂。化服苏合香丸。二剂大解行而啜粥。夜得寐而能言。复予调气宁神蠲饮药。数日霍然。（大凡因惊得病。非阴分不足。即素挟痰浊。脉弦为肝热挟虚。沉弦为热结为里。石菖蒲次入二钱。生远志肉一钱五分。西毛珀研冲八分。旋覆花绢包三钱。川贝母杵八钱。天竺黄三钱。陈胆星七分炖和服。苦杏仁二钱。省头草次入一钱五分。羚角先煎四钱。药化服苏合香丸五分。调气宁神蠲饮方。鲜枇叶刷包三钱。旋覆花绢包三钱。胆汁炒枣仁一钱五分。酒炒川连八分。石草蒲一钱。赖氏橘红一钱。川贝母杵一两。生冬瓜子四钱。）", "14069": "顾女患感十余日。耳聋不语。昏不识人。而客未入室。彼反先知医以为祟。凡犀角地黄牛黄清心复脉等汤遍服无效。延诊于孟英。脉至滑数。舌不能伸。苔色黄腻。遗溺便秘。目不交睫者已四昼夜。胸腹按之不柔。予白虎汤去米草加石菖蒲玄参犀角鳖甲花粉杏仁竹叶竹黄竹沥。投一剂即谵语滔滔。孟英论曰：不语者欲其语。是转机也。再投之大渴而喜极热之饮。渠父母又疑凉药非宜。孟英姑应之曰：再服一剂。更方可也。三投之痰果渐吐。四剂后舌伸便下。神识渐清。乃去菖蒲石膏犀角鳖甲加生地石斛麦冬贝母数剂。热尽退而痰味甚咸。又去杏贝竹黄加西洋参牡蛎龟板苁蓉。服之全愈。（原案叙脉证七语。皆肝风壅痰阻遏气机之象。生石膏先煎一两六钱酒炒知母四钱。石菖蒲次入二钱。玄参片一两。开水泡去渣冲。犀角先煎四钱。血鳖甲一两先炭煨六句钟。南花粉四钱。苦杏仁次入二钱。鲜竹叶二钱。天竹黄三钱。姜竹沥两大酒杯冲。初更方去菖蒲石膏犀角鳖甲。加大生地八钱。鲜石斛先煎八钱。花麦冬四钱。川贝母杵一两。再更方去杏贝竹黄。加西洋参三钱。煅牡蛎四两杵。血龟板二两杵。同先煨六句钟。取汤代水煎药。淡苁蓉一钱半。）", "14070": "邵鱼竹患感。杨某作疟治不应。孟英诊之。脉耎汗多。热不甚壮。苔色厚腻。呕恶烦躁。痰多腿酸。显是湿温。论曰：湿温者湿蕴久而从时令之感以化热也。不可从表治。更勿畏虚率补。予宣解一剂。各恙颇减。（此证前医必误作寒疟从表治。此证辨湿温。在热不甚壮及脉耎。宣解方。石菖蒲次入一钱。苦杏泥次入二钱。姜栀皮一钱五分。生苡仁杵四钱。酒炒川黄柏七分。建兰叶次入三钱。云苓片一钱五分。姜竹茹次入三钱。川贝母杵三钱。）", "14071": "叶杏江子患发热泄泻。医治十七日不效。骨瘦如柴。音嘶气逆。孟英诊之。脉数大渴。汗多苔黄。以竹叶石膏汤加减。十余剂渐以向愈。大解反极坚燥。继予滋养而康。（脉数为阴虚挟热。余皆热炽肺伤之象。鲜竹叶二钱。生石膏先煎一两二钱。酒炒知母四钱。活水芦根二两。鲜枇叶刷包三钱。海浮石生蛤壳。各五钱。同杵先。旋覆花绢包先煎三钱。淡海䖳先煎一两。）", "14072": "张某患发热。医知其非寒邪也。用清解药数剂。腿痛异常。身面渐黄。孟英诊之。脉滑实。腹胀口干。予茵陈大黄汤两剂。便行而各恙霍然。（辨腑实在脉实。若非脉实虽腹胀并非下证。此证脉系胃实。清解则升浮之表热已清。热邪下行结实于胃腑。脏病及腑。故燥矢结于手阳明大肠。热邪上蒸而身面渐黄。胃主周身之机关。胃热下注。故腿痛异常。肝主周身之筋。腿痛似肝病实胃病。故肝病治胃。酒炒西茵陈二钱。酒炒栀皮三钱。西洋参三钱。生粉草三钱。生冬瓜子四钱。炒枳壳二钱。整大白芍杵先八钱。酒炒大黄先煎四钱。）", "14073": "冯媪患左目胞起瘰。继而痛及眉棱额角颠顶。脑后筋掣难忍。医投风剂。其势孔亟。孟英诊脉弦劲。舌绛不饥。予固本合二至桑菊犀羚玄参牡蛎鳖甲白芍知母石斛丹皮细茶等出入互用。匝月始愈。（病情本系肝阳勃升。风剂助纣为虐。脉弦劲二语。皆心肝阳邪逆升。气机不降之象。息风方能降气。霜桑叶四钱。杭白菊二钱。犀角先煎四钱。羚角先煎四钱。玄参片八钱。女贞子杵五钱。旱莲草四钱。煅牡蛎杵四两。血鳖甲二两。整大白芍一两。鲜石斛杵一两。四味同煨六句钟。取汤代水煎药。酒炒知母四钱。数帖去犀羚桑菊。加大生地一两。大熟地八钱。丹皮二钱。再更方去白芍。加明天冬切六钱。花麦冬四钱。终更方去丹皮。加陈细茶三钱。）", "14074": "濮妪于酷热之秋。浑身生疖如疔。痛楚难堪。小溲或秘或频。大便登圊非努挣不下。卧则不能收摄。人皆谓其虚也。孟英诊。脉滑数。舌紫苔黄而渴。予白虎加花粉竹叶栀子白薇紫菀石斛黄柏。十余剂而痊。（脉滑数苔黄而渴。为肺胃热实。舌紫为兼挟瘀血。白薇行瘀。知母泻肺热。黄柏泻肝热。生石膏先煎八钱。酒炒知母三钱。南花粉四钱。鲜竹叶二钱。酒炒栀皮三钱。酒炒白薇三钱。紫菀茸一钱五分。鲜石斛杵先一两。酒炒川黄柏一钱五分。脉数为阴虚挟热。花粉石斛顾阴。）", "14075": "姚女初秋患寒热而汛适至。医用正气散两剂。遂壮热狂烦。目赤谵语。甚至欲刎欲缢。势不可制。孟英按脉洪滑且数。苔色干黄尖绛。脘闷腹胀拒按。畏明口渴。气逆痰多。予桃仁承气汤加犀角石膏知母花粉竹沥甘菊。人谓热虽炽而汛尚行。何必大破其血而又加以极寒之药哉。孟英曰。叟勿过虑。恐一二剂尚不足以济事。果服两大剂始得大便。而神清苔化。目赤亦退。改用甘寒以清之。继而因为更衣。即脉滑苔黄而腹胀。更予小承气汤二剂。便行而各恙遄已。数日后又如故。仍投小承气汤二剂。凡前后六投下剂。才得波浪不兴。渐以清养而瘳。（此证体必阳实。误服温补。故现证用药如是。腹胀拒按为腑实。此方主泻痰热以息风阳。玄明粉一钱。生厢黄四钱。生粉草三钱。犀角先煎四钱。生石膏先煎一两六钱。酒炒知母四钱。姜汁炒花粉四钱。姜竹沥两大酒杯冲。姜汁按竹沥二成。甘菊瓣二钱。生桃仁研三钱。甘寒清胃方。酒炒知母三钱。南花粉五钱。鲜枇叶刷包三钱。鲜石斛先煎一两。活水芦根二两。苦杏仁二钱。姜竹沥一酒杯冲。连皮荸荠二两打入煎。更衣感寒脉滑苔黄腹胀方。生厢黄三钱。制厚朴八分。炒枳实一钱五分。酒炒知母三钱。生冬瓜子八钱。晚蚕砂三钱。省头草一钱五分。）", "14076": "董晓书妇素患脘痛。甚至运厥。今秋病腰疼腿木。胸闷气逆不能卧。胡某进温补药而喘汗欲脱。杳不思谷。孟英切脉。虚细中兼有弦滑。舌绛而渴乃阴虚挟痰耳。予沙参苁蓉木瓜石斛蛤壳蒺藜石英茯苓紫菀杏仁楝实首乌牛膝诸药。旬日而安。继加熟地黄。服之全愈。（此证平素脘痛运厥。为肝阳侮胃。秋证仍属肝阳。但较平素为重。温补反助肝阳。故现证如是。脉虚细为阴虚中挟阳虚。脉兼弦滑。为正虚。中兼挟肝经痰热。北沙参八钱。淡苁蓉一钱半。陈木瓜一钱半。鲜钗斛先煎一两。生蛤壳一两。紫石英三钱。同杵先。云茯苓三钱。紫菀茸一钱五分。苦杏仁二钱。川楝核杵先五钱。制首乌一钱半。生牛膝七分。继加大熟地八钱。）", "14077": "王苇塘患滞下。医投枳朴槟查之药。数服后肢冷自汗。杳不进谷。脘闷腹胀。小溲牵疼。孟英视脉细涩。舌绛无津。是高年阴亏。伏暑伤液。况平昔茹素。胃汁不充。加以燥烈之药。津何以堪。因予沙参银花苁蓉白芍石斛木瓜甘草楝实扁豆花鲜稻头数剂。痛闷渐去。汗止肢温。乃加生地阿胶麦冬柿饼葡萄干等以滋之。居然痢止餐加。惟舌色至匝月始津润复常。（脉细涩是阴虚中兼挟阳虚。楝实苦寒泻暑。北沙参八钱。济银花一两。淡苁蓉一钱半。整大白芍杵八钱。川楝核杵五钱。鲜石斛一两。三味同先煎。陈木瓜一钱半。生粉草三钱。扁豆花三钱次入。鲜稻头绢包三钱。嗣加大生地八钱。花麦冬三钱。柿饼肉去霜四钱。葡萄干三钱。四味同先煎。阿胶二钱炖和服。）", "14078": "一叟患滞下。色白不黏。不饥不渴。腹微痛而不胀。孟英切脉迟微。进大剂真武汤加参而愈。（辨阳虚在脉迟微。土炒干姜五钱。土炒熟附片五钱。炒白术三钱。炒云苓三钱。炒潞党三钱。陈木瓜三钱。鲜薤白三钱次入。炒故纸五钱研先。）", "14079": "朱浚宣母患滞下。医闻色白而予升提温补。旬日后肢冷自汗。液脱肛坠。群医束手。虑其虚脱。延诊于孟英。曰：药误耳。予大剂行气蠲痰清热之药。果渐吐痰而痢愈。又其弟同时患此。五色并见。神昏肢搐。大渴茎肿。腹痛后热。危险异常。孟英察脉细数。予白头翁汤加犀角生地银花石斛楝实延胡芩连滑石丹皮木通甘草梢等药。三剂后热退神清。溺行搐止。乃去犀角草梢丹皮滑石木通。加砂仁拌炒熟地山楂炭。服之渐安。半月而愈。（前证升提温补助热酿痰。行气蠲痰清热方。姜汁炒枯芩三钱。姜炒川连八分。赖橘红一钱。生白芥子二钱。黑栀皮三钱。柴菀茸一钱五分。姜竹茹三钱。姜竹沥两酒杯冲。南花粉四钱。鲜石斛先煎一两。两证阴虚同。但彼病在气。此病在血。此为病同经异。酒炒白头翁一钱五分。犀角先煎四钱。大生地八钱。济银花一两五钱。鲜石斛先煎一两。楝核杵先三钱。延胡索次入八分。酒炒枯芩一钱。酒炒川连八分。西滑石先煎四钱。粉丹皮二钱。细木通一钱。生粉草梢三钱。三帖后去犀角草梢丹皮滑石木通。加砂仁末二分拌炒熟地八钱去砂仁。焦楂肉杵次入一钱。）", "14080": "孙渭川年逾七旬。脉象六阴。按之如无。偶患音嘶痰嗽。舌绛无津。孟英用甘凉清润法。音开而嗽不已。仍予前药。转为滞下。色酱溺赤。脐旁坚硬。按之真心趯趯。舌犹枯绛。汤饮不饥。人皆危之。孟英曰：脏热由腑而出。痢不足虑。第高年阴液难充。不能舍凉润为方。苟犯温燥。其败可必。幸渠家平素恪信。竟服犀角地黄知母银花苁蓉花粉麦冬白芍石斛楝实等药十余剂。痢止而脐旁柔软。因去犀角加西洋参。又服两旬。始解燥矢而溲彻胃苏。又服半月。复得畅解。舌亦润泽而愈。（此凭证不凭脉。证多从证之治法。犀角先煎四钱。大生地八钱。酒炒知母四钱。济银花一两五钱。淡苁蓉一钱半。南花粉五钱。花麦冬四钱。整大白芍杵先八钱。鲜石斛先煎一两。川楝核杵先三钱。更方去犀角。加西洋参三钱。）", "14081": "潘祥衍患疟。孟英视曰：苔腻脉耎伏暑所化。不与正疟同科。风寒药一味不可犯。姜枣汤一滴不可啜。予知芩橘半滑朴杏斛花粉省头草一剂而病若失。（以知芩滑斛花粉针治伏暑。以橘半朴杏省头草针治脉耎。姜炒知母三钱。姜炒枯芩一钱半。西滑石先煎五钱。鲜石斛先煎一两。南花粉四钱。苦杏泥二钱。半夏曲一钱五分。蛀陈皮一钱。制厚朴八分。省头草一钱五分。五味同次入。）", "14082": "张与之母久患痰嗽碍卧。素不投补药。孟英偶持其脉曰：非补不可。予大剂熟地药。一饮而睡。孟英因论曰：脉细痰咸。阴虚水泛。非此不为功。从前服之增病者。想必杂以参术之助气。昔人云勿执一药以论方故处方者贵于用药之恰当病情。而取舍得宜也。（大熟地八钱。明天冬切六钱。淡苁蓉一钱半。制首乌一钱半。血龟板杵先二两。鲜钗斛先煎一两。地骨皮五钱。川贝母杵四钱。肥玉竹三钱。盐水炒陈皮一钱半。旋覆花绢包三钱。灵磁石一两。乌梅肉一钱半。同先煨六句钟。）", "14083": "陈足甫室怀妊九月而患疟。目不能瞑。口渴自汗。便溏气短。医进育阴清解法数剂不应。改用小柴胡一剂。而咽疼舌黑。心头绞痛。孟英过诊。曰：右脉洪滑。虽舌黑而胎固无恙也。病由伏暑。育阴嫌其滋腻。小柴胡乃正疟之主方。古人谓为和剂。须知是伤寒之和剂。在温暑等证。不特手足异经。而人参半夏姜枣。皆不可轻用之药。虽有黄芩之苦寒。而仲圣于伤寒之治。犹有渴者去半夏加栝蒌根之文。古人立方之严密。何后人不加体察耶。投以竹叶石膏汤。四剂疟止便秘。口渴不休。予甘凉濡润法数剂。忽腹鸣泄泻。或疑寒凉所致。孟英曰：吾当以凉药解之。人莫识其意。问难终朝。语多不备录。果以白头翁汤两啜而愈。迨季娩秋后发热不蒸乳。恶露淡且少。家人欲用生化汤。孟英急止之曰：血去阴更伤。岂可妄疑瘀停而攻之。予西洋参生地茯苓石斛女贞旱莲甘草为大剂。数日而安。继因触怒。少腹聚气如瘕。酸痛夜甚。人又疑为凉药凝瘀所致。孟英力为辨折。予橘核橘叶橘络楝实苁蓉木香栀炭乌药丝瓜络海䖳藕石斛两头尖等药。外以葱头捣烂贴之。两剂后腹中雷鸣。周身汗出而痛止。人见其汗。虑为虚脱。孟英视之曰：此气行而病解矣。但脉形细数。阴津大伤。苔黄苦渴。亟宜润补。奈枢机窒滞。滋腻难投。且以濡养八脉为法。服之各恙皆蠲。眠食渐适。（论证尽于原案。竹叶石膏汤加减，鲜竹叶二钱。生石膏先煎八钱。酒炒知母四钱。酒炒川连一钱。细木通一钱。苏荷尖次入八分。姜枇叶刷包三钱。姜竹沥两酒杯冲。活水芦根二两。甘凉濡润方酒炒知母三钱。酒炒枯芩一钱。鲜枇叶刷包三钱。枯荷杆三钱。姜竹沥两酒杯冲。南花粉四钱。连皮荸荠打二两。腹鸣泄泻。系热邪由腑而出。白头翁汤方加减。酒炒白头翁一钱五分。酒炒川黄柏二钱。川楝核杵先三钱。生白蒺三钱。玄胡索一钱半。酒炒桑枝三钱。石斛先煎一两。济银花八钱。青果杵先一个。娩后方。西洋参三钱。大生地八钱。云苓三钱。鲜石斛八钱。女贞五钱。旱莲四钱。生草三钱。少腹气痛方。橘核一钱。橘叶七片。橘络七分。楝核丝瓜络鼠矢黑栀皮各三钱。木香五分。乌药八分。淡海䖳藕各二两。石斛一两先煎。淡苁蓉一钱半。外以葱头三钱。捣烂扎帖少腹。）", "14084": "胡季权子甫六岁。目患内障。继则夜热痰嗽。小溲过多。医作童损治。服滋补数月。病日以甚。孟英持脉右大。口渴苔黄。曰伏热在肺。法当清解。及详诘其因。始言病起瘄后。盖余热未净。而投补太早。予滑石知母花粉桑叶茅根枇杷叶芦根冬瓜子杏仁。服二剂遍身发出斑块。又二剂斑退苔化。乃去滑石加沙参饵之。其热头面先退。次退四肢。以及胸背。又数日甫退于腹。人皆诧其热退之异。孟英谓热伏既久。复为半年之补药腻滞于其间。焉能一旦尽涤。其势必渐清而渐去也。热退既净。溺亦有节。痰嗽递蠲。餐加肌润。而内障亦渐除矣。（辨证在脉右大口渴苔黄。西滑石先煎二钱。姜汁炒知母二钱。姜汁炒花粉二钱。冬桑叶一钱五分。姜汁拌茅根二钱。姜汁炒枇叶刷包一片。姜芦根四钱。生冬瓜子二钱。苦杏泥次入一钱五分。）顾奏云季秋患感。医作虚治。补及旬日。舌卷痉厥。腰以下不能略动危在须臾。孟英设死里求生之策。察脉虚促欲绝。先灌紫雪一钱。随溉犀角地黄汤二大剂。服下厥虽止而舌腭满黑。目赤如鸠。仍用前汤。三日间计服犀角两许。黑苔渐退。神识乃清。而呃忒频作。人犹疑其虚也。孟英曰：营热虽解。气道未肃耳。以犀角玄参石斛连翘银花竹茹知母花粉贝母竹叶为方服之。次日即下黑韧矢甚多而呃忒止。又三剂连解胶黑矢四次。舌色始润。略进米饮。腿能稍动。然臀已磨穿矣。予甘凉育阴药。续解黑矢又五次。便溺之色始正。投以滋养。日渐向安。其弟翰云患左胯间肿硬而疼。暮热溺赤。舌绛而渴。孟英按脉细数。径用西洋参生地麦冬楝实知母花粉银花连翘甘草黄柏等药。服旬余而愈。（犀角先煎四钱。大生地一两。济银花一两五钱。紫丹参三钱。生白蒺次入三钱。陈木瓜三钱。地骨皮五钱。粉丹皮二钱。煅牡蛎杵六两。血龟板杵二两。鲜石斛杵一两。川楝核杵四钱。四味同先炭煨六句钟。取汤代水煎药。清气治呃方。犀角先煎四钱。玄参片八钱。开水泡冲去渣。鲜石斛先煎一两。连翘壳三钱。济银花一两五钱。姜竹茹三钱。酒炒知母三钱。花粉三钱。川贝母杵四钱。鲜竹叶二钱。风阳之呃。非重用犀知银花不止。顾翰云病情阴虚血热。西洋参三钱。大生地八钱。花麦冬四钱。川楝核杵先一钱五分。酒炒知母二钱。酒炒川黄柏一钱。花粉四钱。济银花八钱。连翘壳三钱。生粉草三钱。热虽在血。必使达于气分而解。故方中参用清气品。）", "14085": "许自堂孙患感。延至秋杪。证交二十八日。诸医束手。孟英诊之。左部数。右手俨若鱼翔。痰嗽气促。自汗瘛疭。苔色灰厚。渴无一息一停。垂危若是。孟英曰：据脉莫能下手。吾且竭力勉图。于是先以竹叶石膏汤加减至五剂。气平嗽减。汗亦渐收。苔色转黑。舌尖露绛。改投玄参生地犀角石膏知母花粉竹叶银花等药。又五剂瘛疭渐减。舌绛渐退。病者闻鼓乐喧阗。即谵妄不安。神昏如醉。夜速孟英视之。予紫雪钱余。神即清爽。仍用前方。重加竹沥。服八剂始解黑如胶漆之大便。而黑苔渐退。右脉之至数始清。惟烦渴不减。令其恣啖北梨。舌才不燥。痰出亦多。又六剂舌色乃淡。溲出管痛。热邪得从下行矣。凡十二日之间。共服大剂寒凉已二十四剂。计用犀角三两有奇。而险浪始平。续以前法缓制。服六剂又解胶矢五次。手足始知为己有。又五剂筋络之振惕始定。略能侧卧。呓语乃息。渐进稀糜。继灌甘润充其胃汁。七八剂后渴止知饥。脉皆和缓。又浃旬谷食乃复。又旬余便溺之色始正。前后共下黑矢四十余次。苔色亦净。授滋填善后而康。（右手俨若鱼翔。据脉莫可下手。惟痰嗽苔厚。渴无一息一停。邪旺则正亦旺。此凭证不凭脉之治。鲜竹叶二钱。生石膏先煎一两六钱。酒炒知母四钱。制半夏三钱。姜竹茹三钱。建兰叶三钱。姜枇叶刷包三钱。生冬瓜子八钱。活水芦根二两。南花粉五钱。旋覆花绢包三钱。生蛤壳海浮石各五钱。石斛一两。三味同先煎。更方玄参一两。大生地八钱。泡煎去渣。镑犀角先煎四钱。生石膏先煎一两。酒炒知母四钱。花粉四钱。鲜竹叶二钱。银花一两五钱。）", "14086": "段春木秋杪患发热。而腰腿痛如刀割。孟英视之。略不红肿。脉至细数。苔色黑燥。溺赤便黑。予西洋参麦冬生地犀角银花楝实石斛知母甘草竹沥蔗汁为大剂投之。热渐退。痛渐已。惟舌绛无津。仍予甘凉濡润为方。数日后忽舌绛倍加。燥及咽膈。水饮不能下咽。孟英曰：真阴涸竭。药难奏绩矣。嗣询悉病人自误于女劳复。孟英因论曰：烧裩散鼠矢汤。皆从足少阴以逐邪。不过热邪袭入此经。所谓阴阳易是也。今少腹无绞痛之苦。原非他人之病易于我。真是女劳之复。以致真阴枯涸。更将何药以骤复其真阴哉。然从此而女劳复与阴阳易。一虚一实有定论。不致混同而谈治矣。（脉至细数三句。为阴虚风动。肝阳逆冲肺胃。肺胃不能荫庇腰肾。西洋参三钱。花麦冬四钱。大生地泡冲去渣一两。犀角先煎四钱。楝核杵先三钱。石斛先煎一两。酒炒知母四钱。生粉草三钱。竹沥三两。蔗汁一两和服。）", "14087": "顾升庵子久患多疑善恐。不出房者数年矣。食则不肯与人共案。卧则须人防护。寡言善笑。时或遗精。多医广药。略无寸效。孟英切脉甚滑数。予玄参丹参竹黄竹茹丹皮黄连花粉栀子海䖳荸荠为剂。送服当归龙荟丸。四剂即能出署观剧。（多疑善恐六句。皆肝有痰热现证。龙荟丸泻肝痰热。遗精之因起于肝热。遗精之祸流为肾亏。玄参雪羹针治遗精。玄参片泡煎去渣八钱。紫丹参三钱。天竹黄三钱。姜竹茹三钱。粉丹皮二钱。酒炒川连二钱。黑栀皮一钱五分。淡海䖳二两。整荸荠一两。药送当归龙荟丸三钱。）", "14088": "陈某偶患溏泄。某某投以温补健脾之药。数日后泻虽减。而发热昏痉。咽喉黑腐。肝肾之阴两竭。孟英诊曰：迟矣。病起泄泻。何必为寒。正是伏邪自寻出路。而温补以固留之。自然内陷厥阴。不可救药。果即殒焉。继有高小坨弟因食蟹患泻。黄某用大剂温补药。泻虽止而颈筋酸痛。舌绛呕渴。口气甚臭。孟英持脉沉数。曰：食蟹而后泻。会逢其适耳。脉证如斯。理应清润。病人自畏凉药。复误吴某温补。服及旬日。昏痉舌黑而毙。（高某颈筋酸痛三句。热邪大伤肝胃气分之阴。清润方。酒炒知母四钱。济银花一两五钱。石斛先煎一两。干桑葚杵先一钱半。酒炒川连一钱。苦杏泥一钱五分。活水芦根二两。南花粉四钱。整荸荠一两淡海䖳二两先煎。炒枳壳一钱五分。生姜自然汁箸挑六滴和服。）", "14089": "金某久患脘痛。按之漉漉有声。便秘溲赤。口渴苔黄。杳不知饥。绝粒五日。诸药下咽。倾吐无余。孟英察脉沉弱而弦。用海䖳荸荠各四两煎汤饮之。径不吐。痛亦大减。继以此汤煎高丽参黄连楝实延胡栀子枳椇石斛竹茹柿蒂等药。送服当归龙荟丸。旬日而安。续予春泽汤调补收绩。盖其人善饮而嗜瓜果以成疾也。（脘痛为肝阳侮胃。便秘溲赤三句。皆肝阳贼肺现证。脉沉为痰热遏伏。弦为肝热。弱为脾阳伤败。雪羹先治其倾吐无余。使气降受药。丽参针治脉弱。延胡亦因脉弱防苦寒过剂。高丽参切一钱半。酒炒川连一钱。楝核杵先三钱。酒炒延胡索次入一钱五分。黑栀皮一钱五分。枳𪱷子杵先四钱。石斛先煎一两。姜竹茹三钱。干柿蒂十个。药送龙荟丸三钱。春泽汤五苓加参。孟英必加泻肝润胃之品。）", "14090": "乔有南年三十九岁。患牝疟二旬。医治罔效。孟英往诊脉微无神。倦卧奄奄。便秘半月。溺赤不饥。痰多口甘。稍呷米饮。必揉胸捶背而始下。苔色黑腻。而有蒙茸之。象乃曰：此精气神三者交虚之证。不可与时行伏暑晚发同年而语也。幸前手之药。法主运中。尚无大害。予参术桂附沉香拌炒熟地鹿角石英苁杞归茯杜仲枣仁菟丝山萸橘皮霞天曲胡桃肉等出入为大剂。投十余剂寒后始有热。而苔色乃退。口不作渴。甘痰亦日少。粥食渐加。即裁桂附白术加石斛。又服七剂。解黑燥大便甚多。凡不更衣者四旬二日。寒热亦断。安谷溲澄而竟愈。（中略。）孟英曰：温补亦治病之一法。何可废也。第用较少耳。（治热以寒。定法也。惟热邪陷入之浅深。仍视其人本体阳气衰旺。阴阳两虚。热邪愈易陷入深处。治法参阳药运其邪外出。如此病约二十剂始解黑燥大便。其明证也。牝疟。热病也。脉微无神。倦卧奄奄为阳虚证。溺赤不饥。痰多口甘。热证也。稍呷米饮。必揉胸捶背而始下。则又为脾肾阳虚。苔色黑腻似热。蒙茸则为寒。标病为热。本病为阳虚。此热邪深陷于阳虚之本体。致现此证。潞党参三钱。炒白术一钱五分。厚附片杵五钱。肉桂心二钱。毛鹿角杵先三钱。紫石英杵三钱。二味同先煨六句钟。蛀陈皮次入一钱五分。云茯苓三钱。炒枣仁杵三钱。甘枸杞二钱。更方加霞天曲三钱。再更方去参苓。加山萸肉三钱。淡苁蓉三钱。炒菟丝饼二钱。再更方去霞天曲。加棉杜仲三钱。再更方去杞子。加箱归身二钱。再更方去当归菟丝。加沉香炒熟地四钱。连皮胡桃肉五钱。嗣裁桂附术。加石斛先煎五钱。）", "14091": "陈媪患牝疟月余。腹胀便秘。嗳多不饥。口淡脉滑。孟英主连朴橘贝杏茹旋菀杷蒺为方。数剂即瘳。（脉滑为痰热。口淡为胃阳不旺。姜炒川连二钱。制厚朴一钱。陈橘皮一钱半。川贝母杵四钱。姜竹茹三钱。旋覆花包先三钱。紫菀茸一钱半。姜枇叶刷包三钱。。生白蒺三钱。）", "14092": "王季杰妾因夜间未寐。侵晨饮酒解寒。适见人争谇。即觉心跳。欲吐不出。气即逆奔如喘。且肢麻手握。语言难出。孟英视之。脉象弦驶。曰：夜坐阳升。饮醇则肝阳益浮。见人争谇。是惊则气更上逆。不可刺也。灌以苏合香丸一颗。下咽即瘥。（是案必脱漏一段。饮醇肝阳益浮。其人平素阴虚肝旺可知。岂可专治以苏合丸之辛香。仿孟英另案用六一散一两。淡盐开水搅之。澄去滓。研调苏合香丸一钱。）", "14093": "黄履吉截疟后患浮肿。赵某闻其体素虚。切其脉弦细。遂用温补。驯致呃忒不休。气冲碍卧。饮食不进。势濒于危。孟英曰：脉虽弦细而有力。子必误服温补矣。肯服吾药。犹可无恐。因予栝蒌薤白合小陷胸橘皮竹茹汤加柿蒂旋覆苏子香附赭石紫菀杷叶为方。四剂而瘳。（栝蒌仁研三钱。鲜薤白打一钱半。姜炒川连二钱。制半夏一钱。赖橘红次入八分。姜竹茹三钱。生粉草一钱。姜枇叶刷包三钱。干柿蒂十个。生苏子研次入二钱。生香附次入七分。紫菀茸一钱半。生赭石杵先五钱。炭煨六句钟。旋覆花包先三钱。）", "14094": "吴馥斋室春间娩子不育。汛事亦未一行。偶患呕吐发热。眩晕心𩠎。大解溏泄。口渴溲痛。疑娠疑损。孟英诊曰：产及一载。而经不至。腹不胀。脉弦缓。非娠非损。乃血虚痰滞而感冬温也。以羚羊淡豉竹茹白薇栀子杷叶知母葱白花粉投之。三剂热退吐止。去葱豉羚羊。加生地甘草橘皮调之而愈。（呕吐发热四句。皆肝风煽升。痰热阻遏气机之象。脉弦为肝热。脉缓为肝热壅痰阻气。羚角先煎四钱。炒豆豉次入三钱。姜竹茹三钱。香白薇一钱。黑栀皮三钱。姜枇叶刷包三钱。酒炒知母四钱。姜汁炒花粉三钱。连须葱白打次入一钱半。嗣去葱豉羚羊。加大生地泡煎去渣八钱。生粉草三钱。陈橘皮一钱半。）", "14095": "盛犀林仆患血痢。自秋徂冬罔效。孟英察脉细弱而口干。腰膝酸疼。予鹿角霜苁蓉枸杞杜仲菟丝续断血余石脂木瓜砂仁末炒熟地黄。十余剂而痊。（脉证为阴虚中兼挟阳虚。血余行瘀。石脂涩肠。鹿角霜炖和服三钱。淡苁蓉一钱半。甘枸杞三钱。菟丝饼四钱。绵杜仲二钱。川续断二钱。血余灰绢包一钱。陈木瓜一钱半。砂仁末炒熟地八钱。药汁调服赤石脂末二钱。）", "14096": "徐月岩室患周身麻木。四肢瘫痪。口苦而渴。痰冷如冰。气逆欲呕。汛愆腹胀。频饮极热姜汤。似乎畅适。深秋延至季冬。服药不愈。孟英诊脉沉弦而数。曰：溺热如火乎。间有发厥乎。病者唯唯。遂以雪羹旋赭栀楝茹斛知母花粉桑枝羚羊橄榄蛤壳为方。送下当归龙荟丸。服之递效。二十剂即能起榻。乃去羚赭加西洋参生地苁蓉藕投之。渐愈。（人知口苦而渴为热。不知痰冷如冰。尤为热邪深锢。肺气不行现证。溺热如火。时或发厥。皆热结肝经之证。荸荠一两。淡海䖳二两。旋覆绢包三钱。生赭石杵一两六钱。同先煎。姜栀皮一钱半。楝核杵先二钱。酒炒知母四钱。南花粉四钱。酒炒桑枝三钱。羚角先煎四钱。青果连核杵三个。生蛤壳杵五钱。同先煎。药送龙荟丸三钱。）", "14097": "张肖江妹暮冬患感。朱某进温散药数服。病日剧。孟英视之。目瞪不语。面赤气逆。昼夜需人抱坐。四日不著枕矣。乃冬温挟痰。误提而气不肃降也。以旋赭杏贝花粉茅根冬瓜子紫菀薤白蒌仁苏子石菖蒲竹沥为剂。芦菔汤煎。三剂大便行而能卧矣。自言胸中迷闷。改用小陷胸合三子养亲加沙参知母旋贝竹茹枇杷叶数剂。热退知饥而愈。嗣有王炳华子患感。叶某用温散药而气逆碍卧。王秉衡作肾虚不能纳气治。连服大剂温补。喘嗽益剧。面浮跗肿。抬肩自汗。大渴胁痛。乞治孟英。已半月不交睫矣。诊其脉右部弦大而强。舌根黑苔如煤者两条。面黎形瘦。幸而大解溏泄。得能消受许多误药。径予旋赭黄连枳实栝蒌苏子杏仁紫菀生石膏芦菔汁。六大剂始能就枕。而大渴不止。脘腹反形痞胀。按之坚痛。乃去旋赭。少加白芥子半夏薤白。兼令日啖北梨数十枚。服旬日胸腹皆舒。苔色尽退。惟嗽未已。改用西洋参杏贝芦根知母冬瓜子花粉柿霜杷叶竹沥十余剂。嗽止而跗肿渴泻亦皆霍然矣。凡啖梨三百余斤。闻者莫不诧异。（辨冬温挟痰。在面赤目瞪不语。辨误提气不肃降。在昼夜需人抱坐。四日不著枕。旋覆花包先三钱。生赭石杵先二两。苦杏泥二钱。川贝母杵四钱。鲜茅根五钱。生冬瓜子四钱。紫菀茸一钱半。鲜薤白一钱半。姜炒蒌仁三钱。生苏子研次入二钱。石菖蒲次入一钱。姜竹沥一酒杯冲。芦菔一两。切煨煎药。三帖后便行能卧。自言胸中迷闷。改用姜汁炒川连八分。栝蒌仁研三钱。制半夏一钱。生白芥子研。生莱菔子研。生苏子研。各一钱半。北沙参四钱。姜炒知母三钱。旋覆包先一钱半。姜竹茹三钱。姜枇叶刷包一片。王炳华子右脉弦大而强。为痰热窒肺。舌根黑苔如煤。肺肾为子母之脏。此为肺热注肾。简单论证为温补窒肺。旋覆包先三钱。生赭石杵先一两六钱。姜炒川连二钱。炒枳实一钱半。栝蒌仁研四钱。生苏子研次入二钱。苦杏泥一钱半。紫菀茸一钱。生石膏先煎一两二钱。鲜芦菔一两。打自然汁冲。更方去旋赭。加生白芥子研二钱。制半夏一钱半。鲜薤白打一钱半。终更方西洋参三钱。苦杏泥二钱。川贝母杵八钱。鲜芦根一两。姜汁炒知母三钱。生冬瓜子三钱。南花粉四钱。柿霜一钱。姜枇叶刷包三钱。姜竹沥两酒杯冲。）", "14098": "高汉芳患滞下色酱。日数十行。年已七十七岁。自去秋以来。渐形疲惫。即服补药。驯致见痢。黄某径用温补。势乃剧。孟英诊之。右脉弦细芤迟。口渴溲涩。时时面赤自汗。乃吸受暑邪。误作虚治。幸其所禀极坚。尚能转痢。一误再误。邪愈盛而正反虚矣。以白头翁汤加参术银花芩芍楝斛延胡。二剂即减。五剂而安。继予调补。竟得霍然。（滞下色酱。本挟热邪。补药留邪。素禀极坚。尚能运邪下行作痢。脉弦为肝热。细为阴虚。芤迟为阳弱。酒炒白头翁一钱半。炒潞党三钱。炒白术三钱。济银花八钱。酒炒枯芩一钱。酒炒白芍一钱半。楝核杵先二钱。石斛先煎四钱。酒炒元胡索次入一钱半。）", "14099": "朱叶氏上年四月分娩。七月患赤痢。其家谓产后之病。不敢服药。延至今春。肌消膝软。见食欲呕。孟英诊之。左细软。右滑数。伏暑为病。幸未误药。予沙参陈仓米归芍续断木瓜扁豆连斛石莲荷蒂柿蒂枇杷叶橘皮为方。送驻车丸而愈。（脉左细软为血分阴虚。右滑数为暑邪壅遏气分。故方中泻暑清气之药较多。北沙参四钱。陈仓米洗三钱。酒炒白芍一钱半。箱归身一钱。陈木瓜一钱半。生扁豆杵三钱。川续断一钱半。酒炒川连二钱。石斛先煎五钱。陈石莲杵先二钱。干荷蒂三钱。干柿蒂十个。鲜枇叶刷包三钱。陈橘皮次入一钱半。药送驻车丸三钱。驻车丸黄连阿胶干姜当归。木瓜合黄连为酸苦泄肝。黄连合橘皮为苦辛治呕。驻车内黄连阿胶针治脉右滑数。干姜当归针治左细软。）", "14100": "郑芷塘妻母年逾花甲。仲春患右手足不遂。舌謇不语。面赤便秘。医予疏风不效。延诊孟英。右洪滑。左弦数。为阳明腑实之候。书石菖蒲胆星知母花粉枳实蒌仁秦艽旋覆麻仁竹沥为方。盖古人中脏宜下之脏字。乃腑字之讹。柯韵伯云。读书无眼。病人无命。书方未服。延至二旬。苔裂舌绛。米饮不沾。腹胀息粗。阴津欲竭。非急下不可。即以前方加大黄四钱绞汁服。连下黑矢五次。舌謇顿减。渐啜稀糜。乃去大黄加西洋参生地麦冬丹皮薄荷。服五剂。复更衣。语言乃清。专用甘凉。充津涤热。又旬日。舌色始淡。纳谷如常。改以滋阴。渐收全绩。（石菖蒲次入二钱。陈胆星炖和服一钱。酒炒知母五钱。南花粉四钱。姜蒌仁四钱。左秦艽次入一钱半。旋覆包先三钱。大麻仁研三钱。姜竹沥二大酒杯冲。方延半月未服。加大黄四钱。绞汁冲服。此证右脉洪滑。必重按搏指不挠。嗣去大黄。加西洋参三钱。大生地八钱。花麦冬四钱。粉丹皮四钱。蒲荷尖次入一钱半。连下黑矢五次。气分暑邪略尽。重加凉血之品。针治左脉弦数阴虚。仍加薄荷。使升浮凉润于上焦气分。斯为丝丝入扣。）", "14101": "章养云室患感。适遇猝惊。黄包二医皆主温补。乃至昏谵痉厥。势极危殆。求诊孟英。证交三十八日。脉至细数无伦。两手拘挛。宛如角弓之反张。痰升自汗。渴饮苔黄。面赤臀穿。昼夜不能合眼。先予犀羚贝斛元参连翘知母花粉胆星牛黄鳖甲珍珠竹黄竹叶竹茹竹沥为方。三剂两手渐柔。汗亦渐收。又五剂。热退痰降。脉较和。而自言自答。日夜不休。乃去羚斛珠黄。加西洋参生地大块朱砂两许。服之聒絮不减。复于方中加青黛龙牡。服二剂。仍喋喋不已。孟英苦思数四。径于前方加木通一钱。投匕即效。次日。病者自云前此小溲业已通畅。不甚觉热。昨药服后。似有一团热气从心头直趋于下。由溺而泄。从此神气安谧。粥食渐加。两腿能动。大解亦坚。忽咽肿大痛。水饮不下。孟英曰。余火上炎也。仍予前方。更吹锡类散而安。惟臀疮未敛。腿痛不已。乃下焦气血伤残。改用参耆归芍生地合欢山药麦冬牛膝石斛木瓜桑枝藕肉。数服痛止餐加。又予峻补生肌而愈。（病情为温补助邪。肝风大动。血鳖甲四两。镑犀角羚次尖各四钱。石斛一两。开水先炭煨八句钟。取汤代水煎药。川贝母杵四钱。元参片开水泡冲去渣八钱。连翘壳三钱。酒炒知母四钱。南花粉四钱。陈胆星炖和服八分。西牛黄研和服二厘。濂珠粉舌餂药送一分。天竹黄三钱。鲜竹叶次入二钱。姜竹茹三钱。姜竹沥两大酒杯冲。嗣去羚斛珠黄。加西洋参三钱。大生地八钱。大块朱砂一两二钱。复加飞青黛一钱。煅龙骨杵一两。煅牡蛎杵四两。终加细木通一钱。下焦气血伤残方。潞党参三钱。生西耆三钱。箱归身二钱。酒炒白芍一钱半。大生地八钱。合欢皮一钱半。淮山药三钱。花麦冬四钱。制牛膝七分。石斛先煎一两。陈木瓜三钱。酒炒桑枝三钱。连皮藕肉切先一两。）", "14102": "吴女患感。诸医首以升散。继进温补。至三月下旬。证交三十五日。昏痉谵语。六昼夜不交睫。旬日不沾米饮。孟英会诊。脉弦滑而微数。齿不能开。窥其舌缩苔垢。孟英曰：尖虽卷。色犹红润。且二便不秘。尚有一线生机未绝。揆其受病。原不甚重。只因谬治逾月。并谓病已逾月。腰以下得毋磨坏。书方以犀角四钱石菖蒲二钱贝母二两整块朱砂两许竹沥碗许。佐以竹叶竹黄竹茹知母花粉元参旋覆丝瓜络苇茎银花鳖甲。调下紫雪丹。次日渠母云。王君明视隔垣。小女腰下果已磨穿。糜溃如柈。昨药服后证亦少减。孟英仍主原方。四服后夜始眠。痉才息。舌甫伸。苔乃黑。孟英于前方去鳖甲朱砂菖蒲。加生地栀子。数服后。苔转黄。大便黑如胶漆。且有痰色。盖从前大解黄色。似乎无甚大热。不知热由补药所酿。滞于肠胃曲折之地而不能下行。势必熏蒸于上。致有内陷入脏之逆也。黑矢下而神识渐清。余热复从气分而达。痰嗽不爽。右脉滑搏。孟英主用竹叶石膏汤加减。四剂渐安。而外患痛楚。彻夜呻吟。虽敷以珠黄。滋以甘润。未能向愈。孟英令以大蟾蜍治净煎汤。煎育阴充液之药服之。果痛止肌生。眠食渐进。汛事如期而瘳。（舌色红润。阴液未竭。二便不秘。热有出路。且正气亦能推邪下行。方中应佐鲜竹叶二钱。天竹黄四钱。姜竹茹四钱。酒炒知母四钱。南花粉五钱。元参片一两。泡冲去渣。旋覆花包先三钱。丝瓜络三钱。鲜芦根二两。济银花一两五钱。药调紫雪丹一钱。嗣于前方去鳖甲朱砂菖蒲。加大生地八钱。黑栀皮三钱。）", "14103": "吴酝香仆患感鼻衄数升。苔黄大渴。脉滑而洪。孟英投白虎汤二剂而安。遽食肥甘。复发壮热。脘闷昏倦。孟英以枳实栀豉汤而瘥。数日后。又昏沉欲寐。发热自汗。舌绛溺涩。孟英诊之。左尺细数而芤。右尺洪大。是女劳复也。细诘之。果然。予大剂滋阴清热药。吞豭鼠矢而愈。（羚次尖四钱先煎。生石膏先煎一两六钱。酒炒知母四钱。石斛先煎一两。西洋参三钱。济银花一两五钱。川贝母杵四钱。南花粉五钱。晚蚕砂五钱。建兰叶三钱。鲜芦根二两。枳实栀豉汤加味。炒枳实二钱。黑栀皮三钱。炒豆豉三钱。酒炒枯芩三钱。丝瓜络三钱。生冬瓜子八钱。连翘壳三钱。鲜薤白打一钱半。焦楂肉杵一钱半。整荸荠打入煎一两。女劳复方。元参片一两。大生地八钱。明天冬切六钱。女贞子杵五钱。淡苁蓉一钱半。山萸肉一钱半。石斛先煎一两。酒炒知母四钱。血龟板杵四两。血鳖甲杵二两。紫石英五钱。同先煨六句钟。药送鼠矢二钱。）王月锄媳于庙见时。忽目偏左视。扬手妄言。孟英视之。脉弦滑而微数。苔黄脘闷。盖时虽春暮。天气酷热。兼以劳则火升。挟其素有之痰而使然也。予犀羚栀翘元参丹参薄荷花粉送礞石滚痰丸。三服而痰下神清。改投清养遂愈。（脉必弦滑有力。弦为肝热。滑为痰实。数兼阴虚。犀角羚角同先煎八句钟各四钱。元参片八钱。黑栀皮连翘壳紫丹参各三钱。南花粉四钱。薄荷尖次入一钱半。药送滚痰丸四钱。犀羚元参息风顾阴。花粉滚痰丸清肺豁痰。栀翘薄荷轻解浮热。丹参清营安神。）", "14104": "单左患右胁痛。医予温运药。病益甚。至于音喑不能出声。仰卧不能反侧。坐起则气逆如奔。便溺不行。汤饮不进者。已三日矣。孟英诊其脉。沉而弦。予旋覆赭石薤白蒌仁连夏茹贝枳实紫菀加雪羹服之。一剂知。数剂愈。（脉弦为肝热。沉为热邪锢闭。旋覆包先三钱。生赭石杵一两同先煎。鲜薤白次入三钱。栝蒌仁研四钱。酒炒川连二钱。制半夏研次二钱。姜竹茹三钱。川贝母杵四钱。炒枳实一钱。紫菀茸次入一钱半淡海䖳先煎二两。整荸荠打入一两。）", "14105": "许某于醉饱后。复中胀闷。大解不行。自恃强壮。仍饮酒食肉。二日后腹痛。犹疑为寒。又饮火酒。兼吸洋烟。并小溲不通。继而大渴引饮。饮而即吐。而起居如常也。四朝孟英诊之。脉促歇止。满舌黄苔。极其秽腻。而体丰肉颤。证颇可危。因婉言告之曰：不过停食耳。且饮山楂神曲汤可也。午后始觉指冷倦怠气逆。夜分痰升。比晓胸腹额上俱胀裂而死。盖知下之不及。故不予药也。（证为阳证。脉促歇止为阴脉。阳证阴脉。命必危殆。正气伤残。不任苦寒峻下。）", "14106": "何新之患感旬日。胡某诊谓势欲内陷。孟英视之。呃忒苔腻。便秘痰多。心下拒按。持其脉。右手洪大滑数。予小陷胸加沙参菖贝菀薤茹杏旋杷之类。数剂而安。继以甘凉。二旬后得大解而痊。（姜川连二钱。制半夏一钱半。蒌仁三钱。北沙参四钱。石菖蒲八分。川贝母杵四钱。紫菀茸一钱。鲜薤白打一钱半。姜竹茹三钱。苦杏泥一钱半。旋覆绢包一钱半。姜枇叶刷包三钱。）", "14107": "翁氏妇患目疾。自春徂夏。治不能瘳。渐至腹中痞胀。痛不可当。食不能下。便秘形消。孟英视之。乃肝郁痰滞。而误补以致殆也。脉弦数而滑。予金铃子散合雪羹煎吞当归龙荟丸暨礞石滚痰丸。三投即效。服至二十余日。各恙皆蠲。（川楝核杵先四钱。元胡索次入二钱。淡海䖳二两。整荸荠一两。药送滚痰丸三钱。龙荟丸一钱。）", "14108": "李子瘄未齐。而痰嗽气喘。苔色白滑。小溲不赤。或主犀角地黄汤加柴雪。服而不效。孟英诊之。右脉洪滑而口渴。乃天时酷热。暑邪薄肺。挟其素有之痰。而阻其治节。所以气机不行。而疹不能达。苔不能化。溺不能赤也。温散大忌。凉血亦非。予竹叶石膏汤合苇茎加杏菀旋杷海石投之。气平疹透。苔退舌红。小溲亦赤。数日而愈。（鲜竹叶一钱。生石膏先煎六钱。酒炒知母一钱半。姜汁拌芦根八钱。苦杏泥一钱半。紫菀茸一钱。旋覆包先一钱。姜枇叶一片。浮海石先煎四钱。）", "14109": "魏氏女因事惊骇。次日即不知饥。眩晕便秘。医谓神虚。投补数帖。反致时欲昏厥。更医作中风治。势益甚。旬日后。孟英持其脉。弦伏而滑。胸腹无胀闷之苦。旬余不更衣。是惊则气乱。挟痰逆升。正仲圣所谓诸厥应下者。应下其痰与气也。以旋赭栀连雪羹楝贝金箔竹沥菔汁为方。并以铁器烧红淬醋。令吸其气。二剂厥止。旬日而瘳。（旋覆包先三钱。生赭石杵先一两六钱。黑栀皮三钱。姜炒川连一钱。整荸荠打一两。淡海䖳先煎二两。川贝母杵八钱。川楝核杵先三钱。金箔七页。姜竹沥两酒杯。姜汁按竹沥二成。菔汁大半酒杯冲。）", "14110": "某媪年六十余。患腰腿串痛。闻响声即两腿筋掣不可耐。日必二三十次。卧榻数载。诸药罔效。孟英察脉沉弦。苔腻便秘。亦广服温补而致病日剧也。予雪羹羚楝胆星橘络竹沥丝瓜络。吞礞石滚痰丸及当归龙荟丸。四剂大泻数十次。臭韧异常。筋掣即已。乃去二丸。加栀连羊藿。服六剂即健饭而可扶掖以行矣。（整荸荠打一两淡海䖳先煎二两。羚次尖先炭煨八句钟四钱。楝核杵先四钱。陈胆星炖和服八分。净橘络次入一钱。姜竹沥两大酒杯冲。丝瓜络三钱药送滚痰丸三钱。龙荟丸一钱。）", "14111": "徐艮生室年四十余。于酷暑之进患瘄。沉悦亭连予清解。不能杀其势。孟英视之。体厚痰多。脉甚滑数。扬掷谵妄。舌绛面赤。渴饮便涩。乃予大剂白虎加犀角元参银花花粉贝母竹黄竹叶竹茹竹沥送滚痰丸。服后大便下如胶漆。脉证渐和。数日后去丸药。其势复剧。甚至发厥。仍加丸药乃平。如是者三次。险浪始息。悦亭复以白金丸涤其膈下留痰。续用甘凉濡润法。充津液而搜余热。渐以告愈。（生石膏先煎一两六钱。酒炒知母四钱。镑犀角先煎四钱。济银花一两五钱。南花粉五钱。川贝母杵一两。天竹黄四钱。鲜竹叶二钱。姜竹茹四钱。姜竹沥二大酒杯冲。姜汁按竹沥二成。药送滚痰丸四钱。元参片泡冲去渣八钱。）", "14112": "陈氏妇素无病。娩后甚健。乳极多而善饭。六月初形忽遽瘦。犹疑天热使然。渐至减餐。孟英视之。脉细数。舌光绛。曰：急劳也。无以药为。夫乳者。血之所化也。乳之多寡。可征血之盛衰。兹乳溢过中。与草木将枯精华尽发于外者何异。即令断乳。亦不及矣。即日断乳服药。及秋而逝。", "14113": "蒋某患疟。医予小柴胡平胃散而渐甚。继以大剂温补。势濒于危。复用桂枝白虎。狂乱如故。孟英视之。曰：暑疟也。桂枝白虎用于起病之时。则妙矣。今为温散补燥诸药。助邪烁液。脉数无伦。汗渴不已。虽宜白虎。岂可监以桂枝。助热耗津而自掣其肘邪。因予大剂白虎加花粉竹叶西洋参元参石斛。服之即安。至十余帖。疟始瘳。而舌尚无苔。渴犹不止。予甘凉濡润三十余剂始告痊。（生石膏先煎一两六钱。酒炒知母五钱。南花粉五钱。鲜竹叶二钱。西洋参三钱。元参片泡冲去渣八钱。石斛先煎一两。）", "14114": "孙心言以七十之年患滞下。胡某知为暑热。以清麟丸下之。治颇不谬。继则连投术朴夏葛等药。渐至咽疼口糜。呃忒噤口。诸医进补。其势孔亟。孟英诊之。右脉滑数上溢。身热面赤。溲涩无眠。体厚痰多。时欲出汗。在痢疾门中。固为危候。第以脉证参之。岂是阳虚欲脱。实由升散温燥之剂。烁其阴液。肺胃之气。窒塞而不能下行也。予大剂肃清之药。一剂知。二剂已。随以生津药溉之。痢亦寻愈。（鲜芦根二两。黑栀皮三钱。酒炒枯芩一钱半。酒炒知母三钱。整荸荠一两。淡海䖳二两。石斛先煎一两。南花粉五钱。元参片泡冲去渣八钱。海浮石生蛤壳各五钱。同先煎。旋覆包先三钱。生石膏先煎一两二钱。）", "14115": "曹左患疟痢并作。寒少热多。滞下五色。孟英视之。面垢苔黄。干呕口渴。痛胀溺赤。汗出神疲。脉至洪数不清。予大剂芩连滑朴知母花粉银花石膏连翘竹茹等药。投匕即减。三服而起。（面垢苔黄五句。证属实热。惟干呕为阳郁不舒。神疲为阳因汗泄。故方中参用厚朴。脉洪数为阴虚挟热。故方中参用花粉。酒炒枯芩一钱半。酒炒川连一钱。酒炒知母三钱。制厚朴一钱。南花粉五钱。济银花一两五钱。生石膏先煎一两二钱。连翘壳三钱。姜竹茹四钱。）", "14116": "陈子孟秋患感。医予表散温补。病随药剧。至八月初。孟英视之。目瞪神呆。气喘时作。舌绛不语。便泻稀水。肢搐而厥。察其脉。弦而软数。乃阴亏肝盛之质。提表助其升逆。温补滞其枢机。痰饮𫐖轕。风阳肄横。予鳖甲龙牡旋赭芩连楝贝菖茹胆星犀羚等药。息风镇逆。清热蠲痰。数帖而平。（血鳖甲杵二两。煅牡蛎杵四两。煅龙骨杵一两。醋煅赭石杵八钱。镑犀角羚次尖各四钱。五味同先煨八句钟。取汤代水煎药。旋覆绢包三钱。酒炒枯芩一钱。酒炒川连二钱。楝核杵先二钱。川贝母杵八钱。石菖蒲次入二钱。姜竹茹三钱。陈胆星炖和服八分。）", "14117": "龚妇患秋感。服温散药而日重。请孟英诊之。脉见弦数软滑。苔黑肢瘈。书方用沙参元参知母花粉犀羚茹贝栀菖等药。曰：亟饵之。否将厥矣。灌之遂得生机。次日复诊。脉较和。一致清凉。渐以向愈。（北沙参八钱。元参片泡冲去渣一两。酒炒知母四钱。南花粉五钱。镑犀角羚次尖各四钱。先煨八句钟。黑栀皮三钱。石菖蒲次入二钱。）", "14118": "吴某乡试后患恙。孟英切脉甚数。溲赤苔黄。口渴燥呛。病由暑湿。而体极阴亏。已从热化。不可以便泄。而稍犯温燥之药。先予轻清肃解。继用甘凉撤热。渐能安谷。半月后热始退尽。而寝汗不眠投以大剂滋填潜摄之药。兼吞五味子磁朱丸。数十帖乃得康复。（轻清肃解方。北沙参八钱。元参片泡冲去渣一两。南花粉五钱。鲜芦根二两。鲜枇叶刷包三钱。鲜竹叶二钱。酒炒知母四钱。淡海䖳先煎二两。冬瓜皮四钱。甘凉撤热方。蜜水拌芦根二两。蜜水炒枇叶刷包三钱。鲜茅根五钱。济银花一两。鲜竹叶二钱。整荸荠打一两。酒炒知母三钱。青果连核杵先一个。大剂滋填潜摄方。大熟地八钱。大生地一两。明天冬切六钱。花麦冬四钱。青果杵先三钱。柿饼肉去霜五钱。山萸肉一钱半。煅牡蛎六两。煅龙骨杵一两。血鳖甲杵三两。紫石英五钱。四味先煨八句钟。取汤代水煎药。药送五味子三分。磁朱丸二钱。）", "14119": "张室自春间半产后。发热有时。迄于季秋。广服滋阴之药。竟不能愈。延孟英诊脉。按之豁然。投当归补血汤而热退。继以小建中愈之。（炒西耆五钱。箱归身二钱。炒白术三钱。炒云苓三钱。炒潞党三钱。制半夏三钱。炒陈皮一钱。乌梅肉三钱。夜交藤三钱。炒玉竹三钱。继以小建中炒粉草三钱。大枣擘三枚。潞党参三钱。云茯苓三钱。箱归身二钱。酒炒白芍一钱半。炒枣仁三钱。夜交藤三钱。陈木瓜三钱。山萸肉三钱。）", "14120": "俞子患感。即兼腹痛而胀。胡某投以温散。二便不行。昏谵大渴。舌苔黑刺。孟英以犀翘楝薄栀连花粉元参大黄服之。便下神清。为去犀角加丹皮。二帖苔化热退。惟少腹梗胀。不甚知饥。改投栀连楝蒺延胡橘核苁蓉花粉制军诸药。连解黑矢。渐以向安。（此证孟英用下。必有脉情可据。断非仅以证论。镑犀角先煎四钱。连翘壳三钱。楝核杵先四钱。薄荷尖次入一钱半。酒炒川连一钱。南花粉五钱。元参片泡冲去渣一两。生厢黄泡绞冲四钱。嗣去犀角。加粉丹皮二钱。此证少腹梗胀必拒按。故以辛温行苦寒之制军。改投黑栀皮三钱。酒炒川连八分。楝核杵先三钱。生白蒺三钱。延胡索一钱半。橘核杵一钱。淡苁蓉一钱半。药泡制军四钱。）", "14121": "许守存久患痰嗽。孟英主滋水舒肝法。以阴亏而兼郁也。业已向愈。所亲某亦涉猎医书。谓滋阴药不可过服。投以温补。已而咳嗽复作。渐至咽痛。冬初又延诊于孟英。曰：六脉皆数。见于水令。其不能春乎。果验。世人不辨证之阴阳。但论药之凉热。因而偾事者多矣。", "14122": "朱妇屡患半产。每怀妊服保胎药。卒无效。今秋受孕后病嗽。孟英视之。尽屏温补。纯予清肺。或诘其故。曰：胎之不固。由元气之弱者宜补正。由病气之侵者宜治病。今右寸脉滑大搏指。吾治其病。正所以保其胎。苟不知其所以然。而徒以俗尚保胎之药投之。则肺气愈壅。咳逆愈甚。震动胞系。其胎必堕矣。服之良效。（脉滑为痰实。脉大在此证为阴虚。酒炒知母四钱。陈胆星炖和服八分。鲜芦根二两。鲜枇叶刷包三钱。旋覆包先三钱。淡海䖳先煎二两。南花粉五钱。青果核先一枚。北沙参八钱。方通草三钱。石斛先煎一两。）", "14123": "邵奕堂室以花甲之年。仲冬患喘嗽。药之罔效。坐而不能卧者。旬日矣。乞诊孟英。邵述病原云。每进参汤。则喘稍定。虽服补剂。仍易出汗。虑其欲脱。及察脉。弦滑右甚。孟英曰：甚矣。望闻问切之难。不可胸无权衡也。此证当凭脉设治。参汤切勿沾唇。以栝蒌薤白旋覆苏子花粉杏仁蛤壳茯苓青黛海䖳为方。而以竹沥菔汁和服。（脉弦为肝热挟虚。脉滑为痰热。右甚痰热在肺。蒌仁研四钱。薤白打次入一钱半。旋覆包先三钱。生苏子研一钱半。花粉四钱。苦杏泥二钱。云茯苓一钱半。蛤壳杵先五钱。飞青黛一钱。淡海䖳先煎二两。姜竹沥一酒杯。菔汁半酒杯和服。）投匕即减。十余帖全愈。同时有石媪者。患此极相似。脉见虚弦细滑。孟英于沙参蛤壳旋覆杏仁苏子贝母桑枝茯苓中。重加熟地而瘳。所谓病同体异。难执成方也。（脉见虚弦细滑。为阴虚中兼挟阳虚痰浊。北沙参四钱。生蛤壳杵先五钱。旋覆花包先三钱。苦杏泥二钱。生苏子研二钱。川贝母杵四钱。酒炒桑枝二钱。云茯苓三钱。大熟地八钱。开水泡汤去渣煎药。）", "14124": "许妇患腿痛。而素多噫气。若指头一搓。或眉间一抹。其噫即不已。向以为虚。时服补剂。竟不能愈。孟英诊脉弦滑。乃痰阻于络。气不得宣也。以丝瓜络竹茹旋覆橘络羚羊茯苓豆卷金铃柿蒂海䖳荸荠藕为方。吞当归龙荟丸而安。其媳因丧子悲哀。患发厥屡服补剂。以致汛愆。或疑为娠。孟英曰：脉弦数以滑。乃痰挟风阳而为厥也。予大剂蠲痰息风舒郁清营之剂。渐以获愈。（噫即不已。为内风暗动。脉弦滑为肝风煽痰。此病温补灼津。痰乘风上。雪羹羚楝。救液息风。丝瓜络三钱。姜竹茹三钱。旋覆绢包三钱。净橘络次入一钱。羚次尖先煎八钟四钱。云苓三钱。大豆卷次入三钱。楝核杵先四钱。干柿蒂十个。淡海䖳先煎二两。整荸荠一两。藕切二两。药送龙荟丸三钱。其媳脉弦数以滑。文义注重滑字。前证吃紧在肝。此证吃紧在肺。此编次者教人辨证苦心。蠲痰息风舒郁清营方。川贝杵八钱。生冬瓜子四钱。酒炒知母四钱。鲜竹叶二钱。济银花一两五钱。石斛先煎一两。鲜薤白打一钱半。制半夏二钱。黄郁金一钱。整荸荠打一两。）", "14125": "吴永言于十年前。读论语不撤姜食之文。因日服之。虽盛夏不辍。至三年前。患大溢血。虽以凉药治瘳。而时时火升。迄今不愈。季冬就诊孟英。身不衣绵。头面之汗蓬蓬也。且云：服芩连则烦渴益甚。以苦能化燥也。用生地即闷滞不饥。以甘能缓中也。蔗梨入口亦然。按其脉。沉取滑数。是从前之积热深伏于内。予白虎汤去草米。加竹叶竹茹花粉海䖳荸荠银花绿豆恣服。渐吐胶痰而愈。（治法在脉。沉取滑数。沉字注意。沉取滑数。则气失升降可知。清气则气分有权。而痰得吐。痰得吐则积热即从痰去。肺气日臻清肃。而痛可愈矣。生石膏先煎一两六钱。酒炒知母四钱。鲜竹叶二钱。姜竹茹三钱。整荸荠打一两。淡海䖳先煎二两。济银花八钱。绿豆皮四钱。）", "14126": "赵子循每啖蔗则鼻衄必至。或疑蔗为大热之性。孟英曰：蔗甘而凉。然甘味太重。生津之力有余。凉性甚微。荡热之功不足。津虚热不甚炽者。最属相宜。风温证中救液之良药。吾名之曰天生复脉汤。若湿热痰火内盛者服之。则喻氏所谓翻受胃变。从而化热矣。凡药皆当量人之体气而施。岂可拘乎一定之寒热邪。子循之体。水虚而火旺者也。蔗性不能敌。反从其气而化热。正如蔗经火炼则成糖。全失清凉之本气矣。枸杞子亦然。（水虚火旺方。元参片一两，明天冬切八钱。菟丝饼四钱。女贞杵五钱。地骨皮四钱。酒炒知母四钱。酒炒川黄柏一钱半。菟蔚子杵先四钱。焦栀皮一钱半。酒炒枇叶刷包一片。）", "14127": "李华甫继室娠三月而崩。孟英按脉。弦洪而数。予大剂生地银花茅根柏叶青蒿白薇黄芩续断驴皮胶藕节胎发灰海螵蛸而安。奈不能安佚。越数日。胎堕复崩。孟英于前方去后六味。加犀角竹茹元参为治。或谓胎前宜凉。产后则否。乃招专科治之。咸用温药。且执暴崩宜补。服药数剂。虚象日著。时时汗出昏运。畏闻人声。懒言息微。不食不眠。间有呃忒。崩仍不止。复邀孟英视之。曰：此执死书以治活病也。夫血因热而崩。胎因崩而堕。岂胎堕之后。热即化为寒乎。参术姜桂棕灰五味之类。温补酸涩。既助其热。血益奔流。又窒其气。津亦潜消。致现以上诸证。脉或不知。而苔黄黑燥。岂不见乎。因予犀角石膏元参知母花粉竹沥麦冬银花栀子石斛旋覆青蒿白薇等大剂投之。神气渐清。旬日后。各恙始平。继去犀角。加生地。服两月全愈。（脉弦洪而数。病在血分阴虚挟热。大生地八钱。济银花一两五钱。鲜茅根五钱。酒炒柏叶一钱。鲜青蒿次入二钱。香白薇三钱。酒炒枯芩一钱半。川续断一钱半。清阿胶炖和服二钱。干藕节四钱。胎发灰包先一钱。醋炙海螵蛸杵先三钱。嗣于前方去后六味。加镑犀角先煎八钟四钱。姜竹茹三钱。清气行瘀。元参片泡冲去渣一两。救液点风。苔黄黑燥。病在气分之阴挟热。前后证异。故方亦异。镑犀角四钱。生石膏一两六钱。二味同先煎八钟。元参片一两泡冲去渣。酒炒知母四钱。南花粉四钱。姜竹沥一大酒杯冲。花麦冬四钱。济银花一两五钱。石斛先煎一两。旋覆包先三钱。鲜青蒿一钱半。香白薇三钱。继去犀角。加大生地八钱。）", "14128": "金母陡吐狂血。肢冷自汗。孟英切脉弦涩。察血紫黯。乃肝郁凝瘀也。证虽可愈。复发难瘳。予丹参丹皮茺蔚旋覆苓栀柏叶郁金海䖳之方。复杯果愈。然不能惩忿。逾二年复吐。竟不起。（脉弦涩。已露肝郁凝瘀。察血紫黯益信。复发难瘳者。血为阴类。阴中有阳。陡吐狂血。阴伤阳亦随之。脉弦涩。阴中之阳已不能鼓舞热邪升浮于上。残阴无几。何堪肝郁再吐。阴阳交贼乎。酒炒丹参三钱。酒炒丹皮一钱半。茺蔚子杵先四钱。旋覆包先三钱。云苓三钱。黑栀皮一钱半。酒炒柏叶一钱半。黄郁金一钱。淡海䖳先煎一两。）", "14129": "张妇年逾古稀。患气逆殿屎。烦躁不寐。孟英切脉滑实。且便閟面赤。舌绛痰多。以承气汤下之霍然。（病在气分热实。黑栀皮三钱。丝瓜络三钱。冬瓜皮三钱。川贝母杵四钱。生冬瓜子四钱。石菖蒲次入一钱。酒炒川连一钱。元明粉一钱。生厢黄三钱。二味开水同泡冲去渣。）", "14130": "王右患痰喘。胡某进补肾纳气及二陈三子诸方。证濒于危。孟英诊之。脉沉而涩。体冷自汗。宛似虚脱之证。惟二便不通。脘闷苔腻。是痰热为补药所遏。一身之气机窒痹而不行也。予蒌薤旋赭杏贝栀苑兜铃海䖳竹沥等以开降。复杯即减。再服而安。（病在痰热窒塞气分。姜蒌皮三钱。西薤白打次入一钱半。旋覆包先三钱。生赭石杵先五钱。苦杏泥次入二钱。川贝杵四钱。姜栀皮三钱。紫菀茸一钱半。马兜铃三钱。姜竹沥一酒杯冲。姜汗按竹沥二成。淡海䖳先煎一两。）", "14131": "王右久患痰嗽。食减形消。夜不能眠。寝汗舌绛。广服补剂。病日以增。孟英视之。曰：固虚证之当补者。想未分经辨证。而囫囵颟顸。翻与证悖。是以无功。投以熟地苁蓉坎板胡桃百合石英茯苓冬虫夏草等药。一剂知。旬日愈。以其左脉弦细而虚。右尺寸皆数。为阴亏气不潜纳之候。及阅前服方。果杂用耆术以助气。二陈故纸附桂等以劫阴也。宜乎愈补而愈剧矣。（夜不能眠二句。合之脉弦细而虚。为肾脏阴亏。右尺寸皆数。为阴亏气不潜纳。多食而肥。皆气为之。气不潜纳则食减形消矣。大熟地八钱。淡苁蓉一钱半。血龟板杵四两。先煨八钟。连皮胡桃肉三钱。百合花三钱。紫石英三钱杵先。云苓三钱。冬虫夏草二钱。）", "14132": "张室患感。连服温散。旬日后倏然昏厥。自寅正至辰初不苏。孟英视之。脉伏而弦滑。予大剂犀羚茹贝知母花粉元参银花。调局方至宝丹灌下即安。（此必阴虚之体。温散劫阴。内风陡动。自寅正自辰初。为风木司令之时。肝阳贼肺。则肺气不行。故脉伏。弦滑为肝风煽痰。方义主息风救液。镑犀角四钱。羚次尖四钱。二味同先煨八钟。姜竹茹三钱。川贝杵八钱。南花粉五钱。元参片泡冲去渣一两。济银花一两五钱。）", "14133": "王妇患心悸眩晕广服补剂。初若甚效。继乃日剧。时时出汗。肢冷息微。气逆欲脱。灌以参汤。稍有把握。延逾半载。孟英诊之。脉沉弦且滑。舌绛而有黄腻之苔。口苦溲热。汛事仍行。病属痰热𫐖轕。误补则气机壅塞。予大剂清热涤痰药。吞当归龙荟丸。服之渐以向安。嗣娠后停药。去疾未尽。娩后复患悸运不眠。气短不饥。或作产后血虚治不效。孟英视之。脉极滑数。曰：病根未刈也。予蠲痰清气法果应。（脉沉弦且滑四句。痰热皆在气。汛事仍行。则病不在血可知。大剂清热涤痰方。酒炒知母三钱。姜竹茹三钱。丝瓜络三钱。酒炒川连一钱。南花粉四钱。淡海䖳先煎一两。鲜薤白打一钱半。制半夏二钱。石菖蒲一钱。三味同次入。药送龙荟丸三钱。脉极滑数。蠲痰清气方。姜竹茹三钱。酒炒知母四钱。鲜芦根二两。生冬瓜子八钱。济银花一两。旋覆包先三钱。生赭石杵先八钱。制半夏二钱。石菖蒲一钱。二味同次入。川贝杵一两。姜竹沥两大酒杯冲。）", "14134": "许母仲春之杪。偶患微感。医予温散。热已渐退。孟英偶过。诊右寸脉促数不调。因谓曰：此风温证。其误表乎。恐有骤变。渠复质之前医。以为妄论。仍用温燥。越二日。即见鼾睡。再延孟英诊之。促数尤甚。曰：鼻息鼾矣。必至语言难出。仲圣岂欺我哉。风温误汗。往往皆然。（风温误表方。生石膏先煎一两二钱。酒炒知母五钱。石斛先煎一两。镑犀角先煎四钱。济银花一两五钱。冬桑叶四钱。鲜竹叶二钱。冬瓜皮四钱。姜竹沥一大酒杯冲。连皮北梨三两。连皮青蔗一两，同榨汁去渣冲。分次灌服。鲜青果四钱杵先。）", "14135": "姚某年未三旬。烟瘾甚大。吸受温邪。胁痛筋掣。气逆痰多。热壮神昏。茎缩自汗。孟英诊之。脉见芤数。舌绛无津。有阴虚阳越。热炽液枯之险。况初发即尔。其根蒂之不坚可知。予犀羚元参知母壮水息风。苁蓉楝实鼠矢石英潜阳镇逆。沙参麦冬石斛葳蕤益气充津。花粉栀子银花丝。瓜络蠲痰清热。一剂知。四剂安。随以大剂养阴而愈。（阴虚阳越。热炽液枯。本病也。气逆痰多。标病也。本急则本反为标。故方中治本之药多于治标。且阴虚之痰。补之则气行痰降。镑犀角四钱。羚次尖四钱。二味同先煎八钟。元参片一两。泡煎去渣。酒炒知母五钱。淡苁蓉一钱半。川楝核杵先二钱。鼠矢三钱。紫石英杵先三钱。北沙参八钱。花麦冬四钱。石斛先煎一两。肥玉竹三钱。南花粉五钱。黑栀皮一钱半。济银花一两五钱。丝瓜络三钱。）", "14136": "周母年逾七旬。丧子光远惨痛。渐生咳嗽。气逆痰咸。夜多旋溺。口苦不饥。孟英曰：根蒂虚而兼怫郁也。予沙参甘草麦冬熟地龟板石斛贝母蛤壳小麦大枣而安。迨夏间吸暑而患腹痛滞下。小溲热涩。其嗽复作。脉仍虚弦。略加耎数。但于前方增滑石。吞香连丸而瘳。因平昔畏药。既愈即停。至仲秋嗽又作。惟口不苦而能食。因于前方去沙参加高丽参五味石英牛膝熬膏频服而痊。十月下旬。天气骤冷。陡患吐泻腹痛。肢冷音嘶。孟英视之。脉微为寒邪直中。亟予大剂理中。加吴萸橘皮杜仲故纸石脂余粮而瘥。周光远妻亦因悲郁而患崩漏。面黄腹胀。寝食皆废。孟英用龟板海螵蛸女贞旱莲贝母柏叶青蒿白薇小麦茯苓藕肉莲子心而康。次年夏。其母患温邪痰嗽。脘闷汗多。孟英投石膏竹茹知母花粉旋覆贝母蒌仁紫菀等药三十剂而愈。（根蒂虚兼怫郁方。方义主治阴虚挟痰。参甘麦大枣汤治怫郁。北沙参五钱。生粉草三钱。花麦冬四钱。大熟地八钱。血龟板杵四两。先煨六钟。石斛先煎一两。川贝母杵四钱。生蛤壳杵先一两。北小麦四钱。大枣一枚擘先。周母第二方。于前方增滑石五钱先煎。针治小溲热涩。吞香连丸者。此次脉兼虚耎。气分阳虚。不能偏任苦寒。故以木香行黄连之苦寒。小肠为心腑。黄连泻心。而后小溲之热涩以治。周母第三方。口不苦而能食。则肺胃无热可知。前诊脉兼虚耎。肺胃热去。故加温镇以吸纳虚阳。方加丽参三钱。五味子杵先三钱。紫石英杵先三钱。制牛膝一钱。周母第四方。脉微为寒邪直中。炒干姜五钱。炒潞党三钱。炒白术三钱。生吴萸次入一钱。炒焦陈皮一钱半。炒故纸研五钱。酒炒石脂余粮杵调服各一钱。周光远妻病。为肝郁崩漏。水不涵木。肝肠侮胃。血龟板杵先煨六钟四两。醋炙海螵蛸杵先四钱。女贞杵五钱。旱莲草四钱。川贝杵四钱。酒炒柏叶一钱半。鲜青蒿一钱半。香白薇三钱。北小麦四钱。云苓三钱。连皮藕切一两。莲子心一钱。周光远母第五方。痰热全在气分。生石膏先煎八钱。姜竹茹三钱。一浓姜汁浸炒知母三钱。姜汁浸炒花粉三钱。旋覆包先三钱。川贝杵四钱。姜蒌仁三钱。紫菀茸一钱半。）", "14137": "王小谷体厚善饮。偶患气逆。多医咸从虚治。渐至一身尽肿。恳治孟英。脉甚细数。舌绛无津。间有讝语。乃真阴欲匮。再勉予西洋参元参二地二冬知母花粉茹贝竹沥葱须等药。三剂而囊肿全消。孟英以脉象依然。坚辞不肯承手。寻果不起。（西洋参三钱。元参片一两。熟地生地各八钱。明天冬切六钱。花麦冬四钱。酒炒知母三钱。南花粉四钱。姜竹茹三钱。川贝杵五钱。姜竹沥两大酒杯冲鲜葱须次入二分。人病脉不病者生脉病人不病者死。况脉无起色乎。）", "14138": "朱女患感。医投温散。服二剂遍身麻瘄。汛事适来。医进小柴胡汤。遂狂妄莫制。乞援孟英。脉至洪滑弦数。目赤苔黄。大渴不寐。是瘄因温邪而发。时时大汗。何必再攻其表。汛行为热迫于营。胡反以姜枣温之。参柴升之。宜其燎原而不可遏也。予大剂。犀角元参生地石膏知母花粉银花竹叶贝母白薇以清卫凉营。服后即眠。久而未醒。或疑昏沉也。屡呼惊寤狂易。孟英复视。脉象依然。仍以前方加重。和以竹沥童溲灌下即安。继用养阴清热而愈。（热邪由卫侵营。内风已动。镑犀角先煎八钟四钱。元参片一两。大生地八钱。二味泡煎去渣。生石膏先煎。一两六钱。酒炒知母五钱。南花粉四钱济银花一两五钱。鲜竹叶二钱。川贝杵八钱。香白薇三钱。惊寤狂易。前方加重。并加姜竹沥两大酒杯冲。煎去头尾童便一酒杯冲。竹沥蠲痰清热。童溲引热下行。）", "14139": "高绿卿室。孟夏分娩发热。初疑蒸乳。数日不退。产科治之。知挟温邪。进以清解。而大便溏泄。遂改温燥。其泄不减。张某予参耆姜术鹿角肉果等药。泄泻愈甚。连服之。热壮神昏。汗出不止。势濒于危。孟英按脉洪数七至。口渴苔黄。洞泻如火。小溲不行。书白头翁汤加石膏犀角银花知母花粉竹叶栀楝桑叶予之。次日复诊。脉证较减。仍用前方大剂凉解。服至七剂。泻全止。热尽退。乃去白头翁汤加生地元参茹贝。服半月。始解黑色燥矢。而眠食渐安。第腑脏之邪虽已清涤。而从前温补。将热邪壅滞于膜络之间者。复发数痈于胸乳之间。孟英令其恪守前法。复入蒲公英丝瓜络橘叶菊叶等药。服至百剂。始告全愈。而天癸亦至。（酒炒白头翁一钱半。酒炒川连一钱。楝核杵先二钱。酒炒知母三钱。镑犀角先煎四钱。济银花一两五钱。南花粉五钱。鲜竹叶二钱。黑栀皮三钱。冬桑叶四钱。嗣去白头翁汤。加生地八钱。元参片一两。二味泡煎去渣。姜竹茹三钱。川贝杵八钱。第三方前方去犀角石膏花粉元参。加蒲公英二两丝瓜络三钱。鲜橘叶一钱。鲜菊叶次入二钱。首方用白头翁汤之大苦以敛其热下行。）", "14140": "赵秋舲去秋患左半不遂。伊弟主清热蠲痰。治之未能遽效。孟英诊之。脉甚迟缓。苔极黄腻。便秘多言。令于药中和入竹沥一碗。且以龙荟滚痰二丸相间而投。二丸各用斤许。证始向愈。今春出房。眠食已复。而素嗜厚味。不戒肥甘。孟夏其病陡发。孟英诊之。脉形滑驶如蛇。断其不起。秋初果殁。（石菖蒲次入二钱。制半夏一钱。省头草三钱。姜炒知母三钱。姜竹茹三钱。丝瓜络三钱。炒枳实一钱半。陈胆星炖和服八分。晚蚕砂五钱。姜竹沥四两冲药送滚痰丸二钱。龙荟丸一钱。此证脉迟缓。系痰阻气机。非脾阳虚弱。盖脾阳虚弱。断不用滚痰龙荟二丸。）", "14141": "吴某年逾花甲。素患脘痛。以为虚寒。辄服温补。久而益剧。孟英诊曰：肝火宜清。彼不之信。延至仲夏。形已消瘦。倏然浮肿。胁背刺痛。气逆不眠。心辣如焚。善嗔畏热。大便时泻。饮食下咽即吐。诸医束手。恳治孟英。脉弦软而数。予竹茹黄连枇杷叶知母栀楝旋赭等药而吐止。饮食虽进。各恙未已。投大剂沙参生地龟板鳖甲女贞旱莲桑叶丹皮银花茅根茹贝知柏枇杷叶菊花等药出入为方。二三十剂后。周身发疥疮而肿渐消。右耳出黏稠脓水而泻止。此诸经之伏热得以宣泄也。仍以此药令其久服。迨秋始愈。（此病本系肝阳侮胃。温补肝风遂炽。形已消瘦八句。内风已动。姜竹茹三钱。姜川连一钱。姜知母三钱。姜栀皮三钱。楝核杵先二钱。旋覆包先三钱。生赭石杵先一两六钱。姜枇叶刷包三钱。续方。大生地泡煎去渣八钱。血鳖甲杵先煨六钟四两。女贞杵先五钱。旱莲草四钱。济银花一两五钱。姜竹茹三钱。川贝杵八钱。酒炒知母四钱。嗣去竹茹知母。加血龟板二两同杵先。姜枇叶刷包三钱。酒炒川黄柏三钱。再更方。去枇叶旱莲草。加酒炒茅根五钱。再更方。去贝母加冬桑叶四钱。再更方。去桑叶。加杭白菊三钱。酒炒丹皮次入二钱。）", "14142": "比邱尼体厚蹒跚。偶患眩悸。医以为虚。久服温补。渐至发肿不饥。仲夏孟英视之。脉甚弦滑。舌色光绛。主清痰热。尽撤补药。彼不之信。仍服八味等方。至季夏再屈孟英诊之。脉数七至。眠食尽废。不可救药矣。（清痰热方。酒炒知母四钱。酒炒川连一钱。生冬瓜子八钱。姜竹沥四两冲。济银花一两五钱。鲜竹叶二钱。石斛先煎一两。陈胆星炖和服一钱。蒌仁研四钱。姜竹茹三钱。荸荠打汁冲二两。此证发肿不饥。为肝风暗动。）", "14143": "朱妇初患目赤。服药后渐至满面红肿。壮热神昏。医皆束手。孟英切脉洪实滑数。舌绛大渴。腹微胀。以酒洗大黄犀角元参滑石甘草知母花粉银花黄芩连翘薄荷菊花丹皮两下之径愈。（脉洪实滑数。为实热挟阴虚。酒洗大黄先煎四钱。镑犀角先煎八钟四钱。元参片泡煎去渣一两。西滑石先煎五钱。生粉草一钱半。酒炒知母三钱。南花粉五钱。济银花先煎一两五钱。酒炒枯芩一钱半。连翘壳三钱。薄荷尖四分。杭菊花三钱。丹皮二钱。犀角元参知母银花息风救液。）都城售透土长寿丹。孟英谓执一方以疗百病。无此治法。况以绿豆汤为引。必有热毒之品在内。王雪山久患下部畏冷。吞未百丸。齿痛目赤。诸恙蜂起。孟英察脉弦滑。予多剂石膏药。兼以当归龙荟丸频服。新疾既瘳。腿亦渐温。令其常饮柿饼汤以杜将来之恙。（生石膏先煎一两六钱。酒炒知母四钱。生绿豆二两。生粉草一钱半。济银花一两五钱。晚蚕砂五钱。两头尖三钱。省头草三钱。楝核杵先三钱。药送龙荟丸三钱。旋覆包先三钱。生赭石杵先一两六钱。）", "14144": "广孔愚子仲秋患闲疟。寒少热多。面目甚黄。苔腻大渴。腹胀溺赤。仍能纳谷。且素嗜肥甘。不能撙节。孟英按其脉滑实而数。予承气加知芩半贝翘连滑石石膏大腹花粉之类二十余剂而始愈。是膏粱挟暑湿热之治也。（此证病在气分。脉滑实而数。为痰热挟阴虚。花粉生津顾阴。余皆泻实之品。酒洗生厢黄四钱。酒炒知母三钱。酒炒枯芩一钱半。制半夏二钱。川贝杵五钱。连翘壳三钱。西滑石先煎五钱。酒炒川连一钱。生石膏先煎一两二钱。大腹皮酒洗次入一钱半。南花粉五钱。）", "14145": "王瘦石禀属阴亏。卒闻惊吓之声。而气逆肢冷。自汗息微。孟英视之。身面皆青绿之色。脉沉弦而细。乃素伤忧虑而风阳陡动也。予牡蛎四两。鳖甲二两。蛤壳一两。石英五钱。龙齿小麦辰砂麦冬茯神贝母竹茹为方。一剂知。二剂已。续以滋养而瘳。（煅龙齿杵先一两。北小麦四钱。整辰砂杵先一两二钱。花麦冬四钱。云茯神三钱。川贝杵五钱。姜竹茹三钱。）", "14146": "陈书伯弟年未冠。患失音咽痛。孟英予犀羚石膏元参豆根牛蒡射干等大剂清肃之药。音开而咽糜。吹以锡类散。糜愈而疹点满布。左目及耳后皆肿。方中加以鲜菊叶二两。疹愈。痰嗽不已。仍主前法。服三十余帖而痊。此证脉滑且数。口大渴。初终未曾误药。故能愈。其庶母同时患喉糜。而头偏左痛。心悸欲呕。壮热烦躁。脉弦细数。孟英曰此兼阴亏风动也。初以犀羚元参菊花丹参栀子桑叶马勃投之。外吹锡类散。咽愈热退。续用二至二冬生地石英苁蓉龟板茯苓滋阴潜阳而瘳。其妹亦患喉疹。汛事适行。四肢酸痛。略难举动。气塞于咽。孟英诊脉弦滑。以犀羚旋赭茹贝兜铃牛蒡射干豆根花粉银花海䖳竹沥丝瓜络等出入为方。兼吹锡类散而瘥。（玩方药必系肝风袭肺失音。镑犀角四钱。羚次尖四钱。同先煎八钟。生石膏先煎一两二钱元参片泡冲去渣一两酒炒山豆根二钱姜炒牛蒡子研三钱姜射干三钱。嗣加鲜菊叶打冲二两。陈书伯庶母阴亏风动方。镑犀角四钱。羚次尖四钱。同先煨八钟。元参片泡煎去渣一两。杭白菊三钱。紫丹参三钱。黑栀皮三钱。冬桑叶四钱。马勃一钱半。续方女贞杵五钱。旱莲草四钱。明天冬切六钱。花麦冬四钱。紫石英杵先三钱。淡苁蓉一钱半。血龟板杵先煨八钟四两。云苓三钱。陈书伯妹喉疹。风动煽痰逆升。镑犀角四钱。羚次尖四钱。同先煎。旋覆包先三钱。生赭石杵先一两六钱。姜竹茹三钱。川贝杵四钱。马兜铃三钱。姜射干二钱。酒炒豆根一钱。南花粉四钱。四帖后去犀羚旋赭。加济银花一两五钱。淡海䖳先煎二两。丝瓜络三钱。）", "14147": "吴尔纯八月下旬患滞下。腹痛异常。孟英往诊。形瘦脉数而弦。口渴音微溺涩。乃阴分极虚。肝阳炽盛，伏暑为痢。治法不但与寒痢迥异。即与他人之伏暑成痢者。亦当分别用药也。予白头翁汤加知母花粉银花丹皮金铃延胡沙参芩连服之。次日复视。痢减音开。而右腹痛胀拒按。为加冬瓜子乌药鼠矢三剂而消。滞下亦愈。惟薄暮火升。面赤自汗。重加介类潜阳而痊。（重用苦寒泻暑。则肝阳无所凭借。花粉银花丹皮沙参微顾其阴。酒炒白头翁一钱半。酒炒知母三钱。楝核杵先二钱。酒炒枯芩一钱半。酒炒川连一钱。南花粉五钱。济银花一两五钱。酒炒粉丹皮二钱。元胡索次入一钱半。北沙参八钱。续加生冬瓜子四钱。台乌药次入一钱半。两头尖三钱。薄暮火升。面赤自汗。去花粉沙参芩连冬瓜子丹皮。加煅牡蛎杵四两。血龟板杵二两。生蛤壳杵一两。同先煨八钟。）", "14148": "杨某患感旬日。初则便溏。医予温散。泻止热不退。昼夜静卧。饮食不进。孟英诊脉迟缓。浮取甚微。目眵。舌色光红。口不渴。溲亦行。胸腹无所苦。语懒音低。寻即睡去。是暑湿内伏。而有燥矢在胃。机关为之不利也。先予清营通胃药二剂。热退舌淡而脉证依然。加以酒洗大黄。省头草。即下坚黑燥矢甚多。而睡减啜粥。继以凉润。旬日而痊。（脉迟缓九句。皆暑湿内伏。燥矢在胃之情状。暑湿内伏结成燥矢在胃。则气机不利。邪热升浮。故脉迟缓。浮取甚微。目眵。舌色光红。病不在肺。故口不渴。溲亦行。胸腹无所苦。心胃位次相近。燥矢在胃。热蒸心脏。神志不遂其发舒。故语懒音低。寻即睡去。清营通胃方。济银花一两五钱。鲜茅根五钱。鲜竹茹三钱。丝瓜络三钱。黑栀皮三钱。苦杏仁一钱半。炒枳实一钱。川贝杵五钱。生神曲杵二钱。嗣于方中加酒洗生厢黄四钱。省头草三钱。凉润方。鲜竹叶二钱。鲜枇叶刷包三钱。鲜芦根二两。济银花一两。川贝杵五钱。蒌仁研四钱。云苓一钱半。南花粉五钱。整荸荠打二两。制半夏一钱半。）", "14149": "陈春湖子体素弱。季秋患腹痛自汗。肢冷息微。咸谓元虚欲脱。孟英诊之。脉虽沉伏难寻。而苔色黄腻。口干溺赤。当从证也。予连朴楝栀元胡蚕砂省头草等药而康。又孟英视钱妪腹痛欲绝。证因见弦滑之脉。予当归龙荟丸而安。（陈子方。酒炒川连一钱。楝核杵先四钱。制厚朴次入一钱。黑栀皮三钱。元胡索次入一钱半。晚蚕砂五钱。省头草次入三钱。钱妪脉弦滑。为肝热煽痰贼胃。）", "14150": "朱妇患小溲涩痛。医予渗利。反发热头痛。不饥口渴。夜不成眠。孟英诊之。脉细数。乃阴虚肝郁。化热生风。津液已烁。岂容再利。予白薇栀子金铃知母花粉紫菀麦冬石斛菊花服之即愈。其侄媳怀娠患痢。医投温燥止涩。腹痛甚而发遍身黄。饮食不思。孟英视之。暑湿也。予芩连银花茅根桑叶栀楝竹叶茵陈冬瓜皮而愈。（小溲涩痛。为阴虚挟热。渗利则愈伤其阴。肝热至于发热头痛不饥不眠。则肝风炽逆矣。口渴为肝阳灼肺。香白薇三钱。黑栀皮三钱。楝核杵先四钱。酒炒知母三钱。南花粉五钱。紫菀茸一钱半。花麦冬八钱。石斛先煎一两。杭白菊四钱。热痢宜以凉泻为治。温燥止涩。则暑湿上蒸于肌肤而身黄。窒塞于肺胃而厌食。病邪皆在气分。酒炒枯芩一钱半。酒炒川连八分。济银花八钱。酒拌茅根五钱。冬桑叶三钱。黑栀皮三钱。鲜竹叶二钱。酒炒西茵陈一钱。冬瓜皮四钱。）", "14151": "吴媳汛愆而崩之后。脘痛发厥。自汗肢冷。孟英诊之。细而弦滑。口苦便涩。乃素体多痰。风阳内鼓。虽当崩后。病不在血。予旋赭羚茹枳贝薤蒌蛤壳为方。痛乃渐下。厥亦止。再加金铃延胡苁蓉鼠矢服之而愈。迨季冬因卒惊发狂。笑骂不避亲疏。孟英察脉弦滑而数。予犀羚元参丹皮丹参栀子菖蒲竹叶鳖甲竹沥吞当归龙荟丸。息风阳以涤痰热。果数剂而安。然平时喜服补药。或有眩晕。不知为风痰内动。益疑为元气大虚。孟英尝谏阻之。而彼不能从。至次年季春因伤感而狂证陡发。毁器登高。更甚于昔。孟英视之。苔黑大渴。予前方加真珠牛黄。服之苔色转黄。弦滑之脉略减。而狂莫可制。改以石膏朱砂铁落菖蒲青黛知母胆星鳖甲金铃旋覆元参竹沥为大剂。送礞石滚痰丸。四服而平。继而脚气大发。腹痛便秘。上冲于心。肢冷汗出。昏运欲厥。予连楝栀茹小麦百合旋贝元胡乌药雪羹石英鼠矢黄柏藕等药而安。（脘痛发厥二句。本系血去阴伤。风阳陡动。细而弦滑。为阴虚肝热煽痰。口苦便涩。病邪在气。旋覆包先三钱。生赭石一两六钱。杵先煎八钟。羚次尖先煎五钱。姜竹茹三钱。炒枳实一钱半。川贝杵八钱。西薤白打次入一钱半。姜蒌仁研四钱。生蛤壳杵先五钱。风阳炽盛之时。遽予苦寒。病情反形格拒。惟先以旋赭羚蛤息风镇逆。先引药势下行。然后再投川楝苦寒。脉细则阴中之阳亦虚。故用苁蓉。且非补其阴中之阳。则苦寒泻热之品。不能交济以有成。元胡亦咸苦泻肝药中所必资以反佐。鼠矢咸寒。针治便涩。楝核杵先四钱。元胡索一钱半。淡苁蓉一钱半。鼠矢三钱。脉弦滑而数。文义注重数字。病情为风阳煽痰。兼挟阴虚。犀羚鳖甲元参竹沥息风救液治其本。余药及龙荟丸泻肝清热治其标。镑犀角四钱。羚次尖四钱。同先煎八钟。元参片泡煎去渣一两。粉丹皮二钱。紫丹参三钱。黑栀皮三钱。石菖蒲次入二钱。鲜竹叶二钱。血鳖甲杵先四两。姜竹沥两大酒杯冲。药送龙荟丸三钱。前方加舌餂药送真珠粉一分。西牛黄二厘。改以生石膏先煎一两六钱。整朱砂先煎一两六钱。飞铁落包先四钱。飞青黛一钱。酒炒知母三钱。陈胆星炖和服一钱。血鳖甲杵先二两。楝核杵先四钱。旋覆包先三钱。元参片泡冲去渣八钱。姜竹沥两大酒杯冲。药送礞石滚痰丸四钱。腹痛便秘四句。为风阳炽逆。酒炒川连一钱。楝核杵先三钱。黑栀皮三钱。姜竹茹三钱。北小麦四钱。百合花三钱。旋覆包先三钱。川贝杵八钱。台乌药一钱。元胡索一钱半。淡海䖳先煎二两。整荸荠一两。紫石英杵先五钱。鼠矢三钱。酒炒川黄柏一钱半。连皮藕切先二两。此病计共四正方。第一方主清痰热。第二方主息风阳。第三方主清痰热。第四方主息风阳。相似而实不同。）", "14152": "徐妇怀妊患痢。医投温补。胸腹痛极。昏厥咽糜。水饮碍下。孟英诊之。脉洪数。舌绛燥。亟吹锡类散。灌以犀角元参海䖳茹贝栀菀知斛豆根射干银花楝实诸药。胎下已朽。咽腹之疾随愈。续用甘凉清热存津调之。（病情为热实阴虚。肝风逆上。胸腹痛极三句。风阳逆干肺胃。方义注重息风。镑犀角先煎四钱。元参片泡煎去渣一两。淡海䖳先煎二两。姜竹茹三钱。川贝母杵四钱。黑栀皮三钱。紫菀茸一钱半。酒炒知母三钱。石斛先煎一两。酒炒山豆根一钱。姜射干三钱。济银花一两五钱。楝核杵先二钱。）", "14153": "许培之祖母。年逾七旬。久患淋漏。屡发风斑。孟英持其脉弦而滑。舌绛口干。每以犀角生地二至芩蒿白薇元参龟板海螵之类息其暴。甘露饮增损调其常。人皆疑药过凉。孟英曰：量体裁衣。病属阳旺。气血有余。察其脉色。治当如是。病者乃云：十余年前。偶患崩而广服温补。遂成此恙。始知先天阳气虽充。亦由药酿为病。秋杪患寒热如疟。善怒不眠。苦渴易饥。不能纳食。孟英察脉弦数倍常。予清肺蠲痰柔肝充液之法。渐以向安。今冬某诊。询知病原。作高年脱营论。以血脱益气裁方。初服三四剂。饮食骤增。已而血漏甚多。眠食欲废。复延孟英视之。仍主前议。果得渐康。（久患淋漏二句。为血亏风动。脉弦而滑。为风阳煽痰。舌绛口干。为阴虚热炽。镑犀角四钱。先煎八钟。大生地泡煎去渣八钱。女贞杵五钱。旱莲草四钱。酒炒枯芩三钱。鲜青蒿一钱半。香白薇三钱。血龟板杵先四两。元参片泡煎去渣一两。醋炙海螵蛸杵先四钱。清肺蠲痰柔肝充液方。善怒不眠三句。病情为风阳贼肺。方义主息风阳。大生地八钱。元参片一两。二味泡煎去渣。济银花一两五钱。石斛先煎一两。生石膏先煎一两六钱。大豆卷三钱。淡海䖳先煎二两。荸荠一两。旋覆包先三钱。生赭石杵先二两。豆卷针治寒热如疟。）", "14154": "王妇年五十余。初患左目赤。渐至发热。医投温散。便泄而厥。进以补剂。少腹宿瘕攻痛。势极危殆。孟英诊之。脉甚弦耎。舌绛而渴。予苁蓉橘核当归元胡龟板石英螵蛸茯苓栀楝萸连数服而安。（此病肝风内动故厥。肝风一动。则周身之气逆上。故少腹宿瘕攻痛。脉弦为阴虚肝热。脉耎为阴中之阳虚。重用龟板石英以潜镇。血龟板杵四两。紫石英杵五钱。醋炙海螵蛸杵四钱。三味先煨八钟。淡苁蓉三钱。橘核杵次入一钱。箱归身二钱。元胡索一钱半。云苓三钱。黑栀皮三钱。楝核杵先三钱。淡吴萸六分。酒炒川连八分。）", "14155": "何女孟冬分娩。次日便泻一次。即发热痉厥。谵语昏狂。孟英审之。脉弦滑。恶露仍行。曰此胎前伏暑。乘新产血虚痰滞而发也。予大剂犀羚元参竹叶知母花粉栀楝银花投之。遍身得赤疹而痉止神清。随以清肃调之而愈。（胎前伏暑。乘新产血虚痰滞而煽发风阳。镑犀角四钱。羚次尖四钱。楝核杵三钱同先煎八钟。元参片泡冲去渣八钱。鲜竹叶二钱。酒炒知母三钱。南花粉五钱。酒炒栀皮三钱。济银花一两五钱。方义主息风阳以涤痰热。）", "14156": "胡女年甫笄往岁患眩晕。孟英切其脉滑。作痰治。服一二剂未愈。更医谓虚。进以补药颇效。渠信为实。然今冬复病。径服补药。半月后眠食皆废。闻声惊惕。寒颤自汗。肢冷如冰。以为久虚欲脱。乞援孟英。脉极细数。目赤便秘。胸下痞塞如柈。力辨其非虚证。盖痰饮为患乍补每若相安。具只眼者始不为病所欺也。投以旋赭茹贝蛤壳花粉桑栀蒌薤连枳等药数服即安。而运不能止。乃去赭薤蒌枳加元参菊花二至三甲之。类服匝月始能起榻。（此证阴虚痰实。脉滑废食。皆为痰实。脉极细数。为阴虚挟热。便秘胸痞皆胃实。目赤为痰郁生火。温补助热酿痰。蠲痰即以涤热。旋覆包先三钱。生赭石杵先一两二钱。姜竹茹三钱。川贝杵四钱。生蛤壳杵先五钱。姜花粉四钱。冬桑叶二钱。姜栀皮三钱。姜蒌皮三钱。西薤白打一钱半。姜川连八分。炒枳实一钱半。嗣去赭薤蒌枳。加元参片八钱。杭白菊二钱。女贞杵五钱。旱莲草四钱。煅牡蛎杵四两。血鳖甲杵二两。血龟板杵一两。）", "14157": "汪妇自孟秋患痢之后。大解溏泄未愈。已而怀娠。恐其堕也。投补不辍。延至仲冬。两目赤障满遮。气逆碍眠。脘痛拒按。痰嗽不食。苦渴无溺。孟英诊之。脉甚滑数。曰此温补所酿之疾也。夫秋间滞下。原属暑湿热为病。既失清解。逗留而为溏泄。受孕以来。业经四月。虑其堕而补益峻。将肺胃下行之令皆挽以逆升。是以胸次堵塞而痛。喘嗽不能卧。又恐其上喘下泄而脱也。补之愈力。治节尽废。溲闭不饥。浊气壅至清窍。两目之所以蒙障而瞽也。予沙参蛤壳枇杷叶冬瓜子海石旋覆苏子杏仁黄连枳实海䖳黄芩栀子。重加贝母。服二剂即知饥下榻。目能睹物矣。（温补酿痰。兼灼阴液。故蠲痰方中参用沙参海䖳。盖阴不复。热痰亦不化。北沙参八钱。生蛤壳海浮石各五钱同先煎。姜枇叶刷包三钱。生冬瓜子四钱。旋覆包先三钱。生苏子研二钱。姜川连八分。炒枳实一钱半。淡海䖳先煎二两。姜枯芩一钱半。姜栀皮一钱半。川贝杵八钱。）", "14158": "许仲筠患腹痛不饥。医予参附姜术诸药。疼胀日加。水饮不沾。沉沉如寐。孟英诊脉弦细。苔色黄腻。投以枳朴萸连栀楝香附蒺藜延胡等药。二剂便行脉起。苔退知饥而愈。（脉弦为肝热。脉细为阴虚中兼挟阳虚。炒枳实一钱半。制厚朴一钱。淡吴萸六分。姜栀皮三钱。姜川连一钱。楝核杵先三钱。生香附八分。生白蒺三钱。元胡索一钱半。）", "14159": "毕室患痰嗽碍眠。医予补摄而至涕泪全无。目闭不饥。二便涩滞。干嗽无痰。气逆自汗。孟英切脉右寸沉滑。左手细数而弦。乃高年阴亏。温邪在肺未经清化。率为补药所锢。宜开其痹而通其胃。予蒌薤紫菀兜铃杏贝冬瓜子甘桔旋茹之剂而安。（肺肾为子母之脏。肺脏邪去气行。自能荫庇肝肾。虽阴亏无须滋补。治法宜清通肺胃。脉沉滑。故参用桔薤以开提。姜蒌仁研四钱。西薤白打一钱半。紫菀茸一钱半。马兜铃三钱。苦杏泥二钱。川贝杵五钱。生冬瓜子四钱。生粉草一钱。苦桔梗一钱半。旋覆包先三钱。姜竹茹三钱。）", "14160": "赖母年近古稀。患左半不遂。医予再造九暨补剂。服二旬病如故。孟英按脉弦缓而滑。颧赤苔黄。音微舌謇。便涩无痰。曰此痰中也。伏而未化。予犀羚茹贝菖夏花粉知母白薇豆卷桑枝丝瓜络等药。服三剂而苔化音渐清朗。六七剂腿知痛。痰渐吐。便亦通。既而腿痛难忍。其热如烙。孟英令涂葱蜜以吸其热。痛果渐止。半月后眠食渐安。二旬外手能握。月余可扶掖以行矣。（颧赤苔黄三句。为肝风内动。气机失其升降。方义以息肝风调升降为主要。镑犀角四钱。羚次尖四钱。同先煎八钟。姜竹茹三钱。川贝杵五钱。石菖蒲次入一钱。制半夏一钱半。南花粉四钱。香白薇三钱。大豆卷一钱半。姜汁炒桑枝三钱。丝瓜络三钱。）", "14161": "赵春山向患痰嗽。自仲秋以来。屡发寒热。吴古年从伏暑化疟治。颇为应手。而一旬半月之后。病必复至。延至季冬。孟英按脉滑数。舌绛苔黄。渴饮溲赤。动则喘逆。夜不成眠。痰多畏冷。膏粱酿痰。温补助热。是为病根。迨夏吸暑邪。互相𫐖轕。秋半而发。势颇类疟。古年虽识其证。惜手段小耳。因予羚羊豆豉连翘薄荷知母花粉竹茹贝母旋覆海䖳元参栀子省头草梨汁等药。服五剂。热退不畏冷。去前四味。加沙参麦冬葳蕤枇杷叶。渐能安寐。各恙递减。再加生地。服匝月而体健胜昔。登高不喘。（羚次尖五钱。先煨八钟。炒豆豉三钱。连翘壳三钱。薄荷尖一钱半。酒炒知母四钱。南花粉四钱。姜竹茹三钱。川贝杵五钱。旋覆包先三钱。淡海䖳先煎二两。元参片泡冲。去渣八钱。姜栀皮三钱。省头草三钱。整北梨一两打汁冲。嗣去前四味。加元沙参八钱。花麦冬四钱。肥玉竹三钱。鲜枇叶刷包三钱。）", "14162": "陈秋槎大便骤下黑血数升。继即大吐鲜红之血。而汗出神昏。肢冷搐搦。躁乱妄言。孟英察其脉。左手如无。右弦耎。按之数。高年阴分久亏。肝血大去。风阳陡动。殆由忿怒兼服热药所致。其妻云。日来颇有郁。冬间久服姜枣汤。且饮都中药烧酒一瓶。孟英曰：是矣。以西洋参犀角生地银花绿豆栀子元参茯苓羚羊茅根为剂。冲入热童溲灌之。（脉以沉分为主。按之数。阴虚挟热。此方系脉证互参。西洋参三钱。镑犀角羚次尖各四钱。同炭煨八句钟。元参片一两。大生地八钱。泡煎去渣。济银花一两五钱。生绿豆一两。黑栀皮三钱。云茯苓三钱。鲜茅根五钱。童便一大酒杯煎去头尾冲。）外以烧铁淬醋令吸其气。龙牡研粉扑汗。生附子捣贴涌泉穴。引纳浮阳。两服血止。左脉渐起。又加以龟板鳖甲（血龟板杵四两。血鳖甲杵二两。二味同先炭煨六句钟。）服三帖神气始清。各恙渐息。稍能啜粥。乃去犀羚。加麦冬天冬女贞旱莲投之。（花麦冬四钱。明天冬切六钱。女贞子杵五钱。旱莲草四钱。）眠食日安。半月后始解黑燥矢。两旬外便溺之色始正。予滋补药调痊。", "14163": "姚令舆室素患喘嗽。而病春温。医知其本元久亏。投以温补。痉厥神昏。耳聋谵语。面青舌绛。痰嗽不眠。孟英诊之。脉犹弦滑。曰：证虽危险。生机未绝。予犀角羚羊元参沙参知母花粉石膏。以清热息风救阴生液。（镑犀角羚次尖同先煎各四钱。元参片泡煎去渣一两。北沙参八钱酒炒知母四钱。南花粉四钱。生石膏先煎一两六钱。）佐苁蓉石英鳖甲金铃旋覆贝母竹沥。以潜阳镇逆。通络蠲痰。（淡苁蓉一钱半。作潜阳反佐。紫石英杵三钱。血鳖甲杵二两。楝核杵三钱。旋覆包先三钱。四味同先煨八句钟。川贝母杵一两。姜竹沥两大酒杯冲。以咸苦潜镇之品。引药力下行。合贝沥为降中有升。）三剂而平。继去犀羚石膏。加生地。（大生地泡煎去渣八钱。）服旬日而愈。", "14164": "马香谷患溺秘欲死。孟英视之。脉坚体厚。口渴苔黄。（脉坚则阳实。阳实则能任苦寒。）投知柏栀楝犀苑蒌茹之药。送当归龙荟丸而瘳。竟不复发。（酒炒知母三钱。酒炒川黄柏一钱。黑栀皮三钱。川楝核杵先三钱。镑犀角先煨八钟四钱。蒌仁研四钱。姜竹茹四钱。药送龙荟丸三钱。肝为风脏。肝热极为风升。风升则周身之气不降。溺秘欲死者。内风升也。犀角靖内风。）", "14165": "谢某患嗽。卧难偏左。孟英切其脉。右寸耎滑。曰：此肺虚而痰贮于络。以苇茎丝瓜络生蛤粉贝母冬瓜子茯苓玉竹枇叶燕窝梨肉投之果愈。（脉耎正虚。脉滑痰实。姜汁拌芦根八钱。丝瓜络三钱。生蛤粉包先四钱。川贝母杵八钱。生冬瓜子四钱。云茯苓三钱。肥玉竹三钱。姜枇叶刷包三钱。燕窝包先三钱。连皮梨肉四钱。）", "14166": "许叔超祖母患疟。孟英治之。脉弦滑而数。脘闷便秘。合目汗出。口渴不饥。或虑高年欲脱。孟英曰：此温邪挟素盛之痰所化。补药断不可投。予知芩蒌杏翘贝旋茹连斛雪羹为方。服果渐效。（脉弦为肝热。滑为痰。数为阴虚挟热姜汁炒知母三钱。姜枯芩一钱。姜川连八分。蒌仁研三钱。苦杏泥次入二钱。连翘壳三钱。川贝母杵四钱。旋覆包先三钱。姜竹茹三钱。石斛先煎一两。淡海䖳先煎二两。整荸荠一两。合目汗出为阴虚阳浮。阴不复则阳不靖。阳不靖则气不降。气不降则痰亦不行。故用石斛雪羹。）", "14167": "蒲艾田年逾花甲。陡患鼻衄。诸法不止。孟英诊之。面色黑黯而有红光。脉弦洪而芤。询知冬间广服助阳药。是热亢阴虚之质。予大剂犀角元参茅根女贞旱莲石斛茯苓泽泻天冬知母。（脉情为热实阴虚。镑犀角先煎八钟四钱。元参片一两。明天冬切八钱。开水泡冲去渣鲜茅根五钱。女贞杵先五钱。旱莲草四钱。石斛先煎一两。生泽泻一钱。酒炒知母四钱。投匕而安。续予滋阴药填补而康。鼻衄不止。则风升而肝血随之。故以救液息风为要。）", "14168": "许少卿妻夏初患感。何某十进清解。病不略减。邀诊孟英。脉至弦洪豁大。左手为尤。大渴大汗。能食妄言。面赤足冷。彻夜不瞑。孟英曰：证虽属温。而真阴素亏。久伤思虑。心阳外越。内风鸱张。幸未投温散。尚可无恐。予龙牡犀珠龟板鳖甲贝母竹沥竹叶辰砂小麦元参丹参生地麦冬为大剂投之。（十进清解。下虚而治其上。故病不略减。弦洪豁大左手为尤。血分之阴虚也。大渴为热灼肺阴。大汗为阴虚阳越。能食为风消。妄言为肝热侵营。足冷为热邪伤肺。气不下行。彻夜不瞑。则尤为风升阳浮确据。煎龙骨杵一两。煅牡蛎杵六两。镑犀角四钱。血龟板杵四两。血鳖甲杵二两。整辰砂杵一两二钱。六味先炭煨八钟。取汤代水煎药。川贝母杵四钱。姜竹沥一大酒杯冲。竹叶次入二钱。北小麦四钱。紫丹参三钱。元参片一两。大生地八钱。花麦冬五钱。开水泡冲去渣。）外以烧铁淬醋令吸其气。蛎粉扑止其汗。生附子捣贴涌泉穴（引纳浮阳。）渐以向愈。而阴不易复。频灌甘柔滋镇。月余始能起榻。季夏汛行。惟情志不怡。易生惊恐。予麦参熟地石英茯神龙眼甘麦大枣三甲等药善其后。（煅牡蛎杵六两。血鳖甲杵四两。血龟板杵二两。紫石英杵三钱。四味先煨六钟。取汤代水煎药。花麦冬四钱。北沙参五钱。大熟地八钱。云茯神三钱。桂元肉一钱半。生粉草三钱。北小麦四钱。）秋杪归宁。微吸客邪。孟英投以清解。已得向安。（清解方。酒炒知母四钱。黑栀皮三钱。炒豆豉一钱半。鲜枇叶刷包三钱。鲜芦根一两。西滑石先煎四钱。枯茅杆三钱。石斛先煎八钱。淡海䖳先煎八钱。苦杏泥次入一钱半。）", "14169": "周鹤亭子年甫五龄。痘后月余。清凉药尚未辍。忽发壮热。幼科治之。势益张。肢瘈面赤。呕吐苔黄。渴而溺清。时或昏厥。证交六日。孟英诊之。脉甚弦洪滑数。心下拒按。便秘汗多。投小陷胸加石膏知母花粉竹叶枇叶贝母雪羹。（玩溺清及时或昏厥。痰热全在肺经气分。洪数为阴虚挟热。故用雪羹。半夏合石膏辛凉解表。合知连辛苦豁痰。姜炒川连四分。制半夏研次一钱半。蒌仁研一钱半。生石膏先煎五钱。姜炒知母一钱半。南花粉一钱半。鲜竹叶八分。川贝母杵三钱。姜枇叶刷包一片。整荸荠四钱。淡海蜇先煎八钱。）二剂各恙皆减。溲赤便行。继予清养而安。（清养方。去蒌连石膏竹叶。加西洋参一钱。北沙参二钱。石斛先煎三钱。旋覆包先一钱。炒冬瓜子一钱半。北梨肉三钱。）", "14170": "费伯元患烦躁不眠。医见苔白。投以温药。因而狂妄瘛疭。多方不应。孟英视之。左脉弦细而数。右耎滑乃阴虚之体。心火炽肝风动而痰盛于中也。先以犀羚桑菊息其风。元参丹皮莲心童溲清其火。茹贝雪羹化其痰。（左细数为血分阴虚左弦细合狂妄瘛疭。为阴虚而心火炽肝风动。右耎滑为痰盛于中。镑犀角羚次尖。同先煨八钟各四钱。冬桑叶四钱。杭白菊三钱。元参片泡冲去渣一两。粉丹皮二钱。莲子心一钱。姜竹茹四钱。川贝母杵八钱。整荸荠一两。淡海蛰二两先煎。）随与三甲二至磁朱潜其阳。甘麦大枣缓其急。地黄麦冬养其阴。渐次康复。（续方去犀羚桑叶。加煅牡蛎杵四两。血鳖甲杵二两。血龟板一两。女贞杵五钱。旱莲草四钱。灵磁石一两。大辰砂八钱。三甲磁朱先煨八钟。取汤代水煎药。更方去丹皮竹茹。加生粉草三钱。北小麦四钱。大枣擘先一枚。再更方去童溲贝母。加大生地八钱。花麦冬四钱。）", "14171": "何搢阶妻素患肝厥。仲夏患感。沈樾亭按温证法治之。内风不致陡动。而大便泄泻。脉细而弦。渴饮痰多。不饥不寐。孟英商投白头翁汤加三甲石斛茯苓竹茹而安。随以峻补善后而痊。（辨证在不饥不寐。不饥不寐为热炽阳浮。肝风暗动。白头翁一钱半。酒炒川连一钱。酒炒黄柏三钱。云苓三钱。姜竹茹四钱。煅牡蛎杵六两。血龟板杵四两。血鳖甲杵二两。三味同先煨八钟。取汤代水煎药。峻补方。大生地八钱。明天冬切六钱。花麦冬四钱。女贞杵五钱。川贝杵四钱。赖橘红一钱。云茯苓三钱。陈木瓜一钱半。楝核杵先四钱。血鳖甲杵四两。血龟板杵一两。三味先煨八钟。取汤代水煎药。清阿胶炖和服二钱。）", "14172": "许氏妇患间疟。寒少热多。不饥大渴。善呕无汗。脉滑而弦。孟英投白虎汤加花粉柴胡而愈。（不饥大渴善呕。皆阳升不降之象。无汗为阳郁极不能自达。脉滑挟痰。脉弦阴虚挟热。生石膏先煎一两六钱。酒炒知母四钱。南花粉一两。春柴胡次入三钱。）", "14173": "吴酝香媳时患腹胀减餐。牙衄腿痛。久治不效。肌肉渐消。孟英诊脉。弦细而数。肝气虽滞。而阴虚营热。岂辛通温运之可投耶。以乌梅黄连楝芍栀子木瓜首乌鳖甲茹贝服之果愈。（脉弦数为阴虚挟热。细为阴虚中兼挟阳虚。腹胀减餐。为肝阳侮胃。牙衄腿痛为肝胃热结。肌肉渐消。为肝风消烁。方义以酸苦泄肝治其标。以首乌鳖甲潜阳益肝治其本。乌梅肉杵三钱。酒炒川连一钱。酒炒楝核先三钱。整大白芍杵先一两。黑栀皮三钱。陈木瓜一钱半。制首乌一钱半。血鳖甲杵先煨八钟二两。姜竹茹次入三钱。川贝母杵四钱。甘润滋镇方。大生地八钱。柿饼肉五钱。生粉草三钱。肥玉竹三钱。乌梅肉一钱半。楝核杵先四钱。青果杵先二钱。生冬瓜子四钱。生苡仁杵八钱。山萸肉一钱半。血鳖甲二两杵。煅赭石八钱。紫石英三钱。同先煨八钟。）肌充胃旺。汛准脉和。积岁沉疴若失。", "14174": "顾云萝妻久患脚气。屡治屡发。驯致周身筋掣。上及于巅。龈痛齿麻。腰酸目眩。口干食少。夜不能眠。孟英察其脉。芤而弦数。真阴大亏。腿虽痛。从无赤肿之形。脚气药岂徒无益。予二地二冬二至知柏桑菊栀楝蒿薇龟板鳖甲藕等药。服之各恙渐减。盖因平素带下太甚。阴液漏泄而筋骨失其濡养也。故治病须澄源以洁流。（大熟地八钱。干生地一两。明天冬切六钱。花麦冬四钱。女贞杵五钱。旱莲草四钱。酒炒知母三钱。酒炒川黄柏一钱。鲜青蒿一钱半。酒炒白薇一钱。醋炙血鳖甲二两。醋炙血龟板一两。同先煨八钟。藕二两切先。）秋间以海螵蛸粉鱼膘黄柏阿胶为丸。服之全愈。（海螵蛸粉二两。炒川黄柏八两。线鱼胶一两。阿胶四两。合溶搓丸梧子大。晚膳前稀米汤下四钱。）", "14175": "石北涯妻久患龈痛。渐至身面浮肿。或以为虚。或以为湿。病日以剧。气逆不饥。孟英察脉。左洪数。右弦滑。阴分虽虚。先当清其肺胃之痰热。投白虎加沙参花粉冬瓜皮枇叶栀子竹茹芦根。服之肿即消。继佐滋阴。龈痛亦止。（此证右脉弦滑。必较甚于左脉。生石膏先煎一两二钱。酒炒知母四钱。北沙参八钱。南花粉四钱。冬瓜皮三钱。姜枇叶刷包三钱。黑栀皮三钱。姜竹茹三钱。姜汗拌芦根二两。继去石膏枇叶栀子冬瓜皮芦根。佐淡海䖳二两。元参片泡冲去渣八钱。石斛先煎一两。花麦冬四钱。乌梅肉炭一钱。）", "14176": "蔡初泉陡发寒热。咽痛大渴。脘闷舌绛。孟英诊脉甚数。径投大剂犀羚元参丹皮桑栀银花花粉翘蒡之药。服后遍身发赤疹。而热退知饥矣。（病情为阴虚风炽。镑犀角羚次尖。同先煨八钟。各四钱。元参片泡冲去渣一两。冬桑叶四钱。酒炒栀皮三钱。酒炒银花八钱。南花粉四钱。连翘壳三钱。姜汁炒牛子三钱。）", "14177": "吴诵青室年近五旬。天癸已绝。偶患腹胀。黄某知其体素羸。投以犀气汤而寒热渐作。改从建中法。旬日后病剧而崩。愈补愈甚。乞援孟英。脉洪而数。渴饮苔黄。是吸受暑邪。得温补而血下漏也。予犀角元参茅根柏叶栀楝知斛花粉白薇等药。（病情为温补助热。暑邪挟肝阳由气侵营。脉洪数为阴虚挟热。渴饮苔黄。为肺胃痰热。镑犀角先煎四钱。鲜茅根五钱。元参片泡冲去渣一两。酒炒柏叶一钱。黑栀皮三钱。楝核杵先二钱。酒炒知母三钱。石斛先煎一两。南花粉四钱。香白薇一钱。犀角元参知斛息风救液。花粉茅根栀薇清卫凉营。方中尤以救液息风为重。液复则风息。风息则血不行。）数剂始安。（续方去犀角茅根栀皮花粉。）加生地二至二冬而愈。（大生地八钱。明天冬切六钱。女贞杵五钱。旱莲草四钱。花麦冬四钱。）", "14178": "阮范书室患腹痛欲厥。医见其体甚弱。予镇逆通补之法。而势日甚。孟英察脉弦数左溢。是忿怒而肝阳勃升也。便閟不饥。口苦而渴。予雪羹栀楝旋绛元胡丹皮茹贝下左金丸而愈。（脉弦数左溢。为阴虚挟汗热。便閟不饥二语。为肝风逆升之象。淡海蜇先煎二两。整荸荠打二两。黑栀皮三钱。楝核杵先四钱。旋覆包先三钱。新绛屑六分。元胡索一钱半。粉丹皮二钱。姜竹茹三钱。川贝母杵四钱。雪羹合楝核丹皮能息风肃肺。药送左金丸二钱。）", "14179": "周子因体素弱。偶患间疟。黄某用首乌鳖甲姜枣等药。病日以甚。加以参桂。狂躁妄言。孟英视之。面赤舌绛。溲涩便溏。渴饮汗多。脉形细数。是暑证也。予元参银花知芩茹贝竹叶荷杆莲心西瓜皮为剂寻愈。（温补助热灼津。病情尚在气分。元参片一两。泡冲去渣。银花一两五钱。酒炒知母三钱。酒炒枯芩一钱半。姜竹茹三钱。川贝母杵四钱。莲子心一钱。鲜竹叶二钱。西瓜皮四钱。元参银花知母竹叶西瓜皮救液息风。）", "14180": "吴薇客母患痰嗽。喘逆。便閟不眠。微热不饥。口干畏热。孟英切其脉。右寸关弦滑而浮。左关尺细耎无神。是阴虚于下。痰实于上。微兼客热也。予茹贝旋斛浮石芦根冬瓜子枇叶杏仁花粉为剂。以熟地泡汤煎服。则浊药轻投。清上滋下。是一举两全之策也。投匕果应。再服而大便行。渐次调瘳。（右寸关弦滑而浮为痰实于上。左关尺细耎无神为阴虚于下。此方除熟地外。皆蠲痰肃肺之品。以熟地汤煎服。则阴复而后气行。气行而后在上之痰热悉降。此非独孟英已试之法。凡阴虚痰实之证。悉仿此法。亦百用百效。不敢自秘。姜竹茹三钱。川贝母杵四钱。旋覆包先三钱。石斛先煎八钱。鲜芦根一两。生冬瓜子四钱。姜枇叶刷包三钱。苦杏仁次入二钱。南花粉四钱。大熟地泡煎去渣一两。）", "14181": "谢谱香素属阴亏。情志抑郁。因远行持重而患咳逆。左胁刺痛。寸步难移。杳不知饥。卧难著枕。孟英诊之。脉象弦细耎数。苔腻痰黏。便艰涩少。乃肾气不纳。肝气不舒。肺气不清。胃气不降。（咳逆为肺气不清。左胁刺痛。寸步难移。为肝气不舒。杳不知饥。为胃气不降。脉弦细耎数。为肾虚肝郁。苔腻痰黏。便艰涩少。为肺胃不降。）投以沙参枇叶茹贝旋栀龟板鳖甲丝瓜络冬瓜子青铅白前金铃藕肉。以熟地泡汤煎服。数剂而平。继渐滋镇向愈。（北沙参四钱。姜枇叶刷包三钱。姜竹茹三钱。川贝母杵四钱。旋覆包先三钱。黑栀皮三钱。丝瓜络三钱。生冬瓜子四钱。白前一钱。熟地八钱。泡汤去渣。先煎血龟板杵三两。血鳖甲杵一两。青铅二两。楝核杵先四钱。藕肉切一两。至八句钟。再入前药。阴虚痰实之证。补阴潜阳。则痰自降。历试不爽。）", "14182": "叶承恩室怀妊患感。昏谵不语。善呕便秘。汗出不解脉涩口干。乃营阴素亏。邪热内炽。以元参石膏知芩茹贝银花枇叶薇栀楝斛投数帖而愈。（元参片泡冲去渣八钱。生石膏先煎八钱。姜炒知母三钱。姜炒枯芩一钱。姜炒楝皮去核二钱。姜竹茹三钱。川贝母杵四钱。银花次入一两。姜枇叶刷包三钱。酒炒白薇一钱半。酒炒栀皮三钱。石斛先煎一两。）", "14183": "江梦花妾患两目肿痛。不能略张。医投风药。昏痉欲厥。孟英诊之。脉至洪滑。大渴便秘。予白虎汤二剂霍然。（生石膏先煎一两六钱。酒炒知母四钱。生苡仁杵八钱。生冬瓜子四钱。南花粉五钱。鲜竹叶二钱。济银花一两五钱。青果连核杵先二钱。旋覆包先三钱。生赭石杵先八钱。淡豆豉一钱半。石斛先煎一两。淡海䖳先煎二两。）", "14184": "吴西瀍患疟。寒微热甚。旬余不愈。孟英诊之。脉滑而长。书大剂白虎汤予之。前医亦主是方。屡服无效。汤虽白虎。石膏既少且煨。兼不去米。汤名虽同。药却重用。且去米加花粉。其力不同科矣。此可见服药不可徒有汤头之名。（生石膏先煎一两二钱。酒炒知母四钱。南花粉四钱。姜竹茹三钱。西滑石先煎五钱。生冬瓜子四钱。黑栀皮三钱。淡豆豉一钱半。冬瓜皮三钱。）", "14185": "曹稼梅女。患眩晕脘痛。筋掣吐酸。渴饮不饥。咽中如有炙脔。朱某予温胃药病日剧。孟英诊脉弦滑。投茹贝萸连旋赭栀楝枳郁雪羹之药。十余剂始愈。（眩晕脘痛四句。为肝阳侮胃。胃气不降。脉弦为阴虚肝热。滑为痰热。姜竹茹三钱。川贝母杵五钱。淡吴萸次入六分。酒炒川连一钱。旋覆包先三钱。生赭石杵先二两。酒炒楝核杵先三钱。炒枳实一钱半。黄郁金一钱。整荸荠打一两。淡海䖳先煎二两。）", "14186": "夏氏妇怀娠患感。医投温散。渐至气冲不寐。时欲痉厥。脘闷呻吟。渴难受饮。孟英诊之。脉滑数而溢。予小陷胸加旋薤石膏知栀茹杏腹皮苏子竹沥海䖳大剂。投旬日而愈。（病情为温散劫津。肝肠侮胃。液不布气。胃肠亦弱。姜炒川连二钱。制半夏一钱半蒌仁研三钱。旋覆包先三钱。鲜薤白打次入一钱半。生石膏先煎一两二钱。姜汁炒知母三钱。黑栀皮三钱。姜竹茹三钱。苦杏泥二钱。生苏子研一钱半姜竹沥两大酒杯冲。淡海䖳先煎二两。方中夏薤杏腹苏皆为渴难受饮胃阳不健而设。）沈悦亭妻齿衄。五日不止。去血已多。诸方不应。孟英脉之。弦滑上溢。投犀角泽兰元参旋覆生地花粉茯苓牛膝桃仁泽泻而安。（去血已多合脉弦滑上溢。为阴涸风升。煽痰逆上。镑犀角先煎四钱。泽兰叶次入一钱半元参片一两。旋覆包先三钱。大生地八钱。南花粉四钱。云茯苓三钱。制牛膝一钱。生桃仁研一钱半。生泽泻一钱半。）嗣询经事。本月果已愆期。盖即逆行之候也。继用滋阴清热。乃渐康复。", "14187": "王雪山上年误饵透土丹之时。孟英诊治向愈。即属常饮柿饼汤。以杜关格于将来。次年四月形体日瘦。张某进导湿疏风补气之药。孟英力劝温补莫投。竟误仍服补药。秋间孟英视之。胁痛畏风。周身络胀。时欲敲扑。食少便难。日晡微有寒热。脉来弦涩而数。右寸关弦耎以滑。是升降之令久窒。痰邪袭于隧络。关格之势将成。勉予沙参茹贝薇蒿旋斛栀楝兰草枇叶丝瓜络冬瓜子芦根茅根等出入为方。服之寒热既蠲。胁痛亦减。（此证误服温补。升降之令久窒为远因。痰邪袭于隧络为近因。欲涤痰邪先调升降弦数为热。故方中多凉润清通之品。姜竹茹三钱。川贝母杵四钱。姜栀皮三钱姜枇叶刷包三钱。丝瓜络三钱。姜汁拌芦根八钱。佩兰草三钱。更方去栀皮枇叶。加北沙参四钱。再更方去竹茹。加石斛先煎八钱。再更方去沙参。加楝核杵先三钱。再更方加香白薇一钱。鲜青蒿一钱半。旋覆包先三钱。脉沥则痰邪阻气之征也。）脉颇转和。第肝阴为谋虑所伤。最忌情志不怡。无如嗔怒萦思。屡生枝节。复误温散温补。舌色干紫津涸而亡。", "14188": "徐梦香年近六旬。患手颤不能握管。孟英以通补息风药吞指迷茯苓丸而安。仲秋类中。遗溺痰升。昏瞀妄言。汗多面赤。孟英视之。脉浮弦洪滑。盖吸受暑邪。而连日适服参汤也。予羚角石菖蒲连翘栀子桑叶菊花楝斛知母花粉竹沥银花蒿薇等药。（病情为温补助热。肝风煽痰逆升而厥。羚次尖先煎四钱。石菖蒲次入二钱。连翘壳三钱。黑栀皮三钱。冬桑叶四钱。杭白菊三钱。川楝核杵先二钱。石斛先煎一两。酒炒知母三钱。南花粉四钱。姜竹沥两大酒杯冲。银花一两五钱。鲜青蒿一钱半。香白薇二钱。方以苦甘寒息风救液。菖蒿反佐。）一剂知。二剂神清。乃去羚菖。加茹贝滑石投之。（加姜竹茹三钱。川贝母杵四钱。西滑石先煎五钱。）下利白如脓垢者数日。始知饥纳谷。继以调理而愈。", "14189": "张月波弟陡患腹痛。适饱啖羊肉面条之后。医皆以为食滞。连进消导。痛甚而渴。得饮大吐。二便不行。又疑寒结。叠投燥烈。其病益加。呻吟欲绝。已四日矣。孟英视之。脉弦数。苔干微黄。按腹不坚。以海䖳一斤。荸荠半斤煎汤频灌。果不吐。令将余汤煎栀连楝斛茹芩枇叶知母延胡柿蒂旋覆为剂。吞龙荟丸。投匕而溲行痛减。次日更衣而愈。（痛甚而渴三句。本系温药伤阴。肝阳逆上。叠投燥烈。阴津将涸。故以大剂雪羹频灌救阴。汤煎黑栀皮三钱。酒炒川连一钱。酒炒楝核杵先二钱。石斛先煎一两。姜竹茹三钱。酒炒枯芩一钱半。鲜枇叶刷包三钱。酒炒知母三钱。元胡索一钱半。干柿蒂十个。旋覆包先三钱。药送龙荟丸三钱。）", "14190": "黄鼎如母年七十七岁。季秋患间疟。每发加剧。寒甚微而热必昏痉。舌不能伸。三发后孟英视之。颧赤目垂。鼻冷额颏微汗。苔色黄腻。舌根纯红。口渴痰多。不思粥饮。脉至弦数。重按少神。证属伏暑挟痰。而阴虚阳越。先与苁蓉鳖甲楝斛茹贝燕窝藕。（伏暑挟痰。应用茹贝等轻清之品。惟阴虚阳越。本身气先不降。药气何能下行。常法先标后本。若本病较重。则本反为标。伏暑挟痰虽标病。而阴虚阳越。则本反为标。淡苁蓉一钱半。血鳖甲杵四两。楝核杵四钱。石斛一两。燕窝包三钱。藕切二两。六味先煎八句钟。姜竹茹四钱。川贝母杵一两。同次入。）两剂而颧红颏汗皆蠲。继佐参沥薤麦枇叶旋覆。去竹茹苁蓉。（北沙参八钱。姜竹沥两大酒杯冲。鲜薤白打一钱半。鲜枇叶刷包三钱。旋覆包先三钱。）投三帖而昏痉不作。又去薤楝。加生地花粉。服五日而疟休。（大生地八钱。南花粉四钱。）饮食渐加。居然告愈。（按此系足厥阴肝疟之治。）", "14191": "许芷卿患外寒须复重衾。内热饮不解渴。仍能安谷。便溺皆行。投以温散。即显咽痛。孟英切脉沉弦而缓。作痰热内伏。投以犀羚元参丹皮白薇黑栀茹贝旋蒡之剂。（仍能安谷。便溺皆行。病不在气。饮不解渴。温散咽痛。为内风已动。脉沉弦为肝热遏伏。此脉缓乃痰浊阻气。非脾阳衰弱。镑犀角羚次尖同先煎各四钱。元参片泡冲去渣一两。粉丹皮二钱。香白薇一钱。黑栀皮三钱。姜竹茹三钱。川贝杵四钱。旋覆包先一钱半。姜炒牛蒡子三钱。）两帖而寒渴咽痛皆减。乃去犀羚牛蒡。加二至知母花粉银花。解酱矢而瘳。（女贞杵五钱。旱莲草四钱。酒炒知母三钱。姜汁炒花粉四钱。济银花次入八钱。）", "14192": "韩组林年近古稀。孟冬患肢厥头肿。讝语遗溺。某作虚风类。进以温补。势益剧。孟英切脉。左弦数。右滑溢。乃痰热内阻。风温外侵予羚贝茹栀翘薇桑菊花粉丹皮旋覆。以芦菔汤煎服而瘳。（左弦数为阴虚挟肝热。右滑溢为风阳煽痰逆上。方义主息风阳以涤痰热。羚次尖先煎八钟四钱。川贝杵四钱。姜竹茹三钱。黑栀皮三钱。连翘壳三钱。香白薇一钱。冬桑叶四钱。杭白菊三钱。粉丹皮二钱。南花粉四钱。芦菔一两。煨汤去渣煎药。）", "14193": "钱闻远子患感。汤某进桂朴姜柴等药。而痰血频咯。神瞀耳聋。讝语便溏。不饥大渴。苔黑涩少。彻夜无眠。某某叠进轻清。黑苔渐退。舌绛无津。外证依然。不能措手。孟英诊之。脉皆细数。乃真阴素亏。营液受灼。不必以便溏不食而畏滋腻也。授以西洋参生地二至二冬龟板燕窝茹贝银花藕汁梨汁玉竹百合等药。二剂咯血渐止。痰出甚多。渐进稀糜。夜能稍寐。五剂热退泻止。渴始减。脉渐和。旬日后解燥矢而痊。（无实证而便溏。为脾败除中。有实证而便溏。为热寻出路。此病脉证八句皆实热见证。脉皆细数。何畏滋腻。西洋参三钱。大生地八钱。女贞杵五钱。旱莲草四钱。明天冬切六钱。花麦冬四钱。血龟板杵四两。燕窝包三钱。二味同先煎八钟。姜竹茹三钱。川贝杵四钱。济银花八钱。藕汁梨汁各大半酒杯冲。肥玉竹三钱。百合花三钱。）朱湘槎子忽于饱食后大吐而厥。冷汗息微。孟英视之。厥甫回而腹痛异常。口极苦渴。二便不行。脉来弦缓。乃痰滞而热伏厥阴。肝气无从疏泄也。投雪羹栀楝元胡苁蓉萸连橘核旋覆竹茹菔汁之药。（大吐而厥脉证六句。皆肝热壅痰。肝不疏泄之象。淡海䖳先煎二两。荸荠打一两。黑栀皮三钱。川楝核杵先三钱。元胡索一钱半。淡吴萸六分。姜炒川连八分。橘核杵一钱半。姜竹茹三钱。菔汁半酒杯冲。淡苁蓉一钱半。）一剂痛减。再服便行而愈。", "14194": "韩妪年近花甲。患三疟于仲冬。某主温散。并以姜枣汤恣饮。旬日后粒米不沾。疟至大吐。某以热补进。势益甚。又浃旬。孟英视之。胸中痞结如柈。苔黄苦渴。溲如热汤。脉弦滑右甚。带下如注。投小陷胸合温胆加薤白。（此证热邪由气分侵营。故带下如注。治病必求其本。此病宜先豁痰热。蒌仁研四钱。姜川连二钱。制半夏一钱半。赖橘红八分。炒枳实一钱半。姜竹茹四钱。鲜薤白一钱半。）服后大吐胶痰。十余日胸痞始消。改授甘凉。疟亦渐罢。（甘凉方。鲜芦根二两。姜竹沥一大酒杯冲。鲜枇叶刷包三钱。鲜竹叶二钱。石斛先煎一两。制半夏二钱。荸荠八钱。酒炒知母三钱。鲜薤白一钱半。）继参滋阴。遂以霍然。（元参片泡冲去渣八钱。地骨皮五钱。川贝杵四钱。生冬瓜子四钱。制半夏二钱。花麦冬四钱。荸荠二两。楝核杵先三钱。乌梅肉炭一钱。）", "14195": "魏西林侄女娩后恶露。延至两月。继闻夫父及两弟丧。悲哀不释。干嗽吐血。头痛偏左。不饥不食。不眠不便。渴饮而溲必间日一行。久治不效。孟英切脉。虚弦豁大。予甘麦大枣加熟地首乌鳖甲二至菊花旋覆芍药贝母麻仁青盐等药。（病情为阴虚肝逆。肺胃不降。阴中之阳亦虚。血鳖甲二两杵先煎八钟。取汤代水煎药。生粉草三钱。北小麦四钱。大枣一枚擘先。大熟地八钱。制首乌二钱。女贞杵五钱。旱莲草四钱。杭白菊二钱。旋覆包先三钱。酒炒白芍一钱半。川贝杵三钱。麻仁研三钱。青盐一分。）服后脉渐敛。血亦止。七八剂头痛始息。旬日后便行安谷。", "14196": "韩石甫妻患感发疹。某治以清解。热渐退而神气不爽。舌黑难伸。太息便秘。胸次拒按。脉弦缓而滑。（神气不爽四句。皆痰热窒塞肺胃之象。脉弦缓而滑。文义弦缓在脉之浮分。滑在脉之沉分。故用凉膈之硝黄。若文义为弦滑而缓。则凉膈不可投矣。酒炒枯芩一钱半炒豆豉三钱黑栀皮三钱。薄荷尖八分。鲜竹叶二钱。酒炒知母三钱。南花粉四钱。炒枳实二钱。姜竹茹三钱。元明粉一钱。生厢黄三钱。开水泡冲去渣。）一帖苔即退黄。再服而黑矢下。神气清。即以向愈。", "14197": "陈赤堂妻患感。面赤不眠。烦躁谵语。口甘渴腻。溲涩而痛。某多剂清解未应。孟英切脉左弦洪而数。右滑而溢。胸次痞结。大解未行。肝阳上浮。肺气不降。痰热阻痹。邪乃逗遛。予小陷胸合温胆雪羹加旋薤投之。（脉左弦洪而数。为阴虚挟热。右滑而溢。为痰挟风阳。肺病较急于肝。治法涤痰热即所以息风阳。蒌仁研四钱。姜炒川连二钱。制半夏二钱。炒枳实一钱。姜竹茹三钱。荸荠打一两。淡海䖳先煎二两旋覆包先三钱。西薤白打次一钱半。）胸结渐开。去半薤。药送当归龙荟丸。（药送龙荟丸三钱。）谵语止。且能眠。参以通幽汤下其黑矢。三剂后始进养阴和胃而痊。（养阴和胃方。大生地八钱。明天冬切六钱。女贞杵五钱。生粉草三钱。花麦冬四钱。酒炒知母三钱。乌梅肉炭一钱。大枣擘先一枚。川贝杵四钱。）", "14198": "屠某患梦遗。久治不愈。耳出脓水。目泪难开。肩胁胸背酸疼。微有寒热。食减神疲。孟英察脉左弦数。右虚耎以三才封髓加龙牡黄耆桑丹栀菊。（左弦数为肝脏阴虚挟热。右虚耎为气分阳虚。炒潞党三钱。炒西耆三钱。淡苁蓉一钱半。西砂仁研次入六分。酒炒川黄柏一钱半。大熟地八钱。明天冬切五钱。醋煅牡蛎杵四两。醋煅龙骨杵一两。二味同先煨八钟。冬桑叶三钱。杭白菊二钱。焦神曲杵一钱半。丹皮二钱。黑栀皮三钱。）", "14199": "李华甫妻患头震。孟英脉之。乃肝经郁怒火升也。投当归龙荟丸而瘳。（青果一枚连核杵先煨。汤送龙荟丸三钱。）然不能惩忿。其病发之后。更兼溺閟腹胀。喘汗欲绝。孟英视之。脉甚弦涩。口苦苔黄。舌色紫黯。汛虽不愆。内有瘀滞也。以雪羹加金铃旋覆栀子滑石桃仁茺蔚车前子木通仍吞龙荟丸。（辨瘀滞在腹胀脉弦涩。舌色紫黯。淡海䖳先煎二两。荸荠一两。楝核杵先四钱。旋覆包先三钱。黑栀皮一钱半。西滑石先煎五钱。生桃仁研三钱。茺蔚子杵先四钱。车前子杵先四钱。细木通一钱。仍药送龙荟丸三钱。）外以大田螺三个。生蒜六瓣。车前草一握。捣扎脐下。服后果先下黑血。溲即随通。继而更衣粪色亦黑。遂愈。", "14200": "胡孟绅患疑。坐卧不安。如畏人捕。自知为痰。饵白金丸吐之。汗出头面。神躁妄闻。孟英切其脉。弦滑洪数。不为指挠。投石膏竹茹枳实黄连旋覆花粉胆星石菖蒲加雪羹竹沥童溲吞礞石滚痰丸下其痰火。连得大解。夜分较安。惟不能断酒。为加绿豆银花枳椇子吞当归龙荟丸。旬余脉证渐平。神气亦静。尚多疑惧。改授犀角元参丹皮竹叶竹茹贝母百合莲心猪胆汁炒枣仁盐水炒黄连吞枕中丹。以清包络肝胆之有余而调神志。又旬日各恙皆蠲。继予十味温胆法善其后。乃弟季权同时患黑斑。苔秽脉浑气粗面垢。孟英即以凉膈散投之。大解得行。脘亦不闷。斑皆透绽。脉显滑数而洪。遂予大剂凉润清肃之药。直俟其旬日外大解不泻。药始缓授。复又沉卧不醒。孟英曰：痰热尚炽也。仍投大剂数帖。果频吐胶痰累日而眠食渐安。（白金丸内白矾苦能化躁。薄荷升阳助热。至郁金亦非热痰主要之药。故汗出头面。神躁妄闻。生石膏先煎一两六钱。姜竹茹三钱。炒枳实一钱半。酒炒川连一钱。旋覆包先三钱。南花粉四钱。陈胆星炖和服八分。石菖蒲次入二钱。淡海䖳先煎二两。整荸荠二两。童便煎去头尾冲一酒杯。药送礞石滚痰丸四钱。嗣去石膏竹茹连枳。加生绿豆二两。济银花一两五钱。枳𪱷子杵四钱。药送当归龙荟丸三钱。嗣改授镑犀角四钱先煎。元参片泡冲去渣八钱。粉丹皮二钱。鲜竹叶二钱。姜竹茹三钱。川贝杵四钱。百合花三钱。莲子心一钱。胆汁炒枣仁研三钱。盐水炒川连一钱。药送枕中丹三钱。胡季权凉膈散方。酒炒枯芩三钱。黑栀皮三钱。炒豆豉三钱。鲜竹叶二钱。生粉草三钱。酒洗生厢黄三钱。元明粉一钱。二味同入煎。大剂凉润清肃方。鲜芦根二两。生冬瓜子四钱。酒炒枯芩三钱。鲜枇叶刷包三钱。川贝杵五钱。陈胆星炖和服八分南花粉四钱。姜竹茹三钱。石菖蒲次入二钱。整荸荠打三个。）", "14201": "许芷卿亦精于医。偶患外感。即服清散之药而证不减。或疑其非春温也。邀孟英质之。诊脉迟涩。二便皆行。筋掣不眠。畏寒能食。喉舌皆赤。予大剂清营药数服而瘥。迨夏两腿患疥。外科治之。久而不愈。孟英谓其平昔善饮。蕴热深沉。疡科药亟宜概屏。令以雪羹汤送当归龙荟丸。果得渐瘳。秋间其母患感。迟服温散。转为肢厥便秘。面赤冷汗。脉来一息一歇。举家惶惶。虑即脱变。孟英视其苔。黄腻不渴。按其胸。闷而不舒。且闻其嗅诸食物。无不极臭。断为暑湿内伏。挟痰阻肺。肺主一身之气。气壅不行。法宜升降。是虚脱之反面也。设投补药。则内闭而外脱。昧者犹以为投补迟而不及救。孰知真实类虚。不必以老年怀成见。总须以对证为良药。果一剂而脉至不歇。转为弦滑。再服汗止肢和。便行进粥。数帖而痊。方用紫菀白前竹茹枳实旋贝杏蒌兜铃枇杷叶也。（二便皆行及能食。皆病不在气之明证。脉迟涩为病在血。合之筋掣不眠畏寒及喉舌皆赤。皆营热厥逆之象。清营方。济银花一两五钱。鲜茅根五钱。鲜竹茹三钱。丝瓜络三钱。酒炒桑枝三钱。羚次尖先煎四钱。大生地泡冲去渣八钱。炒豆豉三钱。大豆卷三钱。酒炒川连一钱。酒炒川黄柏三钱。许芷卿母方。紫菀茸一钱半。白前一钱。姜竹茹三钱。炒枳实一钱半。旋覆包先一钱半。川贝杵四钱。苦杏泥二钱。姜蒌皮三钱。马兜铃一钱半。姜枇叶刷包三钱。）", "14202": "沈辛甫妻体素弱而勤于操作。年逾四秩。汛事过多。兼以便溏。冷汗气逆。参耆屡进。病日以危。孟英诊曰：心脾之脉尚有根。犹可望也。予龙骨牡蛎龟板鳖甲海螵蛸石英石脂余粮熟地茯苓为方。一剂转机。渐以向愈。（汛事过多。血虚则肝风暗动。冷汗气逆。为肝阳逆厥之征。至便溏为热寻出路。参耆屡进。则肝风愈炽矣。故用介属重镇。煅龙骨杵一两。煅牡蛎杵四两。血龟板杵二两。血鳖甲杵二两。炙海螵蛸四钱。紫石英五钱。赤石脂三钱。禹余粮三钱。大熟地八钱泡汤去渣。前八味先煎八钟。云苓次入三钱。）", "14203": "胡韵梅年已逾冠。因夜坐感寒。患头痛恶冷。呕吐肢冷。孟英视之。曰：舌绛脉数。斑疹之候。断非受寒。予清透药服之。次日点形圆绽。细询果未出痘。但火势甚炽。一路清凉。自发起至落痂。毫不杂一味温升攻托之药。而满身密布。形色粗紫。浆浓痂黑。便秘不饥。渴无一息之停。苟不如是用药。其能免乎。此建中琐言之所以有功于世也。（清透方。大生地泡冲去渣八钱。酒炒知母三钱。酒炒川黄柏一钱半。酒炒栀皮三钱。石菖蒲次入二钱。酒炒枇叶刷包三钱。酒炒银花四钱。酒炒丹皮二钱。制半夏一钱。）", "14204": "朱大镛新婚后神呆目瞪。言语失伦。或疑其体弱神怯。予镇补安神诸药。驯致善饥善怒。骂詈如狂。孟英诊之。右脉洪滑。予犀角石膏菖蒲胆星竹沥知母吞礞石滚痰丸而愈。其大父患四肢冷颤。常服温补。延久不痊。孟英切其脉弦而缓。曰：非虚也。予通络方。吞指迷茯苓丸而瘥。（方义重涤痰热。参以息风。镑犀角先煎四钱。生石膏先煎一两六钱。石菖蒲次入二钱。陈胆星炖和服八分。姜竹沥两大酒杯冲。酒炒知母四钱。药送礞石滚痰丸四钱。朱大镛祖脉弦而缓。系为温补窒气。并非阳虚。玩吞指迷茯苓丸便见。通络方。制半夏三钱。浮橘络一钱五分。鲜薤白打三钱。石菖蒲二钱。姜竹茹三钱。丝瓜络三钱。姜汁拌茅根四钱。姜汁炒桑枝三钱。陈胆星炖和服八分。药送指迷茯苓丸三钱。）", "14205": "许安卿患咽痛。疡科连予升散之药。延及龈肿。牙关不开。舌不出齿。自汗脉涩。绝谷濒危。孟英往勘。即洗去满颈敷药。以菊叶捣涂。吹以锡数散。煎犀羚射干马勃栀贝山豆根等药灌之。数日而痊。（病情为肝风逆上。窒遏气机。镑犀角四钱。羚次尖四钱。二味同先煎八钟。姜射干三钱。马勃一钱半。姜栀皮三钱。川贝杵四钱。姜炒山豆根一钱。）", "14206": "庄芝阶媳患搐搦。闲日而作。孟英诊脉弦数。泛泛欲呕。口苦不饥。凛寒头痛。汛事愆期。溲热如火。乃足厥阴暑疟也。投以大剂犀羚元参栀菊木通知楝花粉银花之药。数日而愈。（泛泛欲呕四句。皆肝风炽逆现证。镑犀角四钱。羚次尖四钱。二味同先煎八钟。元参片泡煎去渣一两。姜栀皮三钱。杭白菊三钱。细木通一钱。酒炒知母四钱。楝核杵先三钱。南花粉四钱。济银花一两五钱。）", "14207": "仲夏淫雨匝月。泛滥为灾。季夏酷暑如焚。人多热病。沈小园病。医但知湿甚。不知化热。投以平胃散数帖。壮热昏狂。证极危殆。孟英视之。脉滑实而数。大渴溲赤。稀水旁流。予石膏大黄数下之而愈。孟英因论曰：考古惟叶天士甘露消毒丹神犀丹二方为湿温暑疫最妥之药。一治气分。一治营分。规模已具。即有兼证。尚可通融。司天在泉不必拘泥。今岁奇荒。明年恐有奇疫。但甘露二字。人必疑为大寒之药。消毒二字。世人或误作外证之方。因易其名曰普济解疫丹。依方合送。救活极多。（壮热昏狂方。生石膏先煎一两六钱。酒洗生厢黄四钱。鲜芦根二两。生冬瓜子八钱。南花粉五钱。炒枳实二钱。整荸荠二两。冬桑叶四钱。杭白菊三钱。姜竹茹三钱。姜竹沥两大酒杯冲。酒炒知母三钱。鲜枇叶刷包三钱。石菖蒲次入二钱。）", "14208": "姚禄皆遇水复受酷热患感。顾某诊为湿邪。予桂枝葛根药三帖。病乃剧。赵某知其误治。连用清解。因见蓝斑。不肯接诊。孟英视之。脉细数而体瘦。平昔阴亏。热邪借风药而披猖。营液得温燥而干涸。斑色渐退。而昏狂遗溺。大渴不已。仍予前方。调紫雪数剂。热退神清而言出无伦。犹如梦呓。或虑共成癫。孟英曰：痰留包络也。予犀角菖蒲元参鳖甲花粉竹茹黄连生地木通甘草为方。调以真珠牛黄。始得渐安。改授存阴调理而愈。（姚禄皆前方。生石膏先煎一两二钱。鲜芦根二两。整荸荠二两。淡海䖳先煎二两。石斛先煎一两。酒炒知母三钱。酒炒川连一钱。石菖蒲次入二钱。痰留包络方。镑犀角先煎四钱。石菖蒲次入二钱。元参片泡冲去渣一两。血鳖甲杵先煨六钟二两。南花粉四钱。姜竹茹三钱。酒炒川连一钱。大生地泡冲去渣八钱。细木通一钱。生粉草三钱。元参鳖甲生地甘草。针治温散误药。）", "14209": "陈蕴泉陡患昏谵。乞诊孟英。脉甚滑数。苔色腻黄。乃平素多痰。兼吸暑热。予清解药一剂。化而为疟。脉亦较平。或谓体弱不宜凉药。须用人参。孟英坚持不可。盖暑脉颇类乎虚。而痰阻于肺。呼吸不调。又与气虚短促者相似。平昔虽虚。有病必先去病。况热能伤气。清暑热即所以顾元虚也。遂连投白虎加减而愈。（白虎加减方。生石膏先煎八钱。姜炒知母三钱。南花粉四钱。姜竹茹三钱。姜牛子研丝瓜络各三钱。炒枳实一钱半。石菖蒲次入二钱。西滑石包先四钱。）", "14210": "高若舟庶母患脱肛。孟英脉之。弦而滑。溲涩苔黄。虽属高年。非虚证也。清其湿热而痊。（酒炒西茵陈一钱半。酒炒枯芩一钱半。酒炒川连八分。石菖蒲次入二钱。冬瓜皮四钱。晚蚕砂五钱。生冬瓜子四钱。西滑石先五钱。细木通一钱。川贝杵五钱。）", "14211": "孟英治乍浦人滞下证。昼夜百余行。不饥不渴。而欲呕腹痛。上及于心胸。脉颇平和。是寒湿也。与时行暑湿痢大相径庭。投姜桂萸朴之剂。数服霍然。（炒干姜四钱。肉桂心二钱。生吴萸次入一钱半。制厚朴三钱。制半夏四钱。炒陈皮一钱半。省头草三钱。煨姜三钱。鲜薤白打三钱。鲜葱白三钱。陈木瓜三钱。）", "14212": "赵子善患疟。畏冷不饥。孟英诊之。脉滑数。苔黄溲赤。脘闷善呕。投竹叶石膏汤加减。以清伏暑而痊。（鲜竹叶二钱。生石膏先煎一两二钱。姜炒知母四钱。石菖蒲次入二钱。制半夏二钱。西滑石五钱。细木通一钱。陈胆星炖和服八分。枯荷梗三钱。姜枇叶刷包三钱。石斛先煎一两。）", "14213": "王一峰子患疟。多服姜枣温散之药。因致壮热耳聋。谵语遗屎。不寐昏狂。见人欲咬。顾某从伏暑治亦不效。延至初冬。求诊孟英。按脉皆滑。即以顾疏犀角等药内加菖蒲胆星竹沥珍珠牛黄为剂。吞白金丸。一服即减。旬日霍然。继其母发热善呕。频吐黏沫。头痛如劈。口苦耳聋。神识昏瞀。脉弦而数。乃伏暑挟内风鸱张。予犀角元参竹茹花粉知翘苓斛栀菊雪羹等药。七日而瘳。（王子方。镑犀角先煎四钱。姜竹茹三钱。姜竹沥两大酒杯冲。生冬瓜子四钱。川贝杵八钱。南花粉五钱。天竹黄三钱。石菖蒲次入二钱。陈胆星炖和服一钱。舌餂药送珠粉一分。牛黄三厘。王一峰母方。镑犀角先煎四钱。元参片泡冲去渣一两。姜竹茹三钱。南花粉四钱。酒炒知母四钱。连翘壳三钱。云苓三钱。石斛先煎一两。荸荠一两。淡海䖳先煎二两。）", "14214": "王子能妻久患吐血。医不能愈。孟英视之。脉弦滑而搏指。右手较甚。渴喜冷饮。米谷碍于下咽。小溲如沸。夜不成眠。久服滋阴。毫无寸效。孟英以苇茎汤合雪羹加石膏知母花粉枇杷叶竹茹旋覆滑石梨汁大剂投三十剂而痊。（脉弦滑而搏指六句。全系痰热窒肺。久服滋阴。是肺病治肾。宜乎不效。鲜芦根二两。生冬瓜子八钱。整荸荠二两。淡海䖳先煎一两。生石膏先煎一两六钱。浓酒炒知母四钱。姜花粉五钱。姜枇叶三钱。姜竹茹三钱。旋覆包先三钱。西滑石包先四钱。生梨一两绞汁冲。）", "14215": "高瑞生弟疟久不痊。形消不食。医谓虚也。投补药而更增自汗。孟英诊之。脉弦滑。脘下聚气。投小陷胸加竹茹旋枳以开痰结。渐能纳谷。继以清养。病去肌充。（姜川连二钱。姜蒌仁三钱。制半夏研次入二钱。姜竹茹三钱。旋覆包先一钱半。炒枳实一钱半。清养方。川贝杵四钱。旋覆包先一钱半。南花粉三钱。生粉草一钱。北沙参四钱。苦杏仁二钱。石斛先煎五钱。炒枳实一钱。）", "14216": "李贵患感数日。忽然昏厥。孟英见其面色灰黯。戴眼口开。按其脉尚不绝。予菖蒲胆星竹茹旋覆等为剂。和入童溺。调以牛黄至宝丹灌之。复杯而起。（石菖蒲次入二钱。陈胆星炖和一钱。姜竹茹三钱。旋覆包先三钱。天竹黄三钱。姜炒川连一钱。净橘络五分。冲入煎去头尾童便一酒杯。研调西牛黄二厘。至宝丹五分。此病系痰中。先用苦辛香以开其痰。）", "14217": "吴酝香自仲春感冒而起。迨夏徂秋。痰多气逆。肌肉消瘦。延至初冬。诸证蜂起。耳鸣腰痛。卧即火升。梦必干戈。凛寒善怒。多医咸主补虚。迄无小效。孟英诊脉弦细。而左寸与右尺甚数。右寸关急搏不调。且病者颈垂不仰。气促难言。舌黯无苔。面黧不渴。孟英曰：病虽起于劳伤挟感。而延已经年。然溯其所自。平昔善饮。三十年来期在必醉。非仅外来之客邪失于清解。殆由内伏之积热久锢深沉。温补杂投。互相煽动。营津受烁。肉削痰多。升降愆常。火浮足冷。病机错杂。求愈殊难。姑且按经设法。以石膏知母花粉黄芩等清肺涤痰。青蒿鳖甲栀子金铃等柔肝泄热。元参女贞天冬黄柏等壮水制火。竹茹旋覆杷叶橘红等宣中降气。出入为方。间佐龙荟丸直泻胆经之酒毒。紫雪丹搜逐隧络之留邪。服三剂而舌布黄苔。蕴热渐泄。服六剂而嗽病减知饥。渴喜热饮。伏痰渐化。十剂后凛寒始罢。足亦渐温。肺气已得下降。继而梦清夜寐。方中参以西洋参生地麦冬充其液。银花绿豆雪羹化其积。肌肉渐丰。面黑亦退。（左寸与右尺甚数。为心肾阴亏火炽。右寸关急搏不调。为肺胃热炽煽痰逆升。颈垂不仰四句。皆温补煽助痰热。窒遏气机之象。治法必须先清肺胃。生石膏先煎八钱。酒炒知母四钱。姜花粉四钱。姜栀皮三钱。姜竹茹三钱。旋覆包先三钱。姜枇叶刷包三钱。赖氏橘红次入一钱。药送紫雪丹一分。三帖后去知母。加酒炒枯芩一钱半。酒炒楝核杵先三钱。鲜青蒿次入一钱半。药并送当归龙荟丸二钱。又三帖后去紫雪石膏茹枇花粉栀皮黄芩及龙荟丸。加酒炒黄柏一钱半。整荸荠二两。淡海䖳先煎一两。血鳖甲杵先煎八钟一两。女贞杵五钱。元参片八钱。明天冬切六钱。二味泡煎去渣。六帖后去荸荠海䖳。加西洋参三钱。大生地八钱。花麦冬四钱二味同泡煎。绿豆一两。济银花八钱。）", "14218": "杨素园精医。妻多病自治不痊。孟英据信述病状拟方立案云。细阅病原。证延二十余年。始因啖杏。生冷伤乎胃阳。肝木乘虚。遂患胁痛挛掣。身躯素厚。湿盛为痰。温药相投。与湿似合。与痰大悖。驯致积温成热。反助风阳。消烁胃津。渐形瘦削。而痰饮者本水谷之悍气。肝升太过。胃降无权。另辟窠囊。据为山险。初则气滞以停饮。继则饮蟠而气阻。气既阻痹。血亦愆其行度。积以为瘀。前此神术丸控涎丹之涤饮。丹参饮桃核承气之逐血。治皆近似。迨延久元虚。即其气滞而实者。亦将转为散漫而无把握矣。是以气升火浮。颧红面肿。气降火息。黄瘦日增。苟情志不怡。病必陡发。以肝为刚脏。在志为怒。血不濡养。性愈侜张。胃土属阳。宜通宜降。通则不痛。六腑以通为用。更衣得畅。体觉宽舒。是其征也。体虽虚。病则实。虚则虚于胃之液。实则实于肝之阳。中虚原欲纳食。而肝逆蛔扰欲呕。吐出之水。已见黑色。胃底浊阴。风鼓波澜。翻空向上。势难再攻。脉至两关。中取似形鼓指。重按杳然。讵为细故。际此春令。正鸢飞鱼跃之时。仰屋图维。参彻土绸缪之议。立方如下。沙参（八钱）鲜竹茹（四钱）川椒红（二分）乌梅肉炭（六分）茯苓（三钱）旋覆（三钱）金铃肉（二钱）柿蒂（十个）仙半夏（一钱）淡肉苁蓉（一钱五分）吴萸汤炒黄连（四分）冬虫夏草（一钱五分）另用炙龟板藕各四两。漂淡陈海䖳二两。凫茈一两。赭石四钱。先煮清汤代水煎药。（病情。简言之为温补助肝贼胃。茯苓半夏微顾胃阳。龟板藕雪羹滋助胃液。柔戢肝阳。梅楝连酸苦泄肝。柿蒂沙参甘凉益胃。竹茹旋覆涤痰降气。苁蓉益阳配阴。赭石重药轻用。川椒反佐。微剂苦寒。虫草作升降变化之引导。）逾旬日又亲往复诊。案云：证逾二十年。右胁聚气。有升无降。饮阻不宣。呕逆减餐。亦将半载。二便非攻不畅。容色改换不常。吐苦吞酸。苔黄舌绛。渴喜冷饮。畏食甘甜。甘能缓中。冷堪沃热。病机于此逗露。根深难即蠲除。标实本虚。求痊匪易。遽述脉亦屡迁。似无定象。显属于痰。兹按脉左缓滑右耎迟。两尺有根。不甚弦涩。是汛愆因乎气阻。尚非阴血之枯。春令肝木乘权。胃土久受戕克。病已入络。法贵缓通。通则不痛。六腑以通为补。法虽时变。不能舍通字以图功。立方如下。沙参（八钱）鲜竹茹（四钱）青黛（五分）旋覆（三钱）酒炒黄连（六分）白前（一钱）生白蒺（三钱）紫菀（一钱）海石（五钱）川楝肉（三钱）川贝（一两）黑栀（三钱）另以生蛤粉生冬瓜子芦根芦菔各一两。丝瓜络五钱。漂䖳二两。柿蒂十个。先煮汤代水煎药。葱须二分后下。（病情。简言之渴喜冷饮为热。畏食甘甜为痰。汛愆因乎气阻。病在血实在气。此方义主凉润清通。参以楝连黛蒺。虽治肝实治肺。余八味皆清涤流气之品。海石重药轻用。葱须微佐辛通。）", "14219": "再诊左脉如昨兼弦。右寸亦转缓滑。中脘气渐下降。二便欲解不行。盖升降愆常。枢机窒涩。由乎风阳浮动。治节横斜。肺既不主肃清。一身之气皆滞也。轻可去实。先廓上游。前方去海石。加栝蒌三钱。枳实一钱。三诊脉来较静。小溲渐行。虽未更衣。已能安谷。浊得下降。导以清通。前方去贝楝。加归尾钱半。桃仁十粒。送服导水丸十粒。（脉来较静四句。皆气行浊降之象。微加行瘀血药以治汛阻。深得气为血帅之旨。）", "14220": "四诊腿凉便滞。气少下趋。颧面时红。火炎上僭。两胁较热。络聚痰瘀。叠授清宣。更衣色黑。噫气渐罢。酸水不呕。纳谷颇增。脉稍和缓。法仍缓导。冀刈根株。前方去枳实归尾。减导水丸五粒。（腿凉便滞六句。病情系肺胃痰热。得清涤而愈彰显。必至大便色黑。痰热乃全行下降。去枳归减导水丸。仍重清气。）", "14221": "五诊各恙皆减。眠食渐安。火犹易升。头痛面赤。颈酸结核。胁热未蠲。脉渐柔和。且参清养。前方去白前青黛紫菀黄连。加银花贝母黄菊丹参陈细茶橄榄。（银花一两五钱。川贝杵四钱。黄菊二钱。丹参三钱。陈细茶三钱。青果核先三个。）", "14222": "周森伯患发热面赤。渴而微汗。孟英视之。曰：春温也。乘其初犯。邪尚在肺。是以右寸之脉洪大。宜令其下行由腑而出。即可霍然。投知母花粉冬瓜子桑叶杷叶黄芩苇茎栀子等药。果大便连泻极热之水二次。而脉静身凉。知饥啜粥遂痊。（酒炒知母三钱。姜花粉四钱。生冬瓜子四钱。冬桑叶四钱。姜枇叶三钱酒炒枯芩一钱半。鲜芦根二两。姜栀皮三钱。）", "14223": "谢谱香体素阴虚。忽患环跳穴痛。始而下及左腿。继而移于右腿。甚至两足转筋。上冲于腹。间或痛自乳起。下注于髀。日夜呼号。肢冷自汗。略难反侧。医见其血不华色。辄投补剂。孟英诊脉。弦耎微滑。畏热知饥。溲短便坚。舌红不渴。乃阴虚而痰气滞于厥阴也。以苁蓉鼠矢竹茹丝瓜络橘核茴香汤炒当归吴萸汤炒黄连川椒汤炒乌梅延胡汤炒楝实海䖳凫茈为剂。一服即减。数啜而安。继予虎潜加秦艽而起。（病情为阴中阳虚。兼挟痰热。淡苁蓉一钱半。两头尖三钱。丝瓜络三钱。姜竹茹三钱。橘核研次入一钱。茴香汤炒归身二钱。吴萸汤炒川连一钱。川椒汤炒乌梅三钱。延胡汤炒楝实杵先二钱。淡海䖳先煎一两六钱。连皮荸荠一两。）", "14224": "陈建周子患春温。初起即神气躁乱。惊惧不眠。两脉甚数。孟英谓温邪直入营分也。予神犀丹佐紫雪。两剂而瘥。夏间吴守旃暨高若舟子胡秋纫女患温。初起即肢瘈妄言。神情瞀乱。孟英皆用此法。寻即霍然。世人每执汗解为初感之治。孰知病无定体。药贵得宜乎。（犀角磨冲二钱。酒炒枯芩三钱。石菖蒲次入二钱。大生地一两泡冲去渣。济银花一两五钱。连翘壳三钱。元参八钱。泡冲去渣。南花粉四钱。炒香豉一钱半。飞青黛一钱。）", "14225": "鲍继仲季春忽然发冷。而喘汗欲厥。孟英视之。脉沉弦而耎滑带数。是素患痰饮。必误服温补所致也。据述去冬服胡某肾气汤颇若相安。至今久不吐痰。孟英曰：病在肺。肺气展布。痰始能行。虽属久病与少阴水泛迥殊。初服颇若相安者。方中附桂刚猛。直往无前。痰亦不得不为之辟易。又得地黄等厚浊下趋之品。回护其跋扈跳梁之性。然暴戾之气。久而必露。柔腻之质。反阻枢机。治节不伸。二便涩少。痰无出路。愈伏愈多。一朝卒发。遂壅塞于清阳升降之路。是以危险如斯。须知与少阴虚喘。判分霄壤。切勿畏虚妄补。投以薤蒌枳杏旋赭橘半菀茹芦根蛤粉雪羹之剂而平。继与肃清肺气而涤留痰。匝月始愈。（鲜薤白打一钱半。姜蒌皮三钱。炒枳实一钱半。苦杏泥二钱。制半夏一钱半。赖橘红一钱。紫菀茸一钱半。姜竹茹三钱。姜汁拌芦根八钱。生蛤壳杵先五钱。淡海䖳先煎二两连皮荸荠一两打入煎。）", "14226": "王皱石弟患春温。始则谵语发狂。连服清解大剂。遂昏沉不语。肢冷如冰。目闭不开。遗溺不饮。医皆束手。孟英诊其脉弦大而缓滑。黄腻之苔满布。秽气直喷。投承气汤加银花石斛黄芩竹茹元参石菖蒲。下胶黑矢甚多。而神稍清。略进汤饮。次日去硝黄。加海䖳芦菔黄连石膏。服二剂而战解肢和。苔退进粥。不劳余力而愈。孟英继治叶某李某。咸一下而瘳。惟吴妇郑姓。皆下至十余次始痊。（此病系凭证论治。辨证在连服清解大剂。尚苔满黄腻。秽气真喷。实热结于胃腑何疑。元明粉一钱。酒洗生厢黄四钱。制厚朴一钱。剂银花次入八钱。鲜石斛先煎一两。姜炒枯芩一钱半。姜竹茹三钱。元参片五钱。石菖蒲次入二钱。次日去硝黄。加淡海䖳二两先煎。鲜芦菔切一两。姜炒川连八分。生石膏先煎八钱。）", "14227": "褚校书患汛愆寒热。医以为损。辄投温补。驯致腹胀不饥。带淋便秘。溲涩而痛。孟英诊脉。弦劲而数。乃热伏厥阴。误治而肺亦壅塞也。予清肃开上之剂。用当归龙荟丸。两服寒热不作而知饥。旬日诸恙悉安。（辨热伏厥阴在脉弦劲数。溲涩而疼。辨误治肺亦壅塞。在腹胀不饥。带淋便秘。鲜芦根二两。生冬瓜子四钱。姜炒枯芩三钱。炒枳实一钱半。姜枇叶刷包三钱。济银花一两五钱。鲜石斛先煎一两。青果杵先一个。元参片五钱。石菖蒲次入二钱。药送龙荟丸三钱。）", "14228": "闻氏妇孟夏患间疟而妊身八月。数发后热炽昏沉。腰痛欲堕。孟英诊脉来洪滑且数。苔色黄腻垢浊。予芩知竹茹竹叶银花桑叶丝瓜络石斛石膏石菖蒲。一剂而痊。（脉滑为热痰。洪滑为实热兼挟阴虚。酒炒枯芩一钱半。酒炒知母三钱。姜竹茹三钱。鲜竹叶二钱。剂银花一两五钱。冬桑叶四钱。鲜石斛先煎一两。生石膏先煎八钱。石菖蒲次入二钱。）", "14229": "朱佳木父患间疟。年逾七旬。孟英切脉弦滑。脘闷苔黄。曰：无恐也。投清热涤痰药。数剂霍然。李某妻年逾花甲。素患痰嗽。近兼晡热不饥。头疼不食。医治罔效。孟英视之。脉滑数。乃痰火内伏。温热外侵。投石膏药二服而热退知饥。又数剂并宿恙均愈。（朱父方用姜炒川黄柏一钱半。楝核杵先三钱。炒枳实一钱半。炒豆豉一钱半。黑栀皮三钱。姜竹茹三钱。晚蚕砂三钱。苦杏泥一钱半。净橘络七分。生冬瓜子四钱。丝瓜络三钱。姜汁炒川连八分。李妻方用酒炒知母三钱。楝核杵先二钱。生石膏先煎一两。南花粉四钱。川贝母杵五钱。姜竹茹三钱。鲜芦根二两。鲜竹叶二钱。鲜荷杆三钱。淡海䖳先煎一两。）", "14230": "吴某劳伤之后。发热身黄。孟英察脉耎数。是湿温重证。故初起即黄。亟予清解。大便渐溏。小溲甚赤。湿热已得下行。其热即减。辍药七八日后复热。谵语昏聋。抽痉遗溺。孟英视之。湿热之邪扰营矣。投元参犀角菖蒲连翘竹茹竹叶银花石膏泄卫清营之法。佐牛黄丸紫雪丹而瘳。臀皮已塌。亟令贴羊皮金。不致成疮而愈。（吴某湿温清解方。酒炒西茵陈一钱半。冬瓜皮三钱。云茯苓三钱。黑栀皮三钱。炒豆豉一钱半。生苡仁杵四钱。苦杏泥一钱半。省头草三钱。酒炒枯芩一钱半。细木通一钱。姜汁拌芦根一两。湿热扰营方。元参片泡冲去渣八钱。磨犀角冲二钱。石菖蒲次入二钱。连翘壳三钱。姜竹茹三钱。济银花一两五钱。牛黄丸炖和二分。紫雪丹和服一分。）", "14231": "李德昌母仲夏患感。医诊为湿。辄予燥剂。大便反泻。遂疑高年气陷。改用补土。驯致气逆神昏。汗多舌缩。乞诊孟英。脉洪数无伦。右尺更甚。予大剂犀角石膏黄芩黄连黄柏知母花粉栀子石斛竹叶莲心元参生地之药。另以冷雪水调紫雪灌一昼夜。舌即出齿。而喉舌赤腐。咽水甚痛。乃去三黄。加银花射干豆根。并吹锡类散。三日后脉证渐和。稀糜渐受。改授甘凉缓剂。旬日得坚黑矢而愈。（洪数无伦。为实热兼挟阴虚。辨证在右尺更甚。镑犀角先煎四钱。生石膏一两六钱先煎。酒炒枯芩一钱。酒炒川连八分。酒炒川黄柏一钱半。酒炒知母三钱。南花粉四钱。黑栀皮三钱。鲜石斛先煎一两。鲜竹叶二钱。莲子心一钱。元参片一两。大生地八钱。二味开水泡煎去渣。另以雪水调紫雪一钱。灌一昼夜。嗣去三黄。加济银花一两五钱。射干三钱。酒炒山豆根一钱。）", "14232": "余朗斋形瘦体弱。患间日疟。寒少热多。二便涩滞。脘膈闷极。苔腻不渴。孟英切脉。缓滑而上溢。曰：素禀虽阴亏。而痰湿阻痹。既不可以提表助其升逆。亦未宜以凉润碍其枢机。投以滑朴茹旋通草枇杷叶苇茎郁金兰叶之方。苔色渐退。即去朴郁。加连枳半夏。胸闷渐开。疟亦减。便乃畅再去滑半连枳。加沙参石斛橘皮黄芩。浃旬而愈。（脉缓为挟湿。滑溢为痰热不降。西滑石先煎四钱。制厚朴一钱。姜竹茹三钱。旋覆花包先一钱五分。方通草三钱。姜枇叶刷包三钱。姜汁拌芦根八钱。建兰叶三钱。黄郁金八分。更方去朴郁加姜炒川连八分。炒枳实一钱。制半夏一钱。再更方去滑半连枳。加北沙参三钱。鲜石斛先煎四钱。蛀陈皮一钱半。姜炒枯芩一钱半。）", "14233": "董哲卿妻胎前患嗽。娩后不痊。渐至寝汗减餐。头疼口燥。奄奄而卧。略难起坐。孟英诊脉虚弦耎数。视舌光赤无苔。曰：此头疼口燥。乃阳升无液使然。岂可从作感治。是冲经上逆之嗽。初非伤风之证也。予苁蓉石英龟板茯苓冬虫夏草牡蛎穞豆衣甘草小麦红枣藕数帖。嗽减餐加。头疼不作。加以熟地。服之遂愈。（冲脉系于肝。此头疼口燥。为肝阳逆升。惟脉耎为阴中之阳亦虚。苁蓉石英茯苓红枣针治脉耎。淡苁蓉一钱半。紫石英杵先三钱。血龟板二两。煅牡蛎四两。三味先炭煨六句钟。取汤代水煎药。云茯苓三钱。冬虫夏草二钱。穞豆衣四钱。生粉草三钱。北小麦四钱。红枣肉三钱。连皮肥藕切一两。）", "14234": "庆云圃子陡患偏坠。医予茴香芦杷乌药荔核等剂。遂痛不可忍。孟英视之。按其脉肤甚热。曰：非疝也。睪丸肿痛必偏于右。此湿热时邪也。设以疝治之必成痈。按法治之。果复杯而痛减。三服而便行热退。因食羊肉。肿痛复作。再予清解。嘱慎口腹而瘳。（湿热之邪伤气。故睪丸肿痛偏于右。冬瓜皮四钱。鲜芦根一两。生苡仁杵八钱。酒炒西茵陈一钱。川楝核杵先二钱。青果杵先两个。云茯苓三钱。陈木瓜一钱五分。西滑石先煎四钱。）", "14235": "吴宪章年逾花甲患感。医知为湿温。投药不应。仍能起榻理事。孟英视之。诊脉左寸数疾。余皆耎大。谷食略减。便溏溲少。苔色腻黄。舌尖独黑。孟英不肯予方。论曰：证原不重。吾以脉象舌色察之。是平昔曲运心机。离火内亢。坎水不制。势必自焚。况兼湿温之感乎。果数日而殒。", "14236": "黄纯光七十八岁。患湿温至旬余。脉形歇代。呃忒连朝。孟英诊曰：脉虽歇而弦搏有根。是得乎天者厚。虽属高年。犹为实证。参以病深声哕。原非小故。而二便窒涩。苔腻而灰。似腑气未宣。痰湿热阻其气化流行之道也。清宣展布。尚可图焉。以旋茹栀楝杷杏萸连菀蒌雪羹为剂。方通草一两煎汤煮药。投匕即减。数服而大吐胶痰。连次更衣。遂安粥食。惟动则嗽逆。渐露下虚之象。予西洋参龟板牡蛎苁蓉石斛牛膝冬虫夏草石英茯苓当归等药。各恙递安。继加砂仁炒熟地而起。（辨实证。在脉虽歇而弦搏有根。辨腑气未宣。在二便窒涩。苔腻而灰。旋覆花包先三钱。姜竹茹三钱。黑栀皮三钱。川楝核杵先三钱。姜枇叶刷包三钱。苦杏泥次入三钱。紫菀茸次入一钱半。淡吴萸次入六分。姜蒌皮三钱。酒炒川连八分。淡海䖳先煎八钱。整荸荠一个。片通草一两。煮汤煎药。通草一两煮汤。轻药重用。引肺气下行最妙。此法即从重药轻投对面脱化。动则嗽逆。渐露下虚之象。西洋参三钱。血龟板杵二两。煅牡蛎杵四两。石斛一两。紫石英杵三钱。四味先炭煨六句钟。取汤代水煎药。淡苁蓉一钱半。生牛膝七分。虫草二钱。云茯苓三钱。箱归身二钱。继加砂仁末炒熟地八钱。去砂仁。）", "14237": "汤西塍年逾花甲。感证初起。周身肤赤。满舌苔黄。头疼腰痛。便溏溲痛。孟英诊之。脉见弦细而耎。乃阴虚劳倦。湿温毒重之证。清解之中须寓存阴。以犀角羚苓茹银翘桑苇通草兰叶为方。煎以冬瓜汤。服之偏身赤疹。而左眼胞忽肿。右臂酸疼不举。耳聋神不清爽。亟以元参丹皮菊花栀子桑枝丝瓜络石斛竹叶。煎调神犀丹为剂。偶邀疡科视外患。亦知病因湿热。连进木通等药。脉更细弱。神益昏惫。饮食不进。溲涩愈疼。孟英论曰：急救阴液。尚可转机。授复脉汤去姜桂麻仁。易西洋参。加知母花粉竹叶蔗浆灌之。一剂神苏脉起。再服苔退知饥。三啜身凉溺畅。六帖后肤蜕安眠。目开舌润。或疑甘柔滑腻之药。何以能清湿热。孟英曰：阴虚内热之人。蕴湿易于化火。火能烁液。濡布无权。频溉甘凉。津回气达。徒知利湿。阴气先亡。须脉证详参。法难执一也。又服数剂后。忽然肢肿遍发风块。瘙痒异常。孟英论曰：此阴液充而余邪自寻出路耳。予轻清药数帖果瘥。（周身肤赤。湿化热蒸于肌肤。满舌苔黄。湿化热气不肃降。头疼肝热。腰痛肾虚。肺金不制肝木。则肝阳上逆。肺肾子母之脏。肺阴不能荫庇肾阴则肾虚。便溏为热寻出路。溲痛为热结肺胃。脉弦为肝热。细为阴虚。耎为肺痰阻气。茯苓兰草渗湿化浊。犀角先煎四钱。羚角先煎四钱。云茯苓三钱。酒炒银花次入一两五钱。连翘壳三钱。冬桑叶四钱。鲜芦根一两。建兰叶次入三钱。方通草一钱。连皮冬瓜先煨去渣煎药二两。耳聋神不清爽。元参片泡煎去渣一两。粉丹皮二钱。杭白菊四钱。黑栀皮一钱半。酒炒桑枝次入三钱。丝瓜络三钱。石斛先煎一两。鲜竹叶次入二钱。煎调神犀丹一钱。疡医连进木通等药。渗湿伤阴。西洋参三钱。花麦冬四钱。生粉草三钱。大生地八钱。大枣擘先一枚。清阿胶炖和服二钱。酒炒知母三钱。南花粉五钱。鲜竹叶次入二钱。连皮青蔗二两。榨汁冲。轻清药方。酒炒栀皮三钱。酒炒枯芩一钱。姜汁拌芦根一两。酒炒桑枝三钱。薄橘红一钱半。银花次入八钱。建兰叶次入三钱。丝瓜络三钱。）", "14238": "任斐庭季夏患感。黄某闻其身热而时有微寒也。进以姜萸紫枣等药数帖。热愈壮而二便不行。更医连用渗剂。初服溲略通。既而益閟。孟英视焉。证交十四日。骨瘦如柴。脉弦细而涩。舌色光紫。满布白糜。夜不成寐。渴不多饮。粒米不进。少腹拒按。势将喘逆。虽属下证。而形证如斯。法难直授。先令取大田蠃一枚。鲜车前草一握。大蒜六瓣。共捣烂。加麝香少许罨脐下水分穴。方以元参紫菀栀子知母花粉海䖳凫茈苁蓉牛膝天冬为剂。加鲜地黄汁服之。其夜小溲即行。气平略寐。又两剂。大解始下。热退而渐进稀糜。乃去雪羹栀菀苁膝地黄汁。加西洋参麦冬石斛干生地竹茹银花等药。又服十余帖。凡三解黑矢而舌色复于红润。眠食渐安而起。（此证系阴虚挟热，外罨方。田蠃车前滑润清凉。以大蒜辛温反佐开导。内服方。元参片八钱。紫菀茸一钱半。黑栀皮一钱半。酒炒知母三钱。南花粉三钱。淡海䖳先煎二两。整荸荠打一两。淡苁蓉一钱半。酒炒牛膝八分。明天冬切六钱。鲜地黄切开水绞汁冲一两。嗣去雪羹栀菀苁膝地黄汁。加西洋参花麦冬四钱。石斛先煎一两。干生地五钱。姜竹茹四钱。济银花八钱。）", "14239": "庄芝阶女孀居在室。陡患气冲欲厥。脘痛莫当。自服沉香吴萸等药。病益剧。而呕吐发热。略有微寒。孟英按脉弦滑且数。苔色滑腻微黄。而渴喜冷饮。便秘溲热。眠食皆废。是伏痰内盛，肝逆上升。而兼吸受暑热也。予吴萸水炒黄连枳实竹茹栝蒌石膏旋覆赭石知母半夏雪羹。服二剂吐止痛减。五剂热退而解犹不畅。旬日始得豁然。乃去石膏知母旋赭调之而愈。（气冲欲厥。脘痛莫当。本系肝阳侮胃。自服辛温。愈助肝阳。略有微寒。热极似寒。非真寒也。脉弦滑为肝热煽痰。数为兼挟阴虚。苔滑腻微黄为痰浊尚未全行披露。汤喜冷饮二句。为肺有实热。眠食皆废。为肝热侵凌心脯。呕吐非苦辛并用不开不降。故用知母半夏。肝阳非重镇不可。故用旋赭以引药下行。脉数非补阴不可。故用雪羹。吴萸水炒川连八分。炒枳实一钱半姜竹茹三钱。姜蒌皮三钱。生石膏先煎八钱。旋覆包先三钱。生赭石杵先一两六钱。姜炒知母三钱。姜半夏研次一钱。淡海䖳先煎二两。整荸荠打一两。雪羹兼治误药。）", "14240": "陈书伯弟妇娩后三日。发热汗多。苔黄眩悸。孟英切脉。弦细虚数。乃营阴素亏。酷热外烁。风阳浮动。痉厥之萌也。予元参白薇青蒿生地小麦穞豆衣石斛鳖甲竹叶。两剂热退知饥。悸汗不止。去蒿薇。加龙牡莲心龟板石英而安。继又暑风外袭。壮热如焚。渴饮不饥。睹物尽赤。改授白虎加西洋参竹叶莲杆。一啜而瘳。仍予镇摄滋潜善其后而愈。（元参片一两。大生地八钱。开水同泡去渣。用汤先炭煨血鳖甲三两。石斛一两。至六句钟。再入各药。鲜青蒿一钱半。香白薇三钱。北小麦四钱。穞豆衣四钱。鲜竹叶次入二钱。更方去蒿薇。加煅龙骨杵一两。煅牡蛎杵四两。血龟板杵二两。紫石英杵三钱。合鳖斛同先煨六句钟。暑风外袭方。生石膏先煎一两六钱。酒炒知母四钱。西洋参三钱。鲜竹叶次入二钱。鲜莲杆三钱。）", "14241": "高氏妇因戒鸦片而服外洋丸药。诸无所苦。惟便秘不通。医两月迄不能下。且仍安谷。而面赤龈胀欲挑。每以银针嵌入齿缝。拔出时银色已如煤黑。孟英诊脉滑数。予犀角石膏硝黄升麻蜣螂为剂。和以鲜银花汁一杯。服后夜间登圊三四行而病去及半。再予清解化毒而痊。（辨中热毒。在银针拔出色如煤黑。辨实证在脉滑数兼便秘两月。便秘脉不滑数。仍不宜下。以升麻升苦寒于至高之分。肺与大肠相表里。肺肃然后便通。犀角四钱。生石膏一两六钱。同先煎。生厢黄四钱。元明粉一钱。生升麻一钱半。蜣螂一对。三味同次入。鲜银花二两。开水泡绞汁冲。）", "14242": "陆竹琴妻陡患心悸。肢冷如冰。孟英察其脉。浮弦而数。视其舌。尖赤无苔。乃阴虚阳越。煎厥根萌。予元参二至三甲龙齿石英生地牛膝茯神莲子心而愈。（悸分寒热。水凌心下为寒。肝阳勃升为热。脉浮弦数。舌尖浮赤。悸为煎厥根萌。煎厥者。阴虚阳越。热似煎熬而四肢冷厥也。煅牡蛎杵六两。血龟板杵四两。血鳖甲杵二两。煅龙齿杵一两。紫石英四钱。五味先炭煨六句钟。取汤煎药。元参片一两。女贞子杵五钱。旱莲草四钱。酒炒牛膝七分。云茯神三钱。莲子心一钱。）", "14243": "赵子循室娩后。服生化汤二帖。更因惊吓。三朝发热。连投四物六合汤。病日以甚。半月后。孟英诊之。脉象左弦急。右洪滑数。苔黄大渴。谵语嗽痰。恶露仍行。唇齿干燥。是因阴虚之体。血去过多。木火上浮。酷暑外烁。津液大耗。兼有伏痰之候也。亟予营卫两清。冀免他变。母家极畏石膏。坚不予服。越三日势益剧。径以白虎汤加减投之。证有转机。翼日且以西瓜汁助其药力。热始日渐下行。二便如火。又数日渐安粥食。神气亦清。夜能静寐。然热蕴太多。下焦患痈。脓虽即溃。阴液漏伤。脉复空数浮大。便泄善嗔。口干多梦。皆木少水涵。烁津侮胃之见证也。孟英以白头翁汤加龙骨三甲甘草木瓜以育阴潜阳。余粮石脂丸中加梅连以息风镇胃。果得疮口脓干。餐加泻止。脉柔热净。苔退神怡。正须善后。甫授滋填。不期酷热兼旬。甘霖忽降。窗开彻夜。复感风邪。身热微寒。鼻流清涕。而阴液久夺。外患未痂。塔养碍投。又难发汗。肝气内应。瘈噤旋形。然此案自堪传也。（生石膏先煎一两六钱。犀角先煎四钱。济银花一两五钱。酒炒知母四钱。姜竹沥两大酒杯冲。石斛先煎一两。大生地一两泡冲去渣。生冬瓜子八钱。石菖蒲次入二钱。青果杵先一枚。两头尖三钱。木少水涵。烁津侮胃方。酒炒白头翁一钱半。酒炒川连一钱。楝核杵先三钱。煅龙骨杵先一两。煅牡蛎杵先六两。血鳖甲杵先四两。血龟板杵先二两。生粉草三钱。陈木瓜二钱。乌梅肉杵先四钱。药调送余粮赤石脂末各一钱。）", "14244": "陈某患嗽嗽则先吐稀痰。次则黄浓甜浊之痰。继之以深红带紫之血。仍能安谷。别无所苦。多药不愈。孟英切其脉。缓大而右关较甚。乃劳倦伤阳。而兼湿热蕴积也。予沙参生薏苡木瓜茯杏竹茹桑叶枇杷叶生扁豆苇茎花粉为剂。吞松石猪肚丸而愈。（劳倦伤阳为本病。湿热蕴积为标病。常法先治标。故方中治标之药。多于治本以救吐血。北沙参八钱。生苡仁杵八钱。陈木瓜一钱半。云苓三钱。苦杏泥一钱半。姜竹茹三钱。冬桑叶四钱。酒炒枇叶刷包三钱。生扁豆杵一钱半。鲜芦根一两。南花粉三钱。）", "14245": "王瘦石夫人患滞下。腹痛微呕。不饥口苦。溲短耳鸣。孟英诊曰：脉见细弱之形。肌无华泽之色汛不行而早断。舌紫黯以无津。是素质阴亏。情怀悒郁。二阳默炽。五液潜消。虽吸暑邪。莫投套药。予白头翁汤加雪羹银花栀子楝实数剂而减。继去雪羹。加生地苁蓉柿饼藕汁而安。改授甘麦大枣加西洋参生地苁蓉竹茹归芍蒲桃干。而以藕汤煎服。调养体质以痊。（二阳指心肝之阳。五液指五脏阴液。液消则阳炽。酒炒白头翁一钱半。酒炒川连一钱。楝核杵先三钱。淡海䖳先煎二两。整荸荠打入二两。济银花一两五钱。黑栀皮三钱。酒炒黄柏二钱。）", "14246": "陈姓次媳于三月间患时感。气逆不能眠。孟英按脉甚滑疾。谓是为娠。用药必须顾及。数剂而愈。后果产一男。孟英又曰：昨诊魏子恒室。亦妊也。诸医作虚损治。脉虽虚微耎数。而滑象仍形。其女兄伯字关氏。未嫁而卒。证非不治。亦为药误。病中阅吾方案。极为折服。且曰先生来暮。侬不能起矣。前此延致诸名家。徒曰虚证宜补。而不治其所以虚。方则群聚补药。必以地黄为之冠。虽有参耆。亦列于后。即使用药不乖。而阳生阴长气为血帅之旨。尚未分晓。况其他乎。至秋仲。果闻魏妇分娩。", "14247": "沈酝书便血至三十余年。且已形瘦腰疼。嗽痰气逆。似宜温补。孟英按脉弦数。视舌苔黄。询溺短赤。曰：痔血也。殆误于温补矣。肯服吾药。旬日可瘳。方用苇茎合白头翁汤加枇杷叶旋覆花侧柏叶藕。是肃肺祛痰清肝凉血互用也。（鲜芦根二两。生冬瓜子四钱。生桃仁研一钱。酒炒白头翁一钱半。楝核杵先三钱。酒炒川黄柏一钱半。姜枇叶刷包三钱。旋覆包先三钱。酒炒柏叶一钱半。整藕切二两煮汤煎药。脉弦数为阴虚挟热。）产后诸证。首必通瘀。然有不可以常理测者。周鹤庭室新产运汗。目不能开。心若悬旌。毫无恶露。按脉有虚弦豁大之形。孟英予以三甲石英丹参琥珀甘草小麦穞豆衣等药。复杯即安。数服而愈。或诘其何以知非瘀血为患。曰：此阴虚之体。既产而营液大脱。风阳上冒。虽无恶露。胸腹皆舒。岂可误作瘀冲。妄投破血之药耶。（新产运汗三句。为风阳上冒。毫无恶露。为显非实证。煅牡蛎杵六两。血鳖甲杵四两。血龟板杵二两。紫石英杵五钱。四味先煨八钟。酒炒丹参三钱。西毛珀研冲四分。生粉草三钱。北小麦四钱。穞豆衣五钱。方义主潜息镇风。）", "14248": "许季眉室仲秋患痁。自作寒湿治。势益剧。其从子芷卿以为挟风暑。连进清解病不减。孟英诊之。脉弦滑而洪。体丰多汗。苔黄便血。呕渴妄言。彻夜不瞑。欲卧于地。乃伏痰内盛。暑扰阳明也。投大剂石膏知母犀角元参石斛银花黄芩花粉兰叶竹沥。三帖证始平。随以多剂肃清而愈。（病情为风暑挟痰。煽炽风阳。生石膏先煎一两六钱。镑犀角先煎四钱。元参片泡冲去渣一两。酒炒知母四钱。石斛先煎一两。济银花一两五钱。酒炒枯芩一钱半。南花粉五钱。建兰叶次入三钱。姜竹沥两大酒杯冲。）", "14249": "庄芝阶年七十矣。患间疟。寒则战栗。热则妄言。孟英视之。脉弦数而促。苔黑口干。是素有热痰。暑邪内伏。予知母花粉元参石斛黄芩竹茹连翘海䖳芦菔莲子心等药。数啜而瘳。仲冬感冒风邪。痰嗽头疼。不饥寒栗。自服羌苏荆芥药二剂。势益甚。而口渴无溺。孟英切其脉。与季秋无异。但兼浮耳。证属风温。既服温散。所谓热得风而更炽也。舌绛无津。亟宜清化。以桑叶枇杷叶栀子知母冬瓜子元参菊花花粉贝母梨汁为剂。投匕即减。旬日而痊。（前证为热实阴虚。方义泻热救阴。后证为温散劫津。方义清化凉肺。似同实异。前方酒炒知母四钱。南花粉五钱。元参片一两泡煎去渣。石斛先煎一两。酒炒枯芩一钱半。姜竹茹三钱。连翘壳三钱。淡海䖳先煎二两。芦菔切八钱。莲子心一钱。后方冬桑叶四钱。鲜枇叶刷包三钱。黑栀皮三钱。酒炒知母三钱。生冬瓜子四钱。元参片泡冲去渣八钱。南花粉四钱。川贝杵五钱。整北梨一两。打汁去渣冲服。）孙位申室。平昔阴虚肝滞。痛胀少餐。暮热形消。咽疼喉癣。不孕育者九年矣。往岁汛愆。人皆谓将不起。孟英切其脉尚不细。肤犹淖泽。许筹带病延年之策。果月事仍行。而诸恙皆缓。且能作劳。惟饭食不过合米。今秋孟英往诊。云经自三月至今未转。一切旧恙。弥见其增。及举脉。弦滑左甚。遽曰：岂仅可延其算哉。且有熊罴入梦矣。季冬果得一子。", "14250": "翁嘉顺去秋从梯半跌仆。初无所伤。旬日外陡发寒热。膝旁肿痛。外科汪某治之。溃后不能收攻。另拐许某疗之。识为伤络。应手渐效。然培补年余。虽纳食不减。而肌肉渐削。面色黧黑。步履蹇滞。且一旬半月之间。必患处疼肿。大发寒热。卧榻数日。始能强起。大费不赀。愈发愈剧。至冬间咽糜龈腐。睛赤音嘶。孟英按脉滑数。舌绛便艰。口臭溲少。蕴隆虫虫。良由疡医仅知温托一法。既溃之后。更以温补收功。竟未察其体气病情。以致平时所有之湿热痰火一齐关住。病犹自寻出路。寒热频作。医者不识。妄指为虚。补及逾年。人财两瘠。予元参黄柏知母甘草银花花粉绿豆栀子海䖳凫茈为大剂投之。吹以锡类散。且令日啖梨蔗麒麟菜柿饼等物。至五十日诸恙悉蠲。体腴善步。（正旺则邪亦旺。此病可治在脉滑数口臭。元参片泡冲去渣一两。酒炒川黄柏一钱半。酒炒知母三钱。济银花八钱。生粉草三钱。南花粉五钱。绿豆杵一两。黑栀皮三钱。淡海䖳先煎二两。整荸荠二两。）", "14251": "陈肖岩媳。汛愆一度。次月仍行。孟英诊曰：尺虽小弱。来去缓和。是娠也。继而果然。屠仲如弟室经事稍迟。孟英偶诊。亦以孕断。寻验。甫三月患胎漏。别医不克保而堕。堕后恶露虽行。而寒热头疼。时或自汗。且觉冷自心中出。医予温化之药。病日甚。交八日。孟英诊之。脉来沉实而数。舌苔紫黯。乃瘀血为患耳。予桃仁泽兰山楂茺蔚旋覆红花丹参通草琥珀蛤壳丝瓜络之剂。服后腹大痛。下瘀血如肺者一枚。次日诸恙较减。乳汁大流。再以前方去通草加麦蘖投之。服后仍腹痛。复下瘀块累累而诸恙若失。或问先生尝言产后腹无痛苦者。不可妄行其血。此证恶露已行。腹无疼胀。何以断为瘀阻而再行其血耶。孟英曰：正产如瓜熟蒂落。诸经荫胎之血。贯串流通。苟有瘀停。必形痛胀。堕胎如痈疡未熟。强挤其脓。尚有未化之根柈。不能一齐尽出。所以胎虽堕而诸经荫胎之血萃而未涣。浅者虽出。深者尚留。况是血旺之躯。加以温升之药。抛其顺行之路。窒其欲出之机。未到腹中。胀疼奚作。吾以循经通络宣气行瘀之法。导使下行。故出路始通。而后腹痛瘀来。然必有脉可征。非谓凡属堕胎。皆有是证也。（瘀血为患方。生桃仁研三钱。泽兰叶三钱。焦楂杵一钱半。茺蔚子杵先四钱。原红花六分。丹参三钱。旋覆包先三钱。方通草一两。生蛤壳杵一两。丝瓜络五钱。四味先煮清汤代水煎药。琥珀研冲八分。嗣去通草。加生麦芽八钱。）", "14252": "锁容亭姊患时疟。顾某一手清解。业已安谷下榻。忽然气逆肢寒。神疲欲寐。耳聋舌謇。杳不知饥。大便仍行。别无痛苦。顾知其素患脱血。元气久虚。改用参附等药。势愈剧。孟英切脉弦缓。视苔黄腻。乃胎之初孕。阻气凝痰。窒碍枢机。治当宣豁。以石菖蒲枳实旋覆半夏黄连茯苓橘皮葱白海蜇竹沥为方。投匕即效。三啜霍然。继而锁绳先室患疟。而驯致脘痞呕呃。鼻冷自汗。不食不眠。脉来歇止。医者危之。孟英视之。亦痰为患耳。即以此方去葱䖳竹沥。加薤白蒌仁竹茹投之。果验。（豁痰流气方。石菖蒲次入二钱。炒枳实一钱。旋覆包先三钱。制半夏二钱。姜炒川连八分。云苓三钱。陈皮一钱。鲜葱白次入一钱半。淡海䖳先煎一两。姜竹沥一酒杯冲。锁妇病。即以此方去葱䖳竹沥。加鲜薤白打。次入三钱。姜蒌仁研三钱。）", "14253": "潘肯堂室仲冬陡患气喘。医治日剧。孟英诊曰：两气口之脉。皆肺经所主。今肺为痰壅。气不流行。虚促虽形。未必即为虚谛。况年甫三旬。平时善饭。病起于暴。苔腻痰浓。纵有足冷面红不饥不寐自汗等证。无非痰阻枢机。有升无降耳。遂予石膏黄芩知母花粉旋覆赭石蒌仁通草海䖳竹沥菔汁梨汁等药。一剂知。二剂平。乃去二石。加元参杏仁。服旬日而安。俟其痰嗽全蠲。始用沙参地黄麦冬等以滋阴善后。（生石膏一两二钱。生赭石杵五钱。同先煨六钟。酒炒知母四钱。姜汁炒花粉四钱。旋覆包先三钱。姜蒌仁研四钱。方通草三钱。淡海䖳先煎一两。姜竹沥两酒杯冲。整莱菔整北梨各一两同绞汁冲。嗣去二石。加元参片五钱泡冲去渣。苦杏仁一钱半。俟其痰嗽全蠲。去枯芩花粉旋覆通草竹沥菔汁。加北沙参八钱。大生地八钱。花麦冬四钱。二味泡煎去渣。）", "14254": "室女多抑郁。干嗽为火郁。王杞庭姊年逾摽梅。陡患干嗽。无一息之停。目不交睫。服药无功。孟英诊焉。两脉上溢。左兼弦细。口渴无苔。乃真阴久虚。风阳上僭。冲嗽不已。厥脱堪虞。授牡蛎龟板鳖甲石英苁蓉茯苓熟地归身牛膝冬虫夏草胡桃肉之方。药甫煎。果欲厥。亟灌之即寐。次日黄昏犹发寒痉。仍灌前药。至第三夜仅有寝汗而已。四剂后诸恙不作。眠食就安。设此等潜阳镇逆之方。迟投一二日。变恐不可知矣。况作郁治而再用开泄之品耶。故辨证为医家第一要务。（冲脉系于肝。冲嗽即肝阳贼肺之嗽。大熟地一两泡汤去渣。用汤先煎煅牡蛎杵六两。血鳖甲杵四两。血龟板杵一两。紫石英三钱。四味先煨六句钟。取汤煎淡苁蓉一钱半。云苓三钱。当归身二钱。制牛膝五分虫草一钱五分。连衣胡桃肉研三钱。）", "14255": "寓意草谓伤风亦有戴阳证。此为高年而言。然有似是而非者。黄鼎如母年登大耋。季冬感冒。痰嗽气逆。额汗颧红。胸痞不饥。神情躁扰。孟英诊脉。左弦疾而促。右滑数而溢。苔色满布。系冬温挟痰阻肺。治节不伸。肝阳鼓舞直升。罗谦甫有治痰火类孤阳之案。颇相似也。以小陷胸汤加薤白旋覆赭石花粉海䖳凫茈竹沥为大剂投之。痰活便通。数日而瘥。继陈舜廷父年逾花甲。患痰嗽气逆。惟饮姜汤则胸次舒畅。医者以为真属虚寒。连投温补之剂。驯致咽痛不食。苔色灰刺。便秘无溺。孟英诊之。脉至双弦。按之索然。略无胃气。曰：渴喜姜汤者。不过为痰阻清阳之证据耳。岂可妄指为寒。叠投刚烈。胃阴已竭。药不能为矣。（戴阳证真寒假热。面赤躁扰。峻补真阳则愈。此病右脉滑数而溢。冬温挟痰阻肺。治节不伸。肝阳因而逆上。蠲痰热则风阳自息。姜汁炒川连二钱。姜蒌仁研三钱。制半夏一钱。鲜薤白打一钱半。旋覆包先三钱。生赭石杵先八钱。姜花粉四钱。淡海䖳先煎二两。整荸荠打一两。姜竹沥一大酒杯冲。）", "14256": "东垣云：中年以后。已行降令。清阳易陷。升举为宜。赵菊斋年逾花甲。偶因奔走之劳。肛翻患痔。小溲不行。医者拟用补中益气及肾气丸等法。孟英按其脉。耎滑而数。苔色腻滞。此平昔善饮。湿热内蕴。奔走过劳。邪乃下注。想由强忍其肛坠之势。以致膀胱气阻。溲涩不通。既非真火无权。亦拒清阳下陷。方以车前通草乌药延胡栀子橘核金铃子泽泻海金沙。调膀胱之气化而渗水。服之溲即渐行。改用防风地榆丹皮银花荆芥槐蕊石斛黄连当归清血分之热而导湿。肛痔亦平。设不辨证而服升提温补之方。则气愈窒塞。浊水上行。况在高年。告危极易。（车前子杵先四钱。方通草三钱。台乌药一钱半。元胡索一钱。黑栀皮三钱。橘核杵先一钱。楝核杵先三钱。生泽泻三钱。海金沙包先四钱。改用青防风一钱半。酒炒地榆炭二钱。生芥穗二钱。酒炒丹皮一钱。济银花一两。酒炒槐花一钱半。石斛先煎五钱。酒煎川连八分。当归尾一钱。）", "14257": "许芷卿痁起季秋。孟英尝清其伏暑而将愈。其从母亦知医。强投以小柴胡一剂。势复剧。孟英予温胆汤去甘草。加生石膏黄芩知母花粉芦菔而安。继因作劳太早而复发。赵某仍用清解而瘥。迨季冬移居劳顿。疟复间作。且面浮跗肿。喘嗽易嗔。孟英切脉。左弦劲而数。右滑大不调。苔黄且腻。口渴溺多。乃肺胃之痰热有余。肝胆之风阳上僭。畏虚妄补。必不能瘳。用西洋参知母花粉竹茹蛤壳石斛枇杷叶青蒿秦艽白薇银花海䖳为方。连投四剂。大吐胶痰而各恙悉除。（温胆汤加减。制半夏一钱半。陈皮八分。云苓一钱半。炒枳实一钱半。姜竹茹三钱。生石膏先煎八钱。酒炒枯芩一钱半。酒炒知母三钱。姜花粉四钱。整芦菔切一两。疟复间作方。左弦劲而数。为肝热阴虚。右滑大不调。为痰实阴虚。蠲痰热即以息风阳。西洋参三钱。酒炒知母四钱。南花粉四钱。姜竹茹三钱。生蛤壳杵先五钱。石斛先煎一两。姜枇叶刷包三钱。鲜青蒿八分。左秦艽一钱半。白薇三钱。济银花一两五钱。淡海䖳先煎二两。）", "14258": "薛氏医案。每以补中益气汤与地黄丸并用为治。虽卢不远之贤亦或效尤。其实非用药之法也。如果清阳下陷而当升举者。则地黄丸之阴凝滞腻。非所宜也。设属真阴不足当用滋填者。则升柴之耗散。不可投也。自相矛盾。纪律毫无。然上下分治。原有矩矱。屠敬思素属阴亏。久患痰嗽。动则气逆。夜不能寐。频服滋潜。纳食渐减。稍沾厚味。呕腐吞酸。孟英视脉。左弦而微数。右则耎滑兼弦。水常泛溢。土失提防。肝木过升。肺金少降。良由久投滋腻。湿浊内蟠。无益于下焦。反碍乎中运。左强右弱。升降不调。以苁蓉黄柏当归芍药熟地丹皮茯苓楝实砂仁研为末。藕粉为丸。早服温肾水以清肝。以党参白术枳实菖蒲半夏茯苓橘皮黄连蒺藜生晒研末。竹沥为丸。午服培中土而消痰。暮吞威喜丸肃上源以化浊。三焦分治。各恙皆安。悉用丸剂者。避汤药之助痰湿耳。（温肾水以清肝方。淡苁蓉一两五钱。炒川黄柏一两五钱。箱归身一两。大熟地四两。白芍二两。丹皮一两五钱。云苓三两。楝核杵四两。砂仁末二钱。藕粉为丸。培中土以消痰方。潞党参三两。炒白术一两。炒枳实一两五钱。石菖蒲二两。制半夏四两。云苓三两。橘皮一两。淡盐水微泡晒研姜川连二两。生白蒺三两。生晒研末竹沥为丸。）", "14259": "程某仲冬患感。医者闻其病前一日曾啖生芦菔一枚。而大便又溏。苔色又白。今年又为湿土在泉。遂指为中虚寒湿之病。参术附桂多剂率投。驯致舌黑神昏。尚疑为大虚之候。张镜江诊之曰：冬温也。连予犀角地黄汤而无起色。二十日外。始乞孟英视焉。舌缩底绛。苔黑如漆。口开茎萎。脉细数而弦。右则按之如无。阴液尽烁。温毒深蟠。甘露琼浆。不能复其已竭之津矣。俄而果败。继有潘圣征于仲冬患感。至十四日退热之后。杳不知饥。群医杂治。迨季冬下旬。转为滞下五色。腿肿裂血。溲涩口干。孟英诊之。左脉弦细而数。右弦滑而空。苔色黄腻根焦。时或自汗。乃气液两竭。热毒逗留之象。必从前过服温补之药。否则热退在十四日之期。何至延今五十余朝。而见证若是之棘手哉。询悉此番之病。补药不过二三剂。惟仲秋患疟。时医谓其苔白体丰。云是寒湿。尝饵附桂数十剂。且日饮烧酒耳。孟英曰：此即酿病之具矣。治病且难。何况有如许之药毒内伏。更将何法以生之耶。坚不立方。其家必欲。求药以期扶持度岁。孟英曰：是则可也。以白头翁汤加银花绿豆归身白芍陈米芦根兰叶藕为剂。而以补中益气大料蒸露代水煎药。服后焦苔渐退。粪色亦正。举家喜出望外。复丐孟英图之。奈脉无转色。遂力辞之。又沈听松母季秋患疟。孟英尝往诊之。曰：伏暑所化。且体属阳强而多痰火。切勿畏虚。辄从温补。奈病者期于速愈。广征医疗。或以为证属三阴。或谓子母疟。或指为老年胎疟。众楚皆咻。痛不能愈。延至季冬。亦转为痢。且肤肿臀疮。口糜舌疱。诸医束手。复请诊于孟英。脉与潘同。不可救药。（程某脉右按如无。为阴脉。为气竭。医法阳证必投阴药。惟阳脉重按有力可治。右按如无。则阳证阴脉。不能承受阴药。其何以治。潘圣征病左脉弦细而数为液竭。右弦滑而空为气竭。）", "14260": "谢谱香体属久虚。初冬患嗽痰减食。施某视之。云是肾气不纳。命火无权。叠进肾气汤月余。遂致呕恶便溏。不饥无溺。季冬孟英诊之。脉甚弦耎。苔腻舌红。乃中虚而健运失职。误投滋腻。更泄枢机。附桂之刚。徒增肝横。予党参白术茯苓泽泻橘皮半夏竹茹栀子薏苡蒺藜兰叶柿蒂之剂。培中泄木。行水蠲痰。旬日而愈。（弦为肝脉。弦耎则为脾败肝旺。潞党参三钱。炒白术三钱。云苓三钱。炒泽泻一钱半。制半夏三钱。橘皮一钱。姜竹茹三钱。黑栀皮三钱。生苡仁杵四钱。生白蒺三钱。建兰叶三钱。干柿蒂十个。）", "14261": "藁砧远出。妇病若狂。似属七情。而亦有不尽然者。陈氏妇患此月余。巫医屡易。所费既巨。厥疾日增。孟英切其脉弦而数。能食便行。气每上冲。腹时痛胀。询其月事。云病起汛后。继多白带。孟英曰：病因如是。而昼则明了。夜多妄言。酷似热入血室之候。径从瘀血治可也。予桃仁红花犀角菖蒲胆星旋覆赭石丹参琥珀葱白之剂。两服而瘀血果行。神情爽慧。继去桃仁红花。加当归元参数服而瘳。（能食便行。则病不在气。气每上冲。腹时痛胀。为瘀停化热。煽动肝阳。白带为阴液不及化血而时下。生桃仁研一钱半。原红花六分。镑犀角先煎八钟四钱。石菖蒲次入一钱。陈胆星炖和服一钱。旋覆包先三钱。生赭石杵先八钱。紫丹参三钱。西毛珀冲八分连须葱白二分。继去桃仁红花。加箱全归二钱。元参片泡煎去渣八钱。）", "14262": "范廉居患恙。旬日后剧。孟英视之。大解已行。热退未净。气逆不饥。呃忒自汗。脉形虚大。舌紫无苔。为上焦热恋。下部阴亏之象。予西洋参旋覆竹茹枇杷叶石斛柿蒂牡蛎龟板刀豆牛膝之剂。两服即舌润知饥。呃汗皆罢。去刀豆旋覆柿蒂。加熟地一两泡煎去渣。胡桃肉三钱。当归身二钱。投之而愈。其室则苔腻口酸。耳鸣不寐。不饥神惫。脘痛头摇。脉至虚弦。按之涩弱。以当归白芍枸杞木瓜楝实半夏石斛茯神竹茹兰叶白豆蔻为养营调气和胃柔肝之法。数啜而瘳。渠女则壮热殿屎。二便皆閟。苔黄大渴。胀閟难堪。脉来弦滑数实。系腑证也。投桃核承气加海䖳芦菔二剂而痊。韩组林年虽七十。饮啖兼人。而平时喜服药。医以为老。辄用附桂参茸等药。以期可享遐龄。讵料初八日晚饍尚健饭。三更睡醒。倏寒栗发颤。俄而四肢瘛疭。越日云亡。孟英曰：此老系阳旺之体。肥甘过度。痰火日增。年至古稀。真阴日耗。久服此等助火烁阴之药。以致风从火出。立拔根荄。与儿科所云急惊风证。殆无异焉。（范廉居上焦热恋下部阴亏方。西洋参三钱。旋覆包先三钱。姜竹茹三钱。鲜枇叶刷包三钱。刀豆二钱。制牛膝八分。石斛一两。煅牡蛎杵四两。炙龟板二两。三味先煎八钟。取汤代水煎药。脉形虚大。故不用苦寒泻热。范廉居妻肝阳炽逆。侮胃煽痰。阴中之阳亦不旺。箱归身二钱。整大白芍杵先八钱。枸杞子三钱。陈木瓜一钱半。楝核杵先三钱。制半夏一钱。石斛先煎一两。云茯神三钱。姜竹茹三钱。建兰叶三钱。白豆蔻研二分。范廉居妻腑证方。玄明粉一钱。酒洗生厢黄四钱。生桃仁研三钱。淡海䖳先煎二两。整芦菔切二两。）", "14263": "古云肥白之人多气虚。又云痰饮须以温药和之。顾听泉体丰色白。平昔多痰。晨起必喘逆。饱食稍安。颇有气虚之象。自服疏解未效。孟英诊之。左关弦。寸滑如珠。尺细而干。舌尖甚绛。乃真阴素亏。水不涵木。风阳内炽。搏液成痰。谋虑操持。心阳太扰。肺金受烁。治节不伸。苔虽白而已干。热虽微而睛赤。忌投温燥。宜予轻清。用元参石斛栀子竹茹旋覆蛤壳贝母枇叶竹叶兰叶莲心为剂。三啜而安。自谓气虚。遽服党参枸杞当归等药。下咽之后。即觉火升气逆。渐至言语支离。溲频自汗。脉已虚促不调。孟英即投三甲二至元参甘草小麦竹叶莲心。以和心肝之阳。而镇龙雷之火。一剂而平。继又作劳复感。仍授轻清之法。两剂后又因怫怒萦思。肝阳复僭。颧红面赤。左耳时聋。夜不成眠。神情烦躁。越日陡然大汗。湿透衣衾。脉极弦数而细。仍为阴虚阳越。不可误认阳虚。妄施附桂。先令熏以炭醋。扑以蛎粉。随灌以大剂二至二冬三甲元参丹参人参黄连童溲而瘳。继予多剂育阴清肝。始得全愈。（轻清方。元参片一两泡冲去渣。石斛先煎一两。黑栀皮三钱。姜竹茹三钱。旋覆包先三钱。生蛤壳杵先五钱。川贝杵四钱。姜枇叶刷包三钱。鲜竹叶二钱。建兰叶三钱。莲子心一钱。误药脉虚促不调方。煅牡蛎杵六两。血鳖甲杵四两。血龟板杵二两。三味先煨八钟。女贞杵五钱。旱莲草四钱。元参片泡煎去渣一两。生粉花三钱。北小麦四钱。莲子心一钱。脉弦数细阴虚阳越方。女贞杵五钱。旱莲草四钱。明天冬六钱切。花麦冬四钱。醋煅牡蛎杵六两。醋炙鳖甲杵四两。醋炙龟板杵二两。三味先煨八钟。元参片一两。丹参三钱。高丽参八分。酒炒川连一钱。童便煎去头尾。一酒杯冲药温服。）", "14264": "一妇产后。头痛甚剧。脉右甚滑大。予清阳明法。得大解而瘥。（血去肝阳贼胃。热壅阳明。镑犀角先煎四钱。生石膏先煎一两二钱。石斛先煎一两。酒炒知母五钱。济银花一两五钱。鲜芦根二两。姜桃叶刷包三钱。鲜竹叶二钱。旋覆包先三钱。淡海䖳先煎二两。生蛤壳杵先一两。）", "14265": "丁酉八九月间。杭州盛行霍乱转筋之证。沈氏妇夜深患此。继即音哑厥逆。比晓孟英诊其脉。弦细以涩。两尺如无。口极渴。而沾饮即吐不已。足腓坚硬如石。转时痛楚欲绝。乃暑湿内伏。阻塞气机。宣降无权。乱而上逆也。为仿金匮鸡矢白散例。处蚕矢汤一方。令以阴阳水煎成。候凉徐服。此药入口竟不吐。外以烧酒令人用力摩擦其转戾坚硬之处。擦及时许。郁热散而筋结始软。再以盐卤浸之。遂不转戾。吐泻渐止。晡时复予前药半剂。夜得安寐。次日但觉困极耳。予致和汤数服而痊。后治相类者多人。悉以是法出入获效。惟误服附子者最难救疗。", "14266": "郑凤梧年六十余。秋间患霍乱。凛寒厥逆。烦闷躁扰。口不甚渴。或以为寒。余察脉细欲伏。苔白而厚。乃暑湿内蕴未化也。须具然犀之照。庶不为病所蒙。因制然照汤予之。一饮而厥逆凛寒皆退。脉起而吐泻渐止。随以清涤法愈之。", "14267": "一妇年少体瘦。初秋患霍乱转筋。舌绛目赤。大渴饮冷。脉左弦强而右滑大。此肝胃之火素盛。而热复侵荣也。以白虎汤去米草。加生地蒲公英益母草黄柏木瓜丝瓜络薏苡。一剂知。二剂已。丹溪云。转筋由于血热。此证是矣。（生石膏先煎一两二钱。酒炒知母五钱。大生地泡冲去渣八钱。蒲公英一两。益母草五钱。酒炒川黄柏一钱半。陈木瓜三钱。丝瓜络三钱。生苡仁杵八钱。）", "14268": "陆叟年七十余。仲秋患霍乱。自服单方二三日。呕吐虽已。利犹不止。且频频作哕。声不甚扬。面赤目闭。小便不通。孟英视之。脉虽虚软。并无脱象。况舌赤而干。利下臭恶。气分伏暑。业扰及荣。虑其络闭神昏。胡可再投热剂。遂以紫雪三分用竹茹枇杷叶通草丹参连翘石菖蒲桔梗黄芩芦根煎汤。候凉调而徐服。次日复诊。目开哕止。小溲稍行。于前方裁紫雪。加石斛苡仁。服二剂。利减能啜米饮矣。随用致和汤十余服而瘳。（舌赤而干二句。皆气分伏有暑邪实热之现证。姜竹茹三钱。姜枇叶三钱。方通草三钱。紫丹参三钱。连翘壳三钱。石菖蒲次入二钱。苦桔梗次入三钱。酒炒枯芩一钱半。鲜芦根二两。候药凉调送紫雪三分。玩舌赤而干二句。自服方必系温补窒热。频频作哕四句。病邪皆在气分。气机失其升降。欲降暑邪。必清气道。故投凉润清通之品。稍佐菖桔紫雪以行之。紫雪候凉调服。盖恐药汤沸热。减损紫雪辛香之性。）", "14269": "陈妪年已七旬。辛亥秋患霍乱转筋甚危。孟英诊之。已目陷形消。肢冷音飒。脉伏无溺。口渴汗多。腹痛苔黄。自欲投井。因先取西瓜汁命予恣饮。方用石膏知母麦冬黄柏芩连竹茹木瓜威灵仙。略佐细辛分许。煎成徐服。复杯而瘥。（此证可治在口渴汗多。腹痛苔黄。正旺则邪亦旺。汗为阴液。汗多则阴津未竭可知。此脉伏无溺。乃热邪伤肺。肺气不行。非气液两竭之比。重用知柏芩连之苦。合木瓜之酸。以敛其汗入内。则此汗即是阴液。又用灵仙细辛。行使一派沉降苦寒之药。生石膏先煎一两六钱。酒炒知母五钱。酒炒川黄柏二钱。酒炒枯芩一钱半。酒炒川连一钱。花麦冬五钱。陈木瓜四钱。威灵仙次入一钱半。北细辛次入二分。）", "14270": "陈楚珍媳陡患霍乱。脐间贴以回阳膏而不效。孟英按脉。滑数右甚。口竭苔黄。令揣胸下。果坚硬而痛。曰：吐泻虽多。食尚恋膈。非寒证也。回阳膏亟宜揭去。以菖枳苏连芩桔茹牛海䖳芦菔为剂。一服而瘳。（脉滑数右甚。为肺胃痰实兼挟阴虚。石菖蒲次入二钱。苦桔梗次入三钱。生苏子研次二钱。炒枳实一钱半。姜枯芩一钱半。姜川连八分。姜竹茹三钱。姜牛子研三钱。淡海䖳先煎二两。鲜芦菔切一两。）", "14271": "纪运翔年十七。五月霍乱。势亦垂危。孟英往视。然已手面皆黑。目陷睛窜。厥逆音嘶。脉伏无溺。舌紫苔腻。大渴汗淋。神情瞀乱。危象毕呈。时未交芒种。暑湿之令未行。仍是冬寒内伏。春令过冷。入夏犹凉。气机郁遏不宣。故欲变温病者。皆转为此证。与伏暑为患者。殊涂同归。但不腹痛耳。以寒邪化热。究与暑湿较异也。亟令刺曲池委中。出血如墨。方以黄芩为君。臣以栀豉连茹苡半。佐以蚕矢芦根丝瓜络。少加吴萸为使。阴阳水煎。候温徐徐服之。遂不吐。次日脉稍起。又两剂黑色稍淡。肘膝稍和。反加睛赤烦躁。是伏邪将。从外泄也。去吴萸蚕矢。加连翘益母草滑石。而斑发遍身。苔始渐化。肢温得寐。小溲亦行。随予清搜化毒之药。多剂而痊。名其方曰黄芩定乱汤。嗣治多人。悉以此法增损获效。史客素吸洋烟而患此证。予此方数帖后。反便秘目赤。渴汗昏狂。亦是久伏之邪渐欲外越也。予竹叶石膏汤加减而瘳。此外湿盛者加茵陈滑石。气实者加枳桔。饮阻食滞者加厚朴芦菔。肝郁气结者加紫苏楝实。口渴用茅根汤或藕汁频灌。", "14272": "附录黄芩定乱汤方治温病转为霍乱。腹不痛而肢冷脉伏。或肢不冷而口渴苔黄。小水不行。神情烦躁。黄芩（酒炒）焦栀子香豉（炒，各一钱五分）原蚕砂（三钱）制半夏橘红（盐水炒，各一钱）蒲公英（四钱）鲜竹茹（二钱）川连（姜汁炒六分）陈吴萸（泡淡一分）阴阳水二盏煎一盏。候温徐服。此外转筋者加生苡仁八钱。丝瓜络三钱。溺行者用木瓜三钱。湿盛者加连翘茵陈各三钱。（此证可治在舌紫苔腻。大渴汗淋。温热全在气分。大渴肺阳尚旺。汗淋有汗则阴津未竭。刺曲池委中出血最要。针刺以疏泄其邪。投药方能有效。嗣去吴萸蚕矢。加酒炒翘壳一钱半。酒炒益母三钱。二味同次入。西滑石先煎四钱。）", "14273": "上古无痘。至汉始有。今时罕有不出痘者。以生齿日繁。地气日热。所以古人最重伤寒。今世偏多温热也。于此日上海病因。尤为贴切。地气既日热。秽气亦日盛。若伏邪欲发。客邪外入。两邪交讧。肠胃乃乱。故气道立时闭塞。血脉因而瘀滞。四肢厥冷。手面皆黑。阳明多气多血之经。见证若是之骤者。非气血忽然枯槁也。夫人气以成形耳。气不流行。血肉即死。故初起亟宜开闭。俾气通血活。邪得外泄则正自复。昧者不知邪闭血凝热深厥深之理。见其肢冷脉伏。即以为寒。又疑为脱。既不敢刺。更投热药。使邪无宣泄。愈闭愈冷。虽七窍流血而死亦不悔悟。亦有邪闭则正气无以自容而外脱者。阳从上脱。则汗多而气夺。阴从下脱。则泻多而液亡。所谓内闭外脱也。欲其不外脱。必开其内闭。如紫雪绛雪行军散。皆开闭透伏之良方也。而飞龙夺命丹即合行军绛雪二方而加峻者。且有人中白引浊下行。尤具斩关夺命之能。", "14274": "附录飞龙夺命丹方治痧胀疗痛。霍乱转筋。厥冷脉伏神昏危急之证。及受温暑瘴疫秽恶阴晦诸邪。而眩晕痞胀。瞀乱昏狂。或卒倒身强。遗溺不语。身热瘛疭。宛如中风。或时证逆传。神迷狂谵。小儿惊痫。角弓反张。牙关紧闭诸证。朱砂（飞二两）明雄黄（飞）灯心灰（各一两）人中白（漂煅，八钱）明矾青黛（飞，各五钱）梅冰麻黄（去节，各四钱）真珠牙皂当门子蓬砂（各三钱）西牛黄（二钱）杜蟾酥火硝（各一钱五分）飞真金（三百页）十六味各研极细。合研匀。瓷瓶紧收。毋令泄气。以少许吹鼻取嚏。重者再用凉开水调服一分。小儿减半。", "14275": "褚子耘使女患此。已身僵矣。孟英以夺命丹二分嘱其灌入。顷刻活动。随予解毒活血汤。数服得生。一人孟英治愈。后已溺行能食。余热外泄。满面赤瘰。忽然神气瞀乱而死。一人孟英治愈。二便已如常矣。越数日云饮食不得下。戴眼呃忒而逝。一人业已向愈。忽然神情恍惚。药不及救。陈解香弟患此垂危。孟英治愈。遂不服药。月余复来请勘。已咽痛碍进水谷。颐肿舌糜。牙关甚紧。痰嗽胁疼。溺赤管痛。便溏色酱。此余毒蕴隆。失于清解。脉已弦紧数疾。莫可措手。并录以为贾旅告。", "14276": "朱鸣岐患下利转筋。医见肢冷。即投温补。服药即吐。既而呃忒不已。温补加峻。病日以危延至九朝。孟英按脉。至左弦滑。右弱不应指。苔黄厚而腻浊。小水不行。脐上拒按。因谓曰：病原不重。误药致剧。命不应死。幸而得吐。予枳桔芩连茹夏苏翘芦根枇杷叶滑石开痰行食。舒结通阳。两剂呃果止。而遍身赤斑。又两剂燥矢下而苔化溺行。右脉渐振。随予清肃法调养而瘳。此证若初治得法。一二剂可愈。举世以泻证吐证霍乱证霍乱转筋证。皆为寒证。往往不察病情。辄投热药。今见肢冷而右脉软弱。彼方以为虚寒的据。况服药即吐。呃忒随来。以霍乱转筋而见呃忒。皇皇然以为虚脱之象。故温补日以加峻。纵使一蹶不起。病者无怨。医家不悔。授受相承。伎俩如是。良可慨已。此外如胸腹疼痛。疟疾哮喘。经阻产后等证。世俗亦多指为寒病。虽以热药杀之不知。呃忒则尤多枉死。孟英尝治一角妓。患呃累日。破身太早。固是虚证。然血去阴伤。岂可反以温燥助热。遂致下焦不摄。妓性畏药。用一味鸡子黄。连进数服而安。（炒枳实一钱半。苦桔梗次入三钱。酒炒枯芩一钱半。酒炒川连八分。制半夏二钱。姜竹茹三钱。生苏子研次一钱半。连翘壳三钱。姜枇叶刷包三钱。鲜芦根一两。西滑石先煎四钱。）", "14277": "王季杰妾。秋夜陡患霍乱。腹痛异常。诊其脉。细数而弦。肢冷畏寒。盖复甚厚。询其口。不渴而泻。亦不热。然小便全无。吐者极苦。舌色甚赤。新凉外束。伏暑内发也。绛雪玉枢丹灌之皆不受。泻至四五次。始觉渐热而口大渴。仍不受饮。语言微謇。孟英令捣生藕汁徐灌之。渐能受。随以芩连苡楝栀茹桑斛蒲公英煎服。痛即减。吐泻亦止。改用轻清法而愈。（酒炒枯芩一钱半。酒炒川连八分。生苡仁杵八钱。酒炒楝核二钱杵先。酒炒栀皮一钱半。冬桑叶三钱。姜竹茹次入三钱。石斛先煎八钱。蒲公英五钱。药温服。）", "14278": "沈春泉年五十七。立冬前五日食蟹面后。陡患霍乱转筋。所吐泻者皆水。初进桂附药。筋转益甚。周身微汗。神倦懒言。指渐冷。脉渐伏。时欲太息。更方用牡蛎一两。龟板八钱。阿胶四钱。服后势较剧。孟英视之。苔黄大渴。小便全无。泻出极热。心下拒按。伏暑挟食之证。不知何所见而予燥补涩腻之药。嗣闻其次郎于立冬后。亦患此证。医知伏暑。用黄连等药。吐泻已止。因脉未遽起。不知为伏热不清。改投附桂等三帖而亡。尤可哀已。陈艺圃亦知医。其室人于仲秋患霍乱转筋。自诊以为寒也。投热剂势益甚。招朱椒亭视之。亦同乎主人之见也。病尤剧。乃延孟英。曰：此寒为外束之新邪。热是内伏之真病。口苦而渴。姜附不可投矣。予河间法。人皆不信。再与他医商之。仍用热剂。卒至口鼻出血而死。此案已见正编卷二。不抄不印。", "14279": "钱某患霍乱自汗。肢冷脉无。平日贪凉饮冷。人谓寒证。欲用大剂热药。孟英曰：苔虽白。然厚而边绛。且渴甚。头大痛。不可因寒凉致病。不察其有暑热之伏也。遂以五苓去术。加黄连厚朴黄芩竹茹木瓜扁豆叶。服后脉稍出。汗渐收。吐利亦缓。即去肉桂。加桑枝滑石甘草。头痛吐利皆止。苔色转黄。随用清暑和中而愈。（木猪苓三钱。生泽泻三钱。云苓一钱半。姜炒川连二钱。姜炒枯芩一钱。制厚朴一钱。姜竹茹三钱。陈木瓜二钱。扁豆叶七片。肉桂心二分。嗣去肉桂。加姜炒桑枝二钱。西滑石先煎四钱。生粉草一钱。）", "14280": "朱浦香年五十六。自幼患童劳。继以吐血。三十外即绝欲。得延至此。而平素便如羊矢。其血分之亏如是。今秋陡患呃忒。连服滋镇温纳之药。势濒于危。延孟英诊。脉至弦滑搏数。苔黄厚而腻。口苦溺赤。主大剂凉润。如雪羹蒌仁竹沥枇杷叶芦根元参紫菀射干兜铃菖蒲等多剂。连下赤矢始瘳。如此衰年虚体。尚因痰热致呃。故虚寒之呃。殊不多见。（大剂凉润用淡海䖳先煎二两。整荸荠一两。姜蒌仁研四钱。姜竹沥一大酒杯冲。姜枇叶刷包三钱。鲜芦根二两。元参片泡冲去渣八钱。紫菀茸一钱半。姜射干三钱。马兜铃三钱。石菖蒲次入二钱。）", "14281": "蒋循庵媳患霍乱转筋。交三日矣。厥逆目窜。膈闷无溺。苔黄苦渴。脉极弦细。屡进桂附姜术。气逆欲死。予昌阳泻心汤加减。煎成徐服。外以吴萸研末。卤调贴涌泉穴。服二剂。吐止足温。去苏朴。加楝斛蒲公英。多剂始痊。盖伏暑挟素盛之肝阳为病。误服温补。以致遽难廓清也。（昌阳泻心汤方。治霍乱后胸前痞塞。汤水碍下。或渴或呃。石菖蒲黄芩酒炒。制半夏各一钱。川连姜汁炒。五六分。苏叶三四分。制川朴八分。鲜竹茹枇杷叶刷。各二钱。芦根一两。天雨水急火煎。徐徐温服。小溲秘涩者加紫菀。加减用酒炒枯芩三钱。姜竹茹四钱。姜枇叶刷包三钱。芦根二两。制朴一钱。生苏子一钱半。海䖳先煎二两。菖蒲次一钱。）", "14282": "谢氏妇怀孕五月。便泻四日。医投姜附桂朴药一帖。遂四肢麻冷。气塞神昏。溺闭汗淋。大渴呕吐。延孟英诊。脉未全伏。先饮以酱油汤。吐渐止。随予参连芩柏茹斛银花扁豆叶蒲桃干芦根绿豆。以冬瓜汤煎。徐徐温服。外用炭醋熏之。各恙皆瘥。次日脉弦滑。泻未止。以白头翁汤加参草银花扁豆蒲公英蒲桃干砂仁。两剂而痊。（西洋参三钱。酒炒川连八分。酒炒枯芩一钱半。酒炒川柏二钱。姜竹茹三钱。石斛先煎一两。银花一两五钱。扁豆叶十片。蒲桃干一钱。芦根一两。整绿豆先煎五钱。整冬瓜二两。煨汤煎药。）", "14283": "詹耀堂子年二十。患霍乱。服姜桂数剂。泻不止。素吸鸦片。疑为虚漏。补之泻益甚。孟英视之。大渴而脉弦数。幸而起病不因暑热。然阴分素亏。虽饮冷贪凉。热药岂堪过剂。设无便泻以分其药力。则津液早枯矣。予白头翁汤合封髓丹。加银花绿豆石斛。一剂知。二剂已。（方义甘凉救阴。苦寒泻暑。酒炒白头翁一钱半。酒炒川柏三钱。酒炒川连一钱。大生地八钱。明天冬切六钱。开水泡煎去渣。济银花一两五钱。生绿豆先煎五钱。石斛先煎一两。）", "14284": "蒋敬堂母年七十四。陡患呕泻。身热腹痛。神思不清。孟英诊之。脉微弱而数。曰：暑脉自虚。不可以高年而畏脱。辛散痧药。则不免耗伤其津液。爰定芩连滑斛茹柏银花竹叶橘皮枇杷叶之方。冬瓜汤煎。一剂而热退神清。再剂霍然。（酒炒枯芩一钱半。酒炒川连一钱。酒炒川柏三钱。西滑石先煎四钱。济银花一两五钱。鲜竹叶二钱。酒炒枇叶刷包三钱。五爪红一钱半。冬瓜二两。煨汤煎药。）", "14285": "罗吉人立冬前。患霍乱转筋。某知其阴分素亏。病由伏暑。服药已得转机。数日后渐有呃忒。孟英视之。脉弦数左甚。苔焦而渴。龈衄脘闷。便溏色酱。小便短赤。皆伏暑未清。气机阻塞之象。既失清肃。当脐尚贴回阳膏。屡嘱揭去不从。后闻不起。", "14286": "某新秋陡患洞泻如注。即浑身汗出如洗。恹恹一息。孟英往勘。脉来沉细。身不发热。俨似虚寒之证。惟苔色黄腻。小溲全无。乃湿热病也予桂苓甘露饮加厚朴。投匕而瘳。（木猪苓三钱。生泽泻三钱。云苓一钱半。生石膏先煎一两二钱。西滑石先煎五钱。制厚朴次入一钱。）", "14287": "某赤膊不容盖复。犹云五内如焚。目陷音嘶。苔黄大渴。而啜饮即吐。肢厥脉伏。市医令服姜汤一杯。幸不受。适孟英至。亟取冷雪水命将小匙徐灌之。遂不吐。更以石膏黄连知母泻其逆冲之火而愈。（此证可治在苔黄大渴。得饮即吐。生石膏先煎一两二钱。酒炒川连一钱。酒炒知母五钱。鲜枇叶刷包三钱。鲜芦根二两。石斛先煎一两。南花粉四钱。西滑石先煎五钱。旋覆包先三钱。陈木瓜一钱半。石菖蒲次入二钱。）", "14288": "钱某患霍乱。兼吐蛔十余条。而口干脉细。是暑伏厥阴以犯中也。以连梅茹楝苡斛苏芩清之而愈。（酒炒川连一钱。酒炒楝核杵先四钱。乌梅肉杵先三钱。姜竹茹三钱。生苡仁杵八钱。石斛先煎一两。酒炒枯芩一钱半。紫苏叶次入四分。）", "14289": "张二梅年逾六旬。秋间患霍乱转筋。医见高年而厥逆多汗。拟进温补。张不敢服。但用平淡单方及外治法而瘥。然从此大便不坚。时时自汗。遍身疮疥。畏热异常。立冬后。孟英诊之。脉甚滑数。口渴苔黄。便溺皆热。犹著夹衣。是赋质偏阳。湿热内盛。幸而畏进温补。得以引年。予大剂清化法渐愈。（酒炒西茵陈三钱。酒炒枯芩一钱半。酒炒栀皮三钱。冬瓜皮四钱。蚕砂五钱。芦根二两。生苡仁杵八钱。鲜枇叶刷包三钱。西滑石先煎五钱。淡海䖳先煎二两。）", "14290": "石雨田母年近五旬。陡患霍乱转筋。苔黄大渴。神情烦躁。证属伏暑。脉颇不恶。而浑身冷汗。摇扇不停。已为阳越之象。不敢予方。寻即告殒。此凭证不凭脉也。朱巽泉父年已六旬。患霍乱转筋。证不甚剧。问答音清。而脉微欲绝。亦决其不治。已而果然。此凭脉不凭证也。某丙夜患此证。刺出黑血。侵晓孟英往视。形脉两脱。大汗如淋。目陷音嘶。溺无苔腻。平素嗜饮少谷。好善忘劳。暑湿蕴中。正气溃散。勉投参药。竟不能救。孟英次女。八月二十三日忽患痛泻。肢冷脉伏。崔某进附子理中汤加减。泻不止而苔黑唇燥。颇露热象。改投犀斛生脉散等药。形渐脱。又用附桂八味汤。遂于二十九日舌焦如炭而逝。噫。据此病情。是伏暑也。痧证霍乱。挟食者必先去食。伤寒亦然。秦氏论之详矣。然竟有病始饱食之余。初非因食为患者。半痴尝云。既无枵腹待病之理。岂可专以攻消为治。故临证必审问慎思而明辨之。庶免颟顸贻误之弊。", "14291": "李华甫继室。陡患霍乱兼溺血如注。头疼如劈。自汗息微。势极危殆。速孟英诊视。脉甚弦驶。此肝火内炽。暑热外侵。以犀角木通滑石栀子竹茹薏苡银花茅根菊叶为大剂。和入藕汁。送当归龙荟丸。吐泻即已。溺血亦减。惟小便时头犹大痛。必使人紧抱其头。重揿其巅。始可略耐。尚是风阳僭极。肺胃不清也。以苇茎汤去桃仁。加百合白薇元参小蓟蒲公英竹叶西瓜翠衣莲子心为方。和入童溺。仍吞龙荟丸。服旬日全愈。（镑犀角先煎四钱。细木通一钱。滑石先煎五钱。黑栀皮三钱。姜竹茹三钱。生苡仁八钱。银花一两五钱。鲜茅根五钱。鲜菊叶二钱。藕二两打汁冲药送龙荟丸三钱。次方清肺胃佐息风阳。肺胃清。风阳始有下降之机。鲜芦根二两。生冬瓜子四钱。生苡仁杵八钱。百合花三钱。香白薇一钱。元参片泡冲去渣八钱。蒲公英一两。小蓟一钱半。鲜竹叶二钱。西瓜皮四钱。莲子心一钱。童便煎去头尾冲一大酒杯。仍药送龙荟丸三钱。）", "14292": "吴绿园仲夏陡患发热呕吐。茎缩腹痛。孟英诊脉。弦耎而数。苔色黄腻。宜清厥阴蕴热。非痧也。予楝茹连斛栀柏银花通草丝瓜络为方。一剂知。数剂愈。（辨厥阴蕴热。在茎缩腹痛。酒炒楝核杵先二钱。姜竹茹三钱。酒炒川连一钱。酒炒川柏三钱。石斛先煎一两。黑栀皮三钱。济银花一两五钱。方通草三钱。丝瓜络三钱。）", "14293": "姜秋农疟泻初痊。遽劳奔走。陡患霍乱转筋。面臂色紫。目陷音嘶。胸闷苔黄。汗多口腻。神疲溲秘。脉细而弦。孟英以沙参蚕矢苡仁竹茹半夏丝瓜络木瓜车前子扁豆叶。阴阳水煎。送左金丸一钱。外以吴萸一两研末。盐水调涂涌泉穴。服后吐泻渐止。噫气不舒。呃忒胁痛。汗减口燥。脘下拒按。脉耎而弦。以素多肝郁也。去沙参蚕矢木瓜车前左金。加紫菀郁金楝实通草枇杷叶。二帖溲行呃止。苔退足温。腰胀腿痛。手紫渐淡。去郁苑通楝。加沙参石斛兰叶藕鲜稻头。亦二帖。脉和胀减。啜粥口咸。体素阴亏也。去半夏扁豆叶。加归身花粉橘皮。又二帖。大解行而安谷。腰酸少寐。为易西洋参加麦冬羊藿以调之。数帖后。又加枸杞杜仲而愈。此本虚标实之证。须看其先后用药之法。半痴游刃有余。治标而不犯其本。用药与病机宛转相赴。（北沙参四钱。蚕砂五钱。生苡仁杵四钱。姜竹茹三钱。制半夏一钱半。丝瓜络三钱。陈木瓜八分。车前子杵先四钱。扁豆叶十片。药送左金丸一钱。嗣去沙参蚕矢木瓜车前左金。加紫菀茸一钱半。黄郁金一钱。楝核杵先二钱。方通草三钱。姜枇叶刷包三钱。二帖后去郁苑通楝。加沙参四钱。石斛先煎五钱。建兰叶三钱。藕肉切五钱。鲜稻头三钱。又二帖后。去半夏扁豆叶。加箱归身一钱。南花粉四钱。陈皮八分。又二帖后。沙参易西洋参。加花麦冬四钱。羊藿一钱。数帖后。加枸杞三钱。川杜仲一钱。）", "14294": "胡次瑶妇陡患肢麻昏运。以为急痧。孟英视之。面微红。音低神惫。睛微赤。苔色微黄。足微冷。身微汗。胸微闷。脉微弦。乃本元素弱。谋虑萦思。心火上炎。内风随以上僭。岂可误作痧闭。妄投香散之药哉。以人参龙蛎菖连石英麦冬小麦竹叶莲子心为方。两啜而瘥。寻予平补善其后。（高丽参八分。醋煅龙骨杵先五钱。醋煅牡蛎杵先二两。石菖蒲次入八分。酒炒川连一钱。紫石英杵先三钱。花麦冬四钱。北小麦三钱。鲜竹叶二钱。莲子心一钱。）", "14295": "姚欧亭初夏偶患大泻。后苦脾约。更旬始一更衣。既而匝月一行。甚至月余一行。极其艰滞。而先硬后溏。汗出神惫。年逾六秩。步履蹇滞。虽广服人乳及润导诸药。率不效。间或纳食如哽。呕吐酸辣。六脉迟耎。苔色白润不渴。小便清长。腹无胀痛。此真中气不足。溲便为之变也。岂肠燥便秘。可以润药濡之哉。既不宜润。更不可下。以中虚开阖无权。恐一开而不复阖。将何如耶。亦不可升提。盖吐酸食哽。已形下秘上冲之势。又素吸洋烟。设一阖而竟不开。又将何如耶。爰以参术橘半旋芍鸡金木瓜枇杷叶为方。服六剂。更衣两次。解四弹丸。又三剂。解十五六丸。又三剂。下九丸而始畅。并不坚燥。亦无溏矢。毫不怯力。是药证已符。为留调理法而别。设或吐酸食哽。则暂用参连橘半旋茹苏叶枇杷叶紫石英以清肃镇息之。八月初秋阳正烈。欧亭初七日忽然身热呕泻。白苔满布。神惫不支。腹痛汗频。音低溺涩。先予参连夏朴茹滑苡苏蚕砂扁豆叶。二剂热退神清。而左脉仍弦。关上高。呕酸无寐。手足振惕。客邪虽解。土受木乘也。去滑朴蚕砂扁豆叶。加茯神蛤壳紫菜绿豆白蔻仁。三剂苔化能眠。知饥泻减。去蔻蛤。加菖蒲白术。五剂而痊。霍乱之开阖失常。中枢为邪所乱也。此证之开阖无权。中虚不能主持也。一实一虚。正可互勘。至愈后之呕泻振惕。又为风暑乘虚扰中之霍乱证。（潞党参三钱。炒白术一钱半。制半夏三钱。陈橘皮一钱半。旋覆包先一钱半。酒炒白芍一钱半。炙鸡金三钱。陈木瓜六分。酒炒枇叶刷包一片。身热呕泻方。西洋参三钱。酒炒川连八分。制厚朴一钱。制半夏一钱半。姜竹茹三钱。西滑石先煎四钱。生苡仁杵四钱。蚕砂五钱。扁豆叶七片。生苏子研一钱。嗣去滑朴蚕砂扁豆叶。加云茯神三钱。生蛤壳杵先四钱。绿豆先煎五钱。淡紫菜三钱。白蔻仁研入四分。嗣去蔻蛤。加石菖蒲次入六分。炒白术一钱半。热净则仍健其中。）", "14296": "己丑五月。天气骤热。孟英母陡患霍乱。肢冷自汗。脉微苔白。腹大痛。欲重按。是中虚有素。因热而受寒侵也。进大剂理中汤加桂枝白芍。复杯而愈。此所谓舍时从证也。（辨中虚受寒。在脉微苔白。腹欲重按。潞党参三钱。炒白术三钱。炒粉草一钱。炒干姜五钱。川桂枝次入一钱二分。酒炒白芍一钱半。）", "14297": "徐氏素无病。胃亦强。且善作劳。夜分忽泻二次。晨起为孟英梳发未毕。又泻一次。因诊之。脉七至而细促不耐按。略无病。若此脉病人不病。殆不始于今日。不可救药也。既而泻颇缓。且食山东挂面一小碗。然尚能以乳哺女。而既吸之后。乳即瘪而不起矣。形亦渐削。汗亦渐多。脉亦渐脱。音亦渐嘶。戌刻遽逝。乃中气卒然溃散。绝无仅有之候也。", "14298": "蚕矢汤治霍乱转筋。肢冷腹痛。口渴烦躁。目陷脉伏时行急证。", "14299": "解毒活血汤治温暑痧邪。深入营分。转筋吐下。肢厥汗多。脉伏溺无。口渴腹痛。面黑目陷。势极可危之证。", "14300": "驾轻汤治霍乱后余邪未清。身热口渴。及余热内蕴。身冷脉沉。汤药不下而发呃者。", "14301": "高若舟偶患腹胀，医投温运，渐至有形如痞，时欲冲逆吐酸，益信为虚寒之疾。温补之药备尝，饮食日减，其痞日增，肌肉渐消，卧榻半载。甲辰春，迓孟英诊。脉沉弦而软滑，大解不畅，小溲浑短，苔色黄腻。乃肝郁气结，郁则生热，补则凝痰。与栀、楝、萸、连、元胡、乌药、旋、枳、鸡金、鳖甲、茹、橘、苓、夏等药。服之证虽递减，时发寒热，四肢酸痛，或疑为疟。（此少阳之气，郁而欲伸之象。）孟英曰：此气机宣达，郁热外泄，病之出路，岂可截乎？参以秦艽、柴胡、豆卷、羚羊、蚕砂、桑枝之类，迎而导之。（清热涤饮，条达肝气，允属合法。）人皆疑久病元虚，药过凉散，而若舟坚信不疑，孟英识定不惑。寒热渐息，攻冲亦止。按其腹尚坚硬，时以龙荟滚痰丸缓导之，（峻药缓投法。）饮食递加，渐次向愈。若舟善作隶，因集诗品书一联，以赠孟英云：古镜照神，是有真宰；明漪绝底，如见道心。盖颂其隔垣之视也。", "14302": "赵听樵室，高若舟之妹也。去冬偶患脘痛，黄某治之，渐增头疼眩晕，气逆呕吐，痰多不寐，便溏不食，经事不行，（脘痛而过投香燥，亦能致此证，况误投温补乎？）始谓其虚。三月后又疑为娠，诸药遍试，病日以进。若舟延孟英脉之，左弦而数，右滑以驶。曰：病药耳，旬余可瘳。赵疑大病小视，不服其方。越半月，病者颈软头难举。医谓天柱已倒，势无望矣。若舟闻之，复恳援于孟英。疏方仍是前诊之法。赵问：此病诸医束手，大剂补药，尚无寸效，而君两次用药，皆极清淡，虽分两颇重，亦焉能有济乎？孟英曰：子何愚耶？药惟对证，乃克愈病，病未去而补之，是助桀也。病日加而补益峻，是速死也。原彼初意，非欲以药杀人，总缘医理未明，世故先熟，不须辨证，补可媚人，病家虽死不怨，医者至老无闻，一唱百和，孰能挽此颓风！令壶体质虽丰，而阴虚有素，是以木少水涵，肝阳偏盛，上侮于胃，则为脘痛，斯时投以酸苦泄肝，甘凉养胃，（叶氏独得之秘。）数日而愈矣。乃温补妄施，油添火上，肺津胃液灼烁无余，怒木直升，枢机窒塞，水饮入胃，凝结为痰，虽见证多端，皆气失下降，岂可指眠食废以为劳，月汛爽而为妊耶？予以大剂轻淡之品，肃清气道，俾一身治节之令，肝胆逆升之火，胃府逗留之浊，枢机郁遏之热，水饮凝滞之痰，咸得下趋，自可向愈。不必矫枉过正，而妄以硝、黄伤正气。所谓药贵对证，而重病有轻取之法，非敢藐视人命，故将疲药塞责也。赵极感悟。投匕即效，逾旬果安。又一月经至，嗣与滋养，康复如常。越二载又病，复惑于黄某，而孟英之功尽堕，惜哉！", "14303": "马某，年三十余，素用力。患发热恶寒，肢振自汗，少腹气上冲胸，头疼口渴。孟英诊曰：卫虚风袭，而络脉久伤，肝风内动。与建中去饧，（建中之力在饴糖，今去饴糖，仍是桂枝法，）加龙、牡、石英、苁蓉、楝实、桑枝，数帖而痊。（眉批：发热恶寒，头疼自汗，皆桂枝证。此人必津液素亏，因汗出而益耗其津，故肝失所养而上冲，肺胃失所养而口渴也。）", "14304": "李燕标参戎，于癸夏将欲赴都，馆于石北涯家。项后患疽，外科佥云不治。孟英荐老医朱嵩年疗之渐安。孟英偶诊其脉，谓北涯曰：李证有可愈之机，脉难久享其年。北涯惊问所以，孟英曰：左尺坚搏，真阴已伤，非善象也。既而告痊北上，今春果卒于京。", "14305": "李叟，年越古稀，意欲纳妾，虽露其情，而子孙以其耄且瞽也，不敢从。因此渐病狂惑，群医咸谓神志不足，广投热补之药，愈服愈剧，始延孟英诊之。脉劲搏指，面赤不言，口涎自流，力大无制。曰：此禀赋过强，阳气偏盛，姑勿论其脉证，即起病一端，概可见矣。如果命门火衰，早已痿靡不振，焉能兴此念头。医见其老，辄疑其虚，须知根本不坚实者，不能享长年，既享大寿，其得于天者必厚，况人年五十，阴气先衰。徐灵胎所谓千年之木，往往自焚，阴尽火炎，万物皆然。去冬吾治邵可亭，孤阳喘逆，壮水清火之外，天生甘露饮，灌至二百余斤，即梨汁也，病已渐平，仅误于两盏姜汤，前功尽堕。可见阴难充长，火易燎原。今附、桂、仙茅、鹿茸、参、戟、河车等药，服之已久，更将何物以生其涸竭之水而和其亢极之阳乎？寻果不起。", "14306": "翁嘉顺室，娩后发热，竹林寺僧治之不应，温、龚二医，皆主生化汤加减，病益剧。请孟英诊之，脉软滑微数。曰：素体阴亏，热自内生，新产血去，是以发热。惟谵妄昏瞀，最是吓医之证，渴喜热饮，宛似虚寒之据。宜其猜风寒而表散，疑瘀血以攻通，帖帖炮姜，人人桃、桂，阴愈受劫，病乃日加。（眉批：凡痰饮内盛之人，服寒热药，皆如石投水，人皆以为禀赋之异，不知皆痰饮为患也。）幸而痰饮内盛，津液未致涸竭，与蠲饮六神汤去橘、半，加西洋参、生地、花粉、竹茹、知母、生白芍为剂。数日而瘳。逾旬复发热，或疑凉药之弊，或谓产蓐成劳，众楚咻之，病渐进矣！其小姑适吴氏者，向役于冥曹，俗谓之活无常，偶来探病，忽仆地而僵，口中喃喃。或问汝嫂病何如？答云：须服王先生药。人皆异之。次日仍乞诊于孟英。曰：脉浮数而弦，是风温也，与前病异。便泻无溺，肺热所迫，大渴无苔，胃汁受烁。亟与天生建中汤频灌，即蔗汁也。药主大剂甘凉，果得津回舌润，渐以痊可。病染于姑，孟英诊曰：高年阴气太亏，邪气偏盛。「玉版论要」云：病温虚甚死。言人之真阴甚虚，曷足以御邪热而息燎原，可虞在两候之期乎？至十四天果殒。而嘉顺亦染焉，初发热即舌赤而渴，脉数且涩，孟英曰：非善证也。盖阴虚有素，值忧劳哀痛之余，五志内燔，温邪外迫，不必由卫及气，自气而营。急与清营，继投凉血，病不稍减。且家无主药之人，旁议哗然。幸其旧工人陈七，颇有胆识，力恳手援。孟英曰：我肠最热，奈病来颇恶，治虽合法，势必转重。若初起不先觑破，早已殆矣。吾若畏难推诿，恐他手虽识其证，亦无如此大剂，车薪杯水，何益于事！吾且肩劳任怨，殚心尽力以图之。病果日重，昏瞀耳聋，自利红水，目赤妄言。孟英惟以晋三犀角地黄汤，加银花、石膏、知、斛、栀、贝、花粉、兰草、菖蒲、元参、竹沥、竹茹、竹叶、凫花、海䖳等出入互用。至十余剂，舌上忽布秽浊垢苔，口气喷出，臭难向迩，手冷如冰，头面自汗，咸谓绝望矣。孟英曰：生机也。彼阴虚，热邪深入，予一以清营凉血之法，服已逾旬，始得营阴渐振，推邪外出，乃现此苔。惟本元素弱，不能战解，故显肢冷，而汗仅出于头面，非阳虚欲脱也。复与甘寒频灌。越三日，汗收热退，苔化肢温。自始迄终，犀角共服三两许，未犯一毫相悖之药。且赖陈七恪诚，始克起九死于一生。继以滋阴善后而康。（眉批：三江地气卑湿，天时温暖，伤寒之证绝少，最多湿温、风温之证。又人体质柔脆，不任荡涤之药，故惟以甘寒清解之剂，渐次搜剔，斯邪去而正不伤。若在北方，刚坚之体，此等药虽服百剂，亦若罔知，非加硝、黄荡涤，邪终不去。故叶氏之法，擅誉江浙；而吴氏之方，驰名幽冀。易地则皆然，亦智者之因地制宜也。）", "14307": "沈东屏年逾八秩，患腹胀便秘。孟英诊曰：耄年脉实，天畀独厚，证属阳结，法宜清火。与西洋参、石膏、白芍、知母、花粉、桑皮、杏仁、橘皮、枳壳、甘草，送更衣丸。四剂而愈。设投别药，势必迁延而败。人亦谓天年之得尽，断不料其药治之误也。后四年始殁。夏间，汪湘筠明府，因食肉病胀，医谓老年气弱火衰，辄投温补，直至腹如抱瓮，始延孟英视之，弥留己极，不可救药矣！", "14308": "顾石甫宰娄县患恙，医治日剧，解任归，求诊于孟英。脉见左寸如钩。曰：病不能夏矣！许子双适至，闻而疑之，谓此证气逆血溢，腹胀囊肿，宛似上年康康侯之疾，若以外象观之，似较轻焉，胡彼可愈，而此勿治耶？孟英曰：彼为邪气之壅塞，脉虽怪而搏指不挠，证实脉亦实也；此为真气之散漫，脉来瞥瞥如羹上肥，而左寸如钩，是心之真藏见矣。壅塞可以流通，散漫不能收拾，客邪草木能攻，神病刀圭莫济，证虽相似，病判天渊，纵有神丹，终无裨也。季春果殁。", "14309": "孙氏女，年将及笄，久患齿衄，多医莫疗。孟英诊曰：六脉缓滑，天癸将至耳。与丹参、生地、桃仁、牛膝、茯苓、白薇、滑石、茺蔚子。（亦治倒经之法。）一剂知，数日愈。寻即起汛，略无他患。", "14310": "锁某，弱冠吐血。杨医连进归脾汤，吐益甚。孟英视之，面有红光，脉形豁大，因问曰：足冷乎？探之果然。遂与六味地黄汤送饭丸肉桂心一钱，复杯而愈。（眉批：此虚火上炎之证，归脾中参、耆性皆上升，故吐益甚。易以引火归原之法，斯愈矣。）", "14311": "沈裕昆室，偶发脘痛，范某与逍遥法，痛颇止，而发热咽痛，邀顾听泉视之，知感温邪，与清散法。疼已而热不退。七日后，目闭鼻塞，耳聋肢搐，不言语，不饮食，顾疑证险，愿质之孟英。而沈之两郎，乃从王瘦石学，因请决于师，瘦石亦谓孟英识超，我当为汝致之。时已薄暮，乃飞刺追邀。比孟英往诊，见其外候如是，而左手诊毕即缩去，随以右手出之，遽曰：非神昏也。继挖牙关，察其苔色白滑，询知大解未行。曰：病是风温，然不逆传膻中，而顺传胃府，证可无恐。听泉学问胜我，知证有疑窦，而虚心下问，岂非胸襟过人处。但温邪传胃，世所常有，而此证如是骇人者，因素有痰饮，盘踞胃中，外邪入之，得以凭借，苔色之不形黄燥者，亦此故耳，不可误认为寒。夫温为热邪，脉象既形弦滑以数，但令痰饮一降，苔必转黄，此殆云遮雾隐之时，须具温太真燃犀之照，庶不为病所欺。且昔人于温证仅言逆传，不言顺传，后世遂执定伤寒在足经，温热在手经，不知经络贯串，岂容界限！喻氏谓伤寒亦传手经，但足经先受之耳。吾谓温热亦传足经，但手经先受之耳。一隅三反，既有其逆，岂无其顺？盖自肺之心包，病机渐进而内陷，故曰逆；自肺之胃府，病机欲出而下行，故曰顺。今邪虽顺传，欲出未能。所谓胃病，则九窍不和，与逆传神昏之犀角地黄汤证大相迳庭。郭云台云：胃实不和，投滚痰而非峻，可谓治斯疾之真诠。遂疏小陷胸合蠲饮六神汤，加枳、朴，以芦菔煮水煎药，和入竹沥一杯，送下礞石滚痰丸四钱。沈嫌药峻，似有难色。孟英曰：既患骇人之病，必服骇人之药，药不瞑眩，厥疾勿瘳，盖再质之瘦石、听泉乎？沈颔之。王、顾阅方，佥以为是。且云：如畏剂重，陆续徐投可也。翌日，孟英与听泉会诊，诊脉证不甚减，询知昨药分数次而服。孟英曰：是势分力缓之故也，今可释疑急进，病必转机。听泉深然之，病家亦胆壮矣。如法服下，黎明果解胶韧痰秽数升，各恙即减，略吐语言，稍啜稀粥，苔转黄燥。药改轻清，渐以向安。嗣与育阴柔肝而愈。", "14312": "朱氏妇，素畏药，虽极淡之品，服之即吐。近患晡寒夜热，寝汗咽干，咳嗽胁疼。月余后，渐至减餐经少，肌削神疲。始迓孟英诊之。左手弦而数，右部涩且弱，曰：既多悒郁，又善思虑，所谓病发心脾是也。而平昔畏药，岂可强药再戕其胃，诚大窘事。再四思维，以甘草、小麦、红枣、藕四味，（妙想可以益人神志。令其煮汤频饮勿辍。病者尝药大喜，径日夜服之。逾旬复诊，脉证大减。其家请更方。）孟英曰：毋庸。此本仲圣治藏燥之妙剂，吾以红枣易大枣，取其色赤补心，气香悦胃，加藕以舒郁怡情，合之甘、麦，并能益气养血，润燥缓急，虽若平淡无奇，而非恶劣损胃之比，不妨久任，胡可以果子药而忽之哉！恪守两月，病果霍然。", "14313": "江某，年三十余，忽两目发赤，牙龈肿痛，渐至狂妄，奔走骂人，不避亲长，其父皇皇，求孟英诊焉。脉大而数，重按虚散。与东洋参、熟地黄、辰砂、磁石、龙齿、菖蒲、枣仁、琥珀、肉桂、金箔、龙眼肉为剂，投匕即安，翼日能课徒矣。（眉批：昔余友彭香林患此证，医虽知其虚，而治不如法，竟以不起。今读此案，弥增惋叹！）", "14314": "金禄卿室，沈裕昆之女也。患温，顾听泉连进轻清凉解，而病不减。气逆无寐，咳吐黏痰，舌绛咽干，耳聋讝语，旬日外始延孟英诊焉。曰：体瘦，脉细数，尺中更乱，竟是阴气先伤，阳气独发，所谓伤寒偏死下虚人。譬之火患将临，既无池井，缸贮又空，纵竭心力，易能有济？再四研诘，乃知发热前一日，陡然带下如崩，是真液早经漏泄矣。否则，药治未讹，胡反燎原益炽？痉厥之变，不须旋踵。禄卿坚恳勉图。孟英以西洋参、生地、二冬、二至、元参、犀角、黄连、鸡子黄、知母为方，另用石斛、龟板、鳖甲各四两，左牡蛎一斤煮汤代水煎药。顾听泉又加阿胶。且云：我侪用此育阴镇阳，充液息风大剂，焉能津枯风动，痉厥陡生乎？服两剂果不能减。后惑旁言而祷签药，附、桂、干姜，罔知顾忌，径至四肢拘挛而逝。是误药速其毙，而增其惨也。继而，裕昆患湿温，亦犯重暍而亡。", "14315": "一妪，患右腰痛胀欲捶，多药不效。孟英视其形虽羸瘦，而脉滑痰多，苔黄舌绛。曰：体虚病实，温补非宜。苟不攻去其疾，徒以疲药因循，则病益实，体益虚，糜帑劳师，养成寇患，岂治病之道哉？先以雪羹加竹茹、楝实、绿萼梅、杏仁、花粉、橘红、茯苓、旋覆花，送控涎丸，服后果下胶痰。三进而病若失，嗣与调补获痊。", "14316": "魏翎谷浼孟英视其郁甥之病。热逾半月，自胸次胀及少腹，痛而不可抚摩，便秘溺赤，舌黑口干，自汗烦躁，六脉弦强无胃。曰：此恙酷似伤寒大结胸证，结胸烦躁、无药可治，越二日便行而殁。孟英曰：伤寒之邪在表，误下则邪陷而成结胸，未经误下，不为结胸。湿热之邪在里，逆传于心包，而误汗则内闭以外脱；顺传于胃府，而误汗则盘踞而结胸。前人但云：误汗劫夺胃汁而未及于结胸者，因结胸证不多见耳。然亦不可不知也，故谨识之。郁病初起，某医用葛根一剂，继则胡某之柴、葛、羌、防十余剂，酿成是证。（眉批：温病忌误汗，不忌误下，以汗则津涸而热益炽，下则热势可借以少减也。）", "14317": "施氏妇，产后四肢串痛，药治罔效，医谓其成瘫痪矣。延已逾月，丐孟英视之。膏药遍贴，呻吟不息。脉数而洪，舌绛大渴。曰：此非风湿为病，膏药亟为揭去。近日服药，谅皆温补祛风之剂，营血耗伤，内风欲动，势将弄假成真。且吾向见其体丰血旺，何以娩后遽患斯疾？必生化汤、砂糖、酒之类所酿耳。其父倪某目虽瞽，闻而笑云：君诚天医也。小女服过生化汤二帖，赤沙糖八斤，从此渐病，不识尚可起废图全否？孟英曰：幸其体足于阴，恢复尚易，若阴虚血少之人，而蹈此辙，虽不即死，难免不成蓐损。因投大剂凉润壮水之药。一剂知，旬日安，匝月起。", "14318": "王士干室，素多郁怒，气聚于腹，上攻脘痛，旋发旋安。花甲外病益甚，医治益剧。李西园荐孟英视之。曰：此非人间之药所能疗矣。辞不与方。其夫、子及婿环乞手援。孟英曰：既尔，吾当尽力以冀延可也。然腹中聚气为瘕，攻痛呕吐，原属于肝。第病已三十载，从前服药，谅不外乎温补一途。如近服逍遥散最劫肝阴，理中汤极伤胃液，（用古方不可不知此意。）名虽疗疾，实则助桀。人但知呕吐为寒，而未识风阳内煽，水自沸腾。专于炉内添薪，津液渐形涸竭。奈医者犹云水已不吐，病似渐轻，是不察其水已吐尽，仅能哕逆空呕，所以不能纳谷。便秘不行，脉弦无胃，舌痿难伸，蕴隆虫虫，何所措手！可谓女人亦有孤阳之病矣。勉以西洋参、肉苁蓉、麦冬、葳蕤、生白芍、石斛、竹茹、柏子霜、紫石英为方，猪肉煮汤煎药，和入青蔗浆、人乳。服后呕哕皆止，人以为转机。孟英曰：譬草木干枯已久，骤加灌溉，枝叶似转青葱，奈根荄槁矣，生气不存，亦何益耶！继而，糜粥渐进，颇思肉味，其家更喜以为有望。孟英曰：且看解后何如？越数日，大便颇畅，殊若相安，亟迓复诊。孟英曰：枉费苦心矣。脉不柔和，舌不润泽，（审病者宜识此二语。）虽谷进便行，而生津化液之源已绝，药石焉能于无中生有哉！夏至后果殒。", "14319": "酷暑之际，疟疾甚行，有储丽波患此。陆某泥今岁寒水司天，湿土在泉，中运又从湿化，是以多疟，率投平胃、理中之法，渐至危殆。伊表兄徐和圃荐孟英视之。热炽神昏，胸高气逆，苔若姜黄，溺如赫赤，脉伏口渴，不食不便。曰：舍现病之暑热，拘司气而论治，谓之执死书以困治人，幸其体丰阴足，尚可救药，然非白虎汤十剂不能愈也。和圃然之。遂以生石膏、知母、银花、枳、贝、黄连、木通、花粉、茹、芩、杏、斛、海䖳、竹叶等，相迭为方。服旬日，疟果断。", "14320": "外甥庄迪卿，患疟，大渴而喜热饮，脘闷脉伏，苔腻欲呕。孟英曰：蕴湿内盛，暑热外侵，法当清解，然脉证如是，乃痰阻气道使然，清之无益，温之助桀，宜以礞石滚痰丸先为开导。服后痰出甚多，脉即见弦滑而数，呕止胸舒，苔形黄燥。与石膏、知母、连、朴、杏、橘、半、茯、滑、斛、菖蒲、花粉等而安。（眉批：论证论治，俱极明透。）", "14321": "庄晓村，芝阶姊夫之侄孙也。馆于金愿谷舍人家，病疟。孟英曰：吸受暑热，清涤即瘳。阅数日，疟作甚剧，目赤狂言，汗如雨下。居停大惊，闻服凉剂，疑为药误。亟速孟英至，正在披狂莫制之时。按其脉洪滑无伦，视其舌深黄厚燥，心疑其另服他药之故，而扑鼻吹来一阵姜枣气。因诘曰：得无服姜枣汤乎？曰：恣饮三日矣。孟英即令取西瓜一枚，（解暑妙品。）劈开，任病者食之，方从白虎，而生石膏用一两六钱，病即霍然。逾六年以他疾亡。继有陈仰山如君患疟，孟英连与清暑法，病不少减。孟英疑亦姜枣汤所致，询知果然，亟令屏绝，遂愈。余如汪子宽、魏云裳、胡秋纫等暑疟治案，皆以白虎化裁，案多不备载，录此以备读者之隅反焉。", "14322": "潘红茶方伯之孙翼廷，馆于许双南家。酷热之时，啜冷石花一碗，遂致心下痞闷，四肢渐冷，而上过肘膝，脉伏自汗。方某诊谓：阳虚阴暑，脱陷在即。疏大剂姜、附、丁、桂以回阳。双南在苏，其三郎杏书骇难主药，邀族人许芷卿诊而决之。芷卿云：此药断不可投。第证极危急，须逆孟英商之。时夜已半，孟英往视。曰：既受暑热，复为冷饮冰伏胸中，大气不能转旋，是以肢冷脉伏，二便不行。速取六一散一两，以淡盐汤搅之，澄去滓，调下紫雪丹一钱。（藉辛香以通冰伏之气，用意精妙。）翼日再诊，脉见胸舒，溺行肢热，口干舌绛，暑象毕呈，化而为疟。与多剂白虎汤而愈，丙午举于乡。（眉批：认证既确，治法又极精妙，真可谓万世法程。）", "14323": "何永昌者，孟英之舆人也。其妻病疟，间二日而作，乃母曰：疟不可服官料药。径服签方，旬日后势甚危，永昌乞孟英救之。脉沉细而数，尺为甚，口渴目不欲张，两腰收痛，宛如锥刺，寒少热多，心慌不能把握。曰：异哉病也！此暑入足少阴之证。（卓识。）喻氏所谓汗、下、温三法皆不可行者。若病在别家，虑其未必我信，病在汝而求诊于我，事非偶然也。汝母云：官料药不可治疟，此语出于何书？而药别官私，何人所创？既官料之勿服，则私料更不可妄试矣！殊属可嗤！然是证若延医诊，非表散即温补，不可谓非汝母之一得也。疏方：元参八钱，龟板、石斛各一两，地骨皮六钱，知母五钱，桑叶、金银花各四钱，花粉三钱，丹皮二钱。令用大砂锅煎而频服，不必限剂。服三日疟断而各恙皆减，粥食渐进，不劳余药而起。（眉批：暑邪入肾，必伤肾液，故重用滋阴之品以救之。）", "14324": "慎氏妇，产后腹胀泄泻，面浮足肿。医与渗湿温补，月余不效，疑为蓐损。孟英视之，舌色如常，小溲通畅，宛似气虚之证。惟脉至梗涩，毫无微弱之形。因与丹参、滑石、泽兰、茯苓、茺蔚、蛤壳、桃仁、海䖳、五灵脂、豆卷。（亦行瘀利水之法。数服即瘥。）", "14325": "汪子与病革，始延孟英视之。曰：阴虚之质，暑热胶锢，殆误投补药矣。乃叔少洪云：侄素孱弱，医投熟地等药十余剂耳。孟英曰：暑热证必看邪到血分，始可议用生地，何初病即进熟地？岂仅知禀赋之虚，未睹外来之疾耶？昔贤治暑，但申表散温补之戒，讵料今人于律外，更犯滋腻之辜，而一误至此，略无悔悟，不啻如油入面、如漆投胶，将何法以挽回哉！越日果卒。夫小米舍人，仅此一脉，完姻未久，遽尔珠沉，殊为惨然。冬间吴忻山亦惟一子，素禀虚怯，滋补颇投，医者不察其患温发热，佥谓阴虚，竞投滞腻培元之剂，乃至舌黑卷短，唇焦溺赤。孟英一诊即云不救。顾听泉竭力图维，终不能愈。按虚人受感，每蹈此辙，特录以为戒。", "14326": "汪左泉病滞下，昼夜数十行。而即日须补岁考遗才，浼孟英商速愈之策。切脉弦滑，苔黄满布。曰：易事耳。重用芩、连，佐以楂、朴，送服青麟丸四钱，投匕而痊。略无他恙。", "14327": "陈昼三病滞下，某进通因通用法，痛泄无度，呕恶不纳，汗出息微，脉弱眩晕。孟英曰：近多伏暑之痢，此独非其证也，元将脱矣。急投大剂温补，脉候渐安。一月后甫得健复。", "14328": "金朗然之母，偶发脘疼呕吐，医与温补药，初若相安，渐至畏寒不寐，四肢不仁，更医云是风痹，仍投温补，因而不饥不食，二便不行，肌肉尽削，带下如溺，始延孟英诊之。曰：暑伏肺胃耳。其多投温补而不遽变者，以熟地等阴柔腻滞为之挟制也。然津气灼烁而殆尽，脂液奔迫以妄行，治节无权，阳明涸竭，焉能卫皮毛而畅四肢，利机关以和九窍哉！与白虎汤加西洋参、竹茹、橘皮、丝瓜络、石斛、花粉、竹沥、海䖳。连进二十剂，始解黑矢而各恙渐安。嗣与和肝胃、调八脉以善后遂愈。（眉批：汪子与证，误服熟地而不救，此证误服温补兼熟地而竟愈，盖体有虚实，治有迟早，邪有重轻，未可以一端拘耳。）", "14329": "乔有南之侄甫五龄，发热数日，儿医与柴葛解肌汤一剂，肢搐而厥，目张不语。其母孀居，仅此一脉，遍求治疗，毫无寸效。所亲徐和甫托王瘦石访一擅幼科之长者，瘦石谓宜求善于外感者。盖人有大小，病无二致，切勿舍大方而信专科，此喻嘉言活幼金针也。盍延孟英视之？徐从之。孟英曰：病是暑邪，治以风药，热得风而焰烈，津受烁以风腾，乃风药引起肝风，再投俗尚惊风之剂，稚子根本不牢，而狂风不息，折拔堪虞。与王氏犀角地黄汤加羚羊角、生石膏、元参、桑叶、菊花、银花、牡蛎、知母、麦冬、竹叶诸药。数服而痊。（眉批：清暑热，熄肝风，方极平允。）", "14330": "赵铁珊乃郎子善，康廉侯之婿也。因事抑郁，凛寒发热。汤某作血虚治，进以归、芎、丹参之类，多剂不效，乃移榻康寓，延孟英诊之。脉涩而兼沉弦以数，然舌无苔，口不渴，便溺如常，纳谷稍减，惟左胁下及少腹，自觉梗塞不舒，按之亦无形迹，时欲抚摩，似乎稍适。曰：阴虚挟郁，暑邪内伏。夫郁则气机不宣，伏邪无从走泄，遽投血药，引之深入，血为邪踞，更不流行，胁腹不舒，乃其真谛。第病虽在血，而治宜清气为先，气得宣布，热象必露，瘀滞得行，厥疾始瘳。子善因目击去年妇翁之恙，颇极钦服。连投清气，热果渐壮，谵妄不眠，口干痰嗽。孟英曰：脉已转为弦滑，瘀血伏邪，皆有欲出之机，继此当用凉血清瘀为治，但恐旁观诧异，事反掣肘，嘱邀顾听泉质之。顾亦云然。遂同定犀角地黄汤加味。而所亲陈眉生、许小琴暨乃兄子勉，皆疑药凉剂重，纵是热证，岂无冰伏之虞？顾为之再四开导，总不领解。适病者鼻衄大流，孟英笑曰：真赃获矣，诸公之疑，可否冰释？渠舅氏陈谷人鹾尹云：证有疑似，原难主药，鼻血如是，病情已露，毋庸再议。径煎药而饮之。次日，衄复至，苔色转黑。孟英曰：三日不大便，瘀热未能下行也。于前方加滑石、桃仁、木通、海䖳、竹沥、石斛、银花、知母、花粉之类。又二剂大解始行，黑如胶漆，三日间共下七十余次而止。乃去木通、桃仁辈，加西洋参、麦冬以生液。病者疲惫已极，沉寐三昼夜，人皆危之。孟英曰：听之，使其阴气之来复，最是好机。醒后尚有微热讝语，药仍前法。又旬日，始解一次黑燥大便，而各恙悉返。惟口尚渴，与大剂甘凉以濡之。又旬日，大解甫得复行，色始不黑，乃用滋阴填补而康。（眉批：此证不遇孟英必成虚损，讫无知其为伏暑者，虽死亦不知前药之误也。）", "14331": "高若舟之庶母，年逾花甲，体丰善泻。张某向用参、术取效。今秋患白痢，张谓寒湿滞中，仍与理中加减，病遂日增，因疑老年火衰，蒸变无权，前药中复加附子，白痢果减，而腹胀且疼，不食不溺，哕逆发热，势已危殆，始迓孟英视之。脉沉而滑数梗梗。曰：暑热未清，得无补药早投乎？与芩、连、杏、朴、曲、芍、滑、楝、银花、海䖳、鸡内金之类。一剂溺行痛减，而痢下仍白。其女为屠西园之室，乃云：向服补药，白痢已止，今服凉药，白痢复作，盖病本久寒，凉药不可再用矣。孟英曰：言颇近理，使他医闻之，必改温补，但病机隐伏，测识匪易，前此之止，非邪净而止之止，乃邪得补而不行之止，邪气止而不行，是以痛胀欲死。夫强止其痢，遽截其疟，犹之乎新产后妄涩其恶露也。世人但知恶露之宜通，而不知间有不可妄通者；但知疟痢之当止，而不知邪未去而强止之，其害较不止为尤甚也！今邪未清涤，而以温补药壅塞其流行之道，以致邪不能出，逆而上冲，哕不能食，是痢证之所畏。吾以通降凉润之剂，搜邪扫浊，惟恐其去之不速，胡反以白痢复作为忧，岂欲留此垢滞于腹中，冀其化脂膏而填空隙，故若是之宝惜而不愿其去耶？（眉批：通达之论，医所宜知。）幸若舟深信，竟从孟英议。寻愈。", "14332": "十八涧徐有堂室病痢，医作寒湿治，广服温补之药。痢出觉冷，遂谓沉寒，改投燥热。半月后，发热无溺，口渴不饥，腹疼且胀，巅痛不眠。翁嘉顺嘱其求诊于孟英。察脉弦细，沉取甚数，舌绛无津，肌肉尽削，是暑热胶锢，阴气受烁。与北沙参、肉苁蓉、芩、斛、楝、芍、银花、桑叶、丹皮、阿胶，合白头翁汤为剂。次日，各患皆减，痢出反热。有堂不解问故？孟英曰：热证误投热药，热结而大便不行者有之；或热势奔迫，而泄泻如火者有之；若误服热药，而痢出反冷者，殊不多见也，无怪医者指为久伏之沉寒。吾以脉证参之，显为暑热。然暑热之邪，本无形质，其为滞下也，必挟身中有形之垢浊。故治之之道，最忌补涩壅滞之品。设误用之，则邪得补而愈炽，浊被壅而愈塞，耗其真液之灌溉，阻其正气之流行。液耗则出艰，气阻则觉冷。大凡有形之邪，皆能阻气机之周流，如痰盛于中，胸头觉冷，积滞于府，脐下欲熨之类，皆非真冷，人不易识，吾曾治愈多人矣。徐极叹服，仍议育阴涤热，病果渐瘳。", "14333": "萧某素患痰多，常服六君子汤，偶延孟英诊之。脉细数而兼弦滑。曰：六君亟当屏绝，病由阴亏火盛，津液受灼而成痰，须服壮水之剂，庶可杜患将来。萧因向吸鸦片烟，自疑虚寒，滋阴不敢频服。继患咽痛，专科治而不效，仍乞诊于孟英。因谓曰：早从吾策，奚至是耶！此阴虚于下，阳浮于上，喉科药不可试也。大剂育阴潜阳，其痛日瘥，而喉腭皆形白腐。孟英曰：吸烟既久，毒气薰蒸之故耳。令吹锡类散，始得渐退。愈后复患滞下。孟英曰：今秋痢虽盛行，而此独异于人，切勿以痢药治之。盖火迫津液，结为痰饮，酿以烟毒，薰成喉患。吾以燃犀之照，而投激浊扬清之治，病虽愈矣，内蕴之痰浊尚多，奈向来为温补药所禁，锢于肠胃曲折之间，而不得出，今广投壮水之剂，不啻决江河而涤陈莝，岂可与时行暑热之痢同年而语耶！治不易法，食不减餐，日数十行，精神反加。逾月之后，大解始正。计服甘凉约二百剂，肌肉复充，痰患若失。", "14334": "顾宗武偶患微寒发热，医进温散法，热虽退，而不饥不大便。复用平胃散数帖，腹渐胀而偏于右，尚疑其中气之虚寒也，遂与温运燥补诸药，胀乃日增，杳不进谷。或谓恐属痈疡，因招外科连某诊之，作胁疽治，病如故。黄某作肠痈论，以大黄泻之，亦不应。严某谓胁疽部位不对，肠痈证据不符，作内疝治，仿子和活人之法，及当归龙荟丸相间而投，亦无效，（眉批：杂药乱投，一何可笑。）乃延孟英视之。脉极弦细而促，舌绛大渴，小溲赤少，饮而不食者月余矣，证实脉虚，坚辞不治。其家问曰：此证究是何病？乞为指示。孟英曰：据述病人素慎起居，而薄滋味，显非停滞与痈疽之患，良由暑湿内蕴，势欲外泄，是以初起有微寒发热之候。误与风寒药，热虽暂退于表，邪仍伏处乎中，不饥不便，肺胃失其下行，再加辛燥温补，气机更形窒滞，伏邪永无出路。津液潜消，䐜胀日甚，以气血流行之藏府，为暑湿割据之窠巢，补之不可，攻之不能，病虽不在膏肓，卢扁望而惊走。逾旬径殁。", "14335": "黄莲泉家戚妪病痢，朱某以其年老，而为舍病顾虚之治，渐至少腹结块，攻痛异常，大渴无溺，杳不知饥，昼夜百余行，五色并见，呼号欲绝，始延孟英诊之。脉至沉滑而数，因谓曰：纵使暑热深受，见证奚至是耶？此必温补所酿耳！夫痢疾古称滞下，明指欲下而涩滞不通也，顾名思义，岂可以守补之品，更滞其气？燥烈之药，再助其虐乎？少腹聚气如瘕，痢证初起，因于停滞者有之，今见于七八日之后，时欲冲逆，按之不硬，则显非停滞之可拟，实为药剂之误投，以致邪浊蟠踞，滋蔓难图。及检所服诸方，果是参、术、姜、萸、附、桂、粟壳、故纸、川椒、乌梅等一派与病刺谬之药。孟英曰：彼岂仇于汝哉？畏老而补之，见痢而止之，亦未尝不煞费苦心，而欲汝病之即愈，惜徒有欲愈之心，未明致愈之道，但知年老元虚，不闻邪盛则实，彼亦年近古稀，悬壶多载，竟毕世沉迷于立斋、景岳诸书，良可叹也！岂造化果假权于若辈乎？不然何彼书、彼术之风行哉！戚云：壬寅之病，赖君再生，今乃一误至此，恐仙丹不能救矣。孟英曰：幸未呕哕，尚可希冀一二。遂与苁蓉、楝、芍、芩、连、橘、斛、楂、曲、元胡、绿梅、鳖甲、鸡金、鼠矢、海䖳，出入互用，数帖渐安。继加驻车丸吞服，逾月始健。（眉批：痢疾初起即补，变成噤口者有之，延为休息者有之，邪因补而固结不解，虽有明手，无如之何，良可叹恨。）", "14336": "周某患疟，间二日而作，寒少热多。医谓老年三疟，放手温补，渐至杳不进谷。所亲李石泉孝廉嘱迎孟英诊之，脉细硬如弦，毫无胃气，右尺洪数，舌色光绛，大渴溺滴。曰：此足少阴暑疟也，广服温补，津液尽劫，欲以草木生之，事不及矣。世但知治疟不善有三患：邪留肝络则为疟母；戕及脾元则为疟鼓；耗乎肾阴则为疟劳。而此证以药助邪，邪将劫命，求转三患，亦不能得。所谓热得补而更炽，阴受烁以速亡，阴愈亡则邪愈炽，何殊炮烙之刑，病者何辜？可惨！可惨！逾日果殁。特录以为戒，医者鉴之。", "14337": "上虞陈茂才，患头痛，三日一发，发则恶寒，多药不效，饮食渐减。或拟大剂姜、附，或议须投金石。葛仲信嘱其质于孟英。察脉甚弦，重按则滑。曰：热暑伏厥阴也。温补皆为戈戟，与左金加楝、芍、栀、桑、羚、丹、菊、橘为剂，煎吞当归龙荟丸。三服而减，旬日即痊。", "14338": "余某年三十余，发热数日，医投凉解之法，遂呕吐自汗，肢冷神疲。亟延孟英诊之。脉微弱。曰：内伤也，岂可视同伏暑，而一概治之，径不详辨其证耶！与黄耆建中去饴，加龙骨、生姜、茯苓、橘皮，投剂即安。续加参、术，逾旬而愈。", "14339": "钱氏妇，怀妊四月，而患寒热如疟。医与发散安胎，乃至舌黑神昏，大渴便泄，臭痰频吐，腰腹痛坠，人皆不能措手。孟英诊曰：伏暑失于清解，舌虽黑而脉形滑数，痰虽臭而气息调和，是胎尚未坏，犹可治也。重用气血两清之药，五剂而安，糜粥渐进，腰腹皆舒，胎亦跃跃。", "14340": "方氏女，久患泄泻脘痛，间兼齿痛，汛事不调，极其畏热，治不能愈。上年初夏，所亲崔映溪为延孟英诊之。体丰脉不甚显，而隐隐然弦且滑焉。曰：此肝强痰盛耳。然病根深锢，不可再行妄补。渠母曰：溏泄十余年，本元虚极，广服培补，尚无寸效，再攻其病，岂不可虞？孟英曰：非然也。今之医者，每以漫无著落之虚字，括尽天下一切之病，动手辄补，举国如狂，目击心伤，可胜浩叹！且所谓虚者，不外乎阴与阳也。今肌肉不瘦，冬不知寒，是阴虚乎？抑阳虚乎？只因久泻，遂不察其脉证，而佥疑为虚寒之病矣。须知痰之为病，最顽且幻，益以风阳，性尤善变，治必先去其病，而后补其虚不为晚也。（眉批：凡病皆宜如此，不独痰饮为然。）否则，养痈为患，不但徒费参药耳。母不之信，遍访医疗，千方一律，无非补药。至今秋颈下起一痰核，黄某敷之始平。更以大剂温补，连投百日，忽吐泻胶痰斗余而亡。予按：此痰饮滋蔓，木土相仇，久则我不敌彼，而溃败决裂，设早从孟英之言，断不遽死于今日也。", "14341": "鲍继仲患哮，每发于冬，医作虚寒治更剧。孟英诊之：脉滑苔厚，溺赤痰浓。与知母、花粉、冬瓜子、杏、贝、茯苓、滑石、栀子、石斛而安。孙渭川令侄亦患此，气逆欲死。孟英视之：口渴头汗，二便不行。径与生石膏、橘、贝、桂、苓、知母、花粉、杏、菀、海䖳等药而愈。一耳姓回妇病哮，自以为寒，频饮烧酒，不但病加，更兼呕吐泄泻，两脚筋掣，既不能卧，又不能坐。孟英诊曰：口苦而渴乎？泻出如火乎？小溲不行乎？痰黏且韧乎？病者云：诚如君言，想受寒太重使然。孟英曰：汝何愚耶！见证如是，犹谓受寒，设遇他医，必然承教，况当此小寒之候，而哮喘与霍乱，世俗无不硬指为寒者，误投姜、附，汝命休矣！与北沙参、生薏苡、冬瓜子、丝瓜络、竹茹、石斛、枇杷叶、贝母、知母、栀子、芦根、橄榄、海䖳、芦菔汁为方，一剂知，二剂已。（眉批：哮证乃热痰伏于肺络也。至冬则热为寒束，故应时而发。古人治法，于未寒时，先以滚痰丸下之，使冬时无热可束则愈。但其法太峻，人多不敢用。今孟英以轻清通透之品，搜络中之伏痰，斯有利而无弊，真可补古人所未及。）", "14342": "吴芸阁因壮年时患霉疮，过服寒凉之药，疮虽愈，阳气伤残，虚寒病起，改投温补，如金液丹、大造丸之类，始得获安。奈医者昧于药为补偏救弊而设，漫无节制，率以为常，驯致血溢于上，便泄于下，食少痰多，喘逆碍卧，两足不能屈伸。童某犹云寒湿为患，进以苓姜术桂汤多剂，势益剧，且溲渐少，而色绿如胆汁，医皆不能明其故。延孟英诊之，脉弦硬无情。曰：从前寒药戕阳，今则热药竭阴矣。胃中津液，皆灼烁以为痰，五藏咸失所养，而见证如上，水源欲绝，小溲自然渐少，木火内焚，乃露东方之色，与章虚谷所治暑结厥阴，用来复丹攻其邪从溺出，而见深碧之色者，彼实此虚，判分天壤，恐和缓再来，亦难为力矣！寻果殁。", "14343": "戴氏妇，年五十六岁，仲冬患感，初服杨某归、柴、丹参药一剂，继服朱某干姜、苍术、厚朴药五剂，遂崩血一阵。谓其热入血室，不可治矣。（眉批：即热入血室，亦岂不可治之证？）可见此人并不知热入血室为何病，第妄指其名耳！始延孟英诊之。脉形空软促数，苔黑舌绛，足冷而强，息微善笑，询其汛断逾十载。曰：冬温失于清解，营血暴脱于下，岂可与热入血室同年而语耶！必由误服热药所致，因检所服各方而叹曰：小柴胡汤与冬温何涉？即以伤寒论，亦不能初感即投，况以丹参代人参，尤为悖谬。夫人参补气，丹参行血，主治天渊，不论风寒暑湿各气初感，皆禁用血药，为其早用反致引邪深入也。既引而入，再误于辛热燥烈之数投，焉得不将其仅存无几之血，逼迫而使之尽脱于下乎？女人以血为主，天癸既绝，无病者尚不宜有所漏泄，况温邪方炽，而阴从下脱，可不畏哉！病家再四求治。孟英与西洋参、苁蓉、生地、犀角、石斛、生芍、银花、知母、麦冬、甘草、蔗浆、童溺。两剂足温舌润，得解酱粪，脉数渐减而软益甚，乃去犀角，加高丽参。数帖脉渐和，热退进粥，随以调补，幸得向安。", "14344": "王开荣素患痰嗽，兼有红证。今冬病头疼发热，渴饮不饥，便溏溺少，谵语神昏，自述胸中冷气上冲。医见其面赤痰喘，欲投附、桂、黑锡丹等药。所亲翁嘉顺嘱勿轻服，为延孟英诊之。脉滑且数。曰：温邪挟宿饮上逆，法当清解。与北沙参、冬瓜子、知母、滑石、花粉、石菖蒲、贝母、杏仁、芦根、葱白、淡豉、竹沥。二剂后面赤退，乃去葱、豉。加麦冬、桑叶、枇杷叶。数帖热去泻减，谵语止，头痛息，喘定神清。乃裁菖、滑，加梨汁、地栗、海䖳。服数日，痰渐少，谷渐安，渴止溺行，始进养阴法，遂以霍然。（眉批：此人肺气素不清肃，又兼阴虚挟饮，故感受温邪，弥见𫐖轕，非此始终如法施治，殊难奏效也。）", "14345": "石子章患腹胀，朱某与大剂温补之药，殊若相安，孟英见而非之。彼云：服之略不助胀，正须多服图痊，君何疑焉？孟英曰：形瘦脉数，舌色乾红，此为阴虚热胀，昔年范次侯室暨杨改之如君之恙，皆类此，医咸攻补遍施，病无小效。吾以极苦泄热、微辛通络之法投之，应手而瘳。今子病初起时胀不碍食，证非气分可知，而温补不助胀，遂服之不疑。不知阴愈耗，络愈痹，胀虽不加，而肌愈削，脉愈数，干呛气急，与女子之风消息贲何以异耶？寻果不起。予按：喻氏始言男子亦有血蛊证，可见男女虽别，而异中有同，同中有异，临证者不可胶柱以鼓瑟也。", "14346": "沈某患脘痛呕吐，二便秘涩，诸治不效，请孟英视之。脉弦软，苔黄腻。曰：此饮证也，岂沉湎于酒乎？沈云：素不饮酒，性嗜茶耳。然恐茶寒致病，向以武彝红叶，熬浓而饮，谅无害焉？孟英曰：茶虽凉而味清气降，性不停留，惟蒸遏为红，味变甘浊，全失肃清之气，遂为酿疾之媒，较彼曲糵，殆一间耳。医者不察，仅知呕吐为寒，姜、萸、沉、附，不特与病相反，抑且更煽风阳，饮藉风腾，但升不降，是以上不能纳，下不得通，宛似关格，然非阴枯阳结之候。以连、楝、栀、芩、旋覆、竹茹、枇杷叶、橘、半、苓、泽、蛤壳、荷茎、生姜衣为方，送服震灵丹。数剂而平，匝月而起。（眉批：此上有停饮，下元虚寒，故用药如此。）", "14347": "石芷卿，骤患腹胀，旬日后脐间出脓。（湿热积于小肠。）外科视为肠痈，与温补内托之药，（眉批：肠痈无温补内托之法。）遂咳嗽不眠，腹中绞痛异常，痰色红绿，大便不行，乃延孟英商之。脉弦细以数，舌绛而大渴，曰：察脉候是真阴大虚之证。（乃真阴为热药所耗，非本如是也。）耆、术、归、桂，皆为禁剂。以甘露饮加西洋参、花粉、贝母、杏仁、冬瓜子投之。痰咳即安。（眉批：清其上源而下流自清，亦喻氏法也。）外科谓此恙最忌泄泻，润药不宜多服，（此何恙也？而以为最忌泄泻，真呓语也。）孟英曰：阴虚液燥，津不易生，虽求其泻，不可得也，恶可拘泥一偏，而不知通变哉？仍以前法去杏、贝、花粉，加知母、百合、合欢为方。并嘱其另邀老医朱嵩年敷治其外。如法施之，果渐向安。久之当脐痂落，如小儿蜕脐带状，脐内新肉莹然而愈。", "14348": "沈春旸之母，偶患咽喉微痛，服轻清药一剂，即觉稍安，且起居劳作如常。第五日犹操针凿至四鼓，第六日忽云坐立不支，甫就榻，即昏沉如寐。亟延王瘦石视之，用犀角地黄汤，化万氏牛黄丸灌之；继邀徐小坡，亦主是汤，云恐无济。乃邀孟英决之。切其脉左数右滑，皆极虚软。曰：王、徐所见极是，但虽感冬温，邪尚轻微，因积劳久虚之体，肝阳内动，烁液成痰，逆升而厥，俨似温邪内陷之候。方中犀角靖内风，牛黄化痰热，不妨借用，病可无虞，今日不必再投药饵矣。翼日复诊，神气虽清，苔色将黑。孟英与肃肺蠲痰，息风充液之剂，热退而苔色松浮。孟英曰：舌将蜕矣。仍与前药，越宿视之，苔果尽退，宛如脱液之舌，且呕恶时作，大解未行。孟英于甘润生津药内，仍佐竹茹、竹沥、柿蒂、海䖳。数剂呕止便行，而舌上忽布白腐之苔，（此湿热熏蒸于肺也。）以及齿龈唇颊，满口遍生，揩拭不去，人皆异之。孟英坚守肃清肺胃，仍佐茹、沥，加橄榄、银花、建兰叶。数剂白腐渐以脱下，舌色始露，惟啜粥则胸次梗梗不舒，夜不成寐。孟英曰：胃汁不充，热痰未净也。仍守前议。病家疑之，复商于瘦石，瘦石云：勿论其他，即如满口腐苔，酷似小儿鹅白，大方证甚属罕见，苟胸无学识者见之，必按剑而诧，今医者有不惑之智，而病家乃中道生疑，岂求愈之道耶？沈大愧服，一遵孟英设法，既而吐痰渐少，纳谷颇适，两胁又添辣痛。孟英诊脉左关弦数，曰：必犯忿怒矣。诘之果然。加栀、楝、旱莲、女贞、生白芍、绿萼梅等。数服各恙皆安，肤蜕成片，而右腿肿痛不能屈伸，或疑风气，思用艾灸，孟英急止之曰：此阴亏耳，误灸必成废疾，吾以妙药奉赠，但不许速效也。疏方以西洋参、熟地黄、苁蓉、桑椹、石斛、木瓜、归、芍、二冬、杞、菊、楝实、牛膝，加无核白蒲桃子为剂，久服果得向愈。越三载以他疾终。", "14349": "孙执中于春前四日，忽患鼻衄如注，诸法莫塞。夤夜请孟英视之。脉弦而数。曰：冬暖气泄，天令不主闭藏，今晚雷声大振，人身应之，肝阳乃动，血亦随而上溢，不可以其体肥头汗，畏虚脱而进温补也。投以元参、生地、犀角、牡蛎、知母、生白芍、牛膝、茯苓、侧柏叶、童溺诸药。一剂知，二剂已。既而胁痛流乳，人皆异之。孟英与甘露饮加女贞、旱莲、龟板、鳖甲、牡蛎而瘳。", "14350": "庄芝阶舍人之外孙汪震官，春前陡患赤痢。孟英诊之，脉滑数而沉，面赤苔黄，手足冷过肘膝，当脐硬痛，小溲涩少，伏热为病也。与大剂芩、连、栀、楝、滑石、丹皮、砂仁、延胡、楂、曲、银花、草决明等药。（此大实证也，何不加大黄荡涤之。）两服手足渐温，（清热之效。）而脚背红肿起疱如蒲桃大一二十枚。（湿热下注也。若于前方加大黄荡涤，当不至此。）四服后腹痛减，苔退而渴，于原方去楂、曲、砂仁，加白头翁、赤芍、海䖳。旬日后，痢色转白，而腿筋抽痛。乃去丹皮、滑石、赤芍，加鸡金、橘红、生苡、石斛。（热久伤阴也，古人急下存阴之法，原以防此，救法好。）两服痛止溲长，粪色亦正，脚疱溃黄水而平，谷食遂安。改用养胃阴清余热之法而愈。（合法。）闻孟英治此证，每剂银花辄两许，尚须半月而瘳，设病在他家，焉能如此恪信。苟遇别手，断无如此重剂，况在冬春之交，诚古所未有之痢案，后人恐难企及。（眉批：此案步步合法，特少一番荡涤之功，故觉少延时日耳。然凉剂已畏其寒，若加荡涤之品，必不敢服，此治病之所以难也。）", "14351": "郑妪患咳嗽，自觉痰从腰下而起，吐出甚冷。医作肾虚水泛治，渐至咽喉阻塞，饮食碍进，即勉强咽之，而胸次梗不能下，便溏溲频，无一人不从虚论。孟英诊曰：脉虽不甚有力，右部微有弦滑，苔色黄腻，岂属虚证？以苇茎汤含雪羹，加贝母、知母、花粉、竹茹、麦冬、枇杷叶、柿蒂等药，进十余剂而痊。（眉批：此证明明虚寒，何以作虚寒治不效？）盖虚寒乃此人之本体，而痰咳乃新受之外邪，不治其邪，而专补其虚，则邪无出路，以致积补生热，此舌苔之所以黄腻也。孟英以清热化痰为治，尚是一半治病，一半治药误也。", "14352": "满洲少妇，怀娠漏血，医投补药漏如故。间或不漏则吐血，延逾二载，腹中渐动，孕已无疑，然血久溢于上下，甚至纳食即吐，多医不能治。孟英诊之，脉滑数有力，是气实而血热也，证不属虚，补药反能助病，愈补愈漏。胎无血荫而不长，其所以不堕者，气分坚实耳。与大剂清营药，血溢遂止，而稀沫频吐，得饮即呕，口渴心忡，气短似促。乃用西洋参、麦冬、知母、石斛、枇杷叶、竹茹、柿蒂、生白芍、木瓜，重加乌梅投之，（清肺柔肝、益气生津，与证针锋相对。）复杯即安，次日能吃饭矣。", "14353": "一男子患便血，医投温补，血虽止而反泄泻浮肿，延及半年。孟英诊之，脉数舌绛，曰：此病原湿热，温补反伤阴液。与芩、连、栀、芍、桑叶、丹皮、银花、石斛、楝实、冬瓜皮、鳖甲、鸡金等药，旬余而愈。", "14354": "陆厚甫室，陈芷浔主事之女也。产后经旬，偶发脘痛，专用与温补药。（脘痛何以投温补，不问可知其误矣。）因寒热气逆，自汗不寐，登圊不能解，而卧则稀水自流，口渴善呕，杳不纳谷，佥云不起矣。乃父速孟英诊之，脉弦数而滑，曰：本属阴亏，肝阳侮胃，误投温补涩滞之剂，（产后肝血大亏，所以阴虚，肝失血养，故阳独盛。）气机全不下降，以致诸证蜂起，医者见而却走，是未明其故也。与沙参、竹茹、楝实、延胡、栀、连、橘、贝、杏、斛、枇杷叶。为肃肺以和肝胃法，复杯即安。但少腹隐隐作痛，于前方去杏、贝、竹茹，加知母、花粉、苁蓉、白芍、橘核、海䖳。乃解宿垢而瘳。（此脘痛之根。）", "14355": "周子朝患恶寒头痛发热，酷似伤寒，而兼心下疼胀。孟英脉之，右部沉滑，苔黄不渴，溲如苏木汁。先以葱豉汤加栀、连、杏、贝、蒌、橘为方。（先解表。）服后微汗，而不恶寒反恶热，虽汤饮略温，即气逆欲死。孟英曰：客邪解矣，清其痰热可也。与知母、花粉、杏、贝、旋、滑、斛、橘、杷、茹、茅根、芦根、地栗、海䖳等药。（后清里。）果吐胶痰甚多，而纳食渐复，惟动则欲喘，于肃上之中佐以滋下，为善其后而瘥。", "14356": "胡振华以花甲之年，患溺后出血水甚痛，自云溲颇长激，似非火证。孟英察脉有滑数之象。与元参、生地、犀角、栀、楝、槐蕊、侧柏、知母、花粉、石斛、银花、甘草梢、绿豆等药，旬日而痊。逾四载以他疾终。", "14357": "管氏妇，自去秋患赤痢，多医罔效，延至暮春。孟英诊脉弦数，苔黄渴饮，腹胀而坠，五热夜甚。用白头翁汤合金铃子散加芩、芍、栀、斛，吞驻车丸。浃旬而愈。", "14358": "濮树堂室病，孟英甫为参愈，而树堂继焉。起即四肢厥逆，脉伏恶寒，发热头痛，左为甚，惟口渴。因与葱豉二帖。（解表。）热虽退，脉仍伏，四肢冷过肘膝，大解频行，人皆疑为虚寒。孟英曰：此证俨似阴厥，然渴饮溲赤，真情已露，岂可泥于一起即厥，而必定其为寒乎？径投凉解，热果复发，而肢冷脉伏如故。幸病者坚信，服药不疑。至第七日，大便泻出红水，溺则管痛，呕恶烦躁，彻夜不瞑，人更危之。孟英曰：热邪既已下行，可望转机。以白头翁汤加银花、通草、芩、芍、茹、滑、知、斛、栀、楝、羚角之类。投三日红水始止，四肢渐和，颇有昏瞀谵语，用王氏犀角地黄汤一剂。四肢热而脉显滑数，苔转灰黄，大渴遗溺，病人自述如卧烘箱上。于昨方加入元参、银花、竹叶、生石膏、知、贝、栀、斛。服一剂，夜间即安寐，而苔转黑燥，于昨方复加花粉。服一剂，热退而头面汗多，（阳越于上。）懒言倦寐，小溲欲解不通。（阴虚于下。）诸戚友咸以为危，（病已将愈，何危之有？）各举所知，而群医佥云挽救不及，病家皇皇。孟英曰：此证幸初起即予诊视，得尽力以为死里求生之举，非比他人之病，皆因误治致危。然不明言其险者，恐病家惶惑，而筑室于道旁也。今生机已得，不过邪去真阴未复，但当恪守予法，自然水到渠成，切勿二三其德，以致为山亏篑。赖有一二知音，竟从孟英议。服西洋参、生地、苁蓉、麦冬、楝、芍、知、斛药。一剂溺行索粥；再服而黑苔退；三服而神清音朗，舌润津回，唯有韧痰不能吐，左偏头微痛。于原方加二至、桑、菊、贝母、牡蛎。又复五剂，得解硬矢一次，各患始安，眠食渐适而瘳。（眉批：凡厥逆脉伏之证，其热深藏，多不易解，非卓识定力，不惑于证，亦必摇于众议矣。）", "14359": "王开荣偶患腹中绞痛，（伏暑在内。）自服治痧诸药，而大便泻血如注。（香燥可以益热。）孟英诊之，左颇和，右关尺弦大而滑，（弦滑者痰也，大者热也。）面色油红，喘逆不寐。与苇茎汤合金铃子散，加银花、侧柏叶、栀、斛、芩、连。二帖后，面红退，血亦止，乃裁柏叶、银花，加雪羹、枯荷杆。又二帖始发热，一夜得大汗周时，而腹之痛胀，爽然若失，即能安寐进粥。改投沙参、知母、花粉、桑叶、杷叶、石斛、白芍、橘络、杏仁、冬瓜子、茅根、荷杆。三帖大解行，而脉柔安谷。", "14360": "陈叟，久患痰嗽气逆。（肺气不清。）夏初因恶寒，热结在肺。自服理中汤，遂痰中带血，气喘而厥，二便不通，冷汗腹胀。孟英察脉洪大，按腹如烙。与苇茎汤加栀、楝、旋、贝、花粉、海䖳，外以田螺、大蒜、车前草捣贴脐下，即溺行而平。", "14361": "高某，患两膝后筋络酸疼，（血不养筋。）略不红肿，卧则痛不可当，彻夜危坐。孟英切脉虚细，苔色黄腻，咽燥溺赤，与知、斛、栀、楝、牛膝、豆卷、桂枝、竹沥为方，送虎潜丸。（阴虚于下，火炎于上，煎剂以治其上，丸药以培其下，井井有法。）旬日而瘳。", "14362": "杨某方作事，不知背后有人潜立，回顾失惊，遂不言不食，不寐不便，别无他苦。孟英按脉沉弦。以石菖蒲、远志、琥珀、胆星、旋、贝、竹黄、杏仁、省头草、羚羊角为剂，化服苏合香丸。二帖大解行而啜粥，夜得寐而能言。复与调气宁神蠲饮药，数日霍然。", "14363": "顾竹如孝廉令嫒，患感十余日，耳聋不语，昏不识人。（眉批：叶氏云：温邪中人，首先犯肺，其次则入心，正此病也。）而客未入室，彼反先知，（热极而神外越。）医以为祟。凡犀角地黄、牛黄清心、复脉等汤，遍服无效。（药不误，特病重药轻耳。）已摒挡后事矣。所亲濮根厓嘱其延诊于孟英，脉至滑数，舌不能伸，苔色黄腻，遗溺便秘，目不交睫者已四昼夜，（下证已悉备。）胸腹按之不柔。与白虎汤去米、草，加石菖蒲、元参、犀角、鳖甲、花粉、杏仁、竹叶、竹黄、竹沥。投一剂即谵语滔滔。渠父母疑药不对病，孟英曰：不语者欲其语，是转机也。再投之，大渴而喜极热之饮，又疑凉药非宜。孟英姑应之曰：再服一剂，更方可也。三投之，痰果渐吐。四剂后舌伸便下，神识渐清。乃去菖蒲、石膏、犀角、鳖甲，加生地、石斛、麦冬、贝母数帖。（温病后阴必耗竭，宜急救其阴，转方甚合法。）热尽退，而痰味甚咸。又去杏、贝、竹黄，加西洋参、牡蛎、龟板、苁蓉，服之全愈。（眉批：虽不用下剂，而通经透络之品，大剂用之，亦足以荡涤邪秽。）逾年失怙，继遭祝融，郁损情怀，误投温补，至戊申年殒。", "14364": "邵鱼竹给谏患感，杨某作疟治不应，始迓孟英诊之。脉软汗多，（热为湿所持，故脉软。）热不甚壮，苔色厚腻，呕恶烦躁，痰多腿酸，显是湿温。因谓其令郎子瓬曰：湿温者，湿蕴久而从时令之感以化热也。不可从表治，更勿畏虚率补。与宣解一剂，各恙颇减。奈众楚交咻，谓病由心力劳瘁而来，况汗多防脱，岂可不顾本原？群医附和。遂服参、归、熟地之药，（增湿益热，宜乎不救。）病日以剧。最后吴古年诊之云：此湿温也，何妄投补剂？然已末从挽救，交十四日而殒，始悔不从王议。", "14365": "叶杏江仲郎，患发热泄泻，（肺移热于大肠。）医治十七日不效、骨瘦如豺，音嘶气逆。所亲许芷卿荐孟英诊之。脉数大渴，汗多苔黄。以竹叶石膏汤加减，十余剂渐以向愈。大解反坚燥，继与滋养而康。", "14366": "张某患发热，医知其非寒邪也，用清解药数帖，腿痛异常，身面渐黄。孟英诊之，脉滑实，腹胀口干。与茵陈大黄汤。两剂便行，而各恙霍然。", "14367": "冯媪患左目胞起瘰，继而痛及眉棱、额角、巅顶，脑后筋掣难忍。医投风剂，其势孔亟。孟英诊脉弦劲，舌绛不饥。与固本合二至、桑、菊、犀、羚、元参、牡蛎、鳖甲、白芍、知母、石斛、丹皮、细茶等，出入为用，匝月始愈。", "14368": "濮妪于酷热之秋，浑身生疖如疔，痛楚难堪，小溲或秘或频，大便登圊则努挣不下，卧则不能收摄，人皆谓其虚也。（未闻虚而生疖者。）孟英诊脉滑数，舌紫苔黄而渴。与白虎汤加花粉、竹叶、栀子、白薇、紫菀、石斛、黄柏。十余剂而痊。", "14369": "姚小蘅太史令侄女，初秋患寒热而汛适至，医用正气散两帖，遂壮热狂烦，目赤谵语，甚至欲刎欲缢，势不可制。孟英按脉洪滑且数，苔色干黄尖绛，脘闷，腹胀拒按，畏明口渴，气逆痰多。与桃仁承气汤加犀角、石膏、知母、花粉、竹沥、甘菊。（照热入血室例治。）人谓热虽炽而汛尚行，何必大破其血而又加以极寒之药哉？孟英曰：叟勿过虑，恐一二剂尚不足以济事。果服两大剂始得大便，而神清苔化，目赤亦退。改用甘寒以清之。继而又不更衣，即脉滑苔黄而腹胀，更与小承气汤二帖，便行而各恙遄已。数日后，又如此，仍投小承气汤二帖。凡前后六投下剂，才得波浪不兴，渐以清养而瘳。季秋适江右上高令孙明府之子沛堂为室。", "14370": "董晓书令正，素患脘痛，甚至晕厥。今秋病腰疼腿木，胸闷气逆，不能卧。胡某进温补药而喘汗欲脱，杳不思谷。孟英切脉虚细中兼有弦滑，舌绛而渴，乃阴虚挟痰耳。与沙参、苁蓉、木瓜、石斛、蛤壳、蒺藜、石英、茯苓、紫菀、杏仁、楝实、首乌、牛膝诸药。（滋阴调肝而不腻，祛饮利痰而不燥，此孟英独得之秘。）旬日而安。继加熟地黄服之全愈。", "14371": "王苇塘患滞下，医投枳、朴、槟、楂之药。数服后，肢冷自汗，杳不进谷，脘闷腹痛，小溲牵疼，举家皇皇。孟英视脉细涩，舌绛无津，是高年阴亏，伏暑伤液，况平昔茹素，胃汁不充，加以燥烈之药，津何以堪？因与沙参、银花、苁蓉、白芍、石斛、木瓜、甘草、楝实、扁豆花、鲜稻头。（滋阴养液，兼调肝气。）数剂痛闷渐去，汗止肢温。乃加生地、阿胶、麦冬、柿饼、蒲桃干等以滋之。居然而痢止餐加，惟舌色至匝月始津润复常，阴液之难充也如此。", "14372": "一叟患滞下，色白不黏，不饥不渴，腹微痛而不胀。孟英切脉迟微。进大剂真武汤加参而愈。", "14373": "朱浚宣令堂患滞下，医闻色白，而与升提温补。旬日后，肢冷自汗，液脱肛坠。群医束手，虑其虚脱。因浼濮树堂乞诊于孟英。曰：药误耳。与大剂行气、蠲痰、清热之药，果渐吐痰而痢愈。又其令弟同时患此，五色并见，神昏肢搐，大渴茎肿，腹痛夜热，危险异常。孟英察脉细数，与白头翁汤加犀角、生地、银花、石斛、楝实、延胡、芩、连、滑石、丹皮、木通、甘草梢等药。三帖后，热退神清，溺行搐止，乃去犀角、草梢、丹皮、滑石、木通，加砂仁拌炒熟地、山楂炭。服之渐安，半月而愈。", "14374": "孙渭川年逾七旬，脉象六阴，按之如无，偶患音嘶痰嗽，舌绛无津。孟英用甘凉清润法，音开而嗽不已，仍与前药，转为滞下，色酱溺赤，脐旁坚硬，按之趯趯，舌犹枯绛，渴饮不饥，人皆危之。孟英曰：藏热由府而出，（此言甚精。）痢不足虑，第高年阴液难充，不能舍凉润为方，苟犯温燥，其败可必。幸渠家平素恪信，竟服犀角、地黄、知母、银花、苁蓉、花粉、麦冬、白芍、石斛、楝实等药。十余剂痢止，而脐旁柔软。因去犀角，加两洋参。又服西旬，始解燥矢，而溲澈胃苏。又服半月，复得畅解，舌亦润泽而愈。", "14375": "潘祥行在外患疟，买舟归，就孟英视。曰：苔腻脉软，伏邪所化，不与正疟同科，风寒药一味不可犯，姜枣汤一滴不可啜。与知、芩、橘、半、滑、朴、杏、斛、花粉、省头草。一剂而病若失。此等案极多，姑载一二。", "14376": "张与之令堂，久患痰嗽碍卧，素不投补药。孟英偶持其脉，曰：非补不可。与大剂熟地药，一饮而睡。与之曰：吾母有十七载不能服熟地矣，君何所见而重用颇投？孟英曰：脉细痰咸，阴虚水泛，非此不为功。从前服之增病者，想必杂以参、术之助气。昔人云：勿执一药以论方，故处方者贵于用药之恰当病情，而取舍得宜也。", "14377": "陈足甫室，怀妊九月而患疟，目不能瞑，口渴自汗，便溏气短，医进育阴清解法，数剂不应。改用小柴胡一帖，而咽疼舌黑，心头绞痛。乃翁仰山闻之，疑其胎坏，延孟英过诊。曰：右脉洪滑，虽舌黑而胎固无恙也。病由伏暑，育阴嫌其滋腻，小柴胡乃正疟之主方，古人谓为和剂，须知是伤寒之和剂，在温暑等证，不特手足异经，而人参、半夏、姜、枣皆不可轻用之药，虽有黄芩之苦寒，而仲圣于伤寒之治，犹有渴者去半夏，加栝蒌根之文，古人立方之严密，何后人不加体察耶？（眉批：疟亦分经而治，若阳明疟，正以白虎汤为主剂，岂有专守一小柴胡而能愈病者。）投以竹叶石膏汤。四剂疟止便秘，口渴不休。与甘凉濡润法数帖，忽腹鸣泄泻，或疑寒凉所致，孟英曰：吾当以凉药解之。人莫识其意，问难终朝语多不备录。果以白头翁汤，两啜而愈。迨季秋娩后，发热不蒸乳，恶露淡且少，家人欲用生化汤。孟英急止之曰：血去阴更伤，岂可妄疑瘀停而攻之。与西洋参、生地、茯苓、石斛、女贞、旱莲、甘草为大剂，数日而安。继因触怒，少腹聚气如瘕，酸痛夜甚，人又疑为凉药凝瘀所致。孟英力为辨析，与橘核、橘叶、橘络、楝实、苁蓉、木香、栀炭、乌药、丝瓜络、海䖳、藕、石斛、两头尖等药，外以葱头捣烂贴之。两帖后，腹中雷鸣，周身汗出而痛止。人见其汗，虑为虚脱，急追孟英视之，曰：此气行而病解矣。但脉形细数，阴津大伤，苔黄苦渴，亟宜润补。奈枢机窒滞，滋腻难投，且以濡养八脉为法。服之各恙皆蠲，眠食渐适。缘平素多郁，易犯痧气，频发脘痛，屡次反复。孟英竭力图维，幸得转危为安，渐投滋补而愈。", "14378": "胡季权子珍官，甫六岁，目患内障，继则夜热痰嗽，小溲过多，医作童损治。服滋补数月，病日以甚。孟英持脉右大，口渴苔黄，曰：伏热在肺，法当清解。及详诘其因，始言病起瘄后，盖余热未净，而投补太早。与滑石、知母、花粉、桑叶、茅根、枇杷叶、芦根、冬瓜子、杏仁。服二剂，遍身发出斑块。又二剂，斑退苔化，乃去滑石，加沙参饵之，其热头面先退，次退四肢，以及胸背，又数日甫退于腹，人皆诧其热退之异。孟英谓热伏既久，复为半年之补药，腻滞于其间，焉能一旦尽涤？其势必渐清而渐去也。热退既净，溺亦有节，痰嗽递蠲，餐加肌润，而内障亦渐除矣。", "14379": "顾奏云季秋患感，医作虚治，补及旬日，舌卷痉厥，腰以下不能略动，危在须臾。所亲石诵羲延孟英设死里求生之策，察脉虚促欲绝。先灌紫雪一钱，随溉犀角地黄汤二大剂服下。厥虽止而舌腭满黑，目赤如鸠，仍用前汤。三日间计服犀角两许，黑苔渐退，神识乃清，而呃忒频作，人犹疑其虚也。孟英曰：营热虽解，气道未肃耳。以犀角、元参、石花、连翘、银花、竹茹、知母、花粉、贝母、竹叶为方服之。次日即下黑韧矢甚多，而呃忒止。又三剂，连解胶黑矢四次，舌色始润，略进米饮，腿能稍动，然臀已磨穿矣。与甘润育阴药，续解黑矢又五次，便溺之色始正。投以滋养，日渐向安。已酉举于乡。其弟翰云，患左胯间肿硬而疼，暮热溺赤，舌绛而渴。孟英按脉细数，（阴虚血热。）径用西洋参、生地、麦冬、楝实、知母、花粉、银花、连翘、甘草、黄柏等药，服旬余而愈。", "14380": "许自堂令孙子社患感，延至秋杪，证交二十八日，诸医束手。渠伯母鲍玉士夫人，荐孟英诊之，左部数，右手俨若鱼翔，痰嗽气促，自汗瘛疭，苔色灰厚，渴无一息之停。垂危若是，而皓首之祖、孀母、少妻，相依为命，环乞拯救，甚可悯也。孟英曰：据脉莫能下手，吾且竭力勉图。第恐一齐众楚，信任不坚，则绝无可望之机矣。其母长跽而言曰：唯君所命，虽砒鸩勿疑也。于是，先以竹叶石膏汤加减。至五剂，气平嗽减，汗亦渐收，苔色转黑，舌尖露绛，改投元参、生地、犀角、石膏、知母、花粉、竹叶、银花等药。又五剂，瘛疭渐减，舌绛渐退。彼妇翁召羽士为之拜斗，飞符噀水，鼓乐喧阗。病者即谵妄不安，神昏如醉，羽士反为吓退。夤夜速孟英视之，与紫雪钱余，神即清爽。仍用前方，重加竹沥，服八剂，始解黑如胶漆之大便，而黑苔渐退，右脉之至数始清，惟烦渴不减，令其恣啖北梨，舌才不燥，痰出亦多。又六剂，舌色乃淡，溲出管痛，热邪得从下行矣。凡十二日之间，共服大剂寒凉已二十四帖，计用犀角三两有奇，而险浪始平。续以前法缓制，服六剂，又解黑矢五次，手足始知为己有。又五剂，筋络之振惕始定，略能侧卧，呓语乃息，渐进稀糜。继灌甘润充其胃汁，（非此无以善其后。）七八剂后，渴止知饥，脉皆和缓。又浃旬，谷食乃复。又旬余，便溺之色始正。前后共下黑矢四十余次，苔色亦净。授滋填善后而康。是役也，凡同道暨许之族人戚友，莫不以为秋冬之交，用药偏寒，况病延己久，败象毕呈，苟不即投峻补，必致失手。既闻鲍夫人云：归许氏二十余年，目击多人，无不死于温补，此等病曾见之，此等药盖未尝闻也。孰知如此之证，有如此之治，求之古案，亦未前闻，传诸后贤，亦难追步。盖学识可造，而肠热胆坚，非人力所能及。此孟英所以为不世出之良医也。", "14381": "段春木秋杪患发热，（外感温邪。）而腰腿痛如刀割，（真阴内损。）孟英视之：略不红肿，脉至细数，（热伤少阴。）苔色黑燥，溺赤便黑。与西洋参、麦冬、生地、犀角、银花、楝实、石斛、知母、甘草、竹沥、蔗汁为大剂投之。热渐退，痛渐已，惟舌绛无津。（阴亏也。）仍与甘凉濡润为方。数日后，忽舌绛倍加，燥及咽膈，水饮不能下咽。孟英曰：真阴涸竭，药难奏绩矣。然窃疑其何以小愈之后，骤尔阴枯？或者背予而服别药乎？继其契友来询云：段死而舌出，此曷故欤？孟英闻之，爽然大悟。因撷《伤寒》女劳复之文示之，其人顿足云良然。彼于小愈后，曾宿于外，次日归即转剧，苟直陈不讳，或尚可治。孟英曰：未必然也，烧裩散、鼠矢汤，皆从足少阴以逐邪，不过热邪袭入此经，所谓阴阳易是也。今少腹无绞痛之苦，原非他人之病易于我，真是女劳之复，以致真阴枯涸，更将何药以骤复其真阴哉！然从此而女劳复与阴阳易，一虚一实有定论，不致混同而谈治矣。", "14382": "顾升庵参军之仲郎，久患多疑善恐，（痰之见证。）不出房者数年矣。食则不肯与人共案，卧则须人防护，寡言善笑，（热之见症。）时或遗精，多医广药，略无寸效。孟英切脉甚滑数，（脉与证合。）与元参、丹参、竹黄、竹茹、丹皮、黄连、花粉、栀子、海䖳、荸荠为剂，（从痰火治。）送服当归龙荟丸。四帖即能出署观剧，游净慈而登吴山。参军大喜，以为神治。次年为之配室。", "14383": "陈某偶患溏泄，所亲鲍继仲云：余往岁患泻，治不中肯，延逾半载，几为所困。今秋患此，服孟英方，数剂霍然，故服药不可不慎也，盍延孟英治之。陈因中表二人皆知医，招而视之，以为省便，辄投以温补健脾之药，数日后泻果减。（热得补而不行。）而发热昏痉，咽喉黑腐。其居停瞿颖山，疑病变太速，嘱其请援于孟英。孟英诊曰：迟矣！病起泄泻，何必为寒，正是伏邪自寻出路，而温补以固留之，自然内陷厥阴，不可救药。果即殒焉。继有高小垞孝廉令弟雨生，因食蟹患泻，黄某用大剂温补药，泻果止，而颈筋酸痛，舌绛呕渴，口气甚臭。孟英持脉沉数，曰：食蟹而后泻，会逢其适耳。脉证如斯，理应清润。奈病人自畏凉药，复质于吴某，亦主温补。服及旬日，昏痉舌黑而毙！", "14384": "金某久患脘痛，按之漉漉有声，便秘溲赤，口渴苔黄，杳不知饥，绝粒五日，诸药下咽，倾吐无余。孟英察脉沉弱而弦。用海䖳、荸荠各四两煮汤饮之，径不吐，痛亦大减。继以此汤煎高丽参、黄连、楝实、延胡、栀子、枳椇、石斛、竹茹、柿蒂等药，送服当归龙荟丸。旬日而安。续与春泽汤调补收绩。盖其人善饮而嗜瓜果以成疾也。（眉批：此肝气挟痰饮上逆也。缘素嗜瓜果，胃阳久伤，故于平肝涤饮之中，加参以扶胃气。）", "14385": "乔有南年三十九岁，患牝疟二旬。医治罔效。所亲徐和圃疑为伏暑，迓孟英往诊。脉微无神，倦卧奄奄，便秘半月，溺赤不饥，痰多口甘，稍呷米饮，必揉胸槌背而始下，苔色黑腻而有蒙茸之象。乃曰：此精、气、神三者交虚之证，不可与时行伏暑晚发同年而语也。幸前手之药，法主运中，尚无大害。与参、术、桂、附、沉香拌炒熟地、鹿角、石英、苁、杞、归、茯、杜仲、枣仁、菟丝、山茱、橘皮、霞天曲、胡桃肉等，出入为大剂，投十余帖，寒后始有热，而苔色乃退，口不作渴，甘痰亦日少，粥食渐加，即裁桂、附、白术，加石斛，又服七剂，解黑燥大便甚多，凡不更衣者，四旬二日矣。寒热亦断，安谷溲澄而竟愈。或谓先生尝訾人温补之非，何一旦放手而大用？孟英曰：温补亦治病之一法，何可废也，第用较少耳。世之医者，眼不识病，仅知此法可以媚富贵之人，动手辄用，杀人无算，岂非将古人活世之方，翻为误世之药，可不痛恨耶！", "14386": "陈媪患牝疟月余，腹胀便秘，嗳多不饥，口淡脉滑。孟英主连、朴、橘、贝、杏、茹、旋、菀、杷、蒺为方，数剂即瘳。（眉批：此与前案虚实相反，正可对看。）", "14387": "孟英治其令弟季杰之簉室，因夜间未寐，侵晨饮酒解寒，适见人争谇，即觉心跳欲吐，家人疑其醉也，而欲吐不出，气即逆奔如喘，且肢麻手握，语言难出。又疑为急痧而欲刺之，孟英闻而视之，脉象弦驶。曰：夜坐阳升，饮醇则肝阳益浮，见人争谇，是惊则气更上逆，不可刺也。灌以苏合香丸一颗，下咽即瘥。（眉批：此当是痰闭气结之故，苏合丸辛香通气故愈。若是肝浮气逆，益以香窜之药，安能愈乎？）", "14388": "黄履吉截疟后患浮肿，赵某闻其体素虚，切其脉弦细，遂用温补，驯致呃忒不休，气冲碍卧，饮食不进，势濒于危，请孟英决其及返余杭否？孟英曰：脉虽弦细而有力，子必误服温补矣。肯服吾药，犹可无恐。因与栝蒌、蕤白合小陷胸、橘皮竹茹汤，加柿蒂、旋覆、苏子、香附、赭石、紫菀、杷叶为方。四剂而瘳。", "14389": "吴馥斋室，春间娩子不育，汛事亦未一行，偶患呕吐发热，眩晕心嘈，大解溏泄，口渴溲痛，或疑其娠，或疑为损。孟英诊曰：产及一载，而经不至，腹不胀，脉弦缓，非娠非损，乃血虚痰滞而感冬温也。以羚羊、淡豉、竹茹、白薇、栀子、杷叶、知母、葱白、花粉投之。三剂热退吐止，去葱、豉、羚羊，加生地、甘草、橘皮，调之而愈。", "14390": "盛犀林广文仆，患血痢，自秋徂冬，半年罔效。孟英察脉细弱，而口干，腰膝酸疼，与鹿角霜、苁蓉、枸杞、杜仲、菟丝、续断、血余、石脂、木瓜、砂仁末炒熟地黄，十余剂而痊。", "14391": "徐月岩室，患周身麻木，四肢瘫痪，口苦而渴，痰冷如冰，气逆欲呕，汛愆腹胀，频饮极热姜汤，似乎畅适，深秋延至季冬，服药不愈。孟英诊脉沉弦而数。曰：溺热如火乎？间有发厥乎？病者唯唯。遂以雪羹、旋、赭、栀、楝、茹、斛、知母、花粉、桑枝、羚羊、橄榄、蛤壳为方，送下当归龙荟丸。服之递效，二十剂即能起榻，乃去羚、赭，加西洋参、生地、苁蓉、藕。投之渐愈。", "14392": "张肖江妹，暮冬患感。朱某进温散数服，病日剧。比孟英视之，目瞪不语，面赤气逆，昼夜需人抱坐，四日不著枕矣。乃冬温挟痰，误提而气不肃降也。以旋、赭、杏、贝、花粉、茅根、冬瓜子、紫菀、蕤白、蒌仁、苏子、石菖蒲、竹沥为剂，芦菔汤煎。三帖大便行而能卧矣，自言胸中迷闷。改用小陷胸合三子养亲，加沙参、知母、旋、贝、竹茹、枇杷叶。数剂热退，知饥而愈。嗣有王炳华子患感，叶某用温散药，而气逆碍卧。四明老医王秉衡，作肾虚不能纳气治，连服大剂温补，喘嗽益剧，面浮跗肿，抬肩自汗，大渴胁痛。乞治于孟英，已半月不交睫矣。诊其脉右部弦大而强，舌根黑苔如煤者两条，面藜形瘦，幸而大解溏泄，得能消受许多误药。径与旋、赭、黄连、枳实、栝蒌、苏子、杏仁、紫菀、生石膏、芦菔汁。六大剂始能就枕，而大渴不止，脘腹反形痞胀，按之坚痛，乃去旋、赭，少加白芥子、半夏、薤白。兼令日啖北梨数十枚。服旬日，胸腹皆舒，苔色尽退，唯嗽未已。改用西洋参、杏、贝、芦根、知母、冬瓜子、花粉、柿霜、杷叶、竹沥。十许剂嗽止，而跗肿渴泻，亦皆霍然矣。凡啖梨三百余斤，闻者莫不诧异。", "14393": "丙午春，高汉芳患滞下色酱，日数十行，年已七十七岁。自去秋以来，渐形疲惫，即服补药，驯致见痢。黄某径用温补，势乃剧。延孟英诊之，右脉弦细芤迟，（脉虚证实。）口渴溲涩，时时面赤自汗。乃吸受暑邪，误作虚治，幸其所禀极坚，尚能转痢。一误再误，邪愈盛而正反虚矣。以白头翁汤加参、术、银花、芩、芍、楝、斛、延胡。二剂即减，五剂而安。继与调补，竟得霍然。后三载，以他疾终。", "14394": "章养云室患感，适遇猝惊。黄、包二医，皆主温补，乃至昏谵痉厥，势极危殆，棺衾咸备，无生望矣。所亲陈仰山闻之，谓云：去秋顾奏云之恙，仅存一息，得孟英救愈，子盍图之？章遂求诊于孟英。证交三十八日，脉至细数无伦，（阴将竭矣。）两手拘挛，（肝无血养。）宛如角弓之反张，痰升自汗，渴饮苔黄，面赤臀穿，昼夜不能合眼。先与犀、羚、贝、斛、元参、连翘、知母、花粉、胆星、牛黄、鳖甲、珍珠、竹黄、竹叶、竹沥、竹茹为方。三剂，两手渐柔，汗亦渐收。又五剂，热退痰降，脉较和，而自言自答，日夜不休。乃去羚、斛、珠、黄，加西洋参、生地，大块朱砂两许。（太多。）服之聒絮不减，或疑为癫，似有摇惑之意。孟英恐其再误，嘱邀许芷卿商之。芷卿极言治法之丝丝入扣，复于方中加青黛、龙、牡。（热在心而用肝肾药，宜乎不效。）服二剂，仍喋喋不已。孟英苦思数四，径于前方加木通一钱，（眉批：用木通精当。凡心经蕴热用犀角、黄连等药，必兼木通，其效乃捷，以能引心经之热从小肠出也。）投匕即效。次日病者自云：前此小溲业已通畅，不甚觉热，昨药服后，似有一团热气从心头直趋于下，由溺而泄。从此神气安谧，粥食渐加，两腿能动，大解亦坚。忽咽肿大痛，水饮不下。孟英曰：余火上炎也。仍与前方，更吹锡类散而安。惟臀疮未敛，腿痛不己，乃下焦气血伤残，改用参、耆、归、芍、生地、合欢、山药、麦冬、牛膝、石斛、木瓜、桑枝、藕肉。数服痛止餐加，又与峻补生肌而愈。", "14395": "吴酝香孝廉三令嫒患感，诸医首以升散，继进温补，至三月下旬，证交三十五日。昏痉谵语，六昼夜不交睫，旬日不沾米饮。许芷卿视之，俨似养云室证，即拉孟英暨顾听泉、赵笛楼会诊。脉弦滑而微数，齿不能开，窥其舌缩苔垢。孟英曰：尖虽卷，色犹红润，且二便不秘，尚有一线生机未绝也。揆其受病原不甚重，只因谬治逾月，误药酿成大证，势虽危险，吾侪当竭力援之，第勿再犯一味悖药，事或有济。酝香颇极信从。孟英复询其服事婢媪曰：病已逾月，腰以下得毋有磨坏之虞乎？皆曰：无之。惟数日前易其所遗，略有血渍，必月事之不愆也。孟英颇疑之，嘱其再易之时，留心细察。疏方以犀角四钱，石菖蒲二钱，贝母二两，整块朱砂两许，（朱砂不宜入煎剂。）竹沥碗许，佐以竹叶、竹黄、竹茹、知母、花粉、元参、旋覆、丝瓜络、苇茎、银花、鳖甲。（眉批：非此大剂不足以起垂危之证。）调下紫雪丹。次日诸君复会，渠母徐夫人即云：王君明视隔垣，小女腰下果已磨穿，糜溃如柈，婢媪辈粗忽，竟未之知也。昨药服后，证亦少减。孟英仍主原方。四服后夜始眠，痉才息，舌甫伸，苔乃黑。孟英于前方去鳖甲、朱砂、菖蒲，加生地、栀子。数服后苔转黄，大便黑如胶漆，且有痰色，盖从前大解黄色，似乎无甚大热，不知热由补药所酿，滞于肠胃曲折之地，而不能下行，势必薰蒸于上，致有内陷入藏之逆也。黑矢下而神识渐清，余热复从气分而达，痰嗽不爽，右脉滑搏。孟英主用竹叶石膏汤加减。四剂渐安，而外患痛楚，彻夜呻吟，虽敷以珠黄，滋以甘润，未能向愈。孟英令以大蟾蜍治净煮汤，煎育阴充液之药服之。果痛止肌生，眠食渐进，汛事如期而瘳。冬间适张舟甫之子为室。或疑其病虽愈，而过饵凉药，恐难受孕。迨戊申夏，已得子矣。", "14396": "吴酝香之仆吴森，在越患感，旋杭日鼻衄数升，苔黄大渴，脉滑而洪，孟英投白虎汤二帖而安。遽食肥甘，复发壮热，脘闷昏倦，孟英以枳实栀豉汤而瘥。数日后，又昏沉欲寐，发热自汗，舌绛溺涩，仍求孟英诊之。左尺细数而芤，右尺洪大，是女劳复也。研诘之果然。与大剂滋阴清热药，吞豭鼠矢而愈。", "14397": "王月锄令媳，于庙见时忽目偏左视，扬手妄言，诸亲駴然，诘其婢媵，素无此恙，速孟英视之。脉弦滑而微数，苔黄脘闷。盖时虽春暮，天气酷热，兼以劳则火升，挟其素有之痰而使然也。与犀、羚、栀、翘、元参、丹参、薄荷、花粉，送礞石滚痰丸。三服而痰下神清。改投清养遂愈，次年即诞子。", "14398": "单小园巡检，患右胁痛。医与温运药，病益甚，至于音瘖不能出声，仰卧不能反侧，坐起则气逆如奔，便溺不行，汤饮不进者已三日矣。孟英诊其脉沉而弦。与旋覆、赭石、薤白、蒌仁、连、夏、茹、贝、枳实、紫菀，加雪羹服之。一剂知，数剂愈。", "14399": "许某于醉饱后，腹中胀闷，大解不行，自恃强壮，仍饮酒食肉。二日后腹痛，犹疑为寒，又饮火酒，兼吸洋烟，并小溲而不通矣。继而大渴引饮，饮而即吐，而起居如常也。四朝走恳孟英诊之。脉促歇止，满舌黄苔，极其秽腻，而体丰肉颤，证颇可危。因婉言告之曰：不过停食耳，且饮山楂神曲汤可也。午后始觉指冷倦怠，尚能坐轿出城，到家气逆，夜分痰升。比晓，胸腹额上俱胀裂而死，盖知下之不及，故不与药也。", "14400": "何新之亦儒医也。患感旬日，胡士扬诊谓势欲内陷，举家皇皇。渠表弟沈悦亭茂才，亦上岐黄，而心折于孟英，因拉视之。呃忒苔腻，便秘痰多，心下拒按，持其脉右手洪大滑数。与小陷胸，加沙参、菖、贝、菀、薤、茹、杏、旋、杷之剂，数帖而安。继以甘凉，二旬后得大解而痊，何乃执柯，为王、沈联姻娅焉。", "14401": "翁氏妇患目疾，自春徂夏，治不能瘳，渐至腹中痞胀，痛不可当，食不能下，便秘形消。孟英视之，乃肝郁痰滞而误补以致殆也。脉弦数而滑，与金铃子散合雪羹煎，吞当归龙荟丸暨礞石滚痰丸。三投即效，服至二十余日，各恙皆蠲，眠食如旧。", "14402": "仲夏瘄疹流行，幼科执用套药，夭札实多。有王子能参军所亲楚人刘某，仅一子甫五龄，陆某见其瘄点不绽，连进柽柳等药，壮热无汗，面赤静卧，二便不行。参军闻其殆，迟孟英视之。投犀羚白虎汤而转机。陆某力阻石膏不可再饵，仍进温散，以至气喘痰升。复加麻黄八分，欲图定喘，而喘汗濒危，二便复秘。（麻黄定喘，乃方脉中感受风寒之证施之，麻疹何其不通。）再恳孟英救之。投白虎加西洋参、竹叶而愈。继有房氏子亦为陆某误用温散致剧，痰喘便秘，口渴神昏，溲碧肢瘛。孟英与大剂白虎汤，加犀角、元参、竹叶、木通，调紫雪。四帖而始安。（眉批：疹为阳邪，乃肺胃湿热所致。初宜辛凉发散，令其尽出，不宜骤用寒凉，恐冰伏热邪，不能发出也；继即宜大清肺胃之药，以解余毒，从未有温散之法。至麻黄尤为禁剂，何儿科之愦愦耶！）", "14403": "李新畲仲郎，瘄未齐而痰嗽气喘，（疹中应有之证。）苔色白滑，小溲不赤。或主犀角地黄汤加紫雪，热在气而清其肝，故不效。服而不效，延孟英诊之。右脉洪滑而口渴，脉证相符。乃天时酷热，暑邪薄肺，挟其素有之痰而阻其治节，所以气机不行，而疹不能达，苔不能化，溺不能赤也。温散大忌，凉血亦非。与竹叶石膏汤合苇茎，加杏、菀、旋、杷、海石。投之气平疹透，苔退舌红，小溲亦赤，数日而愈。（眉批：治疹原以清肺为第一义。）", "14404": "杭城温元帅，例于五月十六日出巡遣疫。有魏氏女者，家住横河桥之北，会过其门，将及天晓，适有带发头陀，由门前趋过，瞥见之大为惊駴，注目视之，知为僧也，遂亦释然。而次日即不知饥，眩晕便秘。医谓神虚，投补数帖，反致时欲昏厥。（不问何证，概投温补，何其愚耶？）更医作中风治，势益甚。旬日后，孟英持其脉弦伏而滑，胸腹无胀闷之苦，旬余不更衣，是惊则气乱，挟痰逆升，正仲圣所谓诸厥应下者，应下其痰与气也。以旋、赭、栀、连、雪羹、楝、贝、金箔、竹沥、菔汁为方，并以铁器烧红淬醋，令吸其气。二剂厥止，旬日而瘳。", "14405": "某媪年六十余，患腰腿串痛，闻响声即两腿筋掣不可耐，日必二三十次，卧榻数载，诸药罔效。孟英察脉沉弦，苔腻便秘，亦广服温补而致病日剧也。与雪羹、羚、楝、胆星、橘络、竹沥、丝瓜络，吞礞石滚痰丸及当归龙荟丸。四剂，大泻数十次，臭韧异常，筋掣即已。乃去二丸，加栀、连、羊藿。服六剂，即健饭而可扶掖以行矣。（眉批：此人初病，必系血虚不足以养肝，因妄服温补，以致积痰蕴热，胶固不开。孟英治法，亦是救药误为多，愈后必继以滋养血液之药，方收全功。）", "14406": "徐艮生室，年四十余，于酷暑之时患疒昔，所亲沈悦亭连与清解，不能杀其势。为邀孟英视之。体厚痰多，脉甚滑数，扬掷谵妄，舌绛面赤，渴饮便涩。乃与大剂白虎加犀角、元参、银花、花粉、贝母、竹黄、竹叶、竹茹、竹沥，送滚痰丸。服后大便下如胶漆，脉证渐和，数日后去丸药，其势复剧，甚至发厥，仍加丸药乃平。如是者三次，险浪始息。悦亭复以白金丸涤其膈下留痰，续用甘凉濡润法，充津液而搜余热，渐以告愈。（眉批：此大实证也，非峻攻不愈。）", "14407": "陈氏妇，素无病，娩后甚健，乳极多而善饭。六月初形忽遽瘦，犹疑天热使然，渐至减餐。所亲徐丽生嘱延孟英视之。脉细数，舌光绛，曰：急劳也，无以药为。夫乳者，血之所化也，乳之多寡，可征血之盛衰。兹乳溢过中，与草木将枯，精华尽发于外者何异？即今断乳，亦不及矣。其家闻之，尚未深信，即日断乳服药，及秋而逝。", "14408": "蒋北瓯二尹，患疟，医与小柴胡、平胃散而渐甚；继以大剂温补，势濒于危；复用桂枝白虎，狂乱如故。所亲董兰初鹾尹，延孟英视之。曰：暑疟也。桂枝白虎用于起病之时则妙矣，今为温散补燥诸药，助邪烁液，脉数无伦，汗渴不已，虽宜白虎，（分别了亮，）岂可监以桂枝助热耗津，而自掣其肘耶？因与大剂白虎加花粉、竹叶、西洋参、元参、石斛。服之即安，至十余帖疟始瘳，而舌尚无苔，渴犹不止，与甘凉濡润，三十余剂始告痊。", "14409": "孙心言以七十之年患滞下，胡某知为暑热，以清麟丸下之，治颇不谬。继则连投术、朴、夏、葛等药，渐至咽疼口糜，呃忒噤口，诸医进补，其势孔亟。伊婿童秋门迓孟英诊之。右脉滑数上溢，身热面赤，溲涩无眠，体厚痰多，时欲出汗。在痢疾门中，固为危候，第以脉证参之，岂是阳虚欲脱？实由升散温燥之剂烁其阴液，肺胃之气窒塞而不能下行也。与大剂肃清之药，一剂知，二剂已，随以生津药溉之，痢亦寻愈。按：此等痢呃，古书未载，而治法悬殊，世人但守成法，不知变通，治而不愈，诿之证危，况属高年，病家亦不之咎也，孰知有此随时而中之妙法耶！", "14410": "曹泳之二尹，将赴代理昌化任，而疟痢并作，寒少热多，滞下五色。逆孟英视之。面垢苔黄，干呕口渴，痛胀溺赤，汗出神疲，脉至洪数不清。与大剂芩、连、滑、朴、知母、花粉、银花、石膏、连翘、竹茹等药。投匕即减，三服而起。", "14411": "陈邠眉令郎，孟秋患感，医与表散温补，病随药剧。至八月初，渠叔祖陈霭山，延孟英视之。目瞪神呆，气喘时作，舌绛不语，便泻稀水，肢搐而厥，人皆以为必死矣。察其脉弦而软数，乃阴亏肝盛之质，提表助其升逆，温补滞其枢机，痰饮𫐖轕，风阳肆横，祷神驱祟，有何益哉！与鳖甲、龙、牡、旋、赭、芩、连、楝、贝、菖、茹、胆星、犀、羚等药，息风镇逆，清热蠲痰，数帖而平。", "14412": "龚念匏室，故舍人汪小米之女也。患秋感，服温散药而日重。渠叔母韩宜人，请援于孟英。脉见弦数软滑，苔黑肢瘛。疏方用沙参、元参、知母、花粉、犀、羚、茹、贝、栀、菖等药，日亟饵之，否将厥矣！时念匏幕于江南，族人皆应试入场，侍疾者多母党，伊叔少洪疑药凉，不敢与服，迨暮果欲厥矣。众皆皇皇，幸彼女兄为故孝廉金访叔之室，颇具卓识，急煎孟英方灌之，遂得生机。次日复诊脉较和，一路清凉，渐以向愈。", "14413": "仲秋久雨，吴汾伯于乡试后患恙，自言坐于水号，浸及于膝，人皆以为寒湿之病。孟英切脉甚数，溲赤苔黄，口干燥呛，因谓其尊人酝香曰：病由暑湿，而体极阴亏，已从热化，不可以便泄而稍犯温燥之药。先与轻清肃解，继用甘凉撤热，渐能安谷。半月后，热始退尽，而寝汗不眠，投以大剂滋填潜摄之药，兼吞五味子磁朱丸数十帖，乃得康复。此证误治即败，少谬亦必成损，苟非识信于平日，焉能诚服于斯时？闻其寝汗不收，夜不成寐之间，旁言啧啧，孟英恐其摇动主意，必致全功尽弃，嘱其邀顾听泉、许芷卿质政，而顾、许咸是孟英议，于是主人之意益坚，而大病乃痊。吁！谈何易耶。", "14414": "张慈斋室，自春间半产后发热有时，迄于季秋，广服滋阴之药，竟不能愈。其大父陈霭山延孟英诊脉，按之豁然。投当归补血汤而热退，继以小建中愈之。（此众人用滋阴者，而孟英以阳和之品愈之，可见医在认证，不在执方也。）", "14415": "许守存久患痰嗽，孟英主滋水舒肝法，以阴亏而兼郁也，业已向愈。所亲某亦涉猎医书，谓滋阴药不可过服，投以温补。已而咳嗽复作，渐至咽痛。冬初又延诊于孟英，曰：六脉皆数，见于水令，其不能春乎！果验。世人不辨证之阴阳，但论药之凉热，因而偾事者多矣。", "14416": "朱砥斋司李之夫人，屡患半产，每怀妊服保胎药卒无效。今秋受孕后病嗽，孟英视之，尽屏温补，纯与清肺。或诘其故，曰：胎之不固，或由元气之弱者，宜补正；或由病气之侵耳，宜治病。今右寸脉滑大搏指，吾治其病，正所以保其胎。苟不知其所以然，而徒以俗尚保胎之药投之，则肺气愈壅，咳逆愈盛，震动胞系，其胎必堕矣。朱极饮佩，服之良效。次年夏，诞子甚茁壮。（眉批：通达之论，凡病俱宜如此看。）", "14417": "邵奕堂室，以花甲之年，仲冬患喘嗽，药之罔效，坐而不能卧者旬日矣。乞诊于孟英。邵述病原云：每进参汤则喘稍定，虽服补剂，仍易出汗，虑其欲脱。及察脉弦滑右甚，孟英曰：甚矣！望闻问切之难，不可胸无权衡也。此证当凭脉设治，参汤切勿沾唇，以栝蒌、薤白、旋覆、苏子、花粉、杏仁、蛤壳、茯苓、青黛、海䖳为方，而以竹沥、菔汁和服，投匕即减，十余帖全愈。同时有石媪者，患此极相似，脉见虚弦细滑。孟英于沙参、蛤壳、旋覆、杏仁、苏子、贝母、桂枝、茯苓中，重加熟地而瘳。所谓病同体异，难执成方也。", "14418": "许太常滇生之夫人，患腿痛而素多噫气，若指头一搓，或眉间一抹，其噫即不已。向以为虚，在都时服补剂竟不能愈。冬间旋里，孟英诊脉弦滑，乃痰阻于络，气不得宣也。以丝瓜络、竹茹、旋覆、橘络、羚羊、茯苓、豆卷、金铃、柿蒂、海䖳、荸荠、藕为方，吞当归龙荟丸而安。其媳为阮芸台太傅之女孙，在都因丧子悲哀，患发厥。屡服补剂，以致汛愆，或疑为娠。孟英曰：脉虽弦数以滑，乃痰挟风阳而为厥也。与大剂蠲痰息风、舒郁清营之剂，渐以获愈。", "14419": "歙人吴永言，于十年前，读《论语》不撤姜食之文，因日服之，虽盛夏不辍。至三年前患大溢血，虽以凉药治瘳，而时时火升，迄今不愈。季冬就诊于孟英，身不衣绵，头面之汗蓬蓬也。且云：服芩、连则烦渴益甚，以苦能化燥也；用生地即闷滞不饥，以甘能缓中也；蔗、梨入口亦然。按其脉，沉取滑数，是从前之积热，深伏于内。与白虎汤去草、米，加竹叶、竹茹、花粉、海䖳、荸荠、银花、绿豆恣服，渐吐胶痰而愈。继闻赵秋舲进士令郎子循，每啖蔗则鼻衄必至，或疑蔗为大热之性。孟英曰：蔗甘而凉，然甘味太重，生津之力有余，凉性甚微，荡热之功不足，津虚热不甚炽者，最属相宜，风温证中救液之良药，吾名之曰天生复脉汤。若湿热痰火内盛者服之，则喻氏所谓翻受胃变从而化热矣。凡药皆当量人之体气而施，岂可拘乎一定之寒热耶？子循之体，水虚而火旺者也，蔗性不能敌，反从其气而化热，正如蔗经火炼则成糖，全失清凉之本气矣。枸杞子亦然。（眉批：精透之论，由斯类推，可以知药性之功能矣。）", "14420": "李华甫继室，娠三月而崩。孟英按脉弦洪而数，与大剂生地、银花、茅根、柏叶、青蒿、白薇、黄芩、续断、驴皮胶、藕节、胎发灰、海螵蛸而安。奈不能安佚，越数日胎堕复崩。孟英于前方去后六味，加犀角、竹茹、元参为治。或谓胎前宜凉，产后则否，乃招专科暨萧山竹林寺僧治之，咸用温药，且执暴崩宜补。服药数剂，虚象日著，时时汗出昏晕，畏闻人声，懒言息微，不食不眠，间有呃忒，崩仍不止，皆束手待毙矣。复邀孟英视之，曰：此执死书以治活病也。夫血因热而崩，胎因崩而堕，岂胎堕之后，热即化为寒乎？（妙语解颐。）参、术、姜、桂、棕灰、五味之类，温补酸涩，既助其热，血益奔流，又窒其气，津亦潜消，致现以上诸证，脉或不知，而苔黄黑燥，岂不见乎？因与犀角、石膏、元参、知母、花粉、竹沥、麦冬、银花、栀子、石斛、旋覆、青蒿、白薇等大剂投之，神气渐清。旬日后，各恙始平，继去犀角，加生地，服两月全愈。", "14421": "丁未春，金朗然令堂，陡吐狂血，肢冷自汗。孟英切脉弦涩，察血紫黯，乃肝郁凝瘀也。证虽可愈，复发难瘳。予丹参、丹皮、茺蔚、旋覆、苓、栀、柏叶、郁金、海䖳之方，复杯果愈。然不能惩忿，逾二年复吐，竟不起。", "14422": "张孟皋少府令堂，年逾古稀，患气逆殿屎，烦躁不寐。孟英切脉滑实，且便秘面赤，舌绛痰多。以承气汤下之霍然，逾年以他疾终。", "14423": "王致青鹾尹令正，患痰喘，胡某进补肾纳气，及二陈、三子诸方，证濒于危。顾升庵参军，令延孟英诊之，脉沉而涩，体冷自汗，宛似虚脱之证，惟二便不通，脘闷苔腻。是痰热为补药所遏，一身之气机窒痹而不行也。与蒌、薤、旋、赭、杏、贝、栀、菀、兜铃、海䖳、竹沥等以开降，复杯即减，再服而安。", "14424": "王汇涵室，年逾六旬，久患痰嗽，食减形消，夜不能眠，寝汗舌绛，广服补剂，病日以增。孟英视之曰：固虚证之当补者，想未分经辨证，而囫囵颟顸，翻与证悖，是以无功。投以熟地、苁蓉、坎板、胡桃、百合、石英、茯苓、冬虫夏草等药，一剂知，旬日愈。以其左脉弦细而虚，右尺寸皆数，为阴亏气不潜纳之候，及阅前服方，果杂用耆、术以助气，二陈、故纸、附、桂等以劫阴也，宜乎愈补而愈剧矣。", "14425": "张箎百之室患感，连服温散，继邀顾听泉诊之，云有骤变，须延孟英商治。渠之不信，旬日后倏然昏厥，自寅正至辰初不苏。病者之兄吴次欧，速孟英视之。脉伏而弦滑。与大剂犀、羚、茹、贝、知母、花粉、元参、银花，调局方至宝丹，灌下即安。", "14426": "王雪山令媳患心悸眩晕，广服补剂，初若甚效，继乃日剧，时时出汗，肢冷息微，气逆欲脱，灌以参汤，稍有把握，延逾半载，大费不赀。庄芝阶舍人令延孟英诊视。脉沉弦且滑，舌绛而有黄腻之苔，口苦溲热，汛事仍行。病属痰热𫐖轕，误补则气机壅塞。与大剂清热涤痰药，吞当归龙荟丸，服之渐以向安。（痰热体实者，此丸颇有殊功。）仲夏即受孕，次年二月诞一子。惜其娠后停药，去疾未尽，娩后复患悸晕不眠，气短不饥，或作产后血虚治不效，仍请孟英视之。脉极滑数，曰：病根未刈也。与蠲痰清气法果应。", "14427": "许子双令堂梁宜人，仲春之杪，偶患微感，医与温散，热已渐退。孟英偶过诊，右寸脉促数不调，因谓子双曰：此风温证，其误表乎？恐有骤变。渠复质之前医，以为妄论，仍用温燥，越二日即见鼾睡，再延孟英诊之，促数尤甚，曰：鼻息鼾矣，必至语言难出，仲圣岂欺我哉？风温误汗，往往皆然，况在高年，殊难救药。果浃旬而逝。（眉批：此证虽经仲景指出，而人多不识，往往杂药乱投，卒至鼾睡而死，医家、病家两俱茫然。孟英此案可为仲景之功臣矣。）", "14428": "姚某年未三旬，烟瘾甚大，适伊母病温而殁，劳瘁悲哀之际，吸受温邪，胁痛筋掣，气逆痰多，热壮神昏，茎缩自汗，医皆束手。所亲徐丽生嘱其速孟英诊之。脉见芤数，舌绛无津，有阴虚阳越、热炽液枯之险，况初发即尔，其根蒂之不坚可知。与犀、羚、元参、知母壮水息风，苁蓉、楝实、鼠矢、石英潜阳镇逆，沙参、麦冬、石斛、葳蕤益气充津，花粉、栀子、银花、丝瓜络蠲痰清热。一剂知，四剂安，随以大剂养阴而愈。（眉批：吸食鸦片之人，津液素亏，感受温邪较平人倍重，非此标本并治之剂，必不救矣。）", "14429": "周光远无疾而逝，其母夫人年逾七旬，遭此惨痛，渐生咳嗽，气逆痰咸，夜多漩溺，口苦不饥。孟英曰：根蒂虚而兼怫郁也。与沙参、甘草、麦冬、熟地、龟板、石斛、贝母、蛤壳、小麦、大枣而安。（滋阴解郁，丝丝入扣。）迨夏间，吸暑而患腹痛滞下，小溲热涩，其嗽复作，脉仍虚弦，略加软数。但于前方增滑石，（去暑。）吞香连丸（治痢。）而瘳。因平昔畏药，既愈即停。至仲秋嗽又作，惟口不苦而能食。因于前方去沙参，加高丽参、五味、石英、牛膝，熬膏频服而痊。（眉批：此因不兼外邪，故加五味、牛膝等药，径固其本。）若少兼外邪者，断不可用。十月下旬，天气骤冷，徒患吐泻腹痛，肢冷音嘶，急邀孟英视之。脉微为寒邪直中，亟与大剂理中，加吴萸、橘皮、杜仲、故纸、石脂、余粮而瘥。其夫人亦因悲郁而患崩漏，面黄腹胀，寝食皆废。孟英用龟板、海螵蛸、女贞、旱莲、贝母、柏叶、青蒿、白薇、小麦、茯苓、藕肉、莲子心而康。次年夏，其母夫人患温邪痰嗽，脘闷汗多。孟英投石膏、竹茹、知母、花粉、旋覆、贝母、蒌仁、紫菀等药，三十剂而愈，闻者无不叹异。", "14430": "王小谷体厚善饮，偶患气逆，多医咸从虚治，渐至一身尽肿，酷肖《回春录》所载康副转之证。因恳治于孟英。脉甚细数，舌绛无津，间有讝语。乃真阴欲匮，外候虽较轻于康，然不能收绩矣。再四求疏方，与西洋参、元参、二地、二冬、知母、花粉、茹、贝、竹沥、葱须等药。三剂而囊肿全消，举家忻幸，孟英以脉象依然，坚辞不肯承手，寻果不起。（眉批：脉至细数，则阴竭阳亢，不拘何病，均忌此脉，而虚劳为尤甚。）", "14431": "朱敦书令嫒患感，医投温散，服二剂遍身麻瘄，汛事适来，医进小柴胡汤，遂狂妄莫制，乞援于孟英。脉至洪滑弦数，目赤苔黄，大渴不寐。是瘄因温邪而发，所以起病至今，时时大汗，何必再攻其表？汛行为热迫于营，胡反以姜、枣温之，参、柴升之？宜其燎原而不可遏也。（眉批：温散惟宜于伤寒，何可乱投？且既已见疹，则肺胃之热已现于外矣，与柴胡汤有何干涉？此医直是不通。）与大剂犀角、元参、生地、石膏、知母、花粉、银花、竹叶、贝母、白薇以清卫凉营。服后即眠，久而未醒，或疑为昏沉也。屡为呼唤，（俗情可哂。）病者惊寤，即令家人启箧易服，穿鞋梳发，告别父母云：欲往花神庙归位。（此即一呼唤之效也。）人莫能拦，举家痛哭，急迓孟英复视。脉象依然，嘱其家静守勿哭，仍以前方加重，和以竹沥、童溲，灌下即安。继用养阴清热而愈。", "14432": "高禄卿室，吴濂仲之妹也。孟夏分娩发热，初疑蒸乳，数日不退，产科治之，知挟温邪，进以清解，而大便溏泄，（此邪去之征，识力不坚，遂为所眩。）遂改温燥，其泄不减。另招张某视之，因谓专科误用蒌仁所致，与参、耆、姜、术、鹿角、肉果等药，泄泻愈甚，连服之，热壮神昏，汗出不止，势濒于危。酝香孝廉徐夫人，病者之从母也。心慈似佛，有子十人皆已出，闻其殆，夤夜命四郎季眉，请援于孟英。按脉洪数七至，口渴苔黄，洞泻如火，小溲不行，因谓季眉曰：病犹可治，第药太惊人，未必敢服。季眉坚欲求方，且云在此监服。乃疏白头翁汤，加石膏、犀角、银花、知母、花粉、竹叶、栀、楝、桑叶与之。次日复诊，脉证较减，仍用前方，而病家群哗，以为产后最忌寒凉，况洞泄数日乎？仍招张某商之，张谓：幸我屡投温补在前，否则昨药下咽，顷刻亡阳。（盲语。）复定耆、术之方，业已煎矣。所亲张芷舟孝廉闻之，飞告于酝香处。汾伯昆季，即驰至病家，幸未入口，夺盏倾之，索孟英方，煎而督灌，且嘱群季轮流守视，免致再投别药。孟英感其情谊，快舒所长，大剂凉解，服至七帖，泻全止，热尽退，乃去白头翁汤，加生地、元参、茹、贝。服半月始解黑色燥矢，而眠食渐安。第府藏之邪，虽已清涤，而从前温补，将热邪壅滞于膜络之间者，复发数痈于胸乳之间。孟英令其恪守前法，复入蒲公英、丝瓜络、橘叶、菊叶等药。服至百剂，始告全愈，而天癸亦至。孟英曰：世俗泥于产后宜温之谬说，况兼泄泻，即使温补而死，病家不怨，医者无憾也。或具只眼，其谁信之？此证苟非汾伯昆仲笃信于平时，而力排众论于危难之间，余虽见到不疑，亦恶能有济耶？余尝曰：病不易识，尤不易患；医不易荐，尤不易任；药不易用，尤不易服。诚宇宙间第一难事也，而世人浅视之，可不悲哉！（眉批：方遵古法，并不惊人，特读立斋、景岳书者见之，未免吃惊耳。不意浙省名手狃于温补如此，真不能不归咎于景岳、立斋诸公矣。）", "14433": "赵秋舲进士，去秋患左半不遂。伊弟笛楼，暨高弟许芷卿茂才，主清热蠲痰治之，未能遽效，邀孟英诊之。脉甚迟缓，苔极黄腻，便秘多言。令于药中和入竹沥一碗，且以龙荟、滚痰二丸相间而投。（用药固甚合法，何于脉之迟缓处未见照顾。）二丸各用斤许，证始向愈。（如此而止，殊少善后之法。）今春出房，眠食已复，而素嗜厚味，不戒肥甘。孟夏其病陡发，孟英诊之，脉形滑驶如蛇，断其不起，秋初果殁。", "14434": "吴沄门年逾花甲，素患脘痛，以为虚寒，辄服温补，久而益剧。孟英诊曰：肝火宜清。彼不之信，延至仲夏，形已消瘦，倏然浮肿，胁背刺痛，气逆不眠，心辣如焚，善嗔畏热，大便时泻，饮食下咽即吐，诸医束手，乃恳治于孟英。脉弦软而数。与竹茹、黄连、枇杷叶、知母、栀、楝、旋、赭等药，而吐止，饮食虽进，各恙未已，投大剂沙参、生地、龟板、鳖甲、女贞、旱莲、桑叶、丹皮、银花、茅根、茹、贝、知、柏、枇杷叶、菊花等药，出入为方。二三十剂后，周身发疥疮而肿渐消，右耳出黏稠脓水而泻止。此诸经之伏热，得以宣泄也。仍以此药令其久服，迨秋始愈，冬间能出门矣。）眉批：所见诸证俱属痰热，与弦数之脉相合，但软则根柢不坚。初方乃急则治标之法，次方乃顾及根本，亦不易之次第也。）", "14435": "比邱尼心能，体厚蹒跚，偶患眩悸，医以为虚，久服温补，渐至发肿不饥。仲夏延孟英视之。脉甚弦滑，舌色光绛，主清痰热，尽撤补药。彼不之信，仍服八味等方，至季夏再屈孟英诊之。脉数七至，眠食尽废，不可救药矣。果及秋而茶毗。", "14436": "朱养之令弟媳，初患目赤，服药后，渐至满面红肿，壮热神昏，医者束手。孟英切脉洪实滑数，舌绛大渴，腹微胀。以酒洗大黄、犀角、元参、滑石、甘草、知母、花粉、银花、黄芩、连翘、薄荷、菊花、丹皮，两下之径愈。", "14437": "都城售透土长寿丹，极言其功之大，能治诸疾，而价甚廉，人皆称之。孟英谓：勿论其所用何药，执一方以疗百病，无此治法。每以禀赋不齐，证因有别，劝人切勿轻尝。况以绿豆汤为引，必有热毒之品在内，不可不慎也。继而张孟皋少府饵之患疽，广粤亭司马服之咽烂，孟英投多剂甘寒而愈。王雪山久患下部畏冷，吞未百丸，齿痛目赤，诸恙蜂起。孟英察脉弦滑，与多剂石膏药，兼以当归龙荟丸频服。新疾既瘳，腿亦渐温，令其常饮柿饼汤，以杜将来之恙。伊弟患腹胀而喜服温补，久而不效，孟英曰：湿热也，宜清化。彼不信，因服透土丹，初颇应，已而血大溢，始得悔悟。志此数则，以为世之好服奇药者戒。", "14438": "广孔愚司马之大公子，仲秋间患疟，寒少热多，面目甚黄，苔腻大渴，腹胀溺赤，仍能纳谷，且素嗜肥甘，不能撙节，孟英按其脉滑实而数，与承气加知、芩、半、贝、翘、连、滑石、石膏、大腹、花粉之类。二十余剂而始愈，是膏粱挟暑湿热之治也。", "14439": "王瘦石禀属阴亏，卒闻惊吓之声，而气逆肢冷，自汗息微，速孟英视之。身面皆青绿之色，脉沉弦而细，乃素伤忧虑，而风阳陡动也。与牡蛎四两，鳖甲二两，蛤壳一两，石英五钱，龙齿、小麦、辰砂、麦冬、茯神、贝母、竹茹为方，一剂知，二剂已，续以滋养而瘳。（眉批：凡阴虚之体，血不足以养肝，则肝阳易僭，用大剂镇逆养阴开郁治法，丝丝入扣，宜乎应手辄效也。）", "14440": "陈书伯庶常令弟保和，年未冠，患失音咽痛。孟英与犀、羚、石膏、元参、豆根、牛蒡、射干等大剂清肃之药，音开而咽糜，吹以锡类散，糜愈而疹点满布，左目及耳后皆肿。方中加以鲜菊叶二两。疹愈，痰嗽不已，仍主前法，服三十余帖而痊。此证脉滑且数，口大渴，初终未曾误药，故能愈。其庶母同时患喉糜，而头偏左痛，（肝风。）心悸欲呕，壮热烦躁，脉弦细数。孟英曰：此兼阴亏风动也。初以犀、羚、元参、菊花、丹参、栀子、桑叶、马勃投之，外吹锡类散，咽愈热退。续用二至、二冬、生地、石英、苁蓉、龟板、茯苓，滋阴潜阳而瘳。（善后之法非此，则细数之脉何以能复？）又其二令妹亦患喉疹，汛事适行，四肢酸痛，略难举动，气塞于咽，孟英诊脉弦滑。以犀、羚、旋、赭、茹、贝、兜铃、牛蒡、射干、豆根、花粉、银花、海䖳、竹沥、丝瓜络等出人为方，（此则专事清热蠲痰而已，须合三案而细参其同异处，方有会心。）兼吹锡类散而瘥。（眉批：变证虽多，不外肺胃二经积热，得其主脑，尚非难愈之证。）", "14441": "吴尔纯八月下旬患滞下，腹痛异常，伊外祖许仲廉，延孟英往诊。形瘦，脉数而弦，口渴，音微，溺涩。乃阴分极虚，肝阳炽盛，伏暑为痢。治法不但与寒痢迥异，即与他人之伏暑成痢者，亦当分别用药也。与白头翁汤，加知母、花粉、银花、丹皮、金铃、延胡、沙参、芩、连服之。（亦治通伏暑成痢之方。）次日复视，痢减音开，而右腹疼胀拒按，为加冬瓜子、乌药、鼠矢，三剂而消，滞下亦愈。惟薄暮火升，面赤自汗，重加介类潜阳而痊。（此方顾及阴虚。）", "14442": "杨某患感旬日，初则便溏，医与温散，泻止热不退，昼夜静卧，饮食不进。孟英诊脉迟缓，浮取甚微，目眵，舌色光红，口不渴，溲亦行，胸腹无所苦，语懒音低，寻即睡去。是暑湿内伏，而有燥矢在胃，机关为之不利也。先与清营通胃药二剂。热退舌淡，而脉证依然，加以酒洗大黄、省头草，即下坚黑燥矢甚多，而睡减啜粥。继以凉润，旬日而痊。（眉批：此湿胜于热之暑证也，以其湿胜，故不甚现热证，最足眩人，断为暑湿，足征卓识。）", "14443": "陈春湖令郎子庄，体素弱，季秋患腹痛自汗，肢冷息微，咸谓元虚欲脱。孟英诊之，脉虽沉伏难寻，（痛脉多沉。）而苔色黄腻，口干溺赤，当从证也，与连、朴、楝、栀、元胡、蚕砂、醒头草等药而康。次年患感，复误死于补。又夏酝泉延孟英视钱妪腹痛欲绝证，因见弦滑之脉，与当归龙荟丸而安。", "14444": "朱湘槎令媳，患小溲涩痛，医与渗利，反发热头疼，不饥口渴，夜不成眠。孟英诊之，脉细数，乃阴虚肝郁，化热生风，津液已烁，岂容再利？与白薇、栀子、金铃、知母、花粉、紫菀、麦冬、石斛、菊花，服之即愈。（愈后仍当以滋阴善后。）其侄新泉之室，怀娠患痢，医投温燥止涩，腹痛甚，而遍身发黄，饮食不思。孟英视之：暑湿也。与芩、连、银花、茅根、桑叶、栀、楝、竹叶、茵陈、冬瓜皮而愈。", "14445": "吴酝香大令仲媳，汛愆而崩之后，脘痛发厥，自汗肢冷。孟英脉之，细而弦滑，口苦便涩。乃素体多痰，风阳内鼓，虽当崩后，病不在血。与旋、赭、羚、茹、枳、贝、薤、蒌、蛤壳为方，痛乃渐下，厥亦止。再加金铃、延胡、苁蓉、鼠矢，服之而愈。迨季冬因卒惊发狂，笑骂不避亲疏。孟英察脉弦滑而数，与犀、羚、元参、丹皮、丹参、栀子、菖蒲、竹叶、鳖甲、竹沥，吞当归龙荟丸，息风阳以涤痰热，果数剂而安。然平时喜服补药，或有眩晕，不知为风痰内动，益疑为元气大虚。孟英尝谏阻之，而彼不能从。至次年季春，因伤感而狂证陡发，毁器登高更甚于昔。孟英视之，苔黑大渴，与前方加真珠、牛黄服之，苔色转黄，弦滑之脉略减，而狂莫可制，改以石膏、朱砂、（眉批：凡药中用朱砂者，宜另研冲服，不可同入煎剂。）铁落、菖蒲、青黛、知母、胆星、鳖甲、金铃、旋覆、元参、竹沥为大剂，送礞石滚痰丸，四服而平。继而脚气大发，腹痛便秘，上冲于心，肢冷汗出，昏晕欲厥。与连、楝、栀、茹、小麦、百合、旋、贝、元胡、乌药、雪羹、石英、鼠矢、黄柏、藕等药而安。", "14446": "徐氏妇怀妊患痢，医投温补，胸腹痛极，昏厥咽糜，水饮碍下。孟英诊之，脉洪数，舌绛燥，亟吹锡类散，灌以犀角、元参、海䖳、茹、贝、栀、菀、知、斛、豆根、射干、银花、楝实诸药。胎下已朽，咽腹之疾随愈。续用甘凉清热存津调之。", "14447": "许培之令祖母，年逾七旬，久患淋漏，屡发风斑。孟英持其脉弦而滑，舌绛口干。每以犀角、生地、二至、芩、蒿、白薇、元参、龟板、海螵之类息其暴，甘露饮增损调其常。人皆疑药过凉，孟英曰：量体裁衣，禀属阳旺，气血有余，察其脉色，治当如是。病者乃云：十余年前，偶患崩而广服温补，遂成此恙，始知先天阳气虽充，亦由药酿为病。秋杪患寒热如疟，善怒不眠，苦渴易饥，不能纳食。孟英察脉弦数倍常，与清肺蠲痰、柔肝充液之法，渐以向安。今冬有荐吴古年诊治者，询知病原，作高年脱营论，而以血脱益气裁方。初服三四剂，饮食骤增，举家忻幸，已而血漏甚多，眠食欲废，复延孟英视之，仍主前议，果得渐康。", "14448": "王天成牙行一妇，年五十余，初患左目赤，渐至发热，医投温散，便泄而厥，进以补剂，少腹宿瘕攻痛，势极危殆。丐孟英诊之，脉甚弦软，舌绛而渴。与苁蓉、橘核、当归、元胡、龟板、石英、螵蛸、茯苓、栀、楝、萸、连，数服而安。逾年以他病卒。", "14449": "何新之令爱适汤氏，孟冬分娩，次日便泻一次，即发热痉厥，谵语昏狂，举家皇皇，乃翁邀孟英审之。脉弦滑，恶露仍行，曰：此胎前伏暑乘新产血虚痰滞而发也。与大剂犀、羚、元参、竹叶、知母、花粉、栀、楝、银花投之。遍身得赤疹，而痉止神清，乃翁随以清肃调之而愈。（眉批：有是病则有是药，不拘拘于产后之元虚，此明医之所以异于庸医也。）", "14450": "胡秋谷令爱，年甫笄，往岁患眩晕。孟英切其脉滑，作痰治，服一二剂未愈，更医谓虚，进以补药颇效，渠信为实然。今冬复病，径服补药，半月后，眠食皆废，闻声惊惕，寒颤自汗，肢冷如冰，以为久虚欲脱，乞援于孟英。脉极细数，（阴已伤矣。）目赤便秘，胸下痞塞如柈，力辨其非虚证。盖痰饮为患，乍补每若相安，具只眼者，始不为病所欺也。投以旋、赭、茹、贝、蛤壳、花粉、桑、栀、蒌、薤、连、枳等药，数服即安，而晕不能止，乃去赭、薤、蒌、枳，加元参、菊花、二至、三甲之类。服匝月始能起榻。（眉批：痰火为患，十人常居八九，而医书所载皆治寒痰之法，十投而十不效。今得孟英大阐治热痰之法，真可谓独标精义矣。）", "14451": "汪氏妇自孟秋患痢之后，大解溏泄未愈，已而怀娠，恐其堕也，投补不辍。延至仲冬，两目赤障满遮，气逆碍眠，脘疼拒按，痰嗽不食，苦渴无溺，屈孟英诊之。脉甚滑数，曰：此温补所酿之疾也。夫秋间滞下，原属暑湿热为病，既失清解，逗留而为溏泄。受孕以来，业经四月，虑其堕而补益峻，将肺胃下行之令，皆挽以逆升，是以胸次堵塞而疼，喘嗽不能卧。又恐其上喘下泄而脱也，补之愈力，治节尽废，溲闭不饥，浊气壅至清窍，两目之所以蒙障而瞽也。（眉批：论极透快，说尽庸医之弊。）与沙参、蛤壳、枇杷叶、冬瓜子、海石、旋覆、苏子、杏仁、黄连、枳实、海䖳、黄芩、栀子，重加贝母。服二剂，即知饥下榻，目能睹物矣。", "14452": "许仲筠患腹痛不饥，医与参、术、姜、附诸药，疼胀日加，水饮不沾，沉沉如寐。孟英诊脉弦细，苔色黄腻。投以枳、朴、萸、连、栀、楝、香附、蒺藜、延胡等药。二剂便行脉起，苔退知饥而愈。", "14453": "毕方来室，患痰嗽碍眠，医与补摄，而至涕泪全无，耳闭不饥，二便涩滞，干嗽无痰，气逆自汗。孟英切脉，右寸沉滑，左手细数而弦。乃高年阴亏，温邪在肺，未经清化，率为补药所锢，宜开其痹而通其胃。与蒌、薤、紫菀、兜铃、杏、贝、冬瓜子、甘、桔、旋、茹之剂而安。逾二年以他疾终。（亦少善后之法。）", "14454": "赖炳也令堂，年近古稀，患左半不遂，医与再造丸暨补剂，服二旬病如故。孟英按脉弦缓而滑，颧赤苔黄，音微舌蹇，便涩无痰，曰：此痰中也，伏而未化。与犀、羚、茹、贝、菖、夏、花粉、知母、白薇、豆卷、桑枝、丝瓜络等药。服三剂而苔化，音渐清朗。六七剂腿知痛，痰渐吐，便亦通。既而腿痛难忍，其热如烙，孟英令涂葱蜜以吸其热，痛果渐止。半月后，眠食渐安。二旬外，手能握，月余可扶腋以行矣。", "14455": "赵春山司马，向患痰嗽，自秋仲以来，屡发寒热，吴古年从伏暑化疟治，颇为应手，而一旬半月之后，病必复至，延至季冬，董兰痴鹾尹嘱其质于孟英。按脉滑数，舌绛苔黄，渴饮溲赤，动则喘逆，夜不成眠，痰多畏冷，自问不能起矣。孟英曰：无恐也，不过膏粱酿痰，温补助热，是为病根。迨夏吸暑邪，互相𫐖轕，秋半而发，势颇类疟。古年虽识其证，惜手段小耳，因与羚羊、豆豉、连翘、薄荷、知母、花粉、竹茹、贝母、旋覆、海䖳、元参、栀子、醒头草、梨汁等药。服五剂，热退不畏冷，去前四味，加沙参、麦冬、葳蕤、枇杷叶。渐能安寐，各恙递减，再加生地。服匝月而体健胜昔，登高不喘。司马云：余昔曾服参、茸大补之药而阳痿，今服君方而沉疴顿起，乃知药贵对证，不贵补也。", "14456": "戊申元旦，陈秋槎参军，大便骤下黑血数升，（血为热迫而妄行。）继即大吐鲜红之血，而汗出神昏，肢冷搐搦，躁乱妄言。（心无血养故神昏，肝无血养故痉厥。）速孟英至，举家跪泣救命。察其脉左手如无，右弦软，按之数。（虚在阴分，热在气分。）以六十八岁之年，佥虑其脱，参汤煎就，将欲灌之。孟英急止勿服，曰：高年阴分久亏，肝血大去，而风阳陡动，殆由忿怒，兼服热药所致耶？其夫人云：日来颇有郁怒，热药则未服也，惟冬间久服姜枣汤，且饮都中药烧酒一瓶耳。孟英曰：是矣。以西洋参、犀角、生地、银花、绿豆、栀子、元参、茯苓、羚羊、茅根为剂，冲入热童溲灌之；外以烧铁淬醋，令吸其气；龙、牡研粉扑汗；生附子捣贴涌泉穴，引纳浮阳。两服血止，左脉渐起，又加以龟板、鳖甲。（介以潜阳法。）服三帖，神气始清，各恙渐息，稍能啜粥，乃去犀、羚，加麦冬、天冬、女贞、旱莲投之，眠食日安，半月后始解黑燥矢，两旬外便溺之色皆正，与滋补药调痊，仍充抚辕巡捕，矍铄如常。秋间赴任绍兴，己酉秋以他疾终。", "14457": "姚令舆室，素患喘嗽而病春温，（新旧合邪。）医知其本元久亏，投以温补，痉厥神昏，耳聋谵语，面青舌绛，痰喘不眠，（肺原包心而生，故肺热必及于心。）皆束手矣。延孟英诊之，脉犹弦滑，曰：证虽危险，生机未绝，遽尔轻弃，毋乃太忍。与犀角、羚羊、元参、沙参、知母、花粉、石膏，以清热息风，救阴生液；佐苁蓉、石英、鳖甲、金铃、旋覆、贝母、竹沥，以潜阳镇逆，通络蠲痰。三剂而平。继去犀、羚、石膏，加生地黄。服旬日而愈。仲秋令舆病，竟误服温补，数日而殒，岂非命耶？", "14458": "运粮千总马香谷，患溺秘欲死。所亲赵春山司马，延孟英视之。脉坚体厚，口渴苔黄。投知、柏、栀、楝、犀、菀、蒌、茹之药，送当归龙荟丸而瘳，竟不复发。", "14459": "谢某患嗽，卧难偏左。孟英切其脉，右寸软滑，曰：此肺虚而痰贮于络。以苇茎、丝瓜络、生蛤粉、贝母、冬瓜子、茯苓、葳蕤、枇杷叶、燕窝、梨肉投之，果愈。", "14460": "许叔超令大母患疟，延孟英治之。脉弦滑而数，脘闷便秘，合目汗出，口渴不饥。或虑高年欲脱，孟英曰：此温邪挟素盛之痰所化，补药断不可投，与知、芩、蒌、杏、翘、贝、旋、茹、连、斛、雪羹为方，服果渐效。", "14461": "蒲艾田年逾花甲，陡患鼻衄，诸法不能止，速孟英救之。面色黑黯而有红光，脉弦洪而芤，询知冬间广服助阳药，是热亢阴虚之证。与大剂犀角、元参、茅根、女贞、旱莲、石斛、茯苓、泽泻、天冬、知母，投匕而安。续予滋阴药，填补而康。", "14462": "许少卿室，故医陈启东先生之从女也。夏初患感，何新之十进清解，病不略减，因邀诊于孟英。脉至弦洪豁大，左手为尤，大渴大汗，能食妄言，面赤足冷，彻夜不瞑。孟英曰：证虽属温，而真阴素亏，久伤思虑，心阳外越，内风鸱张，幸遇明手，未投温散，尚可无恐。与龙、牡、犀、珠、龟板、鳖甲、贝母、竹沥、竹叶、辰砂、小麦、元参、丹参、生地、麦冬为大剂投之；外以烧铁淬醋，令吸其气；蛎粉扑止其汗；捣生附子贴于涌泉穴。甫服一剂，所亲荐胡某往视，大斥王议为非，而主透疹之法，真盲人。病家惑之，即煎胡药进焉。病者神气昏瞀，忽见世父启东扼其喉，使药不能下嗌，且嘱云：宜服王先生药。少卿闻之大骇，专服王药，渐以向愈，而阴不易复，频灌甘柔滋镇，月余始能起榻。季夏汛行，惟情志不怡，易生惊恐。与麦、参、熟地、石英、茯神、龙眼、甘麦大枣、三甲等药善其后。（一定不易之法。）秋杪归宁，微吸客邪，寒热如疟。孟英投以清解，已得向安。胡某闻之，复于所亲处云：此证实由夏间治法不善，以致邪气留恋，再服清凉，必死无疑。（眉批：服清解药，致邪气留恋，岂服滋补药邪气反不留恋耶？）此等人而亦自命为医，岂非怪物。汤某复从而和之。许氏即招汤某诊治，（总是病者该死，故一时有此二妖孽。）谓其阳气伤残，沉寒久伏，以理中汤加威灵仙、桂枝、半夏、厚朴、姜、枣等药。（既已沉寒，焉能作寒热，勿论其认证之误与不误，即理中汤亦有此等加减法耶？）病者颇疑药太燥烈，汤复膏吞拭舌，说得天花乱坠，病家惑之。初服胃气倍加，继而痰嗽不饥，黄苔满布，肌消汛断，内热汗多，心悸不眠，卧榻不起。病者坚却其药，然已进二十剂矣。再邀何新之商之，亦难措手，仍嘱其求诊于孟英。按脉弦细软数，篡患悬痈，纵有神丹，不可救药矣。", "14463": "周鹤亭令郎，年甫五龄。痘后月余，清凉药尚未辍，忽发壮热，幼科治之势益张，肢瘈面赤，呕吐苔黄，渴而溺清，时或昏厥，证交六日，其外祖何新之邀孟英诊之。脉甚弦洪滑数，心下拒按，便秘汗多。投小陷胸，加石膏、知母、花粉、竹叶、枇杷叶、贝母、雪羹。二剂各恙皆减，溲赤便行，继与清养而安。（眉批：凉药未辍，而忽见如此之证，即不按脉，亦可知为新感温邪矣。）", "14464": "费伯元分司，患烦躁不眠，医见其苔白也，投以温药，因而狂妄瘛疭，多方不应。余荐孟英视之，左脉弦细而数，右软滑，乃阴虚之体，心火炽，肝风动，而痰盛于中也。先以犀、羚、桑、菊息其风，元参、丹皮、莲心、童溲清其火，茹、贝、雪羹化其痰，两剂而安。随与三甲、二至、磁朱潜其阳，甘麦大枣缓其急，地黄、麦冬养其阴，渐次康复。", "14465": "何搢阶令正，素患肝厥，仲夏患感。沈樾亭按温证法治之，内风不至陡动，而大便泄泻，（泄泻乃湿温应有之证，不足为异。）脉细而弦，渴饮痰多，不饥不寐，因邀孟英商之。投白头翁汤，加三甲、石斛、茯苓、竹茹而安。随以峻补善后而痊。", "14466": "许氏妇患间疟，寒少热多，不饥大渴，善呕无汗，脉滑而弦。孟英投白虎汤，加花粉、柴胡而愈。", "14467": "吴酝香大令四令媳，时患腹胀减餐，牙宣腿痛，久治不效，肌肉渐消，孟英诊脉，弦细而数，肝气虽滞，而阴虚营热，岂辛通温运之可投耶？以乌梅、黄连、楝、芍、栀子、木瓜、首乌、鳖甲、茹、贝，服之果愈。继与甘润滋填，肌充胃旺，汛准脉和，积岁沉疴，宛然若失。", "14468": "顾云萝令正，久患脚气，屡治屡发，驯致周身筋掣，上及于巅，龈痛指麻，腰酸目眩，口干食少，夜不成眠，孟英察其脉芤而弦数。真阴大亏，腿虽痛，从无赤肿之形，脚气药岂徒无益而已。与二地、二冬、二至、知、柏、桑、菊、栀、楝、蒿、薇、龟板、鳖甲、藕等药。服之各恙渐减，盖因平素带下太甚，阴液漏泄，而筋骨失其濡养也，故治病须澄源以洁流。秋间以海螵蛸粉、鱼螵、黄柏、阿胶为丸，服之全愈。", "14469": "石北涯令正，久患龈疼，渐至身面浮肿，或以为虚，或以为湿，病日以剧，气逆不饥。孟英察脉，左洪数，右弦滑，阴分虽虚，先当清其肺胃之痰热者。投白虎加沙参、花粉、冬瓜皮、枇杷叶、栀子、竹茹、芦根。服之肿即消，继佐滋阴，龈疼亦止。", "14470": "金畹香令媳，半产后，营分不摄，淋漓数月，治之弗瘳。孟英于季夏诊视，两尺皆浮，左寸关弦。与三甲、二至、二地、蒿、薇、柏叶、螵蛸、黄柏为方，服之渐愈。仲秋诊其脉，即断受孕。渠谓：怀娠必无病矣，而不知病久初痊，正须培养，虽即受孕，涵蓄无权。果至仲冬而胎堕矣。（眉批：肝主疏泄，肾主闭藏，两尺浮而不沉，是肾失其闭藏之职矣；左寸关弦，是肝木太过，独行其疏泄之权矣。填补肾阴，即以涵养肝木。加黄柏之苦以坚之，螵蛸之涩以固之，用药如法，故收效倍捷。）", "14471": "德清蔡初泉，陡发寒热，咽痛大渴，脘闷舌绛，孟英诊脉甚数。径投大剂犀、羚、元参、丹皮、桑、栀、银花、花粉、翘、蒡之药。服后遍身发赤疹，而热退知饥矣。", "14472": "吴诵青室年近五旬，天癸已绝，偶患腹胀，局医黄某，知其体素羸也，投以肾气汤，而寒热渐作，改从建中法，旬日后病剧而崩，愈补愈甚，乞援于孟英。脉洪而数，渴饮苔黄，是吸受暑邪，得温补而血下漏也。与犀角、元参、茅根、柏叶、栀、楝、知、斛、花粉、白薇等药，数剂始安。续加生地、二至、二冬，滋养而愈。次年患病，仍为误药而殒。", "14473": "阮范书明府令正，患腹痛欲厥，医见其体甚弱也，与镇逆通补之法，而势日甚。孟英察脉弦数左溢，是因忿怒而肝阳勃升也。便秘不饥，口苦而渴。与雪羹、栀、楝、旋、绛、元胡、丹皮、茹、贝，下左金丸而愈。逾年以他疾殁于任所。", "14474": "海盐周子因工于画，体素弱，偶患间疟，黄某用首乌、鳖甲、姜、枣等药，病日甚，加以参、桂，狂躁妄言，始延孟英视之。面赤舌绛，溲涩便溏，渴饮汗多，脉形细数，是暑证也。与元参、银花、知母、芩、茹、贝、竹叶、荷杆、莲心、西瓜衣为剂，寻愈。", "14475": "吴薇客太史令堂，患痰嗽喘逆，便秘不眠，微热不饥，口干畏热，年逾六旬，多药勿痊。孟英切其脉右寸关弦滑而浮，左关尺细软无神，是阴虚于下，痰实于上，微兼客热也，攻补皆难偏任。与茹、贝、旋、斛、浮石、芦根、冬瓜子、枇杷叶、杏仁、花粉为剂，而以熟地泡汤煎服，则浊药轻投，清上滋下，是一举两全之策也。投匕果应，再服而大便行，渐次调养获瘳。戌春患感证，比孟英自江西归，已不能治矣。", "14476": "谢谱香素属阴亏，情志抑郁，因远行持重而患咳逆，左胁刺痛，寸步难移，杳不知饥，卧难著枕，延孟英诊之。脉象弦细软数，苔腻痰黏，便难溲少，乃肾气不纳，肝气不舒，肺气不清，胃气不降。投以沙参、枇杷叶、茹、贝、旋、栀、龟板、鳖甲、丝瓜络、冬瓜子、青铅、白前、金铃、藕肉，而以熟地汤煎服。数剂而平，继渐滋填向愈。", "14477": "叶承恩室，怀妊患感，昏谵不眠，善呕便秘，汗出不解，脉涩口干。乃营阴素亏，邪热内炽。以元参、石膏、知、芩、茹、贝、银花、枇杷叶、薇、栀、楝、斛，投数帖而愈。", "14478": "江梦花如君，患两目肿痛，不能略张，医投风药，昏痉欲厥，浼孟英诊之。脉至洪滑，大渴便秘。与白虎汤，二剂霍然。", "14479": "吴西瀍患疟，寒微热甚，旬余不愈。孟英诊之，脉滑而长，疏大剂白虎汤与之。渠兄濂仲云：沈、顾二君皆主是方，屡服无效。孟英索方阅之，汤虽白虎，而石膏既少且煨，兼不去米，因谓其兄曰：汤虽同，君药已重用，而去米加花粉、竹茹等，其力不同科矣。濂仲大悟，服之寻愈。此可以见服药不可徒有汤头之名也。", "14480": "曹稼梅令爱，患眩晕脘痛，筋掣吐酸，渴饮不饥，咽中如有炙脔。朱某与温胃药，病日剧。孟英诊脉弦滑，投茹、贝、萸、连、旋、赭、栀、楝、枳、郁、雪羹之药，（和肝开郁清痰。）十余剂始愈。", "14481": "夏氏妇怀娠患感，医投温散，渐至气冲不寐，时欲痉厥，脘闷呻吟，渴难受饮。所亲张养之延孟英诊之，脉滑数而溢。与小陷胸，加旋、薤、石膏、知、栀、茹、杏、腹皮、苏子、竹沥、海䖳大剂，投旬日而愈。设用轻浅之方，焉克有济耶？", "14482": "沈悦亭令正齿衄，五日不止，去血已多，诸方不应，孟英脉之弦滑上溢。投犀角、泽兰、元参、旋覆、生地、花粉、茯苓、牛膝、桃仁、泽泻而安。既而询其经事，本月果已愆期，盖即逆行之候也。继用滋阴清热，乃渐康复。", "14483": "王雪山于上年误饵透土丹之时，孟英诊治向愈，即嘱其常饮柿饼汤，以杜关格于将来。迨今四月间，形体日瘦，张某进以导湿疏风补气之药。孟英偶见之，力劝其温补莫投，且以凡物遇火则干瘪，得滋则肥润为譬。雪山深韪之，奈为张某辈朝夕虚言所眩，仍服补剂。延至秋间，始延孟英视之。胁痛畏风，周身络胀，时欲敲扑，食少便难，日晡微有寒热，脉来弦涩而数，右寸关弦软以滑，是升降之令久窒，痰邪袭于隧络，关格之势将成。（将断语与脉证合参，便知审病之法。）再四求治，与沙参、茹、贝、薇、蒿、旋、斛、栀、楝、兰草、枇杷叶、丝瓜络、冬瓜子、芦根、茅根等，出入为方。服之寒热既蠲，胁痛亦减。雪山大喜，复请诊之。脉颇转和，第肝阴久为谋虑所伤，最怕情志不怡，必生枝节，小愈奚足为恃？嘱其另邀明眼图之。渠即招沈辛甫、顾听泉、吴卯君、任心柏诸君商之，方案皆与孟英相合。雪山转恳孟英设法，且云：读君之案，洞彻病情，侥幸成全，足感再生之德，即使无效，我亦瞑目而亡。孟英感其言，殚竭心力，以图久延，无如嗔怒索思，诸多枨触，频有转关，屡生枝节，大便必极槌背尻而始解，上则吐痰恶谷，果成关格之候。肩至伊子旋杭，惑于谗言，翻以竹茹、竹沥为药性太凉，而以不用温补为谤，求乩方，径以麻黄、细辛、鹿角等药投之，遂至舌色干紫，津涸而亡。不知者未免以成败论，所谓道高谤多。然柿饼汤投于年余未病之前，其卓见已不可及，而见危受命，勉力图维，肠热心孤，更可钦也。特采其案，以为世之有识者鉴焉。（眉批：此证即叶氏所谓下竭上结之候也，叶氏虽有方案，亦未知果能取效否？不知古名家遇此当作何治法？方书中迄无论及者。孟英此案，已是开人不敢开之口，至其悉当病情与否，则殊未敢轻论也。）", "14484": "徐梦香年近六旬，患手颤不能握管，孟英以通补息风药，吞指迷茯苓丸而安。仲秋类中，遗溺痰升，昏瞀妄言，汗多面赤，急延孟英视之。脉浮弦洪滑，盖吸受热邪，而连日适服参汤也。与羚羊角、石菖蒲、连翘、栀子、桑叶、菊花、楝、斛、知母、花粉、竹沥、银花、蒿、薇等药。一剂知，二剂神清，乃去羚、菖，加茹、贝、滑石投之。下利赤白如脓垢者数日，始知饥纳谷，渐以调理而愈。匝月即能作画，季秋仍幕游江右。", "14485": "张月波令弟，陡患腹痛，适饱啖羊肉面条之后，医皆以为食滞，连进消导，痛甚而渴，得饮大吐，二便不行。又疑寒结，叠投燥热，其病益加，呻吟欲绝，已四日矣。孟英视之，脉弦数，苔干微黄，按腹不坚，以海䖳一斤，凫茈一斤，煎汤频灌，果不吐，令将余汤煎栀、连、楝、斛、茹、芩、枇杷叶、知母、延胡、柿蒂、旋覆为剂，吞龙荟丸。投匕而溲行痛减，次日更衣而愈。", "14486": "黄鼎如令堂，年七十七岁，季秋患间疟，每发加剧，寒甚微而热必昏痉，舌不能伸，三发之后，人皆危之。孟英视之，颧赤目垂，鼻冷额颏微汗，苔色黄腻，舌根纯红，口渴痰多，不思粥饮，脉至弦数，重按少神。证属伏暑挟痰，而阴虚阳越，先与苁蓉、鳖甲、楝、斛、茹、贝、燕窝、藕，两剂而颧红颏汗皆蠲。继佐参、沥、薤、麦、枇杷叶、旋覆，去竹茹、苁蓉。投三帖而昏痉不作，又去薤、楝，加生地、花粉。服五日而疟休，饮食渐加，居然告愈。方疟势披猖之际，鼎如、上水两昆仲，颇以为忧，延诸名家议治。有主人参白虎汤者，有用犀角地黄汤者，有欲大剂温补者，有执小柴胡加减者，赖孟英力排众议，病家始有把握。与孟英意见相合者，何君新之也，怂恿参赞，与有功焉。", "14487": "许芷卿患外寒，须覆重衾，内热，饮不解渴，仍能安谷，便溺皆行。或以为虚寒，或以为疡患，投以温散，即显咽疼。孟英脉之，沉弦而缓，作痰热内伏。投以犀、羚、元参、丹皮、白薇、黑栀、茹、贝、旋、蒡之剂，两帖而寒渴咽疼皆减，乃去犀、羚、牛蒡，加二至、知母、花粉、银花，解酱矢而瘳。", "14488": "韩组林年近古稀，孟冬患肢厥头肿，讝语遗溺。包某作虚风类，进以温补，势益剧。孟英脉之，脉弦数，右滑溢，乃痰热内阻，风温外侵。与羚、贝、茹、栀、翘、薇、桑、菊、丹皮、花粉、旋覆，以芦菔汤煎服而瘳。", "14489": "钱闻远仲郎患感，汤某进桂、朴、姜、柴等药，而痰血频咯，神瞀耳聋，讝语便溏，不饥大渴，苔黑溲少，彻夜无眠。范应枢、顾听泉叠进轻清，黑苔渐退，舌绛无津，外证依然，不能措手。孟英诊之，脉皆细数，乃真阴素亏，营液受烁，不必以便溏不食，而畏滋腻也。授以西洋参、生地、二至、二冬、龟板、燕窝、茹、贝、银花、藕汁、梨汁、葳蕤、百合等药。二剂咯血渐止，痰出甚多，渐进稀糜，夜能稍寐。五剂热退泻止，渴始减，脉渐和，旬日后，解燥矢而痊。", "14490": "朱湘槎令郎留耕，忽于饱食后大吐而厥，冷汗息微，急延孟英视之。厥甫回而腹痛异常，口极苦渴，二便不行，脉来弦缓，乃痰滞而热伏厥阴，肝气无从疏泄也。投雪羹、栀、楝、元胡、苁蓉、萸、连、橘核、旋覆、竹茹、菔汁之药。一剂痛减，再服便行而愈。", "14491": "韩妪年近花甲，患三疟于仲冬。朱某主温散，并以姜枣汤恣饮，旬日后粒米不沾，疟至大吐。黄某以热补进，势益甚。又浃旬，孟英视之，胸中痞结如柈，苔黄苦渴，溲如热汤，脉弦滑右甚，带下如注，投小陷胸合温胆，加薤白。服后大吐胶痰，十余日胸痞始消，改授甘凉，疟亦渐罢。递参滋阴，遂以霍然。", "14492": "魏西林令侄女，娩后恶露延至两月，继闻乃翁条珊主政及两弟卒于京，悲哀不释，而为干嗽吐血，头痛偏左，不饥不食，不眠不便，渴饮而溲，必间日一行，久治不效。孟英切脉，虚弦豁大。与甘麦大枣，加熟地、首乌、鳖甲、二至、菊花、旋覆、芍药、贝母、麻仁、青盐等药，服后脉渐敛，血亦止。七八剂头疼始息，旬日后便行安谷。逾年接柩悲恸，血复溢，误投温补而亡。", "14493": "韩石甫大令令正，患感发疹。沈悦亭治以清解，热渐退而神气不爽，舌黑难伸，太息便秘，胸次拒按，脉弦缓而滑。投凉隔散，加知母、花粉、枳实、竹茹。一帖而苔即退黄，再服而黑矢下，神气清，即以向愈。", "14494": "陈赤堂令正患感，面赤不眠，烦躁谵语，口甘渴腻，溲涩而疼，顾听泉多剂清解未应。孟英切其脉，左弦洪而数，右滑而溢，胸次痞结，大解未行，肝阳上浮，肺气不降，痰热阻痹，邪乃逗留。与小陷胸，合温胆、雪羹，加旋、薤投之。胸结渐开，乃去半、薤，而送当归龙荟丸。谵语止，且能眠，参以通幽汤下其黑矢。三次后始进养阴和胃而痊。", "14495": "屠某患梦遗，久治不愈，耳出脓水，目泪难开，肩胁胸背酸疼，微有寒热，食减神疲。孟英察脉左弦数，右虚软。以三才封髓，加龙、牡、黄耆、桑、丹、栀、菊，旬日而瘳。", "14496": "李华甫令正患头震，孟英脉之弦滑，乃肝经郁怒火升也。投当归龙荟丸而瘥。然不能惩忿，其病屡发之后，更兼溺秘腹胀，喘汗欲绝，亟邀孟英视之。脉甚弦涩，口苦苔黄，舌色紫黯，汛虽不愆，内有瘀滞也。以雪羹加金铃、旋覆、栀子、滑石、桃仁、茺蔚、车前子、木通，仍吞龙荟丸，外以田蠃、大蒜、车前草捣贴脐下。服后果先下黑血，溲即随通，继而更衣，粪色亦黑，遂愈。", "14497": "己酉春，胡孟绅山长患疑，坐卧不安，如畏人捕，自知为痰，饵白金丸吐之，汗出头面，神躁妄闻。（撩动其猖狂之势。）孟英切其脉，弦滑洪数，不为指挠。投石膏、竹茹、枳实、黄连、旋覆、花粉、胆星、石菖蒲，加雪羹、竹沥、童溲，吞礞石滚痰丸。下其痰火，连得大解，夜分较安，惟不能断酒，为加绿豆、银花、枳椇子，吞当归龙荟丸。旬余脉证渐平，神气亦静，尚多疑惧。改授犀角、元参、丹皮、竹叶、竹茹、贝母、百合、丹参、莲心、猪胆汁炒枣仁、盐水炒黄连，吞枕中丹，以清包络肝胆之有余而调神志。又旬日，各恙皆蠲，即能拈韵，继与十味温胆法善其后。乃弟季权，同时患黑斑苔秽，脉浑气粗面垢，孟英即以凉膈散投之。大解得行，脘亦不闷，斑皆透绽，脉显滑数而洪，遂与大剂凉润清肃之药。直俟其旬日外，大解不泻，药始缓授。复又沉卧不醒，人皆疑之。孟英曰：痰热尚炽也。仍投大剂数帖，果频吐胶痰累日，而眠食渐安。是役也，当两病披猖之际，举家皇皇，他医或以前证为神不守舍，议投温补，后证则以为必败，闻者无不危之，赖季权之夫人，独具卓识，任贤不贰，孟英始无掣肘之虑，而咸得收功也。", "14498": "许芷卿亦精于医，偶患外感，即服清散之药，而证不减，或疑其非春温也，邀孟英质之。诊脉迟涩，二便皆行，筋掣不眠，畏寒能食，喉舌皆赤，（血热之征。）与大剂清营药，数服而瘥。迨夏两腿患疥，外科治之，久而不愈。孟英谓：其平昔善饮，蕴热深沉，疡科药亟宜概屏。令以雪羹汤送当归龙荟丸，果得渐瘳。秋间其太夫人患感，连服温散，转为肢厥便秘，面赤冷汗，脉来一息一歇，（肢厥而便秘面赤，可决其非脱证矣。）举家惶惶，虑即脱变。孟英视其苔黄腻不渴，按其胸闷而不舒，且闻其嗅诸食物，无不极臭。断为暑湿内伏，挟痰阻肺，肺主一身之气，气壅不行，法宜开降，是虚脱之反面也。设投补药，则内闭而外脱，昧者犹以为投补迟疑而不及救，（世之愈补愈虚，以至于脱者，大半由此。）孰知真实类虚，不必以老年怀成见，总须以对证为良药。果一剂而脉至不歇，转为弦滑。再服汗止肢和，便行进粥，数帖而痊。方用紫菀、白前、竹茹、枳实、旋、贝、杏、蒌、兜铃、枇杷叶也。", "14499": "沈辛甫善轩岐之学，其令正体素弱而勤于操作，年逾四秩，汛事过多，兼以便溏，冷汗气逆，参、耆屡进，病日以危。孟英诊曰：心脾之脉尚有根，犹可望也。与龙骨、牡蛎、龟板、鳖甲、海螵蛸、石英、石脂、余粮、熟地、茯苓为方。一剂转机，渐以向愈。（眉批：亦下虚而误补其上者，应补之证，补不如法，尚且致害，况不应补而补者乎？）", "14500": "胡韵梅年已逾冠，因夜坐感寒，患头疼恶冷，呕吐肢冷。孟英视之，曰：舌绛脉数，斑疹之候，断非受寒也。幸胡平昔钦信，遂与清透药服之，次日点形圆绽，细询果未出痘，但火势甚炽，恐其惑于俗论，嘱请专科王蔚文会诊。所见略同，一路清凉，自起发至落痂，毫不杂一味温升攻托之药，而满身密布形色粗紫，浆浓痂黑，便秘不饥，渴无一息之停。苟不如是用药，其能免乎？此建中《琐言》之所以有功于世也。（眉批：此大实之证，故治宜如此。予见一小儿出痘，自始至终，参、茸不辍于口，稍停其药，即恹然不振，正与此案相对待。可见用寒用热，皆宜随证变通，未可执一而论也。）", "14501": "朱养心后人名大镛者，新婚后神呆目瞪，言语失伦。或疑其体弱神怯，与镇补安神诸药，驯致善饥善怒，骂詈如狂。其族兄已生邀孟英诊之，右脉洪滑。与犀角、石膏、菖蒲、胆星、竹沥、知母，吞礞石滚痰丸而愈。其大父患四肢冷颤，常服温补，延久不痊。孟英切其脉弦而缓，曰：非虚也。与通络方，吞指迷茯苓丸而瘥。", "14502": "许安卿患咽痛，疡科黄秀元连与升散之药，延及龈肿，牙关不开，舌不出齿，自汗脉涩，绝谷濒危。其族兄辛泉，逆孟英往勘。即洗去满颈敷药，而以菊叶捣涂，吹以锡类散，煎犀、羚、元参、射干、马勃、栀、贝、山豆根等药灌之，数日而痊。（眉批：宜降而反升之，宜其病之增剧也。）", "14503": "庄芝阶舍人三令媳患搐搦，间日而作。孟英诊脉弦数，泛泛欲呕，口苦不饥，凛寒头痛，汛事愆期，溲热如火，乃厥阴暑疟也。投以大剂犀、羚、元参、栀、菊、木通、知、楝、花粉、银花之药，数日而愈。", "14504": "仲夏淫雨匝月，泛滥为灾，季夏酷暑如焚，人多热病。有沈小园者，患病于越。医者但知湿甚，而不知化热，投以平胃散数帖，壮热昏狂，证极危殆，返杭日，渠居停吴仲庄，浼孟英视之。脉滑实而数，大渴溲赤，稀水旁流。与石膏、大黄数下之而愈。仲庄欲施药济人，托孟英定一善法。孟英曰：余不敢师心自用，考古惟叶天士甘露消毒丹、神犀丹二方，为湿温、暑疫最妥之药，一治气分，一治营分，规模已具，即有兼证，尚可通融，司天在泉，不必拘泥。今岁奇荒，明年恐有奇疫，但「甘露」二字，人必疑为大寒之药；「消毒」二字，世人或误作外证之方，因易其名曰普济解疫丹，吴君与诸好善之家，依方合送，救活不知若干人也。", "14505": "姚禄皆在金陵，适遇大水，继而回杭，途次酷热患感。顾某诊为湿邪，与桂枝、葛根药三帖，病乃剧。赵笛楼知其误治，连用清解，因见蓝斑，不肯承手。迓孟英视之，脉细数而体瘦，平昔阴亏，热邪藉风药而披猖，营液得温燥而干涸，斑色既绀，危险万分。勉投大剂石膏、知母、白薇、栀子、青蒿、丹皮、竹叶、竹沥、童溲之药，调以神犀丹。三服大解下如胶漆，斑色渐退，而昏狂遗溺，大渴不已，仍与前方，调以紫雪，数剂热退神清，而言出无伦，犹如梦呓，或虑其成癫，孟英曰：痰留包络也。与犀角、菖蒲、元参、鳖甲、花粉、竹茹、黄连、生地、木通、甘草为方，调以真珠、牛黄，始得渐安。改授存阴，调理而愈。", "14506": "陈蕴泉陡患昏谵，夤夜乞诊于孟英。脉甚滑数，苔色腻黄，乃平素多痰，兼吸暑热。与清解药一剂，化而为疟，脉亦较平。或谓其体弱，不宜凉药，须用人参。渠家惶惑，孟英坚持以为不可。盖暑脉颇类乎虚，而痰阻于肺，呼吸不调，又与气虚短促者相似。平昔虽虚，有病必先去病，况热能伤气，清暑热即所以顾元气也。（眉批：暑证人多不识此二层，昔人虽曾论及，而无此明晰。）何新之亦赞是议。遂连投白虎加减而愈。次年春因丧妾悲悼，复感温邪，失于肃清，病日以甚，迨孟英自豫章归诊，已不救药矣。", "14507": "高若舟庶母患脱肛，孟英脉之弦而滑，溲涩苔黄。虽属高年，非虚证也。清其湿热而痊。", "14508": "谢再华请孟英治乍浦人滞下证，昼夜百余行，不饥不渴，而欲呕，腹痛上及于心胸，切其脉颇平和，是寒湿也，与时行暑湿痢大相径庭。投姜、桂、萸、朴之剂，数服霍然。", "14509": "赵子善患疟，畏冷不饥。孟英诊之，脉滑数，苔黄溲赤，脘闷善呕。投竹叶石膏汤加减，以清伏暑而痊。", "14510": "王一峰次郎患疟，多服姜、枣温散之药，因致壮热耳聋，谵语殿屎，不寐昏狂，见人欲咬。顾听泉从伏暑治亦不效，延至初冬，吴爱棠嘱其求诊于孟英。按脉皆滑，即以顾疏犀角等药内，加菖蒲、胆星、竹沥、珍珠、牛黄为剂，吞白金丸。（大驱风痰，极为合法。）一服即减，旬日霍然。继其令堂发热善呕，频吐黏沫，头疼如劈，口苦耳聋，神识昏瞀，脉弦而数。乃伏暑挟内风之鸱张。与犀角、元参、竹茹、花粉、知、翘、苓、斛、栀、菊、雪羹等药，七日而瘳。", "14511": "王子能参军令正，久患吐血，医不能愈，延孟英视之。脉弦滑而搏指，右手较甚，渴喜冷饮，米谷碍于下咽，小溲如沸，夜不成眠，久服滋阴，毫无寸效。孟英以苇茎汤合雪羹，加石膏、知母、花粉、枇把叶、竹茹、旋覆、滑石、梨汁，大剂投三十剂而痊。继而参军旋省，患久积忧劳，真阴欲匮，竟难救药，寻果仙游。", "14512": "高瑞生令弟，疟久不痊，形消不食，医谓虚也，投补药而更增自汗。孟英诊之，脉弦滑，脘下聚气。投小陷胸，加竹茹、旋、枳，以开痰结，渐能纳谷。继以清养，病去肌充。", "14513": "张箎伯纪纲李贵，患感数日，忽然昏厥，比沿途追求孟英往视，业已薄暮。主人谓：自朝至此，一息奄奄，恐不及灌药矣，实不便屈诊。孟英曰：余既来，且视之。见其面色灰黯，戴眼口开，按其脉尚不绝。与菖蒲、胆星、竹茹、旋覆等为剂，和入童溺、调以牛黄至宝丹灌之，复杯而起。", "14514": "吴酝香大令宰金溪，自春仲感冒而起，迨夏徂秋，痰多气逆，肌肉消瘦。延至初冬，诸证蜂起，耳鸣腰痛，卧即火升，梦必干戈，凛寒善怒。多医咸主补虚，迄无小效，卧理南阳，已将半载。群公子计无所施，飞函至家，嘱大公子汾伯，副车叩求孟英来署，已冬仲之杪日矣。诊脉弦细，而左寸与右尺甚数，右寸关急搏不调，且病者颈垂不仰，气促难言，舌黯无苔，面黛不渴。孟英曰：病虽起于劳伤挟感，而延已经年，然溯其所自，平昔善饮，三十年来期在必醉，非仅外来之客邪，失于清解，殆由内伏之积热，久锢深沉，温补杂投，互相煽动，营津受烁，肉削痰多，升降愆常，火浮足冷，病机错杂，求愈殊难。既承千里相招，姑且按经设法。以石膏、知母、花粉、黄芩等清肺涤痰，青蒿、鳖甲、栀子、金铃等柔肝泄热，元参、女贞、天冬、黄柏等壮水制火，竹茹、旋覆、杷叶、橘红等宣中降气，出入为方，间佐龙荟丸，直泻胆经之酒毒，紫雪丹搜逐隧络之留邪。服三剂而舌布黄苔，蕴热渐泄。服六剂而嗽减知饥，渴喜热饮，伏痰渐化。季冬八日，即能出堂讯案。十剂后凛寒始罢，足亦渐温，肺气已得下降。望日出署行香，继而兵火之梦渐清，夜亦能眠，迎春东郊，审结积案，亦不觉其劳矣。方中参以西洋参、生地、麦冬充其液，银花、绿豆、雪羹化其积。至庚戌岁朝，各处贺年，午后护日，极其裕如，且肌肉渐丰，面黑亦退，药之对病，如是之神。调养至开篆时，起居如旧，各恙皆瘥，而孟英将赴宜黄杨明府之招，酝香为录其逐日方案，跋而蚨之，兹特采其大略如此。（眉批：酝香之证，予于五月间曾为一视，知其感受温邪，投以清解。三服后颇觉轻减，又以赴饮而病复如故，然步履尚无恙也。后乃惑于温补之说，熟地、鹿胶等腻滞之药，恣服不辍，比孟英至而其势已棘，虽逐渐清解，大势向愈，然病久元虚，邪去而正亦随之，此所以终于不起也。）", "14515": "定州杨素园明府宰宜黄，吏治有声，精于医学。其夫人多病，自治不痊。毗陵吴子和，嘱其函恳酝香，屈孟英诊视。而孟英因母老，急欲旋里，坚辞不往，即据来信所述病状，拟方立案云：细阅病原，证延二十余年，始因啖杏，生冷伤乎胃阳，肝木乘虚，遂患胁疼挛掣，身躯素厚，湿盛为痰，温药相投，是其效也。驯致积温成热，反助风阳，消烁胃津，渐形瘦削。而痰饮者，本水谷之悍气，缘肝升太过，胃降无权，另辟窠囊，据为山险。初则气滞以停饮，继则饮蟠而气阻，气既阻痹，血亦愆其行度，积以为瘀。前此神术丸、控涎丹之涤饮，丹参饮、桃核承气之逐血，皆为杰构，已无遁情。迨延久元虚，即其气滞而实者，亦将转为散漫而无把握矣。是以气升火浮，颧红面肿，气降火息，黄瘦日增，苟情志不怡，病必陡发，以肝为刚脏，在志为怒，血不濡养，性愈侜张。胃土属阳，宜通宜降，通则不痛，六腑以通为用，更衣得畅，体觉宽舒，是其征也。体已虚，病似实，虚则虚于胃之液，实则实于肝之阳。中虚原欲纳食，而肝逆蛔扰欲呕，吐出之水已见黑色，似属胃底之浊阴，风鼓波澜，翻空向上，势难再攻。承示脉至两关中取似形鼓指，重按杳然。讵为细故，际此春令，正鸢飞鱼跃之时，仰屋图维，参彻土绸缪之议，是否有当，仰就斤绳。", "14516": "上拟方案，来差星夜赍回，于十六日到宜。素园读案狂喜，以为洞见脏腑，必欲孟英一诊，以冀霍然。遂夤夜备舆，专丁持函，求孟英暂缓归期。酝香笃于寅谊，再四劝驾，并嘱四令郎季眉偕行。孟英迫于情不可却，二十二日抵宜署。初诊案云：证逾二十年，右胁聚气，有升无降，饮阻不宣，呕逆减餐亦将半载，二便非攻不畅，容色改换不常，吐苦吞酸，苔黄舌绛，渴喜冷饮，畏食甘甜，甘能缓中，冷堪沃热，病机于此逗露，根深难即蠲除，标实本虚，求痊匪易。据述脉亦屡迁，似无定象，夫既流善幻，显属于痰，兹按脉左缓滑，右软迟，两尺有根，不甚弦涩，是汛愆因乎气阻，尚非阴血之枯。春令肝木乘权，胃土久受戕克，病已入络，法贵缓通，通则不痛，腑以通为补，法虽时变，不能舍通字以图功，布鼓雷门，诸希教正。", "14517": "再诊：左脉如昨兼弦，右寸亦转缓滑，中脘气渐下降，二便欲解不行，盖升降愆常，枢机窒涩，由乎风阳浮动，治节横斜，肺既不主肃清，一身之气皆滞也。轻可去实，先廓上游。", "14518": "三诊：脉来较静，小溲渐行，虽未更衣，已能安谷，浊得下降，导以清通。", "14519": "四诊：腿凉便滞，气少下趋，颧面时红，火炎上僭，两胁较热，络聚痰瘀。叠授清宣，更衣色黑，噫气渐罢，酸水不呕，纳谷颇增，脉稍和缓，法仍缓导，冀刈根株。", "14520": "五诊：各恙皆减，眠食渐安，火犹易升，头疼面赤，颊酸结核，胁热未蠲，脉渐柔和，且参清养。", "14521": "余侄森伯患发热面赤，渴而微汗，孟英视之，曰：春温也，乘其初犯，邪尚在肺，是以右寸之脉洪大，宜令其下行，由腑而出，则即可霍然。投知母、花粉、冬瓜子、桑叶、杷叶、黄芩、苇茎、栀子等药，果大便连泻极热之水二次，而脉静身凉，知饥啜粥，遂痊。设他人治之，初感总用汗药，势必酿成大证。", "14522": "谢谱香素体阴虚，忽患环跳穴痛，始而下及左腿，继而移于右腿，甚至两足转筋，上冲于腹间，或痛自乳起，下注于髀，日夜呼号，肢冷自汗，略难反侧。医见其血不华色，辄投补剂，迨仲春孟英自江西归诊，脉弦软微滑，畏热知饥，溲短便坚，舌红不渴，乃阴虚而痰气滞于厥阴也。以苁蓉、鼠矢、竹茹、丝瓜络、橘核、茴香汤炒当归、吴萸汤炒黄连、川椒汤炒乌梅、延胡汤炒楝实、海䖳、凫茈为剂。一服即减，数啜而安。继与虎潜加秦艽而起。", "14523": "陈建周令郎患春温，初起即神气躁乱，惊惧不眠，两脉甚数。孟英谓：温邪直入营分也。与神犀丹，佐紫雪，两剂而瘥。夏间吴守旃暨高若舟令郎，胡秋纫四令爱，患温，初起即肢瘛妄言，神情瞀乱，孟英皆用此法，寻则霍然。世人每执汗解之法，为初感之治，孰知病无定体，药贵得宜，无如具眼人稀，以致夭枉载道，归诸天数，岂尽然哉？", "14524": "鲍继仲于季春望日，忽然发冷，而喘汗欲厥，速孟英视之。脉沉弦而软滑带数，是素患痰饮，必误服温补所致也。家人始述：去冬服胡某肾气汤，颇若相发，至今久不吐痰矣。孟英曰：病在肺，肺气展布，痰始能行，虽属久病，与少阴水泛迥殊，辨证不明，何可妄治？初服颇若相安者，方中附、桂刚猛，直往无前，痰亦不得不为之辟易；又得地黄等厚浊下趋之品，回护其跋扈跳梁之性。然暴戾之气久而必露，柔腻之质，反阻枢机，治节不伸，二便涩少，痰无出路，愈伏愈多，一朝卒发，遂壅塞于清阳升降之路，是以危险如斯，须知与少阴虚喘，判分霄壤，切勿畏虚妄补。投以薤、蒌、枳、杏、旋、赭、橘、半、菀、茹、芦根、蛤粉、雪羹之剂而平。继与肃清肺气而涤留痰，匝月始愈。", "14525": "王皱石广文令弟患春温，始则谵语发狂，连服清解大剂，遂昏沉不语，肢冷如冰，目闭不开，遗溺不饮，医皆束手。（眉批：此正吴氏所谓凉药无涤秽之功，而反冰伏其邪也。）孟英诊其脉弦大而缓滑，黄腻之苔满布，秽气直喷。投承气汤，加银花、石斛、黄芩、竹茹、元参、石菖蒲。下胶黑矢甚多，而神稍清，略进汤饮。次日去硝、黄，加海䖳、芦菔、黄连、石膏。服二剂而战解肢和，苔退进粥，不劳余力而愈。继有张镜江邀治叶某，又钱希敏之妹丈李某，孟英咸一下而瘳。惟吴守旃之室暨郑又侨，皆下至十余次始痊。今年时疫盛行，医多失手，孟英随机应变，治法无穷，救活独多，不胜缕载。（眉批：吴又可之法切于疫，而不甚切于温，观此可见。）褚芹香女校书，患汛愆寒热，医以为损，辄投温补，驯致腹胀不饥，带淋便秘，溲涩而痛。孟英诊脉弦劲而数，乃热伏厥阴，误治而肺亦壅塞也。与清肃开上之剂，吞当归龙荟丸两服，寒热不作而知饥，旬日诸恙悉安。", "14526": "闻氏妇孟夏患间疟，而妊身八月，数发后热炽昏沉，腰疼欲堕，张养之嘱援于孟英。脉来洪滑且数、苔色黄腻垢浊。与黄芩、知母、竹茹、竹叶、银花、桑叶、丝瓜络、石斛、石膏、石菖蒲，一剂而痊。眉批：案中所载多温疟、暑疟，故治多凉解。疟症多端，寒热俱有，不可执一而论。此证亦温疟也。", "14527": "朱佳木令尊患间疟，年逾七旬，人颇忧之。孟英切脉弦滑，脘闷苔黄，曰：无恐也。投清热涤痰药，数剂霍然。", "14528": "李明府令正，年逾花甲，素患痰嗽，近兼晡热不饥，头疼不食，医治罔效，姚小荷荐孟英视之。脉滑数，乃痰火内伏，温热外侵。投石膏药二服，而热退知饥。又数剂，并宿恙而愈矣。", "14529": "翁嘉顺之妇弟吴某，劳作之后，发热身黄，自以为脱力也。孟英察脉软数，是湿温重证，故初起即黄，亟与清解。大便渐溏，小溲甚赤，湿热已得下行，其热即减，因家住茅家埠，吝惜舆金，遽尔辍药。七八日后复热，谵语昏聋，抽痉遗溺，再恳孟英视之，湿热之邪扰营矣。投元参、犀角、菖蒲、连翘、竹茹、竹叶、银花、石膏，泄卫清营之法，佐牛黄丸、紫雪丹而瘳。臀皮已塌，亟令贴羊皮金，不致成疮而愈。", "14530": "李德昌之母，仲夏患感，医诊为湿，辄与燥剂，大便反泻，遂疑高年气陷，改用补土，驯致气逆神昏，汗多舌缩，已办后事，始乞诊于孟英。脉洪数无伦，右尺更甚。与大剂犀角、石膏、黄芩、黄连、黄柏、知母、花粉、栀子、石斛、竹叶、莲心、元参、生地之药，另以冷雪水调紫雪，灌一昼夜，舌即出齿，而喉舌赤腐，咽水甚痛，乃去三黄，加银花、射干、豆根，并吹锡类散。三日后脉证渐和，稀糜渐受，改授甘凉缓剂，旬日得坚黑矢而愈。", "14531": "余朗斋形瘦体弱，患间日疟，寒少热多，二便涩滞，脘膈闷极，苔腻不渴。孟英切脉缓滑而上溢，曰：素禀虽阴亏，而痰湿阻痹，既不可以提表助其升逆，亦未宜以凉润碍其枢机。投以滑、朴、茹、旋、通草、枇杷叶、苇茎、郁金、兰叶之方。苔色渐退，即去朴、郁，加连、枳、半夏。胸闷渐开，疟亦减，便乃畅，再去滑、半、连、枳，加沙参、石斛、橘皮、黄芩，浃旬而愈。（眉批：运枢机，通经络，为孟英用药秘诀。无论用补用清，皆不离此意，细观各案自知。）", "14532": "董哲卿贰尹令正，胎前患嗽，娩后不痊，渐至寝汁减餐，头疼口燥，奄奄而卧，略难起坐。孟英诊脉虚弦软数，视舌光赤无苔，曰：此头疼口燥，乃阳升无液使然，岂可从外感治？是冲气上逆之嗽，初非伤风之证也。与苁蓉、石英、龟板、茯苓、冬虫夏草、牡蛎、穞豆衣、甘草、小麦、红枣、藕。数帖嗽减餐加，头疼不作，加以熟地，服之遂愈。", "14533": "庆云圃观察令郎恩荫堂司马，陡患偏坠，医与茴香、芦巴、乌药、荔核等剂，遂痛不可忍，浼赵棠村鹾尹邀孟英视之。按其脉肤甚热，曰：非疝也，睪丸肿痛必偏于右，此湿热时邪也。设以疝治之，必成痈。按法治之，果复杯而痛减，三服而便行热退。因食羊肉肿痛复作，再与清解，谆嘱慎口腹而瘳。", "14534": "吴宪章年逾花甲患感，医知其为湿温也，投药不应，而仍能起榻理事。石北涯拉孟英视之，冀其勿致加剧。及诊脉左寸数疾，余皆软大，谷食略减，便溏溲少，苔色腻黄，舌尖独黑。孟英不肯予方，人咸诧之，因曰：证原不重，吾以脉象舌色察之，是平昔曲运心机，离火内亢，坎水不制，势必自焚，况兼湿温之感乎！果数日而殒。", "14535": "黄纯光年七十八岁，患湿温，至旬余，脉形歇代，呃忒连朝，诸医望而畏之。孟英诊曰：脉虽歇而弦搏有根，是得乎天者厚，虽属高年，犹为实象，参以病深声哕，原非小故，而二便窒涩，苔腻而灰，似府气未宣，痰湿热阻其气化流行之道也。清宣展布，尚可图焉。何新之韪其议，因以旋、茹、栀、楝、杷、杏、萸、连、菀、蒌、雪羹为剂，片通草一两，煎汤煮药，投匕即减，数服而大吐胶痰，连次更衣，遂安粥食。惟动则嗽逆，渐露下虚之象，予西洋参、龟板、牡蛎、苁蓉、石斛、牛膝、冬虫夏草、石英、茯苓、当归等药，而各恙递安。继加砂仁、熟地而起。", "14536": "汤西塍年逾花甲，感证初起，周身肤赤，满舌苔黄，头痛腰疼，便溏溲痛，伊亲家何新之诊为险候，嘱延孟英诊之。脉见弦细而软，乃阴虚劳倦、湿温毒重之证。清解之中，须寓存阴。以犀角、羚、苓、茹、银、翘、桑、苇、通草、兰叶为方，煎以冬瓜汤。服之偏身赤疹而左眼胞忽肿，右臂酸疼不举，耳聋神不清爽，亟以元参、丹皮、菊花、栀子、桑枝、丝瓜络、石斛、竹叶，煎调神犀丹为剂。偶邀疡科视外患，亦知病因湿热，连进木通等药，脉更细弱，神益昏惫，饮食不进，溲涩愈疼，新之以为难挽矣。孟英曰：急救阴液，尚可转机。援复脉汤去姜桂、麻仁，易西洋参，加知母、花粉、竹叶、蔗浆灌之。一剂神苏脉起，再服苔退知饥，三啜身凉溺畅，六帖后肤蜕安眠，目开舌润。或疑甘柔滑腻之药，何以能清湿热？孟英曰：阴虚内热之人，蕴湿易于化火，火能烁液，濡布无权，频溉甘凉，津回气达。徒知利湿，阴气先亡，须脉证详参，法难执一也。又服数剂后，忽然肢肿，偏发风块，瘙痒异常。或又疑证之有变也，孟英曰：此阴液充而余邪自寻出路耳。与轻清药数帖，果瘥。", "14537": "海盐任斐庭，馆于关琴楚家，季夏患感，黄某闻其身热而时有微寒也，进以姜、萸、柴、枣等药，数帖热愈壮，而二便不行。更医连用渗利之剂，初服溲略通，既而益秘，居停以为忧，始延孟英视焉。证交十四日，骨瘦如豺，脉弦细而涩、舌色光紫，满布白糜，夜不成眠，渴不多饮，粒米不进，少腹拒按，势将喘逆，虽属下证，而形脉如斯，法难直授。先令取大田蠃一枚，（外治法甚妥。）鲜车前草一握，大蒜六瓣，共捣烂，加麝香少许，罨脐下水分穴。方以元参、紫菀、栀子、知母、花粉、海䖳、凫茈、苁蓉、牛膝、天冬为剂，加鲜地黄汁服之。其夜小溲即行，气平略寐。又两剂，大解始下，退热而渐进稀糜，乃去雪羹、栀、菀、苁蓉、膝、地黄汁，加西洋参、麦冬、石斛、干生地、竹茹、银花等药。又服十余帖，凡三解黑矢，而舌色复于红润，眠食渐安而起矣。", "14538": "庄芝阶舍人令爱，孀居在室，陡患气冲欲厥，脘痛莫当，自服沉香、吴萸等药，病益剧，而呕吐发热，略有微寒。孟英按脉弦滑且数，苔色滑腻微黄，而渴喜冷饮，便秘溲热，眠食皆废。是伏痰内盛，肝逆上升，而兼吸受暑热也。予吴萸水炒黄连、枳实、竹茹、栝蒌、石膏、旋覆、赭石、知母、半夏、雪羹。服二剂吐止痛减，五剂热退而解犹不畅，旬日始得豁然，乃去石膏、知母、旋、赭，调之而愈。", "14539": "陈书伯太史令弟妇，娩后三日，发热汗多，苔黄眩悸，孟英切脉弦细虚数。乃营阴素亏，酷热外烁，风阳浮动，痉厥之萌也。予元参、白薇、青蒿、生地、小麦、穞豆衣、石斛、鳖甲、竹叶。两剂热退知饥，悸汗不止，去蒿、薇，加龙、牡、莲心、龟板、石英而安。继又暑风外袭，壮热如焚，渴饮不饥，睹物尽赤，改授白虎加西洋参、竹叶、莲杆，一啜而瘳，仍与镇摄滋潜善其后而愈。", "14540": "高氏妇因戒鸦片而服外洋丸药，诸无所苦，惟便秘不通，医治两月，迄不能下，且仍安谷，而面赤龈胀欲挑，每以银针嵌入齿缝，而拔出之时，银色已如煤黑。孟英诊脉滑数，予犀角、石膏、硝、黄、升麻、蜣螂为剂，（解毒妙品。）和以鲜银花汁一杯。服后夜间登圊三四行，而病去及半，再予清解化毒而痊。", "14541": "太仓陆竹琴令正，陡患心悸，肢冷如冰，其子皇皇，浼吴江程勉耘恳援于孟英。察其脉浮弦而数，视其舌尖赤无苔，乃阴虚阳越，煎厥根萌。予元参、二至、三甲、龙齿、石英、生地、牛膝、茯神、莲子心而愈。", "14542": "赵子循室，娩后服生化汤二帖，更因惊吓，三朝发热，连投四物、六合等汤，病日以甚，半月后始延孟英诊之。脉象左弦急，右洪滑数，苔黄大渴，谵语嗽痰，恶露仍行，唇齿干燥，是因阴虚之体，血去过多，木火上浮，酷暑外烁，津液大耗，兼有伏痰之候也。亟与营卫两清，冀免他变。而母家极畏石膏，坚不与服，越三日势益剧，计无所施。子循之叔笛楼，与其表兄许芷卿，径以白虎加减投之，证有转机。翼日再迓孟英会同笛楼，暨其舅氏许吉斋山长，协商妥治，咸是王议。且以西瓜汁助其药力，热始日渐下行，二便如火。又数日渐安粥食，神气亦清，起坐梳头，夜能静寐。然热蕴太久，下焦患痈，脓虽即溃，阴液漏伤，脉复空数浮大，便泄善嗔，口干多梦，皆木少水涵，烁津侮胃之见证也。孟英与笛楼商以白头翁汤，加龙骨、三甲、甘草、木瓜以育阴潜阳，余粮石脂丸中加梅、连以息风镇胃。果得疮口脓干，餐加泻止，脉柔热净，苔退神怡。正须善后，甫授滋填，不期酷热兼旬，甘霖忽降，窗开彻夜，复感风邪，身热微寒，鼻流清涕，而阴液久夺，外患未痂，培养碍投，又难发汗，肝风内应，瘛噤旋形，九仞之功，遂成画饼，门外汉未免以成败论，然此案自堪传也。（眉批：仍是阴血大虚，故变证如此，非盖由于风邪也。）陈某患嗽，嗽则先吐稀痰，次则黄浓甜浊之痰，继之以深红带紫之血，仍能安谷，别无所苦，多药不愈。孟英切其脉缓大，而右关较甚，乃劳倦伤阳，而兼湿热蕴积也。予沙参、生薏苡、木瓜、茯苓、竹茹、桑叶、枇杷叶、生扁豆、苇茎、花粉为剂，吞松石猪肚丸而愈。王瘦石夫人患滞下，腹痛微呕，不饥口苦，溲短耳鸣。孟英诊曰：脉见细弱之形，肌无华泽之色，汛不行而早断，舌紫黯以无津，是素质阴亏，情怀悒郁，二阳默炽，五液潜消，虽吸暑邪，莫投套药。予白头翁汤加雪羹、银花、栀子、楝实，（先清暑邪。）数剂而减。继去雪羹，加生地、苁蓉、柿饼、藕汁而安。改授甘麦大枣，加西洋参、生地、苁蓉、竹茹、归、芍、蒲桃干，而以藕汤煎服，调养体质以痊。", "14543": "《仁术志》者，海丰张君柳吟所题孟英之医案也。吾师赵菊斋先生，暨庄舍人芝阶为之序，余以未与其事，深以为歉。秋间偶过孟英，适有陈姓者牵羊来谢，孟英颇疑之，其人曰：三月间次媳患时感，而气逆不能眠，医皆畏却，特延君诊。甫按脉云：甚滑疾是为娠象，用药必须顾及。此时次媳于去秋娩后，月事尚未一行，君为此言，阖家未尝不窃笑也。迨疾渐平，哺儿之乳亦不觉少，虽自问亦断断非孕。至六月间腹渐胀，方谓有病。不料昨日倏产一孙，举家敬服高明，故来致谢耳。孟英因谓余云：昨诊魏子恒之室亦妊也。诸医作虚损治，脉虽虚微软数，而滑象仍形，病家深不以吾言为然者，缘病人之女兄二人，皆死于虚劳也。然其伯仲之证，吾皆诊焉，今已十余年矣，犹忆伯字于关氏，未嫁而卒，证非不治，亦为药误。病中阅吾方案，极为折服，且曰：先生来暮，侬不能起矣。前此延致诸名家，徒曰虚证宜补，而不治其所以虚，方则群聚补药，必以地黄为之冠，虽有参、耆，亦列于后，即使用药不乖，而阳生阴长，气为血帅之旨，尚未分晓，况其他乎？吾闻而愕然，何以闺中女子，亦解谈医，细询始知为乾隆间名医吴颖昭先生之女孙也，尤为惋惜。仲适于陈少帘少府，的系损证，若季者因其家怀先人之见，遂致医人迎合误事，岂不可叹！迨秋仲果闻魏氏分娩，母子皆亡，方叹孟英之卓见为不可及也。爰采秋冬诸案之治法不同于寻常者，而续成一卷云。", "14544": "便血至三十余年，且已形瘦腰疼，嗽痰气逆，似宜温补之法矣。而嘉定沈酝书患此濒危，求孟英以决归程之及否？比按脉弦数，视舌苔黄，询溺短赤，曰：痔血也。殆误于温补矣。肯服吾药，旬日可瘳。酝书欣感，力排众论，径服其方，果不旬而愈。方用苇茎合白头翁汤，加枇杷叶、旋覆花、侧柏叶、藕，是肃肺祛痰、清肝凉血互用也。（眉批：徐灵胎批叶案云：便血无至十余年者，惟痔血则有之。今便血三十余年，不问可知为痔血矣。惟徐氏未尝出方，孟英此案足为程式。）", "14545": "产后诸证，首必通瘀，然有不可以常理测者。表弟周鹤庭室，新产晕汗，目不能开，心若悬旌，毫无恶露。乃父何君新之，按其脉有虚弦豁大之形，亟拉孟英图之。予以三甲、石英、丹参、琥珀、甘草、小麦、穞豆衣等药，（滋阴镇逆，仍兼行血之品，斯灵动而不滞。）复杯即安，数服而愈。或诘其何以知非瘀血为患？曰：此阴虚之体，既产而营液大脱，风阳上冒，虽无恶露，胸腹皆舒，岂可误作瘀冲，而妄投破血之药耶？", "14546": "许季眉别驾室，归自维扬，仲秋患痁，自作寒湿治，势益剧。其从子芷卿以为挟风暑也，连进清解，病不减，邀孟英诊之。脉弦滑而洪，体丰多汗，苔黄便血，呕渴妄言，彻夜不瞑，欲卧于地。乃伏痰内盛，暑扰阳明也。投大剂石膏、知母、犀角、元参、石斛、银花、黄芩、花粉、兰叶、竹沥，三帖证始平。芷卿随以多剂肃清而愈。", "14547": "庄芝阶舍人，年七十矣，患间疟，寒则战栗，热则妄言。孟英视之，脉弦数而促，苔黑口干，是素有热痰，暑邪内伏。予知母、花粉、元参、石斛、黄芩、竹茹、连翘、海䖳、芦菔、莲子心等药，数啜而瘳。至仲冬因泛湖宴客，感冒风邪，痰嗽头疼，不饥寒栗，自服羌、苏、荆芥药二剂，势益甚，而口渴无溺。孟英切其脉，与季秋无异，但兼浮耳。证属风温，既服温散，所谓热得风而更炽也。舌绛无津，亟宜清化。以桑叶、枇杷叶、栀子、知母、冬瓜子、元参、菊花、花粉、贝母、梨汁为剂，投匕即减，旬日而痊。", "14548": "孙位申室，平昔阴虚肝滞，痛胀少餐，暮热形消，咽疼喉癣，不孕育者九年矣。往岁汛愆，人皆谓将不起，而孟英切其脉尚不细，肤犹淖泽，许筹带病延年之策。果月事仍行，而诸恙皆缓，且能作劳，惟饭食日不过合米。今秋延孟英往诊云：经自三月至今未转，一切旧恙，弥见其增，君术虽仁，恐难再延其算矣。及举脉弦滑左甚，遽曰：岂仅可延其算哉？且有熊罴入梦矣。其家闻之駴异，迨季冬果得一子，颇快而健。", "14549": "翁嘉顺于去年秋间，偶从梯半跌仆，初无所伤，旬日外陡发寒热，膝旁肿痛。外科汪某治之，溃后不能收功。另招许某疗之，识为伤络，应手渐效，翁极信服。然培补年余，虽纳食不减，而肌肉渐削，面色黧黑，步履蹇滞，且一旬半月之间，必患处疼肿，大发寒热，卧榻数日，始能强起，大费不赀，愈发愈剧。至冬间咽糜龈腐，睛赤音嘶，乃恳孟英以决吉凶。按脉滑数，舌绛便艰，口臭溲少，蕴隆虫虫。良由疡医仅知温托一法，既溃之后，更以温补收功善后，竟未察其体气病情，以致平时所有之湿热痰火，一齐关住，病犹自寻出路，寒热频作，而医者不识，妄指为虚，补及逾年，人财两瘠，真谚所云将钱买憔悴也。予元参、黄柏、知母、甘草、银花、花粉、绿豆、栀子、海䖳、凫茈为大剂投之，外吹以锡类散，且令日啖梨、蔗、麒麟菜、柿饼等物。至五十日，诸恙蠲，体腴善步。（眉批：孟英诸案，大抵救温补之失，故寒凉为多。然斟酌尽善，不以苦寒伤生气，则非他人所能学步。）", "14550": "胎前产后，疑似极多，号曰专科，尚难措手。陈肖岩孝廉媳，屠仲如之女也，汛愆一度，次月仍行，方疑其病也。孟英诊曰：尺虽小弱，来去缓和，是娠也。继而果然。仲如令弟子绿之室，经事稍迟，孟英偶诊，亦以孕断，寻验。甫三月患胎漏，适孟英丁内艰，遂不克保而堕。堕后恶露虽行，而寒热头疼，时或自汗，且觉冷自心中出，医谓类疟，与温化之药，病日甚，交八日，孟英始出门，即延诊之。脉来沉实而数，舌色紫黯，乃瘀血为患耳。予桃仁、泽兰、山楂、茺蔚、旋覆、红花、丹参、通草、琥珀、蛤壳、丝瓜络之剂。（眉批：通血之剂，亦清灵无弊。）服后腹大痛，下瘀血如肺者一枚。次日诸恙较减，乳汁大流，再以前方去通草，加麦投之。服后腹仍痛，复下瘀块累累，而诸恙若失。或问先生尝言产后腹无痛苦者，不可妄行其血，此证恶露已行，腹无疼胀，何以断为瘀阻而再行其血耶？孟英曰：正产如瓜熟蒂落，诸经荫胎之血，贯串流通，苟有瘀停，必形痛胀。堕胎如痈疡未熟，强挤其脓，尚有未化之根柈，不能一齐尽出。所以胎虽堕而诸经荫胎之血，萃而未涣，浅者虽出，深者尚留，况是血旺之躯，加以温升之药，挽其顺流之路，窒其欲出之机，未到腹中，胀疼奚作。吾以循经通络、宣气行瘀之法，导使下行，故出路始通，而后腹痛瘀来，然必有脉可征，非谓凡属堕胎皆有是证也。", "14551": "锁容亭令姊，自太仓归宁，即患时疟。顾某一手清解，业已安谷下榻矣。忽然气逆肢寒，神疲欲寐，耳聋舌蹇，杳不知饥，大便仍行，别无痛苦。顾知其素患脱血，元气久虚，改用参、附等药，势愈剧，以为欲脱矣。所亲吴久山，嘱拉孟英图之。切脉弦缓，视苔黄腻，乃胎之初孕，阻气凝痰、窒碍枢机，治当宣豁，以石菖蒲、枳实、旋覆、半夏、黄连、茯苓、橘皮、葱白、海䖳、竹沥为方，投匕即效，三啜霍然。继而久山令妹，为锁绳先之室，患疟而驯致脘痞呕呃，鼻冷自汗，不食不眠，脉来歇止，医者危之。孟英视之，亦痰为患耳。即以此方去葱、䖳、竹沥，加薤白、蒌仁、竹茹，投之果验。", "14552": "古方书云：喘无善证，喘而且汗，尤属可危。潘肯堂室，仲冬陡患气喘，医治日剧。何新之诊其脉无常候，嘱请孟英质焉。孟英曰：两气口之脉，皆肺经所主，今肺为痰壅，气不流行，虚促虽形，未必即为虚谛。况年甫三旬，平时善饭，病起于暴，苔腻痰浓，纵有足冷面红，不饥不寐自汗等证，无非痰阻枢机，有升无降耳。遂与石膏、黄芩、知母、花粉、旋覆、赭石、蒌仁、通草、海䖳、竹沥、菔汁、梨汁等药。一剂知，三剂平。乃去二石，加元参、杏仁，服旬日而安。俟其痰嗽全蠲，始用沙参、地黄、麦冬等，以滋阴善后。", "14553": "室女多抑郁，干嗽为火郁，夫人而知之者。王杞庭之姊，年逾摽梅，陡患干嗽，无一息之停，目不交睫，服药无功，求孟英诊焉。两脉上溢，左兼弦细，口渴无苔，乃真阴久虚，风阳上僭，冲嗽不已，厥脱堪虞。授牡蛎、龟板、鳖甲、石英、苁蓉、茯苓、熟地、归身、牛膝、冬虫夏草、胡桃肉之方，药甫煎，果欲厥，亟灌之即寐。次日黄昏，犹发寒痉，仍灌前药至第三夜，仅有寝汗而已。四剂后诸恙不作，眠食就安。设此等潜阳镇逆之方，迟投一二日，变恐不可知矣，况作郁治，而再用开泄之品耶？故辨证为医家第一要务也。", "14554": "《寓意草》谓：伤风亦有戴阳证。此为高年而言，然有似是而非者。黄鼎如令堂，年登大耋，季冬感冒，痰嗽气逆，额汗颧红，胸痞不饥，神情躁扰。孟英诊脉左弦疾而促，右滑数而溢，苔色满布。系冬温挟痰阻肺，治节不伸，肝阳鼓舞直升。罗谦甫有治痰火类孤阳之案，颇相似也。以小陷胸汤加薤白、旋覆、赭石、花粉、海䖳、凫茈、竹沥为大剂投之，痰活便通，数日而瘥。继有陈舜廷之父，年逾花甲，患痰嗽气逆，惟饮姜汤则胸次舒畅，医者以为真属虚寒矣，连投温补之剂，驯致咽痛不食，苔色灰刺，便秘无溺，求孟英诊之。脉至双弦，按之索然，略无胃气。曰：渴喜姜汤者，不过为痰阻清阳之证据耳，岂可妄指为寒，叠投刚烈？胃阴已竭，药不能为矣。", "14555": "东垣云：中年以后，已行降令，清阳易陷，升举为宜。吾师赵菊斋先生，年逾花甲，偶因奔走之劳，肛翻患痔，小溲不行，医者拟用补中益气及肾气丸等法。孟英按其脉软滑而数，苔色腻滞。此平昔善饮，湿热内蕴，奔走过劳，邪乃下注，想由强忍其肛坠之势，以致膀胱气阻，溲涩不通，既非真火无权，亦讵清阳下陷。师闻而叹曰：论证如见肺肝，虽我自言，无此明切也。方以车前、通草、乌药、延胡、栀子、橘核、金铃子、泽泻、海金砂，调膀胱之气化而渗水。服之溲即渐行。改用防风、地榆、丹皮、银花、荆芥、槐蕊、石斛、黄连、当归，（后治痔漏。）清血分之热而导湿，肛痔亦平。设不辨证而服升提温补之方，则气愈窒塞，浊亦上行，况在高年，告危极易也。", "14556": "许芷卿痁起季秋，孟英尝清其伏暑而将愈。其从母亦知医，强投以小柴胡一剂，势复剧。孟英予温胆汤去甘草，加生石膏、黄芩、知母、花粉、芦菔而安。继因作劳太早而复发，适孟英丁忧，赵君笛楼仍用清解而瘥。迨季冬移居劳顿，疟复间作，且面浮跗肿，喘嗽易嗔，人皆以为大虚之候。孟英切脉左弦劲而数，右滑大不调，苔黄且腻，口渴溺多，乃胃肺之痰热有余，肝胆之风阳上僭，畏虚率补，必不能瘳。用西洋参、知母、花粉、竹茹、蛤壳、石斛、枇杷叶、青蒿、秦艽、白薇、银花、海䖳为方。连投四剂，大吐胶痰，而各恙悉除。", "14557": "《薛氏医案》每以补中益气汤与地黄丸并用为治，虽卢不远之贤，亦或效尤，其实非用药之法也。如果清阳下陷而当升举者，则地黄丸之阴凝滞腻非所宜也；设属真阴不足，当用滋填者，则升、柴之耗散不可投也。自相矛盾，纪律毫无，然上下分治，原有矩矱。屠敬思索属阴亏，久患痰嗽，动即气逆，夜不能眠，频服滋潜，纳食渐减，稍沾厚味，呕腐吞酸。孟英视脉左弦而微数，右则软滑兼弦，水常泛滥，土失堤防，肝木过升，肺金少降，良由久投滋腻，湿浊内蟠，无益于下焦，反碍乎中运，左强右弱，升降不调。以苁蓉、黄柏、当归、芍药、熟地、丹皮、茯苓、楝实、砂仁研为末，藕粉为丸，早服温肾水以清肝；以党参、白术、枳实、菖蒲、半夏、茯苓、橘皮、黄连、蒺藜生晒研末，竹沥为丸，午服培中土而消痰；暮吞威喜丸，肃上源以化浊，三焦分治，各恙皆安。悉用丸剂者，避汤药之助痰湿耳。（眉批：方俱灵妙，可以为法。）", "14558": "本朝乾纲丕振，雀顶尚红，冠饰朱缨，口燔烟草，皆为阳盛之象，是以火证偏多。夫药者补偏之物，医为救弊之人，岂可不识此大气运，而硁硁然泥夫司天在泉以论治，何异痴人说梦耶？安徽人程某，在余姑丈许辛泉典中司会计。仲冬患感，医者闻其病前一日，曾啖生芦菔一枚，而大便又溏，苔色又白，今年又为湿土在泉，遂指为中虚寒湿之病。参、术、附、桂，多剂率投，驯致舌黑神昏，尚疑为大虚之候。禾中沈柳衣见之，知其药误，另招张镜江诊之。曰：冬温也。连与犀角地黄汤而无起色，二十日外，始乞孟英视焉。舌缩底绛，苔黑如漆，口开茎萎，脉细数而弦，右则按之如无。阴液尽烁，温毒深蟠，甘露琼浆，不能复其已竭之津矣。俄而果败。继有潘圣征于仲冬患感，至十四日退热之后，杳不知饥，群医杂治。迨季冬下旬，转为滞下五色，腿肿裂血，溲涩口干，始延孟英诊之。左脉弦细而数，右弦滑而空，苔色黄腻根焦，时或自汗，乃气液两竭，热毒逗留之象，必从前过服温补之药，否则热退在十四日之期，何至延今五十余朝，而见证若是之棘手哉？其弟鸿轩云：此番之病，补药不过二三剂，惟仲秋患疟时，医谓其苔白体丰，云是寒湿，尝饵附、桂数十剂，且日饮烧酒耳。孟英曰：此即酿病之具矣。治病且难，何况有如许之药毒内伏，更将何法以生之耶？坚不立方，其家必欲求药，以期扶持度岁。孟英曰：是则可也。以白头翁汤加银花、绿豆、归身、白芍、陈米、燕根、兰叶、藕为剂，而以补中益气大料，蒸露代水煎药。服后焦苔渐退，粪色亦正，举家喜出望外，复丐孟英图之。奈脉无转色，遂力辞之。又沈听松鹾尹太夫人，季秋患疟，孟英尝往诊之。曰：伏暑所化，且体属阳强而多痰火，切勿畏虚，辄从温补，奈病者期于速愈，广征医疗。或以为证属三阴，或谓是子母疟，或指为老年胎疟，众楚交咻，病不能愈。延至季冬，亦转为痢，且肤肿臀疮，口糜舌疱，诸医束手，复请诊于孟英。脉与潘同，不可救药。", "14559": "谢谱香体属久虚，初冬患嗽痰减食，适孟英丁艰，邀施某视之。云是肾气不纳，命火无权。叠进肾气汤月余，遂致呕恶便溏，不饥无溺，乃束手以为必败矣。季冬仍延孟英诊之，脉甚弦软，苔腻舌红，乃中虚而健运失职，误投滋腻，更滞枢机，附、桂之刚，徒增肝横。予党参、白术、茯苓、泽泻、橘皮、半夏、竹茹、栀子、薏苡、蒺藜、兰叶、柿蒂之剂，培中泄木，行水蠲痰，旬日而愈。（眉批：古人补肾不如补脾、补脾不如补肾之说，均有至理，而用违其宜，亦均足致败，此医所以首贵认证也。）", "14560": "藁砧远出，妇病如狂，似属七情，而亦有不尽然者。有陈氏妇患此月余，巫医屡易，所费既巨，厥疾日增。孟英切其脉弦而数，能食便行，气每上冲，腹时痛胀。询其月事，云：病起汛后，继多白带。孟英曰：病因如是，而昼则明了，夜多妄言，酷似热入血室之候，径从瘀血治可也。予桃仁、红花、犀角、菖蒲、胆星、旋覆、赭石、丹参、琥珀、葱白之剂。两服而瘀血果行，神情爽慧。继去桃仁、红花，加当归、元参，服数剂而瘳。", "14561": "范廉居夫妇，与其令爱，一时患恙，旬日后咸剧，金粟香荐孟英视之。廉居则大解已行，热退未净，气逆不饥，呃忒自汗，脉形虚大，舌紫无苔，为上焦热恋，下部阴亏之象。予西洋参、旋覆、竹茹、枇杷叶、石斛、柿蒂、牡蛎、龟板、刀豆、牛膝之剂。两服即舌润知饥，呃汗皆罢，去刀豆、旋覆、柿蒂，加熟地、胡桃肉、当归，投之而愈。其室则苔腻口酸，耳鸣不寐，不饥神惫，脘痛头摇，脉至虚弦，按之涩弱。以当归、白芍、枸杞、木瓜、楝实、半夏、石斛、茯神、竹茹、兰叶、白豆蔻，为养营调气、和胃柔肝之法，数啜而瘳。渠女则壮热殿屎，二便皆秘，苔黄大渴，胀闷难堪，脉来弦滑数实，系府证也。投桃核承气，加海䖳、芦菔，二剂而痊。廉居尊人颖禾曰：甚矣，服药之不可不慎也。三人之证，医者皆谓可危，而治之日剧，君悉以一二剂起之，抑何神欤？因忆四十二岁时患痁，胡魁先用首乌太早，遂致客邪留恋，缠绵百日，大为所困，嗣后不敢服药，今四十年矣。昨闻韩组林年虽七十，饮啖兼人，而平时喜服药，医以为老，辄用附、桂、参、茸等药，以期可享遐龄，讵料初八日晚饍尚健饭，三更睡醒，倏寒栗发颤，俄而四肢瘛疭，越日云亡，得非即世人所谓之子午证耶？孟英曰：此老系阳旺之体，肥甘过度，痰火日增，年至古稀，真阴日耗，而久服此等助火烁阴之药，以致风从火出，立拔根荄，与儿科所云急惊风证，殆无异焉。", "14562": "古云：肥白之人多气虚。又云：痰饮须以温药和之。儒医顾听泉，体丰色白，平昔多痰，晨起必喘逆，饱食稍安，颇有气虚之象。季冬感冒，自服疏解未效，迓孟英诊焉。左关弦，寸滑如珠，尺细而干，舌尖甚绛。乃真阴素亏，水不涵木，风阳内炽，搏液成痰，谋虑操待，心阳太扰，肺金受烁，治节不伸。苔虽白而已干，热虽微而睛赤，忌投温燥，宜予轻清。用元参、石斛、栀子、竹茹、旋覆、蛤壳、贝母、枇杷叶、竹叶、兰叶、莲心为剂，三啜而安。自谓气虚，遽服党参、枸杞、当归等药，下咽之后，即觉火升气逆，渐至言语支离，溲频自汗，夤夜复迎孟英拯治。脉已虚促不调，即投牡蛎、龟板、鳖甲、女贞、旱莲、元参、甘草、小麦、竹叶、莲心，以和心肝之阳，而镇龙雷之奋，一剂而平。继又作劳复感，仍授轻清之法。两剂后又因怫怒萦思，肝阳复僭，颧红目赤，左耳时聋，夜不成眠，神情烦躁，越日陡然大汗湿透衣衾，再速孟英图之。脉极弦数而细，仍为阴虚阳越，不可误认阳虚，而妄施附、桂者。先令熏以炭醋，扑以蛎粉，随灌以大剂二至、二冬、三甲、元参、丹参、人参、黄连、童溲而瘳。继予多剂育阴清肝，始得全愈。又其媳新产之后，头痛甚剧，孟英按其脉右甚滑大，予清阳明法，得大解而瘥。", "14563": "临证医案，非古也。古人视病不立案语，但书方药。迨宋后医生诊病，始相沿先立案语，后书方药，但随作随弃，无有辑之者。如宋之许知可、张季明，明之薛立斋、陈维宜、孙文垣，以及清初喻嘉言、徐大椿辈，虽有医案，类皆因治疗效验，笔诸于书，其文乃记事，非临证也。良以病多转变，方难一定，恐泥学者眼目，故作者恝置之。然余谓医之有方案，犹名法家之有例案，文章家之有试牍。对病书方，因题立义，相对斯须，人之性命系焉，已之得失亦系焉。虽不足为根柢之学，而病者之情形，医者之学识心思，尽在于是。苟能溯其脉证，观其变化，奚啻与病者医者一堂共语，不大可触发手眼哉！故叶氏《临证指南》，海内风行。然叶案语意高深，方多平淡，学者践其迹，未必入其室。因叶负一时重名，所视者非富室膏粱，即病深气竭，贫寒初病者寥寥焉。盖气体不同，方法即异，读其书而得其用者鲜矣！余旧得无锡王泰林旭高先生方案二卷，爱而藏之，以篇页无多，未梓。更求二十余年，不可得。客春游梁溪，访老友刘君石香。石香出十卷示余，云新得于李氏者。亟假归读之，其心思之敏，见识之超，清华而不高深，灵变而有矩矱，视叶案易于学步。且复诊甚多，前后推究，考其得失，尤足以资助学者。因并余所藏者，去其重复，合而选之。间有字句冗沓率意处，略为删整，依类编次，分二十六门。每门附以拙论，略见大意。其有精警与未惬意者，复随案指出，正之有道，非敢有意毁誉也。原书十卷，约得五六，厘为四卷，命儿辈录出，不敢自私，付之梓人，以公同学焉。", "14564": "朱风温袭肺，肺失宣降，咳嗽气急，头痛发热，舌苔干白，脉象滑数，面色暗晦，额上汗出，正虚邪实，虑其喘脱。", "14565": "二诊服药后熟寐半夜，痰气平静，但身热仍然未退，直至早晨，又复咳嗽气升。今诊脉数稍减，苔仍干白，面色晦滞不开，邪不外达，正气先虚，证届七日，乃一候关节之机，使得安稳，庶几无变，拟方再望转机。", "14566": "朱温邪六日，舌白尖红，胸中烦闷，脉形弦数，邪留少阳阳明，不肯宣达，外则症状如疟，里则协热便泄，拟大柴胡法。", "14567": "孙年逾古稀，触染温邪，遽尔内陷，便泄气粗，神蒙如寐，舌焦干短，左脉空大，右脉模糊，势防痉厥。", "14568": "秦温邪十二日，斑疹遍透，神识仍糊。大便屡行，齿垢未脱。舌尖红，中心焦，阴津灼也。左脉大，右脉小，元气弱也。昨投清泄芳开，是从邪面著笔；今诊脉神委顿，当从元气推求。要知温属阳邪，始终务存津液。胃为阳土，到底宜济甘凉。所虑液涸动风，易生痉厥之变。胃虚气逆，每致呃忒之虞耳！", "14569": "渊按：帆随湘转，妙于转环。脾肾阳气素虚，阳邪一化，阴湿即来。在脉神委顿时早防之，庶免此日波变，然不料其变之如是速耳。古方大豆卷治筋挛湿痹，苏地用麻黄汤浸，借以发汗，与此证总不相宜。", "14570": "五诊温邪甫退，少腹板硬，膀胱气化无权。昨议疏泄三焦，小便仍不畅。今少腹硬满过脐，其大如盘，按之不痛，脉沉小，舌白腻，身无热，口不渴，所谓上热方除，中寒复起是也。夫膀胱与肾相表里，膀胱气化赖肾中阳气蒸腾。肾阳不足，膀胱水气凝而为瘕，须防犯胃冲心呃厥等变。急急温肾通阳泄水，犹恐莫及。", "14571": "某温邪十一日，神昏不醒，齿燥，舌焦干，脉形糊数，斑疹透而未足，色不鲜泽，阳明邪火炽盛，少阴阴液消亡，势有痉厥之险。勉拟生津救液，佐以芳香宣窍。备候高明商夺。", "14572": "华温邪八日，神识模糊，斑色红紫，脘腹拒按，结热旁流。舌红干燥，目赤唇焦，而又肤冷汗出，脉伏如无。邪热内闭，阴津外泄，颇有内闭外脱之虑。勉进黄龙汤法。", "14573": "渊按：肤冷汗出脉伏，非虚象，乃闭象也，从班色红紫上看出。参须可斟酌。", "14574": "尤证交十二日，目赤耳聋，舌白烦渴，脉洪大而汗出。当辛凉以彻气分之热邪，甘凉以救肺胃之津液。", "14575": "二诊目张不语而神慧，与汤则咽，身能转侧。舌苔灰白，脉形洪滑。并非邪闭心包，乃肝阳夹痰火阻塞清明之府。勿再芳香开达，开则邪反内陷矣，慎之！", "14576": "三诊目张不语，多汗脉大。阳盛阴虚，防其厥脱。急救其阴，希图万一。", "14577": "四诊目已能合，口已能言，但舌蹇而言涩。汗多稍收，脉大稍敛，似有一线生机。所嫌两臂动强，恐其发痉。拟存阴熄风法。", "14578": "三诊用和胃化邪法，一剂颇安，二剂反剧。良以畏虚多进谷食，留恋其邪，不能宣化，郁于心胃之间，湿蕴生痰，热蒸灼液，烦燥、恶心、错语，两手寸关脉细滑数，两尺少神，舌边乾红，心苔黄腻，皆将燥未燥、将陷未陷之象。当此阴亏之体，能不虑其内陷乎。拟导赤、泻心各半法，生津化浊，和胃清心。", "14579": "六诊口臭喷人，胃火极盛。斑疹虽见，透而未足。目赤神糊，脉洪口渴。急急化斑为要。古法化斑以白虎为主，今仍参以犀地清营解毒，再复存阴玉女煎。", "14580": "八诊黑苔剥落，舌质深红，阴津大伤，燥火未退，左脉细小，右脉洪大，是其征也。际此阴伤火旺，少阴不足，阳明有余，惟景岳玉女煎最合。一面存阴，一面泻火，守过三候，其阴当复。", "14581": "渊按：右脉洪大，阳明热结夹滞显然。", "14582": "十一诊耳聋无闻，舌干难掉。阴津大伤。用复脉法。", "14583": "复诊证逾旬日，系温邪挟湿，病在气营之交。苔白腻而边红，疹点透而不爽。寐则谵语，寤则神清。呃声徐而未除。脉象软而小数。周先生清营泄卫，理气化浊，恰如其分。僭加一味，仍候主裁。", "14584": "三诊热处湿中，神蒙嗜卧，呼之则清，语言了了。舌白腻，脉软数，知非邪陷膻中，乃湿热弥漫于上焦，肺气失宣布耳。呃尚未除，胃浊未化。拟从肺胃立法。", "14585": "孙温邪袭肺，肺失清肃，湿挟热而生痰，火载气而逆上。喘息痰嘶，舌干口腻。昨日之脉据云弦硬，现诊脉象小而涩数，阴津暗伤，元气渐馁，颇有喘汗厥脱之虑。夫温邪为病，隶乎手经，肺胃位高，治宜清肃。痰随气涌，化痰以降气为先。气因火逆，降气以清肃为要。姑拟一方，备候高明酌夺。", "14586": "原注：凡时证之脉，先大而后渐小，先强而后变弱，其热不退，而病反增者，必死。此死证也，无能为力，立方用药，无甚深意。", "14587": "诒按：此要诀也，最须记好。初病之脉硬大者，邪正相搏也。转为弱小，正气馁矣，而病象不退而反增，正气不能敌邪也。病日进而正日亏，不死何待。", "14588": "黄舌干而绛，齿燥唇焦，痰气喘粗，脉象细数。无形邪热熏蒸于膻中，有形痰浊阻塞于肺胃，而又津枯液燥，正气内亏，恐有厥脱之变。拟化痰涤热治其标，扶正生津救其本，必得痰喘平、神气清，庶几可图。", "14589": "二诊头汗淋沥，痰喘不止，脉形洪大，面色青晦，舌红干涸，齿板唇焦，此少阴阴津不足，阳明邪火有余，火载气而上逆，肺失降而为喘，证势危险，深虑厥脱。勉拟救少阴之津，清阳明之火，益气以敛其汗，保肺以定其喘，转辗图维，冀其应手乃妙。", "14590": "原注：此玉女煎合生脉散，盖温病以救阴为急也。", "14591": "渊按：脉形洪大，合之头汗面青，上实下虚大著。从补下纳气之中，想出清热救津之法，故能应手。人参、石膏、粳米，救肺清热，亦所以救肾也。", "14592": "三诊汗稍收，喘稍平，脉大稍软。但气仍急促，心中烦躁，舌红干涸，齿垢唇焦。津液犹未回，虚阳犹未息，上逆之气犹未降，虽逾险岭，未涉坦途。今心腹似有透㾦之象，是亦邪之出路。仍拟救少阴、清阳明，再望转机。", "14593": "张温邪两候不解，脉形洪大中空，神昏蒙而如醉，舌淡红而无苔。与汤亦不却，不与亦不讨。呓语如呢喃，叮咛重复道。昨日用芳开，神情略觉好。然凭证而论之，乃津枯而液燥。是必甘寒润燥生津液，俾得气化津回方保吉。", "14594": "诒按：葶苈治痰喘证属实者，若身不热，而脉微者，忌之。", "14595": "三诊战而得汗，脉静身凉，邪已解矣。舌黄未去，胃中余浊未清，尚宜和化。", "14596": "原注：凡战汗后脉静身凉，用方大法不外乎此。总以和胃气，化湿热为主。", "14597": "孙营阴素亏之体，感受温邪，病起肢麻寒热，旋即便泄神糊。今交七日，脉数而洪，舌燥齿干，心荡气促。阳明之火方炽，少阴之阴已涸。又腹硬痛，大便三日不通。积聚于中不下，气火尽浮于上。似宜通降为先。然阴津大涸，不得不先养其津。姑拟一方备商。", "14598": "二诊温邪上受，自气传营。而化火上炎，由胃及肺。喉属肺经，咽属胃经，凡咽喉之证，属实火者多，因肺胃之阳盛。肾脉循喉，肝脉绕咽，系虚火者，始关肝肾之阴亏。是其大略也。此证乃斑痧之后，喉痛色赤，全由邪火炽张。图治之方，犀角地黄，不出甘寒清解。昨吐红痰，无非气火熏蒸。今观脉色，已觉神情爽朗。立夏恰今朝，病能减而即是退，胎不动而即是安。大便才通，亦是转机之兆。小心调理，冀无欲速之讥。", "14599": "三诊夫温邪燔亢之余，余热固未能净。肺胃燎原之下，阴津必受其戕。养阴不在血而在津与汗，叶氏之名言。安胎须顺气，阴火忌上冲，妇科之要论。此证几及两候，温痧既退，安得邪火复炽？喉肿既消，何以燥痛复盛？所以然者，胎当七八月之间，正肺与大肠司养之际，肺肠相为表里，肺主气而大肠主津，肺受火淫，燥热移于大肠，大肠当养胎之际，遂移热于胞络。《内经》云：人有重身，九月而喑，是胞之络脉绝也。胞脉者，系于肾而络胞胎。今热上迫肺，故音哑、咳嗽而喉复痛也。按此段经文，明指胎中阴火，当九月之期有此音哑一证，教人勿亟治之，惟恐伤其胎气耳。兹方八月，即得音哑咳频，岂非殃及池鱼之谓欤！今以甘凉生津治其上燥，参入咸寒以降阴中伏火，经所谓热淫于内，治以咸寒是也。须知治病要察机宜，养阴而火自降，指久病虚羸而言。火退而阴自充，乃暴病未虚之证。先辈有提其要曰：暴病多实，久病多虚。是其义也。然欤否欤，仍候华先生裁正。", "14600": "渊按：伏温由内达外，由里传表，从少阴而出太阴，所以退而复来，轻而再重，不尽由乎胎热。疹属肺，肺主一身之表，斑属胃，胃为万物所归，温邪每从两经而达也。胞络者，乃胞门子户之胞，非心胞络。胞络系肾，少阴之脉贯肾，上入喉中，热邪由少阴上干喉中，故音哑，甚则喉痛。", "14601": "沈阴虚之体，感受温邪，反复。今交九日，神识时迷，满舌碎腐，脉象渐沉。防其昏厥。备方候致和先生哂政。", "14602": "秦发汗太过，津液内夺。昨日生津以达邪，汗虽未出而疹点已化，热虽未退而脉象稍和，是佳兆也。苔煤而不甚燥，神糊而有时清。犀角地黄虽可用，然大势无变，方亦无事更张，仍照前方加味。", "14603": "张久患便血，阴气先伤于下。今感温邪，挟积，肺胃之气阻窒。上喘下泄，发热口渴，舌绛如朱，额汗不止，遍体无汗，脉小数疾。厥脱险象环生。拟一方备正。", "14604": "渊按：阴血既耗于下，脾气复伤于中，故一感温邪而上喘下泄。泄为脾陷，喘为肾逆，两藏不守，厥脱易易。头汗者，阴不守而阳越也。身无汗者，阴液虚而气不能化也。舌绛如朱，胃阴亏而心火炽。脉小数疾，阴血虚而邪火伏。两方颇有心思，惟葛根嫌升发，牛蒡嫌泄肺。盖阴阳两虚，中气不守，气虽陷，不可升，汗虽无，不可发，急急顾虑中气阴液，犹恐不及。然肯用心如此，敬服之至。", "14605": "某凡证于阴阳虚实疑似之间，最当详审，此证音低神倦，似虚。而便泄臭水，中脘按痛，实也。肢冷脉细，似阴。而小便热痛，阳也。至于舌白谵语，乃痰蒙火郁之征。而日暮烦躁，为阴虚阳盛之兆。鄙意百般怪证，多属乎痰。痰蒙火郁，清化不解，须从下夺。即使正虚，而虚中夹实，亦当先治其实耳。", "14606": "二诊头胀身疼，热炽脉数，舌苔浊厚灰黄，邪积交蕴不达，有日重之势。", "14607": "三诊温邪吸自口鼻，阻于膜原，蒸痰聚浊，弥漫三焦，热势早轻，过午则甚。舌苔灰黄，渴不多饮，心胸烦躁，脉濡而数，症属湿温。今方四日，邪蕴不达，势防生变，仍以前方加减。", "14608": "五诊证交六日，舌苔焦黄，邪势已离膜原，浊秽结于肠胃，胸中烦躁痞痛，频转屎气，似有可下之机。但左脉小数急，而右脉模糊，乃正虚不能敌邪，邪不宣达，恐其内陷生变。", "14609": "六诊昨投小承气合小陷胸法，得下燥屎并浊秽黏垢甚多，胸腹痞痛已解。而舌反焦黑，脉反数疾，烦躁不安，证交七日，乃一候关节之期，邪热劫津，虑有过卫入营，内陷神昏之变。此际用方，当取甘寒养津，兼以开泄三焦。", "14610": "七诊证逾一候，烦躁不安，舌焦目赤，面色油紫，左脉促数，右脉模糊，肺胃之气不宣，营中之热炽盛，斑疹似透不透。深虑内闭神昏，急与清营透卫。", "14611": "八诊证交九日，胸背臂膊发出红点，挟斑带疹，大小不一。虽属邪之出路，嫌其稠密不疏，烦躁气粗，右脉涩滞，气营之热交炽，深有昏呃之虑。备候高明商定。", "14612": "十诊右脉稍起，当脐动气略宁。仍遵昨法。候仪吉先生政。", "14613": "入夜神烦，阴亏火旺，语言错乱，痰浊内蒙，致有汗不解，舌苔霉黑，脉象虚实，渴不多饮。深虑发痉呃厥变端，再拟存阴清热化痰泄浊，候旭高先生鉴定。", "14614": "神识虽清，热势不退，齿垢未脱，动气又作，脉数无力，正虚邪恋，尚虑变端，方候旭高先生鉴定。", "14615": "宋湿温过候，斑疹并见，心胸烦懊，神识模糊。脉数混混而不清，舌心苔干而不腻。湿蕴化热，热渐化燥。气粗短促，目赤耳聋。阴精下亏，风阳上亢，虑其内陷昏痉。拟生津达邪，兼芳香逐秽。", "14616": "二诊湿温邪在太阴、阳明，湿胜于热，太阴为多。热胜于湿，阳明为甚。日晡烦躁，阳明旺时也。口虽渴，苔仍白腻，乃湿蕴化热，余湿犹滞，气火熏蒸，蒙蔽清窍，故斑疹虽透而神识时糊，脉沉小而数疾，皆邪郁不达之象。倘若热甚风动变痉，便难措手。", "14617": "三诊湿温旬日，脉数较大于昨，热势较盛于前，所谓「数则烦心，大为病进」，并非阴转为阳，自内达外之象。舌苔白厚，上罩微灰。面红目赤，阳盛之征。头昏耳聋，阴虚之象。小溲窒塞，气化不及也。当生津以彻热，利窍以化湿，救阴不在肾而在生胃津，去湿不可燥而在通小便。盖汗生于津，津充汗出而热解。小肠为心之府，小便通利，心火降而神清。", "14618": "四诊湿热郁蒸，如烟如雾，神识沉迷，脉时躁时静，静则神倦若寐，躁则起坐如狂，邪内陷矣。虽便不通，而腹鸣不满，肠胃不实，其粪必溏，未可骤攻下之。大凡温邪时证，验舌为先。今尖苔白，上罩微霉，邪在营气之交。叶氏云：邪乍入营，犹可透热，仍转气分而解，如犀、羚、玄、翘等是也。从此立方，参以芳香宣窍。", "14619": "七诊下后舌黑稍退，而脉反洪大，神识仍昏，阳明火旺也。清阳明燔灼之火，救少阴涸竭之阴，用景岳玉女煎。", "14620": "胡素有肝胃病，适挟湿温，七日汗解，八日复热。舌灰唇焦齿板，口渴欲得热饮。右脉洪大数疾，左亦弦数。脘中仍痛，经事适来。静思其故，请明析之。夫肝胃乃腹中一脏一腑，木乘土则气郁而痛，若不挟邪，安得寒热？即有寒热，断无大热，以此为辨也。又询大便坚硬而黑，是肠胃有实热，所谓燥屎也。考胃气痛门无燥屎症，惟瘀血痛门有便血，然此证无发狂妄喜之状，则断乎非蓄血，此又一辨也。渴喜热饮，疑其为寒，似矣。不知湿与热合，热处湿中，湿居热外，必饮热汤而湿乃开，胸中乃快，与真寒假热不同。再合脉与唇观之，其属湿温挟积无疑。《伤寒大白》云：唇焦为食积。此言诸书不载，可云高出千古。", "14621": "原按：病本湿温挟食，交候战汗而解，少顷复热，为一忌。汗出而脉躁疾者，又一忌。适值经来，恐热邪陷入血室，从此滋变，亦一忌。故用豆豉以解肌，黑栀以清里，一宣一泄，祛表里之客邪。延胡索通血中气滞、气中血滞，兼治上下诸痛。郁金苦泄以散肝郁，香附辛散以利诸气，二味合治妇人经脉之逆行，即可杜热入血室之大患。栝蒌通府，赤苓利湿。加竹茹、连翘，一以开胃气之郁，一以治上焦之烦。外用葱、盐热熨，即古人摩按之法，相赞成功。", "14622": "复诊服药后大便一次，色黑如栗者数枚，兼带溏粪。脘痛大减，舌霉、唇焦俱少退。原为美事。惟脉数大者变为虚小无力，心中觉空，是邪减正虚之象，防神糊痉厥等变。今方九日，延过两候乃吉。", "14623": "诒按：大解后热平，脉转弱小，倘内伏之热邪已净，或稍有余热而不甚重，则从此各候俱平，祗须清养而已。若停一二日，伏邪再炽，则脉随病变，或仍数大，亦未可知。若热势盛而脉虚小，是邪盛正虚之重候，仍当随见证治之，不得以九日两候等语为凭也。", "14624": "某久病元气未复，又感湿温，已逾旬日。解表、疏中、通下之药，皆已服过。现脉仍数，舌白腻。头汗多，身热不解，咳嗽不扬，小溲不爽。且以分泄三焦，再看转机。", "14625": "二诊温邪挟积化燥。昨服药后战汗不透，大热虽减，里热仍炽。舌霉边白，脉形不显。高年恐其内陷。", "14626": "查证交八日，舌苔灰白腻，渴不多饮，咳逆不爽，痰多稠黏，周身骨节疼痛，两胁痹痛尤甚。大便濡泄，神识时糊，脉形软数，证属湿温。邪居手足太阴，而以手太阴为要。盖肺主一身之气，气机不达，则三焦窍络皆阻。故此病之所虑者，在于气急，气急乃喘之渐，若喘甚不休，则有厥脱之危。拟方备商。", "14627": "李暑邪内闭，恶寒发热，脉象不达，口不能言，先有咳嗽，此肺气闭塞。拟开而达之。", "14628": "安连日烦劳忧虑深，暑邪伤气易归心。神昏脉数细而沉，病危甚！邪闭心胞，如火如焚。舌色干黄唇齿燥，耳聋便泄津枯了！三焦皆病须分晓，究治疗，河间热论宜参考。", "14629": "某伏暑挟积伤脾，身热、腹满、便泄，脾伤则木横，热胜则风动，故手足搐搦，眼吊口噤，渐著角弓反张之状，幼科所谓惊，即大方所谓痉也。乱进丹丸，频灌汤水，水饮留伏，中气不运，以致胸腹膨满，漉漉有声。法当转运中气，用连理汤法。然脉细如丝，终为险候。", "14630": "李暑湿先伏于内，凉风复袭于外，交蒸互郁，皆能化火，湿遏热伏，其热愈炽，故其为疟也，先寒后热，日轻夜重，喻氏所谓阴日助阴，则热减而轻，阳日助阳，则热甚而重也。夫疟之发，必从四末始，既必扰及中宫，故心胸烦躁，中脘痞塞，又必先呕吐而泄泻，泻已乃衰，腹中犹胀。所以然者，热甚于中，蒸熏水谷之湿，上泛而复下泄。热势得越，烦躁乃安，余湿复聚，故仍作胀也。今当疟退，脉弦带数，舌苔白腻，小溲不爽，本有胃寒，痰浊素盛，虽从未得汗，表邪未解，而病机偏重于里，法从里治。大旨泄热为主，祛湿兼之，解表佐之，是亦表里分消，三焦并治之意。", "14631": "杨年过花甲，病逾旬日，远途归家，舟车跋涉，病中劳顿，雪上加霜。欲询病原，无从细究。刻诊脉沉糊，神昧，舌强色白，中心焦，身热不扬，手足寒冷，气短作呃，便泄溏臭。是属伏邪挟积、正虚邪陷之象。深虑厥脱。", "14632": "三诊伏暑化燥，劫津动风，舌黑唇焦，鼻煤齿燥，神昏，手指牵引。今早大便自通，据云病势略减。然两脉促疾，阴津消涸，邪火燎原，仍属险象，恐其复剧。", "14633": "复诊投两解法，得汗得便，竟安两日。昨已起床照镜，开窗看菊，须臾之间，渐渐发热，热甚神糊，两目上视，几乎厥脱。逮黄昏，神渐清，热渐减。脉沉不起。据述热时舌色乾红，热退舌色黄腻。此乃湿遏热炽，将燥未燥，将陷未陷。但阳证阴脉，相反可虞。勉拟河间甘露饮，涤热燥湿之中，更借桂以通阳，苓以通阴，复入草果祛太阴湿土之寒，知母清阳明燥金之热。", "14634": "某伏暑为病，湿热居多，阴虚之体，邪不易达，此其常也。然阴虚大有轻重之分，须知此证虚亦不甚，邪亦不多。耳鸣眩悸，苔浊胸痞，微寒微热，脉形弦数。未便大补，亦不可重剂攻邪。但得脉情无变，可保无虞。", "14635": "胡伏暑三候，神糊呃逆，手肢微痉，痰多舌白，渴不多饮，音低，脉大而虚，殊属棘手。今日忽周身干燥而痒，烦躁不安。细询病原，从未得汗。按仲景云：汗出不彻，身痒如虫行皮肤中，久虚故也。吴又可云：发根燥痒，心烦如灼，名曰药烦，中气虚也。经云：声如从瓮中出，是中气之湿也。又谓言微音低，谓之夺气。由此推之，明是中虚浊恋，液涸痰蒙，势极凶危。惟有和中宣化，听其胃气自为敷布，以冀万一生机。", "14636": "吴暑湿伏于太阴，中焦阳气不化。神蒙若寐，身热不扬，肢冷脉濡，手指牵引，舌根牵强，风痰阻络之象。曾用通阳益阴、云蒸化雨之法，病亦无甚增损。然舌苔灰白厚掯，口泛甜味极甚，中宫有浊，阳不舒化。仿缩脾饮醒中化湿浊，浊化则口甜减，阳舒则蒙昧清。", "14637": "赵高年元气素亏，未病以前先已倦怠乏力，微觉咳嗽。五六日来加以发热，热势起伏，是有新邪乘虚而袭，引动伏邪晚发也。今诊脉小数而虚，干咳欲呕，舌边光红，根苔白掯，热甚无汗。津枯邪恋，虑其化燥神昏。", "14638": "李伏邪湿热内蕴，三焦气机不达。午后发热，胸闷头胀，尿少无汗。舌苔白腻，脉象软细。拟开上、疏中、渗下，仿河间法。", "14639": "浦伏邪挟积，阻塞中宫。疟发日轻日重，重则神蒙烦躁，起卧如狂。此乃食积蒸痰，邪热化火，痰火上糊胞络，怕其风动痉厥。脉沉实而舌苔黄，邪积聚于阳明，法当通下，仿大柴胡例备商。", "14640": "诒按：脉舌与证合参，大柴胡是的对之药。", "14641": "三诊昨日疟来，手足寒冷，即时腹中气撑，上塞咽喉，几乎发厥，但不昏狂耳。此乃少阴疟邪，挟内伏之痰浊，上走心胞为昏狂，下乘脾土为腹撑。脾与胃为表里，前日之昏狂，病机偏在阳明，故法从下夺。今腹胀、舌白、脉细，病机偏在太阴，法当辛温通阳、转运中气为要。随机应变，急者为先，莫道用寒用热之不侔也。", "14642": "四诊投姜附、达原、神香、二陈合剂，喉中汩汩痰声顿时即平，腹胀遂松。今脉缓大，神气安和，腹中微觉胀满，痰多黏腻。脾脏阳气虽通，寒热痰涎未化。仍宗前法，轻减其制。", "14643": "陈烂喉丹痧，乃温热时邪，肺胃受病，发于春夏为多。首用辛凉散邪，继用甘寒化毒，是为大法。今交秋季，而贵地（江阴）盛行此证，证虽同于温热，而义则有分。大抵时行为厉，多由地气郁发，轻则偏患一方，盛则遍及他境。吴又可谓「疫厉为邪，著无常处，气有盛衰，所伤亦异」是也。贵地僻处江隅，今岁夏秋久晴少雨，热逼水土之中，郁极则发，湿上甚为热。交秋燥金司令，热胜金燥，邪干肺胃，所患尽属丹痧，而咽喉或痛、或肿、或腐者，由乎燥火湿热孰轻孰重，与体质之偏燥偏温而攸分也。兹阅所服之方，初用升、葛等之升发，继用芩、连等之苦寒，虽亦有辛凉解散、甘寒清化者，仍用升提苦燥夹杂其中，要未明岁气天时，与病成而变之旨，徒守老成之见，不通权变之方，譬犹苦拒剑阁，而寇兵已早渡阴平，同一局也。刻下序届秋分，虽当燥金用事，而消残日暑，尚余湿热蒸淫。经云：「先夏至日者为病温，后夏至日者为病暑。」则知先秋分日者为病暑，后秋分日者为病燥也。此病起于秋分以前，谓非伏暑湿热之使然欤？湿热郁蒸则化火，互相传染则成毒。然则上解肺胃之火，下清湿热之邪，芳香辟秽，甘寒化毒，苟理有可通，必法有可采。至于肌肤之红，咽喉之腐，胸中之烦躁，舌上之浊苔，口之燥渴，脉之数急，身之壮热，溲之短涩，干呃不已，饮食艰进，种种皆为湿邪火炽，邪不外达之象，凶险何辞，顾已共云而共闻之矣，兹不烦赘。", "14644": "三诊半月未诊，小愈复剧。痧乃阳邪，速来速去，安得留恋至今，意必有过慎失察等弊。或热邪未净，而早用滋阴。抑胃气未清，而漫尝滋味。容或有之，不可不告也。据述：七八日前，身热大减，胃气渐开，恶食陈米，进以新香稻粥，此外无他。夫谷食虽非荤油之比，然早稻性温，壅气助热，《内经·热论》有食复之禁，此其然欤！今诊脉数大无力，右脉涩滞不调，身时燥热，口仍干渴，咽腭蒂丁白腐满布，头面手足肌肤浮肿，颐毒穿溃，脓水清稀，面色干枯，神情困惫，而又脘腹胀痛，舌苔黄浊，正虚邪恋，复夹食滞，攻补两难，殊属棘手。勉拟一方，备候商用。", "14645": "贺胸背臂膊肌肤隐隐有红点，咽喉红紫碎腐，此即烂喉丹痧之症也。奈何认作喉蛾。清之不已，更泻之，以致邪不外达，火反内郁，右腭续加肿痛，痛掣耳中，诊脉不见浮弦洪数之象，而反软数模糊，时时恶寒，皆邪郁不达之明验。今证交五日，漫投清泻之后，丹痧欲透不透，深防内陷之变，急与解肌透达，兼以清化。", "14646": "二诊左脉较昨稍大，右脉仍然不利，胸背肌肤红点略透，而喉肿益甚，乃肺胃邪热欲达不达，而痰火又上盛故也。总之，早进寒凉，是谓倒行逆施，故证几及候，当退邪之时，而势犹发轫，正属火炽之际，仍拟透解，兼以清化。", "14647": "四诊昨议清营泄卫，服后似不相安。一夜少眠，痰多干呕，咽喉仍痛，诊脉缓滑不数，是热且退矣。想因体肥多湿，湿得热而蒸痰，痰阻肺胃，胃气失降，故邪热虽因清泄而除，而稠痰因清泄而盛。是必以降气化痰为主，清解次之。盖必得气降而痰始化，亦必痰化而气渐和也。", "14648": "二诊《脉经》有寸左右弹，阳跷为病之诀。《内经》有阳跷脉满，令人不寐之文。大抵阳盛阴亏，卫气不交于阴，此寒热止而复来，仍属营卫不和也。阳跷者，少阴之别，阳跷由外踝而上行卫分，阴翘由内踝而上行营分。夫肺主卫，心主营，又脾为营之本，胃为卫之源，盖以营卫生成于水谷，而五脏多受荫于脾胃。《灵枢》半夏秫米汤，主阳跷脉满，卫气不得入于阴，阴虚而目不瞑者，即以和脾胃，调营卫，交通阴阳为治，未尝专主奇经。自古奇经为病，亦未尝有专主之剂。然以半夏秫米施之于此病，似有不合者，嫌其燥也。今舌边碎痛而恶辣味，体质阴亏而喜甘柔之药，其不宜辛燥可知矣。连日用方大法，甘润益阴，不出门冬、玉竹之属。昨因疟势寒热又来，未便进剂，自饮百合汤数盏，咳缓得寐，颇觉相安。思百合色白入肺，其形象心，甘苦微寒，为心肺二经生津清火之药。仲景用百合一味为君，治百脉一宗，悉致其病，从心营肺卫立法。王晋三注之甚详，不遑缕晰。经云：问病人之所好恶，即可得其治法。今遵此旨，燮安世长兄闻之，得毋又笑其不惮烦乎？", "14649": "严年届六旬，元气素弱，向有肝气，近患三疟。两月以前，先受伏暑。小愈之后，三疟遂作。脉弦，肝胃尤甚。木胜胃土，恶谷厌纳，痰多呕恶，心跳少寐，便闭溺赤。盖胃气一虚，百病丛生矣。高年虽大便两旬不通，未可以通腑为务。培养中气，启胃化痰，是为扼要。调和营卫，退其寒热佐之。", "14650": "渊按：运脾气，补脾阴，和营卫，温督脉，前数方皆虚疟、久疟治法。", "14651": "营久患疮疥，湿热浸淫，复因外感暑湿为疟，缠绵不已，变为三疟。诊脉濡小，其湿仍恋，而元气渐伤，虑加腹满，宜早图之。然须安逸忌口为要。", "14652": "徐左脉细弦，肝肾亏也；右脉软弱，脾胃虚也。三疟之后，气血两亏。补肝肾，调脾胃，养气血，必得安逸少劳而后可也。", "14653": "复诊疟脉自弦，弦大者为阳，其邪易达。今疟来热势稍轻而短，邪有退机矣。仍从前法。", "14654": "丁三疟久延，营卫两伤，复因产后，下焦八脉空虚。今病将九月，而疟仍未止，腹中结块偏左，此疟邪阻于血络，聚于肝募，是属疟母。奄缠不已，虑成疟劳。夏至在迩，乃阴阳剥复之际，瘦人久病，最怕阴伤。趁此图维，迎机导窾，和阳以生阴，从产后立法。稍佐搜络，以杜疟邪之根。", "14655": "某素有痰饮咳嗽，近复凉风外薄，食积内停。寒热似疟，脉弦数，额角痛，胸脘痞胀，大便不通。是有表复有里也，拟以疏里解表。", "14656": "再诊脉弦数，两手掌心独热，大便五日不通，舌苔薄白不黄，燥屎尚未全结。欲通其腑，缓法为宜。", "14657": "马高年下痢，一日夜百余次。舌苔白掯，身热恶心，诊脉细，饮食不纳，痢下五色，皆为忌款。败毒散法初起的是，然须人参扶正和胃。若喻氏痢疾门中,五色噤口不治者多。尚祈商政是荷。", "14658": "孙湿温邪陷厥阴，下痢色紫后重，左脉沉小，右脉弦大，舌黄，晡热，是阳明积热内恋，而木来乘土。高年体虚神怯，防其厥脱。", "14659": "某红痢日久，脾气必虚，营气必耗。前方理中汤下驻车丸，颇验。奈轻听人言，服红曲、滑石末，致痢复剧。脉迟缓而涩，舌薄白而底绛。渴不贪饮，口恶甜味。素体多湿，今脾阳失运，湿又动于中矣。徐灵胎云：血痢挟湿者，胃风汤最妙。《医归·痢疾门》亦采是法。", "14660": "渊按：理中汤温运中阳，驻车丸分导湿热，从脉象迟涩看出。红曲、滑石适与相反。", "14661": "李久吸洋烟，脉沉而细。病方三日，微寒微热，头略胀痛，昼不痢，痢在夜。是属寒邪，而反色赤者，寒伤营也。当以和营散寒、温通阳气为法，勿与常痢同治。", "14662": "渊按：脉细肢寒，昼不痢，痢在夜，乃脾阳不能统摄营阴也。", "14663": "蔡右脉细弦，木侮土也；左脉细弱，肾水亏也。病由肝气而起，水不涵木也。兹患下痢赤白，木胜土衰，湿热不化也。华先生用补中升阳，参入育阴，从本求治，极有见地。鄙意再参温化，乃兼顾脾肾之阳气也。", "14664": "原注：此病两脉虚濡，脾胃元气大弱，似宜参入扶正为善。然下痢古称滞下，起于湿热居乡，早补早敛，往往受累，此河间苦辛宣通腑滞之法，所以为痢门必采之方。若补阴阳、治脾胃，多为久痢而设。尚非此时议论，所以宁落轻浅，不用深重之剂，盖行远自迩之意云耳。", "14665": "陆《脉经》云：代则气衰，细则气少。多指阳气为言。今下痢而得是脉，脾胃之阳微特著。况形衰畏冷，而小便清长者乎！惟下痢赤者属血分，腹中痛者为有积。立方从此设想，寻其罅而通之补之，亦治病之机巧也。", "14666": "薛先患红痢，续加以疟，又变泄泻，泻止仍痢，两月有余。脉弦硬，昼无小便，每交子后至辰便痢数次，小溲亦得稍通。此伏暑湿热蕴于肠胃及厥阴，厥阴之表便是少阳，故先见热痢，后兼疟象，乃厥阴、少阳表里同病也。疟后大便溏泄者，少阳木邪侮土也。泻止而疟痢仍作者，胃气强旺，土不受邪，仍还厥、少两经也。小便少者，阴气亏则渗愈少，当滋其化源也。今清厥阴之热而举清阳，兼益肾之阴，运脾之湿，从白头翁合胃风汤意。", "14667": "复诊痢减腹仍痛，肝胃未和也。现值经来，脉弦寒热。血虚木郁。拟养血疏肝。", "14668": "徐红痢匝月，仍腹痛后重。据云，先曾发疟三次。此属中虚表邪传里。现今脉细肢寒，太阴阳气已弱。小便艰难，膀胱气化又钝。拟开其中焦，化其湿热，兼升阳解表，亦表里双解之法也。", "14669": "张便痢白腻如水晶鱼脑色，小便不利，少腹偏右板窒。诸医以为肠痈，固亦相似。然考肠痈为病，有寒有热。《金匮》并出二方，如大黄牡丹汤、薏苡附子败酱散，概可见矣。此证则属寒积，试观脉弦紧而不数，面色青而不渴，是其征也。宜用温通。", "14670": "某泄痢白腻，腹不痛，脉沉细。此寒也。宜温也。", "14671": "李河间论痢属热者多，而景岳论痢属寒者不少。此证腹不甚痛，但肛酸且胀，脉紧肢寒，并不发热，兼素有寒疝，苔白不渴，寒象为多。宗景岳论治之。", "14672": "某休息痢将及五年，腹中块垒时痛，痢下仍兼干粪。脉弦迟，苔灰白。此虚而有寒积也。《本事方》云：痼冷在肠胃，泄泻腹痛，宜先取去，然后调理，不可畏虚养病。此证的是。姑拟一方备采。", "14673": "某休息下痢，延及半载，色红而黏，脉弦。是风邪久羁于肠脏营分之中，而莫能出。近日畏风身热，是又感新风于外也。补中升阳，兼凉血为法。", "14674": "薛便泄半载，脾肾两亏。脉沉细涩，阴阳并弱。阳痿不举，精伤特甚。面白无华，气虚已极。足跗浮肿，阳虚湿注于下。纳食暖气，胃虚气逆于中。调治之方，自宜脾肾双补，阴阳并顾。然刚热补阳，恐劫其阴。滋腻补阴，恐妨其胃。刻下节届清明，木旺土衰之候。脾者，土也。肾属坎水，一阳藏于二阴之中。当于补土中兼顾肾藏阴阳为是。", "14675": "复诊脾肾双补，略见小效。今腹中鸣响，气向下坠，属脾虚气陷。舌心光红，脉沉细数，为肾藏阴伤。用补中升阳法。", "14676": "王脾虚气陷，肛门先发外疡。疡溃之后，大便作泻，迄今一月有余。自云下部畏冷，而两脉弦硬不柔，此胃牢脉，证属阴虚。法以温中扶土，升阳化湿。", "14677": "陈吐泻转筋，肢冷脉伏，汗出音低，目陷鼻冷，口不渴，身不热，阳欲脱亡，险重之证，拟方备商。", "14678": "二诊霍乱虽平，汤水下咽呛吐，小便不利，四肢仍冷，两手脉微细，冷汗仍出，今拟五苓通利其阴阳，佐以清上，冀其不呛为妙。", "14679": "曾脉形乍大乍小，面色暗晦不泽，似有一团阴气阻遏于中。苔黄而湿，腹满足肿，小便黄赤，又有湿遏热伏之形。色证合参，是属女劳黑疸。变为腹满，在法难医。姑拟泄肾热以去脾湿，仿《金匮》法。", "14680": "施三疟止而复作，腹满平而又发。今目黄脉细，面黑溺少。防延黑疸。然疸而腹满者难治，姑与分消。", "14681": "复诊面色黧黑，腹满足肿，脉沉而细。此脾肾之阳不化，水湿阻滞于中，证势甚重。且与通阳燥湿。", "14682": "章脉禀六阳，先天元气充足，足征松柏之姿，老而弥劲。平素善啖，后天亦富，所以望八之年，一切起居如壮盛之人。然而病患类中者何居？或指为肝肾下虚，而用地黄饮子；或指为中气不足，而用耆术补中。一遵河间之训，一执东垣之说，又有泄降肺气者，乃丹溪之法。要皆各有意见，立方定论，尽属高明，珠玉在前，无从置喙。今诊得脉象洪大，右肢偏废，面色虽无华彩，然亦不见萎黄，目尚有神，言不蹇涩，舌边淡红，中心苔白。前月有二十多日大便不通，初一日大便解后，随即小便不利，似癃非癃，似遗溺而并非遗溺。少腹胀满，饮食日减，种种病情，大抵由中气不足，湿热不化，内风暗动使然。夫中气者何？脾胃是也。何以不足？劳碌伤之也。劳碌何以伤脾胃？脾胃主四肢故也。内风何以暗动？脾胃属土，土衰则木横，木横则风动也。脾胃失运则湿热不化，故舌上有浊苔也。若果肝肾精血衰惫，舌且干而光矣，安得有苔。然又有阳虚浊聚，舌上有苔者，其证必喘而多汗，脉沉微细为辨。今脉洪大，似非阳虚之可拟。然小便何以不利？经曰：「中气不足，则溲便为之变。」又曰：「膀胱者，州都之官，津液藏焉，气化则能出。」拙见用方似宜转运中枢，利其气化为先。《内经》有云：凡病皆当治本，惟大小便不利者，法当先治其标。盖以小便不利，势必膀胱胀满，满极则上攻腹胸，喘厥臻至矣，安得不先治其标乎。", "14683": "二诊按类中一证，风由内生，非关外感。昔河间主火是训，是气召风入，气为本而风为标。丹溪主痰是训，是痰召风人，痰为本而风为标。喻嘉言聪明特识，谓阳虚邪害空窍为本，或气或火或痰为标。以予论之、曰召、曰入、曰邪害，内风外风，混同莫别。惟近代叶天士直指名之曰内风掀动为痱中，最为明了。然则内风何以掀动耶？或由水亏不能涵木，河间之训是也。或由土衰不能培木，东垣之训是也。丹溪湿痰之说，又补二家之未逮。而喻氏阳虚之说，又补三子之未备也。今诊脉大稍敛，一息四至，不失和缓之形，是有胃气。经曰：「得神者昌」，又曰：「安谷则昌」。服药后食粥两盏，神情安稳，未必立见倾危。但少腹胀满，大如覆碗，连及乎脐，诚如昨案所云，倘若上攻腹胸，喘厥臻至，奈何奈何！夫少腹为膀胱之部位，膀胱居少腹之中央，凡小便秘而膀胱胀满者为水，利其小便即愈。小便通而少腹胀满者为气，徒用通利无益也。膀胱者属太阳，有上口而无下口，气化而后能出，亦必气化而后能入，此病欲溲不溲，不溲反遗，乃膀胱启闭无权，阳气失化也。是当以输化膀胱之阳气为要矣。据述未病以前，小溲已不自如，则知中气不足，清阳下陷，已非一日，徒化膀胱之阳，而不助其中气，治与不治等也。握枢而运，惟有从中宣化其上下，仿喻西昌进退黄连一法，以就高明教正。", "14684": "四诊医者意也，以意会之，随机应变，初无一定之法，亦无一定之方。此证初因中气不足，膀胱失化，故前以转运中枢，输化阳气得效。今则心火妄动，相火随炽，故昨以清心导赤泻肝止痛立法，幸获奏功，慰喜慰喜。兹诊左脉稍平，知肝心之火渐退。而右尺尚旺，乃肾膀之火未清，仍以前法增损。", "14685": "三诊昨晚进药之后，舌辣麻涩，片刻即已，一夜安寐，昧爽略觉心跳，总属心血衰少之故。今诊脉稍柔，风阳有渐熄之机，而语言稍贯，机巧有渐灵之意。可喜可喜！然窃有恳者，贵恙既因操劳而起，似宜屏绝应酬，不拘常理，闭目静养，返观内照，使水升火降，心肾自交，交则为既济，济则诸恙霍然矣。昔朱大复先生教人心常放下，目常向下，上者降则下者升，亦交心肾之法也。至于用药养心血以安神，则风阳自静。补阴精而益志，则机窍自灵。仍佐化痰和胃以治其中，经旨所谓交阴阳者，必和其中也。", "14686": "王两手关脉皆见一粒厥厥动摇之象，此脾虚木胜，内风动跃之候也。左半肢体麻木不仁，头眩面麻，此属偏枯，虑延仆中。", "14687": "复诊两关脉厥厥动摇之象大减，其内风有暗熄之机。左手屈伸稍安，左足麻木未愈。今拟补肾生肝，为治本之计。", "14688": "胡少腹胁肋，肝之部也。腰，肾之府也。年老则精血枯而络脉空，肝气乘虚入络，湿热又从之为患。补养精血，疏肝通络，兼化湿热以治之。", "14689": "复诊补养精血，疏通脉络，胁肋之痛稍减。惟小溲短少，夜半以后脘腹觉胀，是浊气不化也。前方加通阳泄浊之品。", "14690": "某脉双弦，有寒饮在胃也。脘痛吐酸，木克土也。得食则痛缓，病属中虚。当和中泄木祛寒，小建中汤加味主之。", "14691": "某脘痛，肢冷脉伏，头汗淋漓。防厥。", "14692": "某肝木挟下焦水寒之气，乘于脾胃。脘痛攻肋，呕吐酸水，脉细而弦。拟温中御寒，扶土抑木方法。", "14693": "某病将一载，肝气横逆而不平，中气久虚而不振。惟肝逆，故胸脘阻塞而攻冲。惟中虚，故营卫不和而寒热。凡大便溏，饮食少，右脉细，左脉弦，是其证也。四君子合逍遥加左金，是其治也。", "14694": "谢久患肝风眩晕，复感秋风成疟。疟愈之后，周身筋脉跳跃，甚则发厥。此乃血虚不能涵木，筋脉失养，虚风走络，痰涎凝聚所致。拟养血熄风，化痰通络。", "14695": "金左手脉沉弦而涩数不调，乃血虚而肝风暗动也。右关脉独缓滑，胃有湿痰。尺寸俱弱，金水两虚。证见耳聋，两肩膊酸而难举，痰多，口中干腻，是其征也。", "14696": "丁脉左弱为血虚，右弱为气虚，气血两虚，上为头眩，半身以下皆形麻木而成瘫痪，甚则心乱神昏，此肝风挟痰所致。法当清上补下。", "14697": "顾血不养筋，筋脉牵掣，昼日则安，暮夜则发，不能安卧，病在阴经。宜养血以和经脉。", "14698": "诒按：此养阴柔肝之正法，与前人复脉、定风、阿胶鸡黄等法，用意相合。", "14699": "徐少腹之块已平，小便已利而反不禁。索有肝风脾泄宿恙，近增右手麻木。脉象弦大而滑，时觉痰多气升。此中气已虚，精血不足，内风走络，脾湿生痰。法当兼顾。", "14700": "陈诊脉左关独弦滑，风阳挟痰上扰阳明，头额偏左连及腮齿皆痛。拟熄风阳，兼清痰火。", "14701": "华病久正虚，阴阳两弱，坎离不交，夜不成寐，久卧于床，不耐烦劳。兹因舟行跋涉，远道就诊，忽然神糊不语，两手不定，遮晴挦发，烦躁不安。诊脉促乱，饮食不进。想由舟中热闷，鼓动风阳，扰乱神明，卒然生变。姑拟熄风和阳，安神定志。冀得神清谷进，或可再商。", "14702": "某肝为风脏而主筋，心为火脏而主脉，心包络与三焦相为表里，俱藏相火。心包主里，三焦统领一身之络。此病起于病后，心中嘈热，胸前跳跃，继而气攻，背脊如火之灼，或大或小，或长或短，皆在经络脊脉之中。良由病后络脉空虚，相火内风，走窜入络。非清不足以熄火，非镇不足以定风。然而络脉空虚，使非堵截其空隙之处，又恐风火去而复入。故清火、熄风、填窍三法，必相须为用也。第此证实属罕见，医者意也，以意会之可耳。仿仲景法。", "14703": "某右脉弦滑搏结，左但弦小，先曾吐血，血未全止，而复发痫厥。此肝火冲激，乘于肺则血上溢，乘于脾胃，为痰所遏，则痫厥作焉，此右脉之所以弦滑也。左但弦而小，肾水不足，不能涵木。法当壮水，则木不亢而火平，佐以化痰镇逆，治其痫厥也。", "14704": "某经云：「年四十而阴气自半也，起居衰矣。」况五十乎。此证肝肾阴亏于下，风阳上升，兼挟痰浊，故去年二月起，病先呕，而继以头眩心嘈，至今不能全愈。诊脉浮弦而大，按少力，是属升多降少，上盛下虚，久延虑其仆中，法当养阴潜阳化痰并进。然养阴补下，当以丸剂。潜阳化痰，煎剂为宜。更须自知静养，庶几无事。", "14705": "某病原的系风阳走络，攻注疼痛，实由肝郁得之。但口中甜腻，胃家又有湿浊，法必兼理为妥。惟是络脉之病，不能速愈，须耐心安守为嘱！", "14706": "某寡居十载，愁肠苦心。牙龈出血，有时若痫，其病已久。兹一月前，猝遭惊恐，遂神糊语乱，口吐紫血，腹胀不食。两脉模糊，难以捉摸。此乃惊动肝阳，神魂扰乱，血随气逆。是即薄厥之属。今两足常冷，阳升于上。急以介类潜阳，重以镇怯。冀其厥止，再商。", "14707": "某春脉当弦而反微，是肝虚也。肝虚魂不藏，夜不得寐。昼日当寤而反寐，是胃虚也。胃为两阳合明之府，胃虚则阳气失明，故昼日反寐。补肝之虚以藏魂，益胃之虚以补气。", "14708": "孙病起有因，药投罔效。初如伏暑之状，渐延劳瘵之形，两脉弦搏不柔，两目正圆直视，舌心光红如柿皮，舌边碎缺如虫蚀，时躁时狂，时清时静。皆病之忌，然亦病之常，无足怪者。狂躁时目中常见绿衣红裤二童子，或在床扰乱，或出外游嬉，大似鬼附神凭，懦者以为有，刚者以为无，皆非也。大凡天下之事，不外乎理，而医之于理为尤切。细按病情，全属心肝两脏郁火变幻。心藏神，肝藏魂，心属离火，其色赤，肝属震木，其色青。木火一升，则神不守舍，两目正圆，直视如痉，掀衣烦躁如狂。所见绿衣红裤二童子，得非神魂之出舍乎？绿者，青之变色也。按《内经·大惑论》，有精神魂魄散不相得之文。妇人脏躁条，有悲伤欲哭，象若神凭之说。左氏论蛊惑之疾，仲景载狐惑之病，详察此病根由，必有所惑而不解，惑之既久，脏阴日伤，阳火日胜，精神魂魄散失，以致变怪莫识，昧者以为外来之邪魅，不知即是脏内之神魂，此真所谓大惑不解也。聊备此说，请质高明，未知以为然否？", "14709": "吴上年夏季痰火迷心，神呆语乱。愈后至今复发。现诊脉浮小弱，舌心红而苔白。语言错乱，哭笑不常。凭脉而论，似属心风。盖由风入心经，蕴热蒸痰所致。用《本事方》独活汤。", "14710": "复诊脉细数，懒言倦卧，其为精气神三者皆虚。然舌苔白腻，有痰且有饮。再察神情，静则气怠而若虚，动则气上而自乱，是虚而有痰兼有火也。火伏而痰不上升则静，静则虚象现，火动而痰升则躁，躁则虚象隐，非不虚也，痰火为之起伏也。治不越十味温胆加减。临证各有心思，悉关根柢。", "14711": "三诊阴遏于外，阳伏于内，阴如迷雾，阳若日光，今阳为阴遏，故沉沉默默而蒙昧，脉亦为之不显。有时阳光见𬀪，则起坐而神清，脉亦为之稍起。顷之阴霾四合，阳气复翳，则仍昏昏如寐。前案谓有痰饮郁于其中，十味温胆屡投不应。再思病源起于头眩心悸，苔白多痰，常服苍术见效。近因神乱若痴，多从事于痰火，清滋重镇，阴胜于阳，以致变幻。然欲开阴雾，法必通阳，譬之离照当空，而后阴雾始散。议进仲景苓桂术甘汤加味。", "14712": "何右关脉独滑动如豆，此有痰浊在中焦也。中脘皮肉觉厚，手足筋脉时或动惕，痰走经络之象。法当攻补兼施。", "14713": "陆素有痰饮咳嗽，土弱金虚。金虚不能制木，并不能生水。土弱不能御木之侮，并不能生金而化痰。病情有似风痰瘫痪，足软难行，口流涎沫，舌左半无苔，口常不渴，脉虚弦滑，大便坚燥。种种见症，皆显金土水不足而风痰有余。病根日久，调之不易，姑拟一方备采。", "14714": "某心境沉闷，意愿不遂。近因患疟，多饮烧酒，酒酣之后，如醉如狂，语言妄乱，及今二日。诊脉小弦滑沉，舌苔薄白。小水短赤，大便不通，渴欲饮冷，昏昏默默，不知病之所的。因思疟必有痰，酒能助火。痰火内扰，神明不安。此少阳、阳明同病，而连及厥阴也。少阳为进出之枢，阳明为藏邪之薮。今邪并阳明，弥漫心包，故发狂而又昏昏默默也。仿仲景柴胡加龙牡汤主之。", "14715": "二诊内热稍和，脉数亦减，腹中偏左有时作痛，年已二九，经事未通，血虚肝郁显然，虑延干血劳损。", "14716": "侯病已两月，外皮不热，而脉微数急，是里有热也。里热属阴虚，非关表邪，并无头痛恶寒。愈散其邪，愈虚其表，故反增咳嗽也。若谓湿热，亦似是而非。夫湿热蕴于中焦，必有胸痞恶心见症。此证无之，其非湿热明矣。近来数日腹中不和，大便溏。且以和中为主，兼理其脾肺，再商治本可耳。", "14717": "复诊和补相投，诸恙俱减。惟脉数未静，究属元气真阴亏损。但前之补在肺脾，再参入肾药，兼养其阴，以观动静。", "14718": "冯病延半载，骨热不已，鼻血时流，周身骨痛。营阴大亏，虚火内亢。脉沉搏数，口燥渴饮。劳损根深，入夏防剧。拟滋少阴，清阳明。", "14719": "钱心脾营阴内亏，肝胆风火上逆。内热头眩，项间结核。脉虚形弱，治以养营。然病由内生，不易速效。", "14720": "某咳嗽发热日久，前投补益脾胃之药六、七剂，谷食加增，起居略健。但热势每交寅卯而盛，乃少阳旺时也。少阳属胆，与肝相为表里。肝胆有郁热，戕伐生生之气，肺金失其清肃，脾胃失其转输，相火日益炽，阴津日益涸，燎原之势不至涸竭不止也。其脉弦数者，肝胆郁热之候也。刻下初交夏令，趁其胃旺加餐，拟进酸苦益阴和阳，清彻肝胆之郁热。考古有柴前梅连煎，颇有深意。", "14721": "徐肺脾两虚，心营亏损。咳嗽气塞，骨蒸夜热，脉形软数，面白无华。劳损根深，夏至防剧。", "14722": "复诊脉软数为气虚，骨蒸心跳为血虚，咳嗽头眩，面色痿黄，脾肺两虚之候也。", "14723": "复诊投扶土生金法，谷食反减，夜热增重，乃胃阴失降，虚阳外浮也。夫脾宜升则健，胃宜降则和，胃为阳土生肺金。今诊左脉数疾，为心肝阳亢之象。肝火戕胃，心火烁金。宜其食减热增，夏令防剧。", "14724": "四诊咳嗽内热俱减，惟脉之细数不退，仍为可虑。", "14725": "诒按：此阴亏而虚火上炎之证也。方以理中合生脉法，温中清上，两面周到。所云：土厚则火敛，金旺则水生，见理极精，非浅学所能学步。", "14726": "王病后胃气不醒，脘腹饱胀，近增寒热恶心，痰升气逆，咳呛口干，阻塞咽嗌，大便艰难，小便短涩，左胁有块，大如复杯，撑攻作痛。此因脾胃不足，肝木亢逆，清气不升，浊气不降，攻消克伐，元气愈伤，纳谷大减，津液日枯，虚火内炽，戕及肺胃，渐见火升颧赤、脉数内热之象，当成劳损。宜以扶土为主，升清降浊，佐以泻火清金，俾得中气安和，自然饱胀渐解。", "14727": "复诊就脉数内热、咳嗽、脘胁仍痛而论，乃阴虚肝郁成热，肺失清肃，仍防吐血。", "14728": "张十年前三疟之后，盗汗常出，阴津大伤。去秋咳嗽气升，痰中带血。至今行动气喘，内热多汗，食少无力，脉虚细数。劳损根深。", "14729": "三诊盗汗气喘，咳嗽脉细。精气两虚，舍补摄肺肾之外，更将何法以治！景岳云：大虚之证即微补尚难见效，而况于不补乎？", "14730": "徐二月间吐痰带血，血止之后，略兼干咳。交清明节，咳嗽渐甚。四月初，身加发热。今诊脉细数，形容消瘦，行动气升。此属肾气先亏于下，复因劳碌感邪，延绵不已，虑成劳损。静养为佳。", "14731": "孙久有咳嗽血痰之恙，今复肛门结疡，是肺遗热于大肠。脉数音哑，劳损之根。时当夏令，火旺金衰，颇有气逆血沸之虑。", "14732": "高脉沉取数，其阴内亏，其热在里，劳损之候。证见咳吐白痰，心腹不时疼痛，痛则气满，得矢气则稍宽。病兼肝郁。据云咳嗽已及三年，初无身热，则病从痰饮而始，宜从痰饮气郁例治之。", "14733": "冯久咳痰稠，上午发热，面色青黄。左脉细数，右脉软弱。病属上损。幸大便不溏，尚未过中及下。加谨调养，交夏至节无变再议。", "14734": "复诊咳嗽脉细数，前上午发热，今下午亦热，阴气渐伤。大便间或带血，脾气虚也。从景岳理阴煎例。扶过夏至节，一阴来复，病无增变，庶几可延。", "14735": "四君子汤合生脉散，加生地、怀山药、白芍、白扁豆、川贝、阿胶、红枣。", "14736": "赵漏疡日久，阴津暗渗。加以咳嗽气耗，考试劳神，于是咳甚气升、便溏内热、音哑喉痛等等，接踵而至。脉象细数，已成劳损。夫精气神为人身三宝，一有所伤，便为大患，况三者皆虚乎！敢谢不敏，幸熟察焉。", "14737": "王左脉空大，肾水亏也。倦怠无力，脾气弱也。食少则阴虚，阴虚生内热，证属内伤。", "14738": "诒按：补中益气补脾气，六味补肾阴，立法颇切实，惟左脉空大，方中升、柴二味，尚宜斟酌耳。", "14739": "胡脉软无力属气虚，便溏食少属脾虚，干咳无痰属肺虚，时觉口苦属心热移脾也。宜十补一清。", "14740": "李病将半载，寒热奄缠。前方补营，兼以疏郁，心悸腹胀仍然。兹更便溏足肿，是脾气虚弱也。脉缓无力，当补其脾，进归脾加减法。", "14741": "金骨格瘦小，先天元气不足。夏秋寒热，至今不已。脉细数弱，气血两亏。头不痛而但身疼，或口沃清水，此胃气虚寒也。当商温补，仿东垣法。", "14742": "赵脉沉数，手足冷，胸闷食少，脾胃衰弱。大便干燥者，肠中之津液枯也。法当温中土，润大肠，仿菟丝子丸加减。", "14743": "叶血止咳不已，脉沉带数，其根犹未去也。盖气犹风也，血犹水也，咳则气逆不顺，血亦逆而不顺矣。经络不和，血不宁静，必降其气而后血不复升，亦必充其阴而后火乃退耳。", "14744": "侯脉数血涌，胃气大虚。胸中痞塞，大便带溏，是痞为虚痞，数为虚数。咳血三月，今忽冲溢，唇白面青，断非实火。大凡实火吐血，宜清宜降。虚火吐血，宜补宜和。古人谓见痰休治痰，见血休治血，血久不止，宜胃药收功。今援引此例。", "14745": "复诊脉数退，血少止，而反恶寒汗出。盖血脱则气无所依，气属阳，主外卫，虚则不固也。最怕喘呃暴脱。犹幸胸痞已宽，稍能容纳。仿血脱益气例。经曰：阳生阴长。是之谓耳。", "14746": "诒按：以后方均是复脉加减。", "14747": "邢先天不足之体，曾发虚痰，溃而将敛。交春阳气升发，渐觉喉痒咳嗽，二、三日来，忽然吐血。今又大吐血，色鲜红。诊脉细促，心嘈若饥。一团虚火，炎炎莫御。用药虽宜清降，亦当预顾真阴。否则恐血脱阴伤而晕。", "14748": "张阴虚内热，咳嗽痰红，脉数无神。渐延劳损。", "14749": "程咳嗽四年，曾经失血。今已音哑，脉形细弱。真阴元气皆亏，劳损根深，药难见效。犹幸胃气尚可，大便未溏。姑拟甘润养阴，希图苟安而已。", "14750": "再诊咳嗽止而失血音哑，津液枯槁，劳损成矣。脉形细弱，精气两亏。《内经》于针药所不及者，调以甘药。《金匮》遵之而用黄耆建中汤，急建其中气，俾得饮食增而津液旺，冀其精血渐充，复其真阴之不足，盖舍此别无良法也。", "14751": "某始由寒饮咳嗽，继而化火动血。一二年来血证屡止屡发，而咳嗽不已，脉弦形瘦，饮邪未去，阴血已亏。安静则咳甚，劳动则气升。盖静则属阴，饮邪由阴生也；动则属阳，气升由火动也。阴虚痰饮，四字显然。拟金水六君同都气丸法，补肾之阴以纳气，化胃之痰以蠲饮。饮去则咳自减，气纳则火不升。", "14752": "范脉虚数，两尺愈虚。心肝脾胃俱受其病，惟肾独虚。心肝火亢，肺胃受戕，痰由湿生，血随气逆，咳嗽黄痰带血，掌中觉热。法宜养肾之阴，以清心肝之火，而肃肺胃之气。", "14753": "吕脉数左寸独锐，心经有火。吐血不止。法宜清养。", "14754": "庞去秋咳嗽，些微带血，已经调治而痊。交春吐血甚多，咳嗽至今不止，更兼寒热，朝轻晡甚，饮食少纳，头汗不休。真阴大亏，虚阳上亢，肺金受烁，脾胃伤戕，津液日益耗，元气日益损。脉沉细涩。口腻而干。虚极成劳，难为力矣。姑拟生脉六君子汤，保肺清金，调元益气。过夏令再议。", "14755": "原注：生脉散保肺清金。六君子去术嫌其燥，加扁豆培养脾阴，土旺自能生金也。不用养阴退热之药，一恐滋以腻肠，一恐凉则妨胃耳。从来久病总以胃气为本，经云有胃则生，此其道也。", "14756": "华咳嗽内伤经络，吐血甚多。脉不数，身不热，口不渴，切勿见血投凉。法当益胃，拟理中加味。", "14757": "薛吐血鼻血，牙血发斑，斑中出血，阳明之火极炽。而腹满濡软，少阴之气不运。病已三月，血有间断，有瘀血在腹中故也。食少身热，脉数，其阴已虚。拟养阴化瘀，清胃和中。", "14758": "薛痰饮久咳，咳伤肺络，失血。脉不数，舌苔白。不必过清。但顺气化痰，气顺则血自归经，痰化则咳嗽可止。", "14759": "郁历春夏秋，血证屡发。诊脉虚弱，形容清瘦。年方十七，精未充而早泄，阴失守而火升。异日难名之疾，恐应褚氏之言。治宜滋水降火，须自保养为要。", "14760": "钱内则阴虚有火，外则寒邪深袭。失血咳嗽，又兼三疟，病已数月。疟来心口酸痛，胸腹空豁难过。经云：阳维为病苦寒热，阴维为病苦心痛。此阴阳营卫之偏虚也。拟黄耆建中法，和中藏之阴阳而调营卫。复合生脉保肺之阴，复脉保肾之阴。通盘合局，头头是道矣。", "14761": "某素患呕血，血止复发。现有胸痛，时时嗳气。舌苔白腻，脉细而迟。此胃中有瘀血，挟痰浊为患也。", "14762": "某便血肠燥，脉大气虚。补气则清阳自升，清肠则便血自止。", "14763": "某肠痔脱肛便血，其根已久，有时举发。而脉象细数，营阴大伤，面黄少神，脾气大困，兼之腹中鸣响，脾阳且不运矣。一切苦寒止血之药，非惟少效，抑恐碍脾。拟东垣黑地黄丸法。", "14764": "三诊面黧腹肿，脉沉而细。此脾肾之阳不化，水湿阻滞于中。证防加剧。姑且渗湿通阳。", "14765": "金风湿相搏，一身悉肿，咽痛发热，咳而脉浮。拟越婢法。", "14766": "朱肿胀已退，脉象较前稍大，汗出至膝而止。阳气有流通之象，阴湿有消化之机。今以温理中州，中州得运，庶几决渎流通，寒转为温，否转为泰矣。然须调养百日，庶无反复之虞。", "14767": "杨脉沉，小便不利，面目肢体大腹阴囊悉肿，病属里水。鼻中流血，喉间略痛，肺家有郁热也。拟越婢汤。", "14768": "某产未满月，劳碌感寒，遂患寒热如疟，一日二三度发，所谓太阳风疟，营卫不和故也。自冬及春，阳气上升，伏寒化热，渐见口渴。弥月以来，阴雨潮湿，阳被湿遏，不得宣越，湿与热合，交蒸互郁，更感风邪，凑袭于肺，骤加咳嗽气急，一身面目四肢大腹悉肿，不得转侧，大便溏泄，小便短涩，舌心苔干，渴喜饮冷，左脉浮洪，右脉软数，病成风水。而寒热仍然，且兼多汗，势频于危，殊属棘手，虽有成法可遵，深恐鞭长莫及。宗仲景风水例，兼调营卫，顾其元气，仍不出产后感邪方法，备质高明商正。", "14769": "某痞块由大疟日久而结，多因水饮痰涎与气相搏而成。久则块散腹满，变为臌胀，所谓癖散成臌也。脉细如丝，重按至骨乃见弦象，是肝木乘脾也。口干，小便短少，是湿热不运也。匝月腹日加大。急宜疏通水道，泄木和中。", "14770": "某暑湿伏邪挟积，阻滞肠胃，中州不运，大腹骤满，腹中时痛，痛则大便黏腻，色红如痢，小水短少。脉沉滑数，是积之征也。拟大橘皮汤送下木香槟榔丸。", "14771": "复诊气与水相搏，大腹骤满，脉沉，小便不利，大便欲泄不泄。法以疏气逐水。", "14772": "孙脾虚胀满，面浮足肿，小便不利。脉形细数，元气大亏。虑其喘急之变。", "14773": "张木旺乘脾，腹胀如鼓，形瘦脉细，证属单胀。法当温通。", "14774": "杨两尺脉滑，湿热积滞在于下焦。小便不利，大腹胀满，是下焦不利，中焦气不通也。", "14775": "张痢后阳虚，水湿不化，腹满面浮足肿，而色青黄，脉来虚细。虑延臌胀重症。", "14776": "某病由肝郁，木横克土，湿热不化。先有淋浊，愈后渐渐腹胀，左肋微觉隐痛，身微有热，脉象细弦。木郁不达，虑延鼓胀。勿轻视之。", "14777": "唐经停十月，腹微满，脉沉细涩，脐上心下块长数寸。是属伏梁，因七情恚怒气郁痰凝所致。经曰：大积大聚，其可犯也，衰其大半而止。洁古谓：养正积自除，不得过用克伐。今拟开郁正元散法，理气行血，和脾化痰，寓消于补之中。", "14778": "丁久患休息痢，止数日后气攻胸脘板痛，上下不通，几至发厥，须大便通始减其痛。匝月以来，大便仅通三次。板痛者聚而成块，偏于右部，是脾之积也。脉沉紧而细，面色晦滞。阳气郁伏，浊阴凝聚。当与温通。", "14779": "复诊大便已通，脘腹之块未化，脉象沉弦而紧，面色之晦滞已明，阳光一𬀪，阴凝渐通之象。仍以温通。", "14780": "金气从少腹上冲咽嗌，则心中跳，胁中痛，初起寒热而呕，此奔豚气之挟肝邪者也。半月以来，寒热虽止，气仍上逆。脉沉弦小。宜宗《金匮》法。", "14781": "冯脉右关滑动，舌苔黄白而腻，是痰积在中焦也。左关弦搏，肝木气旺，故左肋斜至脐下有梗一条，按之觉硬，乃肝气入络所结。尺寸脉俱微缓。泄痢一载，气血两亏。补之无益，攻之不可，而病根终莫能拔。根者何？痰积、湿热、肝气也。夫湿热、痰积，须借元气以运之外出。洁古所谓养正积自除，脾胃健则湿热自化，原指久病而言。此病不谓不久，然则攻消克伐何敢妄施。兹择性味不猛而能通能化者用之。", "14782": "丁脉迟细，脘中有块，纳食撑胀，腹中漉漉作声，嗳腐吞酸，大便坚结。此脾胃有寒积也。当以温药下之，仿温脾法。", "14783": "洪结癖累累，久踞腹中。年逾六旬，元气下虚，中气已弱，肝气肆横，腹渐胀满。脉沉弦细，细而沉为虚为寒，沉而弦为气为郁。病关情志，非湿热积滞可比，攻消克伐难施。拟商通补，补者补其虚，通者通其气。", "14784": "丁血虚木横，两胁气撑胀痛，腹中有块，心荡而寒热，病根日久，损及奇经。经云：冲脉为病，逆气里急；任脉为病，男疝女瘕；阳维为病，苦寒热；阴维为病，苦心痛。合而参之，谓非奇经之病乎。调之不易。", "14785": "诒按：古无专属奇经之病，亦无专入奇经之药。考《内经》八脉行度，及前贤议论，均谓十二经气血有余，则溢入奇经。有病者，也必日久病深，由正经而侵入之。然则用药治病，自当仍以正经为主，学者须明此意，勿为近贤议论所蒙也。", "14786": "钱脉微细，阴之象也。少腹有块，上攻及脘，自脘至嗌一条气塞，发作则大痛欲厥，头汗如雨。用方大法，固宜以温通为主矣。惟舌有黄腻浊苔，便泄臭秽，必兼湿热，而块痛得按稍减，中气又虚，方法极难周顾，尚祈斟酌是荷。", "14787": "复诊下焦浊阴之气，上干清阳之位，少腹胸胁有块，攻撑作痛，痛甚发厥。昨用温通，病势稍减，脉仍微细，泄仍臭秽，恶谷厌纳，中气大亏，阴气凝结，当脐硬痛。恐属脏结。攻之不可，补之亦难，诚为棘手。", "14788": "渊按：水寒血气凝聚冲脉之分，果是实证，此方必效。", "14789": "钱少腹有块，痛则经来如注，气升如喘。冲脉久伤，肝木肆横。", "14790": "某肝胃气痛，痛久则气血瘀凝。曾经吐血，是阳明胃络之血，因郁热蒸迫而上也。血止之后，痛势仍作，每发于午后，诊脉小紧数，舌红无苔。乃血去阴伤，而气分之郁热，仍阻于肝胃之络，而不能透达。宜理气疏郁，取辛通而不耗液者为当。", "14791": "再诊胸痹痰饮，脘痛，甚则呕酸，脉细。胃阳不布，先以通阳。", "14792": "复诊脘胁之痛虽除，脾胃之气大惫。面浮足肿，土衰水泛，脉细少神，虑其腹满。急宜温补中阳以消水湿，又当自知节爱为上。", "14793": "某阳维为病，苦寒热；阴维为病，苦心痛。阳维维于阳，阳气弱，则腹痛而便溏；阴维维于阴，营阴虚则心痛而舌红也。脉微形瘦。阴阳并损，损及奇经。当以甘温。", "14794": "再诊但寒不热，便溏脉细，肢体面目俱浮，悉属阳虚见象。惟舌红无苔，此属阴伤之候，但口不干渴，乃君火之色外露。治当引火归元。", "14795": "某自咸丰四年秋季，饱食睡卧起病，今已五载。过投消积破气之药，中气伤戕。脘间窒痛，得食则安，不能嗳气，亦不易转矢气。脉迟弦。肝胃不和，阳虚寒聚于中。拟通阳泄木法。", "14796": "某热走清道为鼻衄，热逼膻中为心痛，脉涩数，小便赤，此血因火逆，火随血结，仿热厥心痛合瘀血心痛例，清之、导之。", "14797": "三诊腹痛，下午则胀，脉沉弦。此属虚寒挟积。前用温下，痛势稍减。今以温中化积。", "14798": "四诊腹痛三年，时作时止，寒在中焦，当与温化无疑。然脉小弦滑，必有宿积。前用温下、温通两法，病虽减而未定。据云每交午月其痛倍甚，则兼湿热，故脉浮小而沉大，按之有力，此为阴中伏阳也。当利少阴之枢，温厥阴之气，运太阴之滞，更参滑以去著法。", "14799": "渊按：既知宿积，何不再进温下？三年之病，谅非久虚。脉浮小沉大，乃积伏下焦。盖痛则气聚于下，故脉见沉大。此论似是而非。", "14800": "五诊腹痛，左脉弦，木克土也。仲景云：腹痛脉弦者，小建中汤主之。若不止者，小柴胡汤。所以疏土中之木也。余前用四逆散，即是此意。然三年腹痛，痛时得食稍安，究属中虚。而漉漉有声，或兼水饮。今拟建中法加椒目，去其水饮，再观动静。", "14801": "六诊用建中法，痛势上攻及胃脘，连于心下，左脉独弦滑，是肝邪乘胃也。姑拟疏肝。", "14802": "复诊用五积合通圣温通散寒，便通而痛未止。脉迟，喜食甜味，痛在当脐，后连及腰，身常懔懔恶寒。此中虚阳弱，寒积内停。拟通阳以破其沉寒，益火以消其阴翳。", "14803": "王脉弦迟，脐以上连胃脘胀痛，此有寒饮。《脉经》云：迟则为寒。仲景云：口不渴而脉双弦者，饮也。", "14804": "复诊当脐腹痛，痛则气塞胸中，嗳气不得语，脉弦大而迟。此胃中阳气不足，而有寒饮也。当以温药通之。", "14805": "范素有肝胃气痛，兼挟寒积。脘腹胀满，痛及于腰，刻不可忍。舌苔白腻，渴不欲饮。大便似利不利。脉沉弦而紧。恐属脏结，颇为险候。非温不能通其阳，非下不能破其结，仿许学士温脾法。", "14806": "三诊两投温下，大便仍然不通。胸腹高突，汤水下咽辄吐，肢渐冷，脉渐细，鼻煽额汗，厥脱可忧。按结胸、脏结之分，在乎有寒热、无寒热为别。下之不通，胀满愈甚乃太阴脾脏受戕，清阳失于转运。崔行功有枳实理中一法，取其转运中阳，通便在是，挽回厥脱亦在是。惟高明裁酌之。", "14807": "丁脉形弦硬，春令见此，是即但弦无胃。纳食哽痛，大便坚燥，已见木火亢逆，胃汁肠液干枯。治之不易。", "14808": "陈据述病由丧子悲伤，气逆发厥而起，今诊左脉沉数不利，是肝之气郁，血少不泽也。右关及寸滑搏，为痰为火，肺胃之气失降，肝木之火上逆，将水谷津液蒸酿为痰，阻塞气道，故咽喉胸膈若有阻碍，纳食有时呕噎也。夫五志过极，多从火化，哭泣无泪，目涩昏花，皆属阳亢而阴不上承之象，目前治法，不外顺气降火，复入清金平木。", "14809": "徐气郁于胸为膈，气滞于腹为臌。饮食不纳，形肉顿瘦。阴气凝聚，阳气汩没。脉细如丝。姑与培土、通阳、化气一法。", "14810": "朱脉滑大，食入哽噎不下，舌腻。此属痰膈。大肠燥火凝结。拟清痰火，佐以宣通。", "14811": "沈食下则饱胀，作酸呕吐，病属反胃。胃脉浮按则紧，沉按则弦。弦者木侮土，紧者寒在中。", "14812": "孔先曾呕血，胃中空虚，寒饮停留，阳气不通，水谷不化，食入呕吐酸水，谷食随之而出。脉细肢寒，阳微已甚。证成翻胃，虑延脾败难治。", "14813": "某胃中素有酒湿，适因斗殴恼怒，引动肝胆之火，与胃中之痰相搏。致心跳少寐，食入则呕，两手脉沉。是气郁也。用温胆加味。", "14814": "再诊《内经》云：「三阳结，为之膈；三阴结，为之水。」此证反胃而兼浮肿，是三阴三阳俱结也。阴阳俱结，治法极难。前方用荜拨牛乳饮，调服沉香、血珀末。拨动其阴阳俱结之气，幸反胃之势已平，是其三阳之结已解。今腹满虽宽，而腿足之肿仍若。是三阴之结，犹未解也。盖太阴无阳明之阳，少阴无太阳之阳，厥阴无少阳之阳，则阴独盛于内，而阳气不通，阴气凝涩，膀胱不化，而水成焉。其脉沉细，盖重阴之象也。凡补脾崇土、温润通阳，如理中、肾气丸之属，固亦合法，然不若周慎斋和中丸之制，为尤妙。以其用干姜，能回阳明之阳于脾。肉桂回太阳之阳于肾。吴萸回少阳之阳于肝。则三阳气胜，而三阴之结解，水自从膀胱出矣。", "14815": "许吐血后呃逆，作止不定，迄今一月。舌白腻。右脉沉滑，左脉细弱。其呃之气自少腹上冲，乃瘀血挟痰浊阻于肺胃之络，而下焦相火随冲脉上逆，鼓动其痰，则呃作矣。病情并见，安可模糊，若捕风捉影，无怪乎其不效也。酌方必有济，幸勿躁急为嘱。", "14816": "查脉沉细数而涩，血虚气郁，经事之不来宜也。夫五志郁极，皆从火化。饥而善食，小溲澄脚如脓，三消之渐，匪伊朝夕。然胸痛吐酸水，肝郁无疑。肝为风脏，郁甚则生虫，从风化也。姑拟一方，平中见奇。", "14817": "复诊服药后，大便之坚难者化溏粪而易出，原得苦泄之功也。然脉仍数涩，究属血虚而有郁热，郁热日盛，脏阴日消。舌红而碎，口渴消饮，所由来也。月事不至，血日干而火日炽。头眩、目花、带下，皆阴虚阳亢之征。补脏阴为治本之缓图，清郁热乃救阴之先著。转辗思维，寓清泄于通补之中。其或有济耶，所虑病根深固，未易奏绩耳。", "14818": "朱脉左寸关搏数，心肝之火极炽。口干，小溲频数而浑浊，此下消证也。久有脚气，湿热蕴于下焦。拟清心肝之火，而化肾与膀胱之湿。", "14819": "潘肛有漏疡，阴津先损于下。兼以嗜酒，湿热又盛于中。继因劳碌感寒，寒入肺经，与胸中素盛之痰湿相合，咳嗽，呕吐清水，而成痰饮为患。仍饮烧酒祛寒，宜其血溢矣。况内热脉数，阴津已亏。欲蠲痰饮，恐温则劫其阴。欲除内热，恐清则加其咳。宜和胃降气。", "14820": "三诊咳呕清水，乃痰饮之病。脉细数，内热，为阴虚之候。治痰饮则宜温，治阴虚则宜滋，药适相背。肝肾为子母之脏，不妨补母以益子。而胃土又为肺金之母，又当和胃以化痰。拟滋燥兼行，仿东垣法而不碍。", "14821": "顾头眩心悸，脉沉弦者，饮也。病发则呕吐酸水，满背气攻作痛，得嗳则痛松，此浊阴之气上攻阳位。当以温药和之。", "14822": "单痰饮久留，咳喘不已。痰多黏腻，脾肾两亏。脾虚则痰不化而食减，肾虚则阳气衰而水泛，以致腹满足肿面浮，病成溢饮。《金匮》云：病溢饮者，当发其汗，小青龙汤主之。然脉细阳衰，便难液涸，肾气久虚，何堪更投发泄耗阴伤阳之剂！拟进附子都气丸，裁去熟地者，以其痰多痞塞也。", "14823": "孙风邪久恋肺中，寒饮停留胃脘。风能化热，咳久伤阴。积饮生痰，胃阳失布。肺之子，肾也；胃之妻，脾也。肺伤肾亦亏，胃虚脾亦弱。脾弱故便泄，肾亏故左尺脉弦而大也。咳将一载，虽曾吐血，而时呕清水，其为寒饮无疑。今从饮门例治。", "14824": "方向有心痛呕吐之病，得食则安，明系中虚而有痰饮伏留于心下也。上年春季，头痛寒热，从此咳嗽喉有痰声。当时设遇明眼，用小青龙发汗散水，表邪与痰饮悉解，何至奄缠不愈耶！迨至酷暑，邪郁化热，咳痰带臭，肺气受伤。交白露节，秋金得令，肺气清肃而后渐愈。至冬，阳气少藏，其咳复作。交春入夏，咳频不已。病延一载有余。诊脉双弦，形肉瘦削，口不干渴，身不发热，头眩心悸。肝肾之阴已虚，脾胃之气亦弱，痰饮恋而未化，自浅及于深矣。昔贤谓外饮治脾肺，内饮治肾。今自外而至于内，从肺脾肾三经立法，前后绾照，以冀各得其所。", "14825": "某咳嗽口不渴，当脐痛，而脉细，头常眩运。此乃手足太阴二经，有寒饮积滞，阻遏清阳之气，不能通达。故一月之中，必发寒热数次，乃郁极则欲达也。病将四月，元气渐虚，寒饮仍恋而不化。先以小青龙汤，蠲除寒饮，宣通阳气。再议。", "14826": "某脉沉取之数，其阴内亏，其热在里。病延日久，劳损之候。证见咳唾白痰，脘腹时痛，痛则气满，得矢气则稍宽，病由肝郁而成。据云：咳已三年，初无身热，是其根又有痰饮也。经训治病必求其根。兹从痰饮气郁例治之。", "14827": "六味地黄丸合生脉散加青铅", "14828": "冯年逾七旬，伏暑挟湿，湿能生热。病起微寒微热，咳嗽痰稠，曾经吐血。今血虽止而咳仍然，脉涩而数，舌苔灰白而渴，乃湿热痰浊恋于肺胃。病将匝月，元气大伤。脾胃不醒，谷食少进。初起大便坚，今则软而带溏矣。病在肺脾胃三经，治在化痰、降气、和中。", "14829": "复诊夫咳嗽痰喘之病，浅则在肺胃，深则属肝肾。凡用方之法，由浅而深。按脉察色，知其虚中挟实，实者痰浊也，故先以化痰、降气、和中为法。两剂，咳嗽稍平，惟气之喘而短者有出多纳少之意，则其本虚矣。左脉细微，肝肾之虚大著。虽舌苔黄浊不化，亦当以摄纳为要。且额上汗冷，胃泛不纳，将有虚脱之虑。", "14830": "另用好肉桂三分，上沉香三分，坎炁二条，三味各研末，和一处，再研细，分作二服。今晚一服，燕窝汤调下。明日再进一服。若得额汗收敛，左脉稍起，犹有生机可理。若不应手，难为力矣。", "14831": "复诊喘哮频发，脉形细数，身常恶寒。下焦阴虚，中焦痰盛，上焦肺弱。肺弱故畏寒，阴虚故脉数，喘之频发，痰之盛也。有所感触，则病发焉。病有三层，治有三法。层层护卫，法法兼到。终年常服，庶几见效，否恐无益也。", "14832": "叶喘之标在肺，喘之本在肾。脉迟者寒也，舌白者痰也。以金水六君煎加味。", "14833": "三诊周身之汗已收，头汗之多未敛。气喘较前觉重，交午愈甚。掌心觉热，脉形细数，饮食减少。阴津大亏，肺气伤戕。兹当炎暑，水衰火旺，金受其灼。咳嗽痰黄，渐延损症。拟清金丽水，冀其应手为妙。", "14834": "强中气不足，湿化为痰，气逆不降，喘息不安，夜重于昼。脉象弦滑，滑主痰饮，痰饮属阴，故病甚于夜也。拟降气化痰，兼扶中气。", "14835": "邵质小肉脆，先天元气本弱，偶因惊恐，遂发寒热，热重寒轻，仍能饮食行坐，医投发散消导，羌防柴葛服之无数，汗总不出，渐见咳嗽口渴，迄今两月余矣。七八日来，骤加喘促，汗出如淋，大便溏泄，溺窍灼痛，小溲频数，夜不能卧，饥不欲食，渴不多饮，舌红燥裂，右脉虚细，左脉促疾，阴气大亏，阳气偏亢，显成劳瘵之形。将何处治！按《内经》论惊则动肝阳，恐则伤肾阴，阴伤阳不藏，水亏木自横，木能克土，而火烁金，此咳嗽喘促汗多者，火入金乡，肺阴消烁于上也。大便溏泄不食者，木乘土位，脾气受困于中也。溺沥窍痛，相火炽于下，舌红燥裂，君火炎于上。处治之法，当泻木火之实，而补金土水之虚，冀其喘定汗收，二便调和再商。", "14836": "原注：此六味汤合生脉散、芍药甘草汤、导赤散，四方并一。用生地补肾阴，茯苓、山药补脾阴，丹皮、泽泻泻相火，去山萸者，嫌其酸温也。麦冬、沙参补肺阴，五味敛汗，芍药、甘草土中泻木，治腹痛便泄，甘草梢泻火缓痛，加通草、竹叶，合入生地，便为导赤散法，治窍痛。凡杂病杂合，当用杂法，而又一丝不乱，头头是道，大非易事。此方服三剂，喘止泻止，溺痛减，进粥三饭碗，接服此方二十帖愈。", "14837": "复诊脉数未退，阴虚未复。咳嗽不止，肺气日虚。夏暑将临，病尚未稳，仍宜小心安养为要。", "14838": "唐七旬有六之年，面色红润，脉形坚搏，外似有余，里实不足。屡患咳嗽，娇脏暗伤。本月初旬微感风温，咳嗽又作。舌苔薄白，底有裂纹。饮食略减。风温久恋，劫胃津，灼肺阴。不可再投辛散，当以甘润生津。", "14839": "李咳嗽喉痒，痰或稀或浓，浓则腥臭。脉象右弦而滑，左弦小数。肝经有郁勃之热，肺家有胶黏之痰。此痰为火郁而臭，并非肺痈可比。当以平肝开郁，参清金化痰。", "14840": "许咳嗽面白为金伤，脉数而洪属虚火，是脉克色而火胜金也。夏至一阴生，正属火令为剥极则复之际。倘若剥而不复，颇有火灼金销之虑。", "14841": "原注：此生脉散合六君子汤加紫菀。夫四君去术加黄耆、山药、陈皮，亦名六君，在《医方集解》中。", "14842": "王暑风从背俞而内薄于肺，湿热从胃脉而上注于肺，外内合邪，其气并于胸中，气不得通，因而上逆，气升作咳。舌苔薄白，口腻不渴，治属饮家。", "14843": "戴五脏皆有咳，总不离乎肺。肺为娇脏，不耐邪侵，感寒则咳，受热则咳，初起微有寒热，必夹表邪。邪恋肺虚，脉形空大。前方降气化痰，保肺涤饮，俱无少效。据云得汗则身体轻快，想由肺气虽虚，留邪未尽。补虚而兼化邪，亦一法也。用钱氏法。", "14844": "沈脉虚软而似数，内伤虚弱奚疑！夫邪之所凑，其气必虚。虚处受邪，其病则实。咳嗽虽由外感，而实则因于气虚。以为风寒固不可，以为虚损亦未必可。玉竹饮子主之。", "14845": "顾嗜酒多湿，湿蕴生痰。体质阴虚，烦劳伤气。去冬咳嗽，须微带血，行动气升，至今不愈。诊脉虚小，恐加喘急。兹以金水六君煎加味。", "14846": "二诊伤风咳嗽，其脉多浮，今反沉紧而涩，是邪伏深固，肺气郁而不达也。左肋一点疼痛不移，防发肺疽。现在声哑，乃竭力正虚，虽为金实不鸣之象，然一夜安眠，晨起则音清，究属烦劳伤气可知。拟芎枳散合泻白法，一面清金，一面挑其深入血分之风。", "14847": "薛左尺极细，寸关微而似数，右三部俱弦滑。下有遗精暗疾，肛门痒而出水。上则头眩耳鸣，舌苔粉白。以脉合症，肾阴下亏，湿热相火下淫上混，清窍为之蒙闭。法当补肾之阴而清相火，清金和胃，分利膀胱以化湿热。", "14848": "须精浊连年不断，兼有血块淋漓。肝肾大虚，八脉无以固摄，湿热混乱不清。舌苔白腻。法当脾肾双补，固摄下焦。", "14849": "渊按：肝肾八脉之虚，由湿浊混淆，精血频下。若不先清湿热以宁相火，徒事补肾固精，所谓不清其源而欲塞其流，能乎否乎？", "14850": "丁水窍精窍，异路同门，二窍不并开。水窍开则湿热常泄，相火常宁，精窍常闭。若水窍为败精瘀浊阻塞不通，则湿热不泄。病已二载，颇服滋补，使湿热败浊漫无出路，致下焦浊气上攻及胃，时时嗳气，腹中不和，二便不爽，失下行为顺之理。诊脉细肢寒，肾阳与胃阳不布。法宜通阳渗湿，益肾化浊。", "14851": "高脉细固属阴虚，若下垂尺泽，是相火下淫，故精血下流，小溲频数，溺窍疼痛，大便干结也。补养肾阴，兼清相火为法。", "14852": "张操觚莲幕，形逸心劳。肾水下亏不能上承于心，心阳内亢而反下趋于肾，即坎离之不交也。不交则诸病生，由是而下为淋浊尿血，宗筋绊痛。上为眩晕咳嗽，心中震跃。诊脉左小右大，内伤虚证何疑！今远道初归，跋涉劳顿，且拟和平补益，庶无畸重畸轻之病。", "14853": "复诊心阴耗损，君不制相，相火妄动，强阳常举，精浊时流，肛门气坠，大便溏薄，心中嘈辣，干嗽无痰。右脉空大，两尺皆虚。法宜补心阴以制相火，益肾气以固元精。", "14854": "某肾虚精关不固，湿热混于坎宫，精从溺后而出，左脉虚细，右脉洪大。阴亏而相火胜也。补肾阴、化湿热，用凉八味法。", "14855": "某先腹痛数日，遂至小便不利，少腹胀满如鼓，今已半月。屡用通利之药，小便虽通不爽，少腹胀满益甚，诊脉弦紧，舌苔白腻，饮食少纳，身无寒热，大便频泄黏腻如痰。此中阳不足，水湿泛溢，膀胱气化无权。法当温土以御水寒，通阳以化湿浊。", "14856": "张寒气客于下焦，瘀凝停于小腹中央，乃膀胱之部也。寒气瘀凝，阻塞胞门，膀胱阳气失化，以致癃闭。产后八日而小溲不通，脉细肢寒，腹中觉冷，恐其气逆上攻发厥。法以温通下焦，化瘀利水。", "14857": "再诊肺为水源，百脉朝宗于肺，犹众水朝宗于海也。肺热叶焦，则津液不能灌输于经脉，而为痿躄。卧床不能行动，形肉消削，咳嗽痰臭，舌红无苔，脉细而数。是皆津液消耗，燥火内灼之象。考经论，治痿独取阳明者，以阳明主润宗筋，胃为气血之源耳。今拟生胃津以供于肺。仿西昌喻氏意。", "14858": "某暑雨潮湿，湿从下受，入于经络。两足腿股酸楚，不能屈伸，起卧转侧，均觉艰难。此属脚气。适值经行之际，少腹窒塞，小便涩痛。湿热自气伤营，故舌苔白而底绛，脉形濡，身微寒热。虑其有气逆冲胸之变。拟东垣防己饮加减。", "14859": "王经后少腹痛连腰股，肛门气坠，大便不通，小便赤涩热痛。拟宣肝经之郁热，通络脉之凝涩。", "14860": "渊按：此经未尽而行房过度所致，乃经血乘虚入络，冲任八脉受伤也。", "14861": "王经来半月不止，有紫血块，少腹疼痛，气坠阴门，诊脉沉涩，下午恶寒。阳陷入阴，营虚失守。法以升阳收摄其阴。", "14862": "陆营分有热，则经至而淋漓。卫分有寒，则脉小而迟缓。脾为营之本，胃为卫之源。经至而舌苔反布，胸无痞闷，是胃阳虚而无气以化浊也。拟醒胃阳以摄脾阴为法。", "14863": "复诊经行过多，血气两衰，肝肾失固，丽翁所论包括尽矣。然治病之道，有相机从事之权。夫舌白多痰，胃有浊也。咽干色红，阴虚而火浮也。脉细迟缓，中气不足也。考古人肾虚有痰浊者，金水六君煎。气虚而上有浮火者，生脉四君子。合而参之，似觉不可擅易，还祈哂政。", "14864": "三诊肝肾与脾胃同治，经漏仍然不止。左脉稍觉有力，原得归、地之功；右脉更觉细微，脾气虚衰不振。许学士谓补肾不若补脾，盖谓脾胃虚者言之。今心跳食少，心脾不足可知。经血如漏厄不息，冲任不得不固。腹中微痛，气虚且滞，不得不补，不得不通。仿黑归脾法。", "14865": "渊按：既云固冲任，而无固冲任之药。仍用归脾，恐漏仍不止。古人治崩漏急证，自有专方，如血余、棕炭、百草霜、倒挂尘等，殊有效验。且脉小迟缓，其漏未必属热，或脾肾阳虚，不能固摄其血，尤非固而兼温不效，未可见血即以为热也。", "14866": "某寒热无序，脉促数，下有淋带，上则心跳，又少腹痛，大便坚，面色痿黄，血瘀之候也。虑延劳损。", "14867": "王向有淋带，月前血崩，崩止淋带不断，少腹板痛，脉象细数，身发寒热。脾胃大虚。此血瘀未尽，复兼肝气夹寒也。法当通补。", "14868": "潘年近六旬，天癸久去而反频来，是谓脱营。脱营者，元气极虚不能固摄，血从外脱也。又名下竭，故腰痛如折。下竭者必上厥，故面赤、火升、发热也。血属阴，阴虚则阳亢，故脉弦硬无情。其脉愈数，其阴愈虚。夏令一交，阳亢无制，恐致水涸龙飞，难为力矣。", "14869": "舒乳房属胃，乳汁血之所化。无孩子而乳房膨胀，亦下乳汁，非血之有余，乃不循其道以下归冲脉而为月水，反随肝气上入乳房，变为乳汁。事出反常，非细故矣。夫血，犹水也；气，犹风也。血随气行，如水为风激而作波澜也。然则顺其气而使之下行，如风回波转可也，何必参堵截之法，涩其源而止其流哉，此可与知者道，难与俗人言也。", "14870": "三诊脉轻按虚微，是为元气之虚；重按细数，是属营阴之损。左尺细弱，肾水亏也。历诊病情，每遇经来，其热辄甚，舌上即布白苔。良以胃中湿浊，因里热熏蒸而上泛也。少腹有块攻痛，聚散无常，是名为瘕。瘕属无形之气，隶乎肝肾为多。揆其致病之由，因目疾过服苦寒，戕伐生生之气。胃受寒，则阳气郁而生湿。肝受寒，则阴气凝而结瘕。阳气郁于胸中，故内热；阴气凝于下焦，故腹痛。经事过则血去而阴虚，故其热甚。甚则蒸湿上泛，故舌苔浊厚也。刻下将交夏令，火旺水衰，火旺则元气耗而不支，水衰则营阴涸而失守，惟恐增剧耳。图治之法，补脾胃以振元气，培肝肾以养营阴，是治其本也。稍佐辛温，宣通下焦阴气，是兼治其瘕痛之标也。", "14871": "某内热日久，经停二月。投养阴调血通经之剂，得热退经行，可谓效矣。然犹未也，脉数不和，舌仍光赤，乃阴津未充，虚阳未敛也。仍宜小心安养为善。", "14872": "再诊脉数已和，舌色光红已退，但有时尚觉微热。仍以前法增损。", "14873": "某忧愁抑郁，耗损心脾之营，而肝木僭逆。胸中气塞，内热夜甚，经事两月不来，脉沉而数，热伏营血之中。拟用柴胡四物汤，和营血以舒木郁。", "14874": "某年近五十，经事频来且多。是冲脉不司收摄故也。防其崩决，补之摄之。", "14875": "某两次血崩之后，赤带连绵不断，迄今半载有余。脉象虚微，气血大亏，是以头眩、心跳、腰酸、足软等证均见也。近日腹痛食减，恐其复致崩决。拟方固摄奇经。", "14876": "阙体弱素亏，频年屡患咳嗽。今春产后悲伤，咳嗽复作，背寒内热，气逆痰多，脉虚数，大便溏。延今百日，病成蓐劳。按产后血舍空虚，八脉之气先伤于下，加以悲哀伤肺，咳嗽剧作，震动冲脉之气上逆。经云：冲脉为病，逆气里急。阳维为病苦寒热。频进疏风清热，脾胃再伤，以致腹痛便溏，食减无味，斯皆见咳治咳之弊。越人谓上损及脾、下损过胃，俱属难治。姑拟通补奇经，镇摄冲脉，复入扶脾理肺。", "14877": "某左脉细数，营阴亏也。右脉细软，脾气虚也。产后不能安息，反加劳碌，气血伤而不复，致身常内热，心荡若嘈。久延虑成劳损。人参养营汤加减。", "14878": "孙前年小产，恶露数日即止，因而腹中作痛结块，心神妄乱，言语如癫。此血风病也。胞络下连血海，上系心胞，血凝动火，火炽生风，故见诸证。诊脉弦搏，肝阳有上亢之象，防加吐血。为治之法，当以化瘀为先，清火化痰为佐。", "14879": "章先痉厥半日而后产，产后厥仍不醒，痉仍不止，恶露稀少，汤水不能纳，纳则仍复吐出，面赤身温，脉洪而荒。肝风炽张，营虚气耗，虚阳外越，冷汗遂出，恐其厥而不返，奈何奈何！姑拟一方，希冀万一。", "14880": "渊按：脉荒者，乱也。究属杜撰。虚风挟痰上逆，化痰降火，冲入童便最妙。", "14881": "复诊前方勉灌三分之一，恶露稍多，面赤稍退，脉大稍软，而厥仍不醒，舌色灰黄，时沃涎沫，两日饮食不进。营虚气滞，胃虚浊泛。必得温通化浊，以冀阳回厥醒为妙。", "14882": "范产未满月操作，猝遇大雨淋身，水寒之气自毛窍而入于骨节，内舍于肾，外达太阳、阳明，是以始病腰疼，继而上攻头痛，遍体机关不利也。脉沉而寒热，寐少而恐惧，纳少而恶心，邪气留连于胃肾。据云头痛甚则汗出，太阳之表虚矣。用许学士法。", "14883": "再诊疟痢三年，脾胃元气大伤。脉数舌红，腹满足肿，小溲短少。前投升阳益胃，热势略减。今拟补益脾阴，兼以化浊。然童稚阴亏，病延日久，夏令防其增剧。", "14884": "诒按：小儿虚证，自以后天脾胃为主。然脉数舌红，阴液亦损，亦当稍参养阴之意。", "14885": "杨悲哀恼怒则伤肝，肝阴伤则虚阳上亢，烁及三阳，从三阳总会之所，而疡生焉。证名脑疽。及今两候有余，脓水见而不多，火势极盛，腐肉未化，坚肿未消。顷诊脉左部弦洪，右部细小。大便艰结，小溲频数。显系气虚下陷之体，肝阳上升之病。夫气虚宜补，肝阳宜镇，镇肝抑火，固外疡所必然，而补托化脓，亦高年所宜讲。所虑者阴分不充，气将日陷，肝阳无制，脓水腐肉，无朝生暮长之功，气血亦无以滋生，势将渐蹈于陷机。拟方呈政。", "14886": "四诊从十味温胆立方，并无胸满闷滞等患，且能安寐两时，受补可知。惟左脉之弦洪不减，酉戌之交，烦躁不安，心火太旺，脓水较多，终未能畅，根盘稍和，究未能化。仍恐火势太甚，乘气虚而内陷。拟清心化热之品，与补托药相辅成功。", "14887": "五诊日中至黄昏，为阳中之阴，此时痛势最甚，必有阴火上乘，邪火因而愈炽。昨用补托，脓水甚多，想正气得扶，毒便外出。今日诊脉左部略平，惟发际之坚肿火色未退，而脾胃仍不思饮食。当从昨方运以调胃之法，参以镇火之品，备正。", "14888": "六诊脓水淋漓，毒能泄也。小溲能畅，火从下降也。所以面赤火升得平，痛势亦减，左脉之洪数亦较平于前日。种种佳兆，皆由升降各职其司，升降之职司，未始非补托之助，气盛则上下咸宜也。然而前日之方，宜增不宜减。", "14889": "八诊补气顾阴为剂，昨日自朝至暮，神气清朗，胃气亦开，脉情亦和，何乐如之。据述丑寅之际，自觉不适，似梦非梦，语言错误。此心营内虚，相火上乘，意者昨晚珍珠停服乎。夫调理高年重虚之体，因事制宜者，尤当因时服药。鄙意欲阳分服补气之方，一交阴分加养阴之品，质之同道先生，以为然否？", "14890": "九诊统观脉证，其发于外者，痛止火退，脓多而腐未脱耳。其在内者，舌苔灰浊，胃气不开。据述昨晚不时烦闷，且云腹痛干呕而呛，自觉有时模糊。种种见证，由脏腑不和，湿热乘虚而入，夫病后宜补，一定之理。而补法亦有因时制宜之道。古人六腑以通为补，亦犹五脏以填为补也。况时令湿热蒸郁，弱体尤易见累。拟暂去参耆，从胃腑立法，俾胃和再商图本。", "14891": "十诊从胃立法，烦闷顿除，自觉脘中空爽，口味大和，药能应手，何其速也。今晨诊脉，左三部较和于昨，右关亦旺。盖久病宜调补脾胃，胃和则卧能安寐，升降自调，转运得所，生长之机自复。惟每日下午精神较怯，睡觉亦见神情恍惚，神气不安。夏至在迩，阴气大剥之候，而体中真阴大伤，未免因时而动，动而太过，则飞扬之虞，不能不虑及之。而目前所宜，仍当从胃立法，而从柔从润，未始不顾及阴分也。用薛氏盐降法加味。", "14892": "十一诊右关一部和缓有神，不特饮食知味，而梦寐亦安，何快如之，至左脉之弦，亦和于昨。此波平浪静之时，正休养生息之候，慎劳动，节饮食，培植脾胃，以扶初生之阴，其在斯时乎。", "14893": "十二诊腐肉能脱，营卫和矣，眠食能安，脏腑和矣，目前之病，谓之已愈，无乎不可。何以昨日未申之交，气之升降失调，脘闷自汗，不能偃卧，脉亦不调，如是数刻。自云素有肝气，逢节则发，将交夏至，似乎复发，而其实非也。夫舌苔浊厚而带灰色，胃中湿浊分明外见，有证可据。以有湿之胃，而当湿令大行之时，高年气弱不能多运食物，午后阳中之阴，气为阳劫，则阴益弱，宜其浊气当权，反劫正气，此即世俗所谓之痧胀也。从此立方，似乎见证治证之道。", "14894": "十三诊用补从湿热一边著手，随补随通，湿去而正自复，此东垣先生所以高于诸名家也。而夏秋为尤宜，昨日立方，从此著想，竟能安适。夫病者自云安适，则真安适矣。今既脉静神怡，阴生之节已在目前，补气调胃，和平其制，此际立方，正无事求其奇也。", "14895": "十五诊脾宜升则健，胃宜降则和。便溏数次，脾气不和也。宜其精神稍倦，左脉带弦，右部略软，腹中隐痛，必冷积留于肠间。幸纳食尚多，胃气尚和。然高年当大病之后，亦不宜多降。拟钱氏参苓白术散加味。", "14896": "十六诊诸气𪱥郁，皆属于肺，诸腹胀满，皆属于脾。《内经》明文也。太太从前𪱥郁之病已安，昨日便溏而腹中胀痛，岂非脾病乎？夫便溏而兼腹痛，虽属脾虚，必有积滞。昨从钱氏法加入温消之品，腹痛已和，便溏亦止，胃气亦调。今晨左脉弦象稍减，右亦有神，目前论治，统诸脏腑而权宜，究须从脾胃著手。以昨钱氏法，去其温消之品可也。", "14897": "太太之体，先天至足之体也。先天者何？天一之水，即命门之火，道家所谓丹田、关元，医家所谓元阳、真火也。此火足则气旺，而后阴生血长，精神福泽，有不能不过人者，所以八旬之年，而智虑常用，然数年中操持耗阴，寒暑耗阴，老年悼子，则更耗阴，于壮岁尚多生长之机，于老年生机渐少，未免不足矣。夫阴以阳为根，阳以阴为宅，既阴不足，则孤阳少所维系，而有失所之虞。睡后自觉奔走无定，以昭其阴火之不敛也。目中每见奇异，以昭其精之不蕴也。夫不足宜补，一定之理。而太太之体，则有不易补阴者。何则？舌苔浊厚，胸脘易痞，居海虞常熟卑湿之地，加以平日茶饮常多，高年气弱，变而成饮，浊腻有质之品，已属难投，而况春夏令行，正湿气当权之日，目前调理之法，惟有补气之中，略加健燥，以拂拭其胃中之浊。待秋分之后，燥令大行，或可渐加阴药，而气分之药，仍不可却。虽然，论时论体，不宜峻补，倘如前神失精离之病日甚，何可不补。转辗思维，惟有珠粉之灵，可以定心安神，獭肝之灵，可以养肝之神，此补阴而不碍于湿者也。抑更进者，此后暑令日加，惟有湿之人，引暑于自然，同气相求之理。喻西昌有言：人不能避身中之湿，何能避天地之暑。而太太胃恒有湿之体，其于暑之一门，不能不加意焉。夫暑之见证多端，大约以口腻、头蒙、胸闷、哕恶，皆其明证。至治暑之方，要不外去其引暑之湿。古人立方，如消暑丸、香茹饮、六和汤、藿香正气等法，无不半杂燥湿祛湿之品，其进而深者，则有十味香茹饮、清暑益气汤、清燥汤、消暑十全散、生脉散等，此则寓扶正于消暑中者。皆可因时采用，不必泥定成方，而心手间须活泼泼地。盖暑必伤气，断无血分一药，则重浊之品，不宜投可知。而老年尤留意者，又在养津。液之所在，即湿之所留，去湿可也，去液不可。去湿不可过燥，故药当适用而不宜漫用。喻嘉言有瘦人以湿为宝之论，语似太过，其于护液之道，一片婆心，殊可取也。故用豆卷而不用茅术，用川贝而不用半夏，用半夏而必须醋炒，前人制法用药，尽情透露，但未明言耳。以上数条，于夏季秋初调理之法，似乎略备。而秋冬不敢悬拟。兹承主人厚意款待，贤昆仲待爱过当，屡以医理下问，夫空言无补，何如实事为得。即太太之病，竭其愚衷，书之以为刍荛之献。惟主翁先生暨贤昆仲先生谅教不逮。", "14898": "顾脑疽几及三候，根盘板滞，脓水清稀，神识时糊，脉虚细数。此正虚不能化毒，毒反陷入于里。姑用扶正托毒，望其转机。", "14899": "刘偏脑疽自右延及于左，三候有余。偏右穿溃脓少，偏左木肿未腐，头顶平塌，根脚散蔓。此气虚不能引血化腐成脓，托毒外出，高年殊虑内陷。至舌苔白腻，大便闭结，在疡科指为火毒内闭，湿热上蕴，而用内疏黄连等法。阅倪先生方案，谓内夹杂气，邪伏膜原，引用达原、三消数剂，异想超出寻常。今大便已通，舌苔稍化，然右脉软弱，胃气残惫，疡不甚肿，色不甚红，深恐阳变为阴。大凡外疡起发脓腐，须赖元气承载。所谓元气者，卫外捍御之气、胃中冲和之气、三焦升降之气也。亏则脓腐不克依期，从此生变。故黄耆为外疡托毒之圣药，即兼别症，再参他方。古法有攻补兼施、补泻同用者。拙见欲托毒，必扶正。", "14900": "王对口疽脓未透澈，用方急于补托，火毒不能外泄，而反弥漫于中，中宫渐增痞闷呕恶。子和云：虚而不补无害，实而补之祸生。盖虚者不补，尚藉谷气滋培，实者补之，反助邪威也。经云：营气不从，逆于肉里，乃生痈肿。又云：膏粱之变，足生大疔。是疡门扼要语。兹疡旬日，仅一更衣，脉滑数，舌白腻。皆湿热壅遏之象。用苦辛宣达，冀其表里宣通，庶免邪陷神昏变端。", "14901": "孙玉枕疽已逾三候，脓泄不畅，腐肉未脱，大便溏薄，脉形迟细。法以补托，冀其脓透腐脱为妙。", "14902": "二诊玉枕疽，及四候，根稍突，脓稍透，脉迟细。元气亏。温补法，理无违。", "14903": "魏先痛而后肿者，自气分伤及营分，咳逆头胀，余邪尚留于隧道，未全入络可知。夫肺主一身之气化，气机利则关节咸利，气机痹则脉络俱痹，斯谓治病之大纲，是宜从事气机矣。", "14904": "二诊肿势愈甚，恶寒已除。脉来弦数右大，舌苔微黄。风温兼夹痰食，已入胃中。防其化燥神昏。", "14905": "三诊病已及候，头面滋水淋漓，而五日不大便，脘痞，苔黄，脉沉按之而实。温邪外郁化火而内结也。当乘势逐之。", "14906": "陶形寒脉迟细，颊车坚肿，牙关紧合不开。此阴亏络空，寒邪袭入，盘踞不出，久则竟难驱化，治当于温通散寒之中，搜其锢结之邪。", "14907": "许肝胆郁火，凝结成痰。腮颊硬肿，牙关不开，此骨槽痰也。脉象郁涩，气失利畅。药力不易见效。宜自怡悦为要。", "14908": "二诊牙龈肿而不坚，腐而不溃，脉形虚数，日晡微热，此属血虚肝郁，木火上升，略兼外感而发。前方解散，表邪已退。今拟养营熄风潜阳为治，仍宜避风为要。", "14909": "胡素禀阴亏火亢，风阳易于上扰，近感时令风温，引动肝胆之阳，挟痰入络，阻袭少阳阳明，牙关坚急不开，左颊结块焮肿，近世谓之托腮牙咬，即古所云时毒是也。现今怀孕八月，乃手阳明经气养胎。诊脉弦数，舌苔白，口中腻，咽喉痛，厥阳、痰浊、风温三者杂合为病。夫风温宜祛之外散，厥阳宜使之内平，痰浊宜化，胎气宜安。盖病邪庞杂，药必兼赅，自当内外施治，非处方之冗杂也。", "14910": "高牙咬痈色白而脉细弦，身微寒热。此寒痰阻于关窍，略感风邪所致。治以辛温解散。", "14911": "胡少阴肾水不足，阳明胃火有余。牙宣出血，晡时微寒壮热，而其脉极细，此素体之阴亏也。当凭此论治，用景岳玉女煎。", "14912": "诒按：此证之脉细，想系素禀如是，若云阴虚，未必脉细也。总之，须见证确可据，乃可舍脉从证，未可冒昧以将事也。", "14913": "唐七窍皆通，此症生于耳中深底，故脓从上腭鼻孔而出。然痛在耳中，仍属耳痈。脉虚，头眩，心嘈，从肝虚风阳上逆治之。", "14914": "贺喉疳腐烂，脉数不扬，眉心不开，肺气内闭，深虑喘厥之变。", "14915": "汪《内经》云：一阴一阳结，谓之喉痹。指少阴君火合少阳相火上逆而为病也。病由内生，非关外感风温，故治之不易速效。养阴降火化痰，每相须为法。惟嫌脉息太细，系素禀六阴，真阳不足。然清药亦宜酌用，恐阴未足而阳先伤耳。慎之。", "14916": "熊痰疬二载，自颈延胁，或已溃，或未溃，或溃而不敛，或他处续生，累累然如贯珠、如叠石。溃后色黑而脓稀，外软而内坚。诊脉不甚虚，饮食尚可。细询病由气郁而起，郁则肝胆三焦之火，循经上走于络，结成痰核，核之小者为疬，大者为痰，收功非易。必放开胸襟，旷观物理乃佳。", "14917": "诒按：此病也与失营证相类，幸脉实能纳，故用药专从痰火著想。", "14918": "诒按：方以六味滋肾、生脉保肺，合柴、芍以清肝，立方周到熨帖。愚意拟去温肝之萸肉，再加清胆之芩、茹。", "14919": "二诊女子以肝为先天，肝血亏则木火易炽，木火炽则津液燥结，阻于经脉，而成瘰疬。瘰者，累累然如贯珠。疬者，历久而不易愈者也。故曰瘰疬。逍遥散加减主之。", "14920": "薛营虚肝郁，颈结痰核，溃者未敛，坚者不消，脉数食少，有时呕恶，此脾胃气虚也。慎勿漫进苦寒消痰之药，当以益气养营为主，冀其呕止热减为妙。欲图速效，断断不能！", "14921": "严冲脉隶于肝肾，女子以肝为先天。及笄之年，癸水未通，颈项虚痰累累，骨蒸晨汗，血枯肝郁现象，劳瘵之根萌也。《局方》逍遥散，为女科圣剂，大意重在肝脾二经，因郁致损。其方下云：养血以润之，指归、芍也。培土以生之，指术、草也。佐柴胡以升春生之气，令木气敷荣，即《内经》木郁达之之义。但久疡速效难期，必得天癸通行，病根斯拔。", "14922": "某两目内眦肉胀，而有红丝，此属水亏火亢。左耳上结核如鸡蛋，色不变而坚硬，脉形小弱带数，症属虚痰。用壮水制阳，兼以咸降。", "14923": "邹按脉空虚，色白不泽，跨凹胸胁之间，素有瘰疬如贯珠，梦遗滑精，已经数载。今腹胀如鼓，上气喘逆，兀坐不能睡卧，此水泛土溃以凌金，下虚上实之候也。惟水愈深者火愈衰，欲利其水，先温其火，欲归其气，必摄其阴，果能吸受之地完固，狂澜滔天之势自止矣。所虑者，病深气竭，窃恐药难奏效，为棘手耳。然极重之候，岂容袖手旁观。", "14924": "某营行脉中，卫行脉外。体肥湿胜之人，卫恒虚冷，营多盛热。故肥人当暑，往往肌肤常冷，而易生外疡也。疡发背脊三候，内脓已结，外腐未透。营中之火极炽，卫弱失于敷布，不能引血化腐，载毒外出，渐显内陷之机，颇为可虑。非温不能助卫阳以鼓舞，非清不能解营热以化毒。经曰：血实宜决之，气虚宜掣引之。此法是矣。", "14925": "穆疡发极大，脓去过多，精神惫败，脉数无神，脾胃困顿，其势甚险。亟宜扶正托毒，犹恐鞭长莫及。", "14926": "秦曲运烦冗，心阳暗亢，气血怫逆，乃生大疽。方书虽有阴阳之别，指人之体质而言，论病不外乎火毒，但有虚实之分耳。经云：诸痛痒疮，皆属心火。今以痒为虚，以痛为实，则又似是而非。夫羌防升散，黄耆固气，适足以增炎而固火，火毒不得外泄，而反陷入于营中，致有烦躁之患，脉来太旺，亦非高年所宜。按背疽条例，最怕三陷变局。此证脓稀根硬，烦渴干哕，虑有火陷之险。徐先生方极是，但甘寒之品，仅泄阳明之火，混处血中之火，犹恐未能遽化。鄙意佐入芳香以宣内窍。未识以为然否？", "14927": "刘肾俞漫肿色白，脉虚微热，此肾俞发也。属三阴亏损，湿热入络，气血凝滞而生。最为奄缠。姑与消散法。", "14928": "金肾俞痰由肝肾精血衰微，络脉空虚而发，是外证中虚损也。溃脓以来，调治三月，颇有向愈之象，最为可喜。无如每交节令，必发寒热，脉弱无神，面色萎黄。即使外证，功尚难恃，而况脓水淋沥，多此空窦，暗损其津耶。拟补益真元，治内即所以治外，如仍罔效，则非所敢任。", "14929": "王湿火入络，手之外腕，及足跗指，皆肿痛而红，两脉洪大转数。拟清络热方法。", "14930": "郑素有肝火，横逆入络，去夏乳房结痰，溃脓收口，今复结核漫肿，阻于缺盆井穴。《内经》所谓：肝有邪，其气流于两胁。证虽外疡，实从内出。脉左弦数，右濡弱，潮热气逆，咳嗽痰多，胸痹纳少，统诸见证，皆肝邪侵胃，更侮肺金。惟热久津伤，柔肝顾阴，尤在所先，不当纯用疡家消肿法也。拟仲景炙甘草汤去阳药。", "14931": "吕营枯无以养络，络脉不和，而成木硬，乳房结核，症名乳癖。更兼遍体肢麻掣痛。非养营无以生血，非泄木无以化结。治病之法虽则如是，然须开怀胸襟于服药之先。", "14932": "李阴血亏，肝气郁，木来乘土，乳房结核，血不荣筋、筋脉拘急，病所由来，匪伊朝夕，症虽外疡，实从内生。法当养血荣筋，漫用攻消无益。", "14933": "某咳嗽月余，痰腥带血，气升呛逆，脉弦滑数。风温久恋，化火蒸痰，灼金耗液。证属肺痈，非轻候也。", "14934": "二诊咳逆痰腥带血，脉形弦硬，面色暗晦。肺气失降，木火上逆，防加喘急。", "14935": "某咳唾臭脓，脉数，而不欲食，时寒时热，肺痈已见脓后，热不退者，虚也。火克金而土虚不能生金，是谓重虚，恐难治。", "14936": "周咳吐臭痰，已延三月。脉数而虚，其阴已伤。面白无华，饮食渐减，肺失所恃，防成肺痿。", "14937": "二诊咳痰腥臭，面色青晦，脉数而虚，纳谷大减。此木火乘金，金伤及土，脏气克贼，恐延不治。", "14938": "吴咳逆舌绛，脉见洪数无神，肺阴大伤。咳痰秽浊腥臭，不独肺痈重候也。仲景不云乎，脉数大而虚为肺痿。痈犹可也，痿则难治。", "14939": "陈虚体著邪，留恋不化，肺气失清肃之令，胃津乏游溢之权，咳逆痰黏纳少，季胁肿痛，邪热逗留入络矣。脉来弱而数，弱为阴不足，数为阳有余，瘦人最有液涸之虑。戚先生同议益气生津，气壮则邪自却，津充则热自除，惟日暮寒热，痛势加剧，乃成脓之象，旦晚未易奏功。", "14940": "张怒则肝气逆而血菀于上，章门结块硬痛，寒热脉数，小便短少。症属肝痈，防其内溃咳吐脓血而剧。", "14941": "缪病起微寒微热，右肋章门穴酸疼。延今两月，痛处略肿，食少便溏，面浮足肿，腰脊酸痛。脉附骨极细而锐。此脾家有湿热瘀伤，症属脾痈。日久正虚胃弱，恐其不克支持。", "14942": "胡胃脘生痈，脉虚形瘦。初起寒热，延今四十余日，晨必泄泻无度。是中气大虚，不胜攻消之任也。今与内托法。倘仍作泻，则难矣。", "14943": "徐脉来左虚弱，右弦数，湿热壅滞，踞于胃脘之络，胸高坚突不移，此肚角痈也。病后气虚不复，厌谷纳少，且用扶土和中，亦扶正却邪之治。", "14944": "查脘下结肿，按之痛不可仰，是痰气交凝，阻塞脉络所致。有痈脓之虑。拟和中化痰，攻逐络中之瘀。", "14945": "郭伏暑之邪，兼挟肝郁，气痹血阻，脘左板痛，脉形郁数，寒热不时，势有肚角痈之虑。拟和解宣络。", "14946": "周当脐肿硬，名曰脐痈。脉数身热，内痈已成，若不从脐中而出，恐其内走大肠，而变为盘肠，芽孩犯此非轻。", "14947": "三诊肠内痈脓将足，脉细食少。治以托里，冀其外溃为妙。", "14948": "王湿热阻于肝络，右少腹高突成痈，绵延匝月，脓脚已成，脉数寒热，舌苔灰腻。法当攻营逐络，兼以和解。", "14949": "三诊饮食不节，寒热复作，疡脓不尽，弦数之脉，灰腻之苔，减而复来。仍以和解中宫，冀其热退谷增为妥。", "14950": "萧腿之里股及胯，皆三阴经循行之地。此处疼痛而略肿，足屈不能伸，先有寒热，是阳邪入于阴经，而欲结外疡也。舌苔干掯，小便赤痛，大便溏泄。但脉细汗多，精神疲惫，年逾六旬，恐其不克支持，而生晕厥，症势险重，备商。", "14951": "三诊胯凹痛而略肿不高，又无红色，而痛著于骨，如针刺之状，此横痃疽也。疽属阴，由五脏而生，故脉细而便泄，皆为阴象。惟是舌色焦红干涸，小溲赤痛，是属津亏火亢，此阴中夹阳，寒热两歧，高年犯此，颇属棘手。", "14952": "五诊胯凹痛而无形，已及四十余日，脉细、便溏、多汗，皆属虚寒之象。舌干苔掯，阴津大亏，饮食少纳，脾胃极弱。惟小溲茎中作痛，尿色浑浊，似有湿热内瘀。高年犯此，颇虑奄延败坏，法以温补为主，佐以分清化湿，备商。", "14953": "某多年湿毒，左足前臁腐烂。今则膝骨、臀股，上及缺盆而木肿，此湿得热而蔓延，循经窜络，病在阳明，名湿毒流注。口苦带腻，脉缓而小。湿胜于热，热伏湿中。仿防己饮法。", "14954": "于寒邪入络，腿股酸痛漫肿，色白脉细，口不渴，当温散之，拟阳和汤法。", "14955": "毛右膝肿大，皮色不红，骨中如火灼之痛，脉洪，口腻，身热。此湿热相火乘虚注于溪谷，症属鹤膝风痹，殊非小疾，极难速效。", "14956": "袁疡脓之后，气血必虚。奔走烈日之中，汗出招风，风与热毒舍于皮肤脉络之间。至秋凉气外束，热郁于皮中，遂觉遍体搔痒，几及两月。近来面色带黑而浮，少腹略满。据云奇痒之时，唇舌俱麻，是外风引动内风也。经云：面肿曰风。夫风行必燥，木胜克土，此证现为风癞，久防腹满，理势所必然也。", "14957": "（案11）严，左。对口发于督脉，顶虽未起而根脚不散，乃半阴半阳之症。所虑年高气血已枯，不可不兼护托。", "14958": "（案4）某，右。痈生于耳，流脓多而气血伤。脉数，牙关不开，柴胡四物加减。", "14959": "（案6）王，右。耳窍流脓由来数月，痛不减而脉至细数无力。用拟归芍六味加减以滋肝肾之阴，兼少阳之火。", "14960": "（案1）周，童。不肿不痛，非外风也。无翳，无肿，无胬肉，无红筋，并非火也。其视不明，至夜尤甚，乃肾水有亏，肝血不足。至于眼包宽纵者，关乎脾气不运、络脉有亏。寒凉发散决无此理。培补脾肾兼以养血一定方法，但培原固本之久，自然见功。欲求速，势所不能。", "14961": "（案3）郭，右。两目失明，右目风轮翳起，左目内障瞳神，脉见弦数，肝阴亏而阳亢。", "14962": "（案4）刘，右。风轮起翳，气轮赤脉贯睛，脉数，泪多，虽因风热闭结，恐损及瞳神，则调治不易。", "14963": "（案6）陈，右。黄膜上冲，热逼膏伤，视物不见，脉至右关沉有力，春间曾患乳痈，此系阳明余火不清，火性上升害及于目。阳明为多气多血之腑，宜于清降。十日内能见日光，方可调理。", "14964": "（案7）王，右。右目向已失明，肝血之亏不待言矣。今左眼骤加肿痛，黑珠浑浊，视物不见，泪出如糊，左脉全无，内外两症俱有，虚体实邪之恙。眼科一门亦有虚体实邪之证。此其是乎宜养血之中加以辛温疏散之品。", "14965": "（案9）秦，左。气轮赤而风轮起翳，此肝肺两经之邪。脉至右寸关较大，可清可散。", "14966": "（案1）周，左。口舌糜烂，门齿下根为甚，脉至左关尺较数，法宜清肝火、养肾阴，兼以凉解。", "14967": "复诊口疳患处虽未增重亦未减轻，今左脉数而有力，更益头痛，又受风热之故也。", "14968": "（案3）诸，左。牙疳碎烂，色紫暗无神，舌滑带黑，六脉软弱，下门齿脱落，此系肾经下疳，虚症之极重险者，论脉论症理宜桂附导火归原，但远途而来不无外感，况时令又在风阳甚时，难以擅投，勉商六味以壮水制阳，佐以去骨中之湿毒。", "14969": "复诊昨投壮水制阳，兼却骨中湿毒。而烂处色紫，泽稍为明润，脉亦稍为有神。", "14970": "（案4）陈，左。风火上炽，牙龈碎烂，脉至得数，拟与清疏。", "14971": "（案5）吴，右。上下门牙龈脚碎烂，色带紫暗，脉至右大于左，此肝肾之阴不足，阳明湿化为火。", "14972": "（案10）孙，左。近喉左半牙龈腐烂，形似翻花，左胁肋胀痛，脉至沉弦。沉为气滞，弦为肝脉，此症起于抑郁而成，并非时邪客感可比。再虑缠绵，药不易效，须得怡情悦性、耐心静养，一切淡泊，或可有望不致加重。药饵总宜不伤气血，切忌攻伐苦寒有碍生生之气。", "14973": "（案13）龚，右。牙痈有脓，余肿不消，六脉细弱。以扶正为主，稍益清解。", "14974": "木舌，肿连咽喉，脉至滑数，左三部更甚，火炽甚矣。用栀子金银花汤，急宜清三焦之火。明晨轻减，方可得生，否则难治。", "14975": "（案2）尤，左。偏查舌连及左半咽喉肿痛，脉虽细弱无力，此属上焦风热挟痰。宜与清疏，当从症不从脉，然宜轻用，重则犯及中下二焦。初学者此等处留心为嘱。", "14976": "（案4）张，余。舌痈，脉至弦数，内脓已成，目下数日势属危险，急急清解。", "14977": "（案1）窦，左。咽痛连及牙龈，脉至左寸关浮数，大便不解，此宜清降兼疏。岂可辛温施于燥火者？之在上亦忌升提。", "14978": "（案2）徐，右。咽喉溃烂，脉至细弱无神，宜活血养血为主，勿用寒凉致伤生生之气。", "14979": "（案4）高，右。风热在上，咽痛头疼，脉带浮数，宜与清散。", "14980": "（案6）祝，右。咽喉碎烂，色脉合参并无火象，清滋苦寒之药决不可投。", "14981": "（案7）庄，右。咽喉上腭溃烂，脉至弱而细，宜调养气血兼以甘凉解毒，勿服苦寒。", "14982": "（案8）潘，右。色脉和参，并非重恙，只因勤于女红，肺气窒塞为此，咽如茅刺。一切偏寒偏热勿投为嘱。", "14983": "（案9）陈，右。为素有肝气，治痛治呕之药毕竟温燥者多，肺液被劫，以致咽如炙脔，脉右寸关带数。清金保肺缓缓图治之，自效，但苦寒之品亦不相宜。", "14984": "（案10）许，右。咽喉左半腐烂，脉至浮数有力。风热有余，可清可散。", "14985": "（案12）朱，右。外无六淫见症，脉至似有若无，惟左关隐隐带弦带数。今见咽喉右半络脉红紫，每食物下咽，右半咽喉微微硬痛，此肝郁气滞，厥阳亢。络为之瘀，气为之滞，脉不流利，咽喉作此，所谓一阴一阳结为喉痹也。", "14986": "（案13）赵，左。咽喉碎烂，甚于右半，即有实邪，为日已久。只用疏解，施于近感风火之症则可，此症色、脉已亏，必兼清补。", "14987": "（案14）唐，左。咽痛，色如秋海棠叶背红丝绊满，肩背怯寒，脉至浮弦带滑。平素体质阴亏，多半因房欲后受邪所致，宜清上实下。", "14988": "（案17）宗，右。咽痛而甚于左半，脉至带数，此心阳肝火上亢。", "14989": "（案20）诸，左。凡咽喉之症，风火居其八九。去冬曾患喉痈，得脓后迄今咽喉肿痛不除。近因感冒呛咳见红，脉至浮大。先为清散，续商调理，此三月内饮食寒暖须小心，否则非喉痈，即喉风。不可不虑！", "14990": "（案21）陈，右。咽喉漫肿无形，痛甚于左，脉浮而不甚流利，风寒束缚，热郁于里不得透达，则成喉风也。拟散之中兼清药。", "14991": "（案23）王，左。咽喉碎烂而甚于右，脉至右寸浮数，究属风热上感。先为清散。", "14992": "（案5）崔，左。脉至浮迟，牙关紧急，腮颐作胀，此风寒袭于少阳、阳明。宜与清，切忌寒遏。", "14993": "脉至右关较数，面颊浮肿，少阳阳明风热之邪有旺。清之散之。", "14994": "（案8）汪，左。颧疽色紫木硬无情，得脓不化，脉至左弦带滑，此肝郁气滞、积久痰凝所致。急切不易见效，须怡悦情怀，缓缓图治。药忌苦寒，症非实火，恐伤胃也。", "14995": "（案10）余，右。面无华色，脉来少神，气血亏矣。颐颔结核，牙龈碎烂。不可作寻常外症同例，而肆用寒凉攻伐，以伤生生之气。", "14996": "左。脉至右脉洪滑而大，此为痰火有余。鼻衄之类，颈侧之疬皆由此也。", "14997": "（案2）季，右。脉滑数而有力，甚于右关，颏下疬生累累，痰火有余之象。", "14998": "（案4）许，右。痰有虚实，热有内因外因，治各不同。此症之发热不已，颈侧左半之痰俱从产后而起，今面色萎黄，热甚于夜，脉至左三部浮弦带数，显系肝肾之阴有亏。其颈之痰亦属肝血有亏，肝阳上亢，痰随火升，凝炼而成。因虚而致，非比实症之热可以清散、实症之痰可以攻消，法当育阴制阳，兼以咸能软坚。耐心守服，药力到时，方能应效。如求速愈则难矣。", "14999": "（案5）华，右。木郁不舒，颈左结核，按之棉软，脉来艰涩，此气滞痰凝。宗木喜条达法。"});